from typing import List
def number_of_ways(data: str) -> int:
    memo: List[int or None] = [None] * (len(data) + 1)
    def helper(k: int) -> int:
        if k == 0:
            return 1
        i = len(data) - k
        if data[i] == '0':
            return 0
        if memo[k]:
            return memo[k]
        result = helper(k - 1)
        if k >= 2 and data[i:i + 2] <= '26':
            result += helper(k - 2)
        memo[k] = result
        return result
    return helper(len(data))
if __name__ == '__main__':
