import json
import torch
import torch.nn as nn
import numpy as np
from torch import Tensor
from torchtyping import TensorType
import transformer.Constants as Constants
from dataset import PreProcessConfig
from .Layers import ConformerBlock
from text import symbols, accent_symbols
from typing import Optional, List, TypedDict, Tuple
def get_sinusoid_encoding_table(n_position: int, d_hid: int, padding_idx: Optional[int] = None) -> torch.FloatTensor:
    """ Sinusoid position encoding table """
    def cal_angle(position: int, hid_idx: int) -> np.generic:
        return position / np.power(10000, 2 * (hid_idx // 2) / d_hid)
    def get_posi_angle_vec(position: int) -> List[np.generic]:
        return [cal_angle(position, hid_j) for hid_j in range(d_hid)]
    sinusoid_table = np.array(
        [get_posi_angle_vec(pos_i) for pos_i in range(n_position)]
    )
    sinusoid_table[:, 0::2] = np.sin(sinusoid_table[:, 0::2])  # dim 2i
    sinusoid_table[:, 1::2] = np.cos(sinusoid_table[:, 1::2])  # dim 2i+1
    if padding_idx is not None:
        # zero vector for padding dimension
        sinusoid_table[padding_idx] = 0.0
    return torch.FloatTensor(sinusoid_table)
class ModelConfigConformer(TypedDict):
    encoder_layer: int
    encoder_hidden: int
    decoder_layer: int
    decoder_hidden: int
    encoder_dropout: float
    decoder_dropout: float
class ModelConfigVariancePredictor(TypedDict):
    filter_size: int
    kernel_size: int
    dropout: float
class ModelConfigVarianceEmbedding(TypedDict):
    pitch_quantization: str
    energy_quantization: str
    n_bins: int
class ModelConfigVocoder(TypedDict):
    model: str
    speaker: str
class ModelConfig(TypedDict):
    conformer: ModelConfigConformer
    variance_predictor: ModelConfigVariancePredictor
    variance_embedding: ModelConfigVarianceEmbedding
    multi_speaker: bool
    max_seq_len: int
    vocoder: ModelConfigVocoder
class Encoder(nn.Module):
    """ Encoder """
    def __init__(self, preprocess_config: PreProcessConfig, model_config: ModelConfig):
        super(Encoder, self).__init__()
        n_position = model_config["max_seq_len"] + 1
        n_src_vocab = len(symbols) + 1
        n_accent_vocab = len(accent_symbols) + 1
        d_word_vec = model_config["conformer"]["encoder_hidden"]
        n_layers = model_config["conformer"]["encoder_layer"]
        dim = model_config["conformer"]["encoder_hidden"]
        dropout = model_config["conformer"]["encoder_dropout"]
        self.max_seq_len = model_config["max_seq_len"]
        self.d_model = dim
        self.src_word_emb = nn.Embedding(
            n_src_vocab, d_word_vec, padding_idx=Constants.PAD
        )
        self.src_accent_emb = nn.Embedding(
            n_accent_vocab, d_word_vec, padding_idx=Constants.PAD
        )
        self.position_enc = nn.Parameter(
            get_sinusoid_encoding_table(n_position, d_word_vec).unsqueeze(0),
            requires_grad=False,
        )
        self.layer_stack = nn.ModuleList(
            [
                ConformerBlock(
                    dim=dim, ff_dropout=dropout, conv_dropout=dropout,
                )
                for _ in range(n_layers)
            ]
        )
        self.speaker_emb = None
        if model_config["multi_speaker"]:
            with open(
                os.path.join(
                    preprocess_config["path"]["preprocessed_path"], "speakers.json"
                ),
                "r",
            ) as f:
                n_speaker = len(json.load(f))
            self.speaker_emb = nn.Embedding(
                n_speaker,
                model_config["conformer"]["encoder_hidden"],
            )
    def forward(self, src_seq: Tensor, mask: Tensor, accents: Tensor, speakers: Tensor) -> Tensor:
        batch_size: int = src_seq.shape[0]
        max_len: int = src_seq.shape[1]
        # -- Forward
        if not self.training and src_seq.shape[1] > self.max_seq_len:
            enc_output = self.src_word_emb(src_seq) + self.src_accent_emb(accents) + get_sinusoid_encoding_table(
                src_seq.shape[1], self.d_model
            )[: src_seq.shape[1], :].unsqueeze(0).expand(batch_size, -1, -1).to(
                src_seq.device
            )
        else:
            enc_output = self.src_word_emb(src_seq) + self.src_accent_emb(accents) + self.position_enc[
                :, :max_len, :
            ].expand(batch_size, -1, -1)
        for enc_layer in self.layer_stack:
            enc_output = enc_layer(
                enc_output, mask=mask
            )
        if self.speaker_emb is not None:
            enc_output = enc_output + self.speaker_emb(speakers).unsqueeze(1).expand(
                -1, mask.shape[1], -1  # -1, max_src_len, -1
            )
        return enc_output
class Decoder(nn.Module):
    """ Decoder """
    def __init__(self, config: ModelConfig):
        super(Decoder, self).__init__()
        n_position = config["max_seq_len"] + 1
        n_src_vocab = len(symbols) + 1
        d_word_vec = config["conformer"]["decoder_hidden"]
        n_layers = config["conformer"]["decoder_layer"]
        dim = config["conformer"]["decoder_hidden"]
        dropout = config["conformer"]["decoder_dropout"]
        self.max_seq_len = config["max_seq_len"]
        self.d_model = dim
        self.src_word_emb = nn.Embedding(
            n_src_vocab, d_word_vec, padding_idx=Constants.PAD
        )
        self.position_enc = nn.Parameter(
            get_sinusoid_encoding_table(n_position, d_word_vec).unsqueeze(0),
            requires_grad=False,
        )
        self.layer_stack = nn.ModuleList(
            [
                ConformerBlock(
                    dim=dim, ff_dropout=dropout, conv_dropout=dropout,
                )
                for _ in range(n_layers)
            ]
        )
    def forward(self, enc_seq: Tensor, mask: TensorType[bool]) -> Tuple[Tensor, TensorType[bool]]:
        batch_size: int = enc_seq.shape[0]
        max_len: int = enc_seq.shape[1]
        # -- Forward
        if not self.training and enc_seq.shape[1] > self.max_seq_len:
            dec_output = enc_seq + get_sinusoid_encoding_table(
                enc_seq.shape[1], self.d_model
            )[: enc_seq.shape[1], :].unsqueeze(0).expand(batch_size, -1, -1).to(
                enc_seq.device
            )
        else:
            max_len = min(max_len, self.max_seq_len)
            dec_output = enc_seq[:, :max_len, :] + self.position_enc[
                :, :max_len, :
            ].expand(batch_size, -1, -1)
            mask = mask[:, :max_len]
        for dec_layer in self.layer_stack:
            dec_output = dec_layer(
                dec_output, mask=mask
            )
        return dec_output, mask

class RequirementInfo:
    """
    Class to wrap pkg_resources.Requirement and represent package requirement information.
    https://setuptools.pypa.io/en/latest/pkg_resources.html#requirement-objects
    """
    ANY_VERSION = 'Any'
    _requirement = None
    def __init__(self, requirement: Optional = None):
        self._requirement = requirement
    @property
    def specifier(self) -> str:
        """Return required package version"""
        return str(self._requirement.specifier) if self._requirement.specifier else self.ANY_VERSION
    def __eq__(self, other: 'RequirementInfo') -> bool:
        """Compare two RequirementInfo objects"""
        return self._requirement == other._requirement

