        else:
            dy = np.sqrt(k * m) / np.sqrt((1 - gamma)) - y
            dx = np.sqrt(k * (1 - gamma)) / np.sqrt(m) - x
            if dx <= 1e-12:
                return None, None
        token = 1 if dy > 0 else 0
        tokens_in = dy if dy > 0 else dx
        tokens_in = tokens_in / (1 - gamma)
        return token, tokens_in

