def validate_markdown(target_path: Path) -> bool:
    with open(target_path) as markdown_file:
        for line in markdown_file:
            if '### File Under' in line:
                return True
    return False
def validate_path(target_path: Path) -> Path:
    if target_path.is_file():
        return target_path
    return Path('')
