def get_database(database_path: str) -> sqlite3.Connection:
    try:
        db = sqlite3.connect(database_path)
        _LOGGER.info(f'DB Connection Made: {sqlite3.version}')
        return db
    except Error as e:
        _LOGGER.info(f'Database connection failed. Error: {e}')
        return None
def create_table(db: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, headers: list):
    header_string = ', '.join(headers)
    _LOGGER.info(f'CreatingTable [{table_name}]: {header_string}')
    execute_db_command(db, cursor, f"""CREATE TABLE IF NOT EXISTS {table_name} ({header_string})""")
def remove_table(db: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str):
    execute_db_command(db, cursor, f"""DROP TABLE {table_name}""")
def create_table_entry(db: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, values: list):
    values_string = ', '.join(values)
    execute_db_command(db, cursor, f"""INSERT INTO {table_name} VALUES ({values_string})""")
def remove_table_entry(db: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, row_id: int):
    execute_db_command(db, cursor, f"""DELETE from {table_name} where id = {row_id}""")
def execute_db_command(db: sqlite3.Connection, cursor: sqlite3.Cursor, command: str):
    _LOGGER.info(f'Executing: {command}')
    cursor.execute(command)
    db.commit()
def get_table_values(cursor: sqlite3.Cursor, table: str) -> dict:
    table_dict = {}
    cursor.execute(f"""SELECT * from {table}""")
    values = cursor.fetchall()
    for value in values:
        table_dict[value[0]] = value[1]
    return table_dict
def get_database_values(cursor: sqlite3.Cursor, tables: list) -> dict:
    database_values = {}
    for table in tables:
        cursor.execute(f"""SELECT * from {table}""")
        table_values = cursor.fetchall()
        database_values[table] = table_values
    return database_values

from typing import Any, List, Tuple
from aocpy import BaseChallenge
class DeterministicDie:
    num_rolls: int
    def __init__(self, sides: int = 100):
        self._sides = sides
        self._n = 0
        self.num_rolls = 0
    def next_number(self) -> int:
        self.num_rolls += 1
        self._n += 1
        if self._n > self._sides:
            self._n = 1
        return self._n
    def next_n_numbers(self, n: int) -> List[int]:
        o = []
        for _ in range(n):
            o.append(self.next_number())
        return o
Player = List[int]  # position, score
Players = Tuple[Player, Player]
def parse(instr: str) -> Players:
    o = []
    for line in instr.strip().splitlines():
        start_pos = int(line.split(": ")[-1])
        o.append([start_pos, 0])
    return tuple(o)
def get_next_position(current_position: int, steps: int) -> int:
    n = current_position + (steps % 10)
    return n if n <= 10 else n - 10
def move_player_forwards_by(p: Player, steps: int):
    p[0] = get_next_position(p[0], steps)
    p[1] = p[1] + p[0]
def get_player_score(p: Player) -> int:
    return p[1]
class Challenge(BaseChallenge):
    @staticmethod
    def one(instr: str) -> Any:
        players = parse(instr)
        die = DeterministicDie()
        while True:
            game_finished = False
            for player in players:
                forward_steps = sum(die.next_n_numbers(3))
                move_player_forwards_by(player, forward_steps)
                if get_player_score(player) >= 1000:
                    game_finished = True
                    break
            if game_finished:
                break
        scores = list(sorted([get_player_score(p) for p in players]))
        return scores[0] * die.num_rolls
    @staticmethod
    def two(instr: str) -> int:
        return NotImplementedError

import torch
class MinimizeFlag:
    @property
    def minimize(self):
        if hasattr(self, '_minimize'):
            return self._minimize
        return True
class BaseLoss:
    def __init__(self, to_weight: bool):
        self.to_weight = to_weight
    def _calculate_loss(self, returns_tensor: torch.Tensor, masks: torch.Tensor,
                        sdf: torch.Tensor, moments: Optional[torch.Tensor] = None, *args, **kwargs):
        weights = self.get_weights_from_mask(masks)
        if len(returns_tensor.shape) > 3:
            returns_tensor = torch.squeeze(returns_tensor, 0)
        multiplied_tensor = (torch.squeeze(returns_tensor * masks, -1) * sdf)
        if moments is not None:
            if len(moments.shape) > 3:
                moments = torch.squeeze(moments, 0)
            multiplied_tensor = moments * multiplied_tensor
        else:
            multiplied_tensor = torch.unsqueeze(multiplied_tensor, 0)
        empirical_mean = torch.div(torch.sum(multiplied_tensor, dim=1), weights)
        return self.mean_square(empirical_mean, weights if self.to_weight else None)
    @staticmethod
    def get_weights_from_mask(masks: torch.Tensor) -> torch.Tensor:
        weights = torch.sum(masks, dim=0)
        weights = torch.squeeze(weights, -1)
        return weights
    @staticmethod
    def mean_square(output_tensor: torch.Tensor, weights: torch.Tensor = None, normalize_by_max: bool = True):
        squared_output = torch.square(output_tensor)
        if weights is not None:
            denominator = torch.max(weights) if normalize_by_max else torch.sum(weights)
            weights = weights / denominator
            squared_output *= weights
            return torch.mean(squared_output) if normalize_by_max else torch.sum(squared_output)
        return torch.mean(squared_output)
class UnconditionalLoss(BaseLoss):
    def __call__(self, returns_tensor: torch.Tensor, masks: torch.Tensor,
                 sdf: torch.Tensor, *args, **kwargs):
        return self._calculate_loss(returns_tensor, masks, sdf)
class ConditionalLoss(BaseLoss):
    def __call__(self, returns_tensor: torch.Tensor, masks: torch.Tensor,
                 sdf: torch.Tensor, moments: torch.Tensor, *args, **kwargs):
        return self._calculate_loss(returns_tensor, masks, sdf, moments)
class WeightedLSLoss(BaseLoss, MinimizeFlag):
    def __call__(self, returns_tensor: torch.Tensor, masks: torch.Tensor, *args, **kwargs):
        weights = self.get_weights_from_mask(masks)
        return self.mean_square(returns_tensor, weights if self.to_weight else None, normalize_by_max=False)
class ResidualLoss:
    def __call__(self, returns_tensor: torch.Tensor, masks: torch.Tensor, sdf_weights: torch.Tensor, *args, **kwargs):
        num_val_per_time = torch.sum(torch.squeeze(masks, -1), dim=1)
        returns_masked = torch.masked_select(returns_tensor, masks).reshape(
            (torch.sum(masks), returns_tensor.shape[-1]))
        sdf_weights = torch.squeeze(sdf_weights, 0)
        returns_split = torch.split(returns_masked, num_val_per_time.tolist())
        sdf_weights_split = torch.split(sdf_weights, num_val_per_time.tolist())
        residual_square_list = list()
        r_square_list = list()
        for r_t, w_t in zip(returns_split, sdf_weights_split):
            r_t_hat = torch.sum(r_t * w_t) / torch.sum(w_t * w_t) * w_t
            residual_square_list.append(torch.mean(torch.square(r_t - r_t_hat)))
            r_square_list.append(torch.mean(torch.square(r_t)))
        return torch.mean(torch.tensor(residual_square_list)) / torch.mean(torch.tensor(r_square_list))
class LossCompose(MinimizeFlag):
    def __init__(self, minimize: bool, to_weight: bool, main_loss_conditional: bool,
                 residual_loss_factor: float = 0.):
        self.residual_loss_factor = residual_loss_factor
        if main_loss_conditional:
            self.main_loss = ConditionalLoss(to_weight=to_weight)
        else:
            self.main_loss = UnconditionalLoss(to_weight=to_weight)
        self.residual_loss = ResidualLoss()
        self._minimize = minimize
        if not self.minimize and self.residual_loss_factor:
            raise NotImplementedError('Can not maximize with residual loss')
    def __call__(self, returns_tensor: torch.Tensor, masks: torch.Tensor, sdf: torch.Tensor,
                 sdf_weights: torch.Tensor = None, moments: Optional[torch.Tensor] = None, *args, **kwargs):
        main_loss_factor = 1 if self.minimize else -1
        loss = main_loss_factor * self.main_loss(
            returns_tensor=returns_tensor,
            masks=masks,
            sdf=sdf,
            moments=moments)
        if self.residual_loss_factor:
            loss += self.residual_loss(returns_tensor, masks, sdf_weights) * self.residual_loss_factor
        return loss

import re
from bs4 import BeautifulSoup
from scraper.utils import get_page, make_soup
class Song:
    def __init__(self, song_url: str) -> None:
        self.url = song_url
        self.scrape(get_page(song_url))

    def __str__(self) -> str:
        return f'{self.artist} - {self.title}: {" ".join(self.chords)}'

    @staticmethod
    def scrape_chords(soup: BeautifulSoup) -> List[str]:
        """Scrapes and returns chords from the given HTML code."""

        chords = []
        for code_tag in soup.find_all('code'):
            chord = f'{code_tag["data-chord"]}{code_tag["data-suffix"]}'
            if code_tag['data-chord'] and chord not in chords:
                chords.append(chord)
        return chords

    @staticmethod
    def scrape_title(soup: BeautifulSoup) -> str:
        """Scrapes and returns song's title."""
        return soup.select_one('h1 strong').text

    @staticmethod
    def scrape_artist(soup: BeautifulSoup) -> str:
        """Scrapes and returns song's artist/author."""
        tag = soup.select_one('h1')
        tag.find('strong').extract()
        # remove stuff in parentheses
        return re.sub(r'\(.*\)', '', tag.text).strip()

    def scrape(self, html: str) -> None:
        soup = make_soup(html)
        self.chords = self.scrape_chords(soup)
        self.title = self.scrape_title(soup)
        self.artist = self.scrape_artist(soup)

from dataclasses import dataclass
from typing import Any, Optional
from .schema import Schema, SchemaError
from .type_schema import InvalidTypeError
class OptionsSchema(Schema):
    def __init__(self, *options: str):
        self._options = [option.casefold() for option in options]
        self._error = InvalidOptionError(options)
    def validate(self, data: Any) -> Optional[SchemaError]:
        if not isinstance(data, str):
            return InvalidTypeError(str)
        if data.casefold() not in self._options:
            return self._error
        else:
            return None
@dataclass
class InvalidOptionError(SchemaError):
    expected_options: Sequence[str]
def options_of(*options: str) -> OptionsSchema:
    return OptionsSchema(*options)

from typing import List, Optional
import pandas as pd
class InvalidPeprecError(Exception):
    """Invalid PEPREC file."""
    pass
class PeptideRecord:
    """Peptide record (PEPREC)."""
    def __init__(
        self,
        path: Optional[str] = None,
        context: str = "default",
        extra_required_columns: Optional[List[str]] = None,
    ):
        """
        Peptide record (PEPREC).
        Parameters
        ----------
        path: str, None
            Path to PEPREC file. If not None, file is read on instance creation.
        context: str
            Context of PEPREC. Is used for determining the required columns. Can be any
            of the following: {default, ms2rescore}.
        extra_required_columns: List[str]
            Extra required columns to be validated.
        Attributes
        ----------
        df: pandas.DataFrame
            DataFrame containing peptide record content.
        Methods
        -------
        from_csv(path, **kwargs)
            Read PEPREC from CSV.
        to_csv(path, **kwargs)
            Save PEPREC to CSV, if Path is None, overwrite existing PEPREC file.
        """
        self.path = path
        self.context = context
        self.extra_required_columns = extra_required_columns
        self.df = None
        if self.path:
            self.read_csv(self.path)
    def __repr__(self):
        """Get string representation of PeptideRecord."""
        return self.df.__repr__()
    @property
    def df(self) -> Optional[pd.DataFrame]:
        """Get DataFrame with PeptideRecord."""
        return self._df
    @df.setter
    def df(self, value: Optional[pd.DataFrame]):
        """Set DataFrame with PeptideRecord."""
        if isinstance(value, pd.DataFrame):
            self._validate_column_names(value)
        self._df = value
    def read_csv(self, path: str, **kwargs):
        """Read PEPREC from CSV."""
        self._validate_header(path)
        sep = self._infer_separator(path)
        self.df = pd.read_csv(path, sep=sep, index_col=None, **kwargs)
        self.df["modifications"] = self.df["modifications"].fillna("-")
    def to_csv(self, path: Optional[str] = None, **kwargs):
        """Save PEPREC to CSV, if Path is None, overwrite existing PEPREC file."""
        if not path and self.path:
            path = self.path
        elif not path and not self.path:
            raise ValueError("No known path to write PEPREC file.")
        self.df.to_csv(path, sep=" ", index=False, float_format="%.3f", **kwargs)
    def reorder_columns(self):
        """Reorder columns with canonical PeptideRecord columns first."""
        original_columns = self.df.columns.to_list()
        for col in self._required_columns:
            if col in original_columns:
                original_columns.remove(col)
            else:
                self._required_columns.remove(col)
        reordered_columns = self._required_columns + original_columns
        self.df = self.df[reordered_columns]
    @property
    def _required_columns(self):
        """Get required columns depending on PeptideRecord context."""
        required_columns = [
            "spec_id",
            "peptide",
            "modifications",
            "charge",
        ]
        if self.context == "ms2rescore":
            required_columns.extend(
                ["psm_score", "observed_retention_time",]
            )
        elif self.context == "retention_time":
            required_columns.remove("modifications")
        return required_columns
    def _validate_header(self, path: str):
        """Validate PEPREC header."""
        with open(path, "rt") as f:
            line = f.readline()
            if line[:7] != "spec_id":
                raise InvalidPeprecError("PEPREC header should start with `spec_id`.")
    def _validate_column_names(self, df: pd.DataFrame):
        """Validate header of PEPREC file."""
        for col in self._required_columns:
            if col not in df.columns:
                raise InvalidPeprecError(
                    f"Required column `{col}` missing from header."
                )
    @classmethod
    def from_dataframe(cls, dataframe: pd.DataFrame):
        """Create PeptideRecord instance with data from a pandas DataFrame."""
        peprec = cls()
        peprec.df = dataframe
        peprec.reorder_columns()
        return peprec
    @classmethod
    def from_csv(cls, *args, **kwargs):
        """Create PeptideRecord instance with data from CSV file."""
        peprec = cls()
        peprec.read_csv(*args, **kwargs)
        return peprec
    @staticmethod
    def _infer_separator(path: str) -> str:
        """Infer separator in PEPREC file."""
        with open(path, "rt") as f:
            line = f.readline()
            separator = line[7]
        return separator

import re
from pathlib import Path
from skylos.llm.graph import CodeGraph
class CodeChunk:
    def __init__(
        self,
        content,
        start_line,
        end_line,
        chunk_type,
        name,
        imports,
        class_context,
        file_path,
    ):
        self.content = content
        self.start_line = start_line
        self.end_line = end_line
        self.chunk_type = chunk_type
        self.name = name
        self.imports = imports
        self.class_context = class_context
        self.file_path = file_path
    def get_full_context(self):
        parts = []
        if self.imports:
            parts.append(f"# Imports\n{self.imports}")
        if self.class_context:
            parts.append(f"# Class context\n{self.class_context}")
        parts.append(
            f"# {self.chunk_type.title()}: {self.name} (lines {self.start_line}-{self.end_line})"
        )
        parts.append(self.content)
        return "\n\n".join(parts)
    def with_line_numbers(self):
        lines = self.content.splitlines()
        numbered = []
        for i, line in enumerate(lines, self.start_line):
            numbered.append(f"{i:4d} | {line}")
        return "\n".join(numbered)
class ASTChunker:
    def __init__(
        self,
        max_chunk_tokens=2000,
        overlap_lines=5,
        include_imports=True,
        include_class_context=True,
    ):
        self.max_chunk_chars = max_chunk_tokens * 4
        self.overlap_lines = overlap_lines
        self.include_imports = include_imports
        self.include_class_context = include_class_context
    def chunk_file(self, source, file_path=""):
        try:
            tree = ast.parse(source)
        except SyntaxError:
            return self._fallback_chunk(source, file_path)
        lines = source.splitlines()
        imports = self._extract_imports(tree, lines)
        chunks = []
        for node in ast.iter_child_nodes(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                chunk = self._create_function_chunk(node, lines, imports, file_path)
                chunks.append(chunk)
            elif isinstance(node, ast.ClassDef):
                class_chunk = self._create_class_chunk(node, lines, imports, file_path)
                class_size = len(class_chunk.content)
                if class_size <= self.max_chunk_chars:
                    chunks.append(class_chunk)
                else:
                    class_context = self._get_class_header(node, lines)
                    for item in node.body:
                        if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            method_chunk = self._create_method_chunk(
                                item,
                                lines,
                                imports,
                                file_path,
                                class_name=node.name,
                                class_context=class_context,
                            )
                            chunks.append(method_chunk)
        if not chunks:
            chunks.append(
                CodeChunk(
                    content=source,
                    start_line=1,
                    end_line=len(lines),
                    chunk_type="module",
                    name=Path(file_path).stem if file_path else "module",
                    imports=imports,
                    class_context=None,
                    file_path=file_path,
                )
            )
        chunks = self._split_large_chunks(chunks)
        return chunks
    def _extract_imports(self, tree, lines):
        import_lines = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                start = node.lineno - 1
                end = getattr(node, "end_lineno", node.lineno)
                import_lines.extend(lines[start:end])
        return "\n".join(import_lines)
    def _create_function_chunk(self, node, lines, imports, file_path):
        start = node.lineno - 1
        end = getattr(node, "end_lineno", node.lineno + 10)
        if node.decorator_list:
            start = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start:end])
        return CodeChunk(
            content=content,
            start_line=start + 1,
            end_line=end,
            chunk_type="function",
            name=node.name,
            imports=imports if self.include_imports else "",
            class_context=None,
            file_path=file_path,
        )
    def _create_class_chunk(self, node, lines, imports, file_path):
        start = node.lineno - 1
        end = getattr(node, "end_lineno", node.lineno + 20)
        if node.decorator_list:
            start = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start:end])
        return CodeChunk(
            content=content,
            start_line=start + 1,
            end_line=end,
            chunk_type="class",
            name=node.name,
            imports=imports if self.include_imports else "",
            class_context=None,
            file_path=file_path,
        )
    def _create_method_chunk(
        self, node, lines, imports, file_path, class_name, class_context
    ):
        start = node.lineno - 1
        end = getattr(node, "end_lineno", node.lineno + 10)
        if node.decorator_list:
            start = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start:end])
        name = class_name + "." + node.name
        imports_out = ""
        if self.include_imports:
            imports_out = imports
        class_ctx_out = None
        if self.include_class_context:
            class_ctx_out = class_context
        return CodeChunk(
            content=content,
            start_line=start + 1,
            end_line=end,
            chunk_type="method",
            name=name,
            imports=imports_out,
            class_context=class_ctx_out,
            file_path=file_path,
        )
    def _get_class_header(self, node, lines):
        start = node.lineno - 1
        if node.decorator_list:
            start = min(d.lineno - 1 for d in node.decorator_list)
        header_end = node.lineno
        for item in node.body:
            if isinstance(item, ast.Expr) and isinstance(item.value, ast.Constant):
                header_end = getattr(item, "end_lineno", item.lineno)
            else:
                break
        return "\n".join(lines[start:header_end])
    def _split_large_chunks(self, chunks):
        result = []
        for chunk in chunks:
            if len(chunk.content) <= self.max_chunk_chars:
                result.append(chunk)
            else:
                sub_chunks = self._split_by_blocks(chunk)
                result.extend(sub_chunks)
        return result
    def _split_by_blocks(self, chunk):
        lines = chunk.content.splitlines()
        chunk_lines = self.max_chunk_chars // 60
        sub_chunks = []
        i = 0
        while i < len(lines):
            end = min(i + chunk_lines, len(lines))
            if end < len(lines):
                for j in range(end, max(i + chunk_lines // 2, i), -1):
                    if not lines[j].strip() or lines[j].strip().startswith(
                        ("#", "def ", "class ")
                    ):
                        end = j
                        break
            sub_content = "\n".join(lines[i:end])
            sub_chunks.append(
                CodeChunk(
                    content=sub_content,
                    start_line=chunk.start_line + i,
                    end_line=chunk.start_line + end - 1,
                    chunk_type=f"{chunk.chunk_type}_part",
                    name=f"{chunk.name}_part{len(sub_chunks) + 1}",
                    imports=chunk.imports,
                    class_context=chunk.class_context,
                    file_path=chunk.file_path,
                )
            )
            i = end - self.overlap_lines
            if i <= 0 or end >= len(lines):
                break
        if sub_chunks:
            return sub_chunks
        return [chunk]
    def _fallback_chunk(self, source, file_path):
        lines = source.splitlines()
        chunk_lines = self.max_chunk_chars // 60
        import_re = re.compile(r"^(?:from\s+\S+\s+)?import\s+.+$")
        imports_list = []
        for line in lines[:50]:
            if import_re.match(line.strip()):
                imports_list.append(line)
        imports = "\n".join(imports_list)
        chunks = []
        i = 0
        while i < len(lines):
            end = min(i + chunk_lines, len(lines))
            content = "\n".join(lines[i:end])
            chunks.append(
                CodeChunk(
                    content=content,
                    start_line=i + 1,
                    end_line=end,
                    chunk_type="block",
                    name=f"block_{len(chunks) + 1}",
                    imports=imports,
                    class_context=None,
                    file_path=file_path,
                )
            )
            i = end - self.overlap_lines
            if i <= 0:
                break
        return (
            chunks
            if chunks
            else [
                CodeChunk(
                    content=source,
                    start_line=1,
                    end_line=len(lines),
                    chunk_type="module",
                    name="module",
                    imports=imports,
                    class_context=None,
                    file_path=file_path,
                )
            ]
        )
class ContextBuilder:
    def __init__(self, max_context_tokens=8000):
        self.max_context_tokens = max_context_tokens
        self.chunker = ASTChunker(max_chunk_tokens=max_context_tokens // 2)
    def chunk_file(self, source, file_path=""):
        return self.chunker.chunk_file(source, file_path)
    def build_analysis_context(
        self, source_or_chunk, file_path=None, defs_map=None, include_imports=True
    ):
        if isinstance(source_or_chunk, CodeChunk):
            return self._build_chunk_context(source_or_chunk, defs_map)
        source = source_or_chunk
        file_path = file_path or ""
        lines = source.splitlines()
        name = "module"
        if file_path:
            name = Path(file_path).stem
        imports = ""
        if include_imports:
            imports = self._extract_imports_str(source)
        chunk = CodeChunk(
            content=source,
            start_line=1,
            end_line=len(lines),
            chunk_type="module",
            name=name,
            imports=imports,
            class_context=None,
            file_path=file_path,
        )
        return self._build_chunk_context(chunk, defs_map)
    def build_smart_slice(self, full_source, function_name):
        graph = CodeGraph()
        graph.build(full_source)
        sliced = graph.get_slice(function_name)
        if sliced:
            return f"=== CONTEXT SLICE (Focus: {function_name}) ===\n{sliced}"
        return None
    def _extract_imports_str(self, source):
        try:
            tree = ast.parse(source)
            lines = source.splitlines()
            import_lines = []
            for node in ast.walk(tree):
                if isinstance(node, (ast.Import, ast.ImportFrom)):
                    start = node.lineno - 1
                    end = getattr(node, "end_lineno", node.lineno)
                    import_lines.extend(lines[start:end])
            return "\n".join(import_lines)
        except:
            return ""
    def _build_chunk_context(self, chunk, defs_map=None):
        parts = []
        parts.append(f"=== FILE: {chunk.file_path} ===")
        parts.append(
            f"Analyzing: {chunk.chunk_type} '{chunk.name}' (lines {chunk.start_line}-{chunk.end_line})"
        )
        if chunk.imports:
            parts.append(f"\n[IMPORTS]\n{chunk.imports}")
        if chunk.class_context:
            parts.append(f"\n[CLASS CONTEXT]\n{chunk.class_context}")
        if defs_map:
            deps = self._find_dependencies(chunk.content, defs_map, chunk.file_path)
            if deps:
                parts.append(f"\n[EXTERNAL DEPENDENCIES]\n{deps}")
        parts.append(f"\n[CODE]\n{chunk.with_line_numbers()}")
        return "\n".join(parts)
    def build_fix_context(
        self, source, file_path, issue_line, issue_message, defs_map=None
    ):
        lines = source.splitlines()
        chunks = self.chunker.chunk_file(source, file_path)
        target_chunk = None
        for chunk in chunks:
            if chunk.start_line <= issue_line <= chunk.end_line:
                target_chunk = chunk
                break
        if target_chunk:
            context = self.build_analysis_context(target_chunk, defs_map)
        else:
            start = max(0, issue_line - 20)
            end = min(len(lines), issue_line + 20)
            numbered = []
            for i in range(start + 1, end + 1):
                num = str(i).rjust(4)
                numbered.append(num + " | " + lines[i - 1])
            context = "[CODE]\n" + "\n".join(numbered)
        return f"=== FIX CONTEXT ===\n[ISSUE] Line {issue_line}: {issue_message}\n\n{context}"
    def _find_dependencies(self, content, defs_map, current_file):
        used_names = set(re.findall(r"\b([a-zA-Z_][a-zA-Z0-9_]*)\b", content))
        deps = []
        for name, info in defs_map.items():
            if isinstance(info, dict):
                def_name = info.get("name", name)
                def_type = info.get("type", "unknown")
                def_file = str(info.get("file", ""))
            else:
                def_name = getattr(info, "name", name)
                def_type = getattr(info, "type", "unknown")
                def_file = str(getattr(info, "filename", ""))
            if def_name in used_names and def_file:
                source = (
                    "this file" if def_file == current_file else Path(def_file).name
                )
                deps.append(f"  - {def_name} ({def_type}) from {source}")
        return "\n".join(deps[:50])
    def _build_project_index(self, defs_map, max_items=150):
        if not defs_map:
            return ""
        index = []
        for name, info in defs_map.items():
            if isinstance(info, dict):
                def_name = info.get("name", name)
                def_type = info.get("type", "unknown")
                def_file = str(info.get("file", ""))
            else:
                def_name = getattr(info, "name", name)
                def_type = getattr(info, "type", "unknown")
                def_file = str(getattr(info, "filename", ""))
            short_file = Path(def_file).name if def_file else "?"
            index.append(f"  - {def_name} ({def_type}) [{short_file}]")
        if len(index) > max_items:
            index = index[:max_items]
            index.append(f"  ... and {len(defs_map) - max_items} more")
        return "\n".join(index)
