import torch
from torch.distributed.fsdp import fully_shard, MixedPrecisionPolicy
from torch.distributed.tensor import Shard
from torch.distributed.distributed_c10d import ReduceOp
from mindspeed.fsdp.parallel_engine_config import EPPlanConfig
from mindspeed.fsdp.utils.log import print_rank
from mindspeed.fsdp.utils.str_match import module_name_match
from mindspeed_mm.fsdp.params.parallel_args import FSDPPlanConfig
from mindspeed_mm.fsdp.distributed.fully_shard_parallel import get_mixprecision_policy
logger = logging.getLogger(__name__)
def expert_fully_shard_modules(model: torch.nn.Module, efsdp_mesh, ep_plan: EPPlanConfig, fsdp_plan: FSDPPlanConfig) -> torch.nn.Module:
    efsdp_modules = get_efsdp_modules(model, ep_plan)
    config = {'mesh': efsdp_mesh,
              'mp_policy': get_mixprecision_policy(fsdp_plan),
              'shard_placement_fn': lambda x: Shard(1)}
    apply_hccl_premul_sum_patch()
    for experts in efsdp_modules:
        if isinstance(experts, torch.nn.ModuleList):
            for expert in experts:
                fully_shard(expert, **config)
                set_gradient_divide_factor(expert, ep_plan._gradient_divide_factor)
        else:
            fully_shard(experts, **config)
            set_gradient_divide_factor(experts, ep_plan._gradient_divide_factor)
    return model
def get_efsdp_modules(modules: torch.nn.Module, plan: EPPlanConfig):
    efsdp_modules = []
    for plan_name in plan.apply_efsdp_modules:
        for name, module in modules.named_modules():
            if module_name_match(plan_name, name):
                print_rank(logger.debug, f'[Expert Fully Shard]: Apply efsdp to module <{name}>')
                efsdp_modules.append(module)
    if len(efsdp_modules) == 0:
        raise RuntimeError(f'[Expert Fully Shard] No module named {plan} or not be ModuleList')
    return efsdp_modules
def set_gradient_divide_factor(module, factor):
    if hasattr(module, 'set_gradient_divide_factor'):
        module.set_gradient_divide_factor(factor)
    else:
        module.set_reduce_scatter_divide_factor(factor)
def hccl_premul_sum_wrapper(op, output_name):
    """
    A wrapper for distributed operations to handle ReduceOp.PREMUL_SUM which is not supported in Huawei HCCL.
    This wrapper intercepts operations using ReduceOp.PREMUL_SUM and converts them into equivalent
    ReduceOp.SUM operations followed by scalar multiplication.
    """
    def wrapper(*args, **kwargs):
        # Note:Although the sequence of operations(ReduceOp.SUM followed by multiplication) may differ from semantics,
        # we have verified that there is no problem with the performance and accuracy of this sequence.
        factor = None
        if "op" in kwargs and kwargs["op"] == ReduceOp.PREMUL_SUM:
            factor = kwargs["op"].__getstate__()[1]
            kwargs["op"] = ReduceOp.SUM
        handle = op(*args, **kwargs)
        if handle is not None:
            handle.wait()
        if factor is not None:
            output = args[0] if len(args) > 0 else kwargs[output_name]
            output.data.mul_(factor)
        return handle
    return wrapper
def apply_hccl_premul_sum_patch():
    torch.distributed.all_reduce = hccl_premul_sum_wrapper(torch.distributed.all_reduce, "tensor")
    torch.distributed.reduce_scatter = hccl_premul_sum_wrapper(torch.distributed.reduce_scatter, "output")
    torch.distributed.reduce_scatter_tensor = hccl_premul_sum_wrapper(
        torch.distributed.reduce_scatter_tensor, "output"
    )

def period_boundaries(start_date, end_date, granularity):
    periods = []
    if granularity == "monthly":
        cur = start_date.replace(day=1)
        while cur < end_date:
            next_p = (cur.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            periods.append((cur, min(next_p, end_date), cur.strftime("%Y-%m")))
            cur = next_p
    else:  # yearly
        cur = start_date.replace(month=1, day=1)
        while cur < end_date:
            next_p = cur.replace(year=cur.year + 1)
            periods.append((cur, min(next_p, end_date), str(cur.year)))
            cur = next_p
    return periods
def filter_by_date(entries, start_date, end_date):
    filtered = []
    for e in entries:
        if not hasattr(e, "date"):
            filtered.append(e)
            continue
        if start_date and e.date < start_date:
            continue
        if end_date and e.date >= end_date:
            continue
        filtered.append(e)
    return filtered
def walk_tree(real_account):
    node = {
        "account": real_account.account,
        "balance": {},
        "children": [],
    }
    for pos in real_account.balance:
        cur = pos.units.currency
        amt = float(pos.units.number)
        node["balance"][cur] = node["balance"].get(cur, 0) + amt
    for child in sorted(real_account.values(), key=lambda r: r.account):
        child_node = walk_tree(child)
        if child_node["children"] or child_node["balance"]:
            node["children"].append(child_node)
    return node
def extract_tree(realization, root, prefix):
    acc = realization.get(root, prefix)
    if acc is None:
        return {"account": prefix, "balance": {}, "children": []}
    return walk_tree(acc)
def sum_tree(realization, root, prefix):
    acc = realization.get(root, prefix)
    if acc is None:
        return {}
    totals = {}
    def walk(node):
        for pos in node.balance:
            cur = pos.units.currency
            amt = float(pos.units.number)
            totals[cur] = totals.get(cur, 0) + amt
        for child in node.values():
            walk(child)
    walk(acc)
    return totals
def convert_balance(balance, price_map, target_currency, date=None):
    """Convert a {currency: amount} dict to a single {target_currency: amount} dict."""
    from beancount.core.prices import get_price
    total = 0.0
    for cur, amt in balance.items():
        if cur == target_currency:
            total += amt
        else:
            result = get_price(price_map, (cur, target_currency), date)
            if result is None:
                raise click.UsageError(f"No price found for {cur} -> {target_currency}")
            _, price = result
            total += amt * float(price)
    return {target_currency: round(total, 2)}
def _tree_total(node):
    """Sum all balances in a tree (node + descendants)."""
    total = sum(node["balance"].values())
    for child in node["children"]:
        total += _tree_total(child)
    return total
def convert_tree(node, price_map, target_currency, date=None):
    """Recursively convert all balances in an account tree to target currency."""
    children = [convert_tree(child, price_map, target_currency, date) for child in node["children"]]
    children.sort(key=lambda c: abs(_tree_total(c)), reverse=True)
    converted = {
        "account": node["account"],
        "balance": convert_balance(node["balance"], price_map, target_currency, date) if node["balance"] else {},
        "children": children,
    }
    return converted
