class HabitatRLEnv(RLEnv):
    def __init__(self, config, dataset):
        super().__init__(config, dataset)
    def reset(self):
        observations = super().reset()
        metrics = self.habitat_env.get_metrics()
        self.previous_distance = metrics.get("geodesic_to_goal", 0)
        return observations
    def step(self, *args, **kwargs):
        return super().step(*args, **kwargs)
    def get_reward_range(self):
        return (-np.inf, np.inf)
    def get_reward(self, observations):
        metrics = self.habitat_env.get_metrics()
        current_distance = metrics.get("geodesic_to_goal", 0)
        reward = self.previous_distance - current_distance
        reward -= 0.01
        if metrics.get("success", False):
            reward += 10.0
        self.previous_distance = current_distance
        return reward
    def get_done(self, observations):
        done = False
        # 1. if episode is over
        if self.habitat_env.episode_over:
            done = True
        # 2. if collision is detected
        metrics = self.habitat_env.get_metrics()
        if metrics.get("collisions", 0) > 0:
            done = True
        return done
    def get_info(self, observations):
        info = self.habitat_env.get_metrics()
        return info
def _worker(
    parent: connection.Connection,
    p: connection.Connection,
    env_fn_wrapper: CloudpickleWrapper,
    obs_bufs: Optional[Union[dict, tuple, ShArray]] = None,
) -> None:
    def _encode_obs(
        obs: Union[dict, tuple, np.ndarray], buffer: Union[dict, tuple, ShArray]
    ) -> None:
        if isinstance(obs, np.ndarray) and isinstance(buffer, ShArray):
            buffer.save(obs)
        elif isinstance(obs, tuple) and isinstance(buffer, tuple):
            for o, b in zip(obs, buffer):
                _encode_obs(o, b)
        elif isinstance(obs, dict) and isinstance(buffer, dict):
            for k in obs.keys():
                _encode_obs(obs[k], buffer[k])
        return None
    parent.close()
    env = env_fn_wrapper.data()
    try:
        while True:
            try:
                cmd, data = p.recv()
            except EOFError:  # the pipe has been closed
                p.close()
                break
            if cmd == "step":
                env_return = env.step(data)
                if obs_bufs is not None:
                    _encode_obs(env_return[0], obs_bufs)
                    env_return = (None, *env_return[1:])
                p.send(env_return)
            elif cmd == "reset":
                retval = env.reset(**data)
                reset_returns_info = (
                    isinstance(retval, (tuple, list))
                    and len(retval) == 2
                    and isinstance(retval[1], dict)
                )
                if reset_returns_info:
                    obs, info = retval
                else:
                    obs = retval
                if obs_bufs is not None:
                    _encode_obs(obs, obs_bufs)
                    obs = None
                if reset_returns_info:
                    p.send((obs, info))
                else:
                    p.send(obs)
            elif cmd == "close":
                p.send(env.close())
                p.close()
                break
            elif cmd == "render":
                p.send(env.render(**data) if hasattr(env, "render") else None)
            elif cmd == "seed":
                if hasattr(env, "seed"):
                    p.send(env.seed(data))
                else:
                    env.reset(seed=data)
                    p.send(None)
            elif cmd == "getattr":
                p.send(getattr(env, data) if hasattr(env, data) else None)
            elif cmd == "setattr":
                setattr(env.unwrapped, data["key"], data["value"])
            elif cmd == "get_observations":
                # Habitat-specific: get current observations
                if hasattr(env, "get_observations"):
                    p.send(env.get_observations())
                elif hasattr(env, "observations"):
                    p.send(env.observations)
                else:
                    p.send(None)
            elif cmd == "get_current_episode_id":
                # Habitat-specific: get current episode_id from habitat_env.current_episode
                if hasattr(env, "habitat_env") and hasattr(
                    env.habitat_env, "current_episode"
                ):
                    episode_id = env.habitat_env.current_episode.episode_id
                    p.send(episode_id)
                else:
                    p.send(None)
            elif cmd == "reconfigure":
                env.close()
                config = data.pop("config")
                seed = data.pop("seed")
                env = HabitatRLEnv(config=config)
                env.seed(seed)
                p.send(None)
            else:
                p.close()
                raise NotImplementedError
    except KeyboardInterrupt:
        p.close()
class ReconfigureSubprocEnvWorker(SubprocEnvWorker):
    def __init__(self, env_fn: Callable[[], gym.Env], share_memory: bool = False):
        ctx = multiprocessing.get_context("spawn")
        self.parent_remote, self.child_remote = ctx.Pipe()
        self.share_memory = share_memory
        self.buffer: Optional[Union[dict, tuple, ShArray]] = None
        if self.share_memory:
            dummy = env_fn()
            obs_space = dummy.observation_space
            dummy.close()
            del dummy
            self.buffer = _setup_buf(obs_space)
        args = (
            self.parent_remote,
            self.child_remote,
            CloudpickleWrapper(env_fn),
            self.buffer,
        )
        self.process = ctx.Process(target=_worker, args=args, daemon=True)
        self.process.start()
        self.child_remote.close()
        EnvWorker.__init__(self, env_fn)
    def reconfigure_env_fn(self, env_fn_param):
        self.parent_remote.send(["reconfigure", env_fn_param])
        return self.parent_remote.recv()
class ReconfigureSubprocEnv(SubprocVectorEnv):
    def __init__(self, env_fns: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def worker_fn(fn: Callable[[], gym.Env]) -> ReconfigureSubprocEnvWorker:
            return ReconfigureSubprocEnvWorker(fn, share_memory=False)
        BaseVectorEnv.__init__(self, env_fns, worker_fn, **kwargs)
    def reconfigure_env_fns(self, env_fns, id=None):
        self._assert_is_not_closed()
        id = self._wrap_id(id)
        if self.is_async:
            self._assert_id(id)
        for j, i in enumerate(id):
            self.workers[i].reconfigure_env_fn(env_fns[j])
    def get_current_episode_ids(self, id=None):
        self._assert_is_not_closed()
        id = self._wrap_id(id)
        if self.is_async:
            self._assert_id(id)
        episode_ids = []
        for i in id:
            self.workers[i].parent_remote.send(["get_current_episode_id", None])
            episode_id = self.workers[i].parent_remote.recv()
            episode_ids.append(episode_id)
        return episode_ids

