OMEGA JSON Compatibility Wrapper - orjson for hot paths, stdlib fallback.
Drop-in replacement: import omega.json_compat as json
Rollback: OMEGA_USE_STDLIB_JSON=1
"""
import os
import json as _json
_USE_ORJSON = os.environ.get("OMEGA_USE_STDLIB_JSON") != "1"
try:
    if _USE_ORJSON:
        import orjson as _orjson
    else:
        _orjson = None
except ImportError:
    _orjson = None
def loads(s, **kwargs):
    if _orjson and not kwargs:
        return _orjson.loads(s if isinstance(s, (bytes, bytearray, memoryview)) else s.encode())
    return _json.loads(s, **kwargs)
def dumps(obj, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    if indent is not None or not _orjson:
        return _json.dumps(
            obj, indent=indent, default=default, sort_keys=sort_keys, ensure_ascii=ensure_ascii, **kwargs
        )
    opts = 0
    if sort_keys:
        opts |= _orjson.OPT_SORT_KEYS
    orjson_default = default if callable(default) else (str if default == str else None)
    return _orjson.dumps(obj, default=orjson_default, option=opts or None).decode()
def load(fp, **kwargs):
    return loads(fp.read(), **kwargs)
def dump(obj, fp, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    fp.write(dumps(obj, indent=indent, default=default, sort_keys=sort_keys, ensure_ascii=ensure_ascii, **kwargs))

Type definitions for shuo.
All state, events, and actions are immutable dataclasses.
Minimal -- only what the main loop needs to route decisions.
Conversation history lives in Agent, not in AppState.
"""
from dataclasses import dataclass
from enum import Enum, auto
from typing import Optional, Union, List
# =============================================================================
# STATE
# =============================================================================
class Phase(Enum):
    """Current phase of the conversation."""
    LISTENING = auto()    # Waiting for user / user speaking
    RESPONDING = auto()   # Agent active (LLM -> TTS -> Playback)
@dataclass(frozen=True)
class AppState:
    """
    Application state -- just routing information.
    Conversation history is owned by Agent, not tracked here.
    """
    phase: Phase = Phase.LISTENING
    stream_sid: Optional[str] = None
# =============================================================================
# EVENTS (inputs to the system)
# =============================================================================
@dataclass(frozen=True)
class StreamStartEvent:
    """Twilio stream started."""
    stream_sid: str
@dataclass(frozen=True)
class StreamStopEvent:
    """Twilio stream ended."""
    pass
@dataclass(frozen=True)
class MediaEvent:
    """Audio data received from Twilio."""
    audio_bytes: bytes
@dataclass(frozen=True)
class FluxStartOfTurnEvent:
    """Deepgram Flux detected user started speaking (barge-in)."""
    pass
@dataclass(frozen=True)
class FluxEndOfTurnEvent:
    """Deepgram Flux detected user finished speaking."""
    transcript: str
@dataclass(frozen=True)
class AgentTurnDoneEvent:
    """Agent finished speaking (playback complete)."""
    pass
Event = Union[
    StreamStartEvent, StreamStopEvent, MediaEvent,
    FluxStartOfTurnEvent, FluxEndOfTurnEvent,
    AgentTurnDoneEvent,
]
# =============================================================================
# ACTIONS (outputs from the system)
# =============================================================================
@dataclass(frozen=True)
class FeedFluxAction:
    """Send audio to Deepgram Flux."""
    audio_bytes: bytes
