def inject_styles() -> None:
    """Inject the Playbook CSS styles into the page head."""
    ui.add_head_html(f"<style>{PLAYBOOK_CSS}</style>")
# Script to apply dark mode immediately and prevent FOUC
THEME_INIT_SCRIPT = """
<script>
(function() {
    // Check localStorage for theme preference (default to dark)
    var theme = localStorage.getItem('playbook-theme');
    var colorTheme = localStorage.getItem('playbook-color-theme') || 'swizzin';
    if (theme !== 'light') {
        // Default to dark mode if no preference or preference is 'dark'
        document.body.classList.add('body--dark');
    }
    if (colorTheme === 'catppuccin') {
        document.body.classList.add('theme-catppuccin');
    } else {
        document.body.classList.add('theme-swizzin');
    }
    // Enable transitions after a brief delay to prevent FOUC
    setTimeout(function() {
        document.body.classList.add('theme-ready');
    }, 50);
})();
</script>
"""
def inject_theme_init_script() -> None:
    """Inject script to apply theme immediately on page load."""
    ui.add_body_html(THEME_INIT_SCRIPT)
def setup_page_styles() -> None:
    """Set up all page styles."""
    inject_styles()
    inject_theme_init_script()
def apply_color_theme(theme_name: str) -> None:
    """Apply GUI color theme class to document body."""
    normalized = theme_name.strip().lower() if theme_name else "swizzin"
    if normalized not in {"swizzin", "catppuccin"}:
        normalized = "swizzin"
    ui.run_javascript(
        """
        document.body.classList.remove('theme-swizzin', 'theme-catppuccin');
        document.body.classList.add('theme-"""
        + normalized
        + """');
        localStorage.setItem('playbook-color-theme', '"""
        + normalized
        + """');
        """
    )

from .schemas import Finding, Severity, Confidence, IssueType, CodeLocation
class ValidationResult:
    def __init__(self, valid, adjusted_finding, reason):
        self.valid = valid
        self.adjusted_finding = adjusted_finding
        self.reason = reason
class CodeValidator:
    def __init__(self, strict=False):
        self.strict = strict
    def validate(self, finding, source, file_path):
        lines = source.splitlines()
        total_lines = len(lines)
        issues = []
        location = CodeLocation(
            file=finding.location.file,
            line=finding.location.line,
            end_line=finding.location.end_line,
            column=finding.location.column,
        )
        f = Finding(
            rule_id=finding.rule_id,
            issue_type=finding.issue_type,
            severity=finding.severity,
            confidence=finding.confidence,
            message=finding.message,
            location=location,
            suggestion=finding.suggestion,
            explanation=finding.explanation,
        )
        if f.location.line < 1 or f.location.line > total_lines:
            if self.strict:
                msg = (
                    "Line "
                    + str(f.location.line)
                    + " out of range (1-"
                    + str(total_lines)
                    + ")"
                )
                return ValidationResult(False, None, msg)
            if f.location.line < 1:
                f.location.line = 1
            if f.location.line > total_lines:
                f.location.line = total_lines
            f.confidence = Confidence.LOW
            issues.append("line_adjusted")
        line_content = ""
        if f.location.line >= 1 and f.location.line <= total_lines:
            line_content = lines[f.location.line - 1]
        if not self._is_line_relevant(f, line_content):
            if self.strict:
                return ValidationResult(
                    False, None, "Line content not relevant to finding"
                )
            f.confidence = Confidence.LOW
            issues.append("low_relevance")
        symbol = self._extract_symbol(f.message)
        if symbol is not None and symbol != "":
            if not self._symbol_exists(symbol, source):
                if self.strict:
                    return ValidationResult(
                        False, None, "Symbol '" + symbol + "' not found in code"
                    )
                f.confidence = Confidence.UNCERTAIN
                issues.append("symbol_not_found:" + symbol)
        if f.issue_type == IssueType.SECURITY:
            if not self._verify_security_pattern(f, lines):
                if self.strict:
                    return ValidationResult(
                        False, None, "Security pattern not found at location"
                    )
                f.confidence = Confidence.LOW
                issues.append("pattern_not_verified")
        if issues:
            note = "[Validation: " + ", ".join(issues) + "]"
            if f.explanation:
                f.explanation = str(f.explanation) + " " + note
            else:
                f.explanation = note
        return ValidationResult(True, f, "passed")
    def _is_line_relevant(self, finding, line_content):
        if line_content is None:
            return False
        line = line_content.strip().lower()
        if line == "":
            return False
        if line.startswith("#"):
            return False
        if finding.issue_type == IssueType.SECURITY:
            return True
        if finding.issue_type == IssueType.DEAD_CODE:
            keywords = ["def ", "class ", "import ", "from ", "="]
            for kw in keywords:
                if kw in line:
                    return True
            return False
        if finding.issue_type == IssueType.QUALITY:
            return True
        return True
    def _extract_symbol(self, message):
        if not message:
            return None
        patterns = [
            r"(?:function|method|class|import|variable)[\s:]+['\"`]?(\w+)['\"`]?",
            r"['\"`](\w+)['\"`]",
            r":\s+(\w+)\s*$",
            r"unused\s+(\w+)",
        ]
        for pattern in patterns:
            match = re.search(pattern, message, re.IGNORECASE)
            if match:
                return match.group(1)
        return None
    def _symbol_exists(self, symbol, source):
        if not symbol:
            return False
        if not source:
            return False
        pattern = r"\b" + re.escape(symbol) + r"\b"
        return re.search(pattern, source) is not None
    def _verify_security_pattern(self, finding, lines):
        if finding.location.line > len(lines):
            return False
        start = finding.location.line - 3
        if start < 0:
            start = 0
        end = finding.location.line + 2
        if end > len(lines):
            end = len(lines)
        context = "\n".join(lines[start:end]).lower()
        msg = str(finding.message or "").lower()
        patterns = {
            "sql": [
                "execute",
                "query",
                "cursor",
                "select",
                "insert",
                "update",
                "delete",
                'f"',
                "f'",
                "%s",
                ".format",
            ],
            "injection": ["subprocess", "os.system", "shell", "popen", "eval", "exec"],
            "hardcoded": [
                "password",
                "secret",
                "key",
                "token",
                "api_key",
                "apikey",
                '= "',
                "= '",
            ],
            "xss": ["render", "html", "template", "innerhtml", "mark_safe"],
            "pickle": ["pickle", "loads", "load", "unpickle"],
            "yaml": ["yaml.load", "yaml.unsafe_load"],
            "path": ["../", "path", "file", "open(", "read("],
        }
        for keyword in patterns:
            if keyword in msg:
                indicators = patterns[keyword]
                found = False
                for ind in indicators:
                    if ind in context:
                        found = True
                        break
                if found:
                    return True
                return False
        return True
class ResultValidator:
    def __init__(self, strict=False, min_confidence=Confidence.LOW):
        self.code_validator = CodeValidator(strict=strict)
        self.min_confidence = min_confidence
        self.strict = strict
    def validate(self, findings, source, file_path):
        stats = {
            "original": len(findings),
            "accepted": 0,
            "rejected": 0,
            "adjusted": 0,
        }
        validated = []
        for finding in findings:
            result = self.code_validator.validate(finding, source, file_path)
            if result.valid and result.adjusted_finding is not None:
                if self._meets_confidence(result.adjusted_finding.confidence):
                    validated.append(result.adjusted_finding)
                    stats["accepted"] += 1
                    if result.adjusted_finding.confidence != finding.confidence:
                        stats["adjusted"] += 1
                else:
                    stats["rejected"] += 1
            else:
                stats["rejected"] += 1
        return validated, stats
    def _meets_confidence(self, conf):
        rank = {
            Confidence.HIGH: 0,
            Confidence.MEDIUM: 1,
            Confidence.LOW: 2,
            Confidence.UNCERTAIN: 3,
        }
        conf_rank = rank.get(conf, 999)
        min_rank = rank.get(self.min_confidence, 999)
        return conf_rank <= min_rank
def deduplicate_findings(findings):
    if not findings:
        return []
    seen = set()
    unique = []
    for f in findings:
        msg_key = ""
        if f.message:
            msg_key = f.message[:50].lower()
        is_dup = False
        # +-2 line tolerance
        offset = -2
        while offset <= 2:
            key = (f.location.file, f.location.line + offset, msg_key)
            if key in seen:
                is_dup = True
                break
            offset += 1
        if not is_dup:
            key = (f.location.file, f.location.line, msg_key)
            seen.add(key)
            unique.append(f)
    return unique
def merge_findings(llm_findings, static_findings, file_path):
    merged = []
    llm_by_line = {}
    for f in llm_findings:
        line = f.location.line
        if line not in llm_by_line:
            llm_by_line[line] = []
        llm_by_line[line].append(f)
    static_lines_covered = set()
    for f in llm_findings:
        static_match = False
        for static in static_findings:
            static_line = 0
            if "line" in static:
                static_line = static.get("line", 0)
            else:
                static_line = static.get("lineno", 0)
            if abs(f.location.line - static_line) <= 2:
                static_match = True
                static_lines_covered.add(static_line)
                break
        if static_match:
            if f.confidence == Confidence.MEDIUM or f.confidence == Confidence.LOW:
                f.confidence = Confidence.HIGH
            suffix = " [Corroborated by static analysis]"
            if f.explanation:
                f.explanation = str(f.explanation) + suffix
                f.explanation = f.explanation.strip()
            else:
                f.explanation = suffix.strip()
        merged.append(f)
    for static in static_findings:
        static_line = 0
        if "line" in static:
            static_line = static.get("line", 0)
        else:
            static_line = static.get("lineno", 0)
        if static_line in static_lines_covered:
            continue
        nearby = False
        for line in llm_by_line:
            if abs(line - static_line) <= 2:
                nearby = True
                break
        if nearby:
            continue
        rule_id = static.get("rule_id")
        if not rule_id:
            rule_id = static.get("code", "STATIC")
        msg = static.get("message")
        if not msg:
            msg = static.get("msg", "Issue detected")
        merged.append(
            Finding(
                rule_id=rule_id,
                issue_type=_infer_issue_type(static),
                severity=_parse_severity(static.get("severity", "medium")),
                confidence=Confidence.MEDIUM,
                message=msg,
                location=CodeLocation(file=file_path, line=static_line),
                explanation="[From static analysis only]",
            )
        )
    return merged
def _infer_issue_type(static):
    msg = str(static.get("message", "") + static.get("rule_id", "")).lower()
    sec_words = ["security", "injection", "xss", "sql", "secret"]
    for kw in sec_words:
        if kw in msg:
            return IssueType.SECURITY
    dead_words = ["unused", "dead", "unreachable"]
    for kw in dead_words:
        if kw in msg:
            return IssueType.DEAD_CODE
    return IssueType.QUALITY
def _parse_severity(sev):
    s = str(sev or "").lower()
    if s == "critical" or s == "blocker":
        return Severity.CRITICAL
    if s == "high" or s == "error":
        return Severity.HIGH
    if s == "medium" or s == "warning":
        return Severity.MEDIUM
    return Severity.LOW
Validator = CodeValidator
merge_with_static = merge_findings

from mlir import ir
from mlir.dialects import linalg, arith, tensor, math
from .utils import (
    affine_map,
    get_bias,
    get_outputs,
    get_weights,
    parallel,
    reduction,
)
def affine_maps_and_iter_types(rank: int):
    M, N, K = [ir.AffineDimExpr.get(i) for i in range(3)]
    if rank == 2:  # plain 2D weights
        affine_maps = [
            affine_map(3, [M, K]),
            affine_map(3, [K, N]),
            affine_map(3, [M, N]),
        ]
        iterator_types = [parallel, parallel, reduction]
    elif rank == 4:  # tiled weights, no vnni blocking
        mb, nb, kb = [ir.AffineDimExpr.get(i) for i in range(3, 6)]
        affine_maps = [
            affine_map(6, [M, K, mb, kb]),
            affine_map(6, [N, K, kb, nb]),  # transposed K and N on B
            affine_map(6, [M, N, mb, nb]),
        ]
        iterator_types = [parallel, parallel, reduction] * 2
    elif rank == 5:  # tiled weights with vnni blocking
        # FIXME: due to replicating C++ code, vnni dim is in middle instead of at end.
        k_vnni, mb, nb, kb = [ir.AffineDimExpr.get(i) for i in range(3, 7)]
        affine_maps = [
            affine_map(7, [M, K, mb, kb, k_vnni]),
            # TODO(RM): check if kb and (k_)vnni _not_ being contiguous makes sense.
            affine_map(7, [N, K, kb, nb, k_vnni]),  # transposed K and N on B
            affine_map(7, [M, N, mb, nb]),
        ]
        iterator_types = [
            parallel,  # M
            parallel,  # N
            reduction,  # K
            reduction,  # vnni
            parallel,  # mb
            parallel,  # nb
            reduction,  # kb
        ]
    else:
        assert False
    return affine_maps, iterator_types
def times_weights(
    inputs: ir.Value,
    weights_or_weights_type: Union[ir.Value, ir.RankedTensorType],
    outputs_or_outputs_type: Union[ir.Value, ir.RankedTensorType],
) -> ir.Value:
    weights: ir.Value = get_weights(weights_or_weights_type)
    outputs: ir.Value = get_outputs(outputs_or_outputs_type)
    if weights.type.rank == 5:  # tiled weights with vnni blocking
        vnni_block = weights.type.get_dim_size(4)
        assert inputs.type.shape[-1] % vnni_block == 0
        expanded_shape = (
            inputs.type.shape[:-1]
            + [inputs.type.shape[-1] // vnni_block]
            + [vnni_block]
        )
        inputs = tensor.expand_shape(
            ir.RankedTensorType.get(expanded_shape, inputs.type.element_type),
            inputs,
            reassociation=[[0], [1], [2], [3, 4]],
            output_shape=[],
            static_output_shape=expanded_shape,
        )
    affine_maps, iterator_types = affine_maps_and_iter_types(weights.type.rank)
    @linalg.generic([inputs, weights], [outputs], affine_maps, iterator_types)
    def inputs_times_weights(a, b, c):
        prod = arith.MulFOp(a, b)
        return arith.AddFOp(prod.result, c)
    return inputs_times_weights
def add_bias(inputs: ir.Value, bias_or_bias_type: Union[ir.Value, ir.Type] = None):
    bias: ir.Value = get_bias(bias_or_bias_type)
    M, N, mb, nb = [ir.AffineDimExpr.get(i) for i in range(4)]
    affine_maps, iterator_types = {
        2: ([affine_map(2, [N]), affine_map(2, [M, N])], [parallel] * 2),
        4: ([affine_map(4, [N, nb]), affine_map(4, [M, N, mb, nb])], [parallel] * 4),
    }[inputs.type.rank]
    @linalg.generic([bias], [inputs], affine_maps, iterator_types)
    def biased(a, b):
        return arith.AddFOp(a, b)
    return biased
def relu(inputs: ir.Value):
    zero = arith.constant(inputs.type.element_type, 0.0)
    M, N, mb, nb = [ir.AffineDimExpr.get(i) for i in range(4)]
    affine_maps, iterator_types = {
        2: ([affine_map(2, [M, N])], [parallel, parallel]),
        4: ([affine_map(4, [M, N, mb, nb])], [parallel, parallel] * 2),
    }[inputs.type.rank]
    @linalg.generic([], [inputs], affine_maps, iterator_types)
    def relu_ed(a):
        return arith.MaximumFOp(a, zero)
    return relu_ed
def softmax(
    inputs: ir.Value, softmax_buf_or_softmax_buf_type: Union[ir.Value, ir.Type]
) -> ir.Value:
    softmax_buf = get_outputs(softmax_buf_or_softmax_buf_type)
    shape, elem_type = inputs.type.shape, inputs.type.element_type
    exp_out_uninit = tensor.EmptyOp(shape, elem_type)
    dims = [ir.AffineDimExpr.get(i) for i in range(inputs.type.rank)]
    par_affine_map = affine_map(inputs.type.rank, dims)
    par_affine_maps = [par_affine_map] * inputs.type.rank
    par_iter_types = [parallel] * inputs.type.rank
    red_affine_map = affine_map(
        inputs.type.rank, [dims[0], ir.AffineConstantExpr.get(0)]
    )
    red_iter_types = [parallel, reduction] * (inputs.type.rank // 2)
    @linalg.generic([inputs], [exp_out_uninit.result], par_affine_maps, par_iter_types)
    def exped(input, _output):
        return math.exp(input)
    zero = arith.constant(elem_type, 0.0)
    reduction_out_uninit = tensor.EmptyOp((shape[0], 1), elem_type)
    reduction_out = linalg.fill(zero, outs=reduction_out_uninit)
    @linalg.generic(
        [exped], [reduction_out], [par_affine_map, red_affine_map], red_iter_types
    )
    def summed_exped(exped_input, redex):
        return arith.AddFOp(exped_input, redex)
    bcast_out_uninit = tensor.EmptyOp(shape, elem_type)
    @linalg.generic(
        [summed_exped],
        [bcast_out_uninit.result],
        [red_affine_map, par_affine_map],
        par_iter_types,
    )
    def bcasted_summed_exped(input, _output):
        return input
    @linalg.generic(
        [exped, bcasted_summed_exped],
        [softmax_buf],
        [par_affine_map] * 3,
        par_iter_types,
    )
    def dived_bcasted_summed_exped(exped_input, normalizing_term, _output):
        return arith.DivFOp(exped_input, normalizing_term)
    return dived_bcasted_summed_exped

import numpy as np
import torch
from noether.data.preprocessors import PreProcessor
class NumpyToTorchTensorPreProcessor(PreProcessor):
    """Convert numpy arrays to PyTorch tensors."""
    def __init__(self, normalization_key: str):
        super().__init__(normalization_key=normalization_key)
    def __call__(self, x: np.ndarray) -> torch.Tensor:
        """Convert a numpy array to a PyTorch tensor."""
        if not isinstance(x, np.ndarray):
            raise TypeError("Input must be a numpy array.")
        return torch.from_numpy(x)
    def denormalize(self, x: torch.Tensor) -> np.ndarray:
        """Convert a PyTorch tensor back to a numpy array."""
        if not isinstance(x, torch.Tensor):
            raise TypeError("Input must be a torch.Tensor.")
        return x.detach().cpu().numpy()

from functools import partial
from typing import (
    Any,
    Callable,
    Iterable,
    List,
    Optional,
    Tuple,
    Type,
    TypeVar,
    Union,
    overload,
)
T = TypeVar("T")
Result = Iterable[Union[Any, Tuple[Any], Tuple[str, Any], Tuple[str, Any, Any]]]
RichReprResult = Result
class ReprError(Exception):
    """An error occurred when attempting to build a repr."""
@overload
def auto(cls: Optional[Type[T]]) -> Type[T]:
    ...
@overload
def auto(*, angular: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...
def auto(
    cls: Optional[Type[T]] = None, *, angular: Optional[bool] = None
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    """Class decorator to create __repr__ from __rich_repr__"""
    def do_replace(cls: Type[T], angular: Optional[bool] = None) -> Type[T]:
        def auto_repr(self: T) -> str:
            """Create repr string from __rich_repr__"""
            repr_str: List[str] = []
            append = repr_str.append
            angular: bool = getattr(self.__rich_repr__, "angular", False)  # type: ignore[attr-defined]
            for arg in self.__rich_repr__():  # type: ignore[attr-defined]
                if isinstance(arg, tuple):
                    if len(arg) == 1:
                        append(repr(arg[0]))
                    else:
                        key, value, *default = arg
                        if key is None:
                            append(repr(value))
                        else:
                            if default and default[0] == value:
                                continue
                            append(f"{key}={value!r}")
                else:
                    append(repr(arg))
            if angular:
                return f"<{self.__class__.__name__} {' '.join(repr_str)}>"
            else:
                return f"{self.__class__.__name__}({', '.join(repr_str)})"
        def auto_rich_repr(self: Type[T]) -> Result:
            """Auto generate __rich_rep__ from signature of __init__"""
            try:
                signature = inspect.signature(self.__init__)
                for name, param in signature.parameters.items():
                    if param.kind == param.POSITIONAL_ONLY:
                        yield getattr(self, name)
                    elif param.kind in (
                        param.POSITIONAL_OR_KEYWORD,
                        param.KEYWORD_ONLY,
                    ):
                        if param.default == param.empty:
                            yield getattr(self, param.name)
                        else:
                            yield param.name, getattr(self, param.name), param.default
            except Exception as error:
                raise ReprError(
                    f"Failed to auto generate __rich_repr__; {error}"
                ) from None
        if not hasattr(cls, "__rich_repr__"):
            auto_rich_repr.__doc__ = "Build a rich repr"
            cls.__rich_repr__ = auto_rich_repr  # type: ignore[attr-defined]
        auto_repr.__doc__ = "Return repr(self)"
        cls.__repr__ = auto_repr  # type: ignore[assignment]
        if angular is not None:
            cls.__rich_repr__.angular = angular  # type: ignore[attr-defined]
        return cls
    if cls is None:
        return partial(do_replace, angular=angular)
    else:
        return do_replace(cls, angular=angular)
@overload
def rich_repr(cls: Optional[Type[T]]) -> Type[T]:
    ...
@overload
def rich_repr(*, angular: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...
def rich_repr(
    cls: Optional[Type[T]] = None, *, angular: bool = False
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    if cls is None:
        return auto(angular=angular)
    else:
        return auto(cls)
if __name__ == "__main__":
    @auto
    class Foo:
        def __rich_repr__(self) -> Result:
            yield "foo"
            yield "bar", {"shopping": ["eggs", "ham", "pineapple"]}
            yield "buy", "hand sanitizer"
    foo = Foo()
    from pip._vendor.rich.console import Console
    console = Console()
    console.rule("Standard repr")
    console.print(foo)
    console.print(foo, width=60)
    console.print(foo, width=30)
    console.rule("Angular repr")
    Foo.__rich_repr__.angular = True  # type: ignore[attr-defined]
    console.print(foo)
    console.print(foo, width=60)
    console.print(foo, width=30)

