import os
from ucagent.tools.testops import RunUnityChipTest
import ucagent.util.functions as fc
from ucagent.checkers.base import Checker, UnityChipBatchTask
from typing import Tuple
from ucagent.util.log import info
from collections import OrderedDict
class UnityChipCheckerTestMockTestBatch(Checker):
    def __init__(self, target_file, test_file_prefix, test_prefix, test_dir="tests",
                 first_arg="",
                 last_arg="",
                 batch_size=1, 
                 min_file_tests=1, timeout=300, **kw):
        self.target_file = target_file
        self.test_file_prefix = test_file_prefix
        self.test_prefix = test_prefix
        self.test_dir = test_dir
        self.first_arg = first_arg
        self.last_arg = last_arg
        self.batch_size = batch_size
        self.min_file_tests = min_file_tests
        self.timeout = timeout
        self.run_test = RunUnityChipTest()
        self.batch_task = UnityChipBatchTask("mock_test_file", self)
        self.update_dut_name(kw["cfg"])
        assert "*" in target_file, "The target_file must contain a wildcard '*' to match multiple Mock files."
    def get_template_data(self):
        ret = self.batch_task.get_template_data(
            "TOTAL_MOCKS", "COMPLETED_MOCKS", "LIST_CURRENT_MOCKS"
        )
        return ret
    def on_init(self):
        self.batch_task.source_task_list = fc.find_files_by_pattern(
            self.workspace, self.target_file
        )
        self.batch_task.update_current_tbd()
        info(f"Found {len(self.batch_task.source_task_list)} mock component files to check.")
        return super().on_init()
    def set_workspace(self, workspace: str):
        """
        Set the workspace for the test case checker.
        :param workspace: The workspace directory to be set.
        """
        super().set_workspace(workspace)
        self.run_test.set_workspace(workspace)
        return self
    def do_check(self, timeout=0, is_complete=False, **kw) -> Tuple[bool, object]:
        """Check the Mock test implementation for correctness."""
        test_dir_full_path = self.get_path(self.test_dir)
        if not os.path.exists(test_dir_full_path):
            return False, {"error": f"test directory '{self.test_dir}' does not exist in workspace."}
        # Sync source task
        self.batch_task.source_task_list = fc.find_files_by_pattern(self.workspace, self.target_file)
        self.batch_task.update_current_tbd()
        if len(self.batch_task.source_task_list) == 0:
            return False, {
                "error": f"No mock component files found with pattern '{self.target_file}' in workspace."
            }
        # Do check in batch
        task_map = OrderedDict()
        no_test_files = []
        mock_file_prefix = os.path.basename(self.target_file).split("*")[0]
        for task_file in self.batch_task.source_task_list:
            # {OUT}/tests/{DUT}_mock_*.py => {OUT}/tests/test_{DUT}_mock_*.py
            dir_path = os.path.dirname(task_file)
            base_name = os.path.basename(task_file)
            mock_name = base_name.split(".py")[0].replace(mock_file_prefix, "")
            if not mock_name:
                return False, {
                    "error": f"Cannot extract MockComponentName from file '{task_file}'. Please ensure the file name is correct: `{mock_file_prefix}<MockComponentName>.py`"
                }
            test_file = dir_path + "/" + self.test_file_prefix + mock_name + "*.py"
            test_file_list = fc.find_files_by_pattern(self.workspace, test_file)
            if (not test_file_list) and (task_file in self.batch_task.tbd_task_list):
                no_test_files.append(f"{task_file} => {test_file} (not found)")
                continue
            task_map[task_file] = test_file_list
        if len(no_test_files) > 0:
            return False, {
                "error": "No corresponding test files found for some mock component files.",
                "details": no_test_files
            }
        pass_results = []
        fail_results = OrderedDict()
        for target_mock, target_tests in task_map.items():
            info(f"Checking mock component test file(s) for '{target_mock}': {', '.join(target_tests)}")
            ret, msg = self.do_one_check(target_tests, test_dir_full_path, timeout)
            if not ret:
                fail_results[target_mock] = msg
            else:
                pass_results.append(target_mock)
        note_msg = []
        # Complete
        self.batch_task.sync_gen_task(
            pass_results,
            note_msg,
            "Completed file changed."
        )
        if fail_results:
            return False, {
                "error": "Some mock component test files check failed.",
                "details": fail_results
            }
        return self.batch_task.do_complete(note_msg, is_complete, "", "", "")
    def do_one_check(self, test_files, test_dir_full_path, timeout) -> Tuple[bool, object]:
        if len(test_files) == 0:
            tfiles = ', '.join(self.target_file)
            return False, {"error": f"No test files found with pattern '{tfiles}' in workspace."}
        error_cases = []
        for tfile in test_files:
            if test_dir_full_path not in self.get_path(tfile):
                error_cases.append(f"The test file '{tfile}' is not under the test directory '{self.test_dir}'.")
                continue
            test_func_list = fc.get_target_from_file(self.get_path(tfile), f"test*",
                                                         ex_python_path=self.workspace,
                                                         dtype="FUNC")
            for test_func in test_func_list:
                if test_func.__name__.startswith(self.test_prefix) is False:
                    error_cases.append(f"The '{test_func.__name__}' test function's name must start with '{self.test_prefix}'.")
                    continue
                args = fc.get_func_arg_list(test_func)
                if self.first_arg and (len(args) < 1 or args[0] != self.first_arg):
                    error_cases.append(f"The '{test_func.__name__}' test function's first arg must be '{self.first_arg}', but got ({', '.join(args)}).")
                if self.last_arg and (len(args) < 1 or args[-1] != self.last_arg):
                    error_cases.append(f"The '{test_func.__name__}' test function's last arg must be '{self.last_arg}', but got ({', '.join(args)}).")
            if len(test_func_list) < self.min_file_tests:
                error_cases.append(f"Insufficient testcases: {len(test_func_list)} test functions found, minimum required is {self.min_file_tests} in file '{tfile}'. "+
                                    "Please ensure you have implemented enough test cases (need pytest function based not class based).")
        if len(error_cases) > 0:
            return False, {
                "error": "Check test functions failed.",
                "details": error_cases
            }
        # Run test
        timeout = timeout if timeout > 0 else self.timeout
        self.run_test.set_pre_call_back(
            lambda p: self.set_check_process(p, timeout + 10)  # Set the process for the checker
        )
        py_case_files = [fc.rm_workspace_prefix(test_dir_full_path,
                                                self.get_path(t)) for t in test_files]
        report, str_out, str_err = self.run_test.do(
            test_dir_full_path,
            pytest_ex_args=" ".join(py_case_files),
            return_stdout=True, return_stderr=True, return_all_checks=True,
            timeout=timeout
        )
        test_pass, test_msg = fc.is_run_report_pass(report, str_out, str_err)
        if not test_pass:
            return False, test_msg
        if not report or "tests" not in report:
            return False, {
                "error": f"Test execution failed or returned invalid report.",
                "STD_OUT": str_out,
                "STD_ERR": str_err,
            }
        tc_total = report["tests"]["total"]
        tc_failed = report["tests"]["fails"]
        if tc_failed > 0:
            return False, {
                "error": f"Test failed: {tc_failed}/{tc_total} test cases failed. Need all test cases to pass.",
                "STD_OUT": str_out,
                "STD_ERR": str_err,
            }
        ret, msg = fc.check_has_assert_in_tc(self.workspace, report)
        if not ret:
            return ret, msg
        return True, {"message": f"{self.__class__.__name__} check passed."}

import argparse
import asyncio
def parse_args():
    p = argparse.ArgumentParser(description="Control a Kasa-compatible smart bulb on the LAN (modern python-kasa API)")
    p.add_argument("--ip", required=True, help="IP address of the bulb on the LAN")
    p.add_argument("--on", action="store_true", help="Turn bulb on")
    p.add_argument("--off", action="store_true", help="Turn bulb off")
    p.add_argument("--brightness", type=int, help="Set brightness (0-100)")
    p.add_argument("--hsv", nargs=3, type=int, metavar=("H","S","V"), help="Set color as HSV integers: H(0-360) S(0-100) V(0-100)")
    p.add_argument("--transition", type=float, default=0, help="Transition duration in seconds (if supported)")
    return p.parse_args()
async def find_device(ip: str):
    try:
        from kasa import Discover
    except Exception:
        raise
    # discover_single returns a Device or None
    dev = await Discover.discover_single(ip)
    if dev is None:
        raise RuntimeError(f"Device at {ip} not found via discovery")
    return dev
async def main():
    args = parse_args()
    try:
        # Import lazily so users without python-kasa get a helpful message
        from kasa import Discover
    except Exception:
        print("Error importing python-kasa. Install with: pip install python-kasa")
        raise
    dev = await find_device(args.ip)
    # Connect/update device state
    try:
        await dev.update()
    except Exception:
        # Some devices require explicit connect
        try:
            await dev.connect()
            await dev.update()
        except Exception as e:
            print("Failed to connect/update device:", e)
            raise
    # Convenience access to light module (module keys may vary in capitalization)
    light_module = None
    for key in ("Light", "light", "light-1"):
        if key in getattr(dev, 'modules', {}):
            light_module = dev.modules[key]
            break
    # Fallback: try to find first module with 'Light' class name
    if light_module is None:
        for m in getattr(dev, 'modules', {}).values():
            # many modules have a 'MODULE' or class name; we try to find a candidate
            try:
                name = getattr(m, '__class__', type(m)).__name__
                if 'Light' in name or 'light' in name.lower():
                    light_module = m
                    break
            except Exception:
                continue
    # If device has high-level methods, use them as fallback
    async def turn_on():
        if hasattr(dev, 'turn_on'):
            await dev.turn_on()
        elif light_module and hasattr(light_module, 'turn_on'):
            await light_module.turn_on()
        else:
            raise RuntimeError("No turn_on method available for device")
    async def turn_off():
        if hasattr(dev, 'turn_off'):
            await dev.turn_off()
        elif light_module and hasattr(light_module, 'turn_off'):
            await light_module.turn_off()
        else:
            raise RuntimeError("No turn_off method available for device")
    async def set_brightness(b):
        if light_module and hasattr(light_module, 'set_brightness'):
            await light_module.set_brightness(b)
        elif 'set_light_state' in dir(dev):
            await dev.set_light_state(brightness=b)
        else:
            # try generic module method
            if light_module and hasattr(light_module, 'set_state'):
                await light_module.set_state(brightness=b)
            else:
                raise RuntimeError("No supported brightness API found on device")
    async def set_hsv(h, s, v):
        if light_module and hasattr(light_module, 'set_hsv'):
            await light_module.set_hsv(h, s, v)
        elif light_module and hasattr(light_module, 'set_rgb'):
            import colorsys
            r, g, b = colorsys.hsv_to_rgb(h/360.0, s/100.0, v/100.0)
            rgb = (int(r*255), int(g*255), int(b*255))
            await light_module.set_rgb(*rgb)
        elif hasattr(dev, 'set_light_state'):
            # try passing dict
            await dev.set_light_state(hue=h, saturation=s, brightness=v)
        else:
            raise RuntimeError("No supported color API found on device")
    # Execute requested actions
    if args.on:
        await turn_on()
        print(f"Turned on {args.ip}")
    if args.off:
        await turn_off()
        print(f"Turned off {args.ip}")
    if args.brightness is not None:
        b = max(0, min(100, args.brightness))
        try:
            await set_brightness(b)
            print(f"Set brightness to {b}%")
        except Exception as e:
            print("Failed to set brightness:", e)
    if args.hsv:
        h, s, v = args.hsv
        h = max(0, min(360, h))
        s = max(0, min(100, s))
        v = max(0, min(100, v))
        try:
            await set_hsv(h, s, v)
            print(f"Set color HSV=({h},{s},{v})")
        except Exception as e:
            print("Failed to set color:", e)
if __name__ == "__main__":
    asyncio.run(main())

from pydantic import BaseModel
from app.ai.tools.base import Tool
from app.ai.tools.metadata import ToolMetadata
from app.ai.tools.schemas import ClarifyInput, ClarifyOutput
from app.ai.tools.schemas.events import (
    ToolEvent,
    ToolStartEvent,
    ToolEndEvent,
)
class ClarifyTool(Tool):
    """Clarify tool - signals that the planner needs user clarification.
    The actual questions are output by the planner in assistant_message.
    This tool just marks analysis_complete=True to stop the loop and wait for user response.
    """
    @property
    def metadata(self) -> ToolMetadata:
        return ToolMetadata(
            name="clarify",
            description=(
                "ACTION: Signal that you need clarification from the user. "
                "Output your questions in assistant_message, then call this tool to pause and wait for response."
            ),
            category="action",
            version="1.0.0",
            input_schema=ClarifyInput.model_json_schema(),
            output_schema=ClarifyOutput.model_json_schema(),
            max_retries=1,
            timeout_seconds=10,
            idempotent=True,
            required_permissions=[],
            tags=["clarification", "questions", "user-interaction"],
            examples=[
                {
                    "input": {
                        "context": "User requested revenue analysis but didn't specify time period"
                    },
                    "description": "Signal need for clarification (questions go in assistant_message)"
                },
                {
                    "input": {},
                    "description": "Simple clarification signal with no context"
                }
            ]
        )
    @property
    def input_model(self) -> Type[BaseModel]:
        return ClarifyInput
    @property
    def output_model(self) -> Type[BaseModel]:
        return ClarifyOutput
    async def run_stream(self, tool_input: Dict[str, Any], runtime_ctx: Dict[str, Any]) -> AsyncIterator[ToolEvent]:
        data = ClarifyInput(**tool_input)
        yield ToolStartEvent(
            type="tool.start",
            payload={"context": data.context}
        )
        # Simple observation - just mark that we're waiting for user response
        # The actual questions are in the planner's assistant_message
        summary = "Waiting for user clarification"
        if data.context:
            summary = f"Waiting for user clarification: {data.context}"
        yield ToolEndEvent(
            type="tool.end",
            payload={
                "output": {
                    "status": "awaiting_response"
                },
                "observation": {
                    "summary": summary,
                    "artifacts": [],
                    "analysis_complete": True,
                    # No final_answer - the planner's assistant_message has the questions
                },
            }
        )

import base64
import json
from typing import Optional, Tuple, List
from urllib.parse import unquote, urlparse
class ConfigValidator:
    @staticmethod
    def is_base64(s: str) -> bool:
        try:
            s = s.rstrip('=')
            return bool(re.match(r'^[A-Za-z0-9+/\-_]*$', s))
        except:
            return False
    @staticmethod
    def decode_base64_url(s: str) -> Optional[bytes]:
        try:
            s = s.replace('-', '+').replace('_', '/')
            padding = 4 - (len(s) % 4)
            if padding != 4:
                s += '=' * padding
            return base64.b64decode(s)
        except:
            return None
    @staticmethod
    def decode_base64_text(text: str) -> Optional[str]:
        try:
            if ConfigValidator.is_base64(text):
                decoded = ConfigValidator.decode_base64_url(text)
                if decoded:
                    return decoded.decode('utf-8')
            return None
        except:
            return None
    @staticmethod
    def clean_vmess_config(config: str) -> str:
        if "vmess://" in config:
            base64_part = config[8:]
            base64_clean = re.split(r'[^A-Za-z0-9+/=_-]', base64_part)[0]
            return f"vmess://{base64_clean}"
        return config
    @staticmethod
    def normalize_hysteria2_protocol(config: str) -> str:
        if config.startswith('hy2://'):
            return config.replace('hy2://', 'hysteria2://', 1)
        return config
    @staticmethod
    def is_vmess_config(config: str) -> bool:
        try:
            if not config.startswith('vmess://'):
                return False
            base64_part = config[8:]
            decoded = ConfigValidator.decode_base64_url(base64_part)
            if decoded:
                json.loads(decoded)
                return True
            return False
        except:
            return False
    @staticmethod
    def is_tuic_config(config: str) -> bool:
        try:
            if config.startswith('tuic://'):
                parsed = urlparse(config)
                return bool(parsed.netloc and ':' in parsed.netloc)
            return False
        except:
            return False
    @staticmethod
    def convert_ssconf_to_https(url: str) -> str:
        if url.startswith('ssconf://'):
            return url.replace('ssconf://', 'https://', 1)
        return url
    @staticmethod
    def is_base64_config(config: str) -> Tuple[bool, str]:
        protocols = ['vmess://', 'vless://', 'ss://', 'tuic://']
        for protocol in protocols:
            if config.startswith(protocol):
                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                if (ConfigValidator.is_base64(decoded_url) or 
                    ConfigValidator.is_base64(base64_part)):
                    return True, protocol[:-3]
        return False, ''
    @staticmethod
    def check_base64_content(text: str) -> Optional[str]:
        try:
            decoded_text = ConfigValidator.decode_base64_text(text)
            if decoded_text:
                protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
                for protocol in protocols:
                    if protocol in decoded_text:
                        return decoded_text
            return None
        except:
            return None
    @staticmethod
    def split_configs(text: str) -> List[str]:
        configs = []
        lines = text.split('\n')

        for line in lines:
            line = line.strip()
            if not line:
                continue

            if ConfigValidator.is_base64(line):
                decoded_content = ConfigValidator.check_base64_content(line)
                if decoded_content:
                    text = decoded_content

            protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
            current_pos = 0
            text_length = len(text)

            while current_pos < text_length:
                next_config_start = text_length
                matching_protocol = None

                for protocol in protocols:
                    protocol_pos = text.find(protocol, current_pos)
                    if protocol_pos != -1 and protocol_pos < next_config_start:
                        next_config_start = protocol_pos
                        matching_protocol = protocol

                if matching_protocol:
                    if current_pos < next_config_start and configs:
                        current_config = text[current_pos:next_config_start].strip()
                        if ConfigValidator.is_valid_config(current_config):
                            configs.append(current_config)

                    current_pos = next_config_start
                    next_protocol_pos = text_length

                    for protocol in protocols:
                        pos = text.find(protocol, next_config_start + len(matching_protocol))
                        if pos != -1 and pos < next_protocol_pos:
                            next_protocol_pos = pos

                    current_config = text[next_config_start:next_protocol_pos].strip()
                    if matching_protocol == "vmess://":
                        current_config = ConfigValidator.clean_vmess_config(current_config)
                    elif matching_protocol == "hy2://":
                        current_config = ConfigValidator.normalize_hysteria2_protocol(current_config)
                    if ConfigValidator.is_valid_config(current_config):
                        configs.append(current_config)

                    current_pos = next_protocol_pos
                else:
                    break

        return configs
    @staticmethod
    def clean_config(config: str) -> str:
        config = re.sub(r'[\U0001F300-\U0001F9FF]', '', config)
        config = re.sub(r'[\x00-\x08\x0B-\x1F\x7F-\x9F]', '', config)
        config = re.sub(r'[^\S\r\n]+', ' ', config)
        config = config.strip()
        return config
    @staticmethod
    def is_valid_config(config: str) -> bool:
        if not config:
            return False

        protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
        return any(config.startswith(p) for p in protocols)
    @classmethod
    def validate_protocol_config(cls, config: str, protocol: str) -> bool:
        try:
            if protocol in ['vmess://', 'vless://', 'ss://', 'tuic://']:
                if protocol == 'vmess://':
                    return cls.is_vmess_config(config)
                if protocol == 'tuic://':
                    return cls.is_tuic_config(config)
                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                if cls.is_base64(decoded_url) or cls.is_base64(base64_part):
                    return True
                if cls.decode_base64_url(base64_part) or cls.decode_base64_url(decoded_url):
                    return True
            elif protocol in ['trojan://', 'hysteria2://', 'hy2://', 'wireguard://']:
                parsed = urlparse(config)
                return bool(parsed.netloc and '@' in parsed.netloc)
            elif protocol == 'ssconf://':
                return True
            return False
        except:
            return False

import json
import sys
class AbstractModel(object):
    """Base class for all models."""
    def _serialize(self, allow_none=False):
        """Get all params which are not None if None is not allowed."""
        def dfs(obj):
            if isinstance(obj, AbstractModel):
                d = vars(obj)
                ret = {}
                for k in d:
                    r = dfs(d[k])
                    if allow_none or r is not None:
                        ret[k[0].upper() + k[1:]] = r
                return ret
            elif isinstance(obj, list):
                return [dfs(o) for o in obj if allow_none or dfs(o) is not None]
            else:
                return obj.encode("UTF-8") if isinstance(obj, type(u"")) and sys.version_info[0] == 2 else obj
        return dfs(self)
    def _deserialize(self, params):
        return None
    def to_json_string(self, *args, **kwargs):
        """Serialize obj to a JSON formatted str, ensure_ascii is False by default"""
        if "ensure_ascii" not in kwargs:
            kwargs["ensure_ascii"] = False
        return json.dumps(self._serialize(allow_none=True), *args, **kwargs)
    def from_json_string(self, jsonStr):
        """Deserialize a JSON formatted str to a Python object"""
        params = json.loads(jsonStr)
        self._deserialize(params)
    def __repr__(self):
        return "%s" % self.to_json_string()

