import torch
import numpy as np

from neuralogic.core.builder import Sample, Weight, Neuron
from neuralogic.core.settings import SettingsProxy
from neuralogic.core.enums import Initializer, Backend
from neuralogic.nn.base import AbstractNeuraLogic


def longtail(tensor: torch.Tensor, _: SettingsProxy):
    """
    Long-tail distribution initializer.
    Generates values following a specific power-law distribution.
    """
    init = np.random.rand(*tensor.size())
    x0, x1, power = 0.0, 10.0, 50.0
    x0_power = np.power(x0, power + 1)

    # Compute the transformed distribution
    init = x1 - np.power((np.power(x1, power + 1) - x0_power) * init + x0_power, 1 / (power + 1))
    tensor.fill_(init)


class NeuraLogic(AbstractNeuraLogic):
    # Define supported activation functions
    activations = {
        "Sigmoid": torch.sigmoid,
        "Average": torch.mean,
        "Maximum": torch.max,
        "ReLu": torch.relu,
        "Tanh": torch.tanh,
    }

    # Define supported weight initializers
    initializers = {
        Initializer.NORMAL: lambda tensor, _: torch.nn.init.normal_(tensor),
        Initializer.UNIFORM: lambda tensor, settings: torch.nn.init.uniform_(
            tensor, -settings.initializer_uniform_scale / 2, settings.initializer_uniform_scale / 2
        ),
        Initializer.CONSTANT: lambda tensor, settings: torch.nn.init.constant_(tensor, settings.initializer_const),
        Initializer.LONGTAIL: longtail,
        # TODO: GLOROT and HE
    }

    def __init__(self, model: List[Weight], template, settings: Optional[SettingsProxy] = None):
        super().__init__(Backend.TORCH, template, settings)
        self.model: Optional[torch.nn.ParameterList] = None
        self.weights_meta = model
        self.weights: List[torch.nn.Parameter] = []
        self.reset_parameters()

    def reset_parameters(self):
        initializer = Initializer[str(self.settings.initializer)]
        if initializer not in NeuraLogic.initializers:
            raise NotImplementedError

        weight_initializer = NeuraLogic.initializers[initializer]

        for weight in self.weights_meta:
            if weight.fixed:
                parameter = torch.nn.Parameter(
                    torch.tensor(weight.value, dtype=torch.float64), requires_grad=False
                )
            else:
                parameter = torch.nn.Parameter(
                    torch.empty(size=weight.dimensions, requires_grad=True, dtype=torch.float64)
                )
                weight_initializer(parameter.data, self.settings)

            self.weights.append(parameter)

        self.model = torch.nn.ParameterList(self.weights)

    def build_sample(self, sample: Sample):
        self.hooks_set = len(self.hooks) != 0

        torch_neurons: List[Optional[torch.Tensor]] = [None] * len(sample.neurons)

        for neuron in sample.neurons:
            torch_neurons[neuron.index] = self.to_torch_expression(neuron, torch_neurons, self.model)

        return torch_neurons[sample.neurons[-1].index]

    def __call__(self, sample: Sample):
        return self.build_sample(sample)

    def state_dict(self) -> Dict:
        weights = {}
        for meta, weight in zip(self.weights_meta, self.weights):
            if not meta.fixed and meta.index >= 0:
                weights[meta.index] = weight if isinstance(weight, (int, float)) else weight.data
        return {"weights": weights}

    def load_state_dict(self, state_dict: Dict):
        weight_dict = state_dict["weights"]
        for i, (meta, weight) in enumerate(zip(self.weights_meta, self.weights)):
            if meta.index < 0 or meta.fixed:
                continue

            if isinstance(weight, (int, float)):
                weight.data = torch.tensor([weight_dict[meta.index]], dtype=torch.float64)
            else:
                weight.data = torch.tensor(weight_dict[meta.index], dtype=torch.float64)

    @staticmethod
    def to_tensor_value(value) -> torch.Tensor:
        if isinstance(value, (float, int)):
            return torch.tensor([value], requires_grad=False, dtype=torch.float64)
        return torch.tensor(value, requires_grad=False, dtype=torch.float64)

    def to_torch_expression(
        self, neuron: Neuron, neurons: List[torch.Tensor], weights: torch.nn.ParameterList
    ) -> torch.Tensor:
        if neuron.inputs:
            out = self.process_neuron_inputs(neuron, neurons, weights)

            if neuron.activation:
                if not neuron.pooling:
                    out = sum(out)
                else:
                    out = torch.stack(out)

                if neuron.activation != "Identity":
                    out = NeuraLogic.activations[neuron.activation](out)
            else:
                out = sum(out)
        else:
            out = NeuraLogic.to_tensor_value(neuron.value)

            if neuron.activation and neuron.activation != "Identity":
                out = NeuraLogic.activations[neuron.activation](out)

        if self.hooks_set and neuron.hook_name is not None and neuron.hook_name in self.hooks:
            self.run_hook(neuron.hook_name, out.value())

        return out

    def process_neuron_inputs(
        self, neuron: Neuron, neurons: List[torch.Tensor], weights: torch.nn.ParameterList
    ) -> List[torch.Tensor]:
        out = []

        if neuron.weights:
            for w, i in zip(neuron.weights, neuron.inputs):
                neuron = neurons[i]
                weight = weights[w]

                neuron_size = neuron.size()
                weight_size = weight.size()

                if not neuron_size or not weight_size or neuron_size == (1,) or weight_size == (1,):
                    out.append(torch.multiply(weight, neuron))
                else:
                    out.append(torch.matmul(weight, neuron))
        else:
            for i in neuron.inputs:
                out.append(neurons[i])

        return out

# FileTask module for scanning and sorting image files
from os import walk
from pathlib import Path
from time import time
from typing import Dict, List, Iterable, TypeVar, Callable, Union, Any
import numpy as np
from PySide2.QtCore import QThread

# Import custom modules
from vicarutil.image.core import read_beg_labels, Labels
from ..concurrent import typedsignal, signal
from ..ui import Progress
from ...logging import handle_exception

_T = TypeVar('_T')


class FileType(Enum):
    IMAGE = "IMG"
    LABEL = "LBL"


class SortType(Enum):
    FILT = 'filter'
    SEQ = 'sequence'
    EXP = 'exposure'
    OTHER = "--"

    @staticmethod
    def reverse(value: Any):
        if isinstance(value, str):
            if not hasattr(SortType, 'reversed_map'):
                SortType.reversed_map = {e.value: e for e in SortType}
            try:
                return SortType.reversed_map[value]
            except KeyError:
                return SortType.OTHER
        return value


def _safe_file_iter(o: Iterable[_T]) -> Iterable[_T]:
    try:
        yield from o
    except PermissionError:
        yield from o


def labels_from_image(p: Path) -> Labels:
    with open(p, 'rb') as f:
        return read_beg_labels(f)


def sequence_from_image(p: Path) -> str:
    try:
        labels = labels_from_image(p)
        return f"Sequence {labels['IDENTIFICATION']['SEQUENCE_ID']}"
    except KeyError:
        return "Not Found"


def default(*_, **__) -> str:
    return "Files"


def filter_from_image(p: Path) -> str:
    try:
        clear = {"CL1", "CL"}
        labels = labels_from_image(p)
        filters = [str(o).strip() for o in labels['INSTRUMENT']['FILTER_NAME']]
        if len(filters) == 0:
            return "Other"
        elif np.alltrue([filt in clear for filt in filters]):
            return "Clear"
        else:
            return ','.join(filters)
    except KeyError:
        return "Not Found"


def exposure_from_image(p: Path) -> str:
    try:
        labels = labels_from_image(p)
        exposure = int(labels['INSTRUMENT']['EXPOSURE_DURATION']) // 1000
        return f"{exposure - exposure % 10:d}"
    except KeyError:
        return "Not Found"


class FileTask(QThread):
    started = signal()
    set_count = typedsignal(int)
    update_count = typedsignal(int)
    finished = typedsignal(dict)

    def __init__(
            self,
            base_path: str,
            done_callback: Callable[[dict], None],
            sort_by: Union[str, SortType] = None
    ):
        super(FileTask, self).__init__()
        self.base = Path(base_path)
        self._start = 0
        self.sort_by = SortType.reverse(sort_by)

        # Setup callbacks
        _quit = self.quit

        def done(d: Dict):
            done_callback(d)
            Progress.stop()
            _quit()

        self.started.connect(Progress.start())
        self.finished.connect(done)
        self.set_count.connect(lambda i: Progress.max(i))
        self.update_count.connect(lambda i: Progress.value(i))

    def abort(self):
        self.finished.emit(dict())

    def check_time(self):
        current = time()
        if current - self._start > 30:
            raise TimeoutError()

    def scan_dirs(self, path: Path) -> List[Path]:
        out = list()
        self.check_time()
        out.append(path)
        for f in _safe_file_iter(path.iterdir()):
            if f.is_dir():
                out.extend(self.scan_dirs(f))
        return out

    def run(self) -> None:
        try:
            self._start = time()
            self.started.emit()

            if self.base.is_dir():
                dirs = self.scan_dirs(self.base)
                self.set_count.emit(len(dirs))

                out = dict()
                total: int = np.sum([len(files) for _, _, files in walk(self.base, followlinks=False)])
                self.set_count.emit(total)

                cnt = 0
                self.update_count.emit(cnt)

                # Select sorting function based on criteria
                if self.sort_by == SortType.SEQ:
                    func = sequence_from_image
                elif self.sort_by == SortType.FILT:
                    func = filter_from_image
                elif self.sort_by == SortType.EXP:
                    func = exposure_from_image
                else:
                    func = default

                # Process each directory and file
                for d, _, files in walk(self.base, followlinks=False):
                    p = Path(d)
                    for f in files:
                        if f.endswith(FileType.IMAGE.value):
                            try:
                                fp = p.joinpath(f)
                                seq = func(fp)
                                if seq not in out:
                                    out[seq] = list()
                                out[seq].append(fp)
                            except Exception as e:
                                handle_exception(e)
                        cnt += 1
                        self.update_count.emit(cnt)

                self.finished.emit(out)
            else:
                self.finished.emit(dict())

            self.quit()

        except TimeoutError:
            self.finished.emit(dict())
            self.quit()


__all__ = ['FileTask', 'FileType', 'SortType']

import pytest
from ethereum.abi import ValueOutOfBounds

# Token constants
TOKEN_NAME = "Vipercoin"
TOKEN_SYMBOL = "FANG"
TOKEN_DECIMALS = 18
TOKEN_INITIAL_SUPPLY = (21 * 10 ** 6)
TOKEN_TOTAL_SUPPLY = TOKEN_INITIAL_SUPPLY * (10 ** TOKEN_DECIMALS)

@pytest.fixture
def erc20(get_contract):
    # Load ERC20 contract code from file
    erc20_code = open('examples/tokens/vipercoin.v.py').read()
    return get_contract(erc20_code, args=[TOKEN_NAME, TOKEN_SYMBOL, TOKEN_DECIMALS, TOKEN_INITIAL_SUPPLY])

@pytest.fixture
def erc20_caller(erc20, get_contract):
    # Contract that calls ERC20 functions
    erc20_caller_code = """
token_address: address(ERC20)
@public
def __init__(token_addr: address):
    self.token_address = token_addr

@public
def symbol() -> bytes32:
    return self.token_address.symbol()

@public
def balanceOf(_owner: address) -> num256:
    return self.token_address.balanceOf(_owner)

@public
def totalSupply() -> num256:
    return self.token_address.totalSupply()

@public
def transfer(_to: address, _value: num256) -> bool:
    return self.token_address.transfer(_to, _value)

@public
def transferFrom(_from: address, _to: address, _value: num(num256)) -> bool:
    return self.token_address.transferFrom(_from, _to, _value)

@public
def allowance(_owner: address, _spender: address) -> num256:
    return self.token_address.allowance(_owner, _spender)
    """
    return get_contract(erc20_caller_code, args=[erc20.address])

def pad_bytes32(instr):
    """ Pad a string with \x00 bytes to return correct bytes32 representation. """
    bstr = instr.encode()
    return bstr + (32 - len(bstr)) * b'\x00'

def test_initial_state(t, erc20_caller):
    # Verify initial state of the contract
    assert erc20_caller.totalSupply() == TOKEN_TOTAL_SUPPLY == erc20_caller.balanceOf(t.a0)
    assert erc20_caller.balanceOf(t.a1) == 0
    assert erc20_caller.symbol() == pad_bytes32(TOKEN_SYMBOL)

def test_call_transfer(t, chain, erc20, erc20_caller, assert_tx_failed):

    # Basic transfer.
    erc20.transfer(erc20_caller.address, 10)
    assert erc20.balanceOf(erc20_caller.address) == 10

    erc20_caller.transfer(t.a1, 10)
    assert erc20.balanceOf(erc20_caller.address) == 0
    assert erc20.balanceOf(t.a1) == 10

    # Transfer more than allowed
    assert_tx_failed(lambda: erc20_caller.transfer(t.a1, TOKEN_TOTAL_SUPPLY))

    t.s = chain

    # Negative transfer value should fail
    assert_tx_failed(
        function_to_test=lambda: erc20_caller.transfer(t.a1, -1),
        exception=ValueOutOfBounds
    )

def test_caller_approve_allowance(t, erc20, erc20_caller):
    # Check initial allowance
    assert erc20_caller.allowance(erc20.address, erc20_caller.address) == 0

    # Approve and check updated allowance
    assert erc20.approve(erc20_caller.address, 10) == True
    assert erc20_caller.allowance(t.a0, erc20_caller.address) == 10

def test_caller_tranfer_from(t, erc20, erc20_caller, assert_tx_failed):
    # Cannot transfer tokens that are unavailable
    assert_tx_failed(lambda: erc20_caller.transferFrom(t.a0, erc20_caller.address, 10))
    assert erc20.balanceOf(erc20_caller.address) == 0

    # Approve and perform transfers
    assert erc20.approve(erc20_caller.address, 10) == True
    erc20_caller.transferFrom(t.a0, erc20_caller.address, 5)
    assert erc20.balanceOf(erc20_caller.address) == 5
    assert erc20_caller.allowance(t.a0, erc20_caller.address) == 5

    erc20_caller.transferFrom(t.a0, erc20_caller.address, 3)
    assert erc20.balanceOf(erc20_caller.address) == 8
    assert erc20_caller.allowance(t.a0, erc20_caller.address) == 2

