from typing import Any, Union
from fastapi import HTTPException, status
from passlib.context import CryptContext
from .client import get_client_id
from .repository import get_repository, DataCollection
from .settings import Settings
from ..api.v1.models import BaseResponse, AuthenticationCredential

__all__ = [
    "AuthenticationContext",
    "get_auth_credential",
    "set_auth_credential",
    "update_auth_credential",
]


class AuthenticationContext:
    """
    An Authentication context object wrapper
    encapsulating the crypto context used to verify credentials
    """

    def __init__(self, settings: Settings = Settings()):
        # Initialize bcrypt password hashing context
        self.context = CryptContext(schemes=["bcrypt"], deprecated="auto")
        self.settings = settings

    def authenticate_credential(self, username: str, password: str) -> Any:
        # Retrieve credential and verify password
        credential = get_auth_credential(username, self.settings)
        return self.verify_password(password, credential.hashed_password)

    def verify_password(self, plain_password: str, hashed_password: str) -> Any:
        # Verify plain password against hashed password
        return self.context.verify(plain_password, hashed_password)

    def get_password_hash(self, password: Union[bytes, str]) -> Any:
        # Generate hash for given password
        return self.context.hash(password)


def get_auth_credential(
    username: str, settings: Settings = Settings()
) -> AuthenticationCredential:
    """Get an authentication credential from the repository."""
    try:
        with get_repository(
            get_client_id(), DataCollection.AUTHENTICATION, settings
        ) as repository:
            query_result = repository.get({"username": username})

            if not query_result:
                raise HTTPException(
                    status_code=status.HTTP_404_NOT_FOUND,
                    detail=f"Could not find credential for {username}",
                )

            return AuthenticationCredential(**query_result)

    except Exception as error:
        print(sys.exc_info())
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"{username} not found",
        ) from error


def set_auth_credential(
    credential: AuthenticationCredential, settings: Settings = Settings()
) -> None:
    """Set an authentication credential in the repository."""
    try:
        with get_repository(
            get_client_id(), DataCollection.AUTHENTICATION, settings
        ) as repository:
            query_result = repository.get({"username": credential.username})

            if not query_result:
                repository.set(credential.dict())
            else:
                raise HTTPException(
                    status_code=status.HTTP_409_CONFLICT,
                    detail=f"Already exists {credential.username}",
                )

    except Exception as error:
        print(sys.exc_info())
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="set auth credential failed",
        ) from error


def update_auth_credential(
    credential: AuthenticationCredential, settings: Settings = Settings()
) -> BaseResponse:
    """Update an authentication credential in the repository."""
    try:
        with get_repository(
            get_client_id(), DataCollection.AUTHENTICATION, settings
        ) as repository:
            query_result = repository.get({"username": credential.username})

            if not query_result:
                raise HTTPException(
                    status_code=status.HTTP_404_NOT_FOUND,
                    detail=f"Could not find credential {credential.username}",
                )

            repository.update({"username": credential.username}, credential.dict())
            return BaseResponse()

    except Exception as error:
        print(sys.exc_info())
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="update auth credential failed",
        ) from error

# Import necessary modules and types
from typing import TYPE_CHECKING, List, Iterable, Set, Sequence
from collections import OrderedDict

# Import DXF-specific utilities
from ezdxf.lldxf.types import dxftag, uniform_appid
from ezdxf.lldxf.tags import Tags
from ezdxf.lldxf.const import DXFKeyError, DXFStructureError
from ezdxf.lldxf.const import ACAD_REACTORS, REACTOR_HANDLE_CODE, APP_DATA_MARKER

# Type checking imports (only for static analysis)
if TYPE_CHECKING:
    from ezdxf.lldxf.tagwriter import TagWriter

# Exported classes
__all__ = ['AppData', 'Reactors']

# Error message templates
ERR_INVALID_DXF_ATTRIB = 'Invalid DXF attribute for entity {}'
ERR_DXF_ATTRIB_NOT_EXITS = 'DXF attribute {} does not exist'


class AppData:
    """Manages application-specific data associated with DXF entities."""

    def __init__(self):
        # Store app data in an ordered dictionary
        self.data = OrderedDict()

    def __contains__(self, appid: str) -> bool:
        """Check if appid exists in stored data."""
        return uniform_appid(appid) in self.data

    def __len__(self) -> int:
        """Return number of registered application data entries."""
        return len(self.data)

    def get(self, appid: str) -> Tags:
        """Retrieve tags for given appid, raise KeyError if not found."""
        try:
            return self.data[uniform_appid(appid)]
        except KeyError:
            raise DXFKeyError(appid)

    def set(self, tags: Tags) -> None:
        """Set/replace app data using provided tags."""
        if len(tags):
            appid = tags[0].value
            self.data[appid] = tags

    def add(self, appid: str, data: Iterable[Sequence]) -> None:
        """Add new application data for specified appid."""
        # Convert input data to DXF tags
        data = Tags(dxftag(code, value) for code, value in data)
        appid = uniform_appid(appid)

        # Ensure proper DXF structure with start/end markers
        if data[0] != (APP_DATA_MARKER, appid):
            data.insert(0, dxftag(APP_DATA_MARKER, appid))
        if data[-1] != (APP_DATA_MARKER, '}'):
            data.append(dxftag(APP_DATA_MARKER, '}'))

        self.set(data)

    def discard(self, appid: str):
        """Remove app data for given appid if it exists."""
        _appid = uniform_appid(appid)
        if _appid in self.data:
            del self.data[_appid]

    def export_dxf(self, tagwriter: 'TagWriter') -> None:
        """Export all app data as DXF tags."""
        for data in self.data.values():
            tagwriter.write_tags(data)


class Reactors:
    """
    Handle storage for related reactors.
    Reactors are other objects related to the object that contains this
    Reactor() instance.
    """

    def __init__(self, handles: Iterable[str] = None):
        # Initialize reactor handle storage
        self.reactors: Set[str] = None  # stores handles as strings
        self.set(handles)

    def __len__(self) -> int:
        """Return number of reactor handles."""
        return len(self.reactors)

    def __contains__(self, handle):
        """Check if a reactor handle is present."""
        return handle in self.reactors

    def __iter__(self):
        """Iterate over reactor handles in sorted order."""
        return iter(self.get())

    @classmethod
    def from_tags(cls, tags: Tags = None) -> 'Reactors':
        """
        Create Reactors() instance from DXF tags.
        Expected DXF structure: [(102, '{ACAD_REACTORS'), (330, handle), ..., (102, '}')]
        Args:
            tags: list of DXFTags()
        """
        if tags is None:
            return cls(None)

        # Validate minimum tag count
        if len(tags) < 2:  # no reactors are valid
            raise DXFStructureError("ACAD_REACTORS error")

        # Extract handles between markers
        return cls((handle.value for handle in tags[1:-1]))

    def get(self) -> List[str]:
        """Return sorted list of reactor handles (hexadecimal sort)."""
        return sorted(self.reactors, key=lambda x: int(x, base=16))

    def set(self, handles: Iterable[str]) -> None:
        """Set reactor handles from iterable."""
        self.reactors = set(handles or [])

    def add(self, handle: str) -> None:
        """Add a reactor handle."""
        self.reactors.add(handle)

    def discard(self, handle: str):
        """Remove a reactor handle if present."""
        self.reactors.discard(handle)

    def export_dxf(self, tagwriter: 'TagWriter') -> None:
        """Export reactors as DXF tags."""
        tagwriter.write_tag2(APP_DATA_MARKER, ACAD_REACTORS)
        for handle in self.get():
            tagwriter.write_tag2(REACTOR_HANDLE_CODE, handle)
        tagwriter.write_tag2(APP_DATA_MARKER, '}')

# RuuviTag configuration flow for Home Assistant
from typing import Any, Dict, Optional
from .const import DOMAIN
import voluptuous as vol
from .sensor import (
    CONF_MAC,
    CONF_NAME,
    CONF_SENSORS,
    SENSOR_TYPES,
    CONF_MONITORED_CONDITIONS
)
import homeassistant.helpers.config_validation as cv

# Schema for adding a new RuuviTag sensor
CONFIG_FLOW_RUUVI_ADD_SCHEMA = vol.Schema(
    {
        vol.Required(CONF_MAC): cv.string,
        vol.Optional(CONF_NAME): cv.string
    }
)

# Build dynamic config schema based on available sensor types
config_schema = {}
for condition in SENSOR_TYPES.keys():
  config_schema[vol.Optional(condition)] = cv.boolean

CONFIG_FLOW_RUUVI_CONFIG_SCHEMA = vol.Schema(config_schema)

# Schema for asking if user wants to add another sensor
ADD_ANOTHER_SCHEMA = vol.Schema(
    {
        vol.Optional("add_another"): cv.boolean
    }
)


class RuuviConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):
    # Class-level data storage
    data = {
        CONF_SENSORS: []
    }
    previous_step_data = {}

    async def async_step_user(self, user_input=None):
        """Invoked when a user initiates a flow via the user interface."""
        return await self.async_step_add_sensor()

    async def async_step_add_sensor(self, user_input: Optional[Dict[str, Any]] = None):
        errors: Dict[str, str] = {}

        if user_input is not None:
            # VALIDATE HERE
            if not errors:
                self.previous_step_data = {
                    CONF_MAC: user_input[CONF_MAC],
                    CONF_NAME: user_input.get(CONF_NAME, None),
                }
                return await self.async_step_config_sensor()

        return self.async_show_form(
            step_id="add_sensor",
            data_schema=CONFIG_FLOW_RUUVI_ADD_SCHEMA,
            errors=errors
        )

    async def async_step_config_sensor(self, user_input: Optional[Dict[str, Any]] = None):
        """Second step in config flow to configure sensor conditions."""
        errors: Dict[str, str] = {}

        if user_input is not None:
            # VALIDATE HERE
            if not errors:
                # Input is valid, set data.
                self.data[CONF_SENSORS].append(
                    {
                        CONF_MAC: self.previous_step_data[CONF_MAC],
                        CONF_NAME: self.previous_step_data[CONF_NAME],
                        CONF_MONITORED_CONDITIONS: [
                            x for x in SENSOR_TYPES.keys() 
                            if user_input.get(x, False)
                        ]
                    }
                )
                return await self.async_step_add_another()

        return self.async_show_form(
            step_id="config_sensor",
            data_schema=CONFIG_FLOW_RUUVI_CONFIG_SCHEMA,
            errors=errors
        )

    async def async_step_add_another(self, user_input: Optional[Dict[str, Any]] = None):
        errors: Dict[str, str] = {}

        if user_input is not None:
            # VALIDATE HERE
            if not errors:
                # If user ticked the box show this form again so they can add an
                # additional sensor.
                if user_input.get("add_another", False):
                    return await self.async_step_add_sensor()

                # User is done adding sensors, create the config entry.
                return self.async_create_entry(
                    title="Ruuvi Sensors",
                    data=self.data
                )

        return self.async_show_form(
            step_id="add_another",
            data_schema=ADD_ANOTHER_SCHEMA,
            errors=errors
        )

# Import necessary modules
from __future__ import absolute_import, print_function, unicode_literals
from builtins import range

# Import from Framework
from _Framework.ChannelStripComponent import ChannelStripComponent


class SelectChanStripComponent(ChannelStripComponent):
    u""" Subclass of channel strip component that selects tracks that it arms """

    def __init__(self):
        # Initialize parent class
        ChannelStripComponent.__init__(self)

    def _arm_value(self, value):
        # Ensure arm button is assigned and value is valid
        assert self._arm_button != None
        assert value in range(128)

        if self.is_enabled():
            # Check if track was previously armed
            track_was_armed = False
            if self._track != None and self._track.can_be_armed:
                track_was_armed = self._track.arm

            # Call parent implementation
            ChannelStripComponent._arm_value(self, value)

            # If track is now armed and wasn't before, select it
            if self._track != None and self._track.can_be_armed:
                if self._track.arm and not track_was_armed:
                    if self._track.view.select_instrument():
                        self.song().view.selected_track = self._track

import html
