        recipe_parser = sub_tasks.add_parser('recipe', help='transform using custom recipe')
        recipe_parser.set_defaults(recipe_handler=TaskTransform.load_recipe)

        recipe_mutex = recipe_parser.add_mutually_exclusive_group(required=True)
        recipe_mutex.add_argument('--from-file', metavar='<filename>', type=existing_file_type,
                                  help='load recipe from YAML file')
        recipe_mutex.add_argument('--from-json', metavar='<json>',
                                  help='load recipe from JSON-formatted string')

        for sub_task in (rename_parser, copy_parser):
            sub_task.add_argument('tag', metavar='<tag>', type=TagOptions.tag,
                                  help='tag for selecting items to transform. Available tags: '
                                       f'{TagOptions.options()}. Special tag "{CATALOG_TAG_ALL}" selects all items.')

            mutex = sub_task.add_mutually_exclusive_group()
            mutex.add_argument('--regex', metavar='<regex>', type=regex_type,
                               help='regular expression selecting item names to transform')
            mutex.add_argument('--not-regex', metavar='<regex>', type=regex_type,
                               help='regular expression selecting item names NOT to transform')

            sub_task.add_argument('name_regex', metavar='<name-regex>', type=ext_template_type,
                                  help='name-regex used to transform an existing item name. Variable {name} is '
                                       'replaced with the original template name. Sections of the original template '
                                       'name can be selected using the {name <regex>} format. Where <regex> is a '
                                       'regular expression that must contain at least one capturing group. Capturing '
                                       'groups identify sections of the original name to keep.')

        for sub_task in (rename_parser, copy_parser, recipe_parser):
            sub_task.add_argument('output', metavar='<output-directory>', type=filename_type,
                                  help='directory to save transform result')

            sub_task.add_argument('--no-rollover', action='store_true',
                                  help='by default, if the output directory already exists it is renamed using a '
                                       'rolling naming scheme. This option disables this automatic rollover.')

            sub_task.add_argument('--workdir', metavar='<directory>', type=existing_workdir_type,
                                  help='transform will read from the specified directory instead of target vManage')

        return task_parser.parse_args(task_args)

    @staticmethod
    def is_api_required(parsed_args) -> bool:
        return parsed_args.workdir is None

    @staticmethod
    def _recipe_dict(parsed_args, replace_source: bool) -> dict:
        recipe_dict = {
            'tag': parsed_args.tag,
            'name_template': {
                'name_regex': parsed_args.name_regex
            },
            'replace_source': replace_source
        }

        if parsed_args.regex:
            recipe_dict['name_template']['regex'] = parsed_args.regex
        elif parsed_args.not_regex:
            recipe_dict['name_template']['not_regex'] = parsed_args.not_regex

        return recipe_dict

    @classmethod
    def rename_recipe(cls, parsed_args) -> TransformRecipe:
        return TransformRecipe(**cls._recipe_dict(parsed_args, replace_source=True))

    @classmethod
    def copy_recipe(cls, parsed_args) -> TransformRecipe:
        return TransformRecipe(**cls._recipe_dict(parsed_args, replace_source=False))

    @staticmethod
    def load_recipe(parsed_args) -> TransformRecipe:
        if parsed_args.from_file:
            return TransformRecipe.parse_yaml(parsed_args.from_file)
        else:
            return TransformRecipe.parse_raw(parsed_args.from_json)

    def runner(self, parsed_args, api: Optional[Rest] = None) -> Union[None, list]:
        source_info = f'Local workdir: "{parsed_args.workdir}"' if api is None else f'vManage URL: "{api.base_url}"'
        self.log_info(f'Transform task: {source_info} -> Local output dir: "{parsed_args.output}"')

        # Load processors
        try:
            recipe = parsed_args.recipe_handler(parsed_args)
            default_processor = Processor(name='default', recipe=recipe)
            loaded_processors = {
                DeviceTemplateAttached: AttachedProcessor(name='attached devices processor', recipe=recipe),
                DeviceTemplateValues: ValuesProcessor(name='values processor', recipe=recipe)
            }
        except (ValidationError, RecipeException) as ex:
            raise TaskException(f'Error loading transform recipe: {ex}') from None

        # Output directory must be empty for a new transform
        saved_output = clean_dir(parsed_args.output, max_saved=0 if parsed_args.no_rollover else 99)
        if saved_output:
            self.log_info(f'Previous output under "{parsed_args.output}" was saved as "{saved_output}"')

        # Identify backend and server version
        if api is None:
            backend = parsed_args.workdir
            local_info = ServerInfo.load(backend)
            server_version = local_info.server_version if local_info is not None else None
        else:
            backend = api
            server_version = backend.server_version

        if server_version is not None:
            if ServerInfo(server_version=server_version).save(parsed_args.output):
                self.log_info('Saved vManage server information')

        # Process items
        id_mapping: Dict[str, str] = {}  # {<old_id>: <new_id>}
        try:
            for tag in ordered_tags(CATALOG_TAG_ALL, reverse=True):
                self.log_info(f'Inspecting {tag} items')
                for _, info, index_cls, item_cls in catalog_iter(tag, version=server_version):
                    item_index = self.index_get(index_cls, backend)
                    if item_index is None:
                        self.log_debug(f'Skipped {info}, none found')
                        continue

                    processor = loaded_processors.get(item_cls, default_processor)
                    name_set = {item_name for item_id, item_name in item_index}
                    is_bad_name = False
                    export_list = []
                    id_hint_map = {item_name: item_id for item_id, item_name in item_index}

                    for item_id, item_name in item_index:
                        item = self.retrieve(item_cls, backend, item_id, item_name, item_index.need_extended_name)
                        if item is None:
                            self.log_error(f'Failed loading {info} {item_name}')
                            continue

                        self.log_debug(f'Evaluating {info} {item_name} with {processor.name} processor')

                        with suppress(StopProcessorException):
                            new_name = processor.match(item_name, tag)
                            if new_name is None:
                                raise StopProcessorException()

                            self.log_info(f'Matched {info} {item_name}')

                            if not item_cls.is_name_valid(new_name):
                                self.log_error(f'New {info} name is not valid: {new_name}')
                                is_bad_name = True
                                raise StopProcessorException()

                            if new_name in name_set:
                                self.log_error(f'New {info} name already exists: {new_name}')
                                is_bad_name = True
                                raise StopProcessorException()

                            new_id = item_id if processor.replace_source else str(uuid4())
                            new_payload = self.processor_eval(processor, item, new_name, new_id)
                            new_item = item_cls(update_ids(id_mapping, new_payload))

                            if isinstance(item, DeviceTemplate):
                                if item.devices_attached is not None:
                                    b_processor = loaded_processors.get(DeviceTemplateAttached, default_processor)
                                    new_item.devices_attached = DeviceTemplateAttached(
                                        self.processor_eval(b_processor, item.devices_attached, new_name, new_id)
                                    )
                                if item.attach_values is not None:
                                    b_processor = loaded_processors.get(DeviceTemplateValues, default_processor)
                                    new_item.attach_values = DeviceTemplateValues(
                                        self.processor_eval(b_processor, item.attach_values, new_name, new_id)
                                    )

                            if processor.replace_source:
                                self.log_info(f'Replacing {info}: {item_name} -> {new_name}')
                                item = new_item
                            else:
                                self.log_info(f'Adding {info}: {new_name}')
                                export_list.append(new_item)
                                id_mapping[item_id] = new_id

                            name_set.add(new_name)
                            id_hint_map[new_name] = new_id

                        export_list.append(item)

                    if is_bad_name:
                        raise TaskException(f'One or more {info} new names are invalid')

                    if not export_list:
                        self.log_debug(f'No {info} to export')
                        continue

                    x_item_index = index_cls.create(export_list, id_hint_map)
                    if x_item_index.save(parsed_args.output):
                        self.log_debug(f'Saved {info} index')

                    for x_item in export_list:
                        save_params = (parsed_args.output, x_item_index.need_extended_name, x_item.name,
                                       id_hint_map[x_item.name])
                        if x_item.save(*save_params):
                            self.log_debug(f'Saved {info} {x_item.name}')

                        if isinstance(x_item, DeviceTemplate):
                            if x_item.devices_attached is not None and x_item.devices_attached.save(*save_params):
                                self.log_debug(f'Saved {info} {x_item.name} attached devices')
                            if x_item.attach_values is not None and x_item.attach_values.save(*save_params):
                                self.log_debug(f'Saved {info} {x_item.name} values')

        except ProcessorException as ex:
            raise TaskException(f'Transform aborted: {ex}') from None

        return

    def retrieve(self, item_cls: Type[ConfigItem], backend: Union[Rest, str],
                 item_id: str, item_name: str, ext_name: bool) -> Union[ConfigItem, None]:
        item = self.item_get(item_cls, backend, item_id, item_name, ext_name)
        if item is None:
            return None

        if isinstance(item, DeviceTemplate):
            is_api = isinstance(backend, Rest)
            if is_api:
                devices_attached = DeviceTemplateAttached.get_raise(backend, item_id)
            else:
                # devices_attached will be None if there are no attachments (i.e. file is not present)
                devices_attached = DeviceTemplateAttached.load(backend, ext_name, item_name, item_id)

            if devices_attached is not None and not devices_attached.is_empty:
                if is_api:
                    uuid_iter = (uuid for uuid, _ in devices_attached)
                    attach_values = DeviceTemplateValues.get_values(backend, item_id, uuid_iter)
                else:
                    attach_values = DeviceTemplateValues.load(backend, ext_name, item_name, item_id)

                if attach_values is None:
                    self.log_error(f'Failed loading {item_name} values')
                else:
                    item.devices_attached = devices_attached
                    item.attach_values = attach_values

        return item

    def processor_eval(self, p: Processor, config_obj: ConfigItem, new_name: str, new_id: str) -> dict:
        new_payload, trace_log = p.eval(config_obj, new_name, new_id)
        for trace in trace_log:
            self.log_debug(f'Processor {p.name}, {new_name}: {trace}')
        return new_payload


class TransformArgs(TaskArgs):
    output: str
    workdir: Optional[str] = None
    no_rollover: bool = False

    # Validators
    _validate_filename = validator('output', allow_reuse=True)(validate_filename)
    _validate_workdir = validator('workdir', allow_reuse=True)(validate_workdir)


class TransformCopyArgs(TransformArgs):
    recipe_handler: Callable = const(TaskTransform.copy_recipe)
    tag: str
    regex: Optional[str] = None
    not_regex: Optional[str] = None
    name_regex: str

    # Validators
    _validate_tag = validator('tag', allow_reuse=True)(validate_catalog_tag)
    _validate_regex = validator('regex', 'not_regex', allow_reuse=True)(validate_regex)
    _validate_name = validator('name_regex', allow_reuse=True)(validate_ext_template)


class TransformRenameArgs(TransformCopyArgs):
    recipe_handler: Callable = const(TaskTransform.rename_recipe)


class TransformRecipeArgs(TransformArgs):
    recipe_handler: Callable = const(TaskTransform.load_recipe)
    from_file: Optional[str] = None
    from_json: Optional[str] = None

    # Validators
    _validate_existing_file = validator('from_file', allow_reuse=True)(validate_existing_file)
    _validate_json = validator('from_json', allow_reuse=True)(validate_json)

# SwarmerStrategy implementation
import numpy as np
from constants import *
from orbit_util import trace_orbit, sign, get_dist_to_good, gravity_step, trace_orbit_np
from states import State, JoinResult, ThrustPredictor, Thrust
from orbiter import LaserShipStrategy

def min_abs_diff(x, y):
    return min(abs(x), abs(y))

def stat_cost(x):
    return x[0] + LASER_COST * x[1] + REGEN_COST * x[2] + LIVES_COST * x[3]

class SwarmerStrategy(object):
    def __init__(self, homing_horizon=16, homing_T_threshold=64, homing_dist_threshold=3, printships=False):
        self.T = 0
        self.homing_horizon = homing_horizon
        self.homing_T_threshold = homing_T_threshold
        self.homing_dist_threshold = homing_dist_threshold
        self.thrust_predictors = {}
        self.mothership_id = None
        self.mothership_strategy = LaserShipStrategy()
        self.printships = printships

    def pick_stats(self, res):
        joinres = JoinResult.parse(res)
        self.laser_ship_stats = [20, 32, 8, 1] if joinres.budget > 490 else [0, 0, 0, 0]
        laser_budget = stat_cost(self.laser_ship_stats)
        swarm_budget = joinres.budget - laser_budget
        n = swarm_budget // 6
        swarm_fuel = swarm_budget - LIVES_COST * n
        return [swarm_fuel + self.laser_ship_stats[0], self.laser_ship_stats[1], self.laser_ship_stats[2],
                n + self.laser_ship_stats[3]]

    def reset_precomputed(self):
        self.enemy_location = {}
        self.enemy_thrust = {}

    def precompute_enemy_stuff(self, enemy_ship):
        predicted_thrust = self.thrust_predictors[
            enemy_ship.id].predict_only_call_from_precompute() if enemy_ship.fuel > 0 else Thrust(0, 0)
        ex, ey = enemy_ship.next_round_expected_location(predicted_thrust)
        self.enemy_location[enemy_ship.id] = ex, ey
        self.enemy_thrust[enemy_ship.id] = predicted_thrust

    def choose_explode_target(self, my_ship, thrust_action, enemy_ships):
        mindist = 10000
        ship = enemy_ships[0]
        if len(enemy_ships) == 1:
            return ship
        for enemy_ship in enemy_ships:
            predicted_thrust = self.enemy_thrust[enemy_ship.id]
            dist = my_ship.next_dist(thrust_action, enemy_ship, predicted_thrust)
            if dist < mindist:
                mindist = dist
                ship = enemy_ship
        return ship

    def choose_laser_target(self, my_ship, thrust_action, enemy_ships):
        maxp = 0
        ship = None
        for enemy_ship in enemy_ships:
            predicted_thrust = self.enemy_thrust[enemy_ship.id]
            enemy_pos = self.enemy_location[enemy_ship.id]
            laser_power = my_ship.laser_power(thrust_action, enemy_pos[0], enemy_pos[1])
            if laser_power > 0 and laser_power + enemy_ship.fuel > maxp:
                maxp = laser_power + enemy_ship.fuel
                ship = enemy_ship
        return ship

    def asses_laser_power(self, my_ship, thrust_action, enemy_ship):
        can_take_heat = my_ship.max_heat + my_ship.regen - my_ship.heat - (
            THRUST_HEAT if thrust_action != Thrust(0, 0) else 0)
        pw = min(can_take_heat, my_ship.laser)
        predicted_thrust = self.enemy_thrust[enemy_ship.id]
        enemy_pos = self.enemy_location[enemy_ship.id]
        laser_power = my_ship.laser_power(thrust_action, enemy_pos[0], enemy_pos[1], pw)
        if laser_power > 0:
            return pw
        return 0

    # should return Thrust(x,y) object, can get more stuff passed if needed
    def mothership_not_fall_on_planet(self, my_ship, st):
        current_dist_to_good = get_dist_to_good(my_ship.x, my_ship.y, my_ship.vx, my_ship.vy)
        if current_dist_to_good is not None and current_dist_to_good > 0:
            possible_thrusts = []
            for dx in range(-2, 3):
                for dy in range(-2, 3):
                    if my_ship.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                        continue
                    new_dist_to_good = get_dist_to_good(
                        *gravity_step(my_ship.x, my_ship.y, my_ship.vx + dx, my_ship.vy + dy))
                    if new_dist_to_good is not None and new_dist_to_good == current_dist_to_good - 1:
                        possible_thrusts.append((-dx, -dy))
            if possible_thrusts:
                thrust = random.choice(possible_thrusts)
                return Thrust(*thrust)
        return Thrust(0, 0)

    def get_mothership_actions(self, my_ship, st, enemy_ships):
        # we need to spawn swarm first thing
        actions = []
        if my_ship.lives > 1:
            swarm_fuel = max(my_ship.fuel - self.laser_ship_stats[0], 0)
            for n in range(my_ship.lives - 1, 0, -1):
                f = (swarm_fuel * n) // (my_ship.lives - 1)
                if 2 * (f + n) >= my_ship.total_hp():
                    continue
                actions.append(my_ship.do_duplicate_from_mothership(f, n))
                break

        # override all other actions with LaserShipStrategy
        if True:
            thrust = self.mothership_not_fall_on_planet(my_ship, st)
            if thrust.x != 0 or thrust.y != 0:
                actions.append(my_ship.do_thrust(thrust.x, thrust.y))
            actions.extend(self.mothership_strategy.apply_laser(st, my_ship, enemy_ships, thrust, self.enemy_location))
            return actions

        my_pos = [my_ship.x, my_ship.y]
        my_vel = [my_ship.vx, my_ship.vy]
        cur_closest, cur_farthest = trace_orbit(my_pos[0], my_pos[1], my_vel[0], my_vel[1], 384 - self.T)
        thrust = (0, 0)
        if cur_closest <= 24:
            thrust = (-sign(my_pos[0]), -sign(my_pos[0])) if abs(my_pos[0]) > abs(my_pos[1]) else (
                sign(my_pos[1]), -sign(my_pos[1]))
        if cur_farthest > st.field_size:
            thrust = (sign(my_vel[0]), sign(my_vel[1]))
        if my_ship.heat + THRUST_HEAT > my_ship.max_heat:
            thrust = 0, 0
        actions.append([0, my_ship.id, thrust])
        thrust_action = Thrust(*thrust)
        enemy_ship = self.choose_laser_target(my_ship, thrust_action, enemy_ships)
        if enemy_ship:
            predicted_thrust = self.enemy_thrust[enemy_ship.id]
            ex, ey = self.enemy_location[enemy_ship.id]
            next_dist = my_ship.next_dist(thrust_action, enemy_ship, predicted_thrust)
            if my_ship.laser:
                power = self.asses_laser_power(my_ship, thrust_action, enemy_ship)
                if power > 0:
                    actions.append(my_ship.do_laser(ex, ey, power))
        return actions

    def get_explode_gains(self, my_ship, my_ships, enemy_ships, already_hit_ids):
        gains = 0
        no_thrust = Thrust(0, 0)
        hit_ship_ids = [my_ship.id]
        for ship in my_ships:
            if ship.id in already_hit_ids:
                continue
            if my_ship.id == ship.id:
                gains -= my_ship.total_hp()
            else:
                dist = my_ship.next_dist(no_thrust, ship, no_thrust)
                power = my_ship.explode_power(dist)
                gains -= min(ship.total_hp(), power)
                if power > 0:
                    hit_ship_ids.append(ship.id)
        for ship in enemy_ships:
            if ship.id in already_hit_ids:
                continue
            dist = my_ship.next_dist(no_thrust, ship, no_thrust)
            power = my_ship.explode_power(dist)
            gains += 2 * min(ship.total_hp(), power)
            if power > 0:
                hit_ship_ids.append(ship.id)
        return gains, hit_ship_ids

    def apply(self, state):
        self.T += 1
        # assert self.T < 32
        st = State.parse(state)
        self.reset_precomputed()
        actions = []

        for ship in st.ships:
            if ship.id not in self.thrust_predictors:
                self.thrust_predictors[ship.id] = ThrustPredictor()
            self.thrust_predictors[ship.id].add(ship.last_actions)

        my_ships = []
        enemy_ships = []
        for some_ship in st.ships:
            if some_ship.player == st.me:
                if self.mothership_id == None and self.laser_ship_stats[3] > 0:
                    self.mothership_id = some_ship.id
                my_ships.append(some_ship)
            else:
                enemy_ships.append(some_ship)
                self.precompute_enemy_stuff(some_ship)

        orbits = {}
        if self.printships:
            print(f'T:{self.T} Player {st.me}:' + '\n' + "\n".join(str(s) for s in my_ships))

        for my_ship in my_ships:
            if my_ship.id == self.mothership_id:
                actions.extend(self.get_mothership_actions(my_ship, st, enemy_ships))
                continue

            orbit = (my_ship.x, my_ship.y, my_ship.vx, my_ship.vy)
            if orbit not in orbits:
                orbits[orbit] = []
            orbits[orbit].append(my_ship)

        ex = np.array([ship.x for ship in enemy_ships])
        ey = np.array([ship.y for ship in enemy_ships])
        evx = np.array([ship.vx for ship in enemy_ships])
        evy = np.array([ship.vy for ship in enemy_ships])
        exs, eys, evxs, evys = trace_orbit_np(ex, ey, evx, evy, self.homing_horizon)

        explode_actions = []
        already_hist_ids = set()

        for orbit, orbit_ships in orbits.items():
            orbit_dist_to_good = get_dist_to_good(*orbit)
            # print('dist', orbit_dist_to_good, len(orbit_ships))
            if len(orbit_ships) > 1:
                possible_thrusts = []
                target_dist = 3 if sum(ship.lives for ship in orbit_ships) >= 32 else 0
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        if dx == 0 and dy == 0:
                            continue
                        new_dist_to_good = get_dist_to_good(
                            *gravity_step(orbit[0], orbit[1], orbit[2] + dx, orbit[3] + dy))
                        if new_dist_to_good is not None and new_dist_to_good < target_dist:
                            target_dist = new_dist_to_good
                            possible_thrusts = []
                        if new_dist_to_good is not None and new_dist_to_good == target_dist:
                            possible_thrusts.append((-dx, -dy))
                if possible_thrusts:
                    random.shuffle(possible_thrusts)
                    for ship, thrust in zip(orbit_ships[1:], possible_thrusts):
                        actions.append([0, ship.id, thrust])
                continue

            my_ship = orbit_ships[0]
            if orbit_dist_to_good is not None and orbit_dist_to_good > 0 and self.T <= 48:
                possible_thrusts = []
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        if my_ship.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                            continue
                        new_dist_to_good = get_dist_to_good(
                            *gravity_step(orbit[0], orbit[1], orbit[2] + dx, orbit[3] + dy))
                        if new_dist_to_good is not None and new_dist_to_good == orbit_dist_to_good - 1:
                            possible_thrusts.append((-dx, -dy))
                if possible_thrusts:
                    thrust = random.choice(possible_thrusts)
                    actions.append([0, my_ship.id, thrust])
                continue

            if orbit_dist_to_good == 0 and my_ship.lives > 1:
                actions.append(my_ship.do_duplicate_even())
                continue

            if enemy_ships:
                thrust_action = Thrust(0, 0)
                enemy_ship = self.choose_explode_target(my_ship, thrust_action, enemy_ships)
                predicted_thrust = self.enemy_thrust[enemy_ship.id]
                next_dist = my_ship.next_dist(thrust_action, enemy_ship, predicted_thrust)
                if my_ship.explode_power(next_dist) and self.T > 7:
                    new_gains, hit_ids = self.get_explode_gains(my_ship, my_ships, enemy_ships, already_hist_ids)
                    if new_gains > 0:
                        explode_actions.append(my_ship.do_explode())
                        for hit_id in hit_ids:
                            already_hist_ids.add(hit_id)
                        continue

                # homing
                if self.T > self.homing_T_threshold and my_ship.fuel > 0:
                    possible_thrusts = []
                    mx = []
                    my = []
                    mvx = []
                    mvy = []
                    quo_idx = None
                    for dx in range(-2, 3):
                        for dy in range(-2, 3):
                            if my_ship.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                                continue
                            dist_to_good = get_dist_to_good(
                                *gravity_step(orbit[0], orbit[1], orbit[2] + dx, orbit[3] + dy))
                            if dist_to_good is not None and dist_to_good == 0:
                                if dx == 0 and dy == 0:
                                    quo_idx = len(mx)
                                possible_thrusts.append((-dx, -dy))
                                mx.append(orbit[0])
                                my.append(orbit[1])
                                mvx.append(orbit[2] + dx)
                                mvy.append(orbit[3] + dy)
                    mx, my, mvx, mvy = map(np.array, (mx, my, mvx, mvy))
                    mxs, mys, _, _ = trace_orbit_np(mx, my, mvx, mvy, self.homing_horizon)
                    dxs = np.abs(mxs[:, np.newaxis] - exs[np.newaxis])
                    dys = np.abs(mys[:, np.newaxis] - eys[np.newaxis])
                    ds = np.maximum(dxs, dys)
                    ds = np.min(ds, axis=(1, 2))
                    possible_thrusts_close = []
                    for i in range(len(possible_thrusts)):
                        if ds[i] <= self.homing_dist_threshold:
                            possible_thrusts_close.append(possible_thrusts[i])
                            if quo_idx == i:
                                print('cancel homing')
                                possible_thrusts_close = []
                                break
                    if possible_thrusts_close:
                        print('homing!')
                        thrust = random.choice(possible_thrusts_close)
                        actions.append([0, my_ship.id, thrust])
                        continue

        for explode_action in explode_actions:
            actions.append(explode_action)
        return actions

