class CustomOIDCAuthenticationProvider(AuthenticationProvider):
    """
    Custom OIDC authentication implementation
    Args:
        config (MetadataServerConfig):
    Attributes:
        config (MetadataServerConfig)
    """

    def __init__(self, config: OpenMetadataConnection) -> None:
        self.config = config
        self.security_config: CustomOIDCSSOClientConfig = self.config.securityConfig
        self.generated_auth_token = None
        self.expiry = None

    @classmethod
    def create(
        cls, config: OpenMetadataConnection
    ) -> "CustomOIDCAuthenticationProvider":
        return cls(config)

    def auth_token(self) -> None:
        data = {
            "grant_type": "client_credentials",
            "client_id": self.security_config.clientId,
            "client_secret": self.security_config.secretKey,
        }

        response = requests.post(
            url=self.security_config.tokenEndpoint,
            data=data,
        )

        if response.ok:
            response_json = response.json()
            token = response_json.get(ACCESS_TOKEN)

            if not token:
                raise AuthenticationException(
                    f"Error getting access token: {response_json}"
                )

            self.generated_auth_token = token
            self.expiry = response_json.get(EXPIRY)
        else:
            raise APIError(
                error={"message": response.text}, http_error=response.status_code
            )

    def get_access_token(self) -> Tuple[str, int]:
        self.auth_token()
        return self.generated_auth_token, self.expiry

# Linting functionality for Pants build system
from dataclasses import dataclass

from pants.engine.console import Console
from pants.engine.goal import Goal, GoalSubsystem
from pants.engine.isolated_process import FallibleExecuteProcessResult
from pants.engine.legacy.graph import HydratedTargets
from pants.engine.legacy.structs import TargetAdaptor
from pants.engine.objects import Collection, union
from pants.engine.rules import UnionMembership, goal_rule
from pants.engine.selectors import Get, MultiGet


@dataclass(frozen=True)
class LintResult:
    exit_code: int
    stdout: str
    stderr: str

    @staticmethod
    def noop() -> "LintResult":
        return LintResult(exit_code=0, stdout="", stderr="")

    @staticmethod
    def from_fallible_execute_process_result(
        process_result: FallibleExecuteProcessResult
    ) -> "LintResult":
        return LintResult(
            exit_code=process_result.exit_code,
            stdout=process_result.stdout.decode(),
            stderr=process_result.stderr.decode(),
        )


class LintResults(Collection[LintResult]):
    """This collection allows us to aggregate multiple `LintResult`s for a language."""


@union
class LintTarget:
    """A union for registration of a formattable target type."""

    @staticmethod
    def is_lintable(
        target_adaptor: TargetAdaptor, *, union_membership: UnionMembership
    ) -> bool:
        return (
            union_membership.is_member(LintTarget, target_adaptor)
            # TODO: make TargetAdaptor return a 'sources' field with an empty snapshot instead of
            #  raising to remove the hasattr() checks here!
            and hasattr(target_adaptor, "sources")
            and target_adaptor.sources.snapshot.files  # i.e., sources is not empty
        )


class LintOptions(GoalSubsystem):
    """Lint source code."""
    # TODO: make this "lint"
    # Blocked on https://github.com/pantsbuild/pants/issues/8351
    name = 'lint2'
    required_union_implementations = (LintTarget,)


class Lint(Goal):
    subsystem_cls = LintOptions


@goal_rule
async def lint(
    console: Console,
    targets: HydratedTargets,
    union_membership: UnionMembership
) -> Lint:
    nested_results = await MultiGet(
        Get[LintResults](LintTarget, target.adaptor)
        for target in targets
        if LintTarget.is_lintable(target.adaptor, union_membership=union_membership)
    )

    results = [result for results in nested_results for result in results]

    if not results:
        return Lint(exit_code=0)

    exit_code = 0
    for result in results:
        if result.stdout:
            console.print_stdout(result.stdout)
        if result.stderr:
            console.print_stderr(result.stderr)
        if result.exit_code != 0:
            exit_code = result.exit_code

    return Lint(exit_code)


def rules():
    return [
        lint,
    ]

# Import necessary modules for NFT metadata layer handling
from dataclasses import dataclass
from typing import Any, List, Optional, Tuple

from clvm_tools.binutils import disassemble
from chinilla.types.blockchain_format.coin import Coin
from chinilla.types.blockchain_format.program import Program
from chinilla.types.blockchain_format.sized_bytes import bytes32
from chinilla.util.ints import uint64
from chinilla.wallet.puzzle_drivers import PuzzleInfo, Solver
from chinilla.wallet.puzzles.load_clvm import load_clvm

# Load the NFT state layer CLVM program and compute its hash
NFT_STATE_LAYER_MOD = load_clvm("nft_state_layer.clvm")
NFT_STATE_LAYER_MOD_HASH = NFT_STATE_LAYER_MOD.get_tree_hash()


def match_metadata_layer_puzzle(puzzle: Program) -> Tuple[bool, List[Program]]:
    """
    Check if a puzzle matches the metadata layer structure.
    Returns (is_match, curried_arguments)
    """
    mod, meta_args = puzzle.uncurry()
    if mod == NFT_STATE_LAYER_MOD:
        return True, list(meta_args.as_iter())
    return False, []


def puzzle_for_metadata_layer(metadata: Program, updater_hash: bytes32, inner_puzzle: Program) -> Program:
    """Create a metadata layer puzzle with given parameters."""
    return NFT_STATE_LAYER_MOD.curry(NFT_STATE_LAYER_MOD_HASH, metadata, updater_hash, inner_puzzle)


def solution_for_metadata_layer(amount: uint64, inner_solution: Program) -> Program:
    """Construct a solution for the metadata layer."""
    return Program.to([inner_solution, amount])  # type: ignore


@dataclass(frozen=True)
class MetadataOuterPuzzle:
    """Driver class for handling NFT metadata layer puzzles."""

    _match: Any
    _asset_id: Any
    _construct: Any
    _solve: Any
    _get_inner_puzzle: Any
    _get_inner_solution: Any

    def match(self, puzzle: Program) -> Optional[PuzzleInfo]:
        """Match a puzzle reveal to the metadata layer pattern."""
        matched, curried_args = match_metadata_layer_puzzle(puzzle)
        if matched:
            _, metadata, updater_hash, inner_puzzle = curried_args

            constructor_dict = {
                "type": "metadata",
                "metadata": disassemble(metadata),  # type: ignore
                "updater_hash": "0x" + updater_hash.as_python().hex(),
            }

            next_constructor = self._match(inner_puzzle)
            if next_constructor is not None:
                constructor_dict["also"] = next_constructor.info

            return PuzzleInfo(constructor_dict)
        else:
            return None

    def asset_id(self, constructor: PuzzleInfo) -> Optional[bytes32]:
        """Extract the asset ID (updater hash) from constructor info."""
        return bytes32(constructor["updater_hash"])

    def construct(self, constructor: PuzzleInfo, inner_puzzle: Program) -> Program:
        """Build the full metadata layer puzzle."""
        if constructor.also() is not None:
            inner_puzzle = self._construct(constructor.also(), inner_puzzle)
        return puzzle_for_metadata_layer(
            constructor["metadata"],
            constructor["updater_hash"],
            inner_puzzle
        )

    def get_inner_puzzle(self, constructor: PuzzleInfo, puzzle_reveal: Program) -> Optional[Program]:
        """Extract the inner puzzle from a metadata layer puzzle reveal."""
        matched, curried_args = match_metadata_layer_puzzle(puzzle_reveal)
        if matched:
            _, _, _, inner_puzzle = curried_args

            if constructor.also() is not None:
                deep_inner_puzzle: Optional[Program] = self._get_inner_puzzle(
                    constructor.also(), 
                    inner_puzzle
                )
                return deep_inner_puzzle
            else:
                return inner_puzzle
        else:
            raise ValueError("This driver is not for the specified puzzle reveal")

    def get_inner_solution(self, constructor: PuzzleInfo, solution: Program) -> Optional[Program]:
        """Extract the inner solution from a metadata layer solution."""
        my_inner_solution: Program = solution.first()

        if constructor.also():
            deep_inner_solution: Optional[Program] = self._get_inner_solution(
                constructor.also(), 
                my_inner_solution
            )
            return deep_inner_solution
        else:
            return my_inner_solution

    def solve(self, constructor: PuzzleInfo, solver: Solver, inner_puzzle: Program, inner_solution: Program) -> Program:
        """Generate a complete solution for the metadata layer."""
        coin_bytes: bytes = solver["coin"]
        coin: Coin = Coin(
            bytes32(coin_bytes[0:32]),
            bytes32(coin_bytes[32:64]),
            uint64.from_bytes(coin_bytes[64:72])
        )

        if constructor.also() is not None:
            inner_solution = self._solve(constructor.also(), solver, inner_puzzle, inner_solution)

        return solution_for_metadata_layer(
            coin.amount,
            inner_solution,
        )

# Specular Shader Definition
SpecularShaderV1 = Shader(
    language=Shader.GLSL,
    vertex="""
#version 150
uniform mat4 p3d_ModelViewProjectionMatrix;
uniform mat4 p3d_ProjectionMatrix;
uniform mat4 p3d_ModelMatrix;
uniform mat4 p3d_ViewMatrix;
uniform sampler2D p3d_Texture0;
uniform mat3 p3d_NormalMatrix;
uniform vec3 lightPos;
uniform vec3 cameraPos;
uniform sampler2D heightMap;
uniform vec2 textureoffset;
uniform vec2 textureoffset_sec;
uniform sampler2D normalMap;

in vec2 p3d_MultiTexCoord0;
in vec4 vertex;
in vec4 normal;

out vec3 vectorToLight;
out vec3 vectorToCamera;
out vec2 texcoord;
out float alpha;

void main() {
    vec2 coord = (p3d_MultiTexCoord0 + textureoffset);
    vec2 coord_sec = (p3d_MultiTexCoord0 + textureoffset_sec);

    float hgt = texture(heightMap, coord).x * 50;
    float hgt_sec = texture(heightMap, coord_sec).x * 50;

    gl_Position = p3d_ModelViewProjectionMatrix * vec4(vertex.x, vertex.y + (hgt + hgt_sec) / 2, vertex.z, vertex.w);

    vec3 worldPos = (p3d_ModelMatrix * vertex).xyz;
    vectorToLight = lightPos - worldPos;
    vectorToCamera = (inverse(p3d_ViewMatrix) * vec4(0.0, 0.0, 0.0, 1.0)).xyz - worldPos.xyz;

    texcoord = coord * 12;
    alpha = hgt / 40;
    alpha -= sin(dot(vectorToCamera, vec3(0, 1, 0))) / 180;
    alpha = max(alpha, 0.1);
    alpha += 0.1;
}
""",
    fragment="""
#version 140
uniform vec3 lightColor;
uniform float Damper;
uniform float reflectivity;
uniform sampler2D p3d_Texture0;
uniform sampler2D normalMap;
uniform mat3 p3d_NormalMatrix;

in vec3 vectorToLight;
in vec3 vectorToCamera;
in vec2 texcoord;
in vec3 surfaceNormal;
in float alpha;

out vec4 out_color;

void main() {
    vec3 surfaceNormal = p3d_NormalMatrix * texture(normalMap, texcoord).xyz;
    vec4 col = texture(p3d_Texture0, texcoord);
    vec4 color = vec4(0.0, 0.0, col.b, col.a);

    vec3 unitNormal = normalize(surfaceNormal);
    vec3 unitToLight = normalize(vectorToLight);
    vec3 unitToCamera = normalize(vectorToCamera);
    vec3 lightDir = -unitToLight;

    float nDotl = dot(unitNormal, lightDir);
    float brightness = max(nDotl, 0.2);
    vec3 diffuse = brightness * lightColor;

    vec3 reflectedLight = reflect(lightDir, unitNormal);
    float specular = dot(reflectedLight, unitToCamera);
    specular = max(specular, 0.0);
    float damper = pow(specular, Damper);
    vec3 finalSpecular = damper * reflectivity * lightColor;

    vec4 color_final = vec4(diffuse, 1.0) * color + vec4(finalSpecular, 1.0);
    out_color = vec4(color_final.xyz, 1.0);
}
"""
)


class water(Entity):
    def __init__(self, height, size):
        super().__init__()
        self.shader = SpecularShaderV1
        self.vertices = list()
        self.triangles = list()
        self.uvs = list()
        self.hgt = height
        self.createMesh(size)

        self.model = Mesh(
            vertices=self.vertices,
            triangles=self.triangles,
            uvs=self.uvs
        )

        self.set_shader_input("cameraPos", Vec3(0, 0, 0))
        self.set_shader_input("lightPos", Vec3(3, 10, 2))

    def createMesh(self, size):
        for x in range(size):
            for z in range(size):
                index = len(self.vertices)
                self.vertices.extend((
                    Vec3(x, self.hgt, z),
                    Vec3(x + 1, self.hgt, z),
                    Vec3(x + 1, self.hgt, z + 1),
                    Vec3(x, self.hgt, z + 1)
                ))
                self.triangles.extend((
                    (index, index + 1, index + 2),
                    (index + 0, index + 2, index + 3)
                ))
                self.uvs.extend((
                    Vec2(x / size, (z) / size),
                    Vec2((1 + x) / size, (z) / size),
                    Vec2((1 + x) / size, (z + 1) / size),
                    Vec2(x / size, (z + 1) / size)
                ))


