# Mock Celery implementation for testing purposes
import datetime
import logging
import uuid
import celery.result
from celery import states

logger = logging.getLogger(__name__)

def _serialize(value):
    # Handle datetime objects
    if isinstance(value, datetime.datetime):
        return value.isoformat()

    # Handle dictionaries
    if isinstance(value, dict):
        return {key: _serialize(key_value) for key, key_value in value.items()}

    # Handle lists
    if isinstance(value, list):
        return [_serialize(list_value) for list_value in value]

    # Handle tuples (note: original had a bug - should use list comprehension)
    if isinstance(value, tuple):
        return tuple(_serialize(tuple_value) for tuple_value in value)

    # Handle sets
    if isinstance(value, set):
        return {_serialize(set_value) for set_value in value}

    # Default case
    return value

def _async_result_stub(task_id, **kwargs):
    """Stub for AsyncResult to ensure consistent behavior"""
    return _TaskResultStore.get_by_id(task_id)

# Override celery's AsyncResult with our stub
celery.result.AsyncResult = _async_result_stub

class _EagerResultWithStateSupport(celery.result.EagerResult):
    """Extended EagerResult that supports state checking"""
    def ready(self):
        return self._state == states.READY_STATES

class _TaskResultStore:
    """Thread-safe storage for task results"""
    __task_store = {}

    @classmethod
    def put(cls, result):
        """Store a task result by its ID"""
        cls.__task_store[result.id] = result

    @classmethod
    def get_by_id(cls, id):
        """Retrieve a task result by ID or return a pending result"""
        return (
            cls.__task_store[id]
            if id in cls.__task_store
            else _EagerResultWithStateSupport(id, None, states.PENDING)
        )

class CeleryMock:
    """
    Celery App proxy that configures celery app in "task always eager" mode.
    This allows tasks to be executed synchronously during testing.
    """

    def __init__(self, celery_app):
        self.__celery_app = celery_app

        # Configure celery to run tasks eagerly
        self.__celery_app.conf.update(
            task_always_eager=True,
            result_backend="cache",
            cache_backend="memory",
            task_eager_propagates=True,
        )

        self.__task_store = {}

    def __getattr__(self, name):
        if name == "task":
            def task_interceptor(*aa, **oo):
                # Get the original task decorator
                result = getattr(self.__celery_app, "task")(*aa, **oo)

                class AsyncTaskProxy:
                    def __init__(self, method, *a, **o):
                        self.__method = method

                    def apply_async(
                        self,
                        args=None,
                        kwargs=None,
                        task_id=None,
                        producer=None,
                        link=None,
                        link_error=None,
                        shadow=None,
                        **options,
                    ):
                        # Serialize arguments to handle non-serializable types
                        serialized_args = (
                            [_serialize(arg) for arg in args] if args else ()
                        )
                        serialized_kwargs = (
                            {name: _serialize(value) for name, value in kwargs.items()}
                            if kwargs
                            else {}
                        )

                        # Generate task ID if not provided
                        task_id = task_id if task_id else str(uuid.uuid4())

                        try:
                            # Execute the task immediately
                            method_result = self.__method(
                                *serialized_args, **serialized_kwargs
                            )
                            celery_result = celery.result.EagerResult(
                                task_id, method_result, states.SUCCESS
                            )
                        except Exception as e:
                            # Handle exceptions and mark as failure
                            celery_result = celery.result.EagerResult(
                                task_id, e, states.FAILURE
                            )

                        # Store the result
                        _TaskResultStore.put(celery_result)
                        return celery_result

                    def __call__(self, *args, **kwargs):
                        # Direct call bypasses serialization
                        return self.__method(*args, **kwargs)

                return AsyncTaskProxy

            return task_interceptor
        else:
            # Pass through other attributes to the original app
            return getattr(self.__celery_app, name)

from enum import Enum
from typing import Any, Iterable, Dict, Tuple, Callable, Protocol
import regex

class Rule(Protocol):
    def match(self, line: str, index: int = 0, match_all: bool = False) -> int:
        pass

class SimpleRule:
    def __init__(self, rule_str: str):
        self.rule_str = rule_str

    def match(self, line: str, index: int = 0, match_all: bool = False) -> int:
        matched = len(self.rule_str) if line[index:].startswith(self.rule_str) else 0
        return matched if not match_all or index + matched == len(line) else 0

    def __repr__(self):
        return f"<SimpleRule: '{str(self)}'>"

    def __str__(self):
        return self.rule_str

class ChainedRule:
    def __init__(self, sub_rules: Tuple[Rule]):
        self.sub_rules = sub_rules

    def match(self, line: str, index: int = 0, match_all: bool = False) -> int:
        total_digested = 0
        for rule in self.sub_rules:
            digested = rule.match(line, index + total_digested)
            if digested == 0:
                return 0
            assert index + total_digested + digested <= len(line)
            total_digested += digested
        return total_digested if not match_all or index + total_digested == len(line) else 0

    def __repr__(self):
        return f"<ChainedRule: '{str(self)}'>"

    def __str__(self):
        return '+'.join([str(sr) for sr in self.sub_rules])

class FlexRule:
    def __init__(self, sub_rules: Tuple[Rule]):
        self.sub_rules = sub_rules

    def match(self, line: str, index: int = 0, match_all: bool = False) -> int:
        for rule in self.sub_rules:
            digested = rule.match(line, index, match_all)
            assert index + digested <= len(line)
            if digested != 0:
                return digested
        return 0

    def __repr__(self):
        return f"<FlexRule: '{str(self)}'>"

    def __str__(self):
        return "(" + " | ".join([str(sr) for sr in self.sub_rules]) + ")"

def _parse_simple_rule(rule: str):
    SIMPLE_RULE_PATTERN = '(\d+): ("[a-z]+")'
    m = regex.match(SIMPLE_RULE_PATTERN, rule)
    if not m:
        return None

    groups = m.groups()
    rule_id = int(groups[0])
    rule_str = groups[1][1:-1]
    return rule_id, SimpleRule, rule_str

def _parse_compound_rule(rule: str):
    COMPOUND_RULE_PATTERN = '(\d+):( \d+)+( \|( \d+)+)?'
    m = regex.match(COMPOUND_RULE_PATTERN, rule)
    if not m:
        return None
    groups = m.groups()
    rule_type = ChainedRule
    rule_id = int(groups[0])
    sub_rules = (int(sr) for sr in m.captures(2))
    if m.captures(4):
        rule_type = FlexRule
        sub_rules = (sub_rules, (int(sr) for sr in m.captures(4)))
    assert (('|' in rule and rule_type == FlexRule) or rule_type == ChainedRule)
    return rule_id, rule_type, sub_rules

def parse_rule(rule: str) -> Rule:
    return _parse_simple_rule(rule) or _parse_compound_rule(rule)

ParsedRulesMap = Dict[int, Tuple[Callable, Any]]

def parse_rules(rules: Iterable[str]) -> ParsedRulesMap:
    parsed_rules = [parse_rule(r) for r in rules]
    return {rule_id: (rule_type, params) for rule_id, rule_type, params in parsed_rules}

def build_rules(rules: ParsedRulesMap) -> Dict[int, Rule]:
    built_rules = {}
    for rid in rules:
        _build_rule(rules, built_rules, rid)
    return built_rules

def _build_rule(rules, built_rules, rule_id):
    if rule_id in built_rules:
        return
    rule_type, params = rules[rule_id]
    if rule_type == SimpleRule:
        built_rules[rule_id] = rule_type(params)
    elif rule_type == ChainedRule:
        sub_rules = []
        for srid in params:
            sub_rules.append(
                built_rules[srid] if srid in built_rules else
                _build_rule(rules, built_rules, srid)
            )
        built_rules[rule_id] = rule_type(tuple(sub_rules))
    else:
        flex_rule_sub_rules = []
        for chained_group in params:
            chained_rule_sub_rules = []
            for srid in chained_group:
                chained_rule_sub_rules.append(
                    built_rules[srid] if srid in built_rules else
                    _build_rule(rules, built_rules, srid)
                )
            chained_sub_rule = ChainedRule(tuple(chained_rule_sub_rules))
            flex_rule_sub_rules.append(chained_sub_rule)
        built_rules[rule_id] = rule_type(tuple(flex_rule_sub_rules))
    return built_rules[rule_id]

def main():
    lines = open("2020/19/input.txt", "r").readlines()
    rules_strings_separator = lines.index("\n")
    raw_rules = lines[:rules_strings_separator]
    strings = [l[:-1] for l in lines[rules_strings_separator + 1:]]

    print(f"# of rules: {len(raw_rules)}")
    print(f"# of strings: {len(strings)}")

    parsed_rules = parse_rules(raw_rules)
    rules = build_rules(parsed_rules)

    # Part 1:
    lines_matching_rule_0 = list(filter(lambda s: rules[0].match(s, 0, True) != 0, strings))
    print("\n".join(lines_matching_rule_0))
    print(f"Number of lines matching rule #0: {len(list(lines_matching_rule_0))}")

if __name__ == "__main__":
    main()

# Namespace model implementation for Gaphor
from __future__ import annotations

import logging
from typing import TYPE_CHECKING
from gaphas.decorators import g_async
from gi.repository import Gtk
from gaphor import UML
from gaphor.core import Transaction, event_handler, gettext
from gaphor.core.format import format
from gaphor.core.modeling import (
    AttributeUpdated,
    DerivedSet,
    Diagram,
    ElementCreated,
    ElementDeleted,
    ModelFlushed,
    ModelReady,
)
from gaphor.ui.event import Notification

if TYPE_CHECKING:
    from gaphor.core.eventmanager import EventManager
    from gaphor.core.modeling import ElementFactory

log = logging.getLogger(__name__)

# Sentinel object for relationships container
class RELATIONSHIPS:
    name = "0"
    owner = None


def relationship_iter(model, iter):
    """Find or create the relationships pseudo-node in the tree."""
    if iter is not None and not isinstance(model.get_value(iter, 0), UML.Package):
        return iter

    child_iter = model.iter_children(iter)
    while child_iter:
        maybe_relationships = model.get_value(child_iter, 0)
        if maybe_relationships is RELATIONSHIPS:
            return child_iter
        child_iter = model.iter_next(child_iter)

    return model.append(iter, [RELATIONSHIPS])


def relationship_iter_parent(model, iter):
    """Move up the tree until we find a non-relationships node."""
    while model.get_value(iter, 0) is RELATIONSHIPS:
        iter = model.iter_parent(iter)
    return iter


class NamespaceModelRefreshed:
    def __init__(self, model):
        self.model = model


class NamespaceModelElementDropped:
    def __init__(self, model, element):
        self.model = model
        self.element = element


class NamespaceModel(Gtk.TreeStore):
    def __init__(self, event_manager: EventManager, element_factory: ElementFactory):
        super().__init__(object)
        self.event_manager = event_manager
        self.element_factory = element_factory

        # Subscribe to relevant events
        event_manager.subscribe(self.refresh)
        event_manager.subscribe(self._on_element_create)
        event_manager.subscribe(self._on_element_delete)
        event_manager.subscribe(self._on_association_set)
        event_manager.subscribe(self._on_attribute_change)

        # Setup sorting
        self.set_sort_func(0, sort_func, None)
        self.set_sort_column_id(0, Gtk.SortType.ASCENDING)

    def shutdown(self):
        """Unsubscribe from events when shutting down."""
        em = self.event_manager
        em.unsubscribe(self.refresh)
        em.unsubscribe(self._on_element_create)
        em.unsubscribe(self._on_element_delete)
        em.unsubscribe(self._on_association_set)
        em.unsubscribe(self._on_attribute_change)

    def get_element(self, iter):
        """Get the element stored in a tree iterator."""
        return self.get_value(iter, 0)

    def iter_for_element(self, element, old_owner=0):
        """
        Get the Gtk.TreeIter for an element in the Namespace.

        Args:
            element: The element contained in the Namespace.
            old_owner: The old owner containing the element, optional.

        Returns: Gtk.TreeIter object of the model (not the sorted one!)
        """
        # Using `0` as sentinel
        if old_owner != 0:
            parent_iter = self.iter_for_element(old_owner)
        elif element and element.owner:
            parent_iter = self.iter_for_element(element.owner)
        else:
            parent_iter = None

        # Handle relationships specially
        if isinstance(element, UML.Relationship):
            parent_iter = relationship_iter(self, parent_iter)

        # Search for the element among children
        child_iter = self.iter_children(parent_iter)
        while child_iter:
            if self.get_value(child_iter, 0) is element:
                return child_iter
            child_iter = self.iter_next(child_iter)

        return None

    def _visible(self, element):
        """Check if an element should be visible in the namespace view."""
        return isinstance(
            element, (UML.Relationship, UML.NamedElement, Diagram)
        ) and not isinstance(
            element, (UML.InstanceSpecification, UML.OccurrenceSpecification)
        )

    def _add(self, element, iter=None):
        """Add an element and its owned elements to the tree."""
        if self._visible(element):
            # Handle relationships specially
            if isinstance(element, UML.Relationship):
                iter = relationship_iter(self, iter)

            # Add the element
            child_iter = self.append(iter, [element])

            # Recursively add owned elements
            for e in element.ownedElement:
                # Check if owned element is indeed within parent's owner
                if element is e.owner:
                    self._add(e, child_iter)

    def _remove(self, iter):
        """Remove an element from the tree."""
        if iter:
            parent_iter = self.iter_parent(iter)
            self.remove(iter)

            # Clean up empty relationships nodes
            if (
                parent_iter
                and not self.iter_has_child(parent_iter)
                and self.get_value(parent_iter, 0) is RELATIONSHIPS
            ):
                self.remove(parent_iter)

    @event_handler(ModelReady, ModelFlushed)
    def refresh(self, event=None):
        """Load a new model completely."""
        log.debug("Rebuilding namespace model")
        self.clear()

        # Find top-level elements
        toplevel = self.element_factory.select(
            lambda e: self._visible(e) and not e.owner
        )

        for element in toplevel:
            if self._visible(element):
                self._add(element)

        self.event_manager.handle(NamespaceModelRefreshed(self))

    @event_handler(ElementCreated)
    def _on_element_create(self, event: ElementCreated):
        element = event.element
        if self._visible(element) and not self.iter_for_element(element):
            iter = self.iter_for_element(element.owner)
            self._add(element, iter)

    @event_handler(ElementDeleted)
    def _on_element_delete(self, event: ElementDeleted):
        element = event.element
        iter = self.iter_for_element(element)
        self._remove(iter)

    @event_handler(DerivedSet)
    def _on_association_set(self, event: DerivedSet):
        if event.property is not UML.Element.owner:
            return

        old_value, new_value = event.old_value, event.new_value
        element = event.element

        # Remove from old location
        old_iter = self.iter_for_element(element, old_owner=old_value)
        self._remove(old_iter)

        # Add to new location if visible
        if self._visible(element):
            new_iter = self.iter_for_element(new_value)
            # Should be either set (sub node) or unset (root node)
            if bool(new_iter) == bool(new_value):
                self._add(element, new_iter)

    @event_handler(AttributeUpdated)
    def _on_attribute_change(self, event: AttributeUpdated):
        """Element changed, update appropriate row."""
        if (
            event.property is UML.Classifier.isAbstract
            or event.property is UML.BehavioralFeature.isAbstract
            or event.property is UML.Diagram.name
            or event.property is UML.NamedElement.name
        ):
            element = event.element
            iter = self.iter_for_element(element)
            if iter:
                path = self.get_path(iter)
                self.row_changed(path, iter)
                self.sort()

    @g_async(single=True)
    def sort(self):
        """Sort the tree asynchronously."""
        self.set_sort_column_id(
            Gtk.TREE_SORTABLE_UNSORTED_SORT_COLUMN_ID, Gtk.SortType.ASCENDING
        )
        self.set_sort_column_id(0, Gtk.SortType.ASCENDING)

    # Drag and drop support methods
    def do_row_draggable(self, path):
        return True

    def do_drag_data_get(self, path, selection_data):
        target = str(selection_data.get_target())
        row = self[path]
        element = row[0]

        if target == "GTK_TREE_MODEL_ROW":
            return Gtk.tree_set_row_drag_data(selection_data, self, path)
        elif target == "gaphor/element-id":
            selection_data.set(selection_data.get_target(), 8, str(element.id).encode())
            return True

        return False

    def do_drag_data_delete(self, path):
        return False

    def do_row_drop_possible(self, dest_path, selection_data):
        src_data = Gtk.tree_get_row_drag_data(selection_data)
        if not src_data:
            return False

        ok, src_model, src_path = src_data
        if not ok or src_model is not self:
            log.warning("DnD from different tree model")
            return False

        src_row = self[src_path]
        element = src_row[0]
        return isinstance(element, (Diagram, UML.Package, UML.Type))

    def do_drag_data_received(self, dest_path, selection_data):
        if str(selection_data.get_target()) != "GTK_TREE_MODEL_ROW":
            log.warning(f"Wrong drag data type {selection_data.get_target()}")
            return False

        ok, src_model, src_path = Gtk.tree_get_row_drag_data(selection_data)
        if not ok or src_model is not self:
            log.debug("Can't DnD from different tree model")
            return False

        src_row = self[src_path]
        element = src_row[0]

        # Process destination
        dest_path.up()
        if not dest_path:
            dest_element = None
        else:
            try:
                iter = self.get_iter(dest_path)
            except ValueError:
                log.debug(f"Invalid path: '{dest_path}'")
                return False

            dest_element = self.get_value(iter, 0)

            # Skip over relationships pseudo-node
            if dest_element is RELATIONSHIPS:
                iter = relationship_iter_parent(self, iter)
                dest_element = self.get_value(iter, 0)

            # Check if element is already in correct location
            if element.owner is dest_element:
                return False

            # Check for cycles
            ns = dest_element
            while ns:
                if ns is element:
                    log.info("Can not create a cycle")
                    return False
                ns = ns.owner

        try:
            # Set package. This only works for classifiers, packages and diagrams.
            with Transaction(self.event_manager):
                if dest_element is None:
                    del element.package
                elif isinstance(element, Diagram):
                    element.element = dest_element
                else:
                    element.package = dest_element

                self.event_manager.handle(NamespaceModelElementDropped(self, element))
            return True
        except AttributeError as e:
            self.namespace_exception(dest_element, e, element)

        return False

    def namespace_exception(self, dest_element, e, element):
        """Handle namespace exceptions during drag and drop."""
        log.info(f"Unable to drop data {e}")
        self.event_manager.handle(
            Notification(
                gettext("A {} can't be part of a {}.").format(
                    type(element).__name__, type(dest_element).__name__
                )
            )
        )


def sort_func(model, iter_a, iter_b, userdata):
    """Custom sort function for the namespace model."""
    va = model.get_value(iter_a, 0)
    vb = model.get_value(iter_b, 0)

    # Put Relationships pseudo-node at top
    if va is RELATIONSHIPS:
        return -1
    if vb is RELATIONSHIPS:
        return 1

    # Sort by formatted names
    a = (format(va) or "").lower()
    b = (format(vb) or "").lower()

    if a == b:
        return 0
    if a > b:
        return 1
    return -1

