def generate_cache_key(value):
    """
    Generates a cache key for the *args and **kwargs
    """
    # Handle bytes directly
    if is_bytes(value):
        return hashlib.md5(value).hexdigest()

    # Convert text to bytes and recurse
    elif is_text(value):
        return generate_cache_key(to_bytes(text=value))

    # Handle boolean, null, and number types by converting to string representation
    elif is_boolean(value) or is_null(value) or is_number(value):
        return generate_cache_key(repr(value))

    # Handle dictionaries by sorting keys and creating tuples
    elif is_dict(value):
        return generate_cache_key((
            (key, value[key])
            for key
            in sorted(value.keys())
        ))

    # Handle list-like objects and generators
    elif is_list_like(value) or isinstance(value, Generator):
        return generate_cache_key("".join((
            generate_cache_key(item)
            for item
            in value
        )))

    # Raise error for unsupported types
    else:
        raise TypeError("Cannot generate cache key for value {0} of type {1}".format(
            value,
            type(value),
        ))

# Import necessary libraries
from functools import reduce
from typing import List, Callable

import numpy as np
from sklearn import preprocessing, neighbors, metrics


def rank_on_1NN(emerged: List, unemerged: List) -> List:
    # Initialize similarity dictionary with zero values
    closest = {tuple(vec): 0 for vec in unemerged}

    # Compute similarities between emerged and unemerged vectors
    for emerged_vec in emerged:
        for candidate_vec in unemerged:
            sim = get_sim(emerged_vec, candidate_vec)
            if sim > closest[tuple(candidate_vec)]:
                closest[tuple(candidate_vec)] = sim[0][0]

    # Return sorted list of unemerged vectors based on similarity (descending order)
    return [list(item[0]) for item in sorted([item for item in closest.items()], key=lambda x: x[1], reverse=True)]


# Rank on local is implemented by limiting the emerged list to points that emerged at the last timestep
def rank_on_prototype(emerged: List, unemerged: List) -> List:
    # Initialize similarity dictionary with zero values
    closest = {tuple(vec): 0 for vec in unemerged}

    # Compute prototype vector
    proto_vec = get_prototype(emerged)

    # Compute similarities between prototype and unemerged vectors
    for candidate_vec in unemerged:
        sim = get_sim(candidate_vec, proto_vec)
        closest[tuple(candidate_vec)] = sim[0][0]

    # Return sorted list of unemerged vectors based on similarity (descending order)
    return [list(item[0]) for item in sorted([item for item in closest.items()], key=lambda x: x[1], reverse=True)]


def get_prototype(vecs: List) -> List:
    # Compute sum of all vectors using reduce
    sum_vec = reduce(np.add, vecs)
    # Return mean vector
    return np.divide(sum_vec, len(vecs))


def rank_on_progenitor(progenitor: tuple) -> Callable:
    # Factory function returning a ranking function based on progenitor vector
    def rank(emerged: List, unemerged: List) -> List:
        # Initialize similarity dictionary with zero values
        closest = {tuple(vec): 0 for vec in unemerged}

        # Compute similarities between progenitor and unemerged vectors
        for vec in unemerged:
            sim = get_sim(progenitor, vec)
            closest[tuple(vec)] = sim[0][0]

        # Return sorted list of unemerged vectors based on similarity (descending order)
        return [list(item[0]) for item in sorted([item for item in closest.items()], key=lambda x: x[1], reverse=True)]

    return rank


def rank_on_exemplar(emerged: List, unemerged: List) -> List:
    # Initialize cumulative similarity dictionary with zero values
    sum_sim = {tuple(vec): 0 for vec in unemerged}

    # Accumulate similarities across all emerged vectors
    for emerged_vec in emerged:
        for candidate_vec in unemerged:
            sum_sim[tuple(candidate_vec)] += get_sim(emerged_vec, candidate_vec)

    # Return sorted list of unemerged vectors based on cumulative similarity (descending order)
    return [list(item[0]) for item in sorted([item for item in sum_sim.items()], key=lambda x: x[1], reverse=True)]


def get_sim(vec_1: List, vec_2: List) -> float:
    # Compute cosine similarity between two vectors
    return metrics.pairwise.cosine_similarity(
        np.asarray(vec_1).reshape(1, -1), 
        np.asarray(vec_2).reshape(1, -1)
    )


def get_similarity_decreasing(lst: List) -> List:
    # Helper function to sort items by similarity in decreasing order
    return [list(item[0]) for item in sorted([item for item in lst.items()], key=lambda x: x[1], reverse=True)]


