# Import necessary modules
from typing import Any, Dict, List, Optional, Text, Union

from rasa_sdk import Tracker
from rasa_sdk.events import EventType
from rasa_sdk.executor import CollectingDispatcher
from rasa_sdk.forms import FormAction

from covidflow.constants import (
    HAS_ASSISTANCE_SLOT,
    PROVINCE_SLOT,
    PROVINCES_WITH_211,
)
from .form_helper import request_next_slot, validate_boolean_slot, yes_no_nlu_mapping
from .lib.log_util import bind_logger

# Define form name constant
FORM_NAME = "home_assistance_form"


def _has_211(tracker: Tracker) -> bool:
    province = tracker.get_slot(PROVINCE_SLOT)
    return province in PROVINCES_WITH_211


class HomeAssistanceForm(FormAction):
    def name(self) -> Text:
        return FORM_NAME

    async def run(
        self, dispatcher, tracker, domain,
    ):
        bind_logger(tracker)
        return await super().run(dispatcher, tracker, domain)

    @staticmethod
    def required_slots(tracker: Tracker) -> List[Text]:
        if _has_211(tracker):
            return [HAS_ASSISTANCE_SLOT]
        return []

    def slot_mappings(self) -> Dict[Text, Union[Dict, List[Dict]]]:
        return {
            HAS_ASSISTANCE_SLOT: yes_no_nlu_mapping(self),
        }

    def request_next_slot(
        self,
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> Optional[List[EventType]]:
        return request_next_slot(self, dispatcher, tracker, domain, None)

    @validate_boolean_slot
    def validate_has_assistance(
        self,
        value: Union[bool, Text],
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> Dict[Text, Any]:
        return {}

    def submit(
        self,
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> List[Dict]:
        # Check if 211 is available and user doesn't have assistance
        if _has_211(tracker) and not tracker.get_slot(HAS_ASSISTANCE_SLOT):
            dispatcher.utter_message(template="utter_check_delivery_services")

            # Province-specific messages
            if tracker.get_slot(PROVINCE_SLOT) == "qc":
                dispatcher.utter_message(template="utter_may_call_211_qc")
            else:
                dispatcher.utter_message(template="utter_may_call_211_other_provinces")

            dispatcher.utter_message(template="utter_explain_211")
        else:
            dispatcher.utter_message(template="utter_remind_delivery_services")

        dispatcher.utter_message(template="utter_remind_pharmacist_services")
        return []

# Base exception for any error originating from the cruft project
class CruftError(Exception):
    pass

# Raised when Cruft is unable to find a cookiecutter template
class UnableToFindCookiecutterTemplate(CruftError):
    def __init__(self, directory: Union[str, Path]):
        if not isinstance(directory, str):
            directory = str(directory)
        super().__init__(f"Was unable to locate a Cookiecutter template in `{directory}` !")
        self.directory = directory

# Raised when no .cruft.json state is found in the current directory
class NoCruftFound(CruftError):
    def __init__(self, directory: Union[str, Path]):
        if not isinstance(directory, str):
            directory = str(directory)
        super().__init__(
            f"Was unable to locate a `.cruft.json` state file in `{directory}` !"
        )
        self.directory = directory

# Raised when there is an attempt to create a new .cruft.json file but one already exists
class CruftAlreadyPresent(CruftError):
    def __init__(self, file_location: Union[str, Path]):
        if not isinstance(file_location, str):
            file_location = str(file_location)
        super().__init__(f"`.cruft.json` is already defined at `{file_location}` !")
        self.file_location = file_location

# Raised when an invalid cookiecutter repository is provided
class InvalidCookiecutterRepository(CruftError):
    pass

import json
import math
import regex
from collections import defaultdict, Counter, OrderedDict
from dataclasses import dataclass
from fractions import Fraction
from typing import Counter as TypedCounter, Dict, List, FrozenSet, Optional, Any

from ._constant import LETTER
from .language import Language


class _LinguaJSONEncoder(json.JSONEncoder):
    def default(self, obj: Any) -> Any:
        if isinstance(obj, _JSONLanguageModel):
            return {"language": obj.language.name, "ngrams": obj.ngrams}
        return json.JSONEncoder.default(self, obj)


class _LinguaJSONDecoder(json.JSONDecoder):
    def __init__(self, *args, **kwargs):
        json.JSONDecoder.__init__(self, object_hook=self.object_hook, *args, **kwargs)

    def object_hook(self, obj: Any) -> Any:
        if isinstance(obj, dict) and "language" in obj and "ngrams" in obj:
            language = Language[obj["language"]]
            ngrams = self.object_hook(obj["ngrams"])
            return _JSONLanguageModel(language, ngrams)
        return obj


@dataclass
class _JSONLanguageModel:
    language: Language
    ngrams: Dict[str, str]


@dataclass
class _TrainingDataLanguageModel:
    language: Language
    absolute_frequencies: Optional[Dict[str, int]]
    relative_frequencies: Optional[Dict[str, Fraction]]
    json_relative_frequencies: Optional[Dict[str, float]]

    @classmethod
    def from_text(
        cls,
        text: List[str],
        language: Language,
        ngram_length: int,
        char_class: str,
        lower_ngram_absolute_frequencies: Optional[Dict[str, int]],
    ) -> "_TrainingDataLanguageModel":
        absolute_frequencies = cls.compute_absolute_frequencies(
            text, ngram_length, char_class
        )
        relative_frequencies = cls.compute_relative_frequencies(
            ngram_length, absolute_frequencies, lower_ngram_absolute_frequencies
        )
        return _TrainingDataLanguageModel(
            language=language,
            absolute_frequencies=absolute_frequencies,
            relative_frequencies=relative_frequencies,
            json_relative_frequencies=None,
        )

    @classmethod
    def from_json(cls, serialized_json: str) -> "_TrainingDataLanguageModel":
        json_language_model: _JSONLanguageModel = json.loads(
            serialized_json, cls=_LinguaJSONDecoder
        )
        json_relative_frequencies = {}
        for fraction, ngrams in json_language_model.ngrams.items():
            numerator, denominator = fraction.split("/")
            frequency = math.log(int(numerator) / int(denominator))
            for ngram in ngrams.split(" "):
                json_relative_frequencies[ngram] = frequency
        return _TrainingDataLanguageModel(
            language=json_language_model.language,
            absolute_frequencies=None,
            relative_frequencies=None,
            json_relative_frequencies=json_relative_frequencies,
        )

    def to_json(self) -> str:
        fractions_to_ngrams = defaultdict(list)
        if self.relative_frequencies is not None:
            for ngram, fraction in self.relative_frequencies.items():
                fractions_to_ngrams[fraction].append(ngram)
        fractions_to_joined_ngrams = OrderedDict()
        for fraction, ngrams in fractions_to_ngrams.items():
            fraction_str = f"{fraction.numerator}/{fraction.denominator}"
            fractions_to_joined_ngrams[fraction_str] = " ".join(
                sorted(map(lambda n: n, ngrams))
            )
        model = _JSONLanguageModel(self.language, fractions_to_joined_ngrams)
        return regex.sub(r"([:,])\s*", r"\1", json.dumps(model, cls=_LinguaJSONEncoder))

    def get_relative_frequency(self, ngram: str) -> float:
        if (
            self.json_relative_frequencies is None
            or ngram not in self.json_relative_frequencies
        ):
            return 0.0
        return self.json_relative_frequencies[ngram]

    @classmethod
    def compute_absolute_frequencies(
        cls, text: List[str], ngram_length: int, char_class: str
    ) -> Dict[str, int]:
        absolute_frequencies: TypedCounter[str] = Counter()
        regexp = regex.compile(r"^[{}]+$".format(char_class))
        for line in text:
            lowercased_line = line.lower()
            for i in range(0, len(lowercased_line) - ngram_length + 1):
                substr = lowercased_line[i : i + ngram_length]
                if regexp.match(substr) is not None:
                    absolute_frequencies.update([substr])
        return absolute_frequencies

    @classmethod
    def compute_relative_frequencies(
        cls,
        ngram_length: int,
        absolute_frequencies: Dict[str, int],
        lower_ngram_absolute_frequencies: Optional[Dict[str, int]],
    ) -> Dict[str, Fraction]:
        if lower_ngram_absolute_frequencies is None:
            return {}
        ngram_probabilities = {}
        total_ngram_frequency = sum(absolute_frequencies.values())
        for ngram, frequency in absolute_frequencies.items():
            if ngram_length == 1 or len(lower_ngram_absolute_frequencies) == 0:
                denominator = total_ngram_frequency
            else:
                substr = ngram[: ngram_length - 1]
                denominator = lower_ngram_absolute_frequencies[substr]
            ngram_probabilities[ngram] = Fraction(frequency, denominator)
        return ngram_probabilities


@dataclass
class _TestDataLanguageModel:
    ngrams: FrozenSet[str]

    @classmethod
    def from_text(cls, text: str, ngram_length: int) -> "_TestDataLanguageModel":
        if ngram_length not in range(1, 6):
            raise ValueError(f"ngram length {ngram_length} is not in range 1..6")
        ngrams = set()
        text_length = len(text)
        if text_length >= ngram_length:
            for i in range(0, text_length - ngram_length + 1):
                substr = text[i : i + ngram_length]
                if LETTER.fullmatch(substr) is not None:
                    ngrams.add(substr)
        return _TestDataLanguageModel(frozenset(ngrams))

# Solution class for unique paths problem
class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Memoization dictionary to store computed results
        memo = {}

        # Helper function with memoization
        def _uniquePaths(i: int, j: int) -> int:
            # Check if result is already computed
            if (i, j) in memo:
                return memo[(i, j)]

            # Base case: reached the bottom or right edge
            if j >= m - 1 or i >= n - 1:
                return 1

            # Recursive calculation with memoization
            c = _uniquePaths(i + 1, j) + _uniquePaths(i, j + 1)
            memo[(i, j)] = c
            return c

        # Start from top-left corner (0, 0)
        return _uniquePaths(0, 0)

# Custom Numba compiler pipeline for Galois
import numba.cpython.builtins
from llvmlite import ir
from numba.core import compiler, sigutils, types
from numba.core.compiler import CompilerBase, DefaultPassBuilder
from numba.core.imputils import lower_constant

# Configuration flags
disable_nrt = True
external_function_pointer_as_constant = True


class KatanaCompiler(CompilerBase):
    """A numba compiler pipeline that is customized for Galois.
    """
    def define_pipelines(self):
        # Maintain objmode fallback behaviour
        pms = []

        if not self.state.flags.force_pyobject:
            pms.append(DefaultPassBuilder.define_nopython_pipeline(self.state))

        if self.state.status.can_fallback or self.state.flags.force_pyobject:
            pms.append(DefaultPassBuilder.define_objectmode_pipeline(self.state))

        if hasattr(self.state.status, "can_giveup") and self.state.status.can_giveup:
            pms.append(DefaultPassBuilder.define_interpreted_pipeline(self.state))

        return pms


class OperatorCompiler(KatanaCompiler):
    """A numba compiler pipeline that is customized for Galois operators.
    Operators are assumed not to leak references to any memory objects, like arrays.
    """
    def __init__(self, typingctx, targetctx, library, args, return_type, flags, local_vars):
        if disable_nrt:
            flags.nrt = False

        super().__init__(typingctx, targetctx, library, args, return_type, flags, local_vars)
        targetctx.is_operator_context = True


@lower_constant(types.ExternalFunctionPointer)
def constant_function_pointer(context, builder: ir.IRBuilder, ty, pyval):
    """
    Override the internal handling of ExternalFunctionPointer to avoid generating a global variable.
    """
    if (
        external_function_pointer_as_constant
        and hasattr(context, "is_operator_context")
        and context.is_operator_context
    ):
        ptrty = context.get_function_pointer_type(ty)
        return ir.Constant(ir.types.IntType(64), ty.get_pointer(pyval)).inttoptr(ptrty)

    # If we are not in an operator context (as defined by OperatorCompiler use) then call the numba implementation
    return numba.cpython.builtins.constant_function_pointer(context, builder, ty, pyval)

