# Test tool module prefix prevents collisions
def test_tool_module_prefix_prevents_collision():
    """Test that tool modules are loaded with prefix to prevent sys.modules collisions."""
    with tempfile.NamedTemporaryFile(mode="w", suffix=".py", delete=False) as f:
        f.write(
            textwrap.dedent("""
            import strands
            @strands.tools.tool
            def test_tool():
                return "test"
        """)
        )
        f.flush()
        # Load the tool
        tools = load_tools_from_file_path(f.name)
        # Check that module is in sys.modules with prefix
        module_name = os.path.basename(f.name).split(".")[0]
        prefixed_name = f"{_TOOL_MODULE_PREFIX}{module_name}"
        assert prefixed_name in sys.modules
        assert len(tools) == 1
        assert tools[0].tool_name == "test_tool"

# Formatter class for Quranic content
class QuranFormatter:

    @staticmethod
    def format_ayah(ayah_data):
        """Format a single Ayah for display."""
        if not ayah_data:
            return "Ayah not found."

        # Extract ayah details
        surah_name = ayah_data['surah']['englishName'] 
        surah_num = ayah_data['surah']['number']
        ayah_num = ayah_data['numberInSurah']
        text_ar = ayah_data['text_ar']
        text_tr = ayah_data['text_tr']

        # Build formatted output
        return f"=== {surah_name} ({surah_num}:{ayah_num}) ===\n\n{text_ar}\n\n{text_tr}"

    @staticmethod
    def format_surah(ayahs):
        """Format a full Surah."""
        if not ayahs:
            return "Surah not found."

        # ayahs is a list of ayah dicts
        first_ayah = ayahs[0]
        # In get_surah, 'surah' key contains the surah metadata
        surah_meta = first_ayah['surah']
        surah_name = surah_meta.get('englishName', f"Surah {surah_meta.get('number')}")
        surah_num = surah_meta.get('number')

        # Prepare output lines
        output = [f"=== {surah_name} (Surah {surah_num}) ==="]
        for ayah in ayahs:
            output.append(f"\n[{ayah['numberInSurah']}] {ayah['text_ar']}")
            output.append(f"{ayah['text_tr']}")

        return "\n".join(output)

    @staticmethod
    def format_search_results(results, keyword):
        """Format search results."""
        if not results:
            return f"No results found for '{keyword}'."

        # Initialize output with header
        output = [f"Search results for '{keyword}':\n"]
        for ayah in results:
            output.append(QuranFormatter.format_ayah(ayah))
            output.append("-" * 30)

        return "\n".join(output)

# Removes None values from a dictionary
from typing import Any, Dict, Mapping, Optional

def remove_none_from_dict(original: Mapping[str, Optional[Any]]) -> Dict[str, Any]:
    # Create a new dictionary to store non-None values
    new: Dict[str, Any] = {}

    # Iterate through the original dictionary
    for key, value in original.items():
        # Only add keys with non-None values
        if value is not None:
            new[key] = value

    # Return the cleaned dictionary
    return new

