# Imports for date/time handling and type hints
from datetime import datetime, date, timedelta
from typing import Optional, Tuple
import re


def parse_time_input(input_str: str) -> datetime:
    """
    Parse natural language time input into datetime.

    Supports:
    - "9am", "2pm" -> today at that hour
    - "yesterday" -> yesterday at 00:00
    - "last week" -> 7 days ago at 00:00
    - ISO timestamps: "2026-02-06 09:00", "2026-02-06T09:00:00"
    - Relative: "1h ago", "2d ago"
    """
    # Normalize input
    input_str = input_str.strip().lower()

    # Handle "Xam" / "Xpm" (e.g., "9am", "2pm")
    if match := re.match(r'(\d{1,2})(am|pm)$', input_str):
        hour = int(match.group(1))
        if match.group(2) == 'pm' and hour != 12:
            hour += 12
        elif match.group(2) == 'am' and hour == 12:
            hour = 0
        return datetime.combine(date.today(), datetime.min.time()).replace(hour=hour)

    # Handle "yesterday"
    if input_str == 'yesterday':
        return datetime.combine(date.today() - timedelta(days=1), datetime.min.time())

    # Handle "last week"
    if input_str == 'last week':
        return datetime.combine(date.today() - timedelta(days=7), datetime.min.time())

    # Handle "Xh ago", "Xd ago", "Xm ago"
    if match := re.match(r'(\d+)(h|d|m)\s*ago$', input_str):
        amount = int(match.group(1))
        unit = match.group(2)
        if unit == 'h':
            return datetime.now() - timedelta(hours=amount)
        elif unit == 'd':
            return datetime.now() - timedelta(days=amount)
        elif unit == 'm':
            return datetime.now() - timedelta(minutes=amount)

    # Try ISO format parsing
    try:
        # Handle "2026-02-06 09:00" or "2026-02-06T09:00:00"
        if 'T' in input_str or ' ' in input_str:
            return datetime.fromisoformat(input_str)
        # Handle "2026-02-06" (assume 00:00)
        return datetime.combine(date.fromisoformat(input_str), datetime.min.time())
    except ValueError:
        pass

    raise ValueError(f"Could not parse time input: '{input_str}'")


def resolve_time_range(
    period: Optional[str] = None,
    since: Optional[str] = None,
    after: Optional[str] = None,
    between: Optional[Tuple[str, str]] = None,
) -> Tuple[Optional[datetime], Optional[datetime]]:
    """
    Resolve time range from CLI arguments.

    Returns (start, end) datetimes.
    Priority: between > since/after > period
    """
    # Handle --between start end
    if between:
        start_str, end_str = between
        start = parse_time_input(start_str)
        end = parse_time_input(end_str)
        return (start, end)

    # Handle --since / --after (alias)
    time_input = since or after
    if time_input:
        start = parse_time_input(time_input)
        return (start, None)  # No end limit

    # Handle --period (legacy, default behavior)
    if period:
        now = datetime.now()
        if period == 'day':
            start = datetime.combine(date.today(), datetime.min.time())
        elif period == 'week':
            start = datetime.combine(date.today() - timedelta(days=7), datetime.min.time())
        elif period == 'month':
            start = datetime.combine(date.today() - timedelta(days=30), datetime.min.time())
        else:
            raise ValueError(f"Unknown period: {period}")
        return (start, None)

    # Default: today
    return (datetime.combine(date.today(), datetime.min.time()), None)

import base64
import dataclasses
import datetime as dt
from enum import Enum
from pathlib import PurePath
from types import GeneratorType
from typing import Any, Callable, Dict, List, Optional, Set, Union

import pydantic
from .datetime_utils import serialize_datetime
from .pydantic_utilities import (
    IS_PYDANTIC_V2,
    encode_by_type,
    to_jsonable_with_fallback,
)

SetIntStr = Set[Union[int, str]]
DictIntStrAny = Dict[Union[int, str], Any]


def jsonable_encoder(obj: Any, custom_encoder: Optional[Dict[Any, Callable[[Any], Any]]] = None) -> Any:
    custom_encoder = custom_encoder or {}

    # Generated SDKs use Ellipsis (`...`) as the sentinel value for "OMIT".
    # OMIT values should be excluded from serialized payloads.
    if obj is Ellipsis:
        return None

    if custom_encoder:
        if type(obj) in custom_encoder:
            return custom_encoder[type(obj)](obj)
        else:
            for encoder_type, encoder_instance in custom_encoder.items():
                if isinstance(obj, encoder_type):
                    return encoder_instance(obj)

    if isinstance(obj, pydantic.BaseModel):
        if IS_PYDANTIC_V2:
            encoder = getattr(obj.model_config, "json_encoders", {})  # type: ignore # Pydantic v2
        else:
            encoder = getattr(obj.__config__, "json_encoders", {})  # type: ignore # Pydantic v1

        if custom_encoder:
            encoder.update(custom_encoder)

        obj_dict = obj.dict(by_alias=True)

        if "__root__" in obj_dict:
            obj_dict = obj_dict["__root__"]
        if "root" in obj_dict:
            obj_dict = obj_dict["root"]

        return jsonable_encoder(obj_dict, custom_encoder=encoder)

    if dataclasses.is_dataclass(obj):
        obj_dict = dataclasses.asdict(obj)  # type: ignore
        return jsonable_encoder(obj_dict, custom_encoder=custom_encoder)

    if isinstance(obj, bytes):
        return base64.b64encode(obj).decode("utf-8")

    if isinstance(obj, Enum):
        return obj.value

    if isinstance(obj, PurePath):
        return str(obj)

    if isinstance(obj, (str, int, float, type(None))):
        return obj

    if isinstance(obj, dt.datetime):
        return serialize_datetime(obj)

    if isinstance(obj, dt.date):
        return str(obj)

    if isinstance(obj, dict):
        encoded_dict = {}
        allowed_keys = set(obj.keys())

        for key, value in obj.items():
            if key in allowed_keys:
                if value is Ellipsis:
                    continue
                encoded_key = jsonable_encoder(key, custom_encoder=custom_encoder)
                encoded_value = jsonable_encoder(value, custom_encoder=custom_encoder)
                encoded_dict[encoded_key] = encoded_value

        return encoded_dict

    if isinstance(obj, (list, set, frozenset, GeneratorType, tuple)):
        encoded_list = []

        for item in obj:
            if item is Ellipsis:
                continue
            encoded_list.append(jsonable_encoder(item, custom_encoder=custom_encoder))

        return encoded_list

    def fallback_serializer(o: Any) -> Any:
        attempt_encode = encode_by_type(o)
        if attempt_encode is not None:
            return attempt_encode

        try:
            data = dict(o)
        except Exception as e:
            errors: List[Exception] = []
            errors.append(e)

            try:
                data = vars(o)
            except Exception as e:
                errors.append(e)
                raise ValueError(errors) from e

        return jsonable_encoder(data, custom_encoder=custom_encoder)

    return to_jsonable_with_fallback(obj, fallback_serializer)

# Network scanner using nmap
import json
import sys
import ipaddress
import subprocess

def is_valid_ipv4_address(address):
    try:
        ipaddress.ip_address(address)
        return True
    except ValueError:
        return False

def is_valid_cidr(cidr):
    try:
        ipaddress.ip_network(cidr)
        return True
    except ValueError:
        return False

def scan_network(target, ports, quick=False, fast=False, timeout=30, top_ports=None, hosts_limit=None, exclude=None):
    try:
        scanner = nmap.PortScanner()
    except nmap.PortScannerError:
        return {"error": "nmap program was not found. Please install nmap."}

    scan_options = '-sV'

    if fast:
        scan_options += ' -T4'

    if timeout:
        scan_options += f' --host-timeout {timeout}s'

    if top_ports:
        scan_options += f' --top-ports {top_ports}'

    if hosts_limit:
        scan_options += f' -n --max-hosts {hosts_limit}'

    if exclude:
        scan_options += f' --exclude {exclude}'

    try:
        if is_valid_ipv4_address(target):
            results = scanner.scan(target, ports, arguments=scan_options)
        elif is_valid_cidr(target):
            if not top_ports:
                scan_options += f' --top-ports 10'  # default --quick for CIDR
            results = scanner.scan(target, ports, arguments=scan_options)
        elif '-' in target:
            start_ip, end_ip = target.split('-')
            results = scanner.scan(start_ip+'-'+end_ip, ports, arguments=scan_options)
        elif ',' in target:
            results = scanner.scan(target, ports, arguments=scan_options)
        else:
            return {"error": "Invalid target format. Supported formats: CIDR, range (start-end), single IP or comma-separated list."}
    except Exception as e:
        return {"error": str(e)}

    scan_data = {}
    if 'scan' in results:
        for host, host_data in results['scan'].items():
            scan_data[host] = {}
            if 'tcp' in host_data:
                scan_data[host]['tcp'] = host_data['tcp']

    return {"scan_results": scan_data, "nmap_command": scanner.command_line(), "scan_info": scanner.scaninfo()}

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(json.dumps({"error": "Missing arguments. Usage: network-scan target=<target> ports=<ports> [--quick] [--fast] [--timeout <seconds>] [--top-ports <num>] [--hosts-limit <num>] [--exclude <ip>]"}, indent=4))
        sys.exit(1)

    target = None
    ports = None
    quick = False
    fast = False
    timeout = 30
    top_ports = None
    hosts_limit = None
    exclude = None

    try:
        for arg in sys.argv[1:]:
            if arg.startswith("target="):
                target = arg.split("=")[1]
            elif arg.startswith("ports="):
                ports = arg.split("=")[1]
            elif arg == "--quick":
                quick = True
            elif arg == "--fast":
                fast = True
            elif arg.startswith("--timeout="):
                timeout = int(arg.split("=")[1])
            elif arg.startswith("--top-ports="):
                top_ports = int(arg.split("=")[1])
            elif arg.startswith("--hosts-limit="):
                hosts_limit = int(arg.split("=")[1])
            elif arg.startswith("--exclude="):
                exclude = arg.split("=")[1]
    except Exception as e:
        print(json.dumps({"error": f"Error parsing arguments: {str(e)}"}))
        sys.exit(1)

    if not target or not ports:
        print(json.dumps({"error": "Target and ports are required arguments."}))
        sys.exit(1)

    results = scan_network(target, ports, quick, fast, timeout, top_ports, hosts_limit, exclude)
    print(json.dumps(results, indent=4))

# OMEGA JSON Compatibility Wrapper - orjson for hot paths, stdlib fallback.
# Drop-in replacement: import omega.json_compat as json
# Rollback: OMEGA_USE_STDLIB_JSON=1

import os
import json as _json

_USE_ORJSON = os.environ.get("OMEGA_USE_STDLIB_JSON") != "1"

try:
    if _USE_ORJSON:
        import orjson as _orjson
    else:
        _orjson = None
except ImportError:
    _orjson = None


def loads(s, **kwargs):
    if _orjson and not kwargs:
        return _orjson.loads(
            s if isinstance(s, (bytes, bytearray, memoryview)) else s.encode()
        )
    return _json.loads(s, **kwargs)


def dumps(obj, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    if indent is not None or not _orjson:
        return _json.dumps(
            obj,
            indent=indent,
            default=default,
            sort_keys=sort_keys,
            ensure_ascii=ensure_ascii,
            **kwargs
        )

    opts = 0
    if sort_keys:
        opts |= _orjson.OPT_SORT_KEYS

    orjson_default = default if callable(default) else (str if default == str else None)

    return _orjson.dumps(obj, default=orjson_default, option=opts or None).decode()


def load(fp, **kwargs):
    return loads(fp.read(), **kwargs)


def dump(obj, fp, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    fp.write(
        dumps(
            obj,
            indent=indent,
            default=default,
            sort_keys=sort_keys,
            ensure_ascii=ensure_ascii,
            **kwargs
        )
    )

