# Validate a source URL
def validate_source(url, session):
    try:
        response = session.head(url, timeout=5, allow_redirects=True)
        content_type = response.headers.get("content-type", "").lower()
        return response.status_code == 200 and ("text" in content_type or "m3u" in content_type)
    except requests.RequestException as e:
        logger.error(f"Source {url} unreachable: {e}")
        return False

# Check if a URL is active
def is_stream_active(url, session):
    if not url.lower().endswith(".m3u8"):
        return False  # Skip non-.m3u8

    try:
        response = session.head(url, timeout=1, allow_redirects=True)
        if response.status_code in (200, 206, 301, 302):
            return True

        response = session.get(url, timeout=3, allow_redirects=True)
        return response.status_code == 200 and "#EXTM3U" in response.text[:100]
    except requests.RequestException:
        return False

# Validate streams concurrently
def validate_streams_concurrently(entries, processed_links, session):
    valid_streams = []
    to_validate = []
    now = time.time()
    start_time = now

    for extinf, url in entries:
        if url in processed_links:
            last_checked = processed_links[url].get("last_checked", 0)
            is_active = processed_links[url].get("is_active", False)

            if is_active and (now - last_checked) < REVALIDATION_INTERVAL:
                valid_streams.append((extinf, url))
                logger.info(f"Skipped validation for cached active stream: {url}")
                continue

        to_validate.append((extinf, url))

    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as executor:
        future_to_entry = {executor.submit(is_stream_active, url, session): (extinf, url) for extinf, url in to_validate}

        for future in concurrent.futures.as_completed(future_to_entry):
            if time.time() - start_time > VALIDATION_TIMEOUT:
                logger.warning("Validation timeout reached")
                break

            extinf, url = future_to_entry[future]
            try:
                if future.result():
                    valid_streams.append((extinf, url))
                    processed_links[url] = {
                        "last_checked": time.time(),
                        "is_active": True
                    }
                else:
                    processed_links[url] = {
                        "last_checked": time.time(),
                        "is_active": False
                    }
            except Exception:
                processed_links[url] = {
                    "last_checked": time.time(),
                    "is_active": False
                }

    return valid_streams

# Fetch variant streams
def get_variant_streams(master_url, session):
    variants = [{"resolution": "Original", "url": master_url, "bandwidth": 2560000}]

    if not master_url.lower().endswith(".m3u8") or not is_stream_active(master_url, session):
        return variants

    try:
        response = session.get(master_url, timeout=3)
        if response.status_code != 200:
            return variants

        content = response.text
        if "#EXT-X-STREAM-INF" in content:
            lines = content.splitlines()
            for i, line in enumerate(lines):
                if line.startswith("#EXT-X-STREAM-INF"):
                    match = re.search(r'BANDWIDTH=(\d+).*?RESOLUTION=(\d+x\d+)', line)
                    if match:
                        bandwidth = int(match.group(1))
                        resolution = match.group(2)
                        variant_url = lines[i + 1].strip() if i + 1 < len(lines) else None

                        if variant_url and variant_url.startswith("http"):
                            variants.append({
                                "resolution": resolution,
                                "url": variant_url,
                                "bandwidth": bandwidth
                            })
                    elif "BANDWIDTH" in line:
                        bandwidth = int(re.search(r'BANDWIDTH=(\d+)', line).group(1))
                        variant_url = lines[i + 1].strip() if i + 1 < len(lines) else None

                        if variant_url and variant_url.startswith("http"):
                            variants.append({
                                "resolution": f"Variant_{len(variants)}",
                                "url": variant_url,
                                "bandwidth": bandwidth
                            })
        return [v for v in variants if is_stream_active(v["url"], session)] or variants
    except Exception:
        return variants

# Clean channel name
def clean_channel_name(name, url):
    if not name:
        return f"channel_{hashlib.md5(url.encode()).hexdigest()[:8]}"

    name = re.sub(r'[^a-zA-Z0-9\s]', '', name).strip().lower().replace(' ', '_')
    name = re.sub(r'_+', '_', name)

    return f"{name}_{hashlib.md5(url.encode()).hexdigest()[:8]}" if name else f"channel_{hashlib.md5(url.encode()).hexdigest()[:8]}"

# Add default logo and last-checked timestamp
def ensure_logo(extinf):
    now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S+00:00")

    if 'tvg-logo="' not in extinf or 'tvg-logo=""' in extinf:
        match = re.search(r'(#EXTINF:-?\d+\s+)(.*?),(.+)$', extinf)
        if match:
            return f'{match.group(1)}tvg-logo="{DEFAULT_LOGO}" tvg-last-checked="{now}" {match.group(2)},{match.group(3)}'
        return extinf.replace('#EXTINF:', f'#EXTINF:-1 tvg-logo="{DEFAULT_LOGO}" tvg-last-checked="{now}" ')

    if 'tvg-last-checked="' not in extinf:
        match = re.search(r'(#EXTINF:-?\d+\s+.*?)(,.*)$', extinf)
        if match:
            return f'{match.group(1)} tvg-last-checked="{now}"{match.group(2)}'

    return extinf

# Parse M3U content
def parse_m3u(content):
    entries = []
    lines = content.splitlines()
    extinf = None

    for line in lines:
        line = line.strip()
        if not line:
            continue

        if line.startswith("#EXTINF:"):
            extinf = line
        elif line.startswith("http") and extinf:
            entries.append((extinf, line))
            extinf = None

    logger.info(f"Parsed {len(entries)} entries")
    return entries[:MAX_STREAMS_PER_SOURCE]

# Fetch and parse a source
def process_source(source, session):
    if not validate_source(source, session):
        logger.error(f"Source {source} invalid, skipping")
        return []

    try:
        logger.info(f"Fetching {source}")
        response = session.get(source, timeout=5)

        if response.status_code == 200:
            content = response.text
            entries = parse_m3u(content)
            logger.info(f"Found {len(entries)} entries in {source}")
            return entries
        else:
            logger.warning(f"Source {source} returned status {response.status_code}")
    except requests.RequestException as e:
        logger.error(f"Failed to fetch {source}: {e}")

    return []

# Fetch sources concurrently
def fetch_all_sources(sources, session):
    all_entries = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as executor:
        future_to_source = {executor.submit(process_source, source, session): source for source in sources}

        for future in concurrent.futures.as_completed(future_to_source):
            source = future_to_source[future]
            try:
                entries = future.result()
                all_entries.extend(entries)
            except Exception as e:
                logger.error(f"Source {source} failed: {e}")

    return all_entries

# Main processing logic
def main():
    logger.info("Starting stream processing")

    # Create session with retries
    session = create_session()

    # Load processed links
    processed_links = load_processed_links()

    # Clean up old files
    if os.path.exists(BASE_PATH):
        shutil.rmtree(BASE_PATH)
        logger.info(f"Deleted old files in {BASE_PATH}")

    os.makedirs(BASE_PATH, exist_ok=True)
    os.makedirs(os.path.dirname(FINAL_M3U_FILE), exist_ok=True)

    # Fetch sources
    all_entries = fetch_all_sources(SOURCES + FALLBACK_SOURCES, session)
    logger.info(f"Total entries collected: {len(all_entries)}")

    # If no entries, use static M3U
    if not all_entries:
        logger.warning("No entries from sources, using static M3U")
        all_entries = parse_m3u(STATIC_M3U)

    # Validate streams
    logger.info(f"Validating {len(all_entries)} streams concurrently")
    all_entries = validate_streams_concurrently(all_entries, processed_links, session)
    logger.info(f"Found {len(all_entries)} active streams after validation")

    # Save processed links
    save_processed_links(processed_links)

    # Sort to prioritize .m3u8
    all_entries.sort(key=lambda x: 0 if x[1].lower().endswith(".m3u8") else 1)

    # Process for uniqueness
    logger.info(f"Processing {len(all_entries)} entries for uniqueness")
    m3u8_count = 0
    non_m3u8_count = 0
    unique_streams = {}

    for i, (extinf, url) in enumerate(all_entries):
        if len(unique_streams) >= MAX_STREAMS:
            logger.info(f"Reached MAX_STREAMS limit: {MAX_STREAMS}")
            break

        if i % 100 == 0:
            logger.info(f"Processed {i} of {len(all_entries)} entries, {len(unique_streams)} valid streams")

        if url.lower().endswith(".m3u8"):
            m3u8_count += 1
        else:
            non_m3u8_count += 1

        if url in unique_streams:
            continue

        match = re.search(r',(.+)$', extinf)
        channel_name = clean_channel_name(match.group(1) if match else "", url)
        variants = get_variant_streams(url, session)

        unique_streams[url] = (ensure_logo(extinf), url, variants, channel_name)
        logger.info(f"Added valid stream: {channel_name} for URL {url}")

    logger.info(f"Processed {m3u8_count} .m3u8 streams and {non_m3u8_count} non-.m3u8 streams")
    logger.info(f"Total unique valid streams: {len(unique_streams)}")

    # Add fallback if no streams
    if not unique_streams:
        logger.warning("No valid streams found, adding fallback")
        variants = get_variant_streams(FALLBACK_STREAM["url"], session)
        unique_streams[FALLBACK_STREAM["url"]] = (FALLBACK_STREAM["extinf"], FALLBACK_STREAM["url"], variants, FALLBACK_STREAM["name"])

    logger.info(f"Final unique streams: {len(unique_streams)}")

    # Prepare outputs
    now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S+00:00")
    final_m3u_content = [f'#EXTM3U tvg-updated="{now}"']
    individual_files = {}

    for url, (extinf, original_url, variants, channel_name) in unique_streams.items():
        github_url = f"https://bugsfreeweb.github.io/{REPO_NAME}/BugsfreeStreams/StreamsTV-TR/{channel_name}.m3u8"
        file_path = os.path.join(BASE_PATH, f"{channel_name}.m3u8")

        m3u8_content = ["#EXTM3U", "#EXT-X-VERSION:3"]
        for variant in variants:
            resolution = variant["resolution"]
            bandwidth = variant["bandwidth"]
            variant_url = variant["url"]

            m3u8_content.append(f"#EXT-X-STREAM-INF:PROGRAM-ID=1,BANDWIDTH={bandwidth},RESOLUTION={resolution}")
            m3u8_content.append(variant_url)

        individual_files[file_path] = "\n".join(m3u8_content)
        final_m3u_content.append(f"{extinf}\n{github_url}")

    # Write files
    for file_path, content in individual_files.items():
        try:
            with open(file_path, "w", encoding="utf-8") as f:
                f.write(content)
        except OSError as e:
            logger.error(f"Failed to write {file_path}: {e}")

    try:
        with open(FINAL_M3U_FILE, "w", encoding="utf-8") as f:
            f.write("\n".join(final_m3u_content))
        logger.info(f"Wrote {FINAL_M3U_FILE} with {len(final_m3u_content)-1} entries")
    except OSError as e:
        logger.error(f"Failed to write {FINAL_M3U_FILE}: {e}")

    logger.info(f"Total files in {BASE_PATH}: {len(individual_files)}")

if __name__ == "__main__":
    main()

# LazyBytes and service implementations for handling large byte data efficiently

from contextlib import contextmanager
from datetime import datetime, timedelta
from io import SEEK_END, BytesIO
from math import ceil
from mmap import PROT_READ, mmap
from tempfile import (
    NamedTemporaryFile,
    SpooledTemporaryFile,
    TemporaryFile,
    _TemporaryFileWrapper,
)
from typing import IO, Any, BinaryIO, Generator
from gridfs import GridFSBucket
from pydantic import BaseModel, ConfigDict, model_validator
from pymongo.database import Database
from common.settings import settings
from common.utils.gridfs import chunked_iterator_for_stream


class LazyBytes(BaseModel):
    """Serializable container for lazy-loadable byte data."""
    model_config = ConfigDict(frozen=True)

    service_id: Any | None = None
    embedded_data: bytes | None = None

    @model_validator(mode="after")
    def check_either_service_id_or_embedded_data(self) -> "LazyBytes":
        if self.service_id is None and self.embedded_data is None:
            msg = "no service id but no embedded data"
            raise ValueError(msg)

        if not (self.service_id is None or self.embedded_data is None):
            msg = "service id provided together with embedded data"
            raise ValueError(msg)

        return self


class LazyBytesService(ABC):
    def __init__(self):
        self.tempfile_dir = settings.tempfile_dir
        if self.tempfile_dir:
            self.tempfile_dir.mkdir(parents=True, exist_ok=True)

    def from_bytes(self, data: bytes) -> LazyBytes:
        """Stores the given data in this service."""
        if len(data) <= settings.lazy_threshold_bytes:
            return LazyBytes(embedded_data=data)

        service_id = self._store(BytesIO(data))
        return LazyBytes(service_id=service_id)

    def from_generator(
        self, data: Generator[bytes, None, None], data_len: int | None = None
    ) -> LazyBytes:
        """Stores the given data in this service."""
        if data_len is not None and data_len <= settings.lazy_threshold_bytes:
            return LazyBytes(
                embedded_data=bytes(int.from_bytes(b, byteorder="little") for b in data)
            )

        # buffer generator into temporary file
        with TemporaryFile(dir=self.tempfile_dir) as tmp:
            for i in data:
                tmp.write(i)

            tmp.flush()
            tmp.seek(0)
            return self.from_file(tmp)

    def from_file(self, fd: BinaryIO | IO[bytes]) -> LazyBytes:
        """Stores the given data in this service."""
        # get filesize without calling .fileno()
        # -> calling .fileno will have the effect that
        #    python's SpooledTemporaryFiles are written to disk
        curr = fd.tell()
        fd.seek(0, SEEK_END)
        fd_size = fd.tell()
        fd.seek(0, curr)

        if fd_size <= settings.lazy_threshold_bytes:
            return LazyBytes(embedded_data=fd.read())

        service_id = self._store(fd)
        return LazyBytes(service_id=service_id)

    @abstractmethod
    def _store(self, data: IO) -> Any:
        """Stores the data in the service returning a service id."""

    @abstractmethod
    def flush(self):
        """Flush the data in the service."""

    @abstractmethod
    def _load_to(self, service_id: Any, dst: IO):
        """Loads the data at the given service id to dst."""

    @abstractmethod
    def _load_to_generator(self, service_id: Any) -> Generator[bytes, None, None]:
        """Loads the data to the generator."""

    @contextmanager
    def _load_mmap(self, service_id: Any) -> Generator[mmap, None, None]:
        with TemporaryFile(dir=self.tempfile_dir) as dst:
            self._load_to(service_id, dst)
            # we flush here, because we have no guarantee that
            # the override of load_to called it.
            dst.flush()

            with mmap(dst.fileno(), 0, prot=PROT_READ) as mmap_memory:
                yield mmap_memory

    # Pylint contextmanager cleanup is a false positive
    # ref: https://github.com/pylint-dev/pylint/issues/9625
    @contextmanager
    def load_memoryview(  # pylint: disable=contextmanager-generator-missing-cleanup
        self, lazy_bytes: LazyBytes
    ) -> Generator[memoryview, None, None]:
        # pylint: disable=protected-access
        def yield_release(
            memview: memoryview,
        ) -> Generator[memoryview, None, None]:
            try:
                yield memview
            finally:
                memview.release()

        if lazy_bytes.embedded_data is not None:
            # using a loop here because of a pylint bug
            # ref: https://github.com/pylint-dev/pylint/issues/9252
            for x in yield_release(  # pylint: disable=use-yield-from
                memoryview(lazy_bytes.embedded_data)
            ):
                yield x
            # better:
            # yield from yield_release(memoryview(lazy_bytes.embedded_data))
        else:
            with self._load_mmap(lazy_bytes.service_id) as mmap_memory:
                # using a loop here because of a pylint bug
                # ref: https://github.com/pylint-dev/pylint/issues/9252
                for x in yield_release(  # pylint: disable=use-yield-from
                    memoryview(mmap_memory)
                ):
                    yield x
                # better:
                # yield from yield_release(memoryview(mmap_memory))

    @contextmanager
    def load_generator(
        self, lazy_bytes: LazyBytes
    ) -> Generator[Generator[bytes, None, None], None, None]:
        # pylint: disable=protected-access
        if lazy_bytes.embedded_data is not None:
            embedded_data = (
                lazy_bytes.embedded_data
            )  # Capture to preserve type narrowing

            def _embedded_data_generator():
                yield embedded_data

            yield _embedded_data_generator()
        else:
            yield self._load_to_generator(lazy_bytes.service_id)

    @contextmanager
    def load_file(
        self, lazy_bytes: LazyBytes
    ) -> Generator[SpooledTemporaryFile[bytes], None, None]:
        # pylint: disable=protected-access
        #
        # Note do NOT use the following here:
        #
        # with self.load_memoryview(lazy_bytes) as memory:
        #     yield BytesIO(memory)
        #
        # I did quite a lot of experimentation and it looks that
        # BytesIO always copies the bytes given into an internal
        # buffer, even if it could just do copy on write.
        # There is this:
        # - https://bugs.python.org/issue22003
        # but I don't think that was every implemented and/or
        # can be used here.
        with SpooledTemporaryFile(
            max_size=settings.lazy_threshold_bytes, dir=str(self.tempfile_dir)
        ) as dst:
            if lazy_bytes.embedded_data is not None:
                dst.write(lazy_bytes.embedded_data)
            else:
                self._load_to(lazy_bytes.service_id, dst)

            dst.flush()
            dst.seek(0)
            yield dst

    @contextmanager
    def load_file_named(
        self,
        lazy_bytes: LazyBytes,
        prefix: str | None = None,
        suffix: str | None = None,
    ) -> Generator[_TemporaryFileWrapper, None, None]:
        # pylint: disable=protected-access
        #
        # Note do NOT use the following here:
        #
        # with self.load_memoryview(lazy_bytes) as memory:
        #     yield BytesIO(memory)
        #
        # I did quite a lot of experimentation and it looks that
        # BytesIO always copies the bytes given into an internal
        # buffer, even if it could just do copy on write.
        # There is this:
        # - https://bugs.python.org/issue22003
        # but I don't think that was every implemented and/or
        # can be used here.
        with NamedTemporaryFile(
            prefix=prefix, suffix=suffix, dir=str(self.tempfile_dir)
        ) as dst:
            if lazy_bytes.embedded_data is not None:
                dst.write(lazy_bytes.embedded_data)
            else:
                self._load_to(lazy_bytes.service_id, dst)

            dst.flush()
            dst.seek(0)
            yield dst


class GridFSLazyBytesService(LazyBytesService):
    def __init__(self, database: Database):
        super().__init__()
        self._database = database
        self._bucket = GridFSBucket(database)

    def _store(self, data: IO) -> Any:
        id_ = self._bucket.upload_from_stream(
            # We leave the filename empty in the upload because
            # this service is only concerned by the data itself.
            # Two writes to the same filename (in this case the
            # empty string) does not mean that data will be
            # overwritten in GridFS.
            "",
            data,
        )
        return id_

    def _load_to(self, service_id: Any, dst: IO):
        self._bucket.download_to_stream(service_id, dst)

    def _load_to_generator(self, service_id: Any) -> Generator[bytes, None, None]:
        with self._bucket.open_download_stream(service_id) as stream:
            yield from chunked_iterator_for_stream(stream)

    def flush(self):
        # Deletes lazybytes assuming they are no longer used because it's only
        # only called once the system is idle.
        # To prevent deleting of incomplete uploads we check if the number of
        # chunks is what we expect.
        # If a file is older than one hour it is deleted regardless.
        now = datetime.now()
        one_minute_ago = now - timedelta(minutes=1)
        one_hour_ago = now - timedelta(hours=1)

        query = {"uploadDate": {"$lt": one_minute_ago}}
        files_to_delete = self._bucket.find(query)

        for file in files_to_delete:
            file_id = file._id  # pylint: disable=protected-access

            if file.length > file.chunk_size and file.upload_date > one_hour_ago:
                # file has many chunks and was recently uploaded, might still be uploading:
                expected_chunks = ceil(file.length / file.chunk_size)
                actual_chunks = self._database.fs.chunks.count_documents(
                    {"files_id": file_id}
                )

                if actual_chunks < expected_chunks:
                    # not all chunks uploaded yet: skip delete
                    continue

            self._bucket.delete(file_id)


class InMemoryLazyBytesService(LazyBytesService):
    """All in-memory lazybytes service for testing.
    **!!DO NOT USE THIS IN PRODUCTION!!**.
    """
    def __init__(self):
        super().__init__()
        self._storage = []

    def _store(self, data: IO) -> Any:
        service_id = len(self._storage)
        self._storage.append(data.read())
        return service_id

    def _load_to(self, service_id: Any, dst: IO):
        dst.write(self._storage[service_id])

    def _load_to_generator(self, service_id: Any) -> Generator[bytes, None, None]:
        yield self._storage[service_id]

    def flush(self):
        self._storage = []

# Import necessary modules
import sys
from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter

def fill_pdf_fields(input_pdf_path: str, fields_json_path: str, output_pdf_path: str):
    # Load field data from JSON file
    with open(fields_json_path) as f:
        fields = json.load(f)

    # Organize fields by page
    fields_by_page = {}
    for field in fields:
        if "value" in field:
            field_id = field["field_id"]
            page = field["page"]
            if page not in fields_by_page:
                fields_by_page[page] = {}
            fields_by_page[page][field_id] = field["value"]

    # Read input PDF and validate fields
    reader = PdfReader(input_pdf_path)
    has_error = False

    field_info = get_field_info(reader)
    fields_by_ids = {f["field_id"]: f for f in field_info}

    for field in fields:
        existing_field = fields_by_ids.get(field["field_id"])

        # Check if field exists
        if not existing_field:
            has_error = True
            print(f"ERROR: `{field['field_id']}` is not a valid field ID")
        # Check if page number matches
        elif field["page"] != existing_field["page"]:
            has_error = True
            print(
                f"ERROR: Incorrect page number for `{field['field_id']}` (got {field['page']}, expected {existing_field['page']})"
            )
        else:
            # Validate field value if present
            if "value" in field:
                err = validation_error_for_field_value(existing_field, field["value"])
                if err:
                    print(err)
                    has_error = True

    # Exit with error if any validation failed
    if has_error:
        sys.exit(1)

    # Fill form fields and write output PDF
    writer = PdfWriter(clone_from=reader)
    for page, field_values in fields_by_page.items():
        writer.update_page_form_field_values(writer.pages[page - 1], field_values, auto_regenerate=False)

    writer.set_need_appearances_writer(True)

    with open(output_pdf_path, "wb") as f:
        writer.write(f)

def validation_error_for_field_value(field_info, field_value):
    field_type = field_info["type"]
    field_id = field_info["field_id"]

    if field_type == "checkbox":
        checked_val = field_info["checked_value"]
        unchecked_val = field_info["unchecked_value"]
        if field_value != checked_val and field_value != unchecked_val:
            return f'ERROR: Invalid value "{field_value}" for checkbox field "{field_id}". The checked value is "{checked_val}" and the unchecked value is "{unchecked_val}"'

    elif field_type == "radio_group":
        option_values = [opt["value"] for opt in field_info["radio_options"]]
        if field_value not in option_values:
            return f'ERROR: Invalid value "{field_value}" for radio group field "{field_id}". Valid values are: {option_values}'

    elif field_type == "choice":
        choice_values = [opt["value"] for opt in field_info["choice_options"]]
        if field_value not in choice_values:
            return (
                f'ERROR: Invalid value "{field_value}" for choice field "{field_id}". Valid values are: {choice_values}'
            )

    return None

def monkeypatch_pydpf_method():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject

    original_get_inherited = DictionaryObject.get_inherited

    def patched_get_inherited(self, key: str, default=None):
        result = original_get_inherited(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in result)
        ):
            result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = patched_get_inherited

if __name__ == "__main__":
    # Check command line arguments
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    # Apply monkey patch and run main function
    monkeypatch_pydpf_method()
    input_pdf = sys.argv[1]
    fields_json = sys.argv[2]
    output_pdf = sys.argv[3]
    fill_pdf_fields(input_pdf, fields_json, output_pdf)

