    obs_bufs: Optional[Union[dict, tuple, ShArray]] = None,
) -> None:
    """
    Worker process for subprocess-based vectorized environments.
    Handles communication between parent and child processes via pipes.
    """

    def _encode_obs(
        obs: Union[dict, tuple, np.ndarray], buffer: Union[dict, tuple, ShArray]
    ) -> None:
        """Encode observation into shared memory buffers if provided."""
        if isinstance(obs, np.ndarray) and isinstance(buffer, ShArray):
            buffer.save(obs)
        elif isinstance(obs, tuple) and isinstance(buffer, tuple):
            for o, b in zip(obs, buffer):
                _encode_obs(o, b)
        elif isinstance(obs, dict) and isinstance(buffer, dict):
            for k in obs.keys():
                _encode_obs(obs[k], buffer[k])
        return None

    # Close parent end of pipe in worker process
    parent.close()
    env = env_fn_wrapper.data()

    try:
        while True:
            try:
                cmd, data = p.recv()
            except EOFError:
                # Pipe closed; exit loop
                p.close()
                break

            if cmd == "step":
                env_return = env.step(data)
                if obs_bufs is not None:
                    _encode_obs(env_return[0], obs_bufs)
                    env_return = (None, *env_return[1:])
                p.send(env_return)

            elif cmd == "reset":
                retval = env.reset(**data)
                reset_returns_info = (
                    isinstance(retval, (tuple, list))
                    and len(retval) == 2
                    and isinstance(retval[1], dict)
                )
                if reset_returns_info:
                    obs, info = retval
                else:
                    obs = retval

                if obs_bufs is not None:
                    _encode_obs(obs, obs_bufs)
                    obs = None

                if reset_returns_info:
                    p.send((obs, info))
                else:
                    p.send(obs)

            elif cmd == "close":
                p.send(env.close())
                p.close()
                break

            elif cmd == "render":
                p.send(env.render(**data) if hasattr(env, "render") else None)

            elif cmd == "seed":
                if hasattr(env, "seed"):
                    p.send(env.seed(data))
                else:
                    env.reset(seed=data)
                    p.send(None)

            elif cmd == "getattr":
                p.send(getattr(env, data) if hasattr(env, data) else None)

            elif cmd == "setattr":
                setattr(env.unwrapped, data["key"], data["value"])

            elif cmd == "check_success":
                p.send(env.check_success())

            elif cmd == "get_segmentation_of_interest":
                p.send(env.get_segmentation_of_interest(data))

            elif cmd == "get_sim_state":
                p.send(env.get_sim_state())

            elif cmd == "set_init_state":
                obs = env.set_init_state(data)
                p.send(obs)

            elif cmd == "reconfigure":
                env.close()
                seed = data.pop("seed")
                env = OffScreenRenderEnv(**data)
                env.seed(seed)
                p.send(None)

            else:
                p.close()
                raise NotImplementedError(f"Unknown command: {cmd}")

    except KeyboardInterrupt:
        p.close()


class ReconfigureSubprocEnvWorker(SubprocEnvWorker):
    """Extension of SubprocEnvWorker that supports dynamic reconfiguration."""

    def __init__(self, env_fn: Callable[[], gym.Env], share_memory: bool = False):
        ctx = multiprocessing.get_context("spawn")
        self.parent_remote, self.child_remote = ctx.Pipe()
        self.share_memory = share_memory
        self.buffer: Optional[Union[dict, tuple, ShArray]] = None

        if self.share_memory:
            dummy = env_fn()
            obs_space = dummy.observation_space
            dummy.close()
            del dummy
            self.buffer = _setup_buf(obs_space)

        args = (
            self.parent_remote,
            self.child_remote,
            CloudpickleWrapper(env_fn),
            self.buffer,
        )
        self.process = ctx.Process(target=_worker, args=args, daemon=True)
        self.process.start()
        self.child_remote.close()
        EnvWorker.__init__(self, env_fn)

    def reconfigure_env_fn(self, env_fn_param):
        """Send reconfiguration request to the subprocess."""
        self.parent_remote.send(["reconfigure", env_fn_param])
        return self.parent_remote.recv()


class ReconfigureSubprocEnv(SubprocVectorEnv):
    """Vectorized environment with support for dynamic reconfiguration."""

    def __init__(self, env_fns: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def worker_fn(fn: Callable[[], gym.Env]) -> ReconfigureSubprocEnvWorker:
            return ReconfigureSubprocEnvWorker(fn, share_memory=False)

        BaseVectorEnv.__init__(self, env_fns, worker_fn, **kwargs)

    def reconfigure_env_fns(self, env_fns, id=None):
        """Reconfigure specific environments by index."""
        self._assert_is_not_closed()
        id = self._wrap_id(id)
        if self.is_async:
            self._assert_id(id)
        for j, i in enumerate(id):
            self.workers[i].reconfigure_env_fn(env_fns[j])

# Import necessary modules for metadata handling, type checking, and version management
import importlib.metadata
from typing import TYPE_CHECKING
from packaging import version

# Local imports
from .base import HfQuantizer

# Type checking block for forward references
if TYPE_CHECKING:
    from ..modeling_utils import PreTrainedModel

# Utility imports for acceleration, quantization libraries, and logging
from ..utils import is_accelerate_available, is_auto_awq_available, is_torch_available, logging
from ..utils.quantization_config import AWQLinearVersion

# Conditional import for PyTorch
if is_torch_available():
    import torch

# Initialize logger
logger = logging.get_logger(__name__)


class AwqQuantizer(HfQuantizer):
    """
    4-bit quantization for Activation-aware Weight Quantization(AWQ) (https://arxiv.org/abs/2306.00978)
    """

    # AWQ requires data calibration - we support only inference
    requires_calibration = True
    required_packages = ["awq", "accelerate"]

    def __init__(self, quantization_config, **kwargs):
        super().__init__(quantization_config, **kwargs)

    def validate_environment(self, device_map, **kwargs):
        # Check GPU availability
        if not torch.cuda.is_available():
            raise RuntimeError("GPU is required to run AWQ quantized model.")

        # Verify auto-awq library is installed
        if not is_auto_awq_available():
            raise ImportError("Loading an AWQ quantized model requires auto-awq library (`pip install autoawq`)")

        # Verify accelerate library is installed
        if not is_accelerate_available():
            raise ImportError("Loading an AWQ quantized model requires accelerate (`pip install accelerate`)")

        # Handle device map warnings/errors
        if device_map is None:
            logger.warning_once(
                "You have loaded an AWQ model on CPU and have a CUDA device available, make sure to set "
                "your model on a GPU device in order to run your model."
            )
        elif device_map is not None:
            # Ensure no CPU/disk devices are present in device_map
            if isinstance(device_map, dict) and ("cpu" in device_map.values() or "disk" in device_map.values()):
                raise ValueError(
                    "You are attempting to load an AWQ model with a device_map that contains a CPU or disk device."
                    " This is not supported. Please remove the CPU or disk device from the device_map."
                )

    def update_torch_dtype(self, torch_dtype):
        # Set default dtype to float16 if not specified
        if torch_dtype is None:
            torch_dtype = torch.float16
        elif torch_dtype != torch.float16:
            logger.warning("We suggest you to set `torch_dtype=torch.float16` for better efficiency with AWQ.")
        return torch_dtype

    def _process_model_before_weight_loading(self, model: "PreTrainedModel", **kwargs):
        # Import internal integration utilities
        from ..integrations import get_keys_to_not_convert, replace_quantization_scales, replace_with_awq_linear

        # Configure modules to exclude from quantization
        self.modules_to_not_convert = get_keys_to_not_convert(model)
        if self.quantization_config.modules_to_not_convert is not None:
            self.modules_to_not_convert.extend(self.quantization_config.modules_to_not_convert)

        # Perform linear layer replacement with AWQ equivalents
        model, has_been_replaced = replace_with_awq_linear(
            model, quantization_config=self.quantization_config, modules_to_not_convert=self.modules_to_not_convert
        )

        # Apply scale replacements based on model type
        model = replace_quantization_scales(model, model.config.model_type)

        # Warn if no linear modules were replaced
        if not has_been_replaced:
            logger.warning(
                "You are loading an AWQ model but no linear modules were found in your model."
                " Please double check your model architecture, or submit an issue on github if you think this is a bug."
            )

    def _process_model_after_weight_loading(self, model):
        # Fuse AWQ modules if requested
        if self.quantization_config.do_fuse:
            from ..integrations import fuse_awq_modules
            model = fuse_awq_modules(model, self.quantization_config)
            model._awq_is_fused = True  # TODO: consider storing this flag in model.config instead

        # Handle Exllama backend post-initialization
        if self.quantization_config.version == AWQLinearVersion.EXLLAMA:
            from ..integrations import post_init_awq_exllama_modules
            model = post_init_awq_exllama_modules(model, self.quantization_config.exllama_config)

    @property
    def is_serializable(self):
        # AWQ through auto-awq has been always serializable, except if the model is fused.
        if self.quantization_config.do_fuse:
            logger.warning("You cannot save an AWQ model that uses fused modules!")
            return False

        if self.quantization_config.version == AWQLinearVersion.EXLLAMA:
            logger.warning("You cannot save an AWQ model that uses Exllama backend!")
            return False

        return True

    @property
    def is_trainable(self):
        # AWQ supports PEFT fine-tuning from version 0.2.0
        MIN_AWQ_VERSION_FOR_PEFT = "0.2.0"
        return version.parse(importlib.metadata.version("autoawq")) >= version.parse(MIN_AWQ_VERSION_FOR_PEFT)

import inspect
from inspect import cleandoc, getdoc, getfile, isclass, ismodule, signature
from typing import Any, Collection, Iterable, Optional, Tuple, Type, Union

from .console import Group, RenderableType
from .control import escape_control_codes
from .highlighter import ReprHighlighter
from .jupyter import JupyterMixin
from .panel import Panel
from .pretty import Pretty
from .table import Table
from .text import Text, TextType


def _first_paragraph(doc: str) -> str:
    """Get the first paragraph from a docstring."""
    paragraph, _, _ = doc.partition("\n\n")
    return paragraph


class Inspect(JupyterMixin):
    """A renderable to inspect any Python Object.

    Args:
        obj (Any): An object to inspect.
        title (str, optional): Title to display over inspect result, or None use type. Defaults to None.
        help (bool, optional): Show full help text rather than just first paragraph. Defaults to False.
        methods (bool, optional): Enable inspection of callables. Defaults to False.
        docs (bool, optional): Also render doc strings. Defaults to True.
        private (bool, optional): Show private attributes (beginning with underscore). Defaults to False.
        dunder (bool, optional): Show attributes starting with double underscore. Defaults to False.
        sort (bool, optional): Sort attributes alphabetically. Defaults to True.
        all (bool, optional): Show all attributes. Defaults to False.
        value (bool, optional): Pretty print value of object. Defaults to True.
    """

    def __init__(
        self,
        obj: Any,
        *,
        title: Optional[TextType] = None,
        help: bool = False,
        methods: bool = False,
        docs: bool = True,
        private: bool = False,
        dunder: bool = False,
        sort: bool = True,
        all: bool = True,
        value: bool = True,
    ) -> None:
        self.highlighter = ReprHighlighter()
        self.obj = obj
        self.title = title or self._make_title(obj)

        if all:
            methods = private = dunder = True

        self.help = help
        self.methods = methods
        self.docs = docs or help
        self.private = private or dunder
        self.dunder = dunder
        self.sort = sort
        self.value = value

    def _make_title(self, obj: Any) -> Text:
        """Make a default title."""
        title_str = (
            str(obj)
            if (isclass(obj) or callable(obj) or ismodule(obj))
            else str(type(obj))
        )
        title_text = self.highlighter(title_str)
        return title_text

    def __rich__(self) -> Panel:
        return Panel.fit(
            Group(*self._render()),
            title=self.title,
            border_style="scope.border",
            padding=(0, 1),
        )

    def _get_signature(self, name: str, obj: Any) -> Optional[Text]:
        """Get a signature for a callable."""
        try:
            _signature = str(signature(obj)) + ":"
        except ValueError:
            _signature = "(...)"
        except TypeError:
            return None

        source_filename: Optional[str] = None
        try:
            source_filename = getfile(obj)
        except (OSError, TypeError):
            # OSError is raised if obj has no source file, e.g. when defined in REPL.
            pass

        callable_name = Text(name, style="inspect.callable")
        if source_filename:
            callable_name.stylize(f"link file://{source_filename}")

        signature_text = self.highlighter(_signature)
        qualname = name or getattr(obj, "__qualname__", name)

        # If obj is a module, there may be classes (which are callable) to display
        if inspect.isclass(obj):
            prefix = "class"
        elif inspect.iscoroutinefunction(obj):
            prefix = "async def"
        else:
            prefix = "def"

        qual_signature = Text.assemble(
            (f"{prefix} ", f"inspect.{prefix.replace(' ', '_')}"),
            (qualname, "inspect.callable"),
            signature_text,
        )
        return qual_signature

    def _render(self) -> Iterable[RenderableType]:
        """Render object."""

        def sort_items(item: Tuple[str, Any]) -> Tuple[bool, str]:
            key, (_error, value) = item
            return (callable(value), key.strip("_").lower())

        def safe_getattr(attr_name: str) -> Tuple[Any, Any]:
            """Get attribute or any exception."""
            try:
                return (None, getattr(obj, attr_name))
            except Exception as error:
                return (error, None)

        obj = self.obj
        keys = dir(obj)
        total_items = len(keys)

        if not self.dunder:
            keys = [key for key in keys if not key.startswith("__")]
        if not self.private:
            keys = [key for key in keys if not key.startswith("_")]

        not_shown_count = total_items - len(keys)
        items = [(key, safe_getattr(key)) for key in keys]

        if self.sort:
            items.sort(key=sort_items)

        items_table = Table.grid(padding=(0, 1), expand=False)
        items_table.add_column(justify="right")
        add_row = items_table.add_row
        highlighter = self.highlighter

        if callable(obj):
            signature = self._get_signature("", obj)
            if signature is not None:
                yield signature
                yield ""

        if self.docs:
            _doc = self._get_formatted_doc(obj)
            if _doc is not None:
                doc_text = Text(_doc, style="inspect.help")
                doc_text = highlighter(doc_text)
                yield doc_text
                yield ""

        if self.value and not (isclass(obj) or callable(obj) or ismodule(obj)):
            yield Panel(
                Pretty(obj, indent_guides=True, max_length=10, max_string=60),
                border_style="inspect.value.border",
            )
            yield ""

        for key, (error, value) in items:
            key_text = Text.assemble(
                (
                    key,
                    "inspect.attr.dunder" if key.startswith("__") else "inspect.attr",
                ),
                (" =", "inspect.equals"),
            )
            if error is not None:
                warning = key_text.copy()
                warning.stylize("inspect.error")
                add_row(warning, highlighter(repr(error)))
                continue

            if callable(value):
                if not self.methods:
                    continue

                _signature_text = self._get_signature(key, value)
                if _signature_text is None:
                    add_row(key_text, Pretty(value, highlighter=highlighter))
                else:
                    if self.docs:
                        docs = self._get_formatted_doc(value)
                        if docs is not None:
                            _signature_text.append("\n" if "\n" in docs else " ")
                            doc = highlighter(docs)
                            doc.stylize("inspect.doc")
                            _signature_text.append(doc)

                    add_row(key_text, _signature_text)
            else:
                add_row(key_text, Pretty(value, highlighter=highlighter))

        if items_table.row_count:
            yield items_table
        elif not_shown_count:
            yield Text.from_markup(
                f"[b cyan]{not_shown_count}[/][i] attribute(s) not shown.[/i] "
                f"Run [b][magenta]inspect[/]([not b]inspect[/])[/b] for options."
            )

    def _get_formatted_doc(self, object_: Any) -> Optional[str]:
        """
        Extract the docstring of an object, process it and returns it.
        The processing consists in cleaning up the doctring's indentation,
        taking only its 1st paragraph if `self.help` is not True,
        and escape its control codes.

        Args:
            object_ (Any): the object to get the docstring from.

        Returns:
            Optional[str]: the processed docstring, or None if no docstring was found.
        """
        docs = getdoc(object_)
        if docs is None:
            return None

        docs = cleandoc(docs).strip()
        if not self.help:
            docs = _first_paragraph(docs)

        return escape_control_codes(docs)


def get_object_types_mro(obj: Union[object, Type[Any]]) -> Tuple[type, ...]:
    """Returns the MRO of an object's class, or of the object itself if it's a class."""
    if not hasattr(obj, "__mro__"):
        # N.B. we cannot use `if type(obj) is type` here because it doesn't work with
        # some types of classes, such as the ones that use abc.ABCMeta.
        obj = type(obj)
    return getattr(obj, "__mro__", ())


def get_object_types_mro_as_strings(obj: object) -> Collection[str]:
    """
    Returns the MRO of an object's class as full qualified names, or of the object itself if it's a class.
    Examples:
        `object_types_mro_as_strings(JSONDecoder)` will return `['json.decoder.JSONDecoder', 'builtins.object']`
    """
    return [
        f'{getattr(type_, "__module__", "")}.{getattr(type_, "__qualname__", "")}'
        for type_ in get_object_types_mro(obj)
    ]


def is_object_one_of_types(
    obj: object, fully_qualified_types_names: Collection[str]
) -> bool:
    """
    Returns `True` if the given object's class (or the object itself, if it's a class) has one of the
    fully qualified names in its MRO.
    """
    for type_name in get_object_types_mro_as_strings(obj):
        if type_name in fully_qualified_types_names:
            return True
    return False

import torch
import habana_frameworks.torch.core as htcore
import habana_frameworks.torch.utils.experimental as htexp

# Check if device is Gaudi2
is_hpu_gaudi2 = htexp._get_device_type() == htexp.synDeviceType.synDeviceGaudi2


def get_hpu_gaudi2_scale_factor():
    return (torch.finfo(torch.float8_e4m3fn).max / torch.finfo(torch.float8_e4m3fnuz).max)


# Exponent width configuration for different dtypes
EXP_WIDTH = {
    torch.float32: 8,
    torch.bfloat16: 8,
    torch.float8_e4m3fn: 4,
    torch.float8_e5m2: 5,
}


def get_default_exp_bias(dtype):
    exp_width = EXP_WIDTH[dtype]
    return 2**(exp_width - 1) - 1


# Supported exponent bias sets per device and dtype
EXP_BIAS_SETS = {
    ("GAUDI2", torch.float8_e4m3fn): [3, 7, 11, 15],
    ("GAUDI2", torch.float8_e5m2): [15],
    ("GAUDI3", torch.float8_e4m3fn): range(0, 63),
    ("GAUDI3", torch.float8_e5m2): range(0, 63),
}


# Maximum representable values for various dtypes
MAX_RANGE = {
    torch.float32: torch.finfo(torch.float32).max,
    torch.bfloat16: torch.finfo(torch.bfloat16).max,
    torch.float8_e4m3fn: torch.finfo(torch.float8_e4m3fn).max,
    # float8_e4m3fn data type is 8-bit floating point consist of Exponent: 4, Mantissa: 3, bias: 7. It's supported by Gaudi3.
    torch.float8_e5m2: torch.finfo(torch.float8_e5m2).max
    # float8_e5m2 data type is 8-bit floating point consist of Exponent: 5, Mantissa: 2, bias: 15. IEEE 754, with NaN and inf.
}

# Handle optional float8_e4m3fnuz dtype (only available on Gaudi2)
try:
    MAX_RANGE[torch.float8_e4m3fnuz] = torch.finfo(torch.float8_e4m3fnuz).max
    # float8_e4m3fnuz data type is 8-bit floating point consist of Exponent: 4, Mantissa: 3, bias: 8 with 1 sign bit. It's supported by Gaudi2.
except AttributeError as e:
    pass


def get_fullscale(dtype, device, exp_bias=None):
    default_exp_bias = get_default_exp_bias(dtype)
    fullscale = 1

    # Special handling for GAUDI2 with float8_e4m3fn
    if device == "GAUDI2" and dtype == torch.float8_e4m3fn:
        try:
            fullscale = MAX_RANGE[torch.float8_e4m3fnuz]
        except AttributeError:
            pass
    else:
        fullscale = MAX_RANGE[dtype]

    # Use provided exp_bias or default
    exp_bias = default_exp_bias if exp_bias is None else exp_bias

    # Adjust fullscale based on exponent bias difference
    fullscale = fullscale * (2**(default_exp_bias - exp_bias))
    return float(fullscale)


def get_fullscales_by_expbias_set(dtype, device, expbias_set):
    return [get_fullscale(dtype, device, exp_bias=eb) for eb in expbias_set]


def get_fp8_hw_alligned_scales(dtype, device):
    exp_bias_set = EXP_BIAS_SETS.get((device, dtype), None)
    if exp_bias_set is None:
        return None
    return [x / get_fullscale(dtype, device) for x in get_fullscales_by_expbias_set(dtype, device, exp_bias_set)]


# Device-specific scale factors
DEVICES_SCALE_FACTORS = {
    "GAUDI2": 4,
    "GAUDI3": 1,
}

# Precompute FP8_143 scales for each device
FP8_143_SCALES = {
    device: get_fp8_hw_alligned_scales(torch.float8_e4m3fn, device)
    for device in DEVICES_SCALE_FACTORS.keys()
}

# Extract min/max scale and scale factor traits per device
FP8_143_SCALES_TRAITS = {
    device: (
        min(FP8_143_SCALES[device]),
        max(FP8_143_SCALES[device]),
        DEVICES_SCALE_FACTORS[device],
    )
    for device in DEVICES_SCALE_FACTORS.keys()
}


class ScaleToPow2:
    def calc(self, scale):
        scale_pow2 = 2.0**torch.ceil(torch.log2(scale))
        return scale_pow2


class ConvertScaleToHwAligned:
    def __init__(self, device_type="GAUDI3"):
        self.device_type = "GAUDI2" if is_hpu_gaudi2 else "GAUDI3"

    def calc(self, scale):
        # Apply Gaudi2-specific scaling factor if needed
        if self.device_type == "GAUDI2":
            scale = scale * get_hpu_gaudi2_scale_factor()

        # Convert to nearest power of 2 ceiling
        scale_pow2 = ScaleToPow2().calc(scale)

        # Get hardware constraints
        min_scale, max_scale, scale_factor = FP8_143_SCALES_TRAITS[self.device_type]

        # Clamp the scaled value within hardware limits and align to scale_factor boundaries
        scale_pow2_hw = torch.minimum(
            torch.maximum(
                2.0**(torch.ceil(torch.log2(scale_pow2) / scale_factor) * scale_factor),
                torch.tensor(min_scale, dtype=scale.dtype, device=scale.device),
            ),
            torch.tensor(max_scale, dtype=scale.dtype, device=scale.device),
        )
        return scale_pow2_hw

import uuid
from datetime import UTC, datetime
from alphatrion.runtime.contextvars import current_run_id
from alphatrion.runtime.runtime import global_runtime
from alphatrion.storage.sql_models import Status
from alphatrion.types import CallableEntry


class Run:
    __slots__ = ("_id", "_task", "_runtime", "_exp_id", "_result")

    def __init__(self, exp_id: uuid.UUID):
        self._runtime = global_runtime()
        self._exp_id = exp_id
        self._result = None

    @property
    def id(self) -> uuid.UUID:
        return self._id

    @property
    def result(self) -> any:
        return self._result

    def _get_obj(self):
        return self._runtime.metadb.get_run(run_id=self._id)

    def start(self, call_func: CallableEntry) -> None:
        self._id = self._runtime.metadb.create_run(
            team_id=self._runtime.team_id,
            user_id=self._runtime.user_id,
            experiment_id=self._exp_id,
            status=Status.RUNNING,
        )

        # current_run_id context var is used in tracing workflow/task decorators.
        # exp.run() will be called sequentially, so it's safe to set the context var.
        token = current_run_id.set(self.id)

        try:
            # The created task will also inherit the current context,
            # including the current_exp_id, current_run_id context var.
            self._task = asyncio.create_task(call_func())
        finally:
            current_run_id.reset(token)

    def done(self):
        # Callback will always be called even if the run is cancelled.
        # Make sure we don't update the status if it's already cancelled.
        if self.cancelled():
            return

        run = self._runtime._metadb.get_run(run_id=self.id)
        duration = (
            datetime.now(UTC) - run.created_at.replace(tzinfo=UTC)
        ).total_seconds()

        self._runtime.metadb.update_run(
            run_id=self._id, status=Status.COMPLETED, duration=duration
        )
        self._result = self._task.result()

    def cancel(self):
        # TODO: we should wait for the task to be actually cancelled
        # and catch the CancelledError exception in the task function.
        self._task.cancel()

        run = self._runtime._metadb.get_run(run_id=self.id)
        duration = (
            datetime.now(UTC) - run.created_at.replace(tzinfo=UTC)
        ).total_seconds()

        self._runtime.metadb.update_run(
            run_id=self._id, status=Status.CANCELLED, duration=duration
        )

    def cancelled(self) -> bool:
        return self._task.cancelled()

    async def wait(self):
        await self._task

    def add_done_callback(self, callbacks: callable):
        self._task.add_done_callback(callbacks)

import torch.fx as fx
from graph_net.torch.dim_gen_passes import DimensionGeneralizationPass
from collections import namedtuple
import os


class ConcretePass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def get_pass_name(cls) -> bool:
        return os.path.basename(__file__)[:-3]

    def need_rewrite(self, traced_module: fx.GraphModule) -> bool:
        # non batch
        if 0 in self.axes:
            return False
        return any(self._node_need_rewrite(node) for node in traced_module.graph.nodes)

    def node_target(self):
        return torch.full

    def _node_need_rewrite(self, node) -> bool:
        if not (node.op == "call_function"):
            return False
        if not (node.target == self.node_target()):
            return False
        if not (len(node.args) == 1):
            return False
        return any(dim == self.dim for dim in node.args[0])

    def rewrite(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Create a new graph to hold the rewritten nodes
        new_graph = fx.Graph()

        # Create a map to link nodes from the old graph to nodes in the new graph
        val_map = {}

        NodeAxis = namedtuple("NodeAxis", ["node", "shape_axis"])
        last_node_axis = None

        def try_reset_last_node_axis(node, new_node):
            nonlocal last_node_axis
            node_meta = node.meta.get("tensor_meta")
            if node_meta is None:
                return
            if not hasattr(node_meta, "shape"):
                return
            for axis, dim in enumerate(node_meta.shape):
                if not (dim == self.dim and axis > 0):
                    continue
                last_node_axis = NodeAxis(node=new_node, shape_axis=axis)
                return

        def get_new_node_dim(i, dim):
            if not (dim == self.dim):
                return val_map[dim] if dim in val_map else dim
            assert dim == self.dim
            # Use the size() method to retrieve the dynamic dimension
            size_node = new_graph.call_method(
                "size", args=(last_node_axis.node, last_node_axis.shape_axis)
            )
            return size_node

        def create_new_node(node):
            if not (self._node_need_rewrite(node) and last_node_axis is not None):
                # Copy other nodes to the new graph
                new_node = new_graph.node_copy(node, lambda x: val_map[x])
                try_reset_last_node_axis(node=node, new_node=new_node)
                return new_node

            new_node_dims = tuple(
                get_new_node_dim(i, dim) for i, dim in enumerate(node.args[0])
            )
            new_node = new_graph.call_function(
                self.node_target(), args=(new_node_dims,), kwargs=node.kwargs
            )
            return new_node

        for node in traced_module.graph.nodes:
            val_map[node] = create_new_node(node)

        # Replace the old graph with the new graph and return
        traced_module.graph = new_graph
        traced_module.recompile()
        return traced_module

