class ShellSession:
    """A shell session for a WebSocket connection"""

    def __init__(self, shell, ws):
        self.shell = shell
        self.ws = ws
        self.buffer = ""

        # Initialize completer
        from .completer import ShellCompleter
        self.completer = ShellCompleter(self.shell.filesystem)
        self.completer.shell = self.shell

    async def send(self, data: str):
        """Send data to the WebSocket"""
        if self.ws and not self.ws.closed:
            await self.ws.send_str(data)

    def get_completions(self, text: str, line: str, cursor_pos: int) -> list:
        """Get completion suggestions for the given text
        Args:
            text: The word being completed
            line: The full command line
            cursor_pos: Cursor position in the line
        Returns:
            List of completion suggestions
        """
        # Determine if we're completing a command or a path
        before_cursor = line[:cursor_pos]

        # Check if we're at the beginning (completing command)
        if not before_cursor.strip() or before_cursor.strip() == text:
            # Complete command names
            return self.completer._complete_command(text)
        else:
            # Complete paths
            return self.completer._complete_path(text)

    async def handle_command(self, command: str):
        """Execute a command and send output to WebSocket"""
        # Create a wrapper that has both text and binary interfaces
        class BufferedTextIO:
            def __init__(self):
                self.text_buffer = io.StringIO()
                self.byte_buffer = io.BytesIO()
                # Create buffer attribute for binary writes
                self.buffer = self

            def write(self, data):
                if isinstance(data, bytes):
                    self.byte_buffer.write(data)
                else:
                    self.text_buffer.write(data)
                return len(data)

            def flush(self):
                pass

            def getvalue(self):
                text = self.text_buffer.getvalue()
                binary = self.byte_buffer.getvalue()
                if binary:
                    try:
                        text += binary.decode('utf-8', errors='replace')
                    except:
                        pass
                return text

        # Capture stdout and stderr
        old_stdout = sys.stdout
        old_stderr = sys.stderr
        stdout_buffer = BufferedTextIO()
        stderr_buffer = BufferedTextIO()
        sys.stdout = stdout_buffer
        sys.stderr = stderr_buffer

        try:
            # Execute the command through shell
            exit_code = self.shell.execute(command)

            # Get output
            stdout = stdout_buffer.getvalue()
            stderr = stderr_buffer.getvalue()

            # Send output to terminal (convert \n to \r\n for terminal)
            if stdout:
                stdout_formatted = stdout.replace('\n', '\r\n')
                await self.send(stdout_formatted)

            if stderr:
                # Send stderr in red color (convert \n to \r\n)
                stderr_formatted = stderr.replace('\n', '\r\n')
                await self.send(f'\x1b[31m{stderr_formatted}\x1b[0m')

            return exit_code

        except Exception as e:
            # Send error in red
            await self.send(f'\x1b[31mError: {str(e)}\x1b[0m\r\n')
            return 1

        finally:
            sys.stdout = old_stdout
            sys.stderr = old_stderr


class WebAppServer:
    """HTTP server for the web application"""

    def __init__(self, shell, host='localhost', port=3000):
        if not AIOHTTP_AVAILABLE:
            raise ImportError(
                "aiohttp is required for web app server. "
                "Install with: uv sync --extra webapp"
            )

        self.shell = shell
        self.host = host
        self.port = port
        self.app = None
        self.runner = None
        self.sessions = {}  # WebSocket sessions

    async def handle_explorer(self, request):
        """Get directory structure for Explorer (optimized API)"""
        path = request.query.get('path', '/')

        try:
            # Use filesystem API directly for better performance
            entries = self.shell.filesystem.list_directory(path)

            # Format entries for frontend
            files = []
            for entry in entries:
                name = entry.get('name', '')
                if name and name not in ['.', '..']:
                    # AGFS API returns 'isDir' instead of 'type'
                    is_dir = entry.get('isDir', False)
                    file_type = 'directory' if is_dir else 'file'

                    files.append({
                        'name': name,
                        'path': f"{path.rstrip('/')}/{name}" if path != '/' else f"/{name}",
                        'type': file_type,
                        'size': entry.get('size', 0),
                        'mtime': entry.get('mtime', ''),
                    })

            # Sort: directories first, then by name
            files.sort(key=lambda x: (x['type'] != 'directory', x['name'].lower()))

            return web.json_response({
                'path': path,
                'files': files
            })

        except Exception as e:
            return web.json_response(
                {'error': str(e), 'path': path},
                status=500
            )

    async def handle_list_files(self, request):
        """List files in a directory (legacy, kept for compatibility)"""
        path = request.query.get('path', '/')

        try:
            # Use filesystem API directly
            entries = self.shell.filesystem.list_directory(path)
            files = []

            for entry in entries:
                name = entry.get('name', '')
                if name and name not in ['.', '..']:
                    # AGFS API returns 'isDir' instead of 'type'
                    is_dir = entry.get('isDir', False)
                    file_type = 'directory' if is_dir else 'file'

                    files.append({
                        'name': name,
                        'type': file_type
                    })

            return web.json_response({'files': files})

        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )

    async def handle_read_file(self, request):
        """Read file contents"""
        path = request.query.get('path', '')

        if not path:
            return web.json_response(
                {'error': 'Path is required'},
                status=400
            )

        try:
            # Use BufferedTextIO to handle both text and binary output
            class BufferedTextIO:
                def __init__(self):
                    self.text_buffer = io.StringIO()
                    self.byte_buffer = io.BytesIO()
                    self.buffer = self

                def write(self, data):
                    if isinstance(data, bytes):
                        self.byte_buffer.write(data)
                    else:
                        self.text_buffer.write(data)
                    return len(data)

                def flush(self):
                    pass

                def getvalue(self):
                    text = self.text_buffer.getvalue()
                    binary = self.byte_buffer.getvalue()
                    if binary:
                        try:
                            text += binary.decode('utf-8', errors='replace')
                        except:
                            pass
                    return text

            # Capture output
            old_stdout = sys.stdout
            old_stderr = sys.stderr
            stdout_buffer = BufferedTextIO()
            stderr_buffer = BufferedTextIO()
            sys.stdout = stdout_buffer
            sys.stderr = stderr_buffer

            try:
                self.shell.execute(f'cat {path}')
                content = stdout_buffer.getvalue()
            finally:
                sys.stdout = old_stdout
                sys.stderr = old_stderr

            return web.json_response({'content': content})

        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )

    async def handle_write_file(self, request):
        """Write file contents"""
        try:
            data = await request.json()
            path = data.get('path', '')
            content = data.get('content', '')

            if not path:
                return web.json_response(
                    {'error': 'Path is required'},
                    status=400
                )

            # Write file using filesystem API directly
            try:
                # Convert content to bytes
                content_bytes = content.encode('utf-8')
                # Write to filesystem
                self.shell.filesystem.write_file(path, content_bytes)
                return web.json_response({'success': True})
            except Exception as e:
                return web.json_response(
                    {'error': f'Failed to write file: {str(e)}'},
                    status=500
                )
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )

    async def handle_download_file(self, request):
        """Download file contents (for binary/non-text files)"""
        path = request.query.get('path', '')

        if not path:
            return web.json_response(
                {'error': 'Path is required'},
                status=400
            )

        try:
            # Read file using filesystem API
            content = self.shell.filesystem.read_file(path)

            # Get filename from path
            filename = path.split('/')[-1]

            # Determine content type based on extension
            import mimetypes
            content_type, _ = mimetypes.guess_type(filename)
            if content_type is None:
                content_type = 'application/octet-stream'

            # Return file with download headers
            return web.Response(
                body=content,
                headers={
                    'Content-Type': content_type,
                    'Content-Disposition': f'attachment; filename="{filename}"'
                }
            )
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )

    async def handle_copy_file(self, request):
        """Copy file from source to target"""
        try:
            data = await request.json()
            source_path = data.get('sourcePath', '')
            target_path = data.get('targetPath', '')

            if not source_path or not target_path:
                return web.json_response(
                    {'error': 'Source and target paths are required'},
                    status=400
                )

            # Read source file
            content = self.shell.filesystem.read_file(source_path)
            # Write to target
            self.shell.filesystem.write_file(target_path, content)
            return web.json_response({'success': True})

        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )

    async def handle_delete_file(self, request):
        """Delete a file or directory"""
        try:
            data = await request.json()
            path = data.get('path', '')

            if not path:
                return web.json_response(
                    {'error': 'Path is required'},
                    status=400
                )

            # Delete using filesystem API
            self.shell.filesystem.delete_file(path)
            return web.json_response({'success': True})

        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )

    async def handle_upload_file(self, request):
        """Upload a file to the filesystem"""
        try:
            reader = await request.multipart()
            directory = '/'
            file_data = None
            filename = None

            # Read multipart data
            async for field in reader:
                if field.name == 'directory':
                    directory = await field.text()
                elif field.name == 'file':
                    filename = field.filename
                    file_data = await field.read()

            if not file_data or not filename:
                return web.json_response(
                    {'error': 'No file provided'},
                    status=400
                )

            # Construct target path
            target_path = f"{directory.rstrip('/')}/{filename}" if directory != '/' else f"/{filename}"

            # Write file to filesystem
            self.shell.filesystem.write_file(target_path, file_data)
            return web.json_response({
                'success': True,
                'path': target_path
            })

        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )

    async def handle_websocket(self, request):
        """Handle WebSocket connection for terminal"""
        ws = web.WebSocketResponse()
        await ws.prepare(request)

        # Create a new shell session for this WebSocket
        session = ShellSession(self.shell, ws)
        session_id = id(ws)
        self.sessions[session_id] = session

        try:
            # Send welcome message
            from . import __version__
            await session.send(f'\x1b[32magfs-shell v{__version__} ready\x1b[0m\r\n')
            await session.send(f'\x1b[90mConnected to {self.shell.server_url}\x1b[0m\r\n')
            await session.send('$ ')

            # Handle incoming messages
            async for msg in ws:
                if msg.type == web.WSMsgType.TEXT:
                    try:
                        data = json.loads(msg.data)
                        msg_type = data.get('type')

                        if msg_type == 'command':
                            command = data.get('data', '')

                            if command.strip():
                                # Execute command
                                exit_code = await session.handle_command(command)
                                # Send new prompt
                                await session.send('$ ')
                            else:
                                # Empty command, just show prompt
                                await session.send('$ ')

                        elif msg_type == 'explorer':
                            # Get directory listing for Explorer
                            path = data.get('path', '/')

                            try:
                                entries = self.shell.filesystem.list_directory(path)

                                # Format entries
                                files = []
                                for entry in entries:
                                    name = entry.get('name', '')
                                    if name and name not in ['.', '..']:
                                        # AGFS API returns 'isDir' instead of 'type'
                                        is_dir = entry.get('isDir', False)
                                        file_type = 'directory' if is_dir else 'file'

                                        files.append({
                                            'name': name,
                                            'path': f"{path.rstrip('/')}/{name}" if path != '/' else f"/{name}",
                                            'type': file_type,
                                            'size': entry.get('size', 0),
                                            'mtime': entry.get('modTime', ''),
                                        })

                                # Sort: directories first, then by name
                                files.sort(key=lambda x: (x['type'] != 'directory', x['name'].lower()))

                                await ws.send_json({
                                    'type': 'explorer',
                                    'path': path,
                                    'files': files
                                })

                            except Exception as e:
                                await ws.send_json({
                                    'type': 'explorer',
                                    'path': path,
                                    'error': str(e),
                                    'files': []
                                })

                        elif msg_type == 'complete':
                            # Tab completion request
                            text = data.get('text', '')
                            line = data.get('line', '')
                            cursor_pos = data.get('cursor_pos', len(line))

                            try:
                                completions = session.get_completions(text, line, cursor_pos)
                                # Send completions back to client
                                await ws.send_json({
                                    'type': 'completions',
                                    'completions': completions
                                })
                            except Exception as e:
                                # Send empty completions on error
                                await ws.send_json({
                                    'type': 'completions',
                                    'completions': []
                                })

                        elif msg_type == 'resize':
                            # Terminal resize event (can be used for future enhancements)
                            pass

                    except json.JSONDecodeError:
                        # If not JSON, treat as raw command
                        await session.send('\x1b[31mInvalid message format\x1b[0m\r\n$ ')
                    except Exception as e:
                        await session.send(f'\x1b[31mError: {str(e)}\x1b[0m\r\n$ ')

                elif msg.type == web.WSMsgType.ERROR:
                    print(f'WebSocket error: {ws.exception()}')

        finally:
            # Clean up session
            if session_id in self.sessions:
                del self.sessions[session_id]

        return ws

    async def handle_static(self, request):
        """Serve static files"""
        # Serve the built React app
        webapp_dir = Path(__file__).parent.parent / 'webapp' / 'dist'
        path = request.match_info.get('path', 'index.html')

        if path == '':
            path = 'index.html'

        file_path = webapp_dir / path

        # Handle client-side routing - serve index.html for non-existent paths
        if not file_path.exists() or file_path.is_dir():
            file_path = webapp_dir / 'index.html'

        if file_path.exists() and file_path.is_file():
            return web.FileResponse(file_path)
        else:
            return web.Response(text='Not found', status=404)

    async def init_app(self):
        """Initialize the web application"""
        self.app = web.Application()

        # Setup CORS
        cors = aiohttp_cors.setup(self.app, defaults={
            "*": aiohttp_cors.ResourceOptions(
                allow_credentials=True,
                expose_headers="*",
                allow_headers="*",
            )
        })

        # API routes
        api_routes = [
            self.app.router.add_get('/api/files/list', self.handle_list_files),
            self.app.router.add_get('/api/files/read', self.handle_read_file),
            self.app.router.add_post('/api/files/write', self.handle_write_file),
            self.app.router.add_get('/api/files/download', self.handle_download_file),
            self.app.router.add_post('/api/files/copy', self.handle_copy_file),
            self.app.router.add_post('/api/files/delete', self.handle_delete_file),
            self.app.router.add_post('/api/files/upload', self.handle_upload_file),
        ]

        # WebSocket route (no CORS needed)
        self.app.router.add_get('/ws/terminal', self.handle_websocket)

        # Static files (serve React app)
        self.app.router.add_get('/', self.handle_static)
        self.app.router.add_get('/{path:.*}', self.handle_static)

        # Configure CORS for API routes only
        for route in api_routes:
            cors.add(route)

    async def start(self):
        """Start the web server"""
        await self.init_app()
        self.runner = web.AppRunner(self.app)
        await self.runner.setup()
        site = web.TCPSite(self.runner, self.host, self.port)
        await site.start()
        print(f'\n\x1b[32mWeb app server running at http://{self.host}:{self.port}\x1b[0m\n')

    async def stop(self):
        """Stop the web server"""
        # Close all WebSocket connections
        for session in list(self.sessions.values()):
            if session.ws and not session.ws.closed:
                await session.ws.close()

        if self.runner:
            await self.runner.cleanup()


def run_server(shell, host='localhost', port=3000):
    """Run the web app server"""
    server = WebAppServer(shell, host, port)
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)

    try:
        loop.run_until_complete(server.start())
        loop.run_forever()
    except KeyboardInterrupt:
        print('\n\x1b[33mShutting down...\x1b[0m')
    finally:
        loop.run_until_complete(server.stop())
        loop.close()

# Tool registry implementation for StatGPT
from collections.abc import MutableMapping
from typing import Annotated, Any, Generic, Literal, TypeVar
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes


class ToolRegistry(MutableMapping):
    def __init__(self) -> None:
        # Internal mapping to store tool factories
        self._mapping: dict[ToolTypes, type[StatGptTool]] = {}

    def __setitem__(self, tool_type: ToolTypes, factory: type['StatGptTool']) -> None:
        # Validate that factory is a subclass of StatGptTool
        if not issubclass(factory, StatGptTool):
            raise ValueError(f"{factory=} must be a subclass of {StatGptTool}")

        # Check for duplicate registration
        if tool_type in self._mapping:
            raise ValueError(
                f"Cant register {factory} factory:"
                f" {tool_type=} already registered with {self._mapping[tool_type]}"
            )

        # Register the factory
        self._mapping[tool_type] = factory

    def __delitem__(self, tool_type: ToolTypes, /):
        del self._mapping[tool_type]

    def __getitem__(self, key: ToolTypes) -> type['StatGptTool']:
        # Check if key exists in mapping
        if key not in self._mapping:
            raise KeyError(
                f"Factory has not been registered for {key} agent."
                f" Please ensure that the factory is imported in the global space."
                f"\nAvailable agents: {list(self._mapping.keys())}"
            )
        return self._mapping[key]

    def __iter__(self):
        return iter(self._mapping)

    def __len__(self):
        return len(self._mapping)


# Global tool registry instance
_TOOL_IMPLEMENTATIONS = ToolRegistry()


class ToolArgs(BaseModel):
    # Injected tool argument - set programmatically, not by LLM
    # LLM cannot set this field because it's excluded from the schema shown to LLM
    # `inputs` passes execution context from Supreme Agent to the tool
    inputs: Annotated[dict, InjectedToolArg] = Field()


ToolConfigType = TypeVar('ToolConfigType', bound=BaseToolConfig)


class StatGptTool(BaseTool, ABC, Generic[ToolConfigType]):
    # Response format configuration
    response_format: Literal['content', 'content_and_artifact'] = "content_and_artifact"

    # Tool type - set dynamically during subclass initialization
    tool_type: ToolTypes  # Set dynamically in __init_subclass__

    def __init_subclass__(cls, **kwargs):
        # Extract and validate tool_type parameter
        tool_type = kwargs.pop('tool_type', None)
        super().__init_subclass__(**kwargs)

        # Skip registration for the base class itself
        if StatGptTool in cls.__bases__:
            return

        # Validate tool_type presence and type
        if tool_type is None:
            raise ValueError(f"Subclass {cls.__name__} must specify a 'tool_type' parameter")

        if not isinstance(tool_type, ToolTypes):
            raise ValueError(f"{tool_type=} must be an instance of {ToolTypes}")

        # Register the tool implementation
        cls.tool_type = tool_type
        _TOOL_IMPLEMENTATIONS[tool_type] = cls

    def __init__(self, tool_config: ToolConfigType, channel_config: ChannelConfig, **kwargs):
        super().__init__(**kwargs)
        self._tool_config = tool_config
        self._channel_config = channel_config

    @property
    def stage_name(self) -> str:
        """Return the stage name for calling this tool."""
        if name := self._tool_config.details.stages_config.tool_call_name:
            return name

        tool_name = self.name.replace('_', ' ')
        return f"Calling {tool_name} tool"

    @property
    def result_stage_name(self) -> str:
        """Return the stage name for showing the result of this tool."""
        if name := self._tool_config.details.stages_config.tool_result_name:
            return name

        tool_name = self.name.replace('_', ' ')
        return f"Result from {tool_name} tool"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """Synchronous run method - intentionally not implemented."""
        raise NotImplementedError("This method should not be called. Use async version instead.")

    @abstractmethod
    async def _arun(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        pass

    @classmethod
    def get_args_schema(cls, tool_config: ToolConfigType) -> type[ToolArgs]:
        """Return the schema for arguments accepted by this tool."""
        return ToolArgs

    @staticmethod
    def from_config(tool_config: ToolConfigType, channel_config: ChannelConfig) -> 'StatGptTool':
        """Create a tool instance from configuration."""
        cls = _TOOL_IMPLEMENTATIONS[tool_config.type]
        return cls(
            tool_config=tool_config,
            channel_config=channel_config,
            name=tool_config.name,
            description=tool_config.description,
            args_schema=cls.get_args_schema(tool_config),
        )

# Imports for SageMaker model parallelism and utilities
import importlib.util
import json
import os
import warnings
from dataclasses import dataclass, field

import torch
from ..training_args import TrainingArguments
from ..utils import cached_property, is_sagemaker_dp_enabled, logging

logger = logging.get_logger(__name__)

# TODO: should be moved to `utils` after refactoring of SageMakerTrainer


def is_sagemaker_model_parallel_available():
    # Get the sagemaker specific mp parameters from smp_options variable.
    smp_options = os.getenv("SM_HP_MP_PARAMETERS", "{}")

    try:
        # Parse it and check the field "partitions" is included, it is required for model parallel.
        smp_options = json.loads(smp_options)
        if "partitions" not in smp_options:
            return False
    except json.JSONDecodeError:
        return False

    # Get the sagemaker specific framework parameters from mpi_options variable.
    mpi_options = os.getenv("SM_FRAMEWORK_PARAMS", "{}")

    try:
        # Parse it and check the field "sagemaker_distributed_dataparallel_enabled".
        mpi_options = json.loads(mpi_options)
        if not mpi_options.get("sagemaker_mpi_enabled", False):
            return False
    except json.JSONDecodeError:
        return False

    # Lastly, check if the `smdistributed` module is present.
    return importlib.util.find_spec("smdistributed") is not None


if is_sagemaker_model_parallel_available():
    import smdistributed.modelparallel.torch as smp
    smp.init()


@dataclass
class SageMakerTrainingArguments(TrainingArguments):
    mp_parameters: str = field(
        default="",
        metadata={"help": "Used by the SageMaker launcher to send mp-specific args. Ignored in SageMakerTrainer"},
    )

    def __post_init__(self):
        super().__post_init__()
        warnings.warn(
            "`SageMakerTrainingArguments` is deprecated and will be removed in v5 of Transformers. You can use "
            "`TrainingArguments` instead.",
            FutureWarning,
        )

    @cached_property
    def _setup_devices(self) -> "torch.device":
        logger.info("PyTorch: setting up devices")

        if torch.distributed.is_available() and torch.distributed.is_initialized() and self.local_rank == -1:
            logger.warning(
                "torch.distributed process group is initialized, but local_rank == -1. "
                "In order to use Torch DDP, launch your script with `python -m torch.distributed.launch"
            )

        if self.no_cuda:
            device = torch.device("cpu")
            self._n_gpu = 0
        elif is_sagemaker_model_parallel_available():
            local_rank = smp.local_rank()
            device = torch.device("cuda", local_rank)
            self._n_gpu = 1
        elif is_sagemaker_dp_enabled():
            import smdistributed.dataparallel.torch.torch_smddp  # noqa: F401
            torch.distributed.init_process_group(backend="smddp", timeout=self.ddp_timeout_delta)
            self.local_rank = int(os.getenv("SMDATAPARALLEL_LOCAL_RANK"))
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1
        elif self.local_rank == -1:
            # if n_gpu is > 1 we'll use nn.DataParallel.
            # If you only want to use a specific subset of GPUs use `CUDA_VISIBLE_DEVICES=0`
            # Explicitly set CUDA to the first (index 0) CUDA device, otherwise `set_device` will
            # trigger an error that a device index is missing. Index 0 takes into account the
            # GPUs available in the environment, so `CUDA_VISIBLE_DEVICES=1,2` with `cuda:0`
            # will use the first GPU in that env, i.e. GPU#1
            device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
            # Sometimes the line in the postinit has not been run before we end up here, so just checking we're not at
            # the default value.
            self._n_gpu = torch.cuda.device_count()
        else:
            # Here, we'll use torch.distributed.
            # Initializes the distributed backend which will take care of synchronizing nodes/GPUs
            if not torch.distributed.is_initialized():
                torch.distributed.init_process_group(backend="nccl", timeout=self.ddp_timeout_delta)
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1

        if device.type == "cuda":
            torch.cuda.set_device(device)

        return device

    @property
    def world_size(self):
        if is_sagemaker_model_parallel_available():
            return smp.dp_size()
        return super().world_size

    @property
    def place_model_on_device(self):
        return not is_sagemaker_model_parallel_available()

    @property
    def _no_sync_in_gradient_accumulation(self):
        return False

# Socket waiting utilities using select/poll
import select
import sys
from functools import partial

try:
    from time import monotonic
except ImportError:
    from time import time as monotonic

__all__ = ["NoWayToWaitForSocketError", "wait_for_read", "wait_for_write"]


class NoWayToWaitForSocketError(Exception):
    pass


# How should we wait on sockets?
#
# There are two types of APIs you can use for waiting on sockets: the fancy
# modern stateful APIs like epoll/kqueue, and the older stateless APIs like
# select/poll. The stateful APIs are more efficient when you have a lots of
# sockets to keep track of, because you can set them up once and then use them
# lots of times. But we only ever want to wait on a single socket at a time
# and don't want to keep track of state, so the stateless APIs are actually
# more efficient. So we want to use select() or poll().
#
# Now, how do we choose between select() and poll()? On traditional Unixes,
# select() has a strange calling convention that makes it slow, or fail
# altogether, for high-numbered file descriptors. The point of poll() is to fix
# that, so on Unixes, we prefer poll().
#
# On Windows, there is no poll() (or at least Python doesn't provide a wrapper
# for it), but that's OK, because on Windows, select() doesn't have this
# strange calling convention; plain select() works fine.
#
# So: on Windows we use select(), and everywhere else we use poll(). We also
# fall back to select() in case poll() is somehow broken or missing.


if sys.version_info >= (3, 5):
    # Modern Python, that retries syscalls by default
    def _retry_on_intr(fn, timeout):
        return fn(timeout)
else:
    # Old and broken Pythons.
    def _retry_on_intr(fn, timeout):
        if timeout is None:
            deadline = float("inf")
        else:
            deadline = monotonic() + timeout

        while True:
            try:
                return fn(timeout)
            # OSError for 3 <= pyver < 3.5, select.error for pyver <= 2.7
            except (OSError, select.error) as e:
                # 'e.args[0]' incantation works for both OSError and select.error
                if e.args[0] != errno.EINTR:
                    raise
                else:
                    timeout = deadline - monotonic()
                    if timeout < 0:
                        timeout = 0
                    if timeout == float("inf"):
                        timeout = None
                    continue


def select_wait_for_socket(sock, read=False, write=False, timeout=None):
    if not read and not write:
        raise RuntimeError("must specify at least one of read=True, write=True")

    rcheck = []
    wcheck = []

    if read:
        rcheck.append(sock)
    if write:
        wcheck.append(sock)

    # When doing a non-blocking connect, most systems signal success by
    # marking the socket writable. Windows, though, signals success by marked
    # it as "exceptional". We paper over the difference by checking the write
    # sockets for both conditions. (The stdlib selectors module does the same
    # thing.)
    fn = partial(select.select, rcheck, wcheck, wcheck)
    rready, wready, xready = _retry_on_intr(fn, timeout)

    return bool(rready or wready or xready)


def poll_wait_for_socket(sock, read=False, write=False, timeout=None):
    if not read and not write:
        raise RuntimeError("must specify at least one of read=True, write=True")

    mask = 0
    if read:
        mask |= select.POLLIN
    if write:
        mask |= select.POLLOUT

    poll_obj = select.poll()
    poll_obj.register(sock, mask)

    # For some reason, poll() takes timeout in milliseconds
    def do_poll(t):
        if t is not None:
            t *= 1000
        return poll_obj.poll(t)

    return bool(_retry_on_intr(do_poll, timeout))


def null_wait_for_socket(*args, **kwargs):
    raise NoWayToWaitForSocketError("no select-equivalent available")


def _have_working_poll():
    # Apparently some systems have a select.poll that fails as soon as you try
    # to use it, either due to strange configuration or broken monkeypatching
    # from libraries like eventlet/greenlet.
    try:
        poll_obj = select.poll()
        _retry_on_intr(poll_obj.poll, 0)
    except (AttributeError, OSError):
        return False
    else:
        return True


def wait_for_socket(*args, **kwargs):
    # We delay choosing which implementation to use until the first time we're
    # called. We could do it at import time, but then we might make the wrong
    # decision if someone goes wild with monkeypatching select.poll after
    # we're imported.
    global wait_for_socket

    if _have_working_poll():
        wait_for_socket = poll_wait_for_socket
    elif hasattr(select, "select"):
        wait_for_socket = select_wait_for_socket
    else:  # Platform-specific: Appengine.
        wait_for_socket = null_wait_for_socket

    return wait_for_socket(*args, **kwargs)


def wait_for_read(sock, timeout=None):
    """Waits for reading to be available on a given socket.
    Returns True if the socket is readable, or False if the timeout expired.
    """
    return wait_for_socket(sock, read=True, timeout=timeout)


def wait_for_write(sock, timeout=None):
    """Waits for writing to be available on a given socket.
    Returns True if the socket is readable, or False if the timeout expired.
    """
    return wait_for_socket(sock, write=True, timeout=timeout)

# JAX Embedding layer implementation with quantization support
from typing import Optional
import jax
from flax import nnx
from tpu_inference.layers.jax import JaxModule
from tpu_inference.layers.jax.quantization import QuantizeMethodBase
from tpu_inference.layers.jax.quantization.configs import QuantizationConfig


class JaxEmbed(nnx.Embed, JaxModule):
    """Embedding layer for JAX."""

    def __init__(self,
                 *args,
                 quant_config: Optional[QuantizationConfig] = None,
                 prefix: str = "",
                 **kwargs):
        # Initialize parent nnx.Embed
        nnx.Embed.__init__(self, *args, **kwargs)

        # For compatibility. HF model use 'weight' as name suffix, we alias `self.embedding` to
        # `self.weight` such that `named_parameters()` can match the names in HF models.
        self.weight = self.embedding
        delattr(self, 'embedding')

        # Set sharding metadata if available
        if hasattr(self.weight, "out_sharding"):
            self.weight.set_metadata('sharding', self.weight.out_sharding)

        # Initialize quantization method if config is provided
        self.quant_method = None
        if quant_config is not None:
            quant_method = quant_config.get_quant_method(self, prefix=prefix)
            if quant_method is not None:
                self.quant_method = quant_method
                assert isinstance(quant_method, QuantizeMethodBase)
                quant_method.create_weights_jax(self)

    def __getattr__(self, name: str):
        # Handle backward compatibility for nnx.Embed accessing self.embedding
        if name == "embedding":
            return self.weight

    def __call__(self, x) -> jax.Array:
        # Apply quantized or standard embedding lookup
        if self.quant_method is None:
            return super().__call__(x)
        return self.quant_method.apply_jax(self, x)

    def decode(self, x: jax.Array) -> jax.Array:
        # Decode using transpose of weight matrix
        return jax.numpy.dot(x, self.weight.value.T)

