# Health tracking CLI tool using Garmin Connect API
import json
import sys
from datetime import date

try:
    from garmer import GarminClient
    from garmer.auth import AuthenticationError
except ImportError:
    print("Error: garmer not installed. Run: pip install garmer", file=sys.stderr)
    sys.exit(1)


def get_client() -> GarminClient:
    """Get authenticated Garmin client."""
    try:
        return GarminClient.from_saved_tokens()
    except AuthenticationError:
        print("Error: Not authenticated. Run 'garmer login' first.", file=sys.stderr)
        sys.exit(1)


def cmd_summary():
    """Print today's health summary."""
    client = get_client()
    summary = client.get_daily_summary()

    print(f"Date: {date.today()}")
    print(f"Steps: {summary.total_steps:,} / {summary.daily_step_goal:,}")
    print(f"Distance: {summary.total_distance_meters / 1000:.2f} km")
    print(f"Calories: {summary.total_kilocalories:,}")

    if summary.resting_heart_rate:
        print(f"Resting HR: {summary.resting_heart_rate} bpm")
    if summary.avg_stress_level:
        print(f"Avg Stress: {summary.avg_stress_level}")


def cmd_sleep():
    """Print sleep data."""
    client = get_client()
    sleep = client.get_sleep()

    if sleep:
        print(f"Total Sleep: {sleep.total_sleep_hours:.1f} hours")
        print(f"Deep Sleep: {sleep.deep_sleep_hours:.1f} hours")
        print(f"REM Sleep: {sleep.rem_sleep_hours:.1f} hours")

        if sleep.overall_score:
            print(f"Sleep Score: {sleep.overall_score}")
        if sleep.avg_hrv:
            print(f"HRV: {sleep.avg_hrv:.1f} ms")
    else:
        print("No sleep data available")


def cmd_activities():
    """Print recent activities."""
    client = get_client()
    activities = client.get_recent_activities(limit=5)

    if activities:
        for a in activities:
            print(f"- {a.activity_name} ({a.activity_type_key})")
            print(
                f"  Duration: {a.duration_minutes:.0f} min, Distance: {a.distance_km:.2f} km"
            )
    else:
        print("No recent activities")


def cmd_snapshot():
    """Print full health snapshot as JSON."""
    client = get_client()
    snapshot = client.get_health_snapshot()
    print(json.dumps(snapshot, indent=2, default=str))


def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    command = sys.argv[1].lower()

    commands = {
        "summary": cmd_summary,
        "sleep": cmd_sleep,
        "activities": cmd_activities,
        "snapshot": cmd_snapshot,
    }

    if command in commands:
        commands[command]()
    else:
        print(f"Unknown command: {command}")
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()

# Logging module setup with JSON formatting, encryption support, and third-party logger silencing

from .config import FernetEncrypter
from .req_ctx import get_req_ctx

#-----------------------------------------------------------------------------

_fernet_encryptor = None

#-----------------------------------------------------------------------------

class JsonEncoder(json.JSONEncoder):
    def default(self, o):
        if isinstance(o, datetime.datetime):
            return o.isoformat()

        if isinstance(o, bytes):
            try:
                s = str(o)
                return s
            except:
                return base64.urlsafe_b64encode(o).decode()

        elif isinstance(o, list):
            return [self.default(item) for item in o]

        elif isinstance(o, tuple):
            return tuple(self.default(item) for item in o)

        elif isinstance(o, dict):
            return {key: self.default(value) for key, value in o.items()}

        return super().default(o)

#-----------------------------------------------------------------------------

class JsonFormatter(logging.Formatter):
    def __init__(self, extra: dict | None = None):
        super().__init__()
        self._extra = extra

        # Predefined fields that should not be duplicated in the JSON output
        self._predefined_fields = {
            "name",
            "msg",
            "args",
            "levelname",
            "levelno",
            "pathname",
            "filename",
            "module",
            "exc_info",
            "exc_text",
            "stack_info",
            "lineno",
            "funcName",
            "created",
            "msecs",
            "relativeCreated",
            "thread",
            "threadName",
            "processName",
            "process",
            "taskName",
            # Additional custom fields
            "sql",
            "encrypted_info",
            "exception"
        }

    #-----------------------------------------------------

    def format(self, record: logging.LogRecord):
        # Build base JSON record
        json_record = {
            "time"  : self.formatTime(record, self.datefmt),
            "level" : getattr(record, "levelname", "INFO"),
            "msg"   : record.getMessage()
        }

        #-------------------------------------------------
        # Add exception information if present
        if record.exc_info:
            json_record["exception"] = self.formatException(record.exc_info)

        if record.stack_info:
            json_record["stack_info"] = record.stack_info

        #-------------------------------------------------
        # Extract function name from various possible locations
        function = None
        if hasattr(record, "function_name"):
            function = getattr(record, "function_name")
        elif hasattr(record, "funcName"):
            function = getattr(record, "funcName")

        # Only add if it's not the module-level placeholder
        if function and function != "<module>":
            json_record["function"] = function

        #-------------------------------------------------
        # File path and line number
        if hasattr(record, "pathname") and hasattr(record, "lineno"):
            filename = getattr(record, "pathname").removeprefix(os.getcwd()).removeprefix(os.sep)
            json_record["file"] = f"{filename}:{getattr(record, 'lineno')}"

        # Module name
        if hasattr(record, "module") and record.module:
            json_record["module"] = record.module

        #-------------------------------------------------
        # Handle encrypted info field
        encrypted_info = getattr(record, "encrypted_info", "")
        if encrypted_info:
            plain_encrypted_info = json.dumps(
                encrypted_info,
                ensure_ascii=False,
                separators=(',', ':'),
                cls=JsonEncoder
            )

            global _fernet_encryptor
            if _fernet_encryptor:
                try:
                    encrypted_encrypted_info = _fernet_encryptor.encrypt(plain_encrypted_info)
                except Exception as e:
                    logging.warning(str(e))
                    encrypted_encrypted_info = plain_encrypted_info
            else:
                encrypted_encrypted_info = plain_encrypted_info

            # Truncate long strings for readability
            json_record["encrypted_info"] = encrypted_encrypted_info \
                if len(encrypted_encrypted_info) <= 200 \
                else f"{encrypted_encrypted_info[:100]}**********{encrypted_encrypted_info[-100:]}"

        #-------------------------------------------------
        # Add any additional custom fields
        for k in record.__dict__:
            if k not in self._predefined_fields:
                json_record[k] = record.__dict__[k]

        if self._extra:
            json_record.update(self._extra)

        # Add request context fields if missing
        if "trace_id" not in json_record:
            trace_id = get_req_ctx("trace_id")
            if trace_id:
                json_record["trace_id"] = trace_id

        if "url" not in json_record:
            url = get_req_ctx("path")
            if url:
                json_record["url"] = url

        if "method" not in json_record:
            method = get_req_ctx("method")
            if method:
                json_record["method"] = method

        # Return final JSON string
        return json.dumps(json_record, ensure_ascii=False, separators=(",", ":"), cls=JsonEncoder)

#-----------------------------------------------------------------------------

class TqdmLoggingHandler(logging.Handler):
    def __init__(self):
        super().__init__()

    def emit(self, record):
        from tqdm import tqdm
        try:
            msg = self.format(record)
            tqdm.write(msg)
            self.flush()
        except Exception:
            self.handleError(record)

#-----------------------------------------------------------------------------

# Third-party loggers known to produce verbose DEBUG logs (e.g., full HTTP bodies)
VERBOSE_LOGGERS = [
    "google.genai",
    "google.genai._interactions",
    "httpx",
    "httpcore",
    "urllib3",
    "openai",
    "anthropic",
    "langchain",
    "langchain_core",
]

def _silence_verbose_loggers(app_level: int):
    """
    Reduce noise from verbose third-party libraries by setting their level to WARNING.
    Keeps application's own DEBUG logs visible even when app log level is DEBUG.
    """
    if app_level <= logging.DEBUG:
        for logger_name in VERBOSE_LOGGERS:
            logging.getLogger(logger_name).setLevel(logging.WARNING)

#-----------------------------------------------------------------------------

def init_log_console(level: int = logging.INFO, extra: dict = {}, secret_key: str = ""):
    if secret_key:
        global _fernet_encryptor
        _fernet_encryptor = FernetEncrypter(secret_key)

    stream_handler = logging.StreamHandler()
    stream_handler.setFormatter(JsonFormatter(extra))

    logging.root.handlers = [stream_handler]
    logging.root.setLevel(level=level)

    # Silence verbose third-party library logs (especially in DEBUG mode)
    _silence_verbose_loggers(level)

#-----------------------------------------------------------------------------

def init_log_file(name: str, dir: str, level: int = logging.INFO, extra: dict = {}, secret_key: str = ""):
    if secret_key:
        global _fernet_encryptor
        _fernet_encryptor = FernetEncrypter(secret_key)

    if dir:
        os.makedirs(dir, exist_ok=True)

    formatter = JsonFormatter(extra)
    now = datetime.datetime.now()

    file_handler = logging.FileHandler(
        os.path.join(dir, f"{now.strftime('%Y-%m-%d')}_{name}_{now.strftime('%H%M%S_%f')}.log"),
        mode="w+"
    )
    file_handler.setFormatter(formatter)

    stream_handler = logging.StreamHandler()
    stream_handler.setFormatter(formatter)

    logging.root.handlers = [file_handler, stream_handler]
    logging.root.setLevel(level=level)

    # Silence verbose third-party library logs (especially in DEBUG mode)
    _silence_verbose_loggers(level)

#-----------------------------------------------------------------------------

def init_log_tqdm(level: int = logging.INFO):
    tqdm_handler = TqdmLoggingHandler()
    tqdm_handler.setFormatter(JsonFormatter())

    logging.root.handlers = [tqdm_handler]
    logging.root.setLevel(level=level)

#-----------------------------------------------------------------------------

def init_log(name: str = "", dir: str = "", level: int = logging.INFO, extra: dict = {}, secret_key: str = ""):
    if name:
        init_log_file(name, dir, level, extra, secret_key)
    else:
        init_log_console(level, extra, secret_key)

