    def __init__(self):
        self.config_dir = Path.home() / ".wingosy"
        self.config_file = self.config_dir / "config.json"

        # MIGRATION LOGIC: Be extremely thorough to restore user data
        old_dir = Path.home() / ".argosy"
        if old_dir.exists():
            should_migrate = False
            if not self.config_dir.exists() or not self.config_file.exists():
                should_migrate = True
            else:
                # If .wingosy exists but host is still default, it was a failed rebranding attempt
                try:
                    with open(self.config_file, 'r', encoding='utf-8') as f:
                        current = json.load(f)
                        if current.get("host") == "http://localhost:8285":
                            should_migrate = True
                except:
                    should_migrate = True

            if should_migrate:
                try:
                    if self.config_dir.exists():
                        shutil.rmtree(self.config_dir, ignore_errors=True)
                    shutil.copytree(old_dir, self.config_dir)
                    print(f"Successfully migrated all settings and library from {old_dir}")
                except Exception as e:
                    print(f"Migration error: {e}")

        # Load fresh copy of default config
        self.data = copy.deepcopy(self.DEFAULT_CONFIG)
        self.load()

    def load(self):
        if self.config_file.exists():
            try:
                with open(self.config_file, 'r', encoding='utf-8') as f:
                    loaded_data = json.load(f)

                    # 1. Restore all top-level settings (Host, Paths, User, etc.)
                    for k, v in loaded_data.items():
                        if k != "emulators":
                            self.data[k] = v

                    # 2. Clean Host URL
                    if self.data["host"]:
                        self.data["host"] = self.data["host"].rstrip('/')

                    # 3. Smart Merge Emulators (Restore paths while allowing metadata updates)
                    loaded_emus = loaded_data.get("emulators", {})
                    for name, current_cfg in self.data["emulators"].items():
                        for old_name, old_data in loaded_emus.items():
                            if old_data.get("exe") == current_cfg["exe"]:
                                # Restore the user's custom emulator path
                                current_cfg["path"] = old_data.get("path", "")
                                break
            except Exception as e:
                print(f"Error loading config: {e}")
        else:
            self.save()

    def save(self):
        self.config_dir.mkdir(parents=True, exist_ok=True)
        try:
            with open(self.config_file, 'w', encoding='utf-8') as f:
                json.dump(self.data, f, indent=4)
        except Exception as e:
            print(f"Error saving config: {e}")

    def get(self, key, default=None):
        return self.data.get(key, default)

    def set(self, key, value):
        if value is None:
            self.data.pop(key, None)
        else:
            self.data[key] = value
        self.save()

import os
import logging
from typing import Set

logger = logging.getLogger(__name__)


class SecurityService:
    _disposable_domains: Set[str] = set()
    _loaded: bool = False

    @classmethod
    def _load_domains(cls):
        """Loads disposable email domains from JSON resource."""
        if cls._loaded:
            return

        try:
            # Resolve path relative to this file
            current_dir = os.path.dirname(os.path.abspath(__file__))
            json_path = os.path.join(current_dir, "..", "resources", "disposable_emails.json")

            if os.path.exists(json_path):
                with open(json_path, "r") as f:
                    domains = json.load(f)
                    cls._disposable_domains = set(domains)

                cls._loaded = True
                logger.info(f"Loaded {len(cls._disposable_domains)} disposable email domains.")
            else:
                logger.warning(f"Disposable emails list not found at {json_path}")

        except Exception as e:
            logger.error(f"Failed to load disposable domains: {e}")

    @classmethod
    def is_disposable_email(cls, email: str) -> bool:
        """
        Safety check to identify disposable/temporary email addresses.
        Checks both the direct domain and parent domains for suffix matching.
        """
        if not email or "@" not in email:
            return False

        cls._load_domains()

        if not cls._disposable_domains:
            return False

        # Extract domain
        try:
            domain = email.split("@")[-1].lower().strip()

            # 1. Exact match
            if domain in cls._disposable_domains:
                return True

            # 2. Suffix/Parent domain match (e.g., sub.mailinator.com)
            parts = domain.split(".")
            # Reconstruct domains from right to left (min 2 parts like 'example.com')
            for i in range(len(parts) - 1):
                parent_domain = ".".join(parts[i:])
                if parent_domain in cls._disposable_domains:
                    return True

            return False

        except Exception:
            return False

