from mlir import ir
from mlir.dialects import linalg, arith, tensor, math
from .utils import (
    affine_map,
    get_bias,
    get_outputs,
    get_weights,
    parallel,
    reduction,
)

def affine_maps_and_iter_types(rank: int):
    M, N, K = [ir.AffineDimExpr.get(i) for i in range(3)]

    if rank == 2:  # plain 2D weights
        affine_maps = [
            affine_map(3, [M, K]),
            affine_map(3, [K, N]),
            affine_map(3, [M, N]),
        ]
        iterator_types = [parallel, parallel, reduction]

    elif rank == 4:  # tiled weights, no vnni blocking
        mb, nb, kb = [ir.AffineDimExpr.get(i) for i in range(3, 6)]
        affine_maps = [
            affine_map(6, [M, K, mb, kb]),
            affine_map(6, [N, K, kb, nb]),  # transposed K and N on B
            affine_map(6, [M, N, mb, nb]),
        ]
        iterator_types = [parallel, parallel, reduction] * 2

    elif rank == 5:  # tiled weights with vnni blocking
        # FIXME: due to replicating C++ code, vnni dim is in middle instead of at end.
        k_vnni, mb, nb, kb = [ir.AffineDimExpr.get(i) for i in range(3, 7)]
        affine_maps = [
            affine_map(7, [M, K, mb, kb, k_vnni]),
            # TODO(RM): check if kb and (k_)vnni _not_ being contiguous makes sense.
            affine_map(7, [N, K, kb, nb, k_vnni]),  # transposed K and N on B
            affine_map(7, [M, N, mb, nb]),
        ]
        iterator_types = [
            parallel,  # M
            parallel,  # N
            reduction,  # K
            reduction,  # vnni
            parallel,  # mb
            parallel,  # nb
            reduction,  # kb
        ]
    else:
        assert False

    return affine_maps, iterator_types


def times_weights(
    inputs: ir.Value,
    weights_or_weights_type: Union[ir.Value, ir.RankedTensorType],
    outputs_or_outputs_type: Union[ir.Value, ir.RankedTensorType],
) -> ir.Value:
    weights: ir.Value = get_weights(weights_or_weights_type)
    outputs: ir.Value = get_outputs(outputs_or_outputs_type)

    if weights.type.rank == 5:  # tiled weights with vnni blocking
        vnni_block = weights.type.get_dim_size(4)
        assert inputs.type.shape[-1] % vnni_block == 0
        expanded_shape = (
            inputs.type.shape[:-1]
            + [inputs.type.shape[-1] // vnni_block]
            + [vnni_block]
        )
        inputs = tensor.expand_shape(
            ir.RankedTensorType.get(expanded_shape, inputs.type.element_type),
            inputs,
            reassociation=[[0], [1], [2], [3, 4]],
            output_shape=[],
            static_output_shape=expanded_shape,
        )

    affine_maps, iterator_types = affine_maps_and_iter_types(weights.type.rank)

    @linalg.generic([inputs, weights], [outputs], affine_maps, iterator_types)
    def inputs_times_weights(a, b, c):
        prod = arith.MulFOp(a, b)
        return arith.AddFOp(prod.result, c)

    return inputs_times_weights


def add_bias(inputs: ir.Value, bias_or_bias_type: Union[ir.Value, ir.Type] = None):
    bias: ir.Value = get_bias(bias_or_bias_type)
    M, N, mb, nb = [ir.AffineDimExpr.get(i) for i in range(4)]

    affine_maps, iterator_types = {
        2: ([affine_map(2, [N]), affine_map(2, [M, N])], [parallel] * 2),
        4: ([affine_map(4, [N, nb]), affine_map(4, [M, N, mb, nb])], [parallel] * 4),
    }[inputs.type.rank]

    @linalg.generic([bias], [inputs], affine_maps, iterator_types)
    def biased(a, b):
        return arith.AddFOp(a, b)

    return biased


def relu(inputs: ir.Value):
    zero = arith.constant(inputs.type.element_type, 0.0)
    M, N, mb, nb = [ir.AffineDimExpr.get(i) for i in range(4)]

    affine_maps, iterator_types = {
        2: ([affine_map(2, [M, N])], [parallel, parallel]),
        4: ([affine_map(4, [M, N, mb, nb])], [parallel, parallel] * 2),
    }[inputs.type.rank]

    @linalg.generic([], [inputs], affine_maps, iterator_types)
    def relu_ed(a):
        return arith.MaximumFOp(a, zero)

    return relu_ed


def softmax(
    inputs: ir.Value, softmax_buf_or_softmax_buf_type: Union[ir.Value, ir.Type]
) -> ir.Value:
    softmax_buf = get_outputs(softmax_buf_or_softmax_buf_type)
    shape, elem_type = inputs.type.shape, inputs.type.element_type

    exp_out_uninit = tensor.EmptyOp(shape, elem_type)
    dims = [ir.AffineDimExpr.get(i) for i in range(inputs.type.rank)]
    par_affine_map = affine_map(inputs.type.rank, dims)
    par_affine_maps = [par_affine_map] * inputs.type.rank
    par_iter_types = [parallel] * inputs.type.rank

    red_affine_map = affine_map(
        inputs.type.rank, [dims[0], ir.AffineConstantExpr.get(0)]
    )
    red_iter_types = [parallel, reduction] * (inputs.type.rank // 2)

    @linalg.generic([inputs], [exp_out_uninit.result], par_affine_maps, par_iter_types)
    def exped(input, _output):
        return math.exp(input)

    zero = arith.constant(elem_type, 0.0)
    reduction_out_uninit = tensor.EmptyOp((shape[0], 1), elem_type)
    reduction_out = linalg.fill(zero, outs=reduction_out_uninit)

    @linalg.generic(
        [exped], [reduction_out], [par_affine_map, red_affine_map], red_iter_types
    )
    def summed_exped(exped_input, redex):
        return arith.AddFOp(exped_input, redex)

    bcast_out_uninit = tensor.EmptyOp(shape, elem_type)

    @linalg.generic(
        [summed_exped],
        [bcast_out_uninit.result],
        [red_affine_map, par_affine_map],
        par_iter_types,
    )
    def bcasted_summed_exped(input, _output):
        return input

    @linalg.generic(
        [exped, bcasted_summed_exped],
        [softmax_buf],
        [par_affine_map] * 3,
        par_iter_types,
    )
    def dived_bcasted_summed_exped(exped_input, normalizing_term, _output):
        return arith.DivFOp(exped_input, normalizing_term)

    return dived_bcasted_summed_exped

# Import necessary libraries
import numpy as np
import torch

# Import custom preprocessor
from noether.data.preprocessors import PreProcessor


class NumpyToTorchTensorPreProcessor(PreProcessor):
    """Convert numpy arrays to PyTorch tensors."""

    def __init__(self, normalization_key: str):
        # Initialize parent class with normalization key
        super().__init__(normalization_key=normalization_key)

    def __call__(self, x: np.ndarray) -> torch.Tensor:
        """Convert a numpy array to a PyTorch tensor."""
        # Validate input type
        if not isinstance(x, np.ndarray):
            raise TypeError("Input must be a numpy array.")

        # Convert numpy array to torch tensor
        return torch.from_numpy(x)

    def denormalize(self, x: torch.Tensor) -> np.ndarray:
        """Convert a PyTorch tensor back to a numpy array."""
        # Validate input type
        if not isinstance(x, torch.Tensor):
            raise TypeError("Input must be a torch.Tensor.")

        # Detach from computation graph, move to CPU, and convert to numpy
        return x.detach().cpu().numpy()

# Imports for rich repr functionality
from functools import partial
from typing import (
    Any,
    Callable,
    Iterable,
    List,
    Optional,
    Tuple,
    Type,
    TypeVar,
    Union,
    overload,
)

T = TypeVar("T")
Result = Iterable[Union[Any, Tuple[Any], Tuple[str, Any], Tuple[str, Any, Any]]]
RichReprResult = Result


class ReprError(Exception):
    """An error occurred when attempting to build a repr."""


@overload
def auto(cls: Optional[Type[T]]) -> Type[T]:
    ...


@overload
def auto(*, angular: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...


def auto(
    cls: Optional[Type[T]] = None, *, angular: Optional[bool] = None
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    """Class decorator to create __repr__ from __rich_repr__"""

    def do_replace(cls: Type[T], angular: Optional[bool] = None) -> Type[T]:
        def auto_repr(self: T) -> str:
            """Create repr string from __rich_repr__"""
            repr_str: List[str] = []
            append = repr_str.append

            # Determine angular mode
            angular: bool = getattr(self.__rich_repr__, "angular", False)  # type: ignore[attr-defined]

            # Process each element in the rich repr result
            for arg in self.__rich_repr__():  # type: ignore[attr-defined]
                if isinstance(arg, tuple):
                    if len(arg) == 1:
                        append(repr(arg[0]))
                    else:
                        key, value, *default = arg
                        if key is None:
                            append(repr(value))
                        else:
                            # Skip if value matches default
                            if default and default[0] == value:
                                continue
                            append(f"{key}={value!r}")
                else:
                    append(repr(arg))

            # Format output based on angular mode
            if angular:
                return f"<{self.__class__.__name__} {' '.join(repr_str)}>"
            else:
                return f"{self.__class__.__name__}({', '.join(repr_str)})"

        def auto_rich_repr(self: Type[T]) -> Result:
            """Auto generate __rich_rep__ from signature of __init__"""
            try:
                import inspect
                signature = inspect.signature(self.__init__)
                for name, param in signature.parameters.items():
                    if param.kind == param.POSITIONAL_ONLY:
                        yield getattr(self, name)
                    elif param.kind in (
                        param.POSITIONAL_OR_KEYWORD,
                        param.KEYWORD_ONLY,
                    ):
                        if param.default == param.empty:
                            yield getattr(self, param.name)
                        else:
                            yield param.name, getattr(self, param.name), param.default
            except Exception as error:
                raise ReprError(
                    f"Failed to auto generate __rich_repr__; {error}"
                ) from None

        # Attach methods if not already present
        if not hasattr(cls, "__rich_repr__"):
            auto_rich_repr.__doc__ = "Build a rich repr"
            cls.__rich_repr__ = auto_rich_repr  # type: ignore[attr-defined]

        auto_repr.__doc__ = "Return repr(self)"
        cls.__repr__ = auto_repr  # type: ignore[assignment]

        # Set angular mode if specified
        if angular is not None:
            cls.__rich_repr__.angular = angular  # type: ignore[attr-defined]

        return cls

    # Handle decorator usage with or without arguments
    if cls is None:
        return partial(do_replace, angular=angular)
    else:
        return do_replace(cls, angular=angular)


@overload
def rich_repr(cls: Optional[Type[T]]) -> Type[T]:
    ...


@overload
def rich_repr(*, angular: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...


def rich_repr(
    cls: Optional[Type[T]] = None, *, angular: bool = False
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    if cls is None:
        return auto(angular=angular)
    else:
        return auto(cls)


if __name__ == "__main__":
    @auto
    class Foo:
        def __rich_repr__(self) -> Result:
            yield "foo"
            yield "bar", {"shopping": ["eggs", "ham", "pineapple"]}
            yield "buy", "hand sanitizer"

    foo = Foo()

    # Display using Rich console
    from pip._vendor.rich.console import Console
    console = Console()

    console.rule("Standard repr")
    console.print(foo)
    console.print(foo, width=60)
    console.print(foo, width=30)

    console.rule("Angular repr")
    Foo.__rich_repr__.angular = True  # type: ignore[attr-defined]
    console.print(foo)
    console.print(foo, width=60)
    console.print(foo, width=30)

# Diagnose script for checking the current system.
import os
import platform
import socket
import subprocess
import sys
import time
import psutil

try:
    from urllib.parse import urlparse
    from urllib.request import urlopen
except ImportError:
    from urllib2 import urlopen
    from urlparse import urlparse

import argparse
import importlib.metadata
import torch

URLS = {
    "PYPI": "https://pypi.python.org/pypi/pip",
}

REGIONAL_URLS = {
    "cn": {
        "PYPI(douban)": "https://pypi.douban.com/",
        "Conda(tsinghua)": "https://mirrors.tuna.tsinghua.edu.cn/anaconda/pkgs/free/",
    }
}


def test_connection(name, url, timeout=10):
    """Simple connection test"""
    urlinfo = urlparse(url)
    start = time.time()

    try:
        socket.gethostbyname(urlinfo.netloc)
    except Exception as e:
        print("Error resolving DNS for {}: {}, {}".format(name, url, e))
        return

    dns_elapsed = time.time() - start

    start = time.time()
    try:
        _ = urlopen(url, timeout=timeout)
    except Exception as e:
        print("Error open {}: {}, {}, DNS finished in {} sec.".format(name, url, e, dns_elapsed))
        return

    load_elapsed = time.time() - start
    print(
        "Timing for {}: {}, DNS: {:.4f} sec, LOAD: {:.4f} sec.".format(
            name, url, dns_elapsed, load_elapsed
        )
    )


def check_python():
    print("----------Python Info----------")
    print("Version      :", platform.python_version())
    print("Compiler     :", platform.python_compiler())
    print("Build        :", platform.python_build())
    print("Arch         :", platform.architecture())


def check_pip():
    print("------------Pip Info-----------")
    try:
        import pip
        print("Version      :", pip.__version__)
        print("Directory    :", os.path.dirname(pip.__file__))
    except ImportError:
        print("No corresponding pip install for current python.")


def _get_current_git_commit():
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        print(f"Error running git command: {e.stderr.strip()}")
        return None
    except FileNotFoundError:
        print("Did not find command: git")
        return None


def check_verl():
    print("----------verl Info-----------")
    try:
        sys.path.insert(0, os.getcwd())
        import verl
        print("Version      :", verl.__version__)
        verl_dir = os.path.dirname(verl.__file__)
        print("Directory    :", verl_dir)

        try:
            commit_hash = _get_current_git_commit()
            print("Commit Hash  :", commit_hash)
        except AttributeError:
            print("Commit hash not found. ")

    except ImportError as e:
        print(f"No verl installed: {e}")
    except Exception as e:
        import traceback
        if not isinstance(e, IOError):
            print("An error occurred trying to import verl.")
            print("This is very likely due to missing or incompatible library files.")
        print(traceback.format_exc())


def check_os():
    print("----------Platform Info----------")
    print("Platform     :", platform.platform())
    print("system       :", platform.system())
    print("node         :", platform.node())
    print("release      :", platform.release())
    print("version      :", platform.version())


def check_hardware():
    print("----------Hardware Info----------")
    print("machine      :", platform.machine())
    print("processor    :", platform.processor())

    if sys.platform.startswith("darwin"):
        pipe = subprocess.Popen(("sysctl", "-a"), stdout=subprocess.PIPE)
        output = pipe.communicate()[0]
        for line in output.split(b"\n"):
            if b"brand_string" in line or b"features" in line:
                print(line.strip())
    elif sys.platform.startswith("linux"):
        subprocess.call(["lscpu"])
    elif sys.platform.startswith("win32"):
        subprocess.call(["wmic", "cpu", "get", "name"])


def check_network(args):
    print("----------Network Test----------")
    if args.timeout > 0:
        print("Setting timeout: {}".format(args.timeout))
        socket.setdefaulttimeout(10)

    for region in args.region.strip().split(","):
        r = region.strip().lower()
        if not r:
            continue
        if r in REGIONAL_URLS:
            URLS.update(REGIONAL_URLS[r])
        else:
            import warnings
            warnings.warn(
                "Region {} do not need specific test, please refer to global sites.".format(r),
                stacklevel=2,
            )

    for name, url in URLS.items():
        test_connection(name, url, args.timeout)


def check_environment():
    print("----------Environment----------")
    for k, v in os.environ.items():
        if (
            k.startswith("VERL_")
            or k.startswith("OMP_")
            or k.startswith("KMP_")
            or k == "CC"
            or k == "CXX"
        ):
            print('{}="{}"'.format(k, v))


def check_pip_package_versions():
    packages = ["vllm", "sglang", "ray", "torch"]
    for package in packages:
        try:
            version = importlib.metadata.version(package)
            print(f"{package}\t     : {version}")
        except importlib.metadata.PackageNotFoundError:
            print(f"{package}\t     : not found.")


def check_cuda_versions():
    if torch.cuda.is_available():
        try:
            cuda_runtime_version = torch.version.cuda
            print(f"CUDA Runtime : {cuda_runtime_version}")
            import subprocess
            nvcc_output = subprocess.check_output(["nvcc", "--version"]).decode("utf-8")
            cuda_compiler_version = next(
                (line for line in nvcc_output.splitlines() if "release" in line),
                None,
            )
            if cuda_compiler_version:
                print(f"CUDA Compiler : {cuda_compiler_version.strip()}")
            else:
                print("Could not determine CUDA compiler version.")
        except FileNotFoundError as e:
            print(f"CUDA compiler : Not found: {e}")
        except Exception as e:
            print(f"An error occurred while checking CUDA versions: {e}")
    else:
        print("CUDA is not available.")


def _get_cpu_memory():
    """
    Get the total CPU memory capacity in GB.
    """
    memory = psutil.virtual_memory()
    return memory.total / (1024**3)


def _get_gpu_info():
    """
    Get GPU type, GPU memory, and GPU count using nvidia-smi command.
    """
    try:
        result = subprocess.run(
            [
                "nvidia-smi",
                "--query-gpu=gpu_name,memory.total",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            check=True,
        )
        gpu_lines = result.stdout.strip().split("\n")
        gpu_count = len(gpu_lines)
        gpu_info = []
        for line in gpu_lines:
            gpu_name, gpu_memory = line.split(", ")
            gpu_info.append(
                {
                    "type": gpu_name,
                    "memory": float(gpu_memory) / 1024,  # Convert to GB
                }
            )
        return gpu_count, gpu_info
    except subprocess.CalledProcessError:
        print("Failed to execute nvidia-smi command.")
        return 0, []


def _get_system_info():
    """
    Get CPU memory capacity, GPU type, GPU memory, and GPU count.
    """
    cpu_memory = _get_cpu_memory()
    gpu_count, gpu_info = _get_gpu_info()
    return {
        "cpu_memory": cpu_memory,
        "gpu_count": gpu_count,
        "gpu_info": gpu_info,
    }


def check_system_info():
    print("----------System Info----------")
    system_info = _get_system_info()
    print(f"CPU Memory\t: {system_info['cpu_memory']:.2f} GB")
    print(f"GPU Count\t: {system_info['gpu_count']}")
    for i, gpu in enumerate(system_info["gpu_info"]):
        print(f"GPU {i + 1}\tType    : {gpu['type']}")
        print(f"GPU {i + 1}\tMemory  : {gpu['memory']:.2f} GB")


def parse_args():
    """Parse arguments."""
    parser = argparse.ArgumentParser(
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
        description="Diagnose script for checking the current system.",
    )
    choices = ["python", "pip", "verl", "system", "os", "environment"]
    for choice in choices:
        parser.add_argument(
            "--" + choice,
            default=1,
            type=int,
            help="Diagnose {}.".format(choice),
        )
    parser.add_argument("--network", default=0, type=int, help="Diagnose network.")
    parser.add_argument("--hardware", default=0, type=int, help="Diagnose hardware.")
    parser.add_argument(
        "--region",
        default="",
        type=str,
        help="Additional sites in which region(s) to test. \
                        Specify 'cn' for example to test mirror sites in China.",
    )
    parser.add_argument(
        "--timeout",
        default=10,
        type=int,
        help="Connection test timeout threshold, 0 to disable.",
    )
    args = parser.parse_args()
    return args


if __name__ == "__main__":
    args = parse_args()

    if args.python:
        check_python()
    if args.pip:
        check_pip()
        check_pip_package_versions()
    if args.verl:
        check_verl()
    if args.os:
        check_os()
    if args.hardware:
        check_hardware()
    if args.network:
        check_network(args)
    if args.environment:
        check_environment()
        check_cuda_versions()
    if args.system:
        check_system_info()

# Oracle database client implementation
import pandas as pd
import sqlalchemy
from sqlalchemy import text
from contextlib import contextmanager
from typing import Generator, List, Optional
from app.ai.prompt_formatters import Table, TableColumn
from app.ai.prompt_formatters import TableFormatter
from functools import cached_property


class OracledbClient(DataSourceClient):
    def __init__(self, host, port, service_name, user, password, schema: Optional[str] = None):
        self.host = host
        self.port = port
        self.service_name = service_name
        self.user = user
        self.password = password

        # Optional schema or comma-separated list of schemas
        self.schema = schema
        self._schemas = []

        if isinstance(self.schema, str) and self.schema.strip():
            parts = [s.strip() for s in self.schema.split(",") if s.strip()]
            seen = set()
            for p in parts:
                up = p.upper()
                if up not in seen:
                    seen.add(up)
                    self._schemas.append(up)

    @cached_property
    def oracle_uri(self):
        uri = (
            f"oracle+oracledb://{self.user}:{self.password}@"
            f"{self.host}:{self.port}/?service_name={self.service_name}"
        )
        return uri

    @contextmanager
    def connect(self) -> Generator[sqlalchemy.engine.base.Connection, None, None]:
        """Yield a connection to an Oracle database."""
        engine = None
        conn = None

        try:
            engine = sqlalchemy.create_engine(self.oracle_uri)
            conn = engine.connect()

            # Set current schema if provided (Oracle has no search_path; use first schema)
            if self._schemas:
                current_schema = self._schemas[0]
                try:
                    conn.execute(text(f'ALTER SESSION SET CURRENT_SCHEMA = {current_schema}'))
                except Exception:
                    pass

            yield conn
        except Exception as e:
            raise RuntimeError(f"{e}")
        finally:
            if conn is not None:
                conn.close()
            if engine is not None:
                engine.dispose()

    def execute_query(self, sql: str) -> pd.DataFrame:
        """Execute SQL statement and return the result as a DataFrame."""
        try:
            with self.connect() as conn:
                df = pd.read_sql(text(sql), conn)
            return df
        except Exception as e:
            print(f"Error executing SQL: {e}")
            raise

    def get_tables(self) -> List[Table]:
        """Get tables with graceful fallback if enriched query fails."""
        try:
            return self._get_tables_enriched()
        except Exception:
            return self._get_tables_basic()

    def _get_tables_enriched(self) -> List[Table]:
        """Get tables with column/table comments. May fail on some Oracle configurations."""
        with self.connect() as conn:
            params = {}
            where_clauses = []

            if self._schemas:
                in_keys = []
                for idx, sch in enumerate(self._schemas):
                    key = f"o{idx}"
                    params[key] = sch
                    in_keys.append(f":{key}")
                where_clauses.append(f"c.owner IN ({', '.join(in_keys)})")
            else:
                params["owner"] = self.user.upper()
                where_clauses.append("c.owner = :owner")

            where_sql = " WHERE " + " AND ".join(where_clauses)

            sql = text(f"""
                SELECT
                    c.owner,
                    c.table_name,
                    c.column_name,
                    c.data_type,
                    cc.comments AS column_comment,
                    tc.comments AS table_comment
                FROM all_tab_columns c
                LEFT JOIN all_col_comments cc
                    ON c.owner = cc.owner
                    AND c.table_name = cc.table_name
                    AND c.column_name = cc.column_name
                LEFT JOIN all_tab_comments tc
                    ON c.owner = tc.owner
                    AND c.table_name = tc.table_name
                {where_sql}
                ORDER BY c.owner, c.table_name, c.column_id
            """)

            result = conn.execute(sql, params).fetchall()
            tables = {}

            for row in result:
                owner, table_name, column_name, data_type, col_comment, tbl_comment = row
                key = (owner, table_name)
                fqn = f"{owner}.{table_name}"

                if key not in tables:
                    tables[key] = Table(
                        name=fqn,
                        description=tbl_comment if tbl_comment else None,
                        columns=[],
                        pks=[],
                        fks=[],
                        metadata_json={"schema": owner}
                    )

                tables[key].columns.append(TableColumn(
                    name=column_name,
                    dtype=data_type,
                    description=col_comment if col_comment else None
                ))

            return list(tables.values())

    def _get_tables_basic(self) -> List[Table]:
        """Get tables without comments (original query - always works)."""
        try:
            with self.connect() as conn:
                params = {}
                where_clauses = []

                if self._schemas:
                    in_keys = []
                    for idx, sch in enumerate(self._schemas):
                        key = f"o{idx}"
                        params[key] = sch
                        in_keys.append(f":{key}")
                    where_clauses.append(f"owner IN ({', '.join(in_keys)})")
                else:
                    params["owner"] = self.user.upper()
                    where_clauses.append("owner = :owner")

                where_sql = " WHERE " + " AND ".join(where_clauses)

                sql = text(f"""
                    SELECT owner, table_name, column_name, data_type
                    FROM all_tab_columns
                    {where_sql}
                    ORDER BY owner, table_name, column_id
                """)

                result = conn.execute(sql, params).fetchall()
                tables = {}

                for row in result:
                    owner, table_name, column_name, data_type = row
                    key = (owner, table_name)
                    fqn = f"{owner}.{table_name}"

                    if key not in tables:
                        tables[key] = Table(
                            name=fqn, columns=[], pks=[], fks=[], metadata_json={"schema": owner}
                        )

                    tables[key].columns.append(TableColumn(name=column_name, dtype=data_type))

                return list(tables.values())
        except Exception as e:
            print(f"Error retrieving tables: {e}")
            return []

    def get_schema(self, table_id: str) -> Table:
        """This method is now obsolete. Please use get_tables() instead."""
        raise NotImplementedError(
            "get_schema() is obsolete. Use get_tables() instead.")

    def get_schemas(self):
        """Get schemas for all tables in the specified database."""
        return self.get_tables()

    def prompt_schema(self):
        schemas = self.get_schemas()
        return TableFormatter(schemas).table_str

    def test_connection(self):
        """Test connection to Oracle and return status information."""
        try:
            with self.connect() as conn:
                conn.execute(text("SELECT 1 FROM DUAL"))
                return {
                    "success": True,
                    "message": "Successfully connected to Oracle"
                }
        except Exception as e:
            return {
                "success": False,
                "message": str(e)
            }

    @property
    def description(self):
        system_prompt = """
        You can call the execute_query method to run SQL queries.

        The below are examples for how to use the execute_query method. Note that the actual SQL will vary based on the schema.
        Notice only the SQL syntax and instructions on how to use the execute_query method, not the actual SQL queries.

# Applies torch patches for compatibility and bug fixes
from __future__ import annotations

import logging

_logger = logging.getLogger(__name__)

_TORCH_PATCHES_APPLIED = False


def apply_torch_patches() -> None:
    """
    Apply small, version/packaging-specific torch monkey patches.
    This function is idempotent and safe to call multiple times.
    """
    global _TORCH_PATCHES_APPLIED
    if _TORCH_PATCHES_APPLIED:
        return

    try:
        import torch as _torch
    except Exception:
        # torch not installed or failing to import: nothing to patch.
        return

    # -------------------------------------------------------------------------
    # Patch #1: torchdata compatibility
    # Monkey patch pin_memory to optionally accept a device argument.
    # The device argument was removed in some newer torch versions but torchdata
    # still passes it in some versions.
    # -------------------------------------------------------------------------
    try:
        import functools
        import inspect
        from torch.utils.data import _utils as torch_data_utils

        _original_pin_memory_loop = torch_data_utils.pin_memory._pin_memory_loop
        _original_pin_memory = torch_data_utils.pin_memory.pin_memory
        _original_pin_memory_sig = inspect.signature(_original_pin_memory)

        if "device" not in _original_pin_memory_sig.parameters:
            @functools.wraps(_original_pin_memory)
            def _patched_pin_memory(data, device=None):
                return _original_pin_memory(data)

            @functools.wraps(_original_pin_memory_loop)
            def _pin_memory_loop(in_queue, out_queue, device_id, done_event, device):
                return _original_pin_memory_loop(in_queue, out_queue, device_id, done_event)

            torch_data_utils.pin_memory.pin_memory = _patched_pin_memory
            torch_data_utils.pin_memory._pin_memory_loop = _pin_memory_loop
    except Exception as e:
        _logger.debug(f"Could not apply torch pin_memory patch: {e}")

    # -------------------------------------------------------------------------
    # Patch #2: DeviceMesh slicing corner case (specific PyTorch regression)
    # Fixes issue where _dim_group_names is accessed without checking if rank is in mesh.
    # Based on https://github.com/pytorch/pytorch/pull/169454/files
    # -------------------------------------------------------------------------
    try:
        # Only apply the patch for the specific PyTorch version with the regression
        # TODO: Remove this once bump up to a newer PyTorch version with the fix
        if "2.10.0" in _torch.__version__ and "nv25.11" in _torch.__version__:
            from torch.distributed._mesh_layout import _MeshLayout
            from torch.distributed.device_mesh import _MeshEnv

            def _patched_get_slice_mesh_layout(self, device_mesh, mesh_dim_names):
                # 1. Build the layout manually to bypass the legacy 'stride < pre_stride' check
                slice_from_root = device_mesh == self.get_root_mesh(device_mesh)
                flatten_name_to_root_layout = (
                    {
                        key: mesh._layout
                        for key, mesh in self.root_to_flatten_mapping.setdefault(device_mesh, {}).items()
                    }
                    if slice_from_root
                    else {}
                )
                mesh_dim_names_list = getattr(device_mesh, "mesh_dim_names", [])
                valid_mesh_dim_names = [*mesh_dim_names_list, *flatten_name_to_root_layout]

                if not all(name in valid_mesh_dim_names for name in mesh_dim_names):
                    raise KeyError(f"Invalid mesh_dim_names {mesh_dim_names}. Valid: {valid_mesh_dim_names}")

                layout_sliced = []
                for name in mesh_dim_names:
                    if name in mesh_dim_names_list:
                        layout_sliced.append(device_mesh._layout[mesh_dim_names_list.index(name)])
                    elif name in flatten_name_to_root_layout:
                        layout_sliced.append(flatten_name_to_root_layout[name])

                sliced_sizes = tuple(layout.sizes for layout in layout_sliced)
                sliced_strides = tuple(layout.strides for layout in layout_sliced)

                # Bypass the 'stride < pre_stride' check that exists in the original and create MeshLayout directly.
                slice_mesh_layout = _MeshLayout(sliced_sizes, sliced_strides)

                if not slice_mesh_layout.check_non_overlap():
                    raise RuntimeError(f"Slicing overlapping dim_names {mesh_dim_names} is not allowed.")

                # 2. Replicate the _dim_group_names fix (commit f6c8092)
                if hasattr(device_mesh, "_dim_group_names") and len(device_mesh._dim_group_names) > 0:
                    slice_dim_group_name = []
                    submesh_dim_names = mesh_dim_names if isinstance(mesh_dim_names, tuple) else (mesh_dim_names,)
                    for name in submesh_dim_names:
                        if name in mesh_dim_names_list:
                            slice_dim_group_name.append(
                                device_mesh._dim_group_names[mesh_dim_names_list.index(name)]
                            )
                        elif hasattr(device_mesh, "_flatten_mapping") and name in device_mesh._flatten_mapping:
                            flatten_mesh = device_mesh._flatten_mapping[name]
                            slice_dim_group_name.append(
                                flatten_mesh._dim_group_names[flatten_mesh.mesh_dim_names.index(name)]
                            )
                    object.__setattr__(slice_mesh_layout, "_dim_group_names", slice_dim_group_name)

                return slice_mesh_layout

            _MeshEnv._get_slice_mesh_layout = _patched_get_slice_mesh_layout
            _logger.debug(f"Applied DeviceMesh fix for PyTorch {_torch.__version__}")
    except (ImportError, AttributeError) as e:
        _logger.debug(f"Could not apply DeviceMesh patch: {e}")

    # -------------------------------------------------------------------------
    # Patch #3: aten.alias.default sharding strategy (PyTorch 2.9 regression)
    # torch.ops.aten.alias.default has no sharding strategy registered in
    # PyTorch 2.9.0, causing NotImplementedError when DTensor dispatches
    # through aten.alias (e.g. via HF Qwen3's logits_to_keep slice).
    # See https://github.com/pytorch/pytorch/pull/166867 for the upstream fix.
    # Remove this patch once we upgrade to a torch version that includes it.
    # -------------------------------------------------------------------------
    try:
        from packaging.version import parse as _vparse

        if _vparse(_torch.__version__).base_version == "2.9.0":
            from torch.distributed.tensor._ops._tensor_ops import propagate_single_input_strategy
            from torch.distributed.tensor._ops.utils import register_op_strategy

            register_op_strategy(_torch.ops.aten.alias.default)(propagate_single_input_strategy)
            _logger.debug("Applied aten.alias.default sharding strategy patch for PyTorch 2.9.0")
    except Exception as e:
        _logger.debug(f"Could not apply aten.alias.default sharding strategy patch: {e}")

    _TORCH_PATCHES_APPLIED = True

