# Calculate the number of ways to decode a string of digits
from typing import List

def count_decoding_ways(encoded: str) -> int:
    cache: List[int or None] = [None] * (len(encoded) + 1)

    def solve(position: int) -> int:
        if position == 0:
            return 1
        idx = len(encoded) - position
        if encoded[idx] == '0':
            return 0
        if cache[position]:
            return cache[position]

        total = solve(position - 1)
        if position >= 2 and encoded[idx:idx + 2] <= '26':
            total += solve(position - 2)
        cache[position] = total
        return total

    return solve(len(encoded))

if __name__ == '__main__':
    print(count_decoding_ways("12"))
    print(count_decoding_ways("01"))
    print(count_decoding_ways("011"))
    print(count_decoding_ways("3"))
    print(count_decoding_ways(""))
    print(count_decoding_ways("12345"))
    print(count_decoding_ways("111111"))

