# Class to encapsulate package requirement details using pkg_resources.Requirement
# Reference: https://setuptools.pypa.io/en/latest/pkg_resources.html#requirement-objects
class PackageRequirement:
    ANY_VERSION = 'Any'
    _req_obj = None

    def __init__(self, req: Optional = None):
        self._req_obj = req

    @property
    def version_spec(self) -> str:
        """Get the required package version constraint"""
        return str(self._req_obj.specifier) if self._req_obj.specifier else self.ANY_VERSION

    def __eq__(self, other: 'PackageRequirement') -> bool:
        """Check equality between two PackageRequirement instances"""
        return self._req_obj == other._req_obj

