def fragment(render, **kwargs):
    # barycentric
    w, v, u = kwargs['bar']
    # texture
    tx, ty = kwargs['texture_coords']
    grey = int(ty * 100)
    tcolor = color(grey, 50, 15)
    # normals
    nA, nB, nC = kwargs['varying_normals']
    # light intensity
    iA, iB, iC = [dot(n, render.light) for n in (nA, nB, nC)]
    intensity = w * iA + v * iB + u * iC
    if (intensity > 0.85):
        intensity = 1
    elif (intensity > 0.60):
        intensity = 0.80
    elif (intensity > 0.45):
        intensity = 0.60
    elif (intensity > 0.30):
        intensity = 0.45
    elif (intensity > 0.15):
        intensity = 0.30
    else:
        intensity = 0
    return color(
        int(tcolor[2] * intensity) if tcolor[0] * intensity > 0 else 0,
        int(tcolor[1] * intensity) if tcolor[1] * intensity > 0 else 0,
        int(tcolor[0] * intensity) if tcolor[2] * intensity > 0 else 0
