        return title_part + artist_part + album_part


class Artwork(object):
    def __init__(self, base64_data=None, raw_bytes=None, mime_type=None, file_ext=None, hash_value=None):
        self._raw_bytes = raw_bytes         # the actual file bytes
        self._base64_data = base64_data     # base64 encoding
        self._mime_type = mime_type         # e.g. "image/png"
        self._file_ext = file_ext           # e.g. ".png"
        self._hash_value = hash_value       # sha256 of binary

    @property
    def encoded_base64(self):
        if self._base64_data:
            return self._base64_data
        if self._raw_bytes:
            self._base64_data = encodebytes(try_encode(self._raw_bytes))
            return self._base64_data
        else:
            return None

    @property
    def raw_bytes(self):
        return self._raw_bytes

    @property
    def content_type(self):
        if self._mime_type:
            return self._mime_type
        if self._raw_bytes:
            self._mime_type = magic.from_buffer(self._raw_bytes, mime=True).decode("utf-8")
            return self._mime_type
        else:
            return None

    @property
    def extension(self):
        self._file_ext = "jpg"
        return self._file_ext

    @property
    def hash_checksum(self):
        if self._hash_value:
            return self._hash_value
        if self._raw_bytes:
            self._hash_value = sha256(self._raw_bytes).hexdigest()
            return self._hash_value
        else:
            return None

    def to_dictionary(self, include_base64=False):
        result = {
            "content_type": self.content_type,
            "extension": self.extension,
            "hash_checksum": self.hash_checksum,
        }
        if include_base64:
            result["encoded_base64"] = self.encoded_base64
        return result


class DataElement(object):
    def __init__(self, element):
        if isinstance(element, str):
            try:
                element = ET.fromstring(element)
            except Exception:
                LOGGER.exception("Skipping malformed XML line")
                return
        if isinstance(element, ET.Element):
            element = etree_to_dict(element)
        if isinstance(element, dict):
            element = DictObject.objectify(element)

        assert isinstance(element, DictObject)
        assert hasattr(element.item, "type")

        self.type_code = ascii_integers_to_string(element.item.type)
        self.code_value = ascii_integers_to_string(element.item.code)
        self.data_length = int(element.item.length)

        if "data" in element.item:
            assert self.data_length > 0
            self.payload = encoded_to_str(element.item.data["#text"], element.item.data["@encoding"], as_bytes=True)
            if element.item.data["@encoding"] == "base64":
                self._base64_payload = try_decode(element.item.data["#text"])
            else:
                self._base64_payload = None
        else:
            assert self.data_length == 0
            self.payload = try_encode("")
            self._base64_payload = None

    @property
    def text_value(self):
        return try_decode(self.payload)

    @property
    def numeric_value(self):
        if self.payload:
            try:
                return int("0x" + ''.join([hex(ord(c))[2:] for c in self.payload]), base=16)  # Python2
            except:
                return int("0x" + ''.join([hex(b)[2:] for b in self.payload]), base=16)      # Python3
        return None

    @property
    def timestamp_value(self):
        return datetime.fromtimestamp(self.numeric_value)

    @property
    def boolean_value(self):
        if self.numeric_value == 1:
            return True
        elif self.numeric_value == 0:
            return False
        else:
            raise TypeError("Data boolean is neither 0 or 1, but is {val}.".format(val=self.numeric_value))

    @property
    def base64_encoded(self):
        if self._base64_payload:
            return self._base64_payload
        else:
            return encodebytes(try_encode(self.payload))


def ascii_integers_to_string(data, base=16, chars_per_byte=2):
    return "".join([chr(int(data[i:i+chars_per_byte], base=base)) for i in range(0, len(data), chars_per_byte)])


def extract_string_data(element, as_bytes=True):
    return encoded_to_str(element.item.data["#text"], element.item.data["@encoding"], as_bytes=as_bytes)


def decode_payload(data, encoding, as_bytes=True):
    if encoding == "base64":
        decoded_bytes = decodebytes(data.encode('ascii'))
        return decoded_bytes if as_bytes else decoded_bytes.decode("utf-8")
    else:
        raise AttributeError("unknown encoding format: {f}".format(f=encoding))

