import torch
import numpy as np
from typing import List, Optional, Dict
from neuralogic.core.builder import Sample, Weight, Neuron
from neuralogic.core.settings import SettingsProxy
from neuralogic.core.enums import Initializer, Backend
from neuralogic.nn.base import AbstractNeuraLogic

def power_law_distribution(tensor: torch.Tensor, config: SettingsProxy):
    # Initialize with random values in [0, 1)
    random_values = np.random.rand(*tensor.size())

    # Parameters for the distribution transformation
    lower_bound, upper_bound, exponent = 0.0, 10.0, 50.0

    # Compute transformed values using power law formula
    lower_exponent = np.power(lower_bound, exponent + 1)
    transformed = upper_bound - np.power(
        (np.power(upper_bound, exponent + 1) - lower_exponent) * random_values + lower_exponent,
        1 / (exponent + 1)
    )

    # Fill tensor with computed values
    tensor.fill_(transformed)

class Neuralogic(AbstractNeuraLogic):
    activation_functions = {
        "Sigmoid": torch.sigmoid,
        "Average": torch.mean,
        "Maximum": torch.max,
        "ReLu": torch.relu,
        "Tanh": torch.tanh,
    }

    initializer_registry = {
        Initializer.NORMAL: lambda tensor, _: torch.nn.init.normal_(tensor),
        Initializer.UNIFORM: lambda tensor, settings: torch.nn.init.uniform_(
            tensor, -settings.initializer_uniform_range / 2, settings.initializer_uniform_range / 2
        ),
        Initializer.CONSTANT: lambda tensor, settings: torch.nn.init.constant_(tensor, settings.initializer_constant_value),
        Initializer.LONGTAIL: power_law_distribution,
        # TODO: GLOROT and HE
    }

    def __init__(self, weight_list: List[Weight], template, settings: Optional[SettingsProxy] = None):
        super().__init__(Backend.TORCH, template, settings)
        self.parameter_list: Optional[torch.nn.ParameterList] = None
        self.weight_metadata = weight_list
        self.parameters: List[torch.nn.Parameter] = []
        self.initialize_weights()

    def initialize_weights(self):
        init_method = Initializer[str(self.settings.initialization_method)]
        if init_method not in Neuralogic.initializer_registry:
            raise NotImplementedError(f"Initializer '{init_method}' is not implemented")

        weight_init_func = Neuralogic.initializer_registry[init_method]

        for meta_weight in self.weight_metadata:
            if meta_weight.fixed:
                param = torch.nn.Parameter(torch.tensor(meta_weight.value, dtype=torch.float64), requires_grad=False)
            else:
                param = torch.nn.Parameter(
                    torch.empty(size=meta_weight.dimensions, requires_grad=True, dtype=torch.float64)
                )
                weight_init_func(param.data, self.settings)
            self.parameters.append(param)

        self.parameter_list = torch.nn.ParameterList(self.parameters)

    def build_sample(self, sample: Sample):
        self.hooks_active = len(self.hooks) != 0
        torch_neurons: List[Optional[torch.Tensor]] = [None] * len(sample.neurons)

        for neuron in sample.neurons:
            torch_neurons[neuron.index] = self.convert_to_torch(neuron, torch_neurons, self.parameter_list)

        return torch_neurons[sample.neurons[-1].index]

    def __call__(self, sample: Sample):
        return self.build_sample(sample)

    def get_state_dict(self) -> Dict:
        weight_dict = {}
        for meta, param in zip(self.weight_metadata, self.parameters):
            if not meta.fixed and meta.index >= 0:
                weight_dict[meta.index] = param if isinstance(param, (int, float)) else param.data
        return {"weights": weight_dict}

    def set_state_dict(self, state_dict: Dict):
        loaded_weights = state_dict["weights"]
        for i, (meta, param) in enumerate(zip(self.weight_metadata, self.parameters)):
            if meta.index < 0 or meta.fixed:
                continue
            if isinstance(param, (int, float)):
                param.data = torch.tensor([loaded_weights[meta.index]], dtype=torch.float64)
            else:
                param.data = torch.tensor(loaded_weights[meta.index], dtype=torch.float64)

    @staticmethod
    def convert_to_tensor(value) -> torch.Tensor:
        if isinstance(value, (float, int)):
            return torch.tensor([value], requires_grad=False, dtype=torch.float64)
        return torch.tensor(value, requires_grad=False, dtype=torch.float64)

    def convert_to_torch(
        self, neuron: Neuron, neurons: List[torch.Tensor], weights: torch.nn.ParameterList
    ) -> torch.Tensor:
        if neuron.inputs:
            result = self.compute_neuron_output(neuron, neurons, weights)

            if neuron.activation:
                if not neuron.pooling:
                    result = sum(result)
                else:
                    result = torch.stack(result)

                if neuron.activation != "Identity":
                    result = Neuralogic.activation_functions[neuron.activation](result)
            else:
                result = sum(result)
        else:
            result = Neuralogic.convert_to_tensor(neuron.value)
            if neuron.activation and neuron.activation != "Identity":
                result = Neuralogic.activation_functions[neuron.activation](result)

        if self.hooks_active and neuron.hook_name is not None and neuron.hook_name in self.hooks:
            self.execute_hook(neuron.hook_name, result.item())

        return result

    def compute_neuron_output(
        self, neuron: Neuron, neurons: List[torch.Tensor], weights: torch.nn.ParameterList
    ) -> List[torch.Tensor]:
        outputs = []

        if neuron.weights:
            for w_idx, i_idx in zip(neuron.weights, neuron.inputs):
                input_tensor = neurons[i_idx]
                weight_tensor = weights[w_idx]

                input_shape = input_tensor.size()
                weight_shape = weight_tensor.size()

                if not input_shape or not weight_shape or input_shape == (1,) or weight_shape == (1,):
                    outputs.append(torch.multiply(weight_tensor, input_tensor))
                else:
                    outputs.append(torch.matmul(weight_tensor, input_tensor))
        else:
            for i_idx in neuron.inputs:
                outputs.append(neurons[i_idx])

        return outputs

