from os import walk
from pathlib import Path
from time import time as current_time
from typing import Dict, List, Iterable, TypeVar, Callable, Union, Any
import numpy as np
from PySide2.QtCore import QThread
from vicarutil.image.core import read_beg_labels, Labels
from ..concurrent import typedsignal, signal
from ..ui import Progress
from ...logging import handle_exception

_T = TypeVar('_T')

class FileType(Enum):
    IMAGE = "IMG"
    LABEL = "LBL"

class SortType(Enum):
    FILTER = 'filter'
    SEQUENCE = 'sequence'
    EXPOSURE = 'exposure'
    UNKNOWN = "--"

    @staticmethod
    def reverse(value: Any):
        if isinstance(value, str):
            if not hasattr(SortType, '_reverse_map'):
                SortType._reverse_map = {e.value: e for e in SortType}
            try:
                return SortType._reverse_map[value]
            except KeyError:
                return SortType.UNKNOWN
        return value

def _safe_file_iterator(o: Iterable[_T]) -> Iterable[_T]:
    try:
        yield from o
    except PermissionError:
        yield from o

def get_labels_from_image(p: Path) -> Labels:
    with open(p, 'rb') as file_handle:
        return read_beg_labels(file_handle)

def get_sequence_from_image(p: Path) -> str:
    try:
        labels = get_labels_from_image(p)
        return f"Sequence {labels['IDENTIFICATION']['SEQUENCE_ID']}"
    except KeyError:
        return "Not Found"

def placeholder(*_, **__) -> str:
    return "Files"

def get_filter_from_image(p: Path) -> str:
    try:
        clear_filters = {"CL1", "CL"}
        labels = get_labels_from_image(p)
        filters = [str(o).strip() for o in labels['INSTRUMENT']['FILTER_NAME']]
        if len(filters) == 0:
            return "Other"
        elif np.alltrue([filt in clear_filters for filt in filters]):
            return "Clear"
        else:
            return ','.join(filters)
    except KeyError:
        return "Not Found"

def get_exposure_from_image(p: Path) -> str:
    try:
        labels = get_labels_from_image(p)
        exposure_ms = int(labels['INSTRUMENT']['EXPOSURE_DURATION'])
        exposure_sec = exposure_ms // 1000
        rounded_val = exposure_sec - (exposure_sec % 10)
        return f"{rounded_val:d}"
    except KeyError:
        return "Not Found"

class FileProcessor(QThread):
    initialization_complete = signal()
    set_total = typedsignal(int)
    increment_progress = typedsignal(int)
    processing_done = typedsignal(dict)

    def __init__(
            self,
            root_directory: str,
            completion_handler: Callable[[dict], None],
            grouping_method: Union[str, SortType] = None
    ):
        super(FileProcessor, self).__init__()
        self.root = Path(root_directory)
        self._start_time = 0
        self.grouping = SortType.reverse(grouping_method)

        original_quit = self.quit

        def on_completion(d: Dict):
            completion_handler(d)
            Progress.stop()
            original_quit()

        self.initialization_complete.connect(Progress.start())
        self.processing_done.connect(on_completion)
        self.set_total.connect(lambda i: Progress.max(i))
        self.increment_progress.connect(lambda i: Progress.value(i))

    def cancel(self):
        self.processing_done.emit(dict())

    def verify_timeout(self):
        now = current_time()
        if now - self._start_time > 30:
            raise TimeoutError()

    def traverse_directories(self, path: Path) -> List[Path]:
        result = list()
        self.verify_timeout()
        result.append(path)
        for item in _safe_file_iterator(path.iterdir()):
            if item.is_dir():
                result.extend(self.traverse_directories(item))
        return result

    def run(self) -> None:
        try:
            self._start_time = current_time()
            self.initialization_complete.emit()

            if self.root.is_dir():
                directories = self.traverse_directories(self.root)
                self.set_total.emit(len(directories))

                results = dict()
                total_files: int = np.sum([len(files) for _, _, files in walk(self.root, followlinks=False)])
                self.set_total.emit(total_files)

                processed_count = 0
                self.increment_progress.emit(processed_count)

                # Select appropriate grouping function
                if self.grouping == SortType.SEQUENCE:
                    group_func = get_sequence_from_image
                elif self.grouping == SortType.FILTER:
                    group_func = get_filter_from_image
                elif self.grouping == SortType.EXPOSURE:
                    group_func = get_exposure_from_image
                else:
                    group_func = placeholder

                # Process all files
                for dir_path, _, filenames in walk(self.root, followlinks=False):
                    current_dir = Path(dir_path)
                    for filename in filenames:
                        if filename.endswith(FileType.IMAGE.value):
                            try:
                                full_path = current_dir.joinpath(filename)
                                group_key = group_func(full_path)
                                if group_key not in results:
                                    results[group_key] = list()
                                results[group_key].append(full_path)
                            except Exception as err:
                                handle_exception(err)

                        processed_count += 1
                        self.increment_progress.emit(processed_count)

                self.processing_done.emit(results)
            else:
                self.processing_done.emit(dict())
            self.quit()
        except TimeoutError:
            self.processing_done.emit(dict())
            self.quit()

__all__ = ['FileProcessor', 'FileType', 'SortType']

