import pytest
from ethereum.abi import ValueOutOfBounds

TOKEN_NAME = "Vipercoin"
TOKEN_SYMBOL = "FANG"
TOKEN_DECIMALS = 18
TOKEN_INITIAL_SUPPLY = (21 * 10 ** 6)
TOKEN_TOTAL_SUPPLY = TOKEN_INITIAL_SUPPLY * (10 ** TOKEN_DECIMALS)

@pytest.fixture
def erc20(get_contract):
    erc20_code = open('examples/tokens/vipercoin.v.py').read()
    return get_contract(erc20_code, args=[TOKEN_NAME, TOKEN_SYMBOL, TOKEN_DECIMALS, TOKEN_INITIAL_SUPPLY])

@pytest.fixture
def erc20_interactor(erc20, get_contract):
    erc20_interactor_code = """
token_address: address(ERC20)
@public
def __init__(token_addr: address):
    self.token_address = token_addr
@public
def symbol() -> bytes32:
    return self.token_address.symbol()
@public
def balanceOf(_owner: address) -> num256:
    return self.token_address.balanceOf(_owner)
@public
def totalSupply() -> num256:
    return self.token_address.totalSupply()
@public
def transfer(_to: address, _value: num256) -> bool:
    return self.token_address.transfer(_to, _value)
@public
def transferFrom(_from: address, _to: address, _value: num(num256)) -> bool:
    return self.token_address.transferFrom(_from, _to, _value)
@public
def allowance(_owner: address, _spender: address) -> num256:
    return self.token_address.allowance(_owner, _spender)
    """
    return get_contract(erc20_interactor_code, args=[erc20.address])

def pad_to_bytes32(instr):
    """ Pad a string \x00 bytes to return correct bytes32 representation. """
    bstr = instr.encode()
    return bstr + (32 - len(bstr)) * b'\x00'

def test_initial_state(t, erc20_interactor):
    assert erc20_interactor.totalSupply() == TOKEN_TOTAL_SUPPLY == erc20_interactor.balanceOf(t.a0)
    assert erc20_interactor.balanceOf(t.a1) == 0
    assert erc20_interactor.symbol() == pad_to_bytes32(TOKEN_SYMBOL)

def test_transfer_via_interactor(t, chain, erc20, erc20_interactor, assert_tx_failed):

    # Basic transfer.
    erc20.transfer(erc20_interactor.address, 10)
    assert erc20.balanceOf(erc20_interactor.address) == 10
    erc20_interactor.transfer(t.a1, 10)
    assert erc20.balanceOf(erc20_interactor.address) == 0
    assert erc20.balanceOf(t.a1) == 10

    # more than allowed
    assert_tx_failed(lambda: erc20_interactor.transfer(t.a1, TOKEN_TOTAL_SUPPLY))
    t.s = chain

    # Negative transfer value.
    assert_tx_failed(
        function_to_test=lambda: erc20_interactor.transfer(t.a1, -1),
        exception=ValueOutOfBounds
    )

def test_approve_allowance_via_interactor(t, erc20, erc20_interactor):
    assert erc20_interactor.allowance(erc20.address, erc20_interactor.address) == 0
    assert erc20.approve(erc20_interactor.address, 10) == True
    assert erc20_interactor.allowance(t.a0, erc20_interactor.address) == 10

def test_transfer_from_via_interactor(t, erc20, erc20_interactor, assert_tx_failed):
    # Cannot transfer tokens that are unavailable
    assert_tx_failed(lambda: erc20_interactor.transferFrom(t.a0, erc20_interactor.address, 10))
    assert erc20.balanceOf(erc20_interactor.address) == 0

    assert erc20.approve(erc20_interactor.address, 10) == True
    erc20_interactor.transferFrom(t.a0, erc20_interactor.address, 5)
    assert erc20.balanceOf(erc20_interactor.address) == 5
    assert erc20_interactor.allowance(t.a0, erc20_interactor.address) == 5

    erc20_interactor.transferFrom(t.a0, erc20_interactor.address, 3)
    assert erc20.balanceOf(erc20_interactor.address) == 8
    assert erc20_interactor.allowance(t.a0, erc20_interactor.address) == 2

