import os
from logging import DEBUG, INFO, getLevelName
from typing import Dict, Optional, Tuple, Union
import toml
from pydantic import BaseModel, BaseSettings, validator
from pydantic.env_settings import SettingsSourceCallable
from fidesctl.core.utils import echo_red, generate_request_headers

class AppConfigBase(BaseSettings):
    """Base configuration model for all settings."""
    class Config:
        extra = "forbid"
        # Environment variables take precedence over initialization values
        @classmethod
        def customise_sources(
            cls,
            init_settings: SettingsSourceCallable,
            env_settings: SettingsSourceCallable,
            file_secret_settings: SettingsSourceCallable,
        ) -> Tuple[SettingsSourceCallable, ...]:
            return env_settings, init_settings, file_secret_settings

class ProfileSettings(AppConfigBase):
    """Class used to store user-specific configuration values."""
    profile_id: str = "1"
    access_key: str = "test_api_key"
    auth_headers: Dict[str, str] = dict()

    @validator("auth_headers", pre=True, always=True)
    def create_auth_headers(
        cls: BaseModel, value: Optional[Dict], values: Dict
    ) -> Dict[str, str]:
        return generate_request_headers(values["profile_id"], values["access_key"])

    class Config:
        env_prefix = "FIDESCTL__USER__"

class CLIOptions(AppConfigBase):
    """Class used to store CLI-related configuration values."""
    standalone_mode: bool = False
    endpoint_url: str = "http://localhost:8080"

    class Config:
        env_prefix = "FIDESCTL__CLI__"

class ServerSettings(AppConfigBase):
    """Class used to store API server configuration values."""
    # This has to be defined before database_url for validation
    test_db_url: str = (
        "postgresql+psycopg2://postgres:fidesctl@fidesctl-db:5432/fidesctl_test"
    )
    primary_db_url: str = (
        "postgresql+psycopg2://postgres:fidesctl@fidesctl-db:5432/fidesctl"
    )

    @validator("primary_db_url", pre=True, always=True)
    def determine_database_url(cls: AppConfigBase, value: str, values: Dict) -> str:
        "Use test database URL when running in test mode."
        url = (
            values["test_db_url"]
            if os.getenv("FIDESCTL_TEST_MODE") == "True"
            else value
        )
        return url

    log_target: str = ""
    verbosity: Union[int, str] = INFO
    format_output: str = ""

    @validator("log_target", pre=True)
    def set_log_destination(cls: AppConfigBase, value: str) -> str:
        """
        Route logs to stdout by default, unless a valid file path is specified.
        """
        return value if os.path.exists(value) else ""

    @validator("verbosity", pre=True)
    def set_verbosity_level(cls: AppConfigBase, value: str) -> str:
        """
        Set verbosity level to DEBUG in test mode, INFO otherwise.
        Ensures that the string-form of a valid logging._Level is
        always returned.
        """
        if os.getenv("FIDESCTL_TEST_MODE") == "True":
            return getLevelName(DEBUG)
        if isinstance(value, str):
            value = value.upper()
        return value if getLevelName(value) != f"Level {value}" else getLevelName(INFO)

    @validator("format_output", pre=True)
    def set_serialization_format(cls: AppConfigBase, value: str) -> str:
        """
        Only allow JSON serialization or no serialization.
        """
        value = value.lower()
        return value if value == "json" else ""

    class Config:
        env_prefix = "FIDESCTL__API__"

class ApplicationConfiguration(BaseModel):
    """Main configuration container encapsulating all configuration sections."""
    server: ServerSettings = ServerSettings()
    cli: CLIOptions = CLIOptions()
    profile: ProfileSettings = ProfileSettings()

def load_config(config_path: str = "") -> ApplicationConfiguration:
    """
    Attempt to read configuration from:
    a) explicitly provided path, if it exists
    b) environment variable FIDESCTL_CONFIG_PATH
    c) current directory
    d) user's home directory
    Fails on first encountered invalid configuration file.
    """
    default_filename = "fidesctl.toml"
    candidate_paths = [
        config_path,
        os.getenv("FIDESCTL_CONFIG_PATH", ""),
        os.path.join(os.getcwd(), default_filename),
        os.path.join(os.path.expanduser("~"), default_filename),
    ]

    for config_file in candidate_paths:
        if config_file != "" and os.path.isfile(config_file):
            try:
                parsed_data = toml.load(config_file)
                app_config = ApplicationConfiguration.parse_obj(parsed_data)
                return app_config
            except IOError:
                echo_red(f"Error reading configuration from {config_file}")

    # Return default configuration if no file found
    app_config = ApplicationConfiguration()
    return app_config

