]

class AuthenticationContext:
    """
    An Authentication context object wrapper
    encapsulating the crypto context used to verify credentials
    """
    def __init__(self, config: Settings = Settings()):
        self.crypto_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
        self.config = config

    def validate_credential(self, username: str, password: str) -> Any:
        credential = fetch_auth_credential(username, self.config)
        return self.check_password(password, credential.hashed_password)

    def check_password(self, plain_password: str, hashed_password: str) -> Any:
        return self.crypto_context.verify(plain_password, hashed_password)

    def hash_password(self, password: Union[bytes, str]) -> Any:
        return self.crypto_context.hash(password)

def fetch_auth_credential(
    username: str, config: Settings = Settings()
) -> AuthenticationCredential:
    """Retrieve an authentication credential from the repository."""
    try:
        with get_repository(
            get_client_id(), DataCollection.AUTHENTICATION, config
        ) as repo:
            query_result = repo.get({"username": username})
            if not query_result:
                raise HTTPException(
                    status_code=status.HTTP_404_NOT_FOUND,
                    detail=f"Could not locate credential for {username}",
                )
            return AuthenticationCredential(**query_result)
