        ) as repo:
            query_result = repo.get({"username": credential.username})
            if not query_result:
                repo.set(credential.dict())
            else:
                raise HTTPException(
                    status_code=status.HTTP_409_CONFLICT,
                    detail=f"Already exists {credential.username}",
                )
    except Exception as err:
        print(sys.exc_info())
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="store auth credential failed",
        ) from err

def modify_auth_credential(
    credential: AuthenticationCredential, config: Settings = Settings()
) -> BaseResponse:
    """Modify an authentication credential in the repository."""
    try:
        with get_repository(
            get_client_id(), DataCollection.AUTHENTICATION, config
        ) as repo:
            query_result = repo.get({"username": credential.username})
            if not query_result:
                raise HTTPException(
                    status_code=status.HTTP_404_NOT_FOUND,
                    detail=f"Could not locate credential {credential.username}",
                )
            repo.update({"username": credential.username}, credential.dict())
            return BaseResponse()
    except Exception as err:
        print(sys.exc_info())
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="modify auth credential failed",
        ) from err

# Modified version with renamed variables, changed literals, and reordered statements
from typing import TYPE_CHECKING, List, Iterable, Set, Sequence
from collections import OrderedDict
from ezdxf.lldxf.types import dxftag, uniform_appid
from ezdxf.lldxf.tags import Tags
from ezdxf.lldxf.const import DXFKeyError, DXFStructureError
from ezdxf.lldxf.const import ACAD_REACTORS, REACTOR_HANDLE_CODE, APP_DATA_MARKER

if TYPE_CHECKING:
    from ezdxf.lldxf.tagwriter import TagWriter

__all__ = ['AppData', 'Reactors']

ERROR_INVALID_ATTRIB = 'Invalid DXF attribute for entity {}'
ERROR_MISSING_ATTRIB = 'DXF attribute {} does not exist'

class AppData:
    def __init__(self):
        self.storage = OrderedDict()

    def __contains__(self, appid: str) -> bool:
        return uniform_appid(appid) in self.storage

    def __len__(self) -> int:
        return len(self.storage)

    def get(self, appid: str) -> Tags:
        try:
            return self.storage[uniform_appid(appid)]
        except KeyError:
            raise DXFKeyError(appid)

    def set(self, tags: Tags) -> None:
        if len(tags):
            appid = tags[0].value
            self.storage[appid] = tags

    def add(self, appid: str, content: Iterable[Sequence]) -> None:
        content_tags = Tags(dxftag(code, value) for code, value in content)
        appid = uniform_appid(appid)

        # Insert marker at beginning if missing
        if not content_tags or content_tags[0] != (APP_DATA_MARKER, appid):
            content_tags.insert(0, dxftag(APP_DATA_MARKER, appid))

        # Append closing marker if missing
        if not content_tags or content_tags[-1] != (APP_DATA_MARKER, '}'):
            content_tags.append(dxftag(APP_DATA_MARKER, '}'))

        self.set(content_tags)

    def discard(self, appid: str):
        _appid = uniform_appid(appid)
        if _appid in self.storage:
            del self.storage[_appid]

    def export_dxf(self, tagwriter: 'TagWriter') -> None:
        for data in self.storage.values():
            tagwriter.write_tags(data)

class Reactors:
    """ Handle storage for related reactors.
    Reactors are other objects related to the object that contains this
    Reactor() instance.
    """
    def __init__(self, handles: Iterable[str] = None):
        self.handle_set: Set[str] = None  # stores handles as strings
        self.set(handles)

    def __len__(self) -> int:
        return len(self.handle_set)

    def __contains__(self, handle):
        return handle in self.handle_set

    def __iter__(self):
        return iter(self.get())

    @classmethod
    def from_tags(cls, tags: Tags = None) -> 'Reactors':
        """ Create Reactors() instance from tags.
        Expected DXF structure: [(102, '{ACAD_REACTORS'), (330, handle), ..., (102, '}')]
        Args:
            tags: list of DXFTags()
        """
        if tags is None:
            return cls(None)
        if len(tags) < 2:  # no reactors are valid
            raise DXFStructureError("ACAD_REACTORS error")
        return cls((handle.value for handle in tags[1:-1]))

    def get(self) -> List[str]:
        return sorted(self.handle_set, key=lambda x: int(x, base=16))

    def set(self, handles: Iterable[str]) -> None:
        self.handle_set = set(handles or [])

    def add(self, handle: str) -> None:
        self.handle_set.add(handle)

    def discard(self, handle: str):
        self.handle_set.discard(handle)

    def export_dxf(self, tagwriter: 'TagWriter') -> None:
        tagwriter.write_tag2(APP_DATA_MARKER, ACAD_REACTORS)
        for handle in self.get():
            tagwriter.write_tag2(REACTOR_HANDLE_CODE, handle)
        tagwriter.write_tag2(APP_DATA_MARKER, '}')

