# Configuration flow for Ruuvi sensors in Home Assistant
from typing import Any, Dict, Optional
from .const import DOMAIN
import voluptuous as vol
from .sensor import CONF_MAC, CONF_NAME, CONF_SENSORS, SENSOR_TYPES, CONF_MONITORED_CONDITIONS
import homeassistant.helpers.config_validation as cv

# Schema for adding a new Ruuvi sensor device
DEVICE_ADD_SCHEMA = vol.Schema(
    {
        vol.Required(CONF_MAC): cv.string,
        vol.Optional(CONF_NAME): cv.string
    }
)

# Build configuration schema dynamically based on available sensor types
temp_config_schema = {}
for condition in SENSOR_TYPES.keys():
  temp_config_schema[vol.Optional(condition)] = cv.boolean
SENSOR_CONFIG_SCHEMA = vol.Schema(temp_config_schema)

# Schema for asking if user wants to add another sensor
ADD_ANOTHER_CONFIRMATION = vol.Schema(
  {
    vol.Optional("add_another"): cv.boolean
  }
)

class RuuviConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):
    # Shared data storage during configuration
    current_data = {
        CONF_SENSORS: []
    }
    temp_sensor_info = {}

    async def async_step_user(self, user_input=None):
        """Handle the initial step when user starts the configuration flow."""
        return await self.async_step_add_new_sensor()

    async def async_step_add_new_sensor(self, user_input: Optional[Dict[str, Any]] = None):
        """Handle the step where user provides MAC address and optional name."""
        validation_errors: Dict[str, str] = {}
        if user_input is not None:
            # Perform validation here
            if not validation_errors:
                # Store temporary sensor info for next step
                self.temp_sensor_info = {
                        CONF_MAC: user_input[CONF_MAC],
                        CONF_NAME: user_input.get(CONF_NAME, None),            
                }
                return await self.async_step_configure_sensor()

        return self.async_show_form(
            step_id="add_new_sensor", data_schema=DEVICE_ADD_SCHEMA, errors=validation_errors
        )

    async def async_step_configure_sensor(self, user_input: Optional[Dict[str, Any]] = None):
        """Second step: configure which sensor measurements to monitor."""
        validation_errors: Dict[str, str] = {}
        if user_input is not None:
            # Perform validation here
            if not validation_errors:
                # Create sensor entry with selected conditions
                self.current_data[CONF_SENSORS].append(
                    {
                        CONF_MAC: self.temp_sensor_info[CONF_MAC],
                        CONF_NAME: self.temp_sensor_info[CONF_NAME],
                        CONF_MONITORED_CONDITIONS: [key for key in SENSOR_TYPES.keys() if user_input.get(key, False)]
                    }
                )
                return await self.async_step_add_more_sensors()

        return self.async_show_form(
            step_id="configure_sensor", data_schema=SENSOR_CONFIG_SCHEMA, errors=validation_errors
        )

    async def async_step_add_more_sensors(self, user_input: Optional[Dict[str, Any]] = None):
        """Ask user if they want to add another Ruuvi sensor."""
        validation_errors: Dict[str, str] = {}
        if user_input is not None:
            # Perform validation here
            if not validation_errors:
                # Check if user wants to add another sensor
                if user_input.get("add_another", False):
                    return await self.async_step_add_new_sensor()
                # No more sensors to add, finalize the configuration
                return self.async_create_entry(
                  title="Ruuvi Sensors",
                  data=self.current_data
                )

        return self.async_show_form(
            step_id="add_more_sensors", data_schema=ADD_ANOTHER_CONFIRMATION, errors=validation_errors
        )

