app = QuartTrio(__name__)
# TODO: ASGI app
logger = getLogger(__name__)

@app.websocket("/livereload")
async def livereload_websocket() -> NoReturn:
    watcher: Watcher = app.config["REFRESHER_WATCHER"]
    handshake_request = json.loads(await websocket.receive())
    logger.debug("handshake_request: %r", handshake_request)
    client_protocols = handshake_request.get("protocols", [])
    if "http://livereload.com/protocols/official-7" not in client_protocols:
        raise RuntimeError(f"Unsupported protocols: {client_protocols}")
    handshake_reply = {
        "command": "hello",
        "protocols": ["http://livereload.com/protocols/official-7"],
        "serverName": "refresher",
    }
    await websocket.send(json.dumps(handshake_reply))
    while True:
        req = await watcher.get_request()
        reload_request = {
            "command": "reload",
            "path": req.path,
            "liveCSS": True,
        }
        logger.info("Reloading: %s", req.path)
        logger.debug("req = %r", req)
        await websocket.send(json.dumps(reload_request))

@app.route("/livereload.js")
async def livereload_js() -> ResponseReturnValue:
    with open(Path(__file__).parent / "assets" / "livereload.js") as file:
        return file.read()

close_tag_re = re.compile(b"</(body|html)>", re.IGNORECASE)
script_livereload_js = """
<script>document.write('<script src="http://'
    + location.host.split(':')[0]
    + ':{port}/livereload.js"></'
    + 'script>')</script>
"""

def inject_livereload_js(content: bytes, port: int) -> bytes:
    scr = script_livereload_js.format(port=port).encode("ascii")
    m = close_tag_re.search(content)
    if not m:
        return content + scr
    i = m.start() - 1
    return content[:i] + scr + content[i:]

def notfound_page(pagepath: str, port: int) -> ResponseReturnValue:
    scr = script_livereload_js.format(port=port)
    return (
        f"<html>{scr}<body><h1>Not found: <code>/{html.escape(pagepath)}</code></h1>",
        404,
    )

host_port_re = re.compile(".*:([0-9]+)$")

def port_from_host(host: str) -> Optional[int]:
    m = host_port_re.match(host)
    if m:
        return int(m.group(1))
    return None

def current_port(req=request) -> int:
    port = port_from_host(req.host)
    if port is not None:
        return port
    if req.scheme == "https":
        return 443
    else:
        return 80

@app.route("/", defaults={"pagepath": ""})
@app.route("/<path:pagepath>")
async def serve_file(pagepath) -> ResponseReturnValue:
    watcher: Watcher = app.config["REFRESHER_WATCHER"]
    port = current_port()
    if request.cache_control.no_cache:
        # https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control
        logger.info("Invalidating page: %s", pagepath)
        watcher.invalidate_page(pagepath)
    try:
        page = await watcher.get_page(pagepath)
    except PageNotFound as err:
        logger.debug("%s", err)
        return notfound_page(pagepath, port)
    logger.debug("page = %r", page)
    if page.is_cached:
        logger.info("Serving cached page: %s", pagepath)
    if page.is_html:
        return inject_livereload_js(page.content, port)
    else:
        mime, encoding = mimetypes.guess_type(page.filepath)
        if not mime:
            mime, encoding = mimetypes.guess_type(pagepath)
        header = {}
        if mime:
            header["Content-Type"] = mime
        if encoding:
            header["Content-Encoding"] = encoding
        return page.content, 200, header

async def start_server(root: str, debug: bool, port: int) -> None:
    app.config["DEBUG"] = debug
    cfg = Config()
    cfg.bind = [f"localhost:{port}"]
    async with open_watcher(root) as watcher:
        app.config["REFRESHER_WATCHER"] = watcher
        logger.info("Serving and watching: %s", watcher.root.resolve())
        # https://pgjones.gitlab.io/hypercorn/how_to_guides/api_usage.html
        await serve(app, cfg)

# Modified version of ServicePort with renamed variables and reordered logic
from .errors import ConfigurationError
from docker.utils.ports import build_port_bindings

class ServicePort(namedtuple('_ServicePort', 'target published protocol mode external_ip')):
    def __new__(cls, target, published, *args, **kwargs):
        try:
            if target is not None:
                target = int(target)
        except ValueError:
            raise ConfigurationError('Invalid target port: {}'.format(target))

        if published is not None:
            if isinstance(published, str) and '-' in published:  # "x-y:z" format
                start, end = published.split('-', 1)
                if not start.isdigit() or not end.isdigit():
                    raise ConfigurationError('Invalid published port: {}'.format(published))
            else:
                try:
                    published = int(published)
                except ValueError:
                    raise ConfigurationError('Invalid published port: {}'.format(published))

        return super().__new__(
            cls, target, published, *args, **kwargs
        )

    @classmethod
    def parse(cls, spec):
        if isinstance(spec, cls):
            # When extending a service with ports, the port definitions have already been parsed
            return [spec]

        if not isinstance(spec, dict):
            result_list = []
            try:
                for key, value in build_port_bindings([spec]).items():
                    if '/' in key:
                        target_port, protocol = key.split('/', 1)
                    else:
                        target_port, protocol = (key, None)

                    for pub_port in value:
                        if pub_port is None:
                            result_list.append(
                                cls(target_port, None, protocol, None, None)
                            )
                        elif isinstance(pub_port, tuple):
                            result_list.append(
                                cls(target_port, pub_port[1], protocol, None, pub_port[0])
                            )
                        else:
                            result_list.append(
                                cls(target_port, pub_port, protocol, None, None)
                            )
            except ValueError as err:
                raise ConfigurationError(str(err))
            return result_list

        return [cls(
            spec.get('target'),
            spec.get('published'),
            spec.get('protocol'),
            spec.get('mode'),
            None
        )]

    @property
    def merge_field(self):
        return (self.target, self.published, self.external_ip, self.protocol)

    def to_dict(self):
        return {
            field_name: value 
            for field_name, value in zip(self._fields, self) 
            if value is not None
        }

    def legacy_repr(self):
        return normalize_port_dict(self.to_dict())

def normalize_port_dict(port_info):
    return '{external_ip}{has_ext_ip}{published}{is_pub}{target}/{protocol}'.format(
        published=port_info.get('published', ''),
        is_pub=(':' if port_info.get('published') is not None or port_info.get('external_ip') else ''),
        target=port_info.get('target'),
        protocol=port_info.get('protocol', 'tcp'),
        external_ip=port_info.get('external_ip', ''),
        has_ext_ip=(':' if port_info.get('external_ip') else ''),
    )

# Text Editor Cog - Modified version with renamed variables and adjusted logic
import inspect
import random
from typing import Optional
from redbot.core import commands
from redbot.core.utils.chat_formatting import bold, box

class TextProcessor(str):
    """A class used for text manipulation helper functions."""

    def _char_count(self, include_spaces: bool):
        if include_spaces:
            return f"Character count (with spaces): {bold(str(len(self)))}"
        return f"Character count: {bold(len(self) - self.count(' '))}"

    def _word_count(self):
        words = self.split()
        return f"Word count: {len(words)}"

    def _occurrence(self, target):
        count = self.count(target)
        plural_form = "once" if count == 1 else f"{count} times"
        return f"`{target}` is present in the text {bold(plural_form)}."

    def _to_snake_case(self):
        return box(self.replace(" ", "_"))

    def _alternating_case(self):
        chars = list(self)
        chars[0::2] = map(str.upper, chars[0::2])
        chars[1::2] = map(str.lower, chars[1::2])
        return box("".join(chars))

    def _substitute(self, old_text, new_text):
        substitution = lambda s: s.replace(old_text, new_text)
        return box(substitution(self))

    def _compress(self):
        return box(self.replace(" ", ""))

    def _delete(self, to_delete):
        return box(self.replace(to_delete, ""))

    def _trim_edges(self, trim_chars):
        return box(self.strip(trim_chars).strip())

    def _scramble(self):
        parts = self.split()
        random.shuffle(parts)
        return box(" ".join(parts))

    def _invert(self):
        return box(self[::-1])

    def _repeat(self, times):
        return box(self * times)

class TextEditor(commands.Cog):
    """
    A cog for editing and manipulating text.
    """
    __author__ = ["Kreusada"]
    __version__ = "3.0.1"

