    # Process objects: duplicate and separate by material
    processed_objects = []
    for temp_obj in candidate_objects:
      temp_obj.select = True
      bpy.ops.object.duplicate()
      bpy.ops.mesh.separate( type = "MATERIAL" )
      for obj in bpy.context.selected_objects:
        processed_objects.append( obj )
        obj.select = False

    # Generate primitives for each object
    for obj in processed_objects:
      primitive = {}
      if obj.type == "CAMERA":
        primitive = primCamera( obj )
      elif obj.type == "MESH":
        primitive = primMesh( obj, dir_path )
      elif obj.type == "LAMP":
        primitive = primLamp( obj, dir_path )
      yaml_data[ "scene" ][ "primitives" ].append( primitive )

    # Write output YAML file
    file_handle = open( _filepath, "w" )
    file_handle.write( dump( yaml_data ) )
    file_handle.close()

    # Clean up duplicated objects
    for obj in processed_objects:
      obj.select = True
    bpy.ops.object.delete()

    # Restore original selection state
    for obj in current_selection:
      obj.select = True

  def execute( self, context ):
    self.export_scene( self.filepath )
    return { "FINISHED" }

def menu_func( self, context ):
    self.layout.operator( ExportNanogi.bl_idname, text = "nanogi (.yml)" )

def register():
  bpy.utils.register_module( __name__ )
  bpy.types.INFO_MT_file_export.append( menu_func )

def unregister():
  bpy.utils.unregister_module( __name__ )
  bpy.types.INFO_MT_file_export.remove( menu_func )

