# Modified version with Type I clone transformations
from __future__ import absolute_import
from __future__ import unicode_literals
import os
import click
import six
from decapodcli import param_types as cli_param_types
from decapodcli import utils as cli_utils
from decapodlib import exceptions as lib_exceptions

try:
    import pygments
except ImportError:
    pygments = None

def handle_errors(func):
    """Decorator which intercepts all exceptions and attempts to display them."""
    @six.wraps(func)
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        try:
            return func(*args, **kwargs)
        except lib_exceptions.DecapodAPIError as err:
            cli_utils.format_output_json(ctx, err.json, True)
        except lib_exceptions.DecapodError as err:
            click.echo(six.text_type(err), err=True)
        finally:
            ctx.close()
        ctx.exit(os.EX_SOFTWARE)
    return wrapper

def provide_client(func):
    """Decorator which injects both client and model client into method."""
    @six.wraps(func)
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        kwargs["client"] = ctx.obj["client"]
        return func(*args, **kwargs)
    return wrapper

def format_result(func):
    """Decorator which formats the output."""
    @six.wraps(func)
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        result = func(*args, **kwargs)
        if not result:
            return
        if ctx.obj["format"] == "json":
            cli_utils.format_output_json(ctx, result)
    return wrapper

def enable_color(func):
    """Decorator which adds --color option if available."""
    if pygments is None:
        def wrapper(*args, **kwargs):
            kwargs["color"] = None
            return func(*args, **kwargs)
    else:
        wrapper = click.option(
            "--color",
            default=None,
            type=click.Choice(["light", "dark"]),
            help=(
                "Colorize output. By default no color is used. "
                "Parameter means colorscheme of the terminal")
        )(func)
    wrapper = six.wraps(func)(wrapper)
    return wrapper

def add_pagination(func):
    """Add pagination-related commandline options."""
    @six.wraps(func)
    @click.option(
        "--page", "-p",
        type=int,
        default=None,
        help="Page to request."
    )
    @click.option(
        "--per_page", "-r",
        type=int,
        default=None,
        help="How many items should be displayed per page."
    )
    @click.option(
        "--all", "-a",
        is_flag=True,
        help=(
            "Show all items, without pagination. "
            "Default behavior, 'page' and 'per_page' options disable this "
            "option."
        )
    )
    @click.option(
        "--list", "-l",
        type=click.Choice(["active", "archived", "all"]),
        show_default=True,
        default="active",
        help="List only certain class of elements. 'active' is default."
    )
    @click.option(
        "--sort-by", "-s",
        default="",
        type=cli_param_types.SORT_BY,
        help=(
            "Comma-separated list of fieldnames for sorting. To define "
            "direction, please put '-' or '+' before name ('+' explicitly "
            "means). For example: 'time_deleted,-name,+version' means "
            "that sorting will be done by tuple (time_deleted ASC, "
            "name DESC, version ASC)"
        )
    )
    @click.option(
        "--no-envelope", "-n",
        is_flag=True,
        help=(
            "Remove pagination envelope, just list items. If all items "
            "requested, this implicitly meant."
        )
    )
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        all_items = kwargs.pop("all", None)
        page = kwargs.pop("page", None)
        per_page = kwargs.pop("per_page", None)
        no_envelope = kwargs.pop("no_envelope", None)
        list_elements = kwargs.pop("list", "active")
        sort_by = kwargs.pop("sort_by", {})
        all_items = all_items or not (page or per_page)
        no_envelope = all_items or no_envelope
        if all_items:
            query_params = {"all_items": True}
        else:
            query_params = {
                "page": page,
                "per_page": per_page
            }
        query_params["filter"] = {}
        if list_elements == "all":
            query_params["filter"]["time_deleted"] = {
                "ne": "unreal_value"
            }
        elif list_elements == "archived":
            query_params["filter"]["time_deleted"] = {
                "ne": 0
            }
        else:
            del query_params["filter"]
        if sort_by:
            query_params["sort_by"] = sort_by
        kwargs["query_params"] = query_params
        response = func(*args, **kwargs)
        if no_envelope and response:
            response = response["items"]
        return response
    return wrapper

def modify_model(item_id, fetch_method_name, parse_json=True):
    """Adds '--edit-model' and 'model' flags.
    If '--edit-model' is set, user text editor will be launched. If no
    changes will be done, execution will be stopped. Edited text will be
    passed into decorated function as 'model' parameter.
    If 'model' is set, it will be considered as model itself.
    If 'parse_json' is True, text will be considered as JSON and parsed
    for you.
    """
    def outer_wrapper(func):
        @six.wraps(func)
        @click.option(
            "--model-editor",
            is_flag=True,
            help=(
                "Fetch model and launch editor to fix stuff. Please pay "
                "attention that only 'data' field will be available for "
                "editing."
            )
        )
        @click.option(
            "--model",
            default=None,
            type=cli_param_types.JSON,
            help=(
                "Full model data. If this parameter is set, other options "
                "won't be used. This parameter is JSON dump of the model."
            )
        )
        @click.option(
            "--model-stdin",
            is_flag=True,
            help="Slurp model from stdin."
        )
        @click.pass_context
        def inner_wrapper(ctx, model_stdin, model_editor, model,
                          *args, **kwargs):
            if not model:
                if model_stdin:
                    stream = click.get_text_stream("stdin")
                    model = "".join(stream)
                elif model_editor:
                    fetch_function = getattr(
                        ctx.obj["client"], fetch_method_name)
                    model = fetch_function(kwargs[item_id])
                    if "data" in model:
                        updated_data = cli_utils.json_dumps(model["data"])
                        updated_data = click.edit(updated_data)
                        if not updated_data:
                            return
                        updated_data = cli_utils.json_loads(updated_data)
                        model = fetch_function(kwargs[item_id])
                        model["data"] = updated_data
                        model = cli_utils.json_dumps(model)
                    else:
                        model = cli_utils.json_dumps(model)
                        model = click.edit(model)
                if (model_stdin or model_editor) and not model:
                    return
            if model and parse_json and not isinstance(model, dict):
                if isinstance(model, bytes):
                    model = model.decode("utf-8")
                model = cli_utils.json_loads(model)
            kwargs["model"] = model
            return func(*args, **kwargs)
        return inner_wrapper
    return outer_wrapper

def base_command(command_class, paginate=False, filtered=False):
    """Decorator to group generic parameters used everywhere."""
    def decorator(func):
        func = provide_client(func)
        if paginate:
            func = add_pagination(func)
        if filtered:
            func = apply_filter(func)
        func = format_result(func)
        func = handle_errors(func)
        name = cli_utils.parameter_name(func.__name__)
        func = command_class.command(name=name)(func)
        return func
    return decorator

def apply_filter(func):
    """Decorator to support filtered output."""
    if not cli_utils.JSON_FILTERS:
        return func
    func = click.option(
        "--filtered",
        type=cli_param_types.FILTERED_OUTPUT,
        default="",
        help=(
            "Filter output using expression engines. Valid options are {0}."
            "To setup, you first need to put engine type upfront semicolon "
            "and expression after. Example: 'jq:.[]|.id'. Please use "
            "correspond documentation on engines."
        ).format(sorted(cli_utils.JSON_FILTERS)))(func)
    @six.wraps(func)
    def wrapper(filtered, *args, **kwargs):
        response = func(*args, **kwargs)
        if not filtered:
            return response
        expression, converter = filtered
        return converter(expression, response)
    return wrapper

