    return Configuration(**config)

class MySQLQueryExecutor(ActionRunner):
    @staticmethod
    async def create_instance(**kwargs) -> 'MySQLQueryExecutor':
        config = validate_config(kwargs)
        resource = await storage.driver.resource.load(config.source.id)
        return MySQLQueryExecutor(config, resource.credentials)

    def __init__(self, configuration: Configuration, auth_credentials: ResourceCredentials):
        self.pool = None
        self.config = configuration
        self.connection = auth_credentials.get_credentials(self, output=Connection)

    async def execute(self, payload):
        try:
            self.pool = await self.connection.connect(self.config.timeout)
            # Prepare statement data
            template_engine = DictTraverser(self._get_dot_accessor(payload))
            query_data = template_engine.reshape(self.config.data)
            self.console.log("Running query: {} with parameters: {}".format(self.config.query, query_data))

            async with self.pool.acquire() as connection:
                async with connection.cursor(aiomysql.DictCursor) as cursor:
                    if self.config.type == 'call':
                        # todo implement
                        return Result(port="result", value={"result": payload})
                    else:
                        if len(query_data) > 0:
                            await cursor.execute(self.config.query, tuple(query_data))
                        else:
                            await cursor.execute(self.config.query)

                        if self.config.type in ['insert', 'delete', 'update']:
                            await connection.commit()
                            if self.config.type == 'insert':
                                return Result(port="result", value={"last_insert_id": cursor.lastrowid})

                        if self.config.type == 'select':
                            rows = await cursor.fetchall()
                            rows = [self.convert_to_dict(record) for record in rows]
                            return Result(port="result", value={"result": rows})

                    return Result(port="result", value=payload)

        except Exception as ex:
            self.console.error(str(ex))
            return Result(port="error", value={"payload": payload, "error": str(ex)})

    async def cleanup(self):
        if self.pool:
            self.pool.close()
            await self.pool.wait_closed()

    async def handle_error(self):
        await self.cleanup()

    @staticmethod
    def convert_to_dict(record):
        def serialize_datetime(obj):
            """Custom JSON serializer for non-serializable objects"""
            if isinstance(obj, (datetime, date)):
                return obj.isoformat()
            return obj.decode('utf-8')

        serialized = json.dumps(dict(record), default=serialize_datetime)
        return json.loads(serialized)

