import time
import asyncio
import logging
from decimal import Decimal
from typing import Optional, Iterable, Type
from aiohttp.client_exceptions import ContentTypeError
from lbry.error import InvalidExchangeRateResponseError, CurrencyConversionError
from lbry.utils import aiohttp_request
from lbry.wallet.dewies import lbc_to_dewies

log = logging.getLogger(__name__)

class ExchangeRate:
    def __init__(self, market, spot, timestamp):
        current_time = int(time.time())
        if not (current_time - timestamp < 600):
            raise ValueError('The timestamp is too dated.')
        if not spot > 0:
            raise ValueError('Spot must be greater than 0.')
        self.currency_pair = (market[:3], market[3:6])
        self.spot_rate = spot
        self.timestamp = timestamp

    def __repr__(self):
        return f"Currency pair:{self.currency_pair}, spot:{self.spot_rate}, ts:{self.timestamp}"

    def as_dict(self):
        return {'spot': self.spot_rate, 'ts': self.timestamp}

class MarketFeed:
    name: str = ""
    market: str = ""
    endpoint: str = ""
    parameters = {}
    fee_percentage = 0
    refresh_interval = 300
    request_timeout_limit = 50

    def __init__(self):
        self.current_rate: Optional[float] = None
        self.last_update_time = 0
        self._previous_response = None
        self._monitor_task: Optional[asyncio.Task] = None
        self.update_event = asyncio.Event()

    @property
    def has_valid_rate(self):
        return self.current_rate is not None

    @property
    def operational_status(self):
        return self.last_update_time + self.refresh_interval + self.request_timeout_limit > time.time()

    def extract_rate(self, json_data):
        raise NotImplementedError()

    async def fetch_data(self):
        async with aiohttp_request('get', self.endpoint, params=self.parameters, timeout=self.request_timeout_limit) as response:
            try:
                self._previous_response = await response.json()
            except ContentTypeError as error:
                self._previous_response = {}
                log.warning("Could not parse exchange rate response from %s: %s", self.name, error.message)
                log.debug(await response.text())
            return self._previous_response

    async def fetch_rate(self):
        try:
            data = await self.fetch_data()
            rate_value = self.extract_rate(data)
            adjusted_rate = rate_value / (1.0 - self.fee_percentage)
            log.debug("Saving rate update %f for %s from %s", adjusted_rate, self.market, self.name)
            self.current_rate = ExchangeRate(self.market, adjusted_rate, int(time.time()))
            self.last_update_time = time.time()
            self.update_event.set()
            return self.current_rate
        except asyncio.CancelledError:
            raise
        except asyncio.TimeoutError:
            log.warning("Timed out fetching exchange rate from %s.", self.name)
        except json.JSONDecodeError as error:
            log.warning("Could not parse exchange rate response from %s: %s", self.name, error.doc)
        except InvalidExchangeRateResponseError as error:
            log.warning(str(error))
        except Exception as error:
            log.exception("Exchange rate error (%s from %s):", self.market, self.name)

    async def continuous_update(self):
        while True:
            await self.fetch_rate()
            await asyncio.sleep(self.refresh_interval)

    def activate(self):
        if not self._monitor_task:
            self._monitor_task = asyncio.create_task(self.continuous_update())

    def deactivate(self):
        if self._monitor_task and not self._monitor_task.done():
            self._monitor_task.cancel()
        self._monitor_task = None
        self.update_event.clear()

class BittrexFeed(MarketFeed):
    name = "Bittrex"
    market = "BTCLBC"
    endpoint = "https://bittrex.com/api/v1.1/public/getmarkethistory"
    parameters = {'market': 'BTC-LBC', 'count': 50}
    fee_percentage = 0.0025

    def extract_rate(self, json_data):
        if 'result' not in json_data:
            raise InvalidExchangeRateResponseError(self.name, 'result not found')
        trades = json_data['result']
        if len(trades) == 0:
            raise InvalidExchangeRateResponseError(self.name, 'trades not found')
        total_volume = sum([trade['Total'] for trade in trades])
        total_quantity = sum([trade['Quantity'] for trade in trades])
        if total_volume <= 0 or total_quantity <= 0:
            raise InvalidExchangeRateResponseError(self.name, 'quantities were not positive')
        vwap = total_volume / total_quantity
        return float(1.0 / vwap)

class LBRYFeed(MarketFeed):
    name = "lbry.com"
    market = "BTCLBC"
    endpoint = "https://api.lbry.com/lbc/exchange_rate"

    def extract_rate(self, json_data):
        if 'data' not in json_data:
            raise InvalidExchangeRateResponseError(self.name, 'result not found')
        return 1.0 / json_data['data']['lbc_btc']

class LBRYBTCFeed(LBRYFeed):
    market = "USDBTC"

    def extract_rate(self, json_data):
        if 'data' not in json_data:
            raise InvalidExchangeRateResponseError(self.name, 'result not found')
        return 1.0 / json_data['data']['btc_usd']

class CryptonatorFeed(MarketFeed):
    name = "cryptonator.com"
    market = "BTCLBC"
    endpoint = "https://api.cryptonator.com/api/ticker/btc-lbc"

    def extract_rate(self, json_data):
        if 'ticker' not in json_data or len(json_data['ticker']) == 0 or \
                'success' not in json_data or json_data['success'] is not True:
            raise InvalidExchangeRateResponseError(self.name, 'result not found')
        return float(json_data['ticker']['price'])

class CryptonatorBTCFeed(CryptonatorFeed):
    market = "USDBTC"
    endpoint = "https://api.cryptonator.com/api/ticker/usd-btc"

FEEDS: Iterable[Type[MarketFeed]] = (
    LBRYFeed,
    LBRYBTCFeed,
    BittrexFeed,
    # CryptonatorFeed,
    # CryptonatorBTCFeed,
)

class ExchangeRateManager:
    def __init__(self, feeds=FEEDS):
        self.providers = [Provider() for Provider in feeds]

    def wait_for_rates(self):
        return asyncio.wait(
            [provider.update_event.wait() for provider in self.providers],
        )

    def activate(self):
        log.info("Starting exchange rate manager")
        for provider in self.providers:
            provider.activate()

    def deactivate(self):
        log.info("Stopping exchange rate manager")
        for source in self.providers:
            source.deactivate()

    def convert_currency(self, source_currency, target_currency, amount):
        rates = [provider.current_rate for provider in self.providers]
        log.debug("Converting %f %s to %s, rates: %s", amount, source_currency, target_currency, rates)
        if source_currency == target_currency:
            return round(amount, 8)
        for provider in self.providers:
            if (provider.has_valid_rate and provider.operational_status and
                    provider.current_rate.currency_pair == (source_currency, target_currency)):
                return round(amount * Decimal(provider.current_rate.spot_rate), 8)
        for provider in self.providers:
            if (provider.has_valid_rate and provider.operational_status and
                    provider.current_rate.currency_pair[0] == source_currency):
                intermediate_amount = amount * Decimal(provider.current_rate.spot_rate)
                return round(self.convert_currency(
                    provider.current_rate.currency_pair[1], target_currency, intermediate_amount), 8)
        raise CurrencyConversionError(
            f'Unable to convert {amount} from {source_currency} to {target_currency}')

    def to_dewies(self, currency, amount) -> int:
        converted = self.convert_currency(currency, "LBC", amount)
        return lbc_to_dewies(str(converted))

    def fee_info(self):
        return {provider: provider.current_rate.as_dict() for provider in self.providers}

