def get_cache_info(*args, **kwargs):
    """
    Report on each cache.
    :returns: a dictionary with the cache names as the keys and values that
        include 'maxsize' and 'used', if known.
    """
    info_dict = {}
    for cache_name in LruCacheMetaclass.namedCaches:
        with LruCacheMetaclass.namedCaches[cache_name][1]:
            cache = LruCacheMetaclass.namedCaches[cache_name][0]
            info_dict[cache_name] = {
                'maxsize': cache.maxsize,
                'used': cache.currsize
            }
    if isTileCacheSetup():
        tileCache, tileLock = getTileCache()
        try:
            with tileLock:
                info_dict['tileCache'] = {
                    'maxsize': tileCache.maxsize,
                    'used': tileCache.currsize,
                    'items': getattr(tileCache, 'curritems' if hasattr(
                        tileCache, 'curritems') else 'currsize', None)
                }
        except Exception:
            pass
    return info_dict

