# Calculate summary statistics for requests based on their status 
def generate_requests_summary(request_list):
    aggregate_fields = ['status']
    aggregation_result = {}
    for req in request_list:
        for field_name in aggregate_fields:
            value = req[field_name]
            aggregation_result[value] = aggregation_result.get(value, 0) + 1
    return aggregation_result

# Extract request parameters from session data
def extract_request_info(request_obj):
    result_dict = {}
    req_status = request_obj.session['requestParams'].get('reqstatus', None)
    if req_status:
        req_status = req_status.strip()
        result_dict['reqstatus'] = req_status
    return result_dict

# Retrieve iDDS information associated with a specific task ID
def fetch_iDDS_data_for_task(task_id):
    subtitle_helper = SubstitleValue()
    transformation_data = None
    cursor = connection.cursor()
    cursor.execute(
        """
     select r.request_id, r.scope, r.name, r.request_type, r.transform_tag, r.workload_id, r.status, r.created_at request_created_at, r.updated_at request_updated_at, tr.transform_id, tr.transform_status, tr.in_status, tr.in_total_files, tr.in_processed_files, tr.out_status, tr.out_total_files, tr.out_processed_files, tr.out_created_at, tr.out_updated_at
         from ATLAS_IDDS.requests r
          join (
             select t.request_id, t.transform_id, t.workload_id, t.status transform_status, in_coll.status in_status, in_coll.total_files in_total_files, in_coll.processed_files in_processed_files,
             out_coll.status out_status, out_coll.total_files out_total_files, out_coll.processed_files out_processed_files, out_coll.created_at out_created_at, out_coll.updated_at out_updated_at
             from ATLAS_IDDS.transforms t
             left join (select coll_id , transform_id, status, total_files, processed_files, created_at, updated_at from ATLAS_IDDS.collections where relation_type = 0) in_coll on (t.transform_id = in_coll.transform_id)
             left join (select coll_id , transform_id, status, total_files, processed_files, created_at, updated_at from ATLAS_IDDS.collections where relation_type = 1) out_coll on (t.transform_id = out_coll.transform_id)
          ) tr on (r.request_id=tr.request_id and tr.workload_id={0})
            """.format(int(task_id)))
    transformation_data = dictfetchall(cursor)
    if len(transformation_data) > 0:
        # Convert keys to lowercase and map status values using subtitle helper
        transformation_data = {key.lower(): val for key, val in transformation_data[0].items()}
        mapping_table = subtitle_helper.substitleMap
        transformation_data['status'] = mapping_table['requests']['status'][transformation_data['status']]
        transformation_data['request_type'] = mapping_table['requests']['request_type'][
            transformation_data['request_type']]
        transformation_data['transform_status'] = mapping_table['requests']['transform_status'][
            transformation_data['transform_status']]
        if transformation_data['in_status'] is not None:
            transformation_data['in_status'] = mapping_table['requests']['in_status'][transformation_data['in_status']]
        if transformation_data['out_status'] is not None:
            transformation_data['out_status'] = mapping_table['requests']['out_status'][transformation_data['out_status']]
        if transformation_data['out_total_files'] != 0 and transformation_data['out_total_files'] is not None:
            transformation_data['pctprocessed'] = int(100. * transformation_data['out_processed_files'] / transformation_data['out_total_files'])
        else:
            transformation_data['pctprocessed'] = 0
    return transformation_data

# Determine if a task is an iDDS or HPO task based on split rule and task type
def identify_dds_task_type(task_details):
    if task_details['splitrule']:
        split_rules = str(task_details['splitrule']).split(',')
        if 'HO=1' in split_rules:
            return 'hpo'
    if task_details['tasktype']:
        if task_details['tasktype'] == "prod":
            return 'idds'
    return None

