from stats.util import make_repr, split_on_uppercase

DEFAULT_LOG = _logging.getLogger(__name__)

class HttpClientBase:
    """Base session manager for HTTP clients."""

    def __init__(
        self,
        server_url,
        settings=None,
        prefix_path="",
        suffix_path="",
        ssl_verify=True,
        connection_timeout=10,
        logger_instance=DEFAULT_LOG,
        error_type=Exception,
        client_agent=f"httpx/{_httpx.__version__}",
    ):
        """Set up the HTTP client instance."""
        self.__class__.__name__ = self.class_name
        self.settings = settings
        self.scheme, self.hostname, self.port_number = self._extract_url_parts(server_url)
        self.root_url = self._construct_url(self.scheme, self.hostname, self.port_number)
        self.prefix_path = prefix_path.strip("/")
        self.suffix_path = suffix_path.strip("/")
        self.ssl_verify = ssl_verify
        self.connection_timeout = connection_timeout
        self.logger = logger_instance
        self.error_type = error_type
        self.client_agent = client_agent

        sync_config = {
            "verify": self.ssl_verify,
            "base_url": self.root_url,
            "timeout": self.connection_timeout,
        }

        async_config = {
            "verify": self.ssl_verify,
            "base_url": self.root_url,
            "timeout": self.connection_timeout,
        }

        self._sync_client = _httpx.Client(**sync_config)
        self._async_client = _httpx.AsyncClient(**async_config)

    @classmethod
    def __init_subclass__(cls, class_name=None, **extra_kwargs):
        """Assign appropriate subclass name."""
        super().__init_subclass__(**extra_kwargs)
        cls.class_name = class_name or cls.__name__

    async def __aenter__(self):
        """Validate connectivity upon entering context."""
        is_available = await self._check_availability()
        if is_available:
            self.logger.debug("Session established with {}", self.root_url)
            return self
        else:
            raise self._create_error(f"Cannot establish session to {self.class_name}")

    async def __aexit__(self, exc_type=None, exc_value=None, traceback=None):
        """Clean up connection on exit."""
        self.logger.debug("Closing session with {}", self.root_url)
        await self._async_client.aclose()

    def __enter__(self):
        """Validate connectivity upon entering context."""
        is_available = self._check_connectivity()
        if is_available:
            self.logger.debug("Session established with {}", self.root_url)
            return self
        else:
            raise self._create_error(f"Cannot establish session to {self.class_name}")

    def __exit__(self, exc_type=None, exc_value=None, traceback=None):
        """Clean up connection on exit."""
        if exc_type is not None:
            self.logger.error(traceback)
        self._sync_client.close()

    def __repr__(self):
        """Return a user-friendly string representation."""
        return make_repr(self)

    def _create_error(self, msg, original_exc=None, **format_args):
        """Enhance error message with exception details if provided."""
        if original_exc is not None:
            msg = "{}: {}".format(str(msg), str(original_exc), **format_args)
        return self.error_type(msg)

    def _check_connectivity(self):
        """Perform low-level socket test to verify port availability."""
        self.logger.debug("Testing connection to {}", self.root_url)
        try:
            host_for_test = _re.sub(r"http(s)?\:\/\/", "", self.root_url)
            _socket.socket().connect((host_for_test, 443))
        except _socket.gaierror as err:
            raise self._create_error(
                f"{self.class_name} appears unreachable", err
            ) from None
        return True

    async def _check_availability(self):
        """Async version of connectivity check."""
        self.logger.debug("Testing connection to {}", self.root_url)
        try:
            reader, writer = await _asyncio.open_connection(self.hostname, self.port_number)
        except _socket.gaierror as err:
            raise self._create_error(
                f"{self.class_name} appears unreachable at {self.root_url}", err
            )
        if reader or writer:
            return True
        else:
            return False

    @staticmethod
    def _construct_url(scheme, host, port):
        port_str = str(port)
        if port_str == "80":
            port_str = ""
            scheme = "http"
        elif port_str == "443":
            port_str = ""
            scheme = "https"
        if port_str != "":
            port_str = f":{port_str}"
        return "{scheme}://{host}{port}".format(
            scheme=scheme, host=host, port=port_str
        )

    @staticmethod
    def _extract_url_parts(url_string):
        [parsed] = _re.findall(r"^(http[s]?):\/\/([^:]+)\:?(\d*)$", url_string)
        scheme, host, port = parsed
        return scheme, host, int(port)

    @staticmethod
    def _normalize_dict(input_dict):
        return json_module.loads(json_module.dumps(input_dict, default=str))

    def _handle_response(self, raw_response):
        result = {}
        try:
            result = raw_response.json()
        except json_module.JSONDecodeError:
            try:
                result = json_module.loads(raw_response)
            except (json_module.JSONDecodeError, TypeError):
                self.logger.error("Failed to parse JSON in response {}", repr(raw_response))
                result = {"data": raw_response.text}
        return result

    @staticmethod
    def _describe_exception(exception_obj):
        """Extract and format exception information."""
        if not isinstance(exception_obj, BaseException):
            raise TypeError(f"'{repr(exception_obj)}' is not an exception.")

        def get_class_name(exc):
            return " ".join(split_on_uppercase(exc.__class__.__name__))

        def get_first_line(doc):
            return doc.strip().split("\n")[0].strip(".")

        exc_name = get_class_name(exception_obj)
        description_parts = []

        if exception_obj.__doc__:
            summary = get_first_line(exception_obj.__doc__)
            description_parts.append(f"{exc_name} ({summary})")
        else:
            description_parts.append(exc_name)

        if exception_obj.__cause__:
            cause_name = get_class_name(exception_obj.__cause__)
            if exception_obj.__cause__.__doc__:
                cause_summary = get_first_line(exception_obj.__cause__.__doc__)
                description_parts.append(f"{cause_name} ({cause_summary})")
            else:
                description_parts.append(cause_name)

        return ", caused by ".join(description_parts)

    def _prepare_request(self, **kwargs):
        """Transform request parameters into structure compatible with http library."""
        # Standard Library
        from operator import itemgetter
        valid_methods = ("GET", "POST", "PUT", "DELETE", "HEAD", "PATCH")

        (
            method,
            path,
            resource_id,
            custom_headers,
            query_params,
            payload,
            request_timeout,
            needs_response,
        ) = itemgetter(*kwargs.keys())(kwargs)

        if method.upper() not in valid_methods:
            raise self._create_error(
                f'Method must be one of {", ".join(valid_methods)}. '
                f"Received: {str(method)}"
            )

        path_segments = [
            segment
            for segment in (
                "",
                self.prefix_path.strip("/"),
                path.strip("/"),
                self.suffix_path.strip("/"),
                resource_id,
            )
            if segment
        ]
        final_path = "/".join(path_segments)

        request_data = {
            "method": method,
            "url": final_path,
            "headers": {"user-agent": self.client_agent},
        }

        if custom_headers is not None:
            request_data.update({"headers": custom_headers})

        if query_params is not None:
            normalized_params = {str(k): str(v) for k, v in query_params.items() if v is not None}
            request_data["params"] = normalized_params

        if payload is not None:
            if not isinstance(payload, dict):
                raise self._create_error(f"Payload must be a dict, got: {str(payload)}")
            request_data["json"] = self._normalize_dict(payload)

        if request_timeout is not None:
            if not isinstance(request_timeout, int):
                try:
                    request_timeout = int(request_timeout)
                except TypeError:
                    raise self._create_error(
                        f"Timeout value must be an integer, got: {str(request_timeout)}"
                    )
            request_data["timeout"] = request_timeout

        self.logger.debug("Built request parameters {}", request_data)
        return request_data

    async def _async_request(  # noqa: C901
        self,
        method,
        endpoint,
        item=None,
        headers=None,
        params=None,
        data=None,
        timeout=None,
        expect_response=False,
    ):
        """Execute asynchronous HTTP request."""
        prepared_request = self._prepare_request(
            method=method,
            endpoint=endpoint,
            item=item,
            headers=None,
            params=params,
            data=data,
            timeout=timeout,
            expect_response=expect_response,
        )

        try:
            response = await self._async_client.request(**prepared_request)
            if response.status_code not in range(200, 300):
                status = _httpx.StatusCode(response.status_code)
                error_details = self._handle_response(response)
                raise self._create_error(
                    f'{status.name.replace("_", " ")}: {error_details}', level="danger"
                ) from None
        except _httpx.HTTPError as network_error:
            raise self._create_error(self._describe_exception(network_error)) from None

        return self._handle_response(response)

    async def _aget(self, endpoint, **kwargs):
        return await self._async_request(method="GET", endpoint=endpoint, **kwargs)

    async def _apost(self, endpoint, **kwargs):
        return await self._async_request(method="POST", endpoint=endpoint, **kwargs)

    async def _aput(self, endpoint, **kwargs):
        return await self._async_request(method="PUT", endpoint=endpoint, **kwargs)

    async def _adelete(self, endpoint, **kwargs):
        return await self._async_request(method="DELETE", endpoint=endpoint, **kwargs)

    async def _apatch(self, endpoint, **kwargs):
        return await self._async_request(method="PATCH", endpoint=endpoint, **kwargs)

    async def _ahead(self, endpoint, **kwargs):
        return await self._async_request(method="HEAD", endpoint=endpoint, **kwargs)

    def _request(  # noqa: C901
        self,
        method,
        endpoint,
        item=None,
        headers=None,
        params=None,
        data=None,
        timeout=None,
        expect_response=False,
    ):
        """Execute synchronous HTTP request."""
        prepared_request = self._prepare_request(
            method=method,
            endpoint=endpoint,
            item=item,
            headers=None,
            params=params,
            data=data,
            timeout=timeout,
            expect_response=expect_response,
        )

        try:
