            if response.status_code not in range(200, 300):
                status = _httpx.StatusCode(response.status_code)
                error_details = self._handle_response(response)
                raise self._create_error(
                    f'{status.name.replace("_", " ")}: {error_details}', level="danger"
                ) from None
        except _httpx.HTTPError as network_error:
            raise self._create_error(
                self._describe_exception(network_error), level="danger"
            ) from None

        return self._handle_response(response)

    def _get(self, endpoint, **kwargs):
        return self._request(method="GET", endpoint=endpoint, **kwargs)

    def _post(self, endpoint, **kwargs):
        return self._request(method="POST", endpoint=endpoint, **kwargs)

    def _put(self, endpoint, **kwargs):
        return self._request(method="PUT", endpoint=endpoint, **kwargs)

    def _delete(self, endpoint, **kwargs):
