# Extension to display and select windows from dmenu
from libqtile.extension.dmenu import Dmenu
from libqtile.scratchpad import ScratchPad

class WindowSelector(Dmenu):
    """
    Display a vertical list of all active windows using dmenu.
    Allows switching to the chosen window.
    """
    defaults = [
        ("item_template", "{group}.{id}: {window}", "format string for menu entries"),
        (
            "include_all_groups",
            True,
            "If True, include windows from all groups; otherwise only current group",
        ),
        ("menu_height", "80", "Number of lines displayed vertically. Set to None for inline"),
    ]

    def __init__(self, **config):
        Dmenu.__init__(self, **config)
        self.add_defaults(WindowSelector.defaults)

    def collect_windows(self):
        counter = 0
        self.window_mapping = {}
        if self.include_all_groups:
            windows = self.qtile.windows_map.values()
        else:
            windows = self.qtile.current_group.windows

        for window in windows:
            if window.group and not isinstance(window.group, ScratchPad):
                entry = self.item_template.format(
                    group=window.group.label or window.group.name,
                    id=counter,
                    window=window.name
                )
                self.window_mapping[entry] = window
                counter += 1

    def execute(self):
        self.collect_windows()
        result = super().run(items=self.window_mapping.keys())
        try:
            selected = result.rstrip("\n")
        except AttributeError:
            # result is not a string (e.g., Popen object when no items exist)
            return

        try:
            target_window = self.window_mapping[selected]
        except KeyError:
            # Selected window may have been closed during menu display
            return

        current_screen = self.qtile.current_screen
        current_screen.set_group(target_window.group)
        target_window.group.focus(target_window)

# Test that file hashing is correct using cached file line count
from pytest_cases import parametrize_with_cases
from wingline.plumbing import Pipeline, file
from wingline.types import PayloadIterable

def append_a_field(source: PayloadIterable) -> PayloadIterable:
    for record in source:
        record["_a"] = "a"
        yield record

def append_b_field(source: PayloadIterable) -> PayloadIterable:
    for record in source:
        record["_b"] = "b"
        yield record

@parametrize_with_cases(
    "filepath,hash_value,storage_type,encoding,total_items", cases="tests.cases.files"
)
def test_cached_file_line_count(
    filepath, hash_value, storage_type, encoding, total_items, testing_cache
):
    test_pipeline = Pipeline(file.File(filepath), append_a_field, append_b_field)
    output_records = list(test_pipeline)
    assert len(output_records) == total_items

    # Verify that the expected keys were added to each record
    assert [record["_a"] for record in output_records] == ["a"] * total_items
    assert [record["_b"] for record in output_records] == ["b"] * total_items

