# Calculate and process trip data using UDFs and Spark
import datetime
import re
import sys
import time
from google.cloud import storage
from py4j.protocol import Py4JJavaError
from pyspark.sql import SparkSession
from pyspark.sql.functions import UserDefinedFunction
from pyspark.sql.types import FloatType, IntegerType, StringType

def convert_trip_duration(duration):
    """Transform trip duration to seconds. Return None if invalid or negative."""
    if not duration:
        return None
    match = re.match(r"\d*.\d*", duration)
    if not match:
        return None
    value = float(match[0])
    if value < 0:
        return None
    if "m" in duration:
        value *= 60
    elif "h" in duration:
        value *= 60 * 60
    return int(value)

def normalize_station_name(name):
    """Replace '/' with '&' in station names."""
    return name.replace("/", "&") if name else None

def classify_user_type(user):
    """Classify user as 'Subscriber' or 'Customer' based on input."""
    if not user:
        return None
    if user.lower().startswith("sub"):
        return "Subscriber"
    elif user.lower().startswith("cust"):
        return "Customer"

def parse_angle(angle_str):
    """Parse angle from DMS or decimal degrees format."""
    if not angle_str:
        return None
    dms_match = re.match(r'(-?\d*).(-?\d*)\'(-?\d*)"', angle_str)
    if dms_match:
        degrees = int(dms_match[1])
        minutes = int(dms_match[2])
        seconds = int(dms_match[3])
        return degrees + minutes / 60 + seconds / (60 * 60)
    decimal_match = re.match(r"\d*.\d*", angle_str)
    if decimal_match:
        return float(decimal_match[0])

def calculate_time_info(duration, start_time, end_time):
    """Compute missing time fields using available values."""
    fmt = "%Y-%m-%dT%H:%M:%S"

    # Normalize timestamps
    if start_time:
        if "." in start_time:
            start_time = start_time[: start_time.index(".")]
        start_time = datetime.datetime.strptime(start_time, fmt)
    if end_time:
        if "." in end_time:
            end_time = end_time[: end_time.index(".")]
        end_time = datetime.datetime.strptime(end_time, fmt)
    if duration:
        duration = datetime.timedelta(seconds=duration)

    # Fill in missing values
    if start_time and end_time and not duration:
        duration = end_time - start_time
    elif duration and end_time and not start_time:
        start_time = end_time - duration
    elif duration and start_time and not end_time:
        end_time = start_time + duration

    # Convert back to primitives
    result_duration = int(duration.total_seconds()) if duration else None
    result_start = start_time.strftime(fmt) if start_time else None
    result_end = end_time.strftime(fmt) if end_time else None

    return (result_duration, result_start, result_end)

def extract_duration(duration, start_time, end_time):
    """Extract computed duration from time calculation."""
    return calculate_time_info(duration, start_time, end_time)[0]

def extract_start_time(duration, start_time, end_time):
    """Extract computed start time from time calculation."""
    return calculate_time_info(duration, start_time, end_time)[1]

def extract_end_time(duration, start_time, end_time):
    """Extract computed end time from time calculation."""
    return calculate_time_info(duration, start_time, end_time)[2]

if __name__ == "__main__":
    bucket_name = sys.argv[1]
    table_name = sys.argv[2]

    spark = SparkSession.builder.appName("data_processing").getOrCreate()

    try:
        df = spark.read.format("bigquery").option("table", table_name).load()
    except Py4JJavaError as e:
        raise Exception(f"Error reading {table_name}") from e

    # Remove unnecessary column
    df = df.drop("gender")

    # Apply single-column UDFs
    single_udfs = {
        "start_station_name": UserDefinedFunction(normalize_station_name, StringType()),
        "end_station_name": UserDefinedFunction(normalize_station_name, StringType()),
        "tripduration": UserDefinedFunction(convert_trip_duration, IntegerType()),
        "usertype": UserDefinedFunction(classify_user_type, StringType()),
        "start_station_latitude": UserDefinedFunction(parse_angle, FloatType()),
        "start_station_longitude": UserDefinedFunction(parse_angle, FloatType()),
        "end_station_latitude": UserDefinedFunction(parse_angle, FloatType()),
        "end_station_longitude": UserDefinedFunction(parse_angle, FloatType()),
    }

    for col_name, udf_func in single_udfs.items():
        df = df.withColumn(col_name, udf_func(col_name))

    # Apply multi-column UDFs
    multi_udfs = {
        "tripduration": {
            "udf": UserDefinedFunction(extract_duration, IntegerType()),
            "params": ("tripduration", "starttime", "stoptime"),
        },
        "starttime": {
            "udf": UserDefinedFunction(extract_start_time, StringType()),
            "params": ("tripduration", "starttime", "stoptime"),
        },
        "stoptime": {
            "udf": UserDefinedFunction(extract_end_time, StringType()),
            "params": ("tripduration", "starttime", "stoptime"),
        },
    }

    for col_name, obj in multi_udfs.items():
        df = df.withColumn(col_name, obj["udf"](*obj["params"]))

    # Show sample rows
    df.show(n=20)

    # Write results to GCS
    if "--dry-run" in sys.argv:
        print("Data will not be uploaded to GCS")
    else:
        timestamp_path = str(time.time())
        temp_location = "gs://" + bucket_name + "/" + timestamp_path

        print("Uploading data to GCS...")
        (
            df.write
            .options(codec="org.apache.hadoop.io.compress.GzipCodec")
            .csv(temp_location)
        )

        storage_client = storage.Client()
        source_bucket = storage_client.get_bucket(bucket_name)
        blobs = list(source_bucket.list_blobs(prefix=timestamp_path))

        target_path = "clean_data/"
        for blob in blobs:
            file_match = re.match(timestamp_path + r"/(part-\d*)[0-9a-zA-Z\-]*.csv.gz", blob.name)
            if file_match:
                new_blob_name = target_path + file_match[1] + ".csv.gz"
                source_bucket.copy_blob(blob, source_bucket, new_blob_name)

        for blob in blobs:
            blob.delete()

        print(
            "Data successfully uploaded to " + "gs://" + bucket_name + "/" + target_path
        )

# Modified version of the original code with Type I clone transformations
class BoundingBoxTransformer(object):
    def __str__(self) -> str:
        raise NotImplementedError
    def __call__(self, bounding_box: List[float], img_dims: Tuple[int, int]) -> List[float]:
        raise NotImplementedError

class ClipBBoxToCanvas(BoundingBoxTransformer):
    def __str__(self):
        return "clip2canvas"

    def __call__(self, bounding_box: List[float], img_dims: Tuple[int, int]) -> List[float]:
        canvas_w, canvas_h = img_dims
        left, top, box_width, box_height = tuple(bounding_box)

        if left < 0.0:
            box_width += left
            left = 0.0

        if top < 0.0:
            box_height += top
            top = 0.0

        if left + box_width >= canvas_w:
            box_width = canvas_w - left

        if top + box_height >= canvas_h:
            box_height = canvas_h - top

        return [left, top, box_width, box_height]

class SquareBBox(BoundingBoxTransformer):
    def __call__(self, bounding_box: List[float], img_dims: Tuple[int, int]) -> List[float]:
        x1, y1, w, h = bounding_box[0], bounding_box[1], bounding_box[2], bounding_box[3]
        max_side = max(w, h)
        side_extra_w = (max_side - w) / 2
        side_extra_h = (max_side - h) / 2
        adjusted_x = x1 - side_extra_w
        adjusted_y = y1 - side_extra_h
        return [adjusted_x, adjusted_y, max_side, max_side]

    def __str__(self) -> str:
        return "square"

class AdaptivePadding(BoundingBoxTransformer):
    def __init__(self, pad_ratio: float):
        self.pad_ratio = pad_ratio

    def __call__(self, bounding_box: List[float], img_dims: Tuple[int, int]) -> List[float]:
        width_padding = self.pad_ratio * bounding_box[2]
        height_padding = self.pad_ratio * bounding_box[3]
        return [
            (bounding_box[0] - width_padding),
            (bounding_box[1] - height_padding),
            (bounding_box[2] + 2 * width_padding),
            (bounding_box[3] + 2 * height_padding),
        ]

    def __str__(self) -> str:
        return "pad_ad:{ratio:.2f}".format(ratio=self.pad_ratio)

class FixedPadding(BoundingBoxTransformer):
    """
    Increases the bounding box by a fixed amount in all directions. Thus, both width and height 
    will grow by twice the padding value.
    Padding can be negative to shrink the box.
    """
    def __init__(self, pad_size: int):
        self.pad_size = pad_size

    def __str__(self) -> str:
        return "pad:{size}".format(size=self.pad_size)

    def __call__(self, bounding_box: List[float], img_dims: Tuple[int, int]) -> List[float]:
        return [
            bounding_box[0] - self.pad_size,
            bounding_box[1] - self.pad_size,
            bounding_box[2] + 2 * self.pad_size,
            bounding_box[3] + 2 * self.pad_size,
        ]

class BoundingBoxPipeline(BoundingBoxTransformer):
    def __init__(self, operations: List[BoundingBoxTransformer]):
        self.operations = operations

    def __str__(self) -> str:
        return "-".join([op.__str__() for op in self.operations])

    def __call__(self, bounding_box: List[float], img_dims: Tuple[int, int]) -> List[float]:
        for op in self.operations:
            bounding_box = op.__call__(bounding_box, img_dims)
        return bounding_box

# Modified version with renamed variables and restructured code
import torch
import torch.nn as nn
from mmdet.models.builder import LOSSES
from mmdet.models.losses.utils import weighted_loss
from mmdet3d.ops.rotated_iou import cal_giou_3d, cal_iou_3d
from mmdet3d.core.bbox import AxisAlignedBboxOverlaps3D

@weighted_loss
def iou_3d_loss_v2(predictions, targets):
    return 1 - cal_iou_3d(predictions[None, ...], targets[None, ...])

@weighted_loss
def giou_3d_loss_v2(predictions, targets):
    return cal_giou_3d(predictions[None, ...], targets[None, ...])[0][0]

@weighted_loss
def axis_aligned_iou_loss_v2(predictions, targets):
    def _reformat_bbox(bbox):
        return torch.stack((
            bbox[..., 0] - bbox[..., 3] / 2,
            bbox[..., 1] - bbox[..., 4] / 2,
            bbox[..., 2] - bbox[..., 5] / 2,
            bbox[..., 0] + bbox[..., 3] / 2,
            bbox[..., 1] + bbox[..., 4] / 2,
            bbox[..., 2] + bbox[..., 5] / 2,
        ), dim=-1)

    aligned_iou = AxisAlignedBboxOverlaps3D()(
        _reformat_bbox(predictions), _reformat_bbox(targets), is_aligned=True)
    loss_iou = 1 - aligned_iou
    return loss_iou

class IoU3DMixin_v2(nn.Module):
    """Modified version of IoU3DMixin"""
    def __init__(self, loss_op, reduction_mode='mean', weight_factor=1.0):
        super().__init__()
        self.loss_op = loss_op
        self.reduction_mode = reduction_mode
        self.weight_factor = weight_factor

    def forward(self,
                predictions,
                targets,
                sample_weights=None,
                avg_factor=None,
                override_reduction=None,
                **extra_kwargs):
        if sample_weights is not None and not torch.any(sample_weights > 0):
            return predictions.sum() * sample_weights.sum()

        assert override_reduction in (None, 'none', 'mean', 'sum')
        final_reduction = (
            override_reduction if override_reduction else self.reduction_mode)

        if sample_weights is not None and sample_weights.dim() > 1:
            sample_weights = sample_weights.mean(-1)

        computed_loss = self.weight_factor * self.loss_op(
            predictions,
            targets,
            sample_weights,
            reduction=final_reduction,
            avg_factor=avg_factor,
            **extra_kwargs)
        return computed_loss

@LOSSES.register_module()
class IoU3DLoss_v2(IoU3DMixin_v2):
    def __init__(self, yaw_enabled=True, **kwargs):
        loss_func = iou_3d_loss_v2 if yaw_enabled else axis_aligned_iou_loss_v2
        super().__init__(loss_op=loss_func, **kwargs)

@LOSSES.register_module()
class GIoU3DLoss_v2(IoU3DMixin_v2):
    def __init__(self, **kwargs):
        super().__init__(loss_op=giou_3d_loss_v2, **kwargs)

