        'previous': deviation_context['previous']
    }

class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n == 0:
            return 1.0
        if x == 0.0:
            return 0.0

        if n > 0:
            return self.fast_pow(x, n)
        else:
            return 1.0 / self.fast_pow(x, abs(n))

    def fast_pow(self, base, exponent):
        result = 1.0
        current_power = base

        while exponent > 0:
            if exponent % 2 == 1:
                result *= current_power
            current_power *= current_power
            exponent //= 2

        return result

# Modified version with renamed variables, changed literals, and reordered statements
import sys
import re
from enum import Enum
from pizzabot.house import House
from pizzabot.errors import NoInputError, BadInputFormatError, BadHouseCoordinatesError, NotSupportedInputTypeError, MissingPropertyError

class InputKind(Enum):
    """All available input types"""
    CommandResponseInput = 0
    TerminalInput = 1
    FileInput = 2
    LiteralInput = 3

class BaseInput:
    """Abstract base class for all input mechanisms"""
    def __process_data(self, raw_text: str) -> list[House]:
        """Transforms the raw text into a collection of house objects"""
        # Strip whitespace to simplify regex matching
        raw_text = raw_text.replace(" ", "")

        # Regex breakdown:
        #   - ^\d+x\d+: matches exactly one NUMBERxNUMBER at start
        #   - (\(\d+\,\d+\))+$: followed by one or more (NUMBER,NUMBER) patterns until end
        full_pattern = "^\d+x\d+(\(\d+\,\d+\))+$"
        grid_pattern = "^\d+x\d+"
        coords_pattern = "(\d+\,\d+)"

        match = re.search(full_pattern, raw_text)
        if not match:
            raise BadInputFormatError("Invalid format, expected: \"NUMxNUM (NUM, NUM) (NUM, NUM)\"")

        # Extract grid dimensions
        grid_part = re.findall(grid_pattern, raw_text)[0].split("x")
        grid_dims = [int(item) for item in grid_part]

        # Extract coordinates
        coord_strings = re.findall(coords_pattern, raw_text)
        houses_list = []

        for coord_str in coord_strings:
            x_val, y_val = [int(val) for val in coord_str.split(",")]

            # Validate that house is within grid bounds
            if x_val > grid_dims[0] or y_val > grid_dims[1]:
                raise BadHouseCoordinatesError("A house location falls outside the defined grid area.")

            houses_list.append(House(x_val, y_val))

        return houses_list

    def fetch_houses(self) -> list[House]:
        """Retrieves and processes input data"""
        raw_input = self._obtain_input()
        return self.__process_data(raw_input)

class CommandResponseInput(BaseInput):
    """Handles command-line argument inputs"""
    def _obtain_input(self) -> str:
        """Fetches the CLI argument value"""
        if len(sys.argv) < 2:
            raise NoInputError("No input provided. Please specify grid size and house coordinates.")
        return sys.argv[1]

class TerminalInput(BaseInput):
    """Prompts user for text input"""
    def _obtain_input(self) -> str:
        """Waits for user to enter text"""
        return input()

class FileInput(BaseInput):
    """Processes file-based inputs"""
    def __init__(self):
        self.file_path = None

    def _obtain_input(self) -> str:
        """Reads content from file; path must be set via set_file_location() first"""
        if self.file_path is None:
            raise MissingPropertyError("Set the file path using set_file_location() before reading.")

        with open(self.file_path, 'r') as source_file:
            line = source_file.readline()
        return line

    def set_file_location(self, path: str) -> None:
        """Sets the file path BEFORE calling _obtain_input()"""
        self.file_path = path

class LiteralInput(BaseInput):
    """Uses string literals provided directly in code"""
    def __init__(self):
        self.literal_value = None

    def _obtain_input(self) -> str:
        """Returns stored literal; must be set via set_literal_value() first"""
        if self.literal_value is None:
            raise MissingPropertyError("Provide a literal value using set_literal_value().")
        return self.literal_value

    def set_literal_value(self, value: str) -> None:
        """Stores the literal string BEFORE calling _obtain_input()"""
        self.literal_value = value

def instantiate_input(kind: 'InputKind') -> 'BaseInput':
    """Factory function to create appropriate input handler"""
    input_constructors = {
        InputKind.CommandResponseInput: CommandResponseInput,
        InputKind.TerminalInput: TerminalInput,
        InputKind.FileInput: FileInput,
        InputKind.LiteralInput: LiteralInput
    }

    if kind not in input_constructors:
        raise NotSupportedInputTypeError("Only values from InputKind enum are supported.")

    return input_constructors[kind]()

import copy
import hashlib
import logging
import d1_common.const
import d1_common.types
import d1_common.types.exceptions
import d1_common.url
import d1_common.util
import d1_common.utils.ulog
import django.conf
import django.core.cache
import django.db.models

def apply_pagination_filter(request, query, total_count):
    url_params = d1_common.url.parseUrl(request.get_full_path())
    offset_int = _validate_and_get_param(url_params, "start", 0)
    limit_int = _validate_and_get_param(
        url_params, "count", d1_common.const.DEFAULT_SLICE_SIZE
    )
    _ensure_valid_offset(offset_int, limit_int, total_count)
    limit_int = _cap_limit_if_needed(offset_int, limit_int, total_count)
    authn_subjects = _extract_authenticated_subjects(request)
    logging.debug(
        "Applying pagination filter. offset={} limit={} total={} subjects={}".format(
            offset_int, limit_int, total_count, ",".join(authn_subjects)
        )
    )
    last_record_ts = _retrieve_cached_last_record(
        url_params, offset_int, total_count, authn_subjects
    )
    if last_record_ts:
        query = _apply_optimized_pagination(query, last_record_ts, limit_int)
    else:
        query = _apply_standard_pagination(query, offset_int, limit_int, total_count)
    return query, offset_int, limit_int

def store_last_record_in_cache(request, query, offset_int, total_count, order_fields):
    """"""
    url_params = d1_common.url.parseUrl(request.get_full_path())
    authn_subjects = _extract_authenticated_subjects(request)
    cache_key = _create_cache_identifier(
        url_params, offset_int + query.count(), total_count, authn_subjects
    )
    last_obj = query[query.count() - 1] if query.count() else None
    last_values = (
        tuple([getattr(last_obj, field) for field in order_fields]) if last_obj else None
    )
    django.core.cache.cache.set(cache_key, last_values)
    logging.debug('Cache updated. key="{}" last={}'.format(cache_key, last_values))

# Private helper functions
def _validate_and_get_param(url_params, param_name, default_value):
    """Return ``param_str`` converted to an integer.
    If string cannot be parsed as int or is negative, raise InvalidRequest.
    """
    param_str = url_params["query"].get(param_name, default_value)
    try:
        val = int(param_str)
    except ValueError:
        raise d1_common.types.exceptions.InvalidRequest(
            0,
            'Pagination parameter is not a valid integer. {}="{}"'.format(
                param_name, param_str
            ),
        )
    if val < 0:
        raise d1_common.types.exceptions.InvalidRequest(
            0,
            'Pagination parameter must be non-negative. {}="{}"'.format(
                param_name, param_str
            ),
        )
    return val

def _ensure_valid_offset(offset_int, limit_int, total_count):
    """Verify that the requested offset is within bounds of available records.
    Ensures that a valid slice can be created.
    """
    if total_count and offset_int >= total_count:
        raise d1_common.types.exceptions.InvalidRequest(
            0,
            "Requested invalid slice. offset={} limit={} total={}".format(
                offset_int, limit_int, total_count
            ),
        )

def _cap_limit_if_needed(offset_int, limit_int, total_count):
    """Reduce the requested limit if there aren't enough records to satisfy the full slice.
    Assumes offset has already been validated to be less than total count.
    """
    if offset_int + limit_int > total_count:
        limit_int = total_count - offset_int
    limit_int = min(limit_int, django.conf.settings.MAX_SLICE_ITEMS)
    return limit_int

# def _get_pagination_params(query_dict):
#   return query_dict['start'], query_dict['count']

def _extract_authenticated_subjects(request):
    return list(sorted(request.all_subjects_set))

def _apply_optimized_pagination(query, last_record_ts, limit_int):
    logging.debug(
        "Using optimized pagination. last={} limit={}".format(last_record_ts, limit_int)
    )
    last_timestamp, last_identifier = last_record_ts
    return query.filter(
        django.db.models.Q(timestamp__gt=last_timestamp)
        | django.db.models.Q(timestamp__exact=last_timestamp, id__gt=last_identifier)
    )[:limit_int]

def _apply_standard_pagination(query, offset_int, limit_int, total_count):
    """Apply slicing using OFFSET/LIMIT which may be inefficient for large datasets.
    """
    logging.debug(
        "Using standard pagination. offset={} limit={} total={} ".format(
            offset_int, limit_int, total_count
        )
    )
    if not limit_int:
        return query.none()
    else:
        return query[offset_int : offset_int + limit_int]

def _retrieve_cached_last_record(url_params, offset_int, total_count, authn_subjects):
    """Return None if no cached value exists."""
    cache_key = _create_cache_identifier(url_params, offset_int, total_count, authn_subjects)
    try:
        last_record_ts = django.core.cache.cache.get(cache_key)
    except KeyError:
        last_record_ts = None
    logging.debug('Cache lookup. key="{}" -> last_record_ts={}'.format(cache_key, last_record_ts))
    return last_record_ts

def _create_cache_identifier(url_params, offset_int, total_count, authn_subjects):
    """Build a cache key for REST URLs used during pagination.

    When checking current request: offset_int is 0 or the start from current request.
    When preparing next request: offset_int is current offset + count.

    The URL remains same except 'start' increases by items returned.
    Adjustments to slice size are allowed but won't affect caching.
    Active subjects included in key for security during pagination.

    URL dict normalized via JSON serialization with sorted keys; SHA256 hash used
    for consistent key length and improved cache distribution.
    """
    temp_url = copy.deepcopy(url_params)
    temp_url["query"].pop("start", None)
    temp_url["query"].pop("count", None)
    cache_data = d1_common.util.serialize_to_normalized_compact_json(
        {
            "url": temp_url,
            "offset": offset_int,
            "total": total_count,
            "subjects": authn_subjects,
        }
    )
    logging.debug("cache_data={}".format(cache_data))
    return hashlib.sha256(cache_data.encode("utf-8")).hexdigest()

def collatz_sequence():

    # Accumulator variable for the current value
    current_value = 0
    print("Enter number:")

    # Continue looping until the result becomes 1
    while current_value != 1:

        # Handle potential non-integer inputs with try-except
        try:

            # Input from user
            input_number = int(input())

            if input_number % 2 == 0:
                current_value = input_number // 2
            else:
                current_value = 3 * input_number + 1
            print(current_value)
        except:
            print("You must enter an integer number")
collatz_sequence()

import numpy as np
from constants import *
from orbit_util import trace_orbit, sign, get_dist_to_good, gravity_step, trace_orbit_np
from states import State, JoinResult, ThrustPredictor, Thrust
from orbiter import LaserShipStrategy

def min_abs_diff(x, y):
    return min(abs(x), abs(y))

def stat_cost(x):
    return x[0] + LASER_COST * x[1] + REGEN_COST * x[2] + LIVES_COST * x[3]

class SwarmerStrategy(object):
    def __init__(self, homing_horizon=16, homing_T_threshold=64, homing_dist_threshold=3, printships=False):
        self.T = 0
        self.homing_horizon = homing_horizon
        self.homing_T_threshold = homing_T_threshold
        self.homing_dist_threshold = homing_dist_threshold
        self.thrust_predictors = {}
        self.mothership_id = None
        self.mothership_strategy = LaserShipStrategy()
        self.printships = printships

    def pick_stats(self, res):
        joinres = JoinResult.parse(res)
        self.laser_ship_stats = [20, 32, 8, 1] if joinres.budget > 490 else [0, 0, 0, 0]
        laser_budget = stat_cost(self.laser_ship_stats)
        swarm_budget = joinres.budget - laser_budget
        n = swarm_budget // 6
        swarm_fuel = swarm_budget - LIVES_COST * n
        return [swarm_fuel + self.laser_ship_stats[0], self.laser_ship_stats[1], self.laser_ship_stats[2],
                n + self.laser_ship_stats[3]]

    def reset_precomputed(self):
        self.enemy_location = {}
        self.enemy_thrust = {}

    def precompute_enemy_stuff(self, enemy_ship):
        predicted_thrust = self.thrust_predictors[
            enemy_ship.id].predict_only_call_from_precompute() if enemy_ship.fuel > 0 else Thrust(0, 0)
        ex, ey = enemy_ship.next_round_expected_location(predicted_thrust)
        self.enemy_location[enemy_ship.id] = ex, ey
        self.enemy_thrust[enemy_ship.id] = predicted_thrust

    def choose_explode_target(self, my_ship, thrust_action, enemy_ships):
        mindist = 10000
        ship = enemy_ships[0]
        if len(enemy_ships) == 1:
            return ship
        for enemy_ship in enemy_ships:
            predicted_thrust = self.enemy_thrust[enemy_ship.id]
            dist = my_ship.next_dist(thrust_action, enemy_ship, predicted_thrust)
            if dist < mindist:
                mindist = dist
                ship = enemy_ship
        return ship

    def choose_laser_target(self, my_ship, thrust_action, enemy_ships):
        maxp = 0
        ship = None
        for enemy_ship in enemy_ships:
            predicted_thrust = self.enemy_thrust[enemy_ship.id]
            enemy_pos = self.enemy_location[enemy_ship.id]
            laser_power = my_ship.laser_power(thrust_action, enemy_pos[0], enemy_pos[1])
            if laser_power > 0 and laser_power + enemy_ship.fuel > maxp:
                maxp = laser_power + enemy_ship.fuel
                ship = enemy_ship
        return ship

    def asses_laser_power(self, my_ship, thrust_action, enemy_ship):
        can_take_heat = my_ship.max_heat + my_ship.regen - my_ship.heat - (
            THRUST_HEAT if thrust_action != Thrust(0, 0) else 0)
        pw = min(can_take_heat, my_ship.laser)
        predicted_thrust = self.enemy_thrust[enemy_ship.id]
        enemy_pos = self.enemy_location[enemy_ship.id]
        laser_power = my_ship.laser_power(thrust_action, enemy_pos[0], enemy_pos[1], pw)
        if laser_power > 0:
            return pw
        return 0

    # should return Thrust(x,y) object, can get more stuff passed if needed
    def mothership_not_fall_on_planet(self, my_ship, st):
        current_dist_to_good = get_dist_to_good(my_ship.x, my_ship.y, my_ship.vx, my_ship.vy)
        if current_dist_to_good is not None and current_dist_to_good > 0:
            possible_thrusts = []
            for dx in range(-2, 3):
                for dy in range(-2, 3):
                    if my_ship.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                        continue
                    new_dist_to_good = get_dist_to_good(
                        *gravity_step(my_ship.x, my_ship.y, my_ship.vx + dx, my_ship.vy + dy))
                    if new_dist_to_good is not None and new_dist_to_good == current_dist_to_good - 1:
                        possible_thrusts.append((-dx, -dy))
            if possible_thrusts:
                thrust = random.choice(possible_thrusts)
                return Thrust(*thrust)
        return Thrust(0, 0)

    def get_mothership_actions(self, my_ship, st, enemy_ships):
        # we need to spawn swarm first thing
        actions = []
        if my_ship.lives > 1:
            swarm_fuel = max(my_ship.fuel - self.laser_ship_stats[0], 0)
            for n in range(my_ship.lives - 1, 0, -1):
                f = (swarm_fuel * n) // (my_ship.lives - 1)
                if 2 * (f + n) >= my_ship.total_hp():
                    continue
                actions.append(my_ship.do_duplicate_from_mothership(f, n))
                break
        # override all other actions with LaserShipStrategy
        if True:
            thrust = self.mothership_not_fall_on_planet(my_ship, st)
            if thrust.x != 0 or thrust.y != 0:
                actions.append(my_ship.do_thrust(thrust.x, thrust.y))
            actions.extend(self.mothership_strategy.apply_laser(st, my_ship, enemy_ships, thrust, self.enemy_location))
            return actions
        my_pos = [my_ship.x, my_ship.y]
        my_vel = [my_ship.vx, my_ship.vy]
        cur_closest, cur_farthest = trace_orbit(my_pos[0], my_pos[1], my_vel[0], my_vel[1], 384 - self.T)
        thrust = (0, 0)
        if cur_closest <= 24:
            thrust = (-sign(my_pos[0]), -sign(my_pos[0])) if abs(my_pos[0]) > abs(my_pos[1]) else (
                sign(my_pos[1]), -sign(my_pos[1]))
        if cur_farthest > st.field_size:
            thrust = (sign(my_vel[0]), sign(my_vel[1]))
        if my_ship.heat + THRUST_HEAT > my_ship.max_heat:
            thrust = 0, 0
        actions.append([0, my_ship.id, thrust])
        thrust_action = Thrust(*thrust)
        enemy_ship = self.choose_laser_target(my_ship, thrust_action, enemy_ships)
        if enemy_ship:
            predicted_thrust = self.enemy_thrust[enemy_ship.id]
            ex, ey = self.enemy_location[enemy_ship.id]
            next_dist = my_ship.next_dist(thrust_action, enemy_ship, predicted_thrust)
            if my_ship.laser:
                power = self.asses_laser_power(my_ship, thrust_action, enemy_ship)
                if power > 0:
                    actions.append(my_ship.do_laser(ex, ey, power))
        return actions

    def get_explode_gains(self, my_ship, my_ships, enemy_ships, already_hit_ids):
        gains = 0
        no_thrust = Thrust(0, 0)
        hit_ship_ids = [my_ship.id]
        for ship in my_ships:
            if ship.id in already_hit_ids:
                continue
            if my_ship.id == ship.id:
                gains -= my_ship.total_hp()
            else:
                dist = my_ship.next_dist(no_thrust, ship, no_thrust)
                power = my_ship.explode_power(dist)
                gains -= min(ship.total_hp(), power)
                if power > 0:
                    hit_ship_ids.append(ship.id)
        for ship in enemy_ships:
            if ship.id in already_hit_ids:
                continue
            dist = my_ship.next_dist(no_thrust, ship, no_thrust)
            power = my_ship.explode_power(dist)
            gains += 2 * min(ship.total_hp(), power)
            if power > 0:
                hit_ship_ids.append(ship.id)
        return gains, hit_ship_ids

    def apply(self, state):
        self.T += 1
        # assert self.T < 32
        st = State.parse(state)
        self.reset_precomputed()
        actions = []
        for ship in st.ships:
            if ship.id not in self.thrust_predictors:
                self.thrust_predictors[ship.id] = ThrustPredictor()
            self.thrust_predictors[ship.id].add(ship.last_actions)
        my_ships = []
        enemy_ships = []
        for some_ship in st.ships:
            if some_ship.player == st.me:
                if self.mothership_id == None and self.laser_ship_stats[3] > 0:
                    self.mothership_id = some_ship.id
                my_ships.append(some_ship)
            else:
                enemy_ships.append(some_ship)
                self.precompute_enemy_stuff(some_ship)
        orbits = {}
        if self.printships:
            print(f'T:{self.T} Player {st.me}:' + '\n' + "\n".join(str(s) for s in my_ships))
        for my_ship in my_ships:
            if my_ship.id == self.mothership_id:
                actions.extend(self.get_mothership_actions(my_ship, st, enemy_ships))
                continue
            orbit = (my_ship.x, my_ship.y, my_ship.vx, my_ship.vy)
            if orbit not in orbits:
                orbits[orbit] = []
            orbits[orbit].append(my_ship)
        ex = np.array([ship.x for ship in enemy_ships])
        ey = np.array([ship.y for ship in enemy_ships])
        evx = np.array([ship.vx for ship in enemy_ships])
        evy = np.array([ship.vy for ship in enemy_ships])
        exs, eys, evxs, evys = trace_orbit_np(ex, ey, evx, evy, self.homing_horizon)
        explode_actions = []
        already_hist_ids = set()
        for orbit, orbit_ships in orbits.items():
            orbit_dist_to_good = get_dist_to_good(*orbit)
            # print('dist', orbit_dist_to_good, len(orbit_ships))
            if len(orbit_ships) > 1:
                possible_thrusts = []
                target_dist = 3 if sum(ship.lives for ship in orbit_ships) >= 32 else 0
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        if dx == 0 and dy == 0:
                            continue
                        new_dist_to_good = get_dist_to_good(
                            *gravity_step(orbit[0], orbit[1], orbit[2] + dx, orbit[3] + dy))
                        if new_dist_to_good is not None and new_dist_to_good < target_dist:
                            target_dist = new_dist_to_good
                            possible_thrusts = []
                        if new_dist_to_good is not None and new_dist_to_good == target_dist:
                            possible_thrusts.append((-dx, -dy))
                if possible_thrusts:
                    random.shuffle(possible_thrusts)
                    for ship, thrust in zip(orbit_ships[1:], possible_thrusts):
                        actions.append([0, ship.id, thrust])
                continue
            my_ship = orbit_ships[0]
            if orbit_dist_to_good is not None and orbit_dist_to_good > 0 and self.T <= 48:
                possible_thrusts = []
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        if my_ship.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                            continue
                        new_dist_to_good = get_dist_to_good(
                            *gravity_step(orbit[0], orbit[1], orbit[2] + dx, orbit[3] + dy))
                        if new_dist_to_good is not None and new_dist_to_good == orbit_dist_to_good - 1:
                            possible_thrusts.append((-dx, -dy))
                if possible_thrusts:
                    thrust = random.choice(possible_thrusts)
                    actions.append([0, my_ship.id, thrust])
                continue
            if orbit_dist_to_good == 0 and my_ship.lives > 1:
                actions.append(my_ship.do_duplicate_even())
                continue
            if enemy_ships:
                thrust_action = Thrust(0, 0)
                enemy_ship = self.choose_explode_target(my_ship, thrust_action, enemy_ships)
                predicted_thrust = self.enemy_thrust[enemy_ship.id]
                next_dist = my_ship.next_dist(thrust_action, enemy_ship, predicted_thrust)
                if my_ship.explode_power(next_dist) and self.T > 7:
                    new_gains, hit_ids = self.get_explode_gains(my_ship, my_ships, enemy_ships, already_hist_ids)
                    if new_gains > 0:
                        explode_actions.append(my_ship.do_explode())
                        for hit_id in hit_ids:
                            already_hist_ids.add(hit_id)
                        continue
                # homing
                if self.T > self.homing_T_threshold and my_ship.fuel > 0:
                    possible_thrusts = []
                    mx = []
                    my = []
                    mvx = []
                    mvy = []
                    quo_idx = None
                    for dx in range(-2, 3):
                        for dy in range(-2, 3):
                            if my_ship.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                                continue
                            dist_to_good = get_dist_to_good(
                                *gravity_step(orbit[0], orbit[1], orbit[2] + dx, orbit[3] + dy))
                            if dist_to_good is not None and dist_to_good == 0:
                                if dx == 0 and dy == 0:
                                    quo_idx = len(mx)
                                possible_thrusts.append((-dx, -dy))
                                mx.append(orbit[0])
                                my.append(orbit[1])
                                mvx.append(orbit[2] + dx)
                                mvy.append(orbit[3] + dy)
                    mx, my, mvx, mvy = map(np.array, (mx, my, mvx, mvy))
                    mxs, mys, _, _ = trace_orbit_np(mx, my, mvx, mvy, self.homing_horizon)
                    dxs = np.abs(mxs[:, np.newaxis] - exs[np.newaxis])
                    dys = np.abs(mys[:, np.newaxis] - eys[np.newaxis])
                    ds = np.maximum(dxs, dys)
                    ds = np.min(ds, axis=(1, 2))
                    possible_thrusts_close = []
                    for i in range(len(possible_thrusts)):
                        if ds[i] <= self.homing_dist_threshold:
                            possible_thrusts_close.append(possible_thrusts[i])
                            if quo_idx == i:
                                print('cancel homing')
                                possible_thrusts_close = []
                                break
                    if possible_thrusts_close:
                        print('homing!')
                        thrust = random.choice(possible_thrusts_close)
                        actions.append([0, my_ship.id, thrust])
                        continue
        for explode_action in explode_actions:
            actions.append(explode_action)
        return actions

