from .util import auto_repr, to_snake_case

class Account:
    """A model used to describe a Loopring account."""
    account_id: int
    frozen: bool
    key_nonce: int
    key_seed: str
    nonce: int
    owner: str
    publicX: str
    publicY: str
    tags: str

    def __init__(self, **kwargs):
        for key in kwargs.keys():
            if key == "publicKey":
                for sub_key in kwargs[key].keys():
                    setattr(self, f"public{sub_key.upper()}", kwargs[key][sub_key])
            else:
                setattr(self, to_snake_case(key), kwargs[key])

    def __repr__(self) -> str:
        return auto_repr(self)

    def __str__(self) -> str:
        return self.owner


class _PendingBalance:
