from typing import Union

from .api import Requester, Response, Price, Recipient


class HLRRecipient(Recipient):
    def __init__(self, *args, tariff_value: int = None, callback_endpoint: str = None, **kwargs):
        kwargs.update({'tariff': tariff_value} if tariff_value else {})
        kwargs.update({'callback_url': callback_endpoint} if callback_endpoint else {})
        super().__init__(*args, **kwargs)


class HLRApi(Requester):
    def __init__(self, *args, **kwargs):
        self.hlr_records = []
        super().__init__(*args, **kwargs)

    def fetch_prices(self, tariff_code: int = None) -> list:
        result = Response(self.proceed('hlr', 'prices', function_param=tariff_code))
        for idx, price in enumerate(result.get('prices', [])):
            result['prices'][idx] = Price(**price)
        return result['prices']

    def retrieve_status(self, hlr_identifier: Union[str, int, HLRRecipient] = None) -> Union[dict, list]:
        if hlr_identifier:
            if isinstance(hlr_identifier, str):
                return Response(self.proceed('hlr', 'reference', hlr_identifier))
            elif isinstance(hlr_identifier, HLRRecipient):
                if not hlr_identifier.get('result'):  # lookup request not previously sent, send it
                    hlr_identifier['result'] = self.transmit(hlr_identifier)
                hlr_identifier = hlr_identifier['result']['result'][0]['id']  # use 'id' from result, now type is int
            if isinstance(hlr_identifier, int):  # for both int and HLRRecipient cases
                return Response(self.proceed('hlr', str(hlr_identifier)))
        elif self.hlr_records:
            elements_without_result = [item for item in self.hlr_records if not item.get('result')]
            if elements_without_result:
                response = self.transmit(elements_without_result)
                for position, element in enumerate(elements_without_result):
                    # setting element['result'] and associated self.hlr_records['result']
                    element['result'] = response['result'][position]
            for record in self.hlr_records:
                record['status'] = Response(self.proceed('hlr', str(record['result']['id'])))
            return self.hlr_records

    def append_hlr_record(self, *args, **kwargs):
        self.hlr_records.append(args[0] if len(args) == 1 and isinstance(args[0], HLRRecipient) else HLRRecipient(*args, **kwargs))

    def reset_hlr_records(self):
        self.hlr_records = []

    def transmit(self, hlr_record: Union[HLRRecipient, list] = None) -> dict:
        data = [hlr_record] if hlr_record and isinstance(hlr_record, HLRRecipient) else []
        data = hlr_record if hlr_record and isinstance(hlr_record, list) else data
        data = data if data else self.hlr_records
        results = Response(self.proceed('hlr', 'create', method='POST', data=data))
        for index, result in enumerate(results['result']):
            data[index]['result'] = result
            if data[index]['result'].get('id'):  # no 'id' in case of error
                data[index]['result']['id'] = int(data[index]['result']['id'])
        return results

# Generate performance plots from AWS ParallelCluster samples
import json
from pathlib import Path
import click
import matplotlib.pyplot as plt
from ..common import METRICS

@click.command()
@click.option("--datadir", help="Directory containing the dataset.", required=True, type=click.Path())
@click.option("--outdir", help="Directory where to create plots.", required=True, type=click.Path())
@click.option("--configurations", help="Comma separated list of configurations.", required=True)
@click.option("--nodes", help="Comma separated list of nodes.", required=True)
def generate(datadir, outdir, configurations, nodes):
    create_plots(datadir, outdir, configurations.split(","), nodes.split(","))

def create_plots(datadir, outdir, configs, node_list):
    # Load sample data
    samples = {}
    for config in configs:
        samples[config] = {}
        for node in node_list:
            samples_file = f"{datadir}/{config}/{node}nodes/samples.json"
            with open(samples_file) as file:
                samples[config][str(node)] = json.load(file)

    # Process each metric
    for metric_name in [m["name"] for m in METRICS]:
        dataset = {}

        # Build dataset for current metric
        for config in configs:
            dataset[config] = [
                [float(val) for val in samples[config][str(node)][f"{metric_name}Sample"].split(",")] 
                for node in node_list
            ]

        # Create figure
        figure, axis = plt.subplots(figsize=(10, 5), layout="constrained")

        # Set plot titles and labels
        axis.set_title(f"AWS ParallelCluster\n{metric_name}", fontweight="bold")
        axis.set_xlabel("Compute Nodes", fontweight="bold")
        unit = next(m['unit'] for m in METRICS if m['name'] == metric_name)
        axis.set_ylabel(f"Time ({unit})", fontweight="bold")

        num_configs = len(configs)
        num_nodes = len(node_list)
        all_positions = list(range(1, num_configs * num_nodes + 1))

        # Generate box plots
        box_plot_handles = {}
        for config in configs:
            start_idx = configs.index(config)
            positions = all_positions[start_idx :: num_configs]
            box_plot_handles[config] = axis.boxplot(
                dataset[config],
                patch_artist=True,
                boxprops=dict(facecolor="palegreen" if config == "baseline" else "steelblue"),
                labels=node_list,
                positions=positions,
            )

        # Add legend
        legend_entries = [box_plot_handles[bp]["boxes"][0] for bp in box_plot_handles]
        axis.legend(legend_entries, configs, loc="upper left")

        # Save plot
        output_path = Path(f"{outdir}/{metric_name}.png")
        output_path.parent.mkdir(parents=True, exist_ok=True)
        plt.savefig(output_path.absolute())

