# Context manager for redirecting output to both console and log file
@ctx.contextmanager
def redir_allout(logpath):
    try:
        # Save old descriptors
        oldout = os.dup(sy.stdout.fileno())
        olderr = os.dup(sy.stderr.fileno())

        # Set up tee process for logging
        tee = sp.Popen(["tee", logpath], stdin = sp.PIPE)

        # Redirect stdout and stderr to the pipe
        os.dup2(tee.stdin.fileno(), sy.stdout.fileno())
        os.dup2(tee.stdin.fileno(), sy.stderr.fileno())

        yield
    finally:
        # Restore original descriptors
        os.dup2(oldout, sy.stdout.fileno())
        os.dup2(olderr, sy.stderr.fileno())

        # Close resources
        tee.stdin.close()
        os.close(oldout)
        os.close(olderr)

        # Wait for tee to finish
        tee.communicate()

