import numpy as np
from scipy import optimize
import logging
logger = logging.getLogger('optimization.traders')
# TODO: add documentation throughout
class StochasticLiquidityTrader:
    def __init__(self, beta_val, prob_val, seed_val=None):
        self._beta = beta_val
        self._p = prob_val
        self.seed(seed=seed_val)
    def get_swap(self, pool_obj, rng_obj=None):
        if rng_obj is None:
            rng_obj = self._rng
        trade_amounts = rng_obj.exponential(self._beta)
        trade_directions = rng_obj.choice([1, -1], p=[self._p, 1 - self._p])
        trade_result = (trade_amounts * trade_directions)
        token_idx = 1 if trade_result > 0 else 0
        tokens_in = trade_result if trade_result > 0 else abs(trade_result) / pool_obj.price
        return token_idx, tokens_in
    def seed(self, seed_val=None):
        self._rng = np.random.default_rng(seed_val)

class FixedLiquidityTrader:
