@dataclass(init=False)  # type: ignore[misc]
class SecurityAuthenticator(metaclass=ABCMeta):
    """
    Interface definition for a security authentication handler
    """
    @classmethod
    @abstractmethod
    def build(cls, settings: ConfigModel) -> "SecurityAuthenticator":
        """
        Build authentication instance
        Arguments:
            settings (ConfigModel): configuration parameters
        Returns:
            SecurityAuthenticator
        """
    @abstractmethod
    def get_security_token(self) -> str:
        """
        Get the authentication token
        Returns:
            str
        """
    @abstractmethod
    def fetch_bearer_token(self):
        """
        Retrieve access token
        Returns:
            str
        """

class NullSecurityProvider(SecurityAuthenticator):
