class GoogleSecurityProvider(SecurityAuthenticator):
    """
    Google authentication implementation
    Args:
        settings (OpenMetadataConnection):
    Attributes:
        settings (OpenMetadataConnection)
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.settings = settings
        self.security_settings: GoogleSSOClientConfig = self.settings.securityConfig
        self.bearer_token = None
        self.token_expiry = None
    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)
    def get_security_token(self) -> None:
        import google.auth
        import google.auth.transport.requests
        from google.oauth2 import service_account
        credentials = service_account.IDTokenCredentials.from_service_account_file(
            self.security_settings.secretKey,
            target_audience=self.security_settings.audience,
        )
        request = google.auth.transport.requests.Request()
        credentials.refresh(request)
        self.bearer_token = credentials.token
        self.token_expiry = credentials.expiry
    def fetch_bearer_token(self):
        self.get_security_token()
        return self.bearer_token, self.token_expiry

class OktaSecurityProvider(SecurityAuthenticator):
    """
    Prepare the Json Web Token for Okta authentication
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.settings = settings
        self.security_settings: OktaSSOClientConfig = self.settings.securityConfig
        self.bearer_token = None
        self.token_expiry = None
    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)
    async def get_security_token(self) -> None:
        import time
        import uuid
        from urllib.parse import quote, urlencode
        from okta.cache.okta_cache import OktaCache
        from okta.jwt import JWT, jwt
        from okta.request_executor import RequestExecutor
        try:
            my_pem, my_jwk = JWT.get_PEM_JWK(self.security_settings.privateKey)
            current_time = int(time.time())
            expiration_time = current_time + JWT.ONE_HOUR
            generated_jwt_id = str(uuid.uuid4())
            claims = {
                "sub": self.security_settings.clientId,
                "iat": current_time,
                "exp": expiration_time,
                "iss": self.security_settings.clientId,
                "aud": self.security_settings.orgURL,
                "jti": generated_jwt_id,
            }
            jwt_token = jwt.encode(claims, my_jwk.to_dict(), JWT.HASH_ALGORITHM)
            config = {
                "client": {
                    "orgUrl": self.security_settings.orgURL,
                    "authorizationMode": "BEARER",
                    "rateLimit": {},
                    "privateKey": self.security_settings.privateKey,
                    "clientId": self.security_settings.clientId,
                    "token": jwt_token,
                    "scopes": self.security_settings.scopes,
                }
            }
            request_exec = RequestExecutor(
                config=config, cache=OktaCache(ttl=expiration_time, tti=current_time)
            )
            parameters = {
                "grant_type": "client_credentials",
                "scope": " ".join(config["client"]["scopes"]),
                "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
                "client_assertion": jwt_token,
            }
            encoded_parameters = urlencode(parameters, quote_via=quote)
            url = f"{self.security_settings.orgURL}?" + encoded_parameters
            token_request_object = await request_exec.create_request(
                "POST",
                url,
                None,
                {
                    "Accept": "application/json",
                    "Content-Type": "application/x-www-form-urlencoded",
                },
                oauth=True,
            )
            _, res_details, res_json, err = await request_exec.fire_request(
                token_request_object[0]
            )
            if err:
                raise APIError(f"{err}")
            response_dict = json.loads(res_json)
            token = response_dict.get(TOKEN_KEY)
            if not token:
                raise TokenFetchError(
                    f"Error getting access token: {response_dict}"
                )
            self.bearer_token = token
            self.token_expiry = response_dict.get(EXPIRY_TIME)
        except Exception as err:
            log.debug(traceback.print_exc())
            log.error(err)
            sys.exit()
    def fetch_bearer_token(self):
        import asyncio
        asyncio.run(self.get_security_token())
        return self.bearer_token, self.token_expiry

class Auth0SecurityProvider(SecurityAuthenticator):
    """
    OAuth authentication implementation
    Args:
        settings (OpenMetadataConnection):
    Attributes:
        settings (OpenMetadataConnection)
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.settings = settings
        self.security_settings: Auth0SSOClientConfig = self.settings.securityConfig
        self.bearer_token = None
        self.token_expiry = None
    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)
    def get_security_token(self) -> None:
        conn = http.client.HTTPSConnection(self.security_settings.domain)
        payload = (
            f"grant_type=client_credentials&client_id={self.security_settings.clientId}"
            f"&client_secret={self.security_settings.secretKey}&audience=https://{self.security_settings.domain}/api/v2/"
        )
        headers = {"content-type": "application/x-www-form-urlencoded"}
        conn.request(
            "POST", f"/{self.security_settings.domain}/oauth/token", payload, headers
        )
        res = conn.getresponse()
        data = json.loads(res.read().decode("utf-8"))
        token = data.get(TOKEN_KEY)
        if not token:
            raise TokenFetchError(f"Error getting access token: {data}")
        self.bearer_token = token
        self.token_expiry = data[EXPIRY_TIME]
    def fetch_bearer_token(self):
        self.get_security_token()
        return self.bearer_token, self.token_expiry

