        self.settings = settings
        self.security_settings: CustomOIDCSSOClientConfig = self.settings.securityConfig
        self.bearer_token = None
        self.token_expiry = None
    @classmethod
    def build(
        cls, settings: OpenMetadataConnection
    ) -> "CustomOIDCSecurityProvider":
