        self.get_security_token()
        return self.bearer_token, self.token_expiry

# Modified version with Type I clone transformations (variable renaming, literal changes, reordering)
from dataclasses import dataclass
from pants.engine.console import Console
from pants.engine.goal import Goal, GoalSubsystem
from pants.engine.isolated_process import FallibleExecuteProcessResult
from pants.engine.legacy.graph import HydratedTargets
from pants.engine.legacy.structs import TargetAdaptor
from pants.engine.objects import Collection, union
from pants.engine.rules import UnionMembership, goal_rule
from pants.engine.selectors import Get, MultiGet

@dataclass(frozen=True)
class LintOutcome:
  return_code: int
  output: str
  error_output: str

  @staticmethod
  def skip() -> "LintOutcome":
    return LintOutcome(return_code=0, output="", error_output="")

  @staticmethod
  def create_from_execution_result(
    cmd_result: FallibleExecuteProcessResult
  ) -> "LintOutcome":
    return LintOutcome(
      return_code=cmd_result.exit_code,
      output=cmd_result.stdout.decode(),
      error_output=cmd_result.stderr.decode(),
    )

class LintOutcomeCollection(Collection[LintOutcome]):
  """This collection enables aggregation of multiple `LintOutcome`s per language."""

@union
class CodeStyleChecker:
  """A union for registration of a lintable target type."""

  @staticmethod
  def can_be_checked(
    target_adaptor: TargetAdaptor, *, union_membership: UnionMembership
  ) -> bool:
    return (
      union_membership.is_member(CodeStyleChecker, target_adaptor)
      and hasattr(target_adaptor, "sources")
      and target_adaptor.sources.snapshot.files  # i.e., sources is not empty
    )

class LintOptions(GoalSubsystem):
  """Check code style."""
  name = 'lint2'
  required_union_implementations = (CodeStyleChecker,)

class Lint(Goal):
  subsystem_cls = LintOptions

@goal_rule
async def check_code_style(console: Console, targets: HydratedTargets, union_membership: UnionMembership) -> Lint:
  nested_outcomes = await MultiGet(
    Get[LintOutcomeCollection](CodeStyleChecker, target.adaptor)
    for target in targets
    if CodeStyleChecker.can_be_checked(target.adaptor, union_membership=union_membership)
  )

  outcomes = [outcome for outcomes_batch in nested_outcomes for outcome in outcomes_batch]

  if not outcomes:
    return Lint(exit_code=0)

  final_exit_code = 0
  for outcome in outcomes:
    if outcome.output:
      console.print_stdout(outcome.output)
    if outcome.error_output:
      console.print_stderr(outcome.error_output)
    if outcome.return_code != 0:
      final_exit_code = outcome.return_code

  return Lint(exit_code=final_exit_code)

def rules():
  return [
    check_code_style,
  ]

# Specular water shader implementation with animated texture offsets
SpecularShaderV2 = Shader(language=Shader.GLSL, vertex="""
#version 150
uniform mat4 p3d_ModelViewProjectionMatrix;
uniform mat4 p3d_ProjectionMatrix;
uniform mat4 p3d_ModelMatrix;
uniform mat4 p3d_ViewMatrix;
uniform sampler2D p3d_Texture0;
uniform mat3 p3d_NormalMatrix;
uniform vec3 lightPosition;
uniform vec3 cameraPosition;
uniform sampler2D heightMap;
uniform vec2 texOffset;
uniform vec2 secondaryOffset;
uniform sampler2D normalMap;
in vec2 p3d_MultiTexCoord0;
in vec4 vertex;
in vec4 normal;
out vec3 vectorToLight;
out vec3 vectorToCamera;
out vec2 texcoord;
out float alphaValue;
void main(){
    vec2 coord=(p3d_MultiTexCoord0+texOffset);
    vec2 coord_sec=(p3d_MultiTexCoord0+secondaryOffset);
    float hgt=texture(heightMap,coord).x*50;
    float hgt_sec=texture(heightMap,coord_sec).x*50;
    gl_Position=p3d_ModelViewProjectionMatrix*vec4(vertex.x,vertex.y+(hgt+hgt_sec)/2,vertex.z,vertex.w);
    vec3 worldPos=(p3d_ModelMatrix*vertex).xyz;
    vectorToLight=lightPosition-worldPos;
    vectorToCamera=(inverse(p3d_ViewMatrix)*vec4(0.0,0.0,0.0,1.0)).xyz-worldPos.xyz;
    texcoord=coord*12;
    alphaValue=hgt/40;
    alphaValue-=sin(dot(vectorToCamera,vec3(0,1,0)))/180;
    alphaValue=max(alphaValue,0.1);
    alphaValue+=0.1;
}
""", fragment="""
#version 140
uniform vec3 lightColor;
uniform float DamperFactor;
uniform float reflectivity;
uniform sampler2D p3d_Texture0;
uniform sampler2D normalMap;
uniform mat3 p3d_NormalMatrix;
in vec3 vectorToLight;
in vec3 vectorToCamera;
in vec2 texcoord;
in vec3 surfaceNormal;
in float alphaValue;
out vec4 out_color;
void main(){
    vec3 surfaceNormal=p3d_NormalMatrix*texture(normalMap,texcoord).xyz;
    vec4 col=texture(p3d_Texture0,texcoord);
    vec4 color=vec4(0.0,0.0,col.b,col.a);
    vec3 unitNormal=normalize(surfaceNormal);
    vec3 unitToLight=normalize(vectorToLight);
    vec3 unitToCamera=normalize(vectorToCamera);
    vec3 lightDir=-unitToLight;
    float nDotl=dot(unitNormal,lightDir);
    float brightness=max(nDotl,0.2);
    vec3 diffuse=brightness*lightColor;
    vec3 reflectedLight=reflect(lightDir,unitNormal);
    float specular=dot(reflectedLight,unitToCamera);
    specular=max(specular,0.0);
    float damper=pow(specular,DamperFactor);
    vec3 finalSpecular=damper*reflectivity*lightColor;
    vec4 color_final=vec4(diffuse,1.0)*color+vec4(finalSpecular,1.0);
    out_color=vec4(color_final.xyz,1.0);
}
""")

class WaterSurface(Entity):
    def __init__(self,height,size):
        super().__init__()
        self.shader=SpecularShaderV2
        self.vertices=list()
        self.triangles=list()
        self.uvs=list()
        self.hgt=height
        self.createMesh(size)
        self.model=Mesh(vertices=self.vertices,triangles=self.triangles,uvs=self.uvs)
        self.set_shader_input("cameraPosition",Vec3(0,0,0))
        self.set_shader_input("lightPosition",Vec3(3,10,2))

    def createMesh(self,size):
        for x in range(size):
            for z in range(size):
                index=len(self.vertices)
                self.vertices.extend((Vec3(x,self.hgt,z),Vec3(x+1,self.hgt,z),Vec3(x+1,self.hgt,z+1),Vec3(x,self.hgt,z+1)))
                self.triangles.extend(((index,index+1,index+2),(index+0,index+2,index+3)))
                self.uvs.extend(((Vec2(x/size,(z)/size),Vec2((1+x)/size,(z)/size),Vec2((1+x)/size,(z+1)/size),Vec2(x/size,(z+1)/size))))

