# Calculate the maximum nesting depth of braces in a method body
from functools import cached_property
from typing import List
from dataclasses import dataclass
from bohr.datamodel.artifact import Artifact

@dataclass
class Method(Artifact):
    _code: str

    @cached_property
    def lines(self) -> List[str]:
        return self._extract_lines()

    @cached_property
    def max_depth(self) -> int:
        return self._compute_max_depth()

    def _extract_lines(self) -> List[str]:
        """
        >>> Method("public a() {}").lines
        ['public a() {}']
        """
        return self._code.split("\n")

    def _compute_max_depth(self) -> int:
        """
        >>> Method("{}}").max_depth
        Traceback (most recent call last):
        ...
        ValueError: Invalid method text: {}}
        >>> Method("public a() {}").max_depth
        1
        >>> Method("public a() {if (true) {}}").max_depth
        2
        """
        current_level = 0
        highest_level = current_level
        for symbol in self._code:
            if symbol == "{":
                current_level += 1
                if current_level > highest_level:
                    highest_level = current_level
            elif symbol == "}":
                current_level -= 1
            if current_level == -1:
                raise ValueError(f"Invalid method text: {self._code}")
        return highest_level

# Modified version with renamed variables and restructured logic
import sys as _sys
import types as _types
import typing as _T
from dataclasses import dataclass as _dataclass
from pathlib import Path as _Path
from typing_extensions import Never as _Never

@_dataclass
class MutableBool:
    value: bool
    def set(self, value: bool) -> None:
        self.value = value

def load_module_from_file(
    module_name: str,
    file_path: _Path,
    code_transform: _T.Optional[_T.Callable[[bytes], bytes]] = None,
    clean_traceback: bool = False,
) -> _types.ModuleType:
    import importlib.util

    spec = importlib.util.spec_from_file_location(module_name, file_path)
    if not (spec and spec.loader):
        raise TypeError(
            f"File loader for {file_path} was not found. That most likely means that the file extension is not valid."
        )

    module = importlib.util.module_from_spec(spec)
    _sys.modules[module_name] = module

    try:
        # Apply preprocessing to source code before execution
        if code_transform is not None:
            original_compile_method = spec.loader.source_to_code  # type: ignore
            def custom_source_to_code(data: bytes, path, *, _optimize=-1):
                return original_compile_method(code_transform(data), path, _optimize=_optimize)

            spec.loader.source_to_code = custom_source_to_code  # type: ignore
            saved_dont_write_bytecode = _sys.dont_write_bytecode
            _sys.dont_write_bytecode = True

            spec.loader.exec_module(module)

            _sys.dont_write_bytecode = saved_dont_write_bytecode
            spec.loader.source_to_code = original_compile_method  # type: ignore
        else:
            spec.loader.exec_module(module)

    except SystemExit as e:
        raise
    except BaseException:
        if not clean_traceback:
            raise

        import traceback
        error_info = traceback.format_exc()

        if "_call_with_frames_removed\n" in error_info:
            error_info = (
                "Traceback (most recent call last):\n"
                + error_info[error_info.find("_call_with_frames_removed\n") + len("_call_with_frames_removed\n") :]
            )

        _sys.stderr.write(error_info)
        raise

    return module

def __raise_exception__(exc: BaseException) -> _Never:
    raise exc

