# Script to run include-what-you-use on compiled sources
import json
import os
import subprocess
import sys

def _extract_source_files(compilation_database):
    for entry in compilation_database:
        yield os.path.join(entry['directory'], entry['file'])

def _fetch_compilation_database(build_flags):
    subprocess.check_call(['bazel',
                           'build',
                           '//adlik_serving',
                           *build_flags,
                           '--experimental_action_listener=//ci:ci-action-listener'])
    return subprocess.check_output(args=['ci/tools/build-compilation-database.py'], universal_newlines=True)

def execute_check(command_args):
    has_error = False
    compilation_data = json.loads(_fetch_compilation_database(command_args))
    for cmd_entry in compilation_data:
        exit_code = subprocess.run(args=['include-what-you-use', *cmd_entry['arguments'][1:]],
                                   cwd=cmd_entry['directory']).returncode
        if exit_code != 2:
            has_error = True
    if has_error:
        sys.exit(1)

if __name__ == "__main__":
    execute_check(sys.argv[1:])

