import celery.result
from celery import states

logger = logging.getLogger(__name__)

def _serialize_data(value):
    if isinstance(value, datetime.datetime):
        return value.isoformat()
    if isinstance(value, dict):
        return {k: _serialize_data(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_serialize_data(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_serialize_data(item) for item in value)
    if isinstance(value, set):
        return {_serialize_data(item) for item in value}
    return value

def _mock_async_result(task_id, **kwargs):
    return _MockTaskStore.get_task(task_id)

# Override AsyncResult to use our mock implementation
celery.result.AsyncResult = _mock_async_result

class _CustomEagerResult(celery.result.EagerResult):
    def ready(self):
        return self._state in states.READY_STATES

class _MockTaskStore:
    __task_storage = {}

    @classmethod
    def store(cls, result):
        cls.__task_storage[result.id] = result

    @classmethod
    def get_task(cls, task_id):
        return (
            cls.__task_storage[task_id]
            if task_id in cls.__task_storage
            else _CustomEagerResult(task_id, None, states.PENDING)
        )

class CeleryAppMock:
    """
    A wrapper around Celery app that enables eager mode behavior.
    Intercepts task decorators to ensure apply_async executes tasks synchronously.
    """
    def __init__(self, original_app):
        self.__app = original_app
        self.__app.conf.update(
            task_always_eager=True,
            result_backend="cache",
            cache_backend="memory",
            task_eager_propagates=True,
        )
        self.__local_store = {}

    def __getattr__(self, attr_name):
        if attr_name == "task":
            def task_decorator(*args, **kwargs):
                decorated_func = getattr(self.__app, "task")(*args, **kwargs)

                class TaskWrapper:
                    def __init__(self, func, *a, **o):
                        self.__func = func

                    def apply_async(
                        self,
                        args=None,
                        kwargs=None,
                        task_id=None,
                        producer=None,
                        link=None,
                        link_error=None,
                        shadow=None,
                        **extra_options,
                    ):
                        processed_args = (
                            [_serialize_data(arg) for arg in args] if args else ()
                        )
                        processed_kwargs = (
                            {k: _serialize_data(v) for k, v in kwargs.items()}
                            if kwargs
                            else {}
                        )

                        final_task_id = task_id if task_id else str(uuid.uuid4())

                        try:
                            execution_result = self.__func(
                                *processed_args, **processed_kwargs
                            )
                            eager_result = celery.result.EagerResult(
                                final_task_id, execution_result, states.SUCCESS
                            )
                        except Exception as exc:
                            eager_result = celery.result.EagerResult(
                                final_task_id, exc, states.FAILURE
                            )

                        _MockTaskStore.store(eager_result)
                        return eager_result

                    def __call__(self, *args, **kwargs):
                        return self.__func(*args, **kwargs)

                return TaskWrapper
            return task_decorator
        else:
            return getattr(self.__app, attr_name)

