def test_filters_get_schema_params():
    """
    Verify all filters produce correct schema operation parameters
    """
    # List of tuples: (filter_class, expected_parameters)
    test_cases = [
        (dja_filters.QueryParameterValidationFilter, []),
        (
            backends.DjangoFilterBackend,
            [
                {
                    "name": "filter[pk]",
                    "required": False,
                    "in": "query",
                    "description": "pk",
                    "schema": {"type": "string"},
                },
                {
                    "name": "filter[title]",
                    "required": False,
                    "in": "query",
                    "description": "title",
                    "schema": {"type": "string"},
                },
                {
                    "name": "filter[title.contains]",
                    "required": False,
                    "in": "query",
                    "description": "title__contains",
                    "schema": {"type": "string"},
                },
                {
                    "name": "filter[author.username.contains]",
                    "required": False,
                    "in": "query",
                    "description": "author__username__contains",
                    "schema": {"type": "string"},
                },
            ],
        ),
        (
            dja_filters.OrderingFilter,
            [
                {
                    "name": "sort",
                    "required": False,
                    "in": "query",
                    "description": "Field name for ordering results.",
                    "schema": {"type": "string"},
                }
            ],
        ),
        (
            drf_filters.SearchFilter,
            [
                {
                    "name": "filter[search]",
                    "required": False,
                    "in": "query",
                    "description": "Search query term.",
                    "schema": {"type": "string"},
                }
            ],
        ),
    ]

    view_instance = DummyEntryViewSet()
    for filter_class, expected_params in test_cases:
        filter_instance = filter_class()
        actual_params = filter_instance.get_schema_operation_parameters(view_instance)

        assert len(actual_params) == len(expected_params)
        if len(actual_params) == 0:
            continue

        # Compare parameters by name since ordering isn't guaranteed in Python 3.5+
        for param in actual_params:
            assert "name" in param
            for exp_param in expected_params:
                if param["name"] == exp_param["name"]:
                    assert param == exp_param

