# Modified version with Type I clone transformations
import contextlib
from http.client import HTTPConnection
import json
import logging
import shlex
from typing import Any, Dict, Generator, List, Optional, Tuple, Union, cast
from ruamel.yaml import YAML
from tabulate import tabulate
from homeassistant_cli.config import Configuration
import homeassistant_cli.const as const
import homeassistant_cli.yaml as yaml

_LOGGER = logging.getLogger(__name__)

def convert_to_dict(entry: str) -> Dict[str, str]:
    """Transform list of key=value pairs into dictionary."""
    if not entry:
        return {}
    lexer = shlex.shlex(entry, posix=True)
    lexer.whitespace_split = True
    lexer.whitespace = ','
    result_dict = {}  # type: Dict[str, str]
    result_dict = dict(
        item.split('=', 1) for item in lexer  # type: ignore
    )
    return result_dict

def convert_to_list(entry: str) -> List[Tuple[str, str]]:
    """Transform list of key=value pairs into list of tuples."""
    if not entry:
        return []
    lexer = shlex.shlex(entry, posix=True)
    lexer.whitespace_split = True
    lexer.whitespace = ','
    result_list = []  # type: List[Tuple[str,str]]
    result_list = list(
        tuple(item.split('=', 1)) for item in lexer  # type: ignore
    )
    return result_list

def format_raw_output(
    output_format: str,
    payload: Union[Dict[str, Any], List[Dict[str, Any]]],
    yaml_parser: YAML,
    fields: Optional[List] = None,
    hide_headers: bool = False,
    display_format: str = 'plain',
    order_by: Optional[str] = None,
) -> str:
    """Format the raw data according to specified output format."""
    if output_format == 'auto':
        _LOGGER.debug("Output `auto` thus using %s", const.DEFAULT_DATAOUTPUT)
        output_format = const.DEFAULT_DATAOUTPUT

    if order_by and isinstance(payload, List):
        _order_table_data(payload, order_by)

    if output_format == 'json':
        try:
            return json.dumps(payload, indent=2, sort_keys=False)
        except ValueError:
            return str(payload)
    elif output_format == 'yaml':
        try:
            return cast(str, yaml.dumpyaml(yaml_parser, payload))
        except ValueError:
            return str(payload)
    elif output_format == 'table':
        from jsonpath_rw import parse
        if not fields:
            fields = const.COLUMNS_DEFAULT
        format_spec = [(f[0], parse(f[1] if len(f) > 1 else f[0])) for f in fields]
        table_rows = []
        if hide_headers:
            column_titles = []  # type: List[str]
        else:
            column_titles = [f[0] for f in format_spec]

        # Handle single-item data by wrapping in list
        if not isinstance(payload, List):
            payload = [payload]

        for record in payload:
            row_values = []
            for spec in format_spec:
                values = [match.value for match in spec[1].find(record)]
                row_values.append(", ".join(map(str, values)))
            table_rows.append(row_values)

        formatted_result = tabulate(
            table_rows, headers=column_titles, tablefmt=display_format
        )  # type: str
        return formatted_result
    else:
        raise ValueError(
            "Output Format was {}, expected either 'json' or 'yaml'".format(
                output_format
            )
        )

def _order_table_data(table_data: List[Any], sort_key: str) -> List[Any]:
    """Order the content of a table based on specified key."""
    from jsonpath_rw import parse
    expression = parse(sort_key)

    def _extract_sort_value(row: Dict[Any, str]) -> Any:
        value = next(iter([match.value for match in expression.find(row)]), None)
        return (value is None, value)

    table_data.sort(key=_extract_sort_value)
    return table_data

def format_for_output(
    context: Configuration,
    records: List[Dict[str, Any]],
    selected_fields: Optional[List] = None,
) -> str:
    """Format data for output according to configuration settings."""
    return format_raw_output(
        context.output,
        records,
        context.yaml(),
        selected_fields,
        context.no_headers,
        context.table_format,
        context.sort_by,
    )

def enable_debug_requests() -> None:
    """Enable logging for the requests module."""
    HTTPConnection.set_debuglevel(cast(HTTPConnection, HTTPConnection), 1)
    logging.basicConfig()
    logging.getLogger().setLevel(logging.DEBUG)
    requests_logger = logging.getLogger('requests.packages.urllib3')
    requests_logger.setLevel(logging.DEBUG)
    requests_logger.propagate = True

def disable_debug_requests() -> None:
    """Disable logging for the requests module.
    May have side effects.
    """
    HTTPConnection.set_debuglevel(cast(HTTPConnection, HTTPConnection), 1)
    root_logger = logging.getLogger()
    root_logger.setLevel(logging.WARNING)
    root_logger.handlers = []
    requests_logger = logging.getLogger('requests.packages.urllib3')
    requests_logger.setLevel(logging.WARNING)
    requests_logger.propagate = False

@contextlib.contextmanager
def request_debug_context() -> Generator:
    """Context manager to temporarily enable debug logging for requests.
    Usage: with request_debug_context(): <operations>
    """
    enable_debug_requests()
    yield
    disable_debug_requests()

