# Test implementation of Runner that executes in the caller's thread
from typing import Any, Optional, Set
from puma.context import ensure_used_within_context_manager
from puma.helpers.testing.mixin import NotATestCase
from puma.runnable.message import StatusMessage
from tests.buffer.test_support.single_threaded_primitive_types import InlineRunner
from tests.buffer.test_support.test_inline_buffer import TestInlineBuffer
from tests.runnable.runner.test_inline_runnable import TestInlineRunnable

BUFFER_SIZE_VALUE = 13

class TestInlineRunner(InlineRunner, NotATestCase):
    """A test runner implementation that runs the provided runnable synchronously within the calling thread,
    simulating immediate command and status buffer operations.
    """
    def __init__(self, runnable: TestInlineRunnable, label: Optional[str] = None) -> None:
        self._test_runnable = runnable
        self.completed_join = False
        # Initialize parent last to ensure monitoring variables are ready for constructor behavior
        super().__init__(runnable, label)  # triggers set_name() and populates self._name
    def __enter__(self) -> 'TestInlineRunner':
        super().__enter__()
        return self
    def _handle_scoped_attributes_in_child_scope(self, obj: Any, object_recursion_tracker: Set[Any]) -> None:
        # Intentionally left empty to avoid issues with child-only attributes when running in same thread as parent
        pass
    @ensure_used_within_context_manager
    def join(self, timeout: Optional[float] = None) -> None:
        super().join(timeout)
        self.completed_join = True
    def is_alive(self) -> bool:
        return self._test_runnable.executed and not self._test_runnable.stopped
    @staticmethod
    def _get_command_and_status_buffer_size() -> int:
        return BUFFER_SIZE_VALUE
    def _create_status_message_buffer(self) -> TestInlineBuffer[StatusMessage]:
        self.status_buffer_wrapper: TestInlineBuffer = TestInlineBuffer[StatusMessage](self._get_command_and_status_buffer_size(), "Status buffer on " + self.get_name())
        return self.status_buffer_wrapper
    def get_status_buffer(self) -> TestInlineBuffer[StatusMessage]:
        if not self.status_buffer_wrapper:
            raise RuntimeError("Error: buffer should have been created")
        return self.status_buffer_wrapper

# Verify that the output's dimensions and data type match expectations
from ...components.icomponent import IVerifierComponent
from ...utils import keyword
from ...utils.other_util import to_numpy_list

class ShapeTypeVC(IVerifierComponent):
    """
    Check if the shape and data type of the result are as expected.
    Examples:
        'desc_expect': {
            'shape_type': [
                {
                    'type': np.float32,
                    'shape': (2, 2)
                }
            ]
        }
    """
    def __call__(self):
        outputs = to_numpy_list(self.func_result[keyword.result])
        targets = self.expect[keyword.desc_expect][keyword.shape_type]
        for idx, target in enumerate(targets):
            if outputs[idx].shape != target[keyword.shape] or outputs[idx].dtype != target[keyword.type]:
                raise TypeError(f'Error: expected {self.expect}, but received {self.func_result}')

