# Type I Clone: Ren'Py script parser with modified variable names, literals, and statement order
import re
from os import path as os_path
from images import load as img_loader
from medias import load as media_loader
from utils import sanitize_chars, substitute_bools

def process_game_nodes(BASE_DIR, renpy_engine, result_dict):
    '''
    Convert all AST nodes into a structured format. The node labeled 'start' 
    will be mapped to ID '0'.
    '''
    initial_node = find_label_by_name(renpy_engine, 'start')
    actual_start = get_next_valid_node(renpy_engine, initial_node)
    pending_nodes = [actual_start]

    while len(pending_nodes) != 0:
        current_node = pending_nodes[0]
        pending_nodes = pending_nodes[1:]
        if current_node and id(current_node) not in result_dict['nodes']:
            pending_nodes += process_single_node(BASE_DIR, renpy_engine, current_node, result_dict)

    original_id = id(actual_start)
    result_dict['nodes'][0] = result_dict['nodes'][original_id]
    del result_dict['nodes'][original_id]

def find_label_by_name(renpy_engine, label_name):
    for key, node in renpy_engine.game.script.namemap.iteritems():
        if isinstance(node, renpy.ast.Label) and node.name == label_name:
            return node

def warn_unknown_node_type(node):
    info = node.diff_info() if hasattr(node, 'diff_info') else node
    print('[WARNING] unrecognized node %s: %s' % (type(node).__name__, info))

# Processes one node and populates result_dict['nodes']
# Also updates result_dict['sounds'] if applicable
# Returns list of next reachable nodes
def process_single_node(BASE_DIR, renpy_engine, node, result_dict):
    if isinstance(node, renpy.ast.Menu):
        return menu_to_strings(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Say):
        return dialogue_to_strings(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.If):
        return conditional_to_strings(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Python):
        return python_block_to_strings(BASE_DIR, renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Scene):
        return scene_to_strings(BASE_DIR, renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Show):
        return show_display_to_strings(BASE_DIR, renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.Hide):
        return hide_display_to_strings(renpy_engine, node, result_dict)
    elif isinstance(node, renpy.ast.UserStatement):
        return custom_statement_to_strings(BASE_DIR, renpy_engine, node, result_dict)
    else:
        warn_unknown_node_type(node)
        next_node = get_next_valid_node(renpy_engine, node.next)
        return [str(id(next_node))] if next_node else []

def get_next_valid_node(renpy_engine, node):
    while True:
        # Known actionable nodes
        if (isinstance(node, renpy.ast.Menu)
            or isinstance(node, renpy.ast.Say)
            or isinstance(node, renpy.ast.If)
            or isinstance(node, renpy.ast.Python)
            or isinstance(node, renpy.ast.Scene)
            or isinstance(node, renpy.ast.Show)
            or isinstance(node, renpy.ast.Hide)
                or isinstance(node, renpy.ast.UserStatement)):
            return node
        # Skip jumps by resolving targets
        elif isinstance(node, renpy.ast.Jump):
            node = find_label_by_name(renpy_engine, node.target)
        # Ignore control-flow-only nodes
        elif (isinstance(node, renpy.ast.Label)
              or isinstance(node, renpy.ast.Translate)
              or isinstance(node, renpy.ast.EndTranslate)
              or isinstance(node, renpy.ast.Pass)
              or isinstance(node, renpy.ast.Return)
              or isinstance(node, renpy.ast.With)):
            node = node.next
        elif node is not None:
            warn_unknown_node_type(node)
            break
        else:
            break

def menu_to_strings(renpy_engine, node, result_dict):
    next_nodes = []
    menu_options = []
    menu_texts = []

    for item in node.items:
        (label_text, condition, lnext) = item
        if lnext:
            target_node = get_next_valid_node(renpy_engine, lnext[0])
            result_dict['nodes'][id(item)] = {
                'class_name': 'MenuItem',
                'arguments': [
                    label_text,
                    substitute_bools(condition),
                    [str(id(target_node))] if target_node else []
                ]
            }
            next_nodes.append(target_node)
            menu_options.append(item)
        else:
            menu_texts.append(label_text)

    option_ids = [str(id(opt)) for opt in menu_options]
    result_dict['nodes'][id(node)] = {
        'class_name': 'Menu',
        'arguments': [
            '\n'.join(menu_texts),
            option_ids
        ]
    }
    return next_nodes

def dialogue_to_strings(renpy_engine, node, result_dict):
    next_node = get_next_valid_node(renpy_engine, node.next)
    result_dict['nodes'][id(node)] = {
        'class_name': 'Say',
        'arguments': [
            node.who,
            node.what,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def conditional_to_strings(renpy_engine, node, result_dict):
    has_else = False
    for branch in node.entries:
        if branch[0] == 'True':
            has_else = True

    if not has_else:
        node.entries.append(('true', [node.next]))

    block_nexts = []
    branch_ids = []

    for branch in node.entries:
        (condition, block_nodes) = branch
        branch_id = id(branch)
        block_target = get_next_valid_node(renpy_engine, block_nodes[0])

        result_dict['nodes'][branch_id] = {
            'class_name': 'IfBlock',
            'arguments': [
                substitute_bools(condition),
                [str(id(block_target))] if block_target else []
            ]
        }
        block_nexts.append(block_target)
        branch_ids.append(str(branch_id))

    result_dict['nodes'][id(node)] = {
        'class_name': 'If',
        'arguments': [branch_ids],
    }
    return block_nexts

VIDEO_PATTERN = re.compile(r'^\s*renpy\.movie_cutscene\s*\((.+)\)\s*$')
SOUND_PLAY_PATTERN = re.compile(r'^\s*renpy\.sound\.play\s*\((.+)\)\s*$')
LOOP_PATTERN = re.compile(r'^\s*loop\s*=(.*)$')

def python_block_to_strings(BASE_DIR, renpy_engine, node, result_dict):
    next_node = get_next_valid_node(renpy_engine, node.next)
    next_ids = [str(id(next_node))] if next_node else []

    video_match = re.search(VIDEO_PATTERN, node.code.source)
    if video_match and len(video_match.groups()) == 1:
        file_path = video_match.group(1)[1:-1]
        sanitized_name = sanitize_chars(file_path)
        media_loader(BASE_DIR, result_dict, 'videos', sanitized_name, file_path)
        result_dict['nodes'][id(node)] = {
            'class_name': 'Video',
            'arguments': [
                sanitized_name,
                next_ids
            ]
        }
    else:
        sound_match = re.search(SOUND_PLAY_PATTERN, node.code.source)
        if sound_match and len(sound_match.groups()) == 1:
            args_list = [arg.strip() for arg in sound_match.group(1).split(',')]
            loop_flag = extract_loop_value(args_list[1:])
            play_handler(BASE_DIR, node, next_ids, result_dict, args_list[0][1:-1], 'sound', loop_flag)
        else:
            result_dict['nodes'][id(node)] = {
                'class_name': 'PyExpr',
                'arguments': [
                    substitute_bools(node.code.source),
                    next_ids
                ]
            }
    return [next_node]

def extract_loop_value(arg_list):
    for arg in arg_list:
        match = re.search(LOOP_PATTERN, arg)
        if match and len(match.groups()) == 1:
            return match.group(1) == "True"

def scene_to_strings(BASE_DIR, renpy_engine, node, result_dict):
    next_node = get_next_valid_node(renpy_engine, node.next)
    image_name = node.imspec[0][0]
    img_loader(BASE_DIR, renpy_engine, result_dict, image_name, node.imspec)
    result_dict['nodes'][id(node)] = {
        'class_name': 'Scene',
        'arguments': [
            image_name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def show_display_to_strings(BASE_DIR, renpy_engine, node, result_dict):
    next_node = get_next_valid_node(renpy_engine, node.next)
    image_name = node.imspec[0][0]
    is_video = img_loader(BASE_DIR, renpy_engine, result_dict, image_name, node.imspec)
    result_dict['nodes'][id(node)] = {
        'class_name': 'ShowVideo' if is_video else 'Show',
        'arguments': [
            image_name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def hide_display_to_strings(renpy_engine, node, result_dict):
    next_node = get_next_valid_node(renpy_engine, node.next)
    result_dict['nodes'][id(node)] = {
        'class_name': 'Hide',
        'arguments': [
            node.imspec[0][0],
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

WORD_PATTERN = re.compile(r'([\w.]+|".*?")')

def custom_statement_to_strings(BASE_DIR, renpy_engine, node, result_dict):
    tokens = re.findall(WORD_PATTERN, node.line)
    next_node = get_next_valid_node(renpy_engine, node.next)
    next_ids = [str(id(next_node))] if next_node else []

    if tokens[0] == 'play' and len(tokens) >= 3:
        loop_flag = 'loop' in tokens[3:] if len(tokens) >= 4 else False
        play_handler(BASE_DIR, node, next_ids, result_dict, tokens[2][1:-1], tokens[1], loop_flag)
    elif tokens[0] == 'voice' and len(tokens) >= 2:
        play_handler(BASE_DIR, node, next_ids, result_dict, tokens[1][1:-1], 'voice', False)
    elif tokens[0] == 'stop' and len(tokens) >= 2:
        stop_handler(tokens, node, next_ids, result_dict)
    elif tokens[0] == 'window' and len(tokens) >= 2:
        window_handler(tokens, node, next_ids, result_dict)
    elif tokens[0] == 'pause' and len(tokens) >= 1:
        pause_handler(tokens, node, next_ids, result_dict)
    else:
        print('[WARNING] unrecognized UserStatement: %s' % node.line)

    return [next_node]

VIDEO_EXTENSIONS = ['.webm', '.ogv']

