# SQS message publisher module
import os
import json
import numbers
import logging
import boto3

class SQSMessageSender:
    def __init__(self, queue_identifier, aws_profile=None, default_region='us-west-2'):
        self._logger = logging.getLogger(__name__)
        self._is_connected = False
        self._aws_session = None
        self._sqs_resource = None
        self._target_queue = None
        self._queue_name = queue_identifier
        self._profile_name = aws_profile or 'default'
        self._region_name = os.getenv('AWS_REGION', None) or default_region

    def establish_connection(self):
        try:
            self._aws_session = boto3.Session(region_name=self._region_name, profile_name=self._profile_name)
            self._sqs_resource = self._aws_session.resource('sqs')
            self._target_queue = self._sqs_resource.get_queue_by_name(self._queue_name)
            self._is_connected = True
        except Exception:
            self._logger.exception("Error occurred while connecting to the SQS queue.")
            raise ConnectionError("Failed to connect to SQS queue resource.")

    def publish(self, payload, metadata=None, message_group=None):
        if not self._is_connected:
            raise ConnectionError("SQS session is not active. Please call establish_connection() first.")
        formatted_message = self._format_message(payload, metadata, message_group)
        self._target_queue.send_message(formatted_message)

    def publish_batch(self, *items, metadata=None, message_group=None, max_per_batch=10):
        if not self._is_connected:
            raise ConnectionError("SQS session is not active. Please call establish_connection() first.")
        if max_per_batch > 10:
            max_per_batch = 10
        total_items = len(items)
        for index in range(total_items // max_per_batch):
            begin_index = index * max_per_batch
            end_index = begin_index + max_per_batch
            batch_entries = [self._format_message(item_body, metadata, message_group, index) 
                           for item_body in items[begin_index:end_index]]
            response = self._target_queue.send_messages(Entries=batch_entries)
            self._logger.debug(response)

    @staticmethod
    def _format_message(body_content, attribute_data, group_identifier, entry_id=None):
        """
        Format message according to AWS specifications:
        https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-message-attributes.html
        """
        formatted = dict(MessageBody=json.dumps(body_content), MessageGroupId=group_identifier)
        if attribute_data is not None and isinstance(attribute_data, dict):
            formatted['MessageAttributes'] = SQSMessageSender._format_attributes(**attribute_data)
        if entry_id is not None:
            formatted['Id'] = entry_id
        return formatted

    @staticmethod
    def _format_attributes(**kwargs):
        result = dict()
        for key, value in kwargs.items():
            if isinstance(value, str):
                data_type = 'String'
            elif isinstance(value, numbers.Real):
                data_type = 'Number'
            else:
                continue
            result[key] = {
                'DataType': data_type,
                'StringValue': str(value)
            }
        return result

# Module for handling deduplication logic using DynamoDB
import logging
from storagebox.repository.dynamodb import DynamoDBBasedRepository
import abc

logger = logging.getLogger('storageBox')

class DeduplicationRepository(abc.ABC):
    """Abstract base class for deduplication repositories."""

    @abc.abstractmethod
    def fetch_item_by_dup_key(self, dup_key: str):
        """Retrieve stored item associated with a deduplication key."""
        raise NotImplementedError

    @abc.abstractmethod
    def store_dup_key_with_item(self, dup_key: str, data: str):
        """Store a new deduplication key with its associated data."""
        raise NotImplementedError

class DeduplicationDynamoDbRepository(DeduplicationRepository, DynamoDBBasedRepository):
    """Concrete implementation using DynamoDB for deduplication storage."""

    def fetch_item_by_dup_key(self, dup_key: str):
        """Get the stored item string for a given deduplication key."""
        response = self.table.get_item(
            Key={
                'deduplication_id': str(dup_key)
            }
        )
        return response.get('Item', {}).get('item_string')

    def store_dup_key_with_item(self, dup_key: str, data: str):
        """Insert a new deduplication entry only if it doesn't already exist."""
        record = {
            'deduplication_id': dup_key,
            'item_string': data
        }
        self.table.put_item(
            Item=record,
            Expected={
                'deduplication_id': {
                    'Exists': False
                }
            }
        )

