# Import required modules for hashing and type checking
import hashlib
from eth_utils import (
    is_boolean,
    is_bytes,
    is_dict,
    is_list_like,
    is_null,
    is_number,
    is_text,
    to_bytes,
)
from .six import (
    Generator,
)

def create_cache_identifier(data):
    """
    Creates a unique identifier for caching purposes based on the input value.
    Handles various data types including bytes, text, booleans, numbers, dicts, and lists.
    """
    if is_bytes(data):
        return hashlib.md5(data).hexdigest()
    elif is_text(data):
        return create_cache_identifier(to_bytes(text=data))
    elif is_boolean(data) or is_null(data) or is_number(data):
        return create_cache_identifier(repr(data))
    elif is_dict(data):
        # Sort dictionary keys before generating cache key for consistent ordering
        return create_cache_identifier(tuple(
            (key, data[key])
            for key
            in sorted(data.keys())
        ))
    elif is_list_like(data) or isinstance(data, Generator):
        # Concatenate cache keys of all items in the list/generator
        return create_cache_identifier("".join(
            create_cache_identifier(item)
            for item
            in data
        ))
    else:
        raise TypeError("Cannot generate cache identifier for value {0} of type {1}".format(
            data,
            type(data),
        ))

# Compute similarity-based rankings for vector sets
from functools import reduce
from typing import List, Callable

import numpy as np
from sklearn import preprocessing, neighbors, metrics

def rank_by_1NN(new_points: List, existing_points: List) -> List:
    # Initialize similarity scores for all candidate vectors
    similarity_scores = {tuple(vec): -1.0 for vec in existing_points}

    for point_vec in new_points:
        for target_vec in existing_points:
            similarity = compute_similarity(point_vec, target_vec)
            if similarity > similarity_scores[tuple(target_vec)]:
                similarity_scores[tuple(target_vec)] = similarity[0][0]

    # Sort candidates by descending similarity score
    return [list(item[0]) for item in sorted(similarity_scores.items(), key=lambda x: x[1], reverse=True)]

# Prototype ranking uses average of all emerged points as reference
def rank_by_prototype(new_points: List, existing_points: List) -> List:
    similarity_scores = {tuple(vec): -1.0 for vec in existing_points}

    prototype_vector = compute_prototype(new_points)
    for candidate_vec in existing_points:
        similarity = compute_similarity(candidate_vec, prototype_vector)
        similarity_scores[tuple(candidate_vec)] = similarity[0][0]

    return [list(item[0]) for item in sorted(similarity_scores.items(), key=lambda x: x[1], reverse=True)]

def compute_prototype(vectors: List) -> List:
    total = reduce(np.add, vectors)
    return np.divide(total, len(vectors))

def rank_by_progenitor(progenitor: tuple) -> Callable:
    def rank(new_points: List, existing_points: List) -> List:
        similarity_scores = {tuple(vec): -1.0 for vec in existing_points}
        for vec in existing_points:
            similarity = compute_similarity(progenitor, vec)
            similarity_scores[tuple(vec)] = similarity[0][0]

        return [list(item[0]) for item in sorted(similarity_scores.items(), key=lambda x: x[1], reverse=True)]

    return rank

def rank_by_exemplar(new_points: List, existing_points: List) -> List:
    cumulative_similarities = {tuple(vec): 0.0 for vec in existing_points}

    for point_vec in new_points:
        for candidate_vec in existing_points:
            cumulative_similarities[tuple(candidate_vec)] += compute_similarity(point_vec, candidate_vec)

    return [list(item[0]) for item in sorted(cumulative_similarities.items(), key=lambda x: x[1], reverse=True)]

def compute_similarity(vector_1: List, vector_2: List) -> float:
    return metrics.pairwise.cosine_similarity(np.asarray(vector_1).reshape(1, -1), np.asarray(vector_2).reshape(1, -1))

def sort_by_similarity_descending(score_dict: List) -> List:
    return [list(item[0]) for item in sorted(score_dict.items(), key=lambda x: x[1], reverse=True)]

