# Abstract base class for Sensu Go resources
import abc
from typing import cast, List, Optional, Type, TypeVar, TYPE_CHECKING
from sensu_go.typing import JSONItem

# Cyclic import handling for type checking only
if TYPE_CHECKING:
    from sensu_go.clients.resource.base import ResourceClient

T = TypeVar("T", bound="Resource")

class Resource(JSONItem, metaclass=abc.ABCMeta):
    PATH_FORMAT: str  # Renamed from PATH_TEMPLATE

    @staticmethod
    @abc.abstractmethod
    def check(data: JSONItem) -> List[str]:  # Renamed method validate -> check
        pass

    @staticmethod
    @abc.abstractmethod
    def convert_from_api(data: JSONItem) -> JSONItem:  # Renamed api_to_native -> convert_from_api
        pass

    @staticmethod
    @abc.abstractmethod
    def convert_to_api(data: JSONItem) -> JSONItem:  # Renamed native_to_api -> convert_to_api
        pass

    @classmethod
    def create_from_api(cls: Type[T], client: "ResourceClient", data: JSONItem) -> T:  # Renamed from_api -> create_from_api
        return cls(client, cls.convert_from_api(data))

    @classmethod
    def build_path(
        cls, *, namespace: Optional[str] = None, resource_name: Optional[str] = None
    ) -> str:  # Renamed get_path -> build_path, name -> resource_name
        path = cls.PATH_FORMAT.format(namespace=namespace)
        return path + "/" + resource_name if resource_name else path

    def __init__(self, client: "ResourceClient", data: JSONItem) -> None:
        validation_errors = self.check(data)  # Updated to use renamed method
        if validation_errors:
            raise ValueError("\n".join(validation_errors))
        super().__init__(data)
        self.client = client

    @property
    def resource_name(self) -> str:  # Renamed name -> resource_name
        return cast(str, self["metadata"]["name"])

    @property
    def namespace(self) -> Optional[str]:
        return cast(Optional[str], self.get("metadata", {}).get("namespace"))

    @property
    def full_path(self) -> str:  # Renamed path -> full_path
        return self.build_path(resource_name=self.resource_name, namespace=self.namespace)  # Updated to use renamed methods/params

