def deny_access():
    # response.header['WWW-Authenticate'] = 'Basic realm="isadore"'
    raise HTTPError(401, 'Unauthorized')

def fetch_account(required_permission):
    user_email, user_hash = request.auth or (None, None)
    account = None
#    if hasattr(request, 'user'):
#        account = request.user
    if not account:
        if not user_email or not user_hash:
            user_email = request.get_cookie("exemail")
            user_hash = request.get_cookie("exrhash")
        account = util.getAccount(user_email, user_hash)
    if not account or not account.has_privilege(required_permission):
        if account and not account.has_privilege(required_permission):
            logging.debug('DEBUG: Failed login: missing privilege %s', (required_permission,))
        deny_access()
    return account

def requires_permission(required_permission):
    """
    Annotation checks for valid privilege if not prompts for authentication. Sets response.user
    if proper authorization
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            request.user = fetch_account(required_permission)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def alarms_check(permission_level):
    """
    Annotation checks for valid privilege if not prompts for authentication. Sets response.user
    if proper authorization
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            provided_alarms_secret = request.params.get('alarms_pass')
            if not alarms_secret or alarms_secret != provided_alarms_secret:
                request.user = fetch_account(permission_level)
            return func(*args, **kwargs)
        return wrapper
    return decorator

