"""
Module to compute Euler's number (e) using series expansion
"""
#%%
def compute_factorial(value: int) -> int:
    if value == 0 or value == 1:
        return 1
    else:
        return value * compute_factorial(value - 1)

def approximate_euler(limit: int) -> float:
    return 1 + sum((1.0 / compute_factorial(index)) for index in range(1, limit))

def main():
    euler_value: float = approximate_euler(10)
    print(f"Euler's number using vectorization {euler_value: .4f}")

if __name__ == "__main__":
    main()

