# Modified version of HomeAssistanceForm with Type I clone techniques applied
from typing import Any, Dict, List, Optional, Text, Union
from rasa_sdk import Tracker
from rasa_sdk.events import EventType
from rasa_sdk.executor import CollectingDispatcher
from rasa_sdk.forms import FormAction
from covidflow.constants import HAS_ASSISTANCE_SLOT, PROVINCE_SLOT, PROVINCES_WITH_211
from .form_helper import request_next_slot, validate_boolean_slot, yes_no_nlu_mapping
from .lib.log_util import bind_logger

FORM_IDENTIFIER = "home_assistance_form"

def _supports_211_service(tracker: Tracker) -> bool:
    region = tracker.get_slot(PROVINCE_SLOT)
    return region in PROVINCES_WITH_211

class HomeAssistanceForm(FormAction):
    def name(self) -> Text:
        return FORM_IDENTIFIER

    async def execute(
        self, dispatcher, tracker, domain,
    ):
        bind_logger(tracker)
        return await super().execute(dispatcher, tracker, domain)

    @staticmethod
    def mandatory_slots(tracker: Tracker) -> List[Text]:
        if _supports_211_service(tracker):
            return [HAS_ASSISTANCE_SLOT]
        return []

    def mapping_for_slots(self) -> Dict[Text, Union[Dict, List[Dict]]]:
        return {
            HAS_ASSISTANCE_SLOT: yes_no_nlu_mapping(self),
        }

    def get_next_slot(
        self,
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> Optional[List[EventType]]:
        return request_next_slot(self, dispatcher, tracker, domain, None)

    @validate_boolean_slot
    def check_has_assistance(
        self,
        value: Union[bool, Text],
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> Dict[Text, Any]:
        return {}

    def perform_submission(
        self,
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> List[Dict]:
        if _supports_211_service(tracker) and not tracker.get_slot(HAS_ASSISTANCE_SLOT):
            dispatcher.utter_message(template="utter_check_delivery_services")
            if tracker.get_slot(PROVINCE_SLOT) == "qc":
                dispatcher.utter_message(template="utter_may_call_211_qc")
            else:
                dispatcher.utter_message(template="utter_may_call_211_other_provinces")
            dispatcher.utter_message(template="utter_explain_211")
        else:
            dispatcher.utter_message(template="utter_remind_delivery_services")
        dispatcher.utter_message(template="utter_remind_pharmacist_services")
        return []

import jieba
# Load custom dictionary files for jieba
from chi_annotator.algo_factory.components import Component
import glob

user_dict_paths = glob.glob("./custom_jieba_dicts/*")
for dict_path in user_dict_paths:
    jieba.load_userdict(dict_path)

class ChineseTokenizer(Component):
    name = "tokenizer_jieba_custom"
    provides = ["segmented_words"]

    def __init__(self, config=None):
        # type: (AnnotatorConfig) -> None
        self.config = config
        super(Component, self).__init__()

    @classmethod
    def required_packages(cls):
        # type: () -> List[Text]
        return ["jieba"]

    def train(self, training_data, config, **kwargs):
        # type: (TrainingData, RasaNLUConfig, **Any) -> None
        if config.get('language', '') != 'zh':
            raise Exception("Chinese tokenizer requires language setting to be 'zh'. Please check your configuration.")

        for example in training_data.training_examples:
            example.set("segmented_words", self._segment_text(example.text))

    def process(self, message, **kwargs):
        # type: (Message, **Any) -> None
        message.set("segmented_words", self._segment_text(message.text))

    def _segment_text(self, text):
        # type: (Text) -> List[Token]
        segments = jieba.cut(text)
        result_tokens = [token for token in segments]
        return result_tokens

import os
import argparse
from collections import Sequence
import base58
import libnacl

TXN_TYPE_XFER = "10001"

def validate_path(is_directory: bool, path_name: str):
    full_path = os.path.expanduser(path_name)
    access_rights = os.W_OK if is_directory else os.R_OK
    check_func = os.path.isdir if is_directory else os.path.isfile
    size_validation = True if is_directory else os.path.getsize(full_path) > 0
    if check_func(full_path) and os.access(full_path, access_rights) and size_validation:
        return full_path
    raise argparse.ArgumentTypeError("{} not found or permission denied or file empty".format(full_path))

def validate_seed(seed_value: str):
    if len(seed_value) == 32:
        return seed_value
    raise argparse.ArgumentTypeError("Seed must be 32 characters long but provided {}".format(len(seed_value)))

def verify_reply(response):
    if isinstance(response, str):
        response = json.loads(response)
    if "op" not in response or response["op"] != "REPLY":
        raise Exception("Response is not a successful reply: {}".format(response))

def split_sequence_into_batches(sequence_data: Sequence, batch_size: int):
    return (sequence_data[offset:offset + batch_size] for offset in range(0, len(sequence_data), batch_size))

# Copied from Plenum
def rawToBase58(raw_bytes):
    return base58.b58encode(raw_bytes).decode("utf-8")

# Copied from Plenum
def generate_random_string(length: int) -> str:
    assert (length > 0), "Expected random string length cannot be less than 1"
    hex_part = libnacl.randombytes(length // 2).hex()
    return hex_part if length % 2 == 0 else hex_part + hex(libnacl.randombytes_uniform(15))[-1]

def extract_transaction_data(txn_dict):
    temp = txn_dict or {}
    return temp.get('result', {}).get('txn', {}) or temp.get('txn', {})

def extract_transaction_type(txn_dict):
    return extract_transaction_data(txn_dict).get('type', None)

def extract_transaction_id(txn_dict):
    temp = txn_dict or {}
    return (temp.get('result', {}).get('txnMetadata', {}) or temp.get('txnMetadata', {})).get('txnId', None)

def get_operation_type(request_obj):
    if isinstance(request_obj, dict):
        dict_request = request_obj
    elif isinstance(request_obj, str):
        dict_request = json.loads(request_obj)
    else:
        raise RuntimeError("Request of unsupported type")
    txn_category = dict_request.get("operation", {}).get("type", "")
    return txn_category

def construct_input_output(address_utxos, target_value):
    for account_address in address_utxos:
        input_list = []
        output_list = []
        accumulated_amount = 0
        temporary_utxo = []
        while address_utxos[account_address] and accumulated_amount < target_value:
            (utxo_source, utxo_amount) = address_utxos[account_address].pop()
            if utxo_amount > 0:
                input_list.append(utxo_source)
                accumulated_amount += utxo_amount
                temporary_utxo.append((utxo_source, utxo_amount))
        if accumulated_amount >= target_value:
            change_amount = accumulated_amount - target_value
            if change_amount > 0:
                output_list = [{"recipient": account_address, "amount": change_amount}]
            return {account_address: temporary_utxo}, input_list, output_list
        else:
            for u_s in temporary_utxo:
                address_utxos[account_address].append(u_s)
    return None, None, None

# Custom exceptions for the cruft project
from pathlib import Path
from typing import Union

class CruftError(Exception):
    """Base exception class for all errors originating from the cruft project"""

class UnableToFindCookiecutterTemplate(CruftError):
    """Raised when Cruft cannot locate a cookiecutter template"""
    def __init__(self, path: Union[str, Path]):
        if not isinstance(path, str):
            path = str(path)
        super().__init__(f"Was unable to locate a Cookiecutter template in `{path}` !")
        self.path = path

class NoCruftFound(CruftError):
    """Raised when no .cruft.json state file is found in the current directory"""
    def __init__(self, folder: Union[str, Path]):
        if not isinstance(folder, str):
            folder = str(folder)
        super().__init__(
            f"Was unable to locate a `.cruft.json` state file in `{folder}` !"
        )
        self.folder = folder

class CruftAlreadyPresent(CruftError):
    """Raised when attempting to create a new .cruft.json file that already exists"""
    def __init__(self, filepath: Union[str, Path]):
        if not isinstance(filepath, str):
            filepath = str(filepath)
        super().__init__(f"`.cruft.json` is already defined at `{filepath}` !")
        self.filepath = filepath

class InvalidCookiecutterRepository(CruftError):
    """Raised when an invalid cookiecutter repository URL or path is provided"""
    pass

