from typing import Counter as _TypedCounter, Dict as _Dict, List as _List, FrozenSet as _FrozenSet, Optional as _Optional, Any as _Any
from ._constant import LETTER as _LETTER_CONSTANT
from .language import Language as _LanguageClass

class _CustomJSONEncoder(_json_module.JSONEncoder):
    def default(self, obj: _Any) -> _Any:
        if isinstance(obj, _JSONSerializableModel):
            return {"language": obj.language.name, "ngrams": obj.ngrams}
        return _json_module.JSONEncoder.default(self, obj)

class _CustomJSONDecoder(_json_module.JSONDecoder):
    def __init__(self, *args, **kwargs):
        _json_module.JSONDecoder.__init__(self, object_hook=self._custom_object_hook, *args, **kwargs)

    def _custom_object_hook(self, obj: _Any) -> _Any:
        if isinstance(obj, dict) and "language" in obj and "ngrams" in obj:
            language = _LanguageClass[obj["language"]]
            ngrams = self._custom_object_hook(obj["ngrams"])
            return _JSONSerializableModel(language, ngrams)
        return obj

@_dataclass
class _JSONSerializableModel:
    language: _LanguageClass
    ngrams: _Dict[str, str]

@_dataclass
class _CorpusLanguageModel:
    language: _LanguageClass
    absolute_counts: _Optional[_Dict[str, int]]
    relative_counts: _Optional[_Dict[str, _Fraction]]
    json_relative_counts: _Optional[_Dict[str, float]]

    @classmethod
    def create_from_text(
        cls,
        text_data: _List[str],
        target_language: _LanguageClass,
        sequence_length: int,
        character_class: str,
        lower_sequence_absolute_counts: _Optional[_Dict[str, int]],
    ) -> "_CorpusLanguageModel":
        absolute_counts = cls._calculate_absolute_counts(
            text_data, sequence_length, character_class
        )
        relative_counts = cls._calculate_relative_counts(
            sequence_length, absolute_counts, lower_sequence_absolute_counts
        )
        return _CorpusLanguageModel(
            language=target_language,
            absolute_counts=absolute_counts,
            relative_counts=relative_counts,
            json_relative_counts=None,
        )

    @classmethod
    def create_from_json_string(cls, serialized_data: str) -> "_CorpusLanguageModel":
        json_model: _JSONSerializableModel = _json_module.loads(
            serialized_data, cls=_CustomJSONEncoder
        )
        json_relative_counts = {}
        for fraction_str, sequences in json_model.ngrams.items():
            numerator_val, denominator_val = fraction_str.split("/")
            log_frequency = _math_module.log(int(numerator_val) / int(denominator_val))
            for seq in sequences.split(" "):
                json_relative_counts[seq] = log_frequency
        return _CorpusLanguageModel(
            language=json_model.language,
            absolute_counts=None,
            relative_counts=None,
            json_relative_counts=json_relative_counts,
        )

    def export_to_json(self) -> str:
        fractions_to_sequences = _defaultdict(list)
        if self.relative_counts is not None:
            for seq, frac in self.relative_counts.items():
                fractions_to_sequences[frac].append(seq)

        ordered_fractions = _OrderedDict()
        for frac_val, sequences_list in fractions_to_sequences.items():
            fraction_repr = f"{frac_val.numerator}/{frac_val.denominator}"
            ordered_fractions[fraction_repr] = " ".join(
                sorted(map(lambda s: s, sequences_list))
            )

        model_instance = _JSONSerializableModel(self.language, ordered_fractions)
        return _regex_module.sub(r"([:,])\s*", r"\1", _json_module.dumps(model_instance, cls=_CustomJSONEncoder))

    def get_probability_value(self, sequence: str) -> float:
        if (
            self.json_relative_counts is None
            or sequence not in self.json_relative_counts
        ):
            return 0.0
        return self.json_relative_counts[sequence]

    @classmethod
    def _calculate_absolute_counts(
        cls, text_data: _List[str], sequence_length: int, character_class: str
    ) -> _Dict[str, int]:
        absolute_counts: _TypedCounter[str] = _Counter()
        pattern = _regex_module.compile(r"^[{}]+$".format(character_class))
        for line in text_data:
            lowercase_line = line.lower()
            for idx in range(0, len(lowercase_line) - sequence_length + 1):
                substring = lowercase_line[idx : idx + sequence_length]
                if pattern.match(substring) is not None:
                    absolute_counts.update([substring])
        return absolute_counts

    @classmethod
    def _calculate_relative_counts(
        cls,
        sequence_length: int,
        absolute_counts: _Dict[str, int],
        lower_sequence_absolute_counts: _Optional[_Dict[str, int]],
    ) -> _Dict[str, _Fraction]:
        if lower_sequence_absolute_counts is None:
            return {}

        sequence_probabilities = {}
        total_sequence_count = sum(absolute_counts.values())

        for seq, count in absolute_counts.items():
            if sequence_length == 1 or len(lower_sequence_absolute_counts) == 0:
                divisor = total_sequence_count
            else:
                prefix = seq[: sequence_length - 1]
                divisor = lower_sequence_absolute_counts[prefix]

            sequence_probabilities[seq] = _Fraction(count, divisor)

        return sequence_probabilities

@_dataclass
class _ValidationLanguageModel:
    sequences: _FrozenSet[str]

    @classmethod
    def create_from_text(cls, input_text: str, sequence_length: int) -> "_ValidationLanguageModel":
        if sequence_length not in range(1, 6):
            raise ValueError(f"sequence length {sequence_length} is not in range 1..6")

        sequences_set = set()
        text_len = len(input_text)

        if text_len >= sequence_length:
            for i in range(0, text_len - sequence_length + 1):
                substr = input_text[i : i + sequence_length]
                if _LETTER_CONSTANT.fullmatch(substr) is not None:
                    sequences_set.add(substr)

        return _ValidationLanguageModel(frozenset(sequences_set))

# Calculate the number of unique paths in a grid
class Solution:
    def uniquePaths(self, rows: int, cols: int) -> int:
        cache = {}

        def _count_paths(x: int, y: int) -> int:
            if (x, y) in cache:
                return cache[(x, y)]

            # Base case: when we reach the bottom-right corner
            if x >= rows - 1 or y >= cols - 1:
                return 1

            # Recursive case: move right + move down
            path_count = _count_paths(x + 1, y) + _count_paths(x, y + 1)
            cache[(x, y)] = path_count
            return path_count

        return _count_paths(0, 0)

# Custom Numba compiler setup for Galois-specific optimizations
import numba.cpython.builtins
from llvmlite import ir
from numba.core import compiler, sigutils, types
from numba.core.compiler import CompilerBase, DefaultPassBuilder
from numba.core.imputils import lower_constant

# Configuration flags
disable_nrt = True
external_function_pointer_as_constant = True

class GaloisCompiler(CompilerBase):
    """A specialized numba compiler pipeline tailored for Galois computations.
    """
    def define_pipelines(self):
        # Preserve objmode fallback behavior
        pipelines = []
        if not self.state.flags.force_pyobject:
            pipelines.append(DefaultPassBuilder.define_nopython_pipeline(self.state))
        if self.state.status.can_fallback or self.state.flags.force_pyobject:
            pipelines.append(DefaultPassBuilder.define_objectmode_pipeline(self.state))
        if hasattr(self.state.status, "can_giveup") and self.state.status.can_giveup:
            pipelines.append(DefaultPassBuilder.define_interpreted_pipeline(self.state))
        return pipelines

class OperatorKernelCompiler(GaloisCompiler):
    """A numba compiler pipeline optimized for Galois operators.
    Assumes operators do not leak references to memory objects such as arrays.
    """
    def __init__(self, typingctx, targetctx, library, args, return_type, flags, local_vars):
        if disable_nrt:
            flags.nrt = False
        super().__init__(typingctx, targetctx, library, args, return_type, flags, local_vars)
        targetctx.is_operator_context = True

@lower_constant(types.ExternalFunctionPointer)
def constant_function_pointer(context, builder: ir.IRBuilder, ty, pyval):
    """
    Override the internal handling of ExternalFunctionPointer to avoid generating a global variable.
    """
    if (
        external_function_pointer_as_constant
        and hasattr(context, "is_operator_context")
        and context.is_operator_context
    ):
        ptrty = context.get_function_pointer_type(ty)
        return ir.Constant(ir.types.IntType(64), ty.get_pointer(pyval)).inttoptr(ptrty)
    # Fall back to standard Numba implementation when not in operator context
    return numba.cpython.builtins.constant_function_pointer(context, builder, ty, pyval)

