import cv2
import numpy as np

class ShapeClassifier:
    def identify(self, contour):
        figure = "unknown"
        perimeter = cv2.arcLength(contour, True)
        approx_shape = cv2.approxPolyDP(contour, 0.04 * perimeter, True)
        vertices = len(approx_shape)

        if vertices == 3:
            figure = "triangle"
        elif vertices == 4:
            x_coord, y_coord, width, height = cv2.boundingRect(approx_shape)
            aspect_ratio = width / height
            figure = "square" if aspect_ratio >= 0.95 and aspect_ratio <= 1.05 else "rectangle"
        elif vertices == 5:
            figure = "pentagon"
        else:
            figure = "circle"

        return figure

