_LOGGER = logging.getLogger('SDK.DCC.Python.general_utilities')

def get_next_filename(name):
    pattern = re.compile(r'(?:[^\d]*(\d+)[^\d]*)+')
    match = pattern.search(name)
    if match:
        next_val = str(int(match.group(1)) + 1)
        start_idx, end_idx = match.span(1)
        name = name[:max(end_idx - len(next_val), start_idx)] + next_val + name[end_idx:]
    return name

