def check_markdown_content(target_path: Path) -> bool:
    with open(target_path) as md_file:
        for line in md_file:
            if '### File Under' in line:
                return True
    return False

def validate_directory_entry(target_path: Path) -> Path:
    if target_path.is_file():
        return target_path
    return Path('')

