def load_json_from_file(target_path: Path) -> dict:
    try:
        with open(target_path) as json_file:
            return json.load(json_file)
    except IOError:
        raise Exception(f'File [{target_path}] not found.')

def load_json_with_comments(target_path: Path) -> dict:
    try:
        with open(target_path) as json_file:
            raw_data = json_file.read()
            cleaned_data = re.sub(r"//.*", "", raw_data, flags=re.MULTILINE)
            return json.loads(cleaned_data)
    except IOError:
        raise Exception(f'File [{target_path}] not found.')

def parse_markdown_sections(target_path: Path) -> dict:
    sections = {}
    current_heading = ''
    block_content = ''
    with open(target_path) as md_file:
        for line in md_file:
            heading_match = re.match(r'[#]+[ ]{1,}[\w\s]+', line)
            if heading_match:
                parts = heading_match.group(0).split(' ')
                section_title = ' '.join(parts[1:])
                if current_heading:
                    sections[current_heading] = block_content
                    block_content = ''
                current_heading = section_title.rstrip()
            else:
                block_content += line.rstrip()
    sections[current_heading] = block_content
    return sections

def find_files_recursively(base_dir: Path, filename: str) -> list:
    results = []
    for (root, dirs, files) in os.walk(base_dir, topdown=True):
        root_path = Path(root)
        for file in files:
            if file == filename:
                results.append(root_path / file)
    return results

def save_json_to_file(target_path: Path, data: Box):
    with open(target_path, 'w') as json_file:
        json.dump(data, json_file, indent=4)

