def connect_to_db(db_path: str) -> sqlite3.Connection:
    try:
        conn = sqlite3.connect(db_path)
        _LOGGER.info(f'DB Connection Established: {sqlite3.version}')
        return conn
    except Error as e:
        _LOGGER.warning(f'Database connection failed. Error: {e}')
        return None

def initialize_table(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, columns: list):
    column_list = ', '.join(columns)
    _LOGGER.info(f'Creating Table [{table_name}]: {column_list}')
    execute_sql_command(conn, cursor, f"""CREATE TABLE IF NOT EXISTS {table_name} ({column_list})""")

def delete_table(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str):
    execute_sql_command(conn, cursor, f"""DROP TABLE {table_name}""")

def insert_into_table(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, row_values: list):
    value_list = ', '.join(row_values)
    execute_sql_command(conn, cursor, f"""INSERT INTO {table_name} VALUES ({value_list})""")

def delete_row_from_table(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, record_id: int):
    execute_sql_command(conn, cursor, f"""DELETE from {table_name} where id = {record_id}""")

def execute_sql_command(conn: sqlite3.Connection, cursor: sqlite3.Cursor, query: str):
    _LOGGER.info(f'Executing: {query}')
    cursor.execute(query)
    conn.commit()

def fetch_table_contents(cursor: sqlite3.Cursor, table: str) -> dict:
    result_dict = {}
    cursor.execute(f"""SELECT * from {table}""")
    rows = cursor.fetchall()
    for row in rows:
        result_dict[row[0]] = row[1]
    return result_dict

def fetch_multiple_tables(cursor: sqlite3.Cursor, table_names: list) -> dict:
    db_data = {}
    for table in table_names:
        cursor.execute(f"""SELECT * from {table}""")
        table_rows = cursor.fetchall()
        db_data[table] = table_rows
    return db_data

# Calculate the product of the losing player's score and total die rolls
from typing import Any, List, Tuple
from aocpy import BaseChallenge

class LoadedDie:
    roll_count: int
    def __init__(self, faces: int = 100):
        self._faces = faces
        self._current = 0
        self.roll_count = 0

    def roll_once(self) -> int:
        self.roll_count += 1
        self._current += 1
        if self._current > self._faces:
            self._current = 1
        return self._current

    def roll_multiple(self, count: int) -> List[int]:
        results = []
        for _ in range(count):
            results.append(self.roll_once())
        return results

GameState = List[int]  # position, score
GameStates = Tuple[GameState, GameState]

def parse_input(data: str) -> GameStates:
    result = []
    for line in data.strip().splitlines():
        initial_pos = int(line.split(": ")[-1])
        result.append([initial_pos, 0])
    return tuple(result)

def calculate_new_position(current: int, distance: int) -> int:
    new_pos = current + (distance % 10)
    return new_pos if new_pos <= 10 else new_pos - 10

def advance_player(state: GameState, steps: int):
    state[0] = calculate_new_position(state[0], steps)
    state[1] = state[1] + state[0]

def retrieve_score(state: GameState) -> int:
    return state[1]

class Challenge(BaseChallenge):
    @staticmethod
    def solve_part_one(data: str) -> Any:
        game_states = parse_input(data)
        dice = LoadedDie()

        while True:
            round_ended = False
            for player_state in game_states:
                movement = sum(dice.roll_multiple(3))
                advance_player(player_state, movement)

                if retrieve_score(player_state) >= 1000:
                    round_ended = True
                    break

            if round_ended:
                break

        final_scores = sorted([retrieve_score(p) for p in game_states])
        return final_scores[0] * dice.roll_count

    @staticmethod
    def solve_part_two(data: str) -> int:
        raise NotImplementedError

import torch
from typing import Optional

class OptimizationDirection:
    @property
    def direction(self):
        if hasattr(self, '_direction'):
            return self._direction
        return True

class StandardError:
    def __init__(self, apply_weight: bool):
        self.apply_weight = apply_weight

    def _compute_error(self, values_tensor: torch.Tensor, masks: torch.Tensor,
                       factors: torch.Tensor, stats: Optional[torch.Tensor] = None, *args, **kwargs):
        weights = self.extract_weights_from_mask(masks)
        if len(values_tensor.shape) > 3:
            values_tensor = torch.squeeze(values_tensor, 0)
        processed_tensor = (torch.squeeze(values_tensor * masks, -1) * factors)
        if stats is not None:
            if len(stats.shape) > 3:
                stats = torch.squeeze(stats, 0)
            processed_tensor = stats * processed_tensor
        else:
            processed_tensor = torch.unsqueeze(processed_tensor, 0)
        average_value = torch.div(torch.sum(processed_tensor, dim=1), weights)
        return self.compute_squared(average_value, weights if self.apply_weight else None)

    @staticmethod
    def extract_weights_from_mask(masks: torch.Tensor) -> torch.Tensor:
        weights = torch.sum(masks, dim=0)
        weights = torch.squeeze(weights, -1)
        return weights

    @staticmethod
    def compute_squared(tensor_data: torch.Tensor, weights: torch.Tensor = None, scale_by_max: bool = True):
        squared_values = torch.square(tensor_data)
        if weights is not None:
            divisor = torch.max(weights) if scale_by_max else torch.sum(weights)
            weights = weights / divisor
            squared_values *= weights
            return torch.mean(squared_values) if scale_by_max else torch.sum(squared_values)
        return torch.mean(squared_values)

class SimpleError(StandardError):
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor,
                 factors: torch.Tensor, *args, **kwargs):
        return self._compute_error(values_tensor, masks, factors)

class ContextualError(StandardError):
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor,
                 factors: torch.Tensor, stats: torch.Tensor, *args, **kwargs):
        return self._compute_error(values_tensor, masks, factors, stats)

class WeightedError(StandardError, OptimizationDirection):
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor, *args, **kwargs):
        weights = self.extract_weights_from_mask(masks)
        return self.compute_squared(values_tensor, weights if self.apply_weight else None, scale_by_max=False)

class DeviationLoss:
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor, factor_weights: torch.Tensor, *args, **kwargs):
        count_per_time = torch.sum(torch.squeeze(masks, -1), dim=1)
        filtered_values = torch.masked_select(values_tensor, masks).reshape(
            (torch.sum(masks), values_tensor.shape[-1]))
        factor_weights = torch.squeeze(factor_weights, 0)
        value_groups = torch.split(filtered_values, count_per_time.tolist())
        weight_groups = torch.split(factor_weights, count_per_time.tolist())

        deviation_list = list()
        variance_list = list()

        for v_t, w_t in zip(value_groups, weight_groups):
            v_t_pred = torch.sum(v_t * w_t) / torch.sum(w_t * w_t) * w_t
            deviation_list.append(torch.mean(torch.square(v_t - v_t_pred)))
            variance_list.append(torch.mean(torch.square(v_t)))

        return torch.mean(torch.tensor(deviation_list)) / torch.mean(torch.tensor(variance_list))

class ErrorAggregator(OptimizationDirection):
    def __init__(self, direction: bool, apply_weight: bool, use_contextual: bool,
                 deviation_factor: float = 0.):
        self.deviation_factor = deviation_factor
        if use_contextual:
            self.primary_loss = ContextualError(apply_weight=apply_weight)
        else:
            self.primary_loss = SimpleError(apply_weight=apply_weight)
        self.deviation_loss = DeviationLoss()
        self._direction = direction
        if not self.direction and self.deviation_factor:
            raise NotImplementedError('Cannot maximize with deviation loss')

    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor, factors: torch.Tensor,
                 factor_weights: torch.Tensor = None, stats: Optional[torch.Tensor] = None, *args, **kwargs):
        primary_factor = 1 if self.direction else -1
        error = primary_factor * self.primary_loss(
            values_tensor=values_tensor,
            masks=masks,
            factors=factors,
            stats=stats)
        if self.deviation_factor:
            error += self.deviation_loss(values_tensor, masks, factor_weights) * self.deviation_factor
        return error

# Import required libraries for web scraping and regex
import re
from bs4 import BeautifulSoup
from scraper.utils import get_page, make_soup

class Track:
    def __init__(self, track_url: str) -> None:
        self.url = track_url
        self.parse(get_page(track_url))

    def __str__(self) -> str:
        return f'{self.performer} - {self.name}: {" ".join(self.chord_list)}'

    @staticmethod
    def extract_chords(soup: BeautifulSoup) -> List[str]:
        """Extracts and returns chords from the provided HTML content."""

        chord_list = []
        for code_element in soup.find_all('code'):
            chord = f'{code_element["data-chord"]}{code_element["data-suffix"]}'
            if code_element['data-chord'] and chord not in chord_list:
                chord_list.append(chord)
        return chord_list

    @staticmethod
    def extract_title(soup: BeautifulSoup) -> str:
        """Extracts and returns the track's title."""
        return soup.select_one('h1 strong').text

    @staticmethod
    def extract_performer(soup: BeautifulSoup) -> str:
        """Extracts and returns the track's performer/author."""
        tag = soup.select_one('h1')
        tag.find('strong').extract()
        # remove text within parentheses
        return re.sub(r'\(.*\)', '', tag.text).strip()

    def parse(self, html_content: str) -> None:
        soup = make_soup(html_content)
        self.chord_list = self.extract_chords(soup)
        self.name = self.extract_title(soup)
        self.performer = self.extract_performer(soup)

# Custom schema for validating against a set of allowed string options
from dataclasses import dataclass
from typing import Any, Optional, Sequence
from .schema import Schema, SchemaError
from .type_schema import InvalidTypeError

class AllowedValueSchema(Schema):
    def __init__(self, *allowed_values: str):
        self._valid_options = [val.lower() for val in allowed_values]
        self._error_message = InvalidOptionSpecifiedError(allowed_values)

    def validate(self, input_data: Any) -> Optional[SchemaError]:
        if not isinstance(input_data, str):
            return InvalidTypeError(str)
        if input_data.lower() not in self._valid_options:
            return self._error_message
        else:
            return None

@dataclass
class InvalidOptionSpecifiedError(SchemaError):
    permitted_values: Sequence[str]

def create_options_validator(*allowed_values: str) -> AllowedValueSchema:
    return AllowedValueSchema(*allowed_values)

from typing import List, Optional
import pandas as pd

class PEPRECException(Exception):
    """Custom exception for invalid PEPREC files."""
    pass

class PeptideRecord:
    """Class representing a peptide record (PEPREC file)."""

    def __init__(
        self,
        filepath: Optional[str] = None,
        mode: str = "default",
        additional_columns: Optional[List[str]] = None,
    ):
        """
        Initialize a PeptideRecord instance.

        Parameters
        ----------
        filepath: str, None
            Path to the PEPREC file. If provided, the file will be loaded automatically.
        mode: str
            Context mode for determining required columns. Supported values include 
            "default", "ms2rescore", and "retention_time".
        additional_columns: List[str]
            Extra column names to be considered during validation.
        """
        self.filepath = filepath
        self.mode = mode
        self.additional_columns = additional_columns
        self._dataframe = None

        if self.filepath:
            self.load_from_csv(self.filepath)

    def __repr__(self):
        """Return string representation of the internal DataFrame."""
        return self._dataframe.__repr__()

    @property
    def dataframe(self) -> Optional[pd.DataFrame]:
        """Access the underlying DataFrame."""
        return self._dataframe

    @dataframe.setter
    def dataframe(self, df: Optional[pd.DataFrame]):
        """Set and validate the DataFrame."""
        if isinstance(df, pd.DataFrame):
            self._check_column_names(df)
        self._dataframe = df

    def load_from_csv(self, filepath: str, **kwargs):
        """Load PEPREC data from a CSV file."""
        self._validate_file_header(filepath)
        delimiter = self._detect_delimiter(filepath)
        self.dataframe = pd.read_csv(filepath, sep=delimiter, index_col=None, **kwargs)
        self.dataframe["modifications"] = self.dataframe["modifications"].fillna("-")

    def save_to_csv(self, output_path: Optional[str] = None, **kwargs):
        """Save current PEPREC data to a CSV file."""
        target_path = output_path or self.filepath
        if not target_path:
            raise ValueError("No output path specified and no stored filepath available.")

        self.dataframe.to_csv(
            target_path, 
            sep=" ", 
            index=False, 
            float_format="%.3f", 
            **kwargs
        )

    def sort_columns(self):
        """Reorder columns so canonical PEPREC columns appear first."""
        current_cols = self.dataframe.columns.tolist()

        # Remove required columns from current list if present
        for col in self._mandatory_columns:
            if col in current_cols:
                current_cols.remove(col)
            else:
                self._mandatory_columns.remove(col)

        # Reconstruct column order
        ordered_cols = self._mandatory_columns + current_cols
        self.dataframe = self.dataframe[ordered_cols]

    @property
    def _mandatory_columns(self):
        """Determine mandatory columns based on current mode."""
        mandatory = [
            "spec_id",
            "peptide",
            "modifications",
            "charge",
        ]

        if self.mode == "ms2rescore":
            mandatory.extend([
                "psm_score",
                "observed_retention_time",
            ])
        elif self.mode == "retention_time":
            if "modifications" in mandatory:
                mandatory.remove("modifications")

        return mandatory

    def _validate_file_header(self, filepath: str):
        """Ensure the file header starts with 'spec_id'."""
        with open(filepath, "rt") as f:
            first_line = f.readline()
            if not first_line.startswith("spec_id"):
                raise PEPRECException("PEPREC file must begin with 'spec_id' in header.")

    def _check_column_names(self, df: pd.DataFrame):
        """Verify that all mandatory columns are present in the DataFrame."""
        for col in self._mandatory_columns:
            if col not in df.columns:
                raise PEPRECException(f"Mandatory column '{col}' is missing.")

    @classmethod
    def from_dataframe(cls, df: pd.DataFrame):
        """Create a PeptideRecord instance from an existing DataFrame."""
        instance = cls()
        instance.dataframe = df
        instance.sort_columns()
        return instance

    @classmethod
    def from_csv(cls, *args, **kwargs):
        """Create a PeptideRecord instance by loading a CSV file."""
        instance = cls()
        instance.load_from_csv(*args, **kwargs)
        return instance

    @staticmethod
    def _detect_delimiter(filepath: str) -> str:
        """Detect the delimiter used in the PEPREC file."""
        with open(filepath, "rt") as f:
            line = f.readline()
            # Assuming 7th character is the delimiter after 'spec_id'
            delimiter = line[7] if len(line) > 7 else ","
        return delimiter

import re
from pathlib import Path
# Assuming CodeGraph is defined elsewhere in the project
class CodeChunk:
    def __init__(
        self,
        data,
        line_start,
        line_end,
        kind,
        identifier,
        imports_section,
        class_info,
        source_file,
    ):
        self.data = data
        self.line_start = line_start
        self.line_end = line_end
        self.kind = kind
        self.identifier = identifier
        self.imports_section = imports_section
        self.class_info = class_info
        self.source_file = source_file

    def get_full_context(self):
        segments = []
        if self.imports_section:
            segments.append(f"# Imports\n{self.imports_section}")
        if self.class_info:
            segments.append(f"# Class context\n{self.class_info}")
        segments.append(
            f"# {self.kind.title()}: {self.identifier} (lines {self.line_start}-{self.line_end})"
        )
        segments.append(self.data)
        return "\n\n".join(segments)

    def with_line_numbers(self):
        lines = self.data.splitlines()
        numbered_lines = []
        for idx, current_line in enumerate(lines, self.line_start):
            numbered_lines.append(f"{idx:4d} | {current_line}")
        return "\n".join(numbered_lines)


class ASTChunker:
    def __init__(
        self,
        max_chunk_chars_limit=2000 * 4,
        overlap_size=5,
        include_imports_flag=True,
        include_class_context_flag=True,
    ):
        self.max_chunk_chars_limit = max_chunk_chars_limit
        self.overlap_size = overlap_size
        self.include_imports_flag = include_imports_flag
        self.include_class_context_flag = include_class_context_flag

    def chunk_file(self, code_source, file_path=""):
        try:
            tree = ast.parse(code_source)
        except SyntaxError:
            return self._fallback_chunk(code_source, file_path)

        all_lines = code_source.splitlines()
        extracted_imports = self._extract_imports(tree, all_lines)
        result_chunks = []

        for node in ast.iter_child_nodes(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                func_chunk = self._create_function_chunk(node, all_lines, extracted_imports, file_path)
                result_chunks.append(func_chunk)
            elif isinstance(node, ast.ClassDef):
                class_chunk = self._create_class_chunk(node, all_lines, extracted_imports, file_path)
                class_size = len(class_chunk.data)
                if class_size <= self.max_chunk_chars_limit:
                    result_chunks.append(class_chunk)
                else:
                    header_info = self._get_class_header(node, all_lines)
                    for item in node.body:
                        if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            method_chunk = self._create_method_chunk(
                                item,
                                all_lines,
                                extracted_imports,
                                file_path,
                                class_name=node.name,
                                class_context=header_info,
                            )
                            result_chunks.append(method_chunk)

        if not result_chunks:
            result_chunks.append(
                CodeChunk(
                    data=code_source,
                    line_start=1,
                    line_end=len(all_lines),
                    kind="module",
                    identifier=Path(file_path).stem if file_path else "module",
                    imports_section=extracted_imports,
                    class_info=None,
                    source_file=file_path,
                )
            )

        result_chunks = self._split_large_chunks(result_chunks)
        return result_chunks

    def _extract_imports(self, tree, lines):
        import_lines = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                start_idx = node.lineno - 1
                end_idx = getattr(node, "end_lineno", node.lineno)
                import_lines.extend(lines[start_idx:end_idx])
        return "\n".join(import_lines)

    def _create_function_chunk(self, node, lines, imports, file_path):
        start_idx = node.lineno - 1
        end_idx = getattr(node, "end_lineno", node.lineno + 10)
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start_idx:end_idx])
        return CodeChunk(
            data=content,
            line_start=start_idx + 1,
            line_end=end_idx,
            kind="function",
            identifier=node.name,
            imports_section=imports if self.include_imports_flag else "",
            class_info=None,
            source_file=file_path,
        )

    def _create_class_chunk(self, node, lines, imports, file_path):
        start_idx = node.lineno - 1
        end_idx = getattr(node, "end_lineno", node.lineno + 20)
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start_idx:end_idx])
        return CodeChunk(
            data=content,
            line_start=start_idx + 1,
            line_end=end_idx,
            kind="class",
            identifier=node.name,
            imports_section=imports if self.include_imports_flag else "",
            class_info=None,
            source_file=file_path,
        )

    def _create_method_chunk(
        self, node, lines, imports, file_path, class_name, class_context
    ):
        start_idx = node.lineno - 1
        end_idx = getattr(node, "end_lineno", node.lineno + 10)
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start_idx:end_idx])
        method_name = class_name + "." + node.name
        imports_out = ""
        if self.include_imports_flag:
            imports_out = imports
        class_ctx_out = None
        if self.include_class_context_flag:
            class_ctx_out = class_context
        return CodeChunk(
            data=content,
            line_start=start_idx + 1,
            line_end=end_idx,
            kind="method",
            identifier=method_name,
            imports_section=imports_out,
            class_info=class_ctx_out,
            source_file=file_path,
        )

    def _get_class_header(self, node, lines):
        start_idx = node.lineno - 1
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        header_end = node.lineno
        for item in node.body:
            if isinstance(item, ast.Expr) and isinstance(item.value, ast.Constant):
                header_end = getattr(item, "end_lineno", item.lineno)
            else:
                break
        return "\n".join(lines[start_idx:header_end])

    def _split_large_chunks(self, chunks):
        final_chunks = []
        for chunk in chunks:
            if len(chunk.data) <= self.max_chunk_chars_limit:
                final_chunks.append(chunk)
            else:
                sub_parts = self._split_by_blocks(chunk)
                final_chunks.extend(sub_parts)
        return final_chunks

    def _split_by_blocks(self, chunk):
        lines = chunk.data.splitlines()
        lines_per_subchunk = self.max_chunk_chars_limit // 60
        sub_chunks = []
        i = 0
        while i < len(lines):
            end = min(i + lines_per_subchunk, len(lines))
            if end < len(lines):
                for j in range(end, max(i + lines_per_subchunk // 2, i), -1):
                    if not lines[j].strip() or lines[j].strip().startswith(
                        ("#", "def ", "class ")
                    ):
                        end = j
                        break
            sub_content = "\n".join(lines[i:end])
            sub_chunks.append(
                CodeChunk(
                    data=sub_content,
                    line_start=chunk.line_start + i,
                    line_end=chunk.line_start + end - 1,
                    kind=f"{chunk.kind}_part",
                    identifier=f"{chunk.identifier}_part{len(sub_chunks) + 1}",
                    imports_section=chunk.imports_section,
                    class_info=chunk.class_info,
                    source_file=chunk.source_file,
                )
            )
            i = end - self.overlap_size
            if i <= 0 or end >= len(lines):
                break
        if sub_chunks:
            return sub_chunks
        return [chunk]

    def _fallback_chunk(self, code_source, file_path):
        all_lines = code_source.splitlines()
        lines_per_subchunk = self.max_chunk_chars_limit // 60
        import_pattern = re.compile(r"^(?:from\s+\S+\s+)?import\s+.+$")
        found_imports = []
        for line in all_lines[:50]:
            if import_pattern.match(line.strip()):
                found_imports.append(line)
        imports_str = "\n".join(found_imports)
        result_chunks = []
        i = 0
        while i < len(all_lines):
            end = min(i + lines_per_subchunk, len(all_lines))
            content = "\n".join(all_lines[i:end])
            result_chunks.append(
                CodeChunk(
                    data=content,
                    line_start=i + 1,
                    line_end=end,
                    kind="block",
                    identifier=f"block_{len(result_chunks) + 1}",
                    imports_section=imports_str,
                    class_info=None,
                    source_file=file_path,
                )
            )
            i = end - self.overlap_size
            if i <= 0:
                break
        return (
            result_chunks
            if result_chunks
            else [
                CodeChunk(
                    data=code_source,
                    line_start=1,
                    line_end=len(all_lines),
                    kind="module",
                    identifier="module",
                    imports_section=imports_str,
                    class_info=None,
                    source_file=file_path,
                )
            ]
        )


class ContextBuilder:
    def __init__(self, max_context_tokens=8000):
        self.max_context_tokens = max_context_tokens
        self.chunker = ASTChunker(max_chunk_chars_limit=max_context_tokens // 2)

    def chunk_file(self, source, file_path=""):
        return self.chunker.chunk_file(source, file_path)

    def build_analysis_context(
        self, source_or_chunk, file_path=None, defs_map=None, include_imports=True
    ):
        if isinstance(source_or_chunk, CodeChunk):
            return self._build_chunk_context(source_or_chunk, defs_map)

        source = source_or_chunk
        file_path = file_path or ""
        lines = source.splitlines()
        name = "module"
        if file_path:
            name = Path(file_path).stem
        imports = ""
        if include_imports:
            imports = self._extract_imports_str(source)
        chunk = CodeChunk(
            data=source,
            line_start=1,
            line_end=len(lines),
            kind="module",
            identifier=name,
            imports_section=imports,
            class_info=None,
            source_file=file_path,
        )
        return self._build_chunk_context(chunk, defs_map)

    def build_smart_slice(self, full_source, function_name):
        graph = CodeGraph()
        graph.build(full_source)
        sliced = graph.get_slice(function_name)
        if sliced:
            return f"=== CONTEXT SLICE (Focus: {function_name}) ===\n{sliced}"
        return None

    def _extract_imports_str(self, source):
        try:
            tree = ast.parse(source)
            lines = source.splitlines()
            import_lines = []
            for node in ast.walk(tree):
                if isinstance(node, (ast.Import, ast.ImportFrom)):
                    start = node.lineno - 1
                    end = getattr(node, "end_lineno", node.lineno)
                    import_lines.extend(lines[start:end])
            return "\n".join(import_lines)
        except:
            return ""

    def _build_chunk_context(self, chunk, defs_map=None):
        parts = []
        parts.append(f"=== FILE: {chunk.source_file} ===")
        parts.append(
            f"Analyzing: {chunk.kind} '{chunk.identifier}' (lines {chunk.line_start}-{chunk.line_end})"
        )
        if chunk.imports_section:
            parts.append(f"\n[IMPORTS]\n{chunk.imports_section}")
        if chunk.class_info:
            parts.append(f"\n[CLASS CONTEXT]\n{chunk.class_info}")
        if defs_map:
            deps = self._find_dependencies(chunk.data, defs_map, chunk.source_file)
            if deps:
                parts.append(f"\n[EXTERNAL DEPENDENCIES]\n{deps}")
        parts.append(f"\n[CODE]\n{chunk.with_line_numbers()}")
        return "\n".join(parts)

    def build_fix_context(
        self, source, file_path, issue_line, issue_message, defs_map=None
    ):
        lines = source.splitlines()
        chunks = self.chunker.chunk_file(source, file_path)
        target_chunk = None
        for chunk in chunks:
            if chunk.line_start <= issue_line <= chunk.line_end:
                target_chunk = chunk
                break
        if target_chunk:
            context = self.build_analysis_context(target_chunk, defs_map)
        else:
            start = max(0, issue_line - 20)
            end = min(len(lines), issue_line + 20)
            numbered = []
            for i in range(start + 1, end + 1):
                num = str(i).rjust(4)
                numbered.append(num + " | " + lines[i - 1])
            context = "[CODE]\n" + "\n".join(numbered)
        return f"=== FIX CONTEXT ===\n[ISSUE] Line {issue_line}: {issue_message}\n\n{context}"

    def _find_dependencies(self, content, defs_map, current_file):
        used_names = set(re.findall(r"\b([a-zA-Z_][a-zA-Z0-9_]*)\b", content))
        deps = []
        for name, info in defs_map.items():
            if isinstance(info, dict):
                def_name = info.get("name", name)
                def_type = info.get("type", "unknown")
                def_file = str(info.get("file", ""))
            else:
                def_name = getattr(info, "name", name)
                def_type = getattr(info, "type", "unknown")
                def_file = str(getattr(info, "filename", ""))
            if def_name in used_names and def_file:
                source = (
                    "this file" if def_file == current_file else Path(def_file).name
                )
                deps.append(f"  - {def_name} ({def_type}) from {source}")
        return "\n".join(deps[:50])

    def _build_project_index(self, defs_map, max_items=150):
        if not defs_map:
            return ""
        index = []
        for name, info in defs_map.items():
            if isinstance(info, dict):
                def_name = info.get("name", name)
                def_type = info.get("type", "unknown")
                def_file = str(info.get("file", ""))
            else:
                def_name = getattr(info, "name", name)
                def_type = getattr(info, "type", "unknown")
                def_file = str(getattr(info, "filename", ""))
            short_file = Path(def_file).name if def_file else "?"
            index.append(f"  - {def_name} ({def_type}) [{short_file}]")
        if len(index) > max_items:
            index = index[:max_items]
            index.append(f"  ... and {len(defs_map) - max_items} more")
        return "\n".join(index)


