"""
import re
import logging
from difflib import SequenceMatcher
from typing import List, Tuple, Dict, Optional

logger = logging.getLogger(__name__)

# Map Chinese punctuation to English equivalents (token-saving)
ZH_PUNCT_MAP: Dict[str, str] = {
    '\uFF0C': ',', '\u3002': '.', '\uFF1B': ';', '\uFF1A': ':', 
    '\uFF01': '!', '\uFF1F': '?', '\u201C': '"', '\u201D': '"', 
    '\u2018': "'", '\u2019': "'", '\uFF08': '(', '\uFF09': ')', 
    '\u3010': '[', '\u3011': ']', '\u3001': ',', '\u2026': '...', 
    '\u2014\u2014': '--', '\uFF5E': '~',
}
ZH_PUNCT_PATTERN = re.compile('|'.join(re.escape(key) for key in ZH_PUNCT_MAP))

# Emoji pattern (covers emoticons, symbols, pictographs, flags, etc.)
EMOJI_PATTERN = re.compile(
    '[\U0001F600-\U0001F64F'   # emoticons
    '\U0001F300-\U0001F5FF'    # symbols & pictographs
    '\U0001F680-\U0001F6FF'    # transport & map
    '\U0001F1E0-\U0001F1FF'    # flags
    '\U00002702-\U000027B0'    # dingbats
    '\U0001F900-\U0001F9FF'    # supplemental symbols
    '\U0001FA00-\U0001FA6F'    # chess symbols
    '\U0001FA70-\U0001FAFF'    # symbols extended-A
    '\U00002600-\U000026FF'    # misc symbols
    ']+', re.UNICODE
)

# Markdown header regex
HEADER_PATTERN = re.compile(r'^(#{1,6})\s+(.*)', re.MULTILINE)
# Table separator line pattern
TABLE_SEPARATOR_PATTERN = re.compile(r'^[\s|:\-]+$')


def extract_sections(content: str) -> List[Tuple[str, str, int]]:
    """Parse *content* into sections based on markdown headers.
    Returns a list of (header_text, body_text, depth) tuples.
    Text before the first header is returned with header=''.
    """
    if not content:
        return []

    section_list: List[Tuple[str, str, int]] = []
    lines = content.split('\n')
    current_header = ''
    current_depth = 0
    current_body_lines: List[str] = []

    for line in lines:
        match = HEADER_PATTERN.match(line)
        if match:
            # Save previous section
            body_text = '\n'.join(current_body_lines).strip()
            if current_header or body_text:
                section_list.append((current_header, body_text, current_depth))

            current_header = match.group(2).strip()
            current_depth = len(match.group(1))
            current_body_lines = []
        else:
            current_body_lines.append(line)

    # Final section
    final_body = '\n'.join(current_body_lines).strip()
    if current_header or final_body:
        section_list.append((current_header, final_body, current_depth))

    return section_list


def clean_whitespace(text: str) -> str:
    """Normalize excessive blank lines and remove trailing spaces."""
    if not text:
        return ""

    # Reduce 3+ consecutive newlines to 2
    text = re.sub(r'\n{3,}', '\n\n', text)
    # Remove trailing whitespace per line
    cleaned_lines = [line.rstrip() for line in text.split('\n')]
    return '\n'.join(cleaned_lines).strip()


def deduplicate_lines(text: str) -> str:
    """Remove exact duplicate non-empty lines while preserving order."""
    if not text:
        return ""

    seen = set()
    output_lines = []

    for line in text.split('\n'):
        stripped = line.strip()
        if not stripped:
            output_lines.append(line)
            continue
        if stripped in seen:
            continue
        seen.add(stripped)
        output_lines.append(line)

    return '\n'.join(output_lines)


def convert_chinese_punctuation(text: str) -> str:
    """Substitute Chinese full-width punctuation with ASCII equivalents."""
    if not text:
        return ""

    # Handle double em-dash first
    text = text.replace('\u2014\u2014', '--')
    return ZH_PUNCT_PATTERN.sub(lambda m: ZH_PUNCT_MAP.get(m.group(), m.group()), text)


def eliminate_emoji(text: str) -> str:
    """Strip emoji characters from *text*."""
    if not text:
        return ""

    result = EMOJI_PATTERN.sub('', text)
    # Clean up extra spaces created by emoji removal
    result = re.sub(r'  +', ' ', result)
    return result


def filter_empty_headers(text: str) -> str:
    """Eliminate markdown sections that lack meaningful content."""
    if not text:
        return ""

    sections = extract_sections(text)
    if not sections:
        return text

    # Determine which sections have nested child sections
    has_child = [False] * len(sections)
    for idx, (header, body, level) in enumerate(sections):
        if level > 0:
            for parent_idx in range(idx - 1, -1, -1):
                _, _, parent_level = sections[parent_idx]
                if parent_level > 0 and parent_level < level:
                    has_child[parent_idx] = True
                    break

    output_lines: List[str] = []
    for idx, (header, body, level) in enumerate(sections):
        if not header and not body:
            continue
        if header and not body.strip() and not has_child[idx]:
            continue

        if header:
            output_lines.append('#' * level + ' ' + header)
        if body.strip():
            output_lines.append(body)
        output_lines.append('')  # Blank line between sections

    return '\n'.join(output_lines).strip()


def condense_markdown_tables(text: str) -> str:
    """Transform markdown tables into compact key:value format.
    Two-column tables become ``Key: Value`` lines.
    Wider tables use column headers as labels.
    """
    if not text:
        return ""

    lines = text.split('\n')
    processed_lines: List[str] = []
    index = 0

    while index < len(lines):
        current_line = lines[index]

        # Detect table: line with | followed by separator line
        if '|' in current_line and index + 1 < len(lines) and TABLE_SEPARATOR_PATTERN.match(lines[index + 1].strip()):
            # Extract header row
            header_cells = [cell.strip() for cell in current_line.strip().strip('|').split('|')]
            index += 2  # Skip header and separator

            data_rows: List[List[str]] = []
            while index < len(lines) and '|' in lines[index] and lines[index].strip():
                row_cells = [cell.strip() for cell in lines[index].strip().strip('|').split('|')]
                data_rows.append(row_cells)
                index += 1

            if len(header_cells) >= 5:
                # Wide tables: preserve structure without header/separator
                for row in data_rows:
                    processed_lines.append('| ' + ' | '.join(row) + ' |')
            elif len(header_cells) == 2:
                # Two-column: convert to key: value format
                for row in data_rows:
                    key = row[0] if len(row) > 0 else ''
                    value = row[1] if len(row) > 1 else ''
                    if key or value:
                        processed_lines.append(f"- {key}: {value}")
            else:
                # Multi-column: use headers as labels
                for row in data_rows:
                    parts = []
                    for col_index, cell in enumerate(row):
                        if col_index == 0:
                            parts.append(cell)
                        elif col_index < len(header_cells):
                            parts.append(f"{header_cells[col_index]}={cell}")
                        else:
                            parts.append(cell)
                    processed_lines.append(', '.join(parts))
        else:
            processed_lines.append(current_line)
            index += 1

    return '\n'.join(processed_lines)


def consolidate_similar_bullets(text: str, similarity_threshold: float = 0.80) -> str:
    """Merge bullet points with high textual similarity.
    Uses SequenceMatcher ratio; when two bullets exceed *similarity_threshold*,
    retain only the longer version.
    """
    if not text:
        return ""

    lines = text.split('\n')
    bullet_pattern = re.compile(r'^(\s*[-*+]\s+)(.*)')
    output_lines: List[str] = []
    bullet_items: List[Tuple[str, str, str]] = []  # (prefix, content, original_line)

    def process_bullet_group():
        if not bullet_items:
            return

        preserved = list(bullet_items)
        discard_flags: List[bool] = [False] * len(preserved)

        for i in range(len(preserved)):
            if discard_flags[i]:
                continue
            for j in range(i + 1, len(preserved)):
                if discard_flags[j]:
                    continue
                similarity = SequenceMatcher(None, preserved[i][1], preserved[j][1]).ratio()
                if similarity >= similarity_threshold:
                    # Keep the longer one
                    if len(preserved[j][1]) > len(preserved[i][1]):
                        discard_flags[i] = True
                        break
                    else:
                        discard_flags[j] = True

        for idx, (prefix, content, original_line) in enumerate(preserved):
            if not discard_flags[idx]:
                output_lines.append(original_line)

        bullet_items.clear()

    for line in lines:
        match = bullet_pattern.match(line)
        if match:
            bullet_items.append((match.group(1), match.group(2), line))
        else:
            process_bullet_group()
            output_lines.append(line)

    process_bullet_group()
    return '\n'.join(output_lines)


def combine_short_bullets(text: str, word_limit: int = 3, max_consecutive: int = 10) -> str:
    """Join consecutive short bullet points into comma-separated form.
    Bullets with <= *word_limit* words are candidates. Up to *max_consecutive*
    short bullets are merged into one line.
    """
    if not text:
        return ""

    bullet_pattern = re.compile(r'^(\s*[-*+]\s+)(.*)')
    lines = text.split('\n')
    output_lines: List[str] = []
    short_items: List[str] = []
    bullet_prefix = '- '

    def finalize_short_items():
        nonlocal bullet_prefix
        if not short_items:
            return

        if len(short_items) <= 2:
            for item in short_items:
                output_lines.append(bullet_prefix + item)
        else:
            # Merge into single line
            output_lines.append(bullet_prefix + ', '.join(short_items))

        short_items.clear()

    for line in lines:
        match = bullet_pattern.match(line)
        if match:
            content = match.group(2).strip()
            bullet_prefix = match.group(1)
            if len(content.split()) <= word_limit:
                short_items.append(content)
                if len(short_items) >= max_consecutive:
                    finalize_short_items()
            else:
                finalize_short_items()
                output_lines.append(line)
        else:
            finalize_short_items()
            output_lines.append(line)

    finalize_short_items()
    return '\n'.join(output_lines)

