def _parse_json_safely(raw_response):
    if not raw_response:
        return {}
    try:
        return json.loads(raw_response)
    except json.JSONDecodeError:
        return {"raw_content": raw_response}

def _send_request(http_method, endpoint, request_headers, payload_data, request_timeout):
    encoded_payload = json.dumps(payload_data).encode("utf-8") if payload_data is not None else None
    request_obj = urllib.request.Request(
        url=f"{API_BASE}{endpoint}",
        data=encoded_payload,
        headers=request_headers,
        method=http_method,
    )
    try:
        with urllib.request.urlopen(request_obj, timeout=request_timeout) as response:
            return response.getcode(), _parse_json_safely(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        body_text = error.read().decode("utf-8") if error.fp else ""
        return error.code, _parse_json_safely(body_text)
    except urllib.error.URLError as error:
        return 0, {"error": f"network_issue: {error}"}

def _read_json_from_file(file_path):
    try:
        with open(file_path, "r", encoding="utf-8") as file:
            return json.load(file)
    except FileNotFoundError:
        raise ValueError(f"File missing: {file_path}") from None
    except json.JSONDecodeError as error:
        raise ValueError(f"Malformed JSON in {file_path}: {error}") from None

def _prepare_headers(auth_type, api_token=None):
    headers = {"Content-Type": "application/json"}
    token = api_token or os.getenv("DIEVIO_API_KEY")
    if not token:
        raise ValueError("API key required. Provide via --api-key or DIEVIO_API_KEY.")
    if auth_type == "x-api-key":
        headers["X-API-Key"] = token
    else:
        headers["Authorization"] = f"Bearer {token}"
    return headers

def _adjust_pagination(request_body, current_page=None, items_per_page=None, result_limit=None):
    result = dict(request_body)
    if current_page is not None:
        result["_page"] = current_page
    if items_per_page is not None:
        result["_per_page"] = items_per_page
    if result_limit is not None:
        result["max_results"] = result_limit
    return result

def _create_summary(input_data):
    if not isinstance(input_data, dict):
        return input_data
    condensed = {}
    preserved_fields = [
        "success",
        "message",
        "count",
        "preview_count",
        "total_count",
        "page",
        "per_page",
        "total_pages",
        "has_more",
        "next_page",
        "max_results",
        "search_id",
        "counting",
        "error",
    ]
    for field in preserved_fields:
        if field in input_data:
            condensed[field] = input_data[field]
    if "preview_data" in input_data and isinstance(input_data["preview_data"], list):
        condensed["preview_rows"] = len(input_data["preview_data"])
    if "data" in input_data and isinstance(input_data["data"], list):
        condensed["result_rows"] = len(input_data["data"])
    return condensed if condensed else input_data

def _output_result(status_code, response_data, full_output=False):
    payload = response_data if full_output else _create_summary(response_data)
    print(json.dumps({"http_status": status_code, "response": payload}, indent=2, ensure_ascii=True))

def _handle_pagination(endpoint, initial_payload, request_headers, request_timeout, max_iterations, delay_seconds):
    current_page = int(initial_payload.get("_page", 1))
    combined_results = []
    page_records = []
    pages_retrieved = 0

    while True:
        page_payload = dict(initial_payload)
        page_payload["_page"] = current_page
        status_code, page_data = _send_request("POST", endpoint, request_headers, page_payload, request_timeout)
        page_records.append({"page_number": current_page, "status_code": status_code, "data": page_data})
        pages_retrieved += 1

        if status_code >= 400 or status_code == 0:
            return status_code, {
                "success": False,
                "error": "pagination_failed",
                "failed_page": current_page,
                "pages_collected": pages_retrieved,
                "pages": page_records,
            }

        batch_items = page_data.get("preview_data")
        if batch_items is None:
            batch_items = page_data.get("data", [])
        if isinstance(batch_items, list):
            combined_results.extend(batch_items)

        continue_fetching = bool(page_data.get("has_more"))
        next_page_num = page_data.get("next_page")
        if not continue_fetching or next_page_num in (None, 0):
            break
        if max_iterations and pages_retrieved >= max_iterations:
            break
        current_page = int(next_page_num)
        if delay_seconds > 0:
            time.sleep(delay_seconds)

    return 200, {
        "success": True,
        "pages_fetched": pages_retrieved,
        "total_rows": len(combined_results),
        "aggregated_results": combined_results,
        "final_page_data": page_records[-1]["data"] if page_records else {},
    }

def execute_search(args):
    request_body = _read_json_from_file(args.body_file) if args.body_file else {}
    request_body = _adjust_pagination(request_body, args.page, args.per_page, args.max_results)
    headers = _prepare_headers(args.auth_mode, api_key=args.api_key)

    if args.auto_paginate:
        status, result = _handle_pagination(
            SEARCH_ENDPOINT,
            request_body,
            headers,
            args.timeout,
            args.max_pages,
            args.sleep_seconds,
        )
    else:
        status, result = _send_request("POST", SEARCH_ENDPOINT, headers, request_body, args.timeout)

    _output_result(status, result, full_output=args.raw_output)
    return 0 if status and status < 400 else 1

def execute_linkedin_lookup(args):
    if args.body_file:
        request_body = _read_json_from_file(args.body_file)
    else:
        if not args.linkedin_url:
            raise ValueError("Either --body-file or at least one --linkedin-url must be provided.")
        request_body = {
            "linkedinUrls": args.linkedin_url,
            "includeWorkEmails": args.include_work_emails,
            "includePersonalEmails": args.include_personal_emails,
            "onlyWithEmails": args.only_with_emails,
            "includePhones": args.include_phones,
        }

    request_body = _adjust_pagination(request_body, args.page, args.per_page, args.max_results)
    headers = _prepare_headers(args.auth_mode, api_key=args.api_key)

    if args.auto_paginate:
        status, result = _handle_pagination(
            LINKEDIN_ENDPOINT,
            request_body,
            headers,
            args.timeout,
            args.max_pages,
            args.sleep_seconds,
        )
    else:
        status, result = _send_request("POST", LINKEDIN_ENDPOINT, headers, request_body, args.timeout)

    _output_result(status, result, full_output=args.raw_output)
    return 0 if status and status < 400 else 1

def create_argument_parser():
    parser = argparse.ArgumentParser(
        description="Dievio API client for searching leads and retrieving LinkedIn profiles."
    )
    subparsers = parser.add_subparsers(dest="action", required=True)

    # Search command setup
    search_parser = subparsers.add_parser("search", help="Execute POST /api/public/search.")
    search_parser.add_argument("--body-file", help="Path to JSON file containing request body.")
    search_parser.add_argument("--api-key", help="Override DIEVIO_API_KEY environment variable.")
    search_parser.add_argument(
        "--auth-mode",
        choices=["bearer", "x-api-key"],
        default="bearer",
        help="Authentication method for API requests.",
    )
    search_parser.add_argument("--page", type=int, help="Override default page number.")
    search_parser.add_argument("--per-page", type=int, help="Override items per page.")
    search_parser.add_argument("--max-results", type=int, help="Override maximum results limit.")
    search_parser.add_argument("--auto-paginate", action="store_true", help="Automatically fetch all pages using has_more.")
    search_parser.add_argument("--max-pages", type=int, default=0, help="Maximum number of pages to fetch (0 means unlimited).")
    search_parser.add_argument("--sleep-seconds", type=float, default=0.0, help="Wait time between pagination requests.")
    search_parser.add_argument("--timeout", type=int, default=60, help="Request timeout in seconds.")
    search_parser.add_argument(
        "--raw-output",
        action="store_true",
        help="Output complete API response (may contain sensitive information).",
    )
    search_parser.set_defaults(func=execute_search)

    # LinkedIn lookup command setup
    linkedin_parser = subparsers.add_parser("linkedin-lookup", help="Execute POST /api/linkedin/lookup.")
    linkedin_parser.add_argument("--body-file", help="Path to JSON file containing request body.")
    linkedin_parser.add_argument("--linkedin-url", action="append", help="LinkedIn profile URL (can be specified multiple times).")
    linkedin_parser.add_argument(
        "--include-work-emails",
        action=argparse.BooleanOptionalAction,
        default=True,
    )
    linkedin_parser.add_argument(
        "--include-personal-emails",
        action=argparse.BooleanOptionalAction,
        default=True,
    )
    linkedin_parser.add_argument(
        "--only-with-emails",
        action=argparse.BooleanOptionalAction,
        default=True,
    )
    linkedin_parser.add_argument(
        "--include-phones",
        action=argparse.BooleanOptionalAction,
        default=False,
    )
    linkedin_parser.add_argument("--api-key", help="Override DIEVIO_API_KEY environment variable.")
    linkedin_parser.add_argument(
        "--auth-mode",
        choices=["bearer", "x-api-key"],
        default="bearer",
        help="Authentication mode for API calls.",
    )
    linkedin_parser.add_argument("--page", type=int, help="Override page number.")
    linkedin_parser.add_argument("--per-page", type=int, help="Override items per page.")
    linkedin_parser.add_argument("--max-results", type=int, help="Override maximum results.")
    linkedin_parser.add_argument("--auto-paginate", action="store_true", help="Enable automatic pagination.")
    linkedin_parser.add_argument("--max-pages", type=int, default=0, help="Limit number of pages during auto-paginate.")
    linkedin_parser.add_argument("--sleep-seconds", type=float, default=0.0, help="Delay between requests.")
    linkedin_parser.add_argument("--timeout", type=int, default=60, help="HTTP timeout duration.")
    linkedin_parser.add_argument(
        "--raw-output",
        action="store_true",
        help="Print full API response (contains PII).",
    )
    linkedin_parser.set_defaults(func=execute_linkedin_lookup)

    return parser

def main_entry_point():
    parser = create_argument_parser()
    arguments = parser.parse_args()
    try:
        return arguments.func(arguments)
    except ValueError as exception:
        print(str(exception), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main_entry_point())

