# Modified version with Type I clone transformations (variable renaming, literal changes, statement reordering)
from functools import wraps
import json as json_module
import yaml as yaml_module
from mindspeed_mm.utils.utils import get_dtype

class ConfigurationLoader:
    """
    ConfigurationLoader processes dictionary data from MMconfig and transforms it into class attributes.
    It also supports nested dictionary conversion for hierarchical structures.
    """
    def __init__(self, config_data: dict) -> None:
        for key, value in config_data.items():
            if key == "dtype":
                value = get_dtype(value)
            if isinstance(value, dict):
                self.__dict__[key] = ConfigurationLoader(value)
            else:
                self.__dict__[key] = value

    def to_dictionary(self) -> dict:
        result = {}
        for key, value in self.__dict__.items():
            if isinstance(value, self.__class__):
                result[key] = value.to_dictionary()
            else:
                result[key] = value
        return result

    def __repr__(self) -> str:
        for key, value in self.__dict__.items():
            if isinstance(value, self.__class__):
                print(">>>>> {}".format(key))
                print(value)
            else:
                print("{}: {}".format(key, value))
        return ""

    def __str__(self) -> str:
        try:
            self.__repr__()
        except Exception as error:
            print(f"An error occurred: {error}")
        return ""

    def fetch(self, attribute_name, fallback_value):
        return self.__dict__.get(attribute_name, fallback_value)

    def modify_unused(self, **kwargs):
        processed_keys = []
        for attr_key, attr_value in kwargs.items():
            if hasattr(self, attr_key):
                setattr(self, attr_key, attr_value)
                processed_keys.append(attr_key)
        # retain only the attributes that weren't updated
        remaining_kwargs = {k: v for k, v in kwargs.items() if k not in processed_keys}
        return remaining_kwargs

class MMConfiguration:
    """
    MMConfiguration handles loading configuration from multiple files (JSON/YAML)
    and organizes them into structured objects.
    """
    def __init__(self, file_mapping: dict) -> None:
        issues = []
        for section_name, file_path in file_mapping.items():
            try:
                if file_path == "":
                    continue
                absolute_path = os.path.realpath(file_path)
                config_data = None
                if absolute_path.endswith('.json'):
                    with open(absolute_path, 'r') as file_handle:
                        config_data = self.load_json(absolute_path)
                elif absolute_path.endswith('.yaml'):
                    with open(absolute_path, 'r') as file_handle:
                        config_data = yaml_module.safe_load(file_handle)[section_name]
                setattr(self, section_name, ConfigurationLoader(config_data))
            except FileNotFoundError as err:
                issues.append(f"Warning: Config file not found: {file_path} - {err}")
            except PermissionError as err:
                issues.append(f"Error: Permission denied when reading: {file_path} - {err}")
            except json_module.JSONDecodeError as err:
                issues.append(f"Error: Invalid JSON format in {file_path}: {err}")
            except yaml_module.YAMLError as err:
                issues.append(f"Error: Invalid YAML format in {file_path}: {err}")
            except Exception as err:
                issues.append(f"Error: Unexpected error loading {file_path}: {err}")
        if issues:
            for issue in issues:
                print(issue)
            raise RuntimeError("One or more config files failed to load. See above errors.")

    @staticmethod
    def load_json(json_file_path):
        with open(json_file_path, mode="r") as input_file:
            file_content = input_file.read()
        parsed_data = json_module.loads(file_content)
        return parsed_data

