def merge_mm_args_decorator(original_function):
    invocation_flag = False
    @wraps(original_function)
    def decorated(args):
        original_function(args)
        nonlocal invocation_flag
        if not invocation_flag:
            args_security_checker(args)
            invocation_flag = True
    return decorated

@merge_mm_args_decorator
def merge_mm_args(args):
    if not hasattr(args, "mm"):
        setattr(args, "mm", object())
        config_files = {"model": args.mm_model, "data": args.mm_data, "tool": args.mm_tool}
        args.mm = MMConfiguration(config_files)

def args_security_checker(args):
    """
    Validate security of all file path parameters across three repositories:
    mindspeed-mm, mindspeed, megatron
    and three configuration files: mm_data.json, mm_model.json, mm_tool.json
    """
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "validate_params.json"), 'r') as validation_file:
            validation_config = json_module.load(validation_file)
    except OSError:
        print("WARNING: validate_params.json cannot be opened")

    # Check args from mindspeed_mm
    if "mindspeed_mm" in validation_config:
        msmm_params = validation_config["mindspeed_mm"]["params"]
        for param in msmm_params:
            if hasattr(args, param) and getattr(args, param):
                path_validator(getattr(args, param), param)

    # Check args from mindspeed
    if "mindspeed" in validation_config:
        ms_params = validation_config["mindspeed"]["params"]
        for param in ms_params:
            if hasattr(args, param) and getattr(args, param):
                path_validator(getattr(args, param), param)

    # Check args from megatron
    if "megatron" in validation_config:
        megatron_params = validation_config["megatron"][0]["params"]
        for param in megatron_params:
            if hasattr(args, param) and getattr(args, param):
                path_validator(getattr(args, param), param)

        # Handle special megatron parameters with multiple paths
        megatron_special_params = validation_config["megatron"][1]["params"]
        for param in megatron_special_params:
            if hasattr(args, param) and getattr(args, param):
                path_list = parse_special_megatron_param(param)
                for single_path in path_list:
                    path_validator(single_path, param)

    # Check args from MM_Model
    if "mm_model" in validation_config:
        mm_model_params = validation_config["mm_model"]["params"]
        if hasattr(args.mm, "model"):
            for param in mm_model_params:
                values = extract_ConfigurationLoader_values(args.mm.model, param)
                for val in values:
                    if val:
                        path_validator(val, param)

    # Check args from MM_Data
    if "mm_data" in validation_config:
        mm_data_params = validation_config["mm_data"]["params"]
        if hasattr(args.mm, "data"):
            for param in mm_data_params:
                values = extract_ConfigurationLoader_values(args.mm.data, param)
                for val in values:
                    if val:
                        path_validator(val, param)

    # Check args from MM_Tool
    if "mm_tool" in validation_config:
        mm_tool_params = validation_config["mm_tool"]["params"]
        if hasattr(args.mm, "tool"):
            for param in mm_tool_params:
                values = extract_ConfigurationLoader_values(args.mm.tool, param)
                for val in values:
                    if val:
                        path_validator(val, param)

def path_validator(file_path, parameter_name, root_directory=None):
    """
    Perform symbolic link and path traversal checks on file paths
    """
    if not root_directory:
        root_directory = os.getcwd()

    # Verify file existence
    try:
        if not os.path.exists(file_path):
            return False
    except OSError:
        return False

    # Check for symbolic links
    from mindspeed_mm.utils.security_utils.validate_path import normalize_path
    try:
        normalized, is_symlink = normalize_path(file_path)
        if is_symlink:
            print(
                "WARNING: [{}] {} is a symbolic link. Its normalized path is {}".format(parameter_name, file_path,
                                                                                       normalized))
            return False
    except OSError:
        return False

    # Check for path traversal
    try:
        absolute_normalized = os.path.realpath(file_path)
        absolute_root = os.path.abspath(root_directory)
        if not absolute_normalized.startswith(absolute_root):
            print("WARNING: [{}] {} attempts to traverse to an unauthorized directory".format(parameter_name, file_path))
            return False
    except OSError:
        return False

    return True

def parse_special_megatron_param(param_string):
    """
    Parse special megatron parameters that may contain multiple values, e.g., data_path, train_data_path
    """
    def is_numeric(s):
        if isinstance(s, str):
            s = s.strip()
        try:
            float(s)
            return True
        except (ValueError, TypeError):
            return False

    parts = param_string.split(" ")
    if len(parts) == 1:
        return parts
    else:
        if is_numeric(parts[0]):
            return [parts[2 * i] for i in range(len(parts) // 2)]
        else:
            return parts

def extract_ConfigurationLoader_values(config_obj, param_path):
    objects_list = [config_obj.to_dictionary()]
    for segment in param_path.split("."):
        new_objects = []
        for obj in objects_list:
            if not obj:
                continue
            if segment in obj:
                if not obj[segment]:
                    continue
                if isinstance(obj[segment], list):
                    new_objects.extend(obj[segment])
                else:
                    new_objects.append(obj[segment])
        if new_objects:
            objects_list = new_objects
        else:
            return []
    return objects_list

# File model definition with preview-based and legacy description rendering
from datetime import datetime
from typing import Any, Dict, Optional
from sqlalchemy import Column, Integer, String, DateTime, ForeignKey, UUID, JSON
from .base import BaseSchema
from sqlalchemy.orm import relationship
from app.models.report_file_association import report_file_association

class File(BaseSchema):
    __tablename__ = "files"
    filename = Column(String, index=True)
    file_location = Column(String, index=True)
    mime_type = Column(String, index=True)

    # Raw preview data (no LLM) - stores sheet names, raw cells, text preview, etc.
    preview_data = Column(JSON, nullable=True)
    owner_id = Column(String(36), ForeignKey("users.id"), nullable=False)
    owner = relationship("User", back_populates="files")
    org_id = Column(String(36), ForeignKey("organizations.id"), nullable=False)
    organization = relationship("Organization", back_populates="files")
    associated_reports = relationship("Report", secondary=report_file_association, back_populates="files")
    tag_mappings = relationship("FileTag", back_populates="file", lazy="selectin")
    schema_definitions = relationship("SheetSchema", back_populates="file", lazy="selectin")

    def get_legacy_description(self):
        """Legacy method - returns description for backward compatibility."""
        return self.description

    @property
    def description(self) -> str:
        """
        Render file description for LLM/coder context.

        Uses raw preview if available, falls back to legacy schema/tags.
        """
        # Use new preview-based description if preview exists
        if self.preview_data:
            return self._generate_preview_description()

        # Legacy fallback: use schema_definitions or tag_mappings
        return self._generate_legacy_description()

    def _generate_preview_description(self) -> str:
        """Render description from raw preview data."""
        from app.services.file_preview import render_file_description
        return render_file_description(self.preview_data, self.file_location)

    def _generate_legacy_description(self) -> str:
        """Legacy description using LLM-extracted schema/tags (for backward compat)."""
        if self.mime_type == "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":    
            desc = f"Excel File: {self.filename}\nLocation: {self.file_location}\n\nSheet Schemas:\n"
            for schema_def in self.schema_definitions:
                desc += f"Sheet Name: {schema_def.sheet_name}\n"
                desc += f"Sheet index: {schema_def.sheet_index}\n"
                if schema_def.schema:
                    desc += f"Schema: {schema_def.schema}\n"
        elif self.mime_type == "application/vnd.ms-excel":
            desc = f"Excel File: {self.filename}\nLocation: {self.file_location}\n\nSheet Schemas:\n"
            for schema_def in self.schema_definitions:
                desc += f"Sheet Name: {schema_def.sheet_name}\n"
                desc += f"Sheet index: {schema_def.sheet_index}\n"
        elif self.mime_type == "application/pdf":
            desc = f"PDF File: {self.filename}\nLocation: {self.file_location}\n\nFile Tags:\n"
            for tag_map in self.tag_mappings:
                desc += f"{tag_map.key}: {tag_map.value}\n"
        elif self.mime_type in ["text/csv", "application/csv"]:
            desc = f"CSV File: {self.filename}\nLocation: {self.file_location}\n"
        else:
            desc = f"File: {self.filename}\nLocation: {self.file_location}\nType: {self.mime_type}\n"
            for tag_map in self.tag_mappings:
                desc += f"{tag_map.key}: {tag_map.value}\n"

        return desc

