import math

def compute_VLLM_PROMPT_BS_BUCKET_MAX(context):
    return max(1, context['VLLM_PROMPT_BS_BUCKET_MAX'])

def compute_MAX_NUM_BATCHED_TOKENS(context):
    return max(1, context['MAX_NUM_BATCHED_TOKENS'])

def compute_TENSOR_PARALLEL_SIZE(context):
    return max(1, min(8, context['TENSOR_PARALLEL_SIZE']))

def compute_MAX_MODEL_LEN(context):
    return max(1, context['MAX_MODEL_LEN'])

def compute_PT_HPU_ENABLE_LAZY_COLLECTIVES(context):
    return context['TENSOR_PARALLEL_SIZE'] > 1

def compute_VLLM_CONTIGUOUS_PA(context):
    return not context['ENABLE_PREFIX_CACHING']

def compute_VLLM_DEFRAG(context):
    return bool(context['VLLM_CONTIGUOUS_PA'])

def compute_MODEL_MEM_FROM_CONFIG(context):
    return float(context.get('MODEL_MEM_FROM_CONFIG'))

def compute_DEVICE_HPU_MEM(context):
    return context['HPU_MEM'][context['DEVICE_NAME']]

def compute_TOTAL_GPU_MEM(context):
    return context['DEVICE_HPU_MEM'] * context['TENSOR_PARALLEL_SIZE']

def compute_MODEL_MEM_IN_GB(context):
    return (context['MODEL_MEM_FROM_CONFIG'] * context['QUANT_DTYPE'] / context['MODEL_DTYPE']) / (1024 * 1024 * 1024)

def compute_USABLE_MEM(context):
    return ((context['TOTAL_GPU_MEM'] / context['TENSOR_PARALLEL_SIZE']) - context['UNAVAILABLE_MEM_ABS'] -
            (context['MODEL_MEM_IN_GB'] / context['TENSOR_PARALLEL_SIZE']) - context['PROFILER_MEM_OVERHEAD'])

def compute_GPU_MEMORY_UTIL_TEMP(context):
    return (1 - context['GPU_FREE_MEM_TARGET'] / context['USABLE_MEM'])

def compute_GPU_MEM_UTILIZATION(context):
    # If user provided
    if context.get('GPU_MEM_UTILIZATION') is not None:
        return context['GPU_MEM_UTILIZATION']
    return math.floor(context['GPU_MEMORY_UTIL_TEMP'] * 100) / 100

def compute_HEAD_DIM(context):
    if not context['HEAD_DIM'] or math.isnan(context['HEAD_DIM']):
        return context['HIDDEN_SIZE'] / context['NUM_ATTENTION_HEADS']
    else:
        return context['HEAD_DIM']

def compute_KV_CACHE_PER_SEQ(context):
    return (2 * context['MAX_MODEL_LEN'] * context['NUM_HIDDEN_LAYERS'] * compute_HEAD_DIM(context) * context['NUM_KEY_VALUE_HEADS'] *
            context['CACHE_DTYPE_BYTES']) / (1024 * 1024 * 1024)

def compute_EST_MAX_NUM_SEQS(context):
    return max(1,
               context['TENSOR_PARALLEL_SIZE'] * context['USABLE_MEM'] * context['GPU_MEM_UTILIZATION'] / context['KV_CACHE_PER_SEQ'])

def compute_EST_HPU_BLOCKS(context):
    return max(1, context['MAX_MODEL_LEN'] * context['EST_MAX_NUM_SEQS'] / context['BLOCK_SIZE'])

def compute_DECODE_BS_RAMP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 1 + math.ceil(math.log(context['EST_MAX_NUM_SEQS'], 2))
    else:
        return 1 + int(math.log(context['VLLM_DECODE_BS_BUCKET_STEP'] / context['VLLM_DECODE_BS_BUCKET_MIN'], 2))

def compute_DECODE_BS_STEP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 0
    else:
        return max(
            0,
            int(1 + (context['EST_MAX_NUM_SEQS'] - context['VLLM_DECODE_BS_BUCKET_STEP']) / context['VLLM_DECODE_BS_BUCKET_STEP']))

def compute_DECODE_BLOCK_RAMP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 1 + math.ceil(math.log(context['EST_HPU_BLOCKS'], 2))
    else:
        return 1 + int(math.log(context['VLLM_DECODE_BLOCK_BUCKET_STEP'] / context['VLLM_DECODE_BLOCK_BUCKET_MIN'], 2))

def compute_DECODE_BLOCK_STEP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 0
    else:
        return max(
            0,
            int(1 +
                (context['EST_HPU_BLOCKS'] - context['VLLM_DECODE_BLOCK_BUCKET_STEP']) / context['VLLM_DECODE_BLOCK_BUCKET_STEP']))

def compute_NUM_DECODE_GRAPHS(context):
    # 3d update
    decode_graphs = ((context['DECODE_BS_RAMP_GRAPHS'] + context['DECODE_BS_STEP_GRAPHS']) *
                     (context['DECODE_BLOCK_RAMP_GRAPHS'] + context['DECODE_BLOCK_STEP_GRAPHS']))
    if context['VLLM_CONTIGUOUS_PA']:
        return max(1, decode_graphs)
    else:
        return max(1, decode_graphs / 2)

def compute_PROMPT_BS_RAMP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 1 + math.ceil(math.log(context['VLLM_PROMPT_BS_BUCKET_MAX'], 2))
    else:
        return 1 + int(
            math.log(
                min(context['VLLM_PROMPT_BS_BUCKET_MAX'], context['VLLM_PROMPT_BS_BUCKET_STEP']) /
                context['VLLM_PROMPT_BS_BUCKET_MIN'], 2))

def compute_PROMPT_BS_STEP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 0
    else:
        return max(
            0,
            int(1 + (context['VLLM_PROMPT_BS_BUCKET_MAX'] - context['VLLM_PROMPT_BS_BUCKET_STEP']) /
                context['VLLM_PROMPT_BS_BUCKET_STEP']))

def compute_PROMPT_SEQ_RAMP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 1 + math.ceil(math.log(context['MAX_NUM_BATCHED_TOKENS'], 2))
    else:
        return 1 + int(math.log(context['VLLM_PROMPT_QUERY_BUCKET_STEP'] / context['VLLM_PROMPT_QUERY_BUCKET_MIN'], 2))

def compute_PROMPT_SEQ_STEP_GRAPHS(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        return 0
    else:
        return int(1 +
                   (min(context['MAX_NUM_BATCHED_TOKENS'], context['MAX_MODEL_LEN']) - context['VLLM_PROMPT_QUERY_BUCKET_STEP']) /
                   context['VLLM_PROMPT_QUERY_BUCKET_STEP'])

def compute_EST_NUM_PROMPT_GRAPHS(context):
    prompt_bs_graphs = context['PROMPT_BS_RAMP_GRAPHS'] + context['PROMPT_BS_STEP_GRAPHS']
    prompt_seq_graphs = context['PROMPT_SEQ_RAMP_GRAPHS'] + context['PROMPT_SEQ_STEP_GRAPHS']
    graphs_2d = prompt_bs_graphs * prompt_seq_graphs
    if prompt_bs_graphs > 1:
        graphs_2d = graphs_2d / 2
    ctx_blocks_max = max(1, (context['MAX_MODEL_LEN'] - context['VLLM_PROMPT_QUERY_BUCKET_MIN']) / context['BLOCK_SIZE'])
    ctx_blocks_min = max(1, (context['MAX_MODEL_LEN'] - context['MAX_NUM_BATCHED_TOKENS']) / context['BLOCK_SIZE'])
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        ctx_block_graphs_max = max(1, math.ceil(math.log(ctx_blocks_max, 2)))
        ctx_block_graphs_min = max(1, math.ceil(math.log(ctx_blocks_min, 2)))
    else:
        ctx_block_graphs_max = max(1, ctx_blocks_max / context['VLLM_PROMPT_CTX_BUCKET_STEP'])  # ctx step
        ctx_block_graphs_min = max(1, ctx_blocks_min / context['VLLM_PROMPT_CTX_BUCKET_STEP'])  # ctx step
    graphs_3d = max(1, graphs_2d * (ctx_block_graphs_max + ctx_block_graphs_min) / 2)
    return graphs_3d

def compute_EST_PROMPT_GRAPH_MEM(context):
    if context['VLLM_EXPONENTIAL_BUCKETING']:
        est_prompt_graph_mem = context['EST_NUM_PROMPT_GRAPHS'] * context['APPROX_MEM_PER_GRAPH_MB']
    else:
        # Graph mem is function of context size for prompt
        est_prompt_graph_mem = context['EST_NUM_PROMPT_GRAPHS'] * context['APPROX_MEM_PER_GRAPH_MB'] * pow(
            max(1, context['MAX_MODEL_LEN'] / 4352), 0.8552)
    return est_prompt_graph_mem

def compute_EST_DECODE_GRAPH_MEM(context):
    est_decode_graph_mem = context['NUM_DECODE_GRAPHS'] * context['APPROX_MEM_PER_GRAPH_MB']
    return est_decode_graph_mem

def compute_EST_GRAPH_PROMPT_RATIO(context):
    est_prompt_graph_mem = compute_EST_PROMPT_GRAPH_MEM(context)
    est_decode_graph_mem = compute_EST_DECODE_GRAPH_MEM(context)
    est_graph_prompt_ratio = est_prompt_graph_mem / (est_prompt_graph_mem + est_decode_graph_mem)
    return est_graph_prompt_ratio

def compute_DECODE_GRAPH_TARGET_GB(context):
    return math.ceil(compute_EST_DECODE_GRAPH_MEM(context) / 1024 * 100) / 100

def compute_EST_GRAPH_RESERVE_MEM(context):
    return math.ceil(context['DECODE_GRAPH_TARGET_GB'] / (context['USABLE_MEM'] * context['GPU_MEM_UTILIZATION'] *
                                                      (1 - context['EST_GRAPH_PROMPT_RATIO'])) * 100) / 100

def compute_VLLM_GRAPH_RESERVED_MEM(context):
    return min(max(context['EST_GRAPH_RESERVE_MEM'], 0.01), 0.5)

def compute_KV_CACHE_MEM(context):
    return (context['USABLE_MEM'] * context['GPU_MEM_UTILIZATION'] * (1 - context['VLLM_GRAPH_RESERVED_MEM']))

def compute_MAX_NUM_SEQS(context):
    # If user provided, just clamp to min 1
    if context.get('MAX_NUM_SEQS') is not None:
        return max(1, context['MAX_NUM_SEQS'])
    # Otherwise, calculate
    val = (context['TENSOR_PARALLEL_SIZE'] * context['KV_CACHE_MEM'] / context['KV_CACHE_PER_SEQ'])
    # always round down for plugin as WA
    if val < context['VLLM_DECODE_BS_BUCKET_STEP']:
        val = pow(2, math.floor(math.log(val, 2)))
    else:
        val = max(1, math.floor(val / context['VLLM_DECODE_BS_BUCKET_STEP'])) * context['VLLM_DECODE_BS_BUCKET_STEP']
    # Special limit for Vision-Instruct models
    if context['MODEL'] in ['meta-llama/Llama-3.2-11B-Vision-Instruct', 'meta-llama/Llama-3.2-90B-Vision-Instruct'
                        ] and val > 128:
        print(f"{context['MODEL']} currently does not support max-num-seqs > 128. "
              "Limiting max-num-seqs to 128")
        val = 128
    if val < 1:
        raise ValueError("Not enough memory for kv cache. Increase TENSOR_PARALLEL_SIZE or "
                         "reduce MAX_MODEL_LEN or increase bucket step")
    return val

def compute_VLLM_DECODE_BLOCK_BUCKET_MAX(context):
    return max(128, math.ceil((context['MAX_NUM_SEQS'] * context['MAX_MODEL_LEN']) / 128))

# Map parameter names to calculation functions
PARAM_COMPUTE_FUNCS = {
    "VLLM_PROMPT_BS_BUCKET_MAX": compute_VLLM_PROMPT_BS_BUCKET_MAX,
