# Import necessary modules for handling different distribution types
from pip._internal.distributions.sdist import SourceDistribution
from pip._internal.distributions.wheel import WheelDistribution
from pip._internal.req.req_install import InstallRequirement

def create_distribution_for_requirement(
    requirement: InstallRequirement,
) -> AbstractDistribution:
    """Returns a Distribution object corresponding to the given InstallRequirement"""
    # Editable requirements are always treated as source distributions and use legacy logic
    if requirement.editable:
        return SourceDistribution(requirement)
    # If the requirement is already a wheel, use WheelDistribution
    if requirement.is_wheel:
        return WheelDistribution(requirement)
    # For all other cases, default to SourceDistribution
    return SourceDistribution(requirement)

