@staticmethod
    def display_verse(verse_data):
        """Format a single verse for presentation."""
        if not verse_data:
            return "Verse not found."

        chapter_name = verse_data['surah']['englishName'] 
        chapter_num = verse_data['surah']['number']
        verse_num = verse_data['numberInSurah']
        arabic_text = verse_data['text_ar']
        translation_text = verse_data['text_tr']

        return f"=== {chapter_name} ({chapter_num}:{verse_num}) ===\n\n{arabic_text}\n\n{translation_text}"

    @staticmethod
    def display_chapter(verses):
        """Format a full Chapter."""
        if not verses:
            return "Chapter not found."

        # verses is a list of verse dicts
        first_verse = verses[0]
        # In get_chapter, 'surah' key contains the chapter metadata
        chapter_meta = first_verse['surah']
        chapter_name = chapter_meta.get('englishName', f"Chapter {chapter_meta.get('number')}")
        chapter_num = chapter_meta.get('number')

        output_lines = [f"=== {chapter_name} (Chapter {chapter_num}) ==="]
        for verse in verses:
            output_lines.append(f"\n[{verse['numberInSurah']}] {verse['text_ar']}")
            output_lines.append(verse['text_tr'])

        return "\n".join(output_lines)

    @staticmethod
    def display_search_results(matches, search_term):
        """Format search results."""
        if not matches:
            return f"No results found for '{search_term}'."

        output_parts = [f"Search results for '{search_term}':\n"]
        for verse in matches:
            output_parts.append(QuranFormatter.display_verse(verse))
            output_parts.append("-" * 30)

        return "\n".join(output_parts)

