@polling_bp.route("/api/poll", methods=["POST"])
@require_auth
def api_poll():
    """Initiate an immediate modem data collection cycle.
    Reuses the same collector instance used for automatic polling to ensure consistency.
    Uses _collect_lock to prevent race conditions with concurrent auto-polls.
    """
    _modem_collector = get_modem_collector()
    if not _modem_collector:
        return jsonify({"success": False, "error": "Collector not initialized"}), 500

    current_time = time.time()
    if current_time - get_last_manual_poll() < 10:
        lang = _get_lang()
        t = get_translations(lang)
        return jsonify({"success": False, "error": t.get("refresh_rate_limit", "Rate limited")}), 429

    if not _modem_collector._collect_lock.acquire(timeout=0):
        return jsonify({"success": False, "error": "Poll already in progress"}), 429

    try:
        poll_result = _modem_collector.collect()
        if not poll_result.success:
            return jsonify({"success": False, "error": poll_result.error}), 500

        set_last_manual_poll(time.time())
        # Return analysis data (web state and snapshot already updated by ModemCollector)
        return jsonify({"success": True, "analysis": poll_result.data})

    except Exception as err:
        log.error("Manual poll failed: %s", err)
        return jsonify({"success": False, "error": str(err)}), 500

    finally:
        _modem_collector._collect_lock.release()

@polling_bp.route("/api/collectors/status")
@require_auth
def api_collectors_status():
    """Return health status of all active collectors.
    Includes failure counts, penalties, and scheduled next poll times.
    Useful for diagnostics and monitoring fail-safe behavior.
    """
    _collectors = get_collectors()
    if not _collectors:
        return jsonify([])

    return jsonify([collector.get_status() for collector in _collectors])

