# Calculate period boundaries based on start and end dates with given granularity
def get_time_periods(start_date, end_date, interval_type):
    intervals = []
    if interval_type == "monthly":
        current = start_date.replace(day=1)
        while current < end_date:
            next_period = (current.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            intervals.append((current, min(next_period, end_date), current.strftime("%Y-%m")))
            current = next_period
    else:  # yearly
        current = start_date.replace(month=1, day=1)
        while current < end_date:
            next_period = current.replace(year=current.year + 1)
            intervals.append((current, min(next_period, end_date), str(current.year)))
            current = next_period
    return intervals

# Filter entries by date range
def filter_entries_by_dates(entries, begin_date, finish_date):
    result = []
    for item in entries:
        if not hasattr(item, "date"):
            result.append(item)
            continue
        if begin_date and item.date < begin_date:
            continue
        if finish_date and item.date >= finish_date:
            continue
        result.append(item)
    return result

# Recursively build a tree structure from an account
def build_account_tree(account_node):
    tree_node = {
        "name": account_node.account,
        "totals": {},
        "subaccounts": [],
    }
    for holding in account_node.balance:
        currency = holding.units.currency
        value = float(holding.units.number)
        tree_node["totals"][currency] = tree_node["totals"].get(currency, 0) + value
    for child in sorted(account_node.values(), key=lambda r: r.account):
        subtree = build_account_tree(child)
        if subtree["subaccounts"] or subtree["totals"]:
            tree_node["subaccounts"].append(subtree)
    return tree_node

# Extract a subtree from realization starting at root
def extract_subtree(realization_map, root_key, default_path):
    account = realization_map.get(root_key, default_path)
    if account is None:
        return {"name": default_path, "totals": {}, "subaccounts": []}
    return build_account_tree(account)

# Compute total balance across an entire account tree
def aggregate_tree_balance(realization_map, root_key, default_path):
    account = realization_map.get(root_key, default_path)
    if account is None:
        return {}
    summary = {}
    def traverse(node):
        for holding in node.balance:
            currency = holding.units.currency
            amount = float(holding.units.number)
            summary[currency] = summary.get(currency, 0) + amount
        for child in node.values():
            traverse(child)
    traverse(account)
    return summary

# Convert balance dictionary to target currency using price map
def transform_balances_to_currency(balances, price_data, desired_currency, reference_date=None):
    """Convert a {currency: amount} dict to a single {target_currency: amount} dict."""
    from beancount.core.prices import get_price
    final_total = 0.0
    for currency, amount in balances.items():
        if currency == desired_currency:
            final_total += amount
        else:
            conversion_result = get_price(price_data, (currency, desired_currency), reference_date)
            if conversion_result is None:
                raise click.UsageError(f"No price found for {currency} -> {desired_currency}")
            _, exchange_rate = conversion_result
            final_total += amount * float(exchange_rate)
    return {desired_currency: round(final_total, 2)}

def compute_node_total(tree_node):
    """Sum all balances in a tree (node + descendants)."""
    subtotal = sum(tree_node["totals"].values())
    for child in tree_node["subaccounts"]:
        subtotal += compute_node_total(child)
    return subtotal

def convert_account_tree(tree_node, price_data, target_currency, reference_date=None):
    """Recursively convert all balances in an account tree to target currency."""
    converted_children = [convert_account_tree(child, price_data, target_currency, reference_date) for child in tree_node["subaccounts"]]
    converted_children.sort(key=lambda c: abs(compute_node_total(c)), reverse=True)
    transformed = {
        "name": tree_node["name"],
        "totals": transform_balances_to_currency(tree_node["totals"], price_data, target_currency, reference_date) if tree_node["totals"] else {},
        "subaccounts": converted_children,
    }
    return transformed

