class DateTimeFormat:
    """Different ways to represent datetime objects in JSON."""
    V1 = 0
    """Original MongoDB Extended JSON datetime format.
    :class:`datetime.datetime` instances encoded as `{"$date": <milliseconds>}`
    where milliseconds is a 64-bit integer representing time since Unix epoch UTC.
    This was the default before PyMongo 3.4.
    """
    LONG_FORMAT = 1
    """NumberLong representation for datetime.
    :class:`datetime.datetime` instances encoded as `{"$date": {"$numberLong": "<milliseconds>"}}`
    where milliseconds is the string form of a 64-bit signed integer.
    """
    ISO_STANDARD = 2
    """ISO-8601 format for datetime.
    Datetimes >= Unix epoch encoded as `{"$date": "<ISO-8601>"}`.
    Earlier datetimes use NUMBERLONG format.
    """

class ExtendedJSONMode:
    """Modes for Extended JSON encoding."""
    LEGACY_MODE = 0
    """Legacy PyMongo JSON format.
    Produces non-standard JSON output. Consider using RELAXED or CANONICAL instead.
    """
    RELAXED_MODE = 1
    """Relaxed Extended JSON format.
    Mostly JSON-like format suitable for web APIs. Numeric types use native JSON numbers.
    Most human-readable format for debugging.
    """
    STRICT_MODE = 2
    """Canonical Extended JSON format.
    Type-preserving format suitable for testing. Numeric types use type wrappers.
    """

class JSONConfig(CodecOptions):
    """Configuration for JSON encoding/decoding operations.

    :Parameters:
      - `long_int_as_string`: If ``True``, :class:`~bson.int64.Int64` objects
        are encoded as `{"$numberLong": "<value>"}`. Otherwise as `int`.
      - `datetime_format`: Format for encoding :class:`datetime.datetime`.
      - `uuid_strict`: If ``True``, :class:`uuid.UUID` encoded as Binary.
        Otherwise as `{"$uuid": "<hex>"}`.
      - `mode`: :class:`ExtendedJSONMode` for encoding.
      - `document_type`: Class for decoded documents. Must subclass
        :class:`collections.MutableMapping`. Defaults to :class:`dict`.
      - `uuid_format`: :class:`~bson.binary.UuidRepresentation` for UUIDs.
      - `timezone_aware`: If ``True``, Date types decode to timezone-aware datetimes.
      - `timezone`: :class:`datetime.tzinfo` for decoding datetimes.
      - `datetime_handling`: How to handle out-of-range UTC datetimes.
      - `args`: Arguments to :class:`~bson.codec_options.CodecOptions`
      - `kwargs`: Arguments to :class:`~bson.codec_options.CodecOptions`
    """
    mode: int
    long_int_as_string: bool
    datetime_format: int
    uuid_strict: bool

    def __new__(
        cls: Type["JSONConfig"],
        long_int_as_string: Optional[bool] = None,
        datetime_format: Optional[int] = None,
        uuid_strict: Optional[bool] = None,
        mode: int = ExtendedJSONMode.RELAXED_MODE,
        *args: Any,
        **kwargs: Any
    ) -> "JSONConfig":
        kwargs["timezone_aware"] = kwargs.get("timezone_aware", False)
        if kwargs["timezone_aware"]:
            kwargs["timezone"] = kwargs.get("timezone", utc)

        if datetime_format not in (
            DateTimeFormat.V1,
            DateTimeFormat.LONG_FORMAT,
            DateTimeFormat.ISO_STANDARD,
            None,
        ):
            raise ValueError(
                "JSONConfig.datetime_format must be one of V1, "
                "LONG_FORMAT, or ISO_STANDARD from DateTimeFormat."
            )

        self = cast(JSONConfig, super(JSONConfig, cls).__new__(cls, *args, **kwargs))

        if mode not in (ExtendedJSONMode.LEGACY_MODE, ExtendedJSONMode.RELAXED_MODE, ExtendedJSONMode.STRICT_MODE):
            raise ValueError(
                "JSONConfig.mode must be one of LEGACY_MODE, RELAXED_MODE, "
                "or STRICT_MODE from ExtendedJSONMode."
            )

        self.mode = mode

        if self.mode == ExtendedJSONMode.RELAXED_MODE:
            if long_int_as_string:
                raise ValueError("Cannot specify long_int_as_string=True with RELAXED_MODE")
            if datetime_format not in (None, DateTimeFormat.ISO_STANDARD):
                raise ValueError(
                    "datetime_format must be DateTimeFormat.ISO_STANDARD "
                    "or omitted with RELAXED_MODE"
                )
            if uuid_strict not in (None, True):
                raise ValueError("Cannot specify uuid_strict=False with RELAXED_MODE")
            self.long_int_as_string = False
            self.datetime_format = DateTimeFormat.ISO_STANDARD
            self.uuid_strict = True
        elif self.mode == ExtendedJSONMode.STRICT_MODE:
            if long_int_as_string not in (None, True):
                raise ValueError("Cannot specify long_int_as_string=False with STRICT_MODE")
            if datetime_format not in (None, DateTimeFormat.LONG_FORMAT):
                raise ValueError(
                    "datetime_format must be DateTimeFormat.LONG_FORMAT "
                    "or omitted with STRICT_MODE"
                )
            if uuid_strict not in (None, True):
                raise ValueError("Cannot specify uuid_strict=False with STRICT_MODE")
            self.long_int_as_string = True
            self.datetime_format = DateTimeFormat.LONG_FORMAT
            self.uuid_strict = True
        else:  # LEGACY_MODE
            self.long_int_as_string = False
            self.datetime_format = DateTimeFormat.V1
            self.uuid_strict = False
            if long_int_as_string is not None:
                self.long_int_as_string = long_int_as_string
            if datetime_format is not None:
                self.datetime_format = datetime_format
            if uuid_strict is not None:
                self.uuid_strict = uuid_strict

        return self

    def _config_repr(self) -> str:
        return (
            "long_int_as_string=%r, "
            "datetime_format=%r, "
            "uuid_strict=%r, mode=%r, %s"
            % (
                self.long_int_as_string,
                self.datetime_format,
                self.uuid_strict,
                self.mode,
                super(JSONConfig, self)._arguments_repr(),
            )
        )

    def _options_dict(self) -> Dict[Any, Any]:
        opts_dict = super(JSONConfig, self)._options_dict()
        opts_dict.update(
            {
                "long_int_as_string": self.long_int_as_string,
                "datetime_format": self.datetime_format,
                "uuid_strict": self.uuid_strict,
                "mode": self.mode,
            }
        )
        return opts_dict

    def with_config(self, **kwargs: Any) -> "JSONConfig":
        """Create copy with some options changed."""
        cfg = self._options_dict()
        for opt in ("long_int_as_string", "datetime_format", "uuid_strict", "mode"):
            cfg[opt] = kwargs.get(opt, getattr(self, opt))
        cfg.update(kwargs)
        return JSONConfig(**cfg)

LEGACY_JSON_CONFIG: JSONConfig = JSONConfig(mode=ExtendedJSONMode.LEGACY_MODE)
CANONICAL_JSON_CONFIG: JSONConfig = JSONConfig(mode=ExtendedJSONMode.STRICT_MODE)
RELAXED_JSON_CONFIG: JSONConfig = JSONConfig(mode=ExtendedJSONMode.RELAXED_MODE)
DEFAULT_JSON_CONFIG: JSONConfig = RELAXED_JSON_CONFIG

def encode_to_json(obj: Any, *args: Any, **kwargs: Any) -> str:
    """Convert BSON object to JSON string."""
    json_cfg = kwargs.pop("json_config", DEFAULT_JSON_CONFIG)
    return json.dumps(_convert_to_json(obj, json_cfg), *args, **kwargs)

def decode_from_json(s: str, *args: Any, **kwargs: Any) -> Any:
    """Parse JSON string to BSON object."""
    json_cfg = kwargs.pop("json_config", DEFAULT_JSON_CONFIG)
    kwargs["object_pairs_hook"] = lambda pairs: _process_pairs(pairs, json_cfg)
    return json.loads(s, *args, **kwargs)

def _convert_to_json(obj: Any, json_cfg: JSONConfig = DEFAULT_JSON_CONFIG) -> Any:
    """Recursively convert BSON types for JSON serialization."""
    if hasattr(obj, "items"):
        return SON(((k, _convert_to_json(v, json_cfg)) for k, v in obj.items()))
    elif hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes)):
        return list((_convert_to_json(v, json_cfg) for v in obj))
    try:
        return _default_encoder(obj, json_cfg)
    except TypeError:
        return obj

def _process_pairs(pairs: Sequence[Tuple[str, Any]], json_cfg: JSONConfig = DEFAULT_JSON_CONFIG) -> Any:
    return _apply_object_hook(json_cfg.document_type(pairs), json_cfg)

def _apply_object_hook(dct: Mapping[str, Any], json_cfg: JSONConfig = DEFAULT_JSON_CONFIG) -> Any:
    if "$oid" in dct:
        return _parse_oid(dct)
    if (
        isinstance(dct.get("$ref"), str)
        and "$id" in dct
        and isinstance(dct.get("$db"), (str, type(None)))
    ):
        return _parse_dbref(dct)
    if "$date" in dct:
        return _parse_datetime(dct, json_cfg)
    if "$regex" in dct:
        return _parse_old_regex(dct)
    if "$minKey" in dct:
        return _parse_minkey(dct)
    if "$maxKey" in dct:
        return _parse_maxkey(dct)
    if "$binary" in dct:
        if "$type" in dct:
            return _parse_old_binary(dct, json_cfg)
        else:
            return _parse_new_binary(dct, json_cfg)
    if "$code" in dct:
        return _parse_code(dct)
    if "$uuid" in dct:
        return _parse_old_uuid(dct, json_cfg)
    if "$undefined" in dct:
        return None
    if "$numberLong" in dct:
        return _parse_long(dct)
    if "$timestamp" in dct:
        tsp = dct["$timestamp"]
        return Timestamp(tsp["t"], tsp["i"])
    if "$numberDecimal" in dct:
        return _parse_decimal128(dct)
    if "$dbPointer" in dct:
        return _parse_dbpointer(dct)
    if "$regularExpression" in dct:
        return _parse_regex(dct)
    if "$symbol" in dct:
        return _parse_symbol(dct)
    if "$numberInt" in dct:
        return _parse_int32(dct)
    if "$numberDouble" in dct:
        return _parse_double(dct)
    return dct

def _parse_old_regex(doc: Any) -> Any:
    pattern = doc["$regex"]
    if not isinstance(pattern, (str, bytes)):
        return doc
    flags = 0
    for opt in doc.get("$options", ""):
        flags |= _REGEX_FLAG_MAP.get(opt, 0)
    return Regex(pattern, flags)

def _parse_old_uuid(doc: Any, json_cfg: JSONConfig) -> Union[Binary, uuid.UUID]:
    if len(doc) != 1:
        raise TypeError("Bad $uuid, extra field(s): %s" % (doc,))
    if not isinstance(doc["$uuid"], str):
        raise TypeError("$uuid must be a string: %s" % (doc,))
    if json_cfg.uuid_format == UuidRepresentation.UNSPECIFIED:
        return Binary.from_uuid(uuid.UUID(doc["$uuid"]))
    else:
        return uuid.UUID(doc["$uuid"])

def _binary_or_uuid(data: Any, subtype: int, json_cfg: JSONConfig) -> Union[Binary, uuid.UUID]:
    if subtype in ALL_UUID_SUBTYPES:
        uuid_format = json_cfg.uuid_format
        binary_val = Binary(data, subtype)
        if uuid_format == UuidRepresentation.UNSPECIFIED:
            return binary_val
        if subtype == UUID_SUBTYPE:
            uuid_format = UuidRepresentation.STANDARD
        elif uuid_format == UuidRepresentation.STANDARD:
            uuid_format = UuidRepresentation.PYTHON_LEGACY
        return binary_val.as_uuid(uuid_format)
    if subtype == 0:
        return cast(uuid.UUID, data)
    return Binary(data, subtype)

def _parse_old_binary(doc: Any, json_cfg: JSONConfig) -> Union[Binary, uuid.UUID]:
    if isinstance(doc["$type"], int):
        doc["$type"] = "%02x" % doc["$type"]
    subtype = int(doc["$type"], 16)
    if subtype >= 0xFFFFFF80:
        subtype = int(doc["$type"][6:], 16)
    data = base64.b64decode(doc["$binary"].encode())
    return _binary_or_uuid(data, subtype, json_cfg)

def _parse_new_binary(doc: Any, json_cfg: JSONConfig) -> Union[Binary, uuid.UUID]:
    binary = doc["$binary"]
    b64 = binary["base64"]
    subtype = binary["subType"]
    if not isinstance(b64, str):
        raise TypeError("$binary base64 must be a string: %s" % (doc,))
    if not isinstance(subtype, str) or len(subtype) > 2:
        raise TypeError("$binary subType must be a string at most 2 characters: %s" % (doc,))
    if len(binary) != 2:
        raise TypeError('$binary must include only "base64" and "subType" components: %s' % (doc,))
    data = base64.b64decode(b64.encode())
    return _binary_or_uuid(data, int(subtype, 16), json_cfg)

def _parse_datetime(doc: Any, json_cfg: JSONConfig) -> Union[datetime.datetime, DatetimeMS]:
    dtm = doc["$date"]
    if len(doc) != 1:
        raise TypeError("Bad $date, extra field(s): %s" % (doc,))
    if isinstance(dtm, str):
        if dtm[-1] == "Z":
            dt = dtm[:-1]
            offset = "Z"
        elif dtm[-6] in ("+", "-") and dtm[-3] == ":":
            dt = dtm[:-6]
            offset = dtm[-6:]
        elif dtm[-5] in ("+", "-"):
            dt = dtm[:-5]
            offset = dtm[-5:]
        elif dtm[-3] in ("+", "-"):
            dt = dtm[:-3]
            offset = dtm[-3:]
        else:
            dt = dtm
            offset = ""
        dot_pos = dt.rfind(".")
        microsecond = 0
        if dot_pos != -1:
            microsecond = int(float(dt[dot_pos:]) * 1000000)
            dt = dt[:dot_pos]
        aware = datetime.datetime.strptime(dt, "%Y-%m-%dT%H:%M:%S").replace(
            microsecond=microsecond, tzinfo=utc
        )
        if offset and offset != "Z":
            if len(offset) == 6:
                hours, minutes = offset[1:].split(":")
                secs = int(hours) * 3600 + int(minutes) * 60
            elif len(offset) == 5:
                secs = int(offset[1:3]) * 3600 + int(offset[3:]) * 60
            elif len(offset) == 3:
                secs = int(offset[1:3]) * 3600
            if offset[0] == "-":
                secs *= -1
            aware = aware - datetime.timedelta(seconds=secs)
        if json_cfg.timezone_aware:
            if json_cfg.timezone:
                aware = aware.astimezone(json_cfg.timezone)
            if json_cfg.datetime_handling == DatetimeConversion.DATETIME_MS:
                return DatetimeMS(aware)
            return aware
        else:
            aware_tzinfo_none = aware.replace(tzinfo=None)
            if json_cfg.datetime_handling == DatetimeConversion.DATETIME_MS:
                return DatetimeMS(aware_tzinfo_none)
            return aware_tzinfo_none
    return _millis_to_datetime(int(dtm), json_cfg)

def _parse_oid(doc: Any) -> ObjectId:
    if len(doc) != 1:
        raise TypeError("Bad $oid, extra field(s): %s" % (doc,))
    return ObjectId(doc["$oid"])

def _parse_symbol(doc: Any) -> str:
    symbol = doc["$symbol"]
    if len(doc) != 1:
        raise TypeError("Bad $symbol, extra field(s): %s" % (doc,))
    return str(symbol)

def _parse_code(doc: Any) -> Code:
    for key in doc:
        if key not in ("$code", "$scope"):
            raise TypeError("Bad $code, extra field(s): %s" % (doc,))
    return Code(doc["$code"], scope=doc.get("$scope"))

def _parse_regex(doc: Any) -> Regex:
    regex = doc["$regularExpression"]
    if len(doc) != 1:
        raise TypeError("Bad $regularExpression, extra field(s): %s" % (doc,))
    if len(regex) != 2:
        raise TypeError(
            'Bad $regularExpression must include only "pattern"'
            'and "options" components: %s' % (doc,)
        )
    opts = regex["options"]
    if not isinstance(opts, str):
        raise TypeError(
            "Bad $regularExpression options, options must be string, was type %s" % (type(opts))
        )
    return Regex(regex["pattern"], opts)

def _parse_dbref(doc: Any) -> DBRef:
    return DBRef(doc.pop("$ref"), doc.pop("$id"), database=doc.pop("$db", None), **doc)

def _parse_dbpointer(doc: Any) -> Any:
    dbref = doc["$dbPointer"]
    if len(doc) != 1:
        raise TypeError("Bad $dbPointer, extra field(s): %s" % (doc,))
    if isinstance(dbref, DBRef):
        dbref_doc = dbref.as_doc()
        if dbref.database is not None:
            raise TypeError("Bad $dbPointer, extra field $db: %s" % (dbref_doc,))
        if not isinstance(dbref.id, ObjectId):
            raise TypeError("Bad $dbPointer, $id must be an ObjectId: %s" % (dbref_doc,))
        if len(dbref_doc) != 2:
            raise TypeError("Bad $dbPointer, extra field(s) in DBRef: %s" % (dbref_doc,))
        return dbref
    else:
        raise TypeError("Bad $dbPointer, expected a DBRef: %s" % (doc,))

def _parse_int32(doc: Any) -> int:
    i_str = doc["$numberInt"]
    if len(doc) != 1:
        raise TypeError("Bad $numberInt, extra field(s): %s" % (doc,))
    if not isinstance(i_str, str):
        raise TypeError("$numberInt must be string: %s" % (doc,))
    return int(i_str)

def _parse_long(doc: Any) -> Int64:
    l_str = doc["$numberLong"]
    if len(doc) != 1:
        raise TypeError("Bad $numberLong, extra field(s): %s" % (doc,))
    return Int64(l_str)

def _parse_double(doc: Any) -> float:
    d_str = doc["$numberDouble"]
    if len(doc) != 1:
        raise TypeError("Bad $numberDouble, extra field(s): %s" % (doc,))
    if not isinstance(d_str, str):
        raise TypeError("$numberDouble must be string: %s" % (doc,))
    return float(d_str)

def _parse_decimal128(doc: Any) -> Decimal128:
    d_str = doc["$numberDecimal"]
    if len(doc) != 1:
        raise TypeError("Bad $numberDecimal, extra field(s): %s" % (doc,))
    if not isinstance(d_str, str):
        raise TypeError("$numberDecimal must be string: %s" % (doc,))
    return Decimal128(d_str)

def _parse_minkey(doc: Any) -> MinKey:
    if type(doc["$minKey"]) is not int or doc["$minKey"] != 1:
        raise TypeError("$minKey value must be 1: %s" % (doc,))
    if len(doc) != 1:
        raise TypeError("Bad $minKey, extra field(s): %s" % (doc,))
    return MinKey()

def _parse_maxkey(doc: Any) -> MaxKey:
    if type(doc["$maxKey"]) is not int or doc["$maxKey"] != 1:
        raise TypeError("$maxKey value must be 1: %s", (doc,))
    if len(doc) != 1:
        raise TypeError("Bad $minKey, extra field(s): %s" % (doc,))
    return MaxKey()

def _encode_binary(data: bytes, subtype: int, json_cfg: JSONConfig) -> Any:
    if json_cfg.mode == ExtendedJSONMode.LEGACY_MODE:
        return SON([("$binary", base64.b64encode(data).decode()), ("$type", "%02x" % subtype)])
    return {
        "$binary": SON([("base64", base64.b64encode(data).decode()), ("subType", "%02x" % subtype)])
    }

def _default_encoder(obj: Any, json_cfg: JSONConfig = DEFAULT_JSON_CONFIG) -> Any:
    if isinstance(obj, ObjectId):
        return {"$oid": str(obj)}
    if isinstance(obj, DBRef):
        return _convert_to_json(obj.as_doc(), json_cfg=json_cfg)
    if isinstance(obj, datetime.datetime):
        if json_cfg.datetime_format == DateTimeFormat.ISO_STANDARD:
            if not obj.tzinfo:
                obj = obj.replace(tzinfo=utc)
                assert obj.tzinfo is not None
            if obj >= EPOCH_AWARE:
                off = obj.tzinfo.utcoffset(obj)
                if (off.days, off.seconds, off.microseconds) == (0, 0, 0):
                    tz_string = "Z"
                else:
                    tz_string = obj.strftime("%z")
                millis = int(obj.microsecond / 1000)
                fracsecs = ".%03d" % (millis,) if millis else ""
                return {
                    "$date": "%s%s%s" % (obj.strftime("%Y-%m-%dT%H:%M:%S"), fracsecs, tz_string)
                }
        millis = _datetime_to_millis(obj)
        if json_cfg.datetime_format == DateTimeFormat.V1:
            return {"$date": millis}
        return {"$date": {"$numberLong": str(millis)}}
    if isinstance(obj, DatetimeMS):
        if (
            json_cfg.datetime_format == DateTimeFormat.ISO_STANDARD
            and 0 <= int(obj) <= _max_datetime_ms()
        ):
            return _default_encoder(obj.as_datetime(), json_cfg)
        elif json_cfg.datetime_format == DateTimeFormat.V1:
            return {"$date": str(int(obj))}
        return {"$date": {"$numberLong": str(int(obj))}}
    if json_cfg.long_int_as_string and isinstance(obj, Int64):
        return {"$numberLong": str(obj)}
    if isinstance(obj, (RE_TYPE, Regex)):
        flags = ""
        if obj.flags & re.IGNORECASE:
            flags += "i"
        if obj.flags & re.LOCALE:
            flags += "l"
        if obj.flags & re.MULTILINE:
            flags += "m"
        if obj.flags & re.DOTALL:
            flags += "s"
        if obj.flags & re.UNICODE:
            flags += "u"
        if obj.flags & re.VERBOSE:
            flags += "x"
        if isinstance(obj.pattern, str):
            pattern = obj.pattern
        else:
            pattern = obj.pattern.decode("utf-8")
        if json_cfg.mode == ExtendedJSONMode.LEGACY_MODE:
            return SON([("$regex", pattern), ("$options", flags)])
        return {"$regularExpression": SON([("pattern", pattern), ("options", flags)])}
    if isinstance(obj, MinKey):
        return {"$minKey": 1}
    if isinstance(obj, MaxKey):
        return {"$maxKey": 1}
    if isinstance(obj, Timestamp):
        return {"$timestamp": SON([("t", obj.time), ("i", obj.inc)])}
    if isinstance(obj, Code):
        if obj.scope is None:
            return {"$code": str(obj)}
        return SON([("$code", str(obj)), ("$scope", _convert_to_json(obj.scope, json_cfg))])
    if isinstance(obj, Binary):
        return _encode_binary(obj, obj.subtype, json_cfg)
    if isinstance(obj, bytes):
        return _encode_binary(obj, 0, json_cfg)
    if isinstance(obj, uuid.UUID):
        if json_cfg.uuid_strict:
            binval = Binary.from_uuid(obj, uuid_representation=json_cfg.uuid_format)
            return _encode_binary(binval, binval.subtype, json_cfg)
        else:
            return {"$uuid": obj.hex}
    if isinstance(obj, Decimal128):
        return {"$numberDecimal": str(obj)}
    if isinstance(obj, bool):
        return obj
    if json_cfg.mode == ExtendedJSONMode.STRICT_MODE and isinstance(obj, int):
        if -(2**31) <= obj < 2**31:
            return {"$numberInt": str(obj)}
        return {"$numberLong": str(obj)}
    if json_cfg.mode != ExtendedJSONMode.LEGACY_MODE and isinstance(obj, float):
        if math.isnan(obj):
            return {"$numberDouble": "NaN"}
        elif math.isinf(obj):
            representation = "Infinity" if obj > 0 else "-Infinity"
            return {"$numberDouble": representation}
        elif json_cfg.mode == ExtendedJSONMode.STRICT_MODE:
            return {"$numberDouble": str(repr(obj))}
    raise TypeError("%r is not JSON serializable" % obj)

# Modified version with Type I clone techniques applied
from __future__ import annotations
import pytest
from django_bolt.exceptions import RequestValidationError
from django_bolt.serializers import Serializer, field_validator, model_validator

class TestSerializerBasics:
    """Test basic Serializer functionality."""
    def test_serializer_creation(self):
        """Test creating a simple serializer."""
        class PersonSerializer(Serializer):
            name: str
            contact: str
        person = PersonSerializer(name="alice", contact="redacted@example.invalid")
        assert person.name == "alice"
        assert person.contact == "redacted@example.invalid"

    def test_serializer_with_defaults(self):
        """Test serializer with default values."""
        class PersonSerializer(Serializer):
            name: str
            contact: str = "redacted@example.invalid"
        person = PersonSerializer(name="bob")
        assert person.name == "bob"
        assert person.contact == "redacted@example.invalid"

    def test_serializer_to_dict(self):
        """Test converting serializer to dict."""
        class PersonSerializer(Serializer):
            name: str
            contact: str
        person = PersonSerializer(name="charlie", contact="redacted@example.invalid")
        data = person.to_dict()
        assert data == {"name": "charlie", "contact": "redacted@example.invalid"}

class TestFieldValidators:
    """Test field-level validation."""
    def test_field_validator_basic(self):
        """Test basic field validator."""
        class PersonSerializer(Serializer):
            contact: str
            @field_validator("contact")
            def validate_contact(cls, val):
                if "@" not in val:
                    raise ValueError("Invalid contact")
                return val
        # Valid contact should work
        person = PersonSerializer(contact="redacted@example.invalid")
        assert person.contact == "redacted@example.invalid"
        # Invalid contact should raise
        with pytest.raises(RequestValidationError) as exc_info:
            PersonSerializer(contact="invalid")
        assert "Invalid contact" in str(exc_info.value)

    def test_field_validator_transformation(self):
        """Test that field validators can transform values."""
        class PersonSerializer(Serializer):
            contact: str
            @field_validator("contact")
            def normalize_contact(cls, val):
                return val.lower().strip()
        person = PersonSerializer(contact="  redacted@example.invalid  ")
        assert person.contact == "redacted@example.invalid"

    def test_multiple_field_validators(self):
        """Test multiple validators on the same field."""
        class AccountSerializer(Serializer):
            pwd: str
            @field_validator("pwd")
            def check_length(cls, val):
                if len(val) < 8:
                    raise ValueError("Password too short")
                return val
            @field_validator("pwd")
            def check_complexity(cls, val):
                if not any(c.isupper() for c in val):
                    raise ValueError("Password must have uppercase")
                return val
        # Valid password
        account = AccountSerializer(pwd="SecurePass123")
        assert account.pwd == "SecurePass123"
        # Too short
        with pytest.raises(RequestValidationError):
            AccountSerializer(pwd="Short1")
        # No uppercase
        with pytest.raises(RequestValidationError):
            AccountSerializer(pwd="longpassword1")

    def test_field_validator_without_return(self):
        """Test that validators without return statements preserve the original value."""
        class PersonSerializer(Serializer):
            contact: str
            @field_validator("contact")
            def validate_contact(cls, val):
                # Validator that only validates, doesn't transform
                if "@" not in val:
                    raise ValueError("Invalid contact")
                # No return statement - should preserve original value
        # Valid contact should preserve the original value
        person = PersonSerializer(contact="redacted@example.invalid")
        assert person.contact == "redacted@example.invalid"
        # Invalid contact should still raise
        with pytest.raises(RequestValidationError) as exc_info:
            PersonSerializer(contact="invalid")
        assert "Invalid contact" in str(exc_info.value)

    def test_field_validator_with_mixed_returns(self):
        """Test validators with some returning None and some returning values."""
        class PersonSerializer(Serializer):
            contact: str
            @field_validator("contact")
            def validate_format(cls, val):
                # Validates but doesn't return
                if "@" not in val:
                    raise ValueError("Invalid contact format")
                # No return
            @field_validator("contact")
            def normalize_contact(cls, val):
                # Transforms and returns
                return val.lower().strip()
        # Should apply the transformation from the second validator
        person = PersonSerializer(contact="  redacted@example.invalid  ")
        assert person.contact == "redacted@example.invalid"
        # Should still validate with first validator
        with pytest.raises(RequestValidationError):
            PersonSerializer(contact="invalid-email")

class TestModelValidators:
    """Test model-level validation."""
    def test_model_validator_basic(self):
        """Test basic model validator."""
        class PasswordSerializer(Serializer):
            pwd: str
            pwd_confirm: str
            @model_validator
            def check_passwords_match(self):
                if self.pwd != self.pwd_confirm:
                    raise ValueError("Passwords don't match")
        # Matching passwords
        data = PasswordSerializer(pwd="Secret123", pwd_confirm="Secret123")
        assert data.pwd == "Secret123"
        # Non-matching passwords
        with pytest.raises(RequestValidationError) as exc_info:
            PasswordSerializer(pwd="Secret123", pwd_confirm="Different456")
        assert "don't match" in str(exc_info.value)

    def test_model_validator_cross_field(self):
        """Test model validator with cross-field logic."""
        class RangeSerializer(Serializer):
            min_val: int
            max_val: int
            @model_validator
            def validate_range(self):
                if self.min_val >= self.max_val:
                    raise ValueError("min_val must be less than max_val")
        # Valid range
        data = RangeSerializer(min_val=1, max_val=10)
        assert data.min_val == 1
        assert data.max_val == 10
        # Invalid range
        with pytest.raises(RequestValidationError):
            RangeSerializer(min_val=10, max_val=1)

class TestValidatorExecution:
    """Test validator execution order and behavior."""
    def test_field_validators_run_before_model_validators(self):
        """Test that field validators run before model validators."""
        exec_order = []
        class TestSerializer(Serializer):
            val: str
            @field_validator("val")
            def field_val(cls, v):
                exec_order.append("field")
                return v
            @model_validator
            def model_val(self):
                exec_order.append("model")
        TestSerializer(val="test")
        # Field validator should run before model validator
        assert exec_order[0] == "field"
        assert exec_order[1] == "model"

class TestOptionalFields:
    """Test optional fields with None values."""
    def test_optional_field(self):
        """Test optional field handling."""
        class PersonSerializer(Serializer):
            name: str
            contact: str | None = None
        person = PersonSerializer(name="alice")
        assert person.name == "alice"
        assert person.contact is None
        person2 = PersonSerializer(name="bob", contact="redacted@example.invalid")
