# Calculate time range from various input formats
from datetime import datetime, date, timedelta
from typing import Optional, Tuple
import re

def convert_time_input(time_str: str) -> datetime:
    """
    Convert natural language time string into datetime object.

    Supports:
    - "9am", "2pm" -> current day at specified hour
    - "yesterday" -> previous day at 00:00
    - "last week" -> 7 days ago at 00:00
    - ISO timestamps: "2026-02-06 09:00", "2026-02-06T09:00:00"
    - Relative expressions: "1h ago", "2d ago", "30m ago"
    """
    time_str = time_str.strip().lower()

    # Handle "Xam" / "Xpm" (e.g., "9am", "2pm")
    if match := re.match(r'(\d{1,2})(am|pm)$', time_str):
        hour_val = int(match.group(1))
        if match.group(2) == 'pm' and hour_val != 12:
            hour_val += 12
        elif match.group(2) == 'am' and hour_val == 12:
            hour_val = 0
        return datetime.combine(date.today(), datetime.min.time()).replace(hour=hour_val)

    # Handle "yesterday"
    if time_str == 'yesterday':
        return datetime.combine(date.today() - timedelta(days=1), datetime.min.time())

    # Handle "last week"
    if time_str == 'last week':
        return datetime.combine(date.today() - timedelta(days=7), datetime.min.time())

    # Handle "Xh ago", "Xd ago", "Xm ago"
    if match := re.match(r'(\d+)(h|d|m)\s*ago$', time_str):
        value = int(match.group(1))
        unit_type = match.group(2)
        if unit_type == 'h':
            return datetime.now() - timedelta(hours=value)
        elif unit_type == 'd':
            return datetime.now() - timedelta(days=value)
        elif unit_type == 'm':
            return datetime.now() - timedelta(minutes=value)

    # Attempt ISO format parsing
    try:
        # Handle "2026-02-06 09:00" or "2026-02-06T09:00:00"
        if 'T' in time_str or ' ' in time_str:
            return datetime.fromisoformat(time_str)
        # Handle "2026-02-06" (assume 00:00)
        return datetime.combine(date.fromisoformat(time_str), datetime.min.time())
    except ValueError:
        pass

    raise ValueError(f"Unable to parse time input: '{time_str}'")

def determine_time_range(
    interval: Optional[str] = None,
    from_time: Optional[str] = None,
    after_time: Optional[str] = None,
    during: Optional[Tuple[str, str]] = None,
) -> Tuple[Optional[datetime], Optional[datetime]]:
    """
    Determine time range based on command-line parameters.

    Returns (begin, finish) datetime objects.
    Priority order: during > from_time/after_time > interval
    """
    # Process --during start end
    if during:
        begin_str, finish_str = during
        begin = convert_time_input(begin_str)
        finish = convert_time_input(finish_str)
        return (begin, finish)

    # Process --from / --after (synonymous)
    time_spec = from_time or after_time
    if time_spec:
        begin = convert_time_input(time_spec)
        return (begin, None)  # No upper bound

    # Process --interval (legacy support)
    if interval:
        current_time = datetime.now()
        if interval == 'day':
            begin = datetime.combine(date.today(), datetime.min.time())
        elif interval == 'week':
            begin = datetime.combine(date.today() - timedelta(days=7), datetime.min.time())
        elif interval == 'month':
            begin = datetime.combine(date.today() - timedelta(days=30), datetime.min.time())
        else:
            raise ValueError(f"Invalid interval type: {interval}")
        return (begin, None)

    # Default case: today's date at midnight
    return (datetime.combine(date.today(), datetime.min.time()), None)

import base64
import dataclasses
import datetime as dt
from enum import Enum
from pathlib import PurePath
from types import GeneratorType
from typing import Any, Callable, Dict, List, Optional, Set, Union
import pydantic
from .datetime_utils import serialize_datetime
from .pydantic_utilities import (
    IS_PYDANTIC_V2,
    encode_by_type,
    to_jsonable_with_fallback,
)
SetIntStr = Set[Union[int, str]]
DictIntStrAny = Dict[Union[int, str], Any]
def jsonable_encoder(obj: Any, custom_encoder: Optional[Dict[Any, Callable[[Any], Any]]] = None) -> Any:
    custom_encoder = custom_encoder or {}
    # Handle special sentinel value for "OMIT"
    if obj is Ellipsis:
        return None
    if custom_encoder:
        # Check direct type match first
        if type(obj) in custom_encoder:
            return custom_encoder[type(obj)](obj)
        else:
            # Fall back to isinstance checks
            for encoder_type, encoder_instance in custom_encoder.items():
                if isinstance(obj, encoder_type):
                    return encoder_instance(obj)
    # Handle Pydantic models
    if isinstance(obj, pydantic.BaseModel):
        if IS_PYDANTIC_V2:
            encoder = getattr(obj.model_config, "json_encoders", {})  # type: ignore # Pydantic v2
        else:
            encoder = getattr(obj.__config__, "json_encoders", {})  # type: ignore # Pydantic v1
        if custom_encoder:
            encoder.update(custom_encoder)
        obj_dict = obj.dict(by_alias=True)
        # Handle root field variations
        if "__root__" in obj_dict:
            obj_dict = obj_dict["__root__"]
        if "root" in obj_dict:
            obj_dict = obj_dict["root"]
        return jsonable_encoder(obj_dict, custom_encoder=encoder)
    # Handle dataclasses
    if dataclasses.is_dataclass(obj):
        obj_dict = dataclasses.asdict(obj)  # type: ignore
        return jsonable_encoder(obj_dict, custom_encoder=custom_encoder)
    # Handle bytes (base64 encoding)
    if isinstance(obj, bytes):
        return base64.b64encode(obj).decode("utf-8")
    # Handle enums
    if isinstance(obj, Enum):
        return obj.value
    # Handle path objects
    if isinstance(obj, PurePath):
        return str(obj)
    # Handle primitive types
    if isinstance(obj, (str, int, float, type(None))):
        return obj
    # Handle datetime objects
    if isinstance(obj, dt.datetime):
        return serialize_datetime(obj)
    # Handle date objects
    if isinstance(obj, dt.date):
        return str(obj)
    # Handle dictionaries
    if isinstance(obj, dict):
        encoded_dict = {}
        allowed_keys = set(obj.keys())
        for key, value in obj.items():
            if key in allowed_keys:
                if value is Ellipsis:
                    continue
                encoded_key = jsonable_encoder(key, custom_encoder=custom_encoder)
                encoded_value = jsonable_encoder(value, custom_encoder=custom_encoder)
                encoded_dict[encoded_key] = encoded_value
        return encoded_dict
    # Handle sequences (list, set, frozenset, generators, tuples)
    if isinstance(obj, (list, set, frozenset, GeneratorType, tuple)):
        encoded_list = []
        for item in obj:
            if item is Ellipsis:
                continue
            encoded_list.append(jsonable_encoder(item, custom_encoder=custom_encoder))
        return encoded_list
    # Fallback serializer for complex objects
    def fallback_serializer(o: Any) -> Any:
        attempt_encode = encode_by_type(o)
        if attempt_encode is not None:
            return attempt_encode
        try:
            data = dict(o)
        except Exception as e:
            errors: List[Exception] = []
            errors.append(e)
            try:
                data = vars(o)
            except Exception as e:
                errors.append(e)
                raise ValueError(errors) from e
        return jsonable_encoder(data, custom_encoder=custom_encoder)
    return to_jsonable_with_fallback(obj, fallback_serializer)

import json
import sys
import ipaddress
import subprocess

def check_ipv4_format(address):
    try:
        ipaddress.IPv4Address(address)
        return True
    except ValueError:
        return False

def validate_cidr_notation(cidr):
    try:
        ipaddress.ip_network(cidr, strict=False)
        return True
    except ValueError:
        return False

def execute_scan(target_host, port_list, rapid=False, aggressive=False, 
                 max_wait=30, num_ports=None, max_hosts=None, skip_ips=None):
    try:
        scanner = nmap.PortScanner()
    except nmap.PortScannerError:
        return {"error": "nmap executable is missing. Please install nmap."}

    arguments = '-sV'
    if aggressive:
        arguments += ' -T4'
    if max_wait:
        arguments += f' --host-timeout {max_wait}s'
    if num_ports:
        arguments += f' --top-ports {num_ports}'
    if max_hosts:
        arguments += f' -n --max-hosts {max_hosts}'
    if skip_ips:
        arguments += f' --exclude {skip_ips}'

    try:
        if check_ipv4_format(target_host):
            output = scanner.scan(target_host, port_list, arguments=arguments)
        elif validate_cidr_notation(target_host):
            if not num_ports:
                arguments += ' --top-ports 10'  # default for CIDR scan
            output = scanner.scan(target_host, port_list, arguments=arguments)
        elif '-' in target_host:
            begin_ip, finish_ip = target_host.split('-')
            output = scanner.scan(begin_ip + '-' + finish_ip, port_list, arguments=arguments)
        elif ',' in target_host:
            output = scanner.scan(target_host, port_list, arguments=arguments)
        else:
            return {"error": "Unsupported target format. Acceptable formats: CIDR, range (start-end), single IPv4, or comma-separated IPs."}
    except Exception as error:
        return {"error": str(error)}

    extracted_data = {}
    if 'scan' in output:
        for current_host, host_info in output['scan'].items():
            extracted_data[current_host] = {}
            if 'tcp' in host_info:
                extracted_data[current_host]['tcp'] = host_info['tcp']

    return {
        "scan_results": extracted_data, 
        "nmap_command": scanner.command_line(), 
        "scan_details": scanner.scaninfo()
    }

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(json.dumps({
            "error": "Insufficient arguments. Usage: network-scan target=<target> ports=<ports> [--quick] [--fast] [--timeout <seconds>] [--top-ports <num>] [--hosts-limit <num>] [--exclude <ip>]"
        }, indent=4))
        sys.exit(1)

    target_host = None
    port_list = None
    quick_mode = False
    rapid_mode = False
    max_wait = 30
    num_ports = None
    max_hosts = None
    skip_ips = None

    try:
        for argument in sys.argv[1:]:
            if argument.startswith("target="):
                target_host = argument.split("=", 1)[1]
            elif argument.startswith("ports="):
                port_list = argument.split("=", 1)[1]
            elif argument == "--quick":
                quick_mode = True
            elif argument == "--fast":
                rapid_mode = True
            elif argument.startswith("--timeout="):
                max_wait = int(argument.split("=", 1)[1])
            elif argument.startswith("--top-ports="):
                num_ports = int(argument.split("=", 1)[1])
            elif argument.startswith("--hosts-limit="):
                max_hosts = int(argument.split("=", 1)[1])
            elif argument.startswith("--exclude="):
                skip_ips = argument.split("=", 1)[1]
    except Exception as err:
        print(json.dumps({"error": f"Failed to parse arguments: {str(err)}"}))
