# OMEGA JSON Compatibility Wrapper - orjson for performance-critical paths, stdlib fallback.
# Drop-in replacement: import omega.json_compat as json
# Fallback trigger: set OMEGA_USE_STDLIB_JSON=1 in environment variables
import os
import json as _std_json
_USE_ORJSON = os.environ.get("OMEGA_USE_STDLIB_JSON") != "1"
try:
    if _USE_ORJSON:
        import orjson as _fast_json
    else:
        _fast_json = None
except ImportError:
    _fast_json = None

def loads(s, **kwargs):
    if _fast_json and not kwargs:
        data = s if isinstance(s, (bytes, bytearray, memoryview)) else s.encode()
        return _fast_json.loads(data)
    return _std_json.loads(s, **kwargs)

def dumps(obj, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    if indent is not None or not _fast_json:
        return _std_json.dumps(
            obj, indent=indent, default=default, sort_keys=sort_keys, ensure_ascii=ensure_ascii, **kwargs
        )
    options = 0
    if sort_keys:
        options |= _fast_json.OPT_SORT_KEYS
    custom_default = default if callable(default) else (str if default == str else None)
    result = _fast_json.dumps(obj, default=custom_default, option=options or None)
    return result.decode() if isinstance(result, bytes) else result

def load(fp, **kwargs):
    return loads(fp.read(), **kwargs)

def dump(obj, fp, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    fp.write(dumps(obj, indent=indent, default=default, sort_keys=sort_keys, ensure_ascii=ensure_ascii, **kwargs))

# Type definitions for shuo.
# All state, events, and actions are immutable dataclasses.
# Minimal -- only what the main loop needs to route decisions.
# Conversation history lives in Agent, not in AppState.
"""
from dataclasses import dataclass
from enum import Enum, auto
from typing import Optional, Union, List

# =============================================================================
# STATE
# =============================================================================
class ConversationPhase(Enum):
    """Current phase of the conversation."""
    LISTENING = auto()     # Waiting for user / user speaking
    RESPONDING = auto()    # Agent active (LLM -> TTS -> Playback)

@dataclass(frozen=True)
class SystemState:
    """
    Application state -- just routing information.
    Conversation history is owned by Agent, not tracked here.
    """
    current_phase: ConversationPhase = ConversationPhase.LISTENING
    stream_identifier: Optional[str] = None

# =============================================================================
# EVENTS (inputs to the system)
# =============================================================================
@dataclass(frozen=True)
class StreamInitiatedEvent:
    """Twilio stream started."""
    stream_sid: str

@dataclass(frozen=True)
class StreamTerminatedEvent:
    """Twilio stream ended."""
    pass

@dataclass(frozen=True)
class AudioFrameEvent:
    """Audio data received from Twilio."""
    audio_data: bytes

@dataclass(frozen=True)
class DeepgramSpeechStartEvent:
    """Deepgram Flux detected user started speaking (barge-in)."""
    pass

@dataclass(frozen=True)
class DeepgramSpeechEndEvent:
    """Deepgram Flux detected user finished speaking."""
    transcript_text: str

@dataclass(frozen=True)
class AgentSpeechCompleteEvent:
    """Agent finished speaking (playback complete)."""
    pass

Event = Union[
    StreamInitiatedEvent, StreamTerminatedEvent, AudioFrameEvent,
    DeepgramSpeechStartEvent, DeepgramSpeechEndEvent,
    AgentSpeechCompleteEvent,
]

# =============================================================================
# ACTIONS (outputs from the system)
# =============================================================================
@dataclass(frozen=True)
class SendToDeepgramAction:
    """Send audio to Deepgram Flux."""
    audio_bytes: bytes

@dataclass(frozen=True)
class BeginAgentResponseAction:
    """Start agent response pipeline."""
    user_transcript: str

@dataclass(frozen=True)
class CancelAgentResponseAction:
    """Cancel agent response and clear Twilio buffer."""
    pass

Action = Union[
    SendToDeepgramAction,
    BeginAgentResponseAction,
    CancelAgentResponseAction,
]

