def initialize_project(
    name: str,
    destination_dir: Path,
    template_type: str = "nextjs",
    features_list: Optional[List[str]] = None,
    test_mode: bool = False,
) -> Dict:
    """Initialize a complete frontend project."""
    features_list = features_list or []
    project_path = destination_dir / name
    if project_path.exists() and not test_mode:
        return {"error": f"Directory already exists: {project_path}"}

    project_template = PROJECT_TEMPLATES.get(template_type)
    if not project_template:
        return {"error": f"Unknown template: {template_type}"}

    generated_files = []

    # Create project directory
    if not test_mode:
        project_path.mkdir(parents=True, exist_ok=True)

    # Generate base structure
    generated_files.extend(
        create_structure(project_path, project_template["layout"], test_mode)
    )

    # Generate config files
    generated_files.extend(
        generate_config_files(project_path, template_type, name, features_list, test_mode)
    )

    # Add feature files
    for feature in features_list:
        if feature in FEATURE_MODULES:
            for file_path, content_key in FEATURE_MODULES[feature]["files"].items():
                full_path = project_path / file_path
                if not test_mode:
                    full_path.parent.mkdir(parents=True, exist_ok=True)
                    content = FILE_CONTENTS.get(content_key, f"// TODO: Implement {content_key}")
                    full_path.write_text(content)
                generated_files.append(str(full_path))

    return {
        "name": name,
        "template": template_type,
        "template_title": project_template["title"],
        "features": features_list,
        "path": str(project_path),
        "files_created": len(generated_files),
        "files": generated_files,
        "next_steps": [
            f"cd {name}",
            "npm install",
            "npm run dev",
        ],
    }


def display_result(result: Dict) -> None:
    """Print scaffolding result."""
    if "error" in result:
        print(f"Error: {result['error']}", file=sys.stderr)
        return

    print(f"\n{'='*60}")
    print(f"Project Scaffolded: {result['name']}")
    print(f"{'='*60}")
    print(f"Template: {result['template_title']}")
    print(f"Location: {result['path']}")
    print(f"Files Created: {result['files_created']}")
    if result["features"]:
        print(f"Features: {', '.join(result['features'])}")
    print(f"\nNext Steps:")
    for step in result["next_steps"]:
        print(f"  $ {step}")
    print(f"{'='*60}\n")


def main():
    parser = argparse.ArgumentParser(
        description="Initialize a frontend project with best practices"
    )
    parser.add_argument(
        "name",
        help="Project name (kebab-case recommended)"
    )
    parser.add_argument(
        "--dir", "-d",
        default=".",
        help="Output directory (default: current directory)"
    )
    parser.add_argument(
        "--template", "-t",
        choices=list(PROJECT_TEMPLATES.keys()),
        default="nextjs",
        help="Project template (default: nextjs)"
    )
    parser.add_argument(
        "--features", "-f",
        help="Comma-separated features to add (auth,api,forms,testing,storybook)"
    )
    parser.add_argument(
        "--list-templates",
        action="store_true",
        help="List available templates"
    )
    parser.add_argument(
        "--list-features",
        action="store_true",
        help="List available features"
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Show what would be created without creating files"
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Output in JSON format"
    )
    args = parser.parse_args()

    if args.list_templates:
        print("\nAvailable Templates:")
        for key, template in PROJECT_TEMPLATES.items():
            print(f"  {key}: {template['title']}")
            print(f"    {template['info']}")
        return

    if args.list_features:
        print("\nAvailable Features:")
        for key, feature in FEATURE_MODULES.items():
            print(f"  {key}: {feature['description']}")
            packages = ", ".join(feature.get("packages", []))
            if packages:
                print(f"    Adds: {packages}")
        return

    features = []
    if args.features:
        features = [f.strip() for f in args.features.split(",")]
        invalid = [f for f in features if f not in FEATURE_MODULES]
        if invalid:
            print(f"Unknown features: {', '.join(invalid)}", file=sys.stderr)
            print(f"Valid features: {', '.join(FEATURE_MODULES.keys())}")
            sys.exit(1)

    result = initialize_project(
        name=args.name,
        output_dir=Path(args.dir),
        template=args.template,
        features=features,
        dry_run=args.dry_run,
    )

    if args.json:
        print(json.dumps(result, indent=2))
    else:
        display_result(result)


if __name__ == "__main__":
    main()

# Validate RPC envelope according to protocol rules
from typing import Any, Dict, Optional, Tuple
from loguru import logger
from pydantic import ValidationError
from pydantic.type_adapter import TypeAdapter
from .protocol import PROTOCOL_VERSION, RpcEnvelope

_RPC_ENVELOPE_VALIDATOR: TypeAdapter[RpcEnvelope] = TypeAdapter(RpcEnvelope)

def check_rpc_structure(
    request: Any,
    *,
    validation_mode: str,
) -> Tuple[Optional[RpcEnvelope], Optional[str]]:
    if validation_mode == "disabled":
        return None, None

    # Graceful handling: in advisory mode, accept older clients that didn't include protocol version.
    # We preprocess the request before validation to keep the official schema unchanged.
    if validation_mode == "advisory" and isinstance(request, dict) and "v" not in request:
        try:
            request = dict(request)
            request["v"] = PROTOCOL_VERSION
        except Exception:
            pass

    try:
        envelope = _RPC_ENVELOPE_VALIDATOR.validate_python(request)
    except ValidationError as error:
        if validation_mode == "advisory":
            logger.warning("malformed rpc envelope: {}", error)
        return None, "malformed rpc envelope"

    if envelope.v is not None and envelope.v != PROTOCOL_VERSION:
        return None, f"unsupported protocol version: {envelope.v!r}"

    if validation_mode == "enforcing":
        if envelope.v is None:
            return None, "missing protocol version"

    return envelope, None

# Calculate fusible subgraph ranges from model analysis context
from graph_net.sample_pass.resumable_sample_pass_mixin import ResumableSamplePassMixin
from pathlib import Path
import json
from itertools import groupby
from dataclasses import dataclass

class FusibleSubgraphRangesGenerator(SamplePass, ResumableSamplePassMixin):
    def __init__(self, config):
        super().__init__(config)

    def declare_config(
        self,
        model_path_prefix: str,
        output_dir: str,
        input_json_file_name: str,
        resume: bool = False,
        limits_handled_models: int = None,
        output_json_file_name: str = "fusible_subgraph_ranges.json",
    ):
        pass

    def __call__(self, rel_model_path: str):
        self.resumable_handle_sample(rel_model_path)

    def sample_handled(self, rel_model_path: str) -> bool:
        file_name = self.config["output_json_file_name"]
        return self.naive_sample_handled(rel_model_path, search_file_name=file_name)

    def resume(self, rel_model_path: str):
        analyzer = self._make_analyzer(rel_model_path)
        output_obj = {
            "subgraph_ranges": analyzer.analyze(),
        }
        self._save_output(rel_model_path, output_obj)

    def _save_output(self, rel_model_path, output_obj):
        output_json = json.dumps(output_obj, indent=4)
        output_dir_path = Path(self.config["output_dir"]) / rel_model_path
        output_dir_path.mkdir(parents=True, exist_ok=True)
        output_file_path = output_dir_path / self.config["output_json_file_name"]
        output_file_path.write_text(output_json)

    def _make_analyzer(self, rel_model_path: str):
        model_path = (
            Path(self.config["model_path_prefix"])
            / rel_model_path
            / self.config["input_json_file_name"]
        )
        json_ctx = self._make_json_ctx(model_path)
        return FusibleSubgraphRangesAnalyzer(
            num_subgraph_kernels_list=self._get_num_subgraph_kernels_list(json_ctx),
            num_subgraph_ops_list=self._get_num_subgraph_ops_list(json_ctx),
            start_offset_in_original_graph=self._get_start_offset_in_original_graph(
                json_ctx
            ),
        )

    def _get_start_offset_in_original_graph(self, json_ctx):
        return json_ctx["start_offset_in_original_graph"]

    def _get_num_subgraph_kernels_list(self, json_ctx):
        return json_ctx["num_subgraph_kernels"]

    def _get_num_subgraph_ops_list(self, json_ctx):
        return json_ctx["num_subgraph_ops"]

    def _make_json_ctx(self, model_path: Path):
        obj = json.loads(model_path.read_text())
        assert len(obj["num_subgraph_kernels"]) == len(obj["num_subgraph_ops"])
        return obj


class FusibleSubgraphRangesAnalyzer:
    def __init__(
        self,
        num_subgraph_kernels_list: list[int],
        num_subgraph_ops_list: list[int],
        start_offset_in_original_graph: int,
    ):
        assert len(num_subgraph_kernels_list) == len(num_subgraph_ops_list)
        self.num_subgraph_kernels_list = num_subgraph_kernels_list
        self.num_subgraph_ops_list = num_subgraph_ops_list
        self.start_offset_in_original_graph = start_offset_in_original_graph

    def analyze(self):
        analysis_ctx = self._make_analysis_ctx()
        num_kernels_and_num_ops_list = analysis_ctx.num_kernels_and_num_ops_list

        # The tail num_kernels equals the head num_kernels for each num_ops_list
        naive_proposal_fused_num_ops_lists = [
            sorted(set(num_ops_list))
            for _, num_ops_list in num_kernels_and_num_ops_list
            if len(set(num_ops_list)) > 1
        ]

        proposal_fused_num_ops_lists = self._merge_all_decreasing_num_ops_lists(
            analysis_ctx, naive_proposal_fused_num_ops_lists
        )

        return self._create_subgraph_ranges_from_proposal(
            analysis_ctx,
            proposal_fused_num_ops_lists,
        )

    def _merge_all_decreasing_num_ops_lists(self, analysis_ctx, num_ops_lists):
        dead_loop_detect_cnt = 0
        kLimit = 99999
        while True:
            last_len_num_ops_lists = len(num_ops_lists)
            num_ops_lists = self._merge_one_decreasing_num_ops_lists(
                analysis_ctx, num_ops_lists
            )
            assert last_len_num_ops_lists >= len(num_ops_lists)
            if last_len_num_ops_lists == len(num_ops_lists):
                break
            dead_loop_detect_cnt += 1
            assert dead_loop_detect_cnt < kLimit, f"{dead_loop_detect_cnt=}"
        return num_ops_lists

    def _merge_one_decreasing_num_ops_lists(self, analysis_ctx, num_ops_lists):
        merge_pos = self._detect_mergable_decreasing_position(
            analysis_ctx, num_ops_lists
        )
        if merge_pos is None:
            return num_ops_lists
        assert merge_pos >= 0
        assert merge_pos < len(num_ops_lists) - 1
        return [
            *num_ops_lists[:merge_pos],
            [*num_ops_lists[merge_pos], *num_ops_lists[merge_pos + 1]],
            *num_ops_lists[merge_pos + 2 :],
        ]

    def _detect_mergable_decreasing_position(self, analysis_ctx, num_ops_lists):
        def get_cur_tail_num_kernels(i):
            return analysis_ctx.num_kernels4num_ops(num_ops_lists[i][-1])

        def get_next_head_num_kernels(i):
            return analysis_ctx.num_kernels4num_ops(num_ops_lists[i + 1][0])

        for i in range(len(num_ops_lists) - 1):
            assert len(num_ops_lists[i]) > 1
            if get_cur_tail_num_kernels(i) >= get_next_head_num_kernels(i):
                return i
        return None

    def _create_subgraph_ranges_from_proposal(
        self, analysis_ctx, proposal_fused_num_ops_lists
    ):
        # filter valid num_ops_list
        def is_a_range(int_list):
            assert len(int_list) > 1
            return (int_list[-1] + 1) - int_list[0] == len(int_list)

        def have_any_increasing(num_ops_list: list[int]):
            for i, cur_num_ops in enumerate(num_ops_list):
                if i == 0:
                    continue
                cur_num_kernels = analysis_ctx.num_kernels4num_ops(cur_num_ops)
                last_num_kernels = analysis_ctx.num_kernels4num_ops(num_ops_list[i - 1])
                if cur_num_kernels > last_num_kernels:
                    return True
            return False

        def head_eq_tail(num_ops_list: list[int]):
            return analysis_ctx.num_kernels4num_ops(
                num_ops_list[0]
            ) == analysis_ctx.num_kernels4num_ops(num_ops_list[-1])

        def head_gt_tail(num_ops_list: list[int]):
            return analysis_ctx.num_kernels4num_ops(
                num_ops_list[0]
            ) > analysis_ctx.num_kernels4num_ops(num_ops_list[-1])

        def valid_fused_ops(num_ops_list: list[int]):
            if head_gt_tail(num_ops_list):
                return True
            if head_eq_tail(num_ops_list):
                return not have_any_increasing(num_ops_list)
            return False

        proposal_fused_num_ops_lists = [
            sorted(set(num_ops_list)) for num_ops_list in proposal_fused_num_ops_lists
        ]

        num_ops_lists = [
            num_ops_list
            for num_ops_list in proposal_fused_num_ops_lists
            if len(num_ops_list) > 1
            if is_a_range(num_ops_list)
            if valid_fused_ops(num_ops_list)
        ]

        offset = self.start_offset_in_original_graph
        fusible_subgraph_ranges = [
            (start, end)
            for num_ops_list in num_ops_lists
            for start in [num_ops_list[0] - 1 + offset]
            for end in [num_ops_list[-1] + offset]
        ]

        # sorted by `start`
        def range_sort_key(pair):
            start, end = pair
            # smaller `start` first
            # bigger `end` first
            return (start, -end)

        fusible_subgraph_ranges = sorted(fusible_subgraph_ranges, key=range_sort_key)

        # remove shadowed
        fusible_subgraph_ranges = [
            fusible_subgraph_ranges[i]
            for i in range(len(fusible_subgraph_ranges))
            if i == 0
            or (fusible_subgraph_ranges[i][0] >= fusible_subgraph_ranges[i - 1][1])
        ]

        return fusible_subgraph_ranges

    def _make_analysis_ctx(self):
        return AnalysisContext(
            num_kernels_and_num_ops_list=self._make_num_kernels_and_num_ops_list(),
            num_ops2num_kernels=self._make_num_ops2num_kernels(),
        )

    def _make_num_ops2num_kernels(self):
        return dict(zip(self.num_subgraph_ops_list, self.num_subgraph_kernels_list))

    def _make_num_kernels_and_num_ops_list(self):
        num_kernels_and_num_ops = zip(
            self.num_subgraph_kernels_list,
            self.num_subgraph_ops_list,
        )

        def get_num_kernels(pair):
            return pair[0]

        def get_num_ops(pair):
            return pair[1]

        num_kernels_and_num_ops = sorted(num_kernels_and_num_ops, key=get_num_ops)
        grouped_num_kernels_and_num_ops = groupby(
            num_kernels_and_num_ops, key=get_num_kernels
        )

        num_kernels_and_num_ops_list = [
            (num_kernels, [num_ops for _, num_ops in group])
            for num_kernels, group in grouped_num_kernels_and_num_ops
        ]

        return num_kernels_and_num_ops_list


@dataclass
class AnalysisContext:
    num_kernels_and_num_ops_list: list[(int, list[int])]
    num_ops2num_kernels: dict[int, int]

    def num_kernels4num_ops(self, num_ops: int):
        return self.num_ops2num_kernels[num_ops]

# Catch up on unsynced session context for planning files
import json
import sys
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from datetime import datetime

PLANNING_FILE_LIST = ['task_plan.md', 'progress.md', 'findings.md']

def get_storage_path(project_path: str) -> Path:
    """Transform project path into Claude's storage directory format."""
    cleaned = project_path.replace('/', '-')
    if not cleaned.startswith('-'):
        cleaned = '-' + cleaned
    cleaned = cleaned.replace('_', '-')
    return Path.home() / '.claude' / 'projects' / cleaned

def retrieve_sessions(project_dir: Path) -> List[Path]:
    """Fetch all session files sorted by last modification (most recent first)."""
    session_files = list(project_dir.glob('*.jsonl'))
    main_sessions = [s for s in session_files if not s.name.startswith('agent-')]
    return sorted(main_sessions, key=lambda p: p.stat().st_mtime, reverse=True)

def load_session_data(session_file: Path) -> List[Dict]:
    """Load and parse all messages from a session file, maintaining order."""
    data_entries = []
    with open(session_file, 'r') as file:
        for idx, line in enumerate(file):
            try:
                entry = json.loads(line)
                entry['_line_index'] = idx
                data_entries.append(entry)
            except json.JSONDecodeError:
                continue
    return data_entries

def locate_last_planning_change(data_entries: List[Dict]) -> Tuple[int, Optional[str]]:
    """
    Locate the most recent instance where a planning file was modified.
    Returns (line_index, filename) or (-1, None) if none found.
    """
    latest_change_index = -1
    latest_change_name = None
    for entry in data_entries:
        entry_type = entry.get('type')
        if entry_type == 'assistant':
            message_body = entry.get('message', {}).get('content', [])
            if isinstance(message_body, list):
                for segment in message_body:
                    if segment.get('type') == 'tool_use':
                        tool_id = segment.get('name', '')
                        tool_params = segment.get('input', {})
                        if tool_id in ('Write', 'Edit'):
                            target_file = tool_params.get('file_path', '')
                            for pf in PLANNING_FILE_LIST:
                                if target_file.endswith(pf):
                                    latest_change_index = entry['_line_index']
                                    latest_change_name = pf
    return latest_change_index, latest_change_name

def filter_messages_after(data_entries: List[Dict], after_index: int) -> List[Dict]:
    """Extract conversation entries that occurred after a specific line index."""
    output = []
    for entry in data_entries:
        if entry['_line_index'] <= after_index:
            continue
        entry_type = entry.get('type')
        is_meta_entry = entry.get('isMeta', False)
        if entry_type == 'user' and not is_meta_entry:
            message_content = entry.get('message', {}).get('content', '')
            if isinstance(message_content, list):
                for part in message_content:
                    if isinstance(part, dict) and part.get('type') == 'text':
                        message_content = part.get('text', '')
                        break
                else:
                    message_content = ''
            if message_content and isinstance(message_content, str):
                if message_content.startswith(('<local-command', '<command-', '<task-notification')):
                    continue
                if len(message_content) > 20:
                    output.append({'role': 'user', 'content': message_content, 'index': entry['_line_index']})
        elif entry_type == 'assistant':
            msg_text = entry.get('message', {}).get('content', '')
            text_snippet = ''
            tool_actions = []
            if isinstance(msg_text, str):
                text_snippet = msg_text
            elif isinstance(msg_text, list):
                for part in msg_text:
                    if part.get('type') == 'text':
                        text_snippet = part.get('text', '')
                    elif part.get('type') == 'tool_use':
                        tool_name = part.get('name', '')
                        tool_data = part.get('input', {})
                        if tool_name == 'Edit':
                            tool_actions.append(f"Edit: {tool_data.get('file_path', 'unknown')}")
                        elif tool_name == 'Write':
                            tool_actions.append(f"Write: {tool_data.get('file_path', 'unknown')}")
                        elif tool_name == 'Bash':
                            cmd_str = tool_data.get('command', '')[:80]
                            tool_actions.append(f"Bash: {cmd_str}")
                        else:
                            tool_actions.append(f"{tool_name}")
            if text_snippet or tool_actions:
                output.append({
                    'role': 'assistant',
                    'content': text_snippet[:600] if text_snippet else '',
                    'tools': tool_actions,
                    'index': entry['_line_index']
                })
    return output

def main():
    project_location = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    storage_dir = get_storage_path(project_location)

    # Check if planning files exist (indicates active task)
    has_planning_files = any(
        Path(project_location, f).exists() for f in PLANNING_FILE_LIST
    )

    if not storage_dir.exists():
        # No previous sessions, nothing to catch up on
        return

    session_list = retrieve_sessions(storage_dir)
    if len(session_list) < 1:
        return

    # Find a substantial previous session
    selected_session = None
    for session in session_list:
        if session.stat().st_size > 5000:
            selected_session = session
            break

    if not selected_session:
        return

    conversation_history = load_session_data(selected_session)
    change_line, changed_file = locate_last_planning_change(conversation_history)

    # Only output if there's unsynced content
    if change_line < 0:
        recent_entries = filter_messages_after(conversation_history, len(conversation_history) - 30)
    else:
        recent_entries = filter_messages_after(conversation_history, change_line)

    if not recent_entries:
        return

    # Output catchup report
    print("\n[planning-with-files] SESSION CATCHUP DETECTED")
    print(f"Previous session: {selected_session.stem}")
    if change_line >= 0:
        print(f"Last planning update: {changed_file} at message #{change_line}")
        print(f"Unsynced messages: {len(recent_entries)}")
    else:
        print("No planning file updates found in previous session")

    print("\n--- UNSYNCED CONTEXT ---")
    for entry in recent_entries[-15:]:  # Last 15 messages
        if entry['role'] == 'user':
            print(f"USER: {entry['content'][:300]}")
        else:
            if entry.get('content'):
                print(f"CLAUDE: {entry['content'][:300]}")
            if entry.get('tools'):
                print(f"  Tools: {', '.join(entry['tools'][:4])}")

    print("\n--- RECOMMENDED ---")
    print("1. Run: git diff --stat")
    print("2. Read: task_plan.md, progress.md, findings.md")
    print("3. Update planning files based on above context")
    print("4. Continue with task")

if __name__ == '__main__':
    main()

# Certificate Policy API - UCM
# Handles certificate policies and approval workflows.
"""
from flask import Blueprint, request
from auth.unified import require_auth
from utils.response import success_response, error_response
from models import db
from models.policy import CertificatePolicy, ApprovalRequest
from datetime import datetime, timedelta
import json

bp = Blueprint('policies_pro', __name__)

# ============ Policy Management ============
@bp.route('/api/v2/policies', methods=['GET'])
@require_auth(['read:policies'])
def list_policies():
    """List all certificate policies"""
    policies = CertificatePolicy.query.order_by(CertificatePolicy.priority).all()
    return success_response(data=[p.to_dict() for p in policies])

@bp.route('/api/v2/policies/<int:policy_id>', methods=['GET'])
@require_auth(['read:policies'])
def get_policy(policy_id):
    """Get policy details"""
    policy = CertificatePolicy.query.get_or_404(policy_id)
    return success_response(data=policy.to_dict())

@bp.route('/api/v2/policies', methods=['POST'])
@require_auth(['write:policies'])
def create_policy():
    """Create new certificate policy"""
    data = request.get_json()

    if not data.get('name'):
        return error_response("Policy name is required", 400)

    # Check uniqueness
    if CertificatePolicy.query.filter_by(name=data['name']).first():
        return error_response("Policy name already exists", 400)

    policy = CertificatePolicy(
        name=data['name'],
        description=data.get('description'),
        policy_type=data.get('policy_type', 'issuance'),
        ca_id=data.get('ca_id'),
        template_id=data.get('template_id'),
        requires_approval=data.get('requires_approval', False),
        approval_group_id=data.get('approval_group_id'),
        min_approvers=data.get('min_approvers', 1),
        notify_on_violation=data.get('notify_on_violation', True),
        is_active=data.get('is_active', True),
        priority=data.get('priority', 100),
        created_by=request.current_user.get('username') if hasattr(request, 'current_user') else None
    )

    if data.get('rules'):
        policy.set_rules(data['rules'])

    if data.get('notification_emails'):
        policy.notification_emails = json.dumps(data['notification_emails'])

    db.session.add(policy)
    db.session.commit()

    return success_response(data=policy.to_dict(), message="Policy created")

@bp.route('/api/v2/policies/<int:policy_id>', methods=['PUT'])
@require_auth(['write:policies'])
def update_policy(policy_id):
    """Update certificate policy"""
    policy = CertificatePolicy.query.get_or_404(policy_id)
    data = request.get_json()

    # Update fields
    if 'name' in data:
        existing = CertificatePolicy.query.filter_by(name=data['name']).first()
        if existing and existing.id != policy_id:
            return error_response("Policy name already exists", 400)
        policy.name = data['name']

    if 'description' in data:
        policy.description = data['description']
    if 'policy_type' in data:
        policy.policy_type = data['policy_type']
    if 'ca_id' in data:
        policy.ca_id = data['ca_id']
    if 'template_id' in data:
        policy.template_id = data['template_id']
    if 'requires_approval' in data:
        policy.requires_approval = data['requires_approval']
    if 'approval_group_id' in data:
        policy.approval_group_id = data['approval_group_id']
    if 'min_approvers' in data:
        policy.min_approvers = data['min_approvers']
    if 'notify_on_violation' in data:
        policy.notify_on_violation = data['notify_on_violation']
    if 'is_active' in data:
        policy.is_active = data['is_active']
    if 'priority' in data:
        policy.priority = data['priority']
    if 'rules' in data:
        policy.set_rules(data['rules'])
    if 'notification_emails' in data:
        policy.notification_emails = json.dumps(data['notification_emails'])

    db.session.commit()
    return success_response(data=policy.to_dict(), message="Policy updated")

@bp.route('/api/v2/policies/<int:policy_id>', methods=['DELETE'])
@require_auth(['delete:policies'])
def delete_policy(policy_id):
    """Delete certificate policy"""
    policy = CertificatePolicy.query.get_or_404(policy_id)

    # Check for pending requests
    pending = ApprovalRequest.query.filter_by(
        policy_id=policy_id,
        status='pending'
    ).count()

    if pending > 0:
        return error_response(f"Cannot delete policy with {pending} pending approval requests", 400)

    db.session.delete(policy)
    db.session.commit()

    return success_response(message="Policy deleted")

@bp.route('/api/v2/policies/<int:policy_id>/toggle', methods=['POST'])
@require_auth(['write:policies'])
def toggle_policy(policy_id):
    """Enable/disable policy"""
    policy = CertificatePolicy.query.get_or_404(policy_id)
    policy.is_active = not policy.is_active
    db.session.commit()

    status = "enabled" if policy.is_active else "disabled"
    return success_response(data=policy.to_dict(), message=f"Policy {status}")

# ============ Approval Requests ============
@bp.route('/api/v2/approvals', methods=['GET'])
@require_auth(['read:approvals'])
def list_approvals():
    """List approval requests"""
    status = request.args.get('status', 'pending')

    query = ApprovalRequest.query
    if status != 'all':
        query = query.filter_by(status=status)

    requests = query.order_by(ApprovalRequest.created_at.desc()).all()
    return success_response(data=[r.to_dict() for r in requests])

@bp.route('/api/v2/approvals/<int:request_id>', methods=['GET'])
@require_auth(['read:approvals'])
def get_approval(request_id):
    """Get approval request details"""
    approval = ApprovalRequest.query.get_or_404(request_id)
    return success_response(data=approval.to_dict())

@bp.route('/api/v2/approvals/<int:request_id>/approve', methods=['POST'])
@require_auth(['write:approvals'])
def approve_request(request_id):
    """Approve a request"""
    approval = ApprovalRequest.query.get_or_404(request_id)

    if approval.status != 'pending':
        return error_response(f"Request is already {approval.status}", 400)

    data = request.get_json() or {}
    user = request.current_user if hasattr(request, 'current_user') else {}

    approval.add_approval(
        user_id=user.get('id'),
        username=user.get('username', 'system'),
        action='approve',
        comment=data.get('comment')
    )

    db.session.commit()

    return success_response(data=approval.to_dict(), message="Approval recorded")

@bp.route('/api/v2/approvals/<int:request_id>/reject', methods=['POST'])
@require_auth(['write:approvals'])
def reject_request(request_id):
    """Reject a request"""
    approval = ApprovalRequest.query.get_or_404(request_id)

    if approval.status != 'pending':
        return error_response(f"Request is already {approval.status}", 400)

    data = request.get_json() or {}
    user = request.current_user if hasattr(request, 'current_user') else {}

    if not data.get('comment'):
        return error_response("Rejection reason is required", 400)

    approval.add_approval(
        user_id=user.get('id'),
        username=user.get('username', 'system'),
        action='reject',
        comment=data.get('comment')
    )

    db.session.commit()

    return success_response(data=approval.to_dict(), message="Request rejected")

@bp.route('/api/v2/approvals/stats', methods=['GET'])
@require_auth(['read:approvals'])
def approval_stats():
    """Get approval statistics"""
    pending = ApprovalRequest.query.filter_by(status='pending').count()
    approved = ApprovalRequest.query.filter_by(status='approved').count()
    rejected = ApprovalRequest.query.filter_by(status='rejected').count()

    return success_response(data={
        'pending': pending,
        'approved': approved,
        'rejected': rejected,
        'total': pending + approved + rejected
    })

