class PipelineTesterMixin:
    model_tester = None
    pipeline_model_mapping = None
    supported_frameworks = ["pt", "tf"]

    def run_task_tests(self, task_name, torch_dtype="float32"):
        """Run pipeline tests for a specific `task`
        Args:
            task_name (`str`):
                A task name. This should be a key in the mapping `pipeline_test_mapping`.
            torch_dtype (`str`, `optional`, defaults to `'float32'`):
                The torch dtype to use for the model. Can be used for FP16/other precision inference.
        """
        if task_name not in self.pipeline_model_mapping:
            self.skipTest(
                f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{torch_dtype} is skipped: `{task_name}` is not in "
                f"`self.pipeline_model_mapping` for `{self.__class__.__name__}`."
            )
        model_architectures = self.pipeline_model_mapping[task_name]
        if not isinstance(model_architectures, tuple):
            model_architectures = (model_architectures,)
        if not isinstance(model_architectures, tuple):
            raise TypeError(f"`model_architectures` must be a tuple. Got {type(model_architectures)} instead.")

        for architecture_class in model_architectures:
            arch_name = architecture_class.__name__
            # Remove framework prefixes like 'Flax' or 'TF'
            for prefix in ["Flax", "TF"]:
                if arch_name.startswith(prefix):
                    arch_name = arch_name[len(prefix):]
                    break

            tokenizer_list = []
            processor_list = []
            commit_hash = None

            if arch_name in tiny_model_summary:
                tokenizer_list = tiny_model_summary[arch_name]["tokenizer_classes"]
                processor_list = tiny_model_summary[arch_name]["processor_classes"]
                if "sha" in tiny_model_summary[arch_name]:
                    commit_hash = tiny_model_summary[arch_name]["sha"]

            # Ensure at least None is present for iteration
            tokenizer_list = [None] if len(tokenizer_list) == 0 else tokenizer_list
            processor_list = [None] if len(processor_list) == 0 else processor_list

            repo_name = f"tiny-random-{arch_name}"
            if TRANSFORMERS_TINY_MODEL_PATH != "hf-internal-testing":
                repo_name = arch_name

            self.run_model_pipeline_tests(
                task_name, repo_name, architecture_class, tokenizer_list, processor_list, commit_hash, torch_dtype
            )

    def run_model_pipeline_tests(
        self, task_name, repo_id_short, model_class, tokenizer_names, processor_names, commit_hash, torch_dtype="float32"
    ):
        """Run pipeline tests for a specific `task` with the given model class and tokenizer/processor class names
        Args:
            task_name (`str`):
                A task name. This should be a key in the mapping `pipeline_test_mapping`.
            repo_id_short (`str`):
                A model repository id on the Hub.
            model_class (`type`):
                A subclass of `PretrainedModel` or `PretrainedModel`.
            tokenizer_names (`List[str]`):
                A list of names of subclasses of `PreTrainedTokenizerFast` or `PreTrainedTokenizer`.
            processor_names (`List[str]`):
                A list of names of subclasses of `BaseImageProcessor` or `FeatureExtractionMixin`.
            commit_hash (`str`):
                The commit hash of the model repository on the Hub.
            torch_dtype (`str`, `optional`, defaults to `'float32'`):
                The torch dtype to use for the model. Can be used for FP16/other precision inference.
        """
        pipeline_test_class = pipeline_test_mapping[task_name]["test"].__name__
        for tokenizer_class_name in tokenizer_names:
            for processor_class_name in processor_names:
                if self.is_pipeline_test_to_skip(
                    pipeline_test_class,
                    model_class.config_class,
                    model_class,
                    tokenizer_class_name,
                    processor_class_name,
                ):
                    logger.warning(
                        f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{torch_dtype} is skipped: test is "
                        f"currently known to fail for: model `{model_class.__name__}` | tokenizer "
                        f"`{tokenizer_class_name}` | processor `{processor_class_name}`."
                    )
                    continue
                self.run_pipeline_test(
                    task_name, repo_id_short, model_class, tokenizer_class_name, processor_class_name, commit_hash, torch_dtype
                )

    def run_pipeline_test(
        self, task_name, repo_id_short, model_class, tokenizer_class_name, processor_class_name, commit_hash, torch_dtype="float32"
    ):
        """Run pipeline tests for a specific `task` with the given model class and tokenizer/processor class name
        The model will be loaded from a model repository on the Hub.
        Args:
            task_name (`str`):
                A task name. This should be a key in the mapping `pipeline_test_mapping`.
            repo_id_short (`str`):
                A model repository id on the Hub.
            model_class (`type`):
                A subclass of `PretrainedModel` or `PretrainedModel`.
            tokenizer_class_name (`str`):
                The name of a subclass of `PreTrainedTokenizerFast` or `PreTrainedTokenizer`.
            processor_class_name (`str`):
                The name of a subclass of `BaseImageProcessor` or `FeatureExtractionMixin`.
            commit_hash (`str`):
                The commit hash of the model repository on the Hub.
            torch_dtype (`str`, `optional`, defaults to `'float32'`):
                The torch dtype to use for the model. Can be used for FP16/other precision inference.
        """
        full_repo_id = f"{TRANSFORMERS_TINY_MODEL_PATH}/{repo_id_short}"
        if TRANSFORMERS_TINY_MODEL_PATH != "hf-internal-testing":
            model_type = model_class.config_class.model_type
            full_repo_id = os.path.join(TRANSFORMERS_TINY_MODEL_PATH, model_type, repo_id_short)

        tokenizer = None
        if tokenizer_class_name is not None:
            tokenizer_class = getattr(transformers_module, tokenizer_class_name)
            tokenizer = tokenizer_class.from_pretrained(full_repo_id, revision=commit_hash)

        processor = None
        if processor_class_name is not None:
            processor_class = getattr(transformers_module, processor_class_name)
            try:
                processor = processor_class.from_pretrained(full_repo_id, revision=commit_hash)
            except Exception:
                logger.warning(
                    f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{torch_dtype} is skipped: Could not load the "
                    f"processor from `{full_repo_id}` with `{processor_class_name}`."
                )
                self.skipTest(f"Could not load the processor from {full_repo_id} with {processor_class_name}.")

        if tokenizer is None and processor is None:
            logger.warning(
                f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{torch_dtype} is skipped: Could not find or load "
                f"any tokenizer / processor from `{full_repo_id}`."
            )
            self.skipTest(f"Could not find or load any tokenizer / processor from {full_repo_id}.")

        try:
            model = model_class.from_pretrained(full_repo_id, revision=commit_hash)
        except Exception:
            logger.warning(
                f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{torch_dtype} is skipped: Could not find or load "
                f"the model from `{full_repo_id}` with `{model_class}`."
            )
            self.skipTest(f"Could not find or load the model from {full_repo_id} with {model_class}.")

        pipeline_test_class_name = pipeline_test_mapping[task_name]["test"].__name__
        if self.is_pipeline_test_to_skip_more(pipeline_test_class_name, model.config, model, tokenizer, processor):
            logger.warning(
                f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{torch_dtype} is skipped: test is "
                f"currently known to fail for: model `{model_class.__name__}` | tokenizer "
                f"`{tokenizer_class_name}` | processor `{processor_class_name}`."
            )
            self.skipTest(
                f"Test is known to fail for: model `{model_class.__name__}` | tokenizer `{tokenizer_class_name}` | processor `{processor_class_name}`."
            )

        validate_test_components(self, task_name, model, tokenizer, processor)
        if hasattr(model, "eval"):
            model = model.eval()

        task_test_instance = pipeline_test_mapping[task_name]["test"]()
        pipeline, examples = task_test_instance.get_test_pipeline(model, tokenizer, processor, torch_dtype=torch_dtype)
        if pipeline is None:
            logger.warning(
                f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{torch_dtype} is skipped: Could not get the "
                "pipeline for testing."
            )
            self.skipTest(reason="Could not get the pipeline for testing.")

        task_test_instance.run_pipeline_test(pipeline, examples)

        def run_batch_test(pipeline_obj, example_list):
            if pipeline_obj.tokenizer is not None and pipeline_obj.tokenizer.pad_token_id is None:
                return
            def generate_samples(n):
                for _ in range(n):
                    yield copy.deepcopy(random.choice(example_list))
            results = []
            for item in pipeline_obj(generate_samples(10), batch_size=4):
                results.append(item)
            self.assertEqual(len(results), 10)

        run_batch_test(pipeline, examples)

