import datasets as hf_datasets
import httpx
import huggingface_hub as hf_hub

from ajet.schema.task import Task
from ajet.task_reader.task_reader_base import BaseTaskReader


class HuggingFaceTaskReader(BaseTaskReader):
    """
    A task reader implementation for loading tasks from Hugging Face datasets.
    Supports specifying dataset path, name, and train/validation splits.
    """

    def __init__(self, config):
        super().__init__(config)
        self.config = config
        self.use_generator_mode = False
        self.dataset_source = self.config.huggingface_dat_repo.dataset_path

        # Extract dataset name with fallback handling
        try:
            self.dataset_id = self.config.huggingface_dat_repo.dataset_name
        except Exception:
            self.dataset_id = None

        # Proxy configuration (supports both 'http_proxy_address' and legacy 'http_proxy')
        try:
            proxy_endpoint = getattr(
                self.config.huggingface_dat_repo, "http_proxy_address", ""
            ) or getattr(self.config.huggingface_dat_repo, "http_proxy", "")
        except Exception:
            proxy_endpoint = ""

        # Apply proxy settings via set_client_factory (modern approach)
        if proxy_endpoint:
            huggingface_hub.set_client_factory(
                lambda **kw: httpx.Client(
                    proxy=proxy_endpoint,
                    **{key: val for key, val in kw.items() if key != "proxies"},
                )
            )

    def _fetch_dataset_partition(self, partition_name: str):
        """
        Retrieve a specific partition (split) of the dataset.

        Args:
            partition_name: Name of the split to load (e.g., 'train', 'dev')

        Returns:
            Generator yielding Task instances constructed from dataset rows.
        """
        try:
            if self.dataset_source.endswith(".parquet"):
                # Load directly from local Parquet file
                ds = hf_datasets.load_dataset(
                    "parquet", data_files=self.dataset_source, split=partition_name
                )
            else:
                ds = hf_datasets.load_dataset(
                    self.dataset_source, split=partition_name, name=self.dataset_id
                )

            # Add original index before shuffling
            ds = ds.map(lambda example, idx: {"original_index": idx}, with_indices=True)
            ds = ds.shuffle()
        except Exception as err:
            raise ValueError(
                f"Unable to load dataset '{self.dataset_source}' for split '{partition_name}': {str(err)}"
            )

        if len(ds) == 0:
            raise ValueError(f"No samples available in dataset '{self.dataset_source}' for split '{partition_name}'")

        self.use_generator_mode = True
        for _, sample in enumerate(ds):
            task = Task(
                main_query=sample.get("main_query", sample.get("question", "No content")),    # type: ignore
                init_messages=[],  # No initial messages expected in dataset examples
                task_id=str(sample["original_index"]),           # type: ignore
                env_type="no_env",
                metadata=sample,                                 # type: ignore
            )
            yield task
        return

    def produce_training_examples(self):
        """
        Yield training examples from the configured dataset split.

        Returns:
            Generator of Task objects for training.
        """
        split_label = self.config.huggingface_dat_repo.training_split
        return self._fetch_dataset_partition(split_label)

    def produce_validation_examples(self):
        """
        Yield validation examples from the configured dataset split.

        Returns:
            Generator of Task objects for validation.
        """
        split_label = self.config.huggingface_dat_repo.validation_split
        return self._fetch_dataset_partition(split_label)

    def collect_training_data(self):
        return list(self.produce_training_examples())

    def collect_validation_data(self):
        return list(self.produce_validation_examples())

