from graph_net.imp_util import load_module
import graph_net.graph_net_json_file_util as gn_json

class SymbolicDimensionUpdater:
    def __init__(self, settings):
        self.settings = self.configure_settings(**settings)

    def configure_settings(
        self,
        model_directory_prefix,
        factory_module_path,
        factory_class_name,
        factory_parameters=None,
        continue_execution=True,
    ):
        if factory_parameters is None:
            factory_parameters = {}
        return {
            "factory_module_path": factory_module_path,
            "factory_class_name": factory_class_name,
            "factory_parameters": factory_parameters,
            "model_directory_prefix": model_directory_prefix,
            "continue_execution": continue_execution,
        }

    def __call__(self, model_name):
        full_model_path = Path(self.settings["model_directory_prefix"]) / model_name
        model_path_str = str(full_model_path)
        constraint_file_path = full_model_path / "input_tensor_constraints.py"

        if not constraint_file_path.exists():
            return

        if self.settings["continue_execution"] and self._reification_already_done(model_path_str):
            return

        factory_class = self._load_factory_class()
        factory_instance = factory_class(
            config=self.settings["factory_parameters"], 
            model_path=model_path_str
        )

        selected_reifier = factory_instance.get_matched_reifier_name()
        if selected_reifier is None:
            return

        assert isinstance(selected_reifier, str), f"{type(selected_reifier)=}"

        gn_json.update_json(
            model_path_str, 
            gn_json.kSymbolicDimensionReifier, 
            selected_reifier
        )

    def _load_factory_class(self):
        loaded_module = load_module(self.settings["factory_module_path"])
        return getattr(loaded_module, self.settings["factory_class_name"])

    def _reification_already_done(self, model_location):
        json_data = gn_json.read_json(model_location)
        if gn_json.kSymbolicDimensionReifier not in json_data:
            return False
        return json_data[gn_json.kSymbolicDimensionReifier] is not None

# Canonical varint encoding/decoding for unsigned integers
_MAX_UNSIGNED_VARINT = (1 << 64) - 1

def encode_unsigned_varint(number: int) -> bytes:
    """Encode an unsigned integer into its canonical varint representation."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise ValueError("input must be an integer")
    if number < 0:
        raise ValueError("input must be non-negative")
    if number > _MAX_UNSIGNED_VARINT:
        raise ValueError("input must be <= 2^64-1")

    result = bytearray()
    while True:
        segment = number & 0x7F
        number >>= 7
        if number:
            result.append(segment | 0x80)
        else:
            result.append(segment)
            break
    return bytes(result)

def decode_unsigned_varint(buffer: bytes, offset: int) -> tuple[int, int]:
    """Decode a varint from the buffer starting at the given offset."""
    if offset < 0:
        raise ValueError("offset must be non-negative")

    decoded_value = 0
    bit_position = 0
    current_index = offset

    while True:
        if current_index >= len(buffer):
            raise ValueError("varint data is truncated")

        current_byte = buffer[current_index]
        data_bits = current_byte & 0x7F

        # Check for overflow in the final byte
        if bit_position == 63 and data_bits > 1:
            raise ValueError("varint value exceeds 64 bits")

        current_index += 1
        decoded_value |= data_bits << bit_position

        # Check if this is the last byte
        if current_byte & 0x80 == 0:
            # Verify canonical encoding
            if buffer[offset:current_index] != encode_unsigned_varint(decoded_value):
                raise ValueError("non-canonical varint encoding detected")
            return decoded_value, current_index

        bit_position += 7

        # Prevent infinite loop on malformed input
        if bit_position > 63:
            raise ValueError("varint too large")

# Modified version of the PDF field-filling script
import sys
import json
from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter

def populate_pdf_fields(input_file: str, fields_data_path: str, output_file: str):
    with open(fields_data_path) as file:
        fields = json.load(file)

    fields_by_page = {}
    for field in fields:
        if "value" in field:
            field_id = field["field_id"]
            page_num = field["page"]
            if page_num not in fields_by_page:
                fields_by_page[page_num] = {}
            fields_by_page[page_num][field_id] = field["value"]

    reader = PdfReader(input_file)
    has_error = False
    field_info_list = get_field_info(reader)
    fields_by_ids = {f["field_id"]: f for f in field_info_list}

    for field in fields:
        existing_field = fields_by_ids.get(field["field_id"])
        if not existing_field:
            has_error = True
            print(f"ERROR: `{field['field_id']}` is not a valid field ID")
        elif field["page"] != existing_field["page"]:
            has_error = True
            print(
                f"ERROR: Incorrect page number for `{field['field_id']}` (got {field['page']}, expected {existing_field['page']})"
            )
        else:
            if "value" in field:
                err_msg = validation_error_for_field_value(existing_field, field["value"])
                if err_msg:
                    print(err_msg)
                    has_error = True

    if has_error:
        sys.exit(1)

    writer = PdfWriter(clone_from=reader)
    for page, field_values in fields_by_page.items():
        writer.update_page_form_field_values(writer.pages[page - 1], field_values, auto_regenerate=False)

    writer.set_need_appearances_writer(True)
    with open(output_file, "wb") as out_file:
        writer.write(out_file)

def validation_error_for_field_value(field_info, field_value):
    field_type = field_info["type"]
    field_id = field_info["field_id"]

    if field_type == "checkbox":
        checked_val = field_info["checked_value"]
        unchecked_val = field_info["unchecked_value"]
        if field_value != checked_val and field_value != unchecked_val:
            return f'ERROR: Invalid value "{field_value}" for checkbox field "{field_id}". The checked value is "{checked_val}" and the unchecked value is "{unchecked_val}"'

    elif field_type == "radio_group":
        option_values = [opt["value"] for opt in field_info["radio_options"]]
        if field_value not in option_values:
            return f'ERROR: Invalid value "{field_value}" for radio group field "{field_id}". Valid values are: {option_values}'

    elif field_type == "choice":
        choice_values = [opt["value"] for opt in field_info["choice_options"]]
        if field_value not in choice_values:
            return (
                f'ERROR: Invalid value "{field_value}" for choice field "{field_id}". Valid values are: {choice_values}'
            )

    return None

def monkeypatch_pypdf_method():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject
    original_get_inherited = DictionaryObject.get_inherited

    def patched_get_inherited(self, key: str, default=None):
        result = original_get_inherited(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in result)
        ):
            result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = patched_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    monkeypatch_pypdf_method()
    input_pdf = sys.argv[1]
    fields_json = sys.argv[2]
    output_pdf = sys.argv[3]
    populate_pdf_fields(input_pdf, fields_json, output_pdf)

