import multiprocessing
import warnings
from multiprocessing import connection
from typing import Any, Callable, Optional, Union
import gym
import numpy as np
from libero.libero.envs import OffScreenRenderEnv
from rlinf.envs.venv import (
    BaseVectorEnv,
    CloudpickleWrapper,
    EnvWorker,
    ShArray,
    SubprocEnvWorker,
    SubprocVectorEnv,
    _setup_buf,
)

# Define step return types for different Gym versions
gym_old_venv_step_type = tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]
gym_new_venv_step_type = tuple[
    np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray
]

# Suppress repeated deprecation warnings
warnings.simplefilter("once", DeprecationWarning)

def _worker_process(
    parent_conn: connection.Connection,
    child_conn: connection.Connection,
    env_factory: CloudpickleWrapper,
    shared_buffers: Optional[Union[dict, tuple, ShArray]] = None,
) -> None:
    def _store_observation(
        obs_data: Union[dict, tuple, np.ndarray], buffer_data: Union[dict, tuple, ShArray]
    ) -> None:
        if isinstance(obs_data, np.ndarray) and isinstance(buffer_data, ShArray):
            buffer_data.save(obs_data)
        elif isinstance(obs_data, tuple) and isinstance(buffer_data, tuple):
            for o_part, b_part in zip(obs_data, buffer_data):
                _store_observation(o_part, b_part)
        elif isinstance(obs_data, dict) and isinstance(buffer_data, dict):
            for key in obs_data.keys():
                _store_observation(obs_data[key], buffer_data[key])
        return None

    # Close the parent end on the worker side
    parent_conn.close()

    # Instantiate the environment
    env = env_factory.data()

    try:
        while True:
            try:
                command, payload = child_conn.recv()
            except EOFError:
                child_conn.close()
                break

            if command == "step":
                result = env.step(payload)
                if shared_buffers is not None:
                    _store_observation(result[0], shared_buffers)
                    result = (None, *result[1:])
                child_conn.send(result)

            elif command == "reset":
                output = env.reset(**payload)
                has_info = (
                    isinstance(output, (tuple, list))
                    and len(output) == 2
                    and isinstance(output[1], dict)
                )
                if has_info:
                    obs, info_dict = output
                else:
                    obs = output

                if shared_buffers is not None:
                    _store_observation(obs, shared_buffers)
                    obs = None

                if has_info:
                    child_conn.send((obs, info_dict))
                else:
                    child_conn.send(obs)

            elif command == "close":
                child_conn.send(env.close())
                child_conn.close()
                break

            elif command == "render":
                rendered = env.render(**payload) if hasattr(env, "render") else None
                child_conn.send(rendered)

            elif command == "seed":
                if hasattr(env, "seed"):
                    child_conn.send(env.seed(payload))
                else:
                    env.reset(seed=payload)
                    child_conn.send(None)

            elif command == "getattr":
                value = getattr(env, payload) if hasattr(env, payload) else None
                child_conn.send(value)

            elif command == "setattr":
                setattr(env.unwrapped, payload["key"], payload["value"])

            elif command == "check_success":
                child_conn.send(env.check_success())

            elif command == "get_segmentation_of_interest":
                child_conn.send(env.get_segmentation_of_interest(payload))

            elif command == "get_sim_state":
                child_conn.send(env.get_sim_state())

            elif command == "set_init_state":
                obs_result = env.set_init_state(payload)
                child_conn.send(obs_result)

            elif command == "reconfigure":
                env.close()
                seed_value = payload.pop("seed")
                env = OffScreenRenderEnv(**payload)
                env.seed(seed_value)
                child_conn.send(None)

            else:
                child_conn.close()
                raise NotImplementedError

    except KeyboardInterrupt:
        child_conn.close()

class CustomReconfigureSubprocWorker(SubprocEnvWorker):
    def __init__(self, env_fn: Callable[[], gym.Env], use_shared_memory: bool = False):
        ctx = multiprocessing.get_context("spawn")
        self.parent_pipe, self.child_pipe = ctx.Pipe()
        self.use_shared_memory = use_shared_memory
        self.memory_buffer: Optional[Union[dict, tuple, ShArray]] = None

        if self.use_shared_memory:
            temp_env = env_fn()
            observation_space = temp_env.observation_space
            temp_env.close()
            del temp_env
            self.memory_buffer = _setup_buf(observation_space)

        args = (
            self.parent_pipe,
            self.child_pipe,
            CloudpickleWrapper(env_fn),
            self.memory_buffer,
        )
        self.worker_process = ctx.Process(target=_worker_process, args=args, daemon=True)
        self.worker_process.start()
        self.child_pipe.close()
        EnvWorker.__init__(self, env_fn)

    def update_environment(self, new_env_params):
        self.parent_pipe.send(["reconfigure", new_env_params])
        return self.parent_pipe.recv()

class CustomReconfigureSubprocVectorEnv(SubprocVectorEnv):
    def __init__(self, env_functions: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def make_worker(fn: Callable[[], gym.Env]) -> CustomReconfigureSubprocWorker:
            return CustomReconfigureSubprocWorker(fn, use_shared_memory=False)
        BaseVectorEnv.__init__(self, env_functions, make_worker, **kwargs)

    def update_environments(self, env_functions_list, indices=None):
        self._assert_is_not_closed()
        indices = self._wrap_id(indices)
        if self.is_async:
            self._assert_id(indices)
        for idx, i in enumerate(indices):
            self.workers[i].update_environment(env_functions_list[idx])

# Calculate total memory usage and related utilities for TPU inference
import time
from collections import defaultdict
from collections.abc import Sequence
from functools import wraps
from typing import Any, Callable, List, Tuple, Union
import jax
import jax.numpy as jnp
import numpy as np
import torch
from jax._src import dtypes
from jax._src import mesh as mesh_lib
from jax._src import xla_bridge as xb
from jax._src.lib import xla_client as xc
from jax._src.numpy.scalar_types import _ScalarMeta
from jax.sharding import Mesh, NamedSharding, PartitionSpec
from torchax.ops.mappings import j2t_dtype, t2j_dtype
from vllm import envs as vllm_envs
from vllm import utils
from tpu_inference import envs
from tpu_inference.logger import init_logger

GBYTES = 1024 * 1024 * 1024
TPU_HEAD_SIZE_ALIGNMENT = 128
TPU_SECOND_LAST_MINOR = 8

# Mapping from string aliases to JAX dtypes
_DTYPE_STR_ALIAS_TO_JAX_DTYPE = {
    "fp8": jnp.float8_e4m3fn.dtype,
    "fp8_e4m3": jnp.float8_e4m3fn.dtype,
    "fp8_e5m2": jnp.float8_e5m2.dtype,
    "fp4": jnp.float4_e2m1fn.dtype,
}

def convert_to_jax_dtype(dtype: str | jnp.dtype | torch.dtype) -> jnp.dtype:
    if isinstance(dtype, (str, type)):
        if isinstance(dtype, str) and (mapped_dtype :=
                                       _DTYPE_STR_ALIAS_TO_JAX_DTYPE.get(
                                           dtype, None)):
            return mapped_dtype
        return jnp.dtype(dtype)
    elif isinstance(dtype, torch.dtype):
        return t2j_dtype(dtype)
    elif isinstance(dtype, jnp.dtype):
        return dtype
    elif isinstance(dtype, _ScalarMeta):
        return dtype.dtype
    else:
        raise ValueError(f"Unsupported data type {type(dtype)}")

def convert_to_torch_dtype(dtype: str | jnp.dtype | torch.dtype) -> torch.dtype:
    # Convert via JAX dtype as intermediate representation
    dtype = convert_to_jax_dtype(dtype)
    return j2t_dtype(dtype)

_megacore_enabled = False
logger = init_logger(__name__)

def align_dimension(size: int, alignment: int) -> int:
    return (size + alignment - 1) // alignment * alignment

def activate_megacore() -> None:
    global _megacore_enabled
    _megacore_enabled = True

def is_megacore_active() -> bool:
    return _megacore_enabled

def compute_kv_heads(num_kv_heads: int, tensor_parallel_size: int) -> int:
    if tensor_parallel_size <= num_kv_heads:
        assert num_kv_heads % tensor_parallel_size == 0
        return num_kv_heads
    else:
        assert tensor_parallel_size % num_kv_heads == 0
        return tensor_parallel_size

def get_hbm_usage(devices: Any) -> List[Tuple[int, int]]:
    usage_records = []
    if vllm_envs.VLLM_TPU_USING_PATHWAYS:
        return pathways_memory_stats(devices)

    multihost_backend = envs.TPU_MULTIHOST_BACKEND
    if multihost_backend == "ray":
        for device in devices:
            try:
                stats = device.memory_stats()
                used_bytes = stats["bytes_in_use"]
                limit_bytes = stats["bytes_limit"]
                logger.info(
                    "Retrieved memory stats for device %s. Assuming uniform usage across all devices.",
                    device)
                usage_records.extend([(used_bytes, limit_bytes)] * len(devices))
                break
            except Exception as e:
                logger.warning(
                    "Failed to retrieve memory stats for device %s: %s", device,
                    e)
    else:
        for device in devices:
            stats = device.memory_stats()
            used_bytes = stats["bytes_in_use"]
            limit_bytes = stats["bytes_limit"]
            usage_records.append((used_bytes, limit_bytes))
    return usage_records

def identify_device_type(num_devices: int | None = None):
    kind = jax.devices()[0].device_kind
    if 'TPU' not in kind:
        raise RuntimeError('Expected TPU devices')
    suffix = ''
    if kind.endswith(' lite'):
        kind = kind[:-len(' lite')]
        suffix = 'e'
    elif kind.endswith('e'):
        kind = kind[:-1]
        suffix = 'e'
    elif kind.endswith('p'):
        kind = kind[:-1]
        suffix = 'p'
    elif kind == 'TPU7x':
        kind = 'TPU v7'
    assert kind[:-1] == 'TPU v', kind
    kind += suffix
    if num_devices is not None:
        kind += f'-{num_devices}'
    return kind

def get_hbm_capacity() -> int:
    device_type = identify_device_type()
    if device_type == "TPU v5p" or device_type == "TPU v5":
        return 95 * GBYTES
    elif device_type == "TPU v5e":
        return 16 * GBYTES
    elif device_type == "TPU v6e" or device_type == "TPU v4":
        return 32 * GBYTES
    elif device_type == "TPU v7":
        return 96 * GBYTES
    else:
        raise ValueError(f"Unknown device type: {device_type}")

def pathways_memory_stats(devices: Any) -> List[Tuple[float, float]]:
    live_arrays = jax.live_arrays()
    memory_used = defaultdict(int)
    memory_capacity = get_hbm_capacity()
    tracked_buffers = set()
    for array in live_arrays:
        for shard in array.addressable_shards:
            buffer_id = id(shard.data)
            if buffer_id not in tracked_buffers:
                tracked_buffers.add(buffer_id)
                memory_used[shard.data.device] += shard.data.nbytes
    return [(memory_used[device], memory_capacity) for device in devices]

def get_hbm_usage_gb(devices: Any) -> List[Tuple[float, float]]:
    raw_usage = get_hbm_usage(devices)
    return [(round(used / GBYTES, 2), round(limit / GBYTES, 2))
             for used, limit in raw_usage]

def pad_head_dimension(head_dim: int) -> int:
    """Round head_dim up to nearest multiple of 128 for kernel optimization."""
    if head_dim == 64:
        return 64
    return (head_dim + 127) // 128 * 128

def adjust_num_heads_for_sharding(num_heads: int, sharding_factor: int) -> int:
    if num_heads >= sharding_factor:
        assert num_heads % sharding_factor == 0
    else:
        assert sharding_factor % num_heads == 0
        num_heads = sharding_factor
    return num_heads

def compute_packing_factor(dtype):
    bits_per_element = dtypes.itemsize_bits(dtype)
    return 32 // bits_per_element

def create_optimized_mesh(axis_dimensions: Sequence[int],
                          axis_labels: Sequence[str],
                          *,
                          hardware_devices: Sequence[xc.Device] | None = None):
    if hardware_devices is None:
        hardware_devices = xb.devices()
    hardware_devices = sorted(hardware_devices, key=lambda x: x.coords)

    def is_one_dimensional(dimensions):
        return sum(d > 1 for d in dimensions) == 1

    if is_one_dimensional(axis_dimensions):
        device_category = hardware_devices[0].device_kind
        device_count = len(hardware_devices)
        if device_category == "TPU v6 lite":
            ordered_devices = None
            if device_count == 8:
                ordered_devices = np.array([
                    hardware_devices[0],
                    hardware_devices[1],
                    hardware_devices[2],
                    hardware_devices[3],
                    hardware_devices[7],
                    hardware_devices[6],
                    hardware_devices[5],
                    hardware_devices[4],
                ])
            elif device_count == 4:
                ordered_devices = np.array([
                    hardware_devices[0],
                    hardware_devices[1],
                    hardware_devices[3],
                    hardware_devices[2],
                ])
            if ordered_devices is not None:
                ordered_devices = ordered_devices.reshape(axis_dimensions)
                mesh = mesh_lib.Mesh(ordered_devices, axis_labels)
                logger.info("Using custom mesh configuration: %s", mesh)
                return mesh

    try:
        return jax.make_mesh(axis_dimensions, axis_labels, devices=hardware_devices)
    except (AssertionError, ValueError, RuntimeError) as e:
        logger.warning(
            "jax.make_mesh failed due to topology constraints. Falling back to manual mesh: %s",
            e)
        ordered_devices = np.array(hardware_devices).reshape(axis_dimensions)
        return mesh_lib.Mesh(ordered_devices, axis_labels)

def allocate_on_device(mesh: Mesh, *args, sharding=None, **kwargs) -> jax.Array:
    """
    Create a device array with the specified mesh and sharding.
    Args:
        mesh: The JAX mesh for device placement
        *args: Positional arguments for jax.device_put
        sharding: Optional sharding specification; defaults to PartitionSpec(None)
        **kwargs: Keyword arguments for jax.device_put
    Returns:
        A JAX array placed on the specified devices
    """
    if sharding is None:
        sharding = NamedSharding(mesh, PartitionSpec(None))
    return jax.device_put(*args, device=sharding, **kwargs)

def resolve_hash_function(hash_name: str) -> Callable[[Any], bytes]:
    """
    Wrapper around vllm.utils.hashing.get_hash_fn_by_name with built-in support.
    """
    if hash_name == "builtin":
        return hash
    return utils.hashing.get_hash_fn_by_name(hash_name)

def extract_jax_dtype_from_string(string_dtype: str) -> jnp.dtype:
    """
    Get the JAX dtype from a string dtype.
    Args:
        string_dtype: The string dtype to convert.
    Returns:
        jnp.dtype: The corresponding JAX dtype.
    """
    return convert_to_jax_dtype(string_dtype)

def compute_mesh_product(
    mesh: Mesh,
    axes: Union[str, list[str], None],
) -> int:
    """
    Compute the product of mesh dimensions for one or more axes.
    Examples:
        # Single axis (defaults to 1 if not present)
        compute_mesh_product(mesh, "model")
        # Multiple axes - computes product of their sizes
        compute_mesh_product(mesh, ["model", "attn_dp"])
        # None means no sharding on this dimension
        compute_mesh_product(mesh, None)  # returns 1
    """
    if axes is None:
        return 1
    if isinstance(axes, str):
        axes = [axes]
    product = 1
    for axis in axes:
        product *= mesh.shape.get(axis, 1)
    return product

def timed_execution(func):
    """
    Decorator to measure and log function execution time.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.perf_counter()
        result = func(*args, **kwargs)
        end_time = time.perf_counter()
        duration = end_time - start_time
        logger.debug(
            f"Function '{func.__name__}' completed in {duration:.4f} seconds."
        )
        return result
    return wrapper

import importlib.metadata
from typing import TYPE_CHECKING
from packaging import version
from .base import HfQuantizer

if TYPE_CHECKING:
    from ..modeling_utils import PreTrainedModel

from ..utils import is_accelerate_available, is_auto_awq_available, is_torch_available, logging
from ..utils.quantization_config import AWQLinearVersion

if is_torch_available():
    import torch

logger = logging.get_logger(__name__)

class AwqQuantizer(HfQuantizer):
    """
    4-bit quantization for Activation-aware Weight Quantization(AWQ) (https://arxiv.org/abs/2306.00978)
    """
    # AWQ requires data calibration - we support only inference
    requires_calibration = True
    required_packages = ["awq", "accelerate"]

    def __init__(self, quantization_config, **kwargs):
        super().__init__(quantization_config, **kwargs)

    def validate_environment(self, device_map, **kwargs):
        if not torch.cuda.is_available():
            raise RuntimeError("A CUDA-compatible GPU is required to run AWQ quantized models.")

        if not is_auto_awq_available():
            raise ImportError("Loading an AWQ quantized model requires the auto-awq library (`pip install autoawq`)")

        if not is_accelerate_available():
            raise ImportError("Loading an AWQ quantized model requires accelerate (`pip install accelerate`)")

        if device_map is None:
            logger.warning_once(
                "You have loaded an AWQ model on CPU while a CUDA device is available. "
                "For optimal performance, please move your model to a GPU device."
            )
        elif device_map is not None:
            if isinstance(device_map, dict) and ("cpu" in device_map.values() or "disk" in device_map.values()):
                raise ValueError(
                    "AWQ models do not support loading with CPU or disk devices in the device_map. "
                    "Please remove these devices from your configuration."
                )

    def update_torch_dtype(self, torch_dtype):
        if torch_dtype is None:
            torch_dtype = torch.float16
        elif torch_dtype != torch.float16:
            logger.warning("For improved efficiency with AWQ, we recommend setting `torch_dtype=torch.float16`.")
        return torch_dtype

    def _process_model_before_weight_loading(self, model: "PreTrainedModel", **kwargs):
        from ..integrations import get_keys_to_not_convert, replace_quantization_scales, replace_with_awq_linear

        self.modules_to_not_convert = get_keys_to_not_convert(model)

        if self.quantization_config.modules_to_not_convert is not None:
            self.modules_to_not_convert.extend(self.quantization_config.modules_to_not_convert)

        model, has_been_replaced = replace_with_awq_linear(
            model, quantization_config=self.quantization_config, modules_to_not_convert=self.modules_to_not_convert
        )

        model = replace_quantization_scales(model, model.config.model_type)

        if not has_been_replaced:
            logger.warning(
                "You are loading an AWQ model but no linear layers were detected in the model architecture. "
                "Please verify your model structure, or report this issue on GitHub if you believe it's unexpected."
            )

    def _process_model_after_weight_loading(self, model):
        if self.quantization_config.do_fuse:
            from ..integrations import fuse_awq_modules
            model = fuse_awq_modules(model, self.quantization_config)
            model._awq_is_fused = True  # TODO: consider storing this flag in model.config instead

        if self.quantization_config.version == AWQLinearVersion.EXLLAMA:
            from ..integrations import post_init_awq_exllama_modules
            model = post_init_awq_exllama_modules(model, self.quantization_config.exllama_config)

    @property
    def is_serializable(self):
        # AWQ through auto-awq has been always serializable, except if the model is fused.
        if self.quantization_config.do_fuse:
            logger.warning("Saving an AWQ model that uses fused modules is not supported!")
            return False

        if self.quantization_config.version == AWQLinearVersion.EXLLAMA:
            logger.warning("Saving an AWQ model using the Exllama backend is not supported!")
            return False

        return True

    @property
    def is_trainable(self):
        # AWQ supports PEFT fine-tuning starting from version 0.2.0
        MIN_AWQ_VERSION_FOR_PEFT = "0.2.0"
        return version.parse(importlib.metadata.version("autoawq")) >= version.parse(MIN_AWQ_VERSION_FOR_PEFT)

import torch
