# Check if the device is Gaudi2
is_hpu_gaudi2 = htexp._get_device_type() == htexp.synDeviceType.synDeviceGaudi2

def get_hpu_gaudi2_scale_factor():
    # Ratio of maximum representable values between float8_e4m3fn and float8_e4m3fnuz
    return (torch.finfo(torch.float8_e4m3fn).max / torch.finfo(torch.float8_e4m3fnuz).max)

# Exponent width for different data types
EXP_WIDTH = {
    torch.float32: 8,
    torch.bfloat16: 8,
    torch.float8_e4m3fn: 4,
    torch.float8_e5m2: 5,
}

def get_default_exp_bias(dtype):
    exp_width = EXP_WIDTH[dtype]
    return 2**(exp_width - 1) - 1

# Supported exponent bias sets per device and dtype
EXP_BIAS_SETS = {
    ("GAUDI2", torch.float8_e4m3fn): [3, 7, 11, 15],
    ("GAUDI2", torch.float8_e5m2): [15],
    ("GAUDI3", torch.float8_e4m3fn): range(0, 63),
    ("GAUDI3", torch.float8_e5m2): range(0, 63),
}

# Maximum representable range for each dtype
MAX_RANGE = {
    torch.float32: torch.finfo(torch.float32).max,
    torch.bfloat16: torch.finfo(torch.bfloat16).max,
    torch.float8_e4m3fn: torch.finfo(torch.float8_e4m3fn).max,
    torch.float8_e5m2: torch.finfo(torch.float8_e5m2).max
}

# Attempt to add float8_e4m3fnuz max range (only available on Gaudi2)
try:
    MAX_RANGE[torch.float8_e4m3fnuz] = torch.finfo(torch.float8_e4m3fnuz).max
except AttributeError:
    pass

def get_fullscale(dtype, device, exp_bias=None):
    default_exp_bias = get_default_exp_bias(dtype)
    fullscale = 1.0

    # Special handling for GAUDI2 with float8_e4m3fn
    if device == "GAUDI2" and dtype == torch.float8_e4m3fn:
        try:
            fullscale = MAX_RANGE[torch.float8_e4m3fnuz]
        except KeyError:
            pass
    else:
        fullscale = MAX_RANGE[dtype]

    # Adjust by exponent bias if provided
    current_exp_bias = default_exp_bias if exp_bias is None else exp_bias
    fullscale = fullscale * (2**(default_exp_bias - current_exp_bias))
    return float(fullscale)

def get_fullscales_by_expbias_set(dtype, device, expbias_set):
    return [get_fullscale(dtype, device, exp_bias=eb) for eb in expbias_set]

def get_fp8_hw_alligned_scales(dtype, device):
    exp_bias_set = EXP_BIAS_SETS.get((device, dtype), None)
    if exp_bias_set is None:
        return None
    base_fullscale = get_fullscale(dtype, device)
    return [x / base_fullscale for x in get_fullscales_by_expbias_set(dtype, device, exp_bias_set)]

# Device-specific scale factors
DEVICES_SCALE_FACTORS = {
    "GAUDI2": 4,
    "GAUDI3": 1,
}

# Precompute FP8 scales aligned to hardware constraints
FP8_143_SCALES = {
    device: get_fp8_hw_alligned_scales(torch.float8_e4m3fn, device)
    for device in DEVICES_SCALE_FACTORS.keys()
}

# Store min, max, and scale factor traits per device
FP8_143_SCALES_TRAITS = {
    device: (
        min(FP8_143_SCALES[device]),
        max(FP8_143_SCALES[device]),
        DEVICES_SCALE_FACTORS[device],
    )
    for device in DEVICES_SCALE_FACTORS.keys()
}

class ScaleToPow2:
    def calc(self, scale):
        # Compute the next power of two >= scale
        scale_pow2 = 2.0**torch.ceil(torch.log2(scale))
        return scale_pow2

class ConvertScaleToHwAligned:
    def __init__(self, device_type="GAUDI3"):
        self.device_type = "GAUDI2" if is_hpu_gaudi2 else "GAUDI3"

    def calc(self, scale):
        # Apply Gaudi2 scaling factor if needed
        if self.device_type == "GAUDI2":
            scale = scale * get_hpu_gaudi2_scale_factor()

        # Round to nearest power of two
        scale_pow2 = ScaleToPow2().calc(scale)

        # Get hardware constraints
        min_scale, max_scale, scale_factor = FP8_143_SCALES_TRAITS[self.device_type]

        # Clamp and align to hardware grid
        log2_scale = torch.ceil(torch.log2(scale_pow2) / scale_factor) * scale_factor
        aligned_scale = 2.0**log2_scale

        # Enforce bounds
        aligned_scale = torch.minimum(
            torch.maximum(aligned_scale, torch.tensor(min_scale, dtype=scale.dtype, device=scale.device)),
            torch.tensor(max_scale, dtype=scale.dtype, device=scale.device),
        )
        return aligned_scale

# Modified version of Run class with renamed variables and reordered statements
import uuid
from datetime import UTC, datetime
from alphatrion.runtime.contextvars import current_run_id
from alphatrion.runtime.runtime import global_runtime
from alphatrion.storage.sql_models import Status
from alphatrion.types import CallableEntry

class Execution:
    __slots__ = ("_identifier", "_coroutine", "_runtime_instance", "_experiment_id", "_output")

    def __init__(self, exp_id: uuid.UUID):
        self._runtime_instance = global_runtime()
        self._experiment_id = exp_id
        self._output = None
        self._identifier = None
        self._coroutine = None

    @property
    def identifier(self) -> uuid.UUID:
        return self._identifier

    @property
    def output(self) -> any:
        return self._output

    def _fetch_record(self):
        return self._runtime_instance.metadb.get_run(run_id=self._identifier)

    def execute(self, func_entry: CallableEntry) -> None:
        self._identifier = self._runtime_instance.metadb.create_run(
            team_id=self._runtime_instance.team_id,
            user_id=self._runtime_instance.user_id,
            experiment_id=self._experiment_id,
            status=Status.RUNNING,
        )

        # Set context variable for tracing workflow/task decorators
        # Sequential execution ensures safe context management
        context_token = current_run_id.set(self.identifier)
        try:
            # Task inherits current context including run/experiment IDs
            self._coroutine = asyncio.create_task(func_entry())
        finally:
            current_run_id.reset(context_token)

    def complete(self):
        # Ensure status isn't updated if already cancelled
        if self.cancelled():
            return

        record = self._runtime_instance._metadb.get_run(run_id=self.identifier)
        elapsed_time = (
            datetime.now(UTC) - record.created_at.replace(tzinfo=UTC)
        ).total_seconds()

        self._runtime_instance.metadb.update_run(
            run_id=self._identifier, 
            status=Status.COMPLETED, 
            duration=elapsed_time
        )
        self._output = self._coroutine.result()

    def abort(self):
        # Note: Should wait for actual cancellation and handle CancelledError
        self._coroutine.cancel()

        record = self._runtime_instance._metadb.get_run(run_id=self.identifier)
        elapsed_time = (
            datetime.now(UTC) - record.created_at.replace(tzinfo=UTC)
        ).total_seconds()

        self._runtime_instance.metadb.update_run(
            run_id=self._identifier, 
            status=Status.CANCELLED, 
            duration=elapsed_time
        )

    def is_cancelled(self) -> bool:
        return self._coroutine.cancelled()

    async def await_completion(self):
        await self._coroutine

    def register_completion_handler(self, handler: callable):
        self._coroutine.add_done_callback(handler)

# Modified version of ConcretePass with renamed variables and reordered logic
import torch.fx as fx
from graph_net.torch.dim_gen_passes import DimensionGeneralizationPass
from collections import namedtuple
import os

class RenamedConcretePass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    @classmethod
    def get_pass_name(cls) -> str:
        return os.path.basename(__file__)[:-3]

    def should_transform(self, traced_module: fx.GraphModule) -> bool:
        # Skip if batch dimension is present
        if 0 in self.axes:
            return False
        return any(self._requires_transformation(node) for node in traced_module.graph.nodes)

    def target_function(self):
        return torch.full

    def _requires_transformation(self, node) -> bool:
        if node.op != "call_function":
            return False
        if node.target != self.target_function():
            return False
        if len(node.args) != 1:
            return False
        return any(dimension == self.dim for dimension in node.args[0])

    def transform(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Build new computation graph
        updated_graph = fx.Graph()
        node_mapping = {}

        NodeDimension = namedtuple("NodeDimension", ["node", "shape_axis"])
        current_node_dim = None

        def update_current_node_dimension(original_node, transformed_node):
            nonlocal current_node_dim
            tensor_meta = original_node.meta.get("tensor_meta")
            if tensor_meta is None:
                return
            if not hasattr(tensor_meta, "shape"):
                return
            for idx, dim_size in enumerate(tensor_meta.shape):
                if not (dim_size == self.dim and idx > 0):
                    continue
                current_node_dim = NodeDimension(node=transformed_node, shape_axis=idx)
                return

        def compute_new_dimension(index, dim_value):
            if dim_value != self.dim:
                return node_mapping[dim_value] if dim_value in node_mapping else dim_value
            assert dim_value == self.dim
            # Get dynamic size using the size() method
            size_node = updated_graph.call_method(
                "size", args=(current_node_dim.node, current_node_dim.shape_axis)
            )
            return size_node

        def build_transformed_node(original_node):
            if not (self._requires_transformation(original_node) and current_node_dim is not None):
                # Copy unchanged nodes to new graph
                transformed_node = updated_graph.node_copy(original_node, lambda x: node_mapping[x])
                update_current_node_dimension(original_node=original_node, transformed_node=transformed_node)
                return transformed_node

            new_dims = tuple(
                compute_new_dimension(i, dim_val) for i, dim_val in enumerate(original_node.args[0])
            )
            transformed_node = updated_graph.call_function(
                self.target_function(), args=(new_dims,), kwargs=original_node.kwargs
            )
            return transformed_node

        for original_node in traced_module.graph.nodes:
            node_mapping[original_node] = build_transformed_node(original_node)

        # Replace original graph with transformed graph
        traced_module.graph = updated_graph
        traced_module.recompile()
        return traced_module

# Modified version with Type I clone transformations
from skylos.cli import _emit_github_annotations  
import io
import sys

def _capture_annotations(result):
    original_stdout = sys.stdout
    sys.stdout = buffer = io.StringIO()
    _emit_github_annotations(result)
    sys.stdout = original_stdout
    return buffer.getvalue().strip().splitlines()

class TestGitHubAnnotations:
    def test_danger_findings(self):
        scan_result = {
            "danger": [
                {
                    "rule_id": "SKY-D211",
                    "severity": "HIGH",
                    "file": "app.py",
                    "line": 10,
                    "message": "SQL injection detected",
                }
            ],
        }
        output_lines = _capture_annotations(scan_result)
        assert len(output_lines) == 1
        expected_annotation = "::error file=app.py,line=10,title=Skylos SKY-D211::SQL injection detected"
        assert output_lines[0] == expected_annotation

    def test_severity_mapping(self):
        scan_result = {
            "quality": [
                {
                    "rule_id": "SKY-Q301",
                    "severity": "MEDIUM",
                    "file": "a.py",
                    "line": 5,
                    "message": "Complex",
                },
                {
                    "rule_id": "SKY-Q302",
                    "severity": "LOW",
                    "file": "b.py",
                    "line": 8,
                    "message": "Long func",
                },
            ],
        }
        output_lines = _capture_annotations(scan_result)
        assert "::warning" in output_lines[0]
        assert "::notice" in output_lines[1]

    def test_dead_code_annotations(self):
        scan_result = {
            "unused_functions": [
                {"name": "old_func", "file": "app.py", "line": 42},
            ],
            "unused_imports": [
                {"name": "os", "file": "app.py", "line": 1},
            ],
        }
        output_lines = _capture_annotations(scan_result)
        assert len(output_lines) == 2
        assert "::warning" in output_lines[0]
        assert "Unused function: old_func" in output_lines[0]
        assert "Unused import: os" in output_lines[1]

    def test_empty_result(self):
        scan_result = {}
        output_lines = _capture_annotations(scan_result)
        assert output_lines == [""] or output_lines == []

    def test_mixed_categories(self):
        scan_result = {
            "danger": [
                {
                    "rule_id": "SKY-D201",
                    "severity": "CRITICAL",
                    "file": "x.py",
                    "line": 1,
                    "message": "eval",
                },
            ],
            "secrets": [
                {
                    "rule_id": "SKY-S101",
                    "severity": "HIGH",
                    "file": "y.py",
                    "line": 2,
                    "message": "API key",
                },
            ],
            "unused_classes": [
                {"name": "OldClass", "file": "z.py", "line": 3},
            ],
        }
        output_lines = _capture_annotations(scan_result)
        assert len(output_lines) == 3
        # CRITICAL maps to error
        assert lines[0].startswith("::error") if len(lines := output_lines) > 0 else True
        assert lines[1].startswith("::error") if len(lines) > 1 else True  # HIGH -> error
        assert "Unused class: OldClass" in lines[2] if len(lines) > 2 else False

import importlib.metadata
import logging
import os
import pathlib
import sys
import zipfile
import zipimport
from typing import Iterator, List, Optional, Sequence, Set, Tuple
from pip._vendor.packaging.utils import NormalizedName, canonicalize_name
from pip._internal.metadata.base import BaseDistribution, BaseEnvironment
from pip._internal.models.wheel import Wheel
from pip._internal.utils.deprecation import deprecated
from pip._internal.utils.filetypes import WHEEL_EXTENSION
from ._compat import BadMetadata, BasePath, get_dist_name, get_info_location
from ._dists import Distribution
logger = logging.getLogger(__name__)

def _looks_like_wheel(path: str) -> bool:
    if not path.endswith(WHEEL_EXTENSION):
        return False
    if not os.path.isfile(path):
        return False
    if not Wheel.wheel_file_re.match(os.path.basename(path)):
        return False
    return zipfile.is_zipfile(path)

class _DistributionFinder:
    """Finder to locate distributions.
    The main purpose of this class is to memoize found distributions' names, so
    only one distribution is returned for each package name. At lot of pip code
    assumes this (because it is setuptools's behavior), and not doing the same
    can potentially cause a distribution in lower precedence path to override a
    higher precedence one if the caller is not careful.
    Eventually we probably want to make it possible to see lower precedence
    installations as well. It's useful feature, after all.
    """
    FoundResult = Tuple[importlib.metadata.Distribution, Optional[BasePath]]
    def __init__(self) -> None:
        self._seen_names: Set[NormalizedName] = set()

    def _search_impl(self, location: str) -> Iterator[FoundResult]:
        """Find distributions in a location."""
        # Skip looking inside a wheel. Since a package inside a wheel is not
        # always valid (due to .data directories etc.), its .dist-info entry
        # should not be considered an installed distribution.
        if _looks_like_wheel(location):
            return
        # To know exactly where we find a distribution, we have to feed in the
        # paths one by one, instead of dumping the list to importlib.metadata.
        for dist in importlib.metadata.distributions(path=[location]):
            info_location = get_info_location(dist)
            try:
                raw_name = get_dist_name(dist)
            except BadMetadata as e:
                logger.warning("Skipping %s due to %s", info_location, e.reason)
                continue
            normalized_name = canonicalize_name(raw_name)
            if normalized_name in self._seen_names:
                continue
            self._seen_names.add(normalized_name)
            yield dist, info_location

    def locate(self, location: str) -> Iterator[BaseDistribution]:
        """Find distributions in a location.
        The path can be either a directory, or a ZIP archive.
        """
        for dist, info_location in self._search_impl(location):
            if info_location is None:
                installed_location: Optional[BasePath] = None
            else:
                installed_location = info_location.parent
            yield Distribution(dist, info_location, installed_location)

    def locate_via_link(self, location: str) -> Iterator[BaseDistribution]:
        """Read location in egg-link files and return distributions in there.
        The path should be a directory; otherwise this returns nothing. This
        follows how setuptools does this for compatibility. The first non-empty
        line in the egg-link is read as a path (resolved against the egg-link's
        containing directory if relative). Distributions found at that linked
        location are returned.
        """
        path = pathlib.Path(location)
        if not path.is_dir():
            return
        for child in path.iterdir():
            if child.suffix != ".egg-link":
                continue
            with child.open() as f:
                lines = (line.strip() for line in f)
                target_rel = next((line for line in lines if line), "")
            if not target_rel:
                continue
            target_location = str(path.joinpath(target_rel))
            for dist, info_location in self._search_impl(target_location):
                yield Distribution(dist, info_location, path)

    def _locate_eggs_in_directory(self, location: str) -> Iterator[BaseDistribution]:
        from pip._vendor.pkg_resources import find_distributions
        from pip._internal.metadata import pkg_resources as legacy
        with os.scandir(location) as it:
            for entry in it:
                if not entry.name.endswith(".egg"):
                    continue
                for dist in find_distributions(entry.path):
                    yield legacy.Distribution(dist)

    def _locate_eggs_in_archive(self, location: str) -> Iterator[BaseDistribution]:
        from pip._vendor.pkg_resources import find_eggs_in_zip
        from pip._internal.metadata import pkg_resources as legacy
        try:
            importer = zipimport.zipimporter(location)
        except zipimport.ZipImportError:
            return
        for dist in find_eggs_in_zip(importer, location):
            yield legacy.Distribution(dist)

    def locate_eggs(self, location: str) -> Iterator[BaseDistribution]:
        """Find eggs in a location.
        This actually uses the old *pkg_resources* backend. We likely want to
        deprecate this so we can eventually remove the *pkg_resources*
        dependency entirely. Before that, this should first emit a deprecation
        warning for some versions when using the fallback since importing
        *pkg_resources* is slow for those who don't need it.
        """
        if os.path.isdir(location):
            yield from self._locate_eggs_in_directory(location)
        if zipfile.is_zipfile(location):
            yield from self._locate_eggs_in_archive(location)

@functools.lru_cache(maxsize=None)  # Warn a distribution exactly once.
def _warn_about_egg_loading(location: Optional[str]) -> None:
    deprecated(
        reason=f"Loading egg at {location} is deprecated.",
        replacement="to use pip for package installation.",
        gone_in="24.3",
        issue=12330,
    )

class Environment(BaseEnvironment):
    def __init__(self, paths: Sequence[str]) -> None:
        self._search_paths = paths

    @classmethod
    def default(cls) -> BaseEnvironment:
        return cls(sys.path)

    @classmethod
    def create_from_paths(cls, paths: Optional[List[str]]) -> BaseEnvironment:
        if paths is None:
            return cls(sys.path)
        return cls(paths)

    def _iter_all_distributions(self) -> Iterator[BaseDistribution]:
        finder = _DistributionFinder()
        for location in self._search_paths:
            yield from finder.locate(location)
            for dist in finder.locate_eggs(location):
                _warn_about_egg_loading(dist.location)
                yield dist
            # This must go last because that's how pkg_resources tie-breaks.
            yield from finder.locate_via_link(location)

    def get_package(self, name: str) -> Optional[BaseDistribution]:
        matches = (
            distribution
            for distribution in self.iter_all_distributions()
            if distribution.canonical_name == canonicalize_name(name)
        )
        return next(matches, None)

# Certificate Auto-Renewal Service
# Automatically renews certificates before they expire.
"""
from datetime import datetime, timedelta
from models import db, Certificate, CA, SystemConfig, AuditLog
from services.ca_service import CAService
import logging
logger = logging.getLogger(__name__)

class AutoRenewalService:
    """Service for automatic certificate renewal"""

    @staticmethod
    def get_renewal_config():
        """Get auto-renewal configuration"""
        config = {
            'enabled': False,
            'days_before_expiry': 30,
            'renewal_sources': ['scep', 'acme', 'est'],  # Which sources to auto-renew
            'notify_on_renewal': True,
            'notify_on_failure': True,
        }

        enabled = SystemConfig.query.filter_by(key='auto_renewal_enabled').first()
        if enabled:
            config['enabled'] = enabled.value == 'true'

        days = SystemConfig.query.filter_by(key='auto_renewal_days').first()
        if days:
            config['days_before_expiry'] = int(days.value)

        sources = SystemConfig.query.filter_by(key='auto_renewal_sources').first()
        if sources:
            import json
            config['renewal_sources'] = json.loads(sources.value)

        return config

    @staticmethod
    def set_renewal_config(config: dict):
        """Update auto-renewal configuration"""
        import json

        for key, value in config.items():
            db_key = f'auto_renewal_{key}'
            if key == 'enabled':
                db_value = 'true' if value else 'false'
            elif key == 'renewal_sources':
                db_value = json.dumps(value)
            else:
                db_value = str(value)

            existing = SystemConfig.query.filter_by(key=db_key).first()
            if existing:
                existing.value = db_value
            else:
                db.session.add(SystemConfig(key=db_key, value=db_value))

        db.session.commit()

    @staticmethod
    def get_certificates_for_renewal():
        """Get certificates eligible for auto-renewal"""
        config = AutoRenewalService.get_renewal_config()
        if not config['enabled']:
            return []

        threshold = datetime.utcnow() + timedelta(days=config['days_before_expiry'])

        certs = Certificate.query.filter(
            Certificate.status.in_(['valid', 'active']),
            Certificate.not_after != None,
            Certificate.not_after <= threshold,
            Certificate.source.in_(config['renewal_sources'])
        ).all()

        return certs

    @staticmethod
    def renew_certificate(cert: Certificate) -> tuple:
        """
        Renew a single certificate.

        Returns:
            (success: bool, new_cert_id or error_message: int|str)
        """
        try:
            # Get the CA that issued this certificate
            ca = CA.query.filter_by(id=cert.ca_id).first()
            if not ca:
                return False, "Issuing CA not found"

            # Check CA is still valid
            if ca.not_after and ca.not_after < datetime.utcnow():
                return False, "Issuing CA has expired"

            # Calculate new validity (same as original or default)
            if cert.not_before and cert.not_after:
                original_days = (cert.not_after - cert.not_before).days
            else:
                original_days = 365

            # Re-issue with same subject and SANs
            from cryptography import x509
            from cryptography.hazmat.backends import default_backend

            if cert.csr:
                # Re-sign original CSR
                import base64
                csr_pem = base64.b64decode(cert.csr).decode()
                csr = x509.load_pem_x509_csr(csr_pem.encode(), default_backend())
            else:
                # Can't renew without CSR
                return False, "Original CSR not available for renewal"

            # Sign with new validity
            new_cert_pem, serial = CAService.sign_csr_from_crypto(
                ca=ca,
                csr=csr,
                validity_days=original_days,
                source=f'{cert.source}-renewal'
            )

            # Get new certificate ID
            new_cert = Certificate.query.filter_by(serial_number=serial).first()

            # Mark old certificate as superseded (not revoked)
            cert.status = 'superseded'
            cert.superseded_by = new_cert.id if new_cert else None

            # Audit log
            log = AuditLog(
                action='certificate.auto_renewed',
                resource_type='certificate',
                resource_id=new_cert.id if new_cert else None,
                resource_name=cert.common_name,
                details=f'Auto-renewed cert {cert.id}, new cert {new_cert.id if new_cert else "unknown"}'
            )
            db.session.add(log)
            db.session.commit()

            logger.info(f"Auto-renewed certificate {cert.id} -> {new_cert.id if new_cert else 'unknown'}")
            return True, new_cert.id if new_cert else 0

        except Exception as e:
            logger.error(f"Auto-renewal failed for cert {cert.id}: {e}")
            return False, str(e)

    @staticmethod
    def run_auto_renewal():
        """
        Run auto-renewal for all eligible certificates.
        This is called by the scheduler service.
        """
        config = AutoRenewalService.get_renewal_config()
        if not config['enabled']:
            logger.debug("Auto-renewal is disabled")
            return {'renewed': 0, 'failed': 0, 'skipped': 0}

        certs = AutoRenewalService.get_certificates_for_renewal()

        stats = {'renewed': 0, 'failed': 0, 'skipped': 0, 'errors': []}

        for cert in certs:
            # Skip if already being processed
            if cert.status == 'renewing':
                stats['skipped'] += 1
                continue

            # Mark as renewing to prevent concurrent renewal
            cert.status = 'renewing'
            db.session.commit()

            success, result = AutoRenewalService.renew_certificate(cert)

            if success:
                stats['renewed'] += 1
            else:
                stats['failed'] += 1
                stats['errors'].append({
                    'cert_id': cert.id,
                    'common_name': cert.common_name,
                    'error': result
                })
                # Restore status on failure
                cert.status = 'valid'
                db.session.commit()

        logger.info(f"Auto-renewal complete: {stats['renewed']} renewed, {stats['failed']} failed")

        # Send notifications if configured
        if config.get('notify_on_renewal') and stats['renewed'] > 0:
            AutoRenewalService._send_renewal_notification(stats)

        if config.get('notify_on_failure') and stats['failed'] > 0:
            AutoRenewalService._send_failure_notification(stats)

        return stats

    @staticmethod
    def _send_renewal_notification(stats: dict):
        """Send notification about successful renewals"""
        from services.email_service import EmailService

        recipients = SystemConfig.query.filter_by(key='auto_renewal_notify_emails').first()
        if not recipients:
            return

        import json
        emails = json.loads(recipients.value)

        for email in emails:
            try:
                EmailService.send_email(
                    to=email,
                    subject=f'UCM: {stats["renewed"]} certificates auto-renewed',
                    body=f'The following {stats["renewed"]} certificates were automatically renewed.',
                    html=f'<p>The following {stats["renewed"]} certificates were automatically renewed.</p>'
                )
            except Exception as e:
                logger.error(f"Failed to send renewal notification: {e}")

    @staticmethod
    def _send_failure_notification(stats: dict):
        """Send notification about failed renewals"""
        from services.email_service import EmailService

        recipients = SystemConfig.query.filter_by(key='auto_renewal_notify_emails').first()
        if not recipients:
            return

        import json
        emails = json.loads(recipients.value)

        error_list = '\n'.join([
            f"- {e['common_name']} (ID: {e['cert_id']}): {e['error']}"
            for e in stats.get('errors', [])
        ])

        for email in emails:
            try:
                EmailService.send_email(
                    to=email,
                    subject=f'UCM: {stats["failed"]} certificate renewals FAILED',
                    body=f'The following certificate renewals failed:\n\n{error_list}',
                    html=f'<p>The following certificate renewals failed:</p><pre>{error_list}</pre>'
                )
            except Exception as e:
                logger.error(f"Failed to send failure notification: {e}")

# Scheduler task function
def run_auto_renewal_task():
    """Scheduled task for auto-renewal"""
    return AutoRenewalService.run_auto_renewal()

