import logging
import numbers
from typing import Dict

def format_log_string(metrics: Dict, current_step):
    # Initialize the log message with the current step
    log_parts = [f"step:{current_step}"]

    # Iterate through all key-value pairs in the metrics dictionary
    for key, value in metrics.items():
        # Only include numeric values with 3 decimal places
        if isinstance(value, numbers.Number):
            log_parts.append(f"{key}:{value:.3f}")

    # Join all parts with " - " separator
    return " - ".join(log_parts)

class CustomLogger:
    def __init__(self, show_on_console: bool = True):
        self.display_to_terminal = show_on_console
        self.logger = logging.getLogger(self.__class__.__name__)

    def flush(self):
        """Flush method for compatibility with LoggerProtocol."""
        pass

    def record(self, metrics_data, iteration):
        if self.display_to_terminal:
            formatted_message = format_log_string(metrics_data, step=iteration)
            self.logger.info(formatted_message)

    def finalize(self, status_code: int = 0) -> None:
        """Finish method for compatibility with LoggerProtocol."""
        pass

