class DefaultSavePlanner(SavePlanner):
    mappings: FLATTEN_MAPPING

    def __init__(
        self,
        flatten_state_dict: bool = True,
        flatten_sharded_tensors: bool = True,
        dedup_replicated_tensors: Optional[bool] = None,
        dedup_save_to_lowest_rank: bool = False,
        enable_plan_caching: bool = False,
    ) -> None:
        self.flatten_state_dict = flatten_state_dict
        self.flatten_sharded_tensors = flatten_sharded_tensors
        self.mappings = {}
        self.dedup_save_to_lowest_rank = dedup_save_to_lowest_rank
        if dedup_replicated_tensors is not None:
            logger.warning(
                "DefaultSavePlanner's `dedup_replicated_tensors` argument is being "
                "deprecated, and no longer has any effect. Please remove this argument "
                "from your call."
            )
        self._cached_plans_key: str = self.__class__.__name__
        self._enable_plan_caching = enable_plan_caching

    def set_up_planner(
        self,
        state_dict: STATE_DICT_TYPE,
        storage_meta: Optional[StorageMeta] = None,
        is_coordinator: bool = False,
    ) -> None:
        if self.flatten_state_dict:
            state_dict, self.mappings = flatten_state_dict(state_dict)
        if self.flatten_sharded_tensors:
            state_dict = _flatten_sharded_tensors(state_dict)
        self.state_dict = state_dict
        self.is_coordinator = is_coordinator

    def create_local_plan(self) -> SavePlan:
        plan = create_default_local_save_plan(self.state_dict, self.is_coordinator)
        if self.flatten_state_dict:
            plan = dataclasses.replace(plan, planner_data=self.mappings)
        self.plan = plan
        if self._enable_plan_caching:
            if self._cached_plans_key in SavePlanner._cached_save_plan and _compare_save_plans(
                plan, SavePlanner._cached_save_plan[self._cached_plans_key]
            ):
                logger.info("No change in the local plan. Skipping sending the plan to the coordinator")
                return SavePlan([], usable=False)
            else:
                SavePlanner._cached_save_plan[self._cached_plans_key] = plan
        return self.plan

    def _dedup_save_plans(self, all_plans: list[SavePlan]) -> list[SavePlan]:
        return dedup_save_plans(all_plans, self.dedup_save_to_lowest_rank)

    def _create_global_plan(self, all_plans: list[SavePlan]) -> tuple[list[SavePlan], Metadata]:
        deduped_plans = self._dedup_save_plans(all_plans)
        global_plan, metadata = create_default_global_save_plan(deduped_plans)
        if self.flatten_state_dict:
            planner_data_dict = [p.planner_data for p in global_plan]
            merged_mappings = dict(ChainMap(*planner_data_dict))
            metadata = dataclasses.replace(metadata, planner_data=merged_mappings)
        if not _validate_global_plan(global_plan, metadata):
            raise ValueError("Failed to validate global plan")
        return global_plan, metadata

    def _create_global_plan_with_caching(
        self, all_plans: list[SavePlan]
    ) -> tuple[list[SavePlan], list[SavePlan], Metadata]:
        global_plan_delta: list[SavePlan] = []
        if self._cached_plans_key not in SavePlanner._cached_all_plans:
            SavePlanner._cached_all_plans[self._cached_plans_key] = all_plans
            global_plan, metadata = self._create_global_plan(all_plans)
            SavePlanner._cached_global_plan[self._cached_plans_key] = global_plan
            SavePlanner._cached_metadata[self._cached_plans_key] = metadata
            return global_plan, global_plan, metadata

        if not _contains_usable_plan(all_plans):
            global_plan_delta = [SavePlan([], usable=False)] * len(all_plans)
            global_plan = SavePlanner._cached_global_plan[self._cached_plans_key]
            metadata = SavePlanner._cached_metadata[self._cached_plans_key]
        else:
            merged_plans = _merge_delta_local_plans(SavePlanner._cached_all_plans[self._cached_plans_key], all_plans)
            SavePlanner._cached_all_plans[self._cached_plans_key] = merged_plans
            global_plan, metadata = self._create_global_plan(merged_plans)
            if self._cached_plans_key in self._cached_global_plan:
                for cached_plan, new_plan in zip(SavePlanner._cached_global_plan[self._cached_plans_key], global_plan):
                    if _compare_save_plans(cached_plan, new_plan):
                        global_plan_delta.append(SavePlan([], usable=False))
                    else:
                        global_plan_delta.append(new_plan)
            SavePlanner._cached_global_plan[self._cached_plans_key] = global_plan
            SavePlanner._cached_metadata[self._cached_plans_key] = metadata
        return global_plan_delta, global_plan, metadata

    def create_global_plan(self, all_plans: list[SavePlan]) -> tuple[list[SavePlan], Metadata]:
        global_plan_delta: list[SavePlan] = []
        if self._enable_plan_caching:
            (
                global_plan_delta,
                global_plan,
                metadata,
            ) = self._create_global_plan_with_caching(all_plans)
        else:
            global_plan, metadata = self._create_global_plan(all_plans)
            global_plan_delta = global_plan
        self.global_plan = global_plan
        self.metadata = metadata
        return global_plan_delta, self.metadata

    def _finish_plan_with_caching(self, new_plan: SavePlan) -> SavePlan:
        finished_plan: SavePlan = new_plan
        if not new_plan.usable:
            finished_plan = SavePlanner._cached_final_save_plan[self._cached_plans_key]
        else:
            finished_plan = new_plan
            SavePlanner._cached_final_save_plan[self._cached_plans_key] = new_plan
        return finished_plan

    def finish_plan(self, new_plan: SavePlan) -> SavePlan:
        finished_plan: SavePlan = new_plan
        if self._enable_plan_caching:
            finished_plan = self._finish_plan_with_caching(new_plan)
        self.plan = finished_plan
        return self.plan

    def resolve_data(self, write_item: WriteItem) -> Union[torch.Tensor, io.BytesIO]:
        obj = self.lookup_object(write_item.index)
        return self.transform_object(write_item, obj)

    def lookup_object(self, index: MetadataIndex) -> Any:
        return find_state_dict_object(self.state_dict, index)

    def transform_object(self, write_item: WriteItem, obj: Any):
        if write_item.type == WriteItemType.BYTE_IO:
            bytes_io = io.BytesIO()
            torch.save(obj, bytes_io)
            obj = bytes_io
        return obj


class DefaultLoadPlanner(LoadPlanner):
    original_state_dict: STATE_DICT_TYPE
    mappings: FLATTEN_MAPPING

    def __init__(
        self,
        flatten_state_dict: bool = True,
        flatten_sharded_tensors: bool = True,
        allow_partial_load: bool = False,
    ) -> None:
        self.flatten_state_dict = flatten_state_dict
        self.flatten_sharded_tensors = flatten_sharded_tensors
        self.original_state_dict = {}
        self.mappings = {}
        self.allow_partial_load = allow_partial_load

    def set_up_planner(
        self,
        state_dict: STATE_DICT_TYPE,
        metadata: Optional[Metadata] = None,
        is_coordinator: bool = False,
    ) -> None:
        _init_state_dict(state_dict)
        self.original_state_dict = state_dict
        if self.flatten_sharded_tensors:
            state_dict = _flatten_sharded_tensors(state_dict)
        if self.flatten_state_dict:
            state_dict, self.mappings = flatten_state_dict(state_dict)
        self.state_dict = state_dict
        self.metadata = metadata
        self.is_coordinator = is_coordinator

    def create_local_plan(self) -> LoadPlan:
        assert self.metadata is not None
        if self.flatten_state_dict:
            current_keys = set(self.state_dict.keys())
            load_keys = set(self.metadata.state_dict_metadata.keys())
            missing_keys = load_keys - current_keys
            if missing_keys:
                _version._derived_version = "2_3"
                old_state_dict, old_mappings = flatten_state_dict(self.original_state_dict)
                old_keys = set(old_state_dict.keys())
                if old_keys & missing_keys:
                    self.state_dict, self.mappings = old_state_dict, old_mappings
                _version._derived_version = None
        return create_default_local_load_plan(self.state_dict, self.metadata, not self.allow_partial_load)

    def create_global_plan(self, global_plan: list[LoadPlan]) -> list[LoadPlan]:
        return create_default_global_load_plan(global_plan)

    def finish_plan(self, new_plan: LoadPlan) -> LoadPlan:
        return new_plan

    def load_bytes(self, read_item: ReadItem, value: io.BytesIO) -> None:
        if self.flatten_state_dict:
            set_element(
                self.original_state_dict,
                self.mappings[read_item.dest_index.fqn],
                torch.load(value, weights_only=False),
            )
        else:
            self.state_dict[read_item.dest_index.fqn] = torch.load(value, weights_only=False)

    def resolve_tensor(self, read_item: ReadItem):
        tensor = self.lookup_tensor(read_item.dest_index)
        return self.transform_tensor(read_item, tensor)

    def commit_tensor(self, read_item: ReadItem, tensor: torch.Tensor) -> None:
        pass

    def lookup_tensor(self, index: MetadataIndex) -> torch.Tensor:
        return find_state_dict_object(self.state_dict, index)

    def transform_tensor(self, read_item: ReadItem, tensor: torch.Tensor):
        return narrow_tensor_by_index(tensor, read_item.dest_offsets, read_item.lengths)


class _EmptyStateDictLoadPlanner(DefaultLoadPlanner):
    def __init__(self, keys=None, *args, **kwargs):
        self.keys = keys
        super().__init__(*args, **kwargs)

    def _should_include_key(self, key: str, metadata: Metadata) -> bool:
        if self.keys is None:
            return True
        if key in self.keys:
            return True
        unflattened_keys: list[str] = []
        planner_data = metadata.planner_data.get(key)
        for unflattened_key in planner_data:
            if unflattened_keys:
                unflattened_keys.append(".".join([unflattened_keys[-1], str(unflattened_key)]))
            else:
                unflattened_keys.append(unflattened_key)
        if any(unflattened_key in self.keys for unflattened_key in unflattened_keys):
            return True
        return False

    def set_up_planner(
        self,
        state_dict: STATE_DICT_TYPE,
        metadata: Optional[Metadata] = None,
        is_coordinator: bool = False,
    ) -> None:
        assert not state_dict
        assert metadata is not None
        for k, v in metadata.state_dict_metadata.items():
            if not self._should_include_key(k, metadata):
                continue
            if isinstance(v, TensorStorageMetadata):
                v = torch.empty(v.size, dtype=v.properties.dtype)
            if metadata.planner_data is not None and k in metadata.planner_data:
                set_element(state_dict, metadata.planner_data[k], v)
            else:
                state_dict[k] = v
        super().set_up_planner(state_dict, metadata, is_coordinator)


def create_default_local_load_plan(state_dict: dict[str, Any], metadata: Metadata, strict: bool = True) -> LoadPlan:
    requests = []
    for fqn, obj in state_dict.items():
        if fqn not in metadata.state_dict_metadata:
            if strict:
                raise RuntimeError(f"Missing key in checkpoint state_dict: {fqn}.")
            else:
                continue
        md = metadata.state_dict_metadata[fqn]
        if isinstance(md, TensorStorageMetadata) and getattr(obj, "size", None) is not None and md.size != obj.size():
            raise ValueError(
                f"Size mismatch between saved {md.size} and current: {obj.size()} for {fqn}",
            )
        if isinstance(obj, DTensor):
            if obj.device_mesh.get_coordinate() is not None:
                requests += _create_read_items(fqn, md, obj)
        else:
            requests += _create_read_items(fqn, md, obj)
    return LoadPlan(requests)


def create_default_global_load_plan(
    all_plans: list[LoadPlan],
) -> list[LoadPlan]:
    return all_plans


def create_default_local_save_plan(state_dict: dict[str, Any], is_coordinator: bool) -> SavePlan:
    requests = []
    for fqn, obj in state_dict.items():
        if isinstance(obj, DTensor):
            if obj.device_mesh.get_coordinate() is not None:
                requests += _create_write_items(fqn, obj)
        else:
            requests += _create_write_items(fqn, obj)
    return SavePlan(requests)


def create_default_global_save_plan(
    all_plans: list[SavePlan],
    rewrite_index_hints: bool = True,
) -> tuple[list[SavePlan], Metadata]:
    md: dict[str, STORAGE_TYPES] = {}
    new_plans = []
    for plan in all_plans:
        new_items = []
        for item in plan.items:
            if not item.type == WriteItemType.SHARD:
                assert item.index.fqn not in md
            if item.type == WriteItemType.BYTE_IO:
                md[item.index.fqn] = BytesStorageMetadata()
                new_items.append(item)
            else:
                assert item.tensor_data is not None
                tensor_md = cast(
                    TensorStorageMetadata,
                    md.setdefault(
                        item.index.fqn,
                        TensorStorageMetadata(
                            properties=item.tensor_data.properties,
                            size=item.tensor_data.size,
                            chunks=[],
                        ),
                    ),
                )
                new_item = item
                if rewrite_index_hints:
                    new_index = dataclasses.replace(item.index, index=len(tensor_md.chunks))
                    new_item = dataclasses.replace(item, index=new_index)
                new_items.append(new_item)
                assert item.tensor_data.chunk is not None, f"""
                    Cannot create MD for tensor without bounds.
                    FQN: {item.index.fqn}
                """
                tensor_md.chunks.append(item.tensor_data.chunk)
        new_plans.append(dataclasses.replace(plan, items=new_items))
    return (new_plans, Metadata(md))


def _create_default_local_metadata(state_dict: STATE_DICT_TYPE) -> Metadata:
    plan = _create_default_metadata_only_plan(state_dict)
    _, md = create_default_global_save_plan([plan])
    return md


def _check_box_overlap(box0: ChunkStorageMetadata, box1: ChunkStorageMetadata) -> bool:
    ndims = len(box0.offsets)
    for i in range(ndims):
        if box0.offsets[i] >= box1.offsets[i] + box1.sizes[i]:
            return False
        if box1.offsets[i] >= box0.offsets[i] + box0.sizes[i]:
            return False
    return True


def _check_box_bounds(outer_box_size: torch.Size, inner_box: ChunkStorageMetadata) -> bool:
    for i in range(len(outer_box_size)):
        if inner_box.offsets[i] < 0:
            return False
        if inner_box.sizes[i] < 0:
            return False
        if inner_box.offsets[i] + inner_box.sizes[i] > outer_box_size[i]:
            return False
    return True


def _validate_global_plan(global_plan: list[SavePlan], metadata: Metadata) -> bool:
    all_good = True
    for key, value in metadata.state_dict_metadata.items():
        if isinstance(value, BytesStorageMetadata):
            continue
        if len(value.size) == 0:
            continue
        chunks_volume = 0
        for chunk_idx, chunk0 in enumerate(value.chunks):
            if not _check_box_bounds(value.size, chunk0):
                logger.warning(
                    """
                        key:%s has out of bounds chunk:
                        tensor-size:%s chunk: %s
                    """,
                    key,
                    value.size,
                    chunk0,
                )
                all_good = False
            chunks_volume += reduce(operator.mul, chunk0.sizes, 1)
            for chunk1 in value.chunks[chunk_idx + 1 :]:
                if _check_box_overlap(chunk0, chunk1):
                    logger.warning("key:%s has overlapping chunks: %s %s", key, chunk0, chunk1)
                    all_good = False
        tensor_volume = reduce(operator.mul, value.size, 1)
        if chunks_volume != tensor_volume:
            logger.warning(
                """
                    key:%s invalid fill tensor-volume:
                    %s chunks-volume: %s
                """,
                key,
                tensor_volume,
                chunks_volume,
            )
            all_good = False
    return all_good

# Custom tool registry implementation based on MutableMapping
from collections.abc import MutableMapping
from typing import Annotated, Any, Generic, Literal, TypeVar
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes

class ToolRegistry(MutableMapping):
    def __init__(self) -> None:
        self._registry: dict[ToolTypes, type[StatGptTool]] = {}

    def __setitem__(self, tool_type: ToolTypes, factory: type['StatGptTool']) -> None:
        if not issubclass(factory, StatGptTool):
            raise ValueError(f"{factory=} must inherit from {StatGptTool}")
        if tool_type in self._registry:
            raise ValueError(
                f"Cannot register {factory}: "
                f"{tool_type=} already registered with {self._registry[tool_type]}"
            )
        self._registry[tool_type] = factory

    def __delitem__(self, tool_type: ToolTypes, /) -> None:
        del self._registry[tool_type]

    def __getitem__(self, key: ToolTypes) -> type['StatGptTool']:
        if key not in self._registry:
            raise KeyError(
                f"No factory registered for {key}. "
                f"Ensure the factory is imported at module level.\n"
                f"Available tools: {list(self._registry.keys())}"
            )
        return self._registry[key]

    def __iter__(self):
        return iter(self._registry)

    def __len__(self):
        return len(self._registry)

_TOOL_REGISTRY = ToolRegistry()

class ToolInputs(BaseModel):
    # injected argument - populated internally, not by LLM
    # excluded from schema visible to LLM
    context: Annotated[dict, InjectedToolArg] = Field(default_factory=dict)

ConfigType = TypeVar('ConfigType', bound=BaseToolConfig)

class StatGptTool(BaseTool, ABC, Generic[ConfigType]):
    response_mode: Literal['content', 'content_and_artifact'] = "content_and_artifact"
    category: ToolTypes  # Assigned dynamically via __init_subclass__

    def __init_subclass__(cls, **kwargs):
        category = kwargs.pop('category', None)
        super().__init_subclass__(**kwargs)

        if StatGptTool in cls.__bases__:
            # Skip registration for abstract base class itself
            return

        if category is None:
            raise ValueError(f"Subclass {cls.__name__} requires a 'category' parameter")

        if not isinstance(category, ToolTypes):
            raise ValueError(f"{category=} must be an instance of {ToolTypes}")

        cls.category = category
        _TOOL_REGISTRY[category] = cls

    def __init__(self, config: ConfigType, channel: ChannelConfig, **kwargs):
        super().__init__(**kwargs)
        self._config = config
        self._channel = channel

    @property
    def step_label(self) -> str:
        """Return the label for this tool's execution stage."""
        if name := self._config.details.stages_config.tool_call_name:
            return name
        formatted_name = self.name.replace('_', ' ')
        return f"Executing {formatted_name} tool"

    @property
    def result_label(self) -> str:
        """Return the label for displaying the tool's result."""
        if name := self._config.details.stages_config.tool_result_name:
            return name
        formatted_name = self.name.replace('_', ' ')
        return f"Output from {formatted_name} tool"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """Synchronous method placeholder - intentionally not implemented."""
        raise NotImplementedError("Use the asynchronous version instead.")

    @abstractmethod
    async def execute(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        pass

    @classmethod
    def get_input_schema(cls, config: ConfigType) -> type[ToolInputs]:
        """Return the input schema for this tool."""
        return ToolInputs

    @staticmethod
    def create_from_config(config: ConfigType, channel: ChannelConfig) -> 'StatGptTool':
        tool_class = _TOOL_REGISTRY[config.type]
        return tool_class(
            config=config,
            channel=channel,
            name=config.name,
            description=config.description,
            args_schema=tool_class.get_input_schema(config),
        )

import importlib.util
import json
import os
import warnings
from dataclasses import dataclass, field
import torch
from ..training_args import TrainingArguments
from ..utils import cached_property, is_sagemaker_dp_enabled, logging

logger = logging.get_logger(__name__)

# TODO: should be moved to `utils` after refactoring of SageMakerTrainer
def check_sagemaker_model_parallel():
    # Retrieve sagemaker-specific model parallel parameters from environment variable
    mp_config = os.getenv("SM_HP_MP_PARAMETERS", "{}")
    try:
        # Parse the JSON and verify presence of required 'partitions' field
        mp_config = json.loads(mp_config)
        if "partitions" not in mp_config:
            return False
    except json.JSONDecodeError:
        return False

    # Retrieve sagemaker-specific framework parameters
    fw_params = os.getenv("SM_FRAMEWORK_PARAMS", "{}")
    try:
        # Parse and check for MPI enablement flag
        fw_params = json.loads(fw_params)
        if not fw_params.get("sagemaker_mpi_enabled", False):
            return False
    except json.JSONDecodeError:
        return False

    # Confirm availability of the smdistributed package
    return importlib.util.find_spec("smdistributed") is not None

if check_sagemaker_model_parallel():
    import smdistributed.modelparallel.torch as smp
    smp.init()

@dataclass
class SageMakerTrainingArguments(TrainingArguments):
    mp_parameters: str = field(
        default="",
        metadata={"help": "Used by the SageMaker launcher to send mp-specific args. Ignored in SageMakerTrainer"},
    )

    def __post_init__(self):
        super().__post_init__()
        warnings.warn(
            "`SageMakerTrainingArguments` is deprecated and will be removed in v5 of Transformers. You can use "
            "`TrainingArguments` instead.",
            FutureWarning,
        )

    @cached_property
    def _setup_devices(self) -> "torch.device":
        logger.info("PyTorch: setting up devices")

        # Check for existing distributed setup with inconsistent local_rank
        if torch.distributed.is_available() and torch.distributed.is_initialized() and self.local_rank == -1:
            logger.warning(
                "torch.distributed process group is initialized, but local_rank == -1. "
                "In order to use Torch DDP, launch your script with `python -m torch.distributed.launch"
            )

        # CPU-only mode
        if self.no_cuda:
            device = torch.device("cpu")
            self._n_gpu = 0
        elif check_sagemaker_model_parallel():
            # Model parallel setup
            local_rank = smp.local_rank()
            device = torch.device("cuda", local_rank)
            self._n_gpu = 1
        elif is_sagemaker_dp_enabled():
            # Distributed data parallel setup
            import smdistributed.dataparallel.torch.torch_smddp  # noqa: F401
            torch.distributed.init_process_group(backend="smddp", timeout=self.ddp_timeout_delta)
            self.local_rank = int(os.getenv("SMDATAPARALLEL_LOCAL_RANK"))
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1
        elif self.local_rank == -1:
            # Single/multi-GPU without distributed training
            device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
            self._n_gpu = torch.cuda.device_count()
        else:
            # Standard distributed training setup
            if not torch.distributed.is_initialized():
                torch.distributed.init_process_group(backend="nccl", timeout=self.ddp_timeout_delta)
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1

        # Set current CUDA device if available
        if device.type == "cuda":
            torch.cuda.set_device(device)
        return device

    @property
    def world_size(self):
        if check_sagemaker_model_parallel():
            return smp.dp_size()
        return super().world_size

    @property
    def place_model_on_device(self):
        return not check_sagemaker_model_parallel()

    @property
    def _no_sync_in_gradient_accumulation(self):
        return False

# Modified version: renamed variables, reordered statements, changed literals
import select as _select_module
import sys as _sys_module
from functools import partial as _partial
try:
    from time import monotonic as _monotonic_time
except ImportError:
    from time import time as _monotonic_time

__all__ = ["SocketWaitUnavailableError", "await_socket_readable", "await_socket_writable"]

class SocketWaitUnavailableError(Exception):
    pass

def _handle_interruptible_operation(func, timeout_val):
    if _sys_module.version_info >= (3, 5):
        return func(timeout_val)
    else:
        end_time = float("inf") if timeout_val is None else (_monotonic_time() + timeout_val)
        while True:
            try:
                return func(timeout_val)
            except (_sys_module.exc_info()[0].__class__, _select_module.error) as err:
                if hasattr(err, 'args') and len(err.args) > 0 and err.args[0] != 4:  # errno.EINTR == 4
                    raise
                else:
                    remaining = end_time - _monotonic_time()
                    timeout_val = max(0.0, remaining) if remaining != float("inf") else None
                    continue

def _select_based_wait(sock_obj, check_read=False, check_write=False, limit_timeout=None):
    if not check_read and not check_write:
        raise RuntimeError("specify at least one condition: read or write")
    read_list = []
    write_list = []
    if check_read:
        read_list.append(sock_obj)
    if check_write:
        write_list.append(sock_obj)

    operation = _partial(_select_module.select, read_list, write_list, write_list)
    ready_r, ready_w, exceptional = _handle_interruptible_operation(operation, limit_timeout)
    return bool(ready_r or ready_w or exceptional)

def _poll_based_wait(sock_obj, check_read=False, check_write=False, limit_timeout=None):
    if not check_read and not check_write:
        raise RuntimeError("specify at least one condition: read or write")
    event_mask = 0
    if check_read:
        event_mask |= _select_module.POLLIN
    if check_write:
        event_mask |= _select_module.POLLOUT

    poller = _select_module.poll()
    poller.register(sock_obj, event_mask)

    def execute_poll(timeout_sec):
        adjusted_timeout = None if timeout_sec is None else timeout_sec * 1000
        return poller.poll(adjusted_timeout)

    result = _handle_interruptible_operation(execute_poll, limit_timeout)
    return bool(result)

def _unavailable_wait(*args, **kwargs):
    raise SocketWaitUnavailableError("no suitable waiting mechanism found")

def _detect_working_poll_support():
    try:
        test_poller = _select_module.poll()
        _handle_interruptible_operation(test_poller.poll, 0)
    except (AttributeError, OSError):
        return False
    else:
        return True

def wait_for_socket_event(*args, **kwargs):
    global wait_for_socket_event
    if _detect_working_poll_support():
        wait_for_socket_event = _poll_based_wait
    elif hasattr(_select_module, "select"):
        wait_for_socket_event = _select_based_wait
    else:
        wait_for_socket_event = _unavailable_wait
    return wait_for_socket_event(*args, **kwargs)

def await_socket_readable(socket_obj, timeout=None):
    """Waits until data can be read from the socket.
    Returns True when readable, False on timeout."""
    return wait_for_socket_event(socket_obj, check_read=True, limit_timeout=timeout)

def await_socket_writable(socket_obj, timeout=None):
    """Waits until the socket is ready for writing.
    Returns True when writable, False on timeout."""
    return wait_for_socket_event(socket_obj, check_write=True, limit_timeout=timeout)

# JAX embedding layer with quantization support
from typing import Optional
import jax
from flax import nnx
from tpu_inference.layers.jax import JaxModule
from tpu_inference.layers.jax.quantization import QuantizeMethodBase
from tpu_inference.layers.jax.quantization.configs import QuantizationConfig

class JaxEmbedding(nnx.Embed, JaxModule):
    """Embedding implementation for JAX with optional quantization."""
    def __init__(self,
                 *args,
                 quant_config: Optional[QuantizationConfig] = None,
                 module_name: str = "",
                 **kwargs):
        nnx.Embed.__init__(self, *args, **kwargs)
        # Maintain compatibility with HuggingFace models by aliasing embedding to weight
        self.weight = self.embedding
        delattr(self, 'embedding')

        # Set sharding metadata if available
        if hasattr(self.weight, "out_sharding"):
            self.weight.set_metadata('sharding', self.weight.out_sharding)

        self.quantizer = None
        if quant_config is not None:
            quant_method = quant_config.get_quant_method(self, prefix=module_name)
            if quant_method is not None:
                self.quantizer = quant_method
                assert isinstance(quant_method, QuantizeMethodBase)
                quant_method.create_weights_jax(self)

    def __getattr__(self, attr_name: str):
        if attr_name == "embedding":
            # Required by nnx.Embed for internal access
            return self.weight

    def __call__(self, input_ids) -> jax.Array:
        if self.quantizer is None:
            return super().__call__(input_ids)
        return self.quantizer.apply_jax(self, input_ids)

    def decode(self, hidden_states: jax.Array) -> jax.Array:
        return jax.numpy.dot(hidden_states, self.weight.value.T)

