# Add a new bot configuration via CLI
from storage.entity.dto import BotConfig
from storage.service import bot_config as bot_service
from storage.service.user import get_cli_user_id
import click

@click.command('add')
@click.argument('name')
@click.option('--model', '-m', required=True, help='Model name')
@click.option('--api-key', '-k', default='', help='API key')
@click.option('--base-url', '-u', default=None, help='Base URL')
@click.option('--api-type', '-t', default=None, help='API type (e.g. anthropic)')
@click.option('--force', '-f', is_flag=True, help='Overwrite without confirmation')
def bot_add(name, model, api_key, base_url, api_type, force):
    """Add a new bot configuration."""
    user_id = get_cli_user_id()
    current_configs = bot_service.list_configs(user_id)
    if any(cfg.name == name for cfg in current_configs):
        if not force and not click.confirm(f"Bot '{name}' already exists. Overwrite?"):
            click.echo("Operation cancelled")
            return
    default_settings = bot_service.default_config
    if base_url is None:
        base_url = default_settings.base_url
    new_config = BotConfig(name=name, api_key=api_key, base_url=base_url, model=model, api_type=api_type)
    bot_service.add_config(user_id, new_config)
    click.echo(f"Bot '{name}' added successfully")

# Merge user configuration data while preserving sensitive fields
from typing import Dict
from api.schemas.user_configuration import UserConfiguration
from api.services.configuration.masking import is_mask_of

SERVICE_NAMES = ("llm", "tts", "stt", "embeddings")

def combine_user_configs(
    current: UserConfiguration, partial_update: Dict[str, dict]
) -> UserConfiguration:
    """Combine *partial_update* with *current* and return a new UserConfiguration.
    *partial_update* represents the request body (already processed via `model_dump()`).

    Rules:
    1. Omit service blocks not present in the update; retain existing ones.
    2. If provider stays the same and api_key is missing or masked, keep original key.
    3. If provider changes, use incoming api_key directly (validation handles errors).
    4. Other top-level fields (e.g., `contact_phone`) are replaced when provided.
    """
    combined = current.model_dump(exclude_none=True)

    def _process_service_block(service_key: str):
        update_cfg = partial_update.get(service_key)
        if update_cfg is None:
            return  # skip if no update for this service

        prev_cfg = combined.get(service_key, {})
        provider_modified = (
            prev_cfg.get("provider") is not None
            and update_cfg.get("provider") is not None
            and update_cfg.get("provider") != prev_cfg.get("provider")
        )

        update_api_key = update_cfg.get("api_key")
        if not provider_modified:
            # Preserve real api_key when incoming is masked or absent
            if update_api_key is not None:
                if (
                    prev_cfg
                    and "api_key" in prev_cfg
                    and is_mask_of(update_api_key, prev_cfg["api_key"])
                ):
                    update_cfg["api_key"] = prev_cfg["api_key"]
            else:
                if "api_key" in prev_cfg:
                    update_cfg["api_key"] = prev_cfg["api_key"]

        combined[service_key] = update_cfg

    for service in SERVICE_NAMES:
        _process_service_block(service)

    # Handle additional simple fields
    if "contact_phone" in partial_update:
        combined["contact_phone"] = partial_update["contact_phone"]
    if "locale" in partial_update:
        combined["locale"] = partial_update["locale"]

    return UserConfiguration.model_validate(combined)

