# along with this program.  If not, see <https://www.gnu.org/licenses/>.
"""
from typing import Union
from numpy import int64, int32

def get_second() -> int:
    return 1

def get_minute() -> int:
    return get_second() * 60

def get_hour() -> int:
    return get_minute() * 60

def get_day() -> int:
    return get_hour() * 24

def get_week() -> int:
    return get_day() * 7

def get_month() -> int:
    return get_day() * 30

def get_year() -> int:
    return get_day() * 365

def get_decade() -> int:
    return get_year() * 10

def get_century() -> int:
    return get_decade() * 10

def get_millennium() -> int:
    return get_century() * 10

def convert_interval_to_seconds(interval: Union[str, float]) -> float:
    """
    Convert an interval string to its equivalent number of seconds
    """
    if isinstance(interval, float) or isinstance(interval, int) or isinstance(interval, int64) or \
            isinstance(interval, int32):
        return float(interval)

    # Normalize month notation
    if 'mo' in interval:
        interval = interval.replace('mo', 'M')

    try:
        value = int(interval[:-1])
    except ValueError:
        raise ValueError("Invalid time interval definition.")

    unit_char = interval[-1]

    # Map units to base values
    if unit_char == "s":
        base_value = get_second()
    elif unit_char == "m":
        base_value = get_minute()
    elif unit_char == "h":
        base_value = get_hour()
    elif unit_char == "d":
        base_value = get_day()
    elif unit_char == "w":
        base_value = get_week()
    elif unit_char == "M":
        base_value = get_month()
    elif unit_char == "y":
        base_value = get_year()
    elif unit_char == "D":
        base_value = get_decade()
    elif unit_char == "c":
        base_value = get_century()
    elif unit_char == "l":
        base_value = get_millennium()
    else:
        raise ValueError("Invalid time interval definition.")

    # Apply magnitude
    return float(base_value * value)

def convert_seconds_to_interval(seconds: int) -> str:
    """
    Convert integer seconds into a human-readable time interval string
    Example: 3600 -> 1h
    Args:
        seconds: An integer representing the time duration in seconds
    """
    time_units = {
        'mo': get_month(),
        'wk': get_week(),
        'd': get_day(),
        'h': get_hour(),
        'm': get_minute(),
        's': get_second()
    }

    selected_unit = None
    for key in time_units:
        if seconds % time_units[key] == 0:
            selected_unit = key
            break

    count = int(seconds / time_units[selected_unit])
    return f'{count}{selected_unit}'

