                raise ValueError("If a position argument is used, only 1 is allowed to set `current_value`")
            if kwargs:
                raise ValueError("If a position argument is used, keyword arguments cannot be used.")
            super().__init__(current_value=args[0])
        else:
            super().__init__(**kwargs)

    @field_validator('current_value')
    def validate_current_value(cls, v):
        if v is None:
            return v

        instance = cls.model_construct()
        validation_errors = []

        # Try validating as datetime first
        try:
            instance.dt_validator = v
            return v
        except (ValidationError, ValueError) as e:
            validation_errors.append(str(e))

        # Then try validating as string
        try:
            instance.str_validator = v
            return v
        except (ValidationError, ValueError) as e:
            validation_errors.append(str(e))

        if validation_errors:
            raise ValueError("No match found when setting the current_value in Timestamp with anyOf schemas: datetime, str. Details: " + ", ".join(validation_errors))
        else:
            return v

    @classmethod
    def from_dict(cls, obj: Dict[str, Any]) -> Self:
        return cls.from_json(json.dumps(obj))

    @classmethod
    def from_json(cls, json_str: str) -> Self:
        """Returns the object represented by the json string"""
        instance = cls.model_construct()
        if json_str is None:
            return instance

        validation_errors = []

        # Try parsing as datetime
        try:
            parsed_dt = json.loads(json_str)
            instance.dt_validator = parsed_dt
            instance.current_value = instance.dt_validator
            return instance
        except (ValidationError, ValueError) as e:
            validation_errors.append(str(e))

        # Try parsing as string
