            parsed_str = json.loads(json_str)
            instance.str_validator = parsed_str
            instance.current_value = instance.str_validator
            return instance
        except (ValidationError, ValueError) as e:
            validation_errors.append(str(e))

        if validation_errors:
            raise ValueError("No match found when deserializing the JSON string into Timestamp with anyOf schemas: datetime, str. Details: " + ", ".join(validation_errors))
        else:
            return instance

    def to_json(self) -> str:
        """Returns the JSON representation of the actual instance"""
        if self.current_value is None:
            return "null"

        if hasattr(self.current_value, "to_json") and callable(self.current_value.to_json):
            return self.current_value.to_json()
        else:
