# Health tracking CLI tool using Garmin Connect API
import json
import sys
from datetime import date

try:
    from garmer import GarminClient
    from garmer.auth import AuthenticationError
except ImportError:
    print("Error: garmer not installed. Run: pip install garmer", file=sys.stderr)
    sys.exit(1)

def establish_connection() -> GarminClient:
    """Establish authenticated connection to Garmin."""
    try:
        return GarminClient.from_saved_tokens()
    except AuthenticationError:
        print("Error: Not authenticated. Run 'garmer login' first.", file=sys.stderr)
        sys.exit(1)

def display_daily_health():
    """Display today's health summary."""
    client = establish_connection()
    health_data = client.get_daily_summary()
    print(f"Date: {date.today()}")
    print(f"Steps: {health_data.total_steps:,} / {health_data.daily_step_goal:,}")
    print(f"Distance: {health_data.total_distance_meters / 1000:.2f} km")
    print(f"Calories: {health_data.total_kilocalories:,}")
    if health_data.resting_heart_rate:
        print(f"Resting HR: {health_data.resting_heart_rate} bpm")
    if health_data.avg_stress_level:
        print(f"Avg Stress: {health_data.avg_stress_level}")

def display_sleep_info():
    """Display sleep data."""
    client = establish_connection()
    sleep_data = client.get_sleep()
    if sleep_data:
        print(f"Total Sleep: {sleep_data.total_sleep_hours:.1f} hours")
        print(f"Deep Sleep: {sleep_data.deep_sleep_hours:.1f} hours")
        print(f"REM Sleep: {sleep_data.rem_sleep_hours:.1f} hours")
        if sleep_data.overall_score:
            print(f"Sleep Score: {sleep_data.overall_score}")
        if sleep_data.avg_hrv:
            print(f"HRV: {sleep_data.avg_hrv:.1f} ms")
    else:
        print("No sleep data available")

def display_recent_workouts():
    """Display recent activities/workouts."""
    client = establish_connection()
    workouts = client.get_recent_activities(limit=5)
    if workouts:
        for activity in workouts:
            print(f"- {activity.activity_name} ({activity.activity_type_key})")
            print(
                f"  Duration: {activity.duration_minutes:.0f} min, Distance: {activity.distance_km:.2f} km"
            )
    else:
        print("No recent activities")

def display_full_health_report():
    """Print full health snapshot as JSON."""
    client = establish_connection()
    health_snapshot = client.get_health_snapshot()
    print(json.dumps(health_snapshot, indent=2, default=str))

def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    selected_command = sys.argv[1].lower()
    command_map = {
        "summary": display_daily_health,
        "sleep": display_sleep_info,
        "activities": display_recent_workouts,
        "snapshot": display_full_health_report,
    }

    if selected_command in command_map:
        command_map[selected_command]()
    else:
        print(f"Unknown command: {selected_command}")
        print(__doc__)
        sys.exit(1)

if __name__ == "__main__":
    main()

