# Global encryptor instance
_fernet_instance = None

# Custom JSON encoder for special types
class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, datetime.datetime):
            return obj.isoformat()

        if isinstance(obj, bytes):
            try:
                decoded_str = str(obj)
                return decoded_str
            except Exception:
                return base64.urlsafe_b64encode(obj).decode()

        elif isinstance(obj, list):
            return [self.default(item) for item in obj]

        elif isinstance(obj, tuple):
            return tuple(self.default(item) for item in obj)

        elif isinstance(obj, dict):
            return {k: self.default(v) for k, v in obj.items()}

        return super().default(obj)

# Custom formatter that outputs structured JSON logs
class StructuredJsonFormatter(logging.Formatter):
    def __init__(self, additional_fields: dict | None = None):
        super().__init__()
        self._additional_fields = additional_fields
        self._reserved_keys = {
            "name",
            "msg",
            "args",
            "levelname",
            "levelno",
            "pathname",
            "filename",
            "module",
            "exc_info",
            "exc_text",
            "stack_info",
            "lineno",
            "funcName",
            "created",
            "msecs",
            "relativeCreated",
            "thread",
            "threadName",
            "processName",
            "process",
            "taskName",
            # Additional reserved keys
            "sql",
            "encrypted_data",
            "exception"
        }

    def format(self, record: logging.LogRecord):
        # Base fields
        log_entry = {
            "timestamp": self.formatTime(record, self.datefmt),
            "severity": getattr(record, "levelname", "INFO"),
            "message": record.getMessage()
        }

        # Handle exceptions and stack traces
        if record.exc_info:
            log_entry["exception"] = self.formatException(record.exc_info)

        if record.stack_info:
            log_entry["stack_trace"] = record.stack_info

        # Determine function name
        func_name = None
        if hasattr(record, "custom_func"):
            func_name = getattr(record, "custom_func")
        elif hasattr(record, "funcName"):
            func_name = getattr(record, "funcName")

        if func_name and func_name != "<module>":
            log_entry["function"] = func_name

        # File location info
        if hasattr(record, "pathname") and hasattr(record, "lineno"):
            file_path = getattr(record, "pathname").removeprefix(os.getcwd()).removeprefix(os.sep)
            log_entry["location"] = f"{file_path}:{getattr(record, 'lineno')}"

        # Module name
        if hasattr(record, "module") and record.module:
            log_entry["module"] = record.module

        # Handle encrypted data
        encrypted_data = getattr(record, "encrypted_data", "")
        if encrypted_data:
            plain_json = json.dumps(
                encrypted_data,
                ensure_ascii=False,
                separators=(',', ':'),
                cls=CustomJSONEncoder
            )

            global _fernet_instance
            if _fernet_instance:
                try:
                    encrypted_result = _fernet_instance.encrypt(plain_json)
                except Exception as e:
                    logging.warning(str(e))
                    encrypted_result = plain_json
            else:
                encrypted_result = plain_json

            # Truncate long strings
            log_entry["encrypted_data"] = encrypted_result \
                if len(encrypted_result) <= 200 \
                else f"{encrypted_result[:100]}**********{encrypted_result[-100:]}"

        # Add extra fields from log record
        for key in record.__dict__:
            if key not in self._reserved_keys:
                log_entry[key] = record.__dict__[key]

        # Apply additional static fields
        if self._additional_fields:
            log_entry.update(self._additional_fields)

        # Inject request context fields if missing
        if "trace_id" not in log_entry:
            trace_id = get_req_ctx("trace_id")
            if trace_id:
                log_entry["trace_id"] = trace_id

        if "url" not in log_entry:
            url = get_req_ctx("path")
            if url:
                log_entry["url"] = url

        if "method" not in log_entry:
            method = get_req_ctx("method")
            if method:
                log_entry["method"] = method

        # Final JSON output
        return json.dumps(log_entry, ensure_ascii=False, separators=(",", ":"), cls=CustomJSONEncoder)

# Handler for tqdm-compatible logging
class TqdmStreamHandler(logging.Handler):
    def __init__(self):
        super().__init__()

    def emit(self, record):
        from tqdm import tqdm
        try:
            formatted_msg = self.format(record)
            tqdm.write(formatted_msg)
            self.flush()
        except Exception:
            self.handleError(record)

# List of verbose third-party loggers to silence
NOISY_LOGGERS = [
    "google.genai",
    "google.genai._interactions",
    "httpx",
    "httpcore",
    "urllib3",
    "openai",
    "anthropic",
    "langchain",
    "langchain_core",
]

def suppress_verbose_loggers(app_level: int):
    """Raise log level for noisy external libraries when app is in DEBUG mode."""
    if app_level <= logging.DEBUG:
        for logger_name in NOISY_LOGGERS:
            logging.getLogger(logger_name).setLevel(logging.WARNING)

# Initialize console logging
def setup_console_logging(level: int = logging.INFO, extra: dict = {}, encryption_key: str = ""):
    if encryption_key:
        global _fernet_instance
        _fernet_instance = FernetEncrypter(encryption_key)

    console_handler = logging.StreamHandler()
    console_handler.setFormatter(StructuredJsonFormatter(extra))
    logging.root.handlers = [console_handler]
    logging.root.setLevel(level=level)
    suppress_verbose_loggers(level)

# Initialize file-based logging
def setup_file_logging(filename: str, directory: str, level: int = logging.INFO, extra: dict = {}, encryption_key: str = ""):
    if encryption_key:
        global _fernet_instance
        _fernet_instance = FernetEncrypter(encryption_key)

    if directory:
        os.makedirs(directory, exist_ok=True)

    formatter = StructuredJsonFormatter(extra)
    timestamp = datetime.datetime.now()
    filename_part = f"{timestamp.strftime('%Y-%m-%d')}_{filename}_{timestamp.strftime('%H%M%S_%f')}.log"
    file_path = os.path.join(directory, filename_part)

    file_handler = logging.FileHandler(file_path, mode="w+")
    file_handler.setFormatter(formatter)

    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)

    logging.root.handlers = [file_handler, console_handler]
    logging.root.setLevel(level=level)
    suppress_verbose_loggers(level)

# Initialize tqdm-based logging
def setup_tqdm_logging(level: int = logging.INFO):
    handler = TqdmStreamHandler()
    handler.setFormatter(StructuredJsonFormatter())
    logging.root.handlers = [handler]
    logging.root.setLevel(level=level)

# Unified logging initialization
def setup_logging(name: str = "", dir: str = "", level: int = logging.INFO, extra: dict = {}, encryption_key: str = ""):
    if name:
        setup_file_logging(name, dir, level, extra, encryption_key)
    else:
        setup_console_logging(level, extra, encryption_key)

