    def __init__(self):
        self.settings_dir = Path.home() / ".wingosy"
        self.settings_file = self.settings_dir / "config.json"

        # Migration logic: Ensure user data is preserved during rebranding
        legacy_dir = Path.home() / ".argosy"
        if legacy_dir.exists():
            needs_migration = False
            if not self.settings_dir.exists() or not self.settings_file.exists():
                needs_migration = True
            else:
                # If .wingosy exists but host remains default, assume failed rebranding
                try:
                    with open(self.settings_file, 'r', encoding='utf-8') as f:
                        existing = json.load(f)
                        if existing.get("host") == "http://localhost:8285":
                            needs_migration = True
                except:
                    needs_migration = True

            if needs_migration:
                try:
                    if self.settings_dir.exists():
                        shutil.rmtree(self.settings_dir, ignore_errors=True)
                    shutil.copytree(legacy_dir, self.settings_dir)
                    print(f"Successfully migrated all settings and library from {legacy_dir}")
                except Exception as err:
                    print(f"Migration error: {err}")

        # Initialize with deep copy of default configuration
        self.config = copy.deepcopy(self.INITIAL_SETTINGS)
        self.reload()

    def reload(self):
        if self.settings_file.exists():
            try:
                with open(self.settings_file, 'r', encoding='utf-8') as f:
                    stored_data = json.load(f)

                    # Restore top-level settings (excluding emulators)
                    for key, value in stored_data.items():
                        if key != "emulators":
                            self.config[key] = value

                    # Clean up trailing slashes in host URL
                    if self.config["host"]:
                        self.config["host"] = self.config["host"].rstrip('/')

                    # Smart merge emulator configurations (preserve user paths)
                    stored_emus = stored_data.get("emulators", {})
                    for name, current_cfg in self.config["emulators"].items():
                        for old_name, old_data in stored_emus.items():
                            if old_data.get("exe") == current_cfg["exe"]:
                                current_cfg["path"] = old_data.get("path", "")
                                break
            except Exception as error:
                print(f"Error loading config: {error}")
        else:
            self.save()

    def save(self):
        self.settings_dir.mkdir(parents=True, exist_ok=True)
        try:
            with open(self.settings_file, 'w', encoding='utf-8') as f:
                json.dump(self.config, f, indent=4)
        except Exception as error:
            print(f"Error saving config: {error}")

    def get(self, key, default=None):
        return self.config.get(key, default)

    def set(self, key, value):
        if value is None:
            self.config.pop(key, None)
        else:
            self.config[key] = value
        self.save()

import os
import logging
from typing import Set

logger = logging.getLogger(__name__)

class EmailValidator:
    _blocked_domains: Set[str] = set()
    _initialized: bool = False

    @classmethod
    def _initialize_blocked_list(cls):
        """Populates the list of disposable email domains from a JSON file."""
        if cls._initialized:
            return

        try:
            # Determine path relative to current module location
            script_dir = os.path.dirname(os.path.abspath(__file__))
            config_path = os.path.join(script_dir, "..", "data", "temp_emails.json")

            if os.path.isfile(config_path):
                with open(config_path, "r") as file:
                    domain_list = json.load(file)
                    cls._blocked_domains = set(domain_list)
                cls._initialized = True
                logger.info(f"Successfully loaded {len(cls._blocked_domains)} temporary email domains.")
            else:
                logger.warning(f"Temporary email domains file not found at {config_path}")
        except Exception as error:
            logger.error(f"Error while loading blocked domains: {error}")

    @classmethod
    def is_temporary_email(cls, address: str) -> bool:
        """
        Utility method to detect disposable or temporary email accounts.
        Verifies both exact domain matches and parent domain suffixes.
        """
        if not address or "@" not in address:
            return False

        cls._initialize_blocked_list()

        if not cls._blocked_domains:
            return False

        try:
            # Extract domain part and normalize
            domain = address.split("@")[-1].lower().strip()

            # 1. Direct match check
            if domain in cls._blocked_domains:
                return True

            # 2. Check parent domains (e.g., sub.domain.com against domain.com)
            segments = domain.split(".")
            # Build possible parent domains from rightmost parts
            for idx in range(len(segments) - 1):
                parent = ".".join(segments[idx:])
                if parent in cls._blocked_domains:
                    return True

            return False
        except Exception:
            return False

