    attributes = ["image_processor", "tokenizer"]
    image_processor_class = "CLIPImageProcessor"
    tokenizer_class = ("CLIPTokenizer", "CLIPTokenizerFast")

    def __init__(self, image_processor=None, tokenizer=None, custom_attr_1=1, custom_attr_2=True):
        super().__init__(image_processor, tokenizer)
        self.custom_attr_1 = custom_attr_1
        self.custom_attr_2 = custom_attr_2


@require_tokenizers
@require_vision
class ProcessorIntegrationTest(unittest.TestCase):
    processor_type = CustomProcessor

    def setup_processor_config(self):
        return {"custom_attr_1": 1, "custom_attr_2": False}

    def build_processor(self):
        img_proc = CLIPImageProcessor.from_pretrained("openai/clip-vit-large-patch14")
        tok = CLIPTokenizerFast.from_pretrained("openai/clip-vit-large-patch14")
        proc = CustomProcessor(img_proc, tok, **self.setup_processor_config())
        return proc

    def test_serialization_to_json(self):
        proc = self.build_processor()
        parsed_obj = json.loads(proc.to_json_string())
        for key, val in self.setup_processor_config().items():
            self.assertEqual(parsed_obj[key], val)
            self.assertEqual(getattr(proc, key, None), val)

    def test_save_and_load_pretrained(self):
        first_proc = self.build_processor()
        with tempfile.TemporaryDirectory() as tmpdir:
            saved_file = first_proc.save_pretrained(tmpdir)[0]
            check_json_file_has_correct_format(saved_file)
            second_proc = self.processor_type.from_pretrained(tmpdir)
        self.assertEqual(second_proc.to_dict(), first_proc.to_dict())

