from rich.padding import Padding
from rich.text import Text
from epstein_files.documents.emails.constants import FALLBACK_TIMESTAMP
from epstein_files.util.helpers.string_helper import quote
from epstein_files.util.logging import logger

def get_highlight_configuration() -> dict:
    from epstein_files.output.highlight_config import HIGHLIGHTED_NAMES
    result = {}
    for item in HIGHLIGHTED_NAMES:
        result[item.label] = {
            'patterns': item.patterns,
            'regex.pattern': item.regex.pattern,
        }
    return result

def display_all_quoted_highlights(epstein_data):
    from epstein_files.output.rich import console
    for message in epstein_data.emails:
        if message.config and message.config.highlight_quote:
            console.print(message)

def display_all_timestamps(epstein_data):
    from epstein_files.output.rich import console
    missing_count = valid_count = 0
    for idx, record in enumerate(epstein_data.unique_documents):
        console.print(record._summary)
        if record.timestamp == FALLBACK_TIMESTAMP:
            missing_count += 1
        elif record.timestamp:
            valid_count += 1
    no_timestamp_count = len(epstein_data.unique_documents) - valid_count - missing_count
    console.print(f"\nProcessed {idx + 1} records (missing={no_timestamp_count}, confirmed={valid_count}, fallback={missing_count})\n")

def show_highlight_patterns() -> None:
    from epstein_files.output.rich import print_json
    print_json('patterns', get_highlight_configuration())
    import sys
    sys.exit()

def display_file_statistics(epstein_data) -> None:
    from epstein_files.output.rich import console, styled_dict
    category_counts = defaultdict(int)
    for idx, record in enumerate(epstein_data.unique_documents):
        category_counts[record._class_name] += 1
    category_counts['total'] = idx + 1
    console.print(styled_dict(category_counts))

def _check_filenames(epstein_data):
    doc_names = set([doc.file_path.name for doc in epstein_data.documents])
    for path in epstein_data.file_paths:
        if path.name not in doc_names:
            print(f"'{path}' is absent from the {len(doc_names)} Document filenames!")

def display_relevant_document_panels(epstein_data, group_by_category: bool = True):
    """Only displays OtherFile objects."""
    from epstein_files.documents.other_file import OtherFile
    from epstein_files.output.rich import console, indent_txt, styled_dict
    total_shown = 0
    significant_count = 0
    if group_by_category:
        items = sorted(epstein_data.documents, key=lambda d: [d.category, d.timestamp or FALLBACK_TIMESTAMP])
    else:
        items = epstein_data.documents
    for record in items:
        if not isinstance(record, OtherFile):
            continue
        elif record.is_interesting is None and record.config is None:
            continue
        if record.config:
            attributes = record.config.truthy_props.copy()
            attributes.pop('id', None)
            if record.is_interesting != record.config.is_of_interest:
                logger.warning(f"discrepancy between config.is_of_interest and record.is_interesting")
                attributes['record.is_interesting'] = record.is_interesting
        else:
            attributes = {'record.is_interesting': record.is_interesting}
        # console.print(record._summary_panel)
        console.print(record.rich_header())
        from epstein_files.util.env import args
        if args.debug:
            props_table = styled_dict(attributes, sep=': ')
            props_table = Padding(indent_txt(props_table, 12), (0, 0, 1, 0))
            console.print(props_table)
        total_shown += 1
        significant_count += int(record.is_interesting or False)
        # console.line()
    print('')
    logger.warning(f"Displayed {total_shown} object configurations, {significant_count} marked as significant.\n\n")

# Voice transcription and configuration endpoints.
"""
import asyncio
import logging
from typing import Optional
from fastapi import APIRouter, File, HTTPException, Request, UploadFile
from ....voice import VoiceService, VoiceServiceError
logger = logging.getLogger("codex_autorunner.routes.voice")

def create_voice_routes() -> APIRouter:
    """Construct routes for voice transcription and configuration."""
    route_router = APIRouter()

    @route_router.get("/api/voice/config")
    def retrieve_voice_settings(request: Request):
        voice_service: Optional[VoiceService] = request.app.state.voice_service
        voice_settings = request.app.state.voice_config
        absence_reason = getattr(request.app.state, "voice_missing_reason", None)

        if absence_reason:
            return {
                "enabled": False,
                "provider": voice_settings.provider,
                "latency_mode": voice_settings.latency_mode,
                "chunk_ms": voice_settings.chunk_ms,
                "sample_rate": voice_settings.sample_rate,
                "warn_on_remote_api": voice_settings.warn_on_remote_api,
                "has_api_key": False,
                "push_to_talk": {
                    "max_ms": voice_settings.push_to_talk.max_ms,
                    "silence_auto_stop_ms": voice_settings.push_to_talk.silence_auto_stop_ms,
                    "min_hold_ms": voice_settings.push_to_talk.min_hold_ms,
                },
                "missing_extra": absence_reason,
            }

        if voice_service is None:
            # Graceful degradation: still return config to the UI even if service init failed.
            try:
                return VoiceService(
                    voice_settings, logger=request.app.state.logger
                ).config_payload()
            except (ValueError, TypeError, OSError) as err:
                logger.debug("Failed to instantiate VoiceService for config: %s", err)
                return {
                    "enabled": False,
                    "provider": voice_settings.provider,
                    "latency_mode": voice_settings.latency_mode,
                    "chunk_ms": voice_settings.chunk_ms,
                    "sample_rate": voice_settings.sample_rate,
                    "warn_on_remote_api": voice_settings.warn_on_remote_api,
                    "has_api_key": False,
                    "push_to_talk": {
                        "max_ms": voice_settings.push_to_talk.max_ms,
                        "silence_auto_stop_ms": voice_settings.push_to_talk.silence_auto_stop_ms,
                        "min_hold_ms": voice_settings.push_to_talk.min_hold_ms,
                    },
                }

        return voice_service.config_payload()

    @route_router.post("/api/voice/transcribe")
    async def process_transcription(
        request: Request,
        audio_file: Optional[UploadFile] = File(None),
        lang: Optional[str] = None,
    ):
        voice_service: Optional[VoiceService] = request.app.state.voice_service
        voice_settings = request.app.state.voice_config
        absence_reason = getattr(request.app.state, "voice_missing_reason", None)

        if absence_reason:
            raise HTTPException(status_code=503, detail=absence_reason)

        if not voice_service or not voice_settings.enabled:
            raise HTTPException(status_code=400, detail="Voice functionality is disabled")

        filename: Optional[str] = None
        content_type: Optional[str] = None

        if audio_file is not None:
            filename = audio_file.filename
            content_type = audio_file.content_type
            try:
                audio_data = await audio_file.read()
            except Exception as exc:
                raise HTTPException(
                    status_code=400, detail="Unable to read audio upload"
                ) from exc
        else:
            audio_data = await request.body()

        try:
            result = await asyncio.to_thread(
                voice_service.transcribe,
                audio_data,
                client="web",
                user_agent=request.headers.get("user-agent"),
                language=lang,
                filename=filename,
                content_type=content_type,
            )
        except VoiceServiceError as exc:
            if exc.reason == "unauthorized":
                status = 401
            elif exc.reason == "forbidden":
                status = 403
            elif exc.reason == "audio_too_large":
                status = 413
            elif exc.reason == "rate_limited":
                status = 429
            else:
                status = (
                    400
                    if exc.reason in ("disabled", "empty_audio", "invalid_audio")
                    else 502
                )
            raise HTTPException(status_code=status, detail=exc.detail) from exc

        return {"status": "ok", **result}

    return route_router

# Calculate security scan results using Checkov
import datetime
import json
import os
import subprocess
import tempfile
import uuid
from mcp_server_ccapi.errors import ClientError
from mcp_server_ccapi.models.models import RunCheckovRequest

def _verify_checkov_availability() -> dict:
    """Verify that Checkov is installed and accessible.
    As checkov is listed as a required dependency, it should always be present.
    This function acts primarily as a verification step.
    Returns:
        A dictionary containing status details:
        {
            "available": True/False,
            "info": Description of the outcome,
            "requires_action": True/False
        }
    """
    try:
        # Confirm Checkov is accessible
        subprocess.run(
            ['checkov', '--version'],
            capture_output=True,
            text=True,
            check=True,
            shell=False,
        )
        return {
            'available': True,
            'info': 'Checkov is ready for use',
            'requires_action': False,
        }
    except (FileNotFoundError, subprocess.CalledProcessError):
        return {
            'available': False,
            'info': 'Checkov could not be found. This is unexpected since checkov is a declared dependency. Please reinstall the package.',
            'requires_action': True,
        }

async def perform_security_review(resource_kind: str, attributes: dict) -> dict:
    """Basic security review function for testing compatibility."""
    return {'status': 'passed', 'note': 'Security review completed successfully'}

async def execute_checkov_scan(request: RunCheckovRequest, session_store: dict) -> dict:
    """Execute Checkov security and compliance scanner on server-stored cloudcontrol template implementation."""
    # Verify Checkov installation
    checkov_status = _verify_checkov_availability()
    if not checkov_status['available']:
        return {
            'status': 'failed',
            'error': 'Checkov is not installed',
            'summary': {'error': 'Checkov not available'},
            'note': checkov_status['info'],
            'requires_approval': checkov_status['requires_action'],
            'choices': [
                {
                    'choice': 'installation_assistance',
                    'explanation': 'Receive guidance on installing Checkov',
                },
                {
                    'choice': 'continue_unchecked',
                    'explanation': 'Proceed without performing security checks',
                },
                {'choice': 'abort', 'explanation': 'Abort the current operation'},
            ],
        }

    # CRITICAL SECURITY: Validate explained token and retrieve server-stored cloudcontrol template
    if request.explained_token not in session_store:
        raise ClientError('Invalid explained token: you must call explain() first')
    session_data = session_store[request.explained_token]
    if session_data.get('kind') != 'explained_properties':
        raise ClientError('Invalid token type: expected explained_properties token from explain()')

    # Retrieve cloudcontrol template from server-stored data (AI cannot override this)
    cloudcontrol_template = session_data['data']['cloudcontrol_template']
    resource_kind = session_data['data']['properties'].get('Type', 'Unknown')

    # Ensure content is a string for Checkov
    if not isinstance(cloudcontrol_template, str):
        try:
            content = json.dumps(cloudcontrol_template)
        except Exception as e:
            return {
                'status': 'failed',
                'error': f'cloudcontrol template must be valid JSON: {str(e)}',
                'summary': {'error': 'Invalid cloudcontrol template format'},
            }
    else:
        content = cloudcontrol_template

    # Create a temporary file with the cloudcontrol template (always JSON)
    with tempfile.NamedTemporaryFile(suffix='.json', delete=False) as temp_file:
        temp_file.write(content.encode('utf-8'))
        temp_file_path = temp_file.name

    try:
        # Build the checkov command with input validation
        cmd = ['checkov', '-f', temp_file_path, '--output', 'json']

        # Add framework if specified (validate against allowed frameworks)
        if request.framework:
            permitted_frameworks = [
                'terraform',
                'cloudcontrol',
                'kubernetes',
                'dockerfile',
                'arm',
                'all',
            ]
            if request.framework in permitted_frameworks:
                cmd.extend(['--framework', request.framework])
            else:
                return {
                    'status': 'failed',
                    'error': f'Invalid framework: {request.framework}. Allowed: {permitted_frameworks}',
                }

        # Run checkov with shell=False for security
        process = subprocess.run(cmd, capture_output=True, text=True, shell=False)

        # Parse the output
        if process.returncode == 0:
            # All checks passed - generate security scan token
            security_scan_token = f'sec_{str(uuid.uuid4())}'
            session_store[security_scan_token] = {
                'kind': 'security_scan',
                'data': {
                    'status': 'passed',
                    'scan_results': (json.loads(process.stdout) if process.stdout else []),
                    'resource_kind': resource_kind,
                    'timestamp': str(datetime.datetime.now()),
                },
                'timestamp': datetime.datetime.now().isoformat(),
            }
            return {
                'scan_status': 'PASSED',
                'raw_failed_checks': [],
                'raw_passed_checks': (json.loads(process.stdout) if process.stdout else []),
                'raw_summary': {
                    'status': 'passed',
                    'note': 'All security checks passed',
                },
                'resource_kind': resource_kind,
                'timestamp': str(datetime.datetime.now()),
                'security_scan_token': security_scan_token,
                'note': 'Security checks passed. You can proceed with create_resource().',
            }
        elif process.returncode == 1:  # Return code 1 means vulnerabilities were found
            # Some checks failed
            try:
                results = json.loads(process.stdout) if process.stdout else {}
                failed_checks = results.get('results', {}).get('failed_checks', [])
                passed_checks = results.get('results', {}).get('passed_checks', [])
                summary = results.get('summary', {})

                # Security issues found - return results with security_scan_token
                security_scan_token = f'sec_{str(uuid.uuid4())}'
                session_store[security_scan_token] = {
                    'kind': 'security_scan',
                    'data': {
                        'status': 'failed',
                        'scan_results': {
                            'failed_checks': failed_checks,
                            'passed_checks': passed_checks,
                            'summary': summary,
                        },
                        'resource_kind': resource_kind,
                        'timestamp': str(datetime.datetime.now()),
                    },
                    'timestamp': datetime.datetime.now().isoformat(),
                }
                return {
                    'scan_status': 'FAILED',
                    'raw_failed_checks': failed_checks,
                    'raw_passed_checks': passed_checks,
                    'raw_summary': summary,
                    'resource_kind': resource_kind,
                    'timestamp': str(datetime.datetime.now()),
                    'security_scan_token': security_scan_token,
                    'note': 'Security issues found. You can proceed with create_resource() if you approve.',
                }
            except json.JSONDecodeError:
                # Handle case where output is not valid JSON
                return {
                    'status': 'failed',
                    'error': 'Failed to parse Checkov output',
                    'stdout': process.stdout,
                    'stderr': process.stderr,
                }
        else:
            # Error running checkov
            return {
                'status': 'failed',
                'error': f'Checkov exited with code {process.returncode}',
                'stderr': process.stderr,
            }
    except Exception as e:
        return {'status': 'failed', 'error': str(e), 'note': 'Failed to run Checkov'}
    finally:
        # Clean up the temporary file
        if os.path.exists(temp_file_path):
            os.unlink(temp_file_path)

# Modified version with renamed variables, reordered statements, and minor structural changes
import warnings
from multiprocessing import Pipe, connection
from multiprocessing.context import Process
from typing import Any, Callable, Optional, Union
import gymnasium as gym
import numpy as np
from rlinf.envs.venv import (
    BaseVectorEnv,
    CloudpickleWrapper,
    EnvWorker,
    ShArray,
    SubprocEnvWorker,
    SubprocVectorEnv,
    _setup_buf,
)

# Define environment step return types for compatibility
old_venv_step = tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]
new_venv_step = tuple[
    np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray
]

warnings.simplefilter("always", DeprecationWarning)

def _remote_worker(
    conn_parent: connection.Connection,
    conn_child: connection.Connection,
    env_factory: CloudpickleWrapper,
    shared_buffers: Optional[Union[dict, tuple, ShArray]] = None,
) -> None:
    def _store_observation(
        obs_data: Union[dict, tuple, np.ndarray], 
        buffer_data: Union[dict, tuple, ShArray]
    ) -> None:
        if isinstance(obs_data, np.ndarray) and isinstance(buffer_data, ShArray):
            buffer_data.save(obs_data)
        elif isinstance(obs_data, tuple) and isinstance(buffer_data, tuple):
            for o_part, b_part in zip(obs_data, buffer_data):
                _store_observation(o_part, b_part)
        elif isinstance(obs_data, dict) and isinstance(buffer_data, dict):
            for key in obs_data.keys():
                _store_observation(obs_data[key], buffer_data[key])
        return None

    conn_parent.close()
    env_instance = env_factory.data()

    try:
        while True:
            try:
                command, payload = conn_child.recv()
            except EOFError:
                conn_child.close()
                break

            if command == "step":
                result = env_instance.step(payload)
                if shared_buffers is not None:
                    _store_observation(result[0], shared_buffers)
                    result = (None,) + result[1:]
                conn_child.send(result)

            elif command == "reset":
                output = env_instance.reset(**payload)
                has_info = (
                    isinstance(output, (tuple, list)) 
                    and len(output) == 2 
                    and isinstance(output[1], dict)
                )
                if has_info:
                    obs, info_dict = output
                else:
                    obs = output

                if shared_buffers is not None:
                    _store_observation(obs, shared_buffers)
                    obs = None

                if has_info:
                    conn_child.send((obs, info_dict))
                else:
                    conn_child.send(obs)

            elif command == "close":
                conn_child.send(env_instance.close())
                conn_child.close()
                break

            elif command == "render":
                rendered = env_instance.render(**payload) if hasattr(env_instance, "render") else None
                conn_child.send(rendered)

            elif command == "seed":
                if hasattr(env_instance, "seed"):
                    conn_child.send(env_instance.seed(payload))
                else:
                    env_instance.reset(seed=payload)
                    conn_child.send(None)

            elif command == "getattr":
                value = getattr(env_instance, payload) if hasattr(env_instance, payload) else None
                conn_child.send(value)

            elif command == "setattr":
                setattr(env_instance.unwrapped, payload["key"], payload["value"])

            elif command == "reconfigure":
                # Meta-World specific reconfiguration logic
                env_instance.close()
                meta_env_name = payload.pop("env_name")
                env_instance = gym.make(
                    "Meta-World/MT1",
                    env_name=meta_env_name,
                    render_mode="rgb_array",
                    camera_id=2,
                    disable_env_checker=True,
                )
                # Adjust camera position to match sft behavior
                env_instance.env.env.env.env.env.env.env.model.cam_pos[2] = [0.75, 0.075, 0.7]
                conn_child.send(None)

            else:
                conn_child.close()
                raise NotImplementedError

    except KeyboardInterrupt:
        conn_child.close()

class ReconfigurableSubprocWorker(SubprocEnvWorker):
    def __init__(self, make_env: Callable[[], gym.Env], use_shared_mem: bool = False):
        self.parent_conn, self.child_conn = Pipe()
        self.use_shared_memory = use_shared_mem
        self.memory_buffer: Optional[Union[dict, tuple, ShArray]] = None

        if self.use_shared_memory:
            temp_env = make_env()
            observation_space = temp_env.observation_space
            temp_env.close()
            del temp_env
            self.memory_buffer = _setup_buf(observation_space)

        worker_args = (
            self.parent_conn,
            self.child_conn,
            CloudpickleWrapper(make_env),
            self.memory_buffer,
        )

        self.worker_process = Process(target=_remote_worker, args=worker_args, daemon=True)
        self.worker_process.start()
        self.child_conn.close()
        EnvWorker.__init__(self, make_env)

    def update_environment(self, env_params):
        self.parent_conn.send(["reconfigure", env_params])
        return self.parent_conn.recv()

class ReconfigurableSubprocVectorEnv(SubprocVectorEnv):
    def __init__(self, env_creators: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def create_worker(env_fn: Callable[[], gym.Env]) -> ReconfigurableSubprocWorker:
            return ReconfigurableSubprocWorker(env_fn, share_memory=False)

        BaseVectorEnv.__init__(self, env_creators, create_worker, **kwargs)

    def update_environments(self, env_configs, indices=None):
        self._ensure_not_closed()
        indices = self._normalize_indices(indices)

        if self.async_mode:
            self._validate_indices(indices)

        for idx, env_idx in enumerate(indices):
            self.workers[env_idx].update_environment(env_configs[idx])

# Unit tests for profile scoring functionality
import pytest
from app.services.scoring.profile_scoring import desirability, profile_score

class TestDesirabilityFunction:
    def test_value_in_middle_of_range(self):
        assert desirability(250, 0, 500) == 1.0

    def test_value_at_upper_boundary(self):
        assert desirability(500, 0, 500) == 1.0
        assert desirability(0, 0, 500) == 1.0

    def test_value_exceeding_upper_limit(self):
        # Value is 250 beyond max (750-500), range width is 500 -> d = 1 - 250/500 = 0.5
        result = desirability(750, 0, 500)
        assert result == pytest.approx(0.5, abs=0.01)

    def test_value_below_minimum_threshold(self):
        # Value is 100 below min (100-200), range width is 300 (500-200) -> d = 1 - 100/300 ≈ 0.667
        result = desirability(100, 200, 500)
        assert result == pytest.approx(0.667, abs=0.01)

    def test_value_far_outside_bounds(self):
        # Value is 600 beyond max (1100-500), range width is 500 -> would be negative, clamped to 0
        assert desirability(1100, 0, 500) == 0.0

    def test_null_input_handling(self):
        assert desirability(None, 0, 500) is None

class TestProfileScoringFunction:
    def test_all_properties_within_acceptable_range(self):
        props = {"mw": 300, "logp": 2.5}
        limits = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        weights = {"mw": 1.0, "logp": 1.0}
        assert profile_score(props, limits, weights) == 100.0

    def test_single_property_outside_limits(self):
        props = {"mw": 300, "logp": 7.5}
        limits = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        weights = {"mw": 1.0, "logp": 1.0}
        final_score = profile_score(props, limits, weights)
        assert 0 < final_score < 100

    def test_missing_property_ignored(self):
        props = {"mw": 300}
        limits = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        weights = {"mw": 1.0, "logp": 1.0}
        # Only mw is evaluated and it's in range, so score should be 100
        assert profile_score(props, limits, weights) == 100.0

    def test_empty_limits_configuration(self):
        assert profile_score({"mw": 300}, {}, {}) is None

    def test_weighted_property_impact(self):
        props = {"mw": 600, "logp": 2.5}
        limits = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        # Higher weight on out-of-range property results in lower overall score
        heavy_mw_score = profile_score(props, limits, {"mw": 3.0, "logp": 1.0})
        light_mw_score = profile_score(props, limits, {"mw": 1.0, "logp": 1.0})
        assert heavy_mw_score < light_mw_score

# Core algorithms for Type I Exhaustive Search.
# Combinatorial logic for generating current distributions and electrode configurations.
"""
from itertools import product

def generate_current_distributions(total_current, step_size, max_channel):
    """Generate valid current distribution pairs for TI stimulation.
    Returns:
        tuple: (distributions, max_exceeded)
            - distributions: List of (ch1_current, ch2_current) tuples
            - max_exceeded: bool indicating if channel limit was breached
    """
    distributions = []
    tolerance = step_size * 0.01
    lower_bound = max(total_current - max_channel, step_size)
    max_exceeded = lower_bound < step_size - tolerance
    if max_exceeded:
        lower_bound = step_size
    current_first = max_channel
    while current_first >= lower_bound - tolerance:
        current_second = total_current - current_first
        if (
            current_first <= max_channel + tolerance
            and current_second <= max_channel + tolerance
            and current_first >= step_size - tolerance
            and current_second >= step_size - tolerance
        ):
            distributions.append((current_first, current_second))
        current_first -= step_size
    return distributions, max_exceeded

def _electrode_tuples(pos1, neg1, pos2, neg2, use_all_combos):
    """Yield valid electrode 4-tuples."""
    if use_all_combos:
        for combo in product(pos1, repeat=4):
            if len(set(combo)) == 4:
                yield combo
    else:
        yield from product(pos1, neg1, pos2, neg2)

def generate_montage_variants(
    pos1, neg1, pos2, neg2, current_dists, use_all_combos
):
    """Yield (e1p, e1m, e2p, e2m, (ch1_mA, ch2_mA)) tuples."""
    for electrodes in _electrode_tuples(
        pos1, neg1, pos2, neg2, use_all_combos
    ):
        for dist in current_dists:
            yield (*electrodes, dist)

def tally_variants(
    pos1, neg1, pos2, neg2, current_dists, use_all_combos
):
    """Count total montage variants without materializing them."""
    n_electrodes = sum(
        1
        for _ in _electrode_tuples(
            pos1, neg1, pos2, neg2, use_all_combos
        )
    )
    return n_electrodes * len(current_dists)

# Undo operations for email-to-calendar changelog
import json
import sys
import os
from datetime import datetime, timedelta

# Add parent directory to path for imports
sys.path.insert(0, os.path.dirname(__file__))
from json_store import load_json, save_json
from common import format_timestamp, time_ago

CHANGELOG_PATH = os.path.expanduser(
    "~/.openclaw/workspace/memory/email-to-calendar/changelog.json"
)
UNDO_PERIOD_HOURS = 24

def locate_latest_reversible() -> None:
    """Locate and display the most recent reversible change identifier."""
    log_data = load_json(CHANGELOG_PATH, {"changes": []})
    reversal_limit = timedelta(hours=UNDO_PERIOD_HOURS)
    current_time = datetime.now()
    entries = list(reversed(log_data.get("changes", [])))

    for entry in entries:
        if not entry.get("reversible", False):
            continue
        try:
            entry_time = datetime.fromisoformat(entry.get("timestamp", ""))
            if (current_time - entry_time) < reversal_limit:
                print(entry.get("identifier"))
                return
        except (ValueError, TypeError):
            continue
    sys.exit(1)

def enumerate_reversible() -> None:
    """Display all reversible changes within the undo window."""
    log_data = load_json(CHANGELOG_PATH, {"changes": []})
    reversal_limit = timedelta(hours=UNDO_PERIOD_HOURS)
    current_time = datetime.now()
    entries = list(reversed(log_data.get("changes", [])))
    reversible_entries = []

    for entry in entries:
        if not entry.get("reversible", False):
            continue
        try:
            entry_time = datetime.fromisoformat(entry.get("timestamp", ""))
            if (current_time - entry_time) < reversal_limit:
                reversible_entries.append(entry)
        except (ValueError, TypeError):
            continue

    if not reversible_entries:
        print("No reversible changes found (all changes are older than 24 hours or already reversed).")
        return

    print(f"Reversible changes ({len(reversible_entries)}):\n")
    for idx, entry in enumerate(reversible_entries, 1):
        entry_id = entry.get("identifier")
        operation = entry.get("operation")
        ts = entry.get("timestamp", "")
        ts_formatted = format_timestamp(ts)
        relative_str = time_ago(ts)

        if operation == "add":
            summary = entry.get("after", {}).get("summary", "Unknown")
            description = f'Added "{summary}"'
        elif operation == "modify":
            summary = (
                entry.get("after", {}).get("summary") or
                entry.get("before", {}).get("summary", "Unknown")
            )
            description = f'Modified "{summary}"'
        else:
            summary = entry.get("before", {}).get("summary", "Unknown")
            description = f'Removed "{summary}"'

        print(f"{idx}. {entry_id}")
        print(f"   {description}")
        print(f"   {relative_str}")
        print()

    print("Execute 'revert.sh --change-id <id>' to reverse a specific change")
    print("or 'revert.sh latest' to reverse the most recent change.")

def record_reversal(change_id: str) -> None:
    """Mark a change as reversed."""
    log_data = load_json(CHANGELOG_PATH, {"changes": []})
    for entry in log_data.get("changes", []):
        if entry.get("identifier") == change_id:
            entry["reversible"] = False
            entry["reversed_at"] = datetime.now().isoformat()
            break
    save_json(CHANGELOG_PATH, log_data)

def main():
    if len(sys.argv) < 2:
        print("Usage: undo_ops.py <action> [options]", file=sys.stderr)
        sys.exit(1)

    action = sys.argv[1]

    # Parse keyword arguments
    parameters = {}
    i = 2
    while i < len(sys.argv):
        if sys.argv[i].startswith("--"):
            key = sys.argv[i][2:].replace("-", "_")
            if i + 1 < len(sys.argv) and not sys.argv[i + 1].startswith("--"):
                parameters[key] = sys.argv[i + 1]
                i += 2
            else:
                parameters[key] = True
                i += 1
        else:
            i += 1

    if action == "locate-latest":
        locate_latest_reversible()
    elif action == "enumerate":
        enumerate_reversible()
    elif action == "record-reversal":
        record_reversal(parameters.get("change_id", ""))
    else:
        print(f"Unknown action: {action}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

