from .schemas import Finding, Severity, Confidence, IssueType, CodeLocation

class CheckResult:
    def __init__(self, is_valid, modified_finding, explanation):
        self.is_valid = is_valid
        self.modified_finding = modified_finding
        self.explanation = explanation

class SourceInspector:
    def __init__(self, strict_mode=False):
        self.strict_mode = strict_mode

    def inspect(self, finding, source_code, file_name):
        lines = source_code.splitlines()
        total_lines_count = len(lines)
        adjustments = []

        # Create a new location object
        position = CodeLocation(
            file=finding.location.file,
            line=finding.location.line,
            end_line=finding.location.end_line,
            column=finding.location.column,
        )

        # Create a new finding object with adjusted values
        updated_finding = Finding(
            rule_id=finding.rule_id,
            issue_type=finding.issue_type,
            severity=finding.severity,
            confidence=finding.confidence,
            message=finding.message,
            location=position,
            suggestion=finding.suggestion,
            explanation=finding.explanation,
        )

        # Validate line range
        if updated_finding.location.line < 1 or updated_finding.location.line > total_lines_count:
            if self.strict_mode:
                error_msg = (
                    "Line "
                    + str(updated_finding.location.line)
                    + " out of range (1-"
                    + str(total_lines_count)
                    + ")"
                )
                return CheckResult(False, None, error_msg)

            # Adjust line number if out of bounds
            if updated_finding.location.line < 1:
                updated_finding.location.line = 1
            if updated_finding.location.line > total_lines_count:
                updated_finding.location.line = total_lines_count

            updated_finding.confidence = Confidence.LOW
            adjustments.append("line_adjusted")

        # Get the content of the relevant line
        current_line_content = ""
        if 1 <= updated_finding.location.line <= total_lines_count:
            current_line_content = lines[updated_finding.location.line - 1]

        # Check relevance of line content
        if not self._is_line_relevant(updated_finding, current_line_content):
            if self.strict_mode:
                return CheckResult(
                    False, None, "Line content not relevant to finding"
                )
            updated_finding.confidence = Confidence.LOW
            adjustments.append("low_relevance")

        # Extract and validate symbol
        symbol_name = self._extract_symbol_name(updated_finding.message)
        if symbol_name and symbol_name.strip():
            if not self._symbol_present(symbol_name, source_code):
                if self.strict_mode:
                    return CheckResult(
                        False, None, "Symbol '" + symbol_name + "' not found in code"
                    )
                updated_finding.confidence = Confidence.UNCERTAIN
                adjustments.append("symbol_not_found:" + symbol_name)

        # Security-specific validation
        if updated_finding.issue_type == IssueType.SECURITY:
            if not self._security_pattern_exists(updated_finding, lines):
                if self.strict_mode:
                    return CheckResult(
                        False, None, "Security pattern not found at location"
                    )
                updated_finding.confidence = Confidence.LOW
                adjustments.append("pattern_not_verified")

        # Append validation notes if there were adjustments
        if adjustments:
            note = "[Validation: " + ", ".join(adjustments) + "]"
            if updated_finding.explanation:
                updated_finding.explanation = str(updated_finding.explanation) + " " + note
            else:
                updated_finding.explanation = note

        return CheckResult(True, updated_finding, "passed")

    def _is_line_relevant(self, finding, line_text):
        if line_text is None:
            return False

        cleaned_line = line_text.strip().lower()
        if not cleaned_line:
            return False

        if cleaned_line.startswith("#"):
            return False

        if finding.issue_type == IssueType.SECURITY:
            return True

        if finding.issue_type == IssueType.DEAD_CODE:
            keywords = ["def ", "class ", "import ", "from ", "="]
            for kw in keywords:
                if kw in cleaned_line:
