        patterns = [
            r"(?:function|method|class|import|variable)[\s:]+['\"`]?(\w+)['\"`]?",
            r"['\"`](\w+)['\"`]",
            r":\s+(\w+)\s*$",
            r"unused\s+(\w+)",
        ]

        import re
        for pattern in patterns:
            match = re.search(pattern, message_text, re.IGNORECASE)
            if match:
                return match.group(1)
        return None

    def _symbol_present(self, symbol, source_code):
        if not symbol:
            return False
        if not source_code:
            return False

        import re
        pattern = r"\b" + re.escape(symbol) + r"\b"
        return re.search(pattern, source_code) is not None

    def _security_pattern_exists(self, finding, lines):
        if finding.location.line > len(lines):
            return False

        start_index = max(0, finding.location.line - 3)
        end_index = min(len(lines), finding.location.line + 2)

        context_lines = "\n".join(lines[start_index:end_index]).lower()
        message_lower = str(finding.message or "").lower()

        security_patterns = {
            "sql": [
                "execute",
                "query",
                "cursor",
                "select",
                "insert",
                "update",
                "delete",
                'f"',
                "f'",
                "%s",
                ".format",
            ],
            "injection": ["subprocess", "os.system", "shell", "popen", "eval", "exec"],
            "hardcoded": [
                "password",
                "secret",
                "key",
                "token",
                "api_key",
                "apikey",
                '= "',
                "= '",
            ],
            "xss": ["render", "html", "template", "innerhtml", "mark_safe"],
            "pickle": ["pickle", "loads", "load", "unpickle"],
            "yaml": ["yaml.load", "yaml.unsafe_load"],
            "path": ["../", "path", "file", "open(", "read("],
        }

        for category in security_patterns:
            if category in message_lower:
                indicators = security_patterns[category]
                for indicator in indicators:
                    if indicator in context_lines:
                        return True
                return False

        return True

class FinalValidator:
    def __init__(self, strict_mode=False, minimum_confidence=Confidence.LOW):
        self.source_inspector = SourceInspector(strict_mode=strict_mode)
        self.minimum_confidence = minimum_confidence
        self.strict_mode = strict_mode

    def inspect_findings(self, findings_list, source_code, file_path):
        statistics = {
            "original": len(findings_list),
            "accepted": 0,
            "rejected": 0,
            "adjusted": 0,
        }
        validated_findings = []

        for finding in findings_list:
            result = self.source_inspector.inspect(finding, source_code, file_path)
            if result.is_valid and result.modified_finding is not None:
                if self._meets_confidence_threshold(result.modified_finding.confidence):
                    validated_findings.append(result.modified_finding)
                    statistics["accepted"] += 1
                    if result.modified_finding.confidence != finding.confidence:
                        statistics["adjusted"] += 1
                else:
                    statistics["rejected"] += 1
            else:
                statistics["rejected"] += 1

        return validated_findings, statistics

    def _meets_confidence_threshold(self, confidence_level):
        confidence_ranking = {
            Confidence.HIGH: 0,
            Confidence.MEDIUM: 1,
            Confidence.LOW: 2,
            Confidence.UNCERTAIN: 3,
        }
        current_rank = confidence_ranking.get(confidence_level, 999)
        min_required_rank = confidence_ranking.get(self.minimum_confidence, 999)
        return current_rank <= min_required_rank

def remove_duplicate_findings(findings):
    if not findings:
        return []

    seen_keys = set()
    unique_findings = []

    for f in findings:
        message_prefix = ""
        if f.message:
            message_prefix = f.message[:50].lower()

        duplicate_found = False
        for offset in range(-2, 3):  # ±2 line tolerance
            key = (f.location.file, f.location.line + offset, message_prefix)
            if key in seen_keys:
                duplicate_found = True
                break

        if not duplicate_found:
            key = (f.location.file, f.location.line, message_prefix)
            seen_keys.add(key)
            unique_findings.append(f)

    return unique_findings

def integrate_with_static_analysis(llm_results, static_results, file_path):
    integrated_findings = []
    llm_by_line_number = {}

    # Group LLM findings by line number
    for f in llm_results:
        line_number = f.location.line
        if line_number not in llm_by_line_number:
            llm_by_line_number[line_number] = []
        llm_by_line_number[line_number].append(f)

    covered_static_lines = set()

    # Process LLM findings
    for f in llm_results:
        has_static_corroboration = False
        for static_item in static_results:
            static_line = static_item.get("line", static_item.get("lineno", 0))
            if abs(f.location.line - static_line) <= 2:
                has_static_corroboration = True
                covered_static_lines.add(static_line)
                break

        if has_static_corroboration:
            if f.confidence in [Confidence.MEDIUM, Confidence.LOW]:
                f.confidence = Confidence.HIGH

            suffix = " [Corroborated by static analysis]"
            if f.explanation:
                f.explanation = str(f.explanation).strip() + suffix
            else:
                f.explanation = suffix.strip()

        integrated_findings.append(f)

    # Add static-only findings that aren't covered
    for static_item in static_results:
        static_line = static_item.get("line", static_item.get("lineno", 0))
        if static_line in covered_static_lines:
            continue

        nearby_llm_line = False
        for line_num in llm_by_line_number:
            if abs(line_num - static_line) <= 2:
                nearby_llm_line = True
                break

        if nearby_llm_line:
            continue

        rule_id = static_item.get("rule_id", static_item.get("code", "STATIC"))
        message = static_item.get("message", static_item.get("msg", "Issue detected"))

        integrated_findings.append(
            Finding(
                rule_id=rule_id,
                issue_type=_determine_issue_category(static_item),
                severity=_convert_severity(static_item.get("severity", "medium")),
                confidence=Confidence.MEDIUM,
                message=message,
                location=CodeLocation(file=file_path, line=static_line),
                explanation="[From static analysis only]",
            )
        )

    return integrated_findings

def _determine_issue_category(static_item):
    combined_text = str(static_item.get("message", "") + static_item.get("rule_id", "")).lower()

    security_keywords = ["security", "injection", "xss", "sql", "secret"]
    for keyword in security_keywords:
        if keyword in combined_text:
            return IssueType.SECURITY

    dead_keywords = ["unused", "dead", "unreachable"]
    for keyword in dead_keywords:
        if keyword in combined_text:
            return IssueType.DEAD_CODE

    return IssueType.QUALITY

def _convert_severity(severity_str):
    normalized = str(severity_str or "").lower()

    if normalized in ["critical", "blocker"]:
        return Severity.CRITICAL
    if normalized in ["high", "error"]:
        return Severity.HIGH
    if normalized in ["medium", "warning"]:
        return Severity.MEDIUM

    return Severity.LOW

# Aliases for compatibility
Validator = SourceInspector
integrate_with_static_analysis = integrate_with_static_analysis

# Import necessary libraries for data preprocessing
import numpy as np
import torch
from noether.data.preprocessors import PreProcessor

class NumpyToTorchTensorConverter(PreProcessor):
    """Transform numpy arrays into PyTorch tensors and vice versa."""
    def __init__(self, normalization_key: str):
        super().__init__(normalization_key=normalization_key)

    def __call__(self, data: np.ndarray) -> torch.Tensor:
        """Convert a numpy array to a PyTorch tensor."""
        if not isinstance(data, np.ndarray):
            raise TypeError("Input must be a numpy array.")
        return torch.from_numpy(data)

    def denormalize(self, tensor: torch.Tensor) -> np.ndarray:
        """Convert a PyTorch tensor back to a numpy array."""
        if not isinstance(tensor, torch.Tensor):
            raise TypeError("Input must be a torch.Tensor.")
        return tensor.detach().cpu().numpy()

# Modified version with renamed variables and reordered statements
from functools import partial
from typing import (
    Any,
    Callable,
    Iterable,
    List,
    Optional,
    Tuple,
    Type,
    TypeVar,
    Union,
    overload,
)

T = TypeVar("T")
Output = Iterable[Union[Any, Tuple[Any], Tuple[str, Any], Tuple[str, Any, Any]]]
RichReprOutput = Output

class ReprException(Exception):
    """An error occurred during repr generation."""

@overload
def auto(cls: Optional[Type[T]]) -> Type[T]:
    ...

@overload
def auto(*, angular: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...

def auto(
    cls: Optional[Type[T]] = None, *, angular: Optional[bool] = None
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    """Class decorator to generate __repr__ from __rich_repr__"""

    def apply_decorator(cls: Type[T], angular: Optional[bool] = None) -> Type[T]:
        def custom_repr(self: T) -> str:
            """Generate repr string using __rich_repr__"""
            repr_parts: List[str] = []
            add_part = repr_parts.append
            use_angular: bool = getattr(self.__rich_repr__, "angular", False)  # type: ignore[attr-defined]

            for item in self.__rich_repr__():  # type: ignore[attr-defined]
                if isinstance(item, tuple):
                    if len(item) == 1:
                        add_part(repr(item[0]))
                    else:
                        name, val, *default_val = item
                        if name is None:
                            add_part(repr(val))
                        else:
                            if default_val and default_val[0] == val:
                                continue
                            add_part(f"{name}={val!r}")
                else:
                    add_part(repr(item))

            if use_angular:
                return f"<{self.__class__.__name__} {' '.join(repr_parts)}>"
            else:
                return f"{self.__class__.__name__}({', '.join(repr_parts)})"

        def auto_rich_repr(self: Type[T]) -> Output:
            """Automatically create __rich_repr__ based on __init__ signature"""
            try:
                sig = inspect.signature(self.__init__)
                for param_name, param in sig.parameters.items():
                    if param.kind == param.POSITIONAL_ONLY:
                        yield getattr(self, param_name)
                    elif param.kind in (
                        param.POSITIONAL_OR_KEYWORD,
                        param.KEYWORD_ONLY,
                    ):
                        if param.default == param.empty:
                            yield getattr(self, param_name)
                        else:
                            yield param_name, getattr(self, param_name), param.default
            except Exception as exc:
                raise ReprException(
                    f"Failed to auto-generate __rich_repr__; {exc}"
                ) from None

        if not hasattr(cls, "__rich_repr__"):
            auto_rich_repr.__doc__ = "Construct a rich representation"
            cls.__rich_repr__ = auto_rich_repr  # type: ignore[attr-defined]

        custom_repr.__doc__ = "Return repr(self)"
        cls.__repr__ = custom_repr  # type: ignore[assignment]

        if angular is not None:
            cls.__rich_repr__.angular = angular  # type: ignore[attr-defined]

        return cls

    if cls is None:
        return partial(apply_decorator, angular=angular)
    else:
        return apply_decorator(cls, angular=angular)

@overload
def rich_repr(cls: Optional[Type[T]]) -> Type[T]:
    ...

@overload
def rich_repr(*, angular: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...

def rich_repr(
    cls: Optional[Type[T]] = None, *, angular: bool = False
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    if cls is None:
        return auto(angular=angular)
    else:
        return auto(cls)

if __name__ == "__main__":
    @auto
    class Example:
        def __rich_repr__(self) -> Output:
            yield "first"
            yield "second", {"shopping": ["eggs", "ham", "pineapple"]}
            yield "third", "hand sanitizer"

    obj = Example()
    from pip._vendor.rich.console import Console
    console = Console()
    console.rule("Standard repr")
    console.print(obj)
    console.print(obj, width=60)
    console.print(obj, width=30)
    console.rule("Angular repr")
    Example.__rich_repr__.angular = True  # type: ignore[attr-defined]
    console.print(obj)
    console.print(obj, width=60)
    console.print(obj, width=30)

# System diagnostic script for checking current environment setup
import os
import platform
import socket
import subprocess
import sys
import time
import psutil

try:
    from urllib.parse import urlparse
    from urllib.request import urlopen
except ImportError:
    from urllib2 import urlopen
    from urlparse import urlparse

import argparse
import importlib.metadata
import torch

# URL configuration for package and mirror sources
PACKAGE_URLS = {
    "PYPI": "https://pypi.python.org/pypi/pip",
}
REGIONAL_MIRRORS = {
    "cn": {
        "PYPI(douban)": "https://pypi.douban.com/",
        "Conda(tsinghua)": "https://mirrors.tuna.tsinghua.edu.cn/anaconda/pkgs/free/",
    }
}

def test_connectivity(label, address, timeout=10):
    """Basic network connectivity test"""
    parsed = urlparse(address)
    start_time = time.time()

    try:
        socket.gethostbyname(parsed.netloc)
    except Exception as err:
        print("DNS resolution failed for {}: {}, {}".format(label, address, err))
        return

    dns_duration = time.time() - start_time
    start_time = time.time()

    try:
        _ = urlopen(address, timeout=timeout)
    except Exception as err:
        print("Connection error for {}: {}, {}, DNS took {} sec.".format(label, address, err, dns_duration))
        return

    transfer_duration = time.time() - start_time
    print(
        "Performance report for {}: {}, DNS: {:.4f} sec, TRANSFER: {:.4f} sec.".format(
            label, address, dns_duration, transfer_duration
        )
    )

def inspect_python():
    print("-----Python Environment Details-----")
    print("Version      :", platform.python_version())
    print("Compiler     :", platform.python_compiler())
    print("Build        :", platform.python_build())
    print("Architecture :", platform.architecture())

def inspect_pip():
    print("-------Pip Environment Info-------")
    try:
        import pip
        print("Version      :", pip.__version__)
        print("Installation Path:", os.path.dirname(pip.__file__))
    except ImportError:
        print("No pip installation found for this Python version.")

def _fetch_git_commit():
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError as err:
        print(f"Git command failed: {err.stderr.strip()}")
        return None
    except FileNotFoundError:
        print("Git executable not found.")
        return None

def inspect_verl():
    print("--------verl Installation---------")
    try:
        sys.path.insert(0, os.getcwd())
        import verl
        print("Version      :", verl.__version__)
        verl_path = os.path.dirname(verl.__file__)
        print("Installation Directory:", verl_path)
        try:
            commit_id = _fetch_git_commit()
            print("Commit Hash  :", commit_id)
        except AttributeError:
            print("Commit hash unavailable. ")
    except ImportError as err:
        print(f"verl not installed: {err}")
    except Exception as err:
        import traceback
        if not isinstance(err, IOError):
            print("An issue occurred while importing verl.")
            print("This likely stems from missing or incompatible dependencies.")
        print(traceback.format_exc())

def inspect_os():
    print("--------Operating System Info--------")
    print("Platform     :", platform.platform())
    print("OS Name      :", platform.system())
    print("Hostname     :", platform.node())
    print("Kernel Release:", platform.release())
    print("Kernel Version:", platform.version())

def inspect_hardware():
    print("--------Hardware Specifications--------")
    print("Machine Type :", platform.machine())
    print("CPU Info     :", platform.processor())

    if sys.platform.startswith("darwin"):
        pipe = subprocess.Popen(("sysctl", "-a"), stdout=subprocess.PIPE)
        output = pipe.communicate()[0]
        for line in output.split(b"\n"):
            if b"brand_string" in line or b"features" in line:
                print(line.strip().decode('utf-8', errors='ignore'))
    elif sys.platform.startswith("linux"):
        subprocess.call(["lscpu"])
    elif sys.platform.startswith("win32"):
        subprocess.call(["wmic", "cpu", "get", "name"])

def inspect_network(config):
    print("--------Network Diagnostics--------")
    if config.timeout > 0:
        print("Timeout set to: {} seconds".format(config.timeout))
        socket.setdefaulttimeout(10)

    for region in config.region.strip().split(","):
        r = region.strip().lower()
        if not r:
            continue
        if r in REGIONAL_MIRRORS:
            PACKAGE_URLS.update(REGIONAL_MIRRORS[r])
        else:
            import warnings
            warnings.warn(
                f"Region '{r}' does not require specific testing; please refer to global endpoints.",
                stacklevel=2,
            )

    for name, url in PACKAGE_URLS.items():
        test_connectivity(name, url, config.timeout)

def inspect_environment():
    print("--------Environment Variables--------")
    for key, value in os.environ.items():
        if (
            key.startswith("VERL_")
            or key.startswith("OMP_")
            or key.startswith("KMP_")
            or key in ("CC", "CXX")
        ):
            print('{}="{}"'.format(key, value))

def inspect_package_versions():
    packages = ["vllm", "sglang", "ray", "torch"]
    for pkg in packages:
        try:
            version = importlib.metadata.version(pkg)
            print(f"{pkg}\t     : {version}")
        except importlib.metadata.PackageNotFoundError:
            print(f"{pkg}\t     : not found.")

def inspect_cuda():
    if torch.cuda.is_available():
        try:
            cuda_runtime = torch.version.cuda
            print(f"CUDA Runtime : {cuda_runtime}")

            nvcc_output = subprocess.check_output(["nvcc", "--version"]).decode("utf-8")
            compiler_line = next(
                (line for line in nvcc_output.splitlines() if "release" in line.lower()),
                None,
            )
            if compiler_line:
                print(f"CUDA Compiler : {compiler_line.strip()}")
            else:
                print("CUDA compiler version could not be determined.")
        except FileNotFoundError as err:
            print(f"CUDA compiler : Not found: {err}")
        except Exception as err:
            print(f"Error during CUDA version check: {err}")
    else:
        print("CUDA is not available on this system.")

def _get_cpu_ram_capacity():
    """
    Retrieve total CPU memory capacity in GB.
    """
    mem_info = psutil.virtual_memory()
    return mem_info.total / (1024**3)

def _get_gpu_details():
    """
    Retrieve GPU details including type, memory, and count via nvidia-smi.
    """
    try:
        result = subprocess.run(
            [
                "nvidia-smi",
                "--query-gpu=gpu_name,memory.total",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            check=True,
        )
        gpu_lines = result.stdout.strip().split("\n")
        gpu_count = len(gpu_lines)
        gpu_data = []

        for line in gpu_lines:
            gpu_name, gpu_mem = line.split(", ")
            gpu_data.append({
                "type": gpu_name,
                "memory_gb": float(gpu_mem) / 1024,
            })
        return gpu_count, gpu_data
    except subprocess.CalledProcessError:
        print("Failed to execute nvidia-smi command.")
        return 0, []

def _get_system_overview():
    """
    Compile system overview including CPU memory, GPU info, and GPU count.
    """
    cpu_ram = _get_cpu_ram_capacity()
    gpu_count, gpu_details = _get_gpu_details()
    return {
        "cpu_ram_gb": cpu_ram,
        "gpu_count": gpu_count,
        "gpu_details": gpu_details,
    }

def inspect_system():
    print("--------System Overview--------")
    sys_data = _get_system_overview()
    print(f"CPU RAM\t     : {sys_data['cpu_ram_gb']:.2f} GB")
    print(f"GPU Count\t: {sys_data['gpu_count']}")

    for idx, gpu in enumerate(sys_data["gpu_details"]):
        print(f"GPU {idx + 1}\tType    : {gpu['type']}")
        print(f"GPU {idx + 1}\tMemory  : {gpu['memory_gb']:.2f} GB")

def parse_cli_args():
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
        description="Diagnostic utility for system environment analysis.",
    )

    components = ["python", "pip", "verl", "system", "os", "environment"]
    for comp in components:
        parser.add_argument(
            "--" + comp,
            default=1,
            type=int,
            help=f"Enable diagnostics for {comp}.",
        )

    parser.add_argument("--network", default=0, type=int, help="Enable network diagnostics.")
    parser.add_argument("--hardware", default=0, type=int, help="Enable hardware diagnostics.")
    parser.add_argument(
        "--region",
        default="",
        type=str,
        help="Specify additional regions (e.g., 'cn' for Chinese mirrors).",
    )
    parser.add_argument(
        "--timeout",
        default=10,
        type=int,
        help="Network timeout in seconds (0 disables timeout).",
    )

    return parser.parse_args()

if __name__ == "__main__":
    cli_config = parse_cli_args()

    if cli_config.python:
        inspect_python()
    if cli_config.pip:
        inspect_pip()
        inspect_package_versions()
    if cli_config.verl:
        inspect_verl()
    if cli_config.os:
        inspect_os()
    if cli_config.hardware:
        inspect_hardware()
    if cli_config.network:
        inspect_network(cli_config)
    if cli_config.environment:
        inspect_environment()
        inspect_cuda()
    if cli_config.system:
        inspect_system()

import pandas as pd
import sqlalchemy
from sqlalchemy import text
from contextlib import contextmanager
from typing import Generator, List, Optional
from app.ai.prompt_formatters import Table, TableColumn
from app.ai.prompt_formatters import TableFormatter
from functools import cached_property

class OracledbClient(DataSourceClient):
    def __init__(self, hostname, port_num, svc_name, username, passwd, schema: Optional[str] = None):
        self.hostname = hostname
        self.port_num = port_num
        self.svc_name = svc_name
        self.username = username
        self.passwd = passwd
        # Optional schema or comma-separated list of schemas
        self.schema = schema
        self._schemas = []
        if isinstance(self.schema, str) and self.schema.strip():
            parts = [s.strip() for s in self.schema.split(",") if s.strip()]
            seen = set()
            for p in parts:
                up = p.upper()
                if up not in seen:
                    seen.add(up)
                    self._schemas.append(up)

    @cached_property
    def oracle_uri(self):
        uri = (
            f"oracle+oracledb://{self.username}:{self.passwd}@"
            f"{self.hostname}:{self.port_num}/?service_name={self.svc_name}"
        )
        return uri

    @contextmanager
    def connect(self) -> Generator[sqlalchemy.engine.base.Connection, None, None]:
        """Yield a connection to an Oracle database."""
        engine = None
        conn = None
        try:
            engine = sqlalchemy.create_engine(self.oracle_uri)
            conn = engine.connect()
            # Set current schema if provided (Oracle has no search_path; use first schema)
            if self._schemas:
                current_schema = self._schemas[0]
                try:
                    conn.execute(text(f'ALTER SESSION SET CURRENT_SCHEMA = {current_schema}'))
                except Exception:
                    pass
            yield conn
        except Exception as e:
            raise RuntimeError(f"{e}")
        finally:
            if conn is not None:
                conn.close()
            if engine is not None:
                engine.dispose()

    def execute_query(self, sql: str) -> pd.DataFrame:
        """Execute SQL statement and return the result as a DataFrame."""
        try:
            with self.connect() as conn:
                df = pd.read_sql(text(sql), conn)
            return df
        except Exception as e:
            print(f"Error executing SQL: {e}")
            raise

    def get_tables(self) -> List[Table]:
        """Get tables with graceful fallback if enriched query fails."""
        try:
            return self._get_tables_enriched()
        except Exception:
            return self._get_tables_basic()

    def _get_tables_enriched(self) -> List[Table]:
        """Get tables with column/table comments. May fail on some Oracle configurations."""
        with self.connect() as conn:
            params = {}
            where_clauses = []
            if self._schemas:
                in_keys = []
                for idx, sch in enumerate(self._schemas):
                    key = f"s{idx}"
                    params[key] = sch
                    in_keys.append(f":{key}")
                where_clauses.append(f"c.owner IN ({', '.join(in_keys)})")
            else:
                params["owner"] = self.username.upper()
                where_clauses.append("c.owner = :owner")
            where_sql = " WHERE " + " AND ".join(where_clauses)
            sql = text(f"""
                SELECT
                    c.owner,
                    c.table_name,
                    c.column_name,
                    c.data_type,
                    cc.comments AS column_comment,
                    tc.comments AS table_comment
                FROM all_tab_columns c
                LEFT JOIN all_col_comments cc
                    ON c.owner = cc.owner
                    AND c.table_name = cc.table_name
                    AND c.column_name = cc.column_name
                LEFT JOIN all_tab_comments tc
                    ON c.owner = tc.owner
                    AND c.table_name = tc.table_name
                {where_sql}
                ORDER BY c.owner, c.table_name, c.column_id
            """)
            result = conn.execute(sql, params).fetchall()
            tables = {}
            for row in result:
                owner, table_name, column_name, data_type, col_comment, tbl_comment = row
                key = (owner, table_name)
