# Apply torch-specific patches for compatibility and bug fixes
from __future__ import annotations
import logging

_logger = logging.getLogger(__name__)
_TORCH_PATCHES_APPLIED_FLAG = False

def apply_torch_compatibility_fixes() -> None:
    """
    Apply targeted, version-specific monkey patches for PyTorch.
    This function is idempotent and safe to invoke multiple times.
    """
    global _TORCH_PATCHES_APPLIED_FLAG
    if _TORCH_PATCHES_APPLIED_FLAG:
        return

    try:
        import torch as _torch_lib
    except Exception:
        # torch not available or import failed: skip patching
        return

    # -------------------------------------------------------------------------
    # Patch #1: torchdata compatibility (pin_memory device argument)
    # -------------------------------------------------------------------------
    try:
        import functools
        import inspect
        from torch.utils.data import _utils as torch_data_utils

        _orig_pin_loop = torch_data_utils.pin_memory._pin_memory_loop
        _orig_pin_func = torch_data_utils.pin_memory.pin_memory
        _orig_sig = inspect.signature(_orig_pin_func)

        if "device" not in _orig_sig.parameters:
            @functools.wraps(_orig_pin_func)
            def _patched_pin_memory(data, device=None):
                return _orig_pin_func(data)

            @functools.wraps(_orig_pin_loop)
            def _patched_pin_loop(in_queue, out_queue, device_id, done_event, device):
                return _orig_pin_loop(in_queue, out_queue, device_id, done_event)

            torch_data_utils.pin_memory.pin_memory = _patched_pin_memory
            torch_data_utils.pin_memory._pin_memory_loop = _patched_pin_loop
    except Exception as err:
        _logger.debug(f"Failed to apply pin_memory patch: {err}")

    # -------------------------------------------------------------------------
    # Patch #2: DeviceMesh slicing issue (PyTorch 2.10.0 regression)
    # -------------------------------------------------------------------------
    try:
        if "2.10.0" in _torch_lib.__version__ and "nv25.11" in _torch_lib.__version__:
            from torch.distributed._mesh_layout import _MeshLayout
            from torch.distributed.device_mesh import _MeshEnv

            def _custom_get_slice_mesh_layout(self, device_mesh, mesh_dim_names):
                slice_from_root = device_mesh == self.get_root_mesh(device_mesh)
                flatten_name_to_root_layout = (
                    {
                        key: mesh._layout
                        for key, mesh in self.root_to_flatten_mapping.setdefault(device_mesh, {}).items()
                    }
                    if slice_from_root
                    else {}
                )

                mesh_dim_names_list = getattr(device_mesh, "mesh_dim_names", [])
                valid_names = [*mesh_dim_names_list, *flatten_name_to_root_layout]
                if not all(name in valid_names for name in mesh_dim_names):
                    raise KeyError(f"Invalid mesh_dim_names {mesh_dim_names}. Valid: {valid_names}")

                layout_sliced = []
                for name in mesh_dim_names:
                    if name in mesh_dim_names_list:
                        idx = mesh_dim_names_list.index(name)
                        layout_sliced.append(device_mesh._layout[idx])
                    elif name in flatten_name_to_root_layout:
                        layout_sliced.append(flatten_name_to_root_layout[name])

                sliced_sizes = tuple(layout.sizes for layout in layout_sliced)
                sliced_strides = tuple(layout.strides for layout in layout_sliced)

                slice_mesh_layout = _MeshLayout(sliced_sizes, sliced_strides)
                if not slice_mesh_layout.check_non_overlap():
                    raise RuntimeError(f"Slicing overlapping dim_names {mesh_dim_names} is not allowed.")

                # Fix for _dim_group_names access
                if hasattr(device_mesh, "_dim_group_names") and len(device_mesh._dim_group_names) > 0:
                    slice_dim_group_name = []
                    submesh_dim_names = mesh_dim_names if isinstance(mesh_dim_names, tuple) else (mesh_dim_names,)
                    for name in submesh_dim_names:
                        if name in mesh_dim_names_list:
                            idx = mesh_dim_names_list.index(name)
                            slice_dim_group_name.append(device_mesh._dim_group_names[idx])
                        elif hasattr(device_mesh, "_flatten_mapping") and name in device_mesh._flatten_mapping:
                            flatten_mesh = device_mesh._flatten_mapping[name]
                            idx = flatten_mesh.mesh_dim_names.index(name)
                            slice_dim_group_name.append(
                                flatten_mesh._dim_group_names[idx]
                            )
                    object.__setattr__(slice_mesh_layout, "_dim_group_names", slice_dim_group_name)

                return slice_mesh_layout

            _MeshEnv._get_slice_mesh_layout = _custom_get_slice_mesh_layout
            _logger.debug(f"Applied DeviceMesh fix for PyTorch {_torch_lib.__version__}")
    except (ImportError, AttributeError) as err:
        _logger.debug(f"Failed to apply DeviceMesh patch: {err}")

    # -------------------------------------------------------------------------
    # Patch #3: aten.alias.default sharding strategy (PyTorch 2.9.0 regression)
    # -------------------------------------------------------------------------
    try:
        from packaging.version import parse as _vparse
        if _vparse(_torch_lib.__version__).base_version == "2.9.0":
            from torch.distributed.tensor._ops._tensor_ops import propagate_single_input_strategy
            from torch.distributed.tensor._ops.utils import register_op_strategy

            register_op_strategy(_torch_lib.ops.aten.alias.default)(propagate_single_input_strategy)
            _logger.debug("Applied aten.alias.default sharding strategy patch for PyTorch 2.9.0")
    except Exception as err:
        _logger.debug(f"Failed to apply aten.alias.default patch: {err}")

    _TORCH_PATCHES_APPLIED_FLAG = True

