def create_dummy_visual_dataset(
    cfg: CosmosConfig,
    **extra_kwargs,
):
    is_video_mode = cfg.policy.diffusers.is_video
    img_height, img_width = cfg.policy.diffusers.inference_size
    num_train_frames = cfg.policy.diffusers.train_frames

    def generate_visual_tensor():
        if is_video_mode:
            # Video tensor should be (C, T, H, W) and range from -1.0 to 1.0
            return (
                2.0 * torch.rand(3, num_train_frames, img_height, img_width).to(torch.float32) - 1.0
            )
        else:
            # Image tensor should be (C, H, W) and range from -1.0 to 1.0
            return 2.0 * torch.rand(3, img_height, img_width)

    return CombinedDictDataset(
        **{
            "visual": LambdaDataset(generate_visual_tensor),
            "prompt_text": LambdaDataset(lambda: ""),
        }
    )

def create_dummy_validation_dataset(
    cfg: CosmosConfig,
    **extra_kwargs,
):
    is_video_mode = cfg.policy.diffusers.is_video
    img_height, img_width = cfg.policy.diffusers.inference_size
    infer_frame_count = cfg.policy.diffusers.inference_frames
    sample_step_count = cfg.policy.diffusers.sample.num_steps
    guidance_weight = cfg.policy.diffusers.sample.guidance_scale

    dict_dataset = {
        "height": LambdaDataset(lambda: img_height, length=32),
        "width": LambdaDataset(lambda: img_width, length=32),
        "inference_step": LambdaDataset(lambda: sample_step_count, length=32),
        "guidance_scale": LambdaDataset(lambda: guidance_weight, length=32),
        "prompt": LambdaDataset(lambda: str(uuid.uuid4()), length=32),
    }

    if is_video_mode:
        dict_dataset["frames"] = LambdaDataset(lambda: infer_frame_count, length=32)

    return CombinedDictDataset(**dict_dataset)

