import os
from ucagent.tools.testops import RunUnityChipTest
import ucagent.util.functions as fc
from ucagent.checkers.base import Checker, UnityChipBatchTask
from typing import Tuple
from ucagent.util.log import info
from collections import OrderedDict

class UnityChipCheckerTestMockTestBatch(Checker):
    def __init__(self, target_file, test_file_prefix, test_prefix, test_dir="tests",
                 first_arg="",
                 last_arg="",
                 batch_size=1, 
                 min_file_tests=1, timeout=300, **kw):
        self.target_file = target_file
        self.test_file_prefix = test_file_prefix
        self.test_prefix = test_prefix
        self.test_dir = test_dir
        self.first_arg = first_arg
        self.last_arg = last_arg
        self.batch_size = batch_size
        self.min_file_tests = min_file_tests
        self.timeout = timeout
        self.run_test = RunUnityChipTest()
        self.batch_task = UnityChipBatchTask("mock_test_file", self)
        self.update_dut_name(kw["cfg"])
        assert "*" in target_file, "The target_file must contain a wildcard '*' to match multiple Mock files."

    def get_template_data(self):
        ret = self.batch_task.get_template_data(
            "TOTAL_MOCKS", "COMPLETED_MOCKS", "LIST_CURRENT_MOCKS"
        )
        return ret

    def on_init(self):
        self.batch_task.source_task_list = fc.find_files_by_pattern(
            self.workspace, self.target_file
        )
        self.batch_task.update_current_tbd()
        info(f"Found {len(self.batch_task.source_task_list)} mock component files to check.")
        return super().on_init()

    def set_workspace(self, workspace: str):
        """
        Set the workspace for the test case checker.
        :param workspace: The workspace directory to be set.
        """
        super().set_workspace(workspace)
        self.run_test.set_workspace(workspace)
        return self

    def do_check(self, timeout=0, is_complete=False, **kw) -> Tuple[bool, object]:
        """Check the Mock test implementation for correctness."""
        test_dir_full_path = self.get_path(self.test_dir)
        if not os.path.exists(test_dir_full_path):
            return False, {"error": f"test directory '{self.test_dir}' does not exist in workspace."}

        # Sync source task
        self.batch_task.source_task_list = fc.find_files_by_pattern(self.workspace, self.target_file)
        self.batch_task.update_current_tbd()

        if len(self.batch_task.source_task_list) == 0:
            return False, {
                "error": f"No mock component files found with pattern '{self.target_file}' in workspace."
            }

        # Do check in batch
        task_map = OrderedDict()
        no_test_files = []
        mock_file_prefix = os.path.basename(self.target_file).split("*")[0]

        for task_file in self.batch_task.source_task_list:
            # {OUT}/tests/{DUT}_mock_*.py => {OUT}/tests/test_{DUT}_mock_*.py
            dir_path = os.path.dirname(task_file)
            base_name = os.path.basename(task_file)
            mock_name = base_name.split(".py")[0].replace(mock_file_prefix, "")

            if not mock_name:
                return False, {
                    "error": f"Cannot extract MockComponentName from file '{task_file}'. Please ensure the file name is correct: `{mock_file_prefix}<MockComponentName>.py`"
                }

            test_file = dir_path + "/" + self.test_file_prefix + mock_name + "*.py"
            test_file_list = fc.find_files_by_pattern(self.workspace, test_file)

            if (not test_file_list) and (task_file in self.batch_task.tbd_task_list):
                no_test_files.append(f"{task_file} => {test_file} (not found)")
                continue

            task_map[task_file] = test_file_list

        if len(no_test_files) > 0:
            return False, {
                "error": "No corresponding test files found for some mock component files.",
                "details": no_test_files
            }

        pass_results = []
        fail_results = OrderedDict()

        for target_mock, target_tests in task_map.items():
            info(f"Checking mock component test file(s) for '{target_mock}': {', '.join(target_tests)}")
            ret, msg = self.do_one_check(target_tests, test_dir_full_path, timeout)

            if not ret:
                fail_results[target_mock] = msg
            else:
                pass_results.append(target_mock)

        note_msg = []

        # Complete
        self.batch_task.sync_gen_task(
            pass_results,
            note_msg,
            "Completed file changed."
        )

        if fail_results:
            return False, {
                "error": "Some mock component test files check failed.",
                "details": fail_results
            }

        return self.batch_task.do_complete(note_msg, is_complete, "", "", "")

    def do_one_check(self, test_files, test_dir_full_path, timeout) -> Tuple[bool, object]:
        if len(test_files) == 0:
            tfiles = ', '.join(self.target_file)
            return False, {"error": f"No test files found with pattern '{tfiles}' in workspace."}

        error_cases = []

        for tfile in test_files:
            if test_dir_full_path not in self.get_path(tfile):
                error_cases.append(f"The test file '{tfile}' is not under the test directory '{self.test_dir}'.")
                continue

            test_func_list = fc.get_target_from_file(self.get_path(tfile), f"test*",
                                                         ex_python_path=self.workspace,
                                                         dtype="FUNC")

            for test_func in test_func_list:
                if test_func.__name__.startswith(self.test_prefix) is False:
                    error_cases.append(f"The '{test_func.__name__}' test function's name must start with '{self.test_prefix}'.")
                    continue

                args = fc.get_func_arg_list(test_func)

                if self.first_arg and (len(args) < 1 or args[0] != self.first_arg):
                    error_cases.append(f"The '{test_func.__name__}' test function's first arg must be '{self.first_arg}', but got ({', '.join(args)}).")

                if self.last_arg and (len(args) < 1 or args[-1] != self.last_arg):
                    error_cases.append(f"The '{test_func.__name__}' test function's last arg must be '{self.last_arg}', but got ({', '.join(args)}).")

            if len(test_func_list) < self.min_file_tests:
                error_cases.append(f"Insufficient testcases: {len(test_func_list)} test functions found, minimum required is {self.min_file_tests} in file '{tfile}'. "+
                                    "Please ensure you have implemented enough test cases (need pytest function based not class based).")

        if len(error_cases) > 0:
            return False, {
                "error": "Check test functions failed.",
                "details": error_cases
            }

        # Run test
        timeout = timeout if timeout > 0 else self.timeout
        self.run_test.set_pre_call_back(
            lambda p: self.set_check_process(p, timeout + 10)  # Set the process for the checker
        )

        py_case_files = [fc.rm_workspace_prefix(test_dir_full_path,
                                                self.get_path(t)) for t in test_files]

        report, str_out, str_err = self.run_test.do(
            test_dir_full_path,
            pytest_ex_args=" ".join(py_case_files),
            return_stdout=True, return_stderr=True, return_all_checks=True,
            timeout=timeout
        )

        test_pass, test_msg = fc.is_run_report_pass(report, str_out, str_err)

        if not test_pass:
            return False, test_msg

        if not report or "tests" not in report:
            return False, {
                "error": f"Test execution failed or returned invalid report.",
                "STD_OUT": str_out,
                "STD_ERR": str_err,
            }

        tc_total = report["tests"]["total"]
        tc_failed = report["tests"]["fails"]

        if tc_failed > 0:
            return False, {
                "error": f"Test failed: {tc_failed}/{tc_total} test cases failed. Need all test cases to pass.",
                "STD_OUT": str_out,
                "STD_ERR": str_err,
            }

        ret, msg = fc.check_has_assert_in_tc(self.workspace, report)

        if not ret:
            return ret, msg

        return True, {"message": f"{self.__class__.__name__} check passed."}

# Control a Kasa-compatible smart bulb on the LAN (modern python-kasa API)
import argparse
import asyncio

def parse_arguments():
    parser = argparse.ArgumentParser(description="Control a Kasa-compatible smart bulb on the LAN (modern python-kasa API)")
    parser.add_argument("--ip", required=True, help="IP address of the bulb on the LAN")
    parser.add_argument("--on", action="store_true", help="Turn bulb on")
    parser.add_argument("--off", action="store_true", help="Turn bulb off")
    parser.add_argument("--brightness", type=int, help="Set brightness (0-100)")
    parser.add_argument("--hsv", nargs=3, type=int, metavar=("HUE","SAT","VAL"), help="Set color as HSV integers: H(0-360) S(0-100) V(0-100)")
    parser.add_argument("--transition", type=float, default=0, help="Transition duration in seconds (if supported)")
    return parser.parse_args()

async def locate_device(ip_address: str):
    try:
        from kasa import Discover
    except Exception:
        raise
    # discover_single returns a Device or None
    device = await Discover.discover_single(ip_address)
    if device is None:
        raise RuntimeError(f"Device at {ip_address} not found via discovery")
    return device

async def run_main():
    arguments = parse_arguments()
    try:
        # Import lazily so users without python-kasa get a helpful message
        from kasa import Discover
    except Exception:
        print("Error importing python-kasa. Install with: pip install python-kasa")
        raise
    device = await locate_device(arguments.ip)
    # Connect/update device state
    try:
        await device.update()
    except Exception:
        # Some devices require explicit connect
        try:
            await device.connect()
            await device.update()
        except Exception as error:
            print("Failed to connect/update device:", error)
            raise
    # Convenience access to light module (module keys may vary in capitalization)
    light_module = None
    for key in ("Light", "light", "light-1"):
        if key in getattr(device, 'modules', {}):
            light_module = device.modules[key]
            break
    # Fallback: try to find first module with 'Light' class name
    if light_module is None:
        for module in getattr(device, 'modules', {}).values():
            # many modules have a 'MODULE' or class name; we try to find a candidate
            try:
                name = getattr(module, '__class__', type(module)).__name__
                if 'Light' in name or 'light' in name.lower():
                    light_module = module
                    break
            except Exception:
                continue
    # If device has high-level methods, use them as fallback
    async def activate_light():
        if hasattr(device, 'turn_on'):
            await device.turn_on()
        elif light_module and hasattr(light_module, 'turn_on'):
            await light_module.turn_on()
        else:
            raise RuntimeError("No turn_on method available for device")
    async def deactivate_light():
        if hasattr(device, 'turn_off'):
            await device.turn_off()
        elif light_module and hasattr(light_module, 'turn_off'):
            await light_module.turn_off()
        else:
            raise RuntimeError("No turn_off method available for device")
    async def adjust_brightness(level):
        if light_module and hasattr(light_module, 'set_brightness'):
            await light_module.set_brightness(level)
        elif 'set_light_state' in dir(device):
            await device.set_light_state(brightness=level)
        else:
            # try generic module method
            if light_module and hasattr(light_module, 'set_state'):
                await light_module.set_state(brightness=level)
            else:
                raise RuntimeError("No supported brightness API found on device")
    async def adjust_color(hue, saturation, value):
        if light_module and hasattr(light_module, 'set_hsv'):
            await light_module.set_hsv(hue, saturation, value)
        elif light_module and hasattr(light_module, 'set_rgb'):
            import colorsys
            red, green, blue = colorsys.hsv_to_rgb(hue/360.0, saturation/100.0, value/100.0)
            rgb = (int(red*255), int(green*255), int(blue*255))
            await light_module.set_rgb(*rgb)
        elif hasattr(device, 'set_light_state'):
            # try passing dict
            await device.set_light_state(hue=hue, saturation=saturation, brightness=value)
        else:
            raise RuntimeError("No supported color API found on device")
    # Execute requested actions
    if arguments.on:
        await activate_light()
        print(f"Turned on {arguments.ip}")
    if arguments.off:
        await deactivate_light()
        print(f"Turned off {arguments.ip}")
    if arguments.brightness is not None:
        level = max(0, min(100, arguments.brightness))
        try:
            await adjust_brightness(level)
            print(f"Set brightness to {level}%")
        except Exception as err:
            print("Failed to set brightness:", err)
    if arguments.hsv:
        hue, saturation, value = arguments.hsv
        hue = max(0, min(360, hue))
        saturation = max(0, min(100, saturation))
        value = max(0, min(100, value))
        try:
            await adjust_color(hue, saturation, value)
            print(f"Set color HSV=({hue},{saturation},{value})")
        except Exception as err:
            print("Failed to set color:", err)

if __name__ == "__main__":
    asyncio.run(run_main())

# Tool for requesting user clarification during planning
from typing import Dict, Any, Type, AsyncIterator
from pydantic import BaseModel
from app.ai.tools.base import Tool
from app.ai.tools.metadata import ToolMetadata
from app.ai.tools.schemas import ClarifyInput, ClarifyOutput
from app.ai.tools.schemas.events import (
    ToolEvent,
    ToolStartEvent,
    ToolEndEvent,
)

class ClarifyTool(Tool):
    """Clarify tool - signals that the planner needs user clarification.
    The actual questions are output by the planner in assistant_message.
    This tool just marks analysis_complete=True to stop the loop and wait for user response.
    """

    @property
    def metadata(self) -> ToolMetadata:
        return ToolMetadata(
            name="clarify",
            description=(
                "ACTION: Signal that you need clarification from the user. "
                "Output your questions in assistant_message, then call this tool to pause and wait for response."
            ),
            category="action",
            version="1.0.0",
            input_schema=ClarifyInput.model_json_schema(),
            output_schema=ClarifyOutput.model_json_schema(),
            max_retries=1,
            timeout_seconds=10,
            idempotent=True,
            required_permissions=[],
            tags=["clarification", "questions", "user-interaction"],
            examples=[
                {
                    "input": {
                        "context": "User requested revenue analysis but didn't specify time period"
                    },
                    "description": "Signal need for clarification (questions go in assistant_message)"
                },
                {
                    "input": {},
                    "description": "Simple clarification signal with no context"
                }
            ]
        )

    @property
    def input_model(self) -> Type[BaseModel]:
        return ClarifyInput

    @property
    def output_model(self) -> Type[BaseModel]:
        return ClarifyOutput

    async def run_stream(self, tool_input: Dict[str, Any], runtime_ctx: Dict[str, Any]) -> AsyncIterator[ToolEvent]:
        data = ClarifyInput(**tool_input)

        yield ToolStartEvent(
            type="tool.start",
            payload={"context": data.context}
        )

        # Simple observation - just mark that we're waiting for user response
        # The actual questions are in the planner's assistant_message
        summary = "Waiting for user clarification"
        if data.context:
            summary = f"Waiting for user clarification: {data.context}"

        yield ToolEndEvent(
            type="tool.end",
            payload={
                "output": {
                    "status": "awaiting_response"
                },
                "observation": {
                    "summary": summary,
                    "artifacts": [],
                    "analysis_complete": True,
                    # No final_answer - the planner's assistant_message has the questions
                },
            }
        )

import base64
import json
import re
from typing import Optional, Tuple, List
from urllib.parse import unquote, urlparse

class ConfigurationChecker:
    @staticmethod
    def is_base64_encoded(s: str) -> bool:
        try:
            s = s.rstrip('=')
            return bool(re.match(r'^[A-Za-z0-9+/\-_]*$', s))
        except:
            return False

    @staticmethod
    def decode_base64_url_safe(s: str) -> Optional[bytes]:
        try:
            s = s.replace('-', '+').replace('_', '/')
            padding_needed = 4 - (len(s) % 4)
            if padding_needed != 4:
                s += '=' * padding_needed
            return base64.b64decode(s)
        except:
            return None

    @staticmethod
    def decode_base64_string(text: str) -> Optional[str]:
        try:
            if ConfigurationChecker.is_base64_encoded(text):
                decoded_bytes = ConfigurationChecker.decode_base64_url_safe(text)
                if decoded_bytes:
                    return decoded_bytes.decode('utf-8')
            return None
        except:
            return None

    @staticmethod
    def sanitize_vmess_entry(config: str) -> str:
        if "vmess://" in config:
            base64_segment = config[8:]
            base64_filtered = re.split(r'[^A-Za-z0-9+/=_-]', base64_segment)[0]
            return f"vmess://{base64_filtered}"
        return config

    @staticmethod
    def standardize_hysteria2_scheme(config: str) -> str:
        if config.startswith('hy2://'):
            return config.replace('hy2://', 'hysteria2://', 1)
        return config

    @staticmethod
    def is_vmess_entry(config: str) -> bool:
        try:
            if not config.startswith('vmess://'):
                return False
            base64_segment = config[8:]
            decoded_data = ConfigurationChecker.decode_base64_url_safe(base64_segment)
            if decoded_data:
                json.loads(decoded_data)
                return True
            return False
        except:
            return False

    @staticmethod
    def is_tuic_entry(config: str) -> bool:
        try:
            if config.startswith('tuic://'):
                parsed = urlparse(config)
                return bool(parsed.netloc and ':' in parsed.netloc)
            return False
        except:
            return False

    @staticmethod
    def transform_ssconf_to_https(url: str) -> str:
        if url.startswith('ssconf://'):
            return url.replace('ssconf://', 'https://', 1)
        return url

    @staticmethod
    def has_base64_payload(config: str) -> Tuple[bool, str]:
        protocols = ['vmess://', 'vless://', 'ss://', 'tuic://']
        for protocol in protocols:
            if config.startswith(protocol):
                base64_segment = config[len(protocol):]
                decoded_url = unquote(base64_segment)
                if (ConfigurationChecker.is_base64_encoded(decoded_url) or 
                    ConfigurationChecker.is_base64_encoded(base64_segment)):
                    return True, protocol[:-3]
        return False, ''

    @staticmethod
    def inspect_base64_payload(text: str) -> Optional[str]:
        try:
            decoded_text = ConfigurationChecker.decode_base64_string(text)
            if decoded_text:
                protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
                for protocol in protocols:
                    if protocol in decoded_text:
                        return decoded_text
            return None
        except:
            return None

    @staticmethod
    def extract_configs(text: str) -> List[str]:
        configs = []
        lines = text.split('\n')

        for line in lines:
            line = line.strip()
            if not line:
                continue

            if ConfigurationChecker.is_base64_encoded(line):
                extracted_content = ConfigurationChecker.inspect_base64_payload(line)
                if extracted_content:
                    text = extracted_content

            protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
            current_index = 0
            text_size = len(text)

            while current_index < text_size:
                next_config_index = text_size
                found_protocol = None

                for protocol in protocols:
                    protocol_index = text.find(protocol, current_index)
                    if protocol_index != -1 and protocol_index < next_config_index:
                        next_config_index = protocol_index
                        found_protocol = protocol

                if found_protocol:
                    if current_index < next_config_index and configs:
                        segment = text[current_index:next_config_index].strip()
                        if ConfigurationChecker.is_valid_entry(segment):
                            configs.append(segment)

                    current_index = next_config_index
                    next_protocol_index = text_size

                    for protocol in protocols:
                        pos = text.find(protocol, next_config_index + len(found_protocol))
                        if pos != -1 and pos < next_protocol_index:
                            next_protocol_index = pos

                    segment = text[next_config_index:next_protocol_index].strip()
                    if found_protocol == "vmess://":
                        segment = ConfigurationChecker.sanitize_vmess_entry(segment)
                    elif found_protocol == "hy2://":
                        segment = ConfigurationChecker.standardize_hysteria2_scheme(segment)
                    if ConfigurationChecker.is_valid_entry(segment):
                        configs.append(segment)

                    current_index = next_protocol_index
                else:
                    break

        return configs

    @staticmethod
    def clean_entry(config: str) -> str:
        config = re.sub(r'[\U0001F300-\U0001F9FF]', '', config)
        config = re.sub(r'[\x00-\x08\x0B-\x1F\x7F-\x9F]', '', config)
        config = re.sub(r'[^\S\r\n]+', ' ', config)
        config = config.strip()
        return config

    @staticmethod
    def is_valid_entry(config: str) -> bool:
        if not config:
            return False

        protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
        return any(config.startswith(p) for p in protocols)

    @classmethod
    def validate_entry_by_protocol(cls, config: str, protocol: str) -> bool:
        try:
            if protocol in ['vmess://', 'vless://', 'ss://', 'tuic://']:
                if protocol == 'vmess://':
                    return cls.is_vmess_entry(config)
                if protocol == 'tuic://':
                    return cls.is_tuic_entry(config)
                base64_segment = config[len(protocol):]
                decoded_url = unquote(base64_segment)
                if cls.is_base64_encoded(decoded_url) or cls.is_base64_encoded(base64_segment):
                    return True
                if cls.decode_base64_url_safe(base64_segment) or cls.decode_base64_url_safe(decoded_url):
                    return True
            elif protocol in ['trojan://', 'hysteria2://', 'hy2://', 'wireguard://']:
                parsed = urlparse(config)
                return bool(parsed.netloc and '@' in parsed.netloc)
            elif protocol == 'ssconf://':
                return True
            return False
        except:
            return False

# Modified version of AbstractModel with renamed variables and reordered logic
import json
import sys

class BaseModel(object):
    """Base class for all data models."""

    def _convert_to_dict(self, skip_none=True):
        """Convert object to dictionary representation, optionally excluding None values."""
        def traverse(item):
            if isinstance(item, BaseModel):
                attributes = vars(item)
                result = {}
                for field_name in attributes:
                    processed_value = traverse(attributes[field_name])
                    if skip_none and processed_value is None:
                        continue
                    # Capitalize first letter for JSON key
                    json_key = field_name[0].upper() + field_name[1:] if field_name else ""
                    result[json_key] = processed_value
                return result
            elif isinstance(item, list):
                return [traverse(element) for element in item 
                       if not (skip_none and traverse(element) is None)]
            else:
                # Handle string encoding for Python 2 compatibility
                if isinstance(item, type(u"")) and sys.version_info[0] == 2:
                    return item.encode("UTF-8")
                return item

        return traverse(self)

    def _load_from_dict(self, data):
        """Initialize object from dictionary data."""
        return None

    def to_json(self, *args, **options):
        """Serialize object to JSON string with Unicode support by default."""
        if "ensure_ascii" not in options:
            options["ensure_ascii"] = False
        return json.dumps(self._convert_to_dict(skip_none=True), *args, **options)

    def load_json(self, json_data):
        """Deserialize JSON string to populate object attributes."""
        parsed_data = json.loads(json_data)
        self._load_from_dict(parsed_data)

    def __str__(self):
        return "%s" % self.to_json()

import os
import click

from cli.helpers import get_project_name, find_project_files, not_in_project, wrong_place_warning
from cli.helpers.logger import log_error
from cli.commands.inspect.main import InspectorHelper, inspect as run_inspect
from cli.commands.create.helpers.app import AppHelper
from cli.commands.create.helpers.creator import CreatorHelper
from cli.commands.create.helpers.inquire import inquire_app_presets, inquire_docker_options, inquire_project_presets


@click.group()
@click.pass_context
def generate(ctx):
    """
    Generates projects and applications.
    """
    ctx.ensure_object(dict)

    current_dir = os.getcwd()
    dry_run = ctx.obj.get('dry', False)
    verbose_mode = ctx.obj.get('verbose', False)

    ctx.obj['creator'] = CreatorHelper(
        cwd=current_dir,
        dry=dry_run,
        verbose=verbose_mode
    )

    proj_path, proj_dir, mgmt_file = find_project_files(current_dir)
    ctx.obj['project_path'] = proj_path
    ctx.obj['project_dir'] = proj_dir
    ctx.obj['mgmt_file'] = mgmt_file
    ctx.obj['management_module'] = mgmt_file
    ctx.obj['project_name'] = get_project_name(mgmt_file)


@generate.command(name='project')
@click.argument('project_name')
@click.argument('app_names', nargs=-1)
@click.option('--default-config', is_flag=True, help="Use default settings for project")
@click.pass_context
def generate_project(ctx, project_name, app_names, default_config):
    """
    Initializes a new Django project.
    Similar to `django-admin startproject`, but with extended features.
    Apps can be created alongside the project in one step:
        D generate project mysite blog forum shop
    """
    try:
        creator = ctx.obj['creator']

        # Gather project configuration options
        config_options = inquire_project_presets(project_name=project_name, default=default_config)

        # Handle Docker-related services if applicable
        docker_services = {}
        if 'dockerized' in config_options.get('presets', {}):
            docker_services = inquire_docker_options(default=default_config)

        # Create the project
        creator.create_project(
            project=project_name,
            apps=list(app_names),
            **config_options,
            **docker_services,
        )

        # Save CLI configuration
        creator.write_cli_config()

    except (KeyboardInterrupt, SystemExit, Exception) as err:
        log_error(f"Terminated: {repr(err)}")


@generate.command(name='apps')
@click.argument('app_list', nargs=-1)
@click.option('--target-project', '-p', help="Name of the target Django project.")
@click.option('--as-package', is_flag=True, help="Treat app as installable package.")
@click.option('--project-root', '-d', type=click.Path(), help="Path to project’s management file.")
@click.option('--include-api', is_flag=True, help="Include API-specific files (e.g., urls.py).")
@click.option('--default-values', is_flag=True, help="Apply default configurations")
@click.pass_context
def generate_apps(ctx, app_list, target_project, as_package, project_root, include_api, default_values):
    """
    Creates new Django apps with standardized internal structure.
    Supports multiple apps at once:
        D generate apps catalog store analytics
    Each app includes folders for forms, models, serializers, tests, templates, views, viewsets, etc.
    """
    try:
        # Resolve project name and management file path
        project_name = target_project or ctx.obj.get('project_name')
        mgmt_path = project_root or ctx.obj.get('management_module')

        # Warn if outside project context unless creating as package
        if not_in_project(ctx) and not as_package:
            if not click.confirm("You're not inside a project. Continue anyway?"):
                return

        app_generator = AppHelper(
            cwd=os.getcwd(),
            dry=ctx.obj.get('dry', False),
            verbose=ctx.obj.get('verbose', False),
            package=as_package,
        )

        preset_options = {}
        if len(app_list) == 1 and as_package:
            preset_options = inquire_app_presets(app_list[0], default=default_values)

        for app in app_list:
            app_generator.create_app(
                project=project_name,
                app=app,
                api=include_api,
                **preset_options,
            )
            click.echo(f"✅ App '{app}' created successfully.")

        # Optional: display final config state
        print(app_generator.config)

    except (KeyboardInterrupt, SystemExit, Exception) as error:
        log_error("Operation interrupted!")


@generate.command(name='settings')
@click.option('--skip-apps', is_flag=True, help="Skip adding apps to INSTALLED_APPS.")
@click.option('--replace-existing', is_flag=True, help="Overwrite existing settings.py content.")
@click.pass_context
def generate_settings(ctx, skip_apps, replace_existing):
    """
    Generates a custom settings file for the project.
    """
    try:
        wrong_place_warning(ctx)
        project = ctx.obj['project_name']
        base_path = os.path.join(ctx.obj['management_module'], project)
        creator = ctx.obj['creator']

        if not skip_apps:
            inspector = InspectorHelper(cwd=ctx.obj['management_module'])
            discovered_apps = ctx.invoke(run_inspect, scope='apps', suppress_output=True)
            creator.create_file_in_context(
                project=project,
                template='settings.tpl',
                filename='settings_override.py',
                apps=discovered_apps
            )
        else:
            creator.create_file_in_context(
                project=project,
                template='settings.tpl',
                filename='settings_override.py',
            )

    except (KeyboardInterrupt, SystemExit, Exception) as exc:
        log_error(f"Aborted: {repr(exc)}")

