import six
from rally.common.i18n import _

class RallyBaseError(Exception):
    """Core exception class for Rally errors.

    To use this properly, subclass it and set a 'template' string.
    The template will be formatted using keyword arguments passed to the constructor.
    """
    template = _("%(message)s")

    def __init__(self, message=None, **details):
        self.details = details
        if "%(message)s" in self.template:
            details.update({"message": message})
        super(RallyBaseError, self).__init__(self.template % details)

    def describe(self):
        return six.text_type(self)

