class PackageRequirement:
    """
    Wrapper class for handling Python package requirements.
    Provides a simplified interface to work with package version specifications.
    """
    WILDCARD_VERSION = 'Any'
    _req_obj = None

    def __init__(self, req: Optional = None):
        self._req_obj = req

    @property
    def version_constraint(self) -> str:
        """Get the version constraint string for the requirement"""
        if self._req_obj and hasattr(self._req_obj, 'specifier'):
            spec_str = str(self._req_obj.specifier)
            return spec_str if spec_str else self.WILDCARD_VERSION
        return self.WILDCARD_VERSION

    def matches_requirement(self, other: 'PackageRequirement') -> bool:
        """Check if this requirement matches another requirement"""
        return self._req_obj == other._req_obj

import random
from Texture import Texture

def generate_stars(render_region):
    width = render_region.width
    height = render_region.height
    for col in range(width - 1):
        for row in range(height - 1):
            if random.randint(0, col) == col and col > (0.01 * row + 400):
                render_region.pixels[col][row] = (255, 255, 255)

def apply_water_effect(render_region):
    width = render_region.width
    height = render_region.height
    for x in range(width - 1):
        for y in range(height - 1):
            if x > (0.01 * y + 400):
                original_pixel = render_region.pixels[x][y]
                r_val, g_val, b_val = original_pixel[:3]

                new_r = min(r_val + 5, 255)
                new_g = min(g_val + 2, 255)
                new_b = min(b_val + 12, 255)

                mirrored_x = 400 - (x - 400)
                render_region.pixels[mirrored_x][y] = bytes([new_b, new_g, new_r])

def compute_lighting(w, v, u, normals, light_dir):
    nA, nB, nC = normals
    intensities = [dot_product(n, light_dir) for n in (nA, nB, nC)]
    weighted_intensity = w * intensities[0] + v * intensities[1] + u * intensities[2]
    return weighted_intensity ** 3

def sample_texture(render, tx, ty):
    return render.active_texture.get_color(tx, ty)

def apply_common_shader(render, **kwargs):
    w, v, u = kwargs['bar']
    tx, ty = kwargs['texture_coords']
    tcolor = sample_texture(render, tx, ty)
    normals = kwargs['varying_normals']
    intensity = compute_lighting(w, v, u, normals, render.light)

    if tcolor:
        # Swapped RGB components intentionally to match original behavior
        r_out = int(tcolor[2] * intensity) if tcolor[0] * intensity > 0 else 0
        g_out = int(tcolor[1] * intensity) if tcolor[1] * intensity > 0 else 0
        b_out = int(tcolor[0] * intensity) if tcolor[2] * intensity > 0 else 0
        return (r_out, g_out, b_out)
    else:
        return (0, 0, 0)

def starry_sky(render, **kwargs):
    return apply_common_shader(render, **kwargs)

def mountainous_terrain(render, **kwargs):
    return apply_common_shader(render, **kwargs)

def planetary_body(render, **kwargs):
    return apply_common_shader(render, **kwargs)

def terrain_fragment(render, **kwargs):
    w, v, u = kwargs['bar']
    tx, ty = kwargs['texture_coords']
    grey_value = int(ty * 100)
    base_color = (grey_value, 50, 15)

    normals = kwargs['varying_normals']
    intensities = [dot_product(n, render.light) for n in normals]
    weighted_intensity = w * intensities[0] + v * intensities[1] + u * intensities[2]

    # Quantize intensity levels
    if weighted_intensity > 0.85:
        final_intensity = 1.0
    elif weighted_intensity > 0.60:
        final_intensity = 0.80
    elif weighted_intensity > 0.45:
        final_intensity = 0.60
    elif weighted_intensity > 0.30:
        final_intensity = 0.45
    elif weighted_intensity > 0.15:
        final_intensity = 0.30
    else:
        final_intensity = 0.0

    r_out = int(base_color[2] * final_intensity) if base_color[0] * final_intensity > 0 else 0
    g_out = int(base_color[1] * final_intensity) if base_color[1] * final_intensity > 0 else 0
    b_out = int(base_color[0] * final_intensity) if base_color[2] * final_intensity > 0 else 0
    return (r_out, g_out, b_out)

def solid_ground(render, **kwargs):
    w, v, u = kwargs['bar']
    tx, ty = kwargs['texture_coords']
    tcolor = sample_texture(render, tx, ty)
    normals = kwargs['varying_normals']
    intensity = compute_lighting(w, v, u, normals, render.light) / 4

    if tcolor:
        r_out = int(tcolor[2] * intensity) if tcolor[0] * intensity > 0 else 0
        g_out = int(tcolor[1] * intensity) if tcolor[1] * intensity > 0 else 0
        b_out = int(tcolor[0] * intensity) if tcolor[2] * intensity > 0 else 0
        return (r_out, g_out, b_out)
    else:
        return (0, 0, 0)

def table_surface(render, **kwargs):
    tx, ty = kwargs['texture_coords']
    return (255, 255, 255)

