def _bytes_to_ascii_string(byte_data):
    """Convert raw bytes to ASCII string by interpreting each byte as character."""
    return ''.join(chr(b) for b in byte_data)


def _hex_to_ascii(hex_str):
    """Convert hex-encoded string (e.g., '6162') to ASCII ('ab')."""
    return ''.join(chr(int(hex_str[i:i+2], 16)) for i in range(0, len(hex_str), 2))


class MediaMetadata(object):
