    def save_cover_locally(self):
        """Write cover image data to temporary file and return path."""
        fd, path = tempfile.mkstemp(prefix="art_", suffix=".png")
        os.close(fd)
        try:
            with open(path, 'wb') as f:
                f.write(self.cover_art.raw_bytes)
        except Exception:
