class Artwork(object):
    """Encapsulates image data with optional metadata."""

    def __init__(self, base64=None, raw_bytes=None, mime_type=None, ext=None, hash_val=None):
        self._raw_bytes = raw_bytes
        self._base64_str = base64
        self._mime = mime_type
        self._ext = ext or ".png"
        self._hash = hash_val

    @property
    def encoded_base64(self):
        """Return base64 representation of image data."""
        if self._base64_str:
            return self._base64_str
        if self._raw_bytes:
            self._base64_str = try_decode(standard_b64encode(try_encode(self._raw_bytes)))
            return self._base64_str
        return None

    @property
    def raw_bytes(self):
        """Return raw binary image data."""
        return self._raw_bytes

    @property
    def content_type(self):
        """Determine MIME type from bytes if not already set."""
        if self._mime:
            return self._mime
        if self._raw_bytes and HAS_MAGIC:
            try:
                detected = magic.from_buffer(self._raw_bytes, mime=True)
                self._mime = try_decode(detected) if isinstance(detected, bytes) else detected
                return self._mime
            except Exception:
                pass
        return None

    @property
    def extension(self):
        """Return assumed file extension."""
        return self._ext

    @property
    def checksum(self):
        """SHA-256 hash of raw image bytes."""
        if self._hash:
            return self._hash
        if self._raw_bytes:
            self._hash = hashlib.sha256(self._raw_bytes).hexdigest()
            return self._hash
        return None

    def to_dict(self, include_base64=False):
        """Return dictionary representation."""
        result = {
            "mime": self.content_type,
            "extension": self.extension,
            "checksum": self.checksum,
        }
        if include_base64:
            result["base64"] = self.encoded_base64
        return result


class MetadataEntry(object):
    """Represents a single DAAP/RTSP metadata entry."""

    def __init__(self, raw_input):
        if isinstance(raw_input, str):
            try:
                raw_input = ET.fromstring(raw_input)
            except ET.ParseError:
                LOGGER.exception("Malformed XML input skipped")
                return

        if isinstance(raw_input, ET.Element):
            raw_input = etree_to_dict(raw_input)

        if isinstance(raw_input, dict):
            raw_input = DictObject.objectify(raw_input)

        assert isinstance(raw_input, DictObject), "Expected DictObject after conversion"
        assert hasattr(raw_input.item, "type"), "Missing 'item.type' field"

        self.type_code = _hex_to_ascii(raw_input.item.type)
        self.code = _hex_to_ascii(raw_input.item.code)
        self.length = int(raw_input.item.length)

        if "data" in raw_input.item:
            assert self.length > 0, "Length must be positive when data is present"
            payload = raw_input.item.data
            text = payload.get("#text", "")
            encoding = payload.get("@encoding", "").lower()

            self._raw_data = self._decode_payload(text, encoding)
            self._base64_cached = text if encoding == "base64" else None
        else:
            assert self.length == 0, "Length zero requires no data"
            self._raw_data = b""
            self._base64_cached = None

    def _decode_payload(self, text, encoding):
        if encoding == "base64":
            return standard_b64decode(text.encode("ascii"))
        elif encoding == "hex":
            return bytes.fromhex(text)
        else:
            raise ValueError(f"Unsupported encoding: {encoding}")

    @property
    def as_text(self):
        """Decode raw bytes to UTF-8 string."""
        return try_decode(self._raw_data)

    @property
    def as_integer(self):
        """Interpret raw bytes as big-endian integer."""
        if not self._raw_data:
            return 0
        try:
            return int.from_bytes(self._raw_data, byteorder='big', signed=False)
        except AttributeError:
            # Fallback for Python 2
            val = 0
            for ch in self._raw_data:
                val = (val << 8) | ord(ch)
            return val

    @property
    def as_datetime(self):
        """Convert integer timestamp to datetime."""
        ts = self.as_integer
        return datetime.fromtimestamp(ts)

    @property
    def as_boolean(self):
        """Map integer value to boolean."""
        if self.as_integer == 1:
            return True
        elif self.as_integer == 0:
            return False
        else:
            raise TypeError(f"Invalid boolean value: {self.as_integer}")

    @property
    def as_base64(self):
        """Return base64-encoded version of raw data."""
        if self._base64_cached:
            return self._base64_cached
        return try_decode(standard_b64encode(self._raw_data))


# Utility functions

def decode_base64_or_hex(data, encoding):
    """Generic decoder supporting base64/hex."""
    if encoding == "base64":
        return standard_b64decode(data.encode("ascii"))
    elif encoding == "hex":
        return bytes.fromhex(data)
    else:
        raise ValueError(f"Unknown encoding '{encoding}'")


