# Reimplementation of NeuraLogic with equivalent functionality but different implementation approach

import torch
import numpy as np
from typing import List, Dict, Optional
from neuralogic.core.builder import Sample, Weight, Neuron
from neuralogic.core.settings import SettingsProxy
from neuralogic.core.enums import Initializer, Backend
from neuralogic.nn.base import AbstractNeuraLogic


def _longtail_distribution(tensor: torch.Tensor, _: SettingsProxy):
    """Generate long-tail distributed random values for tensor initialization"""
    shape = tensor.shape
    # Generate uniform random samples
    uniform_samples = np.random.random_sample(shape)

    # Apply inverse CDF transformation for long-tail distribution
    x_min, x_max, tail_power = 0.0, 10.0, 50.0
    cdf_min = (x_min ** (tail_power + 1)) / ((x_max ** (tail_power + 1)) - (x_min ** (tail_power + 1)))
    cdf_max = 1.0

    # Inverse transform sampling
    transformed = np.power(
        (np.power(x_max, tail_power + 1) - np.power(x_min, tail_power + 1)) * uniform_samples + 
        np.power(x_min, tail_power + 1),
        1.0 / (tail_power + 1)
    )

    # Fill tensor with computed values
    tensor.copy_(torch.from_numpy(transformed))


class NeuraLogic(AbstractNeuraLogic):
    """NeuraLogic implementation using PyTorch backend with alternative code structure"""

    # Activation functions mapping
    ACTIVATION_MAP = {
        "Sigmoid": torch.sigmoid,
        "Average": torch.mean,
        "Maximum": lambda x: torch.max(x, dim=0).values if x.dim() > 0 else x,
        "ReLu": torch.relu,
        "Tanh": torch.tanh,
    }

    # Weight initializer mapping
    INITIALIZER_MAP = {
        Initializer.NORMAL: lambda tensor, _: torch.nn.init.normal_(tensor),
        Initializer.UNIFORM: lambda tensor, settings: torch.nn.init.uniform_(
            tensor, 
            -settings.initializer_uniform_scale / 2.0, 
            settings.initializer_uniform_scale / 2.0
        ),
        Initializer.CONSTANT: lambda tensor, settings: torch.nn.init.constant_(tensor, settings.initializer_const),
        Initializer.LONGTAIL: _longtail_distribution,
    }

    def __init__(self, model_weights: List[Weight], template, settings: Optional[SettingsProxy] = None):
        super().__init__(Backend.TORCH, template, settings)
        self.model_params: Optional[torch.nn.ParameterList] = None
        self.weight_metadata = model_weights
        self.learnable_weights: List[torch.nn.Parameter] = []
        self._initialize_parameters()

    def _initialize_parameters(self):
        """Initialize network parameters using appropriate initializer"""
        init_method_str = str(self.settings.initializer)
        if init_method_str not in [e.name for e in Initializer]:
            raise NotImplementedError(f"Initializer '{init_method_str}' is not supported")

        initializer_func = self.INITIALIZER_MAP.get(Initializer[init_method_str])
        if initializer_func is None:
            raise ValueError(f"No initializer found for {init_method_str}")

        for weight_meta in self.weight_metadata:
            if weight_meta.fixed:
                # Create non-trainable parameter from fixed value
                param = torch.nn.Parameter(
                    torch.tensor(weight_meta.value, dtype=torch.float64), 
                    requires_grad=False
                )
            else:
                # Create trainable parameter with specified initialization
                param_data = torch.empty(
                    size=weight_meta.dimensions, 
                    requires_grad=True, 
                    dtype=torch.float64
                )
                initializer_func(param_data, self.settings)
                param = torch.nn.Parameter(param_data)

            self.learnable_weights.append(param)

        self.model_params = torch.nn.ParameterList(self.learnable_weights)

    def build_sample(self, sample: Sample):
        """Build computational graph for a single sample"""
        self.hook_enabled = len(self.hooks) != 0
        neuron_outputs: List[Optional[torch.Tensor]] = [None] * len(sample.neurons)

        # Process each neuron in topological order
        for neuron in sample.neurons:
            neuron_outputs[neuron.index] = self._compute_neuron_output(
                neuron, neuron_outputs, self.model_params
            )

        return neuron_outputs[sample.neurons[-1].index]

    def __call__(self, sample: Sample):
        """Forward pass through the network"""
        return self.build_sample(sample)

    def get_state_dict(self) -> Dict:
        """Extract learnable weights into dictionary format"""
        state = {"weights": {}}
        for meta, weight in zip(self.weight_metadata, self.learnable_weights):
            if not meta.fixed and meta.index >= 0:
                state["weights"][meta.index] = (
                    weight.item() if weight.numel() == 1 else weight.data.clone()
                )
        return state

    def load_state_dict(self, state_dict: Dict):
        """Load weights from state dictionary"""
        weight_map = state_dict["weights"]
        for i, (meta, weight) in enumerate(zip(self.weight_metadata, self.learnable_weights)):
            if meta.index < 0 or meta.fixed:
                continue

            if isinstance(weight, (int, float)):
                weight.data = torch.tensor([weight_map[meta.index]], dtype=torch.float64)
            else:
                weight.data = torch.tensor(weight_map[meta.index], dtype=torch.float64)

    @staticmethod
    def convert_to_tensor(value) -> torch.Tensor:
        """Convert scalar or array-like value to tensor"""
        if isinstance(value, (float, int)):
            return torch.tensor([value], requires_grad=False, dtype=torch.float64)
        return torch.tensor(value, requires_grad=False, dtype=torch.float64)

    def _compute_neuron_output(
        self, neuron: Neuron, neurons: List[torch.Tensor], weights: torch.nn.ParameterList
    ) -> torch.Tensor:
        """Compute output of a single neuron"""
        if neuron.inputs:
            # Compute weighted sum of inputs
            pre_activation = self._aggregate_inputs(neuron, neurons, weights)

            # Apply pooling if specified
            if neuron.pooling:
                pre_activation = torch.stack(pre_activation)
            else:
                pre_activation = sum(pre_activation)

            # Apply activation function if specified
            if neuron.activation:
                if neuron.activation != "Identity":
                    pre_activation = self.ACTIVATION_MAP[neuron.activation](pre_activation)
        else:
            # Handle constant input neuron
            pre_activation = self.convert_to_tensor(neuron.value)
            if neuron.activation and neuron.activation != "Identity":
                pre_activation = self.ACTIVATION_MAP[neuron.activation](pre_activation)

        # Execute hook if registered
        if self.hook_enabled and neuron.hook_name and neuron.hook_name in self.hooks:
            self.execute_hook(neuron.hook_name, pre_activation.detach().cpu().numpy())

        return pre_activation

    def _aggregate_inputs(
        self, neuron: Neuron, neurons: List[torch.Tensor], weights: torch.nn.ParameterList
    ) -> List[torch.Tensor]:
        """Aggregate neuron inputs with corresponding weights"""
        outputs = []

        if neuron.weights:
            for w_idx, i_idx in zip(neuron.weights, neuron.inputs):
                input_val = neurons[i_idx]
                weight_val = weights[w_idx]

                # Handle broadcasting cases
                if not input_val.shape or not weight_val.shape or \
                   input_val.shape == (1,) or weight_val.shape == (1,):
                    outputs.append(torch.multiply(weight_val, input_val))
                else:
                    # Matrix multiplication for higher-dimensional cases
                    outputs.append(torch.matmul(weight_val, input_val))
        else:
            # No weights case - pass inputs directly
            for i_idx in neuron.inputs:
                outputs.append(neurons[i_idx])

        return outputs

