from os import walk
from pathlib import Path
from time import time
from typing import Dict, List, Iterable, TypeVar, Callable, Union, Any
import numpy as np
from PySide2.QtCore import QThread
from vicarutil.image.core import read_beg_labels, Labels
from ..concurrent import typedsignal, signal
from ..ui import Progress
from ...logging import handle_exception

_T = TypeVar('_T')

class FileCategory:
    IMAGE = "IMG"
    LABEL = "LBL"

class GroupingCriterion:
    FILTER = 'filter'
    SEQUENCE = 'sequence'
    EXPOSURE = 'exposure'
    DEFAULT = "--"

    @classmethod
    def from_value(cls, val: Any):
        if isinstance(val, str):
            mapping = {
                cls.FILTER: cls.FILTER,
                cls.SEQUENCE: cls.SEQUENCE,
                cls.EXPOSURE: cls.EXPOSURE,
                cls.DEFAULT: cls.DEFAULT
            }
            return mapping.get(val, cls.DEFAULT)
        elif isinstance(val, cls):
            return val
        return cls.DEFAULT


def _iter_with_error_handling(items: Iterable[_T]) -> Iterable[_T]:
    """Safely iterate over items, catching permission errors."""
    try:
        for item in items:
            yield item
    except PermissionError:
        # If permission denied, just continue silently
        pass


def extract_image_labels(path: Path) -> Labels:
    """Read image labels from a file."""
    with open(path, 'rb') as file_obj:
        return read_beg_labels(file_obj)


def get_sequence_id(path: Path) -> str:
    """Extract sequence ID from image labels."""
    try:
        labels = extract_image_labels(path)
        seq_id = labels['IDENTIFICATION']['SEQUENCE_ID']
        return f"Sequence {seq_id}"
    except (KeyError, TypeError):
        return "Not Found"


def get_filter_info(path: Path) -> str:
    """Extract filter information from image labels."""
    try:
        clear_filters = {"CL1", "CL"}
        labels = extract_image_labels(path)
        filters = [str(f).strip() for f in labels['INSTRUMENT']['FILTER_NAME']]

        if not filters:
            return "Other"
        elif all(f in clear_filters for f in filters):
            return "Clear"
        else:
            return ','.join(filters)
    except KeyError:
        return "Not Found"


def get_exposure_time(path: Path) -> str:
    """Extract exposure duration and round to nearest 10 ms."""
    try:
        labels = extract_image_labels(path)
        duration_ms = int(labels['INSTRUMENT']['EXPOSURE_DURATION'])
        rounded = (duration_ms // 10) * 10
        return f"{rounded:d}"
    except KeyError:
        return "Not Found"


def placeholder_key(*_, **__) -> str:
    """Default grouping key function."""
    return "Files"


class ImageScanner(QThread):
    # Signals
    initialization_complete = signal()
    progress_max_changed = typedsignal(int)
    progress_value_changed = typedsignal(int)
    scanning_done = typedsignal(dict)

    def __init__(
            self,
            root_directory: str,
            completion_handler: Callable[[dict], None],
            grouping_mode: Union[str, GroupingCriterion] = None
    ):
        super().__init__()
        self.root_path = Path(root_directory)
        self.start_time = 0
        self.group_by = GroupingCriterion.from_value(grouping_mode)

        # Connect signals to UI updates
        self.initialization_complete.connect(Progress.start())
        self.scanning_done.connect(lambda data: self._on_scan_complete(data, completion_handler))
        self.progress_max_changed.connect(Progress.max)
        self.progress_value_changed.connect(Progress.value)

    def _on_scan_complete(self, result_data: dict, callback: Callable[[dict], None]):
        """Handle scan completion."""
        callback(result_data)
        Progress.stop()
        self.quit()

    def cancel(self):
        """Cancel current operation."""
        self.scanning_done.emit({})

    def _check_timeout(self):
        """Check if operation has exceeded time limit."""
        if time() - self.start_time > 30:
            raise TimeoutError("Operation timed out after 30 seconds")

    def _collect_directories(self, directory: Path) -> List[Path]:
        """Recursively collect all subdirectories."""
        directories = []
        self._check_timeout()
        directories.append(directory)

        for child in _iter_with_error_handling(directory.iterdir()):
            if child.is_dir():
                directories.extend(self._collect_directories(child))

        return directories

    def run(self):
        """Main execution thread."""
        try:
            self.start_time = time()
            self.initialization_complete.emit()

            if self.root_path.is_dir():
                # Get total number of files first
                all_dirs = self._collect_directories(self.root_path)
                self.progress_max_changed.emit(len(all_dirs))

                # Count total image files
                total_files = sum(
                    len(files) 
                    for _, _, files in walk(str(self.root_path), followlinks=False)
                )
                self.progress_max_changed.emit(total_files)

                processed_count = 0
                self.progress_value_changed.emit(processed_count)

                # Select appropriate grouping function
                if self.group_by == GroupingCriterion.SEQUENCE:
                    group_func = get_sequence_id
                elif self.group_by == GroupingCriterion.FILTER:
                    group_func = get_filter_info
                elif self.group_by == GroupingCriterion.EXPOSURE:
                    group_func = get_exposure_time
                else:
                    group_func = placeholder_key

                # Process files
                grouped_files = {}

                for dir_path, _, filenames in walk(str(self.root_path), followlinks=False):
                    current_dir = Path(dir_path)

                    for filename in filenames:
                        if filename.endswith(FileCategory.IMAGE):
                            try:
                                full_path = current_dir / filename
                                group_name = group_func(full_path)

                                if group_name not in grouped_files:
                                    grouped_files[group_name] = []
                                grouped_files[group_name].append(full_path)

                            except Exception as exc:
                                handle_exception(exc)

                        processed_count += 1
                        self.progress_value_changed.emit(processed_count)

                self.scanning_done.emit(grouped_files)
            else:
                self.scanning_done.emit({})

            self.quit()

        except TimeoutError:
            self.scanning_done.emit({})
            self.quit()


__all__ = ['ImageScanner', 'FileCategory', 'GroupingCriterion']

