from typing import Any, Dict, Optional, List
from .const import DOMAIN
import voluptuous as vol
from .sensor import CONF_MAC, CONF_NAME, CONF_SENSORS, SENSOR_TYPES, CONF_MONITORED_CONDITIONS
import homeassistant.helpers.config_validation as cv

# Define schemas for different configuration steps
ADD_SENSOR_SCHEMA = vol.Schema(
    {
        vol.Required(CONF_MAC): cv.string,
        vol.Optional(CONF_NAME): cv.string
    }
)

SENSOR_CONFIG_SCHEMA = vol.Schema(
    {vol.Optional(sensor_type): cv.boolean for sensor_type in SENSOR_TYPES}
)

ADD_ANOTHER_SCHEMA = vol.Schema(
    {
        vol.Optional("continue_adding"): cv.boolean
    }
)

class RuuviConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):
    # Shared data structure for the entire flow
    flow_data = {
        CONF_SENSORS: []
    }

    # Temporary storage for current sensor data between steps
    current_sensor_info = {}

    async def async_step_user(self, user_input=None):
        """Start the configuration flow when triggered by user."""
        return await self.async_step_mac_entry()

    async def async_step_mac_entry(self, user_input: Optional[Dict[str, Any]] = None):
        """Handle MAC address and name input step."""
        validation_errors: Dict[str, str] = {}

        if user_input is not None:
            # Process valid input
            if not validation_errors:
                # Store basic sensor info temporarily
                self.current_sensor_info = {
                    CONF_MAC: user_input[CONF_MAC],
                    CONF_NAME: user_input.get(CONF_NAME),
                }
                return await self.async_step_sensor_options()

        return self.async_show_form(
            step_id="mac_entry",
            data_schema=ADD_SENSOR_SCHEMA,
            errors=validation_errors
        )

    async def async_step_sensor_options(self, user_input: Optional[Dict[str, Any]] = None):
        """Configure which sensor measurements to monitor."""
        validation_errors: Dict[str, str] = {}

        if user_input is not None:
            # Validate and process sensor options
            if not validation_errors:
                # Build list of active monitored conditions
                active_conditions: List[str] = [
                    condition for condition in SENSOR_TYPES 
                    if user_input.get(condition, False)
                ]

                # Add complete sensor configuration to main data
                self.flow_data[CONF_SENSORS].append({
                    CONF_MAC: self.current_sensor_info[CONF_MAC],
                    CONF_NAME: self.current_sensor_info[CONF_NAME],
                    CONF_MONITORED_CONDITIONS: active_conditions
                })

                return await self.async_step_next_action()

        return self.async_show_form(
            step_id="sensor_options",
            data_schema=SENSOR_CONFIG_SCHEMA,
            errors=validation_errors
        )

    async def async_step_next_action(self, user_input: Optional[Dict[str, Any]] = None):
        """Determine whether to add more sensors or finalize setup."""
        validation_errors: Dict[str, str] = {}

        if user_input is not None:
            # Check user's choice for next action
            if not validation_errors:
                should_continue = user_input.get("continue_adding", False)

                if should_continue:
                    # Restart the sensor addition process
                    return await self.async_step_mac_entry()
                else:
                    # Finalize configuration entry
                    return self.async_create_entry(
                        title="Ruuvi Sensor Setup",
                        data=self.flow_data
                    )

        return self.async_show_form(
            step_id="next_action",
            data_schema=ADD_ANOTHER_SCHEMA,
            errors=validation_errors
        )

from collections import namedtuple
from .errors import ConfigurationError
from docker.utils.ports import build_port_bindings

# Define the ServicePort class using a different approach to avoid direct inheritance
class ServicePort:
    _fields = ('target', 'published', 'protocol', 'mode', 'external_ip')

    def __init__(self, target, published, protocol=None, mode=None, external_ip=None):
        # Validate and convert target port
        try:
            if target is not None:
                self.target = int(target)
            else:
                self.target = None
        except (ValueError, TypeError):
            raise ConfigurationError('Invalid target port: {}'.format(target))

        # Validate and convert published port
        if published is not None:
            if isinstance(published, str) and '-' in published:  # "x-y:z" format
                parts = published.split('-', 1)
                if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit():
                    raise ConfigurationError('Invalid published port: {}'.format(published))
                self.published = published  # Keep as string for range representation
            else:
                try:
                    self.published = int(published)
                except (ValueError, TypeError):
                    raise ConfigurationError('Invalid published port: {}'.format(published))
        else:
            self.published = None

        self.protocol = protocol
        self.mode = mode
        self.external_ip = external_ip

    @classmethod
    def parse(cls, spec):
        if isinstance(spec, cls):
            return [spec]

        if not isinstance(spec, dict):
            result = []
            try:
                port_bindings = build_port_bindings([spec])
                for k, v in port_bindings.items():
                    if '/' in k:
                        target, proto = k.split('/', 1)
                    else:
                        target, proto = (k, None)

                    for pub in v:
                        if pub is None:
                            result.append(cls(target, None, proto, None, None))
                        elif isinstance(pub, tuple):
                            result.append(cls(target, pub[1], proto, None, pub[0]))
                        else:
                            result.append(cls(target, pub, proto, None, None))
            except ValueError as e:
                raise ConfigurationError(str(e))
            return result

        # Handle dictionary input
        return [cls(
            spec.get('target'),
            spec.get('published'),
            spec.get('protocol'),
            spec.get('mode'),
            spec.get('external_ip')
        )]

    @property
    def merge_field(self):
        return (self.target, self.published, self.external_ip, self.protocol)

    def repr(self):
        return {
            field: getattr(self, field) 
            for field in self._fields 
            if getattr(self, field) is not None
        }

    def legacy_repr(self):
        return normalize_port_dict(self.repr())


def normalize_port_dict(port):
    external_ip = port.get('external_ip', '')
    has_ext_ip = ':' if external_ip else ''
    published = port.get('published', '')
    is_pub = ':' if port.get('published') is not None or port.get('external_ip') else ''
    target = port.get('target')
    protocol = port.get('protocol', 'tcp')

    return f"{external_ip}{has_ext_ip}{published}{is_pub}{target}/{protocol}"

import inspect
import random
from typing import Optional
from redbot.core import commands
from redbot.core.utils.chat_formatting import bold, box

class TextProcessor(str):
    """A class for processing and manipulating text strings."""

    def _char_count(self, include_spaces: bool) -> str:
        if include_spaces:
            return f"Character count (with spaces): {bold(str(len(self)))}"
        else:
            non_space_chars = len(self) - self.count(' ')
            return f"Character count: {bold(non_space_chars)}"

    def _word_count(self) -> str:
        words = [w for w in self.split() if w.strip()]
        return f"Word count: {bold(len(words))}"

    def _occurrence(self, substring: str) -> str:
        count = self.count(substring)
        times_word = "once" if count == 1 else f"{count} times"
        return f"`{substring}` appears in the text {bold(times_word)}."

    def _to_snake_case(self) -> str:
        return box(self.replace(" ", "_"))

    def _alternating_case(self) -> str:
        chars = list(self)
        for i in range(0, len(chars), 2):
            chars[i] = chars[i].upper()
        for i in range(1, len(chars), 2):
            chars[i] = chars[i].lower()
        return box("".join(chars))

    def _replace_text(self, old: str, new: str) -> str:
        result = self.replace(old, new)
        return box(result)

    def _remove_spaces(self) -> str:
        return box(self.replace(" ", ""))

    def _strip_chars(self, chars_to_strip: str) -> str:
        stripped = self.strip(chars_to_strip).strip()
        return box(stripped)

    def _shuffle_words(self) -> str:
        word_list = self.split()
        random.shuffle(word_list)
        return box(" ".join(word_list))

    def _reverse_string(self) -> str:
        return box(self[::-1])

    def _repeat_text(self, repetitions: int) -> str:
        return box(self * repetitions)

