# Exchange rate fetcher using NBP (National Bank of Poland) data sources

import json
import xml.etree.ElementTree as ET
import requests
from datetime import date


class CurrencyConverterPLN:
    """Fetch currency exchange rates to Polish Zloty (PLN) from official NBP sources."""

    __XML_RATE_PATH = './pozycja[kod_waluty="{0}"]/kurs_sredni'
    __XML_API_ENDPOINT = 'http://www.nbp.pl/kursy/xml/LastA.xml'
    __JSON_API_ENDPOINT = "http://api.nbp.pl/api/exchangerates/rates/A/{0}/{1}/"
    __cached_rates_xml = None

    def __init__(self):
        """Initialize by fetching current exchange rates XML data."""
        response_text = requests.get(self.__XML_API_ENDPOINT).text
        self.__cached_rates_xml = ET.fromstring(response_text)

    def __fetch_current_rate(self, currency_code):
        """Retrieve today's exchange rate for given currency from cached XML."""
        element = self.__cached_rates_xml.find(self.__XML_RATE_PATH.format(currency_code))
        return None if element is None else element.text

    def __fetch_historical_rate(self, currency_code: str, target_date: date):
        # Error handling omitted per original code
        api_url = self.__JSON_API_ENDPOINT.format(currency_code, target_date.isoformat())
        response = requests.get(api_url, headers={'Accept': 'application/json'})
        data = json.loads(response.text)
        return str(data['rates'][0]['mid'])

    def convert_currency_to_pln(self, currency='USD', on_date: date = None):
        """Get PLN exchange rate for specified currency and date (or today if unspecified)."""
        if on_date is None:
            return self.__fetch_current_rate(currency)
        return self.__fetch_historical_rate(currency, on_date)

# Modified storage module with equivalent functionality but different implementation approach

import os
import json
import time
from typing import Optional, List, Any, TYPE_CHECKING
from dragonchain import logger
from dragonchain import exceptions
from dragonchain.lib.database import redis

if TYPE_CHECKING:
    from dragonchain.lib.types import JSONType

_log = logger.get_logger()
LEVEL = os.environ["LEVEL"]
STAGE = os.environ["STAGE"]
STORAGE_TYPE = os.environ["STORAGE_TYPE"].lower()
STORAGE_LOCATION = os.environ["STORAGE_LOCATION"]

# Cache limit configuration (50MB)
CACHE_LIMIT = 52428800

# Storage interface selection
if STORAGE_TYPE == "s3":
    from dragonchain.lib.interfaces.aws import s3 as storage_backend
elif STORAGE_TYPE == "disk":
    from dragonchain.lib.interfaces.local import disk as storage_backend  # noqa: T484
else:
    raise NotImplementedError(f"Storage type '{STORAGE_TYPE}' is not supported")

def retrieve(key: str, cache_ttl: Optional[int] = None, use_cache: bool = True) -> bytes:
    """Fetch an object from storage with optional caching mechanism"""
    try:
        cached_data = None
        if use_cache:
            cached_data = redis.cache_get(key)

        if cached_data is None:
            cached_data = storage_backend.get(STORAGE_LOCATION, key)
            if use_cache and len(cached_data) < CACHE_LIMIT:
                redis.cache_put(key, cached_data, cache_ttl)

        return cached_data
    except exceptions.NotFound:
        raise
    except Exception:
        _log.exception("Unexpected error during storage retrieval")
        raise exceptions.StorageError("Error occurred while retrieving data from storage")

def store(key: str, data: bytes, cache_ttl: Optional[int] = None, use_cache: bool = True) -> None:
    """Store an object in storage with optional cache write-through"""
    try:
        storage_backend.put(STORAGE_LOCATION, key, data)
        if use_cache and len(data) < CACHE_LIMIT:
            redis.cache_put(key, data, cache_ttl)
    except Exception:
        _log.exception("Unexpected error during storage storage")
        raise exceptions.StorageError("Error occurred while storing data to storage")

def remove(key: str) -> None:
    """Delete an object from storage and clear cache entry"""
    try:
        storage_backend.delete(STORAGE_LOCATION, key)
        redis.cache_delete(key)
    except Exception:
        _log.exception("Unexpected error during storage deletion")
        raise exceptions.StorageError("Error occurred while deleting data from storage")

def remove_directory(directory_key: str) -> None:
    """Recursively delete all objects under a directory key"""
    try:
        keys_to_remove = list_keys(directory_key)
        for item_key in keys_to_remove:
            remove(item_key)
        storage_backend.delete_directory(STORAGE_LOCATION, directory_key)
    except Exception:
        _log.exception("Unexpected error during directory deletion")
        raise exceptions.StorageError("Error occurred while deleting directory from storage")

def fetch_transaction(block_id: str, txn_id: str, cache_ttl: Optional[int] = None) -> dict:
    """Retrieve a specific transaction from storage via cache layer"""
    try:
        key = f"{block_id}/{txn_id}"
        cached_obj = redis.cache_get(key)

        if cached_obj:
            return json.loads(cached_obj)

        raw_obj = storage_backend.select_transaction(STORAGE_LOCATION, block_id, txn_id)
        serialized = json.dumps(raw_obj, separators=(",", ":")).encode("utf-8")

        if len(serialized) < CACHE_LIMIT:
            redis.cache_put(key, serialized, cache_ttl)

        return raw_obj
    except exceptions.NotFound:
        raise
    except Exception:
        _log.exception("Unexpected error during transaction retrieval")
        raise exceptions.StorageError("Error occurred while retrieving transaction")

def store_json_object(key: str, payload: "JSONType", cache_ttl: Optional[int] = None, use_cache: bool = True) -> None:
    """Store a Python object as JSON in storage"""
    serialized = json.dumps(payload, separators=(",", ":")).encode("utf-8")
    store(key, serialized, cache_ttl, use_cache)

def load_json_object(key: str, cache_ttl: Optional[int] = None, use_cache: bool = True) -> Any:
    """Load and parse a JSON object from storage"""
    raw_data = retrieve(key, cache_ttl, use_cache)
    return json.loads(raw_data)

def list_keys(prefix: str) -> List[str]:
    """List all object keys matching a given prefix"""
    try:
        return storage_backend.list_objects(STORAGE_LOCATION, prefix)
    except Exception:
        _log.exception("Unexpected error during key listing")
        raise exceptions.StorageError("Error occurred while listing storage keys")

def check_superkey_exists(key: str) -> bool:
    """Check if a directory/superkey exists in storage"""
    try:
        return storage_backend.does_superkey_exist(STORAGE_LOCATION, key)
    except Exception:
        _log.exception("Unexpected error during superkey existence check")
        raise exceptions.StorageError("Error occurred while checking superkey existence")

def check_object_exists(key: str) -> bool:
    """Check if an object key exists in storage"""
    try:
        return storage_backend.does_object_exist(STORAGE_LOCATION, key)
    except Exception:
        _log.exception("Unexpected error during object existence check")
        raise exceptions.StorageError("Error occurred while checking object existence")

def log_error_message(message: str) -> None:
    """Save an error message to storage with timestamped filename"""
    service_name = os.environ.get("SERVICE", "unknown")
    timestamp = time.time()
    filename = f"error_{service_name}_{timestamp}.log"
    store(filename, message.encode("utf-8"), use_cache=False)

# Exporter for nanogi format (YAML-based scene description)
import os
import bpy
from bpy_extras.io_utils import ExportHelper
from .yaml import dump
from .primCamera import *
from .primMesh import *
from .primLamp import *

bl_info = {
  "name" : "nanogi",
  "category" : "Import-Export",
  "version" : ( 0, 0 ),
  "blender" : ( 2, 7, 3 )
}

class ExportNanogi( bpy.types.Operator, ExportHelper ):
  bl_label = "Export nanogi"
  bl_idname = "export.nanogi"
  filename_ext = ".yml"

  flag_selection = bpy.props.BoolProperty(
    name = "Selection Only",
    description = "Export selected objects only",
    default = False
  )

  def run_export( self, filepath ):
    # Initialize output structure
    base_dir = os.path.dirname( filepath ) + "/"
    result = {
      "version" : 5,
      "scene" : {
        "primitives" : []
      }
    }

    # Preserve original selection state
    original_selection = list(bpy.context.selected_objects)
    for obj in original_selection:
      obj.select = False

    # Determine which objects to process
    candidate_objects = []
    if self.flag_selection:
      candidate_objects = original_selection
    else:
      candidate_objects = list(bpy.data.objects)

    # Prepare processed objects: duplicate and separate by material
    final_objects = []
    for obj in candidate_objects:
      obj.select = True
      bpy.ops.object.duplicate()
      bpy.ops.mesh.separate( type = "MATERIAL" )

      for new_obj in bpy.context.selected_objects:
        final_objects.append( new_obj )
        new_obj.select = False

    # Process each object based on its type
    for obj in final_objects:
      primitive_data = {}
      if obj.type == "CAMERA":
        primitive_data = primCamera( obj )
      elif obj.type == "MESH":
        primitive_data = primMesh( obj, base_dir )
      elif obj.type == "LAMP":
        primitive_data = primLamp( obj, base_dir )
      result[ "scene" ][ "primitives" ].append( primitive_data )

    # Write YAML output
    with open( filepath, "w" ) as file:
      file.write( dump( result ) )

    # Cleanup: delete temporary duplicated objects
    for obj in final_objects:
      obj.select = True
    bpy.ops.object.delete()

    # Restore original selection
    for obj in original_selection:
      obj.select = True

  def execute( self, context ):
    self.run_export( self.filepath )
    return { "FINISHED" }

def draw_menu_item( self, context ):
    self.layout.operator( ExportNanogi.bl_idname, text = "nanogi (.yml)" )

def register():
  bpy.utils.register_module( __name__ )
  bpy.types.INFO_MT_file_export.append( draw_menu_item )

def unregister():
  bpy.utils.unregister_module( __name__ )
  bpy.types.INFO_MT_file_export.remove( draw_menu_item )

