# Reimplementation with equivalent logic but different structure and naming

from typing import Optional, Tuple
from ecostake.types.blockchain_format.coin import Coin
from ecostake.types.blockchain_format.program import Program
from ecostake.types.blockchain_format.sized_bytes import bytes32
from ecostake.wallet.puzzles.load_clvm import load_clvm

# Load the CLVM module once at module level
GENESIS_CHECKER_CLVM = load_clvm("genesis-by-puzzle-hash-with-0.clvm", package_or_requirement=__name__)

def build_genesis_checker(puzzle_hash: bytes32) -> Program:
    """
    Construct a genesis puzzle checker that accepts either:
    - The specific genesis coin identified by puzzle_hash, or
    - Any coin with amount zero.
    """
    return GENESIS_CHECKER_CLVM.curry(puzzle_hash)

def extract_genesis_hash(checker_program: Program) -> Optional[bytes32]:
    """
    Extract the original genesis puzzle hash from a constructed checker program.
    Returns None if the program doesn't match expected structure.
    """
    uncurried_result = checker_program.uncurry()

    if uncurried_result is None:
        return None

    func, args = uncurried_result

    # Verify it's the expected module and extract the first argument (puzzle hash)
    if func != GENESIS_CHECKER_CLVM:
        return None

    return args.first().as_atom()

def create_parent_lineage_for_origin(parent_coin: Coin) -> Program:
    """Create lineage proof for the original genesis coin"""
    return Program.to((0, [parent_coin.as_list(), 0]))

def create_parent_lineage_for_zero_amount(parent_coin: Coin) -> Program:
    """Create lineage proof for zero-amount coin"""
    return Program.to((0, [parent_coin.as_list(), 1]))

def construct_lineage_proof(parent_coin: Coin) -> Program:
    """
    Generate appropriate lineage proof based on coin amount:
    - Zero amount coins get zero-amount lineage proof
    - Non-zero amount coins get genesis-origin lineage proof
    """
    if parent_coin.amount == 0:
        return create_parent_lineage_for_zero_amount(parent_coin)
    else:
        return create_parent_lineage_for_origin(parent_coin)

from __future__ import absolute_import
from __future__ import unicode_literals
import os
import click
import six
from decapodcli import param_types
from decapodcli import utils
from decapodlib import exceptions

try:
    import pygments
except ImportError:
    pygments = None


def handle_exceptions(func):
    """Decorator that intercepts exceptions and formats error messages."""
    @six.wraps(func)
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        try:
            return func(*args, **kwargs)
        except exceptions.DecapodAPIError as err:
            utils.format_output_json(ctx, err.json, True)
        except exceptions.DecapodError as err:
            click.echo(six.text_type(err), err=True)
        finally:
            ctx.close()
        ctx.exit(os.EX_SOFTWARE)
    return wrapper


def inject_client(func):
    """Decorator that supplies client instances to the decorated function."""
    @six.wraps(func)
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        kwargs["client"] = ctx.obj["client"]
        return func(*args, **kwargs)
    return wrapper


def apply_formatting(func):
    """Decorator responsible for formatting responses based on context."""
    @six.wraps(func)
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        result = func(*args, **kwargs)
        if not result:
            return
        if ctx.obj.get("format") == "json":
            utils.format_output_json(ctx, result)
        return result
    return wrapper


def enable_colorization(func):
    """Decorator that conditionally adds color support via --color flag."""
    if pygments is None:
        def wrapper(*args, **kwargs):
            kwargs["color"] = None
            return func(*args, **kwargs)
    else:
        wrapper = click.option(
            "--color",
            default=None,
            type=click.Choice(["light", "dark"]),
            help=(
                "Apply syntax highlighting. Default is no coloring. "
                "Value specifies terminal theme (light/dark)."
            )
        )(func)
    wrapper = six.wraps(func)(wrapper)
    return wrapper


def add_pagination_options(func):
    """Decorator that appends common pagination CLI arguments."""
    @six.wraps(func)
    @click.option(
        "--page", "-p",
        type=int,
        default=None,
        help="Specify which page of results to retrieve."
    )
    @click.option(
        "--per_page", "-r",
        type=int,
        default=None,
        help="Number of entries per page."
    )
    @click.option(
        "--all", "-a",
        is_flag=True,
        help=(
            "Retrieve all items without pagination. "
            "This overrides 'page' and 'per_page' when enabled."
        )
    )
    @click.option(
        "--list", "-l",
        type=click.Choice(["active", "archived", "all"]),
        show_default=True,
        default="active",
        help="Filter by status: active (default), archived, or all."
    )
    @click.option(
        "--sort-by", "-s",
        default="",
        type=param_types.SORT_BY,
        help=(
            "Comma-separated field list for sorting. Prefix with '-' for "
            "descending or '+' for ascending order. Example: "
            "'-timestamp,+name'"
        )
    )
    @click.option(
        "--no-envelope", "-n",
        is_flag=True,
        help=(
            "Return raw list instead of paginated envelope. "
            "Automatically applied when fetching all items."
        )
    )
    @click.pass_context
    def wrapper(ctx, *args, **kwargs):
        fetch_all = kwargs.pop("all", False)
        page_num = kwargs.pop("page", None)
        items_per_page = kwargs.pop("per_page", None)
        strip_envelope = kwargs.pop("no_envelope", False)
        status_filter = kwargs.pop("list", "active")
        ordering_fields = kwargs.pop("sort_by", {})

        # Determine whether to fetch all items
        fetch_all = fetch_all or not (page_num or items_per_page)
        strip_envelope = strip_envelope or fetch_all

        query_params = {}
        if fetch_all:
            query_params["all_items"] = True
        else:
            query_params.update({
                "page": page_num,
                "per_page": items_per_page
            })

        # Apply status-based filtering
        query_params["filter"] = {}
        if status_filter == "all":
            query_params["filter"]["time_deleted"] = {
                "ne": "unreal_value"
            }
        elif status_filter == "archived":
            query_params["filter"]["time_deleted"] = {
                "ne": 0
            }
        else:
            del query_params["filter"]

        # Add sorting parameters if specified
        if ordering_fields:
            query_params["sort_by"] = ordering_fields

        kwargs["query_params"] = query_params

        response = func(*args, **kwargs)
        if strip_envelope and response:
            response = response["items"]
        return response
    return wrapper


def configure_model_edit(item_id_key, fetch_method_name, parse_as_json=True):
    """Decorator factory for model editing via editor, stdin, or inline JSON."""
    def outer_wrapper(func):
        @six.wraps(func)
        @click.option(
            "--model-editor",
            is_flag=True,
            help=(
                "Open current model in external editor for modification. "
                "Only 'data' section will be editable."
            )
        )
        @click.option(
            "--model",
            default=None,
            type=param_types.JSON,
            help=(
                "Provide complete model data directly as JSON string. "
                "If set, other options are ignored."
            )
        )
        @click.option(
            "--model-stdin",
            is_flag=True,
            help="Read model from standard input."
        )
        @click.pass_context
        def inner_wrapper(ctx, model_stdin, model_editor, model,
                          *args, **kwargs):
            if not model:
                if model_stdin:
                    stream = click.get_text_stream("stdin")
                    model = "".join(stream)
                elif model_editor:
                    fetcher = getattr(
                        ctx.obj["client"], fetch_method_name)
                    model_data = fetcher(kwargs[item_id_key])
                    if "data" in model_data:
                        json_str = utils.json_dumps(model_data["data"])
                        edited_str = click.edit(json_str)
                        if not edited_str:
                            return
                        parsed_data = utils.json_loads(edited_str)
                        model_data = fetcher(kwargs[item_id_key])
                        model_data["data"] = parsed_data
                        model = utils.json_dumps(model_data)
                    else:
                        model = utils.json_dumps(model_data)
                        model = click.edit(model)
                if (model_stdin or model_editor) and not model:
                    return
            if model and parse_as_json and not isinstance(model, dict):
                if isinstance(model, bytes):
                    model = model.decode("utf-8")
                model = utils.json_loads(model)
            kwargs["model"] = model
            return func(*args, **kwargs)
        return inner_wrapper
    return outer_wrapper


def compose_command(command_class, use_pagination=False, use_filtering=False):
    """Composite decorator combining common CLI command patterns."""
    def decorator(func):
        func = inject_client(func)
        if use_pagination:
            func = add_pagination_options(func)
        if use_filtering:
            func = filtered_result(func)
        func = apply_formatting(func)
        func = handle_exceptions(func)
        cmd_name = utils.parameter_name(func.__name__)
        func = command_class.command(name=cmd_name)(func)
        return func
    return decorator


def apply_response_filtering(func):
    """Decorator supporting post-processing of output using expression engines."""
    if not utils.JSON_FILTERS:
        return func

    func = click.option(
        "--filtered",
        type=param_types.FILTERED_OUTPUT,
        default="",
        help=(
            "Apply transformation engine to output. Supported engines: {0}. "
            "Syntax: 'engine:expression'. Example: 'jq:.[]|.id'."
        ).format(sorted(utils.JSON_FILTERS)))(func)

    @six.wraps(func)
    def wrapper(filtered_expr, *args, **kwargs):
        raw_response = func(*args, **kwargs)
        if not filtered_expr:
            return raw_response
        expr, converter = filtered_expr
        return converter(expr, raw_response)
    return wrapper

