def validate(config: dict) -> Configuration:
    return Configuration(**config)

class MySQLQueryExecutor(ActionRunner):
    @staticmethod
    async def create_instance(**kwargs) -> 'MySQLQueryExecutor':
        config = validate(kwargs)
        resource = await storage.driver.resource.load(config.source.id)
        return MySQLQueryExecutor(config, resource.credentials)

    def __init__(self, cfg: Configuration, auth: ResourceCredentials):
        self.pool = None
        self.config = cfg
        self.connection = auth.get_credentials(self, output=Connection)

    async def execute(self, payload):
        try:
            self.pool = await self.connection.establish(timeout=self.config.timeout)
            traverser = DictTraverser(self._get_dot_accessor(payload))
            input_data = traverser.reshape(self.config.parameters)

            self.console.log(f"Running SQL: {self.config.statement} with params: {input_data}")

            async with self.pool.acquire() as connection:
                async with connection.cursor(aiomysql.DictCursor) as cursor:
                    if self.config.mode == 'procedure':
                        # Placeholder for stored procedure handling
                        return Result(port="result", value={"result": payload})
                    else:
                        if len(input_data) > 0:
                            await cursor.execute(self.config.statement, tuple(input_data))
                        else:
                            await cursor.execute(self.config.statement)

                        if self.config.mode in ['insert', 'delete', 'update']:
                            await connection.commit()
                            if self.config.mode == 'insert':
                                return Result(port="result", value={"last_insert_id": cursor.lastrowid})

                        if self.config.mode == 'fetch':
                            rows = await cursor.fetchall()
                            formatted_rows = [self.serialize_record(row) for row in rows]
                            return Result(port="result", value={"result": formatted_rows})

                    return Result(port="result", value=payload)

        except Exception as ex:
            self.console.error(str(ex))
            return Result(port="error", value={"payload": payload, "error": str(ex)})

    async def cleanup(self):
        if self.pool:
            self.pool.close()
            await self.pool.wait_closed()

    async def handle_exception(self):
        await self.cleanup()

    @staticmethod
    def serialize_record(record):
        def encode_datetime(obj):
            if isinstance(obj, (datetime, date)):
                return obj.isoformat()
            elif isinstance(obj, bytes):
                return obj.decode('utf-8')
            return obj
        serialized = json.dumps(dict(record), default=encode_datetime)
        return json.loads(serialized)

