import time
import asyncio
import logging
from decimal import Decimal
from typing import Optional, Iterable, Type, List
from aiohttp.client_exceptions import ContentTypeError
from lbry.error import InvalidExchangeRateResponseError, CurrencyConversionError
from lbry.utils import aiohttp_request
from lbry.wallet.dewies import lbc_to_dewies

log = logging.getLogger(__name__)

class ExchangeRate:
    def __init__(self, market: str, spot_price: float, timestamp: int):
        current_time = int(time.time())
        if current_time - timestamp >= 600:
            raise ValueError('The timestamp is too dated.')
        if spot_price <= 0:
            raise ValueError('Spot must be greater than 0.')

        self.base_currency = market[:3]
        self.quote_currency = market[3:6]
        self.price = spot_price
        self.timestamp = timestamp

    def __repr__(self):
        return f"Currency pair:{self.base_currency}/{self.quote_currency}, price:{self.price}, ts:{self.timestamp}"

    def to_dict(self) -> dict:
        return {'price': self.price, 'timestamp': self.timestamp}

class MarketFeed:
    name: str = ""
    market: str = ""
    endpoint: str = ""
    request_parameters = {}
    transaction_fee = 0.0
    refresh_interval = 300
    timeout_duration = 50

    def __init__(self):
        self.current_rate: Optional[float] = None
        self.last_update_time = 0
        self._cached_response = None
        self._monitor_task: Optional[asyncio.Task] = None
        self.update_event = asyncio.Event()

    @property
    def has_valid_rate(self) -> bool:
        return self.current_rate is not None

    @property
    def service_available(self) -> bool:
        return self.last_update_time + self.refresh_interval + self.timeout_duration > time.time()

    def extract_rate(self, data: dict) -> float:
        raise NotImplementedError()

    async def fetch_data(self) -> dict:
        async with aiohttp_request('get', self.endpoint, params=self.request_parameters, 
                                   timeout=self.timeout_duration) as response:
            try:
                self._cached_response = await response.json()
            except ContentTypeError as error:
                self._cached_response = {}
                log.warning("Could not parse exchange rate response from %s: %s", self.name, error.message)
                log.debug(await response.text())
            return self._cached_response

    async def fetch_rate(self):
        try:
            json_data = await self.fetch_data()
            rate_value = self.extract_rate(json_data)
            adjusted_rate = rate_value / (1.0 - self.transaction_fee)

            log.debug("Saving rate update %f for %s from %s", adjusted_rate, self.market, self.name)
            self.current_rate = ExchangeRate(self.market, adjusted_rate, int(time.time()))
            self.last_update_time = time.time()
            self.update_event.set()
            return self.current_rate
        except asyncio.CancelledError:
            raise
        except asyncio.TimeoutError:
            log.warning("Timed out fetching exchange rate from %s.", self.name)
        except Exception as e:
            if isinstance(e, (json.JSONDecodeError, InvalidExchangeRateResponseError)):
                log.warning("Could not parse exchange rate response from %s: %s", self.name, getattr(e, 'doc', str(e)))
            else:
                log.exception("Exchange rate error (%s from %s):", self.market, self.name)

    async def monitor_updates(self):
        while True:
            await self.fetch_rate()
            await asyncio.sleep(self.refresh_interval)

    def activate(self):
        if not self._monitor_task:
            self._monitor_task = asyncio.create_task(self.monitor_updates())

    def deactivate(self):
        if self._monitor_task and not self._monitor_task.done():
            self._monitor_task.cancel()
        self._monitor_task = None
        self.update_event.clear()

class BittrexFeed(MarketFeed):
    name = "Bittrex"
    market = "BTCLBC"
    endpoint = "https://bittrex.com/api/v1.1/public/getmarkethistory"
    request_parameters = {'market': 'BTC-LBC', 'count': 50}
    transaction_fee = 0.0025

    def extract_rate(self, data: dict) -> float:
        if 'result' not in data:
            raise InvalidExchangeRateResponseError(self.name, 'result not found')

        trades = data['result']
        if not trades:
            raise InvalidExchangeRateResponseError(self.name, 'trades not found')

        total_volume = sum(trade['Total'] for trade in trades)
        total_quantity = sum(trade['Quantity'] for trade in trades)

        if total_volume <= 0 or total_quantity <= 0:
            raise InvalidExchangeRateResponseError(self.name, 'quantities were not positive')

        vwap = total_volume / total_quantity
        return float(1.0 / vwap)

class LBRYFeed(MarketFeed):
    name = "lbry.com"
    market = "BTCLBC"
    endpoint = "https://api.lbry.com/lbc/exchange_rate"

    def extract_rate(self, data: dict) -> float:
        if 'data' not in data:
            raise InvalidExchangeRateResponseError(self.name, 'result not found')
        return 1.0 / data['data']['lbc_btc']

class LBRYBTCFeed(LBRYFeed):
    market = "USDBTC"

    def extract_rate(self, data: dict) -> float:
        if 'data' not in data:
            raise InvalidExchangeRateResponseError(self.name, 'result not found')
        return 1.0 / data['data']['btc_usd']

class CryptonatorFeed(MarketFeed):
    name = "cryptonator.com"
    market = "BTCLBC"
    endpoint = "https://api.cryptonator.com/api/ticker/btc-lbc"

    def extract_rate(self, data: dict) -> float:
        if 'ticker' not in data or not data.get('ticker') or not data.get('success'):
            raise InvalidExchangeRateResponseError(self.name, 'result not found')
        return float(data['ticker']['price'])

class CryptonatorBTCFeed(CryptonatorFeed):
    market = "USDBTC"
    endpoint = "https://api.cryptonator.com/api/ticker/usd-btc"

FEEDS: Iterable[Type[MarketFeed]] = (
    LBRYFeed,
    LBRYBTCFeed,
    BittrexFeed,
    # CryptonatorFeed,
    # CryptonatorBTCFeed,
)

class ExchangeRateManager:
    def __init__(self, feeds: Iterable[Type[MarketFeed]] = FEEDS):
        self.providers: List[MarketFeed] = [Feed() for Feed in feeds]

    def wait_for_initialization(self):
        return asyncio.wait(
            [provider.update_event.wait() for provider in self.providers],
        )

    def start_services(self):
        log.info("Starting exchange rate manager")
        for provider in self.providers:
            provider.activate()

    def stop_services(self):
        log.info("Stopping exchange rate manager")
        for source in self.providers:
            source.deactivate()

    def convert_amount(self, from_currency: str, to_currency: str, amount: float) -> Decimal:
        available_rates = [provider.current_rate for provider in self.providers]
        log.debug("Converting %f %s to %s, rates: %s", amount, from_currency, to_currency, available_rates)

        if from_currency == to_currency:
            return Decimal(str(round(amount, 8)))

        # Direct conversion
        for provider in self.providers:
            if (provider.has_valid_rate and provider.service_available and
                    provider.current_rate.base_currency == from_currency and
                    provider.current_rate.quote_currency == to_currency):
                return round(amount * Decimal(str(provider.current_rate.price)), 8)

        # Indirect conversion via intermediate currency
        for provider in self.providers:
            if (provider.has_valid_rate and provider.service_available and
                    provider.current_rate.base_currency == from_currency):
                intermediate_amount = amount * Decimal(str(provider.current_rate.price))
                return round(self.convert_amount(
                    provider.current_rate.quote_currency, to_currency, float(intermediate_amount)), 8)

        raise CurrencyConversionError(
            f'Unable to convert {amount} from {from_currency} to {to_currency}')

    def to_dewies(self, currency: str, amount: float) -> int:
        converted = self.convert_amount(currency, "LBC", amount)
        return lbc_to_dewies(str(converted))

    def get_status(self) -> dict:
        return {provider: provider.current_rate.to_dict() for provider in self.providers}

import atexit
from .cache import (CacheProperties, LruCacheMetaclass, getTileCache,
                    isTileCacheSetup, methodcache, strhash)
try:
    from .memcache import MemCache
except ImportError:
    MemCache = None
from cachetools import Cache, LRUCache, cached
