@atexit.register
def cleanupCaches(*args, **kwargs):
    """
    Reset all registered caches and the tile cache. Note that this does not
    flush external caches like memcached (which could be achieved via
    tileCache._client.flush_all, but doing so might affect other processes).
    """
    for cache_name in LruCacheMetaclass.namedCaches:
        cache_obj, lock_obj = LruCacheMetaclass.namedCaches[cache_name]
        with lock_obj:
            cache_obj.clear()

    if isTileCacheSetup():
        tileCache, tileLock = getTileCache()
        try:
            with tileLock:
                tileCache.clear()
        except Exception:
            pass

def getCachesStatus(*args, **kwargs):
    """
    Provide statistics about each configured cache.
    :returns: a dictionary mapping cache names to their properties, including
        'maxsize' and 'used', where available.
    """
    status = {}

    # Collect info from named caches managed by LruCacheMetaclass
    for cache_name in LruCacheMetaclass.namedCaches:
        cache_obj, lock_obj = LruCacheMetaclass.namedCaches[cache_name]
        with lock_obj:
            status[cache_name] = {
                'maxsize': cache_obj.maxsize,
                'used': cache_obj.currsize
            }

    # Add tile cache info if available
    if isTileCacheSetup():
        tileCache, tileLock = getTileCache()
        try:
            with tileLock:
                curr_items_attr = 'curritems' if hasattr(tileCache, 'curritems') else 'currsize'
                status['tileCache'] = {
                    'maxsize': tileCache.maxsize,
                    'used': tileCache.currsize,
                    'items': getattr(tileCache, curr_items_attr, None)
                }
        except Exception:
            pass

    return status

__all__ = ('CacheFactory', 'getTileCache', 'isTileCacheSetup', 'MemCache',
           'strhash', 'LruCacheMetaclass', 'pickAvailableCache', 'cached',
           'Cache', 'LRUCache', 'methodcache', 'CacheProperties')

# Type III Clone: Refactored BaseHttpClient with equivalent functionality but different structure and logic

import re
import json as _json_lib
import socket
import asyncio
import logging
from functools import partial
from operator import itemgetter

# Third Party
import httpx

# Project
from stats.util import make_repr, split_on_uppercase

DEFAULT_LOGGER = logging.getLogger(__file__)

class BaseHttpClient:
    """Base session handler with enhanced modularity and alternative implementation patterns."""

    def __init__(
        self,
        base_url,
        config=None,
        uri_prefix="",
        uri_suffix="",
        verify_ssl=True,
        timeout=10,
        logger=DEFAULT_LOGGER,
        exception_class=Exception,
        user_agent=f"httpx/{httpx.__version__}",
    ):
        """Initialize connection instance."""
        self.__name__ = getattr(self, 'name', None)
        self.config = config
        self.protocol, self.host, self.port = self._extract_url_components(base_url)
        self.base_url = self._construct_url(self.protocol, self.host, self.port)
        self.uri_prefix = uri_prefix.strip("/")
        self.uri_suffix = uri_suffix.strip("/")
        self.verify_ssl = verify_ssl
        self.timeout = timeout
        self.log = logger
        self.exception_class = exception_class
        self.user_agent = user_agent

        # Session initialization using dict unpacking
        session_config = {
            "verify": self.verify_ssl,
            "base_url": self.base_url,
            "timeout": self.timeout,
        }

        self._session = httpx.Client(**session_config)
        self._asession = httpx.AsyncClient(**session_config)

    @classmethod
    def __init_subclass__(cls, name=None, **kwargs):
        """Set correct subclass name."""
        super().__init_subclass__(**kwargs)
        cls.name = name or cls.__name__

    async def __aenter__(self):
        """Test connection on entry."""
        available = await self._test_connectivity()
        if available:
            self.log.debug("Initialized session with {}", self.base_url)
            return self
        else:
            raise self._create_exception(f"Unable to create session to {self.name}")

    async def __aexit__(self, exc_type=None, exc_value=None, traceback=None):
        """Close connection on exit."""
        self.log.debug("Closing session with {}", self.base_url)
        await self._asession.aclose()

    def __enter__(self):
        """Test connection on entry."""
        available = self._check_connectivity()
        if available:
            self.log.debug("Initialized session with {}", self.base_url)
            return self
        else:
            raise self._create_exception(f"Unable to create session to {self.name}")

    def __exit__(self, exc_type=None, exc_value=None, traceback=None):
        """Close connection on exit."""
        if exc_type is not None:
            self.log.error(traceback)
        self._session.close()

    def __repr__(self):
        """Return user friendly representation of instance."""
        return make_repr(self)

    def _create_exception(self, message, exc=None, **kwargs):
        """Add stringified exception to message if passed."""
        if exc is not None:
            message = "{}: {}".format(str(message), str(exc), **kwargs)
        return self.exception_class(message)

    def _check_connectivity(self):
        """Open a low-level connection to the base URL to ensure its port is open."""
        self.log.debug("Testing connection to {}", self.base_url)
        try:
            host_without_protocol = re.sub(r"http(s)?\:\/\/", "", self.base_url)
            socket.socket().connect((host_without_protocol, 443))
        except socket.gaierror as err:
            raise self._create_exception(
                f"{self.name} appears to be unreachable", err
            ) from None
        return True

    async def _test_connectivity(self):
        """Open a low-level connection to the base URL to ensure its port is open."""
        self.log.debug("Testing connection to {}", self.base_url)
        try:
            _reader, _writer = await asyncio.open_connection(self.host, self.port)
        except socket.gaierror as err:
            raise self._create_exception(
                f"{self.name} appears to be unreachable at {self.base_url}", err
            )
        if _reader and _writer:
            return True
        else:
            return False

    @staticmethod
    def _construct_url(protocol, host, port):
        port_str = str(port)
        adjusted_protocol = protocol.lower()

        # Normalize standard ports
        if port_str == "80":
            port_str = ""
            adjusted_protocol = "http"
        elif port_str == "443":
            port_str = ""
            adjusted_protocol = "https"

        # Build final URL
        formatted_port = f":{port_str}" if port_str else ""
        return f"{adjusted_protocol}://{host}{formatted_port}"

    @staticmethod
    def _extract_url_components(url):
        match = re.match(r"^(http[s]?):\/\/([^:]+)\:?(\d*)$", url)
        if not match:
            raise ValueError(f"Invalid URL format: {url}")
        protocol, host, port = match.groups()
        return protocol, host, int(port) if port else 80

    @staticmethod
    def _normalize_dict(_dict):
        return _json_lib.loads(_json_lib.dumps(_dict, default=str))

    def _handle_response(self, response):
        parsed = {}
        try:
            parsed = response.json()
        except _json_lib.JSONDecodeError:
            try:
                parsed = _json_lib.loads(response.text)
            except (_json_lib.JSONDecodeError, TypeError):
                self.log.error("Error parsing JSON for response {}", repr(response))
                parsed = {"data": response.text}
        return parsed

    @staticmethod
    def _format_exception_details(exc):
        """Parse an exception and its direct cause."""
        if not isinstance(exc, BaseException):
            raise TypeError(f"'{repr(exc)}' is not an exception.")

        def get_class_name(exc_obj):
            return " ".join(split_on_uppercase(exc_obj.__class__.__name__))

        def get_first_line(doc):
            return doc.strip().split("\n")[0].strip(".") if doc else ""

        class_name = get_class_name(exc)
        details = []

        if exc.__doc__:
            summary = get_first_line(exc.__doc__)
            details.append(f"{class_name} ({summary})")
        else:
            details.append(class_name)

        if exc.__cause__:
            cause_name = get_class_name(exc.__cause__)
            if exc.__cause__.__doc__:
                cause_summary = get_first_line(exc.__cause__.__doc__)
                details.append(f"{cause_name} ({cause_summary})")
            else:
                details.append(cause_name)

        return ", caused by ".join(details)

    def _prepare_request(self, **kwargs):
        """Process requests parameters into structure usable by http library."""
        supported_methods = ("GET", "POST", "PUT", "DELETE", "HEAD", "PATCH")

        # Extract values using itemgetter
        (
            method,
            endpoint,
            item,
            headers,
            params,
            data,
            timeout,
            response_required,
        ) = itemgetter(*kwargs.keys())(kwargs)

        # Validate method
        if method.upper() not in supported_methods:
            raise self._create_exception(
                f'Method must be one of {", ".join(supported_methods)}. '
                f"Got: {str(method)}"
            )

        # Construct endpoint path
        parts = [
            "",
            self.uri_prefix.strip("/"),
            endpoint.strip("/"),
            self.uri_suffix.strip("/"),
            item,
        ]
        endpoint_path = "/".join(part for part in parts if part)

        # Build request dictionary
        request = {
            "method": method.upper(),
            "url": endpoint_path,
            "headers": {"user-agent": self.user_agent},
        }

        # Add optional parameters
        if headers is not None:
            request.update({"headers": headers})
        if params is not None:
            normalized_params = {str(k): str(v) for k, v in params.items() if v is not None}
            request["params"] = normalized_params
        if data is not None:
            if not isinstance(data, dict):
                raise self._create_exception(f"Data must be a dict, got: {str(data)}")
            request["json"] = self._normalize_dict(data)
        if timeout is not None:
            try:
                timeout_val = int(timeout)
            except (TypeError, ValueError):
                raise self._create_exception(
                    f"Timeout must be an int, got: {str(timeout)}"
                )
            request["timeout"] = timeout_val

        self.log.debug("Constructed request parameters {}", request)
        return request

    async def _execute_async_request(  # noqa: C901
        self,
        method,
        endpoint,
        item=None,
        headers=None,
        params=None,
        data=None,
        timeout=None,
        response_required=False,
    ):
        """Run HTTP operation asynchronously."""
        request = self._prepare_request(
            method=method,
            endpoint=endpoint,
            item=item,
            headers=headers,
            params=params,
            data=data,
            timeout=timeout,
            response_required=response_required,
        )

        try:
            response = await self._asession.request(**request)
            if response.status_code not in range(200, 300):
                status_name = httpx.StatusCode(response.status_code).name.replace("_", " ")
                error_data = self._handle_response(response)
                raise self._create_exception(
                    f'{status_name}: {error_data}', level="danger"
                ) from None
        except httpx.HTTPError as http_err:
            raise self._create_exception(self._format_exception_details(http_err)) from None

        return self._handle_response(response)

    async def _async_get(self, endpoint, **kwargs):
        return await self._execute_async_request(method="GET", endpoint=endpoint, **kwargs)

    async def _async_post(self, endpoint, **kwargs):
        return await self._execute_async_request(method="POST", endpoint=endpoint, **kwargs)

    async def _async_put(self, endpoint, **kwargs):
        return await self._execute_async_request(method="PUT", endpoint=endpoint, **kwargs)

    async def _async_delete(self, endpoint, **kwargs):
        return await self._execute_async_request(method="DELETE", endpoint=endpoint, **kwargs)

    async def _async_patch(self, endpoint, **kwargs):
        return await self._execute_async_request(method="PATCH", endpoint=endpoint, **kwargs)

    async def _async_head(self, endpoint, **kwargs):
        return await self._execute_async_request(method="HEAD", endpoint=endpoint, **kwargs)

    def _execute_sync_request(  # noqa: C901
        self,
        method,
        endpoint,
        item=None,
        headers=None,
        params=None,
        data=None,
        timeout=None,
        response_required=False,
    ):
        """Run HTTP operation synchronously."""
        request = self._prepare_request(
            method=method,
            endpoint=endpoint,
            item=item,
            headers=headers,
            params=params,
            data=data,
            timeout=timeout,
            response_required=response_required,
        )

        try:
            response = self._session.request(**request)
            if response.status_code not in range(200, 300):
                status_name = httpx.StatusCode(response.status_code).name.replace("_", " ")
                error_data = self._handle_response(response)
                raise self._create_exception(
                    f'{status_name}: {error_data}', level="danger"
                ) from None
        except httpx.HTTPError as http_err:
            raise self._create_exception(
                self._format_exception_details(http_err), level="danger"
            ) from None

        return self._handle_response(response)

    def _sync_get(self, endpoint, **kwargs):
        return self._execute_sync_request(method="GET", endpoint=endpoint, **kwargs)

    def _sync_post(self, endpoint, **kwargs):
        return self._execute_sync_request(method="POST", endpoint=endpoint, **kwargs)

    def _sync_put(self, endpoint, **kwargs):
