# Custom extension to display and select windows via dmenu
from libqtile.extension.dmenu import Dmenu
from libqtile.scratchpad import ScratchPad

class WindowSelector(Dmenu):
    """
    Display a vertical menu of active windows using dmenu.
    Allows switching to the selected window by focusing its group and the window itself.
    """
    defaults = [
        ("label_format", "{group}.{index}: {title}", "Format string for menu entries"),
        (
            "scope_windows",
            True,
            "If True, include windows from all groups; otherwise restrict to current group only",
        ),
        ("menu_height", "80", "Number of lines displayed vertically in dmenu"),
    ]

    def __init__(self, **kwargs):
        Dmenu.__init__(self, **kwargs)
        self.add_defaults(WindowSelector.defaults)

    def gather_windows(self):
        index = 0
        self.selection_map = {}
        if self.scope_windows:
            active_windows = self.qtile.windows_map.values()
        else:
            active_windows = self.qtile.current_group.windows

        for window in active_windows:
            # Skip scratchpad containers
            if hasattr(window, 'group') and window.group and not isinstance(window.group, ScratchPad):
                entry = self.label_format.format(
                    group=window.group.label or window.group.name,
                    index=index,
                    title=window.name or ''
                )
                self.selection_map[entry] = window
                index += 1

    def execute(self):
        self.gather_windows()
        result = super().run(items=list(self.selection_map.keys()))

        # Handle cases where no selection was made or input is invalid
        if not isinstance(result, str):
            return

        try:
            selected_label = result.strip()
        except AttributeError:
            return

        try:
            target_window = self.selection_map[selected_label]
        except KeyError:
            # Window may have been closed during menu interaction
            return

        # Switch to the window's group and focus it
        current_screen = self.qtile.current_screen
        current_screen.set_group(target_window.group)
        target_window.group.focus(target_window)

