import datetime
import re
import sys
import time
from google.cloud import storage
from py4j.protocol import Py4JJavaError
from pyspark.sql import SparkSession
from pyspark.sql.functions import UserDefinedFunction
from pyspark.sql.types import FloatType, IntegerType, StringType

# --- Trip Duration Converter ---
def normalize_trip_duration(raw_value):
    """Converts trip duration string (e.g., '2m', '1.5h') to integer seconds; returns None if invalid."""
    if not raw_value:
        return None
    match = re.search(r"(-?\d+\.?\d*)", raw_value)
    if not match:
        return None
    try:
        val = float(match.group(1))
    except ValueError:
        return None
    if val < 0:
        return None
    if "m" in raw_value.lower():
        val *= 60
    elif "h" in raw_value.lower():
        val *= 3600
    return int(val)


# --- Station Name Normalizer ---
def clean_station_name(station):
    """Replaces forward slashes with ampersands."""
    return station.replace("/", "&") if station else None


# --- User Type Standardizer ---
def standardize_user_type(user_input):
    """Maps user type strings to standardized labels: 'Subscriber' or 'Customer'."""
    if not user_input:
        return None
    lower = user_input.lower()
    if lower.startswith("sub"):
        return "Subscriber"
    elif lower.startswith("cust"):
        return "Customer"
    return None


# --- Angle Converter (DMS/Decimal) ---
def parse_angle(value):
    """Parses angle from DMS format (e.g., '40°26\'46"N') or decimal degrees."""
    if not value:
        return None
    dms_match = re.match(r"(-?\d+)\D*(-?\d+)\D*(-?\d+)", value)
    if dms_match:
        deg, minute, sec = map(int, dms_match.groups())
        return deg + minute / 60 + sec / 3600
    dec_match = re.match(r"(-?\d+\.?\d*)", value)
    if dec_match:
        try:
            return float(dec_match.group(1))
        except ValueError:
            return None
    return None


# --- Time Calculation Engine ---
def resolve_time_components(duration_sec, start_str, end_str):
    """Derives missing time fields among duration, start, and end times."""
    fmt = "%Y-%m-%dT%H:%M:%S"

    def safe_parse(dt_str):
        if dt_str and "." in dt_str:
            dt_str = dt_str.split(".")[0]
        try:
            return datetime.datetime.strptime(dt_str, fmt) if dt_str else None
        except (ValueError, TypeError):
            return None

    start_dt = safe_parse(start_str)
    end_dt = safe_parse(end_str)
    dur_delta = datetime.timedelta(seconds=duration_sec) if duration_sec else None

    # Fill missing values
    if start_dt and end_dt and not dur_delta:
        dur_delta = end_dt - start_dt
    elif dur_delta and end_dt and not start_dt:
        start_dt = end_dt - dur_delta
    elif dur_delta and start_dt and not end_dt:
        end_dt = start_dt + dur_delta

    # Format outputs
    result = [None] * 3
    if dur_delta:
        result[0] = int(dur_delta.total_seconds())
    if start_dt:
        result[1] = start_dt.strftime(fmt)
    if end_dt:
        result[2] = end_dt.strftime(fmt)
    return tuple(result)


# --- Helper UDF Wrappers ---
def extract_duration(duration, start, end):
    return resolve_time_components(duration, start, end)[0]


def extract_start_time(duration, start, end):
    return resolve_time_components(duration, start, end)[1]


def extract_end_time(duration, start, end):
    return resolve_time_components(duration, start, end)[2]


# --- Main Execution Block ---
if __name__ == "__main__":
    bucket_name = sys.argv[1]
    table_path = sys.argv[2]

    spark = SparkSession.builder.appName("data_processing").getOrCreate()

    try:
        df = spark.read.format("bigquery").option("table", table_path).load()
    except Py4JJavaError as e:
        raise RuntimeError(f"Failed to load table {table_path}") from e

    # Remove unnecessary column
    df = df.drop("gender")

    # Apply single-argument UDFs
    udf_map = {
        "start_station_name": (station_name_udf := UserDefinedFunction(clean_station_name, StringType())),
        "end_station_name": UserDefinedFunction(clean_station_name, StringType()),
        "tripduration": UserDefinedFunction(normalize_trip_duration, IntegerType()),
        "usertype": UserDefinedFunction(standardize_user_type, StringType()),
        "start_station_latitude": UserDefinedFunction(parse_angle, FloatType()),
        "start_station_longitude": UserDefinedFunction(parse_angle, FloatType()),
        "end_station_latitude": UserDefinedFunction(parse_angle, FloatType()),
        "end_station_longitude": UserDefinedFunction(parse_angle, FloatType()),
    }

    for col_name, udf_func in udf_map.items():
        df = df.withColumn(col_name, udf_func(df[col_name]))

    # Apply multi-argument UDFs
    multi_udfs = [
        ("tripduration", extract_duration, ("tripduration", "starttime", "stoptime")),
        ("starttime", extract_start_time, ("tripduration", "starttime", "stoptime")),
        ("stoptime", extract_end_time, ("tripduration", "starttime", "stoptime")),
    ]

    for target_col, func, args in multi_udfs:
        df = df.withColumn(target_col, UserDefinedFunction(func, StringType() if target_col != "tripduration" else IntegerType())(*[df[arg] for arg in args]))

    # Preview sample rows
    df.show(n=20)

    # Output handling
    if "--dry-run" in sys.argv:
        print("Dry run: no data will be written.")
    else:
        timestamp_suffix = str(int(time.time()))
        temp_gcs_path = f"gs://{bucket_name}/{timestamp_suffix}"

        print("Uploading intermediate data...")
        (
            df.write
            .options(codec="org.apache.hadoop.io.compress.GzipCodec")
            .csv(temp_gcs_path)
        )

        client = storage.Client()
        bucket = client.bucket(bucket_name)

        blobs = list(bucket.list_blobs(prefix=timestamp_suffix))
        final_prefix = "clean_data/"

        for blob in blobs:
            part_file = re.match(timestamp_suffix + r"/(part-\d+).*\.csv\.gz$", blob.name)
            if part_file:
                new_name = f"{final_prefix}{part_file.group(1)}.csv.gz"
                bucket.copy_blob(blob, bucket, new_name)

        # Cleanup temp files
        for blob in blobs:
            blob.delete()

        print(f"Data successfully saved to gs://{bucket_name}/{final_prefix}")

# Type III clone: Modified logic with equivalent functionality

from typing import List, Tuple

class BBoxTransformer:
    def __str__(self) -> str:
        raise NotImplementedError

    def apply(self, bounding_box: List[float], dimensions: Tuple[int, int]) -> List[float]:
        raise NotImplementedError

class ClipToCanvas(BBoxTransformer):
    def __str__(self):
        return "clip_to_canvas"

    def apply(self, bounding_box: List[float], dimensions: Tuple[int, int]) -> List[float]:
        canvas_width, canvas_height = dimensions
        x, y, w, h = bounding_box

        # Adjust position and size when box extends beyond left/top edges
        if x < 0:
            w += x
            x = 0

        if y < 0:
            h += y
            y = 0

        # Adjust size when box exceeds right/bottom edges
        if x + w > canvas_width:
            w = canvas_width - x

        if y + h > canvas_height:
            h = canvas_height - y

        return [x, y, w, h]

class SquareizeBBox(BBoxTransformer):
    def apply(self, bounding_box: List[float], dimensions: Tuple[int, int]) -> List[float]:
        x, y, width, height = bounding_box
        side_length = max(width, height)

        # Center the square by adjusting origin
        offset_x = (side_length - width) / 2.0
        offset_y = (side_length - height) / 2.0

        new_x = x - offset_x
        new_y = y - offset_y

        return [new_x, new_y, side_length, side_length]

    def __str__(self) -> str:
        return "square"

class AdaptivePadding(BBoxTransformer):
    def __init__(self, scale_factor: float):
        self.scale_factor = scale_factor

    def apply(self, bounding_box: List[float], dimensions: Tuple[int, int]) -> List[float]:
        base_w, base_h = bounding_box[2], bounding_box[3]
        pad_w = self.scale_factor * base_w
        pad_h = self.scale_factor * base_h

        return [
            bounding_box[0] - pad_w,
            bounding_box[1] - pad_h,
            bounding_box[2] + 2 * pad_w,
            bounding_box[3] + 2 * pad_h,
        ]

    def __str__(self) -> str:
        return f"adaptive_pad:{self.scale_factor:.2f}"

class FixedPadding(BBoxTransformer):
    """
    Expands or contracts the bounding box uniformly in all directions.
    Positive padding increases size, negative padding shrinks it.
    """
    def __init__(self, margin: int):
        self.margin = margin

    def __str__(self) -> str:
        return f"fixed_pad:{self.margin}"

    def apply(self, bounding_box: List[float], dimensions: Tuple[int, int]) -> List[float]:
        m = self.margin
        return [
            bounding_box[0] - m,
            bounding_box[1] - m,
            bounding_box[2] + 2 * m,
            bounding_box[3] + 2 * m,
        ]

class SequentialTransform(BBoxTransformer):
    def __init__(self, operations: List[BBoxTransformer]):
        self.operations = operations

    def __str__(self) -> str:
        return "__".join([op.__str__() for op in self.operations])

    def apply(self, bounding_box: List[float], dimensions: Tuple[int, int]) -> List[float]:
        current_bbox = bounding_box.copy()
        for operation in self.operations:
            current_bbox = operation.apply(current_bbox, dimensions)
        return current_bbox

