    @abstractmethod
    def retrieve_results(self, info: QueryInfo) -> QueryResults:
        """Fetches full result set after completion, handling pagination if needed."""

    @abstractmethod
    def cancel_query(self, exec_id: str) -> None:
        """Terminates an ongoing query execution."""


class Boto3AthenaClient(AthenaAccessor):
    """
    Concrete implementation using boto3 clients for Athena and S3.
    Can be swapped out during unit tests using FakeProxy.
    """

    _athena: Any  # boto3.client("athena")
    _s3: Any      # boto3.client("s3")

    def __init__(
        self,
        *,
        region: str | None = None,
        athena_client: Any | None = None,
        s3_client: Any | None = None,
    ) -> None:
        self._athena = athena_client or boto3.client("athena", region_name=region)
        self._s3 = s3_client or boto3.client("s3")

    def run_query(
        self,
        statement: str,
        catalog: str | None = None,
        group: str | None = None,
        result_bucket: str | None = None,
    ) -> str:
        payload: Dict[str, Any] = {"QueryString": statement}
        if catalog is not None:
            payload["QueryExecutionContext"] = {"Database": catalog}
        if group is not None:
            payload["WorkGroup"] = group
        if result_bucket is not None:
            payload["ResultConfiguration"] = {"OutputLocation": result_bucket}

        logger.debug(f"ExecuteStatement: {truncate_str(statement)!r}")
        response = self._athena.start_query_execution(**payload)
        exec_id = cast(str, response["QueryExecutionId"])
        logger.debug(f"Started execution ID: {exec_id!r}")
        return exec_id

    def fetch_status(self, exec_id: str) -> QueryInfo:
        logger.debug(f"Fetching status for execution ID: {exec_id!r}")
        resp = self._athena.get_query_execution(QueryExecutionId=exec_id)
        info = QueryInfo(resp["QueryExecution"])
        logger.debug(f"Execution details: {info}")
        return info

    def retrieve_results(self, info: QueryInfo) -> QueryResults:
        exec_id = info.execution_id
        params = {"QueryExecutionId": exec_id}
        logger.debug(f"Requesting results for execution ID: {exec_id!r}")

        raw = self._athena.get_query_results(**params)
        field_names = _extract_field_names(raw)
        field_types = _extract_field_types(raw)

        next_token = raw.get("NextToken")
        if next_token:
            logger.debug("Paginated result detected — fetching from S3.")
            rows = self._fetch_from_s3(info)
        else:
            rows = _parse_result_rows(raw)
            logger.debug(f"Retrieved {len(rows)} rows (including header)")

        cleaned = _sanitize_data(field_names, rows)
        return QueryResults(field_names, field_types, cleaned)

    def cancel_query(self, exec_id: str) -> None:
        logger.debug(f"Cancelling execution ID: {exec_id!r}")
        self._athena.stop_query_execution(QueryExecutionId=exec_id)

    def _fetch_from_s3(self, info: QueryInfo) -> List[Record]:
        bucket, path = s3_parse_uri(info.output_location)
        logger.debug(f"Downloading S3 object: Bucket={bucket!r}, Key={path!r}")
        obj = self._s3.get_object(Bucket=bucket, Key=path)
        with s3_wrap_body(obj["Body"]) as stream:
            records = list(read_csv(stream))
        logger.debug(f"Downloaded {len(records)} rows from S3")
        return records


def _sanitize_data(headers: FieldNames, raw_records: Sequence[Record]) -> List[Record]:
    """
    Normalize inconsistent Athena output formats.

    - Presto-based queries may duplicate column names in first row → strip it.
    - Hive-based queries may merge all columns into one tab-separated string → split.
    """
    if not raw_records:
        return []

    first_row = raw_records[0]
    if first_row == tuple(headers):
        return list(raw_records[1:])

    if all(len(r) == 1 for r in raw_records) and len(headers) > 1:
        # Hive-style single-column output
        merged_values = [r[0] for r in raw_records if r[0]]
        split_rows = [
            v.split("\t", maxsplit=len(headers) - 1) for v in merged_values
        ]
        return split_rows

    return list(raw_records)


def _extract_field_names(result: Mapping[str, Any]) -> FieldNames:
    meta = result["ResultSet"]["ResultSetMetadata"]["ColumnInfo"]
    return tuple(col["Name"] for col in meta)


def _extract_field_types(result: Mapping[str, Any]) -> FieldTypes:
    meta = result["ResultSet"]["ResultSetMetadata"]["ColumnInfo"]
    return tuple(col["Type"] for col in meta)


def _parse_result_rows(result: Mapping[str, Any]) -> List[Record]:
    rows = result["ResultSet"]["Rows"]
    return [tuple(item.get("VarCharValue") for item in row["Data"]) for row in rows]

import os
import sys
import platform
from datetime import datetime
from shutil import copy2
import ssl
import argparse
