# Global configuration paths
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))

def sanitize_path(path_str):
    """Normalize path string by escaping backslashes."""
    return path_str.replace('\\', '\\\\')

def confirm_action(prompt_msg=''):
    """Prompt user for yes/no confirmation."""
    positive_responses = {'yes', 'y', 'ye', ''}
    negative_responses = {'no', 'n'}

    user_input = input(prompt_msg).strip().lower()
    if user_input in positive_responses:
        return True
    elif user_input in negative_responses:
        return False
    else:
        print("Please respond with 'y' or 'n'.")
        return None

def configure_env_variable(var_name, var_value, prepend_mode=False):
    """Configure environment variable based on OS type."""
    current_os = platform.system()

    if prepend_mode:  # Prepend to existing variable
        if current_os == 'Windows':
            print(f'Prepending "{var_name}" with "{var_value}"')
            os.system(f"SETX {var_name} {var_value};%{var_name}%")  # Permanent
            os.system(f'set "{var_name}={var_value};%{var_name}%"')  # Current session
        # TODO: Implement Linux/Mac support
    else:  # Set/replace variable
        if current_os == 'Windows':
            print(f'Setting "{var_name}={var_value}"')
            os.system(f"SETX {var_name} {var_value}")  # Permanent
            os.system(f'set "{var_name}={var_value}"')  # Current session
        # TODO: Implement Linux/Mac support

def check_and_configure_env(var_name, var_value, prepend_mode=False):
    """Check existing env var and prompt before modification."""
    should_update = False

    if var_name in os.environ:
        if prepend_mode and var_value not in os.environ[var_name]:
            should_update = True
        elif not prepend_mode and os.environ[var_name] != var_value:
            response = confirm_action(
                f'Environment variable already set: "{var_name}={os.environ[var_name]}".\n'
                f'Change to {var_value}? [y/n]: '
            )
            if response is True:
                should_update = True
            elif response is False:
                should_update = False
    else:
        should_update = True

    if should_update:
        configure_env_variable(var_name, var_value, prepend_mode=prepend_mode)
    else:
        print(f'Leaving "{var_name}={os.environ.get(var_name, "not set")}" unchanged')

def apply_environment_updates(set_vars=None, prepend_vars=None):
    """Apply multiple environment variable configurations."""
    set_vars = set_vars or {}
    prepend_vars = prepend_vars or {}

    for var_name, var_value in set_vars.items():
        check_and_configure_env(var_name, var_value, prepend_mode=False)

    for var_name, var_value in prepend_vars.items():
        check_and_configure_env(var_name, var_value, prepend_mode=True)

def create_backup(filepath):
    """Create timestamped backup of a file."""
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    base_name, ext = os.path.splitext(filepath)
    backup_path = f"{base_name}-backup_{timestamp}{ext}"
    copy2(filepath, backup_path)
    return backup_path

def merge_text_files(source_file, target_file, create_backup_flag=True):
    """Append content from source file to target if not already present."""
    try:
        with open(target_file, encoding='utf-8') as f:
            existing_lines = f.readlines()

        with open(source_file, encoding='utf-8') as f:
            new_lines = f.readlines()
            new_lines.insert(0, "\n")

        # Check if new content is subset of existing
        if not set(new_lines).issubset(existing_lines):
            backup_path = None
            if create_backup_flag:
                backup_path = create_backup(target_file)
                print(f"Backed up {target_file} to {backup_path}")

            with open(target_file, 'a', encoding='utf-8') as f:
                f.writelines([six.text_type(line) for line in new_lines])
            return True
        return False
    except Exception as e:
        print(f"Error processing files: {e}")
        return False

def integrate_certificates(target_cert_file, cert_sources):
    """Integrate multiple certificate files into target certificate bundle."""
    if not isinstance(cert_sources, list):
        cert_sources = [cert_sources]

    if not cert_sources:
        return "No certificate files provided."

    backed_up_once = False
    result_messages = []

    for cert_path in cert_sources:
        if not os.path.isfile(cert_path):
            raise ValueError(f"Invalid certificate location: '{cert_path}'")

        if merge_text_files(cert_path, target_cert_file, create_backup_flag=(not backed_up_once)):
            result_messages.append(f"Appended {cert_path} to {target_cert_file}.")
            backed_up_once = True

    if not result_messages:
        result_messages.append("Certificates are already integrated.")

    return "\n".join(result_messages)

def update_pip_configuration(config_path, config_content, cert_prefix="cert="):
    """Update pip configuration file with SSL certificate settings."""
    # Extract certificate path from configuration content
    cert_paths = [line.split(cert_prefix) for line in config_content if cert_prefix in line]
    if not cert_paths:
        return "No certificate path found in configuration content."

    extracted_cert_path = re.sub(r'[\n\r]', '', sanitize_path(cert_paths[0][1]))

    # Ensure config directory exists
    config_dir = os.path.dirname(config_path)
    if config_dir and not os.path.exists(config_dir):
        os.makedirs(config_dir)

    # Create new config if it doesn't exist
    if not os.path.exists(config_path):
        with open(config_path, 'w', encoding='utf-8') as f:
            for line in config_content:
                updated_line = re.sub(f'{cert_prefix}.*$', f'{cert_prefix}{extracted_cert_path}', line)
                f.write(six.text_type(updated_line))
        return f"Created and updated {config_path}"

    # Read existing config
    with open(config_path, encoding='utf-8') as f:
        existing_lines = [sanitize_path(line) for line in f.readlines()]

    combined_content = '\t'.join(existing_lines)

    # Update or append certificate path
    if cert_prefix not in combined_content:
        with open(config_path, 'a', encoding='utf-8') as f:
            f.write(six.text_type(re.sub(f'{cert_prefix}.*$', f'{cert_prefix}{extracted_cert_path}',
                                        f'{cert_prefix}{extracted_cert_path}\r\n')))
        return f"Appended certificate config to {config_path}"
    else:
        if extracted_cert_path not in combined_content:
            backup_path = create_backup(config_path)
            with open(config_path, 'w', encoding='utf-8') as f:
                for line in existing_lines:
                    updated_line = re.sub(f'{cert_prefix}.*$', f'{cert_prefix}{extracted_cert_path}', line)
                    f.write(six.text_type(updated_line))
            return f"Updated certificate path in config.\nBackup saved to {backup_path}"
        else:
            return "Config already points to correct certificate location."

def setup_ssl_for_pip(cert_location=None, cert_prefix="cert="):
    """Configure pip SSL settings using system-appropriate configuration."""
    operating_system = platform.system()

    # Determine pip config location
    if 'envs' in sys.prefix:
        pip_config_path = os.path.join(sys.prefix, 'pip.conf')
    else:
        if operating_system == 'Windows':
            pip_config_path = os.path.join(os.environ.get('APPDATA', ''), 'pip', 'pip.ini')
        elif operating_system == 'Darwin':
            mac_dirs = [
                os.path.join(os.environ['HOME'], 'Library', 'Application Support', 'pip'),
                os.path.join(os.environ['HOME'], '.config', 'pip')
            ]
            pip_config_path = next(
                (d for d in mac_dirs if os.path.isdir(d)), 
                os.path.join(mac_dirs[1], 'pip.conf')
            )
            if not pip_config_path.endswith('.conf'):
                pip_config_path = os.path.join(pip_config_path, 'pip.conf')
        elif operating_system == 'Linux':
            home = os.environ.get('HOME', '/root')
            pip_config_path = os.path.join(home, '.config', 'pip', 'pip.conf')
        else:
            pip_config_path = os.path.join(os.environ.get('HOME', ''), '.pip', 'pip.conf')

    # Prepare default pip configuration content
    pip_config_content = [
        '\r\n[global]\r\n',
        f'{cert_prefix}{cert_location}\r\n'
    ]

    # Apply configuration
    return update_pip_configuration(pip_config_path, pip_config_content, cert_prefix="cert=")

def parse_arguments():
    """Parse command-line arguments for the script."""
    parser = argparse.ArgumentParser(
        description='''
        Automated SSL configuration utility:
        - Configure SSL certificates for Python Requests/Conda
        - Set environment variables (HTTPS_PROXY, etc.)
        - Configure pip SSL settings'''
    )

    parser.add_argument("-c", "--cert_path", type=str,
                        help="Path to folder containing SSL certificates (.pem/.crt files)",
                        default=SCRIPT_DIR)

    # Define custom actions for dictionary arguments
    class DictActionSet(argparse.Action):
        def __call__(self, parser, namespace, values, option_string=None):
            result_dict = {}
            for item in values.split(","):
                if "=" in item:
                    k, v = item.split("=", 1)
                    result_dict[k] = v
            setattr(namespace, self.dest, result_dict)

    class DictActionPrepend(argparse.Action):
        def __call__(self, parser, namespace, values, option_string=None):
            result_dict = {}
            for item in values.split(","):
                if "=" in item:
                    k, v = item.split("=", 1)
                    result_dict[k] = v
            setattr(namespace, self.dest, result_dict)

    parser.add_argument("-es", "--set_env",
                        help="Set environment variables (KEY1=VAL1,KEY2=VAL2)",
                        action=DictActionSet,
                        dest="set_env",
                        metavar="KEY1=VAL1,KEY2=VAL2")

    parser.add_argument("-ep", "--prepend_env",
                        help="Prepend to environment variables (KEY1=VAL1,KEY2=VAL2)",
                        action=DictActionPrepend,
                        dest="prepend_env",
                        metavar="KEY1=VAL1,KEY2=VAL2")

    parser.add_argument("-p", "--pip", 
                        help="Configure SSL for pip",
                        action="store_true")

    parser.add_argument("-r", "--requests", 
                        help="Configure SSL for requests/conda",
                        action="store_true")

    parser.add_argument("-a", "--aws", 
                        help="Configure AWS CLI SSL (Windows only)",
                        action="store_true")

    args = parser.parse_args()

    # Execute main function with parsed arguments
    run_main(
        cert_path=args.cert_path,
        set_env=getattr(args, 'set_env', {}),
        prepend_env=getattr(args, 'prepend_env', {}),
        do_pip=args.pip,
        do_requests=args.requests,
        do_aws=args.aws
    )

def run_main(cert_path=SCRIPT_DIR, set_env=None, prepend_env=None, 
             do_pip=False, do_aws=False, do_requests=False):
    """Main execution function for SSL configuration."""
    set_env = set_env or {}
    prepend_env = prepend_env or {}

    # Check if any operation was requested
    if not any([do_requests, do_pip, do_aws, set_env, prepend_env]):
        print("Please specify at least one operation: --requests, --pip, --prepend-env, --set_env, --aws")
        return

    # Collect certificate files
    cert_files = []
    if do_requests or do_pip or do_aws:
        extensions = ['*.pem', '*.crt']
        for ext in extensions:
            found_files = glob.glob(os.path.join(cert_path, ext))
            cert_files.extend([sanitize_path(f) for f in found_files])

    # Configure requests SSL
    if do_requests:
        if 'requests' in sys.modules and 'certifi' in sys.modules and cert_files:
            print("Requests SSL configuration started...")
            try:
                req_status = integrate_certificates(
                    sys.modules['requests'].certs.where(), 
                    cert_files
                )
                print(f"Requests Config: {req_status}")
                print("Requests SSL configuration complete.")
            except Exception as e:
                print(f"Requests configuration failed: {e}")
        else:
            missing_modules = []
            if 'requests' not in sys.modules:
                missing_modules.append("requests")
            if 'certifi' not in sys.modules:
                missing_modules.append("certifi")
            print(f"Missing modules: {', '.join(missing_modules)}. Skipping requests update.")

    # Configure environment variables
    if set_env or prepend_env:
        print("Environment variables configuration started...")
        apply_environment_updates(set_env, prepend_env)
        print("Environment variables configuration complete.")

    # Configure pip SSL
    if do_pip:
        print("Pip SSL configuration started...")
        try:
            if do_requests and 'requests' in sys.modules and 'certifi' in sys.modules:
                pip_cert_loc = sys.modules['requests'].certs.where()
            else:
                pip_cert_loc = ssl.get_default_verify_paths().cafile

            pip_status = setup_ssl_for_pip(pip_cert_loc)
            print(f"Pip Config: {pip_status}")
            print("Pip SSL configuration complete.")
        except Exception as e:
            print(f"Pip configuration failed: {e}")

    # Configure AWS CLI SSL (Windows only)
    if do_aws:
        if platform.system() == 'Windows':
            aws_cert_path = r"C:\Program Files\Amazon\AWSCLI\botocore\vendored\requests\cacert.pem"
            aws_cert_path = sanitize_path(aws_cert_path)

            if os.path.isfile(aws_cert_path):
                print("AWS CLI SSL configuration started...")
                try:
                    aws_status = integrate_certificates(aws_cert_path, cert_files)
                    print(f"AWS CLI SSL config: {aws_status}")
                    print("AWS CLI SSL configuration complete.")
                except Exception as e:
                    print(f"AWS configuration failed: {e}")
            else:
                print(f"AWS CLI certificate file not found at {aws_cert_path}")
        else:
            print("--aws flag only applies to Windows. Skipping...")

if __name__ == "__main__":
    parse_arguments()

# Custom 3D IoU-based loss implementations for object detection

import torch
import torch.nn as nn
from mmdet.models.builder import LOSSES
from mmdet.models.losses.utils import weighted_loss
from mmdet3d.ops.rotated_iou import cal_giou_3d, cal_iou_3d
from mmdet3d.core.bbox import AxisAlignedBboxOverlaps3D

@weighted_loss
def iou3d_calculator(pred_boxes, gt_boxes):
    """Compute 1 - IoU for 3D bounding boxes"""
    return 1.0 - cal_iou_3d(pred_boxes.unsqueeze(0), gt_boxes.unsqueeze(0))

@weighted_loss
def giou3d_calculator(pred_boxes, gt_boxes):
    """Compute GIoU loss for 3D bounding boxes"""
    return cal_giou_3d(pred_boxes.unsqueeze(0), gt_boxes.unsqueeze(0))[0][0]

@weighted_loss
def axis_aligned_iou_calculator(pred_boxes, gt_boxes):
    """Compute axis-aligned IoU loss for 3D bounding boxes"""
    def convert_to_corners(bbox):
        # Convert (x, y, z, w, h, l) to corner format (x1, y1, z1, x2, y2, z2)
        return torch.stack((
            bbox[..., 0] - bbox[..., 3] / 2,
            bbox[..., 1] - bbox[..., 4] / 2,
            bbox[..., 2] - bbox[..., 5] / 2,
            bbox[..., 0] + bbox[..., 3] / 2,
            bbox[..., 1] + bbox[..., 4] / 2,
            bbox[..., 2] + bbox[..., 5] / 2,
        ), dim=-1)

    # Compute axis-aligned IoU using provided utility
    iou_matrix = AxisAlignedBboxOverlaps3D()(
        convert_to_corners(pred_boxes), 
        convert_to_corners(gt_boxes), 
        is_aligned=True
    )

    # Return loss as 1 - IoU
    return 1.0 - iou_matrix

class IoU3DBase(nn.Module):
    """Base class for 3D IoU-based losses with configurable reduction and weighting"""
    def __init__(self, loss_func, reduction='mean', weight=1.0):
        super().__init__()
        self._loss_func = loss_func
        self._reduction = reduction
        self._loss_weight = weight

    def forward(self,
                predictions,
                targets,
                sample_weights=None,
                normalize_factor=None,
                override_reduction=None,
                **extra_kwargs):
        # Handle zero-weight samples
        if sample_weights is not None and not torch.any(sample_weights > 0):
            return predictions.sum() * sample_weights.sum()

        # Determine final reduction mode
        final_reduction = (
            override_reduction if override_reduction else self._reduction
        )

        # Process weights if needed
        if sample_weights is not None and sample_weights.dim() > 1:
            sample_weights = sample_weights.mean(dim=-1)

        # Compute final loss value
        loss_value = self._loss_weight * self._loss_func(
            predictions,
            targets,
            sample_weights,
            reduction=final_reduction,
            avg_factor=normalize_factor,
            **extra_kwargs
        )
        return loss_value

@LOSSES.register_module()
class IoU3DLoss(IoU3DBase):
    """3D IoU loss with optional yaw handling"""
    def __init__(self, include_yaw=True, **kwargs):
        loss_func = iou3d_calculator if include_yaw else axis_aligned_iou_calculator
        super().__init__(loss_func=loss_func, **kwargs)

@LOSSES.register_module()
class GIoU3DLoss(IoU3DBase):
    """3D Generalized IoU loss"""
    def __init__(self, **kwargs):
        super().__init__(loss_func=giou3d_calculator, **kwargs)

