from copy import deepcopy
from django import template
from holodeck.models import Dashboard
from holodeck.widgets import LineChart, SampleDeviation

register = template.Library()

@register.inclusion_tag('holodeck/inclusion_tags/dashboard_dropdown.html', takes_context=True)
def dashboard_dropdown(context):
    # Update context with sorted list of dashboards by name
    updated_context = context.copy()
    updated_context['dashboard_list'] = Dashboard.objects.all().order_by('name')
    return updated_context

@register.inclusion_tag('holodeck/inclusion_tags/render_metric.html', takes_context=True)
def render_metric(context, metric, minimal=False):
    # Create a deep copy to avoid modifying original context
    local_context = deepcopy(context)
    result = metric.render(local_context, minimal)
    return {'result': result}

@register.inclusion_tag('holodeck/inclusion_tags/dashboard_list_summary.html')
def dashboard_list_summary(dashboard):
    # Initialize base context
    context = {
        'dashboard': dashboard,
    }

    # Filter metrics that use LineChart widget
    line_chart_metrics = dashboard.metric_set.filter(
        widget_type='holodeck.widgets.LineChart'
    )

    # Find first metric with available samples
    sampled_metric = None
    for metric in line_chart_metrics:
        if metric.sample_set.exists():
            sampled_metric = metric
            break

    # If no sampled metric found, return basic context
    if not sampled_metric:
        return context

    # Generate chart and deviation contexts
    line_chart_instance = LineChart()
    sample_deviation_instance = SampleDeviation()

    chart_data = line_chart_instance.get_context(sampled_metric)
    deviation_data = sample_deviation_instance.get_context(sampled_metric)

    # Return enhanced context with computed values
    return {
        'metric': sampled_metric,
        'dashboard': dashboard,
        'samples': chart_data['samples'],
        'y_max': chart_data['y_max'] * 1.5,
        'previous': deviation_data['previous']
    }

# Reimplementation of input handling with equivalent functionality but different structure

import sys
import re
from enum import Enum

# Assuming House and error classes are defined elsewhere, we'll mock minimal versions for context
class House:
    def __init__(self, x, y):
        self.x = x
        self.y = y

class NoInputError(Exception): pass
class BadInputFormatError(Exception): pass
class BadHouseCoordinatesError(Exception): pass
class NotSupportedInputTypeError(Exception): pass
class MissingPropertyError(Exception): pass

class InputType(Enum):
    """All supported input mechanisms"""
    CLI_ARGUMENT = 0
    TERMINAL_INPUT = 1
    FILE_SOURCE = 2
    STRING_LITERAL = 3

class BaseInput:
    """Abstract base class for input sources"""

    def _extract_data(self, raw_text: str) -> list[House]:
        """Transforms raw text into a list of House objects"""
        # Normalize by removing whitespace
        normalized = raw_text.replace(" ", "")

        # Validate overall format using regex
        pattern = r"^\d+x\d+(\(\d+,\d+\))+$"
        if not re.match(pattern, normalized):
            raise BadInputFormatError('Invalid format. Expected "WIDTHxHEIGHT (X,Y) ..."')

        # Extract grid dimensions
        grid_match = re.search(r"^\d+x\d+", normalized)
        if not grid_match:
            raise BadInputFormatError("Missing grid size specification")
        width, height = map(int, grid_match.group().split("x"))

        # Extract all coordinate pairs
        coords_pattern = r"\((\d+),(\d+)\)"
        coord_matches = re.findall(coords_pattern, normalized)

        houses = []
        for cx, cy in coord_matches:
            x, y = int(cx), int(cy)
            if x > width or y > height:
                raise BadHouseCoordinatesError(f"House at ({x},{y}) is outside the {width}x{height} grid")
            houses.append(House(x, y))

        return houses

    def fetch_houses(self) -> list[House]:
        """Public method to retrieve parsed house coordinates"""
        raw = self._obtain_raw_input()
        return self._extract_data(raw)

class CliArgumentInput(BaseInput):
    """Reads input from command-line arguments"""
    def _obtain_raw_input(self) -> str:
        if len(sys.argv) < 2:
            raise NoInputError("No command-line argument provided for pizza delivery")
        return sys.argv[1]

class TerminalInput(BaseInput):
    """Prompts user for input via standard input"""
    def _obtain_raw_input(self) -> str:
        return input("Enter grid and house coordinates: ")

class FileInput(BaseInput):
    """Reads input from a specified file"""
    def __init__(self):
        self.path = None

    def _obtain_raw_input(self) -> str:
        if self.path is None:
            raise MissingPropertyError("File path must be set before reading")
        with open(self.path, 'r') as f:
            return f.readline().strip()

    def set_file_path(self, filepath: str) -> None:
        self.path = filepath

class StringInput(BaseInput):
    """Uses a string provided programmatically"""
    def __init__(self):
        self.content = None

    def _obtain_raw_input(self) -> str:
        if self.content is None:
            raise MissingPropertyError("String content must be set before use")
        return self.content

    def provide_string(self, text: str) -> None:
        self.content = text

def instantiate_input(source_type: InputType) -> BaseInput:
    """Factory function to create appropriate input handler"""
    mapping = {
        InputType.CLI_ARGUMENT: CliArgumentInput,
        InputType.TERMINAL_INPUT: TerminalInput,
        InputType.FILE_SOURCE: FileInput,
        InputType.STRING_LITERAL: StringInput
    }

    if source_type not in mapping:
        raise NotSupportedInputTypeError(f"Unsupported input type: {source_type}")

    return mapping[source_type]()

import copy
import hashlib
import logging
import d1_common.const
import d1_common.types
import d1_common.types.exceptions
import d1_common.url
import d1_common.util
import d1_common.utils.ulog
import django.conf
import django.core.cache
import django.db.models


def apply_pagination_filter(request, base_query, total_items):
    parsed_url = d1_common.url.parseUrl(request.get_full_path())
    offset_int = _validate_and_extract_param(parsed_url, "start", 0)
    limit_int = _validate_and_extract_param(
        parsed_url, "count", d1_common.const.DEFAULT_SLICE_SIZE
    )
    _ensure_valid_offset(offset_int, limit_int, total_items)
    limit_int = _cap_limit_if_needed(offset_int, limit_int, total_items)

    user_subjects = _extract_user_subjects(request)
    logging.debug(
        "Applying pagination filter. offset={} limit={} total={} subjects={}".format(
            offset_int, limit_int, total_items, ",".join(user_subjects)
        )
    )

    cached_boundary = _retrieve_cached_boundary(
        parsed_url, offset_int, total_items, user_subjects
    )
    if cached_boundary is not None:
        base_query = _apply_optimized_slice(base_query, cached_boundary, limit_int)
    else:
        base_query = _apply_standard_slice(base_query, offset_int, limit_int, total_items)

    return base_query, offset_int, limit_int


def store_slice_boundary(request, query_set, current_offset, total_count, ordering_fields):
    url_info = d1_common.url.parseUrl(request.get_full_path())
    subject_list = _extract_user_subjects(request)
    cache_key = _build_cache_identifier(
        url_info, current_offset + query_set.count(), total_count, subject_list
    )

    last_item = query_set[query_set.count() - 1] if query_set.count() > 0 else None
    boundary_tuple = (
        tuple(getattr(last_item, field) for field in ordering_fields) if last_item else None
    )

    django.core.cache.cache.set(cache_key, boundary_tuple)
    logging.debug('Stored boundary in cache. key="{}" boundary={}'.format(cache_key, boundary_tuple))


# --- Private helpers ---

def _validate_and_extract_param(url_data, param_name, default_val):
    raw_value = url_data["query"].get(param_name, str(default_val))
    try:
        numeric_val = int(raw_value)
    except ValueError:
        raise d1_common.types.exceptions.InvalidRequest(
            0,
            'Pagination parameter "{}" must be an integer. Got: "{}"'.format(
                param_name, raw_value
            ),
        )
    if numeric_val < 0:
        raise d1_common.types.exceptions.InvalidRequest(
            0,
            'Pagination parameter "{}" cannot be negative. Got: "{}"'.format(
                param_name, raw_value
            ),
        )
    return numeric_val


def _ensure_valid_offset(offset, size, total):
    if total > 0 and offset >= total:
        raise d1_common.types.exceptions.InvalidRequest(
            0,
            "Invalid slice request: start beyond available items. "
            "start={} count={} total={}".format(offset, size, total)
        )


def _cap_limit_if_needed(offset, requested_size, max_available):
    remaining = max_available - offset
    adjusted_size = min(requested_size, remaining) if remaining >= 0 else 0
    upper_bound = django.conf.settings.MAX_SLICE_ITEMS
    return min(adjusted_size, upper_bound)


def _extract_user_subjects(http_request):
    return sorted(list(http_request.all_subjects_set))


def _apply_optimized_slice(query_obj, boundary_vals, item_limit):
    ts_field, id_field = boundary_vals
    logging.debug(
        "Using optimized slice. boundary={} limit={}".format(boundary_vals, item_limit)
    )
    condition = (
        (django.db.models.Q(timestamp__gt=ts_field)) |
        (django.db.models.Q(timestamp=ts_field) & django.db.models.Q(id__gt=id_field))
    )
    return query_obj.filter(condition)[:item_limit]


def _apply_standard_slice(query_obj, start_idx, num_items, total_avail):
    logging.debug(
        "Falling back to standard slice. start={} count={} total={} ".format(
            start_idx, num_items, total_avail
        )
    )
    if num_items == 0:
        return query_obj.none()
    return query_obj[start_idx : start_idx + num_items]


def _retrieve_cached_boundary(url_dict, start_pos, total_items, auth_subjects):
    cache_id = _build_cache_identifier(url_dict, start_pos, total_items, auth_subjects)
    try:
        result = django.core.cache.cache.get(cache_id)
    except KeyError:
        result = None
    logging.debug('Cache lookup. key="{}" -> value={}'.format(cache_id, result))
    return result


def _build_cache_identifier(url_data, offset, total, subjects):
    normalized_url = copy.deepcopy(url_data)
    normalized_url["query"].pop("start", None)
    normalized_url["query"].pop("count", None)

    payload = {
        "url": normalized_url,
        "offset": offset,
        "total": total,
        "subjects": subjects,
    }

    compact_json = d1_common.util.serialize_to_normalized_compact_json(payload)
    logging.debug("Generated cache key JSON: {}".format(compact_json))

    encoded = compact_json.encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()

