class JSONPlugin(base.Comparator):
    """Dac-Man plug-in to compare JSON files"""

    @staticmethod
    def description():
        return JSONPlugin.__doc__

    @staticmethod
    def supports():
        return ['json']

    # Markers for differences
    plus_sign = '+/+'
    minus_sign = '-/-'

    def _check_paths_exist(self, file_paths: list) -> bool:
        all_valid = True
        for path in file_paths:
            if not os.path.exists(path):
                _logger.error(f'Invalid path: {path}')
                all_valid = False
        return all_valid

    def _display_diff_tree(
            self, diff_data: dict, prefix: str = '', spacing: int = 2):
        indent = spacing * ' '
        for key, value in diff_data.items():
            if key.startswith((self.plus_sign, self.minus_sign)):
                marker, actual_key = key[0], key[len(self.plus_sign):]
            else:
                marker, actual_key = prefix, key

            if isinstance(value, dict):
                _logger.info(f'{marker}{indent}{actual_key}: {{')
                new_spacing = spacing + 2
                self._display_diff_tree(
                    value, prefix=marker, spacing=new_spacing)
                _logger.info(f'{marker}{indent}}}')
            else:
                _logger.info(f'{marker}{indent}{actual_key}: {value}')

    def _count_json_keys(self, json_obj: dict, depth: int = 0) -> dict:
        counts = {depth: 0}
        for k, v in json_obj.items():
            if isinstance(v, dict):
                sub_counts = self._count_json_keys(v, depth + 1)
                for d, c in sub_counts.items():
                    counts[d] = c
            counts[depth] += 1
        return counts

    def _gather_unique_key_info(
            self, filename: str, data: dict, stats: dict):
        top_level = stats.setdefault(0, {})
        top_level[filename] = top_level.get(filename, 0) + 1

        if not isinstance(data, dict):
            return

        key_distribution = self._count_json_keys(data)
        total_keys = 1 + sum(key_distribution.values())
        stats[f'total_{filename}_keys'] += total_keys

        for level, count in key_distribution.items():
            nested_stats = stats.setdefault(level + 1, {})
            nested_stats[filename] = nested_stats.get(filename, 0) + count

    def _compare_json_objects(
            self, obj_a: dict, obj_b: dict, depth: int = 0) -> (dict, dict):
        result = {}
        keys_a = set(obj_a.keys())
        keys_b = set(obj_b.keys())

        stats = {
            f'total_{self.file_a}_keys': 0,
            f'total_{self.file_b}_keys': 0,
            'shared_keys_count': 0,
            depth: {self.file_a: 0, self.file_b: 0, 'common': 0}}

        # Keys only in A
        for key in keys_a - keys_b:
            result[f'{self.plus_sign}{key}'] = obj_a[key]
            self._gather_unique_key_info(self.file_a, obj_a[key], stats)

        # Keys only in B
        for key in keys_b - keys_a:
            result[f'{self.minus_sign}{key}'] = obj_b[key]
            self._gather_unique_key_info(self.file_b, obj_b[key], stats)

        # Common keys
        for key in keys_a & keys_b:
            stats['shared_keys_count'] += 1
            val_a = obj_a[key]
            val_b = obj_b[key]
            stats[depth]['common'] += 1

            if isinstance(val_a, dict) and isinstance(val_b, dict):
                sub_result, sub_stats = self._compare_json_objects(
                    val_a, val_b, depth + 1)
                if sub_result:
                    result[key] = sub_result

                for stat_key, stat_val in sub_stats.items():
                    if not isinstance(stat_val, dict):
                        stats[stat_key] += stat_val
                    else:
                        for src, cnt in stat_val.items():
                            level_stat = stats.setdefault(depth + 1, {})
                            level_stat[src] = level_stat.get(src, 0) + cnt
            elif val_a != val_b:
                result[f'{self.plus_sign}{key}'] = val_a
                result[f'{self.minus_sign}{key}'] = val_b

        return result, stats

    def compare(self, path_a: str, path_b: str, **kwargs):
        """Core function for comparing JSON files"""
        self.file_a = os.path.basename(path_a)
        self.file_b = os.path.basename(path_b)

        if not self._check_paths_exist([path_a, path_b]):
            return

        with open(path_a) as af, open(path_b) as bf:
            data_a = json.load(af)
            data_b = json.load(bf)

        diff_result, statistics = self._compare_json_objects(data_a, data_b)
        if not diff_result:
            return

        self.stats_data = statistics

        # Switch to pretty-print formatter
        _handler.setFormatter(_pprint_fmt)

        disclaimer = (
            '\n'
            f'Entries from {self.file_a} marked with "+"\n'
            f'Entries from {self.file_b} marked with "-"\n'
            '\n'
        )
        _logger.info(disclaimer)
        self._display_diff_tree(diff_result)

        # Restore standard formatter
        _handler.setFormatter(_std_fmt)

    def _generate_level0_report(self):
        comparison_word = 'more'
        if float(self._change_percent) < 0:
            comparison_word = 'less'

        detail = (
            '\n'
            'Level 0 summary:\n'
            f'\t{self.file_a} has {self._change_percent:05.2f}% '
            f'{comparison_word} keys than {self.file_b}'
            '\n')
        return detail

    def _generate_level1_report(self):
        shared = self.stats_data.get('shared_keys_count', 0)
        detail = (
            '\n'
            'Level 1 summary:\n'
            f'\tTotal unique keys in {self.file_a}: {self.total_a}\n'
            f'\tTotal unique keys in {self.file_b}: {self.total_b}\n'
            f'\tNumber of common keys: {shared}'
            '\n')
        return detail

    def _generate_level2_report(self):
        lines = []
        header = '\nLevel 2 breakdown:'

        for level, details in self.stats_data.items():
            if not isinstance(level, int):
                continue

            lines.append(f'JSON depth {level}:')
            for name, count in details.items():
                if name == 'common':
                    lines.append(f'\t{count} shared keys')
                else:
                    lines.append(f'\t{count} keys specific to {name}')

        return f'{header}\n\t' + '\n\t'.join(lines)

    def _validate_detail_level(self, requested_level: int) -> int:
        max_allowed = 2
        try:
            self.output_options
            try:
                custom_level = self.output_options.get('detail_level')
                custom_level = int(custom_level)
                if not (0 <= custom_level <= max_allowed):
                    raise ValueError('Detail level must be between 0 and 2')
                _logger.info(f'Using custom detail level {custom_level}')
                return custom_level
            except Exception as e:
                _logger.warning(f'Invalid detail level specified: {e}. Using default.')
        except AttributeError:
            _logger.info('No custom detail level provided; using default.')
        return requested_level

    def calculate_percentage_change(self):
        try:
            self.total_a = (
                self.stats_data.get(f'total_{self.file_a}_keys', 0) +
                self.stats_data.get('shared_keys_count', 0))
            self.total_b = (
                self.stats_data.get(f'total_{self.file_b}_keys', 0) +
                self.stats_data.get('shared_keys_count', 0))

            diff = self.total_a - self.total_b
            self._change_percent = (diff / self.total_a) * 100 if self.total_a else 0.0
        except Exception:
            return False
        return True

    def report_statistics(self, changes, detail_level=0):
        if not self.calculate_percentage_change():
            return

        detail_level = self._validate_detail_level(detail_level)
        reports = []

        if detail_level >= 0:
            reports.append(self._generate_level0_report())
        if detail_level >= 1:
            reports.append(self._generate_level1_report())
        if detail_level >= 2:
            reports.append(self._generate_level2_report())

        _handler.setFormatter(_pprint_fmt)
        for report in reports:
            _logger.info(report)
        _handler.setFormatter(_pprint_fmt)

import numpy as np
from constants import *
from orbit_util import trace_orbit, sign, get_dist_to_good, gravity_step, trace_orbit_np
from states import State, JoinResult, ThrustPredictor, Thrust
from orbiter import LaserShipStrategy


def min_absolute_deviation(a, b):
    return min(abs(a), abs(b))


def compute_resource_cost(stats):
    base, lasers, regens, lives = stats
    return base + LASER_COST * lasers + REGEN_COST * regens + LIVES_COST * lives


class SwarmCommander(object):
    def __init__(self, lookahead=16, homing_delay=64, homing_margin=3, debug=False):
        self.time_step = 0
        self.lookahead_steps = lookahead
        self.homing_wait_limit = homing_delay
        self.homing_tolerance = homing_margin
        self.thrust_forecasters = {}
        self.mother_id = None
        self.laser_control = LaserShipStrategy()
        self.verbose = debug

    def allocate_resources(self, response):
        parsed = JoinResult.parse(response)
        # Prioritize laser ship if budget allows
        optimal_stats = [20, 32, 8, 1] if parsed.budget > 490 else [0, 0, 0, 0]
        laser_allocation = compute_resource_cost(optimal_stats)
        swarm_budget = parsed.budget - laser_allocation
        swarm_count = swarm_budget // 6
        fuel_for_swarm = swarm_budget - LIVES_COST * swarm_count
        return [
            fuel_for_swarm + optimal_stats[0],
            optimal_stats[1],
            optimal_stats[2],
            swarm_count + optimal_stats[3]
        ]

    def clear_cached_predictions(self):
        self.enemy_position_cache = {}
        self.enemy_thrust_cache = {}

    def forecast_opponent_behavior(self, opponent):
        thrust_pred = self.thrust_forecasters[opponent.id].get_prediction() if opponent.fuel > 0 else Thrust(0, 0)
        ox, oy = opponent.predict_next_position(thrust_pred)
        self.enemy_position_cache[opponent.id] = (ox, oy)
        self.enemy_thrust_cache[opponent.id] = thrust_pred

    def select_explode_target(self, unit, move, foes):
        best_distance = float('inf')
        selected = foes[0]
        if len(foes) == 1:
            return selected
        for foe in foes:
            predicted_move = self.enemy_thrust_cache[foe.id]
            dist = unit.compute_future_distance(move, foe, predicted_move)
            if dist < best_distance:
                best_distance = dist
                selected = foe
        return selected

    def pick_laser_target(self, unit, move, foes):
        highest_potential = 0
        chosen = None
        for foe in foes:
            predicted_move = self.enemy_thrust_cache[foe.id]
            fx, fy = self.enemy_position_cache[foe.id]
            potential = unit.calculate_laser_impact(move, fx, fy)
            if potential > 0 and potential + foe.fuel > highest_potential:
                highest_potential = potential + foe.fuel
                chosen = foe
        return chosen

    def evaluate_laser_effectiveness(self, unit, move, foe):
        remaining_heat_capacity = (
            unit.max_thermal_load +
            unit.recovery_rate -
            unit.current_thermal -
            (THERMAL_FROM_THRUST if move != Thrust(0, 0) else 0)
        )
        available_power = min(remaining_heat_capacity, unit.laser_capacity)
        predicted_move = self.enemy_thrust_cache[foe.id]
        fx, fy = self.enemy_position_cache[foe.id]
        effective_power = unit.compute_laser_output(move, fx, fy, available_power)
        return available_power if effective_power > 0 else 0

    def avoid_planet_collision(self, unit, state):
        current_risk = get_dist_to_good(unit.x, unit.y, unit.vx, unit.vy)
        if current_risk is not None and current_risk > 0:
            safe_moves = []
            for dx in range(-2, 3):
                for dy in range(-2, 3):
                    if unit.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                        continue
                    new_state = gravity_step(unit.x, unit.y, unit.vx + dx, unit.vy + dy)
                    next_risk = get_dist_to_good(*new_state)
                    if next_risk is not None and next_risk == current_risk - 1:
                        safe_moves.append((-dx, -dy))
            if safe_moves:
                chosen = np.random.choice(len(safe_moves))
                return Thrust(*safe_moves[chosen])
        return Thrust(0, 0)

    def command_mothership(self, unit, state, enemies):
        actions = []
        if unit.lives > 1:
            leftover_fuel = max(unit.fuel - self.laser_ship_stats[0], 0)
            for attempt in range(unit.lives - 1, 0, -1):
                fuel_per_clone = (leftover_fuel * attempt) // (unit.lives - 1)
                if 2 * (fuel_per_clone + attempt) >= unit.total_health():
                    continue
                actions.append(unit.create_duplicate_from_base(fuel_per_clone, attempt))
                break

        # Use defensive maneuvering before applying laser strategy
        movement = self.avoid_planet_collision(unit, state)
        if movement.x != 0 or movement.y != 0:
            actions.append(unit.execute_thrust(movement.x, movement.y))
        actions.extend(
            self.laser_control.apply_defense(state, unit, enemies, movement, self.enemy_position_cache)
        )
        return actions

    def calculate_explosion_benefit(self, unit, allies, enemies, already_engaged):
        benefit = 0
        no_thrust = Thrust(0, 0)
        affected_ids = {unit.id}
        for ally in allies:
            if ally.id in already_engaged:
                continue
            if unit.id == ally.id:
                benefit -= unit.total_health()
            else:
                separation = unit.estimate_separation(no_thrust, ally, no_thrust)
                blast_radius = unit.explode_range(separation)
                damage = min(ally.total_health(), blast_radius)
                benefit -= damage
                if blast_radius > 0:
                    affected_ids.add(ally.id)
        for enemy in enemies:
            if enemy.id in already_engaged:
                continue
            separation = unit.estimate_separation(no_thrust, enemy, no_thrust)
            blast_radius = unit.explode_range(separation)
            gain = 2 * min(enemy.total_health(), blast_radius)
            benefit += gain
            if blast_radius > 0:
                affected_ids.add(enemy.id)
        return benefit, list(affected_ids)

    def execute(self, game_state):
        self.time_step += 1
        st = State.parse(game_state)
        self.clear_cached_predictions()
        orders = []

        # Update prediction models
        for unit in st.units:
            if unit.id not in self.thrust_forecasters:
                self.thrust_forecasters[unit.id] = ThrustPredictor()
            self.thrust_forecasters[unit.id].record(unit.last_actions)

        my_units = []
        enemy_units = []
        for u in st.units:
            if u.owner == st.me:
                if self.mother_id is None and self.laser_ship_stats[3] > 0:
                    self.mother_id = u.id
                my_units.append(u)
            else:
                enemy_units.append(u)
                self.forecast_opponent_behavior(u)

        # Group identical orbital states
        grouped_orbits = {}
        if self.verbose:
            print(f'T:{self.time_step} Player {st.me}:')
            for s in my_units:
                print(str(s))

        for u in my_units:
            key = (u.x, u.y, u.vx, u.vy)
            if key not in grouped_orbits:
                grouped_orbits[key] = []
            grouped_orbits[key].append(u)

        # Prepare enemy arrays for vectorized prediction
        ex = np.array([e.x for e in enemy_units])
        ey = np.array([e.y for e in enemy_units])
        evx = np.array([e.vx for e in enemy_units])
        evy = np.array([e.vy for e in enemy_units])
        exs, eys, _, _ = trace_orbit_np(ex, ey, evx, evy, self.lookahead_steps)

        explosion_orders = []
        engaged_ids = set()

        for orbit_key, fleet in grouped_orbits.items():
            risk_level = get_dist_to_good(*orbit_key)
            if len(fleet) > 1:
                viable_thrusts = []
                target_separation = 3 if sum(ship.lives for ship in fleet) >= 32 else 0
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        if dx == 0 and dy == 0:
                            continue
                        new_state = gravity_step(orbit_key[0], orbit_key[1], orbit_key[2] + dx, orbit_key[3] + dy)
                        next_risk = get_dist_to_good(*new_state)
                        if next_risk is not None and next_risk < target_separation:
                            target_separation = next_risk
                            viable_thrusts = []
                        if next_risk is not None and next_risk == target_separation:
                            viable_thrusts.append((-dx, -dy))
                if viable_thrusts:
                    np.random.shuffle(viable_thrusts)
                    for ship, thrust in zip(fleet[1:], viable_thrusts):
                        orders.append([0, ship.id, thrust])
                continue

            unit = fleet[0]
            if risk_level is not None and risk_level > 0 and self.time_step <= 48:
                safe_moves = []
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        if unit.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                            continue
                        new_state = gravity_step(orbit_key[0], orbit_key[1], orbit_key[2] + dx, orbit_key[3] + dy)
                        next_risk = get_dist_to_good(*new_state)
                        if next_risk is not None and next_risk == risk_level - 1:
                            safe_moves.append((-dx, -dy))
                if safe_moves:
                    idx = np.random.randint(len(safe_moves))
                    orders.append([0, unit.id, safe_moves[idx]])
                continue

            if risk_level == 0 and unit.lives > 1:
                orders.append(unit.spawn_copy())
                continue

            if enemy_units:
                move = Thrust(0, 0)
                target = self.select_explode_target(unit, move, enemy_units)
                predicted_move = self.enemy_thrust_cache[target.id]
                future_dist = unit.estimate_separation(move, target, predicted_move)
                if unit.explode_range(future_dist) and self.time_step > 7:
                    benefit, hit_list = self.calculate_explosion_benefit(unit, my_units, enemy_units, engaged_ids)
                    if benefit > 0:
                        explosion_orders.append(unit.trigger_detonation())
                        for hid in hit_list:
                            engaged_ids.add(hid)
                        continue

                # Homing logic
                if self.time_step > self.homing_wait_limit and unit.fuel > 0:
                    candidate_thrusts = []
                    mx, my, mvx, mvy = [], [], [], []
                    optimal_idx = None
                    for dx in range(-2, 3):
                        for dy in range(-2, 3):
                            if unit.fuel == 1 and max(abs(dx), abs(dy)) == 2:
                                continue
                            new_state = gravity_step(orbit_key[0], orbit_key[1], orbit_key[2] + dx, orbit_key[3] + dy)
                            risk = get_dist_to_good(*new_state)
                            if risk is not None and risk == 0:
                                if dx == 0 and dy == 0:
                                    optimal_idx = len(mx)
                                candidate_thrusts.append((-dx, -dy))
                                mx.append(orbit_key[0])
                                my.append(orbit_key[1])
                                mvx.append(orbit_key[2] + dx)
                                mvy.append(orbit_key[3] + dy)
                    if candidate_thrusts:
                        mx, my, mvx, mvy = map(np.array, (mx, my, mvx, mvy))
                        mxs, mys, _, _ = trace_orbit_np(mx, my, mvx, mvy, self.lookahead_steps)
                        dx_matrix = np.abs(mxs[:, np.newaxis] - exs[np.newaxis])
                        dy_matrix = np.abs(mys[:, np.newaxis] - eys[np.newaxis])
                        dist_matrix = np.maximum(dx_matrix, dy_matrix)
                        min_dists = np.min(dist_matrix, axis=(1, 2))
                        close_candidates = []
                        for i, thrust in enumerate(candidate_thrusts):
                            if min_dists[i] <= self.homing_tolerance:
                                close_candidates.append(thrust)
                                if i == optimal_idx:
                                    if self.verbose:
                                        print("abort homing")
                                    close_candidates = []
                                    break
                        if close_candidates:
                            if self.verbose:
                                print("homing initiated")
                            idx = np.random.randint(len(close_candidates))
                            orders.append([0, unit.id, close_candidates[idx]])
                            continue

        for exp_order in explosion_orders:
            orders.append(exp_order)
        return orders

