def _extract_source(obj):
	source_lines = inspect.getsource(obj).split("\n")
	base_indent = len(source_lines[0]) - len(source_lines[0].lstrip())
	return "\n".join(line[base_indent:] for line in source_lines)

class _ASTTransformer(ast.NodeTransformer):
	def __init__(self, target_name, replacement_name):
		super().__init__()
		self.target = target_name
		self.replacement = replacement_name

	def visit_Name(self, node):
		if node.id == self.target:
			return ast.Name(id=self.replacement, ctx=node.ctx)
		return node

_transformer = _ASTTransformer("_GlyphBox", "_TLGlyphBox")

def _apply_patch(original_class, method_name):
	module = inspect.getmodule(original_class)
	method_ast = ast.parse(_extract_source(getattr(original_class, method_name)))
	modified_ast = ast.fix_missing_locations(_transformer.visit(method_ast))

	module.__dict__["_TLGlyphBox"] = _TLGlyphBox
	global_dict = module.__dict__
	exec(compile(modified_ast, f"<patch from {inspect.getfile(module)}>", "exec"), global_dict)
	patched_method = global_dict.pop(method_name)
	return patched_method

# Vertex Shaders with Modified Camera Transformations
layout_vertex_source = """
#version 330 core
in vec2 position;
in vec4 colors;
in vec3 tex_coords;
in vec2 translation;
out vec4 text_colors;
out vec2 texture_coords;
out vec4 vert_position;
uniform WindowBlock
{
	mat4 projection;
	mat4 view;
} window;
layout (std140) uniform CameraAttrs {
	float zoom;
	vec2  position;
	vec2  GAME_DIMENSIONS;
} camera;
mat4 m_trans_scale = mat4(1.0);
mat4 m_camera_trans_scale = mat4(1.0);
mat4 m_camera_pre_trans = mat4(1.0);
void main()
{
	m_trans_scale[3] = vec4(translation, 1.0, 1.0);
	m_camera_trans_scale[3][0] = (camera.zoom * -camera.position.x) + (camera.GAME_DIMENSIONS.x / 2);
	m_camera_trans_scale[3][1] = (camera.zoom * -camera.position.y) + (camera.GAME_DIMENSIONS.y / 2);
	m_camera_trans_scale[0][0] = camera.zoom;
	m_camera_trans_scale[1][1] = camera.zoom;
	m_camera_pre_trans[3][0] = -camera.GAME_DIMENSIONS.x / 2;
	m_camera_pre_trans[3][1] = -camera.GAME_DIMENSIONS.y / 2;
	gl_Position =
		window.projection *
		window.view *
		m_camera_trans_scale *
		m_camera_pre_trans *
		m_trans_scale *
		vec4(position, 0, 1)
	;
	vert_position = vec4(position + translation, 0, 1);
	text_colors = colors;
	texture_coords = tex_coords.xy;
}
"""

decoration_vertex_source = """
#version 330 core
in vec2 position;
in vec4 colors;
in vec2 translation;
out vec4 vert_colors;
out vec4 vert_position;
uniform WindowBlock
{
	mat4 projection;
	mat4 view;
} window;
layout (std140) uniform CameraAttrs {
	float zoom;
	vec2  position;
	vec2  GAME_DIMENSIONS;
} camera;
mat4 m_trans_scale = mat4(1.0);
mat4 m_camera_trans_scale = mat4(1.0);
mat4 m_camera_pre_trans = mat4(1.0);
void main()
{
	m_trans_scale[3] = vec4(translation, 1.0, 1.0);
	m_camera_trans_scale[3][0] = (camera.zoom * -camera.position.x) + (camera.GAME_DIMENSIONS.x / 2);
	m_camera_trans_scale[3][1] = (camera.zoom * -camera.position.y) + (camera.GAME_DIMENSIONS.y / 2);
	m_camera_trans_scale[0][0] = camera.zoom;
	m_camera_trans_scale[1][1] = camera.zoom;
	m_camera_pre_trans[3][0] = -camera.GAME_DIMENSIONS.x / 2;
	m_camera_pre_trans[3][1] = -camera.GAME_DIMENSIONS.y / 2;
	gl_Position =
		window.projection *
		window.view *
		m_camera_trans_scale *
		m_camera_pre_trans *
		m_trans_scale *
		vec4(position, 0, 1)
	;
	vert_position = vec4(position + translation, 0, 1);
	vert_colors = colors;
}
"""

_LAYOUT_SHADER_CONTAINER = ShaderContainer(layout_vertex_source, layout_fragment_source)
_DECORATION_SHADER_CONTAINER = ShaderContainer(decoration_vertex_source, decoration_fragment_source)

class PNFTextLayoutGroup(PNFGroup):
	def __init__(
		self,
		texture: "Texture",
		program: "ShaderProgram",
		cam_ubo: "UniformBufferObject",
		parent: t.Optional["PNFGroup"] = None,
		order: int = 0,
	) -> None:
		super().__init__(
			parent,
			order,
			(
				states.ProgramStateMutator(program),
				states.UBOBindingStateMutator(cam_ubo),
				states.UniformStateMutator(program, "scissor", False),
				states.TextureUnitStateMutator(gl.GL_TEXTURE0),
				states.TextureStateMutator(texture),
				states.EnableStateMutator(gl.GL_BLEND),
				states.BlendFuncStateMutator(gl.GL_SRC_ALPHA, gl.GL_ONE_MINUS_SRC_ALPHA),
			),
		)

class PNFTextDecorationGroup(PNFGroup):
	def __init__(
		self,
		program: "ShaderProgram",
		cam_ubo: "UniformBufferObject",
		parent: t.Optional["PNFGroup"] = None,
		order: int = 0,
	) -> None:
		super().__init__(
			parent,
			order,
			(
				states.ProgramStateMutator(program),
				states.UBOBindingStateMutator(cam_ubo),
				states.UniformStateMutator(program, "scissor", False),
				states.EnableStateMutator(gl.GL_BLEND),
				states.BlendFuncStateMutator(gl.GL_SRC_ALPHA, gl.GL_ONE_MINUS_SRC_ALPHA),
			),
		)

class _TLGlyphBox(_GlyphBox):
	def place(self, layout, i, x, y, context):
		assert self.glyphs
		try:
			group = layout.group_cache[self.owner]
		except KeyError:
			group = layout.group_class(
				self.owner,
				_LAYOUT_SHADER_CONTAINER.get_program(),
				layout._context.camera.ubo,
				order=1,
				parent=layout.group,
			)
			layout.group_cache[self.owner] = group

		n_glyphs = self.length
		vertices = []
		tex_coords = []
		baseline = 0
		x1 = x

		for start, end, baseline in context.baseline_iter.ranges(i, i + n_glyphs):
			baseline = layout.parse_distance(baseline)
			assert len(self.glyphs[start - i:end - i]) == end - start
			for kern, glyph in self.glyphs[start - i:end - i]:
				x1 += kern
				vx1, vy1, vx2, vy2 = glyph.vertices
				# TOP LEFT MODIFICATION HERE #
				vy1, vy2 = vy2, vy1
				vx1 += x1
				vx2 += x1
				vy1 += y + baseline
				vy2 += y + baseline
				vertices.extend(map(int, [vx1, vy1, vx2, vy1, vx2, vy2, vx1, vy2]))
				t = glyph.tex_coords
				tex_coords.extend(t)
				x1 += glyph.advance

		colors = []
		for start, end, color in context.colors_iter.ranges(i, i + n_glyphs):
			if color is None:
				color = (0, 0, 0, 255)
			colors.extend(color * ((end - start) * 4))

		indices = []
		for idx in range(n_glyphs):
			indices.extend([element + (idx * 4) for element in [0, 1, 2, 0, 2, 3]])

		vertex_list = layout.batch.add_indexed(
			n_glyphs * 4,
			gl.GL_TRIANGLES,
			group,
			indices,
			('position2f/dynamic', vertices),
			('colors4Bn/dynamic', colors),
			('tex_coords3f/dynamic', tex_coords),
			'translation2f/dynamic',
		)
		context.add_list(vertex_list)

		# Decoration (background color and underline)
		background_vertices = []
		background_colors = []
		underline_vertices = []
		underline_colors = []
		y1 = y + self.descent + baseline
		y2 = y + self.ascent + baseline
		x1 = x

		for start, end, decoration in context.decoration_iter.ranges(i, i + n_glyphs):
			bg, underline = decoration
			x2 = x1
			for kern, glyph in self.glyphs[start - i:end - i]:
				x2 += glyph.advance + kern
			if bg is not None:
				background_vertices.extend([x1, y1, x2, y1, x2, y2, x1, y2])
				background_colors.extend(bg * 4)
			if underline is not None:
				underline_vertices.extend([x1, y + baseline - 2, x2, y + baseline - 2])
				underline_colors.extend(underline * 2)
			x1 = x2

		if background_vertices:
			background_list = layout.batch.add_indexed(
				len(background_vertices) // 2,
				gl.GL_TRIANGLES,
				layout.background_decoration_group,
				[0, 1, 2, 0, 2, 3],
				('position2f/dynamic', background_vertices),
				('colors4Bn/dynamic', background_colors),
				'translation2f/dynamic',
			)
			context.add_list(background_list)

		if underline_vertices:
			underline_list = layout.batch.add(
				len(underline_vertices) // 2,
				gl.GL_LINES,
				layout.foreground_decoration_group,
				('position2f/dynamic', underline_vertices),
				('colors4Bn/dynamic', underline_colors),
				'translation2f/dynamic',
			)
			context.add_list(underline_list)

class PNFLabel(Label, SceneObject):
	group_class = PNFTextLayoutGroup
	decoration_class = PNFTextDecorationGroup
	_flow_glyphs_single_line = _apply_patch(TextLayout, "_flow_glyphs_single_line")
	_flow_glyphs_wrap = _apply_patch(TextLayout, "_flow_glyphs_wrap")

	def __init__(
		self,
		text="",
		font_name=None,
		font_size=None,
		bold=False,
		italic=False,
		stretch=False,
		color=(255, 255, 255, 255),
		x=0,
		y=0,
		width=None,
		height=None,
		anchor_x='left',
		anchor_y='baseline',
		align='left',
		multiline=False,
		dpi=None,
		context=None,
		wrap_lines=True,
	) -> None:
		self._context = context or Context()

		document = decode_text(text)

		self.content_width = 0
		self.content_height = 0
		self._user_group = self._context.group
		decoration_shader = _DECORATION_SHADER_CONTAINER.get_program()
		self.background_decoration_group = self.decoration_class(
			decoration_shader, self._context.camera.ubo, order=0, parent=self._user_group
		)
		self.foreground_decoration_group = self.decoration_class(
			decoration_shader, self._context.camera.ubo, order=2, parent=self._user_group
		)
		self.group_cache = {}

		self._batch = self._context.batch
		self._width = width
		self._height = height
		self._multiline = multiline
		self._flow_glyphs = self._flow_glyphs_wrap if multiline else self._flow_glyphs_single_line
		self._wrap_lines_flag = wrap_lines
		self._wrap_lines_invariant()
		self._dpi = dpi or 96
		self.document = document

		self._x = x
		self._y = y
		self._anchor_x = anchor_x
		self._anchor_y = anchor_y
		self._update()

		self.document.set_style(0, len(self.document.text), {
			'font_name': font_name,
			'font_size': font_size,
			'bold': bold,
			'italic': italic,
			'stretch': stretch,
			'color': color,
			'align': align,
		})

	def update(self, dt: float) -> None:
		pass

	def set_context(self, parent_context: Context) -> None:
		new_batch = parent_context.batch
		old_batch = self._context.batch

		change_batch = new_batch != old_batch
		if (
			parent_context.camera != self._context.camera or
			parent_context.group != self._context.group.parent
		):
			raise RuntimeError(
				"Labels can't change their group, unfortunately you'll have to recreate them."
			)
		if change_batch:
			self._context.batch = new_batch
			self._batch = new_batch
			self._own_batch = False
			self._update()

	def invalidate_context(self) -> None:
		pass

	def delete(self) -> None:
		super().delete()
		self._context = None

from .util import auto_repr, to_snake_case

class Account:
    """A model used to describe a Loopring account."""
    account_id: int
    frozen: bool
    key_nonce: int
    key_seed: str
    nonce: int
    owner: str
    publicX: str
    publicY: str
    tags: str

    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            if key == "publicKey":
                # Handle nested publicKey object by flattening it
                for sub_key, sub_val in value.items():
                    setattr(self, f"public{sub_key.upper()}", sub_val)
            else:
                setattr(self, to_snake_case(key), value)

    def __repr__(self) -> str:
        return auto_repr(self)

    def __str__(self) -> str:
        return self.owner


class _PendingBalance:
    deposit: int
    withdraw: int

    def __init__(self, **kwargs):
        for field_name, field_value in kwargs.items():
            setattr(self, to_snake_case(field_name), int(field_value))

    def __repr__(self) -> str:
        return f"<deposit={self.deposit} withdraw={self.withdraw}>"

    def __str__(self) -> str:
        return f"Deposit: {self.deposit}, Withdraw: {self.withdraw}"


class Balance:
    account_id: int
    locked: int
    pending: _PendingBalance
    token_id: int
    total: int

    def __init__(self, **kwargs):
        for field_name, field_value in kwargs.items():
            if field_name == "pending":
                self.pending = _PendingBalance(**field_value)
            else:
                setattr(self, to_snake_case(field_name), int(field_value))

    def __repr__(self) -> str:
        return auto_repr(self)

    def __str__(self) -> str:
        return str(self.total)

from typing import Union, List

from .api import Requester, Response, Price, Recipient


class HLRL(Recipient):
    def __init__(self, *args, tariff: int = None, callback_url: str = None, **kwargs):
        # Conditionally add optional parameters to kwargs
        if tariff is not None:
            kwargs['tariff'] = tariff
        if callback_url is not None:
            kwargs['callback_url'] = callback_url
        super().__init__(*args, **kwargs)


class HLRAPI(Requester):
    def __init__(self, *args, **kwargs):
        self.hlrl_records = []
        super().__init__(*args, **kwargs)

    def get_prices(self, tariff: int = None) -> List[Price]:
        raw_response = Response(self.proceed('hlr', 'prices', function_param=tariff))
        price_list = raw_response.get('prices', [])
        for idx, item in enumerate(price_list):
            price_list[idx] = Price(**item)
        return price_list

    def get_status(self, hlrl_id: Union[str, int, HLRL] = None) -> Union[dict, list]:
        if hlrl_id is not None:
            if isinstance(hlrl_id, str):
                return Response(self.proceed('hlr', 'reference', hlrl_id))
            elif isinstance(hlrl_id, HLRL):
                if 'result' not in hlrl_id or not hlrl_id['result']:
                    hlrl_id['result'] = self.send(hlrl_id)
                # Extract the ID from the result; ensure it's an integer
                hlrl_id = int(hlrl_id['result']['id'])
            if isinstance(hlrl_id, int):
                return Response(self.proceed('hlr', str(hlrl_id)))
        elif self.hlrl_records:
            # Process records that haven't been sent yet
            pending_records = [rec for rec in self.hlrl_records if 'result' not in rec or not rec['result']]
            if pending_records:
                batch_response = self.send(pending_records)
                for i, record in enumerate(pending_records):
                    record['result'] = batch_response['result'][i]
            # Fetch status for all stored records
            for record in self.hlrl_records:
                record['status'] = Response(self.proceed('hlr', str(record['result']['id'])))
            return self.hlrl_records

    def add_hlrl_record(self, *args, **kwargs):
        if len(args) == 1 and isinstance(args[0], HLRL):
            self.hlrl_records.append(args[0])
        else:
            self.hlrl_records.append(HLRL(*args, **kwargs))

    def clear_hlrl_records(self):
        self.hlrl_records.clear()

    def send(self, hlrl: Union[HLRL, list] = None) -> dict:
        # Determine data to send based on input
        if hlrl is None:
            data_to_send = self.hlrl_records
        elif isinstance(hlrl, list):
            data_to_send = hlrl
        elif isinstance(hlrl, HLRL):
            data_to_send = [hlrl]
        else:
            data_to_send = []

        results = Response(self.proceed('hlr', 'create', method='POST', data=data_to_send))

        # Update each sent record with its result and convert ID to int if present
        for idx, res in enumerate(results['result']):
            if idx < len(data_to_send):
                data_to_send[idx]['result'] = res
                if 'id' in res and res['id'] is not None:
                    res['id'] = int(res['id'])
        return results

