# Reimplementation of context managers for async database connections and transactions

import asyncio
from collections.abc import Coroutine
from .log import logger

class _AsyncContextManagerBase(Coroutine):
    __slots__ = ('_coro', '_resource')

    def __init__(self, coro):
        self._coro = coro
        self._resource = None

    def send(self, value):
        return self._coro.send(value)

    def throw(self, typ, val=None, tb=None):
        if val is None:
            return self._coro.throw(typ)
        elif tb is None:
            return self._coro.throw(typ, val)
        else:
            return self._coro.throw(typ, val, tb)

    def close(self):
        return self._coro.close()

    @property
    def gi_frame(self):
        return self._coro.gi_frame

    @property
    def gi_running(self):
        return self._coro.gi_running

    @property
    def gi_code(self):
        return self._coro.gi_code

    def __next__(self):
        return self.send(None)

    def __iter__(self):
        return self._coro.__await__()

    def __await__(self):
        return self._coro.__await__()

    async def __aenter__(self):
        self._resource = await self._coro
        return self._resource

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        if hasattr(self._resource, 'close'):
            await self._resource.close()
        self._resource = None


class _ConnectionContextManager(_AsyncContextManagerBase):
    async def __aexit__(self, exc_type, exc_val, exc_tb):
        if exc_type is not None:
            self._resource.close()
        else:
            await self._resource.ensure_closed()
        self._resource = None


class _PoolContextManager(_AsyncContextManagerBase):
    async def __aexit__(self, exc_type, exc_val, exc_tb):
        self._resource.close()
        await self._resource.wait_closed()
        self._resource = None


class _SAConnectionContextManager(_AsyncContextManagerBase):
    async def __aiter__(self):
        result = await self._coro
        return result


class _TransactionContextManager(_AsyncContextManagerBase):
    async def __aexit__(self, exc_type, exc_val, exc_tb):
        if exc_type:
            await self._resource.rollback()
        else:
            if self._resource.is_active:
                await self._resource.commit()
        self._resource = None


class _PoolAcquireContextManager:
    __slots__ = ('_coro', '_connection', '_pool')

    def __init__(self, coro, pool):
        self._coro = coro
        self._connection = None
        self._pool = pool

    async def __aenter__(self):
        self._connection = await self._coro
        return self._connection

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        try:
            await self._pool.release(self._connection)
        finally:
            self._pool = None
            self._connection = None


class _PoolConnectionContextManager:
    """Context manager for pool-based connection handling.

    Enables safe usage patterns like:
        with (yield from pool) as conn:
            cur = yield from conn.cursor()

    While preventing unsafe usage such as:
        with pool:
            <block>
    """
    __slots__ = ('_pool', '_connection')

    def __init__(self, pool, conn):
        self._pool = pool
        self._connection = conn

    def __enter__(self):
        assert self._connection
        return self._connection

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self._pool.release(self._connection)
        finally:
            self._pool = None
            self._connection = None

    async def __aenter__(self):
        assert not self._connection
        self._connection = await self._pool.acquire()
        return self._connection

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        try:
            await self._pool.release(self._connection)
        finally:
            self._pool = None
            self._connection = None


class TaskTransactionContextManager:
    __task_storage = dict()
    __slots__ = (
        '_coro', '_connection', '_pool', '_counter', 
        '_callback_list', '__transaction_started', 
        '__committed', '__rolled_back'
    )

    def __init__(self, coro, pool):
        self._coro = coro
        self._connection = None
        self._pool = pool
        self._counter = 0
        self._callback_list = list()

        task = asyncio.Task.current_task()
        if task in self.__task_storage:
            raise Exception('task already registered in storage')

        self.__task_storage[task] = self
        self.__transaction_started = False
        self.__committed = False
        self.__rolled_back = False

    @classmethod
    def create(cls, coro, pool) -> 'TaskTransactionContextManager':
        task = asyncio.Task.current_task()
        if task in cls.__task_storage:
            return cls.__task_storage[task]
        return TaskTransactionContextManager(coro, pool)

    @classmethod
    def get_transaction_context_manager(cls, task=None) -> 'TaskTransactionContextManager':
        if not task:
            task = asyncio.Task.current_task()
        return cls.__task_storage.get(task)

    def add_callback_on_commit(self, callback_func, **kwargs):
        self._callback_list.append((callback_func, kwargs))

    async def start_transaction(self):
        if not self.__transaction_started:
            await self._connection.begin()
            self.__transaction_started = True

    async def commit_changes(self):
        if self._counter <= 1:
            await self._connection.commit()

            for callback_func, kwargs in self._callback_list:
                try:
                    if asyncio.iscoroutine(callback_func):
                        await callback_func(**kwargs)
                    else:
                        callback_func(**kwargs)
                except Exception as e:
                    logger.exception(e)

            self._callback_list.clear()
            self.__committed = True

    async def rollback_transaction(self):
        await self._connection.rollback()
        self._callback_list.clear()
        self.__rolled_back = True

    async def __aenter__(self):
        self._counter += 1
        if not self._connection:
            self._connection = await self._coro
        return TransactionConnection(self._connection)

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        self._counter -= 1
        if self._counter <= 0:
            if (self.__transaction_started and 
                not self.__committed and 
                not self.__rolled_back):
                if not exc_type:
                    logger.warning('SQL operation was not committed. Attempting automatic commit via TaskTransactionContextManager')
                    await self.commit_changes()

            self.__task_storage.pop(asyncio.Task.current_task(), None)
            try:
                await self._pool.release(self._connection)
            finally:
                self._pool = None
                self._connection = None
                self.__transaction_started = False
                self.__committed = False
                self.__rolled_back = False


class TransactionConnection:
    def __init__(self, conn):
        self.__connection = conn

    def __str__(self):
        return f'TransactionConnection {str(self.__connection)}'

    async def begin(self):
        """Begin a new transaction."""
        tm = TaskTransactionContextManager.get_transaction_context_manager()
        if tm:
            await tm.start_transaction()
        else:
            await self.__connection.begin()

    async def commit(self):
        """Commit current transaction to stable storage."""
        tm = TaskTransactionContextManager.get_transaction_context_manager()
        if tm:
            await tm.commit_changes()
        else:
            await self.__connection.commit()

    async def rollback(self):
        """Roll back the current transaction."""
        tm = TaskTransactionContextManager.get_transaction_context_manager()
        if tm:
            await tm.rollback_transaction()
        else:
            await self.__connection.rollback()

    def __getattr__(self, item):
        return getattr(self.__connection, item)

    @property
    def underlying_connection(self):
        return self.__connection

# Reimplementation of FontManager with equivalent functionality but different structure and logic

import os
import random
from functools import lru_cache
from pathlib import Path
from typing import List, Set, Tuple, Dict
from PIL import ImageFont
from fontTools.ttLib import TTFont, TTCollection
from loguru import logger
from text_renderer.utils.errors import PanicError
from text_renderer.utils.utils import load_chars_file


class FontHandler:
    def __init__(
        self,
        directory: Path,
        list_path: Path,
        size_range: Tuple[int, int],
    ):
        if size_range[0] >= size_range[1]:
            raise ValueError("Minimum font size must be less than maximum font size")

        self.min_size = size_range[0]
        self.max_size = size_range[1]
        self.font_files: List[str] = []
        self.char_coverage: Dict[str, Set[str]] = {}
        self.filtered_char_coverage: Dict[str, Set[str]] = {}

        # Load font list
        try:
            with open(str(list_path), "r", encoding="utf-8") as f:
                font_lines = [line.strip() for line in f.readlines()]
        except Exception as e:
            raise PanicError(f"Failed to read font list file {list_path}: {e}")

        if not font_lines:
            raise PanicError(f"Font list file is empty: {list_path}")

        for rel_path in font_lines:
            full_path = directory / rel_path
            if not full_path.exists():
                raise PanicError(f"Font file does not exist: {full_path}")
            self.font_files.append(str(full_path))

        self._scan_font_characters()

    def select_random_font(self) -> Tuple[ImageFont.FreeTypeFont, Set[str], str]:
        selected_path = random.choice(self.font_files)
        chosen_size = random.randint(self.min_size, self.max_size)
        loaded_font = self._load_freetype_font(selected_path, chosen_size)
        char_set = self.char_coverage.get(selected_path, set())
        return loaded_font, char_set, selected_path

    def validate_text(self, content: str, allowed_chars: Set[str]) -> Tuple[bool, Set[str]]:
        missing = set(content) - allowed_chars
        return len(missing) == 0, missing

    def _scan_font_characters(self):
        for font_path in self.font_files:
            ttf_obj = self._open_font_file(font_path)
