def redirect_all_output(log_file):
    try:
        # Preserve original file descriptors
        original_stdout = os.dup(sys.stdout.fileno())
        original_stderr = os.dup(sys.stderr.fileno())

        # Set up tee process for output redirection
        tee_process = subprocess.Popen(
            ["tee", log_file], 
            stdin=subprocess.PIPE
        )

        # Redirect both stdout and stderr to tee
        os.dup2(tee_process.stdin.fileno(), sys.stdout.fileno())
        os.dup2(tee_process.stdin.fileno(), sys.stderr.fileno())

        yield
    finally:
        # Restore original file descriptors
        os.dup2(original_stdout, sys.stdout.fileno())
        os.dup2(original_stderr, sys.stderr.fileno())

        # Clean up resources
        tee_process.stdin.close()
        os.close(original_stdout)
