        self, extra_flags=[], hardening_flags=[], shell_format=False, target_arch=None
    ):
        return self.get_tool_flags(
            "CFLAGS", extra_flags, hardening_flags, shell_format, target_arch
        )

    def get_cxxflags(
        self, extra_flags=[], hardening_flags=[], shell_format=False, target_arch=None
    ):
        return self.get_tool_flags(
            "CXXFLAGS", extra_flags, hardening_flags, shell_format, target_arch
        )

    def get_fortran_flags(
        self, extra_flags=[], hardening_flags=[], shell_format=False, target_arch=None
    ):
        return self.get_tool_flags(
            "FFLAGS", extra_flags, hardening_flags, shell_format, target_arch
        )

    def get_linker_flags(
        self, extra_flags=[], hardening_flags=[], shell_format=False, target_arch=None
    ):
        return self.get_tool_flags(
            "LDFLAGS", extra_flags, hardening_flags, shell_format, target_arch
        )

    def get_compiler_tool(self, tool_name, target_arch=None):
        if tool_name not in self.tools:
            return None

        target_profile = get_profile_for_package(self, target_arch)

        if tool_name in cross_compilation_tools and target_profile.cross:
            if not self.pkgname.endswith("-cross"):
                return f"{target_profile.short_triplet}-{self.tools[tool_name]}"

        return self.tools[tool_name]

    def supports_security_feature(self, feature_name, target_arch=None):
        target_profile = get_profile_for_package(self, target_arch)
        return target_profile.has_hardening(feature_name, self.hardening)

    @contextlib.contextmanager
    def set_profile(self, target_arch):
        previous_profile = self.build_profile

        if self.bootstrapping and (target_arch == "host" or target_arch == "target"):
            target_arch = "bootstrap"
        elif target_arch == "host":
            target_arch = chroot.host_cpu()
        elif target_arch == "target":
            target_arch = chroot.target_cpu()

        try:
            self.build_profile = profile.get_profile(target_arch)
            yield
        finally:
            self.build_profile = previous_profile

    def install_files_to(self, source_path, dest_path, follow_links=True):
        source_path = pathlib.Path(source_path)
        dest_path = pathlib.Path(dest_path)

        if dest_path.is_absolute():
            self.logger.out_red(f"install_files: path '{dest_path}' must not be absolute")
            raise PackageException()

        if source_path.is_absolute():
            self.logger.out_red(f"path '{source_path}' must not be absolute")
            raise PackageException()

        source_full = self.cwd / source_path
        dest_full = self.destdir / dest_path / source_path.name

        shutil.copytree(source_full, dest_full, symlinks=follow_links)

    def install_directory(self, *dirs):
        for dir_name in dirs:
            dir_path = pathlib.Path(dir_name)
            if dir_path.is_absolute():
                self.logger.out_red(f"path '{dir_path}' must not be absolute")
                raise PackageException()

            dir_full = self.destdir / dir_path
            if not dir_full.is_dir():
                self.log_message(f"creating path: {dir_full}")
                dir_full.mkdir(parents=True)

    def install_single_file(self, src_file, dest_dir, file_mode=0o644, file_name=None):
        src_path = pathlib.Path(src_file)
        dest_path = pathlib.Path(dest_dir)

        if dest_path.is_absolute():
            self.logger.out_red(f"install_file: path '{dest_path}' must not be absolute")
            raise PackageException()

        if file_name is None:
            file_name = src_path.name

        dest_full = self.destdir / dest_path / file_name

        if dest_full.exists():
            self.logger.out_red(f"install_file: destination file '{dest_full}' already exists")
            raise PackageException()

        self.install_directory(dest_path)
        shutil.copy2(self.cwd / src_path, dest_full)

        if file_mode is not None:
            dest_full.chmod(file_mode)

    def install_binary(self, *binaries):
        self.install_directory("usr/bin")
        for bin_name in binaries:
            src_path = self.cwd / bin_name
            dest_path = self.destdir / "usr/bin"
            self.log_message(f"copying (755): {src_path} -> {dest_path}")
            shutil.copy2(src_path, dest_path)
            (dest_path / src_path.name).chmod(0o755)

    def install_library(self, *libraries):
        self.install_directory("usr/lib")
        for lib_name in libraries:
            src_path = self.cwd / lib_name
            dest_path = self.destdir / "usr/lib"
            self.log_message(f"copying (755): {src_path} -> {dest_path}")
            shutil.copy2(src_path, dest_path)
            (dest_path / src_path.name).chmod(0o755)

    def install_manpage(self, *man_pages):
        self.install_directory("usr/share/man")
        man_base = self.destdir / "usr/share/man"

        for man_page in man_pages:
            abs_man = self.cwd / man_page
            man_filename = abs_man.name
            man_extension = abs_man.suffix

            if len(man_extension) == 0:
                self.logger.out_red(f"manpage '{man_filename}' has no section")
                raise PackageException()

            try:
                man_section = int(man_extension[1:])
            except:
                self.logger.out_red(f"manpage '{man_filename}' has an invalid section")
                raise PackageException()

            man_dir = man_base / f"man{man_section}"
            man_dir.mkdir(parents=True, exist_ok=True)
            self.log_message(f"copying (644): {abs_man} -> {man_dir}")
            shutil.copy2(abs_man, man_dir)
            (man_dir / man_filename).chmod(0o644)

    def install_license_file(self, *licenses):
        self.install_directory("usr/share/licenses/" + self.pkgname)
        for license_file in licenses:
            src_path = self.cwd / license_file
            dest_path = self.destdir / "usr/share/licenses" / self.pkgname
            self.log_message(f"copying (644): {src_path} -> {dest_path}")
            shutil.copy2(src_path, dest_path)
            (dest_path / src_path.name).chmod(0o644)

    def create_symlink(self, target, link_name):
        link_path = pathlib.Path(link_name)
        if link_path.is_absolute():
            self.logger.out_red(f"path '{link_path}' must not be absolute")
            raise PackageException()

        full_link = self.destdir / link_path
        self.log_message(f"symlinking: {target} -> {full_link}")
        full_link.symlink_to(target)

class Subpackage(PackageBase):
    def __init__(self, name, parent_pkg):
        super().__init__()
        self.pkgname = name
        self.parent = parent_pkg
        self.rparent = parent_pkg

        # Copy subpackage fields from parent
        for attr_name, default_val, attr_type, required, subpkg, inheritable in core_attributes:
            if not subpkg:
                continue
            if inheritable:
                setattr(self, attr_name, clone_default_value(getattr(parent_pkg, attr_name)))
            else:
                setattr(self, attr_name, clone_default_value(default_val))

        # Copy build style fields
        for attr_name, default_val, attr_type, subpkg, inheritable in parent_pkg.build_style_fields:
            if not subpkg:
                continue
            if inheritable:
                setattr(self, attr_name, clone_default_value(getattr(parent_pkg, attr_name)))
            else:
                setattr(self, attr_name, clone_default_value(default_val))

        self.force_mode = parent_pkg.force_mode
        self.bootstrapping = parent_pkg.bootstrapping

    def extract_files(self, pattern, missing_ok=False):
        path_obj = pathlib.Path(pattern)
        if path_obj.is_absolute():
            self.logger.out_red(f"path '{path_obj}' must not be absolute")
            raise PackageException()

        orig_path = self.parent.destdir / path_obj
        matches = glob.glob(str(orig_path))

        if len(matches) == 0 and not missing_ok:
            self.logger.out_red(f"path '{pattern}' did not match anything")
            raise PackageException()

        for full_path in matches:
            parent_dest = self.parent.destdir
            self.log_message(f"moving: {full_path} -> {self.destdir}")
            _move_subdirectory(
                pathlib.Path(full_path).relative_to(parent_dest), self.destdir, parent_dest
            )

def _create_subpackage_installer(subpkg_list):
    def actual_installation():
        for item in subpkg_list:
            self.extract_files(item)
    return actual_installation

def load_template_from_module(module_handle, template_instance):
    # Fill mandatory fields first
    for attr_name, default_val, attr_type, required, subpkg, inheritable in core_attributes:
        if not required:
            break
        if hasattr(module_handle, attr_name):
            setattr(template_instance, attr_name, getattr(module_handle, attr_name))

    # Basic validation
    template_instance.validate_required_fields()
    template_instance.validate_version_format()

    # Fill non-mandatory core fields
    for attr_name, default_val, attr_type, required, subpkg, inheritable in core_attributes:
        if required:
            continue
        if hasattr(module_handle, attr_name):
            attr_value = getattr(module_handle, attr_name)
            if attr_type and not isinstance(attr_value, attr_type):
                template_instance.report_error(f"invalid field value: {attr_name}")
            setattr(template_instance, attr_name, attr_value)

    # Process options
    processed_options = {}
    for opt_name, opt_tuple in default_options_map.items():
        processed_options[opt_name] = opt_tuple[0]

    if template_instance.options:
        for option in template_instance.options:
            negated = option.startswith("!")
            if negated:
                option = option[1:]
            if option not in processed_options:
                template_instance.report_error(f"unknown option: {option}")
            processed_options[option] = not negated

    template_instance.options = processed_options
    template_instance.wrksrc = f"{template_instance.pkgname}-{template_instance.pkgver}"
    template_instance.validate_architecture()

    # Set job count based on parallel option
    if not template_instance.options["parallel"]:
        template_instance.make_jobs = 1
    else:
        template_instance.make_jobs = template_instance.conf_jobs

    template_instance.build_style_fields = []
    template_instance.build_style_defaults = []

    if template_instance.build_style:
        importlib.import_module(f"cbuild.build_style.{template_instance.build_style}").use(template_instance)

    # Initialize custom methods
    if hasattr(module_handle, "init"):
        module_handle.init(template_instance)

    # Handle build-style specific fields
    for attr_name, default_val, attr_type, subpkg, inheritable in template_instance.build_style_fields:
        if not hasattr(module_handle, attr_name):
            setattr(template_instance, attr_name, clone_default_value(default_val))
            continue
        attr_value = getattr(module_handle, attr_name)
        if attr_type and not isinstance(attr_value, attr_type):
            template_instance.report_error(f"invalid field value: {attr_name}")
        setattr(template_instance, attr_name, attr_value)

    # Apply build-style defaults
    for attr_name, default_val in template_instance.build_style_defaults:
        if not hasattr(module_handle, attr_name):
            setattr(template_instance, attr_name, clone_default_value(default_val))

    # Add phase methods from module
    for phase in ["fetch", "patch", "extract", "configure", "build", "check", "install"]:
        if hasattr(module_handle, "init_" + phase):
            setattr(template_instance, "init_" + phase, getattr(module_handle, "init_" + phase))
        if hasattr(module_handle, "pre_" + phase):
            setattr(template_instance, "pre_" + phase, getattr(module_handle, "pre_" + phase))
        if hasattr(module_handle, "do_" + phase):
            setattr(template_instance, "do_" + phase, getattr(module_handle, "do_" + phase))
        if hasattr(module_handle, "post_" + phase):
            setattr(template_instance, "post_" + phase, getattr(module_handle, "post_" + phase))

    # Handle pre_pkg
    if hasattr(module_handle, "pre_pkg"):
        template_instance.pre_pkg = module_handle.pre_pkg

    # Set up paths
    template_instance.files_path = template_instance.template_path / "files"
    template_instance.patches_path = template_instance.template_path / "patches"
    template_instance.builddir = paths.bldroot() / "builddir"
    template_instance.statedir = template_instance.builddir / (".cbuild-" + template_instance.pkgname)
    template_instance.wrapperdir = template_instance.statedir / "wrappers"

    if template_instance.build_profile.cross:
        template_instance.destdir_base = paths.bldroot() / "destdir" / template_instance.build_profile.triplet
    else:
        template_instance.destdir_base = paths.bldroot() / "destdir"

    template_instance.destdir = template_instance.destdir_base / f"{template_instance.pkgname}-{template_instance.pkgver}"
    template_instance.cwd = template_instance.builddir / template_instance.wrksrc / template_instance.build_wrksrc

