import numpy as np
from scipy import optimize
import logging

logger = logging.getLogger('optimization.traders')

class StochasticLiquidityTrader:
    def __init__(self, beta, p, seed=None):
        self._beta = beta
        self._p = p
        self.seed(seed=seed)

    def get_swap(self, pool, rng=None):
        if rng is None:
            rng = self._rng

        # Generate random trade size from exponential distribution
        trade_amounts = rng.exponential(self._beta)

        # Randomly choose direction: 1 for token0->token1, -1 for token1->token0
        direction = rng.choice([1, -1], p=[self._p, 1 - self._p])

        # Calculate net trade value
        net_trade = trade_amounts * direction

        # Determine which token is being swapped in
        input_token = 1 if net_trade > 0 else 0

        # Calculate amount of tokens being swapped in
        if net_trade > 0:
            tokens_in = net_trade
        else:
            tokens_in = abs(net_trade) / pool.price

        return input_token, tokens_in

    def seed(self, seed=None):
        self._rng = np.random.default_rng(seed)


