class Arbitrageur:
    def __init__(self):
        self.trades = {}
        self.total_profit = 0

    def get_swap(self, pool, true_price):
        raise NotImplementedError

    def calc_profit(self, delta_x, delta_y, conversion_price, save=True):
        # Profit calculation in token1 (numeraire asset)
        profit = 0

        if (delta_y > 0 and delta_x < 0):
            # Buying token0, selling token1
            profit = (-delta_x) * conversion_price - delta_y
        elif (delta_y < 0 and delta_x > 0):
            # Selling token0, buying token1
            profit = (-delta_y) - delta_x * conversion_price
        else:
            raise ValueError('Trade deltas must have opposite signs.')

        if save:
            self.trades[(delta_x, delta_y)] = profit
            self.total_profit += profit

        return profit


class Uniswapv3Arbitrageur(Arbitrageur):
    @staticmethod
    def _dy(q1, q0, alpha, beta):
        return alpha * (q1 - q0) + (beta / 2) * (q1 ** 2 - q0 ** 2)

    @staticmethod
    def _q1(dy, q0, alpha, beta):
        discriminant = (alpha + beta * q0) ** 2 + 2 * beta * dy
        return (-alpha + np.sqrt(discriminant)) / beta

    @staticmethod
    def _dx(dy, q0, q1):
        return -dy / (q1 * q0)

    def get_swap(self, pool, true_price):
        # No arbitrage opportunity if prices match
        if abs(pool.price - true_price) < 1e-12:
            return None, None

        m = true_price
        q0 = pool.sqrt_price
        gamma = pool.fee

        # Calculate secant line parameters between current liquidity and true price
        liquidity_at_m = pool.liquidity_curve(m)
        liquidity_at_q0 = pool.liquidity_curve(q0 ** 2)

        slope = (liquidity_at_m - liquidity_at_q0) / (m ** 0.5 - q0)
        intercept = liquidity_at_q0 - slope * q0

        alpha = intercept
        beta = slope

        # Handle constant liquidity case (beta ≈ 0)
        if abs(beta) < 1e-12:
            x, y = pool.virtual_reserves
            k = alpha ** 2

            if m > pool.price:
                dy = np.sqrt(k * m * (1 - gamma)) - y
                dx = np.sqrt(k) / np.sqrt(m * (1 - gamma)) - x
                if dy <= 1e-12:
                    return None, None
            else:
                dy = np.sqrt(k * m) / np.sqrt(1 - gamma) - y
                dx = np.sqrt(k * (1 - gamma)) / np.sqrt(m) - x
                if dx <= 1e-12:
                    return None, None
        else:
            def objective_function(dy_arr, m_val, q0_val, gamma_val, alpha_val, beta_val):
                dy = dy_arr[0]
                q1 = self._q1(dy, q0_val, alpha_val, beta_val)
                dx = self._dx(dy, q0_val, q1)

                # Maximize profit (minimize negative profit)
                if m_val > q0_val ** 2:
                    # Price increasing: fees paid in token1
                    return -((-dx) * m_val - dy / (1 - gamma_val))
                else:
                    # Price decreasing: fees paid in token0
                    return -((-dy) - dx * m_val / (1 - gamma_val))

            # Initial guess for dy
            init_dy = self._dy(np.sqrt(m), q0, alpha, beta)

            # Set constraint based on price direction
            if m > pool.price:
                constraint = {'type': 'ineq', 'fun': lambda x: x}
            else:
                constraint = {'type': 'ineq', 'fun': lambda x: -x}

            # Perform optimization
            res = optimize.minimize(
                objective_function,
                np.array([init_dy]),
                args=(m, q0, gamma, alpha, beta),
                constraints=constraint
            )

            # Check optimization success
            if not res.success:
                logger.warning('Optimization failed. Returning None, None.')
                return None, None

            # Check if profitable
            if -res.fun <= 0:
                return None, None

            dy = res.x[0]
            q1 = self._q1(dy, q0, alpha, beta)
            dx = self._dx(dy, q0, q1)

            # Skip negligible trades
            if abs(dy) <= 1e-12 or abs(dx) <= 1e-12:
                return None, None

        # Determine input token and amount
        token = 1 if dy > 0 else 0
        tokens_in = dy if dy > 0 else dx
        tokens_in = tokens_in / (1 - gamma)

        return token, tokens_in


class Uniswapv2Arbitrageur(Arbitrageur):
    def get_swap(self, pool, true_price):
        # No arbitrage opportunity if prices match
        if abs(pool.price - true_price) < 1e-12:
