# Type III Clone: GPOSUnparser with renamed variables, restructured logic, and equivalent functionality

from .GTableUnparser import GTableUnparser
import fontFeatures

class GPOSUnparser(GTableUnparser):
    _table = "GPOS"

    # Lookup type mapping (unchanged semantics)
    lookup_kinds = {
        1: "SinglePositioning",
        2: "PairPositioning",
        3: "CursiveAttachment",
        4: "MarkToBase",
        5: "MarkToLigature",
        6: "MarkToMark",
        7: "Contextual",
        8: "ChainedContextual",
        9: "Extension",
    }

    # Attribute name mappings (renamed keys for clarity)
    _field_map = {
        "lookup": "PosLookupRecord",
        "format1_ruleset": "PosRuleSet",
        "format1_rule": "PosRule",
        "format2_classset": "PosClassSet",
        "format2_rule": "PosClassRule",
        "chain_format1_ruleset": "ChainPosRuleSet",
        "chain_format1_rule": "ChainPosRule",
        "chain_format2_classset": "ChainPosClassSet",
        "chain_format2_rule": "ChainPosClassRule",
    }

    def makeValueRecord(self, valueRec, fmt):
        # Value format flags (same meaning, reordered and slightly renamed)
        flag_defs = (
            ("XPlacement", 0x0001),   # Horizontal placement adjustment
            ("YPlacement", 0x0002),   # Vertical placement adjustment  
            ("XAdvance", 0x0004),     # Horizontal advance adjustment
            ("YAdvance", 0x0008),     # Vertical advance adjustment
            ("XPlaDevice", 0x0010),   # Horizontal device table for placement
            ("YPlaDevice", 0x0020),   # Vertical device table for placement
            ("XAdvDevice", 0x0040),   # Horizontal device table for advance
            ("YAdvDevice", 0x0080)    # Vertical device table for advance
        )

        # Extract values using getattr; default to None if missing or zero
        extracted_values = []
        for attr_name, _ in flag_defs:
            val = getattr(valueRec, attr_name, 0)
            extracted_values.append(val if val else None)

        return fontFeatures.ValueRecord(*extracted_values)

    def is_chaining_lookup(self, lookup_type):
        return lookup_type >= 7

    def collect_dependencies(self, lookup):
        dependencies = []

        if lookup.LookupType == 9:  # Extension lookup
            for ext_subtable in lookup.SubTable:
                sub_lookup_type = ext_subtable.ExtSubTable.LookupType
                if self.is_chaining_lookup(sub_lookup_type):
                    dependencies.extend(self.collect_dependencies(ext_subtable.ExtSubTable))
                else:
                    return []  # Early exit for non-chaining extension subtables
        elif hasattr(lookup, "SubTable"):
            for subtable in lookup.SubTable:
                dependencies.extend(self._collect_chaining_deps(subtable))
        else:
            dependencies.extend(self._collect_chaining_deps(lookup))

        return set(dependencies)

    def _collect_chaining_deps(self, subtable):
        deps = []

        # Handle class-based lookups (Format 2)
        if hasattr(subtable, "ChainPosClassSet") or hasattr(subtable, "PosClassSet"):
            rulesets = subtable.ChainPosClassSet if hasattr(subtable, "ChainPosClassSet") else subtable.PosClassSet

            for idx, ruleset in enumerate(rulesets):
                if not ruleset:
                    continue

                rule_list = (ruleset.ChainPosClassRule 
                            if hasattr(ruleset, "ChainPosClassRule") 
                            else ruleset.PosClassRule)

                for rule in rule_list:
                    for record in rule.PosLookupRecord:
                        deps.append(record.LookupListIndex)

        # Handle single context rules (Format 1)
        elif hasattr(subtable, "PosRuleSet"):
            for ruleset, input_glyph in zip(subtable.PosRuleSet, subtable.Coverage.glyphs):
                for rule in ruleset.PosRule:
                    for record in rule.PosLookupRecord:
                        deps.append(record.LookupListIndex)

        # Handle direct lookup records
        elif hasattr(subtable, "PosLookupRecord"):
            for record in subtable.PosLookupRecord:
                deps.append(record.LookupListIndex)

        return deps

    def unparseSinglePositioning(self, lookup):
        routine = fontFeatures.Routine(name=self.getname("SinglePositioning" + self.gensym()))
        self._fix_flags(routine, lookup)

        for subtable in lookup.SubTable:
            if subtable.Format == 1:
                pos_spec = fontFeatures.Positioning(
                    [subtable.Coverage.glyphs],
                    [self.makeValueRecord(subtable.Value, subtable.ValueFormat)],
                    address=self.currentLookup,
                    flags=lookup.LookupFlag,
                )
                routine.addRule(pos_spec)
            else:
                # Process each glyph individually for Format 2
                for glyph, value in zip(subtable.Coverage.glyphs, subtable.Value):
                    pos_spec = fontFeatures.Positioning(
                        [[glyph]], 
                        [self.makeValueRecord(value, subtable.ValueFormat)],
                        address=self.currentLookup,
                        flags=lookup.LookupFlag,
                    )
                    routine.addRule(pos_spec)

        return routine, []

    def unparsePairPositioning(self, lookup):
        routine = fontFeatures.Routine(name=self.getname("PairPositioning" + self.gensym()))
        self._fix_flags(routine, lookup)

        for subtable in lookup.SubTable:
            if subtable.Format == 1:
                # PairSet format - iterate through pairs
                for glyph, pair_set in zip(subtable.Coverage.glyphs, subtable.PairSet):
                    for pair_record in pair_set.PairValueRecord:
                        pos_spec = fontFeatures.Positioning(
                            [[glyph], [pair_record.SecondGlyph]],
                            [
                                self.makeValueRecord(pair_record.Value1, subtable.ValueFormat1),
                                self.makeValueRecord(pair_record.Value2, subtable.ValueFormat2),
                            ],
                            address=self.currentLookup,
                            flags=lookup.LookupFlag,
                        )
                        routine.addRule(pos_spec)
            else:
                # Class-based format
                cls1 = self._invertClassDef(subtable.ClassDef1.classDefs, self.font)
                cls2 = self._invertClassDef(subtable.ClassDef2.classDefs, self.font)

                for idx1, class1_items in enumerate(subtable.Class1Record):
                    if idx1 not in cls1:
                        continue

                    for idx2, class2_rec in enumerate(class1_items.Class2Record):
                        if idx2 not in cls2:
                            continue

                        vr1 = self.makeValueRecord(class2_rec.Value1, subtable.ValueFormat1)
                        vr2 = self.makeValueRecord(class2_rec.Value2, subtable.ValueFormat2)

                        if not vr1 and not vr2:
                            continue

                        first_class = list(set(cls1[idx1]) & set(subtable.Coverage.glyphs))
                        pos_spec = fontFeatures.Positioning(
                            [first_class, cls2[idx2]], [vr1, vr2],
                            address=self.currentLookup,
                            flags=lookup.LookupFlag,
                        )
                        routine.addRule(pos_spec)

        return routine, []

    def unparseCursiveAttachment(self, lookup):
        routine = fontFeatures.Routine(name=self.getname("CursiveAttachment" + self.gensym()))
        self._fix_flags(routine, lookup)

        entry_anchors = {}
        exit_anchors = {}

        for st in lookup.SubTable:
            assert st.Format == 1
            for glyph, record in zip(st.Coverage.glyphs, st.EntryExitRecord):
                if record.EntryAnchor:
                    entry_anchors[glyph] = (
                        record.EntryAnchor.XCoordinate,
                        record.EntryAnchor.YCoordinate,
                    )
                if record.ExitAnchor:
                    exit_anchors[glyph] = (
                        record.ExitAnchor.XCoordinate,
                        record.ExitAnchor.YCoordinate,
                    )

        routine.addRule(
            fontFeatures.Attachment(
                "cursive_entry", "cursive_exit", entry_anchors, exit_anchors,
                flags=lookup.LookupFlag,
                address=self.currentLookup
            )
        )
        return routine, []

    def unparseMarkToBase(self, lookup):
        routine = fontFeatures.Routine(name=self.getname("MarkToBase" + self.gensym()))
        self._fix_flags(routine, lookup)

        for subtable in lookup.SubTable:
            assert subtable.Format == 1
            for class_id in range(0, subtable.ClassCount):
                anchor_prefix = "Anchor" + self.gensym()
                marks = self._process_mark_array(
                    subtable.MarkArray, subtable.MarkCoverage, class_id
                )
                bases = self._process_base_array(
                    subtable.BaseArray, subtable.BaseCoverage, class_id
                )

                routine.addRule(
                    fontFeatures.Attachment(
                        anchor_prefix, anchor_prefix + "_", bases, marks,
                        font=self.font,
                        address=self.currentLookup,
                        flags=lookup.LookupFlag,
                    )
                )
        return routine, []

    def _process_mark_array(self, mark_array, coverage, class_id):
        glyph_names = coverage.glyphs
        marks = {}

        for i, record in enumerate(mark_array.MarkRecord):
            if record.Class == class_id:
                marks[glyph_names[i]] = (
                    record.MarkAnchor.XCoordinate,
                    record.MarkAnchor.YCoordinate,
                    record.Class
                )
        return marks

    def _process_mark2_array(self, mark_array, coverage, prefix):
        glyph_names = coverage.glyphs
        marks = {}

        for i, record in enumerate(mark_array.Mark2Record):
            if len(record.Mark2Anchor) != 1:
                continue
            marks[glyph_names[i]] = (
                record.Mark2Anchor[0].XCoordinate,
                record.Mark2Anchor[0].YCoordinate,
            )
        return marks

    def _process_base_array(self, base_array, coverage, target_class):
        glyph_names = coverage.glyphs
        bases = {}

        for i, record in enumerate(base_array.BaseRecord):
            for class_id, anchor in enumerate(record.BaseAnchor):
                if class_id != target_class:
                    continue
                if not anchor:
                    continue
                bases[glyph_names[i]] = (anchor.XCoordinate, anchor.YCoordinate)
        return bases

    def unparseMarkToLigature(self, lookup):
        routine = fontFeatures.Routine(name=self.getname("MarkToLigature" + self.gensym()))
        self._fix_flags(routine, lookup)
        self.unparsable(routine, "Mark to lig pos", lookup)
        return routine, []

    def unparseMarkToMark(self, lookup):
        routine = fontFeatures.Routine(name=self.getname("MarkToMark" + self.gensym()))
        self._fix_flags(routine, lookup)

        for subtable in lookup.SubTable:
            assert subtable.Format == 1
            anchor_prefix = "Anchor" + self.gensym()

            marks = self._process_mark_array(
                subtable.Mark1Array, subtable.Mark1Coverage, anchor_prefix
            )
            bases = self._process_mark2_array(
                subtable.Mark2Array, subtable.Mark2Coverage, anchor_prefix
            )

            routine.addRule(
                fontFeatures.Attachment(
                    anchor_prefix, anchor_prefix + "_", bases, marks,
                    font=self.font,
                    address=self.currentLookup,
                    flags=lookup.LookupFlag,
                )
            )
        return routine, []

