# -*- coding: utf-8 -*-
from __future__ import absolute_import, unicode_literals

from fabric.api import roles, parallel, sudo, env
from fabric.context_managers import cd

from ..const import (
    ROLES_STATIC,
    ROLES_DJANGO,
    ROLES_ALL_SRC,
    ROLES_CELERY,
    ROLES_STATIC_PRIMARY,
)


def _get_active_venv(use_current=False):
    return env.virtualenv_current if use_current else env.virtualenv_root


def _get_active_code_path(use_current=False):
    return env.code_current if use_current else env.code_root


def _run_manage_command(cmd, venv=None, code_path=None, use_current=False):
    venv = venv or _get_active_venv(use_current)
    code_path = code_path or _get_active_code_path(use_current)
    with cd(code_path):
        sudo(f'{venv}/bin/python manage.py {cmd}')


@roles(set(ROLES_STATIC) | set(ROLES_DJANGO))
@parallel
def version_static():
    """
    Embeds versioning info in static asset references to bust browser caches.
    Must execute on web workers — they serve the actual static files.
    """
    _run_manage_command('resource_static')


@parallel
@roles(set(ROLES_STATIC) | set(ROLES_DJANGO) | set(ROLES_CELERY))
def yarn_install():
    with cd(_get_active_code_path()):
        sudo('yarn install --production')


@parallel
@roles(set(ROLES_STATIC) | set(ROLES_DJANGO))
def collectstatic(use_current_release=False):
    """
    Gathers static assets post-deployment.
    Required on web workers due to their role in serving static content.
    """
    venv = _get_active_venv(use_current_release)
    code_path = _get_active_code_path(use_current_release)

    with cd(code_path):
        if not use_current_release:
            sudo('rm -rf staticfiles')
        _run_manage_command('collectstatic --noinput -v 0', venv=venv, code_path=code_path)
        _run_manage_command('fix_less_imports_collectstatic', venv=venv, code_path=code_path)
        _run_manage_command('compilejsi18n', venv=venv, code_path=code_path)
        _run_manage_command('build_requirejs', venv=venv, code_path=code_path)


@parallel
@roles(ROLES_STATIC_PRIMARY)
def compress(use_current_release=False):
    """Applies compression via Django Compressor after deployment."""
    venv = _get_active_venv(use_current_release)
    code_path = _get_active_code_path(use_current_release)

    with cd(code_path):
        _run_manage_command('compress --force -v 0', venv=venv, code_path=code_path)
        _run_manage_command('purge_compressed_files', venv=venv, code_path=code_path)
    push_manifest(use_current_release=use_current_release)


def push_manifest(use_current_release=False):
    if getattr(env, 'use_shared_dir_for_staticfiles', False):
        code_path = _get_active_code_path(use_current_release)
        git_hash = sudo('git rev-parse HEAD').strip()
        shared_path = f"{env.shared_dir_for_staticfiles}/{git_hash}"

        with cd(code_path):
            sudo(f'mkdir -p {shared_path}')
            sudo(
                "rsync -r --delete "
                "--include='staticfiles/' --include='CACHE/' "
                "--include='staticfiles/CACHE/**' --exclude='*' "
                f". {shared_path}"
            )
    else:
        update_manifest(save=True, use_current_release=use_current_release)


@roles(ROLES_DJANGO)
@parallel
def pull_manifest(use_current_release=False):
    if getattr(env, 'use_shared_dir_for_staticfiles', False):
        code_path = _get_active_code_path(use_current_release)
        git_hash = sudo('git rev-parse HEAD').strip()
        shared_path = f"{env.shared_dir_for_staticfiles}/{git_hash}"

        with cd(code_path):
            sudo('mkdir -p staticfiles/CACHE/')
            sudo(f'cp {shared_path}/staticfiles/CACHE/manifest.json staticfiles/CACHE/manifest.json')
    else:
        update_manifest(save=False, soft=False, use_current_release=use_current_release)


@roles(ROLES_STATIC)
@parallel
def pull_staticfiles_cache(use_current_release=False):
    if getattr(env, 'use_shared_dir_for_staticfiles', False):
        code_path = _get_active_code_path(use_current_release)
        git_hash = sudo('git rev-parse HEAD').strip()
        shared_path = f"{env.shared_dir_for_staticfiles}/{git_hash}"

        with cd(code_path):
            sudo('mkdir -p staticfiles/CACHE/')
            sudo(f'rsync -r --delete {shared_path}/staticfiles/CACHE/ staticfiles/CACHE/')


def update_manifest(save=False, soft=False, use_current_release=False):
    """
    Synchronizes compressed asset manifest between Redis and filesystem.
    save=True → writes manifest to Redis; otherwise reads from Redis.
    """
    venv = _get_active_venv(use_current_release)
    code_path = _get_active_code_path(use_current_release)

    args_parts = []
    if save:
        args_parts.append('save')
    if soft:
        args_parts.append('soft')

    cmd_suffix = ' ' + ' '.join(args_parts) if args_parts else ''
    with cd(code_path):
        sudo(f'{venv}/bin/python manage.py update_manifest{cmd_suffix}')


@roles(ROLES_ALL_SRC)
@parallel
def update_translations():
    with cd(_get_active_code_path()):
        sudo(f'{env.virtualenv_root}/bin/python manage.py update_django_locales')
        sudo(f'{env.virtualenv_root}/bin/python manage.py compilemessages -v 0')

