logger = ometa_logger()
TOKEN_KEY = "access_token"
EXPIRY_SECONDS = "expires_in"

class TokenRetrievalError(Exception):
    """
    Exception raised when token acquisition fails from the identity provider
    """

@dataclass(init=False)  # type: ignore[misc]
class SecurityTokenProvider(metaclass=ABCMeta):
    """
    Abstract base class defining the contract for security token management
    """
    @classmethod
    @abstractmethod
    def build(cls, settings: ConfigModel) -> "SecurityTokenProvider":
        """
        Factory method to instantiate appropriate provider based on configuration
        Arguments:
            settings (ConfigModel): authentication configuration details
        Returns:
            SecurityTokenProvider instance
        """

    @abstractmethod
    def obtain_token(self) -> str:
        """
        Retrieve the authentication token
        Returns:
            str representing the token
        """

    @abstractmethod
    def retrieve_credentials(self):
        """
        Get current token and expiration information
        Returns:
            Tuple[str, int] containing token and expiry time
        """

class NullSecurityProvider(SecurityTokenProvider):
    """
    Placeholder implementation that provides no actual authentication
    Args:
        settings (OpenMetadataConnection): connection configuration
    Attributes:
        config (OpenMetadataConnection): stored configuration
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.config = settings

    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)

    def obtain_token(self):
        # No operation for null provider
        pass

    def retrieve_credentials(self):
        return "no_token", None

class GoogleSecurityProvider(SecurityTokenProvider):
    """
    Google Cloud authentication implementation using service account credentials
    Args:
        settings (OpenMetadataConnection): connection configuration
    Attributes:
        config (OpenMetadataConnection): stored configuration
        security_config (GoogleSSOClientConfig): Google-specific settings
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.config = settings
        self.security_settings: GoogleSSOClientConfig = self.config.securityConfig
        self.token_cache = None
        self.expiry_time = None

    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)

    def obtain_token(self) -> None:
        import google.auth
        import google.auth.transport.requests
        from google.oauth2 import service_account

        creds = service_account.IDTokenCredentials.from_service_account_file(
            self.security_settings.secretKey,
            target_audience=self.security_settings.audience,
        )
        req = google.auth.transport.requests.Request()
        creds.refresh(req)
        self.token_cache = creds.token
        self.expiry_time = creds.expiry

    def retrieve_credentials(self):
        self.obtain_token()
        return self.token_cache, self.expiry_time

class OktaSecurityProvider(SecurityTokenProvider):
    """
    Okta authentication implementation using JWT tokens
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.config = settings
        self.security_settings: OktaSSOClientConfig = self.config.securityConfig
        self.token_cache = None
        self.expiry_time = None

    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)

    async def obtain_token(self) -> None:
        import time
        import uuid
        from urllib.parse import quote, urlencode
        from okta.cache.okta_cache import OktaCache
        from okta.jwt import JWT, jwt
        from okta.request_executor import RequestExecutor

        try:
            pem_key, jwk_key = JWT.get_PEM_JWK(self.security_settings.privateKey)
            current_time = int(time.time())
            token_duration = current_time + JWT.ONE_HOUR
            unique_id = str(uuid.uuid4())

            payload = {
                "sub": self.security_settings.clientId,
                "iat": current_time,
                "exp": token_duration,
                "iss": self.security_settings.clientId,
                "aud": self.security_settings.orgURL,
                "jti": unique_id,
            }

            encoded_jwt = jwt.encode(payload, jwk_key.to_dict(), JWT.HASH_ALGORITHM)

            config = {
                "client": {
                    "orgUrl": self.security_settings.orgURL,
                    "authorizationMode": "BEARER",
                    "rateLimit": {},
                    "privateKey": self.security_settings.privateKey,
                    "clientId": self.security_settings.clientId,
                    "token": encoded_jwt,
                    "scopes": self.security_settings.scopes,
                }
            }

            executor = RequestExecutor(
                config=config, cache=OktaCache(ttl=token_duration, tti=current_time)
            )

            params = {
                "grant_type": "client_credentials",
                "scope": " ".join(config["client"]["scopes"]),
                "client_assertion_type": "urn:ietf:params:oauth:client-assertion-type:jwt-bearer",
                "client_assertion": encoded_jwt,
            }

            encoded_params = urlencode(params, quote_via=quote)
            endpoint_url = f"{self.security_settings.orgURL}?" + encoded_params

            request_obj = await executor.create_request(
                "POST",
                endpoint_url,
                None,
                {
                    "Accept": "application/json",
                    "Content-Type": "application/x-www-form-urlencoded",
                },
                oauth=True,
            )

            _, response_meta, response_body, error = await executor.fire_request(
                request_obj[0]
            )

            if error:
                raise APIError(f"{error}")

            result = json.loads(response_body)
            access_token = result.get(TOKEN_KEY)

            if not access_token:
                raise TokenRetrievalError(
                    f"Failed to obtain access token: {result}"
                )

            self.token_cache = access_token
            self.expiry_time = result.get(EXPIRY_SECONDS)

        except Exception as exception:
            logger.debug(traceback.print_exc())
            logger.error(exception)
            sys.exit()

    def retrieve_credentials(self):
        import asyncio
        asyncio.run(self.obtain_token())
        return self.token_cache, self.expiry_time

class Auth0SecurityProvider(SecurityTokenProvider):
    """
    Auth0 authentication implementation using OAuth client credentials
    Args:
        settings (OpenMetadataConnection): connection configuration
    Attributes:
        config (OpenMetadataConnection): stored configuration
        security_settings (Auth0SSOClientConfig): Auth0-specific settings
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.config = settings
        self.security_settings: Auth0SSOClientConfig = self.config.securityConfig
        self.token_cache = None
        self.expiry_time = None

    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)

    def obtain_token(self) -> None:
        connection = http.client.HTTPSConnection(self.security_settings.domain)

        form_data = (
            f"grant_type=client_credentials&client_id={self.security_settings.clientId}"
            f"&client_secret={self.security_settings.secretKey}&audience=https://{self.security_settings.domain}/api/v2/"
        )

        headers = {"content-type": "application/x-www-form-urlencoded"}

        connection.request(
            "POST", f"/{self.security_settings.domain}/oauth/token", form_data, headers
        )

        response = connection.getresponse()
        response_data = json.loads(response.read().decode("utf-8"))

        access_token = response_data.get(TOKEN_KEY)

        if not access_token:
            raise TokenRetrievalError(f"Token request failed: {response_data}")

        self.token_cache = access_token
        self.expiry_time = response_data[EXPIRY_SECONDS]

    def retrieve_credentials(self):
        self.obtain_token()
        return self.token_cache, self.expiry_time

class AzureSecurityProvider(SecurityTokenProvider):
    """
    Microsoft Azure Active Directory authentication implementation
    """
    def __init__(self, settings: OpenMetadataConnection):
        self.config = settings
        self.security_settings: AzureSSOConfig = self.config.securityConfig
        self.token_cache = None
        self.expiry_time = None

    @classmethod
    def build(cls, settings: OpenMetadataConnection):
        return cls(settings)

    def obtain_token(self) -> None:
        from msal import (
            ConfidentialClientApplication,
        )

        app = ConfidentialClientApplication(
            client_id=self.security_settings.clientId,
            client_credential=self.security_settings.clientSecret,
            authority=self.security_settings.authority,
        )

        result = app.acquire_token_for_client(scopes=self.security_settings.scopes)

        access_token = result.get(TOKEN_KEY)

        if not access_token:
            raise TokenRetrievalError(f"Token acquisition failed: {result}")

        self.token_cache = access_token
        self.expiry_time = result.get(EXPIRY_SECONDS)

    def retrieve_credentials(self):
        self.obtain_token()
        return self.token_cache, self.expiry_time

class CustomOIDCSecurityProvider(SecurityTokenProvider):
    """
    Custom OIDC authentication implementation supporting any OIDC-compliant provider
    Args:
        settings (OpenMetadataConnection): connection configuration
    Attributes:
        config (OpenMetadataConnection): stored configuration
        security_settings (CustomOIDCSSOClientConfig): custom OIDC settings
    """
    def __init__(self, settings: OpenMetadataConnection) -> None:
        self.config = settings
        self.security_settings: CustomOIDCSSOClientConfig = self.config.securityConfig
        self.token_cache = None
        self.expiry_time = None

    @classmethod
    def build(
        cls, settings: OpenMetadataConnection
    ) -> "CustomOIDCSecurityProvider":
        return cls(settings)

    def obtain_token(self) -> None:
        payload = {
            "grant_type": "client_credentials",
            "client_id": self.security_settings.clientId,
            "client_secret": self.security_settings.secretKey,
        }

        response = requests.post(
            url=self.security_settings.tokenEndpoint,
            data=payload,
        )

        if response.ok:
            response_json = response.json()
            access_token = response_json.get(TOKEN_KEY)

            if not access_token:
                raise TokenRetrievalError(
                    f"Token request failed: {response_json}"
                )

            self.token_cache = access_token
            self.expiry_time = response_json.get(EXPIRY_SECONDS)
        else:
            raise APIError(
                error={"message": response.text}, http_error=response.status_code
            )

    def retrieve_credentials(self) -> Tuple[str, int]:
        self.obtain_token()
        return self.token_cache, self.expiry_time

