from dataclasses import dataclass
from functools import reduce
from typing import List, Tuple

from pants.engine.console import Console
from pants.engine.goal import Goal, GoalSubsystem
from pants.engine.isolated_process import FallibleExecuteProcessResult
from pants.engine.legacy.graph import HydratedTargets
from pants.engine.legacy.structs import TargetAdaptor
from pants.engine.objects import Collection, union
from pants.engine.rules import UnionMembership, goal_rule
from pants.engine.selectors import Get, MultiGet


@dataclass(frozen=True)
class LintOutcome:
    code: int
    out: str
    err: str

    @staticmethod
    def empty() -> "LintOutcome":
        return LintOutcome(code=0, out="", err="")

    @staticmethod
    def from_result(process_result: FallibleExecuteProcessResult) -> "LintOutcome":
        return LintOutcome(
            code=process_result.exit_code,
            out=process_result.stdout.decode(),
            err=process_result.stderr.decode(),
        )


class LintOutcomes(Collection[LintOutcome]):
    """Aggregates linting results per language."""
    pass


@union
class LintableTarget:
    """Union marker for types that can be linted."""

    @staticmethod
    def qualifies(
        adaptor: TargetAdaptor,
        *,
        union_membership: UnionMembership,
    ) -> bool:
        # Check union membership and presence of non-empty sources
        has_union = union_membership.is_member(LintableTarget, adaptor)
        has_sources = hasattr(adaptor, "sources") and adaptor.sources.snapshot.files
        return has_union and has_sources


class LintOptions(GoalSubsystem):
    """Subsystems defines options for linting."""
    name = 'lint2'
    required_union_implementations = (LintableTarget,)


class Lint(Goal):
    subsystem_cls = LintOptions


async def _collect_lint_results(
    targets: HydratedTargets,
    union_membership: UnionMembership,
) -> List[LintOutcome]:
    # Filter lintable targets first
    lintable_adaptors = [
        t.adaptor for t in targets if LintableTarget.qualifies(t.adaptor, union_membership=union_membership)
    ]

    # Fetch lint results concurrently
    lint_result_collections = await MultiGet(
        Get[LintOutcomes](LintableTarget, adaptor)
        for adaptor in lintable_adaptors
    )

    # Flatten nested collections
    flattened = []
    for collection in lint_result_collections:
        flattened.extend(collection)
    return flattened


async def _report_and_aggregate(
    console: Console,
    outcomes: List[LintOutcome],
) -> int:
    # Use reduce to compute final exit code (non-zero overrides zero)
    def update_exit_code(acc: int, outcome: LintOutcome) -> int:
        return acc or outcome.code

    final_code = reduce(update_exit_code, outcomes, 0)

    # Output each result’s stdout/stderr
    for outcome in outcomes:
        if outcome.out:
            console.print_stdout(outcome.out)
        if outcome.err:
            console.print_stderr(outcome.err)

    return final_code


@goal_rule
async def run_lint(
    console: Console,
    targets: HydratedTargets,
    union_membership: UnionMembership,
) -> Lint:
    outcomes = await _collect_lint_results(targets, union_membership)

    if not outcomes:
        return Lint(exit_code=0)

    final_exit_code = await _report_and_aggregate(console, outcomes)
    return Lint(exit_code=final_exit_code)


def rules():
    return [
        run_lint,
    ]

# Reimplementation of Metadata Outer Puzzle logic with equivalent functionality
# but using different variable names, control flow, and helper structures

from dataclasses import dataclass
from typing import Any, List, Optional, Tuple
from clvm_tools.binutils import disassemble
from chinilla.types.blockchain_format.coin import Coin
from chinilla.types.blockchain_format.program import Program
from chinilla.types.blockchain_format.sized_bytes import bytes32
from chinilla.util.ints import uint64
from chinilla.wallet.puzzle_drivers import PuzzleInfo, Solver
from chinilla.wallet.puzzles.load_clvm import load_clvm

# Load the NFT state layer module once at startup
NFT_STATE_LAYER_PROGRAM = load_clvm("nft_state_layer.clvm")
NFT_STATE_LAYER_HASH = NFT_STATE_LAYER_PROGRAM.get_tree_hash()


def is_metadata_puzzle(puzzle: Program) -> Tuple[bool, List[Program]]:
    """Check if a puzzle matches the metadata layer structure."""
    try:
        mod, args = puzzle.uncurry()
        if mod == NFT_STATE_LAYER_PROGRAM:
            return True, list(args.as_iter())
    except Exception:
        pass
    return False, []


def build_metadata_puzzle(metadata: Program, updater_id: bytes32, base_puzzle: Program) -> Program:
    """Construct a metadata layer puzzle from its components."""
    return NFT_STATE_LAYER_PROGRAM.curry(
        NFT_STATE_LAYER_HASH,
        metadata,
        updater_id,
        base_puzzle,
    )


def wrap_inner_solution(inner_solution: Program, coin_value: uint64) -> Program:
    """Create a solution wrapper containing inner solution and coin amount."""
    return Program.to([inner_solution, coin_value])


@dataclass(frozen=True)
class MetadataLayerDriver:
    """Driver class for handling metadata-layer puzzles."""

    # Internal handlers for nested puzzle solving
    _match_handler: Any
    _asset_identifier: Any
    _constructor_handler: Any
    _solver_handler: Any
    _inner_puzzle_extractor: Any
    _inner_solution_extractor: Any

    def analyze_puzzle(self, puzzle: Program) -> Optional[PuzzleInfo]:
        """Analyze a puzzle reveal to determine if it's a metadata layer."""
        matched, curried_parts = is_metadata_puzzle(puzzle)

        if not matched:
            return None

        # Extract components from curried arguments
        _, metadata, updater_id, base_puzzle = curried_parts

        # Build constructor dictionary
        constructor_info = {
            "type": "metadata",
            "metadata": disassemble(metadata),
            "updater_hash": "0x" + updater_id.as_python().hex(),
        }

        # Check for nested puzzle layers
        nested_constructor = self._match_handler(base_puzzle)
        if nested_constructor is not None:
            constructor_info["also"] = nested_constructor.info

        return PuzzleInfo(constructor_info)

    def derive_asset_id(self, constructor: PuzzleInfo) -> Optional[bytes32]:
        """Extract asset identifier (updater hash) from constructor info."""
        return bytes32(constructor["updater_hash"])

    def assemble_puzzle(self, constructor: PuzzleInfo, base_puzzle: Program) -> Program:
        """Build a complete puzzle from constructor info and inner puzzle."""
        if constructor.also() is not None:
            base_puzzle = self._constructor_handler(constructor.also(), base_puzzle)

        return build_metadata_puzzle(
            constructor["metadata"],
            constructor["updater_hash"],
            base_puzzle,
        )

    def extract_base_puzzle(self, constructor: PuzzleInfo, puzzle_reveal: Program) -> Optional[Program]:
        """Extract the inner/base puzzle from a metadata layer puzzle."""
        matched, curried_parts = is_metadata_puzzle(puzzle_reveal)

        if not matched:
            raise ValueError("This driver cannot process the specified puzzle reveal")

        _, _, _, base_puzzle = curried_parts

        if constructor.also() is not None:
            deeper_puzzle = self._inner_puzzle_extractor(constructor.also(), base_puzzle)
            return deeper_puzzle

        return base_puzzle

    def extract_base_solution(self, constructor: PuzzleInfo, solution: Program) -> Optional[Program]:
        """Extract the inner solution from a metadata layer solution."""
        inner_solution = solution.first()

        if constructor.also():
            deeper_solution = self._inner_solution_extractor(constructor.also(), inner_solution)
            return deeper_solution

        return inner_solution

    def prepare_solution(self, constructor: PuzzleInfo, solver_data: Solver, 
                        base_puzzle: Program, base_solution: Program) -> Program:
        """Generate a complete solution for the metadata layer."""
        # Parse coin information from solver data
        coin_data = solver_data["coin"]
        coin = Coin(
            bytes32(coin_data[0:32]),
            bytes32(coin_data[32:64]),
            uint64.from_bytes(coin_data[64:72])
        )

        # Handle nested puzzle solutions
        if constructor.also() is not None:
            base_solution = self._solver_handler(constructor.also(), solver_data, base_puzzle, base_solution)

        # Wrap with metadata layer solution format
        return wrap_inner_solution(base_solution, coin.amount)

# Specular water shader implementation — Type III Clone

SpecularShaderV2 = Shader(
    language=Shader.GLSL,
    vertex="""
#version 150
uniform mat4 p3d_ModelViewProjectionMatrix;
uniform mat4 p3d_ProjectionMatrix;
uniform mat4 p3d_ModelMatrix;
uniform mat4 p3d_ViewMatrix;
uniform sampler2D p3d_Texture0;
uniform mat3 p3d_NormalMatrix;
uniform vec3 lightPos;
uniform vec3 cameraPos;
uniform sampler2D heightMap;
uniform vec2 uvOffsetA;
uniform vec2 uvOffsetB;
uniform sampler2D normalMap;

in vec2 p3d_MultiTexCoord0;
in vec4 vertex;
in vec4 normal;

out vec3 vectorToLight;
out vec3 vectorToCamera;
out vec2 texcoord;
out float alpha;

void main() {
    vec2 baseCoord = p3d_MultiTexCoord0 + uvOffsetA;
    vec2 secCoord = p3d_MultiTexCoord0 + uvOffsetB;

    float hgt1 = texture(heightMap, baseCoord).r * 50.0;
    float hgt2 = texture(heightMap, secCoord).r * 50.0;

    float displacement = (hgt1 + hgt2) * 0.5;
    gl_Position = p3d_ModelViewProjectionMatrix * vec4(vertex.x, vertex.y + displacement, vertex.z, vertex.w);

    vec3 worldPos = (p3d_ModelMatrix * vertex).xyz;
    vectorToLight = lightPos - worldPos;
    vec4 camWorld = inverse(p3d_ViewMatrix) * vec4(0.0, 0.0, 0.0, 1.0);
    vectorToCamera = camWorld.xyz - worldPos;

    texcoord = baseCoord * 12.0;
    alpha = hgt1 / 40.0;
    alpha -= sin(dot(vectorToCamera, vec3(0.0, 1.0, 0.0))) / 180.0;
    alpha = max(alpha, 0.1);
    alpha += 0.1;
}
""",
    fragment="""
#version 140
uniform vec3 lightColor;
uniform float Damper;
uniform float reflectivity;
uniform sampler2D p3d_Texture0;
uniform sampler2D normalMap;
uniform mat3 p3d_NormalMatrix;

in vec3 vectorToLight;
in vec3 vectorToCamera;
in vec2 texcoord;
in float alpha;

out vec4 out_color;

void main() {
    vec3 rawNormal = texture(normalMap, texcoord).rgb;
    vec3 surfaceNormal = normalize(p3d_NormalMatrix * rawNormal);

    vec4 baseColor = texture(p3d_Texture0, texcoord);
    vec4 tintedColor = vec4(0.0, 0.0, baseColor.b, baseColor.a);

    vec3 unitToLight = normalize(vectorToLight);
    vec3 unitToCamera = normalize(vectorToCamera);
    vec3 lightDirection = -unitToLight;

    float diffuseFactor = max(dot(surfaceNormal, lightDirection), 0.2);
    vec3 diffuseComponent = diffuseFactor * lightColor;

    vec3 reflected = reflect(lightDirection, surfaceNormal);
    float specRaw = dot(reflected, unitToCamera);
    float specTerm = pow(max(specRaw, 0.0), Damper);
    vec3 specular = specTerm * reflectivity * lightColor;

    vec4 finalColor = vec4(diffuseComponent, 1.0) * tintedColor + vec4(specular, 1.0);
    out_color = vec4(finalColor.rgb, 1.0);
}
"""
)

class WaterSurface(Entity):
    def __init__(self, elevation, grid_size):
        super().__init__()
        self.shader = SpecularShaderV2
        self.elevation = elevation
        self.grid_dimension = grid_size
        self.mesh_data = self._generate_water_mesh()
        self.model = Mesh(**self.mesh_data)

        # Set initial shader parameters
        self.set_shader_input("cameraPos", Vec3(0, 0, 0))
        self.set_shader_input("lightPos", Vec3(3, 10, 2))

    def _generate_water_mesh(self):
        vertices = []
        triangles = []
        uvs = []

        idx_map = {}

        for x in range(self.grid_dimension):
            for z in range(self.grid_dimension):
                v0 = Vec3(x, self.elevation, z)
                v1 = Vec3(x + 1, self.elevation, z)
                v2 = Vec3(x + 1, self.elevation, z + 1)
                v3 = Vec3(x, self.elevation, z + 1)

                base_idx = len(vertices)
                vertices.extend([v0, v1, v2, v3])

                triangles.append((base_idx, base_idx + 1, base_idx + 2))
                triangles.append((base_idx, base_idx + 2, base_idx + 3))

                # UV mapping normalized per tile
                uv_base = Vec2(x / self.grid_dimension, z / self.grid_dimension)
                uv_step = 1.0 / self.grid_dimension
                uvs.extend([
                    uv_base,
                    Vec2(uv_base.x + uv_step, uv_base.y),
                    Vec2(uv_base.x + uv_step, uv_base.y + uv_step),
                    Vec2(uv_base.x, uv_base.y + uv_step)
                ])

        return {
            "vertices": vertices,
            "triangles": triangles,
            "uvs": uvs
        }

