from dataclasses import dataclass
from typing import List
from bohr.datamodel.artifact import Artifact


@dataclass
class Method(Artifact):
    _code: str

    @property
    def line_count(self) -> int:
        return len(self._split_lines())

    @property
    def nesting_level(self) -> int:
        return self._compute_nesting()

    def _split_lines(self) -> List[str]:
        """
        >>> Method("public a() {}").line_count
        1
        """
        return self._code.splitlines()

    def _compute_nesting(self) -> int:
        """
        >>> Method("{}}").nesting_level
        Traceback (most recent call last):
        ...
        ValueError: Invalid method text: {}}
        >>> Method("public a() {}").nesting_level
        1
        >>> Method("public a() {if (true) {}}").nesting_level
        2
        """
        current_depth = 0
        deepest_depth = 0
        for symbol in self._code:
            if symbol == '{':
                current_depth += 1
                if current_depth > deepest_depth:
                    deepest_depth = current_depth
            elif symbol == '}':
                current_depth -= 1
            if current_depth < 0:
                raise ValueError(f"Invalid method text: {self._code}")
        return deepest_depth

import sys
import types
import typing as T
from dataclasses import dataclass
from pathlib import Path
from typing_extensions import Never

@dataclass
class MutableBool:
    flag: bool = False

    def update(self, new_value: bool) -> None:
        self.flag = new_value

def load_module_from_file(
    module_name: str,
    file_path: Path,
    code_transform: T.Optional[T.Callable[[bytes], bytes]] = None,
    suppress_traceback: bool = False,
) -> types.ModuleType:
    import importlib.util

    spec = importlib.util.spec_from_file_location(module_name, file_path)
    if not spec or not spec.loader:
        raise TypeError(
            f"Could not locate file loader for {file_path}. This likely indicates an unsupported file extension."
        )

    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module

    try:
        if code_transform is not None:
            original_compile = spec.loader.source_to_code  # type: ignore
            def custom_compile(data: bytes, path: str, *, _optimize: int = -1):
                transformed_data = code_transform(data)
                return original_compile(transformed_data, path, _optimize=_optimize)

            spec.loader.source_to_code = custom_compile  # type: ignore

            saved_dont_write_bytecode = sys.dont_write_bytecode
            sys.dont_write_bytecode = True

            try:
                spec.loader.exec_module(module)
            finally:
                sys.dont_write_bytecode = saved_dont_write_bytecode
                spec.loader.source_to_code = original_compile  # type: ignore
        else:
            spec.loader.exec_module(module)

    except SystemExit as exit_exception:
        raise exit_exception
    except Exception:
        if not suppress_traceback:
            raise

        import traceback
        full_traceback = traceback.format_exc()

        if "_call_with_frames_removed\n" in full_traceback:
            frame_removed_marker = "_call_with_frames_removed\n"
            marker_index = full_traceback.find(frame_removed_marker)
            trimmed_traceback = (
                "Traceback (most recent call last):\n"
                + full_traceback[marker_index + len(frame_removed_marker):]
            )
        else:
            trimmed_traceback = full_traceback

        sys.stderr.write(trimmed_traceback)
        raise

def __trigger_exception__(error: BaseException) -> Never:
    raise error

