        # Alternative implementation for text color calculation
        try:
            # Extract RGB values using different method
            hex_color = self.backdrop_color.lstrip('#') if self.backdrop_color else 'FFFFFF'
            rgb_background_color = tuple(int(hex_color[i:i+2], 16) / 255.0 for i in (0, 2, 4))

            white = (1.0, 1.0, 1.0)
            contrast_with_white = contrast.rgb(rgb_background_color, white)

            if contrast.passes_AA(contrast_with_white, large=True):
                return 'white'
            else:
                return 'grey'
