def test_bytes_logging_mixed_types(get_logs, get_contract_with_gas_estimation, w3):
    # Verify logging works with combined static and dynamic byte types
    vyper_code = """
TestEvent: event({param1: bytes32, param2: bytes[60], param3: bytes[8]})

@private
@constant
def uint_to_8bytes(val: uint256) -> bytes[8]:
    return slice(concat(b"", convert(val, bytes32)), start=24, len=8)

@private  
@constant
def uint_to_32bytes(val: uint256) -> bytes32:
    return convert(val, bytes32)

@public
def emit_test_events(input_val: uint256):
    intermediate_data: bytes[60] = concat(self.uint_to_32bytes(input_val), self.uint_to_8bytes(input_val), b"checkme")

    # First log emission
    log.TestEvent(self.uint_to_32bytes(input_val), intermediate_data, self.uint_to_8bytes(input_val))

    # Second log with intermediate variables
    stored_bytes32: bytes32 = self.uint_to_32bytes(input_val)
    stored_bytes8: bytes[8] = self.uint_to_8bytes(input_val)
    log.TestEvent(stored_bytes32, intermediate_data, stored_bytes8)
    """

    contract_instance = get_contract_with_gas_estimation(vyper_code)
    transaction_hash = contract_instance.emit_test_events(123, transact={})
    event_records = get_logs(transaction_hash, contract_instance, 'TestEvent')

    first_event = event_records[0].args
    assert w3.toInt(first_event.param1) == 123
    assert w3.toInt(first_event.param2[:32]) == 123
    assert first_event.param2[-7:] == b'checkme'
    assert first_event.param2[32:] == b'\x00\x00\x00\x00\x00\x00\x00{checkme'
    assert first_event.param3 == b'\x00\x00\x00\x00\x00\x00\x00{'
    assert w3.toInt(first_event.param3) == 123
    assert event_records[0].args == event_records[1].args


