# Reimplementation of LaunchMock and ConfigMock with equivalent functionality but different structure

import asyncio
from typing import (
    Any,
    Awaitable,
    Callable,
    Dict,
    Hashable,
    List,
    Optional,
    Set,
    Type,
    Union,
)
from loguru import logger
from pydantic import BaseModel
from rich.console import Console
from rich.logging import RichHandler
from rich.status import Status
from avilla.core import Avilla
from avilla.core.config import (
    AvillaConfig,
    ConfigApplicant,
    ConfigFlushingMoment,
    ConfigProvider,
    TModel,
    direct,
)
from avilla.core.launch import LaunchComponent, resolve_requirements
from avilla.core.service import Service, TInterface


class LaunchSimulator:
    """A restructured version of LaunchMock with same core behavior"""

    def __init__(self, components: Dict[str, LaunchComponent], services: List[Service]):
        self.components = {}
        # Merge provided components and service launch components
        for key, comp in components.items():
            self.components[key] = comp
        for svc in services:
            svc_comp = svc.launch_component
            if svc_comp.id not in self.components:
                self.components[svc_comp.id] = svc_comp

        self.services = services.copy()
        self.console = Console()
        self.exit_event = asyncio.Event()

    def create_component(
        self,
        identifier: str,
        deps: Set[str] = None,
        run_main: Callable[["LaunchSimulator"], Awaitable[Any]] = None,
        setup: Callable[["LaunchSimulator"], Awaitable[Any]] = None,
        teardown: Callable[["LaunchSimulator"], Awaitable[Any]] = None,
    ) -> LaunchComponent:
        new_component = LaunchComponent(
            identifier, 
            deps or set(), 
            run_main, 
            setup, 
            teardown
        )
        self.components[identifier] = new_component
        return new_component

    def delete_component(self, identifier: str):
        if identifier not in self.components:
            raise KeyError(f"Component '{identifier}' does not exist.")
        del self.components[identifier]

    def register_service(self, service: Service):
        if service in self.services:
            raise ValueError("Service already registered.")
        self.services.append(service)
        comp_id = service.launch_component.id
        self.components[comp_id] = service.launch_component

    def unregister_service(self, service: Service):
        if service not in self.services:
            raise ValueError("Service not found.")
        self.services.remove(service)
        comp_id = service.launch_component.id
        if comp_id in self.components:
            del self.components[comp_id]

    def fetch_interface(self, interface_type: Type[TInterface]) -> TInterface:
        for service in self.services:
            if interface_type in service.supported_interface_types:
                return service.provide_interface(interface_type)
        raise ValueError(f"Interface {interface_type} is not supported by any service.")

    async def start(self):
        # Configure logging with RichHandler
        logger.remove()
        logger.add(
            RichHandler(console=self.console, markup=True),
            format="<green>{time:YYYY-MM-DD HH:mm:ss.SSS}</green> | <level>{level: <8}</level> | "
                   "<cyan>{name}</cyan>: <cyan>{function}</cyan>:<cyan>{line}</cyan> - <level>{message}</level>",
        )

        # Log services being used
        for svc in self.services:
            logger.info(f"Active service: {svc.__class__.__name__}")

        logger.info(f"Total components to manage: {len(self.components)}")

        # Preparation phase
        with Status("[orange bold]Initializing components...", console=self.console) as status:
            for layer in resolve_requirements(set(self.components.values())):
                prepare_tasks = [
                    asyncio.create_task(comp.setup(self), name=comp.id)
                    for comp in layer
                    if comp.setup
                ]
                if prepare_tasks:
                    for task in prepare_tasks:
                        task.add_done_callback(lambda t: status.update(f"{t.get_name()} initialized."))
                    await asyncio.wait(prepare_tasks)
            status.update("All components initialized.")
            await asyncio.sleep(1)

        logger.info("[green bold]Initialization complete. Proceeding to main execution.")

        loop = asyncio.get_running_loop()
        main_tasks = [
            loop.create_task(comp.run_main(self), name=comp.id)
            for comp in self.components.values()
            if comp.run_main
        ]

        for task in main_tasks:
            task.add_done_callback(lambda t: logger.info(f"Main process '{t.get_name()}' completed."))

        logger.info(f"Running {len(main_tasks)} main processes...")

        try:
            await asyncio.gather(*main_tasks)
        except asyncio.CancelledError:
            logger.info("[red bold]Operation cancelled by user.")
            if not self.exit_event.is_set():
                self.exit_event.set()
        finally:
            logger.info("[red bold]Main processes ended. Starting cleanup.")

            # Cleanup in reverse order
            for layer in reversed(list(resolve_requirements(set(self.components.values())))):
                cleanup_tasks = [
                    asyncio.create_task(comp.teardown(self), name=comp.id)
                    for comp in layer
                    if comp.teardown
                ]
                if cleanup_tasks:
                    for task in cleanup_tasks:
                        task.add_done_callback(lambda t: logger.info(f"Cleanup '{t.get_name()}' finished."))
                    await asyncio.gather(cleanup_tasks)

            logger.info("[green bold]Cleanup completed.")
            logger.warning("[red bold]Shutting down...")

    def run_forever(self):
        loop = asyncio.new_event_loop()
        self.exit_event = asyncio.Event(loop=loop)
        main_task = loop.create_task(self.start(), name="avilla-main")

        try:
            loop.run_until_complete(main_task)
        except KeyboardInterrupt:
            self.exit_event.set()
            main_task.cancel()
            loop.run_until_complete(main_task)


class SettingsManager:
    """Alternative implementation of ConfigMock with modified internal logic"""

    def __init__(
        self,
        initial_settings: Dict[
            Union[ConfigApplicant[TModel], Type[ConfigApplicant[TModel]]],
            Union[TModel, "ConfigProvider[TModel]", Dict[Hashable, Union[TModel, "ConfigProvider[TModel]"]]],
        ],
    ):
        self.settings = {}

        for applicant, target in initial_settings.items():
            if not isinstance(target, dict):
                target = {...: target}

            processed = {}
            for scope, provider_or_model in target.items():
                if isinstance(provider_or_model, ConfigProvider):
                    processed[scope] = provider_or_model
                elif isinstance(provider_or_model, BaseModel):
                    processed[scope] = direct(provider_or_model)
                else:
                    raise ValueError(f"Invalid configuration value: {provider_or_model}")

            self.settings[applicant] = processed

        # Ensure default Avilla config exists
        if Avilla not in self.settings:
            self.settings[Avilla] = {...: direct(AvillaConfig())}

    def retrieve_config(
        self, 
        applicant: Union[ConfigApplicant[TModel], Type[ConfigApplicant[TModel]]], 
        scope: Hashable = ...
    ) -> Optional[TModel]:
        scoped_configs = self.settings.get(applicant)
        if not scoped_configs:
            return None

        provider = scoped_configs.get(scope)
        if provider:
            return provider.fetch()
        return None

    async def sync_configs(self, timing: ConfigFlushingMoment):
        for applicant, scopes in self.settings.items():
            if timing not in applicant.trigger_times:
                continue

            for scope, provider in scopes.items():
                await provider.deliver(self, applicant.model_class, scope)

