"""
A contract for the import linter to secure 3rd-party clients importing.
Wrong::
    import kubernetes
Right::
    try:
        import kubernetes
    except ImportError:
        ...
https://import-linter.readthedocs.io/en/stable/custom_contract_types.html
"""
import os
import ast
from importlinter import Contract, ContractCheck, fields, output

class ConditionalImportContract(Contract):
    """
    Contract that defines a single forbidden import between
    two modules, ensuring they are wrapped in try-except blocks.
    """
    source_modules = fields.ListField(subfield=fields.ModuleField())
    conditional_modules = fields.ListField(subfield=fields.ModuleField())

    def check(self, graph):
        violations = []

        # Filter conditional modules that actually exist in the dependency graph
        existing_conditionals = [m for m in self.conditional_modules if m.name in graph.modules]

        for src_module in self.source_modules:
            for cond_module in existing_conditionals:
                # Find all shortest import chains from source to conditional module
                chains = graph.find_shortest_chains(
                    importer=src_module.name,
                    imported=cond_module.name,
                )

                for chain in chains:
                    # Extract the final import pair (last two modules in chain)
                    importer_name, imported_name = chain[-2:]

                    # Get detailed import information
                    import_details = graph.get_import_details(
                        importer=importer_name,
                        imported=imported_name
                    )

                    # Check each individual import statement
                    for detail in import_details:
                        is_secured = self._verify_import_protection(
                            detail['importer'],
                            detail['line_number']
                        )
                        if not is_secured:
                            violations.append(detail)

        return ContractCheck(
            kept=len(violations) == 0,
            metadata={'violations': violations},
        )

    def render_broken_contract(self, check):
        for violation in check.metadata['violations']:
            importer = violation['importer']
            imported = violation['imported']
            line_no = violation['line_number']
            line_text = violation['line_contents']

            output.print_error(
                f'{importer} must wrap import of {imported} in try-except-ImportError:',
                bold=True,
            )
            output.new_line()
            output.indent_cursor()
            output.print_error(f'{importer}:{line_no}: {line_text}')

    def _verify_import_protection(self, module_path: str, line_num: int) -> bool:
        # Convert module path to file path
        try:
            # Try standard location first
            base_dir = os.path.dirname(__file__)
            file_path = os.path.join(base_dir, module_path.replace('.', '/')) + '.py'

            if not os.path.exists(file_path):
                # Fallback: look for __init__.py in package directory
                init_path = os.path.join(base_dir, module_path.replace('.', '/'), '__init__.py')
                if os.path.exists(init_path):
                    file_path = init_path
                else:
                    return True  # Skip if file not found

            with open(file_path, 'r', encoding='utf-8') as f:
                source_code = f.read()

            # Parse AST to analyze structure
            tree = ast.parse(source_code)

            # Walk through all import nodes and check protection context
            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        # Check if this import matches our target line
                        if hasattr(node, 'lineno') and node.lineno == line_num:
                            # Look for try-except-ImportError wrapper
                            return self._is_in_try_except_importerror(node, tree)

        except Exception:
            # If we can't verify, be conservative and assume not protected
            return False

        return True

    def _is_in_try_except_importerror(self, import_node, tree):
        """Check if an import node is inside a try block with ImportError handler."""
        # Helper to find parent try-except blocks
        class TryFinder(ast.NodeVisitor):
            def __init__(self):
                self.try_blocks = []

            def visit_Try(self, node):
                self.try_blocks.append(node)
                self.generic_visit(node)

        finder = TryFinder()
        finder.visit(tree)

        # Check if import_node is within any try block with ImportError handler
        for try_block in finder.try_blocks:
            if self._node_within_range(import_node, try_block):
                # Check if there's an ImportError handler
                for handler in try_block.handlers:
                    if isinstance(handler.type, ast.Name) and handler.type.id == 'ImportError':
                        return True

        return False

    def _node_within_range(self, node, parent):
        """Check if node is lexically contained within parent node."""
        return (hasattr(parent, 'lineno') and 
                hasattr(parent, 'end_lineno') and
                hasattr(node, 'lineno') and
                parent.lineno <= node.lineno <= (getattr(parent, 'end_lineno', parent.lineno) or parent.lineno))

import json
import os
import subprocess
import sys

def _extract_source_paths(compilation_data):
    for entry in compilation_data:
        yield os.path.join(entry['dir'], entry['file'])

def _fetch_compilation_info(build_flags):
    subprocess.run(['bazel', 'build', '//adlik_serving'] + build_flags + 
                   ['--experimental_action_listener=//ci:ci-action-listener'], check=True)
    output = subprocess.check_output(['ci/tools/build-compilation-database.py'], 
                                     universal_newlines=True)
    return output

def main(argv):
    error_occurred = False
    raw_data = _fetch_compilation_info(argv)
    compilation_entries = json.loads(raw_data)

    for command in compilation_entries:
        result = subprocess.run(['include-what-you-use'] + command['arguments'][1:], 
                                cwd=command['dir'])
        if result.returncode != 2:
            error_occurred = True

    if error_occurred:
        sys.exit(1)

if __name__ == "__main__":
    main(sys.argv[1:])

import datetime
import logging
import uuid
import celery.result
from celery import states

logger = logging.getLogger(__name__)

def _convert_to_serializable(obj):
    if isinstance(obj, datetime.datetime):
        return obj.isoformat()
    elif isinstance(obj, dict):
        return {k: _convert_to_serializable(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [_convert_to_serializable(item) for item in obj]
    elif isinstance(obj, tuple):
        return tuple(_convert_to_serializable(item) for item in obj)
    elif isinstance(obj, set):
        return {_convert_to_serializable(item) for item in obj}
    else:
        return obj

def _get_task_result(task_id):
    return _TaskStorage.fetch_by_identifier(task_id)

# Override AsyncResult to ensure consistent behavior in eager mode
celery.result.AsyncResult = _get_task_result

class _EnhancedEagerResult(celery.result.EagerResult):
    def is_ready(self):
        return self._state in states.READY_STATES

class _TaskStorage:
    __storage = {}

    @classmethod
    def store(cls, result_obj):
        cls.__storage[result_obj.id] = result_obj

    @classmethod
    def fetch_by_identifier(cls, identifier):
        return (
            cls.__storage[identifier]
            if identifier in cls.__storage
            else _EnhancedEagerResult(identifier, None, states.PENDING)
        )

class CeleryEmulator:
    """
    Emulates a Celery application in eager execution mode.
    Intercepts task decorators and ensures tasks execute synchronously while maintaining async semantics.
    """
    def __init__(self, original_app):
        self.__app = original_app
        self.__app.conf.update(
            task_always_eager=True,
            result_backend="cache",
            cache_backend="memory",
            task_eager_propagates=True,
        )
        self.__local_store = {}

    def __getattr__(self, attr_name):
        if attr_name == "task":
            def decorator_interceptor(*args, **kwargs):
                decorated_func = getattr(self.__app, "task")(*args, **kwargs)

                class TaskWrapper:
                    def __init__(self, func_ref):
                        self.__func = func_ref

                    def execute_async(
                        self,
                        args=None,
                        kwargs=None,
                        task_id=None,
                        producer=None,
                        link=None,
                        link_error=None,
                        shadow=None,
                        **extra_options,
                    ):
                        processed_args = (
                            [_convert_to_serializable(arg) for arg in args] if args else ()
                        )
                        processed_kwargs = (
                            {key: _convert_to_serializable(val) for key, val in (kwargs or {}).items()}
                        )

                        final_task_id = task_id or str(uuid.uuid4())

                        try:
                            execution_output = self.__func(*processed_args, **processed_kwargs)
                            eager_result = celery.result.EagerResult(
                                final_task_id, execution_output, states.SUCCESS
                            )
                        except Exception as exc:
                            eager_result = celery.result.EagerResult(
                                final_task_id, exc, states.FAILURE
                            )

                        _TaskStorage.store(eager_result)
                        return eager_result

                    def __call__(self, *args, **kwargs):
                        return self.__func(*args, **kwargs)

                return TaskWrapper(decorated_func.func)
            return decorator_interceptor
        else:
            return getattr(self.__app, attr_name)

# Reimplementation of the rule-matching system with equivalent logic but different structure

from typing import Dict, Tuple, List, Any, Callable, Protocol
import regex

class Matcher(Protocol):
    def try_match(self, text: str, start: int = 0, require_full: bool = False) -> int:
        pass

class LiteralMatcher:
    def __init__(self, literal: str):
        self.literal = literal

    def try_match(self, text: str, start: int = 0, require_full: bool = False) -> int:
        length = len(self.literal)
        if text[start:].startswith(self.literal):
            matched_len = length
            return matched_len if not require_full or start + matched_len == len(text) else 0
        return 0

    def __repr__(self):
        return f"<LiteralMatcher: '{self.literal}'>"

    def __str__(self):
        return self.literal

class SequenceMatcher:
    def __init__(self, matchers: Tuple[Matcher]):
        self.matchers = matchers

    def try_match(self, text: str, start: int = 0, require_full: bool = False) -> int:
        current_pos = start
        for matcher in self.matchers:
            consumed = matcher.try_match(text, current_pos)
            if consumed == 0:
                return 0
            current_pos += consumed
            assert current_pos <= len(text)

        total_consumed = current_pos - start
        return total_consumed if not require_full or current_pos == len(text) else 0

    def __repr__(self):
        return f"<SequenceMatcher: '{self}'>"

    def __str__(self):
        return '+'.join(str(m) for m in self.matchers)

class AlternativeMatcher:
    def __init__(self, options: Tuple[Matcher]):
        self.options = options

    def try_match(self, text: str, start: int = 0, require_full: bool = False) -> int:
        for option in self.options:
            result = option.try_match(text, start, require_full)
            if result != 0:
                return result
        return 0

    def __repr__(self):
        return f"<AlternativeMatcher: '{self}'>"

    def __str__(self):
        return "(" + " | ".join(str(o) for o in self.options) + ")"

def _extract_simple_rule(rule_text: str):
    SIMPLE_PATTERN = r'(\d+): ("[a-z]+")'
    match = regex.match(SIMPLE_PATTERN, rule_text)
    if not match:
        return None

    rule_id = int(match.group(1))
    literal_value = match.group(2)[1:-1]  # Remove quotes
    return rule_id, LiteralMatcher, literal_value

def _extract_complex_rule(rule_text: str):
    COMPLEX_PATTERN = r'(\d+):( \d+)+( \|( \d+)+)?'
    match = regex.match(COMPLEX_PATTERN, rule_text)
    if not match:
        return None

    rule_id = int(match.group(1))
    primary_sequence = tuple(int(x) for x in match.captures(2))

    # Check if there's an alternative sequence
    alt_sequences = match.captures(4)
    if alt_sequences:
        secondary_sequence = tuple(int(x) for x in alt_sequences)
        # Create two alternatives: first sequence and second sequence
        return rule_id, AlternativeMatcher, (primary_sequence, secondary_sequence)
    else:
        return rule_id, SequenceMatcher, primary_sequence

def parse_single_rule(rule_text: str):
    return _extract_simple_rule(rule_text) or _extract_complex_rule(rule_text)

ParsedRuleDict = Dict[int, Tuple[Callable, Any]]

def process_rules(raw_rules: List[str]) -> ParsedRuleDict:
    parsed = [parse_single_rule(r.strip()) for r in raw_rules]
    return {rule_id: (constructor, args) for rule_id, constructor, args in parsed if rule_id is not None}

def construct_matchers(rule_map: ParsedRuleDict) -> Dict[int, Matcher]:
    constructed = {}
    for rid in rule_map:
        _build_matcher(rule_map, constructed, rid)
    return constructed

def _build_matcher(rule_map: ParsedRuleDict, cache: Dict[int, Matcher], rule_id: int):
    if rule_id in cache:
        return cache[rule_id]

    constructor, arguments = rule_map[rule_id]

    if constructor == LiteralMatcher:
        cache[rule_id] = constructor(arguments)
    elif constructor == SequenceMatcher:
        sub_matchers = []
        for sub_id in arguments:
            sub_matchers.append(
                cache[sub_id] if sub_id in cache else _build_matcher(rule_map, cache, sub_id)
            )
        cache[rule_id] = constructor(tuple(sub_matchers))
    else:  # AlternativeMatcher
        alt_constructors = []
        for seq_args in arguments:
            seq_matchers = []
            for sub_id in seq_args:
                seq_matchers.append(
                    cache[sub_id] if sub_id in cache else _build_matcher(rule_map, cache, sub_id)
                )
            alt_constructors.append(SequenceMatcher(tuple(seq_matchers)))
        cache[rule_id] = constructor(tuple(alt_constructors))

    return cache[rule_id]

def main():
    with open("2020/19/input.txt", "r") as file:
        lines = file.readlines()

    # Find separator between rules and test strings
    separator_index = lines.index("\n")
    raw_rules = lines[:separator_index]
    test_strings = [line.rstrip('\n') for line in lines[separator_index + 1:]]

    print(f"# of rules: {len(raw_rules)}")
    print(f"# of test strings: {len(test_strings)}")

    # Process and build matchers
    parsed_rules = process_rules(raw_rules)
    matchers = construct_matchers(parsed_rules)

    # Part 1: Count matches for rule 0
    matching_lines = [s for s in test_strings if matchers[0].try_match(s, 0, True) != 0]

    print("\n".join(matching_lines))
    print(f"Number of lines matching rule #0: {len(matching_lines)}")

if __name__ == "__main__":
    main()

from __future__ import annotations
import logging
from typing import TYPE_CHECKING, Optional, Any
from gaphas.decorators import g_async
from gi.repository import Gtk
from gaphor import UML
from gaphor.core import Transaction, event_handler, gettext
from gaphor.core.format import format as format_value
from gaphor.core.modeling import (
    AttributeUpdated,
    DerivedSet,
    Diagram,
    ElementCreated,
    ElementDeleted,
    ModelFlushed,
    ModelReady,
)
from gaphor.ui.event import Notification

if TYPE_CHECKING:
    from gaphor.core.eventmanager import EventManager
    from gaphor.core.modeling import ElementFactory

log = logging.getLogger(__name__)

# Placeholder node for grouping relationships
class RelationshipGroupMarker:
    label = "0"
    owner = None


def locate_relationship_group(tree_model, parent_iter: Optional[Gtk.TreeIter]) -> Gtk.TreeIter:
    """Find or create the special 'Relationships' group under the given parent."""
    if parent_iter is not None and not isinstance(tree_model.get_value(parent_iter, 0), UML.Package):
        return parent_iter

    child = tree_model.iter_children(parent_iter)
    while child:
        candidate = tree_model.get_value(child, 0)
        if candidate is RelationshipGroupMarker:
            return child
        child = tree_model.iter_next(child)

    return tree_model.append(parent_iter, [RelationshipGroupMarker])


def find_parent_non_group_node(tree_model, iter: Gtk.TreeIter) -> Gtk.TreeIter:
    """Ascend until we reach a non-group node."""
    while tree_model.get_value(iter, 0) is RelationshipGroupMarker:
        iter = tree_model.iter_parent(iter)
    return iter


# Custom events for internal signaling
class TreeRebuilt:
    def __init__(self, model):
        self.model = model


class ItemDroppedEvent:
    def __init__(self, model, item):
        self.model = model
        self.item = item


class ElementTreeStore(Gtk.TreeStore):
    def __init__(self, event_manager: EventManager, element_factory: ElementFactory):
        super().__init__(object)
        self._event_manager = event_manager
        self._element_factory = element_factory
        self._register_handlers()
        self.set_sort_func(0, self._compare_rows, None)
        self.set_sort_column_id(Gtk.TREE_SORTABLE_UNSORTED_SORT_COLUMN_ID, Gtk.SortType.ASCENDING)

    def _register_handlers(self):
        em = self._event_manager
        em.subscribe(self.rebuild_tree)
        em.subscribe(self._handle_new_element)
        em.subscribe(self._handle_removed_element)
        em.subscribe(self._handle_owner_change)
        em.subscribe(self._handle_attribute_update)

    def _unregister_handlers(self):
        em = self._event_manager
        em.unsubscribe(self.rebuild_tree)
        em.unsubscribe(self._handle_new_element)
        em.unsubscribe(self._handle_removed_element)
        em.unsubscribe(self._handle_owner_change)
        em.unsubscribe(self._handle_attribute_update)

    def shutdown(self):
        self._unregister_handlers()

    def get_item_at_iter(self, iter: Gtk.TreeIter) -> Any:
        return self.get_value(iter, 0)

    def find_iter_for_element(self, element: Any, prior_owner: Any = None) -> Optional[Gtk.TreeIter]:
        """Locate the tree iterator corresponding to an element."""
        parent_iter = None
        if prior_owner:
            parent_iter = self.find_iter_for_element(prior_owner)
        elif element and hasattr(element, 'owner') and element.owner:
            parent_iter = self.find_iter_for_element(element.owner)

        if isinstance(element, UML.Relationship):
            parent_iter = locate_relationship_group(self, parent_iter)

        # Linear search among children
        child = self.iter_children(parent_iter)
        while child:
            if self.get_value(child, 0) is element:
                return child
            child = self.iter_next(child)
        return None

    def _is_visible(self, item: Any) -> bool:
        """Check whether an item should appear in the tree."""
        return (
            isinstance(item, (UML.Relationship, UML.NamedElement, Diagram))
            and not isinstance(item, (UML.InstanceSpecification, UML.OccurrenceSpecification))
        )

    def _insert_branch(self, item: Any, parent_iter: Optional[Gtk.TreeIter] = None):
        """Recursively insert an element and its owned elements into the tree."""
        if not self._is_visible(item):
            return

        if isinstance(item, UML.Relationship):
            parent_iter = locate_relationship_group(self, parent_iter)

        new_iter = self.append(parent_iter, [item])
        for sub_item in getattr(item, 'ownedElement', []):
            if getattr(sub_item, 'owner', None) is item:
                self._insert_branch(sub_item, new_iter)

    def _remove_branch(self, iter_to_delete: Optional[Gtk.TreeIter]):
        """Delete a node and clean up empty relationship groups."""
        if not iter_to_delete:
            return

        parent = self.iter_parent(iter_to_delete)
        self.remove(iter_to_delete)

        if (
            parent
            and not self.iter_has_child(parent)
            and self.get_value(parent, 0) is RelationshipGroupMarker
        ):
            self.remove(parent)

    @event_handler(ModelReady, ModelFlushed)
    def rebuild_tree(self, event=None):
        """Fully rebuild the namespace tree."""
        log.debug("Reinitializing element hierarchy view")
        self.clear()
        roots = [
            e for e in self._element_factory.select(lambda x: self._is_visible(x) and not getattr(x, 'owner', None))
        ]
        for root_item in roots:
            self._insert_branch(root_item)
        self._event_manager.handle(TreeRebuilt(self))

    @event_handler(ElementCreated)
    def _handle_new_element(self, event: ElementCreated):
        element = event.element
        if self._is_visible(element) and not self.find_iter_for_element(element):
            parent_iter = self.find_iter_for_element(getattr(element, 'owner', None))
            self._insert_branch(element, parent_iter)

    @event_handler(ElementDeleted)
    def _handle_removed_element(self, event: ElementDeleted):
        element = event.element
        target_iter = self.find_iter_for_element(element)
        self._remove_branch(target_iter)

    @event_handler(DerivedSet)
    def _handle_owner_change(self, event: DerivedSet):
        if event.property is not UML.Element.owner:
            return

        old_owner, new_owner = event.old_value, event.new_value
        element = event.element

        old_iter = self.find_iter_for_element(element, prior_owner=old_owner)
        self._remove_branch(old_iter)

        if self._is_visible(element):
            new_parent_iter = self.find_iter_for_element(new_owner)
            if bool(new_parent_iter) == bool(new_owner):
                self._insert_branch(element, new_parent_iter)

    @event_handler(AttributeUpdated)
    def _handle_attribute_update(self, event: AttributeUpdated):
        """Update UI when relevant attributes change."""
        affected_attrs = {
            UML.Classifier.isAbstract,
            UML.BehavioralFeature.isAbstract,
            UML.Diagram.name,
            UML.NamedElement.name,
        }
        if event.property not in affected_attrs:
            return

        element = event.element
        target_iter = self.find_iter_for_element(element)
        if target_iter:
            path = self.get_path(target_iter)
            self.row_changed(path, target_iter)
            self.sort()

    @g_async(single=True)
    def sort(self):
        """Trigger async re-sorting of the tree."""
        self.set_sort_column_id(Gtk.TREE_SORTABLE_UNSORTED_SORT_COLUMN_ID, Gtk.SortType.ASCENDING)
        self.set_sort_column_id(0, Gtk.SortType.ASCENDING)

    # Drag-and-drop support
    def do_row_draggable(self, path):
        return True

    def do_drag_data_get(self, path, selection_data):
        target_name = str(selection_data.get_target())
        row = self[path]
        item = row[0]

        if target_name == "GTK_TREE_MODEL_ROW":
            return Gtk.tree_set_row_drag_data(selection_data, self, path)
        elif target_name == "gaphor/element-id":
            selection_data.set(selection_data.get_target(), 8, str(item.id).encode())
            return True
        return False

    def do_drag_data_delete(self, path):
        return False

    def do_row_drop_possible(self, dest_path, selection_data):
        source_info = Gtk.tree_get_row_drag_data(selection_data)
        if not source_info:
            return False

        success, src_model, src_path = source_info
        if not success or src_model is not self:
            log.warning("Drag operation from foreign tree model")
            return False

        src_row = self[src_path]
        dragged_item = src_row[0]
        return isinstance(dragged_item, (Diagram, UML.Package, UML.Type))

    def do_drag_data_received(self, dest_path, selection_data):
        if str(selection_data.get_target()) != "GTK_TREE_MODEL_ROW":
            log.warning(f"Unexpected drag data type: {selection_data.get_target()}")
            return False

        ok, src_model, src_path = Gtk.tree_get_row_drag_data(selection_data)
        if not ok or src_model is not self:
            log.debug("Cannot accept DnD from external models")
            return False

        src_row = self[src_path]
        item = src_row[0]

        # Adjust destination path
        dest_path.up()
        if not dest_path:
            target_element = None
        else:
            try:
                dest_iter = self.get_iter(dest_path)
            except ValueError:
                log.debug(f"Invalid drop path: '{dest_path}'")
                return False

            target_element = self.get_value(dest_iter, 0)
            if target_element is RelationshipGroupMarker:
                dest_iter = find_parent_non_group_node(self, dest_iter)
                target_element = self.get_value(dest_iter, 0)

            if item.owner is target_element:
                return False

            # Prevent cycles
            current_ns = target_element
            while current_ns:
                if current_ns is item:
                    log.info("Cycle detected during drop; rejecting")
                    return False
                current_ns = getattr(current_ns, 'owner', None)

        try:
            with Transaction(self._event_manager):
                if target_element is None:
                    del item.package
                elif isinstance(item, Diagram):
                    item.element = target_element
                else:
                    item.package = target_element
                self._event_manager.handle(ItemDroppedEvent(self, item))
            return True
        except AttributeError as err:
            self._report_invalid_drop(target_element, err, item)
        return False

    def _report_invalid_drop(self, target, error, item):
        log.info(f"Drop failed: {error}")
        self._event_manager.handle(
            Notification(
                gettext("A {} cannot be nested inside a {}.").format(
                    type(item).__name__, type(target).__name__
                )
            )
        )

    def _compare_rows(self, model, iter1, iter2, userdata):
        val1 = model.get_value(iter1, 0)
        val2 = model.get_value(iter2, 0)

        # Prioritize relationship group marker
        if val1 is RelationshipGroupMarker:
            return -1
        if val2 is RelationshipGroupMarker:
            return 1

        name1 = (format_value(val1) or "").lower()
        name2 = (format_value(val2) or "").lower()

        if name1 == name2:
            return 0
        return 1 if name1 > name2 else -1

import pytest

# Files to be excluded from test collection
collect_ignore = ["setup.py", "sopel.py"]

def pytest_addoption(parser):
    """Add command-line option for offline mode."""
    parser.addoption('--offline', action='store_true', default=False,
                     help='Run tests without requiring internet access')

def pytest_collection_modifyitems(config, items):
    """Skip tests marked as 'online' when --offline is enabled."""
    if config.getoption('--offline'):
        skip_marker = pytest.mark.skip(reason='skipped due to --offline flag')
        for item in items:
            if hasattr(item, 'get_closest_marker') and item.get_closest_marker('online'):
                item.add_marker(skip_marker)
            elif 'online' in getattr(item, 'keywords', {}):
                item.add_marker(skip_marker)

def pytest_configure(config):
    """Register the 'online' marker for documentation purposes."""
    config.addinivalue_line(
        'markers',
        'online: marks tests that require network connectivity. '
        'These tests will be skipped when running with --offline.'
    )

