# Clickhouse Person Management Module (Type III Clone)

import json
from typing import Dict, List, Optional, Any
from uuid import UUID as UUIDType
from django.db.models.query import QuerySet
from django.db.models.signals import post_delete, post_save
from django.dispatch import receiver
from django.utils.timezone import now
from rest_framework import serializers
from ee.clickhouse.client import sync_execute
from ee.clickhouse.sql.person import (
    DELETE_PERSON_BY_ID,
    DELETE_PERSON_EVENTS_BY_ID,
    INSERT_PERSON_DISTINCT_ID,
    INSERT_PERSON_SQL,
)
from ee.kafka_client.client import ClickhouseProducer
from ee.kafka_client.topics import KAFKA_PERSON, KAFKA_PERSON_UNIQUE_ID
from posthog import settings
from posthog.ee import is_clickhouse_enabled
from posthog.models.person import Person, PersonDistinctId
from posthog.models.utils import UUIDT


# Helper function to generate or validate UUID
def _normalize_uuid(uuid_value: Optional[str]) -> str:
    if uuid_value:
        return str(uuid_value)
    return str(UUIDT())


# Helper function to format timestamp for ClickHouse
def _format_timestamp(dt_obj) -> tuple:
    if not dt_obj:
        dt_obj = now()
    return dt_obj.strftime("%Y-%m-%d %H:%M:%S.%f"), dt_obj.strftime("%Y-%m-%d %H:%M:%S")


# Core person creation logic
def register_person(
    team_identifier: int,
    person_uuid: Optional[str] = None,
    attributes: Optional[Dict] = None,
    immediate_sync: bool = False,
    flagged_identified: bool = False,
    event_time: Optional[Any] = None,
) -> str:
    # Normalize inputs
    person_id = _normalize_uuid(person_uuid)
    formatted_time, raw_time = _format_timestamp(event_time)

    payload = {
        "id": person_id,
        "team_id": team_identifier,
        "properties": json.dumps(attributes or {}),
        "is_identified": 1 if flagged_identified else 0,
        "created_at": formatted_time,
        "_timestamp": raw_time,
    }

    producer = ClickhouseProducer()
    producer.produce(topic=KAFKA_PERSON, sql=INSERT_PERSON_SQL, data=payload, sync=immediate_sync)
    return person_id


# Distinct ID registration logic
def register_person_distinct_id(
    team_identifier: int, 
    identifier: str, 
    person_identifier: str, 
    operation_sign: int = 1
) -> None:
    payload = {
        "distinct_id": identifier,
        "person_id": person_identifier,
        "team_id": team_identifier,
        "sign": operation_sign,
    }

    producer = ClickhouseProducer()
    producer.produce(topic=KAFKA_PERSON_UNIQUE_ID, sql=INSERT_PERSON_DISTINCT_ID, data=payload)


# Signal handlers for Django model events
if settings.EE_AVAILABLE and is_clickhouse_enabled():
    @receiver(post_save, sender=Person)
    def on_person_created(sender, instance: Person, created: bool, **kwargs):
        if created:
            register_person(
                team_identifier=instance.team.pk,
                attributes=instance.properties,
                person_uuid=str(instance.uuid),
                flagged_identified=instance.is_identified,
            )

    @receiver(post_save, sender=PersonDistinctId)
    def on_person_distinct_id_created(sender, instance: PersonDistinctId, created: bool, **kwargs):
        if created:
            register_person_distinct_id(
                instance.team.pk, 
                instance.distinct_id, 
                str(instance.person.uuid)
            )

    @receiver(post_delete, sender=Person)
    def on_person_deleted(sender, instance: Person, **kwargs):
        remove_person(
            person_id=str(instance.uuid),
            properties=instance.properties,
            flagged_identified=instance.is_identified,
            team_identifier=instance.team_id,
        )

    @receiver(post_delete, sender=PersonDistinctId)
    def on_person_distinct_id_deleted(sender, instance: PersonDistinctId, **kwargs):
        register_person_distinct_id(
            instance.team.pk, 
            instance.distinct_id, 
            str(instance.person.uuid), 
            operation_sign=-1
        )


# Person removal logic
def remove_person(
    person_id: UUIDType,
    attributes: Dict,
    flagged_identified: bool,
    delete_related_events: bool = False,
    team_identifier: int = None
) -> None:
    timestamp = now()
    payload = {
        "id": str(person_id),
        "team_id": team_identifier,
        "properties": json.dumps(attributes),
        "is_identified": 1 if flagged_identified else 0,
        "created_at": timestamp.strftime("%Y-%m-%d %H:%M:%S"),
        "_timestamp": timestamp.strftime("%Y-%m-%d %H:%M:%S"),
    }

    try:
        if delete_related_events:
            sync_execute(DELETE_PERSON_EVENTS_BY_ID, {"id": person_id, "team_id": team_identifier})
    except Exception:
        pass  # Ignore errors during distributed table deletion

    sync_execute(DELETE_PERSON_BY_ID, payload)


# Query helper functions
def find_persons_by_identifiers(team_identifier: int, identifiers: List[str]) -> QuerySet:
    return Person.objects.filter(
        team_id=team_identifier,
        persondistinctid__team_id=team_identifier,
        persondistinctid__distinct_id__in=identifiers
    )


def find_persons_by_uuid_list(team_identifier: int, uuid_list: List[str]) -> QuerySet:
    return Person.objects.filter(team_id=team_identifier, uuid__in=uuid_list)


# Serializer for ClickHouse person data
class ClickhousePersonSerializer(serializers.Serializer):
    id = serializers.SerializerMethodField()
    created_at = serializers.SerializerMethodField()
    team_id = serializers.SerializerMethodField()
    properties = serializers.SerializerMethodField()
    is_identified = serializers.SerializerMethodField()
    name = serializers.SerializerMethodField()
    distinct_ids = serializers.SerializerMethodField()

    def get_name(self, person_data):
        props = json.loads(person_data[3])
        email = props.get("email", None)
        return email or person_data[0]

    def get_id(self, person_data):
        return person_data[0]

    def get_created_at(self, person_data):
        return person_data[1]

    def get_team_id(self, person_data):
        return person_data[2]

    def get_properties(self, person_data):
        return json.loads(person_data[3])

    def get_is_identified(self, person_data):
        return person_data[4]

    def get_distinct_ids(self, person_data):
        return person_data[5] if len(person_data) > 5 else []

