        if self._config.get("api_token"):
            self._src_headers["Authorization"] = f"Bearer {self._config['api_token']}"
        self.PUBLISH_MSG = self._config["publish_message"]
        self.PUBLISH_PATTERN = re.compile(f"{re.escape(self.PUBLISH_MSG)}:(.*)")

    @staticmethod
    def _fetch_json(url: str, headers: Dict[str, str]) -> Any:
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.json()
        elif response.status_code == 404:
            raise GrafanaPublisherResourceNotFoundError(f"Resource not found: {url}")
        else:
            raise GrafanaPublisherError(f"Failed to retrieve resource from {url}: {response.reason}")

    def fetch_data(self, api_path: str) -> Any:
        base_url = self._config["url"]
        return self._fetch_json(f"{base_url}/{api_path}", headers=self._src_headers)

    def get_published_dashboards(self) -> List:
        tag_name = self._config["published_tag"]
        return self.fetch_data(f"api/search?tag={tag_name}")

    def latest_published_dashboard(self,
                                    dash_id: int,
                                    cutoff_date: Union[arrow.Arrow, None] = None
                                    ) -> Any:
        versions = self.fetch_data(f"api/dashboards/id/{dash_id}/versions")
        for version in versions:
            if self.PUBLISH_MSG in version['message']:
                if cutoff_date is not None:
                    created_time = arrow.get(version['created'])
                    if created_time < cutoff_date:
                        logger.info("Version %s skipped (already updated.)", version['version'])
                        continue
                # Retrieve specific version data
                return self.fetch_data(
                    f"api/dashboards/id/{dash_id}/versions/{version['version']}"
                )
        logger.info(
            f"Dashboard ID {dash_id} is tagged for publishing, "
            f"but no new published version is available.")
        raise GrafanaPublisherResourceNotFoundError()

    def extract_publish_note(self, version_msg: str) -> str:
        trimmed = version_msg.strip()
        match = self.PUBLISH_PATTERN.match(trimmed)
        if match:
            return match.group(1).strip()
        else:
            if trimmed == self.PUBLISH_MSG:
                return "Updated"
            else:
                return trimmed

class TargetRepoUtils:
    GITLAB_API = "api/v4"
    def __init__(self, config: Dict):
        self._config = config
        self.dash_root = pathlib.Path(self._config["clone_path"],
                                      self._config["dashboard_path"])
        self.gitlab_enabled = bool(self._config.get("gitlab", {}).get("url"))
        self._gitlab_header = {}
        if self._config.get("gitlab", {}).get("access_token"):
            self._gitlab_header["PRIVATE-TOKEN"] = \
                self._config["gitlab"]["access_token"]
        self.local_repo = (self._config.get("repo_url", "").lower() == "local")

    def _execute_command(self, cmd: List, description: str, cwd: str = None) -> str:
        working_dir = cwd or self._config["clone_path"]
        result = subprocess.run(cmd, cwd=working_dir, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE)
        if result.returncode != 0:
            error_msg = result.stderr.decode('utf-8').strip()
            raise GrafanaPublisherError(f"{description} failed: {error_msg}")
        else:
            logger.info("%s: OK", description)
            return result.stdout.decode("utf-8").strip()

    def locate_dashboard(self, dash_uid: str
                         ) -> Tuple[Union[str, None], Union[str, None]]:
        for file_path in self.dash_root.glob("**/*.json"):
            with open(file_path, "r") as dash_file:
                dashboard_data = json.load(dash_file)
                if dashboard_data.get('uid') == dash_uid:
                    return dashboard_data.get('version'), str(file_path)
        return None, None

    def _gitlab_request(self, api_endpoint: str) -> Any:
        base_url = self._config["gitlab"]["url"]
        full_url = f"{base_url}/{self.GITLAB_API}/{api_endpoint}"
        response = requests.get(full_url, headers=self._gitlab_header)
        if response.ok:
            return response.json()
        elif response.status_code == 404:
            raise GrafanaPublisherResourceNotFoundError(
                f"Target repo resource not found: {full_url}")
        else:
            raise GrafanaPublisherError(
                f"Could not fetch resource from target repo {full_url}: {response.reason}"
            )

    def verify_git_repository(self) -> None:
        if self.local_repo:
            self._execute_command(["git", "status"], "Verifying local repository exists")
        else:
            try:
                remote_url = self._execute_command(
                    ["git", "config", "--get", "remote.origin.url"],
                    "Retrieving remote URL")
                if remote_url != self._config["repo_url"]:
                    raise GrafanaPublisherError(
                        f"Target repository has a different remote URL: {remote_url}")
                self._execute_command(
                    ["git", "checkout", self._config["branch"]],
                    f"Switching to branch {self._config['branch']}"
                )
                self._execute_command(["git", "pull"], "Fetching latest changes")
            except FileNotFoundError:
                logger.info("Repository not found — initiating clone operation.")
                self._execute_command(
                    ["git", "clone", self._config["repo_url"],
                     self._config["clone_path"]],
                    f"Cloning repository to {self._config['clone_path']}",
                    cwd="."
                )

    def format_commit_summary(self, change_list: List[Tuple[str, str]]) -> str:
        item_count = len(change_list)
        if item_count == 1:
            summary = change_list[0][0]
        else:
            summary = f"{item_count} dashboards"
        commit_body = f"Published updates to {summary}.\n\n"
        details = "\n".join(
            [f"{dash}: {update_msg}\n" for dash, update_msg in change_list])
        return commit_body + details

    def stage_and_commit(self, change_list: List[Tuple[str, str]]) -> None:
        self._execute_command(["git", "add", "-A"], "Staging all changes")
        commit_message = self.format_commit_summary(change_list)
        self._execute_command(["git", "commit", "-m", commit_message], "Committing changes")

    def push_changes(self) -> None:
        self._execute_command(["git", "push"], "Pushing committed changes")

    def current_head_commit(self) -> Dict:
        project_id = self._config["gitlab"]["project_id"]
        branch_name = self._config["branch"]
        return self._gitlab_request(
            f"projects/{project_id}/repository/commits/{branch_name}")

    def last_commit_timestamp(self) -> arrow.Arrow:
        commit_info = self.current_head_commit()
        return arrow.get(commit_info['created_at'])

import collections
import inspect
import warnings
import math
import json

# Import necessary modules
from metaclasses    import MetaCollectArgs
from ConnectionEdge import ConnectionEdge, PyMTLConnectError
from signals        import Signal, InPort, OutPort, Wire, Constant
from signal_lists   import PortList, WireList
from PortBundle     import PortBundle
from ..datatypes    import Bits


class HardwareModel(object):
    """Base class for PyMTL hardware models.
    Provides utilities for building connectivity between components,
    naming instantiated subcomponents, and constructing data structures
    that tools can leverage.

    Any user-defined model aiming to use PyMTL tools should inherit from this.
    """
    __metaclass__ = MetaCollectArgs
    _debug_mode   = False

    # Black-box configuration options for Verilog translation
    vblackbox      = False  # Treat module as black box during Verilog generation
    vbb_modulename = ""     # Custom module name for black box
    vbb_no_reset   = False  # Omit reset port in generated Verilog
    vbb_no_clk     = False  # Omit clock port in generated Verilog

    # Array annotation support for FPGA synthesis (e.g., BRAM inference)
    vannotate_arrays = {}

    # Mark current model as BRAM for FPGA synthesis
    vmark_as_bram = False

    #=======================================================================
    # Modeling API
    #=======================================================================

    def __new__(cls, *args, **kwargs):
        """Pre-constructor adds default 'clk' and 'reset' ports."""
        instance = object.__new__(cls)

        # Add implicit clock and reset inputs
        instance.clk   = InPort(1)
        instance.reset = InPort(1)

        # Initialize internal tracking structures
        instance._tick_blocks          = []
        instance._posedge_clk_blocks   = []
        instance._combinational_blocks = []
        instance._connections          = set()

        return instance

    def connect(self, src_signal, dst_signal):
        """Establish structural connection between two signals or constants."""
        if isinstance(src_signal, Wire) and isinstance(dst_signal, Wire):
            err_msg = ('Connecting two Wire signals is not supported!\n'
                       'Use connect_wire() instead:\n\n'
                       '  connect_wire(dest=<dst>, src=<src>)')
            frame_info = inspect.stack()[1]
            full_err = f"{err_msg}\n\nLine {frame_info.lineno} in {frame_info.filename}\n>{''.join(frame_info.code_context)}"
            raise PyMTLConnectError(full_err)

        try:
            if isinstance(src_signal, PortBundle):
                self._connect_bundle_pair(src_signal, dst_signal)
            else:
                self._connect_single_pair(src_signal, dst_signal)
        except PyMTLConnectError as e:
            frame_info = inspect.stack()[1]
            full_err = f"{e}\n\nLine {frame_info.lineno} in {frame_info.filename}\n>{''.join(frame_info.code_context)}"
            raise PyMTLConnectError(full_err)

    def connect_pairs(self, *pairs):
        """Connect multiple signal pairs using positional arguments."""
        if len(pairs) % 2 != 0:
            err_msg = "Odd number of signals provided!"
            frame_info = inspect.stack()[1]
            full_err = f"{err_msg}\n\nLine {frame_info.lineno} in {frame_info.filename}\n>{''.join(frame_info.code_context)}"
            raise PyMTLConnectError(full_err)

        iterator = iter(pairs)
        for left_sig, right_sig in zip(iterator, iterator):
            try:
                self.connect(left_sig, right_sig)
            except PyMTLConnectError as e:
                frame_info = inspect.stack()[1]
                full_err = f"{e}\n\nLine {frame_info.lineno} in {frame_info.filename}\n>{''.join(frame_info.code_context)}"
                raise PyMTLConnectError(full_err)

    def connect_dict(self, mapping):
        """Connect signals based on dictionary key-value pairs."""
        for src_key, dst_val in mapping.items():
            try:
                self.connect(src_key, dst_val)
            except PyMTLConnectError as e:
                frame_info = inspect.stack()[1]
                full_err = f"{e}\n\nLine {frame_info.lineno} in {frame_info.filename}\n>{''.join(frame_info.code_context)}"
                raise PyMTLConnectError(full_err)

    def connect_wire(self, dest=None, src=None):
        """Explicitly connect two Wires with specified directionality."""
        self._connect_single_pair(src, dest)

    def connect_auto(self, model_a, model_b=None):
        """EXPERIMENTAL: Attempt automatic port matching by name."""
        if not hasattr(self, '_auto_connections'):
            self._auto_connections = []
        self._auto_connections.append((model_a, model_b))

    def tick_fl(self, func):
        """Decorator for functional-level sequential blocks."""
        return self.tick(func)

    def tick_cl(self, func):
        """Decorator for cycle-level sequential blocks."""
        return self.tick(func)

    def tick_rtl(self, func):
        """Decorator for RTL-level sequential blocks."""
        return self.posedge_clk(func)

    def combinational(self, func):
        """Decorator for combinational logic blocks."""
        self._combinational_blocks.append(func)
        func._owner = self
        return func

    def posedge_clk(self, func):
        """Decorator for RTL sequential logic triggered on positive clock edge."""
        self._posedge_clk_blocks.append(func)
        func._owner = self
        return func

    def tick(self, func):
        """Decorator for general cycle-level sequential logic."""
        self._tick_blocks.append(func)
        func._owner = self
        return func

    def line_trace(self):
        """Return concise state representation for simulation tracing."""
        return ""

    def elaborate_logic(self):
        """DEPRECATED: Placeholder for legacy elaboration logic."""
        pass

    #=====================================================================
    # Tool API
    #=====================================================================

    def elaborate(self):
        """Perform full elaboration: build hierarchy, assign names, etc."""
        self._all_models = set()
        self._traverse_elaboration(self, 'top')
        self._resolve_directionality()

    def is_elaborated(self):
        """Check whether this model has been elaborated."""
        return hasattr(self, 'full_class_name')

    def get_inputs(self):
        """Retrieve all input ports."""
        return self._input_ports

    def get_outputs(self):
        """Retrieve all output ports."""
        return self._output_ports

    def get_all_ports(self, keep_hierarchy=False):
        """Get all input/output ports; optionally preserve hierarchy."""
        if not keep_hierarchy:
            return self._input_ports + self._output_ports
        else:
            return self._hierarchical_ports

    def get_internal_wires(self):
        """Get list of internal wire signals."""
        return self._internal_wires

    def get_submodels(self):
        """Get list of child models."""
        return self._child_models

    def get_connections_list(self):
        """Get list of all structural connections."""
        return self._connections

    def get_sequential_blocks(self):
        """Get list of all tick_* decorated functions."""
        return self._tick_blocks

    def get_clock_edge_blocks(self):
        """Get list of posedge_clk decorated functions."""
        return self._posedge_clk_blocks

    def get_combinational_blocks(self):
        """Get list of combinational decorated functions."""
        return self._combinational_blocks

    #=====================================================================
    # Internal Methods
    #=====================================================================

    def _traverse_elaboration(self, target_model, instance_label):
        """Recursively process model attributes and instantiate subcomponents."""
        if target_model.is_elaborated():
            raise Exception(f"Model {target_model.full_class_name} already elaborated!")

        self._all_models.add(target_model)

        target_model.full_class_name = self._make_unique_name(target_model)
        target_model.parent          = None
        target_model.instance_name   = instance_label

        target_model.elaborate_logic()

        target_model._internal_wires       = []
        target_model._input_ports          = []
        target_model._output_ports         = []
        target_model._hierarchical_ports   = []
        target_model._child_models         = []
        target_model._trace_enabled        = False

        if not hasattr(target_model, '_sensitivity_map'):
            target_model._sensitivity_map = collections.defaultdict(list)

        for attr_name, attr_obj in target_model.__dict__.items():
            if not attr_name.startswith('_'):
                self._classify_attribute(target_model, attr_name, attr_obj)

        if hasattr(target_model, '_auto_connections'):
            target_model._perform_automatic_connections()

    def _classify_attribute(self, owner_model, name, obj, nested_level=False):
        """Categorize and register model attributes based on type."""
        if isinstance(obj, Wire):
            obj.name = name
            obj.owner = owner_model
            owner_model._internal_wires.append(obj)
        elif isinstance(obj, InPort):
            obj.name = name
            obj.owner = owner_model
            owner_model._input_ports.append(obj)
            if not nested_level:
                owner_model._hierarchical_ports.append(obj)
        elif isinstance(obj, OutPort):
            obj.name = name
            obj.owner = owner_model
            owner_model._output_ports.append(obj)
            if not nested_level:
                owner_model._hierarchical_ports.append(obj)
        elif isinstance(obj, PortBundle):
            obj.name = name
            for port in obj.get_ports():
                self._classify_attribute(owner_model, f"{name}.{port.name}", port, nested_level=True)
            if not nested_level:
                owner_model._hierarchical_ports.append(obj)
        elif isinstance(obj, HardwareModel):
            if obj.is_elaborated():
                warnings.warn(f"Model '{obj.__class__.__name__}' has duplicate parent!")
                return
            self._traverse_elaboration(obj, name)
            obj.owner = owner_model
            owner_model._child_models.append(obj)
            owner_model.connect(obj.clk, owner_model.clk)
            owner_model.connect(obj.reset, owner_model.reset)
        elif isinstance(obj, list):
            if obj and isinstance(obj[0], Wire):
                obj = WireList(obj)
                obj.name = name
                assert '.' not in name
                setattr(owner_model, name, obj)
            if obj and isinstance(obj[0], (InPort, OutPort, PortBundle)):
                temp = PortList(obj)
                temp._ports = obj
                obj = temp
                obj.name = name
                assert '.' not in name
                setattr(owner_model, name, obj)
                if not nested_level:
                    owner_model._hierarchical_ports.append(obj)
            for idx, item in enumerate(obj):
                item_id = f"{name}[{idx}]"
                self._classify_attribute(owner_model, item_id, item, nested_level=True)

    @staticmethod
    def convert_keys_to_strings(container):
        if isinstance(container, dict):
            return {str(k): HardwareModel.convert_keys_to_strings(v) for k, v in container.items()}
        return container

    def _make_unique_name(self, model_instance):
        """Generate unique identifier for model instance."""
        base_name = model_instance.__class__.__name__
        try:
            for param_key, param_val in model_instance._init_args.items():
                if isinstance(param_val, Bits.Bits):
                    model_instance._init_args[param_key] = param_val.nbits
            json_repr = json.dumps(HardwareModel.convert_keys_to_strings(model_instance._init_args),
                                   sort_keys=True, default=str)
            combined = f"{model_instance.__module__} {json_repr}"
            hash_suffix = abs(hash(combined))
            model_instance.hash_input = combined
            if hasattr(model_instance, 'custom_module_name'):
                return model_instance.custom_module_name
            return f"{base_name}_{hex(hash_suffix)}"
        except AttributeError:
            return base_name

    def _resolve_directionality(self):
        """Determine direction of each connection edge."""
        for conn in self._connections:
            conn.set_direction()
        for child in self._child_models:
            child._resolve_directionality()

    def _connect_single_pair(self, source, destination):
        """Create a single connection between two signals."""
        assert source != destination
        edge = ConnectionEdge(source, destination)
        if not edge:
            raise ValueError("Invalid connection attempted")
        self._connections.add(edge)

    def _connect_bundle_pair(self, bundle_a, bundle_b):
        """Connect corresponding ports between two bundles."""
        assert bundle_a != bundle_b
        for src_port, dst_port in zip(bundle_a.get_ports(), bundle_b.get_ports()):
            self._connect_single_pair(src_port, dst_port)

    def _perform_automatic_connections(self):
        """Match and connect ports across models by name."""
        def collect_port_map(port_list):
            result = {}
            for p in port_list:
                if p.name not in ('clk', 'reset'):
                    result[p.name] = p
            return result

        for m1, m2 in self._auto_connections:
            parent_ports = collect_port_map(self.get_inputs() + self.get_outputs())
            child1_ports = collect_port_map(m1.get_all_ports())
            child2_ports = collect_port_map(m2.get_all_ports() if m2 else [])

            for name, port in parent_ports.items():
                if name in child1_ports:
                    self.connect(port, child1_ports[name])
                    del child1_ports[name]
                if name in child2_ports:
                    self.connect(port, child2_ports[name])
                    del child2_ports[name]

            for name, port in child2_ports.items():
                if name in child1_ports:
                    self.connect(child1_ports[name], port)

