def _parse_key_value_pairs(entry: str, delimiter: str = ',') -> List[str]:
    """Split input string into key=value tokens using shlex."""
    if not entry:
        return []
    lexer = shlex.shlex(entry, posix=True)
    lexer.whitespace_split = True
    lexer.whitespace = delimiter
    return list(lexer)


def _to_dict_from_kv_list(pairs: List[str]) -> Dict[str, str]:
    """Convert list of 'key=value' strings into dictionary."""
    result = {}
    for item in pairs:
        if '=' in item:
            key, value = item.split('=', 1)
            result[key] = value
    return result


def to_attributes(entry: str) -> Dict[str, str]:
    """Convert comma-separated key=value string to dictionary."""
    tokens = _parse_key_value_pairs(entry)
    return _to_dict_from_kv_list(tokens)


def _to_list_of_tuples_from_kv_list(pairs: List[str]) -> List[Tuple[str, str]]:
    """Convert list of 'key=value' strings into list of tuples."""
    result = []
    for item in pairs:
        if '=' in item:
            key, value = item.split('=', 1)
            result.append((key, value))
    return result


def to_tuples(entry: str) -> List[Tuple[str, str]]:
    """Convert comma-separated key=value string to list of tuples."""
    tokens = _parse_key_value_pairs(entry)
    return _to_list_of_tuples_from_kv_list(tokens)


def _extract_field_value(item: Dict[str, Any], path_expr: Any) -> str:
    """Extract values from item using JSONPath expression and join them."""
    matches = [match.value for match in path_expr.find(item)]
    return ", ".join(str(v) for v in matches)


def _prepare_table_rows(
    data: List[Dict[str, Any]],
    format_specs: List[Tuple[str, Any]],
    include_headers: bool,
) -> Tuple[List[str], List[List[str]]]:
    """Build headers and rows for table output."""
    headers = [spec[0] for spec in format_specs] if include_headers else []
    rows = []
    for record in data:
        row = [_extract_field_value(record, spec[1]) for spec in format_specs]
        rows.append(row)
    return headers, rows


def raw_format_output(
    output_mode: str,
    payload: Union[Dict[str, Any], List[Dict[str, Any]]],
    yaml_engine: YAML,
    fields: Optional[List] = None,
    suppress_headers: bool = False,
    display_style: str = 'plain',
    sort_key: Optional[str] = None,
) -> str:
    """Render data according to specified output format."""
    if output_mode == 'auto':
        output_mode = const.DEFAULT_DATAOUTPUT

    # Handle sorting if applicable
    if sort_key and isinstance(payload, list):
        _apply_sorting(payload, sort_key)

    # Format based on mode
    if output_mode == 'json':
        try:
            return json.dumps(payload, indent=2, sort_keys=False)
        except Exception:
            return str(payload)

    elif output_mode == 'yaml':
        try:
            return cast(str, yaml.dumpyaml(yaml_engine, payload))
        except Exception:
            return str(payload)

    elif output_mode == 'table':
        from jsonpath_rw import parse

        field_defs = fields or const.COLUMNS_DEFAULT
        fmt_specs = [(v[0], parse(v[1] if len(v) > 1 else v[0])) for v in field_defs]

        # Normalize single-item payload to list
        items = payload if isinstance(payload, list) else [payload]

        headers, rows = _prepare_table_rows(items, fmt_specs, not suppress_headers)
        return tabulate(rows, headers=headers, tablefmt=display_style)

    else:
        raise ValueError(
            f"Unsupported output format '{output_mode}'. Expected 'json', 'yaml', or 'table'."
        )


def _apply_sorting(records: List[Any], criterion: str) -> None:
    """Sort records in-place by specified field using JSONPath."""
    from jsonpath_rw import parse
    selector = parse(criterion)

    def _get_sort_key(record: Dict[str, Any]) -> Tuple[int, Any]:
        candidates = [match.value for match in selector.find(record)]
        val = candidates[0] if candidates else None
        return (val is None, val)

    records.sort(key=_get_sort_key)


def format_output(
    ctx: Configuration,
    payload: List[Dict[str, Any]],
    fields: Optional[List] = None,
) -> str:
    """Format response data using configuration context."""
    return raw_format_output(
        ctx.output,
        payload,
        ctx.yaml(),
        fields,
        ctx.no_headers,
        ctx.table_format,
        ctx.sort_by,
    )


def enable_debug_logging() -> None:
    """Activate verbose HTTP request logging."""
    HTTPConnection.set_debuglevel(cast(HTTPConnection, HTTPConnection), 1)
    logging.basicConfig(level=logging.DEBUG)
    urllib3_logger = logging.getLogger('urllib3')
    urllib3_logger.setLevel(logging.DEBUG)
    urllib3_logger.propagate = True


def disable_debug_logging() -> None:
    """Deactivate verbose HTTP request logging."""
    HTTPConnection.set_debuglevel(cast(HTTPConnection, HTTPConnection), 1)
    root_logger = logging.getLogger()
    root_logger.setLevel(logging.WARNING)
    root_logger.handlers.clear()
    urllib3_logger = logging.getLogger('urllib3')
    urllib3_logger.setLevel(logging.WARNING)
    urllib3_logger.propagate = False


@contextlib.contextmanager
def debug_context() -> Generator:
    """Context manager to temporarily enable debug logging."""
    enable_debug_logging()
    try:
        yield
    finally:
        disable_debug_logging()

