import pygame
from os import listdir
from random import choice, randrange
from os.path import exists

from Errors import SpriteError
from Utils import Sounds


class BaseSprite(pygame.sprite.Sprite):
    '''Base sprite class - refactored'''

    __slots__ = ['initial_pos', 'lives', 'config',
                 'layer_group', 'dim_x', 'dim_y', 'asset_dir', 'skin_id']

    def __init__(self, coords: list, lives: int, skin_id: str,
                 asset_dir: str, all_layers, config: dict):
        super().__init__(all_layers)
        self.initial_pos: list = coords.copy()
        self.lives: int = lives
        self.skin_id: str = skin_id
        self.asset_dir: str = asset_dir
        self.config: dict = config
        self.gravity_force = self.config['gravity']

    def initialize(self, asset_path: str) -> None:
        self.apply_texture(asset_path)
        self.dim_x: int = self.image.get_width()
        self.dim_y: int = self.image.get_height()

    def assign_to_layer(self) -> None:
        self.layer_group = pygame.sprite.GroupSingle()
        self.layer_group.add(self)

    def reset_position(self) -> None:
        self.move_to(self.initial_pos)

    def move_to(self, coords: list) -> None:
        self.rect.x, self.rect.y = coords

    def get_full_asset_path(self, texture_name: str) -> str:
        base_path: str = self.config['path']
        full_dir = f'{base_path}/{self.asset_dir}'
        return f'{full_dir}/{self.skin_id}/{texture_name}'

    def apply_texture(self, texture_path: str) -> None:
        full_path = self.get_full_asset_path(texture_path)
        if not exists(full_path):
            raise SpriteError
        self.image = pygame.image.load(full_path).convert_alpha()
        self.rect = self.image.get_rect()
        self.rect.x, self.rect.y = self.initial_pos
        self.mask = pygame.mask.from_surface(self.image)

    def update_texture(self, texture_path: str) -> None:
        full_path = self.get_full_asset_path(texture_path)
        if not exists(full_path):
            raise SpriteError
        current_coords = (self.rect.x, self.rect.y)
        self.image = pygame.image.load(full_path)
        self.rect = self.image.get_rect()
        self.rect.x, self.rect.y = current_coords

    def within_bounds(self, position: list) -> bool:
        x_coord: int = position[0]
        y_coord: int = position[1]
        win_w, win_h = self.config['window_size']
        if x_coord < 0 or x_coord > win_w - self.dim_x:
            return False
        if y_coord < 0 or y_coord > win_h - self.dim_y:
            return False
        return True


class Hero(BaseSprite):
    '''Player sprite class - refactored'''

    __slots__ = ['texture_set', 'audio_system', 'status_flags', 
                 'velocity_x', 'particles', 'velocity_y', 'facing']

    def __init__(self, coords: list, lives: int, skin_id: str,
                 all_layers: pygame.sprite.Group, config: dict):
        super().__init__(coords, lives, skin_id,
                         'assets/sprites/santa', all_layers, config)
        self.initialize(self.get_textures()['idle'])
        self.texture_set: dict = self.get_textures()
        self.status_flags: dict = {'flipped': False, 'idle': True, 'crouching': False}
        db_path: str = config['path'] + '/assets/database/'
        self.audio_system = Sounds(db_path)
        self.velocity_x, self.velocity_y = 0, 0
        self.reset_position()
        self.particles = []
        self.assign_to_layer()
        self.facing = 'right'

    def stand_up(self):
        self.status_flags['crouching'] = False
        self.update_texture(self.get_textures()['idle'])
        prev_facing = self.facing
        self.facing = 'right'
        self.flip(prev_facing)

    def crouch(self):
        self.status_flags['crouching'] = True
        self.update_texture(self.get_textures()['crouch'])
        prev_facing = self.facing
        self.facing = 'right'
        self.flip(prev_facing)

    def switch_skin(self, skin_type: str = '') -> None:
        return self.update_texture(self.get_textures()[skin_type])

    def flip(self, direction):
        if self.facing != direction:
            self.facing = direction
            self.image = pygame.transform.flip(self.image, True, False)

    def get_textures(self) -> dict:
        base_name = f'santa_{self.skin_id}_'
        return {
            'idle': f'{base_name}skin.png',
            'crouch': f'{base_name}sit_skin.png',
            'jump': f'{base_name}jump_skin.png'
        }

    def lose_life(self) -> None:
        self.reset_position()
        self.audio_system.stop('step')
        self.audio_system.play('die')
        self.lives -= 1
        self.status_flags['idle'] = False

    def refresh(self, layer_group, all_layers,
                direction=False,
                jumping=False, crouching=False) -> None:
        # Update particles
        for p in self.particles[:]:
            p.refresh()
            if p.is_dead():
                self.particles.remove(p)

        # Maintain particle count
        while len(self.particles) > 30:
            self.particles.pop(0)

        # Handle crouching
        if crouching:
            self.crouch()

        # Handle jumping
        if jumping and self.status_flags['idle']:
            if not self.status_flags['crouching']:
                self.velocity_y = -self.config['jump_power']
            else:
                self.stand_up()

        # Handle horizontal movement
        if direction == 'left':
            self.velocity_x = -self.config['step']
        elif direction == 'right':
            self.velocity_x = self.config['step']
        else:
            self.velocity_x = 0

        # Apply gravity
        if not self.status_flags['idle']:
            self.velocity_y += self.gravity_force

        # Sound effects
        if self.velocity_y != 0 and self.status_flags['idle']:
            self.audio_system.play('jump')
            self.jump_texture()
        if self.velocity_x != 0 and self.status_flags['idle']:
            self.audio_system.play('step')

        # Handle facing direction
        if self.velocity_x < 0:
            self.flip('left')
        if self.velocity_x > 0:
            self.flip('right')

        # Reset state when grounded
        if self.velocity_y == 0:
            self.stand_up()

        self.status_flags['idle'] = False
        self.navigate(layer_group, all_layers)

    def jump_texture(self):
        self.switch_skin('jump')
        prev_facing = self.facing
        self.facing = 'right'
        self.flip(prev_facing)

    def navigate(self, layer_group, all_layers) -> None:
        # Vertical movement
        self.rect.y += self.velocity_y

        # Vertical collision
        if self.check_collision(layer_group):
            obstacle = self.find_colliding_object(layer_group)
            if self.velocity_y > 0:
                if self.velocity_y != 1:
                    self.particles.append(Particle([self.rect.x, self.rect.y],
                                                  self.config, all_layers))
                self.rect.bottom = obstacle.rect.top
                self.velocity_y = 0
                self.status_flags['idle'] = True
            elif self.velocity_y < 0:
                self.rect.top = obstacle.rect.bottom
                self.velocity_y = 0
                self.status_flags['idle'] = False
        else:
            if self.velocity_y > 0:
                self.status_flags['idle'] = False

        # Horizontal movement
        self.rect.x += self.velocity_x

        # Horizontal collision
        if self.check_collision(layer_group):
            obstacle = self.find_colliding_object(layer_group)
            if self.velocity_x > 0:
                self.rect.right = obstacle.rect.left
                self.velocity_x = 0
            elif self.velocity_x < 0:
                self.rect.left = obstacle.rect.right
                self.velocity_x = 0

    def check_collision(self, layer_group) -> bool:
        for sprite in layer_group:
            if pygame.sprite.collide_mask(self, sprite):
                return True
        return False

    def find_colliding_object(self, layer_group):
        for sprite in layer_group:
            if pygame.sprite.collide_mask(self, sprite):
                return sprite
        return None


class Particle(pygame.sprite.Sprite):
    '''Particle effect class - refactored'''

    __slots__ = ['config', 'motion_vector']

    def __init__(self, coords: list, config: dict,
                 all_layers: pygame.sprite.Group):
        super().__init__(all_layers)
        self.config: dict = config
        self.image: pygame.Surface = self.select_random_asset()
        self.rect: pygame.Rect = self.image.get_rect()
        velocity_range = range(-5, 6)
        self.motion_vector = [choice(velocity_range), choice(velocity_range)]
        self.rect.x, self.rect.y = coords

    def select_random_asset(self) -> pygame.Surface:
        load_image = pygame.image.load
        rel_path = '/assets/sprites/particles/'
        full_path: str = self.config['path'] + rel_path
        assets = [load_image(full_path + file) for file in listdir(full_path)]

        # Add scaled versions
        for scale in (2, 4, 5, 7):
            sample = choice(assets)
            assets.append(pygame.transform.scale(sample, (scale, scale)))

        return choice(assets)

    def refresh(self) -> None:
        self.motion_vector[1] += 1
        window_size = self.config['window_size']
        self.rect.x += self.motion_vector[0]
        self.rect.y += self.motion_vector[1]

    def is_dead(self) -> bool:
        window_size = self.config['window_size']
        return not self.rect.colliderect((0, 0, window_size[0], window_size[1]))


class RollingObstacle(pygame.sprite.Sprite):
    '''Ball obstacle class - refactored'''

    def __init__(self, coords: list, config: dict):
        super().__init__()
        self.config: dict = config
        self.image: pygame.Surface = self.load_asset()
        self.rect: pygame.Rect = self.image.get_rect()
        self.rect.x, self.rect.y = coords

    def load_asset(self) -> pygame.Surface:
        load_image = pygame.image.load
        rel_path = '/assets/sprites/traps/ball/ball_0.png'
        full_path: str = self.config['path'] + rel_path
        return load_image(full_path)

    def refresh(self) -> None:
        window_size = self.config['window_size']
        self.rect.y += 15
        if self.rect.top > window_size[1] + 400:
            self.rect.y = randrange(-400, -30)

# Custom test runner implementation for inline execution without threading

from typing import Any, Optional, Set
from puma.context import ensure_used_within_context_manager
from puma.helpers.testing.mixin import NotATestCase
from puma.runnable.message import StatusMessage
from tests.buffer.test_support.single_threaded_primitive_types import InlineRunner
from tests.buffer.test_support.test_inline_buffer import TestInlineBuffer
from tests.runnable.runner.test_inline_runnable import TestInlineRunnable

BUFFER_SIZE_CONSTANT = 13

class CustomInlineRunner(InlineRunner, NotATestCase):
    """A specialized test runner that executes runnables synchronously within the calling thread,
    simulating immediate command and status buffer operations.
    """
    def __init__(self, target_runnable: TestInlineRunnable, runner_name: Optional[str] = None) -> None:
        self._test_target = target_runnable
        self.completed_join = False
        # Initialize parent after setting up monitoring attributes to track initialization behavior
        super().__init__(target_runnable, runner_name)  # triggers set_name() internally

    def __enter__(self) -> 'CustomInlineRunner':
        super().__enter__()
        return self

    def _handle_scoped_attributes_in_child_scope(self, instance: Any, visited_objects: Set[Any]) -> None:
        # Skip scoped attribute handling to avoid issues when parent/child share same thread context
        pass

    @ensure_used_within_context_manager
    def join(self, deadline: Optional[float] = None) -> None:
        super().join(deadline)
        self.completed_join = True

    def is_running(self) -> bool:
        return self._test_target.executed and not self._test_target.stopped

    @staticmethod
    def _get_buffer_capacity() -> int:
        return BUFFER_SIZE_CONSTANT

    def _instantiate_status_channel(self) -> TestInlineBuffer[StatusMessage]:
        self.internal_status_queue: TestInlineBuffer = TestInlineBuffer[StatusMessage](
            self._get_buffer_capacity(), 
            "Status channel on " + self.get_name()
        )
        return self.internal_status_queue

    def retrieve_status_channel(self) -> TestInlineBuffer[StatusMessage]:
        if not hasattr(self, 'internal_status_queue') or not self.internal_status_queue:
            raise RuntimeError("Critical: status buffer must be initialized first")
        return self.internal_status_queue

from ...components.icomponent import IVerifierComponent
from ...utils import keyword
from ...utils.other_util import to_numpy_list

class ShapeTypeVC(IVerifierComponent):
    """
    Verify if the result's shape and type are correct.
    Examples:
        'desc_expect': {
            'shape_type': [
                {
                    'type': np.float32,
                    'shape': (2, 2)
                }
            ]
        }
    """
    def __call__(self):
        # Convert results to numpy list format
        output_arrays = to_numpy_list(self.func_result[keyword.result])
        # Retrieve expected shape and type specifications
        expected_specs = self.expect[keyword.desc_expect][keyword.shape_type]

        # Validate each output against its corresponding expectation
        for idx, spec in enumerate(expected_specs):
            actual_array = output_arrays[idx]
            target_shape = spec[keyword.shape]
            target_dtype = spec[keyword.type]

            # Check both shape and data type match expectations
            if actual_array.shape != target_shape or actual_array.dtype != target_dtype:
                error_msg = f"Verification failed: expected shape {target_shape} and dtype {target_dtype}, but got shape {actual_array.shape} and dtype {actual_array.dtype}"
                raise TypeError(f"Error: {error_msg}. Full expect: {self.expect}, actual result: {self.func_result}")

import os
import json
from pathlib import Path
import click
from .quality import Quality

class Configuration(object):
    APPLICATION_IDENTIFIER = "AoDDownloader"

    def __init__(self):
        config_path = self._get_config_path()
        if os.path.isfile(config_path):
            with open(config_path, 'r') as file:
                stored_config = json.load(file)
        else:
            stored_config = {}

        self.user = stored_config.get("username")
        self.lang_german = stored_config.get("german", False)
        self.lang_japanese = stored_config.get("japanese", False)

        quality_name = stored_config.get("quality")
        self.max_quality = Quality[quality_name] if quality_name and quality_name in [q.name for q in Quality] else None

        self.use_keyring = stored_config.get("keyring", True)
        self.credentials = stored_config.get("password")

    def _get_config_path(self) -> str:
        base_dir = (
            os.getenv('APPDATA', '') + "/AoDDownloader" 
            if os.name == 'nt' 
            else str(Path.home() / ".AoD")
        )

        if not os.path.exists(base_dir):
            os.makedirs(base_dir, exist_ok=True)

        return os.path.join(base_dir, "settings.json")

    def save(self):
        config_data = {
            "username": self.user,
            "german": self.lang_german,
            "japanese": self.lang_japanese,
            "quality": self.max_quality.name if self.max_quality else "",
            "keyring": self.use_keyring
        }

        with open(self._get_config_path(), 'w') as output_file:
            json.dump(config_data, output_file, indent=2)

    def configure_quality(self):
        selected_quality = click.prompt(
            "Choose maximum video quality to download.", 
            type=click.Choice([item.name for item in Quality], case_sensitive=False),
            show_choices=True
        )
        self.max_quality = Quality[selected_quality]
        self.save()

    def configure_languages(self):
        self.lang_japanese = click.confirm("Attempt to download Japanese audio with subtitles?")
        self.lang_german = click.confirm("Attempt to download German audio?")
        self.save()
        return self.lang_japanese, self.lang_german

# Type III Clone: Refactored version with equivalent functionality but different structure and logic

import io
import logging
import shutil
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, Tuple, TypeVar
import yaml
import configparser
from esque.errors import ConfigTooNew, ConfigTooOld

logger = logging.getLogger(__name__)
CURRENT_VERSION = 1
MIGRATOR_REGISTRY: Dict[int, Type["ConfigMigrator"]] = {}

def validate_config_version(config_path: Path) -> None:
    current_version = retrieve_config_version(config_path)
    if current_version < CURRENT_VERSION:
        raise ConfigTooOld(current_version, CURRENT_VERSION)
    elif current_version > CURRENT_VERSION:
        raise ConfigTooNew(current_version, CURRENT_VERSION)

def retrieve_config_version(config_path: Path) -> int:
    if config_path.suffix == ".cfg":
        return 0
    with config_path.open("r") as file_handle:
        loaded_data = yaml.safe_load(file_handle)
        return loaded_data.get("version", 0)

def perform_migration(config_path: Path) -> Tuple[Path, Optional[Path]]:
    """
    Migrates the configuration file to the latest version.
    :param config_path: Path to the configuration file to migrate.
    :return: Tuple of (new path, backup path if created, else None)
    """
    original_version = retrieve_config_version(config_path)

    if original_version == CURRENT_VERSION:
        logger.info("Configuration already at latest version. No migration needed.")
        return config_path, None

    logger.info(f"Starting migration from version {original_version} to {CURRENT_VERSION}")

    current_path = config_path
    current_data = None
    migrator_instance = None
    backup_path = None

    for target_version in range(original_version + 1, CURRENT_VERSION + 1):
        migrator_class = MIGRATOR_REGISTRY[target_version]
        migrator_instance = migrator_class(current_path, current_data)

        if backup_path is None:
            backup_path = migrator_instance.create_backup()

        current_path = migrator_instance.output_file_path
        current_data = migrator_instance.migrated_content

    migrator_instance.finalize()
    return current_path, backup_path

class ConfigMigrator:
    TARGET_VERSION: int = -1

    def __init__(self, source_path: Path, source_content: Any = None):
        self._source_path = source_path
        self._source_content = source_content
        self.migrated_content = {}

        if source_content is None:
            self._load_source()

        self._process_content()

    def _load_source(self):
        raw_text = self._source_path.read_text()
        self.deserialize(raw_text)

    def _process_content(self):
        self.migrated_content["version"] = self.TARGET_VERSION

    @property
    def output_file_path(self) -> Path:
        return self._source_path

    def serialize_output(self) -> str:
        raise NotImplementedError()

    def deserialize_input(self, text: str):
        raise NotImplementedError()

    def create_backup(self) -> Path:
        backup_path = self._source_path.with_name(self._source_path.name + ".bak")
        shutil.copy2(str(self._source_path), str(backup_path))
        return backup_path

    def finalize(self) -> Path:
        self.output_file_path.write_text(self.serialize_output())
        return self.output_file_path

class VersionOneMigrator(ConfigMigrator):
    TARGET_VERSION = 1

    @property
    def output_file_path(self) -> Path:
        return self._source_path.parent / "esque_config.yaml"

    def deserialize_input(self, text: str):
        parser = configparser.ConfigParser()
        parser.read_string(text)
        self._source_content = parser

    def serialize_output(self) -> str:
        buffer = io.StringIO()
        yaml.dump(
            self.migrated_content, 
            buffer, 
            default_flow_style=False, 
            sort_keys=False, 
            Dumper=yaml.SafeDumper
        )
        return buffer.getvalue()

    def _process_content(self):
        super()._process_content()
        self.migrated_content["current_context"] = self._source_content["Context"]["current"]
        self._transform_contexts()

    def _transform_contexts(self):
        context_sections = filter(self._is_valid_context, self._source_content.values())
        transformed_contexts = dict(map(self._convert_context, context_sections))
        self.migrated_content["contexts"] = transformed_contexts

    @staticmethod
    def _is_valid_context(section: configparser.SectionProxy) -> bool:
        return section.name.startswith("Context.")

    @staticmethod
    def _convert_context(section: configparser.SectionProxy) -> Tuple[str, Dict]:
        context_data = {"bootstrap_servers": VersionOneMigrator._normalize_servers(section)}

        # Copy unchanged fields directly
        direct_fields = ["security_protocol", "schema_registry"]
        for field in direct_fields:
            if field in section:
                context_data[field] = section[field]

        # Add SSL settings if present
        ssl_data = VersionOneMigrator._extract_ssl(section)
        if ssl_data:
            context_data["ssl_params"] = ssl_data

        # Add SASL settings if present
        sasl_data = VersionOneMigrator._extract_sasl(section)
        if sasl_data:
            context_data["sasl_params"] = sasl_data

        # Add default values if present
        defaults = VersionOneMigrator._extract_defaults(section)
        if defaults:
            context_data["default_values"] = defaults

        name = VersionOneMigrator._get_context_name(section)
        return name, context_data

    @staticmethod
    def _extract_defaults(section: configparser.SectionProxy) -> Dict:
        result = {}
        if "default_replication_factor" in section:
            result["replication_factor"] = int(section["default_replication_factor"])
        if "default_partitions" in section:
            result["num_partitions"] = int(section["default_partitions"])
        return result if result else {}

    @staticmethod
    def _normalize_servers(section: configparser.SectionProxy) -> List[str]:
        server_template = "{}"
        if section.get("bootstrap_domain"):
            server_template += "." + section["bootstrap_domain"]
        if section.get("bootstrap_port"):
            server_template += ":" + section["bootstrap_port"]

        hosts = [host.strip() for host in section["bootstrap_hosts"].split(",")]
        return [server_template.format(host) for host in hosts]

    @staticmethod
    def _extract_ssl(section: configparser.SectionProxy) -> Dict:
        has_ssl_entries = any(key.startswith("ssl_") for key in section.keys())
        if not has_ssl_entries:
            return {}

        def rename_ssl_key(key: str) -> str:
            return key[4:]  # Remove 'ssl_' prefix

        ssl_keys = ["ssl_cafile", "ssl_certfile", "ssl_keyfile", "ssl_password"]
        ssl_data = {}
        for key in ssl_keys:
            if key in section:
                ssl_data[rename_ssl_key(key)] = section[key]
        return ssl_data

    @staticmethod
    def _extract_sasl(section: configparser.SectionProxy) -> Dict:
        has_sasl_entries = any(key.startswith("sasl_") for key in section.keys())
        if not has_sasl_entries:
            return {}

        def rename_sasl_key(key: str) -> str:
            return key[5:]  # Remove 'sasl_' prefix

        sasl_keys = ["sasl_mechanism", "sasl_user", "sasl_password"]
        sasl_data = {}
        for key in sasl_keys:
            if key in section:
                sasl_data[rename_sasl_key(key)] = section[key]
        return sasl_data

    @staticmethod
    def _get_context_name(section: configparser.SectionProxy) -> str:
        return section.name.split(".", 1)[1]

