T = TypeVar("T")

def identity_func(x: T) -> T:
    return x

def copy_if_exists(
    source_key: T, 
    source_dict: Dict[T, Any], 
    target_dict: Dict[T, Any], 
    transform: Callable[[T], T] = identity_func
) -> bool:
    """
    Copies value from source_dict[source_key] to target_dict[transform(source_key)] 
    only if source_key exists in source_dict.
    :param source_key: Key to check in source dictionary
    :param source_dict: Dictionary to read from
    :param target_dict: Dictionary to write to
    :param transform: Function to transform key before writing to target
    :return: True if key was copied, False otherwise
    """
    if source_key in source_dict:
        target_dict[transform(source_key)] = source_dict[source_key]
        return True
    return False

import re
from os import path
from images import load as load_image
from medias import load as load_media
from utils import remove_invalid_chars, replace_bools

def process_game_nodes(GAME_BASE_DIR, renpy, res):
    """
    Convert all nodes into a usable format. The node labeled 'start' will be 
    assigned ID '0'.
    """
    initial_label = find_label_by_name(renpy, 'start')
    actual_start = get_next_valid_node(renpy, initial_label)
    pending_nodes = [actual_start]

    while pending_nodes:
        current_node = pending_nodes.pop(0)
        if current_node and id(current_node) not in res['nodes']:
            pending_nodes.extend(process_single_node(GAME_BASE_DIR, renpy, current_node, res))

    start_id = id(actual_start)
    res['nodes'][0] = res['nodes'][start_id]
    del res['nodes'][start_id]

def find_label_by_name(renpy, label_name):
    for key, node in renpy.game.script.namemap.items():
        if isinstance(node, renpy.ast.Label) and node.name == label_name:
            return node

def warn_unknown_node(node):
    info = getattr(node, 'diff_info', lambda: node)()
    print('[WARNING] unknown node %s: %s' % (type(node).__name__, info))

# Processes a single node and updates res['nodes']
# If the node involves media, adds it to res['sounds'] or res['videos']
# Returns list of next nodes to process
def process_single_node(GAME_BASE_DIR, renpy, node, res):
    if isinstance(node, renpy.ast.Menu):
        return handle_menu_node(renpy, node, res)
    elif isinstance(node, renpy.ast.Say):
        return handle_say_node(renpy, node, res)
    elif isinstance(node, renpy.ast.If):
        return handle_if_node(renpy, node, res)
    elif isinstance(node, renpy.ast.Python):
        return handle_python_node(GAME_BASE_DIR, renpy, node, res)
    elif isinstance(node, renpy.ast.Scene):
        return handle_scene_node(GAME_BASE_DIR, renpy, node, res)
    elif isinstance(node, renpy.ast.Show):
        return handle_show_node(GAME_BASE_DIR, renpy, node, res)
    elif isinstance(node, renpy.ast.Hide):
        return handle_hide_node(renpy, node, res)
    elif isinstance(node, renpy.ast.UserStatement):
        return handle_custom_statement_node(GAME_BASE_DIR, renpy, node, res)
    else:
        warn_unknown_node(node)
        next_node = get_next_valid_node(renpy, node.next)
        return [str(id(next_node))] if next_node else []

def get_next_valid_node(renpy, node):
    while True:
        # Handle known node types directly
        if any(isinstance(node, cls) for cls in [
            renpy.ast.Menu, renpy.ast.Say, renpy.ast.If,
            renpy.ast.Python, renpy.ast.Scene, renpy.ast.Show,
            renpy.ast.Hide, renpy.ast.UserStatement
        ]):
            return node

        # Skip jumps by resolving target labels
        elif isinstance(node, renpy.ast.Jump):
            node = find_label_by_name(renpy, node.target)

        # Skip irrelevant control flow nodes
        elif any(isinstance(node, cls) for cls in [
            renpy.ast.Label, renpy.ast.Translate, renpy.ast.EndTranslate,
            renpy.ast.Pass, renpy.ast.Return, renpy.ast.With
        ]):
            node = node.next

        elif node is not None:
            warn_unknown_node(node)
            break
        else:
            break

def handle_menu_node(renpy, node, res):
    next_nodes = []
    menu_items = []
    display_texts = []

    for item in node.items:
        text, condition, next_item = item
        if next_item:
            next_node = get_next_valid_node(renpy, next_item[0])
            res['nodes'][id(item)] = {
                'class_name': 'MenuItem',
                'arguments': [
                    text,
                    replace_bools(condition),
                    [str(id(next_node))] if next_node else []
                ]
            }
            next_nodes.append(next_node)
            menu_items.append(item)
        else:
            display_texts.append(text)

    item_ids = [str(id(item)) for item in menu_items]
    res['nodes'][id(node)] = {
        'class_name': 'Menu',
        'arguments': [
            '\n'.join(display_texts),
            item_ids
        ]
    }
    return next_nodes

def handle_say_node(renpy, node, res):
    next_node = get_next_valid_node(renpy, node.next)
    res['nodes'][id(node)] = {
        'class_name': 'Say',
        'arguments': [
            node.who,
            node.what,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def handle_if_node(renpy, node, res):
    has_else = False
    for condition, _ in node.entries:
        if condition == 'True':
            has_else = True

    if not has_else:
        node.entries.append(('true', [node.next]))

    block_nexts = []
    block_ids = []

    for condition, block in node.entries:
        block_id = id((condition, block))
        next_block = get_next_valid_node(renpy, block[0])
        res['nodes'][block_id] = {
            'class_name': 'IfBlock',
            'arguments': [
                replace_bools(condition),
                [str(id(next_block))] if next_block else []
            ]
        }
        block_nexts.append(next_block)
        block_ids.append(str(block_id))

    res['nodes'][id(node)] = {
        'class_name': 'If',
        'arguments': [block_ids],
    }
    return block_nexts

VIDEO_PATTERN = re.compile(r'^\s*renpy\.movie_cutscene\s*\((.+)\)\s*$')
PLAY_PATTERN = re.compile(r'^\s*renpy\.sound\.play\s*\((.+)\)\s*$')
LOOP_PATTERN = re.compile(r'^\s*loop\s*=(.*)$')

def handle_python_node(GAME_BASE_DIR, renpy, node, res):
    next_node = get_next_valid_node(renpy, node.next)
    next_ids = [str(id(next_node))] if next_node else []

    video_match = re.search(VIDEO_PATTERN, node.code.source)
    if video_match and len(video_match.groups()) == 1:
        file_path = video_match.group(1)[1:-1]
        vid_name = remove_invalid_chars(file_path)
        load_media(GAME_BASE_DIR, res, 'videos', vid_name, file_path)
        res['nodes'][id(node)] = {
            'class_name': 'Video',
            'arguments': [
                vid_name,
                next_ids
            ]
        }
    else:
        play_match = re.search(PLAY_PATTERN, node.code.source)
        if play_match and len(play_match.groups()) == 1:
            args = [arg.strip() for arg in play_match.group(1).split(',')]
            loop_flag = extract_loop_value(args[1:])
            play_to_str(GAME_BASE_DIR, node, next_ids, res, args[0][1:-1], 'sound', loop_flag)
        else:
            res['nodes'][id(node)] = {
                'class_name': 'PyExpr',
                'arguments': [
                    replace_bools(node.code.source),
                    next_ids
                ]
            }
    return [next_node]

def extract_loop_value(arg_list):
    for arg in arg_list:
        match = re.search(LOOP_PATTERN, arg)
        if match and len(match.groups()) == 1:
            return match.group(1) == "True"

def handle_scene_node(GAME_BASE_DIR, renpy, node, res):
    next_node = get_next_valid_node(renpy, node.next)
    name = node.imspec[0][0]
    load_image(GAME_BASE_DIR, renpy, res, name, node.imspec)
    res['nodes'][id(node)] = {
        'class_name': 'Scene',
        'arguments': [
            name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def handle_show_node(GAME_BASE_DIR, renpy, node, res):
    next_node = get_next_valid_node(renpy, node.next)
    name = node.imspec[0][0]
    is_movie = load_image(GAME_BASE_DIR, renpy, res, name, node.imspec)
    res['nodes'][id(node)] = {
        'class_name': 'ShowVideo' if is_movie else 'Show',
        'arguments': [
            name,
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

def handle_hide_node(renpy, node, res):
    next_node = get_next_valid_node(renpy, node.next)
    res['nodes'][id(node)] = {
        'class_name': 'Hide',
        'arguments': [
            node.imspec[0][0],
            [str(id(next_node))] if next_node else []
        ]
    }
    return [next_node]

WORD_PATTERN = re.compile(r'([\w.]+|".*?")')

def handle_custom_statement_node(GAME_BASE_DIR, renpy, node, res):
    cmd_parts = re.findall(WORD_PATTERN, node.line)
    next_node = get_next_valid_node(renpy, node.next)
    next_ids = [str(id(next_node))] if next_node else []

    if cmd_parts[0] == 'play' and len(cmd_parts) >= 3:
        loop_flag = 'loop' in cmd_parts[3:] if len(cmd_parts) >= 4 else False
        play_to_str(GAME_BASE_DIR, node, next_ids, res, cmd_parts[2][1:-1], cmd_parts[1], loop_flag)
    elif cmd_parts[0] == 'voice' and len(cmd_parts) >= 2:
        play_to_str(GAME_BASE_DIR, node, next_ids, res, cmd_parts[1][1:-1], 'voice', False)
    elif cmd_parts[0] == 'stop' and len(cmd_parts) >= 2:
        stop_to_str(cmd_parts, node, next_ids, res)
    elif cmd_parts[0] == 'window' and len(cmd_parts) >= 2:
        window_to_str(cmd_parts, node, next_ids, res)
    elif cmd_parts[0] == 'pause' and len(cmd_parts) >= 1:
        pause_to_str(cmd_parts, node, next_ids, res)
    else:
        print('[WARNING] unrecognized UserStatement: %s' % node.line)

    return [next_node]

VIDEO_EXTENSIONS = ['.webm', '.ogv']

def play_to_str(GAME_BASE_DIR, node, next_ids, res, file_path, channel, loop_flag):
    sound_name = remove_invalid_chars(file_path)
    _, ext = path.splitext(file_path)
    media_category = 'videos' if ext in VIDEO_EXTENSIONS else 'sounds'
    load_media(GAME_BASE_DIR, res, media_category, sound_name, file_path)
    res['nodes'][id(node)] = {
        'class_name': 'Play',
        'arguments': [
            channel,
            sound_name,
            loop_flag,
            next_ids
        ]
    }

def stop_to_str(cmd_parts, node, next_ids, res):
    channel = cmd_parts[1]
    res['nodes'][id(node)] = {
        'class_name': 'Stop',
        'arguments': [
            channel,
            next_ids
        ]
    }

def window_to_str(cmd_parts, node, next_ids, res):
    show_window = None
    if cmd_parts[1] == 'show':
        show_window = True
    elif cmd_parts[1] == 'hide':
        show_window = False

    if isinstance(show_window, bool):
        res['nodes'][id(node)] = {
            'class_name': 'ShowWindow',
            'arguments': [
                show_window,
                next_ids
            ]
        }
    else:
        print('[WARNING] unrecognized window option: %s' % cmd_parts[1])

def pause_to_str(cmd_parts, node, next_ids, res):
    res['nodes'][id(node)] = {
        'class_name': 'Pause',
        'arguments': [
            next_ids
        ]
    }

