# --- Random Example Generators ---
_random_generators: dict[type, callable] = {}


def _register_example(func):
    """Decorator to register a function as an example generator for its return type."""
    try:
        hints = typing.get_type_hints(func)
        ret_type = hints['return']
        if ret_type is not NoneType:
            _random_generators[ret_type] = func
    except KeyError:
        pass
    return func


@_register_example
def _sample_integer(_ctx) -> int:
    return random.randint(1, 100)


@_register_example
def _sample_float(_ctx) -> float:
    raw = f"{random.randint(1, 100)}.{random.randint(0, 99)}"
    val = float(raw)
    return int(val) if val.is_integer() else val


@_register_example
def _sample_boolean(_ctx) -> bool:
