# --- Static Examples Handling ---
_DEFAULT_TEXT = "Lorem ipsum dolor sit amet."


class _StaticExampleLoader:
    def __init__(self):
        self._data = {}

    def load(self):
        try:
            with open('data/arg_examples.json', encoding='utf-8') as f:
                self._data.update(json.load(f))
        except Exception as exc:
            logging.getLogger(__name__).error("Failed to load static examples", exc_info=exc)

    def get(self, key, fallback=None):
        return self._data.get(key, fallback)


_static_loader = _StaticExampleLoader()
_static_loader.load()


def _fetch_static_example(param_name: str, command_obj=None) -> str:
    candidates = []
    if command_obj:
        candidates.append(f"{command_obj.qualified_name}.{param_name}")
    candidates.append(param_name)

    for key in candidates:
        examples = _static_loader.get(key)
        if examples is None:
            continue
        if isinstance(examples, list):
            return random.choice(examples)
        return examples
    return _DEFAULT_TEXT


def _resolve_command_for_help(ctx) -> commands.Command:
    cmd = ctx.command
    return ctx.kwargs.get('command', cmd) if cmd.name == 'help' else cmd


@_register_example
def _sample_string(ctx) -> str:
    param = getattr(ctx, '_current_parameter', None)
    name = param.name if param else ''
    cmd = _resolve_command_for_help(ctx)
    return _fetch_static_example(name, cmd)


# --- Utility Functions ---
def _get_object_name(obj):
    return getattr(obj, '__name__', type(obj).__name__)


def _is_discord_converter(converter):
    mod = getattr(converter, '__module__', '')
    return mod.startswith('discord.') and mod.endswith('.converter')


def _ensure_class_type(obj):
    return obj if isinstance(obj, type) else type(obj)


def _format_annotation(annotation, base_module=None):
    if getattr(annotation, '__module__', None) == 'typing':
        return repr(annotation).replace('typing.', '')
    if isinstance(annotation, type):
        if annotation.__module__ in ('builtins', base_module):
            return annotation.__qualname__
        return f'{annotation.__module__}.{annotation.__qualname__}'
    return repr(annotation)


# --- Core Logic ---

def get_example(converter, ctx):
    """Returns a random example value for the given converter."""
    # Custom random_example override?
    if hasattr(converter, 'random_example'):
        return converter.random_example(ctx)

    # Handle Union types
    origin = getattr(converter, '__origin__', None)
    if origin is typing.Union:
        args = converter.__args__
        if len(args) == 2 and args[-1] is NoneType:
            converter = args[0]
        else:
            converter = random.choice(args)
        return get_example(converter, ctx)

    # Resolve Discord converters
    if _is_discord_converter(converter):
        cls_name = _get_object_name(converter).replace('Converter', '')
        if cls_name == 'CleanContent':
            converter = str
        else:
            converter = getattr(discord, cls_name, str)

    # Lookup registered generator
    try:
        generator = _random_generators[converter]
    except KeyError:
        raise ValueError(f"No example generator available for {_format_annotation(converter)}")
    return generator(ctx)


# --- Wrappers & Decorators ---
def wrap_example(target):
    """Decorator to assign a custom example generator to a converter."""
    def decorator(func):
        target.random_example = func
        return func
    return decorator


def static_example(converter):
    """Assigns static example generation to a converter."""
    converter.random_example = _sample_string
    return converter


# --- Example Formatting Helpers ---
_QUOTE_CHARS = tuple(commands.view._all_quotes)
_QUOTE_PATTERN = '|'.join(map(re.escape, _QUOTE_CHARS))
_QUOTE_REGEX = re.compile(rf'\\(.)|({_QUOTE_PATTERN})')
_ESCAPE_QUOTES = lambda s: _QUOTE_REGEX.sub(r'\\\1\2', s)


def _quote_if_needed(text: str) -> str:
    escaped = _ESCAPE_QUOTES(text)
    if any(c.isspace() for c in escaped):
        return f'"{escaped}"'
    return escaped


def _is_required_param(param):
    return (
        param.default is param.empty and
        param.kind is not param.VAR_POSITIONAL
    )


_MAX_VARARGS_REPETITIONS = 4


def _generate_single_example(param, ctx, command):
    ctx._current_parameter = param
    conv = commands.Command._get_converter(None, param)
    raw_val = str(get_example(conv, ctx))

    # Skip quoting for keyword-only when rest_is_raw or special prefixes
    skip_quote = (
        param.kind is param.KEYWORD_ONLY and
        (not command.rest_is_raw or raw_val.startswith(('#', '@')))
    )
    return raw_val if skip_quote else _quote_if_needed(raw_val)


def _expand_var_positional(params, ctx, command):
    for param in params:
        yield _generate_single_example(param, ctx, command)
        if param.kind is param.VAR_POSITIONAL:
            min_reps = varpos.requires_var_positional(param)
            extra_reps = random.randint(min_reps, _MAX_VARARGS_REPETITIONS)
            for _ in range(extra_reps):
                yield _generate_single_example(param, ctx, command)


def _partition_params(command):
    clean_params = list(command.clean_params.values())
    required = list(itertools.takewhile(_is_required_param, clean_params))
    optional = []
    remaining = itertools.dropwhile(_is_required_param, clean_params)
    for p in remaining:
        if p.kind is p.VAR_POSITIONAL:
            group = required if varpos.requires_var_positional(command) else optional
            group.append(p)
            break
        optional.append(p)
        if p.kind is p.KEYWORD_ONLY:
            break
    return required, optional


def command_example(command, ctx):
    """Generate usage examples for a command."""
    qualified_names = list(all_qualified_names(command))
    required, optional = _partition_params(command)

    def build_example(params):
        parts = list(_expand_var_positional(params, ctx, command))
        resolved = ' '.join(parts)
        chosen_name = random.choice(qualified_names)
        return f'`{ctx.clean_prefix}{chosen_name} {resolved}`'

    base_usage = build_example(required)
    if not optional:
        return base_usage

    incremental = [
        build_example(required + optional[:i+1])
        for i in range(len(optional))
    ]
    return '\n'.join([base_usage] + incremental)

# Clone a run with optional content override and status handling utilities

from rest_framework import status
from rest_framework.exceptions import ValidationError
from rest_framework.response import Response
import ujson
from coredb.managers.statuses import new_run_status
from polyaxon.lifecycle import LifeCycle, V1StatusCondition, V1Statuses


def duplicate_run(view, request, *args, **kwargs):
    # Retrieve and validate the original run
    view.run = view.get_object()
    view.pre_validate(view.run)

    # Extract and parse optional content payload
    payload = None
    if "content" in request.data:
        payload = request.data["content"]

    if payload and not isinstance(payload, dict):
        try:
            payload = ujson.loads(payload)
        except Exception as err:
            raise ValidationError("Failed to clone run: {}".format(err))

    # Perform cloning operation
    try:
        cloned_obj = view.clone(obj=view.run, content=payload)
    except Exception as err:
        raise ValidationError("Cloning failed: {}".format(err))

    # Record audit log and serialize response
    view.audit(request, *args, **kwargs)
    serializer = view.get_serializer(cloned_obj)
    return Response(status=status.HTTP_201_CREATED, data=serializer.data)


def establish_status(view, serializer):
    # Validate incoming data and apply condition if present
    serializer.is_valid(raise_exception=False)
    validated_data = serializer.validated_data

    if not validated_data:
        return

    condition = None
    if "condition" in validated_data and validated_data["condition"]:
        condition = V1StatusCondition.get_condition(**validated_data["condition"])

    if condition:
        new_run_status(run=view.run, condition=condition)


def terminate_run(view, request, *args, **kwargs):
    # Skip if run is already in terminal state
    if LifeCycle.is_done(view.run.status):
        return Response(status=status.HTTP_200_OK, data={})

    # Create stopping condition
    condition = V1StatusCondition.get_condition(
        type=V1Statuses.STOPPING,
        status="True",
        reason="PolyaxonRunStopping",
        message="User requested to stop the run.",
    )

    # Apply new status and record audit
    new_run_status(run=view.run, condition=condition)
    view.audit(request, *args, **kwargs)
    return Response(status=status.HTTP_200_OK, data={})

