def init(ctx, project_title, **kwargs):
    """Initialize a new Rony project.

    Args:
        project_title (str): Desired name for the project
        kwargs (dict): Command-line flags and options
    """
    # Determine required modules
    needed_modules = get_modules_to_add("new", kwargs, ctx)
