        "project_start_date": datetime.today().strftime("%B %d, %Y"),
    }

    # Apply each module in order (preserving duplicates' first occurrence order)
    seen = set()
    unique_modules = []
    for mod in needed_modules:
        if mod not in seen:
            seen.add(mod)
            unique_modules.append(mod)

    for module_id in unique_modules:
        write_module(
            full_path,
            module_id,
            True,
            shared_params,
