def apply_recursive_permissions(target_path, permission_bits):
    """Recursively set file/directory permissions."""
    for root, dirs, files in os.walk(target_path):
        os.chmod(root, permission_bits)
        for fname in files:
            os.chmod(os.path.join(root, fname), permission_bits)

