# Global state for MID configuration and alarm authentication
mid_credentials = {}
alarm_secret = None

def setup():
    global mid_credentials, alarm_secret
    config_row = util.getRowFromTableById("general_config", 1, columns="mid_pass,enabled_p,alarms_pass")

    # Extract configuration values
    mid_credentials["password"] = config_row.get("mid_pass")
    mid_credentials["is_active"] = config_row.get("enabled_p")

    # Set alarm secret if present in config
    if "alarms_pass" in config_row:
        alarm_secret = config_row["alarms_pass"]

setup()

def reject_request():
    # response.header['WWW-Authenticate'] = 'Basic realm="isadore"'
    raise HTTPError(401, 'Unauthorized')

def fetch_user(required_permission):
    email, password_hash = request.auth or (None, None)
    user_account = None

    # Try to get user from cookie if not authenticated via header
    if not user_account:
        if not email or not password_hash:
            email = request.get_cookie("exemail")
            password_hash = request.get_cookie("exrhash")
        user_account = util.getAccount(email, password_hash)

    # Validate user has required permission
    if not user_account or not user_account.has_privilege(required_permission):
        if user_account and not user_account.has_privilege(required_permission):
            logging.debug('DEBUG: Access denied: missing privilege %s', (required_permission,))
        reject_request()

    return user_account

def require_permission(permission_level):
    """
    Decorator ensures the requesting user has the specified permission level.
    If not, triggers authentication challenge or access denial.
    """
    def decorator(handler_func):
        def secured_handler(*args, **kwargs):
            request.user = fetch_user(permission_level)
            return handler_func(*args, **kwargs)
        return secured_handler
    return decorator

def alarm_access_check(access_level):
    """
    Decorator checks for alarm-specific passcode. Falls back to standard auth if missing/invalid.
    """
    def decorator(handler_func):
        def secured_handler(*args, **kwargs):
            provided_alarm_token = request.params.get('alarms_pass')
            if not alarm_secret or alarm_secret != provided_alarm_token:
                request.user = fetch_user(access_level)
            return handler_func(*args, **kwargs)
        return secured_handler
    return decorator

def mid_access_control():
    """
    Decorator enforces MID-specific authentication using query parameter.
    Blocks requests if MID is disabled or wrong password provided.
    """
    def decorator(handler_func):
        def secured_handler(*args, **kwargs):
            provided_mid_token = request.params.get('mid_pass')
            if not mid_credentials["is_active"] or provided_mid_token != mid_credentials["password"]:
                reject_request()
            return handler_func(*args, **kwargs)
        return secured_handler
    return decorator

def alarm_authentication():
    """
    Decorator validates alarm system access token.
    Rejects request if token is missing or incorrect.
    """
    def decorator(handler_func):
        def secured_handler(*args, **kwargs):
            provided_alarm_token = request.params.get('alarms_pass')
            if not alarm_secret or alarm_secret != provided_alarm_token:
                reject_request()
            return handler_func(*args, **kwargs)
        return secured_handler
    return decorator

