# Generate padded graph tuples for model input

import time
import os
import itertools
import random
import numpy as np
import tensorflow as tf
from graph_nets import utils_tf
from graph_nets import graphs

# Field types mapping
FIELD_DTYPE_MAP = {
    'n_node': tf.int32,
    'n_edge': tf.int32,
    'nodes': tf.float32,
    'edges': tf.float32,
    'receivers': tf.int32,
    'senders': tf.int32,
    'globals': tf.float32,
}

# Optional additional features (currently unused)
EXTRA_FEATURES = {}


def pad_graph(g, max_nodes, max_edges, combine=True):
    """
    Pads a graph up to specified maximum node/edge counts.
    Returns either just the padding or concatenated full graph.
    """
    dtype_float = np.float32
    total_nodes = int(tf.reduce_sum(g.n_node))
    total_edges = int(tf.reduce_sum(g.n_edge))

    if max_nodes < total_nodes:
        raise ValueError(f"Requested max_nodes={max_nodes}, but graph has {total_nodes} nodes.")
    if max_edges < total_edges:
        raise ValueError(f"Requested max_edges={max_edges}, but graph has {total_edges} edges.")

    pad_nodes = max_nodes - total_nodes
    pad_edges = max_edges - total_edges

    # Edge padding: dummy edges pointing to node 0
    dummy_edge_idx = tf.zeros([pad_edges], dtype=tf.int32)

    # Compute feature dimensions
    node_feat_dim = g.nodes.shape[-1].value if g.nodes.shape.rank > 1 else 0
    edge_feat_dim = g.edges.shape[-1].value if g.edges.shape.rank > 1 else 0

    # Prepare padding data dict
    pad_data = {
        "n_node": pad_nodes,
        "n_edge": pad_edges,
        "nodes": np.zeros((pad_nodes, node_feat_dim), dtype=dtype_float),
        "edges": np.zeros((pad_edges, edge_feat_dim), dtype=dtype_float),
        "receivers": dummy_edge_idx.numpy(),
        "senders": dummy_edge_idx.numpy(),
        "globals": np.array([0.0], dtype=dtype_float)
    }

    pad_graph_obj = utils_tf.data_dicts_to_graphs_tuple([pad_data])

    if combine:
        return utils_tf.concat([g, pad_graph_obj], axis=0)
    else:
        return pad_graph_obj


def distribute_edges_across_devices(input_graph, num_devices, verbose=False):
    """
    Distribute edges evenly across multiple devices.
    Each device gets roughly equal number of edges.
    """
    def extract_subgraph(full_graph, edge_indices):
        new_edges = tf.gather(full_graph.edges, edge_indices)
        new_receivers = tf.gather(full_graph.receivers, edge_indices)
        new_senders = tf.gather(full_graph.senders, edge_indices)
        return full_graph.replace(
            n_edge=tf.constant([len(edge_indices)], dtype=tf.int32),
            edges=new_edges,
            receivers=new_receivers,
            senders=new_senders
        )

    total_edges = int(tf.reduce_sum(input_graph.n_edge))
    total_nodes = int(tf.reduce_sum(input_graph.n_node))

    subgraphs = []
    base_size = total_edges // num_devices

    if verbose:
        print(f"Total {total_edges:,} edges → split into {num_devices} devices ({base_size:,} per device)")

    for dev_id in range(num_devices):
        start_idx = dev_id * base_size
        end_idx = total_edges if dev_id == num_devices - 1 else (dev_id + 1) * base_size
        idx_list = list(range(start_idx, end_idx))
        subgraphs.append(extract_subgraph(input_graph, idx_list))

    return subgraphs


def decode_example(example_proto):
    """Parse serialized TFRecord example into input/output graph tuples."""
    all_fields = list(graphs.ALL_FIELDS)
    feature_map = {}
    for field in all_fields:
        feature_map[field + "_IN"] = tf.io.FixedLenFeature([], tf.string)
        feature_map[field + "_OUT"] = tf.io.FixedLenFeature([], tf.string)

    parsed = tf.io.parse_single_example(example_proto, feature_map)

    def make_graph(field_name, key_suffix):
        tensor_val = tf.io.parse_tensor(parsed[field_name + key_suffix], FIELD_DTYPE_MAP[field_name])
        return getattr(graphs.GraphsTuple, field_name).property_type(tensor_val)

    input_dict = {f: make_graph(f, "_IN") for f in all_fields}
    output_dict = {f: make_graph(f, "_OUT") for f in all_fields}

    return graphs.GraphsTuple(**input_dict), graphs.GraphsTuple(**output_dict)


def encode_tensor_as_bytes(tensor):
    """Convert tensor to bytes for serialization."""
    if isinstance(tensor, tf.Tensor) and hasattr(tensor, 'numpy'):
        tensor = tensor.numpy()
    return tf.train.Feature(bytes_list=tf.train.BytesList(value=[tensor.tobytes()]))


def pack_graph_pair(G_in, G_out):
    """Serialize two graphs (input & target) into a single Example proto."""
    features = {}
    for field in graphs.ALL_FIELDS:
        in_tensor = getattr(G_in, field)
        out_tensor = getattr(G_out, field)
        features[field + "_IN"] = encode_tensor_as_bytes(tf.io.serialize_tensor(in_tensor))
        features[field + "_OUT"] = encode_tensor_as_bytes(tf.io.serialize_tensor(out_tensor))

    example = tf.train.Example(features=tf.train.Features(feature=features))
    return example.SerializeToString()


def merge_batch_dimension(G):
    """
    Flatten batched graph tensors into single graph.
    Assumes batch size is 1; reshapes accordingly.
    """
    flat_n_node = tf.reshape(G.n_node, [-1])
    flat_n_edge = tf.reshape(G.n_edge, [-1])
    flat_nodes = tf.reshape(G.nodes, [-1, G.nodes.shape[-1]])
    flat_edges = tf.reshape(G.edges, [-1, G.edges.shape[-1]])
    flat_senders = tf.reshape(G.senders, [-1])
    flat_receivers = tf.reshape(G.receivers, [-1])
    flat_globals = tf.reshape(G.globals, [-1, G.globals.shape[-1]])

    return G.replace(
        n_node=flat_n_node,
        n_edge=flat_n_edge,
        nodes=flat_nodes,
        edges=flat_edges,
        senders=flat_senders,
        receivers=flat_receivers,
        globals=flat_globals
    )


def unbatch_graphs(G):
    """
    Split a batched graph tuple into individual graphs.
    Only supports batch size 2 for demonstration.
    """
    result = []
    for b in range(2):
        dd = {
            "nodes": G.nodes[b],
            "edges": G.edges[b],
            "receivers": G.receivers[b],
            "senders": G.senders[b],
            "globals": G.globals[b],
            "n_node": G.n_node[b],
            "n_edge": G.n_edge[b],
        }
        result.append(graphs.GraphsTuple(**dd))
    return utils_tf.concat(result, axis=0)


def add_batch_axis(G, axis=0):
    """
    Insert a new dimension at given axis for batch processing.
    Uses stacking instead of expand_dims for robustness.
    """
    fields = ['n_node', 'n_edge', 'nodes', 'edges', 'senders', 'receivers', 'globals']
    stacked = {}
    for f in fields:
        val = getattr(G, f)
        if f in ['n_node', 'n_edge']:
            stacked[f] = tf.stack([val], axis=axis)
        elif f in ['senders', 'receivers']:
            stacked[f] = tf.expand_dims(val, axis=axis)
        else:
            stacked[f] = tf.stack([val], axis=axis)
    return G.replace(**stacked)


def prepare_graph_batch(input_dd, target_dd, include_batch=True):
    """
    Convert lists of data dicts into batched graph tuples.
    Handles both single and multi-sample cases.
    """
    if not isinstance(input_dd, list):
        input_dd = [input_dd]
    if not isinstance(target_dd, list):
        target_dd = [target_dd]

    batched_inputs = utils_tf.concat(input_dd, axis=0)
    batched_targets = utils_tf.concat(target_dd, axis=0)

    if include_batch:
        batched_inputs = add_batch_axis(batched_inputs)
        batched_targets = add_batch_axis(batched_targets)

    return batched_inputs, batched_targets


def infer_signature(graph_sample):
    """
    Build type signature for a GraphsTuple under distributed strategy.
    """
    field_specs = {}
    for fname in graphs.ALL_FIELDS:
        sample_val = getattr(graph_sample, fname)

        def tensor_spec_from(v):
            shape = list(v.shape)
            dt = v.dtype
            if len(shape) > 1:
                shape[1] = None
            return tf.TensorSpec(shape=shape, dtype=dt)

        field_specs[fname] = tf.distribute.values.PerReplicaSpec(
            *(tensor_spec_from(v) for v in sample_val.values)
        )
    return graphs.GraphsTuple(**field_specs)


def build_graph_specs(
    graph_example,
    add_batch=False,
    allow_var_num_graphs=False,
    allow_var_nodes=True,
    allow_var_edges=True,
    spec_builder=tf.TensorSpec
):
    """
    Construct TensorSpec for each field in GraphsTuple.
    Supports dynamic shapes based on flags.
    """
    specs = {}
    edge_fields = {graphs.EDGES, graphs.SENDERS, graphs.RECEIVERS}

    for field in graphs.ALL_FIELDS:
        field_val = getattr(graph_example, field)
        if field_val is None:
            raise ValueError(f"Field '{field}' must be non-None to define spec.")

        shape = list(field_val.shape)
        dtype = field_val.dtype

        if shape:
            if add_batch:
                shape[1] = None
            elif allow_var_num_graphs or \
                 (allow_var_nodes and field == graphs.NODES) or \
                 (allow_var_edges and field in edge_fields):
                shape[0] = None

        specs[field] = spec_builder(shape=shape, dtype=dtype)

    return graphs.GraphsTuple(**specs)


def get_graph_dtypes_and_shapes(graph_input, no_padding=False, with_batch=False, fixed_size=False):
    """
    Extract dtypes and static/dynamic shapes from a GraphsTuple.
    Optionally allows variable-length dimensions.
    """
    dtypes = {}
    shapes = {}

    edge_fields = {graphs.EDGES, graphs.SENDERS, graphs.RECEIVERS}

    for field in graphs.ALL_FIELDS:
        val = getattr(graph_input, field)
        shape = list(val.shape)
        dtype = val.dtype

        if shape and not fixed_size and not no_padding:
            if with_batch:
                shape[1] = None
            elif field == graphs.NODES or field in edge_fields:
                shape[0] = None

        dtypes[field] = dtype
        shapes[field] = tf.TensorShape(shape)

    return graphs.GraphsTuple(**dtypes), graphs.GraphsTuple(**shapes)


def load_tfrecord_dataset(file_pattern, events_per_file=5000):
    """
    Load dataset from TFRecord files matching pattern.
    Returns dataset object and estimated total number of examples.
    """
    AUTO = tf.data.experimental.AUTOTUNE
    file_list = tf.io.gfile.glob(file_pattern)
    num_files = len(file_list)

    ds = tf.data.TFRecordDataset(file_list)
    ds = ds.map(decode_example, num_parallel_calls=AUTO)

    total_events = num_files * events_per_file
    return ds, total_events


def iterate_in_batches(dataset_pairs, batch_limit):
    """
    Yield batches of (input_graphs, target_graphs).
    Aggregates samples until batch_limit is reached.
    """
    if batch_limit <= 0:
        for pair in dataset_pairs:
            yield pair
        return

    inputs_buffer = []
    targets_buffer = []

    for inp, tgt in dataset_pairs:
        inputs_buffer.append(inp)
        targets_buffer.append(tgt)

        if len(inputs_buffer) == batch_limit:
            yield (
                utils_tf.concat(inputs_buffer, axis=0),
                utils_tf.concat(targets_buffer, axis=0)
            )
            inputs_buffer.clear()
            targets_buffer.clear()

from dataclasses import dataclass
from typing import Dict, List
from ..features import ClassLabel, Features, Value
from .base import TaskTemplate

@dataclass(frozen=True)
class TextClassification(TaskTemplate):
    task = "text-classification"
    input_schema = Features({"text": Value("string")})
    label_schema = Features({"labels": ClassLabel})
    labels: List[str]
    text_column: str = "text"
    label_column: str = "labels"

    def __post_init__(self):
        # Ensure uniqueness of labels by comparing sorted list with its set version
        if len(set(self.labels)) != len(self.labels):
            raise ValueError("Labels must be unique")

        # Sort and store labels as a tuple for immutability and hashing
        sorted_labels = tuple(sorted(self.labels))
        object.__setattr__(self, "labels", sorted_labels)

        # Set column names explicitly (though already done via dataclass defaults)
        object.__setattr__(self, "text_column", self.text_column)
        object.__setattr__(self, "label_column", self.label_column)

        # Update label schema with actual class names
        self.label_schema["labels"] = ClassLabel(names=sorted_labels)

        # Build bidirectional mappings between labels and indices
        label2id = {}
        id2label = {}
        for idx, label in enumerate(sorted_labels):
            label2id[label] = idx
            id2label[idx] = label

        object.__setattr__(self, "label2id", label2id)
        object.__setattr__(self, "id2label", id2label)

    @property
    def column_mapping(self) -> Dict[str, str]:
        return {
            self.text_column: "text",
            self.label_column: "labels",
        }

    @classmethod
    def from_dict(cls, template_dict: dict) -> "TextClassification":
        return cls(
            text_column=template_dict.get("text_column", "text"),
            label_column=template_dict.get("label_column", "labels"),
            labels=template_dict["labels"],
        )

# Approximate Euler's number using iterative approach
# <NAME>
# 12 September 2020

def factorial(n: int) -> int:
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def approximate_euler(limit: int) -> float:
    e_value = 1.0
    for j in range(1, limit):
        e_value += 1.0 / factorial(j)
    return e_value

def main():
    euler_approx = approximate_euler(10)
    print(f"Euler's number approximation {euler_approx: .4f}")

if __name__ == "__main__":
    main()

# Music bot module using Discord.py and external libraries for audio streaming

import discord
from discord.ext import commands
import asyncio
import youtube_dl
import pafy
from datetime import datetime

class AudioPlayer(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.music_queue = {}
        self.initialize_queues()

    def initialize_queues(self):
        for server in self.bot.guilds:
            self.music_queue[server.id] = []

    async def process_next_track(self, ctx):
        if len(self.music_queue[ctx.guild.id]) > 0:
            ctx.voice_client.stop()
            await self.start_audio(ctx, self.music_queue[ctx.guild.id][0])
            self.music_queue[ctx.guild.id].pop(0)

    async def fetch_song_info(self, count, query, return_urls=False):
        ydl_opts = {"format": "bestaudio", "quiet": True}
        info = await self.bot.loop.run_in_executor(None, lambda: youtube_dl.YoutubeDL(ydl_opts).extract_info(
            f"ytsearch{count}:{query}", download=False, ie_key="YoutubeSearch"))

        if not info["entries"]:
            return None

        return [entry["webpage_url"] for entry in info["entries"]] if return_urls else info

    async def start_audio(self, ctx, track_url):
        audio_source = pafy.new(track_url).getbestaudio().url
        player = discord.PCMVolumeTransformer(discord.FFmpegPCMAudio(audio_source))
        ctx.voice_client.play(player, after=lambda err: self.bot.loop.create_task(self.process_next_track(ctx)))
        ctx.voice_client.source.volume = 0.5

    @commands.command(
        name="connect",
        description="Joins the voice channel you're in.",
        usage="connect",
        aliases=["join_vc"]
    )
    async def connect_to_channel(self, ctx):
        user_voice = ctx.author.voice

        if not user_voice:
            return await ctx.send("You need to be in a voice channel first!")

        target_channel = user_voice.channel

        if ctx.voice_client is None:
            await target_channel.connect()
            await ctx.send(f"✅ Connected to **{target_channel}**")
        else:
            if len(ctx.voice_client.channel.members) == 1:
                ctx.voice_client.stop()
                await ctx.voice_client.move_to(target_channel)
                await ctx.send(f"🔄 Moved to **{target_channel}**")
            else:
                await ctx.send("⚠️ Someone else is already listening.")

    @commands.command(
        name="leave",
        description="Leaves the current voice channel.",
        usage="leave",
        aliases=["disconnect_vc"]
    )
    async def leave_channel(self, ctx):
        voice = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("You must be in a voice channel to use this command.")
        elif not voice:
            return await ctx.send("I'm not currently in any voice channel.")

        if ctx.author.voice.channel == voice.channel:
            voice.stop()
            await voice.disconnect()
            await ctx.send(f"👋 Disconnected from **{voice.channel}**")
        else:
            if len(voice.channel.members) == 1:
                voice.stop()
                await voice.disconnect()
                await ctx.send(f"👋 Disconnected from **{voice.channel}**")
            else:
                await ctx.send("⚠️ Someone else is still listening.")

    @commands.command(
        name="play",
        description="Plays music from URL or search term.",
        usage="play <song/url>",
        aliases=["start_music"]
    )
    async def play_track(self, ctx, *, track=None):
        voice = ctx.voice_client

        if not track:
            return await ctx.send("❌ Please provide a song title or URL.")

        if not ctx.author.voice:
            return await ctx.send("❌ You need to join a voice channel first.")

        # Convert search terms to YouTube URLs
        if not ("youtube.com/watch?" in track or "youtu.be/" in track):
            urls = await self.fetch_song_info(1, track, return_urls=True)
            if not urls:
                return await ctx.send("❌ Could not find that song.")
            track = urls[0]

        voice_channel = ctx.author.voice.channel

        # Handle connection logic
        if not ctx.voice_client:
            await voice_channel.connect()
            await self.start_audio(ctx, track)
            return await ctx.send(f"🎵 Now playing: {track}")

        # If already connected
        if voice.source is not None:
            if ctx.author.voice.channel == voice.channel:
                queue_size = len(self.music_queue[ctx.guild.id])
                if queue_size < 10:
                    self.music_queue[ctx.guild.id].append(track)
                    return await ctx.send("➕ Song added to queue.")
                else:
                    return await ctx.send("🚫 Queue is full (max 10 songs).")
            else:
                if len(voice.channel.members) == 1:
                    voice.stop()
                    await voice.move_to(voice_channel)
                    await self.start_audio(ctx, track)
                    return await ctx.send(f"🎵 Now playing: {track}")
                else:
                    return await ctx.send("⚠️ Someone else is listening.")

        # Default play case
        if ctx.author.voice.channel == voice.channel:
            await self.start_audio(ctx, track)
            await ctx.send(f"🎵 Now playing: {track}")
        else:
            if len(voice.channel.members) == 1:
                voice.stop()
                await voice.move_to(voice_channel)
                await self.start_audio(ctx, track)
                await ctx.send(f"🎵 Now playing: {track}")
            else:
                await ctx.send("⚠️ Someone else is listening.")

    @commands.command(
        name="show_queue",
        description="Displays upcoming tracks.",
        usage="queue",
        aliases=["list_songs"]
    )
    async def show_queue(self, ctx):
        if not self.music_queue[ctx.guild.id]:
            return await ctx.send("🎵 No songs in the queue right now.")

        embed = discord.Embed(
            title="🎶 Up Next",
            description="\n".join(f"{i+1}. {url}" for i, url in enumerate(self.music_queue[ctx.guild.id])),
            timestamp=datetime.utcnow(),
            color=discord.Color.from_rgb(134, 36, 42)
        )
        embed.set_footer(text=f"Requested by {ctx.author}", icon_url=ctx.author.avatar.url)
        embed.set_thumbnail(url=self.bot.user.avatar.url)
        await ctx.send(embed=embed)

    @commands.command(
        name="skip",
        description="Votes to skip the current song.",
        usage="skip"
    )
    async def skip_song(self, ctx):
        voice = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("❌ You need to be in a voice channel first.")
        elif not voice:
            return await ctx.send("❌ I'm not in any voice channel.")

        if ctx.author.voice.channel != voice.channel:
            return await ctx.send("⚠️ You must be in the same voice channel as me.")

        # Create poll message
        poll = await ctx.send(
            "⏭️ Skip current song? Vote ✅ to skip, ❌ to keep playing.\n"
            "80% of listeners must vote to skip."
        )

        await poll.add_reaction("✅")
        await poll.add_reaction("❌")

        await asyncio.sleep(15)

        updated_poll = await ctx.channel.fetch_message(poll.id)
        vote_counts = {"✅": 0, "❌": 0}
        voters = set()

        for reaction in updated_poll.reactions:
            if reaction.emoji in ["✅", "❌"]:
                async for voter in reaction.users():
                    if (voter.voice and voter.voice.channel.id == voice.channel.id 
                        and voter.id not in voters and not voter.bot):
                        vote_counts[reaction.emoji] += 1
                        voters.add(voter.id)

        skip_allowed = False
        yes_votes = vote_counts["✅"]
        no_votes = vote_counts["❌"]

        if yes_votes > 0 and (no_votes == 0 or yes_votes / (yes_votes + no_votes) >= 0.8):
            skip_allowed = True
            await ctx.send("✅ Skipping the current song...")

        if not skip_allowed:
            await ctx.send("❌ Not enough votes to skip.")

        await poll.clear_reactions()

        if skip_allowed:
            voice.stop()
            await self.process_next_track(ctx)

    @commands.command(
        name="pause_music",
        description="Pauses the current track.",
        usage="pause"
    )
    async def pause_music(self, ctx):
        voice = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("❌ You need to be in a voice channel first.")
        elif not voice:
            return await ctx.send("❌ I'm not in any voice channel.")

        if ctx.author.voice.channel != voice.channel:
            return await ctx.send("⚠️ You must be in the same voice channel as me.")

        if voice.is_playing():
            voice.pause()
            await ctx.send("⏸️ Paused playback.")
        elif voice.is_paused():
            await ctx.send("⏸️ Already paused.")
        else:
            await ctx.send("ℹ️ Nothing is currently playing.")

    @commands.command(
        name="resume_music",
        description="Resumes paused playback.",
        usage="resume"
    )
    async def resume_music(self, ctx):
        voice = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("❌ You need to be in a voice channel first.")
        elif not voice:
            return await ctx.send("❌ I'm not in any voice channel.")

        if ctx.author.voice.channel != voice.channel:
            return await ctx.send("⚠️ You must be in the same voice channel as me.")

        if voice.is_paused():
            voice.resume()
            await ctx.send("▶️ Resumed playback.")
        elif voice.is_playing():
            await ctx.send("▶️ Already playing.")
        else:
            await ctx.send("ℹ️ Nothing is currently playing.")

    @commands.command(
        name="end_session",
        description="Stops playback and clears queue.",
        usage="stop"
    )
    async def end_session(self, ctx):
        voice = ctx.voice_client

        if not ctx.author.voice:
            return await ctx.send("❌ You need to be in a voice channel first.")
        elif not voice:
            return await ctx.send("❌ I'm not in any voice channel.")

        if ctx.author.voice.channel != voice.channel:
            return await ctx.send("⚠️ You must be in the same voice channel as me.")

        if voice.is_playing() or voice.is_paused():
            voice.stop()
            self.music_queue[ctx.guild.id].clear()
            await ctx.send("🛑 Playback stopped and queue cleared.")
        else:
            await ctx.send("ℹ️ Nothing is currently playing.")

def setup(bot):
    bot.add_cog(AudioPlayer(bot))

# Handle GCD and representation for different Python versions
import sys
from typing import Any

# Use math.gcd for Python 3+, fractions.gcd for Python 2 (with absolute value)
if sys.version_info[0] < 3:
    import fractions
    import re

    def gcd(a, b):
        # Ensure positive result regardless of input signs
        return abs(fractions.gcd(a, b))

    def proper_repr(value: Any) -> str:
        """Generate parseable string representations for special types."""
        if isinstance(value, sympy.Basic):
            # Get internal representation from sympy
            result = sympy.srepr(value)

            # Fix token names to be fully qualified
            fixed_tokens = ['Symbol', 'pi', 'Mul', 'Add', 'Integer', 'Float', 'Rational']
            for token in fixed_tokens:
                result = result.replace(token, f'sympy.{token}')

            # Fix Symbol representation for unicode compatibility
            result = re.sub(
                r'sympy\.Symbol\(([^u][^)]*)\)', 
                r'sympy.Symbol(u"\1")', 
                result
            )
            return result
        elif isinstance(value, np.ndarray):
            return f'np.array({value.tolist()!r})'
        else:
            return repr(value)
else:
    from math import gcd

    def proper_repr(value: Any) -> str:
        """Generate parseable string representations for special types."""
        if isinstance(value, sympy.Basic):
            # Get internal representation from sympy
            result = sympy.srepr(value)

            # Fix token names to be fully qualified
            fixed_tokens = ['Symbol', 'pi', 'Mul', 'Add', 'Integer', 'Float', 'Rational']
            for token in fixed_tokens:
                result = result.replace(token, f'sympy.{token}')

            return result
        elif isinstance(value, np.ndarray):
            return f'np.array({value.tolist()!r})'
        else:
            return repr(value)

