import os
from typing import Optional
from nornir_netmiko import netmiko_file_transfer, netmiko_send_command
from cnaas_nms.app_settings import api_settings
from cnaas_nms.scheduler.thread_data import set_thread_data
from cnaas_nms.tools.log import get_logger
from cnaas_nms.confpush.nornir_helper import cnaas_init, inventory_selector
from cnaas_nms.scheduler.wrapper import job_wrapper
from cnaas_nms.db.session import sqla_session
from cnaas_nms.confpush.nornir_helper import NornirJobResult
from cnaas_nms.db.device import Device
from cnaas_nms.tools.pki import generate_device_cert

class CertificateTransferError(Exception):
    pass

def transfer_arista_certificate(task, job_id: Optional[str] = None) -> str:
    set_thread_data(job_id)
    log = get_logger()
    try:
        private_key_path = os.path.join(api_settings.CERTPATH, "{}.key".format(task.host.name))
        certificate_path = os.path.join(api_settings.CERTPATH, "{}.crt".format(task.host.name))
    except AttributeError:
        raise Exception("Certificate path configuration missing in api.yml")
    except Exception as err:
        raise Exception("Failed to locate certificate files for device {}: {}".format(
            task.host.name, str(err)
        ))

    if not os.path.isfile(private_key_path):
        raise Exception("Private key file '{}' does not exist".format(private_key_path))
    if not os.path.isfile(certificate_path):
        raise Exception("Certificate file '{}' does not exist".format(certificate_path))

    connection = task.host.get_connection("netmiko", task.nornir.config)
    connection.fast_cli = False

    # Transfer private key
    key_result = task.run(
        netmiko_file_transfer,
        source_file=private_key_path,
        dest_file="cnaasnms.key",
        file_system="/mnt/flash",
        overwrite_file=True
    )
    if key_result.failed:
        log.exception(key_result.exception)

    # Transfer certificate
    cert_result = task.run(
        netmiko_file_transfer,
        source_file=certificate_path,
        dest_file="cnaasnms.crt",
        file_system="/mnt/flash",
        overwrite_file=True
    )
    if cert_result.failed:
        log.exception(cert_result.exception)

    if key_result.failed or cert_result.failed:
        raise CertificateTransferError("Failed to transfer certificate files to device: {}".format(task.host.name))
    else:
        log.debug("Certificate files successfully transferred to device: {}".format(task.host.name))

    install_commands = [
        "copy flash:cnaasnms.crt certificate:",
        "copy flash:cnaasnms.key sslkey:",
        "delete flash:cnaasnms.key",
        "delete flash:cnaasnms.crt"
    ]

    for command in install_commands:
        certstore_result = task.run(
            netmiko_send_command,
            command_string=command,
            enable=True
        )
        if certstore_result.failed:
            log.error(
                "Command '{}' failed on device {}: {}".format(
                    command, task.host.name, certstore_result.result
                ))
            raise CertificateTransferError("Failed to install certificate on device: {}".format(task.host.name))

    log.debug("Certificate successfully installed in certstore on device: {}".format(task.host.name))
    return "Certificate transfer completed successfully"

def renew_host_certificate(task, job_id: str) -> str:
    set_thread_data(job_id)
    log = get_logger()

    with sqla_session() as db_session:
        device_record: Device = db_session.query(Device). \
            filter(Device.hostname == task.host.name).one_or_none()
        management_ip = device_record.management_ip
        if not management_ip:
            raise Exception("Device {} lacks a management IP address".format(task.host.name))

    try:
        generate_device_cert(task.host.name, ipv4_address=management_ip)
    except Exception as gen_err:
        raise Exception("Could not generate certificate for device {}: {}".format(
            task.host.name, str(gen_err)
        ))

    if task.host.platform == "eos":
        try:
            result = task.run(task=transfer_arista_certificate, job_id=job_id)
        except Exception as transfer_err:
            log.exception("Error during certificate transfer: {}".format(str(transfer_err)))
            raise transfer_err
    else:
        raise ValueError("Platform '{}' is not supported for certificate renewal".format(task.host.platform))

    return "Certificate renewal completed for device {}".format(task.host.name)

@job_wrapper
def execute_certificate_renewal(hostname: Optional[str] = None,
                                group_name: Optional[str] = None,
                                job_id: Optional[str] = None,
                                initiating_user: Optional[str] = None) -> NornirJobResult:
    log = get_logger()
    nr = cnaas_init()

    if hostname:
        filtered_inventory, device_count, _ = inventory_selector(nr, hostname=hostname)
    elif group_name:
        filtered_inventory, device_count, _ = inventory_selector(nr, group=group_name)
    else:
        raise ValueError("Either hostname or group must be specified for certificate renewal")

    target_devices = list(filtered_inventory.inventory.hosts.keys())
    log.info("Selected {} device(s) for certificate renewal: {}".format(
        device_count, ", ".join(target_devices)
    ))

    allowed_platforms = ['eos']

    # Validate devices and platforms
    for dev_hostname in target_devices:
        with sqla_session() as db_session:
            device: Device = db_session.query(Device). \
                filter(Device.hostname == dev_hostname).one_or_none()
            if not device:
                raise Exception('Device {} not found in database'.format(dev_hostname))
            if device.platform not in allowed_platforms:
                raise Exception('Device {} has unsupported platform "{}"'.format(
                    dev_hostname, device.platform))

    try:
        execution_result = filtered_inventory.run(task=renew_host_certificate, job_id=job_id)
    except Exception as runtime_err:
        log.exception("Runtime error during certificate renewal: {}".format(str(runtime_err)))
        return NornirJobResult(nrresult=execution_result)

    problematic_hosts = list(execution_result.failed_hosts.keys())
    for host in problematic_hosts:
        log.error("Certificate renewal failed on device: {}".format(host))

    if execution_result.failed:
        log.warning("Some devices failed certificate renewal")

    return NornirJobResult(nrresult=execution_result)

