import streamlit as st
import spacy
from textblob import TextBlob

# Replacing sumy imports with safe fallbacks or alternative logic
try:
    from sumy.nlp.tokenizers import Tokenizer
    from sumy.summarizers.lex_rank import LexRankSummarizer
    SUMY_AVAILABLE = True
except ImportError:
    SUMY_AVAILABLE = False

def tokenize_and_lemmatize(text):
    """
    Process input text using spaCy to extract tokens and their lemmas.
    Returns a list of formatted strings for display.
    """
    nlp_model = spacy.load('en_core_web_sm')
    processed_doc = nlp_model(text)

    token_lemma_pairs = []
    for token in processed_doc:
        pair = f"Token: {token.text}, Lemma: {token.lemma_}"
        token_lemma_pairs.append(pair)
    return token_lemma_pairs

def extract_entities(text):
    """
    Extract named entities and their labels from input text using spaCy.
    Returns a list containing tokens and entity information.
    """
    nlp_model = spacy.load('en_core_web_sm')
    doc = nlp_model(text)

    tokens_list = [tok.text for tok in doc]
    entities_list = [(ent.text, ent.label_) for ent in doc.ents]

    return [f"Tokens: {tokens_list}\nEntities: {entities_list}"]

def generate_summary_lexrank(input_text, sentence_count=3):
    """
    Generate a summary using LexRank summarization via sumy.
    Falls back gracefully if sumy is not available.
    """
    if not SUMY_AVAILABLE:
        return "⚠️ Sumy library not installed. Please install 'sumy' to enable summarization."

    try:
        parser = type('MockParser', (), {
            'document': type('MockDoc', (), {
                'sentences': lambda: list(TextBlob(input_text).sentences)
            })()
        })()

        # Fallback: use TextBlob sentences if needed
        sentences = list(TextBlob(input_text).sentences)
        if len(sentences) == 0:
            sentences = [input_text]

        # Simulate parser.document structure expected by LexRankSummarizer
        class MockDocument:
            def __init__(self, sents):
                self.sentences = sents

        mock_parser = type('MockParser', (), {'document': MockDocument(sentences)})()

        summarizer = LexRankSummarizer()
        summary_sentences = summarizer(mock_parser.document, sentence_count)
        summary_text = ' '.join([str(s) for s in summary_sentences])
        return summary_text
    except Exception as e:
        return f"❌ Error during summarization: {str(e)}"

def main():
    st.title("Natural Language Processing Tool")
    st.markdown("Explore NLP features directly in your browser.")

    # --- Token & Lemma Section ---
    if st.checkbox("Show Tokens & Lemmas"):
        st.subheader("Tokenization & Lemmatization")
        user_text = st.text_area("Enter your text here:", placeholder="Type something...")
        if st.button("Process"):
            output = tokenize_and_lemmatize(user_text) if user_text else ["No input provided."]
            st.json(output)

    # --- Named Entity Recognition Section ---
    if st.checkbox("Identify Named Entities"):
        st.subheader("Named Entity Recognition")
        user_text = st.text_area("Enter text to extract entities:", placeholder="Type something...")
        if st.button("Extract Entities"):
            output = extract_entities(user_text) if user_text else ["No input provided."]
            st.json(output)

    # --- Sentiment Analysis Section ---
    if st.checkbox("Analyze Sentiment"):
        st.subheader("Sentiment Scoring")
        user_text = st.text_area("Enter text to analyze sentiment:", placeholder="Type something...")
        if st.button("Compute Sentiment"):
            if user_text:
                blob = TextBlob(user_text)
                sentiment_result = {
                    "polarity": round(blob.sentiment.polarity, 3),
                    "subjectivity": round(blob.sentiment.subjectivity, 3)
                }
                st.success(f"Polarity: {sentiment_result['polarity']}, Subjectivity: {sentiment_result['subjectivity']}")
            else:
                st.warning("Please enter some text first.")

    # --- Text Summarization Section (Revised) ---
    if st.checkbox("Summarize Text"):
        st.subheader("Automatic Summarization")
        user_text = st.text_area("Enter long text to summarize:", placeholder="Paste your article or paragraph here...")
        num_sentences = st.slider("Number of summary sentences", min_value=1, max_value=5, value=3)

        if st.button("Generate Summary"):
            if user_text:
                summary = generate_summary_lexrank(user_text, num_sentences)
                st.write(summary)
            else:
                st.info("Please provide text to summarize.")

if __name__ == "__main__":
    main()

# Type III Clone: HomeAssistanceForm with modified control flow and logic structure

from typing import Any, Dict, List, Optional, Text, Union
from rasa_sdk import Tracker
from rasa_sdk.events import EventType
from rasa_sdk.executor import CollectingDispatcher
from rasa_sdk.forms import FormAction
from covidflow.constants import HAS_ASSISTANCE_SLOT, PROVINCE_SLOT, PROVINCES_WITH_211
from .form_helper import request_next_slot, validate_boolean_slot, yes_no_nlu_mapping
from .lib.log_util import bind_logger

FORM_NAME = "home_assistance_form"

def _supports_211_service(tracker: Tracker) -> bool:
    # Renamed function and variable for semantic clarity
    current_province = tracker.get_slot(PROVINCE_SLOT)
    return current_province in PROVINCES_WITH_211

class HomeAssistanceForm(FormAction):
    def name(self) -> Text:
        return FORM_NAME

    async def run(
        self, dispatcher, tracker, domain,
    ):
        bind_logger(tracker)
        return await super().run(dispatcher, tracker, domain)

    @staticmethod
    def required_slots(tracker: Tracker) -> List[Text]:
        # Changed conditional logic to use early return pattern
        if not _supports_211_service(tracker):
            return []
        return [HAS_ASSISTANCE_SLOT]

    def slot_mappings(self) -> Dict[Text, Union[Dict, List[Dict]]]:
        return {
            HAS_ASSISTANCE_SLOT: yes_no_nlu_mapping(self),
        }

    def request_next_slot(
        self,
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> Optional[List[EventType]]:
        return request_next_slot(self, dispatcher, tracker, domain, None)

    @validate_boolean_slot
    def validate_has_assistance(
        self,
        value: Union[bool, Text],
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> Dict[Text, Any]:
        return {}

    def submit(
        self,
        dispatcher: CollectingDispatcher,
        tracker: Tracker,
        domain: Dict[Text, Any],
    ) -> List[Dict]:
        # Restructured conditional logic using inverted conditionals and helper variables
        needs_211_support = _supports_211_service(tracker)
        has_assistance = tracker.get_slot(HAS_ASSISTANCE_SLOT)

        if needs_211_support and not has_assistance:
            dispatcher.utter_message(template="utter_check_delivery_services")

            # Replaced ternary-style branching with explicit if-else
            province_value = tracker.get_slot(PROVINCE_SLOT)
            if province_value == "qc":
                dispatcher.utter_message(template="utter_may_call_211_qc")
            else:
                dispatcher.utter_message(template="utter_may_call_211_other_provinces")

            dispatcher.utter_message(template="utter_explain_211")
        else:
            dispatcher.utter_message(template="utter_remind_delivery_services")

        dispatcher.utter_message(template="utter_remind_pharmacist_services")
        return []

