    @classmethod
    def required_packages(cls):
        # Specify required dependencies
        return ["jieba"]

    def train(self, training_data, config, **kwargs):
        # Process training examples only if language is Chinese
        if config.get('language', '') != 'zh':
            raise ValueError("Jieba tokenizer is designed for Chinese text processing. Please set 'language' to 'zh' in config.")

        for example in training_data.training_examples:
            tokens = self._segment_text(example.text)
            example.set("tokens", tokens)

    def process(self, message, **kwargs):
        # Tokenize the input message text
        tokens = self._segment_text(message.text)
        message.set("tokens", tokens)

    def _segment_text(self, text):
        # Perform text segmentation using jieba
        segmented_words = jieba.cut(text)
        token_list = list(segmented_words)
        return token_list

