def validate_path(path_name: str, is_directory: bool):
    full_path = os.path.expanduser(path_name)
    required_access = os.W_OK if is_directory else os.R_OK
    existence_check = os.path.isdir if is_directory else os.path.isfile
    size_validation = True if is_directory else os.path.getsize(full_path) > 0

    if existence_check(full_path) and os.access(full_path, required_access) and size_validation:
        return full_path
    raise argparse.ArgumentTypeError("{} does not exist, lacks required permissions, or file is empty".format(full_path))

def verify_seed(seed_value: str):
    if len(seed_value) == 32:
        return seed_value
    raise argparse.ArgumentTypeError("Seed must be exactly 32 characters long, but got {}".format(len(seed_value)))

def confirm_successful_response(response_data):
    if isinstance(response_data, str):
        response_data = json.loads(response_data)
    if "op" not in response_data or response_data["op"] != "REPLY":
