def generate_random_string(length: int) -> str:
    assert (length > 0), "Requested random string length must be positive"
    partial_hex = libnacl.randombytes(length // 2).hex()
    return partial_hex if length % 2 == 0 else partial_hex + hex(libnacl.randombytes_uniform(15))[-1]

def extract_transaction_content(txn_data):
    temp = txn_data or {}
    return temp.get('result', {}).get('txn', {}) or temp.get('txn', {})

def extract_transaction_type(txn_data):
    return extract_transaction_content(txn_data).get('type', None)

def extract_transaction_id(txn_data):
    temp = txn_data or {}
    return (temp.get('result', {}).get('txnMetadata', {}) or temp.get('txnMetadata', {})).get('txnId', None)

def get_operation_type(request_obj):
    if isinstance(request_obj, dict):
        dict_request = request_obj
    elif isinstance(request_obj, str):
        dict_request = json.loads(request_obj)
    else:
        raise RuntimeError("Request object of unsupported type")
    txn_category = dict_request.get("operation", {}).get("type", "")
    return txn_category

def construct_io_sets(address_balances, target_value):
    for user_address in address_balances:
        input_list = []
        output_list = []
        accumulated_value = 0
        temporary_entries = []

        while address_balances[user_address] and accumulated_value < target_value:
            (entry_source, entry_amount) = address_balances[user_address].pop()
            if entry_amount > 0:
                input_list.append(entry_source)
                accumulated_value += entry_amount
                temporary_entries.append((entry_source, entry_amount))

        if accumulated_value >= target_value:
            remainder = accumulated_value - target_value
            if remainder > 0:
                output_list = [{"recipient": user_address, "amount": remainder}]
            return {user_address: temporary_entries}, input_list, output_list
        else:
            for src_amt in temporary_entries:
                address_balances[user_address].append(src_amt)

    return None, None, None

# Custom exception hierarchy for the cruft project

class CruftException(Exception):
    """Base exception class for all errors related to the cruft project"""
    pass

class TemplateNotFound(CruftException):
    """Raised when a Cookiecutter template cannot be located"""
    def __init__(self, path: Union[str, Path]):
        if not isinstance(path, str):
            path = str(path)
        super().__init__(f"Could not find a Cookiecutter template at `{path}`")
        self.path = path

class MissingStateFile(CruftException):
    """Raised when no .cruft.json configuration file is present in the current directory"""
    def __init__(self, location: Union[str, Path]):
        if not isinstance(location, str):
            location = str(location)
        super().__init__(f"No `.cruft.json` state file found in `{location}`")
        self.location = location

class StateFileExists(CruftException):
    """Raised when trying to create a new .cruft.json file that already exists"""
    def __init__(self, filepath: Union[str, Path]):
        if not isinstance(filepath, str):
            filepath = str(filepath)
        super().__init__(f"A `.cruft.json` file already exists at `{filepath}`")
        self.filepath = filepath

class InvalidRepository(CruftException):
    """Raised when an invalid Cookiecutter repository URL or path is provided"""
    pass

import json
import math
import regex
from collections import defaultdict, Counter, OrderedDict
from dataclasses import dataclass
from fractions import Fraction
from typing import Dict, List, FrozenSet, Optional, Any
from ._constant import LETTER
from .language import Language

class _CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj: Any) -> Any:
        if isinstance(obj, _SerializedLanguageModel):
            return {"lang": obj.lang_name, "ngrams": obj.ngram_data}
        return super().default(obj)

class _CustomJSONDecoder(json.JSONDecoder):
    def __init__(self, *args, **kwargs):
        super().__init__(object_hook=self._deserialize_object, *args, **kwargs)

    def _deserialize_object(self, obj: Any) -> Any:
        if isinstance(obj, dict) and "lang" in obj and "ngrams" in obj:
            lang = Language[obj["lang"]]
            ngrams = self._deserialize_object(obj["ngrams"])
            return _SerializedLanguageModel(lang, ngrams)
        return obj

@dataclass
class _SerializedLanguageModel:
    lang_name: Language
    ngram_data: Dict[str, str]

@dataclass
class _CorpusLanguageModel:
    language: Language
    freq_counts: Optional[Dict[str, int]]
    prob_values: Optional[Dict[str, Fraction]]
    json_probabilities: Optional[Dict[str, float]]

    @classmethod
    def create_from_text(
        cls,
        corpus_lines: List[str],
        target_language: Language,
        gram_size: int,
        allowed_chars: str,
        prev_freq_counts: Optional[Dict[str, int]],
    ) -> "_CorpusLanguageModel":
        freq_counts = cls._count_occurrences(corpus_lines, gram_size, allowed_chars)
        prob_values = cls._calculate_probabilities(
            gram_size, freq_counts, prev_freq_counts
        )
        return cls(
            language=target_language,
            freq_counts=freq_counts,
            prob_values=prob_values,
            json_probabilities=None,
        )

    @classmethod
    def create_from_json(cls, json_string: str) -> "_CorpusLanguageModel":
        model_obj: _SerializedLanguageModel = json.loads(
            json_string, cls=_CustomJSONEncoder
        )
        json_probs = {}
        for frac_str, ngram_list in model_obj.ngram_data.items():
            num_str, den_str = frac_str.split("/")
            log_val = math.log(int(num_str) / int(den_str))
            for ngram in ngram_list.split(" "):
                json_probs[ngram] = log_val
        return cls(
            language=model_obj.lang_name,
            freq_counts=None,
            prob_values=None,
            json_probabilities=json_probs,
        )

    def export_to_json(self) -> str:
        frac_to_ngrams = defaultdict(list)
        if self.prob_values is not None:
            for ngram, frac in self.prob_values.items():
                frac_to_ngrams[frac].append(ngram)

        ordered_fracs = OrderedDict()
        for frac, ngrams in frac_to_ngrams.items():
            frac_repr = f"{frac.numerator}/{frac.denominator}"
            ordered_fracs[frac_repr] = " ".join(sorted(ngrams))

        serialized = _SerializedLanguageModel(self.language, ordered_fracs)
        return regex.sub(r"([:,])\s*", r"\1", json.dumps(serialized, cls=_CustomJSONEncoder))

    def get_probability(self, ngram: str) -> float:
        if (
            self.json_probabilities is None
            or ngram not in self.json_probabilities
        ):
            return 0.0
        return self.json_probabilities[ngram]

    @staticmethod
    def _count_occurrences(text_lines: List[str], size: int, char_set: str) -> Dict[str, int]:
        counts = Counter()
        pattern = regex.compile(r"^[{}]+$".format(char_set))
        for line in text_lines:
            lower_line = line.lower()
            for idx in range(len(lower_line) - size + 1):
                chunk = lower_line[idx : idx + size]
                if pattern.match(chunk):
                    counts.update([chunk])
        return dict(counts)

    @classmethod
    def _calculate_probabilities(
        cls,
        ngram_size: int,
        observed_counts: Dict[str, int],
        previous_counts: Optional[Dict[str, int]],
    ) -> Dict[str, Fraction]:
        if previous_counts is None:
            return {}

        total_count = sum(observed_counts.values())
        result = {}

        for ngram, count in observed_counts.items():
            if ngram_size == 1 or len(previous_counts) == 0:
                divisor = total_count
            else:
                prefix = ngram[: ngram_size - 1]
                divisor = previous_counts.get(prefix, 0)

            result[ngram] = Fraction(count, divisor) if divisor > 0 else Fraction(0, 1)

        return result

@dataclass
class _EvaluationLanguageModel:
    ngrams: FrozenSet[str]

    @classmethod
    def build_from_text(cls, input_text: str, gram_length: int) -> "_EvaluationLanguageModel":
        if gram_length not in range(1, 6):
            raise ValueError(f"ngram length {gram_length} must be between 1 and 6")

        found_ngrams = set()
        text_len = len(input_text)

        if text_len >= gram_length:
            for i in range(text_len - gram_length + 1):
                segment = input_text[i : i + gram_length]
                if LETTER.fullmatch(segment):
                    found_ngrams.add(segment)

        return cls(frozenset(found_ngrams))

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Use a dictionary for memoization to store computed results
        cache = {}

        def count_paths(row: int, col: int) -> int:
            # Check if result is already computed
            if (row, col) in cache:
                return cache[(row, col)]

            # Base case: when we reach the bottom-right corner or boundaries
            if row == n - 1 or col == m - 1:
                return 1

            # Recursive calculation with memoization
            paths_right = count_paths(row, col + 1)
            paths_down = count_paths(row + 1, col)
            total_paths = paths_right + paths_down

            # Store result in cache before returning
            cache[(row, col)] = total_paths
            return total_paths

        # Start counting from top-left corner (0, 0)
        return count_paths(0, 0)

import discord
from discord import utils, errors
import checks

class DynamicVoice(commands.Cog):
    """
    A stateless cog that manages voice channels dynamically.
    Provides manual refresh via >refreshVoice command and automatic updates on voice state changes.
    """
    def __init__(self, bot):
        self.bot = bot

    @commands.Cog.listener()
    async def on_voice_state_update(self, member, before, after):
        await self._update_channels()

    @commands.command()
    @checks.trusted()
    async def refreshVoice(self, ctx):
        await self._update_channels()

    async def _update_channels(self):
        # Group channels by user limit
        channel_groups = {
            0: [],
            2: [],
            3: [],
            4: []
        }

        # Locate the target category
        category = utils.get(self.bot.get_all_channels(), name='Party Finder Voice')
        if not category:
            return

        guild = category.guild

        # Organize existing channels by their user limit
        for channel in category.channels:
            if isinstance(channel, discord.VoiceChannel):
                limit = channel.user_limit
                if limit in channel_groups:
                    channel_groups[limit].append(channel)

        # Process each group of channels
        for limit, channels in channel_groups.items():
            if not channels:
                continue

            base_position = channels[0].position
            create_reason = f"DynamicVoice - No empty {limit} Player channel"
            delete_reason = "DynamicVoice - Too many Channels"
            channel_name = f"{limit} Players"

            if limit == 0:
                create_reason = "DynamicVoice - No empty Unlimited Player channel"
                channel_name = "Unlimited Players"

            # Identify empty channels
            vacant_channels = [ch for ch in channels if not ch.members]

            # Create new channel if no empty ones exist
            if not vacant_channels:
                try:
                    await guild.create_voice_channel(
                        channel_name,
                        category=category,
                        user_limit=limit,
                        position=base_position,
                        reason=create_reason
                    )
                except (discord.Forbidden, discord.HTTPException):
                    pass

            # Delete excess empty channels (keep only the first one)
            for excess_channel in vacant_channels[1:]:
                try:
                    await excess_channel.delete(reason=delete_reason)
                except (errors.NotFound, discord.Forbidden, discord.HTTPException):
                    # Channel may have been deleted already or access denied
                    continue

import cv2
import numpy as np

class ShapeClassifier:
    def identify(self, contour):
        shape_name = "unknown"
        perimeter = cv2.arcLength(contour, True)
        approximated = cv2.approxPolyDP(contour, 0.04 * perimeter, True)
        vertices_count = len(approximated)

        if vertices_count == 3:
            shape_name = "triangle"
        elif vertices_count == 4:
            x_coord, y_coord, width, height = cv2.boundingRect(approximated)
            aspect_ratio = float(width) / height
            if 0.95 <= aspect_ratio <= 1.05:
                shape_name = "square"
            else:
                shape_name = "rectangle"
        elif vertices_count == 5:
            shape_name = "pentagon"
        else:
            shape_name = "circle"

        return shape_name

