class Core(commands.Cog):
    def __init__(self, heleus):
        self.heleus = heleus
        self.db_disabled = False
        self.show_full_tracebacks = False  # detailed tracebacks?
        self.user_friendly_errors = True  # user-oriented error messages
        self.config = RedisCollection(self.heleus.redis, 'settings')
        self.log = self.heleus.logger
        self._startup_sequence.start()
        self.global_checks = [self._skip_conditions]  # message processing conditions
        self.global_check_exemptions = [self._exempt_from_skip]  # exceptions to the conditions
        self._eval_context = {}
        self.haste_endpoint = os.environ.get('HELEUS_HASTE_URL', 'https://hastebin.com')
        self.cogs_loaded = False
        self.help_category = 'Core'
        self.help_thumbnail = 'https://i.imgur.com/jLP1NEW.png'
        for attr_name in dir(self):  # docstring formatting
            if attr_name.startswith('_'):
                continue
            attr = getattr(self, attr_name)
            if not isinstance(attr, commands.Command):
                continue
            if not attr.help:
                continue
            attr.help = attr.help.format(self.heleus.name)

    def __unload(self):
        self._shutdown_routine.cancel()
        self._admin_validation.cancel()

    @staticmethod
    def discover_submodules(module_path):
        # Slightly modified approach but same functionality
        if module_path.endswith('.*'):
            module_path = module_path[:-2]
        return [f'{module_path}.{mod.name}' for mod in pkgutil.iter_modules([module_path])]

    async def _cog_manager(self):
        loaded_cogs: list = await self.config.get('cogs', [])
        changed = False
        if self.heleus.autoload and not self.cogs_loaded:
            for module in self.heleus.autoload:
                if module.endswith('.*'):
                    submodules = self.discover_submodules(module)
                    for submodule in submodules:
                        if submodule not in loaded_cogs:
                            loaded_cogs.append(submodule)
                            changed = True
                else:
                    if module not in loaded_cogs:
                        loaded_cogs.append(module)
                        changed = True
            self.cogs_loaded = True
        for cog in loaded_cogs:
            if cog not in list(self.heleus.extensions):
                try:
                    await self.load_extension_module(cog)
                except Exception:
                    loaded_cogs.remove(cog)
                    changed = True
                    self.log.warning(f'{repr(cog)} could not be loaded. This message will not be shown again.')
        if changed:
            await self.config.set('cogs', loaded_cogs)
        for cog in list(self.heleus.extensions):
            if cog == 'cogs.core':
                continue
            if cog not in loaded_cogs:
                self.heleus.unload_extension(cog)

    async def _get_guild_config(self, guild_id, key, fallback=None):
        guild_data = await self.config.get(f'guilds:{guild_id}', {})
        return guild_data.get(key, fallback)

    async def _update_guild_config(self, guild_id, key, value):
        guild_data = await self.config.get(f'guilds:{guild_id}', {})
        guild_data[key] = value
        await self.config.set(f'guilds:{guild_id}', guild_data)

    @tasks.loop(count=1)
    async def _startup_sequence(self):
        """Initial startup sequence. Initialize system."""
        self.heleus.admin_ids = []
        # Set command prefixes
        prefix = str(random.randint(1, 2**8))
        prefixes = await self.config.get('prefixes')
        if prefixes is None:
            prefixes = [prefix]
            await self.config.set('prefixes', prefixes)
        self.heleus.command_prefix = prefixes
        self.log.info(f'{self.heleus.name}\'s prefixes are: {", ".join(map(repr, prefixes))}')
        # Load cogs
        await self._cog_manager()
        # Handle instance state
        instance_state = await self.config.get(self.heleus.instance_id, {'status': CoreMode.boot})
        if not self.heleus.initialized:
            if instance_state['status'] == CoreMode.up:
                instance_state['status'] = CoreMode.boot
                await self.config.set(self.heleus.instance_id, instance_state)
        await self.heleus.wait_until_ready()
        self.heleus.initialized = True
        if instance_state['status'] == CoreMode.boot:
            instance_state['status'] = CoreMode.up
            await self.config.set(self.heleus.instance_id, instance_state)
        # Data migration
        keys = await self.config.keys()
        if 'roles' in keys:
            roles_data = await self.config.get('roles')
            for guild in roles_data:
                await self._update_guild_config(
                    int(guild), 'roles', {k.rstrip('_role'): v for k, v in roles_data[guild].items()}
                )
            await self.config.delete('roles')
        if 'ignores' in keys:
            ignore_data = await self.config.get('ignores')
            for guild in ignore_data:
                entry = []
                [entry.append(int(x)) for x in ignore_data[guild]['ignored_channels']]
                if ignore_data[guild]['server_ignore']:
                    entry.append(int(guild))
                await self._update_guild_config(int(guild), 'ignores', entry)
            await self.config.delete('ignores')
        # Start background tasks
        self._shutdown_routine.start()
        self._admin_validation.start()

    @tasks.loop(seconds=15)
    async def _admin_validation(self):
        # Validate bot owners
        app_info = await self.heleus.application_info()
        admins = await self.config.get('owners', [])
        admins = list(map(int, admins))
        if app_info.team:
            for member in app_info.team.members:
                if member.membership_state == discord.TeamMembershipState.accepted and member.id not in admins:
                    admins.append(member.id)
        else:
            if app_info.owner.id not in admins:
                admins.append(app_info.owner.id)
                await self.config.set('owners', admins)
        self.heleus.admin_ids = admins

    @tasks.loop(seconds=1)
    async def _shutdown_routine(self):
        if not self.db_disabled:
            # Cog management
            await self._cog_manager()
            # Prefix updates
            self.heleus.command_prefix = await self.config.get('prefixes')

    async def _exempt_from_skip(self, message):
        if isinstance(message.author, discord.Member):
            if not self.heleus.intents.guilds:
                self.log.warning('guilds intent is not available! Cannot check exemptions.')
                return
            if message.guild.owner == message.author:
                return True
            try:
                role_names = {x.name.lower() for x in message.author.roles}
                config = await self._get_guild_config(message.guild.id, 'roles', {})
                admin_role = config.get('admin')
                if admin_role in role_names:
                    return True
            except (KeyError, AttributeError):
                pass

    async def _skip_conditions(self, message):
        if isinstance(message.author, discord.Member):
            if not self.heleus.intents.guilds:
                self.log.warning('guilds intent is not available! Cannot check conditions.')
                return
            blocked = await self._get_guild_config(message.guild.id, 'ignores', [])
            if message.author.id in blocked:
                return False
            if message.channel.id in blocked:
                return False
            if message.guild.id in blocked:
                return False

    async def upload_to_haste(self, content):
        async with aiohttp.ClientSession() as session:
            async with session.post(f'{self.haste_endpoint}/documents', data=content) as response:
                return await response.json()

    @staticmethod
    def extract_error_details(exception, depth=None, include_chain=True):
        return ''.join(traceback.format_exception(type(exception), exception, exception.__traceback__, limit=depth,
                                                  chain=include_chain))

    async def refresh_self(self):
        self.heleus.unload_extension('cogs.core')
        await self.load_extension_module('cogs.core')

    # noinspection PyShadowingBuiltins
    async def load_extension_module(self, name):
        self.log.debug(f'Attempting to load module {name}')
        if name in self.heleus.extensions:
            return
        self.heleus.load_extension(name)
        loaded_cogs = await self.config.get('cogs', [])
        if name not in loaded_cogs:
            loaded_cogs.append(name)
            await self.config.set('cogs', loaded_cogs)
        self.log.debug(f'Module {name} loaded successfully')

    # noinspection PyArgumentList
    @commands.Cog.listener()
    async def on_message(self, message):
        instance = await self.config.get(self.heleus.instance_id, {})
        status = instance.get('status', CoreMode.down)
        if status in (CoreMode.down, CoreMode.boot):
            return
        if message.author.id in self.heleus.admin_ids:  # *always* process owner commands
            await self.heleus.process_commands(message)
            return
        if status == CoreMode.maintenance:
            return
        # Exemptions start here
        for exemption in self.global_check_exemptions:
            try:
                result = exemption(message)
                if inspect.isawaitable(result):
                    result = await result
                if result is True:
                    await self.heleus.process_commands(message)
                    return
            except Exception:
                self.log.exception(f'Removed check exemption "{exemption.__name__}", it was malfunctioning.')
                self.global_check_exemptions.remove(exemption)
        # Conditions
        for condition in self.global_checks:
            try:
                result = condition(message)
                if inspect.isawaitable(result):
                    result = await result
                if result is False:
                    return
            except Exception:
                self.log.exception(f'Removed condition "{condition.__name__}", it was malfunctioning.')
                self.global_checks.remove(condition)
        await self.heleus.process_commands(message)

    @commands.Cog.listener()
    async def on_command_error(self, context, exception):
        try:
            if isinstance(exception, commands.CommandInvokeError):
                exception = exception.original
                if isinstance(exception, discord.Forbidden):
                    if self.user_friendly_errors:
                        return await context.send('I don\'t have permission to perform the action you requested.')
                    else:
                        return
