_logger = logging.getLogger('SDK.DCC.Python.general_utilities')

def get_next_filename(original_name: str) -> str:
    """
    Increment the trailing number in a filename string.
    Example: 'file_v2.txt' -> 'file_v3.txt'
    """
    pattern = re.compile(r'(?:\D*(\d+)\D*)+')
    match = pattern.search(original_name)

    if match:
        current_num_str = match.group(1)
        next_num = int(current_num_str) + 1
        start_idx, end_idx = match.span(1)
        # Adjust replacement to preserve original padding if needed
        new_part = str(next_num)
        prefix = original_name[:start_idx]
        suffix = original_name[end_idx:]
        return f"{prefix}{new_part}{suffix}"

    return original_name


def is_valid_markdown_file(file_path: FilePath) -> bool:
    """Check if a markdown file contains the required header marker."""
    try:
        with open(file_path, 'r', encoding='utf-8') as md_file:
            for line in md_file:
                if '### File Under' in line:
                    return True
        return False
    except (IOError, UnicodeDecodeError):
        return False


def ensure_valid_path(path_obj: FilePath) -> FilePath:
    """Return the path only if it points to an existing file; otherwise return empty Path."""
    return path_obj if path_obj.is_file() else FilePath()


def load_json_from_file(file_path: FilePath) -> dict:
    """Load and parse JSON from a standard file."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except IOError:
        raise FileNotFoundError(f"File not found: {file_path}")


def load_json_with_comments(file_path: FilePath) -> dict:
    """Load JSON while stripping C-style single-line comments (// ...)."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            raw_content = f.read()
        # Remove // comments (but not inside strings — simplified approach)
        cleaned = re.sub(r'//.*$', '', raw_content, flags=re.MULTILINE)
        return json.loads(cleaned)
    except IOError:
        raise FileNotFoundError(f"File not found: {file_path}")


def extract_markdown_sections(file_path: FilePath) -> dict:
    """Parse markdown into sections based on headings (#, ##, ###, etc.)."""
    sections = {}
    current_section = None
    content_buffer = []

    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            heading_match = re.match(r'^#{1,6}\s+(.+)$', line.strip())
            if heading_match:
                if current_section is not None:
                    sections[current_section] = '\n'.join(content_buffer).strip()
                    content_buffer.clear()
                current_section = heading_match.group(1).strip()
            else:
                content_buffer.append(line.rstrip())

    if current_section is not None:
        sections[current_section] = '\n'.join(content_buffer).strip()

    return sections


def find_files_recursively(root_dir: FilePath, target_name: str) -> list:
    """Recursively search for files matching a given name under root directory."""
    matches = []
    for dirpath, _, filenames in os.walk(root_dir):
        for fname in filenames:
            if fname == target_name:
                matches.append(FilePath(dirpath) / fname)
    return matches


def save_json_to_file(file_path: FilePath, data: ConfigBox) -> None:
    """Write a Box object as formatted JSON to disk."""
    with open(file_path, 'w', encoding='utf-8') as out_file:
        json.dump(dict(data), out_file, indent=4)


# SQLite Helpers
def connect_to_db(db_path: str) -> sqlite3.Connection:
    """Establish connection to SQLite database."""
    try:
        conn = sqlite3.connect(db_path)
        _logger.info(f"Connected to DB: version {sqlite3.version}")
        return conn
    except SqliteError as err:
        _logger.error(f"DB connection failed: {err}")
        return None


def create_new_table(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, columns: list) -> None:
    """Create a new table with specified column definitions."""
    col_def = ', '.join(columns)
    _logger.info(f"Creating table '{table_name}' with columns: {col_def}")
    cursor.execute(f"CREATE TABLE IF NOT EXISTS {table_name} ({col_def})")
    conn.commit()


def drop_existing_table(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str) -> None:
    """Drop an existing table by name."""
    _logger.info(f"Dropping table '{table_name}'")
    cursor.execute(f"DROP TABLE IF EXISTS {table_name}")
    conn.commit()


def insert_record(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, values: list) -> None:
    """Insert a record into the specified table using provided values."""
    placeholders = ', '.join(['?' for _ in values])
    _logger.info(f"Inserting into '{table_name}' with values: {values}")
    cursor.execute(f"INSERT INTO {table_name} VALUES ({placeholders})", values)
    conn.commit()


def delete_record_by_id(conn: sqlite3.Connection, cursor: sqlite3.Cursor, table_name: str, row_id: int) -> None:
    """Delete a record by its primary key ID."""
    _logger.info(f"Deleting row {row_id} from '{table_name}'")
    cursor.execute(f"DELETE FROM {table_name} WHERE id = ?", (row_id,))
    conn.commit()


def run_sql_command(conn: sqlite3.Connection, cursor: sqlite3.Cursor, query: str) -> None:
    """Execute arbitrary SQL command and commit."""
    _logger.info(f"Executing SQL: {query}")
    cursor.execute(query)
    conn.commit()


def fetch_all_rows(cursor: sqlite3.Cursor, table_name: str) -> dict:
    """Fetch all rows from a table and return as dict keyed by first column."""
    result = {}
    cursor.execute(f"SELECT * FROM {table_name}")
    for row in cursor.fetchall():
        if len(row) >= 2:
            result[row[0]] = row[1]
    return result


def fetch_multiple_tables(cursor: sqlite3.Cursor, table_names: list) -> dict:
    """Fetch contents of multiple tables into nested dictionary structure."""
    db_data = {}
    for table in table_names:
        cursor.execute(f"SELECT * FROM {table}")
        db_data[table] = cursor.fetchall()
    return db_data

from typing import Any, List, Tuple

class CustomDie:
    roll_count: int
    def __init__(self, total_sides: int = 100):
        self._total_sides = total_sides
        self._current_value = 0
        self.roll_count = 0

    def generate_next(self) -> int:
        self.roll_count += 1
        self._current_value += 1
        if self._current_value > self._total_sides:
            self._current_value = 1
        return self._current_value

    def generate_sequence(self, count: int) -> List[int]:
        result = []
        for _ in range(count):
            result.append(self.generate_next())
        return result

GameState = List[int]  # [position, score]
PlayerState = Tuple[GameState, GameState]

def extract_initial_state(input_text: str) -> PlayerState:
    players_data = []
    for line in input_text.strip().splitlines():
        position = int(line.split(": ")[-1])
        players_data.append([position, 0])
    return tuple(players_data)

def compute_new_position(current_pos: int, movement: int) -> int:
    new_pos = current_pos + (movement % 10)
    return new_pos if new_pos <= 10 else new_pos - 10

def advance_player(state: GameState, distance: int):
    state[0] = compute_new_position(state[0], distance)
    state[1] += state[0]

def retrieve_score(state: GameState) -> int:
    return state[1]

class Solution(BaseChallenge):
    @staticmethod
    def solve_part_one(input_data: str) -> Any:
        game_states = extract_initial_state(input_data)
        die_instance = CustomDie()

        while True:
            round_ended = False
            for player_state in game_states:
                move_distance = sum(die_instance.generate_sequence(3))
                advance_player(player_state, move_distance)

                if retrieve_score(player_state) >= 1000:
                    round_ended = True
                    break

            if round_ended:
                break

        final_scores = sorted([retrieve_score(p) for p in game_states])
        return final_scores[0] * die_instance.roll_count

    @staticmethod
    def solve_part_two(input_data: str) -> int:
        raise NotImplementedError

import pyblish.api
from reveries import plugins

def _compute_mesh_digest(mesh):
    from reveries.maya import utils
    hasher = utils.MeshHasher()
    hasher.set_mesh(mesh)
    hasher.update_points()
    return hasher.digest()


def _fetch_protected_nodes(instance):
    from avalon import io
    protected_map = {}
    asset_doc = instance.data["assetDoc"]
    subset_filter = {
        "type": "subset",
        "parent": asset_doc["_id"],
        "name": instance.data["subset"]
    }
    subset_doc = io.find_one(subset_filter)
    if subset_doc is None:
        return protected_map

    version_cursor = io.find(
        {"type": "version", "parent": subset_doc["_id"]},
        sort=[("name", -1)]
    )
    for ver in version_cursor:
        repr_filter = {
            "type": "representation",
            "parent": ver["_id"],
            "name": "mayaBinary"
        }
        repr_doc = io.find_one(repr_filter)
        if not repr_doc:
            continue

        lock_ids = repr_doc["data"].get("modelProtected")
        if lock_ids is None:
            continue

        profile_data = repr_doc["data"].get("modelProfile", {})
        for node_id in lock_ids:
            mesh_info_list = profile_data[node_id]
            if not mesh_info_list:
                continue
            mesh_info = mesh_info_list[0]  # Only one entry expected per ID
            hierarchy_path = mesh_info.pop("hierarchy")
            protected_map[hierarchy_path] = mesh_info

    return protected_map


class SelectModified(plugins.MayaSelectInvalidInstanceAction):
    label = "Invalid Modified"
    symptom = "changed"


class ValidateModelProtectedUnchanged(pyblish.api.InstancePlugin):
    """Models that have been registered as protected should not be altered."""
    families = ["reveries.model"]
    order = pyblish.api.ValidatorOrder - 0.1
    hosts = ["maya"]
    label = "Protected Unchanged"
    actions = [
        pyblish.api.Category("Select"),
        SelectModified,
    ]

    @classmethod
    def _detect_modified(cls, instance, protected_cache=None):
        from maya import cmds
        invalid_nodes = []
        protected = protected_cache or _fetch_protected_nodes(instance)

        all_transforms = cmds.ls(instance, type="transform", long=True)
        for path, ref_data in protected.items():
            if path not in all_transforms:
                continue

            shapes = cmds.listRelatives(
                path,
                shapes=True,
                path=True,
                noIntermediate=True,
                type="mesh"
            )
            if not shapes:
                continue

            mesh_shape = shapes[0]
            current_hash = _compute_mesh_digest(mesh_shape)
            if current_hash["points"] != ref_data["points"]:
                invalid_nodes.append(path)

        return invalid_nodes

    @classmethod
    def _detect_missing(cls, instance, protected_cache=None):
        from maya import cmds
        invalid_nodes = []
        protected = protected_cache or _fetch_protected_nodes(instance)

        existing_transforms = set(cmds.ls(instance, type="transform", long=True))
        for path in protected:
            if path not in existing_transforms:
                invalid_nodes.append(path)

        return invalid_nodes

    def process(self, instance):
        missing_nodes = self._detect_missing(instance)
        if missing_nodes:
            self.log.error("Protected model nodes must not be renamed or deleted.")
            self.log.warning("The following nodes are missing:")
            for node in missing_nodes:
                self.log.warning(node)

        modified_nodes = self._detect_modified(instance)
        if modified_nodes:
            self.log.error("Protected model nodes must not be modified.")
            self.log.warning("The following nodes have been changed:")
            for node in modified_nodes:
                self.log.warning(node)

import torch

class OptimizationDirection:
    @property
    def direction(self):
        if hasattr(self, '_direction'):
            return self._direction
        return True  # default to minimization

class LossFunctionBase:
    def __init__(self, apply_weighting: bool):
        self.apply_weighting = apply_weighting

    def _compute_loss_component(self, values_tensor: torch.Tensor, masks: torch.Tensor,
                                scaling_factors: torch.Tensor, 
                                statistical_moments: Optional[torch.Tensor] = None, *args, **kwargs):
        sample_weights = self._extract_weights(masks)

        # Adjust tensor dimensions if necessary
        if len(values_tensor.shape) > 3:
            values_tensor = torch.squeeze(values_tensor, dim=0)

        # Compute weighted product
        weighted_product = (torch.squeeze(values_tensor * masks, dim=-1) * scaling_factors)

        # Incorporate moments if provided
        if statistical_moments is not None:
            if len(statistical_moments.shape) > 3:
                statistical_moments = torch.squeeze(statistical_moments, dim=0)
            weighted_product = statistical_moments * weighted_product
        else:
            weighted_product = torch.unsqueeze(weighted_product, dim=0)

        # Calculate empirical mean with weights
        total_weight = sample_weights
        numerator = torch.sum(weighted_product, dim=1)
        empirical_mean = torch.div(numerator, total_weight)

        # Apply mean square calculation
        weight_option = total_weight if self.apply_weighting else None
        return self._compute_mean_square(empirical_mean, weight_option)

    @staticmethod
    def _extract_weights(masks: torch.Tensor) -> torch.Tensor:
        # Aggregate mask values across time dimension
        aggregated = torch.sum(masks, dim=0)
        final_weights = torch.squeeze(aggregated, dim=-1)
        return final_weights

    @staticmethod
    def _compute_mean_square(predictions: torch.Tensor, weights: torch.Tensor = None, 
                            use_max_normalization: bool = True):
        squared_errors = torch.square(predictions)

        if weights is not None:
            if use_max_normalization:
                normalization_factor = torch.max(weights)
            else:
                normalization_factor = torch.sum(weights)

            normalized_weights = weights / normalization_factor
            adjusted_squared = squared_errors * normalized_weights

            if use_max_normalization:
                return torch.mean(adjusted_squared)
            else:
                return torch.sum(adjusted_squared)

        return torch.mean(squared_errors)

class SimpleLoss(LossFunctionBase):
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor,
                 scaling_factors: torch.Tensor, *args, **kwargs):
        return self._compute_loss_component(values_tensor, masks, scaling_factors)

class ContextualLoss(LossFunctionBase):
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor,
                 scaling_factors: torch.Tensor, statistical_moments: torch.Tensor, *args, **kwargs):
        return self._compute_loss_component(values_tensor, masks, scaling_factors, statistical_moments)

class WeightedLeastSquares(LossFunctionBase, OptimizationDirection):
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor, *args, **kwargs):
        weights = self._extract_weights(masks)
        return self._compute_mean_square(values_tensor, 
                                        weights if self.apply_weighting else None, 
                                        use_max_normalization=False)

class ResidualComputation:
    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor, 
                 scaling_weights: torch.Tensor, *args, **kwargs):
        # Count valid observations per time point
        observation_counts = torch.sum(torch.squeeze(masks, dim=-1), dim=1)

        # Extract masked values and reshape
        masked_values = torch.masked_select(values_tensor, masks).reshape(
            (torch.sum(masks), values_tensor.shape[-1]))

        # Prepare scaling weights
        adjusted_weights = torch.squeeze(scaling_weights, dim=0)

        # Split data by time points
        value_segments = torch.split(masked_values, observation_counts.tolist())
        weight_segments = torch.split(adjusted_weights, observation_counts.tolist())

        residual_sums = []
        total_sums = []

        for val_segment, weight_segment in zip(value_segments, weight_segments):
            # Compute projection coefficients
            coefficient = torch.sum(val_segment * weight_segment) / torch.sum(weight_segment * weight_segment)
            predicted_values = coefficient * weight_segment

            # Calculate residuals and totals
            residual_sums.append(torch.mean(torch.square(val_segment - predicted_values)))
            total_sums.append(torch.mean(torch.square(val_segment)))

        # Normalize residual sum by total sum
        avg_residual = torch.mean(torch.tensor(residual_sums))
        avg_total = torch.mean(torch.tensor(total_sums))
        return avg_residual / avg_total

class CombinedLoss(OptimizationDirection):
    def __init__(self, optimize_direction: bool, apply_weighting: bool, 
                 uses_context: bool, residual_coefficient: float = 0.):
        self.residual_coefficient = residual_coefficient

        # Initialize main loss component
        if uses_context:
            self.primary_loss = ContextualLoss(to_weight=apply_weighting)
        else:
            self.primary_loss = SimpleLoss(to_weight=apply_weighting)

        self.residual_module = ResidualComputation()
        self._direction = optimize_direction

        # Validate configuration
        if not self.direction and self.residual_coefficient:
            raise NotImplementedError('Maximization mode with residual loss is not supported')

    def __call__(self, values_tensor: torch.Tensor, masks: torch.Tensor, 
                 scaling_factors: torch.Tensor, scaling_weights: torch.Tensor = None,
                 statistical_moments: Optional[torch.Tensor] = None, *args, **kwargs):
        # Determine sign based on optimization direction
        sign_factor = 1 if self.direction else -1

        # Compute primary loss
        primary_value = sign_factor * self.primary_loss(
            values_tensor=values_tensor,
            masks=masks,
            scaling_factors=scaling_factors,
            statistical_moments=statistical_moments)

        # Add residual component if applicable
        if self.residual_coefficient:
            residual_component = self.residual_module(
                values_tensor, masks, scaling_weights) * self.residual_coefficient
            primary_value += residual_component

        return primary_value

import re
from bs4 import BeautifulSoup
from scraper.utils import get_page, make_soup

class Track:
    def __init__(self, track_url: str) -> None:
        self.link = track_url
        self.parse(get_page(track_url))

    def __str__(self) -> str:
        return f'{self.performer} - {self.name}: {" ".join(self.chord_list)}'

    @staticmethod
    def extract_chords(soup: BeautifulSoup) -> list:
        """Extracts and returns unique chords from the provided HTML structure."""

        chord_set = []
        for code_element in soup.find_all('code'):
            chord = f'{code_element["data-chord"]}{code_element["data-suffix"]}'
            if code_element.get('data-chord') and chord not in chord_set:
                chord_set.append(chord)
        return chord_set

    @staticmethod
    def extract_name(soup: BeautifulSoup) -> str:
        """Extracts and returns the track's title."""
        return soup.select_one('h1 strong').get_text()

    @staticmethod
    def extract_performer(soup: BeautifulSoup) -> str:
        """Extracts and returns the track's performer/author."""
        tag = soup.select_one('h1')
        tag.find('strong').decompose()
        # remove content within parentheses
        return re.sub(r'\(.*?\)', '', tag.get_text()).strip()

    def parse(self, html_content: str) -> None:
        soup = make_soup(html_content)
        self.chord_list = self.extract_chords(soup)
        self.name = self.extract_name(soup)
        self.performer = self.extract_performer(soup)

