from dataclasses import dataclass, field
from typing import Dict, Any, Optional, List, Callable, Union, TYPE_CHECKING
from ray.tune.syncer import SyncConfig
from ray.util import PublicAPI

if TYPE_CHECKING:
    from ray.tune.trainable import PlacementGroupFactory
    from ray.tune.callback import Callback
    from ray.tune.stopper import Stopper

# Alias for backward compatibility
ScalingConfig = Dict[str, Any]

@dataclass
class ScalingParameters:
    """Configuration for scaling training workloads.

    This class defines the structure and behavior of scaling configurations,
    including resource allocation for trainer and workers, GPU/CPU settings,
    and placement strategies.
    """
    # Resources allocated specifically for the main trainer process
    trainer_resources: Optional[Dict[str, Any]] = None

    # Number of distributed workers to launch
    num_workers: Optional[int] = None

    # Whether to enable GPU-based training (default: False)
    use_gpu: bool = False

    # Additional per-worker resource specifications beyond CPU/GPU defaults
    resources_per_worker: Optional[Dict[str, Any]] = field(default_factory=dict)

    # Strategy for placing Ray actors in the cluster
    placement_strategy: str = "PACK"

    def __post_init__(self):
        # Ensure resources_per_worker is always a dict
        if self.resources_per_worker is None:
            self.resources_per_worker = {}

        # Validate GPU-related consistency
        if self.resources_per_worker:
            worker_gpus = self.num_gpus_per_worker
            if not self.use_gpu and worker_gpus > 0:
                raise ValueError(
                    "`use_gpu` is set to False but `GPU` is specified in "
                    "`resources_per_worker`. Either enable `use_gpu` or remove "
                    "the `GPU` key from `resources_per_worker`."
                )
            if self.use_gpu and worker_gpus == 0:
                raise ValueError(
                    "`use_gpu` is True but no GPUs are requested in "
                    "`resources_per_worker`. Either disable `use_gpu` or "
                    "specify a positive number of GPUs."
                )

    @property
    def cpu_per_worker(self) -> int:
        """Determine how many CPUs each worker should receive."""
        return self.resources_per_worker.get("CPU", 1)

    @property
    def gpu_per_worker(self) -> int:
        """Determine how many GPUs each worker should receive."""
        return self.resources_per_worker.get("GPU", int(self.use_gpu))

    @property
    def extra_resources_per_worker(self) -> Dict[str, Any]:
        """Extract non-CPU/GPU resources defined per worker."""
        return {
            k: v
            for k, v in self.resources_per_worker.items()
            if k not in ("CPU", "GPU")
        }

    def to_placement_group_factory(self) -> "PlacementGroupFactory":
        """Convert this config into a PlacementGroupFactory for Tune scheduling."""
        from ray.tune.trainable import PlacementGroupFactory

        # Set default trainer resources if none provided
        trainer_res = self.trainer_resources or {"CPU": 1}

        # Build bundles: one for trainer + one per worker
        bundles = [trainer_res]

        # Prepare base worker resources
        base_worker_res = {
            "CPU": self.cpu_per_worker,
            "GPU": self.gpu_per_worker,
        }

        # Append additional resources if any
        if self.resources_per_worker:
            base_worker_res.update(self.extra_resources_per_worker)

        # Create worker bundles
        num_workers = self.num_workers or 0
        bundles.extend([base_worker_res.copy() for _ in range(num_workers)])

        return PlacementGroupFactory(bundles, strategy=self.placement_strategy)


