    storage_path: Optional[str] = None
    event_handlers: Optional[List["Callback"]] = None
    termination_criteria: Optional[Union[Mapping, "Stopper", Callable[[str, Mapping], bool]]] = None
    error_handling: Optional[FailureSettings] = None
    sync_options: Optional[SyncConfig] = None

from dataclasses import dataclass
from typing import Any, Optional, Sequence
from .schema import Schema, SchemaError
from .type_schema import InvalidTypeError

class ChoiceValidator(Schema):
    def __init__(self, *allowed_values: str):
        # Store normalized (lowercase) versions of all valid options
        self._valid_choices = [value.lower() for value in allowed_values]
        self._error_message = OptionMismatchError(allowed_values)

    def check(self, input_value: Any) -> Optional[SchemaError]:
        # First verify the input is a string
        if not isinstance(input_value, str):
            return InvalidTypeError(str)

        # Check if the lowercase version exists in our allowed choices
        if input_value.lower() not in self._valid_choices:
            return self._error_message
        else:
            return None

@dataclass
class OptionMismatchError(SchemaError):
    acceptable_options: Sequence[str]

def select_from(*choices: str) -> ChoiceValidator:
    return ChoiceValidator(*choices)

