from .core import AbstractMetaAPI


class DistributedMetadataInterface(AbstractMetaAPI):
    def __init__(self, session_identifier: str, metadata_backend: Union[AbstractMetaStore, mo.ActorRef]):
        self._session_id = session_identifier
        self._metadata_store = metadata_backend

    @classmethod
    @alru_cache(cache_exceptions=False)
    async def instantiate(cls, session_identifier: str, supervisor_node: str) -> "DistributedMetadataInterface":
        """
        Initialize and return an instance of the metadata interface.
        """
        backend_ref = await mo.actor_ref(
            supervisor_node, MetaStoreActor.uid_for_session(session_identifier)
        )
        return cls(session_identifier, backend_ref)

    @classmethod
    async def establish_session(cls, session_identifier: str, supervisor_node: str) -> "DistributedMetadataInterface":
        """
        Sets up a new session-specific metadata store and returns its interface.
        """
        manager_ref = await mo.actor_ref(supervisor_node, MetaStoreManagerActor.default_uid())
        store_ref = await manager_ref.spawn_session_store(session_identifier)
        return cls(session_identifier, store_ref)

    @classmethod
    async def tear_down_session(cls, session_identifier: str, supervisor_node: str):
        """
        Cleans up resources associated with a session.
        """
        store_ref = await mo.actor_ref(supervisor_node, MetaStoreActor.uid_for_session(session_identifier))
        await mo.delete_actor(store_ref)

    @mo.extensible
    async def register_tileable_metadata(
        self,
        tileable_obj,
        memory_footprint: int = None,
        storage_footprint: int = None,
        **additional_info
    ):
        base_params = dict(tileable_obj.params.items())

        # Special handling for DataFrame-like types
        if isinstance(tileable_obj, (DATAFRAME_TYPE, DATAFRAME_GROUPBY_TYPE, SERIES_GROUPBY_TYPE)):
            base_params.pop('columns_value', None)
            base_params.pop('dtypes', None)
            base_params.pop('key_dtypes', None)
            base_params['dtypes_value'] = tileable_obj.dtypes_value

        base_params['nsplits'] = tileable_obj.nsplits
        base_params.update(additional_info)

        meta_class = get_meta_type(type(tileable_obj))
        metadata_instance = meta_class(
            object_id=tileable_obj.key,
            **base_params,
            memory_size=memory_footprint,
            store_size=storage_footprint
        )

        return await self._metadata_store.put(tileable_obj.key, metadata_instance)

    @mo.extensible
    async def retrieve_tileable_metadata(
        self,
        identifier: str,
        requested_fields: Optional[List[str]] = None
    ) -> Dict[str, Any]:
        return await self._metadata_store.fetch(identifier, fields=requested_fields)

    @mo.extensible
    async def erase_tileable_metadata(self, identifier: str):
        return await self._metadata_store.remove(identifier)

    @staticmethod
    def _prepare_chunk_metadata(
        chunk_obj: ChunkType,
        memory_footprint: int = None,
        storage_footprint: int = None,
        execution_bands: List[BandType] = None,
        **extra_data
    ):
        if isinstance(chunk_obj.op, Fuse):
            chunk_obj = chunk_obj.chunk

        raw_params = dict(chunk_obj.params.items())
        chunk_id = extra_data.pop('chunk_id', chunk_obj.key)

        if isinstance(chunk_obj, (DATAFRAME_CHUNK_TYPE, DATAFRAME_GROUPBY_CHUNK_TYPE, SERIES_GROUPBY_CHUNK_TYPE)):
            raw_params.pop('columns_value', None)
            raw_params.pop('dtypes', None)
            raw_params.pop('key_dtypes', None)

        raw_params.update(extra_data)

        meta_class = get_meta_type(type(chunk_obj))
        return meta_class(
            object_id=chunk_id,
            **raw_params,
            bands=execution_bands,
            memory_size=memory_footprint,
            store_size=storage_footprint
        )

    @mo.extensible
    async def register_chunk_metadata(
        self,
        chunk_obj: ChunkType,
        memory_footprint: int = None,
        storage_footprint: int = None,
        execution_bands: List[BandType] = None,
        **extra_data
    ):
        meta = self._prepare_chunk_metadata(
            chunk_obj,
            memory_footprint=memory_footprint,
            storage_footprint=storage_footprint,
            execution_bands=execution_bands,
            **extra_data
        )
        return await self._metadata_store.put(meta.object_id, meta)

    @register_chunk_metadata.batch
    async def batch_register_chunk_metadata(self, args_list, kwargs_list):
        pending_ops = []
        for args, kwargs in zip(args_list, kwargs_list):
            meta = self._prepare_chunk_metadata(*args, **kwargs)
            pending_ops.append(self._metadata_store.put.delay(meta.object_id, meta))
        return await self._metadata_store.put.batch(*pending_ops)

    @mo.extensible
    async def fetch_chunk_metadata(
        self,
        identifier: str,
        requested_fields: Optional[List[str]] = None,
        on_error: str = 'raise'
    ):
        return await self._metadata_store.fetch(identifier, fields=requested_fields, error=on_error)

    @fetch_chunk_metadata.batch
    async def batch_fetch_chunk_metadata(self, args_list, kwargs_list):
        pending_queries = []
        for args, kwargs in zip(args_list, kwargs_list):
            pending_queries.append(self._metadata_store.fetch.delay(*args, **kwargs))
        return await self._metadata_store.fetch.batch(*pending_queries)

    @mo.extensible
    async def remove_chunk_metadata(self, identifier: str):
        return await self._metadata_store.remove(identifier)

    @remove_chunk_metadata.batch
    async def batch_remove_chunk_metadata(self, args_list, kwargs_list):
        pending_deletions = []
        for args, kwargs in zip(args_list, kwargs_list):
            pending_deletions.append(self._metadata_store.remove.delay(*args, **kwargs))
        return await self._metadata_store.remove.batch(*pending_deletions)

    @mo.extensible
    async def append_execution_bands(self, identifier: str, bands: List[BandType]):
        return await self._metadata_store.extend_bands(identifier, bands)

    @append_execution_bands.batch
    async def batch_append_execution_bands(self, args_list, kwargs_list):
        tasks = []
        for args, kwargs in zip(args_list, kwargs_list):
            tasks.append(self._metadata_store.extend_bands.delay(*args, **kwargs))
        return await self._metadata_store.extend_bands.batch(*tasks)


class SimulatedMetadataInterface(DistributedMetadataInterface):
    @classmethod
    async def instantiate(cls, session_identifier: str, supervisor_node: str) -> "SimulatedMetadataInterface":
        try:
            manager_ref = await mo.create_actor(
                MetaStoreManagerActor,
                'dict',
                {},
                address=supervisor_node,
                uid=MetaStoreManagerActor.default_uid()
            )
        except mo.ActorAlreadyExist:
            manager_ref = await mo.actor_ref(
                MetaStoreManagerActor,
                address=supervisor_node,
                uid=MetaStoreManagerActor.default_uid()
            )

        try:
            await manager_ref.spawn_session_store(session_identifier)
        except mo.ActorAlreadyExist:
            pass

        return await super().instantiate(session_identifier=session_identifier, supervisor_node=supervisor_node)

from typing import List, Optional
import pandas as pd

class PEPRECException(Exception):
    """Custom exception for invalid PEPREC files."""
    pass

class PeptideData:
    """Container for peptide identification data (PEPREC format)."""
    def __init__(
        self,
        filepath: Optional[str] = None,
        mode: str = "standard",
        additional_fields: Optional[List[str]] = None,
    ):
        """
        Initialize a peptide data object.

        Parameters
        ----------
        filepath: str, None
            Path to the input PEPREC file. If provided, file is loaded automatically.
        mode: str
            Operational mode affecting required columns. Supported values: 
            {"standard", "ms2rescore", "retention_time"}.
        additional_fields: List[str]
            Extra column names that must be present during validation.
        """
        self.filepath = filepath
        self.mode = mode
        self.additional_fields = additional_fields or []
        self._dataframe = None

        if self.filepath:
            self.load_from_csv(self.filepath)

    def __str__(self):
        """Return string representation of the underlying DataFrame."""
        return str(self._dataframe)

    @property
    def dataframe(self) -> Optional[pd.DataFrame]:
        """Access the internal DataFrame."""
        return self._dataframe

    @dataframe.setter
    def dataframe(self, df: Optional[pd.DataFrame]):
        """Assign and validate a new DataFrame."""
        if isinstance(df, pd.DataFrame):
            self._check_columns(df)
        self._dataframe = df

    def load_from_csv(self, filepath: str, **kwargs):
        """Load PEPREC data from a CSV file."""
        self._validate_file_header(filepath)
        delimiter = self._detect_delimiter(filepath)
        self.dataframe = pd.read_csv(filepath, sep=delimiter, index_col=None, **kwargs)
        # Replace NaN in 'modifications' with dash
        if 'modifications' in self.dataframe.columns:
            self.dataframe['modifications'] = self.dataframe['modifications'].fillna('-')

    def save_to_csv(self, output_path: Optional[str] = None, **kwargs):
        """Write current data to a CSV file."""
        target_path = output_path or self.filepath
        if not target_path:
            raise ValueError("No output path specified and no stored filepath available.")

        self.dataframe.to_csv(
            target_path, 
            sep=" ", 
            index=False, 
            float_format="%.3f", 
            **kwargs
        )

    def standardize_column_order(self):
        """Reorder columns so canonical fields appear first."""
        current_cols = list(self.dataframe.columns)
        for field in self._mandatory_fields:
            if field in current_cols:
                current_cols.remove(field)
            else:
                self._mandatory_fields.remove(field)

        ordered_cols = self._mandatory_fields + current_cols
        self.dataframe = self.dataframe[ordered_cols]

    @property
    def _mandatory_fields(self) -> List[str]:
        """Determine mandatory columns based on operational mode."""
        base_fields = ["spec_id", "peptide", "modifications", "charge"]

        if self.mode == "ms2rescore":
            base_fields.extend(["psm_score", "observed_retention_time"])
        elif self.mode == "retention_time":
            if "modifications" in base_fields:
                base_fields.remove("modifications")

        return base_fields

    def _validate_file_header(self, filepath: str):
        """Ensure the file starts with the expected header."""
        with open(filepath, 'r') as f:
            first_line = f.readline()
            if not first_line.startswith("spec_id"):
                raise PEPRECException("PEPREC file must begin with 'spec_id'.")

    def _check_columns(self, df: pd.DataFrame):
        """Verify presence of all required columns."""
        missing = [col for col in self._mandatory_fields if col not in df.columns]
        if missing:
            raise PEPRECException(f"Missing required columns: {', '.join(missing)}")

    @classmethod
    def create_from_dataframe(cls, df: pd.DataFrame):
        """Construct a PeptideData instance directly from a DataFrame."""
        instance = cls()
        instance.dataframe = df
        instance.standardize_column_order()
        return instance

    @classmethod
    def create_from_csv(cls, *args, **kwargs):
        """Build a PeptideData instance by loading from a CSV file."""
        instance = cls()
        instance.load_from_csv(*args, **kwargs)
        return instance

    @staticmethod
    def _detect_delimiter(filepath: str) -> str:
        """Guess the delimiter used in the PEPREC file."""
        with open(filepath, 'r') as f:
            line = f.readline()
            # Assuming 7th character after 'spec_id' indicates separator
            return line[7] if len(line) > 7 else ','

