# Configuration
TARGET_PROCESS = "GrilsFrontLine.exe"
PIPE_NAME = "MaaLunaPipe"
SCRIPT_PATH = os.path.join(os.path.dirname(__file__), "hook.js")
active_script = None

def handle_frida_message(msg, data):
    if msg.get('type') == 'send':
        payload = msg.get('payload')
        if isinstance(payload, dict) and payload.get('type') == 'error':
            print(f"[!] Hook Error: {payload.get('stack')}")
        else:
            print(f"[*] Frida: {payload}")
    elif msg.get('type') == 'error':
        print(f"[!] Frida Error: {msg['stack']}")

def ipc_command_processor(input_line):
    """
    Protocol:
    "MOVE x y"       -> Returns "OK"
    "WHEEL delta x y" -> Returns "OK" (delta usually 120 or -120)
    """
    global active_script
    print(f"[IPC DEBUG] Received raw message: '{input_line}'")

    if not active_script:
        print("[IPC DEBUG] Error: Active script is not loaded!")
        return "ERR_NO_SCRIPT"

    try:
        tokens = input_line.strip().split()
        if not tokens:
            return "ERR_EMPTY"

        command = tokens[0].upper()

        if command == 'MOVE' and len(tokens) == 3:
            x_coord = int(tokens[1])
            y_coord = int(tokens[2])
            active_script.post({'type': 'UPDATE_POS', 'x': x_coord, 'y': y_coord})
            return "OK"

        elif command == 'WHEEL' and len(tokens) >= 4:
            wheel_delta = int(tokens[1])
            pos_x = int(tokens[2])
            pos_y = int(tokens[3])

            print(f"[IPC DEBUG] Processing WHEEL >>> Delta: {wheel_delta}, Pos: ({pos_x}, {pos_y})")

            # Update position first, then simulate wheel
            active_script.post({'type': 'UPDATE_POS', 'x': pos_x, 'y': pos_y})
            active_script.post({'type': 'SIMULATE_WHEEL', 'delta': wheel_delta})
            return "OK"
        else:
            print(f"[IPC DEBUG] Warning: Unknown or invalid command format: {input_line}")
            return "ERR_INVALID_CMD"
    except Exception as exc:
        print(f"[!] Handler Exception: {exc}")
        return "ERR_EXCEPTION"

def run_service():
    global active_script
    print(f"[*] Luna Service Starting...")
    print(f"[*] Target Process: {TARGET_PROCESS}")

    # Initialize IPC server
    pipe_server = NamedPipeServer(PIPE_NAME, ipc_command_processor)
    pipe_server.start()

    # Attach to target process with retry logic
    attached_session = None
    while True:
        try:
            attached_session = frida.attach(TARGET_PROCESS)
            print(f"[+] Attached to {TARGET_PROCESS}")
            break
        except Exception as err:
            print(f"[.] Waiting for process... ({err})")
            time.sleep(2)

    try:
        # Load JavaScript hook script
        with open(SCRIPT_PATH, "r", encoding="utf-8") as script_file:
            js_code = script_file.read()

        active_script = attached_session.create_script(js_code)
        active_script.on('message', handle_frida_message)
        active_script.load()
        print(f"[+] Hook loaded. Pipe '\\\\.\\pipe\\{PIPE_NAME}' ready.")

        # Keep service running
        sys.stdin.read()
    except KeyboardInterrupt:
        print("[*] Stopping...")
    except Exception as error:
        print(f"[!] Error: {error}")
    finally:
        if attached_session:
            attached_session.detach()
        # Note: In real implementation, ensure proper cleanup of background threads

if __name__ == '__main__':
    run_service()

# Global state variables for Primus configuration and runtime context
_cli_args = None
_primus_config = None
_target_platform = None

def _validate_not_none(value, var_name):
    """Ensure the provided variable is not None."""
    if value is None:
        raise RuntimeError(f"{var_name} has not been initialized.")

def is_ready():
    """Check whether the system is fully initialized."""
    return _primus_config is not None and getattr(_primus_config, 'initialized', False)

def mark_as_initialized():
    """Mark the global config as initialized."""
    if _primus_config is not None:
        _primus_config.initialized = True

def get_command_line_options():
    """Retrieve command-line arguments."""
    _validate_not_none(_cli_args, "command-line arguments")
    return _primus_config.cli_args if _primus_config else None

def get_configuration():
    """Retrieve the current Primus configuration."""
    _validate_not_none(_primus_config, "Primus configuration")
    return _primus_config

def get_execution_platform():
    """Retrieve the target execution platform."""
    _validate_not_none(_target_platform, "target platform")
    return _target_platform

def initialize_globals(config: 'PrimusConfig'):
    """Initialize global variables using the provided configuration."""
    global _primus_config, _cli_args, _target_platform

    if config is None:
        raise ValueError("Configuration cannot be None.")

    if _primus_config is not None:
        return  # Already initialized

    _primus_config = config
    _configure_cli_options(config)
    _configure_platform(config)

def _configure_cli_options(config: 'PrimusConfig'):
    """Set CLI arguments from configuration."""
    global _cli_args
    if _cli_args is None and hasattr(config, 'cli_args'):
        _cli_args = config.cli_args

def _configure_platform(config: 'PrimusConfig'):
    """Determine and set the appropriate execution platform."""
    global _target_platform

    if _target_platform is not None:
        return

    # Extract platform configuration or create a default local setup
    platform_settings = getattr(config, 'platform_config', None)
    if platform_settings is None:
        # Default fallback: local platform with minimal settings
        platform_settings = type('PlatformConfig', (), {
            'name': 'local',
            'master_sink_level': 'INFO',
            'gpus_per_node_env_key': None
        })()
        setattr(config, 'platform_config', platform_settings)

    # Instantiate the correct platform based on name
    platform_name = getattr(platform_settings, 'name', 'local')
    if platform_name and platform_name.lower() != 'local':
        from primus.platforms import RemotePlatform
        _target_platform = RemotePlatform(platform_name)
    else:
        from primus.platforms import LocalPlatform
        _target_platform = LocalPlatform('local')

import re
from pathlib import Path
from skylos.llm.graph import CodeGraph

class CodeSegment:
    def __init__(
        self,
        text,
        first_line,
        last_line,
        kind,
        identifier,
        imports_section,
        class_info,
        source_file,
    ):
        self.text = text
        self.first_line = first_line
        self.last_line = last_line
        self.kind = kind
        self.identifier = identifier
        self.imports_section = imports_section
        self.class_info = class_info
        self.source_file = source_file

    def full_context(self):
        segments = []
        if self.imports_section:
            segments.append(f"# Imports\n{self.imports_section}")
        if self.class_info:
            segments.append(f"# Class context\n{self.class_info}")
        segments.append(
            f"# {self.kind.title()}: {self.identifier} (lines {self.first_line}-{self.last_line})"
        )
        segments.append(self.text)
        return "\n\n".join(segments)

    def with_line_numbers(self):
        lines = self.text.splitlines()
        numbered_lines = []
        for idx, line in enumerate(lines, start=self.first_line):
            numbered_lines.append(f"{idx:4d} | {line}")
        return "\n".join(numbered_lines)


class ASTPartitioner:
    def __init__(
        self,
        max_segment_chars=2000,
        overlap_size=5,
        include_imports=True,
        include_class_context=True,
    ):
        self.max_segment_chars = max_segment_chars
        self.overlap_size = overlap_size
        self.include_imports_flag = include_imports
        self.include_class_context_flag = include_class_context

    def partition_source(self, source_code, file_path=""):
        try:
            tree = ast.parse(source_code)
        except SyntaxError:
            return self._fallback_partition(source_code, file_path)

        lines = source_code.splitlines()
        imports_block = self._collect_imports(tree, lines)
        segments = []

        for node in ast.iter_child_nodes(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                segment = self._make_function_segment(node, lines, imports_block, file_path)
                segments.append(segment)
            elif isinstance(node, ast.ClassDef):
                class_segment = self._make_class_segment(node, lines, imports_block, file_path)
                class_length = len(class_segment.text)
                if class_length <= self.max_segment_chars:
                    segments.append(class_segment)
                else:
                    class_header = self._extract_class_header(node, lines)
                    for member in node.body:
                        if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            method_segment = self._make_method_segment(
                                member,
                                lines,
                                imports_block,
                                file_path,
                                class_name=node.name,
                                class_header=class_header,
                            )
                            segments.append(method_segment)

        if not segments:
            segments.append(
                CodeSegment(
                    text=source_code,
                    first_line=1,
                    last_line=len(lines),
                    kind="module",
                    identifier=Path(file_path).stem if file_path else "module",
                    imports_section=imports_block,
                    class_info=None,
                    source_file=file_path,
                )
            )

        segments = self._break_large_segments(segments)
        return segments

    def _collect_imports(self, tree, lines):
        import_lines = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                start_idx = node.lineno - 1
                end_idx = getattr(node, "end_lineno", node.lineno)
                import_lines.extend(lines[start_idx:end_idx])
        return "\n".join(import_lines)

    def _make_function_segment(self, node, lines, imports_block, file_path):
        start_idx = node.lineno - 1
        end_idx = getattr(node, "end_lineno", node.lineno + 10)
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start_idx:end_idx])

        return CodeSegment(
            text=content,
            first_line=start_idx + 1,
            last_line=end_idx,
            kind="function",
            identifier=node.name,
            imports_section=imports_block if self.include_imports_flag else "",
            class_info=None,
            source_file=file_path,
        )

    def _make_class_segment(self, node, lines, imports_block, file_path):
        start_idx = node.lineno - 1
        end_idx = getattr(node, "end_lineno", node.lineno + 20)
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start_idx:end_idx])

        return CodeSegment(
            text=content,
            first_line=start_idx + 1,
            last_line=end_idx,
            kind="class",
            identifier=node.name,
            imports_section=imports_block if self.include_imports_flag else "",
            class_info=None,
            source_file=file_path,
        )

    def _make_method_segment(
        self, node, lines, imports_block, file_path, class_name, class_header
    ):
        start_idx = node.lineno - 1
        end_idx = getattr(node, "end_lineno", node.lineno + 10)
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        content = "\n".join(lines[start_idx:end_idx])
        method_name = f"{class_name}.{node.name}"

        imports_out = imports_block if self.include_imports_flag else ""
        class_ctx_out = class_header if self.include_class_context_flag else None

        return CodeSegment(
            text=content,
            first_line=start_idx + 1,
            last_line=end_idx,
            kind="method",
            identifier=method_name,
            imports_section=imports_out,
            class_info=class_ctx_out,
            source_file=file_path,
        )

    def _extract_class_header(self, node, lines):
        start_idx = node.lineno - 1
        if node.decorator_list:
            start_idx = min(d.lineno - 1 for d in node.decorator_list)
        header_end = node.lineno

        for item in node.body:
            if isinstance(item, ast.Expr) and isinstance(item.value, ast.Constant):
                header_end = getattr(item, "end_lineno", item.lineno)
            else:
                break

        return "\n".join(lines[start_idx:header_end])

    def _break_large_segments(self, segments):
        result = []
        for seg in segments:
            if len(seg.text) <= self.max_segment_chars:
                result.append(seg)
            else:
                sub_segments = self._divide_by_blocks(seg)
                result.extend(sub_segments)
        return result

    def _divide_by_blocks(self, segment):
        lines = segment.text.splitlines()
        approx_lines_per_chunk = self.max_segment_chars // 60
        sub_segments = []
        i = 0

        while i < len(lines):
            end = min(i + approx_lines_per_chunk, len(lines))
            if end < len(lines):
                for j in range(end, max(i + approx_lines_per_chunk // 2, i), -1):
                    if not lines[j].strip() or lines[j].strip().startswith(
                        ("#", "def ", "class ")
                    ):
                        end = j
                        break

            sub_content = "\n".join(lines[i:end])
            sub_segments.append(
                CodeSegment(
                    text=sub_content,
                    first_line=segment.first_line + i,
                    last_line=segment.first_line + end - 1,
                    kind=f"{segment.kind}_part",
                    identifier=f"{segment.identifier}_part{len(sub_segments) + 1}",
                    imports_section=segment.imports_section,
                    class_info=segment.class_info,
                    source_file=segment.source_file,
                )
            )
            i = end - self.overlap_size
            if i <= 0 or end >= len(lines):
                break

        return sub_segments if sub_segments else [segment]

    def _fallback_partition(self, source_code, file_path):
        lines = source_code.splitlines()
        approx_lines_per_chunk = self.max_segment_chars // 60
        import_pattern = re.compile(r"^(?:from\s+\S+\s+)?import\s+.+$")
        imports_list = []

        for line in lines[:50]:
            if import_pattern.match(line.strip()):
                imports_list.append(line)

        imports_block = "\n".join(imports_list)
        chunks = []
        i = 0

        while i < len(lines):
            end = min(i + approx_lines_per_chunk, len(lines))
            content = "\n".join(lines[i:end])
            chunks.append(
                CodeSegment(
                    text=content,
                    first_line=i + 1,
                    last_line=end,
                    kind="block",
                    identifier=f"block_{len(chunks) + 1}",
                    imports_section=imports_block,
                    class_info=None,
                    source_file=file_path,
                )
            )
            i = end - self.overlap_size
            if i <= 0:
                break

        return (
            chunks
            if chunks
            else [
                CodeSegment(
                    text=source_code,
                    first_line=1,
                    last_line=len(lines),
                    kind="module",
                    identifier="module",
                    imports_section=imports_block,
                    class_info=None,
                    source_file=file_path,
                )
            ]
        )


class ContextAssembler:
    def __init__(self, max_context_chars=8000):
        self.max_context_chars = max_context_chars
        self.partitioning_engine = ASTPartitioner(max_segment_chars=max_context_chars // 2)

    def partition_source(self, source_code, file_path=""):
        return self.partitioning_engine.partition_source(source_code, file_path)

    def construct_analysis_context(
        self, source_or_segment, file_path=None, definitions_map=None, include_imports=True
    ):
        if isinstance(source_or_segment, CodeSegment):
            return self._construct_segment_context(source_or_segment, definitions_map)

        source_code = source_or_segment
        file_path = file_path or ""
        lines = source_code.splitlines()
        name = "module"
        if file_path:
            name = Path(file_path).stem

        imports_block = ""
        if include_imports:
            imports_block = self._extract_imports_string(source_code)

        segment = CodeSegment(
            text=source_code,
            first_line=1,
            last_line=len(lines),
            kind="module",
            identifier=name,
            imports_section=imports_block,
            class_info=None,
            source_file=file_path,
        )
        return self._construct_segment_context(segment, definitions_map)

    def construct_smart_slice(self, full_source, function_name):
        graph = CodeGraph()
        graph.build(full_source)
        sliced = graph.get_slice(function_name)
        if sliced:
            return f"=== CONTEXT SLICE (Focus: {function_name}) ===\n{sliced}"
        return None

    def _extract_imports_string(self, source_code):
        try:
            tree = ast.parse(source_code)
            lines = source_code.splitlines()
            import_lines = []
            for node in ast.walk(tree):
                if isinstance(node, (ast.Import, ast.ImportFrom)):
                    start_idx = node.lineno - 1
                    end_idx = getattr(node, "end_lineno", node.lineno)
                    import_lines.extend(lines[start_idx:end_idx])
            return "\n".join(import_lines)
        except:
            return ""

    def _construct_segment_context(self, segment, definitions_map=None):
        parts = []
        parts.append(f"=== FILE: {segment.source_file} ===")
        parts.append(
            f"Analyzing: {segment.kind} '{segment.identifier}' (lines {segment.first_line}-{segment.last_line})"
        )
        if segment.imports_section:
            parts.append(f"\n[IMPORTS]\n{segment.imports_section}")
        if segment.class_info:
            parts.append(f"\n[CLASS CONTEXT]\n{segment.class_info}")
        if definitions_map:
            dependencies = self._locate_dependencies(segment.text, definitions_map, segment.source_file)
            if dependencies:
                parts.append(f"\n[EXTERNAL DEPENDENCIES]\n{dependencies}")
        parts.append(f"\n[CODE]\n{segment.with_line_numbers()}")
        return "\n".join(parts)

    def construct_fix_context(
        self, source_code, file_path, issue_line, issue_description, definitions_map=None
    ):
        lines = source_code.splitlines()
        segments = self.partitioning_engine.partition_source(source_code, file_path)
        target_segment = None

        for seg in segments:
            if seg.first_line <= issue_line <= seg.last_line:
                target_segment = seg
                break

        if target_segment:
            context = self.construct_analysis_context(target_segment, definitions_map)
        else:
            start = max(0, issue_line - 20)
            end = min(len(lines), issue_line + 20)
            numbered_lines = []
            for i in range(start + 1, end + 1):
                num_str = str(i).rjust(4)
                numbered_lines.append(num_str + " | " + lines[i - 1])
            context = "[CODE]\n" + "\n".join(numbered_lines)

        return f"=== FIX CONTEXT ===\n[ISSUE] Line {issue_line}: {issue_description}\n\n{context}"

    def _locate_dependencies(self, content, definitions_map, current_file):
        used_names = set(re.findall(r"\b([a-zA-Z_][a-zA-Z0-9_]*)\b", content))
        deps = []

        for name, info in definitions_map.items():
            if isinstance(info, dict):
                def_name = info.get("name", name)
                def_type = info.get("type", "unknown")
                def_file = str(info.get("file", ""))
            else:
                def_name = getattr(info, "name", name)
                def_type = getattr(info, "type", "unknown")
                def_file = str(getattr(info, "filename", ""))

            if def_name in used_names and def_file:
                source_label = (
                    "this file" if def_file == current_file else Path(def_file).name
                )
                deps.append(f"  - {def_name} ({def_type}) from {source_label}")

        return "\n".join(deps[:50])

    def _build_project_index(self, definitions_map, max_entries=150):
        if not definitions_map:
            return ""
        index_entries = []
        for name, info in definitions_map.items():
            if isinstance(info, dict):
                def_name = info.get("name", name)
                def_type = info.get("type", "unknown")
                def_file = str(info.get("file", ""))
            else:
                def_name = getattr(info, "name", name)
                def_type = getattr(info, "type", "unknown")
                def_file = str(getattr(info, "filename", ""))

            short_file = Path(def_file).name if def_file else "?"
            index_entries.append(f"  - {def_name} ({def_type}) [{short_file}]")

        if len(index_entries) > max_entries:
            index_entries = index_entries[:max_entries]
            index_entries.append(f"  ... and {len(definitions_map) - max_entries} more")

        return "\n".join(index_entries)


