"""
Enhanced text processing utilities for markdown normalization and compression.
"""

import re
import logging
from difflib import SequenceMatcher
from typing import List, Tuple, Dict, Optional

logger = logging.getLogger(__name__)

# Mapping from Chinese punctuation to standard ASCII equivalents (for token efficiency)
ZH_PUNCTUATION_MAP: Dict[str, str] = {
    '\uFF0C': ',', '\u3002': '.', '\uFF1B': ';', '\uFF1A': ':',
    '\uFF01': '!', '\uFF1F': '?', '\u201C': '"', '\u201D': '"',
    '\u2018': "'", '\u2019': "'", '\uFF08': '(', '\uFF09': ')',
    '\u3010': '[', '\u3011': ']', '\u3001': ',', '\u2026': '...',
    '\u2014\u2014': '--', '\uFF5E': '~'
}

ZH_PUNCT_PATTERN = re.compile('|'.join(re.escape(key) for key in ZH_PUNCTUATION_MAP))

# Comprehensive emoji pattern covering emoticons, symbols, flags, etc.
EMOJI_PATTERN = re.compile(
    r'[\U0001F600-\U0001F64F'      # emoticons
    r'\U0001F300-\U0001F5FF'       # symbols & pictographs
    r'\U0001F680-\U0001F6FF'       # transport & map
    r'\U0001F1E0-\U0001F1FF'       # flags
    r'\U00002702-\U000027B0'       # dingbats
    r'\U0001F900-\U0001F9FF'       # supplemental symbols
    r'\U0001FA00-\U0001FA6F'       # chess symbols
    r'\U0001FA70-\U0001FAFF'       # symbols extended-A
    r'\U00002600-\U000026FF'       # misc symbols
    r']+', re.UNICODE
)

# Markdown header detection regex
HEADER_REGEX = re.compile(r'^(#{1,6})\s+(.*)', re.MULTILINE)

# Table separator line pattern
TABLE_SEPARATOR_REGEX = re.compile(r'^[\s|:\-]+$')


def extract_sections(content: str) -> List[Tuple[str, str, int]]:
    """Parse *content* into sections based on markdown headers.

    Returns list of tuples: (header_text, section_body, heading_level).
    Preamble before first header is returned with empty header string.
    """
    if not content:
        return []

    parsed_sections: List[Tuple[str, str, int]] = []
    lines = content.split('\n')
    active_header = ''
    active_level = 0
    body_lines: List[str] = []

    for current_line in lines:
        match = HEADER_REGEX.match(current_line)
        if match:
            # Finalize previous section
            section_body = '\n'.join(body_lines).strip()
            if active_header or section_body:
                parsed_sections.append((active_header, section_body, active_level))

            active_header = match.group(2).strip()
            active_level = len(match.group(1))
            body_lines = []
        else:
            body_lines.append(current_line)

    # Handle final section
    final_body = '\n'.join(body_lines).strip()
    if active_header or final_body:
        parsed_sections.append((active_header, final_body, active_level))

    return parsed_sections


def clean_whitespace(text: str) -> str:
    """Normalize excessive blank lines and remove trailing spaces."""
    if not text:
        return ""

    # Reduce triple+ newlines to double newline
    normalized = re.sub(r'\n{3,}', '\n\n', text)

    # Remove trailing whitespace per line
    processed_lines = [line.rstrip() for line in normalized.split('\n')]
    return '\n'.join(processed_lines).strip()


def eliminate_repeated_lines(text: str) -> str:
    """Remove exact duplicate non-empty lines while preserving order."""
    if not text:
        return ""

    seen_items = set()
    output_lines = []

    for line in text.split('\n'):
        stripped = line.strip()
        if not stripped:
            output_lines.append(line)
            continue

        if stripped not in seen_items:
            seen_items.add(stripped)
            output_lines.append(line)

    return '\n'.join(output_lines)


def convert_chinese_punctuation(text: str) -> str:
    """Substitute Chinese full-width punctuation with ASCII alternatives."""
    if not text:
        return ""

    # Process double-em-dash specifically
    text = text.replace('\u2014\u2014', '--')

    # Apply mapping for remaining punctuation
    return ZH_PUNCT_PATTERN.sub(
        lambda match: ZH_PUNCTUATION_MAP.get(match.group(), match.group()), 
        text
    )


def strip_emoji_characters(text: str) -> str:
    """Remove all emoji characters from input text."""
    if not text:
        return ""

    result = EMOJI_PATTERN.sub('', text)
    # Clean up extra spaces created by emoji removal
    result = re.sub(r'  +', ' ', result)
    return result


def filter_empty_headings(text: str) -> str:
    """Eliminate markdown sections lacking substantive content."""
    if not text:
        return ""

    sections = extract_sections(text)
    if not sections:
        return text

    # Identify which sections contain nested subsections
    has_nested_section = [False] * len(sections)

    for idx, (_, _, level) in enumerate(sections):
        if level > 0:
            # Search backwards for parent section
            for parent_idx in range(idx - 1, -1, -1):
                _, _, parent_level = sections[parent_idx]
                if parent_level > 0 and parent_level < level:
                    has_nested_section[parent_idx] = True
                    break

    output_lines: List[str] = []

    for idx, (header, body, level) in enumerate(sections):
        # Skip completely empty entries
        if not header and not body:
            continue

        # Skip header-only sections without children
        if header and not body.strip() and not has_nested_section[idx]:
            continue

        if header:
            output_lines.append('#' * level + ' ' + header)

        if body.strip():
            output_lines.append(body)

        output_lines.append('')  # Section spacing

    return '\n'.join(output_lines).strip()


def simplify_markdown_tables(text: str) -> str:
    """Transform markdown tables into more compact formats.

    Two-column tables become "Key: Value" format.
    Multi-column tables (>2) become labeled key-value pairs.
    Wide tables (>5 columns) retain original structure.
    """
    if not text:
        return ""

    lines = text.split('\n')
    output_lines: List[str] = []
    index = 0

    while index < len(lines):
        current_line = lines[index]

        # Detect table structure: header line followed by separator
        if '|' in current_line and index + 1 < len(lines) and TABLE_SEPARATOR_REGEX.match(lines[index + 1].strip()):
            # Extract column headers
            header_cells = [cell.strip() for cell in current_line.strip().strip('|').split('|')]
            index += 2  # Skip header and separator

            data_rows: List[List[str]] = []

            # Collect table rows
            while index < len(lines) and '|' in lines[index] and lines[index].strip():
                row_cells = [cell.strip() for cell in lines[index].strip().strip('|').split('|')]
                data_rows.append(row_cells)
                index += 1

            num_columns = len(header_cells)

            if num_columns >= 5:
                # Preserve wide tables without header/separator
                for row in data_rows:
                    output_lines.append('| ' + ' | '.join(row) + ' |')

            elif num_columns == 2:
                # Convert two-column tables to key-value format
                for row in data_rows:
                    key_part = row[0] if len(row) > 0 else ''
                    value_part = row[1] if len(row) > 1 else ''
                    if key_part or value_part:
                        output_lines.append(f"- {key_part}: {value_part}")

            else:
                # General multi-column format with labels
                for row in data_rows:
                    formatted_parts = []
                    for col_index, cell_value in enumerate(row):
                        if col_index == 0:
                            formatted_parts.append(cell_value)
                        elif col_index < num_columns:
                            formatted_parts.append(f"{header_cells[col_index]}={cell_value}")
                        else:
                            formatted_parts.append(cell_value)

                    output_lines.append(', '.join(formatted_parts))

        else:
            output_lines.append(current_line)
            index += 1

    return '\n'.join(output_lines)


def consolidate_similar_bullets(text: str, similarity_threshold: float = 0.80) -> str:
    """Merge bullet points with high textual similarity.

    Uses SequenceMatcher ratio; when similarity exceeds threshold,
    retains only the longer variant.
    """
    if not text:
        return ""

    lines = text.split('\n')
    bullet_regex = re.compile(r'^(\s*[-*+]\s+)(.*)')
    output_lines: List[str] = []
    bullet_entries: List[Tuple[str, str, str]] = []  # (prefix, content, original_line)

    def process_bullet_group():
        if not bullet_entries:
            return

        keep_flags = [True] * len(bullet_entries)

        for i in range(len(bullet_entries)):
            if not keep_flags[i]:
                continue

            for j in range(i + 1, len(bullet_entries)):
                if not keep_flags[j]:
                    continue

                similarity = SequenceMatcher(None, 
                                            bullet_entries[i][1], 
                                            bullet_entries[j][1]).ratio()

                if similarity >= similarity_threshold:
                    # Keep longer content
                    if len(bullet_entries[j][1]) > len(bullet_entries[i][1]):
                        keep_flags[i] = False
                        break
                    else:
                        keep_flags[j] = False

        for idx, (prefix, content, original) in enumerate(bullet_entries):
            if keep_flags[idx]:
                output_lines.append(original)

        bullet_entries.clear()

    for line in lines:
        match = bullet_regex.match(line)
        if match:
            bullet_entries.append((match.group(1), match.group(2), line))
        else:
            process_bullet_group()
            output_lines.append(line)

    process_bullet_group()
    return '\n'.join(output_lines)


def combine_concise_bullets(text: str, word_limit: int = 3, max_group_size: int = 10) -> str:
    """Join consecutive short bullet points into single comma-separated items.

    Bullets with <= *word_limit* words are candidates.
    Up to *max_group_size* consecutive short bullets are merged.
    """
    if not text:
        return ""

    bullet_regex = re.compile(r'^(\s*[-*+]\s+)(.*)')
    lines = text.split('\n')
    output_lines: List[str] = []
    short_items: List[str] = []
    current_prefix = '- '

    def finalize_short_items():
        nonlocal current_prefix

        if not short_items:
            return

        if len(short_items) <= 2:
            for item in short_items:
                output_lines.append(current_prefix + item)
        else:
            output_lines.append(current_prefix + ', '.join(short_items))

        short_items.clear()

    for line in lines:
        match = bullet_regex.match(line)
        if match:
            content = match.group(2).strip()
            current_prefix = match.group(1)

            if len(content.split()) <= word_limit:
                short_items.append(content)

                if len(short_items) >= max_group_size:
                    finalize_short_items()
            else:
                finalize_short_items()
                output_lines.append(line)
        else:
            finalize_short_items()
            output_lines.append(line)

    finalize_short_items()
    return '\n'.join(output_lines)

