# Smart Import API - Intelligent certificate/key import endpoint
# Endpoints:
# - POST /api/v2/import/analyze - Analyze content without importing
# - POST /api/v2/import/execute - Execute the import

from flask import Blueprint, request, g
from auth.unified import require_auth
from services.smart_import import SmartImporter
from services.audit_service import AuditService
from utils.response import success_response, error_response
import logging

logger = logging.getLogger(__name__)
bp = Blueprint('smart_import', __name__)

@bp.route('/api/v2/import/analyze', methods=['POST'])
@require_auth(['read:certificates'])
def analyze_import():
    """
    Analyze content for import without actually importing.

    Request body:
    {
        "content": "-----BEGIN CERTIFICATE-----...",
        "password": "REDACTED_CREDENTIAL"
    }

    Response:
    {
        "success": true,
        "data": {
            "objects": [...],
            "chains": [...],
            "matching": {...},
            "validation": {...},
            "summary": {...}
        }
    }
    """
    payload = request.get_json(silent=True)

    if not payload:
        return error_response("No data provided", 400)

    cert_content = payload.get('content')
    if not cert_content:
        return error_response("No content to analyze", 400)

    pwd = payload.get('password')

    try:
        smart_importer = SmartImporter()
        analysis_result = smart_importer.analyze(cert_content, pwd)

        return success_response(data=analysis_result.to_dict())

    except Exception as exc:
        logger.error(f'Smart import analysis failed: {exc}')
        return error_response('Import analysis failed', 500)


@bp.route('/api/v2/import/execute', methods=['POST'])
@require_auth(['write:certificates'])
def execute_import():
    """
    Execute the smart import.

    Request body:
    {
        "content": "-----BEGIN CERTIFICATE-----...",
        "password": "REDACTED_CREDENTIAL",
        "options": {
            "import_cas": true,
            "import_certs": true,
            "import_csrs": true,
            "skip_duplicates": true,
            "description_prefix": "Imported: "
        }
    }

    Response:
    {
        "success": true,
        "data": {
            "certificates_imported": 1,
            "cas_imported": 2,
            "keys_matched": 1,
            "csrs_imported": 0,
            "errors": [],
            "warnings": [],
            "imported_ids": {...}
        }
    }
    """
    payload = request.get_json(silent=True)

    if not payload:
        return error_response("No data provided", 400)

    cert_content = payload.get('content')
    if not cert_content:
        return error_response("No content to import", 400)

    pwd = payload.get('password')
    opts = payload.get('options', {})
    user_name = g.current_user.username if hasattr(g, 'current_user') else 'system'

    try:
        smart_importer = SmartImporter()
        execution_result = smart_importer.execute(cert_content, pwd, opts, user_name)

        AuditService.log_action(
            action='smart_import',
            resource_type='import',
            resource_name='Smart Import',
            details=f'Smart import by {user_name}: {execution_result.to_dict().get("summary", "")}',
            success=execution_result.success
        )

        return success_response(data=execution_result.to_dict())

    except Exception as exc:
        logger.error(f'Smart import execution failed: {exc}')
        return error_response('Import execution failed', 500)


