import os
import json
import yaml
from mindspeed_mm.utils.utils import get_dtype


class ConfigWrapper:
    """
    Alternative implementation of config handling using a more dynamic approach.
    Stores configuration data as instance attributes, supporting nested dictionaries.
    """
    def __init__(self, config_data):
        self._data = {}
        for key, value in config_data.items():
            processed_value = value
            if key == "dtype":
                processed_value = get_dtype(value)
            if isinstance(processed_value, dict):
                processed_value = ConfigWrapper(processed_value)
            self._data[key] = processed_value

    def to_dict(self):
        result = {}
        for key, value in self._data.items():
            if isinstance(value, ConfigWrapper):
                result[key] = value.to_dict()
            else:
                result[key] = value
        return result

    def __repr__(self):
        output_lines = []
        for key, value in self._data.items():
            if isinstance(value, ConfigWrapper):
                output_lines.append(">>>>> {}".format(key))
                output_lines.append(str(value))
            else:
                output_lines.append("{}: {}".format(key, value))
        return "\n".join(output_lines)

    def __str__(self):
        try:
            return self.__repr__()
        except Exception as error:
            return f"An error occurred: {error}"

    def get_attribute(self, key, default=None):
        return self._data.get(key, default)

    def update_attributes(self, **updates):
        updated_keys = []
        remaining_updates = {}

        for key, value in updates.items():
            if key in self._data:
                self._data[key] = value
                updated_keys.append(key)
            else:
                remaining_updates[key] = value

        return remaining_updates


class MMConfiguration:
    """
    Enhanced configuration loader supporting both JSON and YAML formats.
    Implements robust error handling and validation during file loading.
    """
    def __init__(self, file_mapping):
        load_errors = []

        for name, path in file_mapping.items():
            if not path:
                continue

            try:
                absolute_path = os.path.realpath(path)
                config_data = None

                if absolute_path.endswith('.json'):
                    config_data = self._load_json_file(absolute_path)
                elif absolute_path.endswith('.yaml'):
                    with open(absolute_path, 'r') as stream:
                        raw_data = yaml.safe_load(stream)
                        config_data = raw_data.get(name) if isinstance(raw_data, dict) else None

                if config_data is not None:
                    setattr(self, name, ConfigWrapper(config_data))

            except FileNotFoundError as e:
                load_errors.append(f"Warning: Config file not found: {path} - {e}")
            except PermissionError as e:
                load_errors.append(f"Error: Permission denied when reading: {path} - {e}")
            except (json.JSONDecodeError, ValueError) as e:
                load_errors.append(f"Error: Invalid JSON format in {path}: {e}")
            except yaml.YAMLError as e:
                load_errors.append(f"Error: Invalid YAML format in {path}: {e}")
            except Exception as e:
                load_errors.append(f"Error: Unexpected issue loading {path}: {e}")

        if load_errors:
            for err_msg in load_errors:
                print(err_msg)
            raise RuntimeError("One or more configuration files failed to load. See above errors.")

    @staticmethod
    def _load_json_file(file_path):
        with open(file_path, mode='r', encoding='utf-8') as file:
            content = file.read()
        return json.loads(content)


def _register_multimodal_args(parser):
    """Add multimodal-specific command-line arguments to the parser."""
    mm_group = parser.add_argument_group(title="multimodel")
    mm_group.add_argument("--mm-data", type=str, default="")
    mm_group.add_argument("--mm-model", type=str, default="")
    mm_group.add_argument("--mm-tool", type=str, default="")
    return parser


def extend_parser_with_mm_args(parser):
    """Extension point for adding multimodal arguments to argument parser."""
    return _register_multimodal_args(parser)


def merge_mm_configuration(func):
    """Decorator that ensures multimodal configuration is loaded only once."""
    initialized = False

    def wrapper(args):
        func(args)
        nonlocal initialized
        if not initialized:
            validate_external_paths(args)
            initialized = True
    return wrapper


@merge_mm_configuration
def apply_mm_configuration(args):
    """Main function to initialize multimodal configuration from provided paths."""
    if not hasattr(args, "mm"):
        setattr(args, "mm", object())
        config_sources = {
            "model": args.mm_model,
            "data": args.mm_data,
            "tool": args.mm_tool
        }
        args.mm = MMConfiguration(config_sources)


def validate_external_paths(args):
    """
    Comprehensive security check for file paths across multiple repositories.
    Validates against predefined allowed parameters and checks for path traversal risks.
    """
    try:
        script_dir = os.path.dirname(os.path.abspath(__file__))
        validation_file = os.path.join(script_dir, "validate_params.json")
        with open(validation_file, 'r') as vf:
            validation_rules = json.load(vf)
    except OSError:
        print("WARNING: validate_params.json cannot be opened")
        return

    # Check parameters from mindspeed_mm module
    if "mindspeed_mm" in validation_rules:
        for param in validation_rules["mindspeed_mm"].get("params", []):
            if hasattr(args, param) and getattr(args, param):
                verify_file_safety(getattr(args, param), param)

    # Check parameters from mindspeed module
    if "mindspeed" in validation_rules:
        for param in validation_rules["mindspeed"].get("params", []):
            if hasattr(args, param) and getattr(args, param):
                verify_file_safety(getattr(args, param), param)

    # Check parameters from megatron module
    if "megatron" in validation_rules:
        megatron_config = validation_rules["megatron"]
        for param in megatron_config[0].get("params", []) if len(megatron_config) > 0 else []:
            if hasattr(args, param) and getattr(args, param):
                verify_file_safety(getattr(args, param), param)

        # Handle special formatted megatron parameters
        if len(megatron_config) > 1:
            for param in megatron_config[1].get("params", []):
                if hasattr(args, param) and getattr(args, param):
                    extracted_paths = parse_special_megatron_format(param)
                    for path in extracted_paths:
                        verify_file_safety(path, param)

    # Validate MM model configurations
    if "mm_model" in validation_rules and hasattr(args.mm, "model"):
        for param in validation_rules["mm_model"].get("params", []):
            values = extract_nested_values(args.mm.model, param)
            for val in values:
                if val:
                    verify_file_safety(val, param)

    # Validate MM data configurations
    if "mm_data" in validation_rules and hasattr(args.mm, "data"):
        for param in validation_rules["mm_data"].get("params", []):
            values = extract_nested_values(args.mm.data, param)
            for val in values:
                if val:
                    verify_file_safety(val, param)

    # Validate MM tool configurations
    if "mm_tool" in validation_rules and hasattr(args.mm, "tool"):
        for param in validation_rules["mm_tool"].get("params", []):
            values = extract_nested_values(args.mm.tool, param)
            for val in values:
                if val:
                    verify_file_safety(val, param)


def verify_file_safety(file_path, parameter_name, root_directory=None):
    """
    Perform comprehensive safety verification on file paths:
    - Existence check
    - Symbolic link detection
    - Path traversal prevention
    """
    if root_directory is None:
        root_directory = os.getcwd()

    # Verify file existence
    try:
        if not os.path.exists(file_path):
            return False
    except OSError:
        return False

    # Check for symbolic links
    try:
        from mindspeed_mm.utils.security_utils.validate_path import normalize_path
        normalized, has_symlink = normalize_path(file_path)
        if has_symlink:
            print(
                "WARNING: [{}] {} is a symbolic link. Normalized path: {}".format(
                    parameter_name, file_path, normalized
                )
            )
            return False
    except OSError:
        return False

    # Prevent path traversal attacks
    try:
        real_path = os.path.realpath(file_path)
        safe_base = os.path.abspath(root_directory)
        if not real_path.startswith(safe_base + os.sep) and real_path != safe_base:
            print("WARNING: [{}] {} attempts to access an unauthorized directory".format(
                parameter_name, file_path
            ))
            return False
    except OSError:
        return False

    return True


def parse_special_megatron_format(input_string):
    """
    Parse special Megatron-style parameter strings into individual components.
    Handles cases where numeric values alternate with path strings.
    """
    def is_numeric(text):
        cleaned = text.strip() if isinstance(text, str) else text
        try:
            float(cleaned)
            return True
        except (ValueError, TypeError):
            return False

    parts = input_string.split()
    if len(parts) <= 1:
        return parts

    if is_numeric(parts[0]):
        return [parts[i * 2] for i in range(len(parts) // 2)]
    else:
        return parts


def extract_nested_values(config_obj, target_key):
    """
    Extract all values associated with a given key from nested configuration objects.
    Supports dot-notation keys and list traversals.
    """
    current_level = [config_obj.to_dict()] if hasattr(config_obj, 'to_dict') else [config_obj]

    for segment in target_key.split('.'):
        next_level = []
        for item in current_level:
            if not item or not isinstance(item, dict):
                continue
            if segment in item:
                segment_value = item[segment]
                if not segment_value:
                    continue
                if isinstance(segment_value, list):
                    next_level.extend(segment_value)
                else:
                    next_level.append(segment_value)
        if next_level:
            current_level = next_level
        else:
            return []

    return current_level

