from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    """ From a given list of integers, generate a list of rolling maximum element found until given moment
    in the sequence.
    >>> rolling_max([1, 2, 3, 2, 3, 4, 2])
    [1, 2, 3, 3, 3, 4, 4]
    """
    if not numbers:
        return []

    result = [numbers[0]]
    for i in range(1, len(numbers)):
        if numbers[i] > result[-1]:
            result.append(numbers[i])
        else:
            result.append(result[-1])

    return result

# Calculate various configuration parameters for vLLM on HPU

import math

def safe_max(val, default):
    return max(1, val) if val is not None else default

def safe_min(val1, val2):
    return min(val1, val2)

def calc_VLLM_PROMPT_BS_BUCKET_MAX(ctx):
    return safe_max(ctx.get('VLLM_PROMPT_BS_BUCKET_MAX', 1), 1)

def calc_MAX_NUM_BATCHED_TOKENS(ctx):
    return safe_max(ctx.get('MAX_NUM_BATCHED_TOKENS', 1), 1)

def calc_TENSOR_PARALLEL_SIZE(ctx):
    tp_size = ctx.get('TENSOR_PARALLEL_SIZE', 1)
    return max(1, min(8, tp_size))

def calc_MAX_MODEL_LEN(ctx):
    return safe_max(ctx.get('MAX_MODEL_LEN', 1), 1)

def calc_PT_HPU_ENABLE_LAZY_COLLECTIVES(ctx):
    return ctx.get('TENSOR_PARALLEL_SIZE', 1) > 1

def calc_VLLM_CONTIGUOUS_PA(ctx):
    return not bool(ctx.get('ENABLE_PREFIX_CACHING', False))

def calc_VLLM_DEFRAG(ctx):
    return bool(ctx.get('VLLM_CONTIGUOUS_PA', True))

def calc_MODEL_MEM_FROM_CONFIG(ctx):
    return float(ctx.get('MODEL_MEM_FROM_CONFIG', 0.0))

def calc_DEVICE_HPU_MEM(ctx):
    device_name = ctx.get('DEVICE_NAME', 'unknown')
    hpu_mem_map = ctx.get('HPU_MEM', {})
    return hpu_mem_map.get(device_name, 0.0)

def calc_TOTAL_GPU_MEM(ctx):
    return ctx['DEVICE_HPU_MEM'] * ctx['TENSOR_PARALLEL_SIZE']

def calc_MODEL_MEM_IN_GB(ctx):
    model_mem_config = ctx.get('MODEL_MEM_FROM_CONFIG', 0.0)
    quant_dtype = ctx.get('QUANT_DTYPE', 16)
    model_dtype = ctx.get('MODEL_DTYPE', 16)
    return (model_mem_config * quant_dtype / model_dtype) / (1024 ** 3)

def calc_USABLE_MEM(ctx):
    usable = (ctx['TOTAL_GPU_MEM'] / ctx['TENSOR_PARALLEL_SIZE'] -
              ctx.get('UNAVAILABLE_MEM_ABS', 0.0) -
              (ctx['MODEL_MEM_IN_GB'] / ctx['TENSOR_PARALLEL_SIZE']) -
              ctx.get('PROFILER_MEM_OVERHEAD', 0.0))
    return max(0.0, usable)

def calc_GPU_MEMORY_UTIL_TEMP(ctx):
    usable_mem = ctx['USABLE_MEM']
    if usable_mem <= 0:
        return 0.0
    return 1 - ctx.get('GPU_FREE_MEM_TARGET', 0.0) / usable_mem

def calc_GPU_MEM_UTILIZATION(ctx):
    user_util = ctx.get('GPU_MEM_UTILIZATION')
    if user_util is not None:
        return user_util
    temp_util = ctx['GPU_MEMORY_UTIL_TEMP']
    return math.floor(temp_util * 100) / 100

def calc_HEAD_DIM(ctx):
    head_dim = ctx.get('HEAD_DIM')
    hidden_size = ctx.get('HIDDEN_SIZE', 4096)
    num_attn_heads = ctx.get('NUM_ATTENTION_HEADS', 32)

    if head_dim is None or math.isnan(head_dim):
        return hidden_size / num_attn_heads
    return head_dim

def calc_KV_CACHE_PER_SEQ(ctx):
    head_dim = calc_HEAD_DIM(ctx)
    max_len = ctx.get('MAX_MODEL_LEN', 2048)
    num_layers = ctx.get('NUM_HIDDEN_LAYERS', 32)
    num_kv_heads = ctx.get('NUM_KEY_VALUE_HEADS', 8)
    cache_dtype_bytes = ctx.get('CACHE_DTYPE_BYTES', 2)

    numerator = 2 * max_len * num_layers * head_dim * num_kv_heads * cache_dtype_bytes
    return numerator / (1024 ** 3)

def calc_EST_MAX_NUM_SEQS(ctx):
    usable_mem = ctx['USABLE_MEM']
    gpu_util = ctx['GPU_MEM_UTILIZATION']
    kv_per_seq = ctx['KV_CACHE_PER_SEQ']
    tp_size = ctx['TENSOR_PARALLEL_SIZE']

    if kv_per_seq <= 0:
        return 1
    return max(1, tp_size * usable_mem * gpu_util / kv_per_seq)

def calc_EST_HPU_BLOCKS(ctx):
    max_len = ctx.get('MAX_MODEL_LEN', 2048)
    est_max_seqs = ctx['EST_MAX_NUM_SEQS']
    block_size = ctx.get('BLOCK_SIZE', 128)

    return max(1, int(max_len * est_max_seqs / block_size))

def calc_DECODE_BS_RAMP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    if exp_bucketing:
        return 1 + math.ceil(math.log2(ctx['EST_MAX_NUM_SEQS']))
    else:
        step = ctx.get('VLLM_DECODE_BS_BUCKET_STEP', 1)
        minimum = ctx.get('VLLM_DECODE_BS_BUCKET_MIN', 1)
        if minimum <= 0 or step <= minimum:
            return 1
        return 1 + int(math.log(step / minimum, 2))

def calc_DECODE_BS_STEP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    if exp_bucketing:
        return 0
    else:
        step = ctx.get('VLLM_DECODE_BS_BUCKET_STEP', 1)
        minimum = ctx.get('VLLM_DECODE_BS_BUCKET_MIN', 1)
        est_max_seqs = ctx['EST_MAX_NUM_SEQS']
        if step <= 0:
            return 0
        return max(0, int(1 + (est_max_seqs - step) / step))

def calc_DECODE_BLOCK_RAMP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    if exp_bucketing:
        return 1 + math.ceil(math.log2(ctx['EST_HPU_BLOCKS']))
    else:
        step = ctx.get('VLLM_DECODE_BLOCK_BUCKET_STEP', 1)
        minimum = ctx.get('VLLM_DECODE_BLOCK_BUCKET_MIN', 1)
        if minimum <= 0 or step <= minimum:
            return 1
        return 1 + int(math.log(step / minimum, 2))

def calc_DECODE_BLOCK_STEP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    if exp_bucketing:
        return 0
    else:
        step = ctx.get('VLLM_DECODE_BLOCK_BUCKET_STEP', 1)
        minimum = ctx.get('VLLM_DECODE_BLOCK_BUCKET_MIN', 1)
        est_hpu_blocks = ctx['EST_HPU_BLOCKS']
        if step <= 0:
            return 0
        return max(0, int(1 + (est_hpu_blocks - step) / step))

def calc_NUM_DECODE_GRAPHS(ctx):
    ramp_bs = ctx['DECODE_BS_RAMP_GRAPHS']
    step_bs = ctx['DECODE_BS_STEP_GRAPHS']
    ramp_block = ctx['DECODE_BLOCK_RAMP_GRAPHS']
    step_block = ctx['DECODE_BLOCK_STEP_GRAPHS']

    decode_graphs = (ramp_bs + step_bs) * (ramp_block + step_block)

    if ctx.get('VLLM_CONTIGUOUS_PA', False):
        return max(1, decode_graphs)
    else:
        return max(1, decode_graphs // 2)

def calc_PROMPT_BS_RAMP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    max_prompt_bs = ctx.get('VLLM_PROMPT_BS_BUCKET_MAX', 1)

    if exp_bucketing:
        return 1 + math.ceil(math.log2(max_prompt_bs))
    else:
        step = ctx.get('VLLM_PROMPT_BS_BUCKET_STEP', 1)
        minimum = ctx.get('VLLM_PROMPT_BS_BUCKET_MIN', 1)
        limit = min(max_prompt_bs, step)
        if minimum <= 0 or limit <= minimum:
            return 1
        return 1 + int(math.log(limit / minimum, 2))

def calc_PROMPT_BS_STEP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    if exp_bucketing:
        return 0
    else:
        step = ctx.get('VLLM_PROMPT_BS_BUCKET_STEP', 1)
        max_prompt_bs = ctx.get('VLLM_PROMPT_BS_BUCKET_MAX', 1)
        if step <= 0:
            return 0
        return max(0, int(1 + (max_prompt_bs - step) / step))

def calc_PROMPT_SEQ_RAMP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    max_batched_tokens = ctx.get('MAX_NUM_BATCHED_TOKENS', 1)

    if exp_bucketing:
        return 1 + math.ceil(math.log2(max_batched_tokens))
    else:
        step = ctx.get('VLLM_PROMPT_QUERY_BUCKET_STEP', 1)
        minimum = ctx.get('VLLM_PROMPT_QUERY_BUCKET_MIN', 1)
        if minimum <= 0 or step <= minimum:
            return 1
        return 1 + int(math.log(step / minimum, 2))

def calc_PROMPT_SEQ_STEP_GRAPHS(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    if exp_bucketing:
        return 0
    else:
        step = ctx.get('VLLM_PROMPT_QUERY_BUCKET_STEP', 1)
        max_batched_tokens = ctx.get('MAX_NUM_BATCHED_TOKENS', 1)
        max_model_len = ctx.get('MAX_MODEL_LEN', 2048)
        effective_max = min(max_batched_tokens, max_model_len)
        if step <= 0:
            return 0
        return int(1 + (effective_max - step) / step)

def calc_EST_NUM_PROMPT_GRAPHS(ctx):
    prompt_bs_ramp = ctx['PROMPT_BS_RAMP_GRAPHS']
    prompt_bs_step = ctx['PROMPT_BS_STEP_GRAPHS']
    prompt_seq_ramp = ctx['PROMPT_SEQ_RAMP_GRAPHS']
    prompt_seq_step = ctx['PROMPT_SEQ_STEP_GRAPHS']

    prompt_bs_graphs = prompt_bs_ramp + prompt_bs_step
    prompt_seq_graphs = prompt_seq_ramp + prompt_seq_step

    graphs_2d = prompt_bs_graphs * prompt_seq_graphs

    if prompt_bs_graphs > 1:
        graphs_2d //= 2

    max_model_len = ctx.get('MAX_MODEL_LEN', 2048)
    min_prompt_query = ctx.get('VLLM_PROMPT_QUERY_BUCKET_MIN', 1)
    max_batched_tokens = ctx.get('MAX_NUM_BATCHED_TOKENS', 1)
    block_size = ctx.get('BLOCK_SIZE', 128)

    ctx_blocks_max = max(1, (max_model_len - min_prompt_query) / block_size)
    ctx_blocks_min = max(1, (max_model_len - max_batched_tokens) / block_size)

    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)

    if exp_bucketing:
        ctx_block_graphs_max = max(1, math.ceil(math.log2(ctx_blocks_max)))
        ctx_block_graphs_min = max(1, math.ceil(math.log2(ctx_blocks_min)))
    else:
        ctx_block_step = ctx.get('VLLM_PROMPT_CTX_BUCKET_STEP', 1)
        if ctx_block_step <= 0:
            ctx_block_step = 1
        ctx_block_graphs_max = max(1, ctx_blocks_max / ctx_block_step)
        ctx_block_graphs_min = max(1, ctx_blocks_min / ctx_block_step)

    graphs_3d = max(1, graphs_2d * (ctx_block_graphs_max + ctx_block_graphs_min) / 2)
    return graphs_3d

def calc_EST_PROMPT_GRAPH_MEM(ctx):
    exp_bucketing = ctx.get('VLLM_EXPONENTIAL_BUCKETING', False)
    approx_mem_per_graph = ctx.get('APPROX_MEM_PER_GRAPH_MB', 100)

    if exp_bucketing:
        return ctx['EST_NUM_PROMPT_GRAPHS'] * approx_mem_per_graph
    else:
        max_model_len = ctx.get('MAX_MODEL_LEN', 2048)
        factor = max(1, max_model_len / 4352)
        return ctx['EST_NUM_PROMPT_GRAPHS'] * approx_mem_per_graph * pow(factor, 0.8552)

def calc_EST_DECODE_GRAPH_MEM(ctx):
    approx_mem_per_graph = ctx.get('APPROX_MEM_PER_GRAPH_MB', 100)
    return ctx['NUM_DECODE_GRAPHS'] * approx_mem_per_graph

def calc_EST_GRAPH_PROMPT_RATIO(ctx):
    prompt_mem = calc_EST_PROMPT_GRAPH_MEM(ctx)
    decode_mem = calc_EST_DECODE_GRAPH_MEM(ctx)
    total_mem = prompt_mem + decode_mem
    if total_mem == 0:
        return 0.0
    return prompt_mem / total_mem

def calc_DECODE_GRAPH_TARGET_GB(ctx):
    decode_mem_mb = calc_EST_DECODE_GRAPH_MEM(ctx)
    return math.ceil(decode_mem_mb / 1024 * 100) / 100

def calc_EST_GRAPH_RESERVE_MEM(ctx):
    decode_target_gb = ctx['DECODE_GRAPH_TARGET_GB']
    usable_mem = ctx['USABLE_MEM']
    gpu_util = ctx['GPU_MEM_UTILIZATION']
    graph_prompt_ratio = ctx['EST_GRAPH_PROMPT_RATIO']

    denominator = usable_mem * gpu_util * (1 - graph_prompt_ratio)
    if denominator <= 0:
        return 0.01
    reserve = decode_target_gb / denominator
    return math.ceil(reserve * 100) / 100

def calc_VLLM_GRAPH_RESERVED_MEM(ctx):
    est_reserve = ctx['EST_GRAPH_RESERVE_MEM']
    return min(max(est_reserve, 0.01), 0.5)

def calc_KV_CACHE_MEM(ctx):
    usable_mem = ctx['USABLE_MEM']
    gpu_util = ctx['GPU_MEM_UTILIZATION']
    graph_reserved = ctx['VLLM_GRAPH_RESERVED_MEM']
    return usable_mem * gpu_util * (1 - graph_reserved)

def calc_MAX_NUM_SEQS(ctx):
    # If user provided, just clamp to min 1
    if ctx.get('MAX_NUM_SEQS') is not None:
        return max(1, ctx['MAX_NUM_SEQS'])

    # Otherwise, calculate
    kv_cache_mem = ctx['KV_CACHE_MEM']
    kv_per_seq = ctx['KV_CACHE_PER_SEQ']
    tp_size = ctx['TENSOR_PARALLEL_SIZE']

    if kv_per_seq <= 0:
        return 1

    val = tp_size * kv_cache_mem / kv_per_seq

    # Round down for plugin as WA
    decode_bs_step = ctx.get('VLLM_DECODE_BS_BUCKET_STEP', 1)
    if val < decode_bs_step:
        val = pow(2, math.floor(math.log2(val))) if val > 0 else 1
    else:
        val = max(1, int(val / decode_bs_step)) * decode_bs_step

    # Special limit for Vision-Instruct models
    special_models = ['meta-llama/Llama-3.2-11B-Vision-Instruct', 
                      'meta-llama/Llama-3.2-90B-Vision-Instruct']
    if ctx.get('MODEL') in special_models and val > 128:
        print(f"{ctx['MODEL']} currently does not support max-num-seqs > 128. "
              "Limiting max-num-seqs to 128")
        val = 128

    if val < 1:
        raise ValueError("Not enough memory for kv cache. Increase TENSOR_PARALLEL_SIZE or "
                         "reduce MAX_MODEL_LEN or increase bucket step")

    return val

def calc_VLLM_DECODE_BLOCK_BUCKET_MAX(ctx):
    max_seqs = ctx['MAX_NUM_SEQS']
    max_len = ctx.get('MAX_MODEL_LEN', 2048)
    return max(128, math.ceil((max_seqs * max_len) / 128))

# Map parameter names to calculation functions
PARAM_CALC_FUNCS = {
    "VLLM_PROMPT_BS_BUCKET_MAX": calc_VLLM_PROMPT_BS_BUCKET_MAX,
