import os
import re
import select
import sys
import termios
import time
import tty
from typing import BinaryIO, Final
from klaude_code.log import DebugType, log_debug

# Constants for terminal control sequences
OSC_END_SEQUENCE: Final[bytes] = b"\x1b\\"  # ESC \
BEL_CODE: Final[int] = 7

# Regex pattern to extract RGB values from OSC 11 responses
_TERMINAL_BG_PATTERN = re.compile(r"\x1b]11;([^\x07\x1b\\]*)")

# Cache storing the most recently detected background color (R, G, B)
_cached_bg_color: tuple[int, int, int] | None = None


def is_terminal_light_background(timeout: float = 0.5) -> bool | None:
    """
    Determine if the terminal uses a light background.

    Returns:
        True if background appears light, False if dark, None if detection fails.
    """
    rgb_values = _fetch_osc_color(slot=11, timeout=timeout)
    if rgb_values is None:
        return None

    global _cached_bg_color
    _cached_bg_color = rgb_values
    r, g, b = rgb_values

    # Compute luminance using standard relative luminance formula
    luminance = 0.299 * float(r) + 0.587 * float(g) + 0.114 * float(b)
    return luminance > 128.0


def get_cached_terminal_background() -> tuple[int, int, int] | None:
    """
    Retrieve the last successfully captured terminal background color.

    Must be called after `is_terminal_light_background()` has run successfully.
    """
    return _cached_bg_color


def _fetch_osc_color(slot: int, timeout: float) -> tuple[int, int, int] | None:
    """
    Query an OSC color slot (e.g., 10 for foreground, 11 for background).

    Sends query via /dev/tty and parses the response.
    """
    if sys.platform == "win32":
        return None

    terminal_type = os.getenv("TERM", "").lower()
    if terminal_type in {"", "dumb"}:
        return None

    try:
        with open("/dev/tty", "r+b", buffering=0) as tty_stream:
            fd = tty_stream.fileno()
            if not os.isatty(fd):
                return None

            try:
                saved_settings = termios.tcgetattr(fd)
            except Exception as err:
                log_debug(
                    f"Could not retrieve termios settings: {err}",
                    debug_type=DebugType.TERMINAL,
                )
                saved_settings = None

            try:
                if saved_settings is not None:
                    tty.setcbreak(fd)

                _transmit_osc_request(tty_stream, slot)
                raw_response = _collect_osc_data(fd, timeout=timeout)

            finally:
                if saved_settings is not None:
                    try:
                        termios.tcsetattr(fd, termios.TCSADRAIN, saved_settings)
                    except Exception as err:
                        log_debug(
                            f"Failed to restore termios state: {err}",
                            debug_type=DebugType.TERMINAL,
                        )

    except OSError as err:
        log_debug(
            f"Error accessing /dev/tty for OSC query: {err}",
            debug_type=DebugType.TERMINAL,
        )
        return None

    if not raw_response:
        return None

    return _interpret_osc_response(raw_response)


def _transmit_osc_request(tty_stream: BinaryIO, slot: int) -> None:
    """Send OSC request to query color slot."""
    command = f"\x1b]{slot};?\x1b\\".encode("ascii", errors="ignore")
    try:
        tty_stream.write(command)
        tty_stream.flush()
    except Exception as err:
        log_debug(
            f"OSC transmission failed: {err}",
            debug_type=DebugType.TERMINAL,
        )


def _collect_osc_data(fd: int, timeout: float) -> bytes | None:
    """Read OSC response data until BEL or ST terminator."""
    end_time = time.monotonic() + max(timeout, 0.0)
    buffer = bytearray()

    while True:
        remaining = end_time - time.monotonic()
        if remaining <= 0:
            break

        ready, _, _ = select.select([fd], [], [], remaining)
        if not ready:
            continue

        try:
            chunk = os.read(fd, 1024)
        except Exception as err:
            log_debug(
                f"Error reading OSC data: {err}",
                debug_type=DebugType.TERMINAL,
            )
            break

        if not chunk:
            break

        buffer.extend(chunk)

        # Check for BEL termination
        if BEL_CODE in buffer:
            idx = buffer.index(BEL_CODE)
            return bytes(buffer[: idx + 1])

        # Check for ST termination (ESC \)
        st_pos = buffer.find(OSC_END_SEQUENCE)
        if st_pos != -1:
            return bytes(buffer[: st_pos + len(OSC_END_SEQUENCE)])

    return bytes(buffer) if buffer else None


def _interpret_osc_response(data: bytes) -> tuple[int, int, int] | None:
    """Parse OSC payload into RGB triple."""
    try:
        text = data.decode("ascii", errors="ignore")
    except LookupError:
        return None

    match = _TERMINAL_BG_PATTERN.search(text)
    if not match:
        return None

    payload = match.group(1).strip()
    # Extract only first segment before any semicolon
    payload = payload.split(";", 1)[0].strip()

    return _extract_rgb(payload)


def _extract_rgb(spec: str) -> tuple[int, int, int] | None:
    """Parse color specification string into (R, G, B)."""
    spec = spec.strip()

    # Handle xterm-style format: rgb:rrrr/gggg/bbbb
    if spec.lower().startswith("rgb:"):
        body = spec[4:]
        components = body.split("/")
        if len(components) != 3:
            return None

        try:
            r_val = _normalize_hex_value(components[0])
            g_val = _normalize_hex_value(components[1])
            b_val = _normalize_hex_value(components[2])
        except ValueError:
            return None

        return r_val, g_val, b_val

    # Handle simple hex format: #rrggbb
    if spec.startswith("#") and len(spec) == 7:
        try:
            r_val = int(spec[1:3], 16)
            g_val = int(spec[3:5], 16)
            b_val = int(spec[5:7], 16)
        except ValueError:
            return None

        return r_val, g_val, b_val

    return None


def _normalize_hex_value(hex_part: str) -> int:
    """Convert variable-length hex component to 0-255 range."""
    if not hex_part:
        raise ValueError("Empty hex component")

    value = int(hex_part, 16)
    max_possible = (16 ** len(hex_part)) - 1
    if max_possible <= 0:
        raise ValueError("Invalid hex width")

    normalized = round((value / float(max_possible)) * 255.0)
    return max(0, min(255, int(normalized)))

import os
import platform
import shutil
import subprocess
from collections import defaultdict
import psutil
import re
from vllm.logger import logger
from vllm_ascend.utils import AscendDeviceType, get_ascend_device_type

# Constants
CPU_MASK_WIDTH = 32  # bits per mask group
MIN_CORES_PER_NPU = 5  # IRQ(2) + main(1+) + acl(1) + release(1)
ALLOWED_CPUS_FILE = "/proc/self/status"
VISIBLE_DEVICES_ENV = os.getenv("ASCEND_RT_VISIBLE_DEVICES")

BINDING_MODES = {
    "topo_affinity": "topo_affinity",
    "global_slice": "global_slice"
}

DEVICE_BINDING_POLICY = {
    AscendDeviceType.A2: BINDING_MODES["topo_affinity"],
    AscendDeviceType.A3: BINDING_MODES["global_slice"],
    AscendDeviceType._310P: BINDING_MODES["topo_affinity"],
}


def is_arm_architecture() -> bool:
    arch = platform.machine().lower()
    if arch in {"x86_64", "amd64", "i386", "i686"}:
        return False
    if arch.startswith(("aarch64", "arm64", "arm")):
        return True
    logger.warning(f"Unknown CPU architecture '{arch}', CPU binding will be disabled.")
    return False


def run_cmd(cmd_args: list[str]) -> tuple[str, int]:
    try:
        proc = subprocess.Popen(cmd_args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out, _ = proc.communicate(timeout=1000)
        return out.decode(), proc.returncode
    except Exception as e:
        logger.error(f"Command execution failed: {e}")
        return "", -1


class NpuTopologyInfo:
    def __init__(self):
        self.chip_map = self._fetch_npu_topology()
        self.active_logical_ids = self._collect_active_npus()
        self.cpu_affinity = self._parse_cpu_affinity()
        self.all_logical_npus = sorted(self._gather_all_logic_ids())

    @staticmethod
    def _expand_cpu_ranges(range_str: str) -> list[int]:
        cpus = []
        for segment in range_str.split(","):
            if "-" in segment:
                start, end = map(int, segment.split("-"))
                cpus.extend(range(start, end + 1))
            else:
                cpus.append(int(segment))
        return cpus

    def _fetch_npu_topology(self) -> dict[str, dict[str, str]]:
        output, code = run_cmd(["npu-smi", "info", "-m"])
        if code != 0 or not output.strip():
            return {}
        lines = output.strip().split("\n")[1:]
        topology = {}
        for line in lines:
            parts = line.strip().split()
            if len(parts) < 3:
                continue
            board_id, chip_id, logic_id = parts[:3]
            if not logic_id.isdigit():
                continue
            topology.setdefault(board_id, {})[chip_id] = logic_id
        return topology

    def _gather_all_logic_ids(self) -> set[int]:
        ids = set()
        for chip_data in self.chip_map.values():
            for logical_id in chip_data.values():
                if logical_id.isdigit():
                    ids.add(int(logical_id))
        return ids

    def _collect_active_npus(self) -> list[int]:
        output, code = run_cmd(["npu-smi", "info"])
        if code != 0:
            raise RuntimeError("Failed to retrieve active NPU info via npu-smi")
        lines = output.strip().splitlines()
        active_set = set()
        in_proc_section = False
        for line in lines:
            stripped = line.strip()
            if "Process id" in stripped and stripped.startswith("| NPU"):
                in_proc_section = True
                continue
            if not in_proc_section:
                continue
            if not stripped.startswith("|"):
                continue
            fields = [f.strip() for f in stripped.strip("|").split("|")]
            if len(fields) < 2:
                continue
            try:
                board_chip = fields[0].split()
                board_id, chip_id = board_chip[0], board_chip[1]
                if not board_id.isdigit() or not chip_id.isdigit():
                    continue
                logical_id = self.chip_map.get(board_id, {}).get(chip_id)
                if not logical_id or not logical_id.isdigit():
                    raise RuntimeError("Missing or invalid logical NPU ID mapping.")
                active_set.add(int(logical_id))
            except (IndexError, ValueError):
                continue
        if VISIBLE_DEVICES_ENV:
            visible_ids = {int(x) for x in VISIBLE_DEVICES_ENV.split(",")}
            active_set &= visible_ids
        if not active_set:
            raise RuntimeError("No active NPUs detected.")
        return sorted(active_set)

    def _parse_cpu_affinity(self) -> dict[int, list[int]]:
        affinity_map = {}
        output, code = run_cmd(["npu-smi", "info", "-t", "topo"])
        if code != 0:
            return affinity_map
        idx = 0
        for line in output.splitlines():
            if line.startswith("NPU"):
                tokens = line.split()
                last_token = tokens[-1]
                if last_token != "Affinity":
                    affinity_map[idx] = self._expand_cpu_ranges(last_token)
                idx += 1
        return affinity_map


class CpuResourceAllocator:
    def __init__(self, global_rank: int):
        self.rank = global_rank
        self.topology = NpuTopologyInfo()
        self.numa_layout = {}
        self.node_to_cpus = defaultdict(list)
        self.npu_core_pool = {}
        self.main_threads = {}
        self.acl_threads = {}
        self.release_threads = {}

    @staticmethod
    def encode_cpu_mask(cpu_index: int) -> str:
        group = cpu_index // CPU_MASK_WIDTH
        offset = cpu_index % CPU_MASK_WIDTH
        value = 1 << offset
        hex_val = f"{value:08x}"
        full_mask = hex_val
        for _ in range(group):
            full_mask += ",00000000"
        return full_mask

    @staticmethod
    def extract_thread_mapping(proc_output: str) -> dict[str, dict[str, list[str]]]:
        thread_map = {}
        pattern = r'^(\d+)\s+(\d+)\s+.*?(acl_thread|release_thread)'
        for line in proc_output.splitlines():
            match = re.match(pattern, line)
            if not match:
                continue
            main_pid, sub_pid, thread_type = match.groups()
            if main_pid not in thread_map:
                thread_map[main_pid] = {"acl_thread": [], "release_thread": []}
            thread_map[main_pid][thread_type].append(sub_pid)
        return thread_map

    @staticmethod
    def apply_cpu_binding(pid: str, cpu_list: list[int], include_subthreads: bool) -> None:
        if not cpu_list:
            return
        cpu_str = ",".join(map(str, cpu_list))
        cmd = ["taskset", "-acp" if include_subthreads else "-cp", cpu_str, pid]
        _, ret = run_cmd(cmd)
        if ret != 0:
            raise RuntimeError(f"Failed to bind process {pid} to CPUs: {cpu_str}")

    def _build_numa_topology(self) -> None:
        output, code = run_cmd(["lscpu", "-e=CPU,NODE"])
        if code != 0:
            raise RuntimeError("Failed to retrieve NUMA topology via lscpu.")
        for line in output.strip().splitlines():
            parts = line.strip().split()
            if len(parts) != 2 or not parts[0].isdigit():
                continue
            cpu_id, node_id = map(int, parts)
            self.numa_layout[cpu_id] = node_id
            self.node_to_cpus[node_id].append(cpu_id)
        if not self.node_to_cpus:
            raise RuntimeError("NUMA node information could not be retrieved.")

    def _slice_global_cpus(self) -> None:
        allowed = sorted(set(self.topology.active_logical_ids))
        total_npus = len(self.topology.all_logical_npus) or len(self.topology.active_logical_ids)
        if total_npus <= 0:
            return
        all_cpus = sorted(set(self._read_allowed_cpus()))
        total_cores = len(all_cpus)
        if total_cores == 0:
            return
        base_per_npu = total_cores // total_npus
        remainder = total_cores % total_npus
        logger.debug(
            f"[cpu_global_slice] rank={self.rank}, visible={VISIBLE_DEVICES_ENV}, "
            f"npus={total_npus}, cores={total_cores}, base={base_per_npu}, extra={remainder}"
        )
        if base_per_npu < MIN_CORES_PER_NPU:
            raise RuntimeError(
                f"Not enough CPUs: need at least {total_npus * MIN_CORES_PER_NPU}, "
                f"but only {total_cores} available."
            )

        def _assign_slice(npu_idx: int) -> list[int]:
            start = npu_idx * base_per_npu + min(npu_idx, remainder)
            take = base_per_npu + (1 if npu_idx < remainder else 0)
            return all_cpus[start:start + take]

        for npu_id in self.topology.active_logical_ids:
            if not (0 <= npu_id < total_npus):
                raise RuntimeError(f"NPU ID {npu_id} out of range [0, {total_npus})")
            cpus = _assign_slice(npu_id)
            if len(cpus) < MIN_CORES_PER_NPU:
                raise RuntimeError(f"NPU{npu_id} assigned too few CPUs: {len(cpus)}")
            self.npu_core_pool[npu_id] = cpus

    def _read_allowed_cpus(self) -> list[int]:
        if not os.path.exists(ALLOWED_CPUS_FILE):
            return []
        with open(ALLOWED_CPUS_FILE) as f:
            for line in f:
                if line.startswith("Cpus_allowed_list"):
                    return self._expand_cpu_ranges(line.split()[1])
        raise RuntimeError("Cpus_allowed_list not found in /proc/self/status")

    @staticmethod
    def _expand_cpu_ranges(range_str: str) -> list[int]:
        cpus = []
        for part in range_str.split(","):
            if "-" in part:
                lo, hi = map(int, part.split("-"))
                cpus.extend(range(lo, hi + 1))
            else:
                cpus.append(int(part))
        return cpus

    def _extend_with_numa_neighbors(self, core_list: list[int]) -> list[int]:
        if not core_list:
            return []
        nodes = {self.numa_layout[c] for c in core_list}
        if len(nodes) != 1:
            return core_list
        current_node = list(nodes)[0]
        next_node = (current_node + 1) % len(self.node_to_cpus)
        extended = core_list[:]
        for candidate in self.node_to_cpus[next_node]:
            if candidate in self._read_allowed_cpus():
                extended.append(candidate)
        return sorted(set(extended))

    def _setup_topo_based_pools(self) -> None:
        for npu_id in self.topology.active_logical_ids:
            raw_affinity = self.topology.cpu_affinity.get(npu_id, [])
            filtered = [c for c in raw_affinity if c in self._read_allowed_cpus()]
            if not filtered:
                raise RuntimeError("No overlapping CPUs between affinity and allowed list.")
            extended = self._extend_with_numa_neighbors(filtered)
            self.npu_core_pool[npu_id] = extended

        # Group identical pools and redistribute evenly
        pool_groups = defaultdict(list)
        for npu, cpus in self.npu_core_pool.items():
            pool_groups[tuple(cpus)].append(npu)

        final_pool = {}
        for cpus_tuple, npus in pool_groups.items():
            if len(npus) == 1:
                final_pool[npus[0]] = list(cpus_tuple)
            else:
                cpus_list = sorted(set(cpus_tuple))
                per_npu = len(cpus_list) // len(npus)
                for i, npu in enumerate(npus):
                    s = i * per_npu
                    e = (i + 1) * per_npu if i < len(npus) - 1 else len(cpus_list)
                    final_pool[npu] = cpus_list[s:e]
        self.npu_core_pool = final_pool

    def build_resource_layout(self) -> None:
        self._build_numa_topology()
        mode = DEVICE_BINDING_POLICY.get(get_ascend_device_type(), BINDING_MODES["topo_affinity"])
        logger.info(f"[cpu_bind_mode] mode={mode}, rank={self.rank}, visible_npus={self.topology.active_logical_ids}")
        if mode == BINDING_MODES["global_slice"]:
            self._slice_global_cpus()
            return
        if not self.topology.cpu_affinity:
            logger.warning("Topo affinity missing; falling back to global slice.")
            self._slice_global_cpus()
            return
        self._setup_topo_based_pools()

    def assign_cpu_resources(self) -> None:
        for npu_id, pool in self.npu_core_pool.items():
            if len(pool) < MIN_CORES_PER_NPU:
                raise RuntimeError(f"NPU{npu_id} lacks minimum required CPUs ({MIN_CORES_PER_NPU}).")
            self.main_threads[npu_id] = pool[2:-2]
            self.acl_threads[npu_id] = [pool[-2]]
            self.release_threads[npu_id] = [pool[-1]]

    def log_allocation_plan(self) -> None:
        logger.info("CPU allocation plan:")
        target_npu = self.topology.active_logical_ids[self.rank]
        main_str = " ".join(map(str, self.main_threads[target_npu]))
        acl_str = " ".join(map(str, self.acl_threads[target_npu]))
        rel_str = str(self.release_threads[target_npu]) if self.release_threads[target_npu] else ""
        logger.info(f"NPU{target_npu}: main=[{main_str}] acl=[{acl_str}] release=[{rel_str}]")

    def migrate_memory_to_local_numa(self, pid: str, npu_id: int) -> None:
        def find_target_numa(npu_idx: int) -> int | None:
            cpus = self.npu_core_pool.get(npu_idx, [])
            if not cpus:
                return None
            anchor = cpus[0]
            return self.numa_layout.get(anchor)
        if not shutil.which("migratepages"):
            logger.info("Skipping memory migration: 'migratepages' not found.")
            return
        numa = find_target_numa(npu_id)
        if numa is None:
            logger.warning(f"[mem_migrate] rank={self.rank}, NPU{npu_id} has no CPU pool.")
            return
        all_nodes = sorted(self.node_to_cpus.keys())
        if numa not in all_nodes:
            logger.warning(f"[mem_migrate] NUMA {numa} not found for NPU{npu_id}.")
            return
        execute_cmd = ["migratepages", pid, ",".join(map(str, all_nodes)), str(numa)]
        run_cmd(execute_cmd)
        logger.info(f"[mem_migrate] NPU{npu_id} -> NUMA {numa}")

    def bind_subprocess_threads(self) -> None:
        ps_out, _ = run_cmd(["ps", "-Te"])
        threads = self.extract_thread_mapping(ps_out)
        main_pid = str(os.getpid())
        target_npu = self.topology.active_logical_ids[self.rank]
        self.apply_cpu_binding(main_pid, self.main_threads[target_npu], True)
        for sub_pid in threads.get(main_pid, {}).get("acl_thread", []):
            self.apply_cpu_binding(sub_pid, self.acl_threads[target_npu], False)
            self.migrate_memory_to_local_numa(sub_pid, target_npu)
        for sub_pid in threads.get(main_pid, {}).get("release_thread", []):
            self.apply_cpu_binding(sub_pid, self.release_threads[target_npu], False)

    def bind_interrupts(self) -> None:
        if not os.access("/proc/irq", os.W_OK):
            return
        target_npu = self.topology.active_logical_ids[self.rank]
        if target_npu not in self.npu_core_pool:
            logger.warning(f"[irq] rank={self.rank}, NPU{target_npu} has no CPU pool.")
            return
        if shutil.which("systemctl"):
            systemctl_status, _ = run_cmd(["systemctl", "list-unit-files"])
            if "irqbalance.service" in systemctl_status:
                _, ret = run_cmd(["systemctl", "is-active", "--quiet", "irqbalance"])
                if ret == 0:
                    logger.warning("Stopping irqbalance service...")
                    run_cmd(["systemctl", "stop", "irqbalance"])
        sq_irqs = []
        with open("/proc/interrupts") as f:
            for line in f:
                if "sq_send_trigger_irq" in line:
                    irq = line.split(":")[0].strip()
                    sq_irqs.append(irq)
        npu_id = target_npu
        cpus = self.npu_core_pool[npu_id]
        if len(cpus) < 2:
            logger.warning(f"[irq] NPU{npu_id} has fewer than 2 CPUs; skipping IRQ binding.")
            return
        sq_cpu, cq_cpu = cpus[0], cpus[1]
        pci_addr = ""
        dev_type = get_ascend_device_type()
        if dev_type == AscendDeviceType.A3:
            card_id = npu_id // 2
            chip_id = npu_id % 2
            info, _ = run_cmd(["npu-smi", "info", "-t", "board", "-i", str(card_id), "-c", str(chip_id)])
        else:
            info, _ = run_cmd(["npu-smi", "info", "-t", "board", "-i", str(npu_id)])
        for line in info.splitlines():
            if "PCIe Bus Info" in line:
                pci_addr = line.split()[-1].lower()
                break
        if not pci_addr:
            logger.warning(f"[irq] Could not find PCIe address for NPU{npu_id}.")
            return
        try:
            msi_irqs = sorted(os.listdir(f"/sys/bus/pci/devices/{pci_addr}/msi_irqs/"), key=lambda x: int(x))
        except FileNotFoundError:
            logger.warning(f"[irq] No msi_irqs directory for PCI {pci_addr}.")
            return
        sq_irq, cq_irq = "", ""
        for irq in sq_irqs:
            if irq in msi_irqs:
                sq_irq = irq
                cq_irq = str(int(irq) + 1)
                break
        if not sq_irq:
            logger.warning(f"[irq] No sq_send_trigger_irq found for NPU{npu_id}.")
            return
        logger.info(
            f"NPU{npu_id}(PCI {pci_addr}): sq={sq_irq}→CPU{sq_cpu}, cq={cq_irq}→CPU{cq_cpu}"
        )
        with open(f"/proc/irq/{sq_irq}/smp_affinity", "w") as f:
            f.write(self.encode_cpu_mask(sq_cpu))
        with open(f"/proc/irq/{cq_irq}/smp_affinity", "w") as f:
            f.write(self.encode_cpu_mask(cq_cpu))

    def execute_full_binding(self) -> None:
        self.build_resource_layout()
        self.assign_cpu_resources()
        self.log_allocation_plan()
        self.bind_subprocess_threads()
        self.bind_interrupts()


def bind_cpu_resources(rank_id: int) -> None:
    if not is_arm_architecture():
        logger.info("CPU binding skipped: non-ARM CPU detected.")
        return
    allocator = CpuResourceAllocator(rank_id)
    allocator.execute_full_binding()

from pip._internal.distributions.sdist import SourceDistribution
from pip._internal.distributions.wheel import WheelDistribution
from pip._internal.req.req_install import InstallRequirement

def get_distribution_for_requirement(
    requirement: InstallRequirement,
) -> AbstractDistribution:
    """Returns a Distribution for the given InstallRequirement"""
    # Handle editable requirements using source distribution logic
    if getattr(requirement, 'editable', False):
        return SourceDistribution(requirement)

    # Check if the requirement is already a wheel
    if hasattr(requirement, 'is_wheel') and requirement.is_wheel:
        return WheelDistribution(requirement)

    # Default case: use source distribution
    return SourceDistribution(requirement)

