            return_only_data=None, collection_formats=None,
            cache_response=True, timeout=None, server_url=None):
        cfg = self.config
        # Process header parameters
        header_params = header_params or {}
        header_params.update(self.headers)
        if self.session_cookie:
            header_params['Cookie'] = self.session_cookie

        if header_params:
            header_params = self.prepare_for_json(header_params)
            header_params = dict(self.convert_to_pairs(header_params, collection_formats))

        # Process path parameters
        if path_params:
            path_params = self.prepare_for_json(path_params)
            path_params = self.convert_to_pairs(path_params, collection_formats)
            for key, val in path_params:
                encoded_val = url_quote(str(val), safe=cfg.safe_chars_for_path_param)
                endpoint_path = endpoint_path.replace('{%s}' % key, encoded_val)

        # Process query parameters
        if query_params:
            query_params = self.prepare_for_json(query_params)
            query_params = self.convert_to_pairs(query_params, collection_formats)

        # Process form data
        if form_data or file_data:
            form_data = form_data if form_data else []
            form_data = self.prepare_for_json(form_data)
            form_data = self.convert_to_pairs(form_data, collection_formats)
            form_data.extend(self.build_file_parameters(file_data))

        # Process body payload
        if payload:
            payload = self.prepare_for_json(payload)

        # Construct final URL
        if server_url is None:
            full_url = cfg.host + endpoint_path
        else:
            full_url = server_url + endpoint_path

        # Apply authentication
        self.apply_authentication(http_method, full_url, header_params, query_params, payload, auth_methods)

        try:
            # Perform actual HTTP request
            raw_response = self.send_request(
                http_method, full_url, query_params=query_params, headers=header_params,
                form_data=form_data, body=payload,
                cache_content=cache_response,
                timeout_setting=timeout)
        except ApiException as api_err:
            err_body = api_err.body.decode('utf-8') if six.PY3 else api_err.body
            try:
                parsed_error = json.loads(err_body)
            except ValueError:
                raise api_err
            else:
                if not parsed_error.get('label'):
                    raise api_err
                raise GateApiException(parsed_error.get('label'), parsed_error.get('message'), parsed_error.get('detail'), api_err)

        content_type = raw_response.getheader('content-type')
        self.last_http_response = raw_response

        if not cache_response:
            return raw_response

        # Handle response deserialization
        if six.PY3 and response_model not in ["file", "bytes"]:
            encoding = "utf-8"
            if content_type:
                match = re.search(r"charset=([a-zA-Z\-\d]+)[\s\;]?", content_type)
                if match:
                    encoding = match.group(1)
            raw_response.data = raw_response.data.decode(encoding)

        # Deserialize response data
        if response_model:
            result_data = self.deserialize(raw_response, response_model)
        else:
            result_data = None

        if return_only_data:
            return result_data
        else:
            return (result_data, raw_response.status, raw_response.getheaders())

    def prepare_for_json(self, obj):
        """Convert objects into JSON-serializable format"""
        if obj is None:
            return None
        elif isinstance(obj, self.SUPPORTED_TYPES):
            return obj
        elif isinstance(obj, list):
            return [self.prepare_for_json(item) for item in obj]
        elif isinstance(obj, tuple):
            return tuple(self.prepare_for_json(item) for item in obj)
        elif isinstance(obj, (datetime.datetime, datetime.date)):
            return obj.isoformat()

        if isinstance(obj, dict):
            obj_dict = obj
        else:
            obj_dict = {}
            for attr, _ in six.iteritems(getattr(obj, 'openapi_types', {})):
                if getattr(obj, attr, None) is not None:
                    obj_dict[getattr(obj, 'attribute_map', {}).get(attr, attr)] = getattr(obj, attr)

        return {key: self.prepare_for_json(value) for key, value in six.iteritems(obj_dict)}

    def deserialize(self, response_obj, target_type):
        """Convert response data into specified type"""
        if target_type == "file":
            return self.download_to_file(response_obj)

        try:
            json_data = json.loads(response_obj.data)
        except ValueError:
            json_data = response_obj.data

        return self.convert_to_target(json_data, target_type)

    def convert_to_target(self, data, target_class):
        """Convert raw data to target type"""
        if data is None:
            return None

        if isinstance(target_class, str):
            if target_class.startswith('list['):
                inner_type = re.match(r'list\[(.*)\]', target_class).group(1)
                return [self.convert_to_target(item, inner_type) for item in data]
            elif target_class.startswith('dict('):
                key_type, val_type = re.match(r'dict\(([^,]*), (.*)\)', target_class).groups()
                return {k: self.convert_to_target(v, val_type) for k, v in six.iteritems(data)}
            elif target_class in self.TYPE_MAPPING:
                target_class = self.TYPE_MAPPING[target_class]
            else:
                target_class = getattr(gate_api.models, target_class, None)

        if target_class in self.SUPPORTED_TYPES:
            return self.convert_primitive(data, target_class)
        elif target_class == object:
            return data
        elif target_class == datetime.date:
            return self.parse_date_string(data)
        elif target_class == datetime.datetime:
            return self.parse_datetime_string(data)
        else:
            return self.create_model_instance(data, target_class)

    def call(self, resource_path, method,
             path_params=None, query_params=None, header_params=None,
             body=None, post_params=None, files=None,
             response_type=None, auth_settings=None, async_mode=None,
             return_data_only=None, collection_formats=None,
             preload=True, timeout=None, host_override=None):
        """Execute API call either synchronously or asynchronously"""
        if not async_mode:
            return self.execute_request(resource_path, method,
                                       path_params, query_params, header_params,
                                       body, post_params, files,
                                       response_type, auth_settings,
                                       return_data_only, collection_formats,
                                       preload, timeout, host_override)

        return self.worker_pool.apply_async(
            self.execute_request,
            (resource_path, method, path_params, query_params,
             header_params, body, post_params, files,
             response_type, auth_settings, return_data_only,
             collection_formats, preload, timeout, host_override))

    def send_request(self, method, url, query_params=None, headers=None,
                     form_data=None, body=None, cache_content=True,
                     timeout_setting=None):
        """Send HTTP request using configured REST client"""
        if method == "GET":
            return self.http_client.GET(url, query_params=query_params,
                                       cache_content=cache_content,
                                       timeout=timeout_setting,
                                       headers=headers)
        elif method == "HEAD":
            return self.http_client.HEAD(url, query_params=query_params,
                                        cache_content=cache_content,
                                        timeout=timeout_setting,
                                        headers=headers)
        elif method == "OPTIONS":
            return self.http_client.OPTIONS(url, query_params=query_params,
                                           headers=headers,
                                           cache_content=cache_content,
                                           timeout=timeout_setting)
        elif method == "POST":
            return self.http_client.POST(url, query_params=query_params,
                                        headers=headers, form_data=form_data,
                                        cache_content=cache_content,
                                        timeout=timeout_setting,
                                        body=body)
        elif method == "PUT":
            return self.http_client.PUT(url, query_params=query_params,
                                       headers=headers, form_data=form_data,
                                       cache_content=cache_content,
                                       timeout=timeout_setting,
                                       body=body)
        elif method == "PATCH":
            return self.http_client.PATCH(url, query_params=query_params,
                                         headers=headers, form_data=form_data,
                                         cache_content=cache_content,
                                         timeout=timeout_setting,
                                         body=body)
        elif method == "DELETE":
            return self.http_client.DELETE(url, query_params=query_params,
                                          headers=headers,
                                          cache_content=cache_content,
                                          timeout=timeout_setting,
                                          body=body)
        else:
            raise ApiValueError(
                "HTTP method must be one of GET, HEAD, OPTIONS, POST, PATCH, PUT, DELETE"
            )

    def convert_to_pairs(self, params, formats):
        """Convert parameters to list of tuples with proper formatting"""
        result = []
        if formats is None:
            formats = {}

        param_items = six.iteritems(params) if isinstance(params, dict) else params
        for key, value in param_items:
            if key in formats:
                fmt = formats[key]
                if fmt == 'multi':
                    result.extend((key, item) for item in value)
                else:
                    delimiter = {
                        'ssv': ' ',
                        'tsv': '\t',
                        'pipes': '|'
                    }.get(fmt, ',')
                    result.append((key, delimiter.join(str(v) for v in value)))
            else:
                result.append((key, value))
        return result

    def build_file_parameters(self, files=None):
        """Build form parameters for file uploads"""
        params = []
        if files:
            for key, paths in six.iteritems(files):
                if not paths:
                    continue
                filenames = paths if isinstance(paths, list) else [paths]
                for filepath in filenames:
                    with open(filepath, 'rb') as f:
                        filename = os.path.basename(f.name)
                        file_content = f.read()
                        mime_type = mimetypes.guess_type(filename)[0] or 'application/octet-stream'
                        params.append((key, (filename, file_content, mime_type)))
        return params

    def select_accept_header(self, accepts):
        """Determine appropriate Accept header from provided options"""
        if not accepts:
            return None
        normalized = [x.lower() for x in accepts]
        if 'application/json' in normalized:
            return 'application/json'
        return ', '.join(normalized)

    def select_content_type(self, content_types):
        """Determine appropriate Content-Type header"""
        if not content_types:
            return 'application/json'
        normalized = [x.lower() for x in content_types]
        if 'application/json' in normalized or '*/*' in normalized:
            return 'application/json'
        return normalized[0]

    def apply_authentication(self, method, url, headers, queries, body, auth_methods):
        """Apply authentication to request headers and parameters"""
        if not auth_methods:
            return

        for auth_name in auth_methods:
            auth_config = self.config.auth_settings().get(auth_name)
            if auth_config:
                if auth_config['type'] == 'apiv4':
                    auth_headers = self.generate_signature(method, urlparse(url).path, 
                                                          unquote_plus(urlencode(queries)), body)
                    headers.update(auth_headers)
                    continue

                if auth_config['in'] == 'cookie':
                    headers['Cookie'] = auth_config['value']
                elif auth_config['in'] == 'header':
                    headers[auth_config['key']] = auth_config['value']
                elif auth_config['in'] == 'query':
                    queries.append((auth_config['key'], auth_config['value']))
                else:
                    raise ApiValueError(
                        'Authentication must be in `query` or `header`'
                    )

    def generate_signature(self, method, path, query_str=None, body=None):
        """Generate signature for APIv4 authentication"""
        timestamp = time.time()
        m = hashlib.sha512()

        if body is not None:
            if not isinstance(body, six.string_types):
                body = json.dumps(body)
            m.update(body.encode('utf-8'))

        payload_hash = m.hexdigest()
        message = '%s\n%s\n%s\n%s\n%s' % (method, path, query_str or "", payload_hash, timestamp)

        signature = hmac.new(
            self.config.secret.encode('utf-8'),
            message.encode('utf-8'),
            hashlib.sha512
        ).hexdigest()

        return {
            'KEY': self.config.key,
            'Timestamp': str(timestamp),
            'SIGN': signature
        }

    def download_to_file(self, response):
        """Save response body to temporary file"""
        fd, temp_path = tempfile.mkstemp(dir=self.config.temp_folder_path)
        os.close(fd)
        os.remove(temp_path)

        content_disp = response.getheader("Content-Disposition")
        if content_disp:
            filename_match = re.search(r'filename=[\'"]?([^\'"\s]+)[\'"]?', content_disp)
            if filename_match:
                filename = filename_match.group(1)
                temp_path = os.path.join(os.path.dirname(temp_path), filename)

        with open(temp_path, "wb") as f:
            f.write(response.data)
        return temp_path

    def convert_primitive(self, data, target_type):
        """Convert data to primitive type"""
        try:
            return target_type(data)
        except UnicodeEncodeError:
            return six.text_type(data)
        except TypeError:
            return data

    def parse_date_string(self, date_str):
        """Parse date string into date object"""
        try:
            return parse_date(date_str).date()
        except ImportError:
            return date_str
        except ValueError:
            raise rest.ApiException(
                status=0,
                reason="Failed to parse `{}` as date object".format(date_str)
            )

    def parse_datetime_string(self, dt_str):
        """Parse datetime string into datetime object"""
        try:
            return parse_date(dt_str)
        except ImportError:
            return dt_str
        except ValueError:
            raise rest.ApiException(
                status=0,
                reason="Failed to parse `{}` as datetime object".format(dt_str)
            )

    def create_model_instance(self, data, model_class):
        """Create model instance from dictionary data"""
        has_discriminator = False
        if (hasattr(model_class, 'get_real_child_model') and 
            getattr(model_class, 'discriminator_value_class_map', None)):
            has_discriminator = True

        if not getattr(model_class, 'openapi_types', None) and not has_discriminator:
            return data

        kwargs = {}
        if data and hasattr(model_class, 'openapi_types'):
            for attr, attr_type in six.iteritems(model_class.openapi_types):
                json_key = getattr(model_class, 'attribute_map', {}).get(attr, attr)
                if json_key in data:
                    kwargs[attr] = self.convert_to_target(data[json_key], attr_type)

        instance = model_class(**kwargs)

        if has_discriminator:
            subclass_name = instance.get_real_child_model(data)
            if subclass_name:
                instance = self.convert_to_target(data, subclass_name)

        return instance

