def test_load_from_tempfile_module_naming_conflict():
    with tempfile.NamedTemporaryFile(suffix=".py", delete=False) as fp:
        fp.write(textwrap.dedent("""
            import strands
            @strands.tools.tool
            def sample_tool():
                return "ok"
        """).encode())
        fp.flush()
        tools = load_tools_from_file_path(fp.name)

        base_name = os.path.basename(fp.name).rsplit(".", 1)[0]
        expected_module_name = f"{_TOOL_MODULE_PREFIX}{base_name}"

        assert expected_module_name in sys.modules
        assert len(tools) == 1
        assert tools[0].tool_name == "sample_tool"

        os.unlink(fp.name)

@staticmethod
    def display_verse(verse_info):
        """Prepare a single verse for presentation."""
        if not verse_info:
            return "Verse unavailable."

        chapter_name = verse_info['surah']['englishName'] 
        chapter_id = verse_info['surah']['number']
        verse_id = verse_info['numberInSurah']
        arabic_text = verse_info['text_ar']
        translation_text = verse_info['text_tr']

        return f"=== {chapter_name} ({chapter_id}:{verse_id}) ===\n\n{arabic_text}\n\n{translation_text}"

    @staticmethod
    def display_chapter(verses):
        """Prepare an entire chapter for presentation."""
        if not verses:
            return "Chapter unavailable."

        # verses is expected to be a list of verse dictionaries
        initial_verse = verses[0]
        # In get_surah, 'surah' key holds the chapter metadata
        chapter_info = initial_verse['surah']
        chapter_title = chapter_info.get('englishName', f"Chapter {chapter_info.get('number')}")
        chapter_number = chapter_info.get('number')

        lines = [f"=== {chapter_title} (Chapter {chapter_number}) ==="]
        for verse in verses:
            lines.append(f"\n[{verse['numberInSurah']}] {verse['text_ar']}")
            lines.append(verse['text_tr'])

        return "\n".join(lines)

    @staticmethod
    def present_search_matches(matches, search_term):
        """Present the outcomes of a keyword search."""
        if not matches:
            return f"No matches identified for '{search_term}'."

        result_lines = [f"Search findings for '{search_term}':\n"]
        for verse in matches:
            result_lines.append(QuranFormatter.display_verse(verse))
            result_lines.append("-" * 30)

        return "\n".join(result_lines)

import ast
import re
from typing import Any, Callable, Dict, List, Tuple

class VariableNameExtractor(ast.NodeVisitor):
    """Custom AST visitor to collect variable identifiers and attribute chains"""
    def __init__(self):
        self.identifiers = set()
        # Predefined set of Python built-in function names to exclude
        self.builtins = {
            "min", "max", "abs", "round", "int", "float", "sum", "len",
            "str", "bool", "list", "dict", "tuple", "set", "range",
            "enumerate", "zip", "map", "filter", "sorted", "reversed",
            "all", "any", "bin", "hex", "oct", "chr", "ord", "pow",
            "divmod", "type", "isinstance", "hasattr", "getattr",
            "setattr", "delattr", "callable", "iter", "next"
        }

    def visit_Name(self, node):
        if node.id not in self.builtins:
            self.identifiers.add(node.id)
        self.generic_visit(node)

    def visit_Attribute(self, node):
        full_path = self._build_attribute_chain(node)
        if full_path and not self._is_module_attribute(full_path):
            self.identifiers.add(full_path)

    def _build_attribute_chain(self, node):
        parts = []
        current = node
        while isinstance(current, ast.Attribute):
            parts.append(current.attr)
            current = current.value
        if isinstance(current, ast.Name):
            parts.append(current.id)
        return ".".join(reversed(parts)) if parts else None

    def _is_module_attribute(self, attr_chain):
        module_prefixes = {"math", "os", "sys", "json", "re", "datetime"}
        parts = attr_chain.split(".")
        return len(parts) > 0 and parts[0] in module_prefixes

def decompose_expression(
    expr_str: str, reserved_fields: List[str] = []
) -> Tuple[List[str], Callable[[Dict[str, Any]], Any]]:
    """
    Parse a mathematical expression string using AST and extract variable references and operators.

    Args:
        expr_str: Expression string like "(min(ajet.rollout.max_env_worker // ajet.rollout.n_vllm_engine, 64))"
        reserved_fields: Optional list of fields to preserve (not used in this implementation but kept for API compatibility)

    Returns:
        A tuple containing:
        - List of extracted variable names (sorted)
        - A callable that computes the result given a dictionary of values
    """
    try:
        tree = ast.parse(expr_str, mode="eval")
    except SyntaxError as e:
        raise ValueError(f"Invalid syntax in expression: {expr_str}") from e

    extractor = VariableNameExtractor()
    extractor.visit(tree)
    variables = sorted(list(extractor.identifiers))

    def compute(values: Dict[str, Any]) -> Any:
        missing = [var for var in variables if var not in values]
        if missing:
            raise KeyError(f"Missing required variables: {missing}")

        # Prepare safe variable mappings
        mapping = {}
        transformed_expr = expr_str

        # Sort by length descending to avoid partial replacements
        sorted_vars = sorted(variables, key=len, reverse=True)
        for idx, var in enumerate(sorted_vars):
            placeholder = f"__v_{idx}__"
            mapping[placeholder] = values[var]
            # Use word boundary-like regex to prevent partial matches
            pattern = re.escape(var) + r"(?![a-zA-Z0-9_\.])"
            transformed_expr = re.sub(pattern, placeholder, transformed_expr)

        # Build restricted namespace with only necessary built-ins
        safe_namespace = {
            "__builtins__": {
                "min": min,
                "max": max,
                "abs": abs,
                "round": round,
                "int": int,
                "float": float,
                "sum": sum,
                "len": len,
            }
        }
        safe_namespace.update(mapping)

        try:
            return eval(transformed_expr, safe_namespace)
        except Exception as e:
            raise RuntimeError(f"Failed to evaluate '{expr_str}': {e}") from e

    return variables, compute

import typing as t
import re
from uuid import UUID
from langchain_core.callbacks.base import AsyncCallbackHandler
