class StreamLoggerAsync(AsyncCallbackHandler):
    """
    Custom async callback handler to reduce verbosity in LangChain logs.
    Filters out base64-encoded images from GPT-4 Vision inputs and formats messages cleanly.
    """
    IMAGE_DATA_PATTERN = re.compile(r"(data:image/(\w+);base64,)(.*?)(['\"\n])")

    def _extract_message_role_content(self, message: BaseMessage) -> dict[str, t.Any]:
        result = {"role": message.type, "content": message.content}
        if self._include_tool_calls:
            extra_kwargs = getattr(message, "additional_kwargs", {})
            if tool_calls := extra_kwargs.get("tool_calls"):
                result["tool_calls"] = tool_calls
            if tool_id := getattr(message, "tool_call_id", None):
                result["tool_call_id"] = tool_id
        return result

    def __init__(
        self,
        log_raw_response: bool = True,
        track_token_stats: bool = False,
        include_tool_calls: bool = True,
    ):
        super().__init__()
        self._log_raw_response = log_raw_response
        self._track_token_stats = track_token_stats
        self._include_tool_calls = include_tool_calls

    def on_chat_model_start(
        self,
        serialized: dict[str, t.Any],
        messages: list[list[BaseMessage]],
        **kwargs: t.Any,
    ) -> None:
        if len(messages) != 1:
            raise ValueError(f"Expected exactly one message batch, got {len(messages)}")

        llm_id = serialized.get("id", [])
        model_name = "<unknown>"
        if llm_id and llm_id[-1] == "AzureChatOpenAI":
            try:
                model_name = serialized["kwargs"]["deployment_name"]
            except KeyError:
                pass
        else:
            model_name = "<not_recognized>"

        formatted_messages = [
            self._extract_message_role_content(msg) for msg in messages[0]
        ]
        message_str = "\n".join(map(str, formatted_messages))
        # Strip base64 image data from vision calls
        message_str = self.IMAGE_DATA_PATTERN.sub(
            lambda m: f"{m.group(1)}<base64_image>{m.group(4)}", message_str
        )
        logger.info(f"Calling {model_name} with {len(formatted_messages)} messages:\n{message_str}")

    def on_llm_end(
        self,
        response: LLMResult,
        **kwargs: t.Any,
    ) -> None:
        generations = response.generations
        if len(generations) != 1:
            raise ValueError(f"Expected one generation group, got {len(generations)}")
        if len(generations[0]) != 1:
            raise ValueError(f"Expected one generation per group, got {len(generations[0])}")

        gen: ChatGeneration = generations[0][0]  # type: ignore[assignment]
        ai_msg = gen.message

        if self._log_raw_response:
            logger.info(f'Raw LLM output: "{ai_msg.content}"')

        if self._track_token_stats:
            usage_info = response.llm_output or {}
            token_data = usage_info.get("token_usage")
            if token_data:
                logger.info(f"Token usage (from LLM): {token_data}")
            else:
                logger.warning("No 'token_usage' found in LLM output")


class ModelTokenTracker(AsyncCallbackHandler):
    """Tracks token usage per model deployment."""

    def on_llm_end(
        self,
        response: LLMResult,
        **kwargs: t.Any,
    ) -> None:
        prompt_tokens = 0
        completion_tokens = 0
        model_id = "unknown"

        try:
            first_gen = response.generations[0][0]
        except IndexError:
            first_gen = None

        if isinstance(first_gen, ChatGeneration):
            msg = first_gen.message
            if isinstance(msg, AIMessage):
                meta = getattr(msg, "usage_metadata", None)
                if meta:
                    prompt_tokens = meta.get("input_tokens", 0)
                    completion_tokens = meta.get("output_tokens", 0)
            info = getattr(first_gen, "generation_info", {}) or {}
            model_id = info.get("model_name") or model_id

        if not (prompt_tokens or completion_tokens):
            llm_out = response.llm_output or {}
            token_info = llm_out.get("token_usage", {})
            prompt_tokens = token_info.get("prompt_tokens", 0)
            completion_tokens = token_info.get("completion_tokens", 0)

        if not model_id:
            llm_out = response.llm_output or {}
            model_id = llm_out.get("model_name") or "unknown"

        logger.info(
            f"Tokens used by '{model_id}': "
            f"prompt={prompt_tokens}, completion={completion_tokens}"
        )

        manager = get_token_usage_manager()
        manager.add_usage(
            TokenUsageItem(
                deployment=model_id,
                model=model_id,
                prompt_tokens=prompt_tokens,
                completion_tokens=completion_tokens,
            )
        )


class ResponseValidator(AsyncCallbackHandler):
    """Validates streaming tokens against a pattern; raises exception after too many invalid tokens."""
    max_invalid_chunks: int = 3

    def __init__(self, pattern: str, max_invalid: int = 3):
        if max_invalid < 1:
            raise ValueError("max_invalid must be at least 1")
        self._pattern = pattern
        self._max_invalid = max_invalid
        self._regex = re.compile(pattern)
        self._invalid_count = 0

    def __repr__(self) -> str:
        return (
            f"{type(self).__name__}(pattern={self._pattern!r}, "
            f"max_invalid={self._max_invalid})"
        )

    async def on_llm_new_token(
        self,
        token: str,
        *,
        chunk: GenerationChunk | ChatGenerationChunk | None = None,
        run_id: UUID,
        parent_run_id: UUID | None = None,
        tags: list[str] | None = None,
        **kwargs: t.Any,
    ) -> None:
        if self._regex.fullmatch(token) is None:
            self._invalid_count = 0
            return

        self._invalid_count += 1
        if self._invalid_count >= self._max_invalid:
            raise InvalidLLMStreamResponse(
                f"Received {self._invalid_count} consecutive invalid tokens"
            )

# Filter out None values from a dictionary

from typing import Any, Dict

def remove_none_from_dict(original: Dict[str, Any]) -> Dict[str, Any]:
    result = {}
    for key in original:
        val = original[key]
        if val is not None:
            result[key] = val
    return result

import os
import sys
from typing import Optional, Tuple

def get_glibc_info() -> Optional[str]:
    """Attempt to retrieve glibc version information using alternative methods."""
    return try_confstr_method() or try_ctypes_detection()

def try_confstr_method() -> Optional[str]:
    """First approach: Use configuration string retrieval via os.confstr."""
    if sys.platform.startswith("win"):
        return None

    try:
        # Attempt to get GNU libc version from system configuration
        raw_version = os.confstr(os.confstr_names["CS_GNU_LIBC_VERSION"])
        if raw_version is None:
            return None

        # Parse version from format like "glibc 2.17" to just "2.17"
        parts = raw_version.split()
        if len(parts) >= 2:
            return parts[1]
        return None
    except (KeyError, AttributeError, OSError, ValueError):
        return None

def try_ctypes_detection() -> Optional[str]:
    """Secondary approach: Use ctypes to access glibc symbols directly."""
    try:
        import ctypes
    except ImportError:
        return None

    # Load the main process namespace to find libc
    try:
        lib_loader = ctypes.CDLL(None)
    except (OSError, AttributeError):
        return None

    # Check for glibc-specific symbol
    try:
        version_func = getattr(lib_loader, 'gnu_get_libc_version', None)
        if version_func is None:
            return None

        version_func.restype = ctypes.c_char_p
        result = version_func()

        # Handle both Python 2 and 3 string types
        if isinstance(result, bytes):
            return result.decode('utf-8')
        return result
    except (AttributeError, OSError):
        return None

def detect_libc_details() -> Tuple[str, str]:
    """Determine libc implementation and version.

    Returns tuple of (library_name, version_string), 
    with empty strings if detection fails.
    """
    detected_version = get_glibc_info()
    if detected_version is None:
        return ("", "")
    return ("glibc", detected_version)

