# Type III Clone: Headers class with equivalent functionality but different internal structure and logic

from collections.abc import Iterable, Iterator, Mapping, MutableMapping
from typing import Any, Protocol, Union

__all__ = [
    "HeaderStore",
    "HeaderLike",
    "DuplicateKeyError",
]

class DuplicateKeyError(LookupError):
    """
    Exception raised when HeaderStore has multiple values for a key.
    """
    def __str__(self) -> str:
        if len(self.args) == 1:
            return repr(self.args[0])
        return super().__str__()

class HeaderStore(MutableMapping[str, str]):
    """
    Optimized container for HTTP header management.

    This class provides efficient storage and retrieval of HTTP headers while 
    supporting case-insensitive keys and multiple values per key.

    Behavior:
    - Accessing via []: raises KeyError if missing, returns single value if unique,
      raises DuplicateKeyError if multiple values exist
    - Setting via []: appends new value to existing list for that header
    - Deleting via del: removes all entries for the specified header (slower operation)

    Additional capabilities:
    - get_all(): retrieve all values for a given header name
    - items_raw(): iterate over raw (header_name, value) pairs preserving order
    """
    __slots__ = ["_storage", "_sequence"]

    def __init__(self, *sources, **initial_values: str) -> None:
        self._storage: dict[str, list[str]] = {}
        self._sequence: list[tuple[str, str]] = []
        self.update(*sources, **initial_values)

    def __str__(self) -> str:
        # Format as standard HTTP header block
        result = ""
        for name, val in self._sequence:
            result += f"{name}: {val}\r\n"
        return result + "\r\n"

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}({self._sequence!r})"

    def clone(self) -> "HeaderStore":
        new_instance = self.__class__()
        new_instance._storage = {k: v[:] for k, v in self._storage.items()}
        new_instance._sequence = self._sequence[:]
        return new_instance

    def to_bytes(self) -> bytes:
        # ASCII-only encoding for HTTP compatibility
        return str(self).encode("ascii")

    # Collection interface implementation
    def __contains__(self, key: object) -> bool:
        return isinstance(key, str) and key.lower() in self._storage

    def __iter__(self) -> Iterator[str]:
        return iter(self._storage)

    def __len__(self) -> int:
        return len(self._storage)

    # MutableMapping core methods
    def __getitem__(self, key: str) -> str:
        candidates = self._storage.get(key.lower())
        if not candidates:
            raise KeyError(key)
        if len(candidates) == 1:
            return candidates[0]
        raise DuplicateKeyError(key)

    def __setitem__(self, key: str, value: str) -> None:
        lower_key = key.lower()
        if lower_key not in self._storage:
            self._storage[lower_key] = []
        self._storage[lower_key].append(value)
        self._sequence.append((key, value))

    def __delitem__(self, key: str) -> None:
        lower_key = key.lower()
        if lower_key not in self._storage:
            raise KeyError(key)

        del self._storage[lower_key]
        # Rebuild sequence without deleted entries
        self._sequence = [(k, v) for k, v in self._sequence if k.lower() != lower_key]

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, HeaderStore):
            return NotImplemented
        return self._storage == other._storage

    # Utility methods
    def reset(self) -> None:
        """Remove all stored headers."""
        self._storage.clear()
        self._sequence.clear()

    def extend(self, *sources, **kwargs: str) -> None:
        """Add headers from various sources including HeaderStore instances."""
        processed_sources = []
        for src in sources:
            if isinstance(src, HeaderStore):
                processed_sources.append(src.items_raw())
            else:
                processed_sources.append(src)

        super().update(*processed_sources, **kwargs)

    # Multi-value support methods
    def fetch_all(self, key: str) -> list[str]:
        """
        Retrieve all values associated with a header name.

        Args:
            key: The header name to look up

        Returns:
            List of all values for this header (empty if none found)
        """
        return self._storage.get(key.lower(), [])

    def items_raw(self) -> Iterator[tuple[str, str]]:
        """
        Provide direct access to stored header pairs in insertion order.

        Returns:
            Iterator yielding (header_name, value) tuples
        """
        return iter(self._sequence)

# Protocol definition for type checking compatibility
class KeyAndItemAccess(Protocol):  # pragma: no cover
    """Types supporting both keys() method and item access via __getitem__."""
    def keys(self) -> Iterable[str]: ...
    def __getitem__(self, key: str) -> str: ...

# Union type for flexible input handling
HeaderLike = Union[
    HeaderStore,
    Mapping[str, str],
    Iterable[tuple[str, str]],
    KeyAndItemAccess,
]
"""
Union of types acceptable where HeaderStore is expected.
Includes HeaderStore itself, standard mappings, iterables of pairs, and 
objects implementing both keys() and __getitem__() methods.
"""

# Re-export click for error handling (must be after other imports)
import click  # noqa: E402

def compute_periods(start_date, end_date, period_type):
    result = []
    if period_type == "monthly":
        current = start_date.replace(day=1)
        while current < end_date:
            # Compute next month by going to day 28 + 4 days then setting to day 1
            next_period = (current.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            result.append((current, min(next_period, end_date), current.strftime("%Y-%m")))
            current = next_period
    else:  # assume yearly
        current = start_date.replace(month=1, day=1)
        while current < end_date:
            next_year = current.replace(year=current.year + 1)
            result.append((current, min(next_year, end_date), str(current.year)))
            current = next_year
    return result

def filter_entries_by_time(data_items, begin=None, finish=None):
    output = []
    for item in data_items:
        if not hasattr(item, "date"):
            output.append(item)
            continue
        if begin and item.date < begin:
            continue
        if finish and item.date >= finish:
            continue
        output.append(item)
    return output

def build_account_tree(account_node):
    tree_entry = {
        "name": account_node.account,
        "values": {},
        "subaccounts": [],
    }

    # Aggregate balances per currency
    for holding in account_node.balance:
        currency = holding.units.currency
        value = float(holding.units.number)
        tree_entry["values"][currency] = tree_entry["values"].get(currency, 0.0) + value

    # Process child accounts in sorted order
    for child_account in sorted(account_node.values(), key=lambda acc: acc.account):
        subtree = build_account_tree(child_account)
        # Only include non-empty subtrees
        if subtree["subaccounts"] or subtree["values"]:
            tree_entry["subaccounts"].append(subtree)

    return tree_entry

def extract_subtree(realization_map, account_path, default_name):
    found_account = realization_map.get(account_path, default_name)
    if found_account is None:
        return {"name": default_name, "values": {}, "subaccounts": []}
    return build_account_tree(found_account)

def aggregate_balances(realization_map, account_path, default_name):
    target_account = realization_map.get(account_path, default_name)
    if target_account is None:
        return {}

    totals = {}

    def traverse(node):
        for position in node.balance:
            currency = position.units.currency
            amount = float(position.units.number)
            totals[currency] = totals.get(currency, 0.0) + amount
        for child in node.values():
            traverse(child)

    traverse(target_account)
    return totals

def transform_currency_dict(amounts, price_data, desired_currency, reference_date=None):
    """Convert a dictionary of {currency: quantity} into one {desired_currency: total_value}."""
    from beancount.core.prices import get_price

    final_sum = 0.0
    for currency, quantity in amounts.items():
        if currency == desired_currency:
            final_sum += quantity
        else:
            conversion_rate = get_price(price_data, (currency, desired_currency), reference_date)
            if conversion_rate is None:
                raise click.UsageError(f"Missing price data for {currency} to {desired_currency}")
            _, rate_value = conversion_rate
            final_sum += quantity * float(rate_value)

    return {desired_currency: round(final_sum, 2)}

def _sum_all_balances(tree_node):
    """Compute the total of all numeric balances in a tree structure."""
    subtotal = sum(tree_node["values"].values())
    for branch in tree_node["subaccounts"]:
        subtotal += _sum_all_balances(branch)
    return subtotal

def convert_entire_tree(tree_root, market_prices, target_currency, as_of_date=None):
    """Recursively convert all balances in an account tree to a single target currency."""
    # Recursively process children first
    processed_children = [
        convert_entire_tree(child, market_prices, target_currency, as_of_date) 
        for child in tree_root["subaccounts"]
    ]

    # Sort children by absolute total balance (descending)
    processed_children.sort(key=lambda c: abs(_sum_all_balances(c)), reverse=True)

    # Convert current node's balance if any exists
    converted_values = (
        transform_currency_dict(tree_root["values"], market_prices, target_currency, as_of_date)
        if tree_root["values"] else {}
    )

    return {
        "name": tree_root["name"],
        "values": converted_values,
        "subaccounts": processed_children,
    }

