class HabitatRLEnv(RLEnv):
    def __init__(self, config, dataset=None):
        super().__init__(config, dataset)
        self._prev_dist_to_goal = 0.0

    def reset(self, **kwargs):
        obs = super().reset(**kwargs)
        metrics = self.habitat_env.get_metrics()
        self._prev_dist_to_goal = metrics.get("geodesic_to_goal", 0.0)
        return obs

    def step(self, action, *args, **kwargs):
        return super().step(action, *args, **kwargs)

    def reward_bounds(self):
        return (-float('inf'), float('inf'))

    def compute_reward(self, observations):
        metrics = self.habitat_env.get_metrics()
        curr_dist = metrics.get("geodesic_to_goal", 0.0)
        delta = self._prev_dist_to_goal - curr_dist
        reward = delta - 0.01
        if metrics.get("success", False):
            reward += 10.0
        self._prev_dist_to_goal = curr_dist
        return reward

    def check_done(self, observations):
        done = self.habitat_env.episode_over
        if not done:
            metrics = self.habitat_env.get_metrics()
            done = metrics.get("collisions", 0) > 0
        return done

    def extract_info(self, observations):
        return self.habitat_env.get_metrics()


def _remote_worker(
    parent_conn: Connection,
    child_conn: Connection,
    env_factory: CloudpickleWrapper,
    shared_buffers: Optional[Union[Dict, Tuple, ShArray]] = None,
) -> None:
    def _serialize_observation(obs, buffer):
        if isinstance(obs, np.ndarray) and isinstance(buffer, ShArray):
            buffer.store(obs)
        elif isinstance(obs, tuple) and isinstance(buffer, tuple):
            for o_part, b_part in zip(obs, buffer):
                _serialize_observation(o_part, b_part)
        elif isinstance(obs, dict) and isinstance(buffer, dict):
            for key in obs:
                _serialize_observation(obs[key], buffer[key])
        return None

    child_conn.close()
    env = env_factory.data()
    try:
        while True:
            try:
                message_type, payload = parent_conn.recv()
            except EOFError:
                parent_conn.close()
                break

            if message_type == "step":
                result = env.step(payload)
                if shared_buffers is not None:
                    _serialize_observation(result[0], shared_buffers)
                    result = (None,) + result[1:]
                parent_conn.send(result)

            elif message_type == "reset":
                output = env.reset(**payload) if payload else env.reset()
                has_info = isinstance(output, (list, tuple)) and len(output) == 2 and isinstance(output[1], dict)
                if has_info:
                    obs, info = output
                else:
                    obs = output
                    info = None

                if shared_buffers is not None:
                    _serialize_observation(obs, shared_buffers)
                    obs = None

                if has_info:
                    parent_conn.send((obs, info))
                else:
                    parent_conn.send(obs)

            elif message_type == "close":
                result = env.close() if hasattr(env, "close") else None
                parent_conn.send(result)
                parent_conn.close()
                break

            elif message_type == "render":
                rendered = env.render(**payload) if hasattr(env, "render") else None
                parent_conn.send(rendered)

            elif message_type == "seed":
                if hasattr(env, "seed"):
                    seed_result = env.seed(payload)
                else:
                    env.reset(seed=payload)
                    seed_result = None
                parent_conn.send(seed_result)

            elif message_type == "getattr":
                attr_value = getattr(env, payload) if hasattr(env, payload) else None
                parent_conn.send(attr_value)

            elif message_type == "setattr":
                setattr(env.unwrapped, payload["key"], payload["value"])

            elif message_type == "get_observations":
                obs = None
                if hasattr(env, "get_observations"):
                    obs = env.get_observations()
                elif hasattr(env, "observations"):
                    obs = env.observations
                parent_conn.send(obs)

            elif message_type == "get_current_episode_id":
                episode_id = None
                if hasattr(env, "habitat_env") and hasattr(env.habitat_env, "current_episode"):
                    episode_id = env.habitat_env.current_episode.episode_id
                parent_conn.send(episode_id)

            elif message_type == "reconfigure":
                env.close()
                cfg = payload.pop("config")
                seed_val = payload.pop("seed")
                env = HabitatRLEnv(config=cfg)
                env.seed(seed_val)
                parent_conn.send(None)

            else:
                parent_conn.close()
                raise ValueError(f"Unknown command received: {message_type}")

    except KeyboardInterrupt:
        parent_conn.close()


class ReconfigurableSubprocWorker(SubprocEnvWorker):
    def __init__(self, env_fn: Callable[[], gym.Env], use_shared_mem: bool = False):
        ctx = mp.get_context("spawn")
        self.parent_pipe, self.child_pipe = ctx.Pipe()
        self.use_shared_mem = use_shared_mem
        self.memory_buffer: Optional[Union[Dict, Tuple, ShArray]] = None

        if self.use_shared_mem:
            temp_env = env_fn()
            observation_space = temp_env.observation_space
            temp_env.close()
            del temp_env
            self.memory_buffer = _setup_buf(observation_space)

        args = (
            self.parent_pipe,
            self.child_pipe,
            CloudpickleWrapper(env_fn),
            self.memory_buffer,
        )
        self.worker_process = ctx.Process(target=_remote_worker, args=args, daemon=True)
        self.worker_process.start()
        self.child_pipe.close()
        EnvWorker.__init__(self, env_fn)

    def update_env_config(self, new_config):
        self.parent_pipe.send(["reconfigure", new_config])
        return self.parent_pipe.recv()


class ReconfigurableSubprocVectorEnv(SubprocVectorEnv):
    def __init__(self, env_constructors: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def make_worker(fn: Callable[[], gym.Env]) -> ReconfigurableSubprocWorker:
            return ReconfigurableSubprocWorker(fn, share_memory=False)

        BaseVectorEnv.__init__(self, env_constructors, make_worker, **kwargs)

    def apply_reconfiguration(self, configs, indices=None):
        self._check_closed()
        indices = self._normalize_indices(indices)
        if self.async_mode:
            self._validate_indices(indices)
        for idx, worker_idx in enumerate(indices):
            self.workers[worker_idx].update_env_config(configs[idx])

    def fetch_episode_ids(self, indices=None):
        self._check_closed()
        indices = self._normalize_indices(indices)
        if self.async_mode:
            self._validate_indices(indices)

        ids_list = []
        for idx in indices:
            self.workers[idx].parent_pipe.send(["get_current_episode_id", None])
            eid = self.workers[idx].parent_pipe.recv()
            ids_list.append(eid)
        return ids_list

# Type III Clone: Refactored role and access resolution logic with equivalent functionality

import base64
import json
from abc import ABC, abstractmethod
from typing import Any
from jsonpath_ng import parse
from authentication.interface import AuthTuple
from models.config import JwtRoleRule, AccessRule, JsonPathOperator, Action
import constants
from log import get_logger

logger = get_logger(__name__)

UserRoles = set[str]

class RoleResolutionError(Exception):
    """Custom exception for role resolution errors."""
    pass

class RolesResolver(ABC):
    """Base class for all role resolution strategies."""

    @abstractmethod
    async def resolve_roles(self, auth: AuthTuple) -> UserRoles:
        """Resolve user roles from authentication data."""
        pass

class NoopRolesResolver(RolesResolver):
    """No-op resolver that returns empty roles."""

    async def resolve_roles(self, auth: AuthTuple) -> UserRoles:
        """Return an empty set of roles regardless of input."""
        return set()

def extract_claims(token: str) -> dict[str, Any]:
    """Extract JWT claims without signature verification.

    Decodes the payload portion of a JWT token using base64 decoding.
    Assumes prior validation has occurred during authentication.
    """
    parts = token.split(".")
    if len(parts) < 2:
        return {}

    payload = parts[1]
    # Add padding if necessary for valid base64
    padded_payload = payload + "=" * (-len(payload) % 4)
    try:
        decoded_bytes = base64.urlsafe_b64decode(padded_payload)
        return json.loads(decoded_bytes)
    except Exception:
        return {}

class JwtRolesResolver(RolesResolver):
    """Resolves roles by evaluating JSONPath rules against JWT claims."""

    def __init__(self, rules: list[JwtRoleRule]):
        """Initialize with role extraction rules."""
        self.rules = rules

    async def resolve_roles(self, auth: AuthTuple) -> UserRoles:
        """Extract roles using configured rules on JWT claims."""
        claims = self._extract_claims(auth)

        resolved_roles = set()
        for rule in self.rules:
            matches = [m.value for m in parse(rule.jsonpath).find(claims)]
            if self._check_rule_match(rule, matches):
                resolved_roles.update(rule.roles)

        return resolved_roles

    @staticmethod
    def _check_rule_match(rule: JwtRoleRule, values: list[Any]) -> bool:
        """Determine if a rule applies to given values."""
        outcome = False

        match rule.operator:
            case JsonPathOperator.EQUALS:
                outcome = (values == rule.value)
            case JsonPathOperator.CONTAINS:
                outcome = (rule.value in values)
            case JsonPathOperator.IN:
                outcome = (values in rule.value)
            case JsonPathOperator.MATCH:
                if rule.compiled_regex is not None:
                    outcome = any(
                        isinstance(v, str) and rule.compiled_regex.search(v)
                        for v in values
                    )

        return not outcome if rule.negate else outcome

    @staticmethod
    def _extract_claims(auth: AuthTuple) -> dict[str, Any]:
        """Get JWT claims from auth tuple."""
        _, _, _, token = auth

        if token == constants.NO_USER_TOKEN:
            return {}

        return extract_claims(token)

class AccessResolver(ABC):
    """Base class for access control resolution."""

    @abstractmethod
    def check_access(self, action: Action, roles: UserRoles) -> bool:
        """Check if any role permits the specified action."""
        pass

    @abstractmethod
    def list_permissions(self, roles: UserRoles) -> set[Action]:
        """List all actions permitted by the given roles."""
        pass

class NoopAccessResolver(AccessResolver):
    """Resolver that grants all access unconditionally."""

    def check_access(self, action: Action, roles: UserRoles) -> bool:
        """Always grant access."""
        return True

    def list_permissions(self, roles: UserRoles) -> set[Action]:
        """Return all non-admin actions."""
        return set(Action) - {Action.ADMIN}

class GenericAccessResolver(AccessResolver):
    """Role-based access resolver supporting ADMIN override."""

    def __init__(self, rules: list[AccessRule]):
        """Build internal mapping from roles to allowed actions."""
        for rule in rules:
            if Action.ADMIN in rule.actions and len(rule.actions) > 1:
                raise ValueError("Admin role cannot be combined with other actions")

        self.role_map = {}
        for rule in rules:
            if rule.role not in self.role_map:
                self.role_map[rule.role] = set()
            self.role_map[rule.role].update(rule.actions)

    def check_access(self, action: Action, roles: UserRoles) -> bool:
        """Verify if any role allows the requested action."""
        # Check for admin override first
        if action != Action.ADMIN and self.check_access(Action.ADMIN, roles):
            return True

        for role in roles:
            if role in self.role_map and action in self.role_map[role]:
                logger.debug("Access granted: role '%s' can perform action '%s'", role, action)
                return True

        logger.debug("Access denied: roles %s cannot perform action '%s'", roles, action)
        return False

    def list_permissions(self, roles: UserRoles) -> set[Action]:
        """Aggregate permissions across all roles."""
        permissions = set()
        for role in roles:
            permissions.update(self.role_map.get(role, set()))

        if Action.ADMIN in permissions:
            return set(Action) - {Action.ADMIN}
        return permissions

