    "x": re.VERBOSE,
}

class DateTimeFormatMode:
    """Alternative datetime representation modes"""
    V1 = 0  # Legacy format
    V2 = 1  # NumberLong format
    V3 = 2  # ISO8601 format

class ExtendedJSONStyle:
    """Extended JSON formatting styles"""
    ORIGINAL = 0
    MODERN = 1
    STRICT = 2

class JsonConfig(CodecOptions):
    """Configuration class for JSON encoding/decoding operations"""

    use_strict_long: bool
    date_format_mode: int
    strict_uuid_handling: bool

    def __new__(
        cls: Type["JsonConfig"],
        use_strict_long: Optional[bool] = None,
        date_format_mode: Optional[int] = None,
        strict_uuid_handling: Optional[bool] = None,
        json_style: int = ExtendedJSONStyle.MODERN,
        *args: Any,
        **kwargs: Any
    ) -> "JsonConfig":
        kwargs["tz_aware"] = kwargs.get("tz_aware", False)
        if kwargs["tz_aware"]:
            kwargs["tzinfo"] = kwargs.get("tzinfo", utc)

        # Validate date format mode
        if date_format_mode not in (
            DateTimeFormatMode.V1,
            DateTimeFormatMode.V2,
            DateTimeFormatMode.V3,
            None,
        ):
            raise ValueError(
                "JsonConfig.date_format_mode must be one of V1, V2, or V3 from DateTimeFormatMode."
            )

        self = cast(JsonConfig, super(JsonConfig, cls).__new__(cls, *args, **kwargs))

        # Validate JSON style
        if json_style not in (ExtendedJSONStyle.ORIGINAL, ExtendedJSONStyle.MODERN, ExtendedJSONStyle.STRICT):
            raise ValueError(
                "JsonConfig.json_style must be one of ORIGINAL, MODERN, "
                "or STRICT from ExtendedJSONStyle."
            )

        self.json_style = json_style

        # Apply style-specific defaults
        if self.json_style == ExtendedJSONStyle.MODERN:
            if use_strict_long:
                raise ValueError("Cannot specify use_strict_long=True with json_style=MODERN")
            if date_format_mode not in (None, DateTimeFormatMode.V3):
                raise ValueError(
                    "date_format_mode must be DateTimeFormatMode.V3 or omitted with json_style=MODERN"
                )
            if strict_uuid_handling not in (None, True):
                raise ValueError("Cannot specify strict_uuid_handling=False with json_style=MODERN")
            self.use_strict_long = False
            self.date_format_mode = DateTimeFormatMode.V3
            self.strict_uuid_handling = True
        elif self.json_style == ExtendedJSONStyle.STRICT:
            if use_strict_long not in (None, True):
                raise ValueError("Cannot specify use_strict_long=False with json_style=STRICT")
            if date_format_mode not in (None, DateTimeFormatMode.V2):
                raise ValueError(
                    "date_format_mode must be DateTimeFormatMode.V2 or omitted with json_style=STRICT"
                )
            if strict_uuid_handling not in (None, True):
                raise ValueError("Cannot specify strict_uuid_handling=False with json_style=STRICT")
            self.use_strict_long = True
            self.date_format_mode = DateTimeFormatMode.V2
            self.strict_uuid_handling = True
        else:  # ExtendedJSONStyle.ORIGINAL
            self.use_strict_long = False
            self.date_format_mode = DateTimeFormatMode.V1
            self.strict_uuid_handling = False
            if use_strict_long is not None:
                self.use_strict_long = use_strict_long
            if date_format_mode is not None:
                self.date_format_mode = date_format_mode
            if strict_uuid_handling is not None:
                self.strict_uuid_handling = strict_uuid_handling

        return self

    def _arguments_repr(self) -> str:
        return (
            "use_strict_long=%r, "
            "date_format_mode=%r, "
            "strict_uuid_handling=%r, json_style=%r, %s"
            % (
                self.use_strict_long,
                self.date_format_mode,
                self.strict_uuid_handling,
                self.json_style,
                super(JsonConfig, self)._arguments_repr(),
            )
        )

    def _options_dict(self) -> Dict[Any, Any]:
        options_dict = super(JsonConfig, self)._options_dict()
        options_dict.update(
            {
                "use_strict_long": self.use_strict_long,
                "date_format_mode": self.date_format_mode,
                "strict_uuid_handling": self.strict_uuid_handling,
                "json_style": self.json_style,
            }
        )
        return options_dict

    def with_options(self, **kwargs: Any) -> "JsonConfig":
        """
        Create a modified copy of this JsonConfig, overriding specific settings.
        Example usage:
            >>> from .json_util import STRICT_JSON_CONFIG
            >>> STRICT_JSON_CONFIG.tz_aware
            True
            >>> config = STRICT_JSON_CONFIG.with_options(tz_aware=False, tzinfo=None)
            >>> config.tz_aware
            False
        """
        opts = self._options_dict()
        for opt in ("use_strict_long", "date_format_mode", "strict_uuid_handling", "json_style"):
            opts[opt] = kwargs.get(opt, getattr(self, opt))
        opts.update(kwargs)
        return JsonConfig(**opts)

ORIGINAL_JSON_CONFIG: JsonConfig = JsonConfig(json_style=ExtendedJSONStyle.ORIGINAL)
""":class:`JsonConfig` for original PyMongo JSON format."""
STRICT_JSON_CONFIG: JsonConfig = JsonConfig(json_style=ExtendedJSONStyle.STRICT)
""":class:`JsonConfig` for strict Extended JSON."""
MODERN_JSON_CONFIG: JsonConfig = JsonConfig(json_style=ExtendedJSONStyle.MODERN)
""":class:`JsonConfig` for modern Extended JSON."""
DEFAULT_JSON_CONFIG: JsonConfig = MODERN_JSON_CONFIG
"""Default configuration for JSON operations."""

def encode_json(obj: Any, *args: Any, **kwargs: Any) -> str:
    """Convert BSON objects to JSON string representation."""
    json_config = kwargs.pop("json_config", DEFAULT_JSON_CONFIG)
    return json.dumps(_transform_for_json(obj, json_config), *args, **kwargs)

def decode_json(s: str, *args: Any, **kwargs: Any) -> Any:
    """Parse JSON string back to BSON objects."""
    json_config = kwargs.pop("json_config", DEFAULT_JSON_CONFIG)
    kwargs["object_pairs_hook"] = lambda pairs: _reconstruct_from_pairs(pairs, json_config)
    return json.loads(s, *args, **kwargs)

def _transform_for_json(obj: Any, json_config: JsonConfig = DEFAULT_JSON_CONFIG) -> Any:
    """Recursive transformer that prepares BSON types for JSON serialization."""
    if hasattr(obj, "items"):
        return SON(((k, _transform_for_json(v, json_config)) for k, v in obj.items()))
    elif hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes)):
        return list((_transform_for_json(v, json_config) for v in obj))
    try:
        return _serialize_value(obj, json_config)
    except TypeError:
        return obj

def _reconstruct_from_pairs(
    pairs: Sequence[Tuple[str, Any]], json_config: JsonConfig = DEFAULT_JSON_CONFIG
) -> Any:
    return _reconstruct_object(_create_document(pairs), json_config)

def _create_document(pairs: Sequence[Tuple[str, Any]]) -> Any:
    """Create document from key-value pairs."""
    return pairs

def _reconstruct_object(dct: Mapping[str, Any], json_config: JsonConfig = DEFAULT_JSON_CONFIG) -> Any:
    """Process JSON objects to reconstruct BSON types."""
    if "$oid" in dct:
        return _extract_oid(dct)
    if (
        isinstance(dct.get("$ref"), str)
        and "$id" in dct
        and isinstance(dct.get("$db"), (str, type(None)))
    ):
        return _extract_dbref(dct)
    if "$date" in dct:
        return _extract_datetime(dct, json_config)
    if "$regex" in dct:
        return _extract_regex(dct)
    if "$minKey" in dct:
        return _extract_minkey(dct)
    if "$maxKey" in dct:
        return _extract_maxkey(dct)
    if "$binary" in dct:
        if "$type" in dct:
            return _extract_legacy_binary(dct, json_config)
        else:
            return _extract_canonical_binary(dct, json_config)
    if "$code" in dct:
        return _extract_code(dct)
    if "$uuid" in dct:
        return _extract_legacy_uuid(dct, json_config)
    if "$undefined" in dct:
        return None
    if "$numberLong" in dct:
        return _extract_int64(dct)
    if "$timestamp" in dct:
        tsp = dct["$timestamp"]
        return Timestamp(tsp["t"], tsp["i"])
    if "$numberDecimal" in dct:
        return _extract_decimal128(dct)
    if "$dbPointer" in dct:
        return _extract_dbpointer(dct)
    if "$regularExpression" in dct:
        return _extract_regex_v2(dct)
    if "$symbol" in dct:
        return _extract_symbol(dct)
    if "$numberInt" in dct:
        return _extract_int32(dct)
    if "$numberDouble" in dct:
        return _extract_double(dct)
    return dct

def _extract_regex(doc: Any) -> Any:
    """Extract regex pattern and flags from legacy format."""
    pattern = doc["$regex"]
    if not isinstance(pattern, (str, bytes)):
        return doc
    flags = 0
    for opt in doc.get("$options", ""):
        flags |= _REGEX_FLAG_MAP.get(opt, 0)
    return Regex(pattern, flags)

def _extract_legacy_uuid(doc: Any, json_config: JsonConfig) -> Union[Binary, uuid.UUID]:
    """Decode legacy $uuid format."""
    if len(doc) != 1:
        raise TypeError("Invalid $uuid format, extra fields detected: %s" % (doc,))
    if not isinstance(doc["$uuid"], str):
        raise TypeError("$uuid must be a string: %s" % (doc,))
    if json_config.uuid_representation == UuidRepresentation.UNSPECIFIED:
        return Binary.from_uuid(uuid.UUID(doc["$uuid"]))
    else:
        return uuid.UUID(doc["$uuid"])

def _binary_or_uuid(data: Any, subtype: int, json_config: JsonConfig) -> Union[Binary, uuid.UUID]:
    """Handle binary data or UUID conversion based on subtype."""
    if subtype in ALL_UUID_SUBTYPES:
        uuid_rep = json_config.uuid_representation
        binary_val = Binary(data, subtype)
        if uuid_rep == UuidRepresentation.UNSPECIFIED:
            return binary_val
        if subtype == UUID_SUBTYPE:
            uuid_rep = UuidRepresentation.STANDARD
        elif uuid_rep == UuidRepresentation.STANDARD:
            uuid_rep = UuidRepresentation.PYTHON_LEGACY
        return binary_val.as_uuid(uuid_rep)
    if subtype == 0:
        return cast(uuid.UUID, data)
    return Binary(data, subtype)

def _extract_legacy_binary(doc: Any, json_config: JsonConfig) -> Union[Binary, uuid.UUID]:
    """Process legacy binary format."""
    if isinstance(doc["$type"], int):
        doc["$type"] = "%02x" % doc["$type"]
    subtype = int(doc["$type"], 16)
    if subtype >= 0xFFFFFF80:
        subtype = int(doc["$type"][6:], 16)
    data = base64.b64decode(doc["$binary"].encode())
    return _binary_or_uuid(data, subtype, json_config)

def _extract_canonical_binary(doc: Any, json_config: JsonConfig) -> Union[Binary, uuid.UUID]:
    """Process canonical binary format."""
    binary_data = doc["$binary"]
    b64_content = binary_data["base64"]
    subtype_hex = binary_data["subType"]
    if not isinstance(b64_content, str):
        raise TypeError("$binary base64 must be a string: %s" % (doc,))
    if not isinstance(subtype_hex, str) or len(subtype_hex) > 2:
        raise TypeError("$binary subType must be a string at most 2 characters: %s" % (doc,))
    if len(binary_data) != 2:
        raise TypeError('$binary must include only "base64" and "subType" components: %s' % (doc,))
    data_bytes = base64.b64decode(b64_content.encode())
    return _binary_or_uuid(data_bytes, int(subtype_hex, 16), json_config)

def _extract_datetime(
    doc: Any, json_config: JsonConfig
) -> Union[datetime.datetime, DatetimeMS]:
    """Extract datetime from JSON representation."""
    dt_content = doc["$date"]
    if len(doc) != 1:
        raise TypeError("Invalid $date format, extra fields detected: %s" % (doc,))
    if isinstance(dt_content, str):
        # Handle ISO8601 format
        if dt_content[-1] == "Z":
            dt_part = dt_content[:-1]
            tz_part = "Z"
        elif dt_content[-6] in ("+", "-") and dt_content[-3] == ":":
            dt_part = dt_content[:-6]
            tz_part = dt_content[-6:]
        elif dt_content[-5] in ("+", "-"):
            dt_part = dt_content[:-5]
            tz_part = dt_content[-5:]
        elif dt_content[-3] in ("+", "-"):
            dt_part = dt_content[:-3]
            tz_part = dt_content[-3:]
        else:
            dt_part = dt_content
            tz_part = ""

        # Parse fractional seconds
        dot_pos = dt_part.rfind(".")
        microsecond_val = 0
        if dot_pos != -1:
            microsecond_val = int(float(dt_part[dot_pos:]) * 1000000)
            dt_part = dt_part[:dot_pos]

        aware_dt = datetime.datetime.strptime(dt_part, "%Y-%m-%dT%H:%M:%S").replace(
            microsecond=microsecond_val, tzinfo=utc
        )

        # Apply timezone offset
        if tz_part and tz_part != "Z":
            if len(tz_part) == 6:
                hours_offset, minutes_offset = tz_part[1:].split(":")
                total_seconds = int(hours_offset) * 3600 + int(minutes_offset) * 60
            elif len(tz_part) == 5:
                total_seconds = int(tz_part[1:3]) * 3600 + int(tz_part[3:]) * 60
            elif len(tz_part) == 3:
                total_seconds = int(tz_part[1:3]) * 3600
            if tz_part[0] == "-":
                total_seconds *= -1
            aware_dt = aware_dt - datetime.timedelta(seconds=total_seconds)

        if json_config.tz_aware:
            if json_config.tzinfo:
                aware_dt = aware_dt.astimezone(json_config.tzinfo)
            if json_config.datetime_conversion == DatetimeConversion.DATETIME_MS:
                return DatetimeMS(aware_dt)
            return aware_dt
        else:
            naive_dt = aware_dt.replace(tzinfo=None)
            if json_config.datetime_conversion == DatetimeConversion.DATETIME_MS:
                return DatetimeMS(naive_dt)
            return naive_dt

    return _millis_to_datetime(int(dt_content), json_config)

def _extract_oid(doc: Any) -> ObjectId:
    """Extract ObjectId from JSON."""
    if len(doc) != 1:
        raise TypeError("Invalid $oid format, extra fields detected: %s" % (doc,))
    return ObjectId(doc["$oid"])

def _extract_symbol(doc: Any) -> str:
    """Extract symbol from JSON."""
    symbol_val = doc["$symbol"]
    if len(doc) != 1:
        raise TypeError("Invalid $symbol format, extra fields detected: %s" % (doc,))
    return str(symbol_val)

def _extract_code(doc: Any) -> Code:
    """Extract code with optional scope from JSON."""
    for key in doc:
        if key not in ("$code", "$scope"):
            raise TypeError("Invalid $code format, extra fields detected: %s" % (doc,))
    return Code(doc["$code"], scope=doc.get("$scope"))

def _extract_regex_v2(doc: Any) -> Regex:
    """Extract regex from canonical format."""
    regex_data = doc["$regularExpression"]
    if len(doc) != 1:
        raise TypeError("Invalid $regularExpression format, extra fields detected: %s" % (doc,))
    if len(regex_data) != 2:
        raise TypeError(
            'Invalid $regularExpression format, must include only "pattern" and "options": %s' % (doc,)
        )
    opts_str = regex_data["options"]
    if not isinstance(opts_str, str):
        raise TypeError(
            "Invalid $regularExpression options, expected string but got %s" % (type(opts_str))
        )
    return Regex(regex_data["pattern"], opts_str)

def _extract_dbref(doc: Any) -> DBRef:
    """Extract DBRef from JSON."""
    return DBRef(doc.pop("$ref"), doc.pop("$id"), database=doc.pop("$db", None), **doc)

def _extract_dbpointer(doc: Any) -> Any:
    """Extract DBPointer from JSON."""
    db_pointer = doc["$dbPointer"]
    if len(doc) != 1:
        raise TypeError("Invalid $dbPointer format, extra fields detected: %s" % (doc,))
    if isinstance(db_pointer, DBRef):
        dbref_doc = db_pointer.as_doc()
        if db_pointer.database is not None:
            raise TypeError("Invalid $dbPointer, contains $db field: %s" % (dbref_doc,))
        if not isinstance(db_pointer.id, ObjectId):
            raise TypeError("Invalid $dbPointer, $id must be an ObjectId: %s" % (dbref_doc,))
        if len(dbref_doc) != 2:
            raise TypeError("Invalid $dbPointer, DBRef has extra fields: %s" % (dbref_doc,))
        return db_pointer
    else:
        raise TypeError("Invalid $dbPointer, expected a DBRef: %s" % (doc,))

def _extract_int32(doc: Any) -> int:
    """Extract int32 from JSON."""
    i_str = doc["$numberInt"]
    if len(doc) != 1:
        raise TypeError("Invalid $numberInt format, extra fields detected: %s" % (doc,))
    if not isinstance(i_str, str):
        raise TypeError("$numberInt must be string: %s" % (doc,))
    return int(i_str)

def _extract_int64(doc: Any) -> Int64:
    """Extract int64 from JSON."""
    l_str = doc["$numberLong"]
    if len(doc) != 1:
        raise TypeError("Invalid $numberLong format, extra fields detected: %s" % (doc,))
    return Int64(l_str)

def _extract_double(doc: Any) -> float:
    """Extract double from JSON."""
    d_str = doc["$numberDouble"]
    if len(doc) != 1:
        raise TypeError("Invalid $numberDouble format, extra fields detected: %s" % (doc,))
    if not isinstance(d_str, str):
        raise TypeError("$numberDouble must be string: %s" % (doc,))
    return float(d_str)

def _extract_decimal128(doc: Any) -> Decimal128:
    """Extract decimal128 from JSON."""
    d_str = doc["$numberDecimal"]
    if len(doc) != 1:
        raise TypeError("Invalid $numberDecimal format, extra fields detected: %s" % (doc,))
    if not isinstance(d_str, str):
        raise TypeError("$numberDecimal must be string: %s" % (doc,))
    return Decimal128(d_str)

def _extract_minkey(doc: Any) -> MinKey:
    """Extract MinKey from JSON."""
    if type(doc["$minKey"]) is not int or doc["$minKey"] != 1:
        raise TypeError("$minKey value must be 1: %s" % (doc,))
    if len(doc) != 1:
        raise TypeError("Invalid $minKey format, extra fields detected: %s" % (doc,))
    return MinKey()

def _extract_maxkey(doc: Any) -> MaxKey:
    """Extract MaxKey from JSON."""
    if type(doc["$maxKey"]) is not int or doc["$maxKey"] != 1:
        raise TypeError("$maxKey value must be 1: %s", (doc,))
    if len(doc) != 1:
        raise TypeError("Invalid $maxKey format, extra fields detected: %s" % (doc,))
    return MaxKey()

def _encode_binary_data(data: bytes, subtype: int, json_config: JsonConfig) -> Any:
    """Encode binary data to appropriate JSON format."""
    if json_config.json_style == ExtendedJSONStyle.ORIGINAL:
        return SON([("$binary", base64.b64encode(data).decode()), ("$type", "%02x" % subtype)])
    return {
        "$binary": SON([("base64", base64.b64encode(data).decode()), ("subType", "%02x" % subtype)])
    }

def _serialize_value(obj: Any, json_config: JsonConfig = DEFAULT_JSON_CONFIG) -> Any:
    """Serialize individual values to JSON-compatible format."""
    if isinstance(obj, ObjectId):
        return {"$oid": str(obj)}
    if isinstance(obj, DBRef):
        return _transform_for_json(obj.as_doc(), json_config=json_config)
    if isinstance(obj, datetime.datetime):
        if json_config.date_format_mode == DateTimeFormatMode.V3:
            if not obj.tzinfo:
                obj = obj.replace(tzinfo=utc)
                assert obj.tzinfo is not None
            if obj >= EPOCH_AWARE:
                offset = obj.tzinfo.utcoffset(obj)
                if (offset.days, offset.seconds, offset.microseconds) == (0, 0, 0):  # type: ignore
                    tz_suffix = "Z"
                else:
                    tz_suffix = obj.strftime("%z")
                millis_val = int(obj.microsecond / 1000)
                frac_secs = ".%03d" % (millis_val,) if millis_val else ""
                return {
                    "$date": "%s%s%s" % (obj.strftime("%Y-%m-%dT%H:%M:%S"), frac_secs, tz_suffix)
                }
        millis_val = _datetime_to_millis(obj)
        if json_config.date_format_mode == DateTimeFormatMode.V1:
            return {"$date": millis_val}
        return {"$date": {"$numberLong": str(millis_val)}}
    if isinstance(obj, DatetimeMS):
        if (
            json_config.date_format_mode == DateTimeFormatMode.V3
            and 0 <= int(obj) <= _max_datetime_ms()
        ):
            return _serialize_value(obj.as_datetime(), json_config)
        elif json_config.date_format_mode == DateTimeFormatMode.V1:
            return {"$date": str(int(obj))}
        return {"$date": {"$numberLong": str(int(obj))}}
    if json_config.use_strict_long and isinstance(obj, Int64):
        return {"$numberLong": str(obj)}
    if isinstance(obj, (RE_TYPE, Regex)):
        flags_str = ""
        if obj.flags & re.IGNORECASE:
            flags_str += "i"
        if obj.flags & re.LOCALE:
            flags_str += "l"
        if obj.flags & re.MULTILINE:
            flags_str += "m"
        if obj.flags & re.DOTALL:
            flags_str += "s"
        if obj.flags & re.UNICODE:
            flags_str += "u"
        if obj.flags & re.VERBOSE:
            flags_str += "x"
        if isinstance(obj.pattern, str):
            pattern_str = obj.pattern
        else:
            pattern_str = obj.pattern.decode("utf-8")
        if json_config.json_style == ExtendedJSONStyle.ORIGINAL:
            return SON([("$regex", pattern_str), ("$options", flags_str)])
        return {"$regularExpression": SON([("pattern", pattern_str), ("options", flags_str)])}
    if isinstance(obj, MinKey):
        return {"$minKey": 1}
    if isinstance(obj, MaxKey):
        return {"$maxKey": 1}
    if isinstance(obj, Timestamp):
        return {"$timestamp": SON([("t", obj.time), ("i", obj.inc)])}
    if isinstance(obj, Code):
        if obj.scope is None:
            return {"$code": str(obj)}
        return SON([("$code", str(obj)), ("$scope", _transform_for_json(obj.scope, json_config))])
    if isinstance(obj, Binary):
        return _encode_binary_data(obj, obj.subtype, json_config)
    if isinstance(obj, bytes):
        return _encode_binary_data(obj, 0, json_config)
    if isinstance(obj, uuid.UUID):
        if json_config.strict_uuid_handling:
            binval = Binary.from_uuid(obj, uuid_representation=json_config.uuid_representation)
            return _encode_binary_data(binval, binval.subtype, json_config)
        else:
            return {"$uuid": obj.hex}
    if isinstance(obj, Decimal128):
        return {"$numberDecimal": str(obj)}
    if isinstance(obj, bool):
        return obj
    if json_config.json_style == ExtendedJSONStyle.STRICT and isinstance(obj, int):
        if -(2**31) <= obj < 2**31:
            return {"$numberInt": str(obj)}
        return {"$numberLong": str(obj)}
    if json_config.json_style != ExtendedJSONStyle.ORIGINAL and isinstance(obj, float):
        if math.isnan(obj):
            return {"$numberDouble": "NaN"}
        elif math.isinf(obj):
            representation = "Infinity" if obj > 0 else "-Infinity"
            return {"$numberDouble": representation}
        elif json_config.json_style == ExtendedJSONStyle.STRICT:
            return {"$numberDouble": str(repr(obj))}
    raise TypeError("%r is not JSON serializable" % obj)

# Type III Clone: Refactored test suite for Serializer validation logic

from __future__ import annotations
import pytest
from django_bolt.exceptions import RequestValidationError
from django_bolt.serializers import Serializer, validate_field, validate_model


class TestSerializerBasicConstructs:
    """Alternative tests for core Serializer functionality."""

    def test_basic_instance_construction(self):
        """Revised test for serializer object creation."""
        class ProfileSerializer(Serializer):
            name: str
            contact: str
        profile = ProfileSerializer(name="diana", contact="redacted@example.invalid")
        assert profile.name == "diana"
        assert profile.contact == "redacted@example.invalid"

