class TestFieldValidationMechanisms:
    """Tests for field-level validation behavior."""

    def test_simple_validation_rule(self):
        """Test basic field validation with custom rule."""
        class ProfileSerializer(Serializer):
            contact: str
            @validate_field("contact")
            def ensure_valid_contact(cls, val):
                if "@" not in val:
                    raise ValueError("Contact must be email-like")
                return val
        # Valid input should succeed
        profile = ProfileSerializer(contact="redacted@example.invalid")
        assert profile.contact == "redacted@example.invalid"
        # Invalid input should fail
        with pytest.raises(RequestValidationError) as err_ctx:
            ProfileSerializer(contact="bad-contact")
        assert "Contact must be email-like" in str(err_ctx.value)

    def test_value_normalization(self):
        """Test that validators can normalize input values."""
        class ProfileSerializer(Serializer):
            contact: str
            @validate_field("contact")
            def standardize_contact(cls, val):
                return val.strip().lower()
        profile = ProfileSerializer(contact="  redacted@example.invalid  ")
        assert profile.contact == "redacted@example.invalid"

    def test_chained_validation_rules(self):
        """Test multiple validators on a single field."""
        class AccountSerializer(Serializer):
            secret: str
            @validate_field("secret")
            def enforce_minimum_length(cls, val):
                if len(val) < 6:
                    raise ValueError("Secret too short")
                return val
            @validate_field("secret")
            def require_mixed_case(cls, val):
                if not any(c.isupper() for c in val):
                    raise ValueError("Secret must contain uppercase")
                return val
        # Valid secret passes all checks
        account = AccountSerializer(secret="SafePass123")
        assert account.secret == "SafePass123"
        # Fails minimum length
        with pytest.raises(RequestValidationError):
            AccountSerializer(secret="Short1")
        # Fails mixed case requirement
        with pytest.raises(RequestValidationError):
            AccountSerializer(secret="longpassword1")

    def test_validator_preserves_original_when_no_return(self):
        """Test that validators without explicit returns preserve original value."""
        class ProfileSerializer(Serializer):
            contact: str
            @validate_field("contact")
            def check_only(cls, val):
                if "@" not in val:
                    raise ValueError("Invalid contact format")
                # Intentionally no return statement
        # Valid input preserves original form
        profile = ProfileSerializer(contact="redacted@example.invalid")
        assert profile.contact == "redacted@example.invalid"
        # Invalid input still raises error
        with pytest.raises(RequestValidationError) as err_ctx:
            ProfileSerializer(contact="invalid")
        assert "Invalid contact format" in str(err_ctx.value)

    def test_mixed_return_behavior_in_chain(self):
        """Test validators where some return transformed values and others don't."""
        class ProfileSerializer(Serializer):
            contact: str
            @validate_field("contact")
            def format_check(cls, val):
                if "@" not in val:
                    raise ValueError("Bad format")
                # No return here
            @validate_field("contact")
            def case_normalize(cls, val):
                return val.lower().strip()
        # Should apply normalization from second validator
        profile = ProfileSerializer(contact="  redacted@example.invalid  ")
        assert profile.contact == "redacted@example.invalid"
        # First validator still enforces format
        with pytest.raises(RequestValidationError):
            ProfileSerializer(contact="no-at-sign")


class TestModelLevelValidation:
    """Tests for model-level (cross-field) validation."""

    def test_cross_field_consistency_check(self):
        """Test model validator ensuring consistency between fields."""
        class PasswordSerializer(Serializer):
            password: str
            confirmation: str
            @validate_model
            def verify_match(self):
                if self.password != self.confirmation:
                    raise ValueError("Passwords do not match")
        # Matching passwords succeed
        instance = PasswordSerializer(password="REDACTED_CREDENTIAL", confirmation="MyP@ss123")
        assert instance.password == "MyP@ss123"
        # Non-matching passwords fail
        with pytest.raises(RequestValidationError) as err_ctx:
            PasswordSerializer(password="REDACTED_CREDENTIAL", confirmation="Different456")
        assert "do not match" in str(err_ctx.value)

    def test_range_validation_logic(self):
        """Test model validator for range constraints."""
        class IntervalSerializer(Serializer):
            lower_bound: int
            upper_bound: int
            @validate_model
            def validate_interval(self):
                if self.lower_bound >= self.upper_bound:
                    raise ValueError("Lower bound must be less than upper bound")
        # Valid interval
        interval = IntervalSerializer(lower_bound=5, upper_bound=15)
        assert interval.lower_bound == 5
        assert interval.upper_bound == 15
        # Invalid interval
        with pytest.raises(RequestValidationError):
            IntervalSerializer(lower_bound=15, upper_bound=5)


