class TestMultiErrorHandling:
    """Tests for collecting multiple validation errors."""

    def test_aggregated_field_errors(self):
        """Test collection of multiple field validation errors."""
        class ProfileSerializer(Serializer):
            email: str
            password: str
            @validate_field("email")
            def validate_email(cls, val):
                if "@" not in val:
                    raise ValueError("Email invalid")
                return val
            @validate_field("password")
            def validate_password(cls, val):
                if len(val) < 8:
                    raise ValueError("Password too short")
                return val
        # Both fields invalid
