        assert len(errors) == 2
        messages = [e["msg"] for e in errors]
        assert "Email invalid" in messages
        assert "Password too short" in messages

    def test_combined_field_and_model_errors(self):
        """Test collection of both field and model validation errors."""
        class PasswordSerializer(Serializer):
            email: str
            password: str
            confirm: str
            @validate_field("email")
            def validate_email(cls, val):
                if "@" not in val:
                    raise ValueError("Email invalid")
                return val
            @validate_model
            def verify_passwords(self):
                if self.password != self.confirm:
                    raise ValueError("Passwords mismatch")
                return self
        # Multiple issues
        with pytest.raises(RequestValidationError) as err_ctx:
            PasswordSerializer(email="bad", password="REDACTED_CREDENTIAL", confirm="other")
        errors = err_ctx.value.errors()
        assert len(errors) == 2
        messages = [e["msg"] for e in errors]
        assert "Email invalid" in messages
