# Alternative implementation of time parsing and range resolution

from datetime import datetime, date, timedelta
from typing import Optional, Tuple
import re

def parse_time_input(input_str: str) -> datetime:
    """
    Parse natural language time input into datetime.

    Supports:
    - "9am", "2pm" -> today at that hour
    - "yesterday" -> yesterday at 00:00
    - "last week" -> 7 days ago at 00:00
    - ISO timestamps: "2026-02-06 09:00", "2026-02-06T09:00:00"
    - Relative: "1h ago", "2d ago"
    """
    cleaned_input = input_str.strip().lower()

    # Handle "Xam" / "Xpm" (e.g., "9am", "2pm")
    time_match = re.match(r'^(\d{1,2})(am|pm)$', cleaned_input)
    if time_match:
        hour_value = int(time_match.group(1))
        period = time_match.group(2)

        if period == 'pm' and hour_value != 12:
            hour_value += 12
        elif period == 'am' and hour_value == 12:
            hour_value = 0

        base_date = date.today()
        return datetime(year=base_date.year, month=base_date.month, day=base_date.day, hour=hour_value)

    # Handle "yesterday"
    if cleaned_input == 'yesterday':
        yesterday_date = date.today() - timedelta(days=1)
        return datetime.combine(yesterday_date, datetime.min.time())

    # Handle "last week"
    if cleaned_input == 'last_week' or cleaned_input == 'last week':
        week_ago_date = date.today() - timedelta(days=7)
        return datetime.combine(week_ago_date, datetime.min.time())

    # Handle "Xh ago", "Xd ago", "Xm ago"
    relative_match = re.match(r'^(\d+)(h|d|m)\s*ago$', cleaned_input)
    if relative_match:
        quantity = int(relative_match.group(1))
        unit = relative_match.group(2)
        current_time = datetime.now()

        if unit == 'h':
            return current_time - timedelta(hours=quantity)
        elif unit == 'd':
            return current_time - timedelta(days=quantity)
        elif unit == 'm':
            return current_time - timedelta(minutes=quantity)

    # Try ISO format parsing
    try:
        # Handle formats with space or T separator
        if 'T' in cleaned_input or ' ' in cleaned_input:
            return datetime.fromisoformat(cleaned_input)
        # Handle date-only format (assume midnight)
        parsed_date = date.fromisoformat(cleaned_input)
        return datetime.combine(parsed_date, datetime.min.time())
    except ValueError:
        pass

    raise ValueError(f"Could not parse time input: '{input_str}'")

def resolve_time_range(
    period: Optional[str] = None,
    since: Optional[str] = None,
    after: Optional[str] = None,
    between: Optional[Tuple[str, str]] = None,
) -> Tuple[Optional[datetime], Optional[datetime]]:
    """
    Resolve time range from CLI arguments.

    Returns (start, end) datetimes.
    Priority: between > since/after > period
    """
    # Handle --between start end
    if between is not None:
        start_str, end_str = between
        start_time = parse_time_input(start_str)
        end_time = parse_time_input(end_str)
        return (start_time, end_time)

    # Handle --since / --after (alias)
    time_input = since or after
    if time_input:
        start_time = parse_time_input(time_input)
        return (start_time, None)  # No end limit

    # Handle --period (legacy, default behavior)
    if period:
        now = datetime.now()
        if period == 'day':
            start_date = date.today()
            start_time = datetime.combine(start_date, datetime.min.time())
        elif period == 'week':
            start_date = date.today() - timedelta(days=7)
            start_time = datetime.combine(start_date, datetime.min.time())
        elif period == 'month':
            start_date = date.today() - timedelta(days=30)
            start_time = datetime.combine(start_date, datetime.min.time())
        else:
            raise ValueError(f"Unknown period: {period}")
        return (start_time, None)

    # Default: today
    today_start = datetime.combine(date.today(), datetime.min.time())
    return (today_start, None)

# Custom type encoding/decoding utilities for BSON processing

import abc
import datetime
import warnings
from collections import namedtuple
from collections.abc import MutableMapping as _MutableMapping
from .binary import (
    ALL_UUID_REPRESENTATIONS,
    UUID_REPRESENTATION_NAMES,
    UuidRepresentation,
)

def _make_abstract_property(func):
    """Create a property that enforces abstract method implementation."""
    return property(abc.abstractmethod(func))

_RAW_BSON_DOCUMENT_MARKER = 101

def _is_raw_bson_class(cls):
    """Check if a class is a RawBSONDocument or subclass."""
    return getattr(cls, "_type_marker", None) == _RAW_BSON_DOCUMENT_MARKER

class BaseEncoder(abc.ABC):
    """Abstract base class for encoders that convert Python types to BSON-compatible formats.

    Subclasses must implement:
    - python_type: the type this encoder handles
    - encode_value: method to transform the value
    """

    @_make_abstract_property
    def python_type(self):
        """Return the Python type this encoder handles."""
        raise NotImplementedError

    @abc.abstractmethod
    def encode_value(self, obj):
        """Convert a Python object to a BSON-serializable format."""
        raise NotImplementedError

class BaseDecoder(abc.ABC):
    """Abstract base class for decoders that convert BSON types to custom Python types.

    Subclasses must implement:
    - bson_type: the BSON type this decoder handles
    - decode_value: method to transform the BSON value
    """

    @_make_abstract_property
    def bson_type(self):
        """Return the BSON type this decoder handles."""
        raise NotImplementedError

    @abc.abstractmethod
    def decode_value(self, value):
        """Convert a BSON value to a custom Python type."""
        raise NotImplementedError

class TypeConverter(BaseEncoder, BaseDecoder):
    """Base class for bidirectional type converters between Python and BSON types.

    Implement both encode_value and decode_value methods.
    """
    pass

class TypeRegistry(object):
    """Manages custom type codecs for BSON serialization/deserialization.

    Once created, the registry cannot be modified. Multiple codecs for the same
    type are resolved by last-wins policy.

    :Parameters:
      - `codecs`: optional list of codec instances
      - `encoder_fallback`: optional callable for handling unencodable types
    """

    def __init__(self, codecs=None, encoder_fallback=None):
        self._codecs = list(codecs or [])
        self._fallback_encoder = encoder_fallback
        self._encoding_map = {}
        self._decoding_map = {}

        # Validate fallback encoder if provided
        if self._fallback_encoder is not None:
            if not callable(encoder_fallback):
                raise TypeError("fallback_encoder %r is not callable" % (encoder_fallback,))

        # Process each codec
        for codec in self._codecs:
            registered = False

            # Register encoder if applicable
            if isinstance(codec, BaseEncoder):
                self._check_builtin_encoding(codec)
                registered = True
                self._encoding_map[codec.python_type] = codec.encode_value

            # Register decoder if applicable
            if isinstance(codec, BaseDecoder):
                registered = True
                self._decoding_map[codec.bson_type] = codec.decode_value

            if not registered:
                raise TypeError(
                    "Expected an instance of %s, %s, or %s, got %r instead"
                    % (BaseEncoder.__name__, BaseDecoder.__name__, TypeConverter.__name__, codec)
                )

    def _check_builtin_encoding(self, codec):
        """Ensure custom encoders don't override built-in type handling."""
        from . import _BUILT_IN_TYPES
        for builtin_type in _BUILT_IN_TYPES:
            if issubclass(codec.python_type, builtin_type):
                raise TypeError(
                    "Custom encoders cannot modify built-in type behavior "
                    "(encoder %s affects type %s)" % (codec, builtin_type)
                )

    def __repr__(self):
        return "%s(codecs=%r, encoder_fallback=%r)" % (
            self.__class__.__name__,
            self._codecs,
            self._fallback_encoder,
        )

    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return NotImplemented
        return (
            (self._decoding_map == other._decoding_map) and
            (self._encoding_map == other._encoding_map) and
            (self._fallback_encoder == other._fallback_encoder)
        )

# Named tuple for codec options configuration
_options_base = namedtuple(
    "CodecOptions",
    (
        "document_class",
        "timezone_aware",
        "uuid_format",
        "unicode_error_policy",
        "timezone_info",
        "type_registry",
    ),
)

class CodecOptions(_options_base):
    """Configuration for BSON encoding/decoding behavior.

    Example usage:
        >>> from .codec_options import CodecOptions
        >>> options = CodecOptions(document_class=dict, tz_aware=True)

    :Parameters:
      - `document_class`: Class for BSON document representation
      - `timezone_aware`: Whether datetime objects should include timezone info
      - `uuid_format`: How UUIDs should be represented in BSON
      - `unicode_error_policy`: Error handling for Unicode decoding issues
      - `timezone_info`: Specific timezone for datetime conversions
      - `type_registry`: Custom type handling registry
    """

    def __new__(
        cls,
        document_class=dict,
        timezone_aware=False,
        uuid_format=UuidRepresentation.UNSPECIFIED,
        unicode_error_policy="strict",
        timezone_info=None,
        type_registry=None,
    ):
        # Validate document_class
        if not (issubclass(document_class, _MutableMapping) or _is_raw_bson_class(document_class)):
            raise TypeError(
                "document_class must be dict, bson.son.SON, "
                "bson.raw_bson.RawBSONDocument, or a "
                "sublass of collections.abc.MutableMapping"
            )

        # Validate timezone_aware flag
        if not isinstance(timezone_aware, bool):
            raise TypeError("timezone_aware must be True or False")

        # Validate UUID format
        if uuid_format not in ALL_UUID_REPRESENTATIONS:
            raise ValueError(
                "uuid_format must be a value " "from .binary.UuidRepresentation"
            )

        # Validate unicode error policy
        if not isinstance(unicode_error_policy, (str, type(None))):
            raise ValueError("unicode_error_policy must be a string " "or None")

        # Validate timezone info
        if timezone_info is not None:
            if not isinstance(timezone_info, datetime.tzinfo):
                raise TypeError("timezone_info must be an instance of datetime.tzinfo")
            if not timezone_aware:
                raise ValueError("cannot specify timezone_info without also setting timezone_aware=True")

        # Ensure type registry exists
        type_registry = type_registry or TypeRegistry()
        if not isinstance(type_registry, TypeRegistry):
            raise TypeError("type_registry must be an instance of TypeRegistry")

        # Create the named tuple instance
        return tuple.__new__(
            cls,
            (
                document_class,
                timezone_aware,
                uuid_format,
                unicode_error_policy,
                timezone_info,
                type_registry,
            ),
        )

    def _describe_arguments(self):
        """Return string representation of constructor arguments."""
        doc_class_str = "dict" if self.document_class is dict else repr(self.document_class)
        uuid_repr_str = UUID_REPRESENTATION_NAMES.get(
            self.uuid_format, self.uuid_format
        )
        return (
            "document_class=%s, timezone_aware=%r, uuid_format=%s, "
            "unicode_error_policy=%r, timezone_info=%r, "
            "type_registry=%r"
            % (
                doc_class_str,
                self.timezone_aware,
                uuid_repr_str,
                self.unicode_error_policy,
                self.timezone_info,
                self.type_registry,
            )
        )

    def _as_configuration_dict(self):
        """Return configuration as dictionary."""
        return {
            "document_class": self.document_class,
            "tz_aware": self.timezone_aware,
            "uuid_representation": self.uuid_format,
            "unicode_decode_error_handler": self.unicode_error_policy,
            "tzinfo": self.timezone_info,
            "type_registry": self.type_registry,
        }

    def __repr__(self):
        return "%s(%s)" % (self.__class__.__name__, self._describe_arguments())

    def with_options(self, **kwargs):
        """Create a new CodecOptions instance with selected options changed."""
        config = self._as_configuration_dict()
        config.update(kwargs)
        return CodecOptions(**config)

DEFAULT_CODEC_OPTIONS = CodecOptions()

def _extract_codec_options(options_dict):
    """Extract codec options from a dictionary, normalizing key names."""
    kwargs = {}
    normalized_keys = {
        "uuidrepresentation": "uuid_representation",
    }

    for key in set(options_dict) & {
        "document_class",
        "tz_aware",
        "uuidrepresentation",
        "unicode_decode_error_handler",
        "tzinfo",
        "type_registry",
    }:
        target_key = normalized_keys.get(key, key)
        kwargs[target_key] = options_dict[key]

    return CodecOptions(**kwargs)

import base64
import dataclasses
import datetime as dt
from enum import Enum
from pathlib import PurePath
from types import GeneratorType
from typing import Any, Callable, Dict, List, Optional, Set, Union
import pydantic
from .datetime_utils import serialize_datetime
from .pydantic_utilities import (
    IS_PYDANTIC_V2,
    encode_by_type,
    to_jsonable_with_fallback,
)

# Type aliases for clarity
SetIntStr = Set[Union[int, str]]
DictIntStrAny = Dict[Union[int, str], Any]

def jsonable_encoder(obj: Any, custom_encoder: Optional[Dict[Any, Callable[[Any], Any]]] = None) -> Any:
    # Initialize custom encoder if not provided
    encoder_map = custom_encoder or {}

    # Handle Ellipsis sentinel value (used for "OMIT" in generated SDKs)
    if obj is Ellipsis:
        return None

    # Check custom encoders first
    if encoder_map:
        # Direct type match first
        if type(obj) in encoder_map:
            return encoder_map[type(obj)](obj)

        # Then check isinstance for inheritance cases
        for encoder_type, encoder_func in encoder_map.items():
            if isinstance(obj, encoder_type):
                return encoder_func(obj)

    # Handle Pydantic models
    if isinstance(obj, pydantic.BaseModel):
        if IS_PYDANTIC_V2:
            # Pydantic v2 configuration
            model_encoders = getattr(obj.model_config, "json_encoders", {})  # type: ignore
        else:
            # Pydantic v1 configuration
            model_encoders = getattr(obj.__config__, "json_encoders", {})  # type: ignore

        # Merge with custom encoders if present
        if encoder_map:
            model_encoders.update(encoder_map)

        # Convert model to dictionary
        obj_dict = obj.dict(by_alias=True)

        # Handle special root fields
        if "__root__" in obj_dict:
            obj_dict = obj_dict["__root__"]
        elif "root" in obj_dict:
            obj_dict = obj_dict["root"]

        return jsonable_encoder(obj_dict, custom_encoder=model_encoders)

    # Handle dataclasses
    if dataclasses.is_dataclass(obj):
        obj_dict = dataclasses.asdict(obj)  # type: ignore
        return jsonable_encoder(obj_dict, custom_encoder=encoder_map)

    # Handle bytes (base64 encoding)
    if isinstance(obj, bytes):
        return base64.b64encode(obj).decode("utf-8")

    # Handle enums
    if isinstance(obj, Enum):
        return obj.value

    # Handle pathlib paths
    if isinstance(obj, PurePath):
        return str(obj)

    # Handle primitive types
    if isinstance(obj, (str, int, float, type(None))):
        return obj

    # Handle datetime objects
    if isinstance(obj, dt.datetime):
        return serialize_datetime(obj)

    # Handle date objects
    if isinstance(obj, dt.date):
        return str(obj)

    # Handle dictionaries
    if isinstance(obj, dict):
        encoded_dict = {}
        allowed_keys = set(obj.keys())

        for key, value in obj.items():
            if key in allowed_keys and value is not Ellipsis:
                encoded_key = jsonable_encoder(key, custom_encoder=encoder_map)
                encoded_value = jsonable_encoder(value, custom_encoder=encoder_map)
                encoded_dict[encoded_key] = encoded_value

        return encoded_dict

    # Handle collections (list, set, frozenset, generators, tuples)
    if isinstance(obj, (list, set, frozenset, GeneratorType, tuple)):
        encoded_list = []

        for item in obj:
            if item is not Ellipsis:
                encoded_list.append(jsonable_encoder(item, custom_encoder=encoder_map))

        return encoded_list

    # Fallback serializer for complex objects
    def default_serializer(o: Any) -> Any:
        # Try specialized encoding first
        encoded_result = encode_by_type(o)
        if encoded_result is not None:
            return encoded_result

        # Try converting to dict via dict() constructor
        try:
            data = dict(o)
        except Exception as e1:
            try:
                # Fall back to instance attributes
                data = vars(o)
            except Exception as e2:
                raise ValueError([e1, e2]) from None

        return jsonable_encoder(data, custom_encoder=encoder_map)

    return to_jsonable_with_fallback(obj, default_serializer)

import json
import sys
import ipaddress
import subprocess

def check_ipv4_format(addr):
    try:
        ipaddress.IPv4Address(addr)
        return True
    except (ipaddress.AddressValueError, ValueError):
        return False

def validate_cidr_notation(cidr_str):
    try:
        ipaddress.IPv4Network(cidr_str, strict=False)
        return True
    except (ipaddress.NetmaskValueError, ipaddress.AddressValueError, ValueError):
        return False

def perform_network_scan(target_hosts, port_spec, quick_mode=False, aggressive=False, 
                         host_timeout=30, num_top_ports=None, max_hosts=None, 
                         excluded_ips=None):
    try:
        import nmap
        nm = nmap.PortScanner()
    except ImportError:
        return {"error": "nmap library not available. Please install python-nmap."}

    nmap_args = '-sV'
    if aggressive:
        nmap_args += ' -T4'
    if host_timeout:
        nmap_args += f' --host-timeout {host_timeout}s'
    if num_top_ports:
        nmap_args += f' --top-ports {num_top_ports}'
    if max_hosts:
        nmap_args += f' -n --max-hosts {max_hosts}'
    if excluded_ips:
        nmap_args += f' --exclude {excluded_ips}'

    try:
        if check_ipv4_format(target_hosts):
            scan_result = nm.scan(target_hosts, port_spec, arguments=nmap_args)
        elif validate_cidr_notation(target_hosts):
            if num_top_ports is None:
                nmap_args += ' --top-ports 10'  # default for CIDR scans
            scan_result = nm.scan(target_hosts, port_spec, arguments=nmap_args)
        elif '-' in target_hosts and target_hosts.count('-') == 1:
            start_ip, end_ip = target_hosts.split('-')
            ip_range = f"{start_ip}-{end_ip}"
            scan_result = nm.scan(ip_range, port_spec, arguments=nmap_args)
        elif ',' in target_hosts:
            scan_result = nm.scan(target_hosts, port_spec, arguments=nmap_args)
        else:
            return {"error": "Unsupported target format. Acceptable formats: single IP, CIDR, IP range (start-end), or comma-separated IPs."}
    except Exception as exc:
        return {"error": str(exc)}

    extracted_data = {}
    if 'scan' in scan_result:
        for host_addr, details in scan_result['scan'].items():
            extracted_data[host_addr] = {}
            if 'tcp' in details:
                extracted_data[host_addr]['tcp'] = details['tcp']

    return {
        "scan_results": extracted_data,
        "nmap_command": nm.command_line(),
        "scan_info": nm.scaninfo()
    }

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(json.dumps({
            "error": "Missing arguments. Usage: network-scan target=<target> ports=<ports> [--quick] [--fast] [--timeout <seconds>] [--top-ports <num>] [--hosts-limit <num>] [--exclude <ip>]"
        }, indent=4))
        sys.exit(1)

    target = None
    ports = None
    quick = False
    fast = False
    timeout_val = 30
    top_port_count = None
    host_limit = None
    exclude_list = None

    try:
        for arg in sys.argv[1:]:
            if arg.startswith("target="):
                target = arg.split("=", 1)[1]
            elif arg.startswith("ports="):
                ports = arg.split("=", 1)[1]
            elif arg == "--quick":
                quick = True
            elif arg == "--fast":
                fast = True
            elif arg.startswith("--timeout="):
                timeout_val = int(arg.split("=", 1)[1])
            elif arg.startswith("--top-ports="):
                top_port_count = int(arg.split("=", 1)[1])
            elif arg.startswith("--hosts-limit="):
                host_limit = int(arg.split("=", 1)[1])
            elif arg.startswith("--exclude="):
                exclude_list = arg.split("=", 1)[1]
    except Exception as err:
        print(json.dumps({"error": f"Argument parsing failed: {str(err)}"}))
        sys.exit(1)

    if not target or not ports:
        print(json.dumps({"error": "Both target and ports are required parameters."}))
        sys.exit(1)

    output = perform_network_scan(
        target, ports, quick, fast, timeout_val, top_port_count, host_limit, exclude_list
    )
    print(json.dumps(output, indent=4))

# JSON compatibility layer: prioritizes orjson for performance, falls back to standard library
# Usage: import omega.json_compat as json
# Fallback trigger: set environment variable OMEGA_USE_STDLIB_JSON=1

import os
import json as _standard_json

# Determine whether to use orjson based on environment variable
_use_orjson = os.environ.get("OMEGA_USE_STDLIB_JSON") != "1"

# Attempt to import orjson; fall back gracefully if unavailable
_orjson_module = None
if _use_orjson:
    try:
        import orjson as _orjson_module
    except ImportError:
        _orjson_module = None
else:
    _orjson_module = None


def parse_json_string(json_str, **kwargs):
    """Parse JSON string using orjson when possible and no extra kwargs are provided."""
    if _orjson_module and not kwargs:
        # Ensure input is bytes-like for orjson
        data = json_str if isinstance(json_str, (bytes, bytearray, memoryview)) else json_str.encode()
        return _orjson_module.loads(data)
    return _standard_json.loads(json_str, **kwargs)


def serialize_to_json_string(obj, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    """Serialize object to JSON string, preferring orjson for compact output unless special formatting needed."""
    if indent is not None or _orjson_module is None:
        return _standard_json.dumps(
            obj, indent=indent, default=default, sort_keys=sort_keys, ensure_ascii=ensure_ascii, **kwargs
        )

    # Prepare orjson options
    options = 0
    if sort_keys:
        options |= _orjson_module.OPT_SORT_KEYS

    # Handle default serializer
    custom_default = default if callable(default) else (str if default == str else None)

    # Serialize with orjson and decode result
    result_bytes = _orjson_module.dumps(obj, default=custom_default, option=options or None)
    return result_bytes.decode()


def load_from_file_like_object(file_obj, **kwargs):
    """Read and parse JSON from a file-like object."""
    return parse_json_string(file_obj.read(), **kwargs)


def write_to_file_like_object(obj, file_obj, *, indent=None, default=None, sort_keys=False, ensure_ascii=True, **kwargs):
    """Serialize object to JSON and write to a file-like object."""
    json_str = serialize_to_json_string(
        obj, indent=indent, default=default, sort_keys=sort_keys, ensure_ascii=ensure_ascii, **kwargs
    )
    file_obj.write(json_str)

