def create_structure(
    root_path: Path,
    structure: Dict,
    simulate: bool = False
) -> List[str]:
    """Create directory structure recursively."""
    created_items = []
    for name, content in structure.items():
        current_path = root_path / name
        if isinstance(content, dict):
            # It's a directory
            if not simulate:
                current_path.mkdir(parents=True, exist_ok=True)
            created_items.extend(create_structure(current_path, content, simulate))
        else:
            # It's a file
            if not simulate:
                current_path.parent.mkdir(parents=True, exist_ok=True)
                file_content = FILE_CONTENTS.get(content, "")
                current_path.write_text(file_content)
            created_items.append(str(current_path))
    return created_items

def generate_config_files(
    project_path: Path,
    template_name: str,
    project_name: str,
    selected_features: List[str],
    simulate: bool = False
) -> List[str]:
    """Generate configuration files."""
    created_items = []
    config_templates = get_configuration_templates(project_name, template_name, selected_features)
    template_info = PROJECT_TEMPLATES[template_name]
    for config_file in template_info["config_files"]:
        file_path = project_path / config_file
        if config_file in config_templates:
            if not simulate:
                file_path.write_text(config_templates[config_file])
            created_items.append(str(file_path))
    return created_items

