def initialize_project(
    name: str,
    target_dir: Path,
    template: str = "nextjs",
    features: Optional[List[str]] = None,
    simulate: bool = False,
) -> Dict:
    """Initialize a complete frontend project."""
    features = features or []
    project_path = target_dir / name

    if project_path.exists() and not simulate:
        return {"error": f"Directory already exists: {project_path}"}

    template_info = PROJECT_TEMPLATES.get(template)
    if not template_info:
        return {"error": f"Unknown template: {template}"}

    created_items = []

    # Create project directory
    if not simulate:
        project_path.mkdir(parents=True, exist_ok=True)

    # Generate base structure
    created_items.extend(
        create_structure(project_path, template_info["layout"], simulate)
    )

    # Generate config files
    created_items.extend(
        generate_config_files(project_path, template, name, features, simulate)
    )

    # Add feature files
    for feature in features:
        if feature in FEATURE_MODULES:
            for file_path, content_key in FEATURE_MODULES[feature]["files"].items():
                full_path = project_path / file_path
                if not simulate:
                    full_path.parent.mkdir(parents=True, exist_ok=True)
                    content = FILE_CONTENTS.get(content_key, f"// TODO: Implement {content_key}")
                    full_path.write_text(content)
                created_items.append(str(full_path))

    return {
        "name": name,
        "template": template,
        "template_title": template_info["title"],
        "features": features,
        "path": str(project_path),
        "items_created": len(created_items),
        "items": created_items,
        "subsequent_steps": [
            f"cd {name}",
            "npm install",
            "npm run dev",
        ],
    }

def display_result(result: Dict) -> None:
    """Display scaffolding result."""
    if "error" in result:
        print(f"Error: {result['error']}", file=sys.stderr)
        return

    print(f"\n{'='*60}")
    print(f"Project Initialized: {result['name']}")
    print(f"{'='*60}")
    print(f"Template: {result['template_title']}")
    print(f"Location: {result['path']}")
    print(f"Files Created: {result['items_created']}")
    if result["features"]:
        print(f"Features: {', '.join(result['features'])}")
    print(f"\nNext Steps:")
    for step in result["subsequent_steps"]:
        print(f"  $ {step}")
    print(f"{'='*60}\n")

def main():
    parser = argparse.ArgumentParser(
        description="Initialize a frontend project with best practices"
    )
    parser.add_argument(
        "name",
        help="Project name (kebab-case recommended)"
    )
    parser.add_argument(
        "--dir", "-d",
        default=".",
        help="Output directory (default: current directory)"
    )
    parser.add_argument(
        "--template", "-t",
        choices=list(PROJECT_TEMPLATES.keys()),
        default="nextjs",
        help="Project template (default: nextjs)"
    )
    parser.add_argument(
        "--features", "-f",
        help="Comma-separated features to add (auth,api,forms,testing,storybook)"
    )
    parser.add_argument(
        "--list-templates",
        action="store_true",
        help="List available templates"
    )
    parser.add_argument(
        "--list-features",
        action="store_true",
        help="List available features"
    )
    parser.add_argument(
        "--simulate",
        action="store_true",
        help="Show what would be created without creating files"
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Output in JSON format"
    )
    args = parser.parse_args()

    if args.list_templates:
        print("\nAvailable Templates:")
        for key, template in PROJECT_TEMPLATES.items():
            print(f"  {key}: {template['title']}")
            print(f"    {template['info']}")
        return

    if args.list_features:
        print("\nAvailable Features:")
        for key, feature in FEATURE_MODULES.items():
            print(f"  {key}: {feature['description']}")
            pkgs = ", ".join(feature.get("packages", []))
            if pkgs:
                print(f"    Adds: {pkgs}")
        return

    features = []
    if args.features:
        features = [f.strip() for f in args.features.split(",")]
        invalid = [f for f in features if f not in FEATURE_MODULES]
        if invalid:
            print(f"Unknown features: {', '.join(invalid)}", file=sys.stderr)
            print(f"Valid features: {', '.join(FEATURE_MODULES.keys())}")
            sys.exit(1)

    result = initialize_project(
        name=args.name,
        target_dir=Path(args.dir),
        template=args.template,
        features=features,
        simulate=args.simulate,
    )

    if args.json:
        print(json.dumps(result, indent=2))
    else:
        display_result(result)

if __name__ == "__main__":
    main()

from typing import Any, Dict, Optional, Tuple
from loguru import logger
from pydantic import ValidationError
from pydantic.type_adapter import TypeAdapter
from .protocol import PROTOCOL_VERSION, RpcEnvelope

# Pre-compile the validator for RpcEnvelope
_RPC_ENVELOPE_VALIDATOR = TypeAdapter(RpcEnvelope)

def check_rpc_message(
    message: Any,
    *,
    validation_mode: str = "off",
) -> Tuple[Optional[RpcEnvelope], Optional[str]]:
    """
    Validate an RPC envelope with configurable strictness.

    Returns:
        A tuple of (validated envelope or None, error message or None)
    """
    # Skip validation if explicitly disabled
    if validation_mode == "off":
        return None, None

    # Handle legacy clients in warn mode by injecting protocol version if missing
    if validation_mode == "warn" and isinstance(message, dict) and "v" not in message:
        try:
            message = {**message, "v": PROTOCOL_VERSION}
        except Exception:
            # If injection fails, continue with original data
            pass

    # Attempt to validate the message
    try:
        envelope = _RPC_ENVELOPE_VALIDATOR.validate_python(message)
    except ValidationError as err:
        if validation_mode == "warn":
            logger.warning("malformed rpc envelope: {}", err)
        return None, "malformed rpc envelope"

    # Check protocol version compatibility
    if envelope.v is not None and envelope.v != PROTOCOL_VERSION:
        return None, f"unsupported protocol version: {envelope.v!r}"

    # Enforce protocol version presence in strict mode
    if validation_mode == "strict":
        if envelope.v is None:
            return None, "missing protocol version"

    return envelope, None

from graph_net.sample_pass.resumable_sample_pass_mixin import ResumableSamplePassMixin
from pathlib import Path
import json
from itertools import groupby
from dataclasses import dataclass

class FusibleSubgraphRangesGenerator(SamplePass, ResumableSamplePassMixin):
    def __init__(self, config):
        super().__init__(config)

    def configure(
        self,
        model_directory: str,
        result_directory: str,
        source_json_filename: str,
        continue_processing: bool = False,
        max_models_to_process: int = None,
        result_json_filename: str = "fusible_subgraph_ranges.json",
    ):
        pass

    def execute(self, relative_model_path: str):
        self.process_with_resume_capability(relative_model_path)

    def was_processed(self, relative_model_path: str) -> bool:
        target_file = self.config["result_json_filename"]
        return self.check_if_already_processed(relative_model_path, filename=target_file)

    def resume_processing(self, relative_model_path: str):
        processor = self._create_processor(relative_model_path)
        result_data = {
            "subgraph_ranges": processor.perform_analysis(),
        }
        self._write_results(relative_model_path, result_data)

    def _write_results(self, relative_model_path, results):
        json_content = json.dumps(results, indent=4)
        destination_dir = Path(self.config["result_directory"]) / relative_model_path
        destination_dir.mkdir(parents=True, exist_ok=True)
        output_file = destination_dir / self.config["result_json_filename"]
        output_file.write_text(json_content)

    def _create_processor(self, relative_model_path: str):
        model_file = (
            Path(self.config["model_directory"])
            / relative_model_path
            / self.config["source_json_filename"]
        )
        context_data = self._prepare_context(model_file)
        return FusibleSubgraphRangesProcessor(
            kernel_counts=self._extract_kernel_counts(context_data),
            op_counts=self._extract_op_counts(context_data),
            original_graph_offset=self._extract_original_graph_offset(context_data),
        )

    def _extract_original_graph_offset(self, context_data):
        return context_data["start_offset_in_original_graph"]

    def _extract_kernel_counts(self, context_data):
        return context_data["num_subgraph_kernels"]

    def _extract_op_counts(self, context_data):
        return context_data["num_subgraph_ops"]

    def _prepare_context(self, model_file: Path):
        raw_data = json.loads(model_file.read_text())
        assert len(raw_data["num_subgraph_kernels"]) == len(raw_data["num_subgraph_ops"])
        return raw_data

class FusibleSubgraphRangesProcessor:
    def __init__(
        self,
        kernel_counts: list[int],
        op_counts: list[int],
        original_graph_offset: int,
    ):
        assert len(kernel_counts) == len(op_counts)
        self.kernel_counts = kernel_counts
        self.op_counts = op_counts
        self.original_graph_offset = original_graph_offset

    def perform_analysis(self):
        processing_state = self._setup_processing_state()
        kernel_and_op_combinations = processing_state.kernel_and_op_combinations

        # Initial candidate groups based on varying op counts
        initial_candidates = [
            sorted(set(op_list))
            for _, op_list in kernel_and_op_combinations
            if len(set(op_list)) > 1
        ]

        refined_candidates = self._consolidate_reducing_op_lists(
            processing_state, initial_candidates
        )

        return self._generate_fusible_ranges(
            processing_state,
            refined_candidates,
        )

    def _consolidate_reducing_op_lists(self, processing_state, candidate_lists):
        iteration_counter = 0
        max_iterations = 99999
        while True:
            previous_count = len(candidate_lists)
            candidate_lists = self._single_consolidation_step(
                processing_state, candidate_lists
            )
            assert previous_count >= len(candidate_lists)
            if previous_count == len(candidate_lists):
                break
            iteration_counter += 1
            assert iteration_counter < max_iterations, f"{iteration_counter=}"
        return candidate_lists

    def _single_consolidation_step(self, processing_state, candidate_lists):
        merge_index = self._find_consolidatable_position(
            processing_state, candidate_lists
        )
        if merge_index is None:
            return candidate_lists
        assert merge_index >= 0
        assert merge_index < len(candidate_lists) - 1
        return [
            *candidate_lists[:merge_index],
            [*candidate_lists[merge_index], *candidate_lists[merge_index + 1]],
            *candidate_lists[merge_index + 2 :],
        ]

    def _find_consolidatable_position(self, processing_state, candidate_lists):
        def get_current_tail_kernels(i):
            return processing_state.get_kernels_for_ops(candidate_lists[i][-1])

        def get_next_head_kernels(i):
            return processing_state.get_kernels_for_ops(candidate_lists[i + 1][0])

        for i in range(len(candidate_lists) - 1):
            assert len(candidate_lists[i]) > 1
            if get_current_tail_kernels(i) >= get_next_head_kernels(i):
                return i
        return None

    def _generate_fusible_ranges(self, processing_state, candidate_lists):
        def is_contiguous_sequence(int_list):
            assert len(int_list) > 1
            return (int_list[-1] + 1) - int_list[0] == len(int_list)

        def contains_any_increase(op_list: list[int]):
            for idx, current_ops in enumerate(op_list):
                if idx == 0:
                    continue
                current_kernels = processing_state.get_kernels_for_ops(current_ops)
                previous_kernels = processing_state.get_kernels_for_ops(op_list[idx - 1])
                if current_kernels > previous_kernels:
                    return True
            return False

        def kernels_match_end(op_list: list[int]):
            return processing_state.get_kernels_for_ops(
                op_list[0]
            ) == processing_state.get_kernels_for_ops(op_list[-1])

        def kernels_exceed_end(op_list: list[int]):
            return processing_state.get_kernels_for_ops(
                op_list[0]
            ) > processing_state.get_kernels_for_ops(op_list[-1])

        def qualifies_as_fusable(op_list: list[int]):
            if kernels_exceed_end(op_list):
                return True
            if kernels_match_end(op_list):
                return not contains_any_increase(op_list)
            return False

        candidate_lists = [
            sorted(set(op_list)) for op_list in candidate_lists
        ]

        valid_sequences = [
            op_list
            for op_list in candidate_lists
            if len(op_list) > 1
            if is_contiguous_sequence(op_list)
            if qualifies_as_fusable(op_list)
        ]

        offset = self.original_graph_offset
        fusible_ranges = [
            (begin, finish)
            for op_list in valid_sequences
            for begin in [op_list[0] - 1 + offset]
            for finish in [op_list[-1] + offset]
        ]

        def sort_ranges(pair):
            start, end = pair
            return (start, -end)

        fusible_ranges = sorted(fusible_ranges, key=sort_ranges)

        # Remove overlapping/shadowed ranges
        final_ranges = [
            fusible_ranges[i]
            for i in range(len(fusible_ranges))
            if i == 0
            or (fusible_ranges[i][0] >= fusible_ranges[i - 1][1])
        ]

        return final_ranges

    def _setup_processing_state(self):
        return ProcessingState(
            kernel_and_op_combinations=self._organize_by_kernel_counts(),
            op_to_kernel_mapping=self._build_op_to_kernel_map(),
        )

    def _build_op_to_kernel_map(self):
        return dict(zip(self.op_counts, self.kernel_counts))

    def _organize_by_kernel_counts(self):
        combined = zip(self.kernel_counts, self.op_counts)

        def extract_ops(item):
            return item[1]

        def extract_kernels(item):
            return item[0]

        sorted_combined = sorted(combined, key=extract_ops)
        grouped = groupby(sorted_combined, key=extract_kernels)

        organized = [
            (kernels, [ops for _, ops in group])
            for kernels, group in grouped
        ]

        return organized

@dataclass
class ProcessingState:
    kernel_and_op_combinations: list[(int, list[int])]
    op_to_kernel_mapping: dict[int, int]

    def get_kernels_for_ops(self, num_ops: int):
        return self.op_to_kernel_mapping[num_ops]

# Catch-up session analyzer for Claude-style project sessions
# Identifies unsynced conversation context after last planning file update

import json
import sys
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from datetime import datetime

PLANNING_FILES = ['task_plan.md', 'progress.md', 'findings.md']

def get_project_dir(project_path: str) -> Path:
    """Convert project path to storage path format."""
    sanitized = project_path.replace('/', '-')
    if not sanitized.startswith('-'):
        sanitized = '-' + sanitized
    sanitized = sanitized.replace('_', '-')
    return Path.home() / '.claude' / 'projects' / sanitized

def get_sessions_sorted(project_dir: Path) -> List[Path]:
    """Get all session files sorted by modification time (newest first)."""
    sessions = list(project_dir.glob('*.jsonl'))
    main_sessions = [s for s in sessions if not s.name.startswith('agent-')]
    return sorted(main_sessions, key=lambda p: p.stat().st_mtime, reverse=True)

def parse_session_messages(session_file: Path) -> List[Dict]:
    """Parse all messages from a session file, preserving order."""
    messages = []
    with open(session_file, 'r') as f:
        for line_num, line in enumerate(f):
            try:
                data = json.loads(line)
                data['_line_num'] = line_num
                messages.append(data)
            except json.JSONDecodeError:
                pass
    return messages

def find_last_planning_update(messages: List[Dict]) -> Tuple[int, Optional[str]]:
    """
    Find the last time a planning file was written/edited.
    Returns (line_number, filename) or (-1, None) if not found.
    """
    last_update_line = -1
    last_update_file = None
    for msg in messages:
        msg_type = msg.get('type')
        if msg_type == 'assistant':
            content = msg.get('message', {}).get('content', [])
            if isinstance(content, list):
                for item in content:
                    if item.get('type') == 'tool_use':
                        tool_name = item.get('name', '')
                        tool_input = item.get('input', {})
                        if tool_name in ('Write', 'Edit'):
                            file_path = tool_input.get('file_path', '')
                            for pf in PLANNING_FILES:
                                if file_path.endswith(pf):
                                    last_update_line = msg['_line_num']
                                    last_update_file = pf
    return last_update_line, last_update_file

def extract_relevant_messages(messages: List[Dict], cutoff_line: int) -> List[Dict]:
    """Extract conversation messages after a certain line number."""
    result = []
    for msg in messages:
        if msg['_line_num'] <= cutoff_line:
            continue
        msg_type = msg.get('type')
        is_meta = msg.get('isMeta', False)

        # Process user messages
        if msg_type == 'user' and not is_meta:
            content = msg.get('message', {}).get('content', '')
            if isinstance(content, list):
                for item in content:
                    if isinstance(item, dict) and item.get('type') == 'text':
                        content = item.get('text', '')
                        break
                else:
                    content = ''
            if content and isinstance(content, str):
                if content.startswith(('<local-command', '<command-', '<task-notification')):
                    continue
                if len(content) > 20:
                    result.append({'role': 'user', 'content': content, 'line': msg['_line_num']})

        # Process assistant messages
        elif msg_type == 'assistant':
            msg_content = msg.get('message', {}).get('content', '')
            text_content = ''
            tool_uses = []

            if isinstance(msg_content, str):
                text_content = msg_content
            elif isinstance(msg_content, list):
                for item in msg_content:
                    if item.get('type') == 'text':
                        text_content = item.get('text', '')
                    elif item.get('type') == 'tool_use':
                        tool_name = item.get('name', '')
                        tool_input = item.get('input', {})
                        if tool_name == 'Edit':
                            tool_uses.append(f"Edit: {tool_input.get('file_path', 'unknown')}")
                        elif tool_name == 'Write':
                            tool_uses.append(f"Write: {tool_input.get('file_path', 'unknown')}")
                        elif tool_name == 'Bash':
                            cmd = tool_input.get('command', '')[:80]
                            tool_uses.append(f"Bash: {cmd}")
                        else:
                            tool_uses.append(f"{tool_name}")

            if text_content or tool_uses:
                result.append({
                    'role': 'assistant',
                    'content': text_content[:600] if text_content else '',
                    'tools': tool_uses,
                    'line': msg['_line_num']
                })
    return result

def main():
    project_path = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    project_dir = get_project_dir(project_path)

    # Check if planning files exist (indicates active task)
    has_planning_files = any(
        Path(project_path, f).exists() for f in PLANNING_FILES
    )

    if not project_dir.exists():
        # No previous sessions, nothing to catch up on
        return

    sessions = get_sessions_sorted(project_dir)
    if len(sessions) < 1:
        return

    # Find a substantial previous session
    target_session = None
    for session in sessions:
        if session.stat().st_size > 5000:
            target_session = session
            break
    if not target_session:
        return

    messages = parse_session_messages(target_session)
    last_update_line, last_update_file = find_last_planning_update(messages)

    # Only output if there's unsynced content
    if last_update_line < 0:
        messages_after = extract_relevant_messages(messages, len(messages) - 30)
    else:
        messages_after = extract_relevant_messages(messages, last_update_line)

    if not messages_after:
        return

    # Output catchup report
    print("\n[planning-with-files] SESSION CATCHUP DETECTED")
    print(f"Previous session: {target_session.stem}")
    if last_update_line >= 0:
        print(f"Last planning update: {last_update_file} at message #{last_update_line}")
        print(f"Unsynced messages: {len(messages_after)}")
    else:
        print("No planning file updates found in previous session")

    print("\n--- UNSYNCED CONTEXT ---")
    for msg in messages_after[-15:]:  # Last 15 messages
        if msg['role'] == 'user':
            print(f"USER: {msg['content'][:300]}")
        else:
            if msg.get('content'):
                print(f"CLAUDE: {msg['content'][:300]}")
            if msg.get('tools'):
                print(f"  Tools: {', '.join(msg['tools'][:4])}")

    print("\n--- RECOMMENDED ---")
    print("1. Run: git diff --stat")
    print("2. Read: task_plan.md, progress.md, findings.md")
    print("3. Update planning files based on above context")
    print("4. Continue with task")

if __name__ == '__main__':
    main()

# Certificate Policy API - UCM (Revised Implementation)
# Handles certificate policies and approval workflows with alternative logic structures

from flask import Blueprint, request
from auth.unified import require_auth
from utils.response import success_response, error_response
from models import db
from models.policy import CertificatePolicy, ApprovalRequest
from datetime import datetime, timedelta
import json

bp = Blueprint('policies_pro', __name__)

# ============ Policy Management ============
@bp.route('/api/v2/policies', methods=['GET'])
@require_auth(['read:policies'])
def list_policies():
    """Retrieve all certificate policies sorted by priority"""
    policies = CertificatePolicy.query.order_by(CertificatePolicy.priority).all()
    return success_response(data=[policy.to_dict() for policy in policies])

@bp.route('/api/v2/policies/<int:policy_id>', methods=['GET'])
@require_auth(['read:policies'])
def get_policy(policy_id):
    """Fetch specific policy details"""
    policy = CertificatePolicy.query.get_or_404(policy_id)
    return success_response(data=policy.to_dict())

@bp.route('/api/v2/policies', methods=['POST'])
@require_auth(['write:policies'])
def create_policy():
    """Create new certificate policy with validation"""
    payload = request.get_json()

    # Validate required fields
    if not payload or 'name' not in payload or not payload['name']:
        return error_response("Policy name is required", 400)

    # Check uniqueness constraint
    if CertificatePolicy.query.filter_by(name=payload['name']).first():
        return error_response("Policy name already exists", 400)

    # Initialize policy object with default values
    policy = CertificatePolicy(
        name=payload['name'],
        description=payload.get('description'),
        policy_type=payload.get('policy_type', 'issuance'),
        ca_id=payload.get('ca_id'),
        template_id=payload.get('template_id'),
        requires_approval=bool(payload.get('requires_approval', False)),
        approval_group_id=payload.get('approval_group_id'),
        min_approvers=int(payload.get('min_approvers', 1)),
        notify_on_violation=bool(payload.get('notify_on_violation', True)),
        is_active=bool(payload.get('is_active', True)),
        priority=int(payload.get('priority', 100)),
        created_by=request.current_user.get('username') if hasattr(request, 'current_user') else None
    )

    # Process additional data fields
    if payload.get('rules'):
        policy.set_rules(payload['rules'])

    if payload.get('notification_emails'):
        policy.notification_emails = json.dumps(payload['notification_emails'])

    db.session.add(policy)
    db.session.commit()

    return success_response(data=policy.to_dict(), message="Policy created")

@bp.route('/api/v2/policies/<int:policy_id>', methods=['PUT'])
@require_auth(['write:policies'])
def update_policy(policy_id):
    """Update existing certificate policy"""
    policy = CertificatePolicy.query.get_or_404(policy_id)
    payload = request.get_json()

    # Update allowed fields with duplicate checking for name
    if 'name' in payload:
        existing = CertificatePolicy.query.filter_by(name=payload['name']).first()
        if existing and existing.id != policy_id:
            return error_response("Policy name already exists", 400)
        policy.name = payload['name']

    # Field updates using conditional assignment
    update_fields = {
        'description': payload.get('description'),
        'policy_type': payload.get('policy_type'),
        'ca_id': payload.get('ca_id'),
        'template_id': payload.get('template_id'),
        'requires_approval': payload.get('requires_approval'),
        'approval_group_id': payload.get('approval_group_id'),
        'min_approvers': payload.get('min_approvers'),
        'notify_on_violation': payload.get('notify_on_violation'),
        'is_active': payload.get('is_active'),
        'priority': payload.get('priority')
    }

    for field, value in update_fields.items():
        if value is not None:
            setattr(policy, field, value)

    # Handle special cases
    if 'rules' in payload:
        policy.set_rules(payload['rules'])

    if 'notification_emails' in payload:
        policy.notification_emails = json.dumps(payload['notification_emails'])

    db.session.commit()
    return success_response(data=policy.to_dict(), message="Policy updated")

@bp.route('/api/v2/policies/<int:policy_id>', methods=['DELETE'])
@require_auth(['delete:policies'])
def delete_policy(policy_id):
    """Delete certificate policy after checking dependencies"""
    policy = CertificatePolicy.query.get_or_404(policy_id)

    # Verify no pending approvals exist
    pending_count = ApprovalRequest.query.filter_by(
        policy_id=policy_id,
        status='pending'
    ).count()

    if pending_count > 0:
        return error_response(f"Cannot delete policy with {pending_count} pending approval requests", 400)

    db.session.delete(policy)
    db.session.commit()

    return success_response(message="Policy deleted")

@bp.route('/api/v2/policies/<int:policy_id>/toggle', methods=['POST'])
@require_auth(['write:policies'])
def toggle_policy(policy_id):
    """Enable/disable policy state"""
    policy = CertificatePolicy.query.get_or_404(policy_id)
    policy.is_active = not policy.is_active
    db.session.commit()

    status = "enabled" if policy.is_active else "disabled"
    return success_response(data=policy.to_dict(), message=f"Policy {status}")

