    """Extract LoRA parameters based on bias setting"""
    if bias_option == "none":
        return {k: t for k, t in named_params if "lora_" in k}
    elif bias_option == "all":
        return {k: t for k, t in named_params if "lora_" in k or "bias" in k}
    elif bias_option == "lora_only":
        lora_dict = {}
        potential_bias = {}
        bias_names_set = set()

        for k, t in named_params:
            if "lora_" in k:
                lora_dict[k] = t
                base_name = k.split("lora_")[0] + "bias"
                bias_names_set.add(base_name)
            elif "bias" in k:
                potential_bias[k] = t

        for k, t in potential_bias.items():
            if k in bias_names_set:
                lora_dict[k] = t
        return lora_dict
    else:
        raise ValueError(f"Invalid bias option: {bias_option}")

def extract_non_lora_state(named_params, require_grad_only=True):
    """Extract non-LoRA parameters"""
    result = {k: t for k, t in named_params if "lora_" not in k}
    if require_grad_only:
        result = {k: t for k, t in result.items() if t.requires_grad}
    return {k: zero_param(v, skip_check=True).cpu() for k, v in result.items()}

def extract_projector_state(named_params, target_keys):
    """Extract projector-related parameters"""
    result = {k: t for k, t in named_params if any(key_match in k for key_match in target_keys)}
    return {k: zero_param(v, skip_check=True).cpu() for k, v in result.items()}

def find_linear_modules(model):
    """Find all linear layers suitable for LoRA adaptation"""
    linear_class = torch.nn.Linear
    lora_modules = set()
    vision_keywords = ['mm_projector', 'vision_tower', 'vision_resampler']

    for name, module in model.named_modules():
        # Skip vision-related modules
        if any(vision_keyword in name for vision_keyword in vision_keywords):
            continue

        if isinstance(module, linear_class):
            parts = name.split('.')
            module_name = parts[0] if len(parts) == 1 else parts[-1]
            lora_modules.add(module_name)

    # Remove lm_head if present (needed for 16-bit training)
    if 'lm_head' in lora_modules:
        lora_modules.remove('lm_head')

    return list(lora_modules)

def save_training_checkpoint(trainer, output_dir):
    """Save model checkpoint with appropriate handling for different configurations"""
    if getattr(trainer.args, "tune_projection", False):
        # Only save projection adapter
        target_keys = ['mm_projector']
        if getattr(trainer.args, "use_image_special_tokens", False):
            target_keys.extend(['embed_tokens', 'embed_in'])

        weights_to_save = extract_projector_state(trainer.model.named_parameters(), target_keys)
        trainer.model.config.save_pretrained(output_dir)

        current_folder = os.path.basename(output_dir)
        parent_folder = os.path.dirname(output_dir)

        if trainer.args.local_rank == 0 or trainer.args.local_rank == -1:
            if current_folder.startswith('checkpoint-'):
                projector_dir = os.path.join(parent_folder, "mm_projector")
                os.makedirs(projector_dir, exist_ok=True)
                torch.save(weights_to_save, os.path.join(projector_dir, f'{current_folder}.bin'))
            else:
                torch.save(weights_to_save, os.path.join(output_dir, 'mm_projector.bin'))
        return

    if trainer.deepspeed:
        torch.cuda.synchronize()
        trainer.save_model(output_dir)
        return

    state_dict = trainer.model.state_dict()
    if trainer.args.should_save:
        cpu_state = {key: value.cpu() for key, value in state_dict.items()}
        del state_dict
        trainer._save(output_dir, state_dict=cpu_state)

def adjust_tokenizer_and_embeddings(
    special_tokens: Dict,
    tokenizer: transformers.PreTrainedTokenizer,
    model: transformers.PreTrainedModel,
):
    """Resize tokenizer and embeddings for new tokens"""
    added_tokens = tokenizer.add_special_tokens(special_tokens)
    model.resize_token_embeddings(len(tokenizer))

    if added_tokens > 0:
        input_embeds = model.get_input_embeddings().weight.data
        output_embeds = model.get_output_embeddings().weight.data

        input_avg = input_embeds[:-added_tokens].mean(dim=0, keepdim=True)
        output_avg = output_embeds[:-added_tokens].mean(dim=0, keepdim=True)

        input_embeds[-added_tokens:] = input_avg
        output_embeds[-added_tokens:] = output_avg

def tokenize_conversation_batch(texts: Sequence[str], tokenizer: transformers.PreTrainedTokenizer) -> Dict:
    """Tokenize a batch of conversation strings"""
    tokenized_list = [
        tokenizer(
            text,
            return_tensors="pt",
            padding="longest",
            max_length=tokenizer.model_max_length,
            truncation=True,
        ) for text in texts
    ]

    input_ids = [tokenized.input_ids[0] for tokenized in tokenized_list]
    input_lengths = [
        tokenized.input_ids.ne(tokenizer.pad_token_id).sum().item()
        for tokenized in tokenized_list
    ]

    return {
        "input_ids": input_ids,
        "lengths": input_lengths
    }

def apply_conversation_mask(target_tensor, token_lengths, speaker_labels):
    """Apply masking to conversation targets based on speaker"""
    current_idx = token_lengths[0]
    remaining_lengths = token_lengths[1:]

    target_tensor[:current_idx] = IGNORE_INDEX

    for length, speaker in zip(remaining_lengths, speaker_labels):
        if speaker == "human":
            target_tensor[current_idx+2:current_idx + length] = IGNORE_INDEX
        current_idx += length

def format_conversation_with_speakers(header, source_messages, include_conversation=True):
    """Format conversation with speaker labels and signals"""
    START_SIGNAL = "### "
    END_SIGNAL = "\n"
    conversation_text = header

    for message in source_messages:
        speaker = message["from"]
        if speaker.lower() == "human":
            speaker = conversation_lib.default_conversation.roles[0]
        elif speaker.lower() == "gpt":
            speaker = conversation_lib.default_conversation.roles[1]
        else:
            speaker = 'unknown'

        message["value"] = (START_SIGNAL + speaker + ": " + 
                           message["value"] + END_SIGNAL)
        if include_conversation:
            conversation_text += message["value"]

    conversation_text += START_SIGNAL
    return conversation_text

def process_multimodal_data(sources: Sequence[str], dataset_config: DatasetConfig) -> Dict:
    """Process multimodal data by handling image tokens"""
    if not dataset_config.multimodal_enabled:
        return sources

    for conversation in sources:
        for turn in conversation:
            if DEFAULT_IMAGE_TOKEN in turn['value']:
                # Clean up image token formatting
                turn['value'] = turn['value'].replace(DEFAULT_IMAGE_TOKEN, '').strip()
                turn['value'] = DEFAULT_IMAGE_TOKEN + '\n' + turn['value']
                turn['value'] = turn['value'].strip()

                # Handle special mmtag format
                if "mmtag" in conversation_lib.default_conversation.version:
                    turn['value'] = turn['value'].replace(DEFAULT_IMAGE_TOKEN, 
                                                         '<Image>' + DEFAULT_IMAGE_TOKEN + '</Image>')

            # Apply image token replacement
            replace_token = DEFAULT_IMAGE_TOKEN
            if dataset_config.use_image_special_tokens:
                replace_token = DEFAULT_IM_START_TOKEN + replace_token + DEFAULT_IM_END_TOKEN
            turn["value"] = turn["value"].replace(DEFAULT_IMAGE_TOKEN, replace_token)

    return sources

def prepare_llama2_conversation(sources, tokenizer, has_image=False):
    """Prepare conversations for Llama-2 style models"""
    conv_template = conversation_lib.default_conversation.copy()
    role_mapping = {"human": conv_template.roles[0], "gpt": conv_template.roles[1]}

    conversations = []
    for i, source in enumerate(sources):
        # Skip first message if not from human
        if role_mapping[source[0]["from"]] != conv_template.roles[0]:
            source = source[1:]

        conv_template.messages = []
        for j, turn in enumerate(source):
            role = role_mapping[turn["from"]]
            assert role == conv_template.roles[j % 2], f"Role mismatch at index {i}"
            conv_template.append_message(role, turn["value"])
        conversations.append(conv_template.get_prompt())

    # Tokenize conversations
    if has_image:
        input_ids = torch.stack([
            tokenizer_image_token(prompt, tokenizer, return_tensors='pt') 
            for prompt in conversations
        ], dim=0)
    else:
        input_ids = tokenizer(
            conversations,
            return_tensors="pt",
            padding="longest",
            max_length=tokenizer.model_max_length,
            truncation=True,
        ).input_ids

    targets = input_ids.clone()
    sep_token = "[/INST] "

    for conversation, target in zip(conversations, targets):
        total_length = int(target.ne(tokenizer.pad_token_id).sum())
        rounds = conversation.split(conv_template.sep2)
        current_pos = 1
        target[:current_pos] = IGNORE_INDEX

        for round_text in rounds:
            if round_text == "":
                break
            parts = round_text.split(sep_token)
            if len(parts) != 2:
                break
            parts[0] += sep_token

            if has_image:
                round_len = len(tokenizer_image_token(round_text, tokenizer))
                instruction_len = len(tokenizer_image_token(parts[0], tokenizer)) - 2
            else:
                round_len = len(tokenizer(round_text).input_ids)
                instruction_len = len(tokenizer(parts[0]).input_ids) - 2

            target[current_pos : current_pos + instruction_len] = IGNORE_INDEX
            current_pos += round_len

        target[current_pos:] = IGNORE_INDEX

        if current_pos < tokenizer.model_max_length and current_pos != total_length:
            target[:] = IGNORE_INDEX
            print(f"WARNING: tokenization mismatch: {current_pos} vs. {total_length}")

    return {"input_ids": input_ids, "labels": targets}

def prepare_v1_conversation(sources, tokenizer, has_image=False):
    """Prepare conversations for Vicuna v1 style models"""
    conv_template = conversation_lib.default_conversation.copy()
    role_mapping = {"human": conv_template.roles[0], "gpt": conv_template.roles[1]}

    conversations = []
    for i, source in enumerate(sources):
        if role_mapping[source[0]["from"]] != conv_template.roles[0]:
            source = source[1:]

        conv_template.messages = []
        for j, turn in enumerate(source):
            role = role_mapping[turn["from"]]
            assert role == conv_template.roles[j % 2], f"Role mismatch at index {i}"
            conv_template.append_message(role, turn["value"])
        conversations.append(conv_template.get_prompt())

    # Tokenize conversations
    if has_image:
        input_ids = torch.stack([
            tokenizer_image_token(prompt, tokenizer, return_tensors='pt') 
            for prompt in conversations
        ], dim=0)
    else:
        input_ids = tokenizer(
            conversations,
            return_tensors="pt",
            padding="longest",
            max_length=tokenizer.model_max_length,
            truncation=True,
        ).input_ids

    targets = input_ids.clone()
    sep_token = conv_template.sep + conv_template.roles[1] + ": "

    for conversation, target in zip(conversations, targets):
        total_length = int(target.ne(tokenizer.pad_token_id).sum())
        rounds = conversation.split(conv_template.sep2)
        current_pos = 1
        target[:current_pos] = IGNORE_INDEX

        for idx, round_text in enumerate(rounds):
            if round_text == "":
                break
            parts = round_text.split(sep_token)
            if len(parts) != 2:
                break
            parts[0] += sep_token

            if has_image:
                round_len = len(tokenizer_image_token(round_text, tokenizer))
                instruction_len = len(tokenizer_image_token(parts[0], tokenizer)) - 2
            else:
                round_len = len(tokenizer(round_text).input_ids)
                instruction_len = len(tokenizer(parts[0]).input_ids) - 2

            # Adjust for tokenizer version differences
            if idx != 0 and not tokenizer.legacy and IS_NEW_TOKENIZER:
                round_len -= 1
                instruction_len -= 1

            target[current_pos : current_pos + instruction_len] = IGNORE_INDEX
            current_pos += round_len

        target[current_pos:] = IGNORE_INDEX

        if current_pos < tokenizer.model_max_length and current_pos != total_length:
            target[:] = IGNORE_INDEX
            print(f"WARNING: tokenization mismatch: {current_pos} vs. {total_length}")

    return {"input_ids": input_ids, "labels": targets}

def prepare_mpt_conversation(sources, tokenizer, has_image=False):
    """Prepare conversations for MPT style models"""
    conv_template = conversation_lib.default_conversation.copy()
    role_mapping = {"human": conv_template.roles[0], "gpt": conv_template.roles[1]}

    conversations = []
    for i, source in enumerate(sources):
        if role_mapping[source[0]["from"]] != conv_template.roles[0]:
            source = source[1:]

        conv_template.messages = []
        for j, turn in enumerate(source):
            role = role_mapping[turn["from"]]
            assert role == conv_template.roles[j % 2], f"Role mismatch at index {i}"
            conv_template.append_message(role, turn["value"])
        conversations.append(conv_template.get_prompt())

    # Tokenize conversations
    if has_image:
        input_ids = torch.stack([
            tokenizer_image_token(prompt, tokenizer, return_tensors='pt') 
            for prompt in conversations
        ], dim=0)
    else:
        input_ids = tokenizer(
            conversations,
            return_tensors="pt",
            padding="longest",
            max_length=tokenizer.model_max_length,
            truncation=True,
        ).input_ids

    targets = input_ids.clone()
    sep_token = conv_template.sep + conv_template.roles[1]

    for conversation, target in zip(conversations, targets):
        total_length = int(target.ne(tokenizer.pad_token_id).sum())
        rounds = conversation.split(conv_template.sep)
        # Group into system + user + gpt chunks
        re_rounds = [conv_template.sep.join(rounds[:3])]
        for idx in range(3, len(rounds), 2):
            re_rounds.append(conv_template.sep.join(rounds[idx:idx+2]))

        current_pos = 0
        target[:current_pos] = IGNORE_INDEX

        for idx, round_text in enumerate(re_rounds):
            if round_text == "":
                break
            parts = round_text.split(sep_token)
            if len(parts) != 2:
                break
            parts[0] += sep_token

            if has_image:
                round_len = len(tokenizer_image_token(round_text, tokenizer))
                instruction_len = len(tokenizer_image_token(parts[0], tokenizer)) - 1
            else:
                round_len = len(tokenizer(round_text).input_ids)
                instruction_len = len(tokenizer(parts[0]).input_ids) - 1

            # Adjust for tokenizer version differences
            if idx != 0 and getattr(tokenizer, 'legacy', False) and IS_NEW_TOKENIZER:
                round_len += 1
                instruction_len += 1

            target[current_pos : current_pos + instruction_len] = IGNORE_INDEX
            current_pos += round_len

        target[current_pos:] = IGNORE_INDEX

        if current_pos < tokenizer.model_max_length and current_pos != total_length:
            target[:] = IGNORE_INDEX
            print(f"WARNING: tokenization mismatch: {current_pos} vs. {total_length}")

    return {"input_ids": input_ids, "labels": targets}

def prepare_plain_conversation(sources: Sequence[str], tokenizer: transformers.PreTrainedTokenizer) -> Dict:
    """Prepare plain conversation format without special formatting"""
    conversations = []
    for source in sources:
        assert len(source) == 2
        assert DEFAULT_IMAGE_TOKEN in source[0]['value']
        source[0]['value'] = DEFAULT_IMAGE_TOKEN
        conversation = source[0]['value'] + source[1]['value'] + conversation_lib.default_conversation.sep
        conversations.append(conversation)

    input_ids = [tokenizer_image_token(prompt, tokenizer, return_tensors='pt') for prompt in conversations]
    targets = copy.deepcopy(input_ids)

    for target, source in zip(targets, sources):
        tokenized_len = len(tokenizer_image_token(source[0]['value'], tokenizer))
        target[:tokenized_len] = IGNORE_INDEX

    return {"input_ids": input_ids, "labels": targets}

def prepare_conversation_data(sources: Sequence[str], tokenizer: transformers.PreTrainedTokenizer, has_image: bool = False) -> Dict:
    """Main function to prepare conversation data based on conversation style"""
    style = conversation_lib.default_conversation.sep_style

    if style == conversation_lib.SeparatorStyle.PLAIN:
        return prepare_plain_conversation(sources, tokenizer)
    elif style == conversation_lib.SeparatorStyle.LLAMA_2:
        return prepare_llama2_conversation(sources, tokenizer, has_image=has_image)
    elif style.version.startswith("v1"):
        return prepare_v1_conversation(sources, tokenizer, has_image=has_image)
    elif style == conversation_lib.SeparatorStyle.MPT:
        return prepare_mpt_conversation(sources, tokenizer, has_image=has_image)

    # Default processing with speaker signals
    conversations = []
    for source in sources:
        header = f"{conversation_lib.default_conversation.system}\n\n"
        conversation = format_conversation_with_speakers(header, source)
        conversations.append(conversation)

    # Tokenize conversations
    def get_tokenized_lengths(prompts):
        return [len(tokenizer_image_token(prompt, tokenizer)) for prompt in prompts]

    if has_image:
        input_ids = [tokenizer_image_token(prompt, tokenizer, return_tensors='pt') for prompt in conversations]
    else:
        tokenized = tokenize_conversation_batch(conversations, tokenizer)
        input_ids = tokenized["input_ids"]

    targets = copy.deepcopy(input_ids)

    for target, source in zip(targets, sources):
        if has_image:
            lengths = get_tokenized_lengths([header] + [s["value"] for s in source])
        else:
            lengths = tokenize_conversation_batch([header] + [s["value"] for s in source], tokenizer)["lengths"]
        speakers = [sentence["from"] for sentence in source]
        apply_conversation_mask(target, lengths, speakers)

    return {"input_ids": input_ids, "labels": targets}

class LazySupervisedDataset(Dataset):
    """Dataset for supervised fine-tuning with lazy preprocessing"""
    def __init__(self, data_path: str, tokenizer: transformers.PreTrainedTokenizer, data_args: DatasetConfig):
        super().__init__()
        with open(data_path, "r") as f:
            self.samples = json.load(f)

        print_log("Formatting inputs...Skip in lazy mode")
        self.tokenizer = tokenizer
        self.data_args = data_args
        self.sample_list = self.samples

    def __len__(self):
        return len(self.sample_list)

    @property
    def sequence_lengths(self):
        """Calculate sequence lengths including image tokens"""
        lengths = []
        for sample in self.sample_list:
            img_tokens = 128 if 'image' in sample else 0
            text_tokens = sum(len(conv['value'].split()) for conv in sample['conversations'])
            lengths.append(text_tokens + img_tokens)
        return lengths

    @property
    def modality_sequence_lengths(self):
        """Calculate modality-specific sequence lengths"""
        lengths = []
        for sample in self.sample_list:
            text_len = sum(len(conv['value'].split()) for conv in sample['conversations'])
            # Negative for text-only samples
            modality_len = text_len if 'image' in sample else -text_len
            lengths.append(modality_len)
        return lengths

    def __getitem__(self, index) -> Dict[str, torch.Tensor]:
        sources = self.sample_list[index]
        if isinstance(index, int):
            sources = [sources]

        assert len(sources) == 1, "Don't know why it is wrapped to a list"

        data_dict = {}

        # Process image if present
        if 'image' in sources[0]:
            image_file = self.sample_list[index]['image']
            image_folder = self.data_args.image_dir
            image_processor = self.data_args.image_processor

            # Load and process image
            image_path = os.path.join(image_folder, image_file)
            image = Image.open(image_path).convert('RGB')

            # Handle different aspect ratio modes
            if self.data_args.image_resize_mode == 'pad':
                def pad_to_square(pil_img, background_color):
                    width, height = pil_img.size
                    if width == height:
                        return pil_img
                    elif width > height:
                        result = Image.new(pil_img.mode, (width, width), background_color)
                        result.paste(pil_img, (0, (width - height) // 2))
                        return result
                    else:
                        result = Image.new(pil_img.mode, (height, height), background_color)
                        result.paste(pil_img, ((height - width) // 2, 0))
                        return result

                image = pad_to_square(image, tuple(int(x*255) for x in image_processor.image_mean))
                image = image_processor.preprocess(image, return_tensors='pt')['pixel_values'][0]
            else:
                image = image_processor.preprocess(image, return_tensors='pt')['pixel_values'][0]

            # Process multimodal data
            processed_sources = process_multimodal_data(
                copy.deepcopy([e["conversations"] for e in sources]),
                self.data_args)
        else:
            processed_sources = copy.deepcopy([e["conversations"] for e in sources])

        # Prepare conversation data
        has_image = 'image' in self.sample_list[index]
        data_dict = prepare_conversation_data(processed_sources, self.tokenizer, has_image=has_image)

        if isinstance(index, int):
            data_dict = {
                "input_ids": data_dict["input_ids"][0],
                "labels": data_dict["labels"][0]
            }

        # Add image data to dictionary
        if 'image' in self.sample_list[index]:
            data_dict['image'] = image
        elif self.data_args.multimodal_enabled:
            # Create dummy image for multimodal models without images
            crop_size = self.data_args.image_processor.crop_size
            data_dict['image'] = torch.zeros(3, crop_size['height'], crop_size['width'])

        return data_dict

@dataclass
class SupervisedCollator:
    """Collate function for supervised learning batches"""
    tokenizer: transformers.PreTrainedTokenizer

    def __call__(self, instances: Sequence[Dict]) -> Dict[str, torch.Tensor]:
        # Extract input_ids and labels
        input_ids_list = [instance["input_ids"] for instance in instances]
        labels_list = [instance["labels"] for instance in instances]

        # Pad sequences
        input_ids = torch.nn.utils.rnn.pad_sequence(
            input_ids_list,
            batch_first=True,
            padding_value=self.tokenizer.pad_token_id)
        labels = torch.nn.utils.rnn.pad_sequence(
            labels_list,
            batch_first=True,
            padding_value=IGNORE_INDEX)

        # Truncate to maximum length
        max_length = self.tokenizer.model_max_length
        input_ids = input_ids[:, :max_length]
        labels = labels[:, :max_length]

        # Create attention mask
        attention_mask = input_ids.ne(self.tokenizer.pad_token_id)

        batch = {
            "input_ids": input_ids,
            "labels": labels,
            "attention_mask": attention_mask
        }

        # Handle image data
        if 'image' in instances[0]:
            images = [instance['image'] for instance in instances]
            if all(x is not None and x.shape == images[0].shape for x in images):
                batch['images'] = torch.stack(images)
            else:
                batch['images'] = images

        return batch

def create_supervised_dataset_module(tokenizer: transformers.PreTrainedTokenizer, data_args) -> Dict:
    """Create dataset and collator for supervised fine-tuning"""
    train_dataset = LazySupervisedDataset(
        tokenizer=tokenizer,
        data_path=data_args.dataset_path,
        data_args=data_args
    )

    collator = SupervisedCollator(tokenizer=tokenizer)

    return {
        "train_dataset": train_dataset,
        "eval_dataset": None,
        "data_collator": collator
    }

def start_training(attn_implementation=None):
    """Main training function"""
    global local_rank

    # Parse command line arguments
    parser = transformers.HfArgumentParser(
        (ModelConfig, DatasetConfig, TrainingConfig))
    model_args, data_args, training_args = parser.parse_args_into_dataclasses()

    local_rank = training_args.local_rank
    compute_dtype = (torch.float16 if training_args.fp16 else 
                    (torch.bfloat16 if training_args.bf16 else torch.float32))

    # Configure quantization settings
    quantization_args = {}
    if training_args.precision_bits in [4, 8]:
        from transformers import BitsAndBytesConfig
        quantization_args.update({
            "device_map": {"": training_args.device},
            "load_in_4bit": training_args.precision_bits == 4,
            "load_in_8bit": training_args.precision_bits == 8,
            "quantization_config": BitsAndBytesConfig(
                load_in_4bit=training_args.precision_bits == 4,
                load_in_8bit=training_args.precision_bits == 8,
                llm_int8_skip_modules=["mm_projector"],
                llm_int8_threshold=6.0,
                llm_int8_has_fp16_weight=False,
                bnb_4bit_compute_dtype=compute_dtype,
                bnb_4bit_use_double_quant=training_args.double_quantization,
                bnb_4bit_quant_type=training_args.quantization_scheme
            )
        })

    # Initialize model based on architecture
    if model_args.vision_encoder is not None:
        if 'mpt' in model_args.pretrained_path:
            config = transformers.AutoConfig.from_pretrained(
                model_args.pretrained_path, 
                trust_remote_code=True
            )
            config.attn_config['attn_impl'] = training_args.mpt_attention_implementation
            model = LlavaMptForCausalLM.from_pretrained(
                model_args.pretrained_path,
                config=config,
                cache_dir=training_args.cache_directory,
                **quantization_args
            )
        else:
            model = LlavaLlamaForCausalLM.from_pretrained(
                model_args.pretrained_path,
                cache_dir=training_args.cache_directory,
                attn_implementation=attn_implementation,
                torch_dtype=(torch.bfloat16 if training_args.bf16 else None),
                **quantization_args
            )
    else:
        model = transformers.LlamaForCausalLM.from_pretrained(
            model_args.pretrained_path,
            cache_dir=training_args.cache_directory,
            attn_implementation=attn_implementation,
            torch_dtype=(torch.bfloat16 if training_args.bf16 else None),
            **quantization_args
        )

    # Configure model settings
    model.config.use_cache = False

    if model_args.freeze_backbone:
        model.model.requires_grad_(False)

    # Prepare model for quantized training
    if training_args.precision_bits in [4, 8]:
        from peft import prepare_model_for_kbit_training
        model.config.torch_dtype = (torch.float32 if training_args.fp16 else 
                                   (torch.bfloat16 if training_args.bf16 else torch.float32))
        model = prepare_model_for_kbit_training(
            model, 
            use_gradient_checkpointing=training_args.gradient_checkpointing
        )

    # Configure gradient checkpointing
    if training_args.gradient_checkpointing:
        if hasattr(model, "enable_input_require_grads"):
            model.enable_input_require_grads()
        else:
            def make_inputs_require_grad(module, input, output):
                output.requires_grad_(True)
            model.get_input_embeddings().register_forward_hook(make_inputs_require_grad)

    # Configure LoRA adapters
    if training_args.lora_enabled:
        from peft import LoraConfig, get_peft_model
        lora_config = LoraConfig(
            r=training_args.lora_rank,
            lora_alpha=training_args.lora_alpha_value,
            target_modules=find_linear_modules(model),
            lora_dropout=training_args.lora_dropout_rate,
            bias=training_args.lora_bias_setting,
            task_type="CAUSAL_LM",
        )

        if training_args.precision_bits == 16:
            if training_args.bf16:
                model.to(torch.bfloat16)
            if training_args.fp16:
                model.to(torch.float16)

        print_log("Adding LoRA adapters...")
        model = get_peft_model(model, lora_config)

    # Initialize tokenizer
    if 'mpt' in model_args.pretrained_path:
        tokenizer = transformers.AutoTokenizer.from_pretrained(
            model_args.pretrained_path,
            cache_dir=training_args.cache_directory,
            model_max_length=training_args.sequence_length_limit,
            padding_side="right"
        )
    else:
        tokenizer = transformers.AutoTokenizer.from_pretrained(
            model_args.pretrained_path,
            cache_dir=training_args.cache_directory,
            model_max_length=training_args.sequence_length_limit,
            padding_side="right",
            use_fast=False,
        )

    # Configure special tokens
    if model_args.chat_version == "v0":
        if tokenizer.pad_token is None:
            adjust_tokenizer_and_embeddings(
                special_tokens_dict=dict(pad_token="[PAD]"),
                tokenizer=tokenizer,
                model=model,
            )
    elif model_args.chat_version == "v0.5":
        tokenizer.pad_token = tokenizer.unk_token
    else:
        tokenizer.pad_token = tokenizer.unk_token
        if model_args.chat_version in conversation_lib.conv_templates:
            conversation_lib.default_conversation = conversation_lib.conv_templates[model_args.chat_version]
        else:
            conversation_lib.default_conversation = conversation_lib.conv_templates["vicuna_v1"]

    # Initialize vision tower if specified
    if model_args.vision_encoder is not None:
        model.get_model().initialize_vision_modules(
            model_args=model_args,
            fsdp=training_args.fsdp
        )

        vision_tower = model.get_vision_tower()
        dtype = torch.bfloat16 if training_args.bf16 else torch.float16
        vision_tower.to(dtype=dtype, device=training_args.device)

        data_args.image_processor = vision_tower.image_processor
        data_args.multimodal_enabled = True
        model.config.image_aspect_ratio = data_args.image_resize_mode
        model.config.tokenizer_padding_side = tokenizer.padding_side
        model.config.tokenizer_model_max_length = tokenizer.model_max_length
        model.config.tune_projection = training_args.tune_projection = model_args.tune_projection

        if model_args.tune_projection:
            model.requires_grad_(False)
            for p in model.get_model().mm_projector.parameters():
                p.requires_grad = True

        model.config.freeze_projection = training_args.freeze_projection
        if training_args.freeze_projection:
            for p in model.get_model().mm_projector.parameters():
                p.requires_grad = False

        if training_args.precision_bits in [4, 8]:
            model.get_model().mm_projector.to(dtype=compute_dtype, device=training_args.device)

        model.config.use_image_special_tokens = data_args.use_image_special_tokens = model_args.use_image_special_tokens
        model.config.projector_learning_rate = training_args.projector_learning_rate
        training_args.use_image_special_tokens = model_args.use_image_special_tokens
        model.config.use_image_patch_token = model_args.use_image_patch_token
        model.initialize_vision_tokenizer(model_args, tokenizer=tokenizer)

    # Handle quantization-specific configurations
    if training_args.precision_bits in [4, 8]:
        from peft.tuners.lora import LoraLayer
        for name, module in model.named_modules():
            if isinstance(module, LoraLayer):
                if training_args.bf16:
                    module = module.to(torch.bfloat16)
            if 'norm' in name:
                module = module.to(torch.float32)
            if 'lm_head' in name or 'embed_tokens' in name:
                if hasattr(module, 'weight'):
                    if training_args.bf16 and module.weight.dtype == torch.float32:
                        module = module.to(torch.bfloat16)

    # Create dataset module
    dataset_module = create_supervised_dataset_module(
        tokenizer=tokenizer,
        data_args=data_args
    )

    # Initialize trainer
    trainer = LLaVATrainer(
        model=model,
        tokenizer=tokenizer,
        args=training_args,
        **dataset_module
    )

    # Resume training if checkpoints exist
    checkpoint_dirs = list

# Initialize global runtime instance
_runtime_instance = None

def initialize(
    owner_id: str,
    group_id: str | None = None,
):
    """
    Set up the AlphaTrion execution context.

    Args:
        owner_id: Unique identifier for the current user (as string or UUID).
        group_id: Optional identifier for the team/group. If omitted, the system
                  will attempt to retrieve the first group linked to the user.
    """
    global _runtime_instance
    _runtime_instance = ExecutionEnvironment(
        owner_id=owner_id,
        group_id=group_id,
    )

def get_active_runtime():
    if _runtime_instance is None:
        raise RuntimeError("Runtime environment not initialized. Please call alphatrion.initialize() first.")
    return _runtime_instance


# ExecutionEnvironment encapsulates core services and stateful data
class ExecutionEnvironment:
    __slots__ = (
        "_owner_uuid",
        "_group_uuid",
        "_database_client",
        "_tracing_client",
        "_artifact_manager",
        "_base_directory",
        "_active_experiment",
    )

    def __init__(
        self,
        owner_id: str,
        group_id: str | None = None,
    ):
        # Initialize underlying storage layer
        storage_runtime.init()
        db_layer = storage_runtime.storage_runtime()
        self._database_client = db_layer.metadb
        self._tracing_client = db_layer.tracestore

        self._owner_uuid = owner_id
        self._group_uuid = group_id

        # Auto-detect group if not explicitly provided
        if group_id is None:
            associated_groups = self._database_client.list_user_groups(owner_id)
            if not associated_groups:
                raise ValueError(
                    f"No groups found for owner {owner_id}. Ensure the user is "
                    f"registered in at least one group."
                )
            self._group_uuid = associated_groups[0].uuid

        # Configure base directory for local artifacts
        self._base_directory = os.getenv(envs.ROOT_PATH, os.path.expanduser("~/.alphatrion"))

        # Determine artifact storage mode (secure/insecure)
        artifact_security_mode = os.getenv(envs.ARTIFACT_INSECURE, "false").lower() == "true"

        # Initialize artifact manager only if enabled
        if self.is_artifact_storage_active():
            self._artifact_manager = Artifact(group_id=self._group_uuid, secure=not artifact_security_mode)

        # Ensure base directory exists
        if not os.path.isdir(self._base_directory):
            os.makedirs(self._base_directory, exist_ok=True)

    def is_artifact_storage_active(self) -> bool:
        return os.getenv(envs.ENABLE_ARTIFACT_STORAGE, "true").lower() == "true"

    @property
    def database(self):
        return self._database_client

    @property
    def tracing(self):
        return self._tracing_client

    @property
    def owner(self):
        return self._owner_uuid

    @property
    def group(self):
        return self._group_uuid

    @property
    def home_dir(self):
        return self._base_directory

    @property
    def active_project(self):
        return self._active_experiment

    @active_project.setter
    def active_project(self, project):
        self._active_experiment = project

