class PipelineTesterMixin:
    model_tester = None
    supported_frameworks = ["pt", "tf"]

    def execute_pipeline_tasks(self, task_name, precision="float32"):
        """Execute pipeline tests for a specific task"""
        if task_name not in self.pipeline_model_mapping:
            self.skipTest(
                f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{precision} is skipped: "
                f"`{task_name}` is not in `self.pipeline_model_mapping`."
            )

        model_classes = self.pipeline_model_mapping[task_name]
        if not isinstance(model_classes, (list, tuple)):
            model_classes = [model_classes]

        for model_class in model_classes:
            model_name = model_class.__name__
            # Remove framework prefixes like 'Flax' or 'TF'
            for prefix in ["Flax", "TF"]:
                if model_name.startswith(prefix):
                    model_name = model_name[len(prefix):]
                    break

            tokenizer_types = []
            processor_types = []
            commit_hash = None

            if model_name in tiny_model_data:
                tokenizer_types = tiny_model_data[model_name].get("tokenizer_classes", [])
                processor_types = tiny_model_data[model_name].get("processor_classes", [])
                commit_hash = tiny_model_data[model_name].get("sha")

            # Ensure at least one entry even if empty
            tokenizer_types = tokenizer_types or [None]
            processor_types = processor_types or [None]

            repo_id_base = f"tiny-random-{model_name}"
            actual_repo_path = TRANSFORMERS_TINY_MODEL_PATH if TRANSFORMERS_TINY_MODEL_PATH == "hf-internal-testing" else model_name

            self.execute_model_pipeline_tests(
                task_name, actual_repo_path, model_class, tokenizer_types, processor_types, commit_hash, precision
            )

    def execute_model_pipeline_tests(
        self, task_name, repo_path, model_class, tokenizer_types, processor_types, commit_hash, precision="float32"
    ):
        """Run pipeline tests for a specific task with given model and tokenizers"""
        test_class_name = PIPELINE_TEST_CONFIG[task_name]["test_cls"].__name__

        for tokenizer_type in tokenizer_types:
            for processor_type in processor_types:
                if self.should_skip_test(
                    test_class_name, model_class.config_class, model_class, tokenizer_type, processor_type
                ):
                    logger.warning(
                        f"{self.__class__.__name__}::test_pipeline_{task_name.replace('-', '_')}_{precision} is skipped: "
                        f"test known to fail for model `{model_class.__name__}`, tokenizer `{tokenizer_type}`, processor `{processor_type}`."
                    )
                    continue

                self.run_single_pipeline_test(
                    task_name, repo_path, model_class, tokenizer_type, processor_type, commit_hash, precision
                )

    def run_single_pipeline_test(
        self, task_name, repo_path, model_class, tokenizer_type, processor_type, commit_hash, precision="float32"
    ):
        """Run a single pipeline test with specified components"""
        # Construct repository ID
        repo_id = f"{TRANSFORMERS_TINY_MODEL_PATH}/{repo_path}" if TRANSFORMERS_TINY_MODEL_PATH == "hf-internal-testing" else repo_path

        # Handle tokenizer loading
        tokenizer = None
        if tokenizer_type is not None:
            try:
                tokenizer_class = getattr(transformers_module, tokenizer_type)
                tokenizer = tokenizer_class.from_pretrained(repo_id, revision=commit_hash)
            except Exception as e:
                logger.warning(f"Could not load tokenizer {tokenizer_type}: {e}")

        # Handle processor loading
        processor = None
        if processor_type is not None:
            try:
                processor_class = getattr(transformers_module, processor_type)
                processor = processor_class.from_pretrained(repo_id, revision=commit_hash)
            except Exception as e:
                logger.warning(f"Could not load processor {processor_type}: {e}")
                self.skipTest(f"Could not load processor {processor_type} from {repo_id}.")

        # Skip if neither tokenizer nor processor available
        if tokenizer is None and processor is None:
            logger.warning(f"No tokenizer or processor found in {repo_id}")
            self.skipTest(f"Could not find any tokenizer or processor from {repo_id}.")

        # Load model
        try:
            model = model_class.from_pretrained(repo_id, revision=commit_hash)
        except Exception as e:
            logger.warning(f"Could not load model {model_class.__name__}: {e}")
            self.skipTest(f"Could not load model {model_class.__name__} from {repo_id}.")

        # Check additional skip conditions
        test_class_name = PIPELINE_TEST_CONFIG[task_name]["test_cls"].__name__
        if self.should_skip_test_advanced(test_class_name, model.config, model, tokenizer, processor):
            logger.warning(f"Skipping due to advanced skip conditions for {model_class.__name__}")
            self.skipTest(f"Test known to fail for {model_class.__name__} with tokenizer {tokenizer_type} and processor {processor_type}.")

        # Validate test components
        validate_components(self, task_name, model, tokenizer, processor)

        # Put model in eval mode if applicable
        if hasattr(model, "eval"):
            model = model.eval()

        # Get pipeline and examples
        task_test_instance = PIPELINE_TEST_CONFIG[task_name]["test_cls"]()
        pipeline, examples = task_test_instance.get_test_pipeline(model, tokenizer, processor, torch_dtype=precision)

        if pipeline is None:
            logger.warning("Could not create pipeline for testing")
            self.skipTest("Pipeline creation failed.")

        # Run pipeline tests
        task_test_instance.run_pipeline_test(pipeline, examples)

        # Batch processing test
        def batch_process_check(pipe, exs):
            if pipe.tokenizer is not None and pipe.tokenizer.pad_token_id is None:
                return  # No batching support
            results = []
            for item in pipe((cp.deepcopy(rnd.choice(exs)) for _ in range(10)), batch_size=4):
                results.append(item)
            assert len(results) == 10, "Batch processing produced incorrect number of results"

        batch_process_check(pipeline, examples)

