    """Validate test components meet requirements"""
    # Special handling for BlenderbotForCausalLM
    if model.__class__.__name__ == "BlenderbotForCausalLM":
        model.config.encoder_no_repeat_ngram_size = 0

    # Check vocab size requirements
    CONFIG_WITHOUT_VOCAB_SIZE = ["CanineConfig"]
    if tokenizer is not None:
        vocab_size = getattr(model.config, "vocab_size", None)
        # For CLIP-like models
        if vocab_size is None:
            if hasattr(model.config, "text_config"):
                vocab_size = getattr(model.config.text_config, "vocab_size", None)
            elif hasattr(model.config, "text_encoder"):
                vocab_size = getattr(model.config.text_encoder, "vocab_size", None)

        if vocab_size is None and model.config.__class__.__name__ not in CONFIG_WITHOUT_VOCAB_SIZE:
            raise ValueError(
                "Could not determine `vocab_size` from model configuration while `tokenizer` is not `None`."
            )

