DEFAULT_GLOBAL_SEGMENT_SIZE = 1073741824  # 1.0 GiB
DEFAULT_LOCAL_BUFFER_SIZE = 1073741824  # 1.0 GiB


def _normalize_size_input(value: Union[int, str, float]) -> int:
    """Normalize various input types to integer byte count."""
    if isinstance(value, int):
        return value
    elif isinstance(value, str):
        return _parse_size_string(value.strip())
    else:
        try:
            return int(float(value))
        except (TypeError, ValueError) as err:
            raise TypeError(f"Cannot convert {type(value)} to size: {value}") from err


def _parse_size_string(size_str: str) -> int:
    """Parse human-readable size strings like '1GB', '512MB' into bytes."""
    pattern = r"^(\d+(?:\.\d+)?)\s*(gb|mb|kb|b)?$"
    match = re.match(pattern, size_str.lower())
    if not match:
        raise ValueError(f"Invalid size format: '{size_str}'")

    num_part, unit = match.groups()
    unit = unit or "b"
    multipliers = {
        "b": 1,
        "kb": 1024,
        "mb": 1024 ** 2,
        "gb": 1024 ** 3,
    }
    try:
        numeric_val = float(num_part)
        result = int(numeric_val * multipliers[unit])
        if result < 0:
            raise ValueError("Size must be non-negative.")
        return result
    except (ValueError, OverflowError) as e:
        raise ValueError(f"Failed to parse size '{size_str}': {e}") from e


@dataclass
class MooncakeStoreConfig:
    metadata_server: str
    global_segment_size: int
    local_buffer_size: int
    protocol: str
    device_name: str
    master_server_address: str

    @classmethod
    def load_from_env(cls) -> "MooncakeStoreConfig":
        config_path = os.getenv("MOONCAKE_CONFIG_PATH")
        if not config_path:
            raise ValueError("Environment variable 'MOONCAKE_CONFIG_PATH' is not set.")
        return cls.from_file(config_path)

    @classmethod
    def from_file(cls, file_path: str) -> "MooncakeStoreConfig":
        path = Path(file_path)
        with path.open("r", encoding="utf-8") as f:
            raw_config = json.load(f)

        return cls(
            metadata_server=raw_config.get("metadata_server"),
            global_segment_size=_normalize_size_input(
                raw_config.get("global_segment_size", DEFAULT_GLOBAL_SEGMENT_SIZE)
            ),
            local_buffer_size=_normalize_size_input(
                raw_config.get("local_buffer_size", DEFAULT_LOCAL_BUFFER_SIZE)
            ),
            protocol=raw_config.get("protocol", "ascend"),
            device_name=raw_config.get("device_name", ""),
            master_server_address=raw_config.get("master_server_address"),
        )


class MooncakeBackend(Backend):
    def __init__(self, parallel_config: ParallelConfig):
        try:
            from mooncake.store import MooncakeDistributedStore  # type: ignore
        except ImportError as e:
            raise ImportError(
                "Please install mooncake by following the instructions at "
                "https://github.com/kvcache-ai/Mooncake/blob/main/doc/en/build.md "
                "to run vLLM with MooncakeConnector."
            ) from e

        self.settings = MooncakeStoreConfig.load_from_env()
        self.store = MooncakeDistributedStore()
        self.rank = parallel_config.rank

        self._initialize_storage()

    def _initialize_storage(self):
        fabric_mem_enabled = os.getenv("ASCEND_ENABLE_USE_FABRIC_MEM", "0") == "1"
        local_hostname = get_ip()

        if not fabric_mem_enabled:
            transfer_engine = global_te.get_transfer_engine(local_hostname, device_name=None)
            local_seg = f"{local_hostname}:{transfer_engine.get_rpc_port()}"
            engine_handle = transfer_engine.get_engine()
            buffer_size = self.settings.local_buffer_size
        else:
            local_seg = local_hostname
            engine_handle = None
            buffer_size = 0

        status_code = self.store.setup(
            local_seg,
            self.settings.metadata_server,
            self.settings.global_segment_size,
            buffer_size,
            self.settings.protocol,
            self.settings.device_name,
            self.settings.master_server_address,
        )

        if status_code != 0:
            msg = "Mooncake initialization failed."
            logger.error(msg)
            raise RuntimeError(msg)

    def set_device(self):
        device = torch.device(f"npu:{self.rank}")
        torch.npu.set_device(device)

    def register_buffer(self, ptrs: list[int], lengths: list[int]):
        if os.getenv("ASCEND_ENABLE_USE_FABRIC_MEM", "0") != "1":
            global_te.register_buffer(ptrs, lengths)

    def exists(self, keys: list[str]) -> list[int]:
        return self.store.batch_is_exist(keys)

    def _safe_operation(self, op_name: str, operation: Callable, keys: list[str], *args):
        try:
            results = operation(*args)
            for idx, val in enumerate(results):
                if val < 0:
                    logger.error(f"{op_name} failed for key {keys[idx]}, result: {val}")
        except Exception as exc:
            logger.error(f"{op_name} exception for keys {keys}: {exc}")

    def put(self, keys: list[str], addrs: list[list[int]], sizes: list[list[int]]):
        self._safe_operation(
            "PUT",
            self.store.batch_put_from_multi_buffers,
            keys,
            keys,
            addrs,
            sizes,
        )

    def get(self, keys: list[str], addrs: list[list[int]], sizes: list[list[int]]):
        self._safe_operation(
            "GET",
            self.store.batch_get_into_multi_buffers,
            keys,
            keys,
            addrs,
            sizes,
        )

