# Create session with retry mechanism
def build_session():
    sess = requests.Session()
    retry_config = Retry(total=3, backoff_factor=0.5, status_forcelist=[429, 500, 502, 503, 504])
    adapter = HTTPAdapter(max_retries=retry_config)
    sess.mount("http://", adapter)
    sess.mount("https://", adapter)
    return sess

# Load previously validated links
def retrieve_cache():
    if os.path.exists(CACHE_FILE):
        try:
            with open(CACHE_FILE, "r", encoding="utf-8") as file:
                return json.load(file)
        except Exception as err:
            logger.warning(f"Could not load cache: {err}")
    return {}

# Save validation results
def store_cache(cache_data):
    try:
        with open(CACHE_FILE, "w", encoding="utf-8") as file:
            json.dump(cache_data, file, indent=2)
        logger.info(f"Stored {len(cache_data)} entries in cache")
    except Exception as err:
        logger.error(f"Failed to save cache: {err}")

# Check if source is accessible
def check_source_availability(url, session):
    try:
        resp = session.head(url, timeout=5, allow_redirects=True)
        ctype = resp.headers.get("content-type", "").lower()
        return resp.status_code == 200 and ("text" in ctype or "m3u" in ctype)
    except requests.RequestException as e:
        logger.error(f"Source {url} unreachable: {e}")
        return False

# Verify stream connectivity
def verify_stream_connectivity(link, session):
    if not link.lower().endswith(".m3u8"):
        return False
    try:
        head_resp = session.head(link, timeout=1, allow_redirects=True)
        if head_resp.status_code in (200, 206, 301, 302):
            return True
        get_resp = session.get(link, timeout=3, allow_redirects=True)
        return get_resp.status_code == 200 and "#EXTM3U" in get_resp.text[:100]
    except requests.RequestException:
        return False

# Concurrent validation of streams
def validate_streams_batch(items, cache, session):
    active_streams = []
    pending_validation = []
    current_time = time.time()
    start_timestamp = current_time

    for info_line, link in items:
        if link in cache:
            last_check = cache[link].get("last_checked", 0)
            was_active = cache[link].get("is_active", False)
            if was_active and (current_time - last_check) < REFRESH_INTERVAL:
                active_streams.append((info_line, link))
                logger.debug(f"Using cached result for {link}")
                continue
        pending_validation.append((info_line, link))

    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
        future_map = {pool.submit(verify_stream_connectivity, link, session): (info, link) 
                      for info, link in pending_validation}

        for future in concurrent.futures.as_completed(future_map):
            if time.time() - start_timestamp > VALIDATION_TIMEOUT_LIMIT:
                logger.warning("Validation time limit reached")
                break

            info_line, link = future_map[future]
            try:
                if future.result():
                    active_streams.append((info_line, link))
                    cache[link] = {"last_checked": time.time(), "is_active": True}
                else:
                    cache[link] = {"last_checked": time.time(), "is_active": False}
            except Exception:
                cache[link] = {"last_checked": time.time(), "is_active": False}

    return active_streams

# Extract variant streams from master playlist
def extract_variant_streams(master_url, session):
    variants = [{"res": "Original", "url": master_url, "bw": 2560000}]

    if not master_url.lower().endswith(".m3u8") or not verify_stream_connectivity(master_url, session):
        return variants

    try:
        response = session.get(master_url, timeout=3)
        if response.status_code != 200:
            return variants

        content = response.text
        if "#EXT-X-STREAM-INF" in content:
            lines = content.splitlines()
            for idx, line in enumerate(lines):
                if line.startswith("#EXT-X-STREAM-INF"):
                    # Try resolution + bandwidth pattern
                    match = re.search(r'BANDWIDTH=(\d+).*?RESOLUTION=(\d+x\d+)', line)
                    if match:
                        bw = int(match.group(1))
                        res = match.group(2)
                        next_line = lines[idx + 1].strip() if idx + 1 < len(lines) else ""
                        if next_line.startswith("http"):
                            variants.append({
                                "res": res,
                                "url": next_line,
                                "bw": bw
                            })
                    else:
                        # Fallback to bandwidth only
                        bw_match = re.search(r'BANDWIDTH=(\d+)', line)
                        if bw_match:
                            bw = int(bw_match.group(1))
                            next_line = lines[idx + 1].strip() if idx + 1 < len(lines) else ""
                            if next_line.startswith("http"):
                                variants.append({
                                    "res": f"Variant_{len(variants)}",
                                    "url": next_line,
                                    "bw": bw
                                })
        # Filter to only active variants
        return [v for v in variants if verify_stream_connectivity(v["url"], session)] or variants
    except Exception:
        return variants

# Normalize channel name
def normalize_channel_name(name, url):
    if not name:
        return f"channel_{hashlib.md5(url.encode()).hexdigest()[:8]}"

    clean_name = re.sub(r'[^a-zA-Z0-9\s]', '', name).strip().lower().replace(' ', '_')
    clean_name = re.sub(r'_+', '_', clean_name)

    suffix = hashlib.md5(url.encode()).hexdigest()[:8]
    return f"{clean_name}_{suffix}" if clean_name else f"channel_{suffix}"

# Ensure metadata fields are present
def enrich_metadata(info_line):
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S+00:00")

    if 'tvg-logo="' not in info_line or 'tvg-logo=""' in info_line:
        match = re.search(r'(#EXTINF:-?\d+\s+)(.*?),(.+)$', info_line)
        if match:
            return f'{match.group(1)}tvg-logo="{DEFAULT_LOGO_URL}" tvg-last-checked="{now}" {match.group(2)},{match.group(3)}'
        return info_line.replace('#EXTINF:', f'#EXTINF:-1 tvg-logo="{DEFAULT_LOGO_URL}" tvg-last-checked="{now}" ')

    if 'tvg-last-checked="' not in info_line:
        match = re.search(r'(#EXTINF:-?\d+\s+.*?)(,.*)$', info_line)
        if match:
            return f'{match.group(1)} tvg-last-checked="{now}"{match.group(2)}'

    return info_line

# Parse M3U content into list of entries
def parse_m3u_content(content):
    entries = []
    lines = content.splitlines()
    current_info = None

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("#EXTINF:"):
            current_info = stripped
        elif stripped.startswith("http") and current_info:
            entries.append((current_info, stripped))
            current_info = None

    logger.info(f"Parsed {len(entries)} entries")
    return entries[:MAX_PER_SOURCE]

# Process single source
def handle_source(source, session):
    if not check_source_availability(source, session):
        logger.error(f"Skipping invalid source: {source}")
        return []

    try:
        logger.info(f"Fetching playlist: {source}")
        response = session.get(source, timeout=5)
        if response.status_code == 200:
            content = response.text
            entries = parse_m3u_content(content)
            logger.info(f"Retrieved {len(entries)} entries from {source}")
            return entries
        else:
            logger.warning(f"Source {source} returned status {response.status_code}")
    except requests.RequestException as e:
        logger.error(f"Error fetching {source}: {e}")
    return []

# Fetch all sources concurrently
def collect_all_sources(sources, session):
    total_entries = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        futures = {pool.submit(handle_source, src, session): src for src in sources}
        for future in concurrent.futures.as_completed(futures):
            src = futures[future]
            try:
                entries = future.result()
                total_entries.extend(entries)
            except Exception as e:
                logger.error(f"Error processing {src}: {e}")
    return total_entries

# Main execution logic
def run_pipeline():
    logger.info("Starting stream collection pipeline")

    # Initialize session
    session = build_session()

    # Load existing cache
    cache = retrieve_cache()

    # Clean up previous output
    if os.path.exists(BASE_DIR):
        shutil.rmtree(BASE_DIR)
        logger.info(f"Cleared directory: {BASE_DIR}")

    os.makedirs(BASE_DIR, exist_ok=True)
    os.makedirs(os.path.dirname(OUTPUT_FILE), exist_ok=True)

    # Collect entries from all sources
    all_entries = collect_all_sources(SOURCE_LIST + BACKUP_SOURCES, session)
    logger.info(f"Total entries collected: {len(all_entries)}")

    # Fallback if no entries found
    if not all_entries:
        logger.warning("No entries found, using static fallback")
        all_entries = parse_m3u_content(STATIC_PLAYLIST)

    # Validate streams
    logger.info(f"Validating {len(all_entries)} streams")
    all_entries = validate_streams_batch(all_entries, cache, session)
    logger.info(f"Found {len(all_entries)} active streams")

    # Update cache
    store_cache(cache)

    # Sort by extension preference
    all_entries.sort(key=lambda x: 0 if x[1].lower().endswith(".m3u8") else 1)

    # Deduplicate and process
    logger.info(f"Processing {len(all_entries)} entries for uniqueness")
    m3u8_count = 0
    non_m3u8_count = 0
    unique_streams = {}

    for idx, (info, link) in enumerate(all_entries):
        if len(unique_streams) >= MAX_CHANNELS:
            logger.info(f"Reached maximum channel limit: {MAX_CHANNELS}")
            break

        if idx % 100 == 0:
            logger.info(f"Processed {idx}/{len(all_entries)} entries, {len(unique_streams)} valid channels")

        if link.lower().endswith(".m3u8"):
            m3u8_count += 1
        else:
            non_m3u8_count += 1

        if link in unique_streams:
            continue

        name_match = re.search(r',(.+)$', info)
        channel_id = normalize_channel_name(name_match.group(1) if name_match else "", link)
        variants = extract_variant_streams(link, session)
        unique_streams[link] = (enrich_metadata(info), link, variants, channel_id)
        logger.info(f"Added channel: {channel_id} ({link})")

    logger.info(f"Processed {m3u8_count} .m3u8 and {non_m3u8_count} other streams")
    logger.info(f"Total unique valid channels: {len(unique_streams)}")

    # Add default fallback if needed
    if not unique_streams:
        logger.warning("No valid channels found, adding fallback")
        variants = extract_variant_streams(DEFAULT_TEST_STREAM["link"], session)
        unique_streams[DEFAULT_TEST_STREAM["link"]] = (
            DEFAULT_TEST_STREAM["info"], 
            DEFAULT_TEST_STREAM["link"], 
            variants, 
            DEFAULT_TEST_STREAM["label"]
        )

    logger.info(f"Final channel count: {len(unique_streams)}")

    # Generate output files
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S+00:00")
    final_playlist = [f'#EXTM3U tvg-updated="{now}"']
    individual_files = {}

    for link, (info, original_link, variants, channel_id) in unique_streams.items():
        github_path = f"https://bugsfreeweb.github.io/{REPO_NAME}/BugsfreeStreams/StreamsTV-TR/{channel_id}.m3u8"
        local_path = os.path.join(BASE_DIR, f"{channel_id}.m3u8")

        m3u8_content = ["#EXTM3U", "#EXT-X-VERSION:3"]
        for variant in variants:
            m3u8_content.append(
                f"#EXT-X-STREAM-INF:PROGRAM-ID=1,BANDWIDTH={variant['bw']},RESOLUTION={variant['res']}"
            )
            m3u8_content.append(variant["url"])

        individual_files[local_path] = "\n".join(m3u8_content)
        final_playlist.append(f"{info}\n{github_path}")

    # Write individual files
    for path, content in individual_files.items():
        try:
            with open(path, "w", encoding="utf-8") as file:
                file.write(content)
        except OSError as err:
            logger.error(f"Failed to write {path}: {err}")

    # Write main playlist
    try:
        with open(OUTPUT_FILE, "w", encoding="utf-8") as file:
            file.write("\n".join(final_playlist))
        logger.info(f"Wrote {len(final_playlist)-1} entries to {OUTPUT_FILE}")
    except OSError as err:
        logger.error(f"Failed to write {OUTPUT_FILE}: {err}")

    logger.info(f"Generated {len(individual_files)} individual stream files")

if __name__ == "__main__":
    run_pipeline()

import datasets
import httpx
import huggingface_hub
from ajet.schema.task import Task
from ajet.task_reader.task_reader_base import BaseTaskReader

class HuggingFaceTaskReader(BaseTaskReader):
    """
    Task reader that reads tasks from Hugging Face datasets.
    This class enables loading tasks directly from Hugging Face dataset repositories.
    It supports configuring the dataset path and split names for training and validation.
    """
    def __init__(self, config):
        super().__init__(config)
        self.config = config
        self.use_generator = False
        self.dataset_source = self.config.huggingface_dat_repo.dataset_path

        # Extract dataset name with fallback
        try:
            self.dataset_id = self.config.huggingface_dat_repo.dataset_name
        except AttributeError:
            self.dataset_id = None

        # Handle proxy configuration
        try:
            proxy_config = self.config.huggingface_dat_repo
            self.proxy_url = getattr(proxy_config, "http_proxy_address", "") or \
                             getattr(proxy_config, "http_proxy", "")
        except Exception:
            self.proxy_url = ""

        # Apply proxy settings via client factory (modern approach)
        if self.proxy_url:
            huggingface_hub.set_client_factory(
                lambda **kwargs: httpx.Client(
                    proxy=self.proxy_url,
                    **{k: v for k, v in kwargs.items() if k != "proxies"}
                )
            )

    def _fetch_dataset_split(self, split_name: str):
        """
        Load a specific dataset split from Hugging Face datasets.
        Args:
            split_name: Name of the dataset split to load (e.g., 'train', 'validation')
        Returns:
            Generator yielding Task objects constructed from dataset entries.
        """
        try:
            if self.dataset_source.endswith(".parquet"):
                # Load from local parquet file
                raw_dataset = datasets.load_dataset(
                    "parquet", data_files=self.dataset_source, split=split_name
                )
            else:
                raw_dataset = datasets.load_dataset(
                    self.dataset_source, split=split_name, name=self.dataset_id
                )

            # Add original index before shuffling
            indexed_dataset = raw_dataset.map(
                lambda example, idx: {"original_idx": idx}, 
                with_indices=True
            )
            shuffled_dataset = indexed_dataset.shuffle()
        except Exception as error:
            raise ValueError(
                f"Unable to load dataset '{self.dataset_source}' with split '{split_name}': {str(error)}"
            )

        if len(shuffled_dataset) == 0:
            raise ValueError(f"No samples found in dataset '{self.dataset_source}' with split '{split_name}'")

        self.use_generator = True
        for position, sample in enumerate(shuffled_dataset):
            # Construct Task object
            task = Task(
                main_query=sample.get("main_query") or sample.get("question") or "Empty",
                init_messages=[],
                task_id=str(sample["original_idx"]),
                env_type="no_env",
                metadata=sample,
            )
            yield task

    def produce_training_tasks(self):
        """
        Retrieve training tasks from the Hugging Face dataset defined in configuration.
        Returns:
            Generator yielding training Task objects.
        """
        split_name = self.config.huggingface_dat_repo.training_split
        return self._fetch_dataset_split(split_name)

    def produce_validation_tasks(self):
        """
        Retrieve validation tasks from the Hugging Face dataset defined in configuration.
        Returns:
            Generator yielding validation Task objects.
        """
        split_name = self.config.huggingface_dat_repo.validation_split
        return self._fetch_dataset_split(split_name)

    def collect_training_tasks(self):
        return list(self.produce_training_tasks())

    def collect_validation_tasks(self):
        return list(self.produce_validation_tasks())

"""
Automatic patching module for torchada.
This module patches PyTorch to automatically translate 'cuda' device strings
to 'musa' when running on Moore Threads hardware.
Usage:
    import torchada  # This applies all patches automatically
    import torch
    # Then use torch.cuda as normal - it will work on MUSA
    torch.cuda.is_available()
    x = torch.randn(3, 3).cuda()
    from torch.cuda.amp import autocast, GradScaler
    # Distributed training with NCCL also works transparently
    import torch.distributed as dist
    dist.init_process_group(backend="nccl")  # Uses MCCL on MUSA
    # CUDA Graphs work transparently
    g = torch.cuda.CUDAGraph()  # Uses MUSAGraph on MUSA
"""
import functools
import inspect
import sys
import warnings
from types import ModuleType
from typing import Any, Callable, Dict, List, Optional, Set
import torch
from ._platform import is_musa_platform

# Global state tracking
_patches_applied = False
_patch_functions: List[Callable] = []
_original_cuda_module = None
_device_cache: Dict[str, str] = {}
_is_musa_cached: Optional[bool] = None

def register_patch(func: Callable) -> Callable:
    """
    Decorator to register a function to be called during patching.
    Functions decorated with @register_patch are collected and executed
    in order when apply_patches() is called.
    """
    _patch_functions.append(func)
    return func

def require_modules(*modules: str) -> Callable[[Callable], Callable]:
    """
    Decorator to guard a patch function with import checks.
    If any required modules cannot be imported, the patch function is skipped.
    """
    def decorator(fn: Callable) -> Callable:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for mod_name in modules:
                try:
                    __import__(mod_name)
                except ImportError:
                    return None
            return fn(*args, **kwargs)
        return wrapper
    return decorator

def check_param_exists(func: Callable, param: str) -> bool:
    """Check if a function has a specific parameter in its signature."""
    try:
        sig = inspect.signature(func)
        return param in sig.parameters
    except (ValueError, TypeError):
        return False

def remap_device_spec(device_input: Any) -> Any:
    """
    Translate device specifications from 'cuda' to 'musa' on MUSA platform.
    Handles multiple input formats: strings, torch.device objects, integers.
    """
    global _is_musa_cached

    # Cache platform detection result
    if _is_musa_cached is None:
        _is_musa_cached = is_musa_platform()

    if not _is_musa_cached:
        return device_input

    if device_input is None:
        return device_input

    # Handle string inputs
    if isinstance(device_input, str):
        if device_input in _device_cache:
            return _device_cache[device_input]

        if device_input == "cuda" or device_input.startswith("cuda:"):
            translated = device_input.replace("cuda", "musa")
            _device_cache[device_input] = translated
            return translated

        _device_cache[device_input] = device_input
        return device_input

    # Handle torch.device objects
    if isinstance(device_input, torch.device):
        if device_input.type == "cuda":
            return torch.device("musa", device_input.index)
        return device_input

    # Return other types unchanged
    return device_input

def wrap_tensor_to_method(original_to: Callable) -> Callable:
    """Wrap tensor.to() method to translate device arguments."""
    @functools.wraps(original_to)
    def wrapped(self, *args, **kwargs):
        # Process positional arguments
        new_args = list(args)
        if args:
            first_arg = args[0]
            if isinstance(first_arg, (str, torch.device)):
                new_args[0] = remap_device_spec(first_arg)
            elif len(args) > 1 and isinstance(args[0], torch.dtype):
                new_args[1] = remap_device_spec(args[1])

        # Process keyword arguments
        if "device" in kwargs:
            kwargs["device"] = remap_device_spec(kwargs["device"])

        return original_to(self, *new_args, **kwargs)
    return wrapped

def wrap_tensor_cuda_method(original_cuda: Callable) -> Callable:
    """Wrap tensor.cuda() method to use musa on MUSA platform."""
    is_musa = is_musa_platform()

    @functools.wraps(original_cuda)
    def wrapped(self, device=None, non_blocking=False):
        if is_musa:
            if hasattr(self, "musa"):
                return self.musa(device=device, non_blocking=non_blocking)
            target = f"musa:{device}" if device else "musa"
            return self.to(target, non_blocking=non_blocking)
        return original_cuda(self, device=device, non_blocking=non_blocking)
    return wrapped

def wrap_module_cuda_method(original_cuda: Callable) -> Callable:
    """Wrap nn.Module.cuda() method to use musa on MUSA platform."""
    is_musa = is_musa_platform()

    @functools.wraps(original_cuda)
    def wrapped(self, device=None):
        if is_musa:
            if hasattr(self, "musa"):
                return self.musa(device=device)
            target = f"musa:{device}" if device else "musa"
            return self.to(target)
        return original_cuda(self, device=device)
    return wrapped

class _DeviceAliasMeta(type):
    """Metaclass for torch.device alias that handles cuda->musa translation."""
    def __instancecheck__(cls, instance):
        if _original_torch_device is not None:
            return isinstance(instance, _original_torch_device)
        return False

    def __subclasscheck__(cls, subclass):
        if _original_torch_device is not None:
            return issubclass(subclass, _original_torch_device)
        return False

class DeviceAlias(metaclass=_DeviceAliasMeta):
    """Wrapper class for torch.device that translates cuda to musa."""
    _base_class = None

    def __new__(cls, device=None, index=None, *, type=None):
        base = cls._base_class
        if base is None:
            raise RuntimeError("DeviceAlias not initialized")

        # Handle type keyword argument
        if type is not None:
            device = type

        # Handle existing torch.device objects
        if isinstance(device, base):
            if device.type == "cuda":
                idx = index if index is not None else device.index
                device = "musa"
            else:
                return device

        # Translate device string
        if isinstance(device, str):
            device = remap_device_spec(device)

        # Create device object
        if index is not None:
            return base(device, index)
        elif device is not None:
            return base(device)
        else:
            return base()

_original_torch_device = None

@register_patch
def patch_device_class():
    """Patch torch.device to translate 'cuda' to 'musa' on MUSA platform."""
    global _original_torch_device
    if _original_torch_device is not None:
        return

    _original_torch_device = torch.device
    DeviceAlias._base_class = _original_torch_device
    torch.device = DeviceAlias

_original_generator_class = None
_original_c_generator = None

@register_patch
def patch_generator_class():
    """Patch torch.Generator to translate 'cuda' device to 'musa' on MUSA platform."""
    global _original_generator_class, _original_c_generator
    if _original_generator_class is not None:
        return

    _original_generator_class = torch.Generator
    _original_c_generator = torch._C.Generator

    class GeneratorAliasMeta(type):
        def __instancecheck__(cls, instance):
            return isinstance(instance, _original_c_generator)

        def __subclasscheck__(cls, subclass):
            return subclass is _original_c_generator or issubclass(subclass, _original_c_generator)

    class GeneratorAlias(metaclass=GeneratorAliasMeta):
        def __new__(cls, device=None):
            if device is not None:
                device = remap_device_spec(device)
            return _original_generator_class(device=device)

    GeneratorAlias.__doc__ = _original_generator_class.__doc__
    GeneratorAlias.__module__ = _original_generator_class.__module__
    torch.Generator = GeneratorAlias

_original_graph_func = None

@register_patch
def patch_graph_context_manager():
    """Patch torch.cuda.graph context manager to accept cuda_graph= keyword argument."""
    global _original_graph_func
    if _original_graph_func is not None:
        return

    if not hasattr(torch.cuda, "graph"):
        return

    _original_graph_func = torch.cuda.graph

    class GraphAdapter:
        default_capture_stream = None

        def __init__(
            self,
            cuda_graph=None,
            pool=None,
            stream=None,
            capture_error_mode: str = "global",
            *,
            musa_graph=None,
        ):
            graph_obj = cuda_graph if cuda_graph is not None else musa_graph
            if graph_obj is None:
                raise TypeError("graph() missing required argument: 'cuda_graph'")

            self._wrapped = _original_graph_func(
                graph_obj,
                pool=pool,
                stream=stream,
                capture_error_mode=capture_error_mode,
            )

        def __enter__(self):
            return self._wrapped.__enter__()

        def __exit__(self, exc_type, exc_value, traceback):
            return self._wrapped.__exit__(exc_type, exc_value, traceback)

    GraphAdapter.__doc__ = _original_graph_func.__doc__
    GraphAdapter.__module__ = _original_graph_func.__module__
    torch.cuda.graph = GraphAdapter

    if hasattr(torch, "musa") and hasattr(torch.musa, "graph"):
        torch.musa.graph = GraphAdapter

def wrap_factory_function(original_fn: Callable) -> Callable:
    """Wrap tensor factory functions to translate device argument."""
    @functools.wraps(original_fn)
    def wrapped(*args, **kwargs):
        if "device" in kwargs:
            kwargs["device"] = remap_device_spec(kwargs["device"])
        return original_fn(*args, **kwargs)
    return wrapped

