            translated = translate_activities(activities)
            self._profiler = original_profile(*args, activities=translated, **kwargs)

        def __enter__(self):
            return self._profiler.__enter__()

        def __exit__(self, *args):
            return self._profiler.__exit__(*args)

        def __getattr__(self, name):
            return getattr(self._profiler, name)

