class _CDLLAdapter:
    """Wrapper for ctypes.CDLL that translates CUDA/NCCL function names to MUSA/MCCL."""
    _MUSART_PATTERNS = ("libmusart", "musart.so", "libmusa_runtime")
    _MCCL_PATTERNS = ("libmccl", "mccl.so")
    _MUBLAS_PATTERNS = ("libmublas", "mublas.so")
    _MURAND_PATTERNS = ("libmurand", "murand.so")

    def __init__(self, cdll_instance, lib_path: str):
        object.__setattr__(self, "_cdll", cdll_instance)
        object.__setattr__(self, "_lib_path", lib_path)
        object.__setattr__(self, "_lib_type", self._detect_lib_type(lib_path))

    def _detect_lib_type(self, lib_path: str) -> str:
        lib_lower = lib_path.lower()
        if any(p in lib_lower for p in self._MUSART_PATTERNS):
            return "musart"
        elif any(p in lib_lower for p in self._MCCL_PATTERNS):
            return "mccl"
        elif any(p in lib_lower for p in self._MUBLAS_PATTERNS):
            return "mublas"
        elif any(p in lib_lower for p in self._MURAND_PATTERNS):
            return "murand"
        return "unknown"

    def _translate_name(self, name: str) -> str:
        lib_type = object.__getattribute__(self, "_lib_type")
        if lib_type == "musart" and name.startswith("cuda"):
            return "musa" + name[4:]
        elif lib_type == "mccl" and name.startswith("nccl"):
            return "mccl" + name[4:]
        elif lib_type == "mublas" and name.startswith("cublas"):
            return "mublas" + name[6:]
        elif lib_type == "murand" and name.startswith("curand"):
            return "murand" + name[6:]
        return name

    def __getattr__(self, name: str):
        cdll = object.__getattribute__(self, "_cdll")
        translated = self._translate_name(name)
        value = getattr(cdll, translated)
        object.__setattr__(self, name, value)
        return value

    def __setattr__(self, name: str, value):
        cdll = object.__getattribute__(self, "_cdll")
        translated = self._translate_name(name)
        setattr(cdll, translated, value)

    def __getitem__(self, name: str):
        cdll = object.__getattribute__(self, "_cdll")
        translated = self._translate_name(name)
        return cdll[translated]

_original_ctypes_cdll = None

@register_patch
def patch_ctypes_cdll():
    """Patch ctypes.CDLL to automatically translate CUDA/NCCL function names."""
    import ctypes
    global _original_ctypes_cdll

    if _original_ctypes_cdll is not None:
        return

    _original_ctypes_cdll = ctypes.CDLL

    class PatchedCDLL:
        def __new__(cls, name, *args, **kwargs):
            cdll_instance = _original_ctypes_cdll(name, *args, **kwargs)
            name_str = str(name) if name else ""

            patterns = (
                "libmusart", "musart.so", "libmusa_runtime",
                "libmccl", "mccl.so", "libmublas", "mublas.so",
                "libmurand", "murand.so"
            )

            if any(p in name_str.lower() for p in patterns):
                return _CDLLAdapter(cdll_instance, name_str)
            return cdll_instance

    ctypes.CDLL = PatchedCDLL

def apply_patches():
    """Apply all necessary patches for CUDA to MUSA translation."""
    global _patches_applied

    if _patches_applied:
        return

    if not is_musa_platform():
        _patches_applied = True
        return

    try:
        import torch_musa  # noqa: F401
    except ImportError:
        _patches_applied = True
        return

    # Apply registered patches
    for patch_fn in _patch_functions:
        patch_fn()

    # Patch tensor methods
    if hasattr(torch.Tensor, "to"):
        torch.Tensor.to = wrap_tensor_to_method(torch.Tensor.to)

    if hasattr(torch.Tensor, "cuda"):
        torch.Tensor.cuda = wrap_tensor_cuda_method(torch.Tensor.cuda)

    if hasattr(torch.nn.Module, "cuda"):
        torch.nn.Module.cuda = wrap_module_cuda_method(torch.nn.Module.cuda)

    # Patch factory functions
    original_fns = []
    for fn_name in _FACTORY_FUNCTIONS:
        if hasattr(torch, fn_name):
            original_fn = getattr(torch, fn_name)
            original_fns.append(original_fn)
            setattr(torch, fn_name, wrap_factory_function(original_fn))

    # Update device constructors cache
    try:
        from torch.utils._device import _device_constructors
        constructors = _device_constructors()
        for orig_fn in original_fns:
            constructors.add(orig_fn)
    except (ImportError, AttributeError):
        pass

    _patches_applied = True

def is_patched() -> bool:
    """Check if patches have been applied."""
    return _patches_applied

