from pathlib import Path
from graph_net.imp_util import load_module
import graph_net.graph_net_json_file_util as gn_json

class SymbolicDimensionReifierUpdater:
    def __init__(self, settings):
        self.settings = self._prepare_settings(**settings)

    def _prepare_settings(
        self,
        model_root,
        factory_module_path,
        factory_class_name,
        factory_parameters=None,
        continue_existing=True,
    ):
        if factory_parameters is None:
            factory_parameters = {}
        return {
            "factory_module_path": factory_module_path,
            "factory_class_name": factory_class_name,
            "factory_parameters": factory_parameters,
            "model_root": model_root,
            "continue_existing": continue_existing,
        }

    def __call__(self, relative_model_path):
        full_model_path = Path(self.settings["model_root"]) / relative_model_path
        full_model_str = str(full_model_path)

        constraint_file = full_model_path / "input_tensor_constraints.py"
        if not constraint_file.is_file():
            return

        if self.settings["continue_existing"] and self._has_reification_data(full_model_str):
            return

        factory_class = self._acquire_factory_class()
        factory_instance = factory_class(
            config=self.settings["factory_parameters"],
            model_dir=full_model_str
        )

        selected_reifier = factory_instance.find_matching_reifier()
        if selected_reifier is None:
            return

        if not isinstance(selected_reifier, str):
            raise TypeError(f"Expected string for reifier name, got {type(selected_reifier)}")

        gn_json.modify_json(
            full_model_str,
            gn_json.kSymbolicDimensionReifier,
            selected_reifier
        )

    def _acquire_factory_class(self):
        module_obj = load_module(self.settings["factory_module_path"])
        return getattr(module_obj, self.settings["factory_class_name"])

    def _has_reification_data(self, model_directory):
        json_data = gn_json.load_json(model_directory)
        if gn_json.kSymbolicDimensionReifier not in json_data:
            return False
        return json_data[gn_json.kSymbolicDimensionReifier] is not None

# Alternative implementation with modified structure and naming conventions

from abc import ABC, abstractmethod
from contextlib import contextmanager
from datetime import datetime, timedelta
from io import SEEK_END, BytesIO
from math import ceil
from mmap import PROT_READ, mmap
from tempfile import (
    NamedTemporaryFile,
    SpooledTemporaryFile,
    TemporaryFile,
    _TemporaryFileWrapper,
)
from typing import IO, Any, BinaryIO, Generator
from gridfs import GridFSBucket
from pydantic import BaseModel, ConfigDict, model_validator
from pymongo.database import Database
from common.settings import settings
from common.utils.gridfs import chunked_iterator_for_stream


class DeferredBytes(BaseModel):
    """Container for deferred byte data loading."""
    model_config = ConfigDict(frozen=True)
    service_identifier: Any | None = None
    inline_data: bytes | None = None

    @model_validator(mode="after")
    def validate_storage_method(self) -> "DeferredBytes":
        if self.service_identifier is None and self.inline_data is None:
            raise ValueError("Neither service identifier nor inline data provided")
        if not (self.service_identifier is None or self inline_data is None):
            raise ValueError("Both service identifier and inline data cannot be present simultaneously")
        return self


class DeferredBytesProvider(ABC):
    def __init__(self):
        self.temp_directory = settings.tempfile_dir
        if self.temp_directory:
            self.temp_directory.mkdir(parents=True, exist_ok=True)

    def create_from_bytes(self, payload: bytes) -> DeferredBytes:
        """Creates a deferred byte object from raw bytes."""
        if len(payload) <= settings.lazy_threshold_bytes:
            return DeferredBytes(inline_data=payload)

        identifier = self._save(BytesIO(payload))
        return DeferredBytes(service_identifier=identifier)

    def create_from_iterable(
        self, 
        stream: Generator[bytes, None, None], 
        expected_size: int | None = None
    ) -> DeferredBytes:
        """Creates a deferred byte object from an iterable source."""
        if expected_size is not None and expected_size <= settings.lazy_threshold_bytes:
            combined = b''.join(stream)
            return DeferredBytes(inline_data=combined)

        # Buffer generator into temporary file
        with TemporaryFile(dir=self.temp_directory) as buffer_file:
            for chunk in stream:
                buffer_file.write(chunk)
            buffer_file.flush()
            buffer_file.seek(0)
            return self.create_from_file(buffer_file)

    def create_from_handle(self, handle: BinaryIO | IO[bytes]) -> DeferredBytes:
        """Creates a deferred byte object from a file-like object."""
        original_position = handle.tell()
        handle.seek(0, SEEK_END)
        total_size = handle.tell()
        handle.seek(original_position)

        if total_size <= settings.lazy_threshold_bytes:
            return DeferredBytes(inline_data=handle.read())

        identifier = self._save(handle)
        return DeferredBytes(service_identifier=identifier)

    @abstractmethod
    def _save(self, source: IO) -> Any:
        """Saves the data and returns a service-specific identifier."""

    @abstractmethod
    def commit(self):
        """Commits pending operations."""

    @abstractmethod
    def _retrieve_to(self, identifier: Any, destination: IO):
        """Retrieves data identified by identifier to destination."""

    @abstractmethod
    def _retrieve_as_stream(self, identifier: Any) -> Generator[bytes, None, None]:
        """Retrieves data as a streaming generator."""

    @contextmanager
    def _map_memory_region(self, identifier: Any) -> Generator[mmap, None, None]:
        with TemporaryFile(dir=self.temp_directory) as temp_file:
            self._retrieve_to(identifier, temp_file)
            temp_file.flush()
            with mmap(temp_file.fileno(), 0, prot=PROT_READ) as memory_mapped:
                yield memory_mapped

    @contextmanager
    def access_view(  # pylint: disable=contextmanager-generator-missing-cleanup
        self, deferred_object: DeferredBytes
    ) -> Generator[memoryview, None, None]:
        def safe_yield(view: memoryview) -> Generator[memoryview, None, None]:
            try:
                yield view
            finally:
                view.release()

        if deferred_object.inline_data is not None:
            for item in safe_yield(memoryview(deferred_object.inline_data)):
                yield item
        else:
            with self._map_memory_region(deferred_object.service_identifier) as mapped:
                for item in safe_yield(memoryview(mapped)):
                    yield item

    @contextmanager
    def stream_content(
        self, deferred_object: DeferredBytes
    ) -> Generator[Generator[bytes, None, None], None, None]:
        if deferred_object.inline_data is not None:
            stored_data = deferred_object.inline_data
            def inline_generator():
                yield stored_data
            yield inline_generator()
        else:
            yield self._retrieve_as_stream(deferred_object.service_identifier)

    @contextmanager
    def open_buffered_file(
        self, deferred_object: DeferredBytes
    ) -> Generator[SpooledTemporaryFile[bytes], None, None]:
        with SpooledTemporaryFile(
            max_size=settings.lazy_threshold_bytes, dir=str(self.temp_directory)
        ) as output_file:
            if deferred_object.inline_data is not None:
                output_file.write(deferred_object.inline_data)
            else:
                self._retrieve_to(deferred_object.service_identifier, output_file)
            output_file.flush()
            output_file.seek(0)
            yield output_file

    @contextmanager
    def open_named_file(
        self,
        deferred_object: DeferredBytes,
        filename_prefix: str | None = None,
        filename_suffix: str | None = None,
    ) -> Generator[_TemporaryFileWrapper, None, None]:
        with NamedTemporaryFile(
            prefix=filename_prefix, suffix=filename_suffix, dir=str(self.temp_directory)
        ) as output_file:
            if deferred_object.inline_data is not None:
                output_file.write(deferred_object.inline_data)
            else:
                self._retrieve_to(deferred_object.service_identifier, output_file)
            output_file.flush()
            output_file.seek(0)
            yield output_file


class GridFSDeferredProvider(DeferredBytesProvider):
    def __init__(self, database: Database):
        super().__init__()
        self._db = database
        self._gridfs_bucket = GridFSBucket(database)

    def _save(self, source: IO) -> Any:
        identifier = self._gridfs_bucket.upload_from_stream(
            "",
            source,
        )
        return identifier

    def _retrieve_to(self, identifier: Any, destination: IO):
        self._gridfs_bucket.download_to_stream(identifier, destination)

    def _retrieve_as_stream(self, identifier: Any) -> Generator[bytes, None, None]:
        with self._gridfs_bucket.open_download_stream(identifier) as stream:
            yield from chunked_iterator_for_stream(stream)

    def commit(self):
        now = datetime.now()
        cleanup_threshold = now - timedelta(minutes=1)
        expiration_threshold = now - timedelta(hours=1)
        query = {"uploadDate": {"$lt": cleanup_threshold}}

        for file_record in self._gridfs_bucket.find(query):
            file_id = file_record._id
            if file_record.length > file_record.chunk_size and file_record.upload_date > expiration_threshold:
                expected_chunks = ceil(file_record.length / file_record.chunk_size)
                actual_chunks = self._db.fs.chunks.count_documents(
                    {"files_id": file_id}
                )
                if actual_chunks < expected_chunks:
                    continue
            self._gridfs_bucket.delete(file_id)


class InMemoryDeferredProvider(DeferredBytesProvider):
    """In-memory provider for testing purposes only.
    **!!DO NOT USE IN PRODUCTION!!**.
    """
    def __init__(self):
        super().__init__()
        self._memory_store = []

    def _save(self, source: IO) -> Any:
        identifier = len(self._memory_store)
        self._memory_store.append(source.read())
        return identifier

    def _retrieve_to(self, identifier: Any, destination: IO):
        destination.write(self._memory_store[identifier])

    def _retrieve_as_stream(self, identifier: Any) -> Generator[bytes, None, None]:
        yield self._memory_store[identifier]

    def commit(self):
        self._memory_store.clear()

import sys
import json
from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter

def populate_pdf_fields(input_path: str, fields_data_path: str, output_path: str):
    with open(fields_data_path) as file:
        data = json.load(file)

    organized_fields = {}
    for item in data:
        if "value" in item:
            field_identifier = item["field_id"]
            page_number = item["page"]
            if page_number not in organized_fields:
                organized_fields[page_number] = {}
            organized_fields[page_number][field_identifier] = item["value"]

    pdf_reader = PdfReader(input_path)
    issues_found = False

    available_fields = get_field_info(pdf_reader)
    field_map = {f["field_id"]: f for f in available_fields}

    for entry in data:
        current_field = field_map.get(entry["field_id"])
        if current_field is None:
            issues_found = True
            print(f"ERROR: `{entry['field_id']}` is not a valid field ID")
        elif entry["page"] != current_field["page"]:
            issues_found = True
            print(
                f"ERROR: Incorrect page number for `{entry['field_id']}` (got {entry['page']}, expected {current_field['page']})"
            )
        else:
            if "value" in entry:
                validation_issue = check_field_value(current_field, entry["value"])
                if validation_issue:
                    print(validation_issue)
                    issues_found = True

    if issues_found:
        sys.exit(1)

    pdf_writer = PdfWriter(clone_from=pdf_reader)
    for page_num, values_dict in organized_fields.items():
        pdf_writer.update_page_form_field_values(
            pdf_writer.pages[page_num - 1], 
            values_dict, 
            auto_regenerate=False
        )

    pdf_writer.set_need_appearances_writer(True)
    with open(output_path, "wb") as out_file:
        pdf_writer.write(out_file)

def check_field_value(field_details, provided_value):
    field_kind = field_details["type"]
    field_name = field_details["field_id"]

    if field_kind == "checkbox":
        checked_state = field_details["checked_value"]
        unchecked_state = field_details["unchecked_value"]
        if provided_value != checked_state and provided_value != unchecked_state:
            return f'ERROR: Invalid value "{provided_value}" for checkbox field "{field_name}". The checked value is "{checked_state}" and the unchecked value is "{unchecked_state}"'

    elif field_kind == "radio_group":
        valid_options = [opt["value"] for opt in field_details["radio_options"]]
        if provided_value not in valid_options:
            return f'ERROR: Invalid value "{provided_value}" for radio group field "{field_name}". Valid values are: {valid_options}'

    elif field_kind == "choice":
        allowed_choices = [opt["value"] for opt in field_details["choice_options"]]
        if provided_value not in allowed_choices:
            return f'ERROR: Invalid value "{provided_value}" for choice field "{field_name}". Valid values are: {allowed_choices}'

    return None

def apply_pypdf_patch():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject

    original_method = DictionaryObject.get_inherited

    def modified_get_inherited(self, key: str, default=None):
        base_result = original_method(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(base_result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in base_result)
        ):
            base_result = [item[0] for item in base_result]
        return base_result

    DictionaryObject.get_inherited = modified_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    apply_pypdf_patch()
    input_pdf_file = sys.argv[1]
    fields_json_file = sys.argv[2]
    output_pdf_file = sys.argv[3]

    populate_pdf_fields(input_pdf_file, fields_json_file, output_pdf_file)

