def compute_image_hash(img_obj: Image) -> str:
    """Compute MD5 hash of image byte content."""
    m = insecure_hashlib.md5()
    if hasattr(img_obj, 'tobytes'):
        m.update(img_obj.tobytes())
    else:
        # Handle edge case where image object lacks tobytes method
        m.update(b"")
    return m.hexdigest()

