import multiprocessing as mp
import warnings
from multiprocessing.connection import Connection
from typing import Any, Callable, Optional, Union, Dict, Tuple
import gym
import numpy as np
from libero.libero.envs import OffScreenRenderEnv
from rlinf.envs.venv import (
    BaseVectorEnv,
    CloudpickleWrapper,
    EnvWorker,
    ShArray,
    SubprocEnvWorker,
    SubprocVectorEnv,
    _setup_buf,
)

# Type aliases for compatibility with Gym versions
OldStepReturn = Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]
NewStepReturn = Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]

warnings.simplefilter("once", DeprecationWarning)


def _transfer_obs_to_shared_memory(
    observation: Union[Dict, Tuple, np.ndarray],
    shared_buffers: Union[Dict, Tuple, ShArray],
) -> None:
    """Recursively copy observation data into pre-allocated shared memory buffers."""
    if isinstance(observation, np.ndarray) and isinstance(shared_buffers, ShArray):
        shared_buffers.store(observation)
    elif isinstance(observation, tuple) and isinstance(shared_buffers, tuple):
        for obs_part, buf_part in zip(observation, shared_buffers):
            _transfer_obs_to_shared_memory(obs_part, buf_part)
    elif isinstance(observation, dict) and isinstance(shared_buffers, dict):
        for key in observation:
            _transfer_obs_to_shared_memory(observation[key], shared_buffers[key])
    # No-op for other cases


def _process_worker_command(
    parent_conn: Connection,
    child_conn: Connection,
    env_factory: CloudpickleWrapper,
    shared_mem_buffers: Optional[Union[Dict, Tuple, ShArray]] = None,
) -> None:
    """Main worker loop handling environment operations over pipes."""

    def _encode_observations(obs: Any, buffers: Any) -> None:
        return _transfer_obs_to_shared_memory(obs, buffers)

    # Close unused end of pipe
    parent_conn.close()

    # Instantiate environment
    env = env_factory.data()

    try:
        while True:
            try:
                command, payload = child_conn.recv()
            except EOFError:
                child_conn.close()
                break

            if command == "step":
                result = env.step(payload)
                if shared_mem_buffers is not None:
                    _encode_observations(result[0], shared_mem_buffers)
                    result = (None,) + result[1:]
                child_conn.send(result)

            elif command == "reset":
                output = env.reset(**payload) if payload else env.reset()

                # Detect whether info dict is returned
                has_info = (
                    isinstance(output, (list, tuple)) 
                    and len(output) == 2 
                    and isinstance(output[1], dict)
                )

                if has_info:
                    obs, info = output
                else:
                    obs = output
                    info = None

                if shared_mem_buffers is not None:
                    _encode_observations(obs, shared_mem_buffers)
                    obs = None

                if has_info:
                    child_conn.send((obs, info))
                else:
                    child_conn.send(obs)

            elif command == "close":
                result = env.close() if hasattr(env, "close") else None
                child_conn.send(result)
                child_conn.close()
                break

            elif command == "render":
                rendered = env.render(**payload) if hasattr(env, "render") else None
                child_conn.send(rendered)

            elif command == "seed":
                if hasattr(env, "seed"):
                    child_conn.send(env.seed(payload))
                else:
                    env.reset(seed=payload)
                    child_conn.send(None)

            elif command == "getattr":
                value = getattr(env, payload) if hasattr(env, payload) else None
                child_conn.send(value)

            elif command == "setattr":
                setattr(env.unwrapped, payload["key"], payload["value"])

            elif command == "check_success":
                child_conn.send(env.check_success())

            elif command == "get_segmentation_of_interest":
                child_conn.send(env.get_segmentation_of_interest(payload))

            elif command == "get_sim_state":
                child_conn.send(env.get_sim_state())

            elif command == "set_init_state":
                obs = env.set_init_state(payload)
                child_conn.send(obs)

            elif command == "reconfigure":
                env.close()
                seed_val = payload.pop("seed")
                new_env = OffScreenRenderEnv(**payload)
                new_env.seed(seed_val)
                env = new_env
                child_conn.send(None)

            else:
                child_conn.close()
                raise ValueError(f"Unknown command received: {command}")

    except KeyboardInterrupt:
        child_conn.close()


class CustomReconfigurableWorker(SubprocEnvWorker):
    """Extended worker supporting dynamic reconfiguration of the underlying environment."""

    def __init__(self, env_fn: Callable[[], gym.Env], use_shmem: bool = False):
        ctx = mp.get_context("spawn")
        self.parent_pipe, self.child_pipe = ctx.Pipe()
        self.use_shared_mem = use_shmem
        self.shared_mem_region: Optional[Union[Dict, Tuple, ShArray]] = None

        if self.use_shared_mem:
            temp_env = env_fn()
            observation_space = temp_env.observation_space
            temp_env.close()
            del temp_env
            self.shared_mem_region = _setup_buf(observation_space)

        args = (
            self.parent_pipe,
            self.child_pipe,
            CloudpickleWrapper(env_fn),
            self.shared_mem_region,
        )

        self.worker_process = ctx.Process(target=_process_worker_command, args=args, daemon=True)
        self.worker_process.start()
        self.child_pipe.close()
        EnvWorker.__init__(self, env_fn)

    def update_environment(self, config_dict):
        """Send reconfiguration request to the subprocess."""
        self.parent_pipe.send(["reconfigure", config_dict])
        return self.parent_pipe.recv()


class ReconfigurableSubprocVectorEnv(SubprocVectorEnv):
    """Vectorized environment with support for per-env reconfiguration."""

    def __init__(self, env_creators: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def make_worker(fn: Callable[[], gym.Env]) -> CustomReconfigurableWorker:
            return CustomReconfigurableWorker(fn, use_shmem=False)

        BaseVectorEnv.__init__(self, env_creators, make_worker, **kwargs)

    def apply_reconfiguration(self, configs: list, indices=None):
        """Apply new configurations to specified environments."""
        self._ensure_not_closed()
        indices = self._normalize_indices(indices)

        if self.async_mode:
            self._validate_indices(indices)

        for idx, cfg in zip(indices, configs):
            self.workers[idx].update_environment(cfg)

