GBYTES = 1024 ** 3
TPU_HEAD_SIZE_ALIGNMENT = 128
TPU_SECOND_LAST_MINOR = 8

# Alternative mapping for dtype aliases to JAX types
_JAX_DTYPE_ALIASES = {
    "fp8": jnp.float8_e4m3fn.dtype,
    "fp8_e4m3": jnp.float8_e4m3fn.dtype,
    "fp8_e5m2": jnp.float8_e5m2.dtype,
    "fp4": jnp.float4_e2m1fn.dtype,
}

def convert_to_jax_dtype(dtype_spec):
    """Convert various dtype representations to JAX dtype."""
    if isinstance(dtype_spec, str):
        return _JAX_DTYPE_ALIASES.get(dtype_spec, jnp.dtype(dtype_spec))
    elif isinstance(dtype_spec, torch.dtype):
        return t2j_dtype(dtype_spec)
    elif isinstance(dtype_spec, jnp.dtype):
        return dtype_spec
    elif isinstance(dtype_spec, type) and hasattr(dtype_spec, 'dtype'):
        return dtype_spec.dtype
    else:
        raise TypeError(f"Unsupported dtype specification: {type(dtype_spec)}")

def convert_to_torch_dtype(dtype_spec):
    """Convert dtype to torch.dtype via JAX intermediate representation."""
    jax_dtype = convert_to_jax_dtype(dtype_spec)
    return j2t_dtype(jax_dtype)

_megacore_enabled = False
logger = init_logger(__name__)

def round_up_to_multiple(value, multiple):
    """Round value up to nearest multiple."""
    return ((value + multiple - 1) // multiple) * multiple

def activate_megacore_mode():
    """Enable megacore mode globally."""
    global _megacore_enabled
    _megacore_enabled = True

def is_megacore_active():
    """Check if megacore mode is enabled."""
    return _megacore_enabled

def calculate_kv_heads(num_kv_heads, tensor_parallel_size):
    """Determine KV heads per device based on parallelization strategy."""
    if tensor_parallel_size <= num_kv_heads:
        assert num_kv_heads % tensor_parallel_size == 0, "KV heads must be divisible by TP size"
        return num_kv_heads
    else:
        assert tensor_parallel_size % num_kv_heads == 0, "TP size must be divisible by KV heads"
        return tensor_parallel_size

def collect_device_memory_stats(devices):
    """Gather memory statistics from devices."""
    memory_data = []

    if vllm_envs.VLLM_TPU_USING_PATHWAYS:
        return pathways_memory_measurements(devices)

    multihost_backend = envs.TPU_MULTIHOST_BACKEND

    if multihost_backend == "ray":
        # For Ray backend, sample one device and assume uniformity
        for dev in devices:
            try:
                stats = dev.memory_stats()
                used_bytes = stats["bytes_in_use"]
                limit_bytes = stats["bytes_limit"]
                logger.info(
                    "Sampled memory stats from device %s; assuming all devices have similar usage.",
                    dev)
                memory_data.extend([(used_bytes, limit_bytes)] * len(devices))
                break
            except Exception as err:
                logger.warning(
                    "Failed to retrieve memory stats from device %s: %s", dev, err)
    else:
        # Direct measurement for other backends
        for dev in devices:
            stats = dev.memory_stats()
            memory_data.append((stats["bytes_in_use"], stats["bytes_limit"]))

    return memory_data

def determine_device_type(device_count=None):
    """Identify TPU device type and configuration."""
    first_device = jax.devices()[0]
    kind = first_device.device_kind

    if 'TPU' not in kind:
        raise RuntimeError("Expected TPU devices but found non-TPU hardware")

    suffix = ''
    if kind.endswith(' lite'):
        kind = kind[:-5]
        suffix = 'e'
    elif kind.endswith('e') or kind.endswith('p'):
        kind = kind[:-1]
        suffix = kind[-1] if kind[-1] in 'ep' else ''
    elif kind == 'TPU7x':
        kind = 'TPU v7'

    if not kind.startswith('TPU v'):
        raise ValueError(f"Unexpected device kind format: {kind}")

    kind += suffix
    if device_count is not None:
        kind += f'-{device_count}'

    return kind

def get_hbm_capacity():
    """Get HBM capacity based on device type."""
    device_type = determine_device_type()

    capacities = {
        ("TPU v5p", "TPU v5"): 95 * GBYTES,
        "TPU v5e": 16 * GBYTES,
        ("TPU v6e", "TPU v4"): 32 * GBYTES,
        "TPU v7": 96 * GBYTES  # Half of 192GB chip per JAX device
    }

    for keys, capacity in capacities.items():
        if isinstance(keys, tuple):
            if device_type in keys:
                return capacity
        elif device_type == keys:
            return capacity

    raise ValueError(f"Unknown device type: {device_type}")

def pathways_memory_measurements(devices):
    """Calculate memory usage using Pathways live arrays."""
    live_arrays = jax.live_arrays()
    device_usage = defaultdict(int)
    hbm_limit = get_hbm_capacity()
    seen_buffers = set()

    for arr in live_arrays:
        for shard in arr.addressable_shards:
            buffer_id = id(shard.data)
            if buffer_id not in seen_buffers:
                seen_buffers.add(buffer_id)
                device_usage[shard.data.device] += shard.data.nbytes

    return [(device_usage[dev], hbm_limit) for dev in devices]

def memory_usage_in_gb(devices):
    """Convert raw memory bytes to gigabytes."""
    raw_stats = collect_device_memory_stats(devices)
    return [(round(used / GBYTES, 2), round(limit / GBYTES, 2)) 
            for used, limit in raw_stats]

def align_head_dimension(head_dim):
    """Align head dimension for optimal kernel performance."""
    if head_dim == 64:
        return 64  # Special case for optimized kernel
    return round_up_to_multiple(head_dim, TPU_HEAD_SIZE_ALIGNMENT)

def adjust_num_heads_for_sharding(num_heads, sharding_factor):
    """Adjust number of heads according to sharding constraints."""
    if num_heads >= sharding_factor:
        assert num_heads % sharding_factor == 0, "Heads must be divisible by sharding factor"
    else:
        assert sharding_factor % num_heads == 0, "Sharding factor must be divisible by heads"
        num_heads = sharding_factor
    return num_heads

def compute_packing_factor(dtype):
    """Calculate data packing efficiency based on dtype size."""
    bits_per_element = dtypes.itemsize_bits(dtype)
    return 32 // bits_per_element

def construct_optimized_mesh(dimension_sizes, axis_labels, *, devices=None):
    """Build an optimized device mesh with topology awareness."""
    if devices is None:
        devices = xb.devices()

    # Sort devices by coordinates for consistent ordering
    sorted_devices = sorted(devices, key=lambda d: d.coords)

    def is_single_dimensional(sizes):
        return sum(1 for s in sizes if s > 1) == 1

    if is_single_dimensional(dimension_sizes):
        device_type = sorted_devices[0].device_kind
        device_count = len(sorted_devices)

        if device_type == "TPU v6 lite":
            ordered_devices = None

            # Handle specific device arrangements for v6e
            if device_count == 8:
                ordered_devices = [
                    sorted_devices[0], sorted_devices[1], sorted_devices[2], sorted_devices[3],
                    sorted_devices[7], sorted_devices[6], sorted_devices[5], sorted_devices[4]
                ]
            elif device_count == 4:
                ordered_devices = [
                    sorted_devices[0], sorted_devices[1], 
                    sorted_devices[3], sorted_devices[2]
                ]

            if ordered_devices is not None:
                reshaped = np.array(ordered_devices).reshape(dimension_sizes)
                mesh = mesh_lib.Mesh(reshaped, axis_labels)
                logger.info("Using custom topology-aware mesh: %s", mesh)
                return mesh

    # Fallback to standard mesh creation with graceful degradation
    try:
        return jax.make_mesh(dimension_sizes, axis_labels, devices=sorted_devices)
    except (AssertionError, ValueError, RuntimeError) as e:
        logger.warning(
            "Standard mesh creation failed (%s); falling back to basic layout", e)
        reshaped = np.array(sorted_devices).reshape(dimension_sizes)
        return mesh_lib.Mesh(reshaped, axis_labels)

def create_device_array(mesh, *args, sharding=None, **kwargs):
    """Create a JAX array distributed across specified mesh with optional sharding."""
    if sharding is None:
        sharding = NamedSharding(mesh, PartitionSpec(None))
    return jax.device_put(*args, device=sharding, **kwargs)

def resolve_hash_function(name):
    """Select appropriate hashing function by name."""
    if name == "builtin":
        return hash
    return utils.hashing.get_hash_fn_by_name(name)

def extract_jax_dtype_from_string(dtype_str):
    """Extract JAX dtype from string representation."""
    return convert_to_jax_dtype(dtype_str)

def compute_mesh_dimension_product(mesh, axes):
    """Compute product of mesh dimensions for specified axes."""
    if axes is None:
        return 1

    if isinstance(axes, str):
        axes = [axes]

    product = 1
    for axis in axes:
        product *= mesh.shape.get(axis, 1)
    return product

def timed_execution(func):
    """Decorator to measure and log function execution time."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        duration = time.perf_counter() - start
        logger.debug(
            f"Function '{func.__name__}' completed in {duration:.4f} seconds."
        )
        return result
    return wrapper

