if is_torch_available():
    import torch

_logger = logging.get_logger(__name__)


class AwqQuantizer(HfQuantizer):
    """
    4-bit quantization for Activation-aware Weight Quantization (AWQ)
    Reference: https://arxiv.org/abs/2306.00978
    """

    # Calibration required — inference-only use case
    requires_calibration = True
    required_packages = {"autoawq", "accelerate"}

    def __init__(self, quantization_config, **kwargs):
        super().__init__(quantization_config, **kwargs)

    def validate_environment(self, device_map, **kwargs):
        # Ensure GPU availability
        if not torch.cuda.is_available():
            raise RuntimeError("A CUDA-compatible GPU is required to run AWQ-quantized models.")

        # Check dependencies
        if not is_auto_awq_available():
            raise ImportError(
                "The 'autoawq' library is required for loading AWQ models. Install via: pip install autoawq"
            )
        if not is_accelerate_available():
            raise ImportError(
                "The 'accelerate' library is required for loading AWQ models. Install via: pip install accelerate"
            )

        # Device map validation
        if device_map is None:
            _logger.warning_once(
                "AWQ model loaded on CPU despite CUDA being available. "
                "For optimal performance, move the model to a GPU device."
            )
        elif isinstance(device_map, dict):
            forbidden_devices = {"cpu", "disk"}
            if any(dev in forbidden_devices for dev in device_map.values()):
                raise ValueError(
                    "Device mapping includes unsupported devices ('cpu' or 'disk'). "
                    "AWQ models must run entirely on GPU. Please adjust your device_map."
                )

    def update_torch_dtype(self, torch_dtype):
        # Default to float16 if not specified
        target_dtype = torch.float16 if torch_dtype is None else torch_dtype

        # Warn if non-fp16 dtype is used
        if target_dtype != torch.float16:
            _logger.warning(
                "Using a dtype other than torch.float16 may reduce efficiency with AWQ. "
                "Recommend setting torch_dtype=torch.float16."
            )
        return target_dtype

    def _process_model_before_weight_loading(self, model: "PreTrainedModel", **kwargs):
        from ..integrations import get_keys_to_not_convert, replace_quantization_scales, replace_with_awq_linear

        # Collect modules that should remain unquantized
        self.modules_to_not_convert = get_keys_to_not_convert(model)
        if self.quantization_config.modules_to_not_convert:
            self.modules_to_not_convert.extend(self.quantization_config.modules_to_not_convert)

        # Perform linear layer replacement
        model, replaced = replace_with_awq_linear(
            model,
            quantization_config=self.quantization_config,
            modules_to_not_convert=self.modules_to_not_convert,
        )

        # Apply scale adjustments based on model type
        model = replace_quantization_scales(model, model.config.model_type)

        # Alert if no replacements occurred
        if not replaced:
            _logger.warning(
                "No linear layers were converted during AWQ preprocessing. "
                "Verify model architecture or report potential issues on GitHub."
            )

    def _process_model_after_weight_loading(self, model):
        # Fuse AWQ modules if requested
        if getattr(self.quantization_config, "do_fuse", False):
            from ..integrations import fuse_awq_modules

            model = fuse_awq_modules(model, self.quantization_config)
            setattr(model, "_awq_is_fused", True)  # Consider storing in config instead

        # Initialize ExLlama backend if selected
        if self.quantization_config.version == AWQLinearVersion.EXLLAMA:
            from ..integrations import post_init_awq_exllama_modules

            model = post_init_awq_exllama_modules(model, self.quantization_config.exllama_config)

    @property
    def is_serializable(self):
        # Serialization restrictions for fused or ExLlama models
        if getattr(self.quantization_config, "do_fuse", False):
            _logger.warning("Saving AWQ models with fused modules is not supported.")
            return False

        if self.quantization_config.version == AWQLinearVersion.EXLLAMA:
            _logger.warning("Serialization of ExLlama-backed AWQ models is disabled.")
            return False

        return True

    @property
    def is_trainable(self):
        # Trainability depends on autoawq version >= 0.2.0 for PEFT support
        MIN_VERSION_FOR_TRAINING = "0.2.0"
        current_version = importlib.metadata.version("autoawq")
        return version.parse(current_version) >= version.parse(MIN_VERSION_FOR_TRAINING)

import torch
import habana_frameworks.torch.core as htcore
import habana_frameworks.torch.utils.experimental as htexp

# Detect device type at runtime
def _detect_hpu_generation():
    try:
        dev_type = htexp._get_device_type()
        return "GAUDI2" if dev_type == htexp.synDeviceType.synDeviceGaudi2 else "GAUDI3"
    except Exception:
        return "GAUDI3"

HPU_GEN = _detect_hpu_generation()

# Helper: compute max finite value safely for optional dtypes
def _safe_finfo_max(dtype):
    try:
        return torch.finfo(dtype).max
    except AttributeError:
        return None

# Compute exponent bias based on bit-width of exponent field
def _compute_exp_bias(bit_width):
    return (1 << (bit_width - 1)) - 1

# Mapping from dtype to exponent width
EXP_WIDTH_MAP = {
    torch.float32: 8,
    torch.bfloat16: 8,
    torch.float8_e4m3fn: 4,
    torch.float8_e5m2: 5,
}

# Precomputed maximum representable values per dtype
MAX_VALS = {
    k: _safe_finfo_max(k)
    for k in [torch.float32, torch.bfloat16, torch.float8_e4m3fn, torch.float8_e5m2]
}
# Attempt to add float8_e4m3fnuz if available
try:
    MAX_VALS[torch.float8_e4m3fnuz] = _safe_finfo_max(torch.float8_e4m3fnuz)
except AttributeError:
    pass

# Hardware-specific scale factor for Gaudi2 (ratio of fn vs fnuz max)
def _gaudi2_scale_ratio():
    return MAX_VALS.get(torch.float8_e4m3fn, 0) / MAX_VALS.get(torch8_e4m3fnuz, 1)

# Get full-scale range for given dtype and exp bias adjustment
def _fullscale_range(dtype, device_gen, custom_exp_bias=None):
    default_exp_bias = _compute_exp_bias(EXP_WIDTH_MAP[dtype])
    base_max = MAX_VALS.get(dtype)
    if base_max is None:
        raise ValueError(f"Unsupported dtype {dtype}")

    # Special case: GAUDI2 + e4m3fn → use fnuz max as baseline
    if device_gen == "GAUDI2" and dtype == torch.float8_e4m3fn:
        try:
            base_max = MAX_VALS[torch.float8_e4m3fnuz]
        except KeyError:
            pass

    effective_exp_bias = custom_exp_bias if custom_exp_bias is not None else default_exp_bias
    scale_factor = 2 ** (default_exp_bias - effective_exp_bias)
    return float(base_max * scale_factor)

# Generate list of fullscale values for a set of exponent biases
def _fullscales_for_biases(dtype, device_gen, bias_list):
    return [_fullscale_range(dtype, device_gen, eb) for eb in bias_list]

# Return hardware-aligned FP8 scales for given dtype & device
def _aligned_fp8_scales(dtype, device_gen):
    # Bias sets per device/dtype
    BIAS_SETS = {
        ("GAUDI2", torch.float8_e4m3fn): [3, 7, 11, 15],
        ("GAUDI2", torch.float8_e5m2): [15],
        ("GAUDI3", torch.float8_e4m3fn): list(range(63)),
        ("GAUDI3", torch.float8_e5m2): list(range(63)),
    }
    bias_set = BIAS_SETS.get((device_gen, dtype))
    if bias_set is None:
        return None

    base_fullscale = _fullscale_range(dtype, device_gen)
    return [
        x / base_fullscale
        for x in _fullscales_for_biases(dtype, device_gen, bias_set)
    ]

# Device scaling factors
DEVICE_SCALE_FACTORS = {
    "GAUDI2": 4,
    "GAUDI3": 1,
}

# Precompute aligned FP8 scales per device
FP8_E4M3_SCALES = {
    dev: _aligned_fp8_scales(torch.float8_e4m3fn, dev)
    for dev in DEVICE_SCALE_FACTORS.keys()
}

# Extract min/max/scale-factor traits per device
FP8_E4M3_TRAITS = {
    dev: (
        min(FP8_E4M3_SCALES[dev]),
        max(FP8_E4M3_SCALES[dev]),
        DEVICE_SCALE_FACTORS[dev],
    )
    for dev in DEVICE_SCALE_FACTORS.keys()
}

# Round up to nearest power of two
class PowerOfTwoRounding:
    def apply(self, scale_tensor):
        log2_val = torch.log2(scale_tensor)
        ceil_log2 = torch.ceil(log2_val)
        return 2.0 ** ceil_log2

# Align scale to hardware constraints (GAUDI2/GAUDI3)
class HardwareScaleAligner:
    def __init__(self, preferred_device=None):
        self.device = preferred_device or HPU_GEN

    def apply(self, scale_tensor):
        # Adjust for Gaudi2 special scaling
        adjusted_scale = scale_tensor.clone()
        if self.device == "GAUDI2":
            adjusted_scale *= _gaudi2_scale_ratio()

        # Step 1: round to nearest power-of-two
        pow2_scaled = PowerOfTwoRounding().apply(adjusted_scale)

        # Step 2: clamp to valid range and align to step size
        min_val, max_val, step_factor = FP8_E4M3_TRAITS[self.device]
        step_size = step_factor

        # Compute aligned exponent: round log2(scale) to nearest multiple of step_factor
        log2_pow2 = torch.log2(pow2_scaled)
        aligned_exponent = torch.round(log2_pow2 / step_size) * step_size
        hw_aligned = 2.0 ** aligned_exponent

        # Clamp within bounds
        clamped = torch.clamp(hw_aligned, min=min_val, max=max_val)
        return clamped.to(dtype=scale_tensor.dtype, device=scale_tensor.device)

import uuid
from datetime import datetime, timezone
from alphatrion.runtime.contextvars import current_run_id
from alphatrion.runtime.runtime import global_runtime
from alphatrion.storage.sql_models import Status
from alphatrion.types import CallableEntry

class Execution:
    __slots__ = ("_run_identifier", "_coroutine_task", "_runtime_instance", "_experiment_id", "_output")

    def __init__(self, experiment_id: uuid.UUID):
        self._runtime_instance = global_runtime()
        self._experiment_id = experiment_id
        self._output = None
        self._run_identifier = None
        self._coroutine_task = None

    @property
    def run_id(self) -> uuid.UUID:
        return self._run_identifier

    @property
    def output(self):
        return self._output

    def _fetch_run_record(self):
        return self._runtime_instance.metadb.get_run(run_id=self._run_identifier)

    def execute(self, func_entry: CallableEntry) -> None:
        self._run_identifier = self._runtime_instance.metadb.create_run(
            team_id=self._runtime_instance.team_id,
            user_id=self._runtime_instance.user_id,
            experiment_id=self._experiment_id,
            status=Status.RUNNING,
        )

        token = current_run_id.set(self.run_id)
        try:
            self._coroutine_task = asyncio.create_task(func_entry())
        finally:
            current_run_id.reset(token)

    def complete(self):
        if self.is_cancelled():
            return

        run_record = self._runtime_instance.metadb.get_run(run_id=self.run_id)
        start_time = run_record.created_at.replace(tzinfo=timezone.utc)
        elapsed = (datetime.now(timezone.utc) - start_time).total_seconds()

        self._runtime_instance.metadb.update_run(
            run_id=self._run_identifier, 
            status=Status.COMPLETED, 
            duration=elapsed
        )
        self._output = self._coroutine_task.result()

    def abort(self):
        self._coroutine_task.cancel()

        run_record = self._runtime_instance.metadb.get_run(run_id=self.run_id)
        start_time = run_record.created_at.replace(tzinfo=timezone.utc)
        elapsed = (datetime.now(timezone.utc) - start_time).total_seconds()

        self._runtime_instance.metadb.update_run(
            run_id=self._run_identifier, 
            status=Status.CANCELLED, 
            duration=elapsed
        )

    def is_cancelled(self) -> bool:
        return self._coroutine_task.cancelled()

    async def await_completion(self):
        await self._coroutine_task

    def register_completion_handler(self, handler: callable):
        self._coroutine_task.add_done_callback(handler)

import torch.fx as fx
from graph_net.torch.dim_gen_passes import DimensionGeneralizationPass
from collections import namedtuple
import os

class RewrittenConcretePass(DimensionGeneralizationPass):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    @classmethod
    def pass_identifier(cls) -> str:
        return os.path.splitext(os.path.basename(__file__))[0]

    def requires_modification(self, traced_module: fx.GraphModule) -> bool:
        # Skip if batch dimension (axis 0) is involved
        if 0 in self.axes:
            return False
        # Check whether any node in the graph needs rewriting
        for node in traced_module.graph.nodes:
            if self._requires_transformation(node):
                return True
        return False

    def target_operation(self):
        return torch.full

    def _requires_transformation(self, node) -> bool:
        # Only consider function call nodes
        if node.op != "call_function":
            return False
        # Match the target operation
        if node.target != self.target_operation():
            return False
        # Expect exactly one positional argument (shape tuple)
        if len(node.args) != 1:
            return False
        # Check if the shape tuple contains the target dimension
        shape_dims = node.args[0]
        return any(d == self.dim for d in shape_dims)

    def transform(self, traced_module: fx.GraphModule) -> fx.GraphModule:
        # Build a fresh computation graph
        updated_graph = fx.Graph()
        # Map old nodes to their replacements in the new graph
        node_mapping = {}

        # Track the most recent node with dynamic dimension along axis > 0
        DynamicNodeInfo = namedtuple("DynamicNodeInfo", ["node", "spatial_axis"])
        current_dynamic_node = None

        def update_dynamic_tracking(original_node, replacement_node):
            nonlocal current_dynamic_node
            tensor_meta = original_node.meta.get("tensor_meta")
            if tensor_meta is None or not hasattr(tensor_meta, "shape"):
                return
            # Scan spatial dimensions (skip batch axis 0)
            for idx, dim_size in enumerate(tensor_meta.shape):
                if idx == 0 or dim_size != self.dim:
                    continue
                current_dynamic_node = DynamicNodeInfo(
                    node=replacement_node, 
                    spatial_axis=idx
                )
                break

        def resolve_dimension_value(axis_index, original_dim):
            # Replace target dimension with dynamic size lookup
            if original_dim != self.dim:
                return node_mapping.get(original_dim, original_dim)
            # Ensure dynamic dimension was previously identified
            assert original_dim == self.dim
            # Retrieve dynamic size from tracked node
            return updated_graph.call_method(
                "size", 
                args=(current_dynamic_node.node, current_dynamic_node.spatial_axis)
            )

        def process_node(original_node):
            nonlocal current_dynamic_node
            # Handle nodes that don't need transformation
            if not (self._requires_transformation(original_node) and current_dynamic_node is not None):
                # Standard copy with remapped inputs
                new_node = updated_graph.node_copy(
                    original_node, 
                    lambda n: node_mapping.get(n, n)
                )
                update_dynamic_tracking(original_node, new_node)
                return new_node

            # Transform the shape arguments by replacing target dimension
            transformed_dims = tuple(
                resolve_dimension_value(i, dim) 
                for i, dim in enumerate(original_node.args[0])
            )

            # Create new operation with transformed shape
            new_node = updated_graph.call_function(
                self.target_operation(),
                args=(transformed_dims,),
                kwargs=original_node.kwargs
            )
            return new_node

        # Process all nodes in original graph
        for original_node in traced_module.graph.nodes:
            node_mapping[original_node] = process_node(original_node)

        # Install new graph and recompile
        traced_module.graph = updated_graph
        traced_module.recompile()
        return traced_module

