import io
import sys
from contextlib import redirect_stdout

def _generate_annotation(severity, rule_id, file_path, line_num, message):
    # Map severity levels to GitHub annotation types
    severity_map = {
        "CRITICAL": "::error",
        "HIGH": "::error",
        "MEDIUM": "::warning",
        "LOW": "::notice"
    }

    annotation_type = severity_map.get(severity, "::notice")
    title = f"Skylos {rule_id}"

    return f"{annotation_type} file={file_path},line={line_num},title={title}::{message}"

def _capture_annotations(result):
    output_buffer = io.StringIO()

    with redirect_stdout(output_buffer):
        _emit_github_annotations(result)

    captured_output = output_buffer.getvalue().strip()
    if not captured_output:
        return []

    return captured_output.splitlines()

class TestGitHubAnnotations:
    def test_danger_findings(self):
        findings_data = {
            "danger": [
                {
                    "rule_id": "SKY-D211",
                    "severity": "HIGH",
                    "file": "app.py",
                    "line": 10,
                    "message": "SQL injection detected",
                }
            ],
        }
        lines = _capture_annotations(findings_data)
        assert len(lines) == 1
        expected_line = "::error file=app.py,line=10,title=Skylos SKY-D211::SQL injection detected"
        assert lines[0] == expected_line

    def test_severity_mapping(self):
        analysis_results = {
            "quality": [
                {
                    "rule_id": "SKY-Q301",
                    "severity": "MEDIUM",
                    "file": "a.py",
                    "line": 5,
                    "message": "Complex",
                },
                {
                    "rule_id": "SKY-Q302",
                    "severity": "LOW",
                    "file": "b.py",
                    "line": 8,
                    "message": "Long func",
                },
            ],
        }
        lines = _capture_annotations(analysis_results)
        assert "::warning" in lines[0]
        assert "::notice" in lines[1]

    def test_dead_code_annotations(self):
        code_analysis = {
            "unused_functions": [
                {"name": "old_func", "file": "app.py", "line": 42},
            ],
            "unused_imports": [
                {"name": "os", "file": "app.py", "line": 1},
            ],
        }
        lines = _capture_annotations(code_analysis)
        assert len(lines) == 2
        assert "::warning" in lines[0]
        assert "Unused function: old_func" in lines[0]
        assert "Unused import: os" in lines[1]

    def test_empty_result(self):
        empty_data = {}
        lines = _capture_annotations(empty_data)
        assert lines == [""] or lines == []

    def test_mixed_categories(self):
        combined_results = {
            "danger": [
                {
                    "rule_id": "SKY-D201",
                    "severity": "CRITICAL",
                    "file": "x.py",
                    "line": 1,
                    "message": "eval",
                },
            ],
            "secrets": [
                {
                    "rule_id": "SKY-S101",
                    "severity": "HIGH",
                    "file": "y.py",
                    "line": 2,
                    "message": "API key",
                },
            ],
            "unused_classes": [
                {"name": "OldClass", "file": "z.py", "line": 3},
            ],
        }
        lines = _capture_annotations(combined_results)
        assert len(lines) == 3

        # Verify annotation types based on severity
        assert lines[0].startswith("::error")  # CRITICAL -> error
        assert lines[1].startswith("::error")  # HIGH -> error
        assert "Unused class: OldClass" in lines[2]

import functools
import importlib.metadata
import logging
import os
import pathlib
import sys
import zipfile
import zipimport
from typing import Iterator, List, Optional, Sequence, Set, Tuple
from pip._vendor.packaging.utils import NormalizedName, canonicalize_name
from pip._internal.metadata.base import BaseDistribution, BaseEnvironment
from pip._internal.models.wheel import Wheel
from pip._internal.utils.deprecation import deprecated
from pip._internal.utils.filetypes import WHEEL_EXTENSION
from ._compat import BadMetadata, BasePath, get_dist_name, get_info_location
from ._dists import Distribution

logger = logging.getLogger(__name__)

def _is_wheel_file(path: str) -> bool:
    """Check if a path points to a valid wheel file."""
    if not path.endswith(WHEEL_EXTENSION):
        return False
    if not os.path.isfile(path):
        return False
    if not Wheel.wheel_file_re.match(os.path.basename(path)):
        return False
    return zipfile.is_zipfile(path)

class _PackageFinder:
    """Finder to locate installed packages.

    This class ensures only one distribution per package name is returned,
    respecting precedence rules (higher precedence paths override lower ones).
    """

    MatchResult = Tuple[importlib.metadata.Distribution, Optional[BasePath]]

    def __init__(self) -> None:
        self._seen_packages: Set[NormalizedName] = set()

    def _discover_impl(self, search_path: str) -> Iterator[MatchResult]:
        """Search for distributions in the given path."""
        # Skip wheel files as they don't represent installed distributions
        if _is_wheel_file(search_path):
            return

        # Iterate through distributions found at this specific location
        for dist in importlib.metadata.distributions(path=[search_path]):
            info_dir = get_info_location(dist)
            try:
                raw_package_name = get_dist_name(dist)
            except BadMetadata as err:
                logger.warning("Skipping %s due to %s", info_dir, err.reason)
                continue

            normalized_name = canonicalize_name(raw_package_name)
            if normalized_name in self._seen_packages:
                continue

            self._seen_packages.add(normalized_name)
            yield dist, info_dir

    def locate(self, directory: str) -> Iterator[BaseDistribution]:
        """Find distributions in a directory or ZIP archive."""
        for dist, info_dir in self._discover_impl(directory):
            base_path = None if info_dir is None else info_dir.parent
            yield Distribution(dist, info_dir, base_path)

    def locate_via_link(self, directory: str) -> Iterator[BaseDistribution]:
        """Process .egg-link files and return distributions from linked locations.

        Reads the first non-empty line of each .egg-link file as a relative path
        to another directory containing distributions.
        """
        dir_path = pathlib.Path(directory)
        if not dir_path.is_dir():
            return

        for link_file in dir_path.iterdir():
            if link_file.suffix != ".egg-link":
                continue

            with open(link_file) as f:
                lines = (line.strip() for line in f)
                target_relative = next((line for line in lines if line), "")

            if not target_relative:
                continue

            linked_path = str(dir_path.joinpath(target_relative))
            for dist, info_dir in self._discover_impl(linked_path):
                yield Distribution(dist, info_dir, dir_path)

    def _find_legacy_eggs_in_directory(self, directory: str) -> Iterator[BaseDistribution]:
        from pip._vendor.pkg_resources import find_distributions
        from pip._internal.metadata import pkg_resources as legacy_metadata

        with os.scandir(directory) as entries:
            for entry in entries:
                if not entry.name.endswith(".egg"):
                    continue
                for dist in find_distributions(entry.path):
                    yield legacy_metadata.Distribution(dist)

    def _find_legacy_eggs_in_archive(self, archive_path: str) -> Iterator[BaseDistribution]:
        from pip._vendor.pkg_resources import find_eggs_in_zip
        from pip._internal.metadata import pkg_resources as legacy_metadata

        try:
            importer = zipimport.zipimporter(archive_path)
        except zipimport.ZipImportError:
            return

        for dist in find_eggs_in_zip(importer, archive_path):
            yield legacy_metadata.Distribution(dist)

    def locate_eggs(self, location: str) -> Iterator[BaseDistribution]:
        """Find egg distributions in a location using legacy mechanisms.

        This method supports both directories and ZIP archives containing eggs.
        Note: This functionality uses the older pkg_resources backend and should
        eventually be removed when egg support is fully deprecated.
        """
        if os.path.isdir(location):
            yield from self._find_legacy_eggs_in_directory(location)
        if zipfile.is_zipfile(location):
            yield from self._find_legacy_eggs_in_archive(location)

@functools.lru_cache(maxsize=None)
def _warn_about_egg_loading(path: Optional[str]) -> None:
    """Issue deprecation warning once per egg path."""
    deprecated(
        reason=f"Loading egg from {path} is deprecated.",
        replacement="Use pip for package installation instead.",
        gone_in="24.3",
        issue=12330,
    )

class PackageEnvironment(BaseEnvironment):
    def __init__(self, search_paths: Sequence[str]) -> None:
        self._search_paths = search_paths

    @classmethod
    def create_default(cls) -> BaseEnvironment:
        return cls(sys.path)

    @classmethod
    def create_from_paths(cls, paths: Optional[List[str]]) -> BaseEnvironment:
        effective_paths = sys.path if paths is None else paths
        return cls(effective_paths)

    def _generate_distributions(self) -> Iterator[BaseDistribution]:
        finder = _PackageFinder()
        for path in self._search_paths:
            # Standard distributions
            yield from finder.locate(path)

            # Legacy egg distributions
            for dist in finder.locate_eggs(path):
                _warn_about_egg_loading(dist.location)
                yield dist

            # Distributions via egg-link files (lowest precedence)
            yield from finder.locate_via_link(path)

    def get_package(self, name: str) -> Optional[BaseDistribution]:
        """Retrieve a specific package by name."""
        for dist in self.iter_all_distributions():
            if dist.canonical_name == canonicalize_name(name):
                return dist
        return None

# Certificate Auto-Renewal Service
# Automatically renews certificates before they expire.
"""
This module provides functionality for automatically renewing digital certificates
based on configurable policies and thresholds.
"""
from datetime import datetime, timedelta
from models import db, Certificate, CA, SystemConfig, AuditLog
from services.ca_service import CAService
import logging

logger = logging.getLogger(__name__)

class CertificateRenewalHandler:
    """Handles automatic certificate renewal operations"""

    @staticmethod
    def fetch_renewal_settings():
        """Retrieve current auto-renewal configuration settings"""
        config = {
            'active': False,
            'advance_days': 30,
            'eligible_sources': ['scep', 'acme', 'est'],
            'send_success_alerts': True,
            'send_failure_alerts': True,
        }

        # Load enabled status from database
        status_record = SystemConfig.query.filter_by(key='auto_renewal_enabled').first()
        if status_record:
            config['active'] = status_record.value == 'true'

        # Load advance notice period
        days_record = SystemConfig.query.filter_by(key='auto_renewal_days').first()
        if days_record:
            config['advance_days'] = int(days_record.value)

        # Load eligible renewal sources
        sources_record = SystemConfig.query.filter_by(key='auto_renewal_sources').first()
        if sources_record:
            import json
            config['eligible_sources'] = json.loads(sources_record.value)

        return config

    @staticmethod
    def update_renewal_settings(settings: dict):
        """Update auto-renewal configuration in the database"""
        import json

        for setting_name, value in settings.items():
            db_key = f'auto_renewal_{setting_name}'

            if setting_name == 'active':
                db_value = 'true' if value else 'false'
            elif setting_name == 'eligible_sources':
                db_value = json.dumps(value)
            else:
                db_value = str(value)

            existing_entry = SystemConfig.query.filter_by(key=db_key).first()
            if existing_entry:
                existing_entry.value = db_value
            else:
                db.session.add(SystemConfig(key=db_key, value=db_value))

        db.session.commit()

    @staticmethod
    def find_certificates_needing_renewal():
        """Identify certificates that qualify for automatic renewal"""
        settings = CertificateRenewalHandler.fetch_renewal_settings()
        if not settings['active']:
            return []

        cutoff_date = datetime.utcnow() + timedelta(days=settings['advance_days'])

        qualifying_certs = Certificate.query.filter(
            Certificate.status.in_(['valid', 'active']),
            Certificate.not_after != None,
            Certificate.not_after <= cutoff_date,
            Certificate.source.in_(settings['eligible_sources'])
        ).all()

        return qualifying_certs

    @staticmethod
    def process_certificate_renewal(cert: Certificate) -> tuple:
        """
        Process renewal of a single certificate.

        Returns:
            (success: bool, new_certificate_id or error_message: int|str)
        """
        try:
            # Locate the issuing Certificate Authority
            ca = CA.query.filter_by(id=cert.ca_id).first()
            if not ca:
                return False, "Certificate Authority not found"

            # Verify CA is still valid
            if ca.not_after and ca.not_after < datetime.utcnow():
                return False, "Issuing Certificate Authority has expired"

            # Determine validity period for new certificate
            if cert.not_before and cert.not_after:
                original_duration = (cert.not_after - cert.not_before).days
            else:
                original_duration = 365

            # Prepare CSR for renewal
            from cryptography import x509
            from cryptography.hazmat.backends import default_backend

            if cert.csr:
                # Decode and load original CSR
                import base64
                csr_pem = base64.b64decode(cert.csr).decode()
                csr = x509.load_pem_x509_csr(csr_pem.encode(), default_backend())
            else:
                return False, "Original CSR unavailable for renewal"

            # Generate new certificate with same parameters
            new_cert_pem, serial = CAService.sign_csr_from_crypto(
                ca=ca,
                csr=csr,
                validity_days=original_duration,
                source=f'{cert.source}-renewal'
            )

            # Retrieve newly created certificate record
            new_cert = Certificate.query.filter_by(serial_number=serial).first()

            # Update status of old certificate
            cert.status = 'superseded'
            cert.superseded_by = new_cert.id if new_cert else None

            # Record audit event
            log_entry = AuditLog(
                action='certificate.auto_renewed',
                resource_type='certificate',
                resource_id=new_cert.id if new_cert else None,
                resource_name=cert.common_name,
                details=f'Auto-renewed cert {cert.id}, new cert {new_cert.id if new_cert else "unknown"}'
            )
            db.session.add(log_entry)
            db.session.commit()

            logger.info(f"Auto-renewed certificate {cert.id} -> {new_cert.id if new_cert else 'unknown'}")
            return True, new_cert.id if new_cert else 0

        except Exception as e:
            logger.error(f"Auto-renewal failed for cert {cert.id}: {e}")
            return False, str(e)

    @staticmethod
    def execute_auto_renewal_process():
        """
        Execute auto-renewal workflow for all qualified certificates.
        Intended to be invoked by the scheduled task runner.
        """
        settings = CertificateRenewalHandler.fetch_renewal_settings()
        if not settings['active']:
            logger.debug("Auto-renewal functionality is currently disabled")
            return {'processed': 0, 'errors': 0, 'bypassed': 0}

        candidates = CertificateRenewalHandler.find_certificates_needing_renewal()

        results = {'processed': 0, 'errors': 0, 'bypassed': 0, 'error_details': []}

        for cert in candidates:
            # Skip certificates already in renewal process
            if cert.status == 'renewing':
                results['bypassed'] += 1
                continue

            # Lock certificate for processing
            cert.status = 'renewing'
            db.session.commit()

            success, outcome = CertificateRenewalHandler.process_certificate_renewal(cert)

            if success:
                results['processed'] += 1
            else:
                results['errors'] += 1
                results['error_details'].append({
                    'cert_id': cert.id,
                    'common_name': cert.common_name,
                    'error': outcome
                })
                # Restore original status on failure
                cert.status = 'valid'
                db.session.commit()

        logger.info(f"Auto-renewal cycle completed: {results['processed']} renewed, {results['errors']} errors")

        # Trigger notifications based on configuration
        if settings.get('send_success_alerts') and results['processed'] > 0:
            CertificateRenewalHandler._notify_success(results)

        if settings.get('send_failure_alerts') and results['errors'] > 0:
            CertificateRenewalHandler._notify_errors(results)

        return results

    @staticmethod
    def _notify_success(stats: dict):
        """Send notification about successful certificate renewals"""
        from services.email_service import EmailService

        recipient_config = SystemConfig.query.filter_by(key='auto_renewal_notify_emails').first()
        if not recipient_config:
            return

        import json
        email_list = json.loads(recipient_config.value)

        for address in email_list:
            try:
                EmailService.send_email(
                    to=address,
                    subject=f'UCM: {stats["processed"]} certificates auto-renewed',
                    body=f'The following {stats["processed"]} certificates were automatically renewed.',
                    html=f'<p>The following {stats["processed"]} certificates were automatically renewed.</p>'
                )
            except Exception as e:
                logger.error(f"Failed to send renewal notification: {e}")

    @staticmethod
    def _notify_errors(stats: dict):
        """Send notification about failed certificate renewals"""
        from services.email_service import EmailService

        recipient_config = SystemConfig.query.filter_by(key='auto_renewal_notify_emails').first()
        if not recipient_config:
            return

        import json
        email_list = json.loads(recipient_config.value)

        error_summary = '\n'.join([
            f"- {e['common_name']} (ID: {e['cert_id']}): {e['error']}"
            for e in stats.get('error_details', [])
        ])

        for address in email_list:
            try:
                EmailService.send_email(
                    to=address,
                    subject=f'UCM: {stats["errors"]} certificate renewals FAILED',
                    body=f'The following certificate renewals failed:\n\n{error_summary}',
                    html=f'<p>The following certificate renewals failed:</p><pre>{error_summary}</pre>'
                )
            except Exception as e:
                logger.error(f"Failed to send failure notification: {e}")

# Scheduled task entry point
def trigger_auto_renewal_job():
    """Entry point for scheduled auto-renewal execution"""
    return CertificateRenewalHandler.execute_auto_renewal_process()

import logging
