from typing import Dict

def format_log_entry(data: Dict, step_value) -> str:
    # Start building the log message with step info
    parts = [f"step:{step_value}"]

    # Iterate through dictionary items
    for key, value in data.items():
        # Only include numeric values with 3 decimal places
        if isinstance(value, (int, float)):
            parts.append(f"{key}:{value:.3f}")

    # Join all parts with " - " separator
    return " - ".join(parts)

