        result = []
        for name, _ in transforms.items():
            decomposed_info = self.weight_mapper.policy_decompose_param_1_to_n_for_sync(name)

            if decomposed_info:
                for decomposed_name, _ in decomposed_info:
                    if decomposed_name in transforms:
                        result.append((decomposed_name, transforms[decomposed_name]))
                    elif self.weight_mapper.get_transform_func_from_local_param_for_sync(decomposed_name) is not None:
                        transform = self.weight_mapper.get_transform_func_from_local_param_for_sync(decomposed_name)
                        direct_view = transforms[name]

