    @classmethod
    def register(cls, x, default_weight_mapper_cls, *, allow_override: bool = False, default_data_packer_cls=None):
        def decorator(cls: Type) -> Type:
            model_types = cls.supported_model_types()
            if isinstance(model_types, str):
                model_types = [model_types]
            for model_type in model_types:
                if (
                    not allow_override
                    and model_type in cls._MODEL_REGISTRY
                    and cls._MODEL_REGISTRY[model_type] != cls
                ):
                    raise ValueError(f"Model {model_type} is already registered.")
                cls.register_model(cls, default_weight_mapper_cls, data_packer_cls=default_data_packer_cls)
            return cls
        return decorator

