class WeightMapper(ABC):
    _WEIGHT_MAPPER_BACKEND_SUPPORTED = ["vllm", "trtllm"]
    _MODEL_WEIGHT_MAPPER_REGISTRY: Dict[str, Tuple[Type["WeightMapper"], int]] = {}

    def __init__(self, hf_config: AutoConfig):
        logger.info(f"WeightMapper: {type(self).__name__} is being initialized.")
        self.config = hf_config
        self.backend = "vllm"

    @torch.no_grad()
    def policy_map_local_key_for_export_tensor(self, name, param):
        yield name, param

    def rollout_prepare_recv(self, rollout_model: torch.nn.Module) -> Tuple[Dict[str, torch.Tensor], List[List[Tuple[str, int]]]]:
        recv_key_n_shape_list = []
        rollout_weight_inplace_view_map = {}
        self.map_to_unsplited_weight_name = {}

        for param_name, param in rollout_model.named_parameters():
            unsplited_weight_name = self.rollout_map_local_key_to_hf_key(param_name)
            group_keys_n_params = self.rollout_split_local_key_n_param_to_hf_key_n_param(param_name, param)
            recv_key_n_shape_list.append([(k, w.ndim) for k, w in group_keys_n_params])
            rollout_weight_inplace_view_map.update({k: w for k, w in group_keys_n_params})
            if len(group_keys_n_params) > 1:
                self.map_to_unsplited_weight_name.update({k: unsplited_weight_name for k, w in group_keys_n_params})

        return rollout_weight_inplace_view_map, recv_key_n_shape_list

    def rollout_split_local_key_n_param_to_hf_key_n_param(self, param_name: str, param: torch.Tensor) -> List[Tuple[str, torch.Tensor]]:
        raise NotImplementedError

    def policy_map_local_key_to_hf_key(self, name: str) -> str:
        return name

    def rollout_map_local_key_to_hf_key(self, name: str) -> str:
        return name

    def get_unsplited_weight_name(self, weight_key: str) -> str:
        assert hasattr(self, "map_to_unsplited_weight_name"), (
            "map_to_unsplited_weight_name is not set. Please call rollout_prepare_recv first."
        )
        if hasattr(self, "map_to_unsplited_weight_name") and weight_key in self.map_to_unsplited_weight_name:
            return self.map_to_unsplited_weight_name[weight_key]
        else:
            return weight_key

    def get_policy_parallelism_strategy(self):
        return []

    def get_rollout_parallelism_strategy(self):
        return []

    @classmethod
    def register_class(cls, reg_key: Union[str, List[str]], default_weight_mapper_cls: Type["WeightMapper"], *, allow_override: bool = False):
        if isinstance(reg_key, str):
            reg_key = [reg_key]
        for model_type in reg_key:
            if (
                not allow_override
                and model_type in cls._MODEL_WEIGHT_MAPPER_REGISTRY
                and cls._MODEL_WEIGHT_MAPPER_REGISTRY[model_type] != default_weight_mapper_cls
            ):
                raise ValueError(f"WeightMapper for '{model_type}' is already registered.")
            cls._MODEL_WEIGHT_MAPPER_REGISTRY[model_type] = (default_weight_mapper_cls,)

    def set_transform_func_from_local_param_for_sync(self, name: str, transform: Callable):
        if not hasattr(self, "policy_map_param_to_transform_func_for_sync"):
            self.policy_map_param_to_transform_func_for_sync = {}
        self.policy_map_param_to_transform_func_for_sync[name] = transform

    def get_transform_func_from_local_param_for_sync(self, name: str) -> Optional[Callable]:
        if not hasattr(self, "policy_map_param_to_transform_func_for_sync"):
            return None
        return self.policy_map_param_to_transform_func_for_sync.get(name, None)

    @classmethod
    def get_weight_mapper(cls, model_type: str) -> Type["WeightMapper"]:
        if model_type not in cls._MODEL_WEIGHT_MAPPER_REGISTRY:
            raise ValueError(f"ModelType '{model_type}' is not supported now.")
        return cls._MODEL_WEIGHT_MAPPER_REGISTRY[model_type][0]

    def policy_pre_P2R_gather_required_for_sync(self, name: str) -> bool:
        return False

    @cached_property
    def packed_modules_mapping(self) -> Dict[str, List[str]]:
        return {
            "qkv": ["q", "k", "v"],
            "gate_up_proj": ["gate_proj", "up_proj"],
            "qkv_proj": ["q_proj", "k_proj", "v_proj"],
        }

    def policy_decompose_param_1_to_n_for_sync(self, name):
        return []

    def setup_rollout_backend(self, backend: str):
        self.backend = backend
        if backend not in self._WEIGHT_MAPPER_BACKEND_SUPPORTED:
            raise ValueError(f"Backend {backend} is not supported by weight mapper.")

    def rollout_prepare_recv_filter(self, key: str) -> bool:
        if "_scale" in key:
            return True
        return False

    def cosmos_rollout_prepare_recv(self, rollout_model: Any) -> Tuple[Dict[str, torch.Tensor], List[List[Tuple[str, int]]]]:
        rollout_weight_inplace_view_map, recv_key_n_shape_list = self.rollout_prepare_recv(rollout_model)
        final_rollout_weight_inplace_view_map = {}
        final_recv_key_n_shape_list = []

        for key, value in rollout_weight_inplace_view_map.items():
            if self.rollout_prepare_recv_filter(key):
                continue
            final_rollout_weight_inplace_view_map[key] = value

        total_count = 0
        for group_keys in recv_key_n_shape_list:
            group_key = group_keys[0][0]
            if self.rollout_prepare_recv_filter(group_key):
                continue
            final_recv_key_n_shape_list.append(group_keys)
            total_count += len(group_keys)

        assert len(final_rollout_weight_inplace_view_map) == total_count, (
            f"{len(final_rollout_weight_inplace_view_map)} != {total_count} in rollout recv instructions generation"
        )
        return final_rollout_weight_inplace_view_map, final_recv_key_n_shape_list

    def update_tensor_view(self, tensor_view: torch.Tensor, recv_tensor: torch.Tensor, inst_dest_name: str, **kwargs):
        tmp_recv_tensor = recv_tensor.to(tensor_view.dtype)
        tensor_view.copy_(tmp_recv_tensor)

import math
from abc import ABC, abstractmethod
from typing import Optional
from fitter import DataFitter
from util import get_global_config

class ComponentNode(ABC):
    def __init__(self, role: str):
        self.role = role
        self.config = get_global_config()
        self.max_world_size = self.config.components_config[role].max_world_size
        self.model_parallel_size = self.config.components_config[
            role
        ].model_parallel_size
        self.collocated_cost_total = self.config.components_config[
            role
        ].collocated_cost_total
        self.collocated_cost_per_group_batch = (
            self.collocated_cost_total / self.config.rollout_batch_size
        )
        self._gpu_to_cost_map: dict[int, float] = {
            self.max_world_size: self.collocated_cost_per_group_batch
        }
        self._build_profile_data()

    @abstractmethod
    def _build_profile_data(self): ...

    def _is_valid_gpu_count(self, gpu_count: int) -> bool:
        return gpu_count % self.model_parallel_size == 0

    def estimate_cost(self, gpu_count: int) -> Optional[float]:
        return self._gpu_to_cost_map.get(gpu_count, None)

    def __str__(self):
        return self.role

    def __repr__(self):
        return self.__str__()

    def __hash__(self):
        return hash(self.__str__())

    def __eq__(self, other):
        if not isinstance(other, ComponentNode):
            return False
        return hash(self) == hash(other)


class MegatronNode(ComponentNode):
    """The MegatronNode denotes Actor or Inference which backend is Megatron."""
    def __init__(self, role: str, supported_gpu_counts: list[int] = []):
        self.supported_gpu_counts = supported_gpu_counts
        super().__init__(role)

    def _build_profile_data(self):
        for gpu_count in range(1, self.max_world_size):
            if not self._is_valid_gpu_count(gpu_count):
                continue
            self._gpu_to_cost_map[gpu_count] = self._compute_cost(gpu_count)

    def _is_valid_gpu_count(self, gpu_count: int) -> bool:
        if not self.supported_gpu_counts:
            return super()._is_valid_gpu_count(gpu_count)
        return gpu_count in self.supported_gpu_counts

    def _compute_cost(self, gpu_count: int) -> float:
        """Performance model for MegatronNode.
        1. base_cost = self.collocated_cost_per_group_batch * scale_factor
        2. efficiency_ratio = 1 + min(0.9, max(scale_factor / 10, 0.1))
        3. final_cost = base_cost / efficiency_ratio
        """
        scale_factor = self.max_world_size / gpu_count
        base_cost = self.collocated_cost_per_group_batch * scale_factor
        efficiency_ratio = 1 + min(0.9, max(scale_factor / 10, 0.1))
        final_cost = base_cost / efficiency_ratio
        return final_cost


class RolloutNode(ComponentNode):
    def __init__(
        self,
    ):
        super().__init__("rollout")

    def _build_profile_data(self):
        queue_wait_ratio = 0.9 if self.config.max_running_requests >= 128 else 1.0
        self._performance_params = {
            "max_active_requests_without_queue": math.ceil(
                self.config.max_running_requests * queue_wait_ratio
            )
        }
        for gpu_count in range(1, self.max_world_size):
            if not self._is_valid_gpu_count(gpu_count):
                continue
            instance_count = gpu_count // self.model_parallel_size
            capacity = (
                instance_count * self._performance_params["max_active_requests_without_queue"]
            )
            required_capacity = self.config.rollout_batch_size * self.config.group_size
            if capacity >= required_capacity:
                self._gpu_to_cost_map[gpu_count] = self.collocated_cost_per_group_batch
            else:
                self._gpu_to_cost_map[gpu_count] = (
                    self.collocated_cost_per_group_batch
                    * (self.max_world_size / gpu_count)
                )


class EnvProfiler:
    def __init__(
        self,
        profile_data: dict[int, float],
        total_env_num: int,
        max_envs_per_instance: int = -1,
    ):
        self.data_fitter = DataFitter(profile_data)
        self.total_env_num = total_env_num
        if max_envs_per_instance == -1:
            self.max_envs_per_instance = max(profile_data.keys())
        else:
            self.max_envs_per_instance = max_envs_per_instance

    def _get_single_gpu_env_cost(self, envs_per_instance: int) -> float:
        return self.data_fitter.get_value(envs_per_instance)

    def profile(self, instance_count: int, enforce_alignment: bool) -> Optional[float]:
        if enforce_alignment and self.total_env_num % instance_count != 0:
            return None
        if self.total_env_num // instance_count > self.max_envs_per_instance:
            return None
        return self._get_single_gpu_env_cost(self.total_env_num // instance_count)


class EnvNode(ComponentNode):
    def __init__(self, profiler: EnvProfiler):
        self.role = "env"
        self.profiler = profiler
        self._gpu_to_cost_map: dict[int, float] = {}
        self._build_profile_data()

    def _build_profile_data(self):
        config = get_global_config()
        self._gpu_to_cost_map.clear()
        for gpu_count in range(1, config.total_gpus + 1):
            self._gpu_to_cost_map[gpu_count] = self.profiler.profile(
                instance_count=gpu_count, enforce_alignment=True
            )


class EnvRolloutNode(ComponentNode):
    """Rollout Node in embodiment task."""
    def __init__(
        self,
        profiler: EnvProfiler,
        model_parallel_size: int,
    ):
        self.role = "env_rollout"
        self.profiler = profiler
        self.model_parallel_size = model_parallel_size
        self._gpu_to_cost_map: dict[int, float] = {}
        self._build_profile_data()

    def _build_profile_data(self):
        config = get_global_config()
        for gpu_count in range(1, config.total_gpus + 1):
            if gpu_count % self.model_parallel_size != 0:
                continue
            self._gpu_to_cost_map[gpu_count] = self.profiler.profile(
                instance_count=gpu_count // self.model_parallel_size, enforce_alignment=False
            )


class SccNode(ComponentNode):
    """The SccNode denotes a strongly connected component (SCC) Node.
    Assert nodes is sorted by execute order.
    """
    def __init__(self, nodes: list[ComponentNode]):
        self.nodes = nodes
        self.role = " - ".join([node.role for node in nodes])

    def _build_profile_data(self): ...

    def estimate_cost(self, gpu_count: int) -> Optional[float]:
        raise NotImplementedError("SccNode does not support direct cost estimation")

import asyncio
