except ImportError:
    AIOHTTP_AVAILABLE = False

class TerminalSession:
    """A terminal session for a WebSocket connection"""
    def __init__(self, terminal, ws):
        self.terminal = terminal
        self.ws = ws
        self.input_buffer = ""
        # Initialize completer
        from .completer import TerminalCompleter
        self.completer = TerminalCompleter(self.terminal.filesystem)
        self.completer.terminal = self.terminal

    async def transmit(self, data: str):
        """Transmit data to the WebSocket"""
        if self.ws and not self.ws.closed:
            await self.ws.send_str(data)

    def fetch_completions(self, text: str, line: str, cursor_pos: int) -> list:
        """Fetch completion suggestions for the given text
        Args:
            text: The word being completed
            line: The full command line
            cursor_pos: Cursor position in the line
        Returns:
            List of completion suggestions
        """
        # Determine if we're completing a command or a path
        before_cursor = line[:cursor_pos]
        # Check if we're at the beginning (completing command)
        if not before_cursor.strip() or before_cursor.strip() == text:
            # Complete command names
            return self.completer._complete_command(text)
        else:
            # Complete paths
            return self.completer._complete_path(text)

    async def process_command(self, command: str):
        """Execute a command and send output to WebSocket"""
        # Create a wrapper that has both text and binary interfaces
        class StreamBuffer:
            def __init__(self):
                self.text_stream = io.StringIO()
                self.byte_stream = io.BytesIO()
                # Create buffer attribute for binary writes
                self.buffer = self
            def write(self, data):
                if isinstance(data, bytes):
                    self.byte_stream.write(data)
                else:
                    self.text_stream.write(data)
                return len(data)
            def flush(self):
                pass
            def read_all(self):
                text = self.text_stream.getvalue()
                binary = self.byte_stream.getvalue()
                if binary:
                    try:
                        text += binary.decode('utf-8', errors='replace')
                    except:
                        pass
                return text
        # Capture stdout and stderr
        old_stdout = sys.stdout
        old_stderr = sys.stderr
        stdout_buffer = StreamBuffer()
        stderr_buffer = StreamBuffer()
        sys.stdout = stdout_buffer
        sys.stderr = stderr_buffer
        try:
            # Execute the command through terminal
            exit_code = self.terminal.run(command)
            # Get output
            stdout = stdout_buffer.read_all()
            stderr = stderr_buffer.read_all()
            # Send output to terminal (convert \n to \r\n for terminal)
            if stdout:
                stdout_formatted = stdout.replace('\n', '\r\n')
                await self.transmit(stdout_formatted)
            if stderr:
                # Send stderr in red color (convert \n to \r\n)
                stderr_formatted = stderr.replace('\n', '\r\n')
                await self.transmit(f'\x1b[31m{stderr_formatted}\x1b[0m')
            return exit_code
        except Exception as e:
            # Send error in red
            await self.transmit(f'\x1b[31mError: {str(e)}\x1b[0m\r\n')
            return 1
        finally:
            sys.stdout = old_stdout
            sys.stderr = old_stderr

class HTTPServer:
    """HTTP server for the web application"""
    def __init__(self, terminal, host='localhost', port=3000):
        if not AIOHTTP_AVAILABLE:
            raise ImportError(
                "aiohttp is required for web app server. "
                "Install with: uv sync --extra webapp"
            )
        self.terminal = terminal
        self.host = host
        self.port = port
        self.app = None
        self.runner = None
        self.active_sessions = {}  # WebSocket sessions
    async def handle_explorer_view(self, request):
        """Get directory structure for Explorer (optimized API)"""
        path = request.query.get('path', '/')
        try:
            # Use filesystem API directly for better performance
            entries = self.terminal.filesystem.list_directory(path)
            # Format entries for frontend
            files = []
            for entry in entries:
                name = entry.get('name', '')
                if name and name not in ['.', '..']:
                    # AGFS API returns 'isDir' instead of 'type'
                    is_dir = entry.get('isDir', False)
                    file_type = 'directory' if is_dir else 'file'
                    files.append({
                        'name': name,
                        'path': f"{path.rstrip('/')}/{name}" if path != '/' else f"/{name}",
                        'type': file_type,
                        'size': entry.get('size', 0),
                        'mtime': entry.get('mtime', ''),
                    })
            # Sort: directories first, then by name
            files.sort(key=lambda x: (x['type'] != 'directory', x['name'].lower()))
            return web.json_response({
                'path': path,
                'files': files
            })
        except Exception as e:
            return web.json_response(
                {'error': str(e), 'path': path},
                status=500
            )
    async def handle_file_listing(self, request):
        """List files in a directory (legacy, kept for compatibility)"""
        path = request.query.get('path', '/')
        try:
            # Use filesystem API directly
            entries = self.terminal.filesystem.list_directory(path)
            files = []
            for entry in entries:
                name = entry.get('name', '')
                if name and name not in ['.', '..']:
                    # AGFS API returns 'isDir' instead of 'type'
                    is_dir = entry.get('isDir', False)
                    file_type = 'directory' if is_dir else 'file'
                    files.append({
                        'name': name,
                        'type': file_type
                    })
            return web.json_response({'files': files})
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )
    async def handle_read_operation(self, request):
        """Read file contents"""
        path = request.query.get('path', '')
        if not path:
            return web.json_response(
                {'error': 'Path is required'},
                status=400
            )
        try:
            # Use StreamBuffer to handle both text and binary output
            class StreamBuffer:
                def __init__(self):
                    self.text_stream = io.StringIO()
                    self.byte_stream = io.BytesIO()
                    self.buffer = self
                def write(self, data):
                    if isinstance(data, bytes):
                        self.byte_stream.write(data)
                    else:
                        self.text_stream.write(data)
                    return len(data)
                def flush(self):
                    pass
                def read_all(self):
                    text = self.text_stream.getvalue()
                    binary = self.byte_stream.getvalue()
                    if binary:
                        try:
                            text += binary.decode('utf-8', errors='replace')
                        except:
                            pass
                    return text
            # Capture output
            old_stdout = sys.stdout
            old_stderr = sys.stderr
            stdout_buffer = StreamBuffer()
            stderr_buffer = StreamBuffer()
            sys.stdout = stdout_buffer
            sys.stderr = stderr_buffer
            try:
                self.terminal.run(f'cat {path}')
                content = stdout_buffer.read_all()
            finally:
                sys.stdout = old_stdout
                sys.stderr = old_stderr
            return web.json_response({'content': content})
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )
    async def handle_write_operation(self, request):
        """Write file contents"""
        try:
            data = await request.json()
            path = data.get('path', '')
            content = data.get('content', '')
            if not path:
                return web.json_response(
                    {'error': 'Path is required'},
                    status=400
                )
            # Write file using filesystem API directly
            try:
                # Convert content to bytes
                content_bytes = content.encode('utf-8')
                # Write to filesystem
                self.terminal.filesystem.save_file(path, content_bytes)
                return web.json_response({'success': True})
            except Exception as e:
                return web.json_response(
                    {'error': f'Failed to write file: {str(e)}'},
                    status=500
                )
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )
    async def handle_download_operation(self, request):
        """Download file contents (for binary/non-text files)"""
        path = request.query.get('path', '')
        if not path:
            return web.json_response(
                {'error': 'Path is required'},
                status=400
            )
        try:
            # Read file using filesystem API
            content = self.terminal.filesystem.load_file(path)
            # Get filename from path
            filename = path.split('/')[-1]
            # Determine content type based on extension
            import mimetypes
            content_type, _ = mimetypes.guess_type(filename)
            if content_type is None:
                content_type = 'application/octet-stream'
            # Return file with download headers
            return web.Response(
                body=content,
                headers={
                    'Content-Type': content_type,
                    'Content-Disposition': f'attachment; filename="{filename}"'
                }
            )
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )
    async def handle_copy_operation(self, request):
        """Copy file from source to target"""
        try:
            data = await request.json()
            source_path = data.get('sourcePath', '')
            target_path = data.get('targetPath', '')
            if not source_path or not target_path:
                return web.json_response(
                    {'error': 'Source and target paths are required'},
                    status=400
                )
            # Read source file
            content = self.terminal.filesystem.load_file(source_path)
            # Write to target
            self.terminal.filesystem.save_file(target_path, content)
            return web.json_response({'success': True})
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )
    async def handle_remove_operation(self, request):
        """Delete a file or directory"""
        try:
            data = await request.json()
            path = data.get('path', '')
            if not path:
                return web.json_response(
                    {'error': 'Path is required'},
                    status=400
                )
            # Delete using filesystem API
            self.terminal.filesystem.remove_file(path)
            return web.json_response({'success': True})
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )
    async def handle_upload_operation(self, request):
        """Upload a file to the filesystem"""
        try:
            reader = await request.multipart()
            directory = '/'
            file_data = None
            filename = None
            # Read multipart data
            async for field in reader:
                if field.name == 'directory':
                    directory = await field.text()
                elif field.name == 'file':
                    filename = field.filename
                    file_data = await field.read()
            if not file_data or not filename:
                return web.json_response(
                    {'error': 'No file provided'},
                    status=400
                )
            # Construct target path
            target_path = f"{directory.rstrip('/')}/{filename}" if directory != '/' else f"/{filename}"
            # Write file to filesystem
            self.terminal.filesystem.save_file(target_path, file_data)
            return web.json_response({
                'success': True,
                'path': target_path
            })
        except Exception as e:
            return web.json_response(
                {'error': str(e)},
                status=500
            )
    async def handle_websocket_connection(self, request):
        """Handle WebSocket connection for terminal"""
        ws = web.WebSocketResponse()
        await ws.prepare(request)
        # Create a new terminal session for this WebSocket
        session = TerminalSession(self.terminal, ws)
        session_id = id(ws)
        self.active_sessions[session_id] = session
        try:
            # Send welcome message
            from . import __version__
            await session.transmit(f'\x1b[32magfs-shell v{__version__} ready\x1b[0m\r\n')
            await session.transmit(f'\x1b[90mConnected to {self.terminal.server_url}\x1b[0m\r\n')
            await session.transmit('$ ')
            # Handle incoming messages
            async for msg in ws:
                if msg.type == web.WSMsgType.TEXT:
                    try:
                        data = json.loads(msg.data)
                        msg_type = data.get('type')
                        if msg_type == 'command':
                            command = data.get('data', '')
                            if command.strip():
                                # Execute command
                                exit_code = await session.process_command(command)
                                # Send new prompt
                                await session.transmit('$ ')
                            else:
                                # Empty command, just show prompt
                                await session.transmit('$ ')
                        elif msg_type == 'explorer':
                            # Get directory listing for Explorer
                            path = data.get('path', '/')
                            try:
                                entries = self.terminal.filesystem.list_directory(path)
                                # Format entries
                                files = []
                                for entry in entries:
                                    name = entry.get('name', '')
                                    if name and name not in ['.', '..']:
                                        # AGFS API returns 'isDir' instead of 'type'
                                        is_dir = entry.get('isDir', False)
                                        file_type = 'directory' if is_dir else 'file'
                                        files.append({
                                            'name': name,
                                            'path': f"{path.rstrip('/')}/{name}" if path != '/' else f"/{name}",
                                            'type': file_type,
                                            'size': entry.get('size', 0),
                                            'mtime': entry.get('modTime', ''),
                                        })
                                # Sort: directories first, then by name
                                files.sort(key=lambda x: (x['type'] != 'directory', x['name'].lower()))
                                await ws.send_json({
                                    'type': 'explorer',
                                    'path': path,
                                    'files': files
                                })
                            except Exception as e:
                                await ws.send_json({
                                    'type': 'explorer',
                                    'path': path,
                                    'error': str(e),
                                    'files': []
                                })
                        elif msg_type == 'complete':
                            # Tab completion request
                            text = data.get('text', '')
                            line = data.get('line', '')
                            cursor_pos = data.get('cursor_pos', len(line))
                            try:
                                completions = session.fetch_completions(text, line, cursor_pos)
                                # Send completions back to client
                                await ws.send_json({
                                    'type': 'completions',
                                    'completions': completions
                                })
                            except Exception as e:
                                # Send empty completions on error
                                await ws.send_json({
                                    'type': 'completions',
                                    'completions': []
                                })
                        elif msg_type == 'resize':
                            # Terminal resize event (can be used for future enhancements)
                            pass
                    except json.JSONDecodeError:
                        # If not JSON, treat as raw command
                        await session.transmit('\x1b[31mInvalid message format\x1b[0m\r\n$ ')
                    except Exception as e:
                        await session.transmit(f'\x1b[31mError: {str(e)}\x1b[0m\r\n$ ')
                elif msg.type == web.WSMsgType.ERROR:
                    print(f'WebSocket error: {ws.exception()}')
        finally:
            # Clean up session
            if session_id in self.active_sessions:
                del self.active_sessions[session_id]
        return ws
    async def handle_static_content(self, request):
        """Serve static files"""
        # Serve the built React app
        webapp_dir = Path(__file__).parent.parent / 'webapp' / 'dist'
        path = request.match_info.get('path', 'index.html')
        if path == '':
            path = 'index.html'
        file_path = webapp_dir / path
        # Handle client-side routing - serve index.html for non-existent paths
        if not file_path.exists() or file_path.is_dir():
            file_path = webapp_dir / 'index.html'
        if file_path.exists() and file_path.is_file():
            return web.FileResponse(file_path)
        else:
            return web.Response(text='Not found', status=404)
    async def setup_app(self):
        """Initialize the web application"""
        self.app = web.Application()
        # Setup CORS
        cors = aiohttp_cors.setup(self.app, defaults={
            "*": aiohttp_cors.ResourceOptions(
                allow_credentials=True,
                expose_headers="*",
                allow_headers="*",
            )
        })
        # API routes
        api_routes = [
            self.app.router.add_get('/api/files/list', self.handle_file_listing),
            self.app.router.add_get('/api/files/read', self.handle_read_operation),
            self.app.router.add_post('/api/files/write', self.handle_write_operation),
            self.app.router.add_get('/api/files/download', self.handle_download_operation),
            self.app.router.add_post('/api/files/copy', self.handle_copy_operation),
            self.app.router.add_post('/api/files/delete', self.handle_remove_operation),
            self.app.router.add_post('/api/files/upload', self.handle_upload_operation),
        ]
        # WebSocket route (no CORS needed)
        self.app.router.add_get('/ws/terminal', self.handle_websocket_connection)
        # Static files (serve React app)
        self.app.router.add_get('/', self.handle_static_content)
        self.app.router.add_get('/{path:.*}', self.handle_static_content)
        # Configure CORS for API routes only
        for route in api_routes:
            cors.add(route)
    async def launch(self):
        """Start the web server"""
        await self.setup_app()
        self.runner = web.AppRunner(self.app)
        await self.runner.setup()
        site = web.TCPSite(self.runner, self.host, self.port)
        await site.start()
        print(f'\n\x1b[32mWeb app server running at http://{self.host}:{self.port}\x1b[0m\n')
    async def shutdown(self):
        """Stop the web server"""
        # Close all WebSocket connections
        for session in list(self.active_sessions.values()):
            if session.ws and not session.ws.closed:
                await session.ws.close()
        if self.runner:
            await self.runner.cleanup()

def start_server(terminal, host='localhost', port=3000):
    """Run the web app server"""
    server = HTTPServer(terminal, host, port)
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    try:
        loop.run_until_complete(server.launch())
        loop.run_forever()
    except KeyboardInterrupt:
        print('\n\x1b[33mShutting down...\x1b[0m')
    finally:
        loop.run_until_complete(server.shutdown())
        loop.close()

from collections.abc import Mapping
from typing import (
    Any,
    Callable,
    ClassVar,
    Generic,
    Literal,
    TypeAlias,
    TypeVar,
)
from abc import ABC, abstractmethod
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes


# Alias for factory function type: config + channel -> tool instance
ToolFactory: TypeAlias = Callable[[BaseToolConfig, ChannelConfig], "StatGptTool"]


class ToolFactoryMap(Mapping):
    """A read-only registry mapping tool types to their factory classes."""

    def __init__(self) -> None:
        self._registry: dict[ToolTypes, type["StatGptTool"]] = {}

    def register(self, tool_type: ToolTypes, factory_class: type["StatGptTool"]) -> None:
        if not issubclass(factory_class, StatGptTool):
            raise TypeError(f"{factory_class!r} must inherit from {StatGptTool.__name__}")
        if tool_type in self._registry:
            existing = self._registry[tool_type]
            raise RuntimeError(
                f"Duplicate registration attempt: {tool_type!r} already bound to {existing.__name__}"
            )
        self._registry[tool_type] = factory_class

    def get_factory(self, key: ToolTypes) -> type["StatGptTool"]:
        try:
            return self._registry[key]
        except KeyError:
            available = list(self._registry.keys())
            raise KeyError(
                f"No factory registered for tool type {key!r}. "
                f"Ensure the corresponding tool module is imported.\n"
                f"Registered types: {available}"
            ) from None

    def __getitem__(self, key: ToolTypes) -> type["StatGptTool"]:
        return self.get_factory(key)

    def __iter__(self):
        return iter(self._registry)

    def __len__(self) -> int:
        return len(self._registry)


_registered_tools = ToolFactoryMap()


class ToolInputs(BaseModel):
    # Inherited context passed internally; hidden from LLM schema.
    inputs: Annotated[dict, InjectedToolArg] = Field(default_factory=dict)


ConfigT = TypeVar("ConfigT", bound=BaseToolConfig)


class StatGptTool(BaseTool, ABC, Generic[ConfigT]):
    response_format: Literal["content", "content_and_artifact"] = "content_and_artifact"
    tool_type: ClassVar[ToolTypes]

    def __init_subclass__(cls, tool_type: ToolTypes | None = None, **kwargs) -> None:
        super().__init_subclass__(**kwargs)

        # Skip registration for base class itself
        if cls.__bases__ == (StatGptTool,):
            return

        if tool_type is None:
            raise ValueError(f"Subclass {cls.__name__} must define 'tool_type' in __init_subclass__")
        if not isinstance(tool_type, ToolTypes):
            raise TypeError(f"'tool_type' must be an instance of {ToolTypes.__name__}")

        cls.tool_type = tool_type
        _registered_tools.register(tool_type, cls)

    def __init__(
        self,
        tool_config: ConfigT,
        channel_config: ChannelConfig,
        **kwargs,
    ):
        super().__init__(**kwargs)
        self._config = tool_config
        self._channel = channel_config

    @property
    def step_label(self) -> str:
        """Label used during tool invocation."""
        if label := self._config.details.stages_config.tool_call_name:
            return label
        display_name = self.name.replace("_", " ")
        return f"Executing {display_name}"

    @property
    def result_label(self) -> str:
        """Label used when displaying results."""
        if label := self._config.details.stages_config.tool_result_name:
            return label
        display_name = self.name.replace("_", " ")
        return f"Output from {display_name}"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """Synchronous run is intentionally unsupported."""
        raise NotImplementedError("Use async execution path only.")

    @abstractmethod
    async def _arun(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        """Async execution method that returns (result_str, artifact)."""
        raise NotImplementedError

    @classmethod
    def input_schema(cls, cfg: ConfigT) -> type[ToolInputs]:
        """Return the argument schema expected by this tool."""
        return ToolInputs

    @staticmethod
    def build(cfg: ConfigT, ch_cfg: ChannelConfig) -> "StatGptTool":
        """Instantiate a tool instance from its configuration."""
        factory_cls = _registered_tools[cfg.type]
        return factory_cls(
            tool_config=cfg,
            channel_config=ch_cfg,
            name=cfg.name,
            description=cfg.description,
            args_schema=factory_cls.input_schema(cfg),
        )

# Alternative implementation of SageMaker training arguments setup logic

import importlib.util
import json
import os
import warnings
from dataclasses import dataclass, field
import torch
from ..training_args import TrainingArguments
from ..utils import cached_property, is_sagemaker_dp_enabled, logging

logger = logging.get_logger(__name__)

def check_sagemaker_model_parallel_support():
    # Check if SM model parallel configuration is present and valid
    smp_config_str = os.getenv("SM_HP_MP_PARAMETERS", "{}")
    try:
        smp_config = json.loads(smp_config_str)
        if "partitions" not in smp_config:
            return False
    except (json.JSONDecodeError, TypeError):
        return False

    # Verify MPI-related framework parameters
    mpi_config_str = os.getenv("SM_FRAMEWORK_PARAMS", "{}")
    try:
        mpi_config = json.loads(mpi_config_str)
        if not mpi_config.get("sagemaker_mpi_enabled", False):
            return False
    except (json.JSONDecodeError, TypeError):
        return False

    # Confirm availability of smdistributed package
    return importlib.util.find_spec("smdistributed") is not None

# Initialize SageMaker Model Parallel if available
if check_sagemaker_model_parallel_support():
    import smdistributed.modelparallel.torch as smp
    smp.init()

@dataclass
class SageMakerTrainingArguments(TrainingArguments):
    mp_parameters: str = field(
        default="",
        metadata={"help": "SageMaker launcher parameter for MP-specific settings. Not used in SageMakerTrainer"},
    )

    def __post_init__(self):
        super().__post_init__()
        warnings.warn(
            "`SageMakerTrainingArguments` is deprecated and will be removed in v5 of Transformers. "
            "Please use `TrainingArguments` instead.",
            FutureWarning,
        )

    @cached_property
    def _setup_devices(self) -> "torch.device":
        logger.info("PyTorch: configuring device environment")

        # Handle case where distributed setup exists but local_rank isn't set properly
        if torch.distributed.is_available() and torch.distributed.is_initialized() and self.local_rank == -1:
            logger.warning(
                "Torch distributed process group is active, but local_rank is unset (-1). "
                "For DDP usage, launch with: python -m torch.distributed.launch"
            )

        # CPU-only mode
        if self.no_cuda:
            device = torch.device("cpu")
            self._n_gpu = 0
        # SageMaker Model Parallel setup
        elif check_sagemaker_model_parallel_support():
            local_rank = smp.local_rank()
            device = torch.device("cuda", local_rank)
            self._n_gpu = 1
        # SageMaker Data Parallel setup
        elif is_sagemaker_dp_enabled():
            import smdistributed.dataparallel.torch.torch_smddp  # noqa: F401
            torch.distributed.init_process_group(backend="smddp", timeout=self.ddp_timeout_delta)
            self.local_rank = int(os.getenv("SMDATAPARALLEL_LOCAL_RANK"))
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1
        # Single GPU or multi-GPU without distributed setup
        elif self.local_rank == -1:
            device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
            self._n_gpu = torch.cuda.device_count()
        # Standard distributed setup
        else:
            if not torch.distributed.is_initialized():
                torch.distributed.init_process_group(backend="nccl", timeout=self.ddp_timeout_delta)
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1

        # Set CUDA device explicitly when using GPU
        if device.type == "cuda":
            torch.cuda.set_device(device)

        return device

    @property
    def world_size(self):
        if check_sagemaker_model_parallel_support():
            return smp.dp_size()
        return super().world_size

    @property
    def place_model_on_device(self):
        return not check_sagemaker_model_parallel_support()

    @property
    def _no_sync_in_gradient_accumulation(self):
        return False

# Reimplementation of marker evaluation logic with equivalent functionality but different structure

import os
import platform
import sys
from typing import Any, Callable, Dict, List, Optional, Tuple, Union
from pip._vendor.pyparsing import (  # noqa: N817
    Forward,
    Group,
    Literal as L,
    ParseException,
    ParseResults,
    QuotedString,
    ZeroOrMore,
    stringEnd,
    stringStart,
)
from .specifiers import InvalidSpecifier, Specifier

__all__ = [
    "InvalidMarker",
    "UndefinedComparison",
    "UndefinedEnvironmentName",
    "Marker",
    "default_environment",
]

OperatorFunc = Callable[[str, str], bool]

class InvalidMarker(ValueError):
    """Raised when an invalid marker is encountered."""
    pass

class UndefinedComparison(ValueError):
    """Raised when an unsupported comparison operation is attempted."""
    pass

class UndefinedEnvironmentName(ValueError):
    """Raised when a referenced environment variable doesn't exist."""
    pass

class BaseNode:
    """Base class for all marker nodes."""
    def __init__(self, data: Any) -> None:
        self.data = data

    def __str__(self) -> str:
        return str(self.data)

    def __repr__(self) -> str:
        return f"<{self.__class__.__name__}('{self}')>"

    def to_string(self) -> str:
        raise NotImplementedError

class EnvKey(BaseNode):
    """Represents an environment variable key."""
    def to_string(self) -> str:
        return str(self)

class LiteralValue(BaseNode):
    """Represents a literal string value."""
    def to_string(self) -> str:
        return f'"{self}"'

class ComparisonOp(BaseNode):
    """Represents a comparison operator."""
    def to_string(self) -> str:
        return str(self)

# Define supported environment keys
ENVIRONMENT_KEYS = (
    L("implementation_version")
    | L("platform_python_implementation")
    | L("implementation_name")
    | L("python_full_version")
    | L("platform_release")
    | L("platform_version")
    | L("platform_machine")
    | L("platform_system")
    | L("python_version")
    | L("sys_platform")
    | L("os_name")
    | L("os.name")  # PEP-345
    | L("sys.platform")  # PEP-345
    | L("platform.version")  # PEP-345
    | L("platform.machine")  # PEP-345
    | L("platform.python_implementation")  # PEP-345
    | L("python_implementation")  # undocumented setuptools legacy
    | L("extra")  # PEP-508
)

# Define aliases for environment keys
KEY_ALIASES = {
    "os.name": "os_name",
    "sys.platform": "sys_platform",
    "platform.version": "platform_version",
    "platform.machine": "platform_machine",
    "platform.python_implementation": "platform_python_implementation",
    "python_implementation": "platform_python_implementation",
}

# Set up parsing actions
ENVIRONMENT_KEYS.setParseAction(
    lambda s, l, t: EnvKey(KEY_ALIASES.get(t[0], t[0]))
)

# Define comparison operators
COMPARISON_OPERATORS = (
    L("===") | L("==") | L(">=") | L("<=") | L("!=") | L("~=") | L(">") | L("<")
)

MARKER_OPERATORS = COMPARISON_OPERATORS | L("not in") | L("in")
MARKER_OPERATORS.setParseAction(lambda s, l, t: ComparisonOp(t[0]))

# Define quoted string values
MARKER_STRING_VALUE = QuotedString("'") | QuotedString('"')
MARKER_STRING_VALUE.setParseAction(lambda s, l, t: LiteralValue(t[0]))

# Boolean operators
BOOL_OPERATORS = L("and") | L("or")

# Marker components
MARKER_OPERAND = ENVIRONMENT_KEYS | MARKER_STRING_VALUE
MARKER_CONDITION = Group(MARKER_OPERAND + MARKER_OPERATORS + MARKER_OPERAND)
MARKER_CONDITION.setParseAction(lambda s, l, t: tuple(t[0]))

# Parser setup
LEFT_PAREN = L("(").suppress()
RIGHT_PAREN = L(")").suppress()
MARKER_EXPRESSION = Forward()
MARKER_ATOMIC = MARKER_CONDITION | Group(LEFT_PAREN + MARKER_EXPRESSION + RIGHT_PAREN)
MARKER_EXPRESSION << MARKER_ATOMIC + ZeroOrMore(BOOL_OPERATORS + MARKER_EXPRESSION)
MARKER_GRAMMAR = stringStart + MARKER_EXPRESSION + stringEnd

def _normalize_parse_result(results: Union[ParseResults, List[Any]]) -> List[Any]:
    """Recursively convert ParseResults to standard Python lists."""
    if isinstance(results, ParseResults):
        return [_normalize_parse_result(item) for item in results]
    else:
        return results

def _format_marker_expression(
    expr: Union[List[str], Tuple[BaseNode, ...], str], 
    first: Optional[bool] = True
) -> str:
    """Format marker expression as a string."""
    assert isinstance(expr, (list, tuple, str))

    # Handle nested single-item lists
    if (
        isinstance(expr, list)
        and len(expr) == 1
        and isinstance(expr[0], (list, tuple))
    ):
        return _format_marker_expression(expr[0])

    if isinstance(expr, list):
        formatted_parts = (_format_marker_expression(part, first=False) for part in expr)
        if first:
            return " ".join(formatted_parts)
        else:
            return "(" + " ".join(formatted_parts) + ")"
    elif isinstance(expr, tuple):
        return " ".join([node.to_string() for node in expr])
    else:
        return expr

# Operator implementations
MARKER_OPERATIONS: Dict[str, OperatorFunc] = {
    "in": lambda left, right: left in right,
    "not in": lambda left, right: left not in right,
    "<": lambda left, right: left < right,
    "<=": lambda left, right: left <= right,
    "==": lambda left, right: left == right,
    "!=": lambda left, right: left != right,
    ">=": lambda left, right: left >= right,
    ">": lambda left, right: left > right,
}

def _perform_comparison(left_val: str, op: ComparisonOp, right_val: str) -> bool:
    """Evaluate a comparison operation between two values."""
    try:
        spec = Specifier(op.to_string() + right_val)
        return spec.contains(left_val)
    except InvalidSpecifier:
        pass

    operation = MARKER_OPERATIONS.get(op.to_string())
    if operation is None:
        raise UndefinedComparison(f"Unsupported {op!r} operation on {left_val!r} and {right_val!r}.")
    return operation(left_val, right_val)

class MissingValue:
    """Sentinel class for missing environment values."""
    pass

_MISSING = MissingValue()

def _fetch_env_value(env: Dict[str, str], key: str) -> str:
    """Get a value from the environment dictionary."""
    result: Union[str, MissingValue] = env.get(key, _MISSING)
    if isinstance(result, MissingValue):
        raise UndefinedEnvironmentName(
            f"Environment variable {key!r} is not defined."
        )
    return result

def _process_markers(markers: List[Any], env: Dict[str, str]) -> bool:
    """Process markers and evaluate their truthiness."""
    condition_groups: List[List[bool]] = [[]]

    for marker in markers:
        assert isinstance(marker, (list, tuple, str))

        if isinstance(marker, list):
            condition_groups[-1].append(_process_markers(marker, env))
        elif isinstance(marker, tuple):
            left_node, op_node, right_node = marker

            if isinstance(left_node, EnvKey):
                left_val = _fetch_env_value(env, left_node.data)
                right_val = right_node.data
            else:
                left_val = left_node.data
                right_val = _fetch_env_value(env, right_node.data)

            condition_groups[-1].append(_perform_comparison(left_val, op_node, right_val))
        else:
            assert marker in ["and", "or"]
            if marker == "or":
                condition_groups.append([])

    return any(all(group) for group in condition_groups)

def _build_full_version(info: "sys._version_info") -> str:
    """Build a full version string from version info."""
    version_str = "{0.major}.{0.minor}.{0.micro}".format(info)
    release_level = info.releaselevel
    if release_level != "final":
        version_str += release_level[0] + str(info.serial)
    return version_str

def _get_default_environment() -> Dict[str, str]:
    """Generate the default environment mapping."""
    impl_version = _build_full_version(sys.implementation.version)
    impl_name = sys.implementation.name

    return {
        "implementation_name": impl_name,
        "implementation_version": impl_version,
        "os_name": os.name,
        "platform_machine": platform.machine(),
        "platform_release": platform.release(),
        "platform_system": platform.system(),
        "platform_version": platform.version(),
        "python_full_version": platform.python_version(),
        "platform_python_implementation": platform.python_implementation(),
        "python_version": ".".join(platform.python_version_tuple()[:2]),
        "sys_platform": sys.platform,
    }

class EnvironmentMarker:
    """Represents and evaluates PEP 508 environment markers."""
    def __init__(self, marker_text: str) -> None:
        try:
            self._parsed_markers = _normalize_parse_result(
                MARKER_GRAMMAR.parseString(marker_text)
            )
        except ParseException as error:
            raise InvalidMarker(
                f"Invalid marker: {marker_text!r}, parse error at "
                f"{marker_text[error.loc : error.loc + 8]!r}"
            )

    def __str__(self) -> str:
        return _format_marker_expression(self._parsed_markers)

    def __repr__(self) -> str:
        return f"<EnvironmentMarker('{self}')>"

    def check(self, env_override: Optional[Dict[str, str]] = None) -> bool:
        """
        Evaluate the marker against the current environment.

        Args:
            env_override: Optional dictionary to override environment values.

        Returns:
            Boolean result of evaluating the marker.
        """
        current_env = _get_default_environment()
        if env_override is not None:
            current_env.update(env_override)
        return _process_markers(self._parsed_markers, current_env)

"""
Quota governance system supporting per-user or per-cluster limits.
Each policy is defined via a _quota governor_ — either 'user_governor' or 'cluster_governor'.
Configuration includes:
1. `interval`: duration string (see PostgreSQL interval syntax)
2. `base_allowance`: initial token count at period start
3. `incremental_topup`: optional extra tokens added on period rollover

Use cases:
- Resetting quota weekly/monthly: set `base_allowance`, omit `incremental_topup`
- Daily top-up: set `incremental_topup`, leave `base_allowance` = 0

Both can be combined: final reset = base_allowance + incremental_topup.

Multiple governors may coexist—for instance:
- daily top-up of 100k tokens
- monthly reset to 10M tokens
"""

import datetime
from abc import ABCMeta, abstractmethod
from typing import Optional, Union
import sqlite3
import psycopg2
from log import get_logger
from models.config import SQLiteDatabaseConfiguration, PostgreSQLDatabaseConfiguration
from quota.connect_pg import connect_pg
from quota.connect_sqlite import connect_sqlite

logger = get_logger(__name__)


class UsageGovernor(metaclass=ABCMeta):
    """Base class for quota enforcement mechanisms."""

    @abstractmethod
    def remaining_quota(self, entity_id: str) -> int:
        """Fetch current available quota for an entity (user/service)."""

    @abstractmethod
    def clear_quota(self, entity_id: str) -> None:
        """Zero out remaining quota for specified entity."""

    @abstractmethod
    def refresh_quota(self, entity_id: str) -> None:
        """Apply periodic quota adjustments (reset/increase) for entity."""

    @abstractmethod
    def enforce_quota(self, entity_id: str = "") -> None:
        """Raise if insufficient quota remains for requested operation."""

    @abstractmethod
    def deduct_usage(
        self, input_tokens: int, output_tokens: int, entity_id: str = ""
    ) -> None:
        """Deduct token usage from entity’s quota."""

    def __init__(self) -> None:
        """Constructs a UsageGovernor instance."""
        self._db_cfg_sqlite: Optional[SQLiteDatabaseConfiguration] = None
        self._db_cfg_postgres: Optional[PostgreSQLDatabaseConfiguration] = None
        self._conn = None

    @abstractmethod
    def _setup_schema(self) -> None:
        """Ensure required DB tables/indexes exist; safe to call repeatedly."""

    # pylint: disable=W0201
    def establish_connection(self) -> None:
        """Open DB connection and prepare storage layer."""
        logger.info("Establishing database link for quota governance")
        try:
            if self._db_cfg_postgres is not None:
                self._conn = connect_pg(self._db_cfg_postgres)
            elif self._db_cfg_sqlite is not None:
                self._conn = connect_sqlite(self._db_cfg_sqlite)
                # Custom datetime serialization for SQLite (Python ≥3.12)
                sqlite3.register_adapter(
                    datetime.datetime,
                    lambda dt: dt.replace(tzinfo=None).isoformat()
                )
            else:
                raise RuntimeError("No database configuration provided")

            self._setup_schema()
        except Exception as err:
            if self._conn:
                self._conn.close()
            logger.exception("Schema setup failed: %s", err)
            raise

        self._conn.autocommit = True

    def is_connected(self) -> bool:
        """Verify active database session."""
        if self._conn is None:
            logger.warning("No active session—reconnection needed")
            return False

        cursor = None
        try:
            cursor = self._conn.cursor()
            cursor.execute("SELECT 1")
            logger.debug("DB session verified")
            return True
        except (psycopg2.OperationalError, sqlite3.Error) as db_err:
            logger.error("Lost DB connection: %s", db_err)
            return False
        finally:
            if cursor is not None:
                try:
                    cursor.close()
                except Exception:  # broad catch for cleanup safety
                    logger.warning("Failed to close cursor during health check")

# Alternative implementation for socket waiting utilities

import select
import sys
from functools import partial
try:
    from time import monotonic
except ImportError:
    from time import time as monotonic

__all__ = ["NoWaitSocketError", "await_socket_readable", "await_socket_writable"]

class NoWaitSocketError(Exception):
    """Raised when no method is available to wait for socket events."""
    pass

def _handle_interruptible_operation(operation_func, timeout_val):
    """Execute an operation that may be interrupted by signals, retrying if needed."""
    if sys.version_info >= (3, 5):
        # Python 3.5+ automatically retries system calls
        return operation_func(timeout_val)

    # For older Python versions, implement manual retry logic
    if timeout_val is None:
        end_time = float("inf")
    else:
        end_time = monotonic() + timeout_val

    while True:
        try:
            return operation_func(timeout_val)
        except (OSError, select.error) as err:
            # Handle EINTR (interrupted system call)
            error_code = err.args[0] if hasattr(err, 'args') and err.args else None
            if error_code != 11 and error_code != 4:  # EAGAIN/EINTR common codes
                raise
            # Recalculate remaining timeout
            remaining = end_time - monotonic()
            if remaining <= 0:
                timeout_val = 0
            elif remaining == float("inf"):
                timeout_val = None
            else:
                timeout_val = remaining
            continue

def _select_based_wait(sock_obj, check_read=False, check_write=False, limit_timeout=None):
    """Use select() to wait for socket events."""
    if not check_read and not check_write:
        raise ValueError("At least one of check_read or check_write must be True")

    read_fds = []
    write_fds = []

    if check_read:
        read_fds.append(sock_obj)
    if check_write:
        write_fds.append(sock_obj)

    # Use partial to prepare the select call with fixed arguments
    select_call = partial(select.select, read_fds, write_fds, write_fds)
    ready_read, ready_write, _ = _handle_interruptible_operation(select_call, limit_timeout)

    return bool(ready_read or ready_write)

def _poll_based_wait(sock_obj, check_read=False, check_write=False, limit_timeout=None):
    """Use poll() to wait for socket events."""
    if not check_read and not check_write:
        raise ValueError("At least one of check_read or check_write must be True")

    event_mask = 0
    if check_read:
        event_mask |= select.POLLIN
    if check_write:
        event_mask |= select.POLLOUT

    poller = select.poll()
    poller.register(sock_obj, event_mask)

    # Convert seconds to milliseconds for poll()
    def poll_with_timeout(t):
        adjusted_timeout = t * 1000 if t is not None else -1
        return poller.poll(adjusted_timeout)

    result = _handle_interruptible_operation(poll_with_timeout, limit_timeout)
    return bool(result)

def _fallback_wait(*args, **kwargs):
    """Fallback when no polling mechanism is available."""
    raise NoWaitSocketError("No suitable method found for waiting on sockets")

def _check_poll_availability():
    """Determine if poll() is functional in current environment."""
    try:
        poller = select.poll()
        _handle_interruptible_operation(lambda t: poller.poll(t), 0)
        return True
    except (AttributeError, OSError):
        return False

# Global variable to store the selected implementation
wait_impl = None

def _select_implementation():
    """Dynamically choose the best available implementation."""
    global wait_impl

    if _check_poll_availability():
        wait_impl = _poll_based_wait
    elif hasattr(select, 'select'):
        wait_impl = _select_based_wait
    else:
        wait_impl = _fallback_wait

    return wait_impl

def await_socket_readable(socket_obj, timeout=None):
    """
    Wait until data is available for reading on the given socket.

    Returns:
        bool: True if the socket is readable, False if timeout occurred.
    """
    if wait_impl is None:
        _select_implementation()
    return wait_impl(socket_obj, check_read=True, limit_timeout=timeout)

def await_socket_writable(socket_obj, timeout=None):
    """
    Wait until the socket is ready for writing.

    Returns:
        bool: True if the socket is writable, False if timeout occurred.
    """
    if wait_impl is None:
        _select_implementation()
    return wait_impl(socket_obj, check_write=True, limit_timeout=timeout)

from typing import Optional
import jax
from flax import nnx
from tpu_inference.layers.jax import JaxModule
from tpu_inference.layers.jax.quantization import QuantizeMethodBase
from tpu_inference.layers.jax.quantization.configs import QuantizationConfig


class JaxEmbedding(JaxModule):
    """JAX-based embedding module supporting quantization."""

    def __init__(self,
                 *args,
                 quant_config: Optional[QuantizationConfig] = None,
                 prefix: str = "",
                 **kwargs):
        # Initialize base embedding using nnx.Embed internally
        self._base_embed = nnx.Embed(*args, **kwargs)

        # Expose weights under 'weight' for HF compatibility
        self.weight = self._base_embed.embedding
        # Remove original attribute to avoid duplication/conflict
        delattr(self._base_embed, 'embedding')

        # Set sharding metadata if available
        if hasattr(self.weight, "out_sharding"):
            self.weight.set_metadata('sharding', self.weight.out_sharding)

        # Handle quantization setup
        self.quantizer = None
        if quant_config is not None:
            q_method = quant_config.get_quant_method(self, prefix=prefix)
            if q_method is not None:
                self.quantizer = q_method
                assert isinstance(q_method, QuantizeMethodBase)
                q_method.create_weights_jax(self)

    def __getattr__(self, attr_name: str):
        # Allow backward-compatible access to .embedding as .weight
        if attr_name == "embedding":
            return self.weight
        raise AttributeError(f"'{type(self).__name__}' has no attribute '{attr_name}'")

    def __call__(self, input_ids) -> jax.Array:
        if self.quantizer is None:
            return self._base_embed(input_ids)
        return self.quantizer.apply_jax(self, input_ids)

    def decode(self, hidden_states: jax.Array) -> jax.Array:
        # Perform linear projection via transpose-weight dot product
        return jax.numpy.dot(hidden_states, self.weight.value.T)

