# Add a new bot configuration with optional overwrite confirmation

from storage.entity.dto import BotConfig
from storage.service import bot_config as bot_service
from storage.service.user import get_cli_user_id
import click

@click.command('add')
@click.argument('bot_name')
@click.option('--model', '-m', required=True, help='Model name')
@click.option('--api-key', '-k', default='', help='API key')
@click.option('--base-url', '-u', default=None, help='Base URL')
@click.option('--api-type', '-t', default=None, help='API type (e.g. anthropic)')
@click.option('--force', '-f', is_flag=True, help='Overwrite without confirmation')
def bot_add(bot_name, model, api_key, base_url, api_type, force):
    """Add or update a bot configuration."""
    user_identifier = get_cli_user_id()
    current_configs = bot_service.list_configs(user_identifier)

    # Check if a config with the same name already exists
    duplicate_found = any(config.name == bot_name for config in current_configs)

    if duplicate_found and not force:
        if not click.confirm(f"A bot named '{bot_name}' already exists. Do you want to replace it?"):
            click.echo("Operation cancelled")
            return

    # Use default base URL if none provided
    if base_url is None:
        base_url = bot_service.default_config.base_url

    # Create new configuration object
    new_bot_config = BotConfig(
        name=bot_name,
        api_key=api_key,
        base_url=base_url,
        model=model,
        api_type=api_type
    )

    # Save the configuration
    bot_service.add_config(user_identifier, new_bot_config)
    click.echo(f"Bot '{bot_name}' added successfully")

import binascii
import calendar
import datetime
import os
import struct
import threading
import time
from random import SystemRandom
from typing import Any, NoReturn, Optional, Type, Union
from .errors import InvalidId
from .tz_util import utc

# Maximum value for the 3-byte counter
_COUNTER_LIMIT = 0xFFFFFF + 1

def _validate_objectid_format(identifier: str) -> NoReturn:
    """Raise an exception when the ObjectId format is invalid."""
    raise InvalidId(
        "%r is not a valid ObjectId, it must be a 12-byte input"
        " or a 24-character hex string" % identifier
    )

def _generate_random_component() -> bytes:
    """Generate 5 random bytes for the ObjectId's random component."""
    return os.urandom(5)

class ObjectId(object):
    """A MongoDB ObjectId."""
    # Process ID for tracking process changes
    _process_id = os.getpid()
    # Thread-safe counter for uniqueness within process
    _counter = SystemRandom().randint(0, _COUNTER_LIMIT - 1)
    _counter_lock = threading.Lock()
    # Random component cached per process
    _random_cache = _generate_random_component()

    __slots__ = ("_value",)
    _type_marker = 7

    def __init__(self, identifier: Optional[Union[str, "ObjectId", bytes]] = None) -> None:
        """Initialize a new ObjectId.

        An ObjectId is a 12-byte unique identifier consisting of:
          - a 4-byte value representing the seconds since the Unix epoch,
          - a 5-byte random value,
          - a 3-byte counter, starting with a random value.

        By default, ``ObjectId()`` creates a new unique identifier. The
        optional parameter `identifier` can be an :class:`ObjectId`, or any 12
        :class:`bytes`.

        :Parameters:
          - `identifier` (optional): a valid ObjectId representation.
        """
        if identifier is None:
            self._create_new()
        elif isinstance(identifier, bytes) and len(identifier) == 12:
            self._value = identifier
        else:
            self._check_and_set(identifier)

    @classmethod
    def from_datetime(cls: Type["ObjectId"], creation_time: datetime.datetime) -> "ObjectId":
        """Create a dummy ObjectId instance with a specific creation time.

        This method is useful for doing range queries on a field
        containing :class:`ObjectId` instances.

        `creation_time` will be converted to UTC. Naive datetime
        instances will be treated as though they already contain UTC.

        :Parameters:
          - `creation_time`: :class:`~datetime.datetime` to be used
            as the creation time for the resulting ObjectId.
        """
        # Normalize to UTC
        offset = creation_time.utcoffset()
        if offset is not None:
            creation_time = creation_time - offset

        # Convert to Unix timestamp
        unix_timestamp = calendar.timegm(creation_time.timetuple())

        # Create ObjectId with timestamp and zeroed remaining bytes
        oid = struct.pack(">I", int(unix_timestamp)) + b"\x00\x00\x00\x00\x00\x00\x00\x00"
        return cls(oid)

    @classmethod
    def is_valid(cls: Type["ObjectId"], identifier: Any) -> bool:
        """Check if a given identifier is a valid ObjectId.

        :Parameters:
          - `identifier`: the object id to validate
        """
        if not identifier:
            return False
        try:
            cls(identifier)
            return True
        except (InvalidId, TypeError):
            return False

    @classmethod
    def _get_random(cls) -> bytes:
        """Get the 5-byte random component, regenerating if process changed."""
        current_pid = os.getpid()
        if current_pid != cls._process_id:
            cls._process_id = current_pid
            cls._random_cache = _generate_random_component()
        return cls._random_cache

    def _create_new(self) -> None:
        """Generate a new ObjectId value."""
        # Pack current timestamp (4 bytes)
        timestamp_bytes = struct.pack(">I", int(time.time()))

        # Add random component (5 bytes)
        random_part = self._get_random()

        # Get and increment counter (3 bytes)
        with self._counter_lock:
            counter_value = self._counter
            self._counter = (self._counter + 1) % _COUNTER_LIMIT

        # Combine all parts into 12-byte ObjectId
        counter_bytes = struct.pack(">I", counter_value)[1:4]
        self._value = timestamp_bytes + random_part + counter_bytes

    def _check_and_set(self, identifier: Any) -> None:
        """Validate and set the ObjectId value from various input types.

        Raises TypeError if identifier is not an accepted type.
        Raises InvalidId if identifier is not valid.
        """
        if isinstance(identifier, ObjectId):
            self._value = identifier.binary
        elif isinstance(identifier, str):
            if len(identifier) == 24:
                try:
                    self._value = bytes.fromhex(identifier)
                except (TypeError, ValueError):
                    _validate_objectid_format(identifier)
            else:
                _validate_objectid_format(identifier)
        else:
            raise TypeError(
                "id must be an instance of (bytes, str, ObjectId), not %s" % (type(identifier),)
            )

    @property
    def binary(self) -> bytes:
        """12-byte binary representation of this ObjectId."""
        return self._value

    @property
    def generation_time(self) -> datetime.datetime:
        """A :class:`datetime.datetime` instance representing the time of
        generation for this :class:`ObjectId`.

        The :class:`datetime.datetime` is timezone aware, and
        represents the generation time in UTC. It is precise to the
        second.
        """
        # Extract timestamp from first 4 bytes
        timestamp = struct.unpack(">I", self._value[0:4])[0]
        return datetime.datetime.fromtimestamp(timestamp, utc)

    def __getstate__(self) -> bytes:
        """Return value of object for pickling."""
        return self._value

    def __setstate__(self, state: Any) -> None:
        """Restore state from pickling with backward compatibility."""
        # Handle older pickle formats
        if isinstance(state, dict):
            state_value = state.get("_ObjectId__id")
        else:
            state_value = state

        # Handle Python 2.x pickled data (str → bytes conversion)
        if isinstance(state_value, str):
            self._value = state_value.encode("latin-1")
        else:
            self._value = state_value

    def __str__(self) -> str:
        """Return hexadecimal string representation."""
        return binascii.hexlify(self._value).decode()

    def __repr__(self):
        return "ObjectId('%s')" % (str(self),)

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, ObjectId):
            return self._value == other.binary
        return NotImplemented

    def __ne__(self, other: Any) -> bool:
        if isinstance(other, ObjectId):
            return self._value != other.binary
        return NotImplemented

    def __lt__(self, other: Any) -> bool:
        if isinstance(other, ObjectId):
            return self._value < other.binary
        return NotImplemented

    def __le__(self, other: Any) -> bool:
        if isinstance(other, ObjectId):
            return self._value <= other.binary
        return NotImplemented

    def __gt__(self, other: Any) -> bool:
        if isinstance(other, ObjectId):
            return self._value > other.binary
        return NotImplemented

    def __ge__(self, other: Any) -> bool:
        if isinstance(other, ObjectId):
            return self._value >= other.binary
        return NotImplemented

    def __hash__(self) -> int:
        """Get a hash value for this ObjectId."""
        return hash(self._value)

from datetime import datetime, timedelta
import calendar
import collections
from src.logic.openclaw_intelligence import OpenClawIntelligence
import logging

logger = logging.getLogger(__name__)

class IntelligenceEngine:
    def __init__(self, client: OdooClient):
        self.client = client
        self._ai_issue = None
        try:
            self.ai = OpenClawIntelligence()
        except Exception as exc:
            self.ai = None
            self._ai_issue = str(exc)
            logger.warning(f"OpenClawIntelligence unavailable: {exc}")

    def fetch_ai_report(self):
        """Leverage AI for advanced anomaly insights on recent financial entries."""
        if not self.ai:
            err_desc = f"AI module inactive: {self._ai_issue}" if self._ai_issue else "AI module not initialized."
            return {"error": err_desc, "backup": "Try detect_issues() for rule-driven inspection"}

        records = self.client.search_read(
            'account.move',
            domain=[('state', '=', 'posted')],
            fields=['name', 'partner_id', 'amount_total', 'invoice_date', 'move_type', 'ref'],
            limit=50
        )
        try:
            return self.ai.analyze_anomalies(records)
        except Exception as ex:
            return f"AI processing error: {str(ex)}"

    def natural_language_request(self, prompt: str):
        """Answer queries using natural language by combining user input with live Odoo data."""
        if not self.ai:
            err_desc = f"AI module inactive: {self._ai_issue}" if self._ai_issue else "AI module not initialized."
            return {"error": err_desc, "backup": "Use structured reporting tools for deterministic results"}

        context_data = {
            "latest_transactions": self._fetch_moves(limit=20),
            "cash_accounts": self._fetch_cash_accounts()
        }
        return self.ai.natural_language_query(prompt, context_data)

    def _fetch_moves(self, limit=20):
        return self.client.search_read(
            'account.move',
            domain=[('state', '=', 'posted')],
            fields=['name', 'partner_id', 'amount_total', 'invoice_date', 'move_type', 'ref'],
            limit=limit
        )

    def _fetch_cash_accounts(self):
        return self.client.search_read(
            'account.account',
            domain=[('account_type', '=', 'asset_cash')],
            fields=['name', 'code', 'current_balance']
        )

    def vat_summary(self, start_date, end_date):
        """
        Compute VAT liability over a specified period.
        Uses tax lines from journal entries to separate output/input VAT.
        """
        filter_clause = [
            ('date', '>=', start_date),
            ('date', '<=', end_date),
            ('parent_state', '=', 'posted'),
            ('tax_line_id', '!=', False)
        ]

        tax_records = self.client.search_read(
            'account.move.line',
            domain=filter_clause,
            fields=['debit', 'credit', 'tax_line_id', 'tax_tag_ids', 'move_type']
        )

        out_vat = 0.0
        in_vat = 0.0

        for entry in tax_records:
            mt = entry['move_type']
            if mt in {'out_invoice', 'out_refund'}:
                out_vat += entry.get('credit', 0.0) - entry.get('debit', 0.0)
            elif mt in {'in_invoice', 'in_refund'}:
                in_vat += entry.get('debit', 0.0) - entry.get('credit', 0.0)

        return {
            'interval': f"{start_date} – {end_date}",
            'output_tax': round(out_vat, 2),
            'input_tax': round(in_vat, 2),
            'net_vat': round(out_vat - in_vat, 2),
            'currency': self._get_currency_name()
        }

    def _get_currency_name(self):
        company_rec = self.client.search_read('res.company', limit=1, fields=['currency_id'])
        return company_rec[0]['currency_id'][1] if company_rec else "Unknown"

    def trend_overview(self, months_back=6):
        """
        Analyze monthly revenue vs expenditure trends.
        """
        current = datetime.now()
        result_list = []

        for offset in range(months_back):
            # First day of target month
            base_month = current.replace(day=1) - timedelta(days=offset * 30)
            year, month = base_month.year, base_month.month
            _, last_day = calendar.monthrange(year, month)
            end_of_month = base_month.replace(day=last_day)

            s_str = base_month.strftime('%Y-%m-%d')
            e_str = end_of_month.strftime('%Y-%m-%d')

            rev_entries = self.client.search_read(
                'account.move',
                domain=[
                    ('move_type', '=', 'out_invoice'),
                    ('state', '=', 'posted'),
                    ('invoice_date', '>=', s_str),
                    ('invoice_date', '<=', e_str)
                ],
                fields=['amount_total']
            )
            total_rev = sum(map(lambda x: x.get('amount_total', 0), rev_entries))

            exp_entries = self.client.search_read(
                'account.move',
                domain=[
                    ('move_type', '=', 'in_invoice'),
                    ('state', '=', 'posted'),
                    ('invoice_date', '>=', s_str),
                    ('invoice_date', '<=', e_str)
                ],
                fields=['amount_total']
            )
            total_exp = sum(map(lambda x: x.get('amount_total', 0), exp_entries))

            result_list.append({
                'period': base_month.strftime('%Y-%m'),
                'income': round(total_rev, 2),
                'cost': round(total_exp, 2)
            })

        return list(reversed(result_list))  # Chronological order

    def detect_issues(self):
        """
        Identify suspicious activity using heuristic rules.
        """
        flagged_items = []

        # Rule 1: Potential duplicate vendor bills
        recent_purchases = self.client.search_read(
            'account.move',
            domain=[('move_type', '=', 'in_invoice'), ('state', '!=', 'cancel')],
            fields=['ref', 'partner_id', 'amount_total', 'invoice_date'],
            limit=500
        )

        ref_groups = collections.defaultdict(list)
        for item in recent_purchases:
            partner_id = item.get('partner_id')
            ref_val = item.get('ref')
            if partner_id and ref_val:
                key = (partner_id[0], ref_val)
                ref_groups[key].append(item)

        for key, group in ref_groups.items():
            if len(group) > 1:
                partner_name = group[0]['partner_id'][1]
                flagged_items.append({
                    'category': 'duplicate_bill',
                    'note': f"Found {len(group)} bills for {partner_name} referencing '{key[1]}'",
                    'ids': [b['id'] for b in group]
                })

        # Rule 2: Invoices without tax despite having amount
        untaxed_moves = self.client.search_read(
            'account.move',
            domain=[
                ('move_type', 'in', ['out_invoice', 'in_invoice']),
                ('state', '=', 'posted'),
                ('amount_tax', '=', 0),
                ('amount_total', '>', 0)
            ],
            fields=['name', 'partner_id', 'amount_total'],
            limit=100
        )
        for mv in untaxed_moves:
            flagged_items.append({
                'category': 'missing_tax',
                'note': f"Transaction '{mv['name']}' has zero tax but non-zero total.",
                'id': mv['id']
            })

        # Rule 3: High-value outlier payments
        recent_payments = self.client.search_read(
            'account.payment',
            domain=[('state', '=', 'posted')],
            fields=['amount', 'name'],
            limit=100,
            order='id desc'
        )
        if recent_payments:
            avg_amt = sum(p['amount'] for p in recent_payments) / len(recent_payments)
            for pay in recent_payments[:10]:
                if pay['amount'] > avg_amt * 5:
                    flagged_items.append({
                        'category': 'payment_spike',
                        'note': f"Payment '{pay['name']}' exceeds norm: {pay['amount']} vs avg {avg_amt:.2f}",
                        'id': pay['id']
                    })

        return flagged_items

# Type III Clone: Equivalent functionality with modified structure and naming

def create_dataset_with_dynamic_items(data_dict, dynamic_funcs, output_keys):
    # Internal helper to compute dynamic values on demand
    class CustomDataset:
        def __init__(self, data, dyn_items, out_keys):
            self.data = data
            self.dynamic_items = dyn_items  # list of dicts: {provides, func, takes}
            self.output_keys = out_keys
            self._id_list = sorted(data.keys())

        def __getitem__(self, idx):
            if isinstance(idx, int):
                utt_id = self._id_list[idx]
            else:
                utt_id = idx
            result = {}
            for key in self.output_keys:
                if key == "id":
                    result["id"] = utt_id
                elif key in self.data[utt_id]:
                    result[key] = self.data[utt_id][key]
                else:
                    # Try to compute dynamic item
                    val = None
                    for dyn in self.dynamic_items:
                        if dyn["provides"] == key:
                            args = [self.data[utt_id][t] for t in dyn["takes"]]
                            val = dyn["func"](*args)
                            break
                    if val is None:
                        raise KeyError(f"Key '{key}' not found or computable")
                    result[key] = val
            return result

        def set_output_keys(self, keys):
            self.output_keys = keys

        def add_dynamic_item(self, func, inputs, name):
            self.dynamic_items.append({
                "provides": name,
                "func": func,
                "takes": inputs
            })

        def __iter__(self):
            for uid in self._id_list:
                yield self[uid]

        def filtered_sorted(self, key_min_value=None, key_max_value=None,
                            key_test=None, sort_key=None, reverse=False, select_n=None):
            # Build filtered list
            filtered_ids = []
            for uid in self._id_list:
                item_data = self.data[uid]
                include = True

                if key_min_value:
                    for k, v in key_min_value.items():
                        if item_data.get(k) < v:
                            include = False
                            break
                if include and key_max_value:
                    for k, v in key_max_value.items():
                        if item_data.get(k) > v:
                            include = False
                            break
                if include and key_test:
                    # Temporarily build full dict with dynamic items
                    temp_out = {}
                    for k in self.output_keys + list(key_test.keys()):
                        if k == "id":
                            temp_out["id"] = uid
                        elif k in item_data:
                            temp_out[k] = item_data[k]
                        else:
                            for d in self.dynamic_items:
                                if d["provides"] == k:
                                    vals = [item_data[t] for t in d["takes"]]
                                    temp_out[k] = d["func"](*vals)
                                    break
                    for k, pred in key_test.items():
                        if k not in temp_out or not pred(temp_out[k]):
                            include = False
                            break

                if include:
                    filtered_ids.append(uid)

            # Sorting step
            if sort_key:
                def get_sort_val(uid):
                    val = self.data[uid].get(sort_key)
                    if val is None:
                        for d in self.dynamic_items:
                            if d["provides"] == sort_key:
                                vals = [self.data[uid][t] for t in d["takes"]]
                                val = d["func"](*vals)
                                break
                    return val if val is not None else float('inf')
                filtered_ids.sort(key=get_sort_val, reverse=reverse)

            # Select top-n if specified
            if select_n is not None:
                filtered_ids = filtered_ids[:select_n]

            # Return new dataset view (not shallow copy)
            new_ds = CustomDataset(self.data, self.dynamic_items.copy(), self.output_keys.copy())
            new_ds._id_list = filtered_ids
            return new_ds

    return CustomDataset(data_dict, dynamic_funcs, output_keys)


