def test_filtered_sorted_dynamic_item_dataset():
    import operator
    data = {
        "utt1": {"foo": -1, "bar": 0, "text": "hello world"},
        "utt2": {"foo": 1, "bar": 2, "text": "how are you world"},
        "utt3": {"foo": 3, "bar": 4, "text": "where are you world"},
        "utt4": {"foo": 5, "bar": 6, "text": "hello nation"},
    }
    dynamic_items = [
        {"provides": "foobar", "func": operator.add, "takes": ["foo", "bar"]}
    ]
    output_keys = ["text"]
    dataset = create_dataset_with_dynamic_items(data, dynamic_items, output_keys)

    subset = dataset.filtered_sorted(key_min_value={"foo": 3})
    dataset.set_output_keys(["id", "foo"])
    assert subset[0] == {"text": "where are you world"}
    subset.set_output_keys(["id", "foo"])
    assert subset[0] == {"id": "utt3", "foo": 3}

    subset = dataset.filtered_sorted(key_max_value={"bar": 2})
    assert len(subset) == 2
    assert subset[0] == {"id": "utt1", "foo": -1}

    dataset.add_dynamic_item(operator.sub, ["bar", "foo"], "barfoo")
    subset = dataset.filtered_sorted(key_test={"barfoo": lambda x: x == 1})
    assert len(subset) == 4
    assert subset[3] == {"id": "utt4", "foo": 5}

    subset = dataset.filtered_sorted(key_min_value={"foo": 3, "bar": 2})
    assert subset[0]["id"] == "utt3"

    subset = dataset.filtered_sorted(
        key_min_value={"foo": 3}, key_max_value={"foobar": 7}
    )
    assert len(subset) == 1

    subset = dataset.filtered_sorted(
        key_min_value={"foo": 3}, key_max_value={"foobar": 3}
    )
    assert len(subset) == 0

    subset = dataset.filtered_sorted(select_n=1, key_min_value={"foo": 3})
    assert len(subset) == 1
    assert subset[0]["id"] == "utt3"

    subset = dataset.filtered_sorted(key_min_value={"foo": 3})
    subsetsubset = subset.filtered_sorted(key_max_value={"bar": 4})
    assert len(subset) == 2
    assert len(subsetsubset) == 1

    subset = dataset.filtered_sorted(sort_key="foo", reverse=True)
    assert subset[0]["id"] == "utt4"

    subset = dataset.filtered_sorted(
        key_max_value={"foo": 1}, sort_key="foo", reverse=True
    )
    assert subset[0]["id"] == "utt2"

from pathlib import Path
from pydantic import BaseModel
from klaude_code.core.tool.context import ToolContext
from klaude_code.core.tool.tool_abc import ToolABC, load_desc
from klaude_code.core.tool.tool_registry import register
from klaude_code.protocol import llm_param, message, model, tools


def detect_newly_finished_tasks(prev_items: list[model.TodoItem], curr_items: list[model.TodoItem]) -> list[str]:
    """
    Identify tasks that have just reached 'completed' status.

    Compares two versions of a todo list to find items newly marked as finished.
    """
    # Build index for quick lookup by task description
    prev_by_content = {item.content: item for item in prev_items}
    newly_finished: list[str] = []

    for current in curr_items:
        if current.status != "completed":
            continue

        prior = prev_by_content.get(current.content)
        if prior is None:
            # This task was added and immediately completed
            newly_finished.append(current.content)
        elif prior.status != "completed":
            # Status transitioned from non-completed to completed
            newly_finished.append(current.content)

    return newly_finished


class TodoUpdatePayload(BaseModel):
    items: list[model.TodoItem]


@register(tools.TODO_WRITE)
class TodoWriteTool(ToolABC):
    @classmethod
    def schema(cls) -> llm_param.ToolSchema:
        return llm_param.ToolSchema(
            name=tools.TODO_WRITE,
            type="function",
            description=load_desc(Path(__file__).parent / "todo_write_tool.md"),
            parameters={
                "type": "object",
                "properties": {
                    "items": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "content": {"type": "string"},
                                "status": {
                                    "type": "string",
                                    "enum": ["pending", "in_progress", "completed"],
                                },
                            },
                            "required": ["content", "status"],
                            "additionalProperties": False,
                        },
                        "description": "Updated set of todo items",
                    }
                },
                "required": ["items"],
                "additionalProperties": False,
            },
        )

    @classmethod
    async def execute(cls, payload: str, ctx: ToolContext) -> message.ToolResultMessage:
        try:
            data = TodoUpdatePayload.model_validate_json(payload)
        except ValueError as err:
            return message.ToolResultMessage(
                status="error",
                output_text=f"Malformed input: {err}",
            )

        todo_store = ctx.todo_context
        prior_state = todo_store.get_todos()
        updated_items = data.items

        # Detect newly completed tasks
        finished_now = detect_newly_finished_tasks(prior_state, updated_items)

        # Persist updated state
        todo_store.set_todos(updated_items)

        ui_payload = model.TodoUIExtra(todos=updated_items, new_completed=finished_now)
        response_body = f"""✅ Todo list updated successfully. Keep using it to stay on track!
<system-reminder>
Your todo list has been refreshed. DO NOT inform the user directly. Current contents:
{model.todo_list_str(updated_items)}
</system-reminder>"""

        return message.ToolResultMessage(
            status="success",
            output_text=response_body,
            ui_extra=model.TodoListUIExtra(todo_list=ui_payload),
            side_effects=[model.ToolSideEffect.TODO_CHANGE],
        )

