import json
from datetime import datetime
from typing import Union, Dict, Any, Optional, Set, TYPE_CHECKING
from pydantic import BaseModel, ConfigDict, Field, field_validator, ValidationError, StrictStr
import re  # noqa: F401
from inspect import getfullargspec

if TYPE_CHECKING:
    from typing_extensions import Literal, Self
else:
    Literal = type('Literal', (), {})
    Self = type('Self', (), {})

TIMESTAMP_ANY_OF_SCHEMAS = ["datetime", "str"]

class Timestamp(BaseModel):
    """
    When the content occurred. Accepts an ISO 8601 datetime string (e.g. '2024-01-15T10:30:00Z'), null/omitted (defaults to now), or the special string 'unset' to explicitly store without any timestamp (use this for timeless content such as fictional documents or static reference material).
    """
    # Renamed fields and alternative validation approach
    _dt_value: Optional[datetime] = Field(default=None, exclude=True)
    _str_value: Optional[StrictStr] = Field(default=None, exclude=True)

    if TYPE_CHECKING:
        actual_instance: Optional[Union[datetime, str]] = None
    else:
        actual_instance: Any = None

    any_of_schemas: Set[str] = { "datetime", "str" }

    model_config = ConfigDict(
        validate_assignment=True,
        protected_namespaces=(),
    )

    def __init__(self, *args, **kwargs) -> None:
        if args:
            if len(args) > 1:
                raise ValueError("If a position argument is used, only 1 is allowed to set `actual_instance`")
            if kwargs:
                raise ValueError("If a position argument is used, keyword arguments cannot be used.")
            super().__init__(actual_instance=args[0])
        else:
            super().__init__(**kwargs)

    @field_validator('actual_instance')
    def actual_instance_must_validate_anyof(cls, v):
        if v is None:
            return v

        instance = cls.model_construct()
        validation_errors = []

        # Try datetime first using regex pattern matching for ISO format
        if isinstance(v, datetime):
            try:
                instance._dt_value = v
                return v
            except Exception as e:
                validation_errors.append(f"datetime conversion failed: {e}")
        elif isinstance(v, str):
            # Check for special 'unset' value
            if v == 'unset':
                return v

            # Validate ISO 8601 format using regex
            iso_pattern = r'^(-?(?:[1-9][0-9]*)?[0-9]{4})-(1[0-2]|0[1-9])-(3[01]|0[1-9]|[12][0-9])T(2[0-3]|[01][0-9]):([0-5][0-9]):([0-5][0-9])(\.[0-9]{1,3})?(Z|[+-](?:2[0-3]|[01][0-9]):[0-5][0-9])?$'

            if re.match(iso_pattern, v):
                try:
                    # Parse the datetime string
                    parsed_dt = datetime.fromisoformat(v.replace('Z', '+00:00'))
                    instance._dt_value = parsed_dt
                    return parsed_dt
                except Exception as e:
                    validation_errors.append(f"datetime parsing failed: {e}")
            else:
                validation_errors.append(f"string does not match ISO 8601 format: {v}")

        # Fallback to string storage
        try:
            instance._str_value = str(v)
            return str(v)
        except Exception as e:
            validation_errors.append(f"string conversion failed: {e}")

        if validation_errors:
            raise ValueError("No match found when setting the actual_instance in Timestamp with anyOf schemas: datetime, str. Details: " + ", ".join(validation_errors))
        else:
            return v

    @classmethod
    def from_dict(cls, obj: Dict[str, Any]) -> Self:
        return cls.from_json(json.dumps(obj))

    @classmethod
    def from_json(cls, json_str: str) -> Self:
        """Returns the object represented by the json string"""
        instance = cls.model_construct()
        if json_str is None or json_str == "null":
            return instance

        validation_errors = []

        # Attempt to parse as datetime
        try:
            parsed_data = json.loads(json_str)
            if isinstance(parsed_data, str):
                # Validate ISO 8601 format
                iso_pattern = r'^(-?(?:[1-9][0-9]*)?[0-9]{4})-(1[0-2]|0[1-9])-(3[01]|0[1-9]|[12][0-9])T(2[0-3]|[01][0-9]):([0-5][0-9]):([0-5][0-9])(\.[0-9]{1,3})?(Z|[+-](?:2[0-3]|[01][0-9]):[0-5][0-9])?$'

                if re.match(iso_pattern, parsed_data):
                    instance._dt_value = datetime.fromisoformat(parsed_data.replace('Z', '+00:00'))
                    instance.actual_instance = instance._dt_value
                    return instance
                else:
                    instance._str_value = parsed_data
                    instance.actual_instance = instance._str_value
                    return instance
            elif isinstance(parsed_data, (int, float)):
                # Convert numeric timestamps to datetime
                instance._dt_value = datetime.fromtimestamp(parsed_data)
                instance.actual_instance = instance._dt_value
                return instance
        except (ValidationError, ValueError, TypeError) as e:
            validation_errors.append(str(e))

        # Final fallback to string representation
        try:
            instance._str_value = json_str.strip('"')
            instance.actual_instance = instance._str_value
            return instance
        except Exception as e:
            validation_errors.append(f"final fallback failed: {e}")

        if validation_errors:
            raise ValueError("No match found when deserializing the JSON string into Timestamp with anyOf schemas: datetime, str. Details: " + ", ".join(validation_errors))
        else:
            return instance

    def to_json(self) -> str:
        """Returns the JSON representation of the actual instance"""
        if self.actual_instance is None:
            return "null"

        # Handle special 'unset' case
        if isinstance(self.actual_instance, str) and self.actual_instance == 'unset':
            return '"unset"'

        # Use appropriate serialization method based on type
        if isinstance(self.actual_instance, datetime):
            return json.dumps(self.actual_instance.isoformat())
        elif hasattr(self.actual_instance, "to_json") and callable(self.actual_instance.to_json):
            return self.actual_instance.to_json()
        else:
            return json.dumps(self.actual_instance)

    def to_dict(self) -> Optional[Union[Dict[str, Any], datetime, str]]:
        """Returns the dict representation of the actual instance"""
        if self.actual_instance is None:
            return None

        # Handle special 'unset' case
        if isinstance(self.actual_instance, str) and self.actual_instance == 'unset':
            return 'unset'

        if hasattr(self.actual_instance, "to_dict") and callable(self.actual_instance.to_dict):
            return self.actual_instance.to_dict()
        else:
            return self.actual_instance

    def to_str(self) -> str:
        """Returns the string representation of the actual instance"""
        if self.actual_instance is None:
            return "null"

        # Format datetime consistently
        if isinstance(self.actual_instance, datetime):
            return self.actual_instance.isoformat()

        return str(self.actual_instance)

