def display_health_summary():
    """Display today's health summary."""
    client = establish_client()
    daily_data = client.get_daily_summary()
    print(f"Date: {date.today()}")
    print(f"Steps: {daily_data.total_steps:,} / {daily_data.daily_step_goal:,}")
    print(f"Distance: {daily_data.total_distance_meters / 1000:.2f} km")
    print(f"Calories: {daily_data.total_kilocalories:,}")
    if daily_data.resting_heart_rate:
        print(f"Resting HR: {daily_data.resting_heart_rate} bpm")
    if daily_data.avg_stress_level:
        print(f"Avg Stress: {daily_data.avg_stress_level}")

def display_sleep_info():
    """Display sleep data."""
    client = establish_client()
    sleep_data = client.get_sleep()
    if sleep_data:
        print(f"Total Sleep: {sleep_data.total_sleep_hours:.1f} hours")
        print(f"Deep Sleep: {sleep_data.deep_sleep_hours:.1f} hours")
        print(f"REM Sleep: {sleep_data.rem_sleep_hours:.1f} hours")
        if sleep_data.overall_score:
            print(f"Sleep Score: {sleep_data.overall_score}")
        if sleep_data.avg_hrv:
            print(f"HRV: {sleep_data.avg_hrv:.1f} ms")
    else:
        print("No sleep data available")

