class CustomJSONEncoder(json.JSONEncoder):
    """Custom JSON encoder to handle non-standard types like datetime, bytes, etc."""

    def default(self, obj: Any) -> Any:
        # Handle datetime objects
        if isinstance(obj, datetime.datetime):
            return obj.isoformat()

        # Handle bytes with fallback to base64 encoding
        if isinstance(obj, bytes):
            try:
                return str(obj)
            except Exception:
                return base64.urlsafe_b64encode(obj).decode()

        # Recursively process lists and tuples
        if isinstance(obj, list):
            return [self.default(item) for item in obj]
        if isinstance(obj, tuple):
            return tuple(self.default(item) for item in obj)

        # Recursively process dictionaries
        if isinstance(obj, dict):
            return {k: self.default(v) for k, v in obj.items()}

        # Fall back to default encoder
        return super().default(obj)


class StructuredLogFormatter(logging.Formatter):
    """Formatter that outputs structured JSON logs with optional encryption."""

    def __init__(self, additional_fields: Optional[Dict[str, Any]] = None):
        super().__init__()
        self._extra_fields = additional_fields or {}
        self._reserved_keys = {
            "name", "msg", "args", "levelname", "levelno",
            "pathname", "filename", "module", "exc_info", "exc_text",
            "stack_info", "lineno", "funcName", "created", "msecs",
            "relativeCreated", "thread", "threadName", "processName", "process",
            "taskName", "sql", "encrypted_info", "exception"
        }

    def format(self, record: logging.LogRecord) -> str:
        # Base structured fields
        log_entry = {
            "time": self.formatTime(record, self.datefmt),
            "level": getattr(record, "levelname", "INFO"),
            "msg": record.getMessage()
        }

        # Add exception info if present
        if record.exc_info:
            log_entry["exception"] = self.formatException(record.exc_info)
        if record.stack_info:
            log_entry["stack_info"] = record.stack_info

        # Extract function name from various possible attributes
        func_name = None
        if hasattr(record, "function_name"):
            func_name = getattr(record, "function_name")
        elif hasattr(record, "funcName"):
            func_name = getattr(record, "funcName")

        if func_name and func_name != "<module>":
            log_entry["function"] = func_name

        # File location info
        if hasattr(record, "pathname") and hasattr(record, "lineno"):
            path = getattr(record, "pathname")
            rel_path = path.removeprefix(os.getcwd()).removeprefix(os.sep)
            log_entry["file"] = f"{rel_path}:{getattr(record, 'lineno')}"

        # Module name
        if hasattr(record, "module") and record.module:
            log_entry["module"] = record.module

        # Handle encrypted info field
        raw_encrypted_data = getattr(record, "encrypted_info", "")
        if raw_encrypted_data:
            serialized = json.dumps(
                raw_encrypted_data,
                ensure_ascii=False,
                separators=(',', ':'),
                cls=CustomJSONEncoder
            )

            global _fernet_instance
            if _fernet_instance:
                try:
                    encrypted_payload = _fernet_instance.encrypt(serialized)
                except Exception as err:
                    logging.warning(str(err))
                    encrypted_payload = serialized
            else:
                encrypted_payload = serialized

            # Truncate long payloads for readability
            if len(encrypted_payload) > 200:
                encrypted_payload = (
                    encrypted_payload[:100] +
                    "**********" +
                    encrypted_payload[-100:]
                )
            log_entry["encrypted_info"] = encrypted_payload

        # Include any custom fields not in reserved set
        for key, value in record.__dict__.items():
            if key not in self._reserved_keys:
                log_entry[key] = value

        # Merge extra static fields
        log_entry.update(self._extra_fields)

        # Inject request context fields if missing
        if "trace_id" not in log_entry:
            trace_id = get_req_ctx("trace_id")
            if trace_id:
                log_entry["trace_id"] = trace_id

        if "url" not in log_entry:
            url = get_req_ctx("path")
            if url:
                log_entry["url"] = url

        if "method" not in log_entry:
            method = get_req_ctx("method")
            if method:
                log_entry["method"] = method

        return json.dumps(log_entry, ensure_ascii=False, separators=(",", ":"), cls=CustomJSONEncoder)


class TqdmStreamHandler(logging.Handler):
    """Logging handler that writes to tqdm progress bar-aware output."""

    def __init__(self):
        super().__init__()

    def emit(self, record: logging.LogRecord):
        try:
            formatted_msg = self.format(record)
            from tqdm import tqdm
            tqdm.write(formatted_msg)
            self.flush()
        except Exception:
            self.handleError(record)


