]


def suppress_verbose_logging(app_level: int):
    """Set elevated log level for known noisy libraries when app is in DEBUG mode."""
    if app_level <= logging.DEBUG:
        for lib_name in VERBOSE_LIBS:
            logging.getLogger(lib_name).setLevel(logging.WARNING)


def configure_console_logging(
    level: int = logging.INFO,
    extra_data: Dict[str, Any] = {},
    encryption_key: str = ""
):
    """Initialize console-based structured logging."""
    global _fernet_instance
    if encryption_key:
        _fernet_instance = FernetEncrypter(encryption_key)

    handler = logging.StreamHandler()
    handler.setFormatter(StructuredLogFormatter(extra_data))

    logging.root.handlers = [handler]
    logging.root.setLevel(level)
    suppress_verbose_logging(level)


def configure_file_logging(
    filename: str,
    directory: str,
    level: int = logging.INFO,
    extra_data: Dict[str, Any] = {},
    encryption_key: str = ""
):
    """Initialize file + console structured logging."""
    global _fernet_instance
    if encryption_key:
        _fernet_instance = FernetEncrypter(encryption_key)

    if directory:
        os.makedirs(directory, exist_ok=True)

    formatter = StructuredLogFormatter(extra_data)
    timestamp = datetime.datetime.now()
    file_path = os.path.join(
        directory,
        f"{timestamp.strftime('%Y-%m-%d')}_{filename}_{timestamp.strftime('%H%M%S_%f')}.log"
    )

    file_handler = logging.FileHandler(file_path, mode="w+")
    file_handler.setFormatter(formatter)

    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)

    logging.root.handlers = [file_handler, console_handler]
    logging.root.setLevel(level)
    suppress_verbose_logging(level)


def configure_tqdm_logging(level: int = logging.INFO):
    """Configure logging to use tqdm-compatible output."""
    handler = TqdmStreamHandler()
    handler.setFormatter(StructuredLogFormatter())
    logging.root.handlers = [handler]
    logging.root.setLevel(level)


def setup_logging(
    name: str = "",
    dir: str = "",
    level: int = logging.INFO,
    extra_data: Dict[str, Any] = {},
    encryption_key: str = ""
):
    """Unified logging initializer: chooses between file/console based on presence of name."""
    if name:
        configure_file_logging(name, dir, level, extra_data, encryption_key)
    else:
        configure_console_logging(level, extra_data, encryption_key)

