    def __init__(self):
        self.config_directory = Path.home() / ".wingosy"
        self.config_filepath = self.config_directory / "config.json"

        # Migration logic: Thoroughly restore user data from legacy location
        legacy_dir = Path.home() / ".argosy"
        if legacy_dir.exists():
            needs_migration = False
            if not self.config_directory.exists() or not self.config_filepath.exists():
                needs_migration = True
            else:
                # If .wingosy exists but server URL is still default, assume failed rebranding
                try:
                    with open(self.config_filepath, 'r', encoding='utf-8') as f:
                        current_config = json.load(f)
                        if current_config.get("server_url") == "http://localhost:8285":
                            needs_migration = True
                except:
                    needs_migration = True

            if needs_migration:
                try:
                    if self.config_directory.exists():
                        shutil.rmtree(self.config_directory, ignore_errors=True)
                    shutil.copytree(legacy_dir, self.config_directory)
                    print(f"Successfully migrated all settings and library from {legacy_dir}")
                except Exception as error:
                    print(f"Migration error: {error}")

        # Initialize with fresh copy of default configuration
        self.configuration = copy.deepcopy(self.INITIAL_SETTINGS)
        self.reload()

    def reload(self):
        if self.config_filepath.exists():
            try:
                with open(self.config_filepath, 'r', encoding='utf-8') as f:
                    stored_data = json.load(f)

                    # 1. Restore top-level configuration values
                    for key, value in stored_data.items():
                        if key != "emulator_definitions":
                            self.configuration[key] = value

                    # 2. Normalize server URL
                    if self.configuration.get("server_url"):
                        self.configuration["server_url"] = self.configuration["server_url"].rstrip('/')

                    # 3. Preserve user-defined emulator paths while allowing metadata updates
                    previous_emus = stored_data.get("emulator_definitions", {})
                    for name, current_settings in self.configuration["emulator_definitions"].items():
                        for old_name, old_settings in previous_emus.items():
                            if old_settings.get("executable") == current_settings["executable"]:
                                current_settings["location"] = old_settings.get("location", "")
                                break
            except Exception as error:
                print(f"Error loading configuration: {error}")
        else:
            self.store()

    def store(self):
        self.config_directory.mkdir(parents=True, exist_ok=True)
        try:
            with open(self.config_filepath, 'w', encoding='utf-8') as f:
                json.dump(self.configuration, f, indent=4)
        except Exception as error:
            print(f"Error saving configuration: {error}")

    def retrieve(self, key, fallback=None):
        return self.configuration.get(key, fallback)

    def update(self, key, value):
        if value is None:
            self.configuration.pop(key, None)
        else:
            self.configuration[key] = value
        self.store()

import os
import json
import logging
from typing import Set

logger = logging.getLogger(__name__)

class EmailValidator:
    _blocked_domains: Set[str] = set()
    _initialized: bool = False

    @classmethod
    def _initialize_blocked_list(cls):
        """Populates the list of disposable email domains from a JSON file."""
        if cls._initialized:
            return

        try:
            # Determine path relative to current module location
            script_dir = os.path.dirname(os.path.realpath(__file__))
            config_path = os.path.join(script_dir, "..", "resources", "disposable_emails.json")

            if os.path.isfile(config_path):
                with open(config_path, "r", encoding="utf-8") as file:
                    domain_list = json.load(file)
                    cls._blocked_domains = set(domain_list)
                cls._initialized = True
                logger.info(f"Successfully loaded {len(cls._blocked_domains)} disposable email domains.")
            else:
                logger.warning(f"Disposable email configuration file not found at {config_path}")
        except Exception as error:
            logger.error(f"Error while loading disposable domains: {error}")

    @classmethod
    def is_temporary_email(cls, address: str) -> bool:
        """
        Determines whether an email address belongs to a disposable provider.
        Performs exact and hierarchical domain matching against known disposable domains.
        """
        if not address or "@" not in address:
            return False

        cls._initialize_blocked_list()

        if not cls._blocked_domains:
            return False

        try:
            # Normalize and extract domain part
            domain = address.split("@")[-1].lower().strip()

            # Check for exact match first
            if domain in cls._blocked_domains:
                return True

            # Check parent domains (e.g., check 'mailinator.com' if input is 'sub.mailinator.com')
            segments = domain.split(".")
            # Iterate from second-to-last segment to beginning
            for idx in range(len(segments) - 1):
                candidate = ".".join(segments[idx:])
                if candidate in cls._blocked_domains:
                    return True

            return False
        except Exception:
            return False

