class ProcessorTestBase:
    """Base class providing common test utilities for processors."""

    processor_class = None

    def get_component_instance(self, attr_name, **kwargs):
        assert attr_name in self.processor_class.attributes
        comp_class_name = getattr(self.processor_class, f"{attr_name}_class")
        if isinstance(comp_class_name, tuple):
            comp_class_name = comp_class_name[0]
        comp_cls = processor_class_from_name(comp_class_name)
        component = comp_cls.from_pretrained(self.tmpdirname, **kwargs)

        if attr_name == "tokenizer" and not component.pad_token:
            component.pad_token = "[TEST_PAD]"
        return component

    def build_processor_components(self):
        components_dict = {}
        for attribute in self.processor_class.attributes:
            components_dict[attribute] = self.get_component_instance(attribute)
        return components_dict

    def instantiate_processor(self):
        base_components = self.build_processor_components()
        extra_kwargs = self.get_processor_config()
        return self.processor_class(**base_components, **extra_kwargs)

    def get_processor_config(self):
        return {}

