            console.print(email)

def display_all_timestamps(epstein_files):
    from epstein_files.output.rich import console
    fallback_count = valid_count = 0
    total_docs = len(epstein_files.unique_documents)

    for doc in epstein_files.unique_documents:
        console.print(doc._summary)
        if doc.timestamp == FALLBACK_TIMESTAMP:
            fallback_count += 1
        elif doc.timestamp is not None:
            valid_count += 1

    missing_timestamp = total_docs - valid_count - fallback_count
    console.print(f"\nFound {total_docs} documents (no_timestamp={missing_timestamp}, valid={valid_count}, fallback={fallback_count})\n")

