    from collections import defaultdict
    category_counts = defaultdict(int)

    for idx, doc in enumerate(epstein_files.unique_documents):
        category_counts[doc._class_name] += 1

    category_counts['total'] = idx + 1
    console.print(styled_dict(category_counts))

def _check_filenames(epstein_files):
    doc_filenames = set()
    for doc in epstein_files.documents:
        doc_filenames.add(doc.file_path.name)

    for file_path in epstein_files.file_paths:
        if file_path.name not in doc_filenames:
            print(f"'{file_path}' is not in list of {len(doc_filenames)} Document obj filenames!")

def display_relevant_doc_panels_and_properties(epstein_files, sort_by_category: bool = True):
    """Only displays OtherFile objects."""
    from epstein_files.documents.other_file import OtherFile
    from epstein_files.output.rich import console, indent_txt, styled_dict
    displayed_count = 0
    interesting_count = 0

    if sort_by_category:
        sorted_docs = sorted(epstein_files.documents, key=lambda d: [d.category, d.timestamp or FALLBACK_TIMESTAMP])
    else:
        sorted_docs = epstein_files.documents

    for doc in sorted_docs:
        if not isinstance(doc, OtherFile):
            continue
        elif doc.is_interesting is None and doc.config is None:
            continue

        if doc.config:
            props = dict(doc.config.truthy_props)
            props.pop('id', None)
            if doc.is_interesting != doc.config.is_of_interest:
                logger.warning("mismatch of config.is_of_interest and doc.is_interesting")
                props['doc.is_interesting'] = doc.is_interesting
        else:
            props = {'doc.is_interesting': doc.is_interesting}

        console.print(doc.rich_header())
        from epstein_files.util.env import args
        if args.debug:
            props_table = styled_dict(props, sep=': ')
            props_table = Padding(indent_txt(props_table, 12), (0, 0, 1, 0))
            console.print(props_table)

        displayed_count += 1
        interesting_count += int(bool(doc.is_interesting))

    print('')
    logger.warning(f"Displayed {displayed_count} object configs, {interesting_count} interesting ones.\n\n")

# Voice transcription and configuration endpoints
"""
Module for handling voice-related API endpoints including configuration retrieval and audio transcription.
"""
import asyncio
import logging
from typing import Optional
from fastapi import APIRouter, File, HTTPException, Request, UploadFile
from ....voice import VoiceService, VoiceServiceError

logger = logging.getLogger("codex_autorunner.routes.voice")


def create_voice_endpoints() -> APIRouter:
    """Construct and return the router containing voice service routes."""
    endpoint_router = APIRouter()

    @endpoint_router.get("/api/voice/config")
    def retrieve_voice_configuration(request: Request):
        # Access shared application state objects
        voice_service_instance: Optional[VoiceService] = request.app.state.voice_service
        voice_settings = request.app.state.voice_config
        disable_reason = getattr(request.app.state, "voice_missing_reason", None)

        if disable_reason:
            return {
                "enabled": False,
                "provider": voice_settings.provider,
                "latency_mode": voice_settings.latency_mode,
                "chunk_ms": voice_settings.chunk_ms,
                "sample_rate": voice_settings.sample_rate,
                "warn_on_remote_api": voice_settings.warn_on_remote_api,
                "has_api_key": False,
                "push_to_talk": {
                    "max_ms": voice_settings.push_to_talk.max_ms,
                    "silence_auto_stop_ms": voice_settings.push_to_talk.silence_auto_stop_ms,
                    "min_hold_ms": voice_settings.push_to_talk.min_hold_ms,
                },
                "missing_extra": disable_reason,
            }

        if voice_service_instance is None:
            # Attempt to instantiate service for config retrieval on failure
            try:
                temp_service = VoiceService(
                    voice_settings, logger=request.app.state.logger
                )
                return temp_service.config_payload()
            except (ValueError, TypeError, OSError) as err:
                logger.debug("Could not initialize VoiceService for config: %s", err)
                return {
                    "enabled": False,
                    "provider": voice_settings.provider,
                    "latency_mode": voice_settings.latency_mode,
                    "chunk_ms": voice_settings.chunk_ms,
                    "sample_rate": voice_settings.sample_rate,
                    "warn_on_remote_api": voice_settings.warn_on_remote_api,
                    "has_api_key": False,
                    "push_to_talk": {
                        "max_ms": voice_settings.push_to_talk.max_ms,
                        "silence_auto_stop_ms": voice_settings.push_to_talk.silence_auto_stop_ms,
                        "min_hold_ms": voice_settings.push_to_talk.min_hold_ms,
                    },
                }

        return voice_service_instance.config_payload()

    @endpoint_router.post("/api/voice/transcribe")
    async def process_audio_transcription(
        request: Request,
        audio_file: Optional[UploadFile] = File(None),
        lang_code: Optional[str] = None,
    ):
        voice_service_instance: Optional[VoiceService] = request.app.state.voice_service
        voice_settings = request.app.state.voice_config
        disable_reason = getattr(request.app.state, "voice_missing_reason", None)

        if disable_reason:
            raise HTTPException(status_code=503, detail=disable_reason)

        if not voice_service_instance or not voice_settings.enabled:
            raise HTTPException(status_code=400, detail="Voice functionality is disabled")

        file_name: Optional[str] = None
        mime_type: Optional[str] = None

        if audio_file is not None:
            file_name = audio_file.filename
            mime_type = audio_file.content_type
            try:
                audio_data = await audio_file.read()
            except Exception as exc:
                raise HTTPException(
                    status_code=400, detail="Failed to read uploaded audio data"
                ) from exc
        else:
            audio_data = await request.body()

        try:
            transcription_result = await asyncio.to_thread(
                voice_service_instance.transcribe,
                audio_data,
                client="web",
                user_agent=request.headers.get("user-agent"),
                language=lang_code,
                filename=file_name,
                content_type=mime_type,
            )
        except VoiceServiceError as exc:
            error_mapping = {
                "unauthorized": 401,
                "forbidden": 403,
                "audio_too_large": 413,
                "rate_limited": 429,
            }
            status_code = error_mapping.get(exc.reason)
            if status_code is None:
                if exc.reason in ("disabled", "empty_audio", "invalid_audio"):
                    status_code = 400
                else:
                    status_code = 502
            raise HTTPException(status_code=status_code, detail=exc.detail) from exc

        return {"status": "ok", **transcription_result}

    return endpoint_router

