import datetime
import json
import os
import subprocess
import tempfile
import uuid
from mcp_server_ccapi.errors import ClientError
from mcp_server_ccapi.models.models import RunCheckovRequest

def _verify_checkov_availability() -> dict:
    """Verify Checkov is installed and accessible.
    Since checkov is now a declared dependency, it should always be available.
    This function serves as a validation step to ensure proper setup.
    Returns:
        A dictionary with status information:
        {
            "available": True/False,
            "info": Description of what happened,
            "requires_action": True/False
        }
    """
    try:
        # Verify Checkov is available by checking version
        subprocess.run(
            ['checkov', '--version'],
            capture_output=True,
            text=True,
            check=True,
            shell=False,
        )
        return {
            'available': True,
            'info': 'Checkov is properly installed',
            'requires_action': False,
        }
    except (FileNotFoundError, subprocess.CalledProcessError):
        return {
            'available': False,
            'info': 'Checkov is not found. As checkov is a declared dependency, please reinstall the package.',
            'requires_action': True,
        }

async def perform_security_audit(resource_type: str, properties: dict) -> dict:
    """Basic security audit function for test compatibility."""
    return {'status': 'success', 'message': 'Security audit completed successfully'}

async def execute_checkov_scan(request: RunCheckovRequest, workflow_store: dict) -> dict:
    """Execute Checkov security and compliance scanner on server-stored cloudcontrol template implementation."""
    # Verify Checkov installation
    checkov_status = _verify_checkov_availability()
    if not checkov_status['available']:
        return {
            'passed': False,
            'error': 'Checkov is not installed',
            'summary': {'error': 'Checkov not installed'},
            'message': checkov_status['info'],
            'requires_confirmation': checkov_status['requires_action'],
            'options': [
                {
                    'option': 'install_assistance',
                    'description': 'Get help installing Checkov',
                },
                {
                    'option': 'continue_without_checks',
                    'description': 'Continue without security verification',
                },
                {'option': 'abort', 'description': 'Abort the operation'},
            ],
        }

    # CRITICAL SECURITY: Validate explained token and retrieve server-stored cloudcontrol template
    if request.explained_token not in workflow_store:
        raise ClientError('Invalid explained token: you must call explain() first')
    workflow_data = workflow_store[request.explained_token]
    if workflow_data.get('type') != 'explained_properties':
        raise ClientError('Invalid token type: expected explained_properties token from explain()')

    # Retrieve cloudcontrol template from server-stored data (AI cannot override this)
    cloudcontrol_template = workflow_data['data']['cloudcontrol_template']
    resource_type = workflow_data['data']['properties'].get('Type', 'Unknown')

    # Ensure content is a string for Checkov
    if not isinstance(cloudcontrol_template, str):
        try:
            content = json.dumps(cloudcontrol_template)
        except Exception as e:
            return {
                'passed': False,
                'error': f'cloudcontrol template must be valid JSON: {str(e)}',
                'summary': {'error': 'Invalid cloudcontrol template format'},
            }
    else:
        content = cloudcontrol_template

    # Create a temporary file with the cloudcontrol template (always JSON)
    temp_file_path = None
    try:
        with tempfile.NamedTemporaryFile(suffix='.json', delete=False) as temp_file:
            temp_file.write(content.encode('utf-8'))
            temp_file_path = temp_file.name

        # Build the checkov command with input validation
        cmd = ['checkov', '-f', temp_file_path, '--output', 'json']

        # Add framework if specified (validate against allowed frameworks)
        if request.framework:
            allowed_frameworks = [
                'terraform',
                'cloudcontrol',
                'kubernetes',
                'dockerfile',
                'arm',
                'all',
            ]
            if request.framework in allowed_frameworks:
                cmd.extend(['--framework', request.framework])
            else:
                return {
                    'passed': False,
                    'error': f'Invalid framework: {request.framework}. Allowed: {allowed_frameworks}',
                }

        # Run checkov with shell=False for security
        process = subprocess.run(cmd, capture_output=True, text=True, shell=False)

        # Parse the output
        if process.returncode == 0:
            # All checks passed - generate security scan token
            security_scan_token = f'sec_{str(uuid.uuid4())}'
            workflow_store[security_scan_token] = {
                'type': 'security_scan',
                'data': {
                    'passed': True,
                    'scan_results': (json.loads(process.stdout) if process.stdout else []),
                    'resource_type': resource_type,
                    'timestamp': str(datetime.datetime.now()),
                },
                'timestamp': datetime.datetime.now().isoformat(),
            }
            return {
                'scan_status': 'PASSED',
                'raw_failed_checks': [],
                'raw_passed_checks': (json.loads(process.stdout) if process.stdout else []),
                'raw_summary': {
                    'passed': True,
                    'message': 'All security checks passed',
                },
                'resource_type': resource_type,
                'timestamp': str(datetime.datetime.now()),
                'security_scan_token': security_scan_token,
                'message': 'Security checks passed. You can proceed with create_resource().',
            }
        elif process.returncode == 1:  # Return code 1 means vulnerabilities were found
            # Some checks failed
            try:
                results = json.loads(process.stdout) if process.stdout else {}
                failed_checks = results.get('results', {}).get('failed_checks', [])
                passed_checks = results.get('results', {}).get('passed_checks', [])
                summary = results.get('summary', {})

                # Security issues found - return results with security_scan_token
                security_scan_token = f'sec_{str(uuid.uuid4())}'
                workflow_store[security_scan_token] = {
                    'type': 'security_scan',
                    'data': {
                        'passed': False,
                        'scan_results': {
                            'failed_checks': failed_checks,
                            'passed_checks': passed_checks,
                            'summary': summary,
                        },
                        'resource_type': resource_type,
                        'timestamp': str(datetime.datetime.now()),
                    },
                    'timestamp': datetime.datetime.now().isoformat(),
                }
                return {
                    'scan_status': 'FAILED',
                    'raw_failed_checks': failed_checks,
                    'raw_passed_checks': passed_checks,
                    'raw_summary': summary,
                    'resource_type': resource_type,
                    'timestamp': str(datetime.datetime.now()),
                    'security_scan_token': security_scan_token,
                    'message': 'Security issues found. You can proceed with create_resource() if you approve.',
                }
            except json.JSONDecodeError:
                # Handle case where output is not valid JSON
                return {
                    'passed': False,
                    'error': 'Failed to parse Checkov output',
                    'stdout': process.stdout,
                    'stderr': process.stderr,
                }
        else:
            # Error running checkov
            return {
                'passed': False,
                'error': f'Checkov exited with code {process.returncode}',
                'stderr': process.stderr,
            }
    except Exception as e:
        return {'passed': False, 'error': str(e), 'message': 'Failed to run Checkov'}
    finally:
        # Clean up the temporary file
        if temp_file_path and os.path.exists(temp_file_path):
            os.unlink(temp_file_path)

import warnings
from multiprocessing import Pipe, Process
from multiprocessing.connection import Connection
from typing import Any, Callable, Optional, Union
import gymnasium as gym
import numpy as np
from rlinf.envs.venv import (
    BaseVectorEnv,
    CloudpickleWrapper,
    EnvWorker,
    ShArray,
    SubprocEnvWorker,
    _setup_buf,
)

# Suppress repeated deprecation warnings
warnings.simplefilter("once", DeprecationWarning)


def _encode_observation(obs: Any, buffer: Any) -> None:
    """Helper function to encode observations into shared memory buffers."""
    if isinstance(obs, np.ndarray) and isinstance(buffer, ShArray):
        buffer.save(obs)
    elif isinstance(obs, tuple) and isinstance(buffer, tuple):
        for o_part, b_part in zip(obs, buffer):
            _encode_observation(o_part, b_part)
    elif isinstance(obs, dict) and isinstance(buffer, dict):
        for key in obs:
            _encode_observation(obs[key], buffer[key])


def _worker_process(
    parent_conn: Connection,
    child_conn: Connection,
    env_factory: CloudpickleWrapper,
    shared_buffers: Optional[Any] = None,
) -> None:
    """Worker process that handles environment operations via message passing."""
    # Close the parent end on the worker side
    parent_conn.close()

    # Instantiate the environment
    env = env_factory.data()

    try:
        while True:
            try:
                command, payload = child_conn.recv()
            except EOFError:
                child_conn.close()
                break

            if command == "step":
                result = env.step(payload)
                if shared_buffers is not None:
                    _encode_observation(result[0], shared_buffers)
                    result = (None,) + result[1:]
                child_conn.send(result)

            elif command == "reset":
                reset_result = env.reset(**payload) if isinstance(payload, dict) else env.reset()

                # Check if reset returns (obs, info)
                has_info = (
                    isinstance(reset_result, (tuple, list)) 
                    and len(reset_result) == 2 
                    and isinstance(reset_result[1], dict)
                )

                if has_info:
                    obs, info = reset_result
                else:
                    obs = reset_result

                # Encode observation if sharing memory
                if shared_buffers is not None:
                    _encode_observation(obs, shared_buffers)
                    obs = None

                # Send appropriate response
                if has_info:
                    child_conn.send((obs, info))
                else:
                    child_conn.send(obs)

            elif command == "close":
                child_conn.send(env.close())
                child_conn.close()
                break

            elif command == "render":
                render_method = getattr(env, "render", None)
                child_conn.send(render_method(**payload) if callable(render_method) else None)

            elif command == "seed":
                seed_method = getattr(env, "seed", None)
                if callable(seed_method):
                    child_conn.send(seed_method(payload))
                else:
                    env.reset(seed=payload)
                    child_conn.send(None)

            elif command == "getattr":
                child_conn.send(
                    getattr(env, payload) if hasattr(env, payload) else None
                )

            elif command == "setattr":
                setattr(env.unwrapped, payload["key"], payload["value"])

            elif command == "reconfigure":
                # Reconfigure logic for Meta-World-like environments
                env.close()
                meta_env_name = payload.pop("env_name")
                env = gym.make(
                    "Meta-World/MT1",
                    env_name=meta_env_name,
                    render_mode="rgb_array",
                    camera_id=2,
                    disable_env_checker=True,
                )
                # Adjust camera position for consistency with SFT
                env.env.env.env.env.env.env.model.cam_pos[2] = [0.75, 0.075, 0.7]
                child_conn.send(None)

            else:
                child_conn.close()
                raise ValueError(f"Unknown command: {command}")

    except KeyboardInterrupt:
        child_conn.close()


class CustomReconfigurableSubprocWorker(SubprocEnvWorker):
    """Extended subprocess worker supporting dynamic environment reconfiguration."""

    def __init__(self, env_fn: Callable[[], gym.Env], use_shared_memory: bool = False):
        self.parent_pipe, self.child_pipe = Pipe()
        self.use_shared_memory = use_shared_memory
        self.memory_buffer: Optional[Any] = None

        if self.use_shared_memory:
            temp_env = env_fn()
            observation_space = temp_env.observation_space
            temp_env.close()
            del temp_env
            self.memory_buffer = _setup_buf(observation_space)

        worker_args = (
            self.parent_pipe,
            self.child_pipe,
            CloudpickleWrapper(env_fn),
            self.memory_buffer,
        )
        self.worker_process = Process(
            target=_worker_process,
            args=worker_args,
            daemon=True,
        )
        self.worker_process.start()
        self.child_pipe.close()
        EnvWorker.__init__(self, env_fn)

    def update_environment(self, config_params: Any) -> Any:
        """Send a reconfiguration request to the worker process."""
        self.parent_pipe.send(["reconfigure", config_params])
        return self.parent_pipe.recv()


class CustomReconfigurableSubprocVectorEnv(BaseVectorEnv):
    """Vectorized environment with support for per-environment reconfiguration."""

    def __init__(self, env_constructors: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def create_worker(fn: Callable[[], gym.Env]) -> CustomReconfigurableSubprocWorker:
            return CustomReconfigurableSubprocWorker(fn, use_shared_memory=False)

        super().__init__(env_constructors, create_worker, **kwargs)

    def update_environments(self, configs: list[Any], indices=None) -> None:
        """Update multiple environments with new configurations."""
        self._ensure_not_closed()
        indices = self._normalize_indices(indices)

        if self.async_mode:
            self._validate_indices(indices)

        for idx, env_idx in enumerate(indices):
            self.workers[env_idx].update_environment(configs[idx])

# Calculate desirability score and profile score with adjusted logic

import pytest
from app.services.scoring.profile_scoring import desirability, profile_score

class TestDesirability:
    def test_value_in_range_returns_one(self):
        # Value strictly within bounds should yield maximum desirability
        assert desirability(300, 0, 500) == 1.0

    def test_value_at_boundary_returns_one(self):
        # Values exactly at min or max boundaries are fully desirable
        assert desirability(500, 0, 500) == 1.0
        assert desirability(0, 0, 500) == 1.0

    def test_value_above_max_linear_falloff(self):
        # Value beyond max: linear decay from 1 to 0 over one range width
        # (750 - 500) / 500 = 0.5 -> desirability = 1 - 0.5 = 0.5
        result = desirability(750, 0, 500)
        assert result == pytest.approx(0.5, abs=0.01)

    def test_value_below_min_linear_falloff(self):
        # Value below min: linear decay from 1 to 0 over one range width
        # (200 - 100) / 300 = 0.333... -> desirability = 1 - 0.333 = 0.667
        result = desirability(100, 200, 500)
        assert result == pytest.approx(0.667, abs=0.01)

    def test_value_far_outside_returns_zero(self):
        # Values beyond two range widths are clamped to zero
        assert desirability(-200, 0, 500) == 0.0
        assert desirability(1100, 0, 500) == 0.0

    def test_none_value_returns_none(self):
        # Invalid input should propagate as None
        assert desirability(None, 0, 500) is None

class TestProfileScore:
    def test_all_in_range_returns_100(self):
        properties = {"mw": 300, "logp": 2.5}
        thresholds = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        weights = {"mw": 1.0, "logp": 1.0}
        # All properties in range with equal weights → perfect score
        assert profile_score(properties, thresholds, weights) == 100.0

    def test_one_out_of_range_reduces_score(self):
        properties = {"mw": 300, "logp": 7.5}
        thresholds = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        weights = {"mw": 1.0, "logp": 1.0}
        # logp outside its acceptable range reduces overall score
        score = profile_score(properties, thresholds, weights)
        assert 0 < score < 100

    def test_missing_property_skipped(self):
        properties = {"mw": 300}
        thresholds = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        weights = {"mw": 1.0, "logp": 1.0}
        # Only present properties contribute; missing ones ignored
        assert profile_score(properties, thresholds, weights) == 100.0

    def test_empty_thresholds_returns_none(self):
        # No scoring criteria provided → no valid computation possible
        assert profile_score({"mw": 300}, {}, {}) is None

    def test_weights_affect_score(self):
        properties = {"mw": 600, "logp": 2.5}
        thresholds = {"mw": {"min": 0, "max": 500}, "logp": {"min": -5, "max": 5}}
        # Higher weight on out-of-range property leads to lower overall score
        score_heavy = profile_score(properties, thresholds, {"mw": 3.0, "logp": 1.0})
        score_light = profile_score(properties, thresholds, {"mw": 1.0, "logp": 1.0})
        assert score_heavy < score_light

# TI Exhaustive Search: Core computational logic for montage and current ratio enumeration

from itertools import combinations, permutations

def compute_current_pairs(total_current, step_size, max_channel_load):
    """Compute admissible current distribution pairs between two channels.

    Returns:
        tuple: (valid_pairs, is_under_limit)
            - valid_pairs: list of (current_ch1, current_ch2) tuples in mA
            - is_under_limit: True if total current can be distributed within channel limits
    """
    valid_pairs = []
    tolerance = step_size * 0.01
    # Determine minimum feasible current for channel 1 given constraints
    lower_bound = max(step_size, total_current - max_channel_load)
    under_limit = lower_bound < step_size - tolerance

    if under_limit:
        lower_bound = step_size

    # Iterate from maximum possible current on channel 1 downward
    ch1_current = min(max_channel_load, total_current)
    while ch1_current >= lower_bound - tolerance:
        ch2_current = total_current - ch1_current

        # Validate both channels meet operational bounds
        if (
            abs(ch1_current - max_channel_load) <= tolerance or ch1_current <= max_channel_load + tolerance
        ) and (
            abs(ch2_current - max_channel_load) <= tolerance or ch2_current <= max_channel_load + tolerance
        ) and (
            ch1_current >= step_size - tolerance and ch2_current >= step_size - tolerance
        ):
            valid_pairs.append((round(ch1_current, 4), round(ch2_current, 4)))

        ch1_current -= step_size

    return valid_pairs, under_limit


def _generate_electrode_patterns(pos_group_a, neg_group_a, pos_group_b, neg_group_b, enforce_distinct):
    """Generate electrode configurations based on selection mode."""
    if enforce_distinct:
        # Enforce all four electrodes must be distinct by sampling without replacement
        for combo in combinations(pos_group_a, 4):
            if len(set(combo)) == 4:
                yield combo
    else:
        # Allow overlapping electrodes across groups using Cartesian product
        for e1p in pos_group_a:
            for e1m in neg_group_a:
                for e2p in pos_group_b:
                    for e2m in neg_group_b:
                        yield (e1p, e1m, e2p, e2m)


def enumerate_montage_configs(
    pos_a, neg_a, pos_b, neg_b, current_set, unique_electrodes_required
):
    """Produce complete montage specifications as (e1+, e1-, e2+, e2-, (i1, i2))."""
    for electrode_tuple in _generate_electrode_patterns(
        pos_a, neg_a, pos_b, neg_b, unique_electrodes_required
    ):
        for current_pair in current_set:
            yield (*electrode_tuple, current_pair)


def tally_configurations(
    pos_a, neg_a, pos_b, neg_b, current_list, require_unique_electrodes
):
    """Estimate total number of montage configurations without full enumeration."""
    # Count unique electrode patterns first
    pattern_count = sum(
        1 
        for _ in _generate_electrode_patterns(
            pos_a, neg_a, pos_b, neg_b, require_unique_electrodes
        )
    )
    return pattern_count * len(current_list)

import logging
import threading
from abc import ABC, abstractmethod
from collections import deque
from contextlib import contextmanager
from typing import Any, override
from omegaconf import DictConfig

from ..base_module import NexRLModule
from ..weight_sync.weight_sync_controller import WeightSyncController

logger = logging.getLogger(__name__)


class BaseDataLoader(NexRLModule, ABC):
    """
    Abstract base class for data loading.
    """

    def __init__(self, config: DictConfig, is_validate: bool = False):
        super().__init__()
        self._weight_sync_controller: WeightSyncController = None  # type: ignore
        self._is_validate: bool = is_validate

    def add_item(self, item: dict[str, Any]) -> None:
        self.add_item_back(item)

    @abstractmethod
    def add_item_front(self, item: dict[str, Any]) -> None:
        pass

    @abstractmethod
    def add_item_back(self, item: dict[str, Any]) -> None:
        pass

    @abstractmethod
    def get_next_item(self) -> dict[str, Any] | None:
        pass

    @abstractmethod
    def can_return_item(self) -> bool:
        pass

    @abstractmethod
    def is_finished(self) -> bool:
        pass

    @abstractmethod
    def unlock_for_weight_sync(self) -> None:
        pass

    @abstractmethod
    def reset(self) -> None:
        pass

    @abstractmethod
    def skip_batches(self, num_batches: int) -> None:
        pass

    def set_module_references(self, weight_sync_controller: WeightSyncController):
        self._weight_sync_controller = weight_sync_controller

    @staticmethod
    def repeat_item(item: dict[str, Any], n: int) -> list[dict[str, Any]]:
        repeated_items = []
        import hashlib
        import json

        group_id = item.get("group_id", "") or ""
        if not group_id:
            if "task_id" in item:
                group_id = f"task-{item['task_id']}"
            elif "prompt" in item:
                group_id = (
                    f"prompt-{hashlib.sha256(str(item['prompt']).encode('utf-8')).hexdigest()[:16]}"
                )
            else:
                payload = json.dumps(item, sort_keys=True, default=str)
                group_id = f"item-{hashlib.sha256(payload.encode('utf-8')).hexdigest()[:16]}"

        for run_id in range(n):
            copy = item.copy()
            copy["group_id"] = group_id
            copy["run_id"] = run_id
            repeated_items.append(copy)

        return repeated_items


class SequentialDataLoader(BaseDataLoader, ABC):
    """
    Abstract base class for sequential data loaders that maintain insertion order.
    """

    def __init__(self, config: DictConfig, is_validate: bool = False):
        super().__init__(config, is_validate)
        self._lock = threading.RLock()
        self._total_items_consumed: int = 0
        self._batch_size: int = config.get("batch_size", 32)
        self._buffer: deque[dict[str, Any]] = deque()
        self._next_buffer_pos: int = 0
        self._keep_batch_order: bool = config.get("keep_batch_order", False)
        if self._is_validate:
            self._keep_batch_order = False
        self._rollout_repeat_n: int = config.get("rollout_repeat_n", 1)
        self._sync_lock_event = threading.Event()
        self._sync_lock_event.clear()

        logger.info(
            f"SequentialDataLoader initialized - is_validate: {self._is_validate}, "
            f"batch_size: {self._batch_size}, keep_batch_order: {self._keep_batch_order}, "
            f"rollout_repeat_n: {self._rollout_repeat_n}"
        )

    @contextmanager
    def _synchronized(self):
        try:
            self._lock.acquire()
            yield
        finally:
            self._lock.release()

    @override
    def can_return_item(self) -> bool:
        with self._synchronized():
            return self._next_buffer_pos < len(self._buffer)

    @override
    def get_next_item(self) -> dict[str, Any] | None:
        with self._synchronized():
            if self._next_buffer_pos >= len(self._buffer):
                if not self._keep_batch_order or self._total_items_consumed == 0:
                    fetched = self._attempt_load_new_batch()
                    if not fetched:
                        return None
                else:
                    if not self._sync_lock_event.is_set():
                        logger.info(
                            "SequentialDataLoader: Buffer exhausted, locking for weight sync"
                        )
                        self._sync_lock_event.set()
                    else:
                        logger.debug("SequentialDataLoader: Waiting for weight sync unlock")
                    return None

            item = self._buffer[self._next_buffer_pos]
            self._next_buffer_pos += 1
            self._total_items_consumed += 1
            return item

    @override
    def unlock_for_weight_sync(self) -> None:
        with self._synchronized():
            logger.info("SequentialDataLoader: Unlocking for weight sync")
            self._sync_lock_event.clear()
            if self._keep_batch_order and self._next_buffer_pos >= len(self._buffer):
                self._attempt_load_new_batch()

    @override
    def add_item_front(self, item: dict[str, Any]) -> None:
        with self._synchronized():
            self._buffer.insert(self._next_buffer_pos, item)

    def _attempt_load_new_batch(self) -> bool:
        raw_batch = self._fetch_raw_batch()
        if not raw_batch:
            return False

        if not self._is_validate:
            expanded = self._expand_with_rollout_repeat(raw_batch)
            self._buffer = deque(expanded)
        else:
            self._buffer = deque(raw_batch)

        self._next_buffer_pos = 0
        logger.info(f"SequentialDataLoader: Loaded batch of {len(self._buffer)} items")
        return True

    def _expand_with_rollout_repeat(self, batch: list[dict[str, Any]]) -> list[dict[str, Any]]:
        expanded = []
        start_idx = self._total_items_consumed
        for idx, original in enumerate(batch):
            modified = original.copy()
            if "task_id" not in modified:
                stable_index = modified.get("index", start_idx + idx)
                modified["task_id"] = stable_index
            expanded.extend(BaseDataLoader.repeat_item(modified, self._rollout_repeat_n))
        logger.info(
            f"SequentialDataLoader: Expanded batch using rollout_repeat_n={self._rollout_repeat_n} "
            f"to {len(expanded)} items"
        )
        return expanded

    def get_progress_info(self) -> dict[str, Any]:
        with self._synchronized():
            current_len = len(self._buffer)
            processed = self._next_buffer_pos
            remaining = current_len - processed
            return {
                "batch_size": current_len,
                "batch_remaining": remaining,
                "batch_processed": processed,
                "total_processed": self._total_items_consumed,
            }

    @abstractmethod
    def _fetch_raw_batch(self) -> list[dict[str, Any]]:
        pass

    @abstractmethod
    def _reset_underlying_source(self) -> None:
        pass

    @override
    def reset(self) -> None:
        with self._synchronized():
            self._reset_underlying_source()
            self._buffer.clear()
            self._next_buffer_pos = 0
            self._total_items_consumed = 0
            self._sync_lock_event.clear()
            logger.info(
                f"SequentialDataLoader: Reset dataloader to beginning "
                f"(is_validate={self._is_validate})"
            )

    def skip_batches(self, num_batches: int) -> None:
        with self._synchronized():
            if self._total_items_consumed > 0:
                raise RuntimeError(
                    f"Cannot skip batches after iteration started. Current total consumed: {self._total_items_consumed}"
                )
            if num_batches <= 0:
                logger.info("No batches to skip.")
                return

            logger.info(
                f"Skipping {num_batches} batches for resume (rollout_repeat_n={self._rollout_repeat_n})"
            )
            skipped = 0
            for i in range(num_batches):
                success = self._attempt_load_new_batch()
                if not success:
                    logger.warning(
                        f"Reached end of data after skipping {skipped}/{num_batches} batches."
                    )
                    break
                skipped += 1
                if (i + 1) % 10 == 0 or (i + 1) == num_batches:
                    logger.info(f"Skipped {i + 1}/{num_batches} batches...")

            self._buffer.clear()
            self._next_buffer_pos = 0
            logger.info(
                f"Successfully skipped {skipped} batches ({self._total_items_consumed} items after expansion)"
            )

