    --brand-soft: rgba(52, 211, 153, 0.2);
}
body.body--dark.theme-swizzin {
    --brand-primary: #34d399;
    --brand-hover: #2cb783;
    --brand-soft: rgba(52, 211, 153, 0.2);
}
body.body--dark.theme-catppuccin {
    --brand-primary: #cba6f7;
    --brand-hover: #b78de8;
    --brand-soft: rgba(203, 166, 247, 0.24);
}

/* ===== Theme Transitions - Modified Selector ===== */
.theme-ready * { transition: background-color 0.3s ease; }
.theme-ready *::before { transition: border-color 0.3s ease; }
.theme-ready *::after { transition: color 0.2s ease; }

/* ===== Page Background ===== */
body { background: var(--surface-main) !important; }

/* ===== Content Text ===== */
.q-page, .q-page-container { color: var(--font-main); }

/* ===== Glassmorphism Cards ===== */
.glass-card {
    background: var(--card-glass) !important;
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.22);
    border-radius: 12px;
}
body.body--dark .glass-card {
    background: #2a2a2d !important;
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.24);
}
.glass-card.q-card { background: var(--card-glass) !important; }

/* ===== Card Text Colors ===== */
.glass-card .text-slate-800,
.glass-card .text-slate-700 { color: var(--font-main) !important; }
.glass-card .text-slate-600,
.glass-card .text-slate-500 { color: var(--font-dim) !important; }

/* ===== Typography ===== */
.text-3xl.font-bold { color: var(--font-main) !important; }
.text-xl.font-semibold { color: var(--font-sub) !important; }

/* ===== Progress Bar ===== */
.modern-progress {
    height: 8px;
    border-radius: 4px;
    background: rgba(148, 163, 184, 0.2);
    overflow: hidden;
}
.modern-progress .q-linear-progress__track { background: transparent; }
.modern-progress .q-linear-progress__model { border-radius: 4px; }

/* Progress bar variants */
.modern-progress.progress-success .q-linear-progress__model {
    background: linear-gradient(90deg, #22c55e, #4ade80);
}
.modern-progress.progress-warning .q-linear-progress__model {
    background: linear-gradient(90deg, #f59e0b, #fbbf24);
}
.modern-progress.progress-info .q-linear-progress__model {
    background: linear-gradient(90deg, var(--brand-primary), var(--brand-hover));
}
.modern-progress.progress-error .q-linear-progress__model {
    background: linear-gradient(90deg, #ef4444, #f87171);
}

/* ===== Status Chips ===== */
.status-chip {
    padding: 4px 12px;
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 500;
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
.status-chip-matched {
    background: rgba(34, 197, 94, 0.15);
    color: #16a34a;
}
body.body--dark .status-chip-matched {
    background: rgba(34, 197, 94, 0.25);
    color: #4ade80;
}
.status-chip-missing {
    background: rgba(148, 163, 184, 0.15);
    color: #64748b;
}
body.body--dark .status-chip-missing {
    background: rgba(148, 163, 184, 0.2);
    color: #94a3b8;
}
.status-chip-error {
    background: rgba(239, 68, 68, 0.15);
    color: #dc2626;
}
body.body--dark .status-chip-error {
    background: rgba(239, 68, 68, 0.25);
    color: #f87171;
}

/* ===== Episode Row ===== */
.episode-row {
    padding: 12px 16px;
    border-radius: 8px;
    transition: background-color 0.15s ease;
}
.episode-row:hover { background: rgba(148, 163, 184, 0.1); }
.episode-row-matched { border-left: 3px solid #22c55e; }
.episode-row-missing { border-left: 3px solid #94a3b8; }
.episode-row-error { border-left: 3px solid #ef4444; }
.episode-row .q-btn.episode-row-action-btn.bg-primary {
    background: transparent !important;
    background-color: transparent !important;
}
.episode-row .q-btn.episode-row-action-btn.text-primary,
.episode-row .q-btn.episode-row-action-btn .text-primary,
.episode-row .q-btn.episode-row-action-btn .q-icon {
    color: inherit !important;
}

/* ===== Season Section ===== */
.season-section {
    border: 1px solid var(--border-glass);
    border-radius: 12px;
    overflow: hidden;
}
.season-header {
    background: rgba(148, 163, 184, 0.05);
    padding: 16px;
}

/* ===== Sidebar ===== */
.playbook-sidebar .q-drawer__content {
    background: #0e0e16 !important;
    border-right: 1px solid rgba(255, 255, 255, 0.06) !important;
    box-shadow: none !important;
}
.sidebar-nav-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 12px;
    border-radius: 8px;
    width: 100%;
    transition: all 0.15s ease;
    color: rgba(255, 255, 255, 0.3);
}
.sidebar-nav-item:hover {
    background: rgba(255, 255, 255, 0.07);
    color: rgba(255, 255, 255, 0.7);
}
.sidebar-nav-item-active {
    background: var(--brand-soft) !important;
    color: var(--brand-primary) !important;
}
.sidebar-separator {
    width: 100%;
    height: 1px;
    background: rgba(255, 255, 255, 0.06);
}
.sidebar-icon-btn {
    color: rgba(255, 255, 255, 0.3);
}
.sidebar-icon-btn:hover {
    background: rgba(255, 255, 255, 0.07);
    color: rgba(255, 255, 255, 0.7);
}

/* ===== Stats Card ===== */
.stat-card {
    border-radius: 12px;
    padding: 20px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.stat-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 40px var(--shadow-glass);
}

/* ===== Tables ===== */
.modern-table {
    border-radius: 12px;
    overflow: hidden;
}
.modern-table .q-table__top,
.modern-table .q-table__bottom { background: transparent; }
.modern-table tbody tr:hover { background: rgba(148, 163, 184, 0.08); }
.modern-table tbody tr.cursor-pointer:hover { background: rgba(0, 212, 212, 0.08); }

/* Table header styling */
.q-table thead th {
    background: rgba(148, 163, 184, 0.08);
    color: var(--font-dim);
    font-weight: 600;
    font-size: 0.75rem;
    letter-spacing: 0.02em;
}
body.body--dark .q-table thead th { background: rgba(148, 163, 184, 0.05); }

/* Table body text */
.q-table tbody td {
    color: var(--font-main);
    border-bottom: 1px solid var(--border-glass);
}
body.body--dark .q-table tbody tr:hover td { background: rgba(148, 163, 184, 0.08); }

/* Clickable rows */
.q-table tbody tr.cursor-pointer { cursor: pointer; }
body.body--dark .q-table tbody tr.cursor-pointer:hover td { background: rgba(0, 212, 212, 0.12); }

/* Table container in dark mode */
body.body--dark .q-table__container { background: transparent; }

/* Remove default table borders */
.q-table--bordered thead th,
.q-table--bordered tbody td { border-color: var(--border-glass); }

/* ===== Log Viewer ===== */
.log-container {
    background: #1a1f2e !important;
    border-radius: 12px;
    font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}
.log-line { padding: 2px 8px; border-radius: 4px; }
.log-line:hover { background: rgba(255, 255, 255, 0.05); }

/* ===== Expansion Panels ===== */
.q-expansion-item { border-radius: 8px; overflow: hidden; }
.q-expansion-item__container { border-radius: 8px; }

/* ===== Scrollbar Styling ===== */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
    background: rgba(148, 163, 184, 0.3);
    border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover { background: rgba(148, 163, 184, 0.5); }
body.body--dark ::-webkit-scrollbar-thumb { background: rgba(148, 163, 184, 0.2); }

/* ===== Focus States ===== */
*:focus-visible {
    outline: 2px solid var(--brand-primary);
    outline-offset: 2px;
}
body.body--dark *:focus-visible { outline-color: var(--brand-primary); }

/* ===== Quasar Component Overrides ===== */
body.body--dark .q-card { background: var(--card-solid); }
body.body--dark .q-table { background: transparent; }
body.body--dark .q-table th,
body.body--dark .q-table td { color: var(--font-main); }
body.body--dark .q-field__label,
body.body--dark .q-field__native,
body.body--dark .q-select__dropdown-icon { color: var(--font-main); }
body.body--dark .q-checkbox__label { color: var(--font-main); }
body.body--dark .q-expansion-item__toggle-icon { color: var(--font-dim); }

/* ===== Link Colors ===== */
a { color: var(--brand-primary); }
a:hover { color: var(--brand-hover); }

/* ===== Settings Page Styles ===== */
.settings-page-shell { min-height: calc(100vh - 32px); }
.settings-main-layout { align-items: flex-start; }
.settings-sidebar {
    border-right: 1px solid var(--border-glass);
    padding-right: 14px;
    min-height: 70vh;
    align-items: stretch;
}
.settings-sidebar .q-btn .q-btn__content { justify-content: flex-start; }
.settings-sidebar .q-btn { width: 100%; text-align: left; }

.settings-subnav-item {
    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
    transition: all 0.15s ease;
    border-radius: 8px;
    color: rgba(255, 255, 255, 0.62) !important;
    background: transparent !important;
    border: 1px solid transparent;
}
.settings-subnav-item .q-btn__content,
.settings-subnav-item .q-icon,
.settings-subnav-item .q-badge,
.settings-subnav-item .q-focus-helper,
.settings-subnav-item .q-btn__content span {
    color: inherit !important;
}
.settings-subnav-item .q-btn__content {
    width: 100%;
    justify-content: flex-start !important;
    text-align: left;
}
.settings-subnav-item .q-btn__content .nicegui-row {
    width: 100%;
    justify-content: flex-start !important;
}
.settings-subnav-item.text-primary,
.settings-subnav-item .text-primary { color: inherit !important; }

@layer quasar_importants {
    .settings-subnav-item.text-primary,
    .settings-subnav-item .text-primary,
    .settings-subnav-item .q-icon,
    .settings-subnav-item .q-btn__content,
    .settings-subnav-item .q-btn__content span {
        color: inherit !important;
    }
}
.settings-sidebar .q-btn.settings-subnav-item.text-primary,
.settings-sidebar .q-btn.settings-subnav-item .text-primary {
    color: inherit !important;
}
.settings-subnav-item:hover {
    background: rgba(255, 255, 255, 0.08) !important;
    color: rgba(255, 255, 255, 0.9) !important;
}
.settings-subnav-item-active {
    background: rgba(255, 255, 255, 0.14) !important;
    color: #f8fafc !important;
    border: 1px solid rgba(255, 255, 255, 0.24) !important;
}
body.body--dark .settings-subnav-item-active {
    background: rgba(255, 255, 255, 0.14) !important;
    color: #f8fafc !important;
}
.settings-content { gap: 14px; max-width: none; }
.settings-surface {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.06)) !important;
    border: 1px solid rgba(255, 255, 255, 0.1) !important;
    border-radius: 12px !important;
    box-shadow: 0 14px 32px rgba(0, 0, 0, 0.25) !important;
}
.view-shell { min-height: calc(100vh - 24px); }
.settings-surface .q-expansion-item,
.settings-surface .q-expansion-item__container { border-radius: 8px; }
.settings-inline-card {
    background: rgba(255, 255, 255, 0.06) !important;
    border: 1px solid rgba(255, 255, 255, 0.08) !important;
    border-radius: 10px !important;
    box-shadow: none !important;
}
.settings-modal-card {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.11), rgba(255, 255, 255, 0.08)) !important;
}
.settings-theme-card {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    box-shadow: none;
}
.settings-theme-card-active {
    border-color: var(--brand-primary) !important;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06), 0 0 0 1px var(--brand-soft) !important;
}

/* Settings form inputs */
.settings-input .q-field__control {
    min-height: 40px;
    background: rgba(255, 255, 255, 0.02);
    border-radius: 8px;
}
.settings-input .q-field__label { font-size: 0.875rem; }
body.body--dark .settings-input .q-field__control::before {
    border-color: rgba(255, 255, 255, 0.16) !important;
}
body.body--dark .settings-input.q-field--focused .q-field__control::before,
body.body--dark .settings-input.q-field--focused .q-field__control::after {
    border-color: var(--brand-primary) !important;
}
body.body--dark .settings-input .q-field__native,
body.body--dark .settings-input .q-field__input,
body.body--dark .settings-input .q-field__label,
body.body--dark .settings-input .q-select__dropdown-icon {
    color: rgba(255, 255, 255, 0.82) !important;
}

/* Settings toggle */
.settings-toggle .q-toggle__label { font-size: 0.875rem; }
body.body--dark .settings-toggle .q-toggle__inner { color: var(--brand-primary); }

/* Buttons scoped to settings header actions */
.settings-action-primary {
    background: var(--brand-primary) !important;
    color: #f8fafc !important;
    border: 1px solid var(--brand-primary) !important;
}
.settings-action-primary.bg-primary { background: var(--brand-primary) !important; }
.settings-action-primary .q-btn__content,
.settings-action-primary .q-icon { color: #f8fafc !important; }
.settings-action-primary:hover {
    background: var(--brand-hover) !important;
    border-color: var(--brand-hover) !important;
}
.settings-action-secondary {
    border: 1px solid rgba(255, 255, 255, 0.2) !important;
    color: rgba(255, 255, 255, 0.85) !important;
    background: transparent !important;
}
.settings-action-secondary.bg-primary { background: transparent !important; }
.settings-action-secondary .q-btn__content,
.settings-action-secondary .q-icon { color: rgba(255, 255, 255, 0.85) !important; }
.settings-action-secondary:hover { background: rgba(255, 255, 255, 0.08) !important; }

/* App-wide semantic button system */
.app-btn {
    border-radius: 8px;
    font-weight: 600;
    letter-spacing: 0.01em;
    align-items: flex-start !important;
}
.app-btn .q-btn__content {
    width: 100%;
    justify-content: flex-start !important;
    text-align: left;
}
.app-btn.bg-primary { background: transparent !important; }
.app-btn.text-white,
.app-btn .text-white { color: inherit !important; }

.app-btn-primary {
    background: var(--brand-primary) !important;
    border: 1px solid var(--brand-primary) !important;
    color: #f8fafc !important;
}
.app-btn-primary.bg-primary { background: var(--brand-primary) !important; }
.app-btn-primary .q-btn__content,
.app-btn-primary .q-icon { color: #f8fafc !important; }
.app-btn-primary:hover {
    background: var(--brand-hover) !important;
    border-color: var(--brand-hover) !important;
}

.app-btn-danger {
