.app-btn-danger .q-btn__content,
.app-btn-danger .q-icon { color: #fca5a5 !important; }
.app-btn-danger:hover { background: rgba(239, 68, 68, 0.18) !important; }

.app-btn-outline {
    background: rgba(255, 255, 255, 0.03) !important;
    border: 1px solid rgba(255, 255, 255, 0.16) !important;
    color: rgba(255, 255, 255, 0.88) !important;
}
.app-btn-outline.bg-primary { background: rgba(255, 255, 255, 0.03) !important; }
.app-btn-outline .q-btn__content,
.app-btn-outline .q-icon { color: rgba(255, 255, 255, 0.88) !important; }
.app-btn-outline:hover {
    background: rgba(255, 255, 255, 0.09) !important;
    border-color: rgba(255, 255, 255, 0.24) !important;
}

.q-btn .q-btn__content { text-transform: none !important; letter-spacing: normal !important; }
body.body--dark .q-btn--outline,
body.body--dark .q-btn--flat { color: var(--font-main); }

/* App-wide chips and badges */
.app-chip {
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: rgba(255, 255, 255, 0.72) !important;
    background: transparent !important;
    padding: 4px 8px;
}

@layer quasar_importants {
    .q-btn.text-primary,
    .q-btn .text-primary { color: inherit !important; }
    .q-btn.bg-primary:not(.app-btn) {
        background: transparent !important;
        background-color: transparent !important;
    }
    .q-btn.app-chip.text-primary,
    .q-btn.app-chip .text-primary,
    .q-chip.app-chip.text-primary,
    .q-chip.app-chip .text-primary { color: inherit !important; }
    .q-btn.app-chip.bg-primary,
    .q-chip.app-chip.bg-primary {
        background: transparent !important;
        background-color: transparent !important;
    }
}
.app-chip .q-btn__content,
.app-chip .q-icon { color: inherit !important; }
.app-chip:hover {
    background: rgba(255, 255, 255, 0.07) !important;
    color: rgba(255, 255, 255, 0.9) !important;
}
.app-chip-active {
    background: var(--brand-soft) !important;
    border-color: rgba(255, 255, 255, 0.2) !important;
    color: var(--brand-primary) !important;
}
.app-badge { border-radius: 6px; border: 1px solid transparent; }

/* Quasar adds bg/text utility classes to badges by default; neutralize them. */
