# Type III Clone: Refactored validation logic with equivalent functionality

from .schemas import Finding, Severity, Confidence, IssueType, CodeLocation
import re

class ValidationOutcome:
    def __init__(self, is_valid, modified_finding, explanation):
        self.is_valid = is_valid
        self.modified_finding = modified_finding
        self.explanation = explanation

class StaticAnalyzer:
    def __init__(self, strict_mode=False):
        self.strict_mode = strict_mode

    def analyze(self, finding, code_source, file_name):
        lines = code_source.splitlines()
        total_lines = len(lines)
        adjustments = []

        # Normalize location information
        adjusted_location = CodeLocation(
            file=finding.location.file,
            line=finding.location.line,
            end_line=finding.location.end_line,
            column=finding.location.column,
        )

        # Create a new finding object with normalized data
        updated_finding = Finding(
            rule_id=finding.rule_id,
            issue_type=finding.issue_type,
            severity=finding.severity,
            confidence=finding.confidence,
            message=finding.message,
            location=adjusted_location,
            suggestion=finding.suggestion,
            explanation=finding.explanation,
        )

        # Validate line range
        if updated_finding.location.line < 1 or updated_finding.location.line > total_lines:
            if self.strict_mode:
                error_msg = f"Line {updated_finding.location.line} out of range (1-{total_lines})"
                return ValidationOutcome(False, None, error_msg)

            # Adjust line number to valid range
            if updated_finding.location.line < 1:
                updated_finding.location.line = 1
            elif updated_finding.location.line > total_lines:
                updated_finding.location.line = total_lines

            updated_finding.confidence = Confidence.LOW
            adjustments.append("line_adjusted")

        # Get content of the relevant line
        current_line_content = ""
        if 1 <= updated_finding.location.line <= total_lines:
            current_line_content = lines[updated_finding.location.line - 1]

        # Check relevance of line content
        if not self._is_code_relevant(updated_finding, current_line_content):
            if self.strict_mode:
                return ValidationOutcome(False, None, "Line content not relevant to finding")

            updated_finding.confidence = Confidence.LOW
            adjustments.append("low_relevance")

        # Extract and verify symbol existence
        symbol_name = self._extract_identifier(updated_finding.message)
        if symbol_name and symbol_name.strip():
            if not self._identifier_exists(symbol_name, code_source):
                if self.strict_mode:
                    return ValidationOutcome(False, None, f"Identifier '{symbol_name}' not found in code")

                updated_finding.confidence = Confidence.UNCERTAIN
                adjustments.append(f"identifier_not_found:{symbol_name}")

        # Security-specific pattern verification
        if updated_finding.issue_type == IssueType.SECURITY:
            if not self._check_security_pattern(updated_finding, lines):
                if self.strict_mode:
                    return ValidationOutcome(False, None, "Security pattern not found at location")

                updated_finding.confidence = Confidence.LOW
                adjustments.append("pattern_not_verified")

        # Add validation notes if there were any adjustments
        if adjustments:
            note = f"[Validation: {', '.join(adjustments)}]"
            if updated_finding.explanation:
                updated_finding.explanation = str(updated_finding.explanation) + " " + note
            else:
                updated_finding.explanation = note

        return ValidationOutcome(True, updated_finding, "passed")

    def _is_code_relevant(self, finding, line_text):
        if not line_text:
            return False

        text = line_text.strip().lower()
        if not text:
            return False

        if text.startswith("#"):
            return False

        if finding.issue_type == IssueType.SECURITY:
            return True

        if finding.issue_type == IssueType.DEAD_CODE:
            keywords = ["def ", "class ", "import ", "from ", "="]
            return any(kw in text for kw in keywords)

        return True

    def _extract_identifier(self, message):
        if not message:
            return None

        patterns = [
            r"(?:function|method|class|import|variable)[\s:]+['\"`]?(\w+)['\"`]?",
            r"['\"`](\w+)['\"`]",
            r":\s+(\w+)\s*$",
            r"unused\s+(\w+)",
        ]

        for pattern in patterns:
            match = re.search(pattern, message, re.IGNORECASE)
            if match:
                return match.group(1)

        return None

    def _identifier_exists(self, identifier, source_code):
        if not identifier or not source_code:
            return False

        pattern = r"\b" + re.escape(identifier) + r"\b"
        return bool(re.search(pattern, source_code))

    def _check_security_pattern(self, finding, lines):
        if finding.location.line > len(lines):
            return False

        start_idx = max(0, finding.location.line - 3)
        end_idx = min(len(lines), finding.location.line + 2)

        context = "\n".join(lines[start_idx:end_idx]).lower()
        message = str(finding.message or "").lower()

        security_patterns = {
            "sql": ["execute", "query", "cursor", "select", "insert", "update", "delete", 'f"', "f'", "%s", ".format"],
            "injection": ["subprocess", "os.system", "shell", "popen", "eval", "exec"],
            "hardcoded": ["password", "secret", "key", "token", "api_key", "apikey", '= "', "= '"],
            "xss": ["render", "html", "template", "innerhtml", "mark_safe"],
            "pickle": ["pickle", "loads", "load", "unpickle"],
            "yaml": ["yaml.load", "yaml.unsafe_load"],
            "path": ["../", "path", "file", "open(", "read("],
        }

        for category in security_patterns:
            if category in message:
                indicators = security_patterns[category]
                if any(indicator in context for indicator in indicators):
                    return True
                return False

        return True

class QualityAssurance:
    def __init__(self, strict_mode=False, minimum_confidence=Confidence.LOW):
        self.static_analyzer = StaticAnalyzer(strict_mode=strict_mode)
        self.minimum_confidence = minimum_confidence
        self.strict_mode = strict_mode

    def assess(self, findings, code_source, file_path):
        metrics = {
            "original": len(findings),
            "approved": 0,
            "denied": 0,
            "modified": 0,
        }

        validated_findings = []

        for finding in findings:
            result = self.static_analyzer.analyze(finding, code_source, file_path)

            if result.is_valid and result.modified_finding is not None:
                if self._meets_quality_threshold(result.modified_finding.confidence):
                    validated_findings.append(result.modified_finding)
                    metrics["approved"] += 1

                    if result.modified_finding.confidence != finding.confidence:
                        metrics["modified"] += 1
                else:
                    metrics["denied"] += 1
            else:
                metrics["denied"] += 1

        return validated_findings, metrics

    def _meets_quality_threshold(self, confidence_level):
        confidence_ranking = {
            Confidence.HIGH: 0,
            Confidence.MEDIUM: 1,
            Confidence.LOW: 2,
            Confidence.UNCERTAIN: 3,
        }

        level_rank = confidence_ranking.get(confidence_level, 999)
        min_rank = confidence_ranking.get(self.minimum_confidence, 999)

        return level_rank <= min_rank

def eliminate_duplicates(findings):
    if not findings:
        return []

    seen = set()
    unique_findings = []

    for finding in findings:
        message_snippet = ""
        if finding.message:
            message_snippet = finding.message[:50].lower()

        duplicate_found = False

        # Check within ±2 line tolerance
        for offset in range(-2, 3):
            key = (finding.location.file, finding.location.line + offset, message_snippet)
            if key in seen:
                duplicate_found = True
                break

        if not duplicate_found:
            key = (finding.location.file, finding.location.line, message_snippet)
            seen.add(key)
            unique_findings.append(finding)

    return unique_findings

def integrate_findings(llm_results, static_results, file_path):
    integrated = []
    llm_by_line = {}

    # Group LLM findings by line number
    for finding in llm_results:
        line_number = finding.location.line
        if line_number not in llm_by_line:
            llm_by_line[line_number] = []
        llm_by_line[line_number].append(finding)

    covered_static_lines = set()

    # Process LLM findings first
    for finding in llm_results:
        has_static_corroboration = False

        for static_item in static_results:
            static_line = static_item.get("line", static_item.get("lineno", 0))

            if abs(finding.location.line - static_line) <= 2:
                has_static_corroboration = True
                covered_static_lines.add(static_line)
                break

        if has_static_corroboration:
            if finding.confidence in [Confidence.MEDIUM, Confidence.LOW]:
                finding.confidence = Confidence.HIGH

            corroboration_note = " [Corroborated by static analysis]"
            if finding.explanation:
                finding.explanation = str(finding.explanation).rstrip() + corroboration_note
            else:
                finding.explanation = corroboration_note

        integrated.append(finding)

    # Process remaining static findings
    for static_item in static_results:
        static_line = static_item.get("line", static_item.get("lineno", 0))

        if static_line in covered_static_lines:
            continue

        nearby_llm_line = any(abs(line - static_line) <= 2 for line in llm_by_line)
        if nearby_llm_line:
            continue

        rule_id = static_item.get("rule_id") or static_item.get("code", "STATIC")
        message = static_item.get("message") or static_item.get("msg", "Issue detected")

        integrated.append(
            Finding(
                rule_id=rule_id,
                issue_type=_categorize_issue(static_item),
                severity=_determine_severity(static_item.get("severity", "medium")),
                confidence=Confidence.MEDIUM,
                message=message,
                location=CodeLocation(file=file_path, line=static_line),
                explanation="[From static analysis only]",
            )
        )

    return integrated

def _categorize_issue(static_item):
    combined_text = (str(static_item.get("message", "")) + str(static_item.get("rule_id", ""))).lower()

    security_keywords = ["security", "injection", "xss", "sql", "secret"]
    for keyword in security_keywords:
        if keyword in combined_text:
            return IssueType.SECURITY

    dead_keywords = ["unused", "dead", "unreachable"]
    for keyword in dead_keywords:
        if keyword in combined_text:
            return IssueType.DEAD_CODE

    return IssueType.QUALITY

def _determine_severity(severity_str):
    sev = str(severity_str or "").lower()

    if sev in ["critical", "blocker"]:
        return Severity.CRITICAL
    elif sev in ["high", "error"]:
        return Severity.HIGH
    elif sev in ["medium", "warning"]:
        return Severity.MEDIUM

    return Severity.LOW

# Alias for backward compatibility
Validator = StaticAnalyzer
combine_with_static = integrate_findings

# Type III Clone: Refactored version with equivalent logic and functionality

import os
import platform
import shlex
import shutil
import subprocess
import sys
import urllib.parse
from pathlib import Path
from typing import List, Optional, Sequence, Union
from .argumentsparse import get_parser
from .constants import FileManagerType, Platform, single_file_only
from .system import current_platform, is_wsl, is_wsl1, is_wsl2, linux, tools, windows

# Module-level state for caching file manager info
_valid_file_manager_cache = None
_valid_file_manager_type_cache = None
_cache_initialized = False

def _get_default_file_manager() -> str:
    """Determine the default file manager based on OS/platform."""
    if current_platform == Platform.windows or is_wsl1:
        return "explorer.exe"
    elif current_platform == Platform.linux:
        return linux.stock_linux_file_manager()
    elif current_platform == Platform.macos:
        return "open"
    else:
        raise NotImplementedError("Unsupported platform")

def _validate_file_manager_executable(fm_name: str) -> str:
    """Ensure the given file manager executable exists."""
    if shutil.which(fm_name) is None:
        raise FileNotFoundError(f"File manager '{fm_name}' not found in PATH")
    return fm_name

def _get_user_file_manager() -> str:
    """Get user-specified file manager (with validation)."""
    if current_platform == Platform.windows or is_wsl1:
        fm = "explorer.exe"
    elif current_platform == Platform.linux:
        fm = linux.user_linux_file_manager()
    elif current_platform == Platform.macos:
        fm = "open"
    else:
        raise NotImplementedError("Unsupported platform")
    return _validate_file_manager_executable(fm)

def _get_fallback_file_manager() -> str:
    """Get fallback file manager (user's choice or stock default)."""
    global _valid_file_manager_cache, _valid_file_manager_type_cache, _cache_initialized

    if not _cache_initialized:
        try:
            # Try to get user's preferred file manager first
            if current_platform == Platform.windows or is_wsl1:
                fm = "explorer.exe"
            elif current_platform == Platform.linux:
                fm = linux.valid_linux_file_manager()
            elif current_platform == Platform.macos:
                fm = "open"
            else:
                raise NotImplementedError("Unsupported platform")

            # Validate it works
            _validate_file_manager_executable(fm)
            _valid_file_manager_cache = fm
            _valid_file_manager_type_cache = _determine_file_manager_type(fm)
        except Exception:
            # Fall back to stock file manager
            try:
                _valid_file_manager_cache = _get_default_file_manager()
                _valid_file_manager_type_cache = _determine_file_manager_type(_valid_file_manager_cache)
            except Exception as e:
                # If even stock fails, use empty string as sentinel
                _valid_file_manager_cache = ""
                _valid_file_manager_type_cache = None

        _cache_initialized = True

    return _valid_file_manager_cache

def _determine_file_manager_type(file_manager: str) -> FileManagerType:
    """Classify file manager behavior type."""
    if current_platform == Platform.windows or is_wsl1:
        return windows.windows_file_manager_type(file_manager)
    elif current_platform == Platform.linux:
        return linux.linux_file_manager_type(file_manager)
    elif current_platform == Platform.macos:
        return FileManagerType.reveal
    else:
        raise NotImplementedError("Unsupported platform")

def show_in_file_manager(
    path_or_uri: Optional[Union[str, Sequence[str]]] = None,
    open_not_select_directory: Optional[bool] = True,
    file_manager: Optional[str] = None,
    allow_conversion: bool = True,
    verbose: bool = False,
    debug: bool = False,
) -> None:
    """Open file manager to show specified paths/URIs."""

    # Determine which file manager to use
    fm_to_use = file_manager or _get_fallback_file_manager()
    fm_type = _determine_file_manager_type(fm_to_use) if fm_to_use else None

    # Early exit if no valid file manager available
    if not fm_to_use and not is_wsl2:
        return

    # Prepare lists for different handling scenarios
    target_uris_paths = []
    dir_uris_paths = []
    wsl_win_paths = []
    wsl_win_dirs = []

    # Process input paths/URIs
    if path_or_uri:
        items = [path_or_uri] if isinstance(path_or_uri, str) else list(path_or_uri)

        for item in items:
            if not item:
                continue

            uri = path = None

            # Handle WSL-specific path transformations
            if is_wsl:
                win_path_needed = fm_to_use == "explorer.exe"
                wsl_info = linux.wsl_transform_path_uri(item, win_path_needed)

                if not wsl_info.exists:
                    continue

                use_windows_explorer = (
                    (wsl_info.is_win_location and not file_manager) or 
                    fm_to_use == "explorer.exe"
                )

                if use_windows_explorer:
                    converted_uri = wsl_info.win_uri
                    if debug:
                        print(f"Converted '{item}' to '{converted_uri}'", file=sys.stderr)

                    if not (wsl_info.is_dir and open_not_select_directory):
                        wsl_win_paths.append(converted_uri)
                    else:
                        wsl_win_dirs.append(converted_uri)
                    continue
                else:
                    if tools.filemanager_requires_path(file_manager=fm_to_use):
                        path = Path(wsl_info.linux_path).resolve()
                    else:
                        uri = Path(wsl_info.linux_path).resolve().as_uri()
            else:
                # Non-WSL path/URI processing
                if tools.is_uri(item):
                    if tools.filemanager_requires_path(file_manager=fm_to_use) and allow_conversion:
                        path = Path(tools.file_uri_to_path(item))
                    else:
                        uri = item
                else:
                    if tools.filemanager_requires_path(file_manager=fm_to_use) or not allow_conversion:
                        path = Path(item)
                    else:
                        uri = Path(item).resolve().as_uri()

            # Handle directory vs file selection logic
            if fm_type == FileManagerType.dir_only_uri:
                assert current_platform != Platform.windows
                if uri:
                    parsed = urllib.parse.urlparse(uri)
                    path = Path(parsed.path)

                if not (path.is_dir() and open_not_select_directory):
                    path = path.parent

                if uri:
                    new_uri = urllib.parse.urlunparse(
                        parsed._replace(path=str(path))
                    )
                    target_uris_paths.append(new_uri)
                else:
                    target_uris_paths.append(tools.quote_path(path=path))
            else:
                should_open_dir = False
                if (open_not_select_directory and 
                    fm_type != FileManagerType.dual_panel or 
                    fm_type == FileManagerType.regular):

                    if uri:
                        temp_path = tools.file_uri_to_path(uri)
                        should_open_dir = Path(temp_path).is_dir()
                    else:
                        should_open_dir = path.is_dir()

                    if should_open_dir:
                        if fm_type == FileManagerType.regular and not open_not_select_directory:
                            path = path.parent
                            if uri:
                                uri = path.as_uri()

                        if uri is None:
                            path = tools.quote_path(path=path)
                        dir_uris_paths.append(uri or str(path))

                if not should_open_dir:
                    if uri is None and fm_to_use != "explorer.exe":
                        path = tools.quote_path(path=path)
                    target_uris_paths.append(uri or str(path))

    # Build command arguments based on file manager type
    arg_prefix = ""
    if fm_type == FileManagerType.win_select:
        arg_prefix = "/select,"
    elif fm_type in (FileManagerType.select, FileManagerType.show_item, 
                     FileManagerType.show_items, FileManagerType.reveal):
        arg_map = {
            FileManagerType.select: "--select ",
            FileManagerType.show_item: "--show-item ",
            FileManagerType.show_items: "--show-items ",
            FileManagerType.reveal: "--reveal "
        }
        arg_prefix = arg_map.get(fm_type, "")

    # Execute file manager commands
    if current_platform == Platform.windows and not is_wsl and fm_to_use == "explorer.exe":
        if target_uris_paths:
            windows.launch_file_explorer(target_uris_paths, verbose)

        for d in dir_uris_paths:
            if verbose:
                print("Executing Windows shell to open", d)
            path_obj = Path(d)
            if path_obj.exists() and path_obj.is_dir():
                os.startfile(d)  # noqa: S606
            elif verbose:
                print(f"Skipping invalid or non-directory path: {d}", file=sys.stderr)
    else:
        # Launch file managers for regular paths/URIs
        if target_uris_paths:
            combined = [" ".join(target_uris_paths)] if fm_to_use not in single_file_only else target_uris_paths
            for u in combined:
                _execute_file_manager(u, arg_prefix, fm_to_use, verbose)

        # Launch for directories only
        if dir_uris_paths:
            combined = [" ".join(dir_uris_paths)] if fm_to_use not in single_file_only else dir_uris_paths
            for d in combined:
                _execute_file_manager(d, "", fm_to_use, verbose)

        # Handle WSL Windows paths
        if wsl_win_paths:
            for p in wsl_win_paths:
                _execute_file_manager(p, "/select,", "explorer.exe", verbose)

        if wsl_win_dirs:
            for d in wsl_win_dirs:
                _execute_file_manager(d, "", "explorer.exe", verbose)

    # Default case: launch file manager without arguments
    if not any([target_uris_paths, dir_uris_paths, wsl_win_paths, wsl_win_dirs]):
        _execute_file_manager("", "", fm_to_use, verbose)

def _execute_file_manager(uriorpath: str, prefix: str, fm: str, verbose: bool) -> None:
    """Execute the file manager with given parameters."""
    cmd = f"{fm} {prefix}{uriorpath}"
    if verbose:
        print("Executing", cmd)

    # Platform-specific command parsing
    args = shlex.split(cmd) if platform.system() != "Windows" else cmd
    proc = subprocess.Popen(args)

    # Wait for explorer.exe in WSL2 context
    if is_wsl2 and fm == "explorer.exe":
        proc.wait()

class Diagnostics:
    """Collect diagnostic information about file manager setup."""

    def __init__(self):
        try:
            self.stock_fm = _get_default_file_manager()
        except Exception as e:
            self.stock_fm = str(e)

        try:
            self.user_fm = _get_user_file_manager()
        except Exception as e:
            self.user_fm = str(e)

        try:
            self.valid_fm = _get_fallback_file_manager()
        except Exception as e:
            self.valid_fm = str(e)

        # Desktop environment info
        if current_platform == Platform.linux:
            try:
                self.desktop_env = linux.linux_desktop()
            except Exception:
                self.desktop_env = linux.LinuxDesktop.unknown
        else:
            self.desktop_env = ""

        # WSL version info
        if is_wsl:
            self.wsl_ver = "2" if is_wsl2 else "1"
        else:
            self.wsl_ver = ""

    def __str__(self):
        desktop_str = f"Linux Desktop: {self.desktop_env.name}\n" if self.desktop_env else ""
        wsl_str = f"WSL version {self.wsl_ver}\n" if self.wsl_ver else ""
        fm_info = "Stock: {}\nUser's choice: {}\nValid: {}".format(
            self.stock_fm, self.user_fm, self.valid_fm
        )
        return desktop_str + wsl_str + fm_info

def main() -> None:
    """Main entry point for CLI usage."""
    parser = get_parser()
    args = parser.parse_args()

    verbose = args.verbose
    debug = args.debug

    if debug:
        print(Diagnostics())
        verbose = True

    # Parse paths differently on Windows vs other platforms
    if current_platform == Platform.windows and not is_wsl:
        paths = windows.parse_command_line_arguments(args.path)
    else:
        paths = args.path

    # Convert select_folder flag to open_not_select_directory
    open_not_select_directory = not args.select_folder

    try:
        show_in_file_manager(
            file_manager=args.file_manager,
            path_or_uri=paths,
            verbose=verbose,
            open_not_select_directory=open_not_select_directory,
            debug=debug,
        )
    except Exception as e:
        sys.stderr.write(str(e))
        if args.debug:
            raise

import numpy as np
import torch
from noether.data.preprocessors import PreProcessor

class NumpyToTorchConverter(PreProcessor):
    """Transform numpy arrays to PyTorch tensors and vice versa."""

    def __init__(self, norm_param: str):
        super().__init__(normalization_key=norm_param)

    def __call__(self, data: np.ndarray) -> torch.Tensor:
        """Transform a numpy array into a PyTorch tensor."""
        if not isinstance(data, np.ndarray):
            raise TypeError("Expected input to be a numpy array.")
        return torch.from_numpy(data)

    def to_numpy(self, tensor: torch.Tensor) -> np.ndarray:
        """Convert a PyTorch tensor back to a numpy array."""
        if not isinstance(tensor, torch.Tensor):
            raise TypeError("Input must be a torch.Tensor.")
        return tensor.detach().cpu().numpy()

# Type III Clone: Modified implementation of auto and rich_repr decorators
# Changes:
# - Renamed variables and functions for clarity
# - Replaced list.append with list.extend in a different pattern
# - Restructured conditional logic for yield generation
# - Used alternative approach to handle default values
# - Changed iteration method in repr generation

from functools import partial
from typing import (
    Any,
    Callable,
    Iterable,
    List,
    Optional,
    Tuple,
    Type,
    TypeVar,
    Union,
    overload,
)

T = TypeVar("T")
RichReprOutput = Iterable[
    Union[Any, Tuple[Any], Tuple[str, Any], Tuple[str, Any, Any]]
]

class RepresentationError(Exception):
    """Exception raised when building a representation fails."""

@overload
def automatic_repr(cls: Optional[Type[T]]) -> Type[T]:
    ...

@overload
def automatic_repr(*, bracket_style: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...

def automatic_repr(
    cls: Optional[Type[T]] = None, *, bracket_style: Optional[bool] = None
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    """Decorator to automatically generate __repr__ from __rich_repr__."""

    def implement_repr(cls: Type[T], bracket_style: Optional[bool] = None) -> Type[T]:
        def generate_repr(self: T) -> str:
            """Construct string representation using __rich_repr__"""
            parts: List[str] = []

            # Determine angular vs parentheses style
            use_angular = getattr(self.__rich_repr__, "bracket_style", False)

            # Collect representation components
            for item in self.__rich_repr__():
                if isinstance(item, tuple):
                    if len(item) == 1:
                        parts += [repr(item[0])]
                    else:
                        name, val, *defaults = item
                        if name is None:
                            parts += [repr(val)]
                        else:
                            # Skip if value matches default
                            if defaults and defaults[0] == val:
                                continue
                            parts += [f"{name}={val!r}"]
                else:
                    parts += [repr(item)]

            # Format final string based on style
            if use_angular:
                return f"<{self.__class__.__name__} {' '.join(parts)}>"
            else:
                return f"{self.__class__.__name__}({', '.join(parts)})"

        def construct_rich_repr(self: Type[T]) -> RichReprOutput:
            """Automatically build __rich_repr__ from __init__ signature"""
            try:
                import inspect

                sig = inspect.signature(self.__init__)
                for param_name, parameter in sig.parameters.items():
                    if parameter.kind == parameter.POSITIONAL_ONLY:
                        yield getattr(self, param_name)
                    elif parameter.kind in (
                        parameter.POSITIONAL_OR_KEYWORD,
                        parameter.KEYWORD_ONLY,
                    ):
                        if parameter.default == parameter.empty:
                            yield getattr(self, param_name)
                        else:
                            yield param_name, getattr(self, param_name), parameter.default
            except Exception as exc:
                raise RepresentationError(
                    f"Failed to auto-generate __rich_repr__; {exc}"
                ) from None

        # Attach methods if not already present
        if not hasattr(cls, "__rich_repr__"):
            construct_rich_repr.__doc__ = "Dynamically create rich representation"
            cls.__rich_repr__ = construct_rich_repr  # type: ignore[attr-defined]

        generate_repr.__doc__ = "Return string representation of instance"
        cls.__repr__ = generate_repr  # type: ignore[assignment]

        # Set angular/bracket style if specified
        if bracket_style is not None:
            cls.__rich_repr__.bracket_style = bracket_style  # type: ignore[attr-defined]

        return cls

    if cls is None:
        return partial(implement_repr, bracket_style=bracket_style)
    else:
        return implement_repr(cls, bracket_style=bracket_style)

@overload
def rich_repr_decorator(cls: Optional[Type[T]]) -> Type[T]:
    ...

@overload
def rich_repr_decorator(*, bracket_style: bool = False) -> Callable[[Type[T]], Type[T]]:
    ...

def rich_repr_decorator(
    cls: Optional[Type[T]] = None, *, bracket_style: bool = False
) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:
    """Convenience decorator that delegates to automatic_repr."""
    if cls is None:
        return automatic_repr(bracket_style=bracket_style)
    else:
        return automatic_repr(cls, bracket_style=bracket_style)

if __name__ == "__main__":
    @automatic_repr
    class ExampleClass:
        def __rich_repr__(self) -> RichReprOutput:
            yield "first"
            yield "data", {"shopping": ["eggs", "ham", "pineapple"]}
            yield "item", "hand sanitizer"

    example = ExampleClass()

    # Note: This requires pip._vendor.rich.console to be available
    try:
        from pip._vendor.rich.console import Console
        console = Console()
        console.rule("Standard repr")
        console.print(example)
        console.print(example, width=60)
        console.print(example, width=30)
        console.rule("Bracket-style repr")
        ExampleClass.__rich_repr__.bracket_style = True  # type: ignore[attr-defined]
        console.print(example)
        console.print(example, width=60)
        console.print(example, width=30)
    except ImportError:
        print("Rich library not available for display demonstration.")

# System diagnostic tool for environment and hardware analysis

import os
import platform
import socket
import subprocess
import sys
import time
import psutil

try:
    from urllib.parse import urlparse
    from urllib.request import urlopen
except ImportError:
    from urllib2 import urlopen
    from urlparse import urlparse

import argparse
import importlib.metadata
import torch

URLS = {
    "PYPI": "https://pypi.python.org/pypi/pip",
}

REGIONAL_URLS = {
    "cn": {
        "PYPI(douban)": "https://pypi.douban.com/",
        "Conda(tsinghua)": "https://mirrors.tuna.tsinghua.edu.cn/anaconda/pkgs/free/",
    }
}


def test_connection(name, url, timeout=10):
    """Test network connectivity with timing"""
    urlinfo = urlparse(url)

    # DNS resolution timing
    start = time.time()
    try:
        socket.gethostbyname(urlinfo.netloc)
    except Exception as e:
        print(f"DNS resolution failed for {name} ({url}): {e}")
        return

    dns_time = time.time() - start

    # HTTP request timing
    start = time.time()
    try:
        _ = urlopen(url, timeout=timeout)
    except Exception as e:
        print(f"Connection failed for {name} ({url}): {e}, DNS took {dns_time:.4f}s")
        return

    load_time = time.time() - start
    print(f"{name}: {url} | DNS: {dns_time:.4f}s | Load: {load_time:.4f}s")


def check_python():
    print("----------Python Info----------")
    print("Version      :", platform.python_version())
    print("Compiler     :", platform.python_compiler())
    print("Build        :", platform.python_build())
    print("Arch         :", platform.architecture())


def check_pip():
    print("------------Pip Info-----------")
    try:
        import pip
        print("Version      :", pip.__version__)
        print("Directory    :", os.path.dirname(pip.__file__))
    except ImportError:
        print("No pip installation found for current Python.")


def _get_git_commit():
    """Get current git commit hash if available"""
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout.strip()
    except (subprocess.CalledProcessError, FileNotFoundError) as e:
        print(f"Git command error: {e}")
        return None


def check_verl():
    print("----------verl Info-----------")
    try:
        sys.path.insert(0, os.getcwd())
        import verl
        print("Version      :", verl.__version__)
        print("Directory    :", os.path.dirname(verl.__file__))

        commit_hash = _get_git_commit()
        if commit_hash:
            print("Commit Hash  :", commit_hash)
        else:
            print("Commit Hash  : Not available")
    except ImportError as e:
        print(f"verl not installed: {e}")
    except Exception as e:
        print("Error importing verl:", e)
        import traceback
        print(traceback.format_exc())


def check_os():
    print("----------Platform Info----------")
    print("Platform     :", platform.platform())
    print("system       :", platform.system())
    print("node         :", platform.node())
    print("release      :", platform.release())
    print("version      :", platform.version())


def check_hardware():
    print("----------Hardware Info----------")
    print("machine      :", platform.machine())
    print("processor    :", platform.processor())

    if sys.platform.startswith("darwin"):
        pipe = subprocess.Popen(("sysctl", "-a"), stdout=subprocess.PIPE)
        output = pipe.communicate()[0]
        for line in output.split(b"\n"):
            if b"brand_string" in line or b"features" in line:
                print(line.strip().decode('utf-8'))
    elif sys.platform.startswith("linux"):
        subprocess.call(["lscpu"])
    elif sys.platform.startswith("win32"):
        subprocess.call(["wmic", "cpu", "get", "name"])


def check_network(args):
    print("----------Network Test----------")
    if args.timeout > 0:
        socket.setdefaulttimeout(args.timeout)

    for region in args.region.strip().split(","):
        r = region.strip().lower()
        if not r:
            continue
        if r in REGIONAL_URLS:
            URLS.update(REGIONAL_URLS[r])
        else:
            import warnings
            warnings.warn(
                f"Region '{r}' does not require specific testing.",
                stacklevel=2,
            )

    for name, url in URLS.items():
        test_connection(name, url, args.timeout)


def check_environment():
    print("----------Environment----------")
    env_vars = [
        k for k in os.environ.keys()
        if k.startswith(("VERL_", "OMP_", "KMP_")) or k in ("CC", "CXX")
    ]
    for key in sorted(env_vars):
        print(f'{key}="{os.environ[key]}"')


def check_pip_package_versions():
    packages = ["vllm", "sglang", "ray", "torch"]
    print("--------Package Versions-------")
    for package in packages:
        try:
            version = importlib.metadata.version(package)
            print(f"{package}\t: {version}")
        except importlib.metadata.PackageNotFoundError:
            print(f"{package}\t: not found")


def check_cuda_versions():
    print("----------CUDA Info------------")
    if torch.cuda.is_available():
        cuda_runtime = torch.version.cuda
        print(f"CUDA Runtime : {cuda_runtime}")

        try:
            nvcc_output = subprocess.check_output(["nvcc", "--version"]).decode("utf-8")
            for line in nvcc_output.splitlines():
                if "release" in line.lower():
                    print(f"CUDA Compiler : {line.strip()}")
                    break
            else:
                print("Could not determine CUDA compiler version.")
        except FileNotFoundError:
            print("CUDA compiler : Not found")
        except Exception as e:
            print(f"CUDA compiler check error: {e}")
    else:
        print("CUDA is not available")


def _get_cpu_memory():
    """Get total CPU memory in GB"""
    memory = psutil.virtual_memory()
    return memory.total / (1024**3)


def _get_gpu_info():
    """Get GPU information using nvidia-smi"""
    try:
        result = subprocess.run(
            [
                "nvidia-smi",
                "--query-gpu=gpu_name,memory.total",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            check=True,
        )
        gpu_lines = result.stdout.strip().split("\n")
        gpu_count = len(gpu_lines)
        gpu_info = []

        for line in gpu_lines:
            parts = line.split(", ")
            if len(parts) >= 2:
                gpu_name, gpu_mem = parts[0], parts[1]
                gpu_info.append({
                    "type": gpu_name,
                    "memory": float(gpu_mem) / 1024  # Convert to GB
                })
        return gpu_count, gpu_info
    except (subprocess.CalledProcessError, Exception) as e:
        print(f"GPU info retrieval error: {e}")
        return 0, []


def _get_system_info():
    """Aggregate system information"""
    cpu_mem = _get_cpu_memory()
    gpu_count, gpu_info = _get_gpu_info()
    return {
        "cpu_memory": cpu_mem,
        "gpu_count": gpu_count,
        "gpu_info": gpu_info,
    }


def check_system_info():
    print("----------System Info----------")
    sys_info = _get_system_info()
    print(f"CPU Memory\t: {sys_info['cpu_memory']:.2f} GB")
    print(f"GPU Count\t: {sys_info['gpu_count']}")

    for i, gpu in enumerate(sys_info["gpu_info"]):
        print(f"GPU {i+1}\tType    : {gpu['type']}")
        print(f"GPU {i+1}\tMemory  : {gpu['memory']:.2f} GB")


def parse_args():
    parser = argparse.ArgumentParser(
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
        description="System diagnostic utility for environment and hardware checks."
    )

    choices = ["python", "pip", "verl", "system", "os", "environment"]
    for choice in choices:
        parser.add_argument(
            f"--{choice}",
            default=1,
            type=int,
            help=f"Enable {choice} diagnostics"
        )

    parser.add_argument("--network", default=0, type=int, help="Enable network diagnostics")
    parser.add_argument("--hardware", default=0, type=int, help="Enable hardware diagnostics")
    parser.add_argument(
        "--region",
        default="",
        type=str,
        help="Additional regions to test (e.g., 'cn' for China mirrors)"
    )
    parser.add_argument(
        "--timeout",
        default=10,
        type=int,
        help="Network connection timeout in seconds (0 to disable)"
    )

    return parser.parse_args()


if __name__ == "__main__":
    args = parse_args()

    if args.python:
        check_python()

    if args.pip:
        check_pip()
        check_pip_package_versions()

    if args.verl:
        check_verl()

    if args.os:
        check_os()

    if args.hardware:
        check_hardware()

    if args.network:
        check_network(args)

    if args.environment:
        check_environment()
        check_cuda_versions()

    if args.system:
        check_system_info()

# Oracle database client implementation with fallback mechanisms for schema introspection

import pandas as pd
import sqlalchemy
from sqlalchemy import text
from contextlib import contextmanager
from typing import Generator, List, Optional
from app.ai.prompt_formatters import Table, TableColumn
from app.ai.prompt_formatters import TableFormatter
from functools import cached_property


class OracledbClient(DataSourceClient):
    def __init__(self, host, port, service_name, user, password, schema: Optional[str] = None):
        self.host = host
        self.port = port
        self.service_name = service_name
        self.user = user
        self.password = password
        self.schema = schema
        self._schemas = []
        if isinstance(self.schema, str) and self.schema.strip():
            parts = [s.strip() for s in self.schema.split(",") if s.strip()]
            seen = set()
            for p in parts:
                up = p.upper()
                if up not in seen:
                    seen.add(up)
                    self._schemas.append(up)

    @cached_property
    def oracle_uri(self):
        return (
            f"oracle+oracledb://{self.user}:{self.password}@"
            f"{self.host}:{self.port}/?service_name={self.service_name}"
        )

    @contextmanager
    def connect(self) -> Generator[sqlalchemy.engine.base.Connection, None, None]:
        """Establish connection to Oracle database with proper resource cleanup."""
        engine = None
        conn = None
        try:
            engine = sqlalchemy.create_engine(self.oracle_uri)
            conn = engine.connect()
            # Set session schema context if specified
            if self._schemas:
                try:
                    conn.execute(text(f'ALTER SESSION SET CURRENT_SCHEMA = {self._schemas[0]}'))
                except Exception:
                    pass
            yield conn
        except Exception as e:
            raise RuntimeError(f"Connection error: {e}")
        finally:
            if conn is not None:
                conn.close()
            if engine is not None:
                engine.dispose()

    def execute_query(self, sql: str) -> pd.DataFrame:
        """Execute SQL query and return results as DataFrame."""
        try:
            with self.connect() as conn:
                df = pd.read_sql(text(sql), conn)
            return df
        except Exception as e:
            print(f"Query execution failed: {e}")
            raise

    def get_tables(self) -> List[Table]:
        """Retrieve table metadata with fallback to basic method if enriched fails."""
        try:
            return self._get_tables_enriched()
        except Exception:
            return self._get_tables_basic()

    def _get_tables_enriched(self) -> List[Table]:
        """Fetch tables with column and table comments using advanced Oracle views."""
        with self.connect() as conn:
            params = {}
            conditions = []

            if self._schemas:
                placeholders = []
                for idx, sch in enumerate(self._schemas):
                    param_key = f"s{idx}"
                    params[param_key] = sch
                    placeholders.append(f":{param_key}")
                conditions.append(f"c.owner IN ({', '.join(placeholders)})")
            else:
                params["owner"] = self.user.upper()
                conditions.append("c.owner = :owner")

            where_clause = " WHERE " + " AND ".join(conditions)

            query = text(f"""
                SELECT
                    c.owner,
                    c.table_name,
                    c.column_name,
                    c.data_type,
                    cc.comments AS column_comment,
                    tc.comments AS table_comment
                FROM all_tab_columns c
                LEFT JOIN all_col_comments cc
                    ON c.owner = cc.owner
                    AND c.table_name = cc.table_name
                    AND c.column_name = cc.column_name
                LEFT JOIN all_tab_comments tc
                    ON c.owner = tc.owner
                    AND c.table_name = tc.table_name
                {where_clause}
                ORDER BY c.owner, c.table_name, c.column_id
            """)

            rows = conn.execute(query, params).fetchall()
            tables_dict = {}

            for row in rows:
                owner, table_name, column_name, data_type, col_comment, tbl_comment = row
                key = (owner, table_name)
                full_name = f"{owner}.{table_name}"

                if key not in tables_dict:
                    tables_dict[key] = Table(
                        name=full_name,
                        description=tbl_comment or None,
                        columns=[],
                        pks=[],
                        fks=[],
                        metadata_json={"schema": owner}
                    )

                tables_dict[key].columns.append(TableColumn(
                    name=column_name,
                    dtype=data_type,
                    description=col_comment or None
                ))

            return list(tables_dict.values())

    def _get_tables_basic(self) -> List[Table]:
        """Basic table retrieval without comments - more compatible across Oracle versions."""
        try:
            with self.connect() as conn:
                params = {}
                filters = []

                if self._schemas:
                    placeholders = []
                    for idx, sch in enumerate(self._schemas):
                        param_key = f"s{idx}"
                        params[param_key] = sch
                        placeholders.append(f":{param_key}")
                    filters.append(f"owner IN ({', '.join(placeholders)})")
                else:
                    params["owner"] = self.user.upper()
                    filters.append("owner = :owner")

                where_condition = " WHERE " + " AND ".join(filters)

                query = text(f"""
                    SELECT owner, table_name, column_name, data_type
                    FROM all_tab_columns
                    {where_condition}
                    ORDER BY owner, table_name, column_id
                """)

                rows = conn.execute(query, params).fetchall()
                tables_dict = {}

                for row in rows:
                    owner, table_name, column_name, data_type = row
                    key = (owner, table_name)
                    full_name = f"{owner}.{table_name}"

                    if key not in tables_dict:
                        tables_dict[key] = Table(
                            name=full_name,
                            columns=[],
                            pks=[],
                            fks=[],
                            metadata_json={"schema": owner}
                        )

                    tables_dict[key].columns.append(TableColumn(
                        name=column_name,
                        dtype=data_type
                    ))

                return list(tables_dict.values())
        except Exception as e:
            print(f"Error retrieving tables: {e}")
            return []

    def get_schema(self, table_id: str) -> Table:
        """Deprecated method - retained for backward compatibility but raises exception."""
        raise NotImplementedError(
            "get_schema() is obsolete. Use get_tables() instead.")

    def get_schemas(self):
        """Alias for get_tables() to maintain interface consistency."""
        return self.get_tables()

    def prompt_schema(self):
        """Generate formatted schema string for AI prompts."""
        schemas = self.get_schemas()
        return TableFormatter(schemas).table_str

    def test_connection(self):
        """Verify database connectivity and return status report."""
        try:
            with self.connect() as conn:
                conn.execute(text("SELECT 1 FROM DUAL"))
                return {
                    "success": True,
                    "message": "Successfully connected to Oracle"
                }
        except Exception as e:
            return {
                "success": False,
                "message": str(e)
            }

    @property
    def description(self):
        system_prompt = """
        You can call the execute_query method to run SQL queries.

        The below are examples for how to use the execute_query method. Note that the actual SQL will vary based on the schema.
        Notice only the SQL syntax and instructions on how to use the execute_query method, not the actual SQL queries.

# Alternative implementation of pad_ends and ngrams functions

def custom_pad_ends(tokens, pad_left=True):
    """Custom implementation to mimic pad_ends behavior"""
    if not tokens:
        return iter([])

    result = []
    if pad_left:
        result.append("<s>")

    result.extend(tokens)

    if not pad_left or pad_left:
        result.append("</s>")

    return iter(result)

def test_pad_ends_custom():
    # Test cases for custom pad_ends
    assert next(custom_pad_ends(["a", "b", "c"])) == "<s>"
    assert next(custom_pad_ends(["a", "b", "c"], pad_left=False)) == "a"
    assert list(custom_pad_ends(["a", "b", "c"], pad_left=False))[-1] == "</s>"
    assert list(custom_pad_ends([], pad_left=False)) == []
    assert list(custom_pad_ends([], pad_left=True)) == []

def custom_ngrams(tokens, n):
    """Generate n-grams from token list"""
    if n <= 0:
        return iter([])

    result = []
    for i in range(len(tokens) - n + 1):
        result.append(tuple(tokens[i:i+n]))

    return iter(result)

def test_ngrams_custom():
    # Test cases for custom ngrams
    assert next(custom_ngrams(["a", "b", "c"], n=3)) == ("a", "b", "c")
    assert next(custom_ngrams(["a", "b", "c"], n=1)) == ("a",)
    assert not list(custom_ngrams(["a", "b", "c"], n=4))
    assert list(custom_ngrams(["a", "b", "c"], n=2)) == [("a", "b"), ("b", "c")]

def custom_ngrams_for_evaluation(tokens, max_n, predict_first=False):
    """Generate n-grams for language model evaluation"""
    result = []

    if predict_first:
        start_idx = 0
    else:
        start_idx = 1

    for i in range(start_idx, len(tokens)):
        context_len = min(i, max_n - 1)
        context = tuple(tokens[i-context_len:i]) if context_len > 0 else ()
        target = tokens[i]
        result.append((target, context))

    return iter(result)

def test_ngrams_for_evaluation_custom():
    # Test cases for custom ngrams_for_evaluation
    assert list(custom_ngrams_for_evaluation(["a", "b", "c"], max_n=3)) == [
        ("b", ("a",)),
        ("c", ("a", "b")),
    ]
    assert list(
        custom_ngrams_for_evaluation(["a", "b", "c"], max_n=3, predict_first=True)
    ) == [("a", ()), ("b", ("a",)), ("c", ("a", "b"))]

# Apply torch-specific patches for compatibility and bug fixes
# This module ensures safe, idempotent application of targeted monkey patches

import logging
_logger = logging.getLogger(__name__)
_PATCHES_APPLIED_FLAG = False

def apply_torch_fixes() -> None:
    """
    Safely apply version-specific torch patches.
    Designed to be called multiple times without side effects.
    """
    global _PATCHES_APPLIED_FLAG
    if _PATCHES_APPLIED_FLAG:
        return

    try:
        import torch as _torch_module
    except Exception:
        # Torch not available: skip patching
        return

    # Patch 1: Handle pin_memory signature mismatch (torchdata compatibility)
    try:
        import functools
        import inspect
        from torch.utils.data import _utils as data_utils

        base_pin_mem = data_utils.pin_memory.pin_memory
        base_loop = data_utils.pin_memory._pin_memory_loop

        sig = inspect.signature(base_pin_mem)
        if "device" not in sig.parameters:
            @functools.wraps(base_pin_mem)
            def patched_pin_mem(data, device=None):
                return base_pin_mem(data)

            @functools.wraps(base_loop)
            def patched_loop(in_q, out_q, dev_id, done_ev, device=None):
                return base_loop(in_q, out_q, dev_id, done_ev)

            data_utils.pin_memory.pin_memory = patched_pin_mem
            data_utils.pin_memory._pin_memory_loop = patched_loop
    except Exception as err:
        _logger.debug(f"Pin memory patch failed: {err}")

    # Patch 2: DeviceMesh slicing issue in PyTorch 2.10.0-nv25.11
    try:
        if "2.10.0" in _torch_module.__version__ and "nv25.11" in _torch_module.__version__:
            from torch.distributed._mesh_layout import _MeshLayout
            from torch.distributed.device_mesh import _MeshEnv

            def custom_slice_layout(self, device_mesh, mesh_names):
                is_root = device_mesh == self.get_root_mesh(device_mesh)
                root_to_flat_map = {
                    k: m._layout
                    for k, m in self.root_to_flatten_mapping.setdefault(device_mesh, {}).items()
                } if is_root else {}

                mesh_dims = getattr(device_mesh, "mesh_dim_names", [])
                valid_names = list(mesh_dims) + list(root_to_flat_map)
                if not all(name in valid_names for name in mesh_names):
                    raise KeyError(f"Invalid names: {mesh_names}. Valid: {valid_names}")

                sliced_layouts = []
                for name in mesh_names:
                    if name in mesh_dims:
                        idx = mesh_dims.index(name)
                        sliced_layouts.append(device_mesh._layout[idx])
                    elif name in root_to_flat_map:
                        sliced_layouts.append(root_to_flat_map[name])

                sizes = tuple(l.sizes for l in sliced_layouts)
                strides = tuple(l.strides for l in sliced_layouts)
                new_layout = _MeshLayout(sizes, strides)

                if not new_layout.check_non_overlap():
                    raise RuntimeError(f"Cannot slice overlapping dims: {mesh_names}")

                # Fix _dim_group_names handling
                group_names = []
                names_tuple = (mesh_names,) if isinstance(mesh_names, str) else mesh_names
                for n in names_tuple:
                    if n in mesh_dims:
                        group_names.append(device_mesh._dim_group_names[mesh_dims.index(n)])
                    elif hasattr(device_mesh, "_flatten_mapping") and n in device_mesh._flatten_mapping:
                        flat_mesh = device_mesh._flatten_mapping[n]
                        group_names.append(
                            flat_mesh._dim_group_names[flat_mesh.mesh_dim_names.index(n)]
                        )
                object.__setattr__(new_layout, "_dim_group_names", group_names)

                return new_layout

            _MeshEnv._get_slice_mesh_layout = custom_slice_layout
            _logger.debug(f"Applied DeviceMesh fix for {_torch_module.__version__}")
    except (ImportError, AttributeError) as e:
        _logger.debug(f"DeviceMesh patch skipped: {e}")

    # Patch 3: aten.alias.default sharding strategy for PyTorch 2.9.0
    try:
        from packaging.version import Version
        if Version(_torch_module.__version__).base_version == "2.9.0":
            from torch.distributed.tensor._ops._tensor_ops import propagate_single_input_strategy
            from torch.distributed.tensor._ops.utils import register_op_strategy

            op_alias = _torch_module.ops.aten.alias.default
            register_op_strategy(op_alias)(propagate_single_input_strategy)
            _logger.debug("Applied alias sharding strategy for PyTorch 2.9.0")
    except Exception as ex:
        _logger.debug(f"Alias strategy patch failed: {ex}")

    _PATCHES_APPLIED_FLAG = True

