import narwhals as nw
import polars as pl
from typing import Any, TypeVar, overload

FrameT = TypeVar("FrameT", bound=nw.Frame)
DataFrameT = TypeVar("DataFrameT", bound=nw.DataFrame[Any])
LazyFrameT = TypeVar("LazyFrameT", bound=nw.LazyFrame[Any])

def convert_to_eager_polars(frame: nw.Frame) -> pl.DataFrame:
    """Convert any Narwhals frame to an eager Polars DataFrame."""
    lazy_frame = frame.lazy()
    return lazy_frame.collect().to_polars()

def convert_lazy_to_polars_lazy(frame: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """Convert a Narwhals LazyFrame to a Polars LazyFrame.

    If the underlying implementation is already Polars, return the native object directly.
    Otherwise, collect and convert to Polars, then make it lazy again.
    """
    if frame.implementation == nw.Implementation.POLARS:
        return frame.to_native()
    else:
        eager_df = frame.collect().to_polars()
        return eager_df.lazy()

@overload
def adapt_to_polars_backend(frame: DataFrameT) -> DataFrameT: ...
@overload
def adapt_to_polars_backend(frame: LazyFrameT) -> LazyFrameT: ...

def adapt_to_polars_backend(frame: FrameT) -> FrameT:
    """Adapt a Narwhals frame to use Polars as its backend implementation."""
    if frame.implementation == nw.Implementation.POLARS:
        return frame

    if isinstance(frame, nw.DataFrame):
        return nw.from_native(frame.to_polars())
    elif isinstance(frame, nw.LazyFrame):
        # Convert to Polars eager, then back to lazy
        polars_lazy = frame.collect().to_polars().lazy()
        return nw.from_native(polars_lazy)
    else:
        raise TypeError(f"Unsupported frame type: {type(frame)}")

__all__ = ["convert_to_eager_polars", "convert_lazy_to_polars_lazy", "adapt_to_polars_backend"]

