from typing import Any, List, Dict, Union, Callable
import torch
from cosmos_rl.launcher.worker_entry import main as launch_worker
from cosmos_rl.policy.config import Config as CosmosConfig
from cosmos_rl.dispatcher.data.packer import BaseDataPacker
from cosmos_rl.tools.dataset.wfm.data_sources.mock_data import (
    LambdaDataset,
    CombinedDictDataset,
)
import secrets


def _generate_random_visual_tensor(
    is_video: bool,
    train_frames: int,
    height: int,
    width: int,
) -> torch.Tensor:
    """Generate a normalized visual tensor in [-1.0, 1.0] range."""
    if is_video:
        # Shape: (C=3, T=train_frames, H, W), values in [-1, 1]
        raw = torch.randn(3, train_frames, height, width, dtype=torch.float32)
        return torch.tanh(raw)  # maps (-inf, inf) → (-1, 1)
    else:
        # Shape: (C=3, H, W), values in [-1, 1]
        raw = torch.randn(3, height, width, dtype=torch.float32)
        return torch.tanh(raw)


def create_dummy_training_dataset(
    cfg: CosmosConfig,
    *,
    visual_transform: Callable[[], torch.Tensor] | None = None,
    prompt_transform: Callable[[], str] | None = None,
    **_,
):
    """Constructs a dummy training dataset with visual and prompt entries."""
    cfg_policy = cfg.policy.diffusers
    is_video = cfg_policy.is_video
    h, w = cfg_policy.inference_size
    t_frames = cfg_policy.train_frames

    def default_visual():
        return _generate_random_visual_tensor(is_video, t_frames, h, w)

    def default_prompt():
        return ""

    visual_fn = visual_transform or default_visual
    prompt_fn = prompt_transform or default_prompt

    return CombinedDictDataset(
        visual=LambdaDataset(visual_fn),
        prompt=LambdaDataset(prompt_fn),
    )


def create_dummy_validation_dataset(
    cfg: CosmosConfig,
    *,
    num_samples: int = 32,
    **_,
):
    """Builds a fixed-size validation dataset with static metadata."""
    cfg_policy = cfg.policy.diffusers
    h, w = cfg_policy.inference_size
    infer_frames = cfg_policy.inference_frames
    sample_steps = cfg_policy.sample.num_steps
    guidance = cfg_policy.sample.guidance_scale
    is_video = cfg_policy.is_video

    # Helper to generate constant-length datasets
    const_ds = lambda val: LambdaDataset(lambda: val, length=num_samples)

    dict_items = {
        "height": const_ds(h),
        "width": const_ds(w),
        "inference_step": const_ds(sample_steps),
        "guidance_scale": const_ds(guidance),
        "prompt": LambdaDataset(lambda: secrets.token_hex(8), length=num_samples),
    }

    if is_video:
        dict_items["frames"] = const_ds(infer_frames)

    return CombinedDictDataset(**dict_items)


class DiffusersSampleCollator(BaseDataPacker):
    """
    Minimal data collator for diffusion-based rollout/policy workflows.
    Demonstrates how inputs are prepared and outputs processed through stages.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def configure(self, config: CosmosConfig, *args, **kwargs):
        """Optional hook called after mounting; can be used for setup."""
        super().configure(config, *args, **kwargs)

    def prepare_rollout_input(self, item: Any) -> Any:
        """Convert raw dataset item into format expected by rollout engine."""
        return item

    def batch_rollout_inputs(self, items: List[Any]) -> Any:
        """Aggregate multiple rollout inputs into a single batch."""
        return items

    def prepare_policy_input(
        self,
        item: Any,
        rollout_result: Union[str, List[int]],
        skip_prefix_tokens: int = 0,
    ) -> Any:
        """Transform rollout output + original item for policy model input."""
        return {"item": item, "rollout": rollout_result}

    def estimate_max_sequence_length(self, samples: List[Any]) -> int:
        """Estimate max token count across processed samples."""
        return max(len(str(s)) for s in samples) if samples else 0

    def batch_policy_samples(
        self, processed: List[Any], target_len: int
    ) -> Dict[str, Any]:
        """Final collation step before feeding into policy model."""
        return {"data": processed, "max_len": target_len}

    def process_for_sft(self, sample: Any) -> Any:
        """No-op SFT preprocessing."""
        return sample

    def collate_for_sft(
        self, processed: List[Dict[str, Any]], is_eval: bool = False
    ) -> Dict[str, Any]:
        """Collate function for supervised fine-tuning."""
        if not is_eval:
            visuals = [sample["visual"] for sample in processed]
            prompts = [sample["prompt"] for sample in processed]
            return {"visual": visuals, "prompt": prompts}
        else:
            return processed


if __name__ == "__main__":
    launch_worker(
        dataset=create_dummy_training_dataset,
        val_dataset=create_dummy_validation_dataset,
        data_packer=DiffusersSampleCollator(),
        val_data_packer=DiffusersSampleCollator(),
    )

# Type III Clone: Equivalent functionality with different implementation approach

from pip._vendor.requests.models import CONTENT_CHUNK_SIZE, Response
from pip._internal.exceptions import NetworkConnectionError
from typing import Dict, Generator

# Original comment preserved for context but rephrased slightly
HEADERS: Dict[str, str] = {"Accept-Encoding": "identity"}

def check_response_status(resp: Response) -> None:
    """
    Raises NetworkConnectionError if response indicates HTTP error (4xx or 5xx).
    Handles both string and bytes reason phrases.
    """
    error_message = ""

    # Process reason phrase - handle both string and bytes types
    if isinstance(resp.reason, bytes):
        try:
            decoded_reason = resp.reason.decode("utf-8")
        except UnicodeDecodeError:
            decoded_reason = resp.reason.decode("iso-8859-1")
    else:
        decoded_reason = resp.reason

    # Determine error type based on status code range
    status_code = resp.status_code
    if 400 <= status_code < 500:
        error_message = f"{status_code} Client Error: {decoded_reason} for URL: {resp.url}"
    elif 500 <= status_code < 600:
        error_message = f"{status_code} Server Error: {decoded_reason} for URL: {resp.url}"

    # Raise exception only if an error message was constructed
    if error_message:
        raise NetworkConnectionError(error_message, response=resp)

def stream_response_data(
    response: Response, 
    buffer_size: int = CONTENT_CHUNK_SIZE
) -> Generator[bytes, None, None]:
    """
    Yields data chunks from a requests Response object.
    Maintains raw bytes without automatic decompression.
    """
    try:
        # Attempt to use urllib3's stream method directly
        raw_stream = response.raw.stream(
            buffer_size,
            decode_content=False  # Preserve original encoding for checksum verification
        )

        for chunk in raw_stream:
            yield chunk

    except AttributeError:
        # Fallback for standard file-like objects
        while True:
            data_chunk = response.raw.read(buffer_size)
            if not data_chunk:
                break
            yield data_chunk

import os
from ucagent.tools.testops import RunUnityChipTest
import ucagent.util.functions as fc
from ucagent.checkers.base import Checker, UnityChipBatchTask
from typing import Tuple, List, Dict, Any, Optional
from ucagent.util.log import info
from collections import OrderedDict


class UnityChipMockTestBatchValidator(Checker):
    def __init__(
        self,
        mock_pattern: str,
        test_file_prefix: str,
        test_func_prefix: str,
        tests_dir: str = "tests",
        first_param_name: str = "",
        last_param_name: str = "",
        batch_limit: int = 1,
        min_tests_per_file: int = 1,
        max_wait_seconds: int = 300,
        **config_kwargs
    ):
        self.mock_component_pattern = mock_pattern
        self.test_filename_prefix = test_file_prefix
        self.test_function_prefix = test_func_prefix
        self.tests_directory = tests_dir
        self.expected_first_arg = first_param_name
        self.expected_last_arg = last_param_name
        self.max_concurrent_checks = batch_limit
        self.minimum_test_functions_required = min_tests_per_file
        self.execution_timeout = max_wait_seconds

        self._test_runner = RunUnityChipTest()
        self._batch_processor = UnityChipBatchTask("mock_validation_task", self)
        self._update_device_identifier(config_kwargs["cfg"])

        assert "*" in self.mock_component_pattern, \
            "Mock component pattern must include a wildcard '*' to match multiple files."

    def _prepare_template_context(self) -> Dict[str, Any]:
        return self._batch_processor.get_template_data(
            "TOTAL_MOCKS", "COMPLETED_MOCKS", "LIST_CURRENT_MOCKS"
        )

    def on_initialize(self) -> None:
        self._batch_processor.source_tasks = fc.find_files_by_pattern(
            self.workspace, self.mock_component_pattern
        )
        self._batch_processor.refresh_pending_list()
        info(f"Discovered {len(self._batch_processor.source_tasks)} mock component files for validation.")
        super().on_init()

    def set_workspace_path(self, workspace_dir: str) -> "UnityChipMockTestBatchValidator":
        super().set_workspace(workspace_dir)
        self._test_runner.set_workspace(workspace_dir)
        return self

    def execute_validation(self, timeout_override: int = 0, is_final_run: bool = False, **kwargs) -> Tuple[bool, Any]:
        full_test_path = self.resolve_path(self.tests_directory)
        if not os.path.isdir(full_test_path):
            return False, {"error": f"Test directory '{self.tests_directory}' does not exist in workspace."}

        # Re-scan for mock components
        self._batch_processor.source_tasks = fc.find_files_by_pattern(
            self.workspace, self.mock_component_pattern
        )
        self._batch_processor.refresh_pending_list()

        if not self._batch_processor.source_tasks:
            return False, {
                "error": f"No mock component files matched pattern '{self.mock_component_pattern}' in workspace."
            }

        mapping = OrderedDict()
        missing_tests = []

        base_mock_prefix = os.path.basename(self.mock_component_pattern).split("*")[0]

        for mock_file in self._batch_processor.source_tasks:
            dir_part = os.path.dirname(mock_file)
            file_part = os.path.basename(mock_file)
            mock_suffix = file_part.replace(".py", "").replace(base_mock_prefix, "")

            if not mock_suffix:
                return False, {
                    "error": f"Unable to extract MockComponentName from '{mock_file}'. "
                             f"Expected format: `{base_mock_prefix}<MockComponentName>.py`"
                }

            expected_test_pattern = f"{dir_part}/{self.test_filename_prefix}{mock_suffix}*.py"
            found_tests = fc.find_files_by_pattern(self.workspace, expected_test_pattern)

            if not found_tests and mock_file in self._batch_processor.pending_tasks:
                missing_tests.append(f"{mock_file} => {expected_test_pattern} (missing)")
                continue

            mapping[mock_file] = found_tests

        if missing_tests:
            return False, {
                "error": "Some mock component files lack corresponding test files.",
                "details": missing_tests
            }

        successful_components = []
        failed_components = OrderedDict()

        for mock_file, test_files in mapping.items():
            info(f"Validating tests for '{mock_file}': {', '.join(test_files)}")
            ok, details = self._validate_single_mock(test_files, full_test_path, timeout_override)
            if ok:
                successful_components.append(mock_file)
            else:
                failed_components[mock_file] = details

        notes = []
        self._batch_processor.sync_generation(
            successful_components,
            notes,
            "Updated mock test results."
        )

        if failed_components:
            return False, {
                "error": "Validation failed for some mock components.",
                "details": failed_components
            }

        return self._batch_processor.finalize(notes, is_final_run, "", "", "")

    def _validate_single_mock(
        self,
        test_paths: List[str],
        test_root: str,
        timeout: int
    ) -> Tuple[bool, Any]:
        if not test_paths:
            return False, {"error": f"No test files matched pattern '{self.mock_component_pattern}'."}

        issues = []

        for path in test_paths:
            resolved = self.resolve_path(path)
            if test_root not in resolved:
                issues.append(f"Test file '{path}' is outside the test directory '{self.tests_directory}'.")
                continue

            functions = fc.extract_functions_from_file(
                resolved,
                prefix="test",
                python_path=self.workspace,
                target_type="FUNC"
            )

            for func in functions:
                name = func.__name__
                if not name.startswith(self.test_function_prefix):
                    issues.append(
                        f"Function '{name}' must start with '{self.test_function_prefix}'."
                    )
                    continue

                params = fc.get_function_parameters(func)
                if self.expected_first_arg and (
                    len(params) < 1 or params[0] != self.expected_first_arg
                ):
                    issues.append(
                        f"First parameter of '{name}' must be '{self.expected_first_arg}', got {params}."
                    )
                if self.expected_last_arg and (
                    len(params) < 1 or params[-1] != self.expected_last_arg
                ):
                    issues.append(
                        f"Last parameter of '{name}' must be '{self.expected_last_arg}', got {params}."
                    )

            if len(functions) < self.minimum_test_functions_required:
                issues.append(
                    f"File '{path}' has only {len(functions)} test functions; "
                    f"minimum required: {self.minimum_test_functions_required}. "
                    "Only pytest-style function-based tests are accepted (not classes)."
                )

        if issues:
            return False, {
                "error": "Test function validation errors detected.",
                "details": issues
            }

        # Execute tests
        effective_timeout = timeout if timeout > 0 else self.execution_timeout
        self._test_runner.on_before_execution(
            lambda proc: self.configure_process(proc, effective_timeout + 10)
        )

        relative_paths = [
            fc.strip_workspace_prefix(test_root, self.resolve_path(p))
            for p in test_paths
        ]

        report, stdout, stderr = self._test_runner.run(
            test_root,
            pytest_args=" ".join(relative_paths),
            capture_output=True,
            collect_all_results=True,
            timeout=effective_timeout
        )

        success, message = fc.analyze_test_report(report, stdout, stderr)
        if not success:
            return False, message

        if not report or "tests" not in report:
            return False, {
                "error": "Test execution produced invalid or empty report.",
                "STDOUT": stdout,
                "STDERR": stderr,
            }

        total = report["tests"]["total"]
        failures = report["tests"]["fails"]

        if failures > 0:
            return False, {
                "error": f"Test suite failure: {failures}/{total} cases failed. All must pass.",
                "STDOUT": stdout,
                "STDERR": stderr,
            }

        assertion_check_ok, assertion_msg = fc.verify_assertions_in_tests(self.workspace, report)
        if not assertion_check_ok:
            return assertion_check_ok, assertion_msg

        return True, {"message": f"{self.__class__.__name__} validation succeeded."}

# Kasa Smart Bulb Controller - Type III Clone
