import argparse
import asyncio


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Manage a Kasa-compatible smart bulb on the local network (modern python-kasa API)"
    )
    parser.add_argument("--ip", required=True, help="LAN IP address of the target bulb")
    parser.add_argument("--activate", action="store_true", dest="turn_on_flag", help="Power on the bulb")
    parser.add_argument("--deactivate", action="store_true", dest="turn_off_flag", help="Power off the bulb")
    parser.add_argument("--level", type=int, dest="brightness_value", help="Adjust brightness (0-100%)")
    parser.add_argument("--color", nargs=3, type=int, metavar=("HUE","SAT","VAL"), 
                        dest="hsv_values", help="Set color using HSV: H(0-360) S(0-100) V(0-100)")
    parser.add_argument("--fade", type=float, default=0.0, dest="transition_time", 
                        help="Duration for transition in seconds (if supported)")
    return parser.parse_args()


async def locate_bulb(target_ip: str):
    try:
        from kasa import Discover
    except ImportError:
        raise RuntimeError("Missing dependency: python-kasa")

    device = await Discover.discover_single(target_ip)
    if device is None:
        raise RuntimeError(f"Unable to discover device at {target_ip}")
    return device


async def initialize_device(device):
    try:
        await device.update()
    except Exception as e:
        try:
            await device.connect()
            await device.update()
        except Exception as inner_e:
            print(f"Connection failed: {inner_e}")
            raise


async def find_light_module(device):
    # Try known module keys first
    candidate_keys = ["Light", "light", "light-1"]
    for key in candidate_keys:
        modules = getattr(device, 'modules', {})
        if key in modules:
            return modules[key]

    # Fallback: scan all modules by class name
    for module in getattr(device, 'modules', {}).values():
        try:
            module_type = type(module).__name__
            if any(term in module_type.lower() for term in ['light']):
                return module
        except Exception:
            continue

    return None


async def execute_command_sequence(args):
    try:
        from kasa import Discover
    except ImportError:
        print("Error: python-kasa not installed. Run 'pip install python-kasa' to fix.")
        raise

    bulb = await locate_bulb(args.ip)
    await initialize_device(bulb)

    light_control = find_light_module(bulb)

    async def power_up():
        if hasattr(bulb, 'turn_on'):
            await bulb.turn_on()
        elif light_control and hasattr(light_control, 'turn_on'):
            await light_control.turn_on()
        else:
            raise RuntimeError("No turn-on capability detected")

    async def power_down():
        if hasattr(bulb, 'turn_off'):
            await bulb.turn_off()
        elif light_control and hasattr(light_control, 'turn_off'):
            await light_control.turn_off()
        else:
            raise RuntimeError("No turn-off capability detected")

    async def adjust_luminance(level):
        clamped_level = max(0, min(100, level))

        if light_control and hasattr(light_control, 'set_brightness'):
            await light_control.set_brightness(clamped_level)
        elif hasattr(bulb, 'set_light_state'):
            await bulb.set_light_state(brightness=clamped_level)
        elif light_control and hasattr(light_control, 'set_state'):
            await light_control.set_state(brightness=clamped_level)
        else:
            raise RuntimeError("Brightness control unavailable")

    async def apply_color(hue, saturation, value):
        hue = max(0, min(360, hue))
        saturation = max(0, min(100, saturation))
        value = max(0, min(100, value))

        if light_control and hasattr(light_control, 'set_hsv'):
            await light_control.set_hsv(hue, saturation, value)
        elif light_control and hasattr(light_control, 'set_rgb'):
            import colorsys
            r, g, b = colorsys.hsv_to_rgb(hue/360.0, saturation/100.0, value/100.0)
            rgb_values = tuple(int(c * 255) for c in (r, g, b))
            await light_control.set_rgb(*rgb_values)
        elif hasattr(bulb, 'set_light_state'):
            await bulb.set_light_state(hue=hue, saturation=saturation, brightness=value)
        else:
            raise RuntimeError("Color control unavailable")

    # Execute requested operations
    if args.turn_on_flag:
        await power_up()
        print(f"Bulb at {args.ip} powered ON")

    if args.turn_off_flag:
        await power_down()
        print(f"Bulb at {args.ip} powered OFF")

    if args.brightness_value is not None:
        try:
            await adjust_luminance(args.brightness_value)
            print(f"Brightness set to {max(0, min(100, args.brightness_value))}%")
        except Exception as err:
            print(f"Brightness adjustment failed: {err}")

    if args.hsv_values:
        h, s, v = args.hsv_values
        try:
            await apply_color(h, s, v)
            print(f"Color adjusted: HSV({h}, {s}, {v})")
        except Exception as err:
            print(f"Color adjustment failed: {err}")


if __name__ == "__main__":
    parsed_args = parse_arguments()
    asyncio.run(execute_command_sequence(parsed_args))

# Custom tool to request user clarification during planning

from typing import Dict, Any, Type, AsyncIterator
from pydantic import BaseModel
from app.ai.tools.base import Tool
from app.ai.tools.metadata import ToolMetadata
from app.ai.tools.schemas import ClarifyInput, ClarifyOutput
from app.ai.tools.schemas.events import (
    ToolEvent,
    ToolStartEvent,
    ToolEndEvent,
)


class RequestClarificationTool(Tool):
    """RequestClarificationTool - indicates that the planner requires additional input from the user.

    The tool itself does not generate questions; instead, it serves as a signal for the planner
    to include clarifying questions in the assistant_message. Once invoked, it sets analysis_complete=True
    to halt further automated processing and await user feedback.
    """

    @property
    def metadata(self) -> ToolMetadata:
        return ToolMetadata(
            name="request_clarification",
            description=(
                "ACTION: Notify that additional information is needed from the user. "
                "Formulate your queries in assistant_message, then invoke this tool to pause execution."
            ),
            category="action",
            version="1.0.0",
            input_schema=ClarifyInput.model_json_schema(),
            output_schema=ClarifyOutput.model_json_schema(),
            max_retries=1,
            timeout_seconds=10,
            idempotent=True,
            required_permissions=[],
            tags=["clarification", "user-feedback", "interruption"],
            examples=[
                {
                    "input": {
                        "context": "User asked for sales report but omitted date range"
                    },
                    "description": "Trigger clarification request (actual questions placed in assistant_message)"
                },
                {
                    "input": {},
                    "description": "Basic clarification trigger without context"
                }
            ]
        )

    @property
    def input_model(self) -> Type[BaseModel]:
        return ClarifyInput

    @property
    def output_model(self) -> Type[BaseModel]:
        return ClarifyOutput

    async def run_stream(self, tool_input: Dict[str, Any], runtime_ctx: Dict[str, Any]) -> AsyncIterator[ToolEvent]:
        # Parse input using Pydantic model
        parsed_input = ClarifyInput(**tool_input)

        # Emit start event with context
        yield ToolStartEvent(
            type="tool.start",
            payload={"context": parsed_input.context}
        )

        # Prepare observation summary based on provided context
        observation_summary = "Awaiting user clarification"
        if parsed_input.context:
            observation_summary = f"Awaiting user clarification: {parsed_input.context}"

        # Emit end event indicating pause and readiness for user response
        yield ToolEndEvent(
            type="tool.end",
            payload={
                "output": {
                    "status": "awaiting_response"
                },
                "observation": {
                    "summary": observation_summary,
                    "artifacts": [],
                    "analysis_complete": True,
                    # Final answer omitted — planner's assistant_message contains the questions
                },
            }
        )

import base64
import json
import re
from typing import Optional, Tuple, List
from urllib.parse import unquote, urlparse

class ConfigValidator:
    @staticmethod
    def is_base64(s: str) -> bool:
        try:
            s = s.rstrip('=')
            return bool(re.match(r'^[A-Za-z0-9+/\-_]*$', s))
        except:
            return False

    @staticmethod
    def decode_base64_url(s: str) -> Optional[bytes]:
        try:
            # Replace URL-safe characters with standard base64 characters
            s = s.replace('-', '+').replace('_', '/')
            # Add padding if necessary
            padding_needed = len(s) % 4
            if padding_needed != 0:
                s += '=' * (4 - padding_needed)
            return base64.b64decode(s)
        except:
            return None

    @staticmethod
    def decode_base64_text(text: str) -> Optional[str]:
        try:
            if ConfigValidator.is_base64(text):
                decoded_bytes = ConfigValidator.decode_base64_url(text)
                if decoded_bytes:
                    return decoded_bytes.decode('utf-8')
            return None
        except:
            return None

    @staticmethod
    def clean_vmess_config(config: str) -> str:
        if "vmess://" in config:
            # Extract the base64 part after 'vmess://'
            base64_part = config[8:]
            # Clean the base64 part by removing invalid characters
            base64_clean = re.split(r'[^A-Za-z0-9+/=_-]', base64_part)[0]
            return f"vmess://{base64_clean}"
        return config

    @staticmethod
    def normalize_hysteria2_protocol(config: str) -> str:
        # Convert hy2:// to hysteria2:// for consistency
        if config.startswith('hy2://'):
            return config.replace('hy2://', 'hysteria2://', 1)
        return config

    @staticmethod
    def is_vmess_config(config: str) -> bool:
        try:
            if not config.startswith('vmess://'):
                return False
            # Extract base64 part and attempt to decode
            base64_part = config[8:]
            decoded = ConfigValidator.decode_base64_url(base64_part)
            if decoded:
                # Verify it's valid JSON
                json.loads(decoded)
                return True
            return False
        except:
            return False

    @staticmethod
    def is_tuic_config(config: str) -> bool:
        try:
            if config.startswith('tuic://'):
                parsed = urlparse(config)
                # Check if netloc exists and contains a colon (port indicator)
                return bool(parsed.netloc and ':' in parsed.netloc)
            return False
        except:
            return False

    @staticmethod
    def convert_ssconf_to_https(url: str) -> str:
        # Convert ssconf:// to https://
        if url.startswith('ssconf://'):
            return url.replace('ssconf://', 'https://', 1)
        return url

    @staticmethod
    def is_base64_config(config: str) -> Tuple[bool, str]:
        protocols = ['vmess://', 'vless://', 'ss://', 'tuic://']
        for protocol in protocols:
            if config.startswith(protocol):
                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                # Check both original and URL-decoded versions
                if (ConfigValidator.is_base64(decoded_url) or 
                    ConfigValidator.is_base64(base64_part)):
                    return True, protocol[:-3]
        return False, ''

    @staticmethod
    def check_base64_content(text: str) -> Optional[str]:
        try:
            decoded_text = ConfigValidator.decode_base64_text(text)
            if decoded_text:
                # Check for known protocols in decoded content
                protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
                for protocol in protocols:
                    if protocol in decoded_text:
                        return decoded_text
            return None
        except:
            return None

    @staticmethod
    def split_configs(text: str) -> List[str]:
        configs = []
        lines = text.split('\n')

        for line in lines:
            line = line.strip()
            if not line:
                continue

            # If the line itself is base64, check its decoded content
            if ConfigValidator.is_base64(line):
                decoded_content = ConfigValidator.check_base64_content(line)
                if decoded_content:
                    text = decoded_content

            protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
            current_pos = 0
            text_length = len(text)

            while current_pos < text_length:
                next_config_start = text_length
                matching_protocol = None

                # Find the earliest occurrence of any protocol
                for protocol in protocols:
                    protocol_pos = text.find(protocol, current_pos)
                    if protocol_pos != -1 and protocol_pos < next_config_start:
                        next_config_start = protocol_pos
                        matching_protocol = protocol

                if matching_protocol:
                    # Process any text between previous config and this one
                    if current_pos < next_config_start and configs:
                        current_config = text[current_pos:next_config_start].strip()
                        if ConfigValidator.is_valid_config(current_config):
                            configs.append(current_config)

                    current_pos = next_config_start
                    next_protocol_pos = text_length

                    # Find the start of the next protocol
                    for protocol in protocols:
                        pos = text.find(protocol, next_config_start + len(matching_protocol))
                        if pos != -1 and pos < next_protocol_pos:
                            next_protocol_pos = pos

                    # Extract current config
                    current_config = text[next_config_start:next_protocol_pos].strip()

                    # Apply protocol-specific cleaning/normalization
                    if matching_protocol == "vmess://":
                        current_config = ConfigValidator.clean_vmess_config(current_config)
                    elif matching_protocol == "hy2://":
                        current_config = ConfigValidator.normalize_hysteria2_protocol(current_config)

                    if ConfigValidator.is_valid_config(current_config):
                        configs.append(current_config)

                    current_pos = next_protocol_pos
                else:
                    break

        return configs

    @staticmethod
    def clean_config(config: str) -> str:
        # Remove emojis and other non-printable characters
        config = re.sub(r'[\U0001F300-\U0001F9FF]', '', config)
        config = re.sub(r'[\x00-\x08\x0B-\x1F\x7F-\x9F]', '', config)
        # Normalize whitespace
        config = re.sub(r'[^\S\r\n]+', ' ', config)
        config = config.strip()
        return config

    @staticmethod
    def is_valid_config(config: str) -> bool:
        if not config:
            return False

        protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
        return any(config.startswith(p) for p in protocols)

    @classmethod
    def validate_protocol_config(cls, config: str, protocol: str) -> bool:
        try:
            if protocol in ['vmess://', 'vless://', 'ss://', 'tuic://']:
                if protocol == 'vmess://':
                    return cls.is_vmess_config(config)
                if protocol == 'tuic://':
                    return cls.is_tuic_config(config)

                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                # Check if base64 encoded part is valid
                if cls.is_base64(decoded_url) or cls.is_base64(base64_part):
                    return True
                if cls.decode_base64_url(base64_part) or cls.decode_base64_url(decoded_url):
                    return True
            elif protocol in ['trojan://', 'hysteria2://', 'hy2://', 'wireguard://']:
                parsed = urlparse(config)
                # Check for required authentication component
                return bool(parsed.netloc and '@' in parsed.netloc)
            elif protocol == 'ssconf://':
                return True
            return False
        except:
            return False

import json
import sys

class BaseModel(object):
    """Base class for all data models."""

    def _to_dict(self, include_nulls=False):
        """Convert object to dictionary representation, filtering None values if needed."""
        def traverse(item):
            if isinstance(item, BaseModel):
                attributes = vars(item)
                result = {}
                for key in attributes:
                    value = traverse(attributes[key])
                    if include_nulls or value is not None:
                        # Capitalize first letter of key (camelCase conversion)
                        formatted_key = key[0].upper() + key[1:] if key else ""
                        result[formatted_key] = value
                return result
            elif isinstance(item, list):
                processed_items = [traverse(element) for element in item]
                return [item for item in processed_items if include_nulls or item is not None]
            else:
                # Handle string encoding for Python 2 compatibility
                if isinstance(item, str) and sys.version_info[0] == 2:
                    return item.encode("utf-8")
                return item

        return traverse(self)

    def _load_from_dict(self, data):
        """Initialize object from dictionary data."""
        return None

    def to_json(self, *args, **options):
        """Serialize object to JSON string with Unicode support."""
        if "ensure_ascii" not in options:
            options["ensure_ascii"] = False
        return json.dumps(self._to_dict(include_nulls=True), *args, **options)

    def load_json(self, json_text):
        """Deserialize object from JSON string."""
        data = json.loads(json_text)
        self._load_from_dict(data)

    def __str__(self):
        return self.to_json()
